runtimeSource "beam-scalar" = "%% @doc The shared BEAM scalar domain. Exact arithmetic never uses native\n%% floating-point numbers, and IEEE values keep their bits because Erlang\n%% cannot represent infinity or NaN. Every target facade uses these same\n%% operations and checked bridges. ref:DEC-portable-exact-arithmetic\n%% ref:ieee-754 ref:DEC-explicit-machine-profile\n-module(lawspec_beam_scalar).\n-export([\n    literal/1, literal/2, wire/2, validate/3, convert/3,\n    binary/5, negate/1, equal/2, compare/2, helper/4,\n    ratio/2, decimal/2, exact/1, float_bits/2, float_from_ratio/4,\n    float_from_native/2, float_to_native/1, float_class/1,\n    float_binary/3, float_compare/2, integer_type/1, bounds/2,\n    type/1, new_symbol/1\n]).\n-export_type([ieee/0, rational/0, decimal/0, complex/0, symbol/0]).\n\n-opaque ieee() :: {ls_float, 32 | 64, non_neg_integer()}.\n-opaque rational() :: {ls_ratio, integer(), pos_integer()}.\n-opaque decimal() :: {ls_decimal, integer(), integer()}.\n-opaque complex() :: {ls_complex, 32 | 64, ieee(), ieee()}.\n-opaque symbol() :: {ls_symbol, term(), binary()}.\n\n%% @doc Literal symbols are interned by the caller's context, so two uses of\n%% one literal agree without sharing identities between independent runs.\n%% ref:DEC-portable-exact-arithmetic\nliteral(Value) -> literal(Value, make_ref()).\n\nliteral(#{<<\"type\">> := T} = Value, Context) ->\n    case T of\n        <<\"Bool\">> -> maps:get(<<\"value\">>, Value);\n        <<\"Decimal\">> -> decimal(integer_field(<<\"coefficient\">>, Value),\n            integer_field(<<\"exponent\">>, Value));\n        <<\"Rational\">> -> ratio(integer_field(<<\"numerator\">>, Value),\n            integer_field(<<\"denominator\">>, Value));\n        <<\"Float32\">> -> float_bits(32, hex(maps:get(<<\"bits\">>, Value)));\n        <<\"Float64\">> -> float_bits(64, hex(maps:get(<<\"bits\">>, Value)));\n        <<\"Complex64\">> -> {ls_complex, 32,\n            literal(maps:get(<<\"real\">>, Value), Context),\n            literal(maps:get(<<\"imaginary\">>, Value), Context)};\n        <<\"Complex128\">> -> {ls_complex, 64,\n            literal(maps:get(<<\"real\">>, Value), Context),\n            literal(maps:get(<<\"imaginary\">>, Value), Context)};\n        <<\"Text\">> -> text(maps:get(<<\"units\">>, Value));\n        <<\"Bytes\">> -> list_to_binary(checked_units(T, maps:get(<<\"units\">>, Value)));\n        <<\"CodePointText\">> -> {ls_raw, T, checked_units(T, maps:get(<<\"units\">>, Value))};\n        <<\"Utf16Text\">> -> {ls_raw, T, checked_units(T, maps:get(<<\"units\">>, Value))};\n        <<\"Char\">> -> unit(T, maps:get(<<\"value\">>, Value));\n        <<\"CodePoint\">> -> unit(T, maps:get(<<\"value\">>, Value));\n        <<\"CodeUnit16\">> -> unit(T, maps:get(<<\"value\">>, Value));\n        <<\"Unit\">> -> ls_unit;\n        <<\"Null\">> -> ls_null;\n        <<\"Undefined\">> -> ls_undefined;\n        <<\"Symbol\">> -> {ls_symbol, {Context, maps:get(<<\"id\">>, Value)},\n            text(unicode:characters_to_list(maps:get(<<\"description\">>, Value)))};\n        _ when T =:= <<\"Nullable\">>; T =:= <<\"Optional\">> ->\n            {ls_presence, T, case maps:get(<<\"value\">>, Value) of\n                null -> none;\n                Present -> {some, literal(Present, Context)}\n            end};\n        _ ->\n            require(integer_type(T), {unknown_scalar, T}),\n            integer_field(<<\"value\">>, Value)\n    end.\n\ninteger_field(Key, Value) ->\n    case maps:get(Key, Value) of\n        N when is_integer(N) -> N;\n        B when is_binary(B) -> binary_to_integer(B)\n    end.\n\nhex(B) when is_binary(B) -> binary_to_integer(B, 16).\n\n%% @doc The public scalar wire shape is shared with the Core oracle and other\n%% targets. No native external-term format crosses this boundary.\n%% ref:DEC-distribution-canonical-wire\nwire(Value, T) when is_binary(T) -> wire(Value, type(T));\nwire({ls_presence, T, Presence}, {T, Args}) ->\n    #{<<\"type\">> => T, <<\"value\">> => case {Presence, Args} of\n        {none, _} -> null;\n        {{some, V}, [Inner]} -> wire(V, Inner);\n        _ -> fail(presence_wire_requires_element_type)\n    end};\nwire(Value, {T, []}) ->\n    Base = #{<<\"type\">> => T},\n    case {T, Value} of\n        {<<\"Bool\">>, B} when is_boolean(B) -> Base#{<<\"value\">> => B};\n        {<<\"Decimal\">>, {ls_decimal, C, E}} ->\n            Base#{<<\"coefficient\">> => integer_to_binary(C), <<\"exponent\">> => integer_to_binary(E)};\n        {<<\"Rational\">>, {ls_ratio, N, D}} ->\n            Base#{<<\"numerator\">> => integer_to_binary(N), <<\"denominator\">> => integer_to_binary(D)};\n        {_, {ls_float, W, Bits}} ->\n            Digits = integer_to_binary(Bits, 16),\n            Hex = string:lowercase(<< (binary:copy(<<\"0\">>, W div 4 - byte_size(Digits)))/binary,\n                Digits/binary >>),\n            Base#{<<\"bits\">> => Hex};\n        {_, {ls_complex, W, R, I}} ->\n            FT = float_type(W),\n            Base#{<<\"real\">> => wire(R, FT), <<\"imaginary\">> => wire(I, FT)};\n        {<<\"Text\">>, B} -> Base#{<<\"units\">> => unicode:characters_to_list(B)};\n        {<<\"Bytes\">>, B} -> Base#{<<\"units\">> => binary_to_list(B)};\n        {_, {ls_raw, _, Units}} -> Base#{<<\"units\">> => Units};\n        {_, {ls_symbol, {_, Id}, Desc}} -> Base#{<<\"id\">> => Id, <<\"description\">> => Desc};\n        {_, N} when is_integer(N) ->\n            Base#{<<\"value\">> => case integer_type(T) of true -> integer_to_binary(N); false -> N end};\n        {_, A} when A =:= ls_unit; A =:= ls_null; A =:= ls_undefined -> Base;\n        _ -> fail({invalid_scalar_wire, T})\n    end.\n\n%% @doc A bridge checks the specification's width and domain, irrespective of\n%% the BEAM word size. Containers keep their presence and constructor tags.\n%% ref:DEC-explicit-machine-profile ref:DEC-portable-exact-arithmetic\nvalidate(Value, Name, Bits) when is_binary(Name) ->\n    validate(Value, type(Name), Bits);\nvalidate(Value, {Name, []}, Bits) ->\n    case {Name, Value} of\n        {<<\"Bool\">>, B} when is_boolean(B) -> B;\n        {<<\"Text\">>, B} when is_binary(B) ->\n            require(is_list(unicode:characters_to_list(B)), invalid_unicode), B;\n        {<<\"Bytes\">>, B} when is_binary(B) -> B;\n        {<<\"Char\">>, N} -> unit(Name, N);\n        {<<\"CodePoint\">>, N} -> unit(Name, N);\n        {<<\"CodeUnit16\">>, N} -> unit(Name, N);\n        {<<\"CodePointText\">>, {ls_raw, Name, Units}} ->\n            {ls_raw, Name, checked_units(Name, Units)};\n        {<<\"Utf16Text\">>, {ls_raw, Name, Units}} ->\n            {ls_raw, Name, checked_units(Name, Units)};\n        {<<\"Decimal\">>, {ls_decimal, C, E}} when is_integer(C), is_integer(E) -> Value;\n        {<<\"Rational\">>, {ls_ratio, N, D}} -> ratio(N, D);\n        {<<\"Float32\">>, {ls_float, 32, B}} -> float_bits(32, B);\n        {<<\"Float64\">>, {ls_float, 64, B}} -> float_bits(64, B);\n        {<<\"Complex64\">>, {ls_complex, 32, R, I}} ->\n            {ls_complex, 32, validate(R, <<\"Float32\">>, Bits), validate(I, <<\"Float32\">>, Bits)};\n        {<<\"Complex128\">>, {ls_complex, 64, R, I}} ->\n            {ls_complex, 64, validate(R, <<\"Float64\">>, Bits), validate(I, <<\"Float64\">>, Bits)};\n        {<<\"Symbol\">>, {ls_symbol, _, D}} when is_binary(D) -> Value;\n        {<<\"Unit\">>, ls_unit} -> Value;\n        {<<\"Null\">>, ls_null} -> Value;\n        {<<\"Undefined\">>, ls_undefined} -> Value;\n        _ ->\n            require(integer_type(Name) andalso is_integer(Value), {invalid_value, Name}),\n            check_bounds(Value, Name, Bits)\n    end;\nvalidate(Value, {<<\"List\">>, [Element]}, Bits) when is_list(Value) ->\n    [validate(V, Element, Bits) || V <- Value];\nvalidate({ls_data, <<\"Maybe::Nothing\">>, []} = V, {<<\"Maybe\">>, [_]}, _) -> V;\nvalidate({ls_data, <<\"Maybe::Just\">>, [V]}, {<<\"Maybe\">>, [T]}, Bits) ->\n    {ls_data, <<\"Maybe::Just\">>, [validate(V, T, Bits)]};\nvalidate({ls_data, <<\"Either::Left\">>, [V]}, {<<\"Either\">>, [T, _]}, Bits) ->\n    {ls_data, <<\"Either::Left\">>, [validate(V, T, Bits)]};\nvalidate({ls_data, <<\"Either::Right\">>, [V]}, {<<\"Either\">>, [_, T]}, Bits) ->\n    {ls_data, <<\"Either::Right\">>, [validate(V, T, Bits)]};\nvalidate({ls_presence, Kind, Presence}, {Kind, [T]}, Bits)\n        when Kind =:= <<\"Nullable\">>; Kind =:= <<\"Optional\">> ->\n    {ls_presence, Kind, case Presence of\n        none -> none;\n        {some, V} -> {some, validate(V, T, Bits)}\n    end};\nvalidate(_, T, _) -> fail({invalid_value, T}).\n\nconvert(V, T, Bits) when is_binary(T) -> convert(V, type(T), Bits);\nconvert(V, {T, []}, Bits) ->\n    case T of\n        <<\"Rational\">> -> {N, D} = exact(V), ratio(N, D);\n        <<\"Decimal\">> -> {N, D} = exact(V), finite_decimal(N, D);\n        <<\"Float32\">> -> to_float(V, 32);\n        <<\"Float64\">> -> to_float(V, 64);\n        <<\"Complex64\">> -> to_complex(V, 32);\n        <<\"Complex128\">> -> to_complex(V, 64);\n        _ -> case integer_type(T) of\n            true ->\n                {N, D} = exact(V),\n                require(N rem D =:= 0, {fractional_conversion, T}),\n                check_bounds(N div D, T, Bits);\n            false -> validate(V, {T, []}, Bits)\n        end\n    end;\nconvert(ls_null, {<<\"Nullable\">>, [_]}, _) -> {ls_presence, <<\"Nullable\">>, none};\nconvert(ls_undefined, {<<\"Optional\">>, [_]}, _) -> {ls_presence, <<\"Optional\">>, none};\nconvert({ls_presence, Kind, P}, {Kind, [T]}, Bits)\n        when Kind =:= <<\"Nullable\">>; Kind =:= <<\"Optional\">> ->\n    {ls_presence, Kind, case P of\n        none -> none;\n        {some, V} -> {some, convert(V, T, Bits)}\n    end};\nconvert(V, T, Bits) -> validate(V, T, Bits).\n\ninteger_type(T) -> lists:member(T, [\n    <<\"Int8\">>, <<\"Int16\">>, <<\"Int32\">>, <<\"Int64\">>,\n    <<\"UInt8\">>, <<\"UInt16\">>, <<\"UInt32\">>, <<\"UInt64\">>,\n    <<\"IntSize\">>, <<\"UIntSize\">>, <<\"UIntPtr\">>,\n    <<\"Integer\">>, <<\"BigInt\">>, <<\"BigUInt\">>]).\n\nbounds(T, Bits) ->\n    require(Bits =:= 32 orelse Bits =:= 64, invalid_machine_bits),\n    case T of\n        <<\"Integer\">> -> {none, none};\n        <<\"BigInt\">> -> {none, none};\n        <<\"BigUInt\">> -> {0, none};\n        <<\"IntSize\">> -> signed_bounds(Bits);\n        <<\"UIntSize\">> -> {0, (1 bsl Bits) - 1};\n        <<\"UIntPtr\">> -> {0, (1 bsl Bits) - 1};\n        <<\"Int\", W/binary>> -> signed_bounds(binary_to_integer(W));\n        <<\"UInt\", W/binary>> -> {0, (1 bsl binary_to_integer(W)) - 1};\n        _ -> fail({unknown_integer, T})\n    end.\n\nsigned_bounds(W) -> {-(1 bsl (W - 1)), (1 bsl (W - 1)) - 1}.\ncheck_bounds(V, T, Bits) ->\n    {Lo, Hi} = bounds(T, Bits),\n    require((Lo =:= none orelse V >= Lo) andalso (Hi =:= none orelse V =< Hi),\n        {integer_out_of_range, T}),\n    V.\n\n%% @doc Type keys are parsed without creating atoms from input. Parentheses\n%% preserve the boundaries of nested Either and presence arguments.\n%% ref:DEC-portable-exact-arithmetic\ntype(T) when is_tuple(T) -> T;\ntype(T) when is_binary(T) ->\n    {Parts, Rest} = type_parts(type_tokens(binary_to_list(T), [], []), []),\n    require(Rest =:= [], invalid_type_key),\n    type_application(Parts).\n\ntype_tokens([], Word, Acc) -> lists:reverse(flush_word(Word, Acc));\ntype_tokens([C | Cs], Word, Acc) when C =:= $(; C =:= $) ->\n    type_tokens(Cs, [], [C | flush_word(Word, Acc)]);\ntype_tokens([C | Cs], Word, Acc) when C =:= $\\s; C =:= $\\t ->\n    type_tokens(Cs, [], flush_word(Word, Acc));\ntype_tokens([C | Cs], Word, Acc) -> type_tokens(Cs, [C | Word], Acc).\nflush_word([], Acc) -> Acc;\nflush_word(Word, Acc) -> [list_to_binary(lists:reverse(Word)) | Acc].\ntype_parts([], Acc) -> {lists:reverse(Acc), []};\ntype_parts([$) | Rest], Acc) -> {lists:reverse(Acc), [$) | Rest]};\ntype_parts([$( | Rest], Acc) ->\n    {Inner, After} = type_parts(Rest, []),\n    case After of\n        [$) | Next] -> type_parts(Next, [type_application(Inner) | Acc]);\n        _ -> fail(invalid_type_key)\n    end;\ntype_parts([Word | Rest], Acc) -> type_parts(Rest, [{Word, []} | Acc]).\ntype_application([{Name, []}]) -> {Name, []};\ntype_application([{Name, []} | Args])\n        when Name =:= <<\"List\">>; Name =:= <<\"Maybe\">>;\n             Name =:= <<\"Optional\">>; Name =:= <<\"Nullable\">> ->\n    {Name, [type_application(Args)]};\ntype_application([{Name, []} | Args]) -> {Name, Args};\ntype_application([T]) -> T;\ntype_application(_) -> fail(invalid_type_key).\n\n%% @doc Fractions are normalized with a positive denominator; decimal\n%% conversion succeeds only when its expansion terminates in base ten.\n%% ref:decimal-arithmetic\nratio(N, D) when is_integer(N), is_integer(D), D =/= 0 ->\n    G = gcd(abs(N), abs(D)), S = case D < 0 of true -> -1; false -> 1 end,\n    {ls_ratio, S * N div G, abs(D) div G};\nratio(_, _) -> fail(invalid_rational).\ndecimal(C, E) when is_integer(C), is_integer(E) -> {ls_decimal, C, E}.\ngcd(A, 0) -> A;\ngcd(A, B) -> gcd(B, A rem B).\npow(_, 0) -> 1;\npow(A, N) when N > 0 ->\n    H = pow(A, N div 2),\n    case N rem 2 of 0 -> H * H; 1 -> H * H * A end.\nexact(N) when is_integer(N) -> {N, 1};\nexact({ls_ratio, N, D}) -> {N, D};\nexact({ls_decimal, 0, E}) when is_integer(E) -> {0, 1};\nexact({ls_decimal, C, E}) when E >= 0 -> {C * pow(10, E), 1};\nexact({ls_decimal, C, E}) -> normalized(C, pow(10, -E));\nexact({ls_float, _, _} = F) ->\n    case decode_float(F) of\n        {finite, Sign, Mantissa, Exponent} ->\n            Signed = case Sign of 0 -> Mantissa; 1 -> -Mantissa end,\n            case Exponent >= 0 of\n                true -> {Signed bsl Exponent, 1};\n                false -> normalized(Signed, 1 bsl (-Exponent))\n            end;\n        _ -> fail(non_finite_exact_conversion)\n    end;\nexact(_) -> fail(exact_number_required).\nnormalized(N, D) -> {ls_ratio, RN, RD} = ratio(N, D), {RN, RD}.\nfinite_decimal(N, D) ->\n    {RN, RD} = normalized(N, D),\n    {D2, Twos} = factors(RD, 2, 0),\n    {D5, Fives} = factors(D2, 5, 0),\n    require(D5 =:= 1, non_terminating_decimal),\n    Scale = max(Twos, Fives),\n    decimal(RN * pow(2, Scale - Twos) * pow(5, Scale - Fives), -Scale).\nfactors(N, Factor, Count) ->\n    case N rem Factor of\n        0 -> factors(N div Factor, Factor, Count + 1);\n        _ -> {N, Count}\n    end.\n\n%% @doc IEEE encoding rounds an exact ratio once, to nearest with ties to\n%% even, including the subnormal/normal and finite/infinity boundaries.\n%% ref:ieee-754\nfloat_bits(W, Bits) when (W =:= 32 orelse W =:= 64), is_integer(Bits),\n        Bits >= 0, Bits < (1 bsl W) -> {ls_float, W, Bits};\nfloat_bits(_, _) -> fail(invalid_ieee_bits).\nformat(32) -> {23, 8, 127};\nformat(64) -> {52, 11, 1023}.\nfloat_type(32) -> <<\"Float32\">>;\nfloat_type(64) -> <<\"Float64\">>.\ndecode_float({ls_float, W, Bits}) ->\n    {P, E, Bias} = format(W),\n    Sign = Bits bsr (W - 1),\n    Exp = (Bits bsr P) band ((1 bsl E) - 1),\n    Fraction = Bits band ((1 bsl P) - 1),\n    case {Exp, Fraction} of\n        {Top, 0} when Top =:= (1 bsl E) - 1 -> {infinity, Sign};\n        {Top, _} when Top =:= (1 bsl E) - 1 -> nan;\n        {0, F} -> {finite, Sign, F, 1 - Bias - P};\n        {X, F} -> {finite, Sign, (1 bsl P) + F, X - Bias - P}\n    end.\nfloat_class(F) -> case decode_float(F) of\n    nan -> nan;\n    {infinity, _} -> infinity;\n    {finite, _, 0, _} -> zero;\n    _ -> finite\nend.\nfloat_sign({ls_float, W, B}) -> B bsr (W - 1).\nfloat_zero(W, S) -> float_bits(W, S bsl (W - 1)).\nfloat_infinity(W, S) ->\n    {P, E, _} = format(W),\n    float_bits(W, (S bsl (W - 1)) bor (((1 bsl E) - 1) bsl P)).\nfloat_nan(W) ->\n    {P, _, _} = format(W),\n    {ls_float, W, Inf} = float_infinity(W, 0),\n    float_bits(W, Inf bor (1 bsl (P - 1))).\nfloat_from_ratio(W, 0, D, ZeroSign) when D =/= 0 -> float_zero(W, ZeroSign);\nfloat_from_ratio(W, N, D, _) when D =/= 0 ->\n    {P, _, Bias} = format(W),\n    S = case (N < 0) =/= (D < 0) of true -> 1; false -> 0 end,\n    AN = abs(N), AD = abs(D),\n    Exp = max(1 - Bias, floor_log2(AN, AD)),\n    Shift = P - Exp,\n    Mantissa = case Shift >= 0 of\n        true -> round_ratio(AN bsl Shift, AD);\n        false -> round_ratio(AN, AD bsl (-Shift))\n    end,\n    {M, E} = case Mantissa >= (1 bsl (P + 1)) of\n        true -> {Mantissa bsr 1, Exp + 1};\n        false -> {Mantissa, Exp}\n    end,\n    case E > Bias of\n        true -> float_infinity(W, S);\n        false ->\n            EncodedExp = case M < (1 bsl P) of true -> 0; false -> E + Bias end,\n            float_bits(W, (S bsl (W - 1)) bor (EncodedExp bsl P) bor (M band ((1 bsl P) - 1)))\n    end;\nfloat_from_ratio(_, _, _, _) -> fail(zero_denominator).\nfloor_log2(N, D) ->\n    Guess = bit_length(N) - bit_length(D),\n    Below = case Guess >= 0 of\n        true -> N < (D bsl Guess);\n        false -> (N bsl (-Guess)) < D\n    end,\n    case Below of true -> Guess - 1; false -> Guess end.\nbit_length(0) -> 0;\nbit_length(N) ->\n    B = binary:encode_unsigned(N),\n    <<Head, _/binary>> = B,\n    8 * (byte_size(B) - 1) + byte_bits(Head).\nbyte_bits(0) -> 0;\nbyte_bits(N) -> 1 + byte_bits(N bsr 1).\nround_ratio(N, D) ->\n    Q = N div D, R = N rem D,\n    case 2 * R > D orelse (2 * R =:= D andalso Q rem 2 =:= 1) of\n        true -> Q + 1;\n        false -> Q\n    end.\nfloat_from_native(W, F) when is_float(F) ->\n    <<B:64/unsigned>> = <<F:64/float>>,\n    to_float(float_bits(64, B), W).\nfloat_to_native({ls_float, W, B} = F) ->\n    require(float_class(F) =/= nan andalso float_class(F) =/= infinity,\n        non_finite_native_float),\n    <<Native:W/float>> = <<B:W/unsigned>>,\n    Native.\nto_float({ls_float, W, _} = F, W) -> F;\nto_float({ls_float, _, _} = F, W) ->\n    case decode_float(F) of\n        nan -> float_nan(W);\n        {infinity, Sign} -> float_infinity(W, Sign);\n        _ -> {N, D} = exact(F), float_from_ratio(W, N, D, float_sign(F))\n    end;\nto_float(V, W) ->\n    {N, D} = exact(V), float_from_ratio(W, N, D, 0).\nsame_ratio({A, B}, {C, D}) -> A * D =:= C * B.\nto_complex({ls_complex, _, R, I}, W) ->\n    {ls_complex, W, to_float(R, W), to_float(I, W)};\nto_complex(V, W) -> {ls_complex, W, to_float(V, W), float_zero(W, 0)}.\n\n%% @doc Arithmetic handles IEEE exceptional values before exact finite\n%% computation; it never relies on badarith to guess an infinity's sign.\n%% ref:ieee-754\nfloat_binary(Op, {ls_float, WA, _} = A, {ls_float, WB, _} = B) ->\n    W = max(WA, WB),\n    AF = to_float(A, W), BF = to_float(B, W),\n    float_op(Op, W, AF, BF, float_class(AF), float_class(BF)).\nfloat_op(_, W, _, _, nan, _) -> float_nan(W);\nfloat_op(_, W, _, _, _, nan) -> float_nan(W);\nfloat_op(<<\"-\">>, W, A, B, CA, CB) -> float_op(<<\"+\">>, W, A, negate(B), CA, CB);\nfloat_op(<<\"+\">>, W, A, B, infinity, infinity) ->\n    case float_sign(A) =:= float_sign(B) of true -> A; false -> float_nan(W) end;\nfloat_op(<<\"+\">>, _, A, _, infinity, _) -> A;\nfloat_op(<<\"+\">>, _, _, B, _, infinity) -> B;\nfloat_op(<<\"*\">>, W, _, _, infinity, zero) -> float_nan(W);\nfloat_op(<<\"*\">>, W, _, _, zero, infinity) -> float_nan(W);\nfloat_op(<<\"*\">>, W, A, B, CA, CB) when CA =:= infinity; CB =:= infinity ->\n    float_infinity(W, float_sign(A) bxor float_sign(B));\nfloat_op(<<\"/\">>, W, _, _, infinity, infinity) -> float_nan(W);\nfloat_op(<<\"/\">>, W, _, _, zero, zero) -> float_nan(W);\nfloat_op(<<\"/\">>, W, A, B, infinity, _) ->\n    float_infinity(W, float_sign(A) bxor float_sign(B));\nfloat_op(<<\"/\">>, W, A, B, _, zero) ->\n    float_infinity(W, float_sign(A) bxor float_sign(B));\nfloat_op(<<\"/\">>, W, A, B, _, infinity) ->\n    float_zero(W, float_sign(A) bxor float_sign(B));\nfloat_op(Op, W, A, B, _, _) ->\n    {AN, AD} = exact(A), {BN, BD} = exact(B),\n    {N, D, ZeroSign} = case Op of\n        <<\"+\">> -> {AN * BD + BN * AD, AD * BD, float_sign(A) band float_sign(B)};\n        <<\"*\">> -> {AN * BN, AD * BD, float_sign(A) bxor float_sign(B)};\n        <<\"/\">> -> {AN * BD, AD * BN, float_sign(A) bxor float_sign(B)};\n        _ -> fail({unknown_float_operation, Op})\n    end,\n    float_from_ratio(W, N, D, ZeroSign).\n\nfloat_compare(A, B) ->\n    case {decode_float(A), decode_float(B)} of\n        {nan, _} -> unordered;\n        {_, nan} -> unordered;\n        {{infinity, S}, {infinity, S}} -> 0;\n        {{infinity, 1}, _} -> -1;\n        {_, {infinity, 1}} -> 1;\n        {{infinity, 0}, _} -> 1;\n        {_, {infinity, 0}} -> -1;\n        _ -> compare_ratios(exact(A), exact(B))\n    end.\ncompare_ratios({A, B}, {C, D}) -> order(A * D, C * B).\norder(A, B) when A < B -> -1;\norder(A, B) when A > B -> 1;\norder(_, _) -> 0.\n\nnegate(N) when is_integer(N) -> -N;\nnegate({ls_ratio, N, D}) -> ratio(-N, D);\nnegate({ls_decimal, C, E}) -> decimal(-C, E);\nnegate({ls_float, W, B}) -> float_bits(W, B bxor (1 bsl (W - 1)));\nnegate({ls_complex, W, R, I}) -> {ls_complex, W, negate(R), negate(I)}.\n\nbinary(<<\"==\">>, A, B, _, _) -> equal(A, B);\nbinary(<<\"!=\">>, A, B, _, _) -> not equal(A, B);\nbinary(Op, A, B, TA, TB) when Op =:= <<\"<\">>; Op =:= <<\"<=\">>;\n        Op =:= <<\">\">>; Op =:= <<\">=\">> ->\n    Order = case inexact_width(TA) > 0 orelse inexact_width(TB) > 0 of\n        true -> float_compare(A, B);\n        false -> compare(A, B)\n    end,\n    relation(Op, Order);\nbinary(Op, A, B, TA, TB) ->\n    require((inexact_width(TA) > 0) =:= (inexact_width(TB) > 0),\n        exact_inexact_mixing),\n    case max(inexact_width(TA), inexact_width(TB)) of\n        0 -> exact_binary(Op, A, B, TA, TB);\n        Width -> case is_complex_type(TA) orelse is_complex_type(TB) of\n            true -> complex_binary(Op, to_complex(A, Width), to_complex(B, Width));\n            false -> float_binary(Op, A, B)\n        end\n    end.\ninexact_width(<<\"Float32\">>) -> 32;\ninexact_width(<<\"Float64\">>) -> 64;\ninexact_width(<<\"Complex64\">>) -> 32;\ninexact_width(<<\"Complex128\">>) -> 64;\ninexact_width(_) -> 0.\nis_complex_type(<<\"Complex64\">>) -> true;\nis_complex_type(<<\"Complex128\">>) -> true;\nis_complex_type(_) -> false.\nrelation(_, unordered) -> false;\nrelation(<<\"<\">>, N) -> N < 0;\nrelation(<<\"<=\">>, N) -> N =< 0;\nrelation(<<\">\">>, N) -> N > 0;\nrelation(<<\">=\">>, N) -> N >= 0.\nexact_binary(<<\"pow\">>, A, B, _, _) when is_integer(A), is_integer(B), B >= 0 -> pow(A, B);\nexact_binary(<<\"quot\">>, A, B, _, _) when is_integer(A), is_integer(B), B =/= 0 -> A div B;\nexact_binary(<<\"rem\">>, A, B, _, _) when is_integer(A), is_integer(B), B =/= 0 -> A rem B;\nexact_binary(Op, A, B, TA, TB) ->\n    {AN, AD} = exact(A), {BN, BD} = exact(B),\n    {N, D} = case Op of\n        <<\"+\">> -> {AN * BD + BN * AD, AD * BD};\n        <<\"-\">> -> {AN * BD - BN * AD, AD * BD};\n        <<\"*\">> -> {AN * BN, AD * BD};\n        <<\"/\">> -> {AN * BD, AD * BN};\n        _ -> fail({invalid_exact_operation, Op})\n    end,\n    R = ratio(N, D),\n    case Op =:= <<\"/\">> orelse TA =:= <<\"Rational\">> orelse TB =:= <<\"Rational\">> of\n        true -> R;\n        false -> case TA =:= <<\"Decimal\">> orelse TB =:= <<\"Decimal\">> of\n            true -> finite_decimal(N, D);\n            false -> {ls_ratio, I, 1} = R, I\n        end\n    end.\ncomplex_binary(Op, {ls_complex, W, A, B}, {ls_complex, W, C, D}) ->\n    F = fun float_binary/3,\n    {R, I} = case Op of\n        <<\"+\">> -> {F(Op, A, C), F(Op, B, D)};\n        <<\"-\">> -> {F(Op, A, C), F(Op, B, D)};\n        <<\"*\">> -> {F(<<\"-\">>, F(Op, A, C), F(Op, B, D)),\n            F(<<\"+\">>, F(Op, A, D), F(Op, B, C))};\n        <<\"/\">> ->\n            Den = F(<<\"+\">>, F(<<\"*\">>, C, C), F(<<\"*\">>, D, D)),\n            {F(Op, F(<<\"+\">>, F(<<\"*\">>, A, C), F(<<\"*\">>, B, D)), Den),\n             F(Op, F(<<\"-\">>, F(<<\"*\">>, B, C), F(<<\"*\">>, A, D)), Den)}\n    end,\n    {ls_complex, W, R, I}.\n\n%% @doc Structural equality recurses through values; native tuple equality\n%% would incorrectly make a NaN equal to itself, even inside a container.\n%% ref:DEC-portable-exact-arithmetic\nequal({ls_float, _, _} = A, {ls_float, _, _} = B) -> float_compare(A, B) =:= 0;\nequal({ls_complex, _, A, B}, {ls_complex, _, C, D}) -> equal(A, C) andalso equal(B, D);\nequal({ls_complex, W, R, I}, {ls_float, _, _} = B) ->\n    equal(R, B) andalso equal(I, float_zero(W, 0));\nequal({ls_float, _, _} = A, {ls_complex, _, _, _} = B) -> equal(B, A);\nequal({ls_symbol, A, _}, {ls_symbol, B, _}) -> A =:= B;\nequal({ls_presence, T, {some, A}}, {ls_presence, T, {some, B}}) -> equal(A, B);\nequal({ls_data, T, A}, {ls_data, T, B}) -> equal(A, B);\nequal(A, B) when is_list(A), is_list(B) -> equal_lists(A, B);\nequal(A, B) when is_tuple(A), is_tuple(B) ->\n    case is_exact(A) andalso is_exact(B) of\n        true -> same_ratio(exact(A), exact(B));\n        false -> equal_lists(tuple_to_list(A), tuple_to_list(B))\n    end;\nequal(A, B) ->\n    case is_exact(A) andalso is_exact(B) of\n        true -> same_ratio(exact(A), exact(B));\n        false -> A =:= B\n    end.\nequal_lists([], []) -> true;\nequal_lists([A | As], [B | Bs]) -> equal(A, B) andalso equal_lists(As, Bs);\nequal_lists(_, _) -> false.\nis_exact(N) when is_integer(N) -> true;\nis_exact({ls_ratio, _, _}) -> true;\nis_exact({ls_decimal, _, _}) -> true;\nis_exact(_) -> false.\n\n%% @doc Collection keys use LawSpec's order, which differs from Erlang's\n%% term order. Floating values, symbols and distinct handles are not keys.\n%% ref:DEC-portable-exact-arithmetic\ncompare(false, false) -> 0;\ncompare(true, true) -> 0;\ncompare(false, true) -> -1;\ncompare(true, false) -> 1;\ncompare(A, B) when is_binary(A), is_binary(B) -> order(A, B);\ncompare({ls_raw, T, A}, {ls_raw, T, B}) -> compare_lists(A, B);\ncompare({ls_presence, T, none}, {ls_presence, T, none}) -> 0;\ncompare({ls_presence, T, none}, {ls_presence, T, {some, _}}) -> -1;\ncompare({ls_presence, T, {some, _}}, {ls_presence, T, none}) -> 1;\ncompare({ls_presence, T, {some, A}}, {ls_presence, T, {some, B}}) -> compare(A, B);\ncompare({ls_data, <<\"Maybe::Nothing\">>, []}, {ls_data, <<\"Maybe::Just\">>, _}) -> -1;\ncompare({ls_data, <<\"Maybe::Just\">>, _}, {ls_data, <<\"Maybe::Nothing\">>, []}) -> 1;\ncompare({ls_data, T, A}, {ls_data, T, B}) -> compare_lists(A, B);\ncompare({ls_data, TA, _}, {ls_data, TB, _}) -> order(TA, TB);\ncompare(A, B) when is_list(A), is_list(B) -> compare_lists(A, B);\ncompare({ls_handle, _, _} = H, H) -> 0;\ncompare(A, A) when A =:= ls_unit; A =:= ls_null; A =:= ls_undefined -> 0;\ncompare(A, B) ->\n    require(is_exact(A) andalso is_exact(B), no_portable_order),\n    compare_ratios(exact(A), exact(B)).\ncompare_lists([], []) -> 0;\ncompare_lists([], _) -> -1;\ncompare_lists(_, []) -> 1;\ncompare_lists([A | As], [B | Bs]) ->\n    case compare(A, B) of 0 -> compare_lists(As, Bs); Result -> Result end.\n\nhelper(<<\"isNaN\">>, [F], _, _) -> float_class(F) =:= nan;\nhelper(<<\"isInfinite\">>, [F], _, _) -> float_class(F) =:= infinity;\nhelper(<<\"isFinite\">>, [F], _, _) ->\n    C = float_class(F), C =:= finite orelse C =:= zero;\nhelper(<<\"isNegativeZero\">>, [F], _, _) ->\n    float_class(F) =:= zero andalso float_sign(F) =:= 1;\nhelper(<<\"length\">>, [V], _, _) when is_list(V) -> length(V);\nhelper(<<\"length\">>, [V], [<<\"Bytes\">>], _) -> byte_size(V);\nhelper(<<\"length\">>, [V], [<<\"Text\">>], _) -> length(unicode:characters_to_list(V));\nhelper(<<\"length\">>, [{ls_raw, _, V}], _, _) -> length(V);\nhelper(<<\"real\">>, [{ls_complex, _, R, _}], _, _) -> R;\nhelper(<<\"imag\">>, [{ls_complex, _, _, I}], _, _) -> I;\nhelper(<<\"imaginary\">>, [{ls_complex, _, _, I}], _, _) -> I;\nhelper(<<\"conjugate\">>, [{ls_complex, W, R, I}], _, _) -> {ls_complex, W, R, negate(I)};\nhelper(<<\"abs\">>, [V], _, _) ->\n    case is_exact(V) of\n        true -> {N, _} = exact(V), case N < 0 of true -> negate(V); false -> V end;\n        false -> {ls_float, W, B} = V, float_bits(W, B band ((1 bsl (W - 1)) - 1))\n    end;\nhelper(<<\"round\">>, [V, Places], _, _) when is_integer(Places) ->\n    {N, D} = exact(V),\n    {SN, SD} = case Places >= 0 of\n        true -> {N * pow(10, Places), D};\n        false -> {N, D * pow(10, -Places)}\n    end,\n    Q = round_ratio(abs(SN), SD),\n    decimal(case SN < 0 of true -> -Q; false -> Q end, -Places);\nhelper(<<\"startsWith\">>, [Text, Prefix], _, _) ->\n    byte_size(Text) >= byte_size(Prefix) andalso\n        binary:part(Text, 0, byte_size(Prefix)) =:= Prefix;\nhelper(<<\"endsWith\">>, [Text, Suffix], _, _) ->\n    byte_size(Text) >= byte_size(Suffix) andalso\n        binary:part(Text, byte_size(Text) - byte_size(Suffix), byte_size(Suffix)) =:= Suffix;\nhelper(<<\"textContains\">>, [Text, Part], _, _) ->\n    Part =:= <<>> orelse binary:match(Text, Part) =/= nomatch;\nhelper(<<\"regexMatches\">>, [Pattern, Text], _, _) -> lawspec_beam_regex:matches(Pattern, Text);\nhelper(<<\"checked\">>, [_], _, _) -> true;\nhelper(<<\"select\">>, [true, A, _], _, _) -> A;\nhelper(<<\"select\">>, [false, _, B], _, _) -> B;\nhelper(<<\"compare\">>, [A, B], _, _) ->\n    Tag = case compare(A, B) of -1 -> <<\"Less\">>; 0 -> <<\"Equal\">>; 1 -> <<\"Greater\">> end,\n    {ls_data, <<\"lawspec.collections::type::Ordering::\", Tag/binary>>, []};\nhelper(<<\"isPresent\">>, [{ls_presence, _, P}], _, _) -> P =/= none;\nhelper(<<\"presentValue\">>, [{ls_presence, _, {some, V}}], _, _) -> V;\nhelper(<<\"presentValue\">>, [{ls_presence, _, none}], _, _) -> fail(absent_presence_value);\nhelper(<<\"negate\">>, [V], _, _) -> negate(V);\nhelper(Op, [A, B], [TA, TB], _) when Op =:= <<\"quot\">>; Op =:= <<\"rem\">>; Op =:= <<\"pow\">> ->\n    binary(Op, A, B, TA, TB);\nhelper(Name, [V], _, Bits) -> convert(V, Name, Bits);\nhelper(Name, _, _, _) -> fail({unknown_helper, Name}).\n\nnew_symbol(Description) -> {ls_symbol, make_ref(), validate(Description, <<\"Text\">>, 64)}.\ntext(Units) -> unicode:characters_to_binary(checked_units(<<\"Text\">>, Units)).\nchecked_units(Kind, Units) when is_list(Units) -> [unit(Kind, U) || U <- Units].\nunit(Kind, N) when is_integer(N), N >= 0 ->\n    Valid = case Kind of\n        <<\"Bytes\">> -> N =< 255;\n        <<\"CodeUnit16\">> -> N =< 65535;\n        <<\"Utf16Text\">> -> N =< 65535;\n        <<\"CodePoint\">> -> N =< 1114111;\n        <<\"CodePointText\">> -> N =< 1114111;\n        _ -> N =< 1114111 andalso (N < 55296 orelse N > 57343)\n    end,\n    require(Valid, {invalid_character, Kind}), N;\nunit(Kind, _) -> fail({invalid_character, Kind}).\nrequire(true, _) -> ok;\nrequire(false, Reason) -> fail(Reason).\nfail(Reason) -> erlang:error({lawspec, Reason}).\n"
runtimeSource "beam-schema" = "%% @doc Core schemas are the boundary between portable values and native\n%% Erlang tuples, Elixir structs or Gleam constructors. Shapes, GADT equations,\n%% witnesses, index guards and field predicates are checked by the same walk.\n%% ref:DEC-typed-core-boundary ref:DEC-native-bindings-typed-identity\n-module(lawspec_beam_schema).\n-export([new/3, validate/3, construct/4, match/2, constructors/2, witness_instances/1,\n    to_native/3, from_native/3, all_payloads/4, substitute/2, index/4,\n    check_type/2, handle/2, with_codecs/2, with_bindings/3, constructor_shape/2, type_key/1]).\n-export_type([schema/0, value/0, type_ref/0]).\n\n-type type_ref() :: {binary(), [type_ref()]} | {parameter, non_neg_integer()}.\n-type value() :: term().\n-opaque schema() :: #{definitions := map(), arities := map(), bits := 32 | 64,\n    codecs := map()}.\n\nnew(Definitions, Primitives, Bits) when Bits =:= 32; Bits =:= 64 ->\n    Builtins = [{<<\"List\">>, 1}, {<<\"Maybe\">>, 1}, {<<\"Either\">>, 2},\n        {<<\"Nullable\">>, 1}, {<<\"Optional\">>, 1}],\n    Names = [maps:get(name, D) || D <- Definitions],\n    Unique = Names ++ Primitives ++ [N || {N, _} <- Builtins],\n    require(length(Unique) =:= length(lists:usort(Unique)), duplicate_type),\n    Ds = maps:from_list([{maps:get(name, D), D} || D <- Definitions]),\n    Arities = maps:from_list([{N, 0} || N <- Primitives] ++ Builtins ++\n        [{maps:get(name, D), maps:get(parameters, D)} || D <- Definitions]),\n    Schema = #{definitions => Ds, arities => Arities, bits => Bits, codecs => #{}},\n    Tags = [maps:get(tag, C) || D <- Definitions, C <- maps:get(constructors, D)],\n    require(length(Tags) =:= length(lists:usort(Tags)), duplicate_constructor),\n    lists:foreach(fun(D) -> audit_definition(D, Schema) end, Definitions),\n    Schema.\n\naudit_definition(#{parameters := Count, constructors := Cs}, S) ->\n    require(is_integer(Count) andalso Count >= 0, invalid_parameter_count),\n    lists:foreach(fun(C) ->\n        Fields = maps:get(fields, C),\n        Names = [N || {N, _} <- Fields],\n        require(length(Names) =:= length(lists:usort(Names)), duplicate_field),\n        Extra = maps:get(existentials, C, 0),\n        require(is_integer(Extra) andalso Extra >= 0, invalid_existentials),\n        Scope = Count + Extra,\n        lists:foreach(fun({_, T}) -> check_type(T, Scope, S) end, Fields),\n        lists:foreach(fun({I, T}) ->\n            require(is_integer(I) andalso I >= 0 andalso I < Count, invalid_refined_parameter),\n            check_type(T, Scope, S)\n        end, maps:get(refinements, C, [])),\n        Witnesses = maps:get(witnesses, C, []),\n        require(length(Witnesses) =< length(Fields), invalid_witnesses),\n        lists:foreach(fun(I) ->\n            require(is_integer(I) andalso I >= Count andalso I < Scope, invalid_witness)\n        end, Witnesses),\n        lists:foreach(fun(P) -> require(is_function(P, 3), invalid_predicate) end,\n            maps:get(predicates, C, []))\n    end, Cs).\n\ncheck_type(T, S) -> check_type(T, 0, S).\ncheck_type(T, Scope, S) when is_binary(T) -> check_type(lawspec_beam_scalar:type(T), Scope, S);\ncheck_type({parameter, I}, Scope, _) ->\n    require(is_integer(I) andalso I >= 0 andalso I < Scope, unbound_schema_parameter);\ncheck_type({Name, Args}, Scope, #{arities := Arities} = S) when is_binary(Name), is_list(Args) ->\n    require(maps:get(Name, Arities, missing) =:= length(Args), {unknown_type_or_arity, Name}),\n    lists:foreach(fun(T) -> check_type(T, Scope, S) end, Args);\ncheck_type(_, _, _) -> fail(invalid_type_reference).\n\nsubstitute({parameter, I} = T, Known) -> maps:get(I, Known, T);\nsubstitute({Name, Args}, Known) -> {Name, [substitute(T, Known) || T <- Args]}.\n\ntype_key(T) when is_binary(T) -> T;\ntype_key({Name, []}) -> Name;\ntype_key({Name, Args}) ->\n    iolist_to_binary([Name, [[<<\" (\">>, type_key(T), <<\")\">>] || T <- Args]]).\n\n%% @doc GADT equations can bind existential parameters, while a witnessed\n%% existential stays open until its trailing Text field supplies its type.\n%% ref:DEC-gadts-and-index-arithmetic\nconstructors(T, S) when is_binary(T) -> constructors(lawspec_beam_scalar:type(T), S);\nconstructors({Name, Args} = T, #{definitions := Ds} = S) ->\n    check_type(T, S),\n    case maps:find(Name, Ds) of\n        error -> builtin_constructors(Name, Args);\n        {ok, D} -> lists:filtermap(fun(C) -> instantiate(C, Args) end, maps:get(constructors, D))\n    end.\n\ninstantiate(C, Args) ->\n    Known = maps:from_list(lists:zip(lists:seq(0, length(Args) - 1), Args)),\n    Bound = lists:foldl(fun\n        (_, mismatch) -> mismatch;\n        ({I, Pattern}, K) -> unify(Pattern, lists:nth(I + 1, Args), K)\n    end, Known, maps:get(refinements, C, [])),\n    case Bound of\n        mismatch -> false;\n        _ -> {true, C#{fields => [{N, substitute(T, Bound)} || {N, T} <- maps:get(fields, C)]}}\n    end.\n\nunify({parameter, I}, Actual, Known) ->\n    case maps:find(I, Known) of\n        error -> Known#{I => Actual};\n        {ok, Actual} -> Known;\n        _ -> mismatch\n    end;\nunify({Name, Ps}, {Name, As}, Known) when length(Ps) =:= length(As) ->\n    lists:foldl(fun\n        (_, mismatch) -> mismatch;\n        ({P, A}, K) -> unify(P, A, K)\n    end, Known, lists:zip(Ps, As));\nunify(_, _, _) -> mismatch.\n\nbuiltin_constructors(<<\"Maybe\">>, [T]) ->\n    [#{tag => <<\"Maybe::Nothing\">>, fields => [], native_tag => nothing},\n     #{tag => <<\"Maybe::Just\">>, fields => [{<<\"value\">>, T}], native_tag => just}];\nbuiltin_constructors(<<\"Either\">>, [A, B]) ->\n    [#{tag => <<\"Either::Left\">>, fields => [{<<\"value\">>, A}], native_tag => left},\n     #{tag => <<\"Either::Right\">>, fields => [{<<\"value\">>, B}], native_tag => right}];\nbuiltin_constructors(_, _) -> none.\n\nwith_codecs(#{codecs := Existing} = S, Codecs) ->\n    maps:foreach(fun(Name, #{encode := Encode, decode := Decode}) ->\n        require(maps:is_key(Name, maps:get(arities, S)), {unknown_codec_type, Name}),\n        require(is_function(Encode, 2) andalso is_function(Decode, 2), invalid_codec)\n    end, Codecs),\n    S#{codecs => maps:merge(Existing, Codecs)}.\n\n%% Application mappings change native shapes while keeping the same logical\n%% contracts. A codec receives canonical native values, not internal ls_data\n%% tuples; its child converters cross between canonical and bound native data.\n%% ref:DEC-native-bindings-typed-identity\nwith_bindings(#{definitions := Definitions} = S, Shapes, Hooks) ->\n    Constructors = maps:from_list([{maps:get(tag, C), Name} || {Name, D} <- maps:to_list(Definitions),\n        C <- maps:get(constructors, D)]),\n    maps:foreach(fun(Tag, Shape) ->\n        require(maps:is_key(Tag, Constructors), {unknown_native_constructor, Tag}),\n        case Shape of\n            #{native_tag := Atom} when map_size(Shape) =:= 1, is_atom(Atom) -> ok;\n            #{encode := Encode, decode := Decode} when map_size(Shape) =:= 2,\n                    is_function(Encode, 1), is_function(Decode, 1) -> ok;\n            _ -> fail({invalid_native_shape, Tag})\n        end\n    end, Shapes),\n    NativeShapes = maps:merge(maps:get(native_shapes, S, #{}), Shapes),\n    Existing = maps:get(native_codecs, S, #{}),\n    Combined = maps:merge(Existing, Hooks),\n    maps:foreach(fun(Name, Hook) ->\n        require(maps:is_key(Name, Definitions) andalso\n            maps:get(constructors, maps:get(Name, Definitions)) =/= [], {unknown_native_codec, Name}),\n        require(not lists:any(fun(Tag) -> maps:get(Tag, Constructors) =:= Name end, maps:keys(NativeShapes)),\n            {conflicting_native_binding, Name}),\n        case Hook of\n            #{encode := Encode, decode := Decode} when map_size(Hook) =:= 2,\n                    is_function(Encode, 2), is_function(Decode, 2) -> ok;\n            _ -> fail({invalid_native_codec, Name})\n        end\n    end, Combined),\n    Native = maps:map(fun(_, D) -> D#{constructors => [case maps:find(maps:get(tag, C), Shapes) of\n        error -> C;\n        {ok, Shape} -> maps:merge(maps:without([native_tag, encode, decode], C), Shape)\n    end || C <- maps:get(constructors, D)]} end, Definitions),\n    S#{definitions => Native, native_codecs => Combined, native_shapes => NativeShapes,\n        canonical => maps:get(canonical, S, S)}.\n\n%% A generated Gleam helper calls the application's constructor by field name.\n%% Unique markers reveal the compiler's tuple positions without guessing its\n%% field order or duplicating its constructor-name normalization. The helper\n%% only constructs a custom-type value; it never calls application functions.\n%% ref:DEC-native-bindings-typed-identity\nconstructor_shape(Encode, Count) when is_function(Encode, 1), is_integer(Count), Count >= 0 ->\n    Markers = [make_ref() || _ <- lists:seq(1, Count)],\n    Template = Encode(Markers),\n    case {Count, Template} of\n        {0, Tag} when is_atom(Tag) -> #{native_tag => Tag};\n        {_, Tuple} when is_tuple(Tuple), tuple_size(Tuple) =:= Count + 1,\n                is_atom(element(1, Tuple)) ->\n            Positions = [[I || I <- lists:seq(2, Count + 1), element(I, Tuple) =:= Marker] || Marker <- Markers],\n            require(lists:all(fun(P) -> length(P) =:= 1 end, Positions), invalid_constructor_shape),\n            Tag = element(1, Tuple),\n            #{encode => Encode, decode => fun\n                (V) when is_tuple(V), tuple_size(V) =:= Count + 1, element(1, V) =:= Tag ->\n                    {ok, [element(I, V) || [I] <- Positions]};\n                (_) -> no_match\n            end};\n        _ -> fail(invalid_constructor_shape)\n    end.\n\nvalidate(Value, T, S) when is_binary(T) -> validate(Value, lawspec_beam_scalar:type(T), S);\nvalidate(Value, T, S) -> check_type(T, S), walk(Value, T, S, validate).\n\nto_native(Value, T, S) when is_binary(T) -> to_native(Value, lawspec_beam_scalar:type(T), S);\nto_native(Value, T, S) -> walk(validate(Value, T, S), T, S, encode).\nfrom_native(Value, T, S) when is_binary(T) -> from_native(Value, lawspec_beam_scalar:type(T), S);\nfrom_native(Value, T, S) -> check_type(T, S), validate(walk(Value, T, S, decode), T, S).\n\nwalk(Value, {Name, Args} = T, #{codecs := Codecs} = S, Mode)\n        when Mode =:= encode; Mode =:= decode ->\n    case maps:find(Name, maps:get(native_codecs, S, #{})) of\n        {ok, Hook} -> native_codec(Value, T, S, Mode, Hook);\n        error -> case maps:find(Name, Codecs) of\n        {ok, Codec} ->\n            Children = [fun(V) -> case Mode of\n                encode -> to_native(V, Child, S);\n                decode -> from_native(V, Child, S)\n            end end || Child <- Args],\n            (maps:get(Mode, Codec))(Value, Children);\n            error -> walk_shape(Value, T, S, Mode)\n        end\n    end;\nwalk(Value, T, S, Mode) -> walk_shape(Value, T, S, Mode).\n\nnative_codec(Value, {Name, Args} = T, #{canonical := Canonical} = S, Mode, Hook) ->\n    try\n        Children = [fun(V) -> case Mode of\n            encode -> to_native(from_native(V, Child, Canonical), Child, S);\n            decode -> to_native(from_native(V, Child, S), Child, Canonical)\n        end end || Child <- Args],\n        Convert = maps:get(Mode, Hook),\n        case Mode of\n            encode -> Convert(to_native(Value, T, Canonical), Children);\n            decode -> from_native(Convert(Value, Children), T, Canonical)\n        end\n    catch Kind:Reason:Stack ->\n        erlang:raise(error, {lawspec, {native_codec, Name, Mode, Kind, Reason}}, Stack)\n    end.\n\nwalk_shape(Values, {<<\"List\">>, [T]}, S, Mode) when is_list(Values) ->\n    [walk(V, T, S, Mode) || V <- Values];\nwalk_shape(ls_unit, {<<\"Unit\">>, []}, _, encode) -> ok;\nwalk_shape(ok, {<<\"Unit\">>, []}, _, decode) -> ls_unit;\nwalk_shape(ls_null, {<<\"Null\">>, []}, _, encode) -> null;\nwalk_shape(null, {<<\"Null\">>, []}, _, decode) -> ls_null;\nwalk_shape(ls_undefined, {<<\"Undefined\">>, []}, _, encode) -> undefined;\nwalk_shape(undefined, {<<\"Undefined\">>, []}, _, decode) -> ls_undefined;\nwalk_shape({ls_raw, Name, Units}, {Name, []}, _, encode)\n        when Name =:= <<\"CodePointText\">>; Name =:= <<\"Utf16Text\">> -> Units;\nwalk_shape(Units, {Name, []}, _, decode) when is_list(Units),\n        (Name =:= <<\"CodePointText\">> orelse Name =:= <<\"Utf16Text\">>) -> {ls_raw, Name, Units};\nwalk_shape({ls_presence, <<\"Optional\">>, none}, {<<\"Optional\">>, [_]}, _, encode) -> none;\nwalk_shape({ls_presence, <<\"Nullable\">>, none}, {<<\"Nullable\">>, [_]}, _, encode) -> null;\nwalk_shape({ls_presence, Name, {some, V}}, {Name, [T]}, S, encode)\n        when Name =:= <<\"Optional\">>; Name =:= <<\"Nullable\">> ->\n    Tag = case Name of <<\"Optional\">> -> some; <<\"Nullable\">> -> non_null end,\n    {Tag, walk(V, T, S, encode)};\nwalk_shape(none, {<<\"Optional\">>, [_]}, _, decode) -> {ls_presence, <<\"Optional\">>, none};\nwalk_shape(null, {<<\"Nullable\">>, [_]}, _, decode) -> {ls_presence, <<\"Nullable\">>, none};\nwalk_shape({some, V}, {<<\"Optional\">>, [T]}, S, decode) ->\n    {ls_presence, <<\"Optional\">>, {some, walk(V, T, S, decode)}};\nwalk_shape({non_null, V}, {<<\"Nullable\">>, [T]}, S, decode) ->\n    {ls_presence, <<\"Nullable\">>, {some, walk(V, T, S, decode)}};\nwalk_shape({ls_presence, Name, P}, {Name, [T]}, S, Mode)\n        when Name =:= <<\"Optional\">>; Name =:= <<\"Nullable\">> ->\n    {ls_presence, Name, case P of none -> none; {some, V} -> {some, walk(V, T, S, Mode)} end};\nwalk_shape(Value, {Name, _} = T, #{definitions := Ds, bits := Bits} = S, Mode) ->\n    case maps:find(Name, Ds) of\n        {ok, #{handle := true}} -> case Mode of\n            encode -> {ls_handle, Name, Identity} = checked_handle(Value, Name), Identity;\n            decode -> case Value of\n                {ls_handle, _, _} -> checked_handle(Value, Name);\n                _ -> handle(Value, Name)\n            end;\n            _ -> checked_handle(Value, Name)\n        end;\n        _ -> case constructors(T, S) of\n            none -> lawspec_beam_scalar:validate(Value, T, Bits);\n            Cs -> walk_data(Value, T, Cs, S, Mode)\n        end\n    end.\n\nwalk_data(Value, {_, Args}, Cs, S, Mode) ->\n    {C, Fields} = case {Mode, Value} of\n        {decode, _} -> native_fields(Value, Cs);\n        {_, {ls_data, ValueTag, Fs}} -> {find_constructor(ValueTag, Cs), Fs};\n        _ -> fail(expected_data)\n    end,\n    Tag = maps:get(tag, C),\n    Declared = maps:get(fields, C),\n    require(is_list(Fields) andalso length(Fields) =:= length(Declared), {wrong_field_count, Tag}),\n    Typed = witnessed(C, Fields, S),\n    Converted = case Mode of\n        shallow -> Fields;\n        _ -> [walk(F, T, S, Mode) || {F, {_, T}} <- lists:zip(Fields, Typed)]\n    end,\n    case Mode of\n        encode -> native_construct(C, Converted);\n        decode -> {ls_data, Tag, Converted};\n        _ ->\n            check_predicates(C, Args, Converted, S),\n            check_indices(C#{fields => Typed}, Converted, S),\n            {ls_data, Tag, Converted}\n    end.\n\nfind_constructor(Tag, Cs) ->\n    case [C || C <- Cs, maps:get(tag, C) =:= Tag] of\n        [C] -> C;\n        _ -> fail({foreign_constructor, Tag})\n    end.\n\nwitnessed(C, Values, S) ->\n    Witnesses = maps:get(witnesses, C, []),\n    Texts = lists:nthtail(length(Values) - length(Witnesses), Values),\n    Known = maps:from_list([{I, lawspec_beam_scalar:type(Text)} || {I, Text} <- lists:zip(Witnesses, Texts)]),\n    maps:foreach(fun(_, T) -> check_type(T, S) end, Known),\n    [{N, substitute(T, Known)} || {N, T} <- maps:get(fields, C)].\n\n%% Generated free existentials use Core's finite Bool/Int32 witness pool.\n%% GADT-bound existentials were already substituted by instantiate/2.\n%% ref:DEC-gadts-and-index-arithmetic\nwitness_instances(C) ->\n    Identities = maps:get(witnesses, C, []),\n    Pool = [{<<\"Bool\">>, []}, {<<\"Int32\">>, []}],\n    Assignments = lists:foldl(fun(I, Previous) ->\n        [Known#{I => T} || Known <- Previous, T <- Pool]\n    end, [#{}], Identities),\n    Fields = lists:sublist(maps:get(fields, C), length(maps:get(fields, C)) - length(Identities)),\n    [C#{fields => [{N, substitute(T, Known)} || {N, T} <- Fields],\n        witness_values => [type_key(maps:get(I, Known)) || I <- Identities]} || Known <- Assignments].\n\ncheck_predicates(C, Args, Values, S) ->\n    lists:foreach(fun(Predicate) ->\n        case Predicate(S, Args, Values) of\n            true -> ok;\n            false -> fail({refinement_violation, maps:get(tag, C)});\n            _ -> fail(non_boolean_predicate)\n        end\n    end, maps:get(predicates, C, [])).\n\nnative_construct(#{encode := F}, Fields) -> F(Fields);\nnative_construct(#{native_tag := Tag}, []) -> Tag;\nnative_construct(#{native_tag := Tag}, Fields) -> list_to_tuple([Tag | Fields]).\n\nnative_fields(_, []) -> fail(invalid_native_constructor);\nnative_fields(V, [#{decode := F} = C | Cs]) ->\n    case F(V) of {ok, Fs} -> {C, Fs}; no_match -> native_fields(V, Cs) end;\nnative_fields(V, [#{native_tag := Tag} = C | Cs]) ->\n    case V of\n        Tag when is_atom(Tag) -> {C, []};\n        Tuple when is_tuple(Tuple), tuple_size(Tuple) > 0, element(1, Tuple) =:= Tag ->\n            [_ | Fields] = tuple_to_list(Tuple), {C, Fields};\n        _ -> native_fields(V, Cs)\n    end;\nnative_fields(V, [_ | Cs]) -> native_fields(V, Cs).\n\n%% @doc Construction is shallow because its fields are already checked Core\n%% values. A native boundary performs a full walk exactly once.\n%% ref:DEC-structural-size-budget\nconstruct(Tag, Fields, T, S) when is_binary(T) ->\n    construct(Tag, Fields, lawspec_beam_scalar:type(T), S);\nconstruct(<<\"List::Nil\">>, [], {<<\"List\">>, [_]}, _) -> [];\nconstruct(<<\"List::Cons\">>, [H, Tail], {<<\"List\">>, [_]}, _) when is_list(Tail) -> [H | Tail];\nconstruct(Tag, Fields, T, S) ->\n    check_type(T, S), walk_data({ls_data, Tag, Fields}, T, constructors(T, S), S, shallow).\n\nmatch([], Branches) -> (maps:get(<<\"List::Nil\">>, Branches))([]);\nmatch([H | T], Branches) -> (maps:get(<<\"List::Cons\">>, Branches))([H, T]);\nmatch({ls_data, Tag, Fields}, Branches) -> (maps:get(Tag, Branches))(Fields).\n\n%% @doc BEAM handles carry identity explicitly. A native process, port or\n%% reference keeps its identity across repeated crossings of the boundary.\n%% A generated actor uses its stable mailbox address, including the child\n%% path: two children of one tree must remain distinct after either restarts.\n%% ref:DEC-native-bindings-typed-identity\nhandle(Value, Name) when is_pid(Value); is_reference(Value); is_port(Value) ->\n    {ls_handle, Name, Value};\nhandle({lawspec_actor, Tree, Path} = Value, Name) when is_pid(Tree), is_list(Path) ->\n    {ls_handle, Name, Value};\nhandle(_, _) -> fail(handle_requires_identity).\nchecked_handle({ls_handle, Name, Identity} = H, Name)\n        when is_pid(Identity); is_reference(Identity); is_port(Identity) -> H;\nchecked_handle({ls_handle, Name, {lawspec_actor, Tree, Path}} = H, Name)\n        when is_pid(Tree), is_list(Path) -> H;\nchecked_handle(_, Name) -> fail({invalid_handle, Name}).\n\n%% @doc Index terms use the same prefix language as Core's schema metadata.\n%% Subtraction is undefined below zero and division is undefined at zero.\n%% ref:DEC-gadts-and-index-arithmetic\nindex({ls_data, Tag, Values}, T, Position, S) ->\n    C0 = find_constructor(Tag, constructors(T, S)),\n    C = C0#{fields => witnessed(C0, Values, S)},\n    Terms = [Tokens || Text <- maps:get(indices, C, []),\n        Tokens <- [tokens(Text)], not guard_tokens(Tokens)],\n    require(Position >= 0 andalso Position < length(Terms), no_index),\n    {Value, []} = eval_index(lists:nth(Position + 1, Terms), C, Values, S),\n    Value.\n\ncheck_indices(C, Values, S) ->\n    lists:foreach(fun(Text) -> case tokens(Text) of\n        [Op | Rest] when Op =:= <<\"==\">>; Op =:= <<\">=\">> ->\n            {A, Next} = eval_index(Rest, C, Values, S),\n            {B, []} = eval_index(Next, C, Values, S),\n            require(A =/= undefined andalso B =/= undefined andalso\n                case Op of <<\"==\">> -> A =:= B; <<\">=\">> -> A >= B end,\n                {refinement_violation, {index_guard, Text}});\n        _ -> ok\n    end end, maps:get(indices, C, [])).\n\ntokens(Text) -> binary:split(Text, <<\" \">>, [global, trim_all]).\nguard_tokens([<<\"==\">> | _]) -> true;\nguard_tokens([<<\">=\">> | _]) -> true;\nguard_tokens(_) -> false.\neval_index([<<\"c\", N/binary>> | Rest], _, _, _) -> {binary_to_integer(N), Rest};\neval_index([<<\"f\", Field/binary>> | Rest], C, Values, S) ->\n    {P, I} = case binary:split(Field, <<\".\">>) of\n        [Pos] -> {binary_to_integer(Pos), 0};\n        [Pos, Idx] -> {binary_to_integer(Pos), binary_to_integer(Idx)}\n    end,\n    {_, T} = lists:nth(P + 1, maps:get(fields, C)),\n    {index(lists:nth(P + 1, Values), T, I, S), Rest};\neval_index([Op | Rest], C, Values, S) ->\n    {A, Next} = eval_index(Rest, C, Values, S),\n    {B, After} = eval_index(Next, C, Values, S),\n    {index_binary(Op, A, B), After}.\nindex_binary(_, undefined, _) -> undefined;\nindex_binary(_, _, undefined) -> undefined;\nindex_binary(<<\"+\">>, A, B) -> A + B;\nindex_binary(<<\"-\">>, A, B) when A >= B -> A - B;\nindex_binary(<<\"*\">>, A, B) -> A * B;\nindex_binary(<<\"div\">>, A, B) when B > 0 -> A div B;\nindex_binary(<<\"mod\">>, A, B) when B > 0 -> A rem B;\nindex_binary(<<\"^\">>, A, B) when B >= 0, B =< 64 ->\n    lawspec_beam_scalar:binary(<<\"pow\">>, A, B, <<\"Integer\">>, <<\"Integer\">>);\nindex_binary(_, _, _) -> undefined.\n\n%% @doc Payload predicates follow declaration parameters rather than the\n%% concrete types they happen to instantiate to. Fixed fields are not payloads.\n%% ref:DEC-typed-core-boundary\nall_payloads(Value, T, Predicates, S) when is_binary(T) ->\n    all_payloads(Value, lawspec_beam_scalar:type(T), Predicates, S);\nall_payloads(Value, {Name, Args} = T, Predicates, S) ->\n    require(length(Args) =:= length(Predicates), payload_arity_mismatch),\n    _ = validate(Value, T, S),\n    Known = [{predicate, P} || P <- Predicates],\n    payload({Name, Known}, Value, S).\n\nrecipe({parameter, I}, Args) ->\n    case I < length(Args) of true -> lists:nth(I + 1, Args); false -> none end;\nrecipe({Name, Fields}, Args) ->\n    Children = [recipe(T, Args) || T <- Fields],\n    case lists:all(fun(T) -> T =:= none end, Children) of\n        true -> none;\n        false -> {Name, Children}\n    end.\npayload(none, _, _) -> true;\npayload({predicate, P}, Value, _) ->\n    Result = P(Value), require(is_boolean(Result), non_boolean_payload_predicate), Result;\npayload({<<\"List\">>, [T]}, Values, S) -> lists:all(fun(V) -> payload(T, V, S) end, Values);\npayload({Name, [_]}, {ls_presence, Name, none}, _) -> true;\npayload({Name, [T]}, {ls_presence, Name, {some, V}}, S) -> payload(T, V, S);\npayload({<<\"Maybe\">>, [_]}, {ls_data, <<\"Maybe::Nothing\">>, []}, _) -> true;\npayload({<<\"Maybe\">>, [T]}, {ls_data, <<\"Maybe::Just\">>, [V]}, S) -> payload(T, V, S);\npayload({<<\"Either\">>, [T, _]}, {ls_data, <<\"Either::Left\">>, [V]}, S) -> payload(T, V, S);\npayload({<<\"Either\">>, [_, T]}, {ls_data, <<\"Either::Right\">>, [V]}, S) -> payload(T, V, S);\npayload({Name, Args}, {ls_data, Tag, Values}, #{definitions := Ds} = S) ->\n    C = find_constructor(Tag, maps:get(constructors, maps:get(Name, Ds))),\n    lists:all(fun({{_, T}, V}) -> payload(recipe(T, Args), V, S) end,\n        lists:zip(maps:get(fields, C), Values)).\n\nrequire(true, _) -> ok;\nrequire(false, Reason) -> fail(Reason).\nfail(Reason) -> erlang:error({lawspec, Reason}).\n"
runtimeSource "beam-regex" = "%% @doc The portable regex grammar runs on Unicode scalar values, not bytes\n%% or the host regex library's character classes. Matching covers the whole\n%% text. Reachable positions avoid backtracking through ambiguous repeats.\n%% ref:DEC-typed-core-boundary\n-module(lawspec_beam_regex).\n-export([compile/1, matches/2, run/2]).\n\ncompile(Pattern) ->\n    _ = lawspec_beam_scalar:validate(Pattern, <<\"Text\">>, 64),\n    {Node, Rest} = alternatives(unicode:characters_to_list(Pattern)),\n    require(Rest =:= [], unmatched_closing_parenthesis),\n    Node.\n\nmatches(Pattern, Text) -> run(compile(Pattern), Text).\nrun(Node, Text) ->\n    _ = lawspec_beam_scalar:validate(Text, <<\"Text\">>, 64),\n    Points = list_to_tuple(unicode:characters_to_list(Text)),\n    lists:member(tuple_size(Points), reach(Node, Points, [0])).\n\nalternatives(Cs) ->\n    {Branch, Rest} = sequence(Cs, []),\n    alternatives(Rest, [Branch]).\nalternatives([$| | Rest], Acc) ->\n    {Branch, Next} = sequence(Rest, []),\n    alternatives(Next, [Branch | Acc]);\nalternatives(Rest, [Only]) -> {Only, Rest};\nalternatives(Rest, Acc) -> {{alt, lists:reverse(Acc)}, Rest}.\n\nsequence([], Acc) -> {{seq, lists:reverse(Acc)}, []};\nsequence([C | _] = Rest, Acc) when C =:= $); C =:= $| ->\n    {{seq, lists:reverse(Acc)}, Rest};\nsequence(Cs, Acc) ->\n    {Atom, Rest} = atom(Cs),\n    {Node, Next} = quantified(Atom, Rest),\n    sequence(Next, [Node | Acc]).\n\natom([$(, $?, $: | Cs]) -> group(Cs);\natom([$(, $? | _]) -> fail(unsupported_group);\natom([$( | Cs]) -> group(Cs);\natom([$[, $^ | Cs]) -> char_class(Cs, true, []);\natom([$[ | Cs]) -> char_class(Cs, false, []);\natom([$. | Cs]) -> {{set, true, [{false, [{10, 10}]}]}, Cs};\natom([$\\\\ | Cs]) ->\n    {Item, Rest} = escape(Cs), {{set, false, [Item]}, Rest};\natom([C | Cs]) ->\n    require(not lists:member(C, \"*+?{^$]}\"), {unexpected_character, C}),\n    {{set, false, [{false, [{C, C}]}]}, Cs};\natom([]) -> fail(missing_atom).\ngroup(Cs) ->\n    {Node, Rest} = alternatives(Cs),\n    case Rest of [$) | Next] -> {Node, Next}; _ -> fail(unclosed_group) end.\n\nescape([C | Cs]) when C =:= $d; C =:= $D -> {{C =:= $D, [{48, 57}]}, Cs};\nescape([C | Cs]) when C =:= $w; C =:= $W ->\n    {{C =:= $W, [{48, 57}, {65, 90}, {95, 95}, {97, 122}]}, Cs};\nescape([C | Cs]) when C =:= $s; C =:= $S -> {{C =:= $S, [{9, 13}, {32, 32}]}, Cs};\nescape([C | Cs]) ->\n    case lists:keyfind(C, 1, [{$n, 10}, {$t, 9}, {$r, 13}, {$f, 12}, {$v, 11}]) of\n        {_, V} -> {{false, [{V, V}]}, Cs};\n        false ->\n            require(lists:member(C, \"\\\\.^$|?*+()[]{}-/\"), {unsupported_escape, C}),\n            {{false, [{C, C}]}, Cs}\n    end;\nescape([]) -> fail(trailing_escape).\n\nclass_item([$\\\\ | Cs]) -> escape(Cs);\nclass_item([$[ | _]) -> fail(unescaped_class_open);\nclass_item([C | Cs]) -> {{false, [{C, C}]}, Cs};\nclass_item([]) -> fail(unclosed_class).\nchar_class([], _, _) -> fail(unclosed_class);\nchar_class([$] | _], _, []) -> fail(empty_class);\nchar_class([$] | Cs], Negated, Acc) -> {{set, Negated, lists:reverse(Acc)}, Cs};\nchar_class(Cs, Negated, Acc) ->\n    {Item, Rest} = class_item(Cs),\n    case {Item, Rest} of\n        {{false, [{Lo, Lo}]}, [$-, C | Tail]} when C =/= $] ->\n            {High, Next} = class_item([C | Tail]),\n            case High of\n                {false, [{Hi, Hi}]} when Hi >= Lo ->\n                    char_class(Next, Negated, [{false, [{Lo, Hi}]} | Acc]);\n                _ -> fail(invalid_class_range)\n            end;\n        _ -> char_class(Rest, Negated, [Item | Acc])\n    end.\n\nquantified(Node, [$* | Cs]) -> repeat(Node, 0, infinity, Cs);\nquantified(Node, [$+ | Cs]) -> repeat(Node, 1, infinity, Cs);\nquantified(Node, [$? | Cs]) -> repeat(Node, 0, 1, Cs);\nquantified(Node, [${ | Cs]) ->\n    {Low, Rest} = count(Cs),\n    case Rest of\n        [$} | Next] -> repeat(Node, Low, Low, Next);\n        [$,, $} | Next] -> repeat(Node, Low, infinity, Next);\n        [$, | Tail] ->\n            {High, After} = count(Tail),\n            case After of\n                [$} | Next] -> repeat(Node, Low, High, Next);\n                _ -> fail(unclosed_repetition)\n            end;\n        _ -> fail(invalid_repetition)\n    end;\nquantified(Node, Cs) -> {Node, Cs}.\n\nrepeat(Node, Low, High, Cs) ->\n    require(Low =< 1000 andalso (High =:= infinity orelse (High =< 1000 andalso High >= Low)),\n        invalid_repetition_count),\n    case Cs of\n        [C | _] -> require(not lists:member(C, \"*+?{\"), repeated_quantifier);\n        [] -> ok\n    end,\n    {{repeat, Node, Low, High}, Cs}.\ncount(Cs) ->\n    {Digits, Rest} = lists:splitwith(fun(C) -> C >= $0 andalso C =< $9 end, Cs),\n    require(Digits =/= [], missing_repetition_count),\n    {list_to_integer(Digits), Rest}.\n\nreach({set, Negated, Items}, Text, Positions) ->\n    [P + 1 || P <- Positions, P < tuple_size(Text),\n        in_set(element(P + 1, Text), Items) =/= Negated];\nreach({seq, Nodes}, Text, Positions) ->\n    lists:foldl(fun(Node, Ps) -> reach(Node, Text, Ps) end, Positions, Nodes);\nreach({alt, Nodes}, Text, Positions) ->\n    ordsets:union([reach(Node, Text, Positions) || Node <- Nodes]);\nreach({repeat, Node, Low, High}, Text, Positions) ->\n    Required = repeat_required(Node, Text, Positions, Low),\n    Limit = case High of infinity -> infinity; _ -> High - Low end,\n    repeat_reach(Node, Text, Required, Required, Limit).\nin_set(C, Items) ->\n    lists:any(fun({Neg, Ranges}) ->\n        Neg =/= lists:any(fun({Lo, Hi}) -> C >= Lo andalso C =< Hi end, Ranges)\n    end, Items).\nrepeat_required(_, _, [], _) -> [];\nrepeat_required(_, _, Ps, 0) -> Ps;\nrepeat_required(Node, Text, Ps, N) -> repeat_required(Node, Text, reach(Node, Text, Ps), N - 1).\nrepeat_reach(_, _, _, Seen, 0) -> Seen;\nrepeat_reach(_, _, [], Seen, _) -> Seen;\nrepeat_reach(Node, Text, Frontier, Seen, Limit) ->\n    Next = ordsets:subtract(reach(Node, Text, Frontier), Seen),\n    Remaining = case Limit of infinity -> infinity; _ -> Limit - 1 end,\n    repeat_reach(Node, Text, Next, ordsets:union(Seen, Next), Remaining).\n\nrequire(true, _) -> ok;\nrequire(false, Reason) -> fail(Reason).\nfail(Reason) -> erlang:error({lawspec, {non_portable_regex, Reason}}).\n"
runtimeSource "beam-random" = "%% @doc The portable SplitMix64 sequence, with its state passed explicitly so\n%% concurrent callers never draw from one another's stream.\n%% ref:splitmix ref:DEC-portable-seeded-generation\n-module(lawspec_beam_random).\n-export([seed/1, next/1, below/2]).\n-define(MASK, 16#ffffffffffffffff).\n\nseed(N) when is_integer(N) -> N band ?MASK.\nnext(State) ->\n    S = (State + 16#9e3779b97f4a7c15) band ?MASK,\n    A = ((S bxor (S bsr 30)) * 16#bf58476d1ce4e5b9) band ?MASK,\n    B = ((A bxor (A bsr 27)) * 16#94d049bb133111eb) band ?MASK,\n    {B bxor (B bsr 31), S}.\nbelow(Bound, State) when is_integer(Bound), Bound > 0 ->\n    {N, Next} = next(State), {N rem Bound, Next};\nbelow(Bound, State) when is_integer(Bound), Bound =< 0 -> {0, State}.\n"
runtimeSource "beam-values" = "%% @doc Model and scenario descriptors share seeded generation, shrinking,\n%% rendering and canonical wire bytes with every other target. Descriptor\n%% identifiers remain binaries: reading input never interns a BEAM atom.\n%% ref:DEC-portable-seeded-generation ref:DEC-distribution-canonical-wire\n-module(lawspec_beam_values).\n-export([read_descriptor/1, from_text/1, generate/4, minimal/2, shrink/3,\n    render/1, encode/3, decode/3, decode_prefix/3, resolve/2, varint/1, read_varint/1]).\n\nread_descriptor(Text) when is_binary(Text) ->\n    {Forms, Rest} = forms(unicode:characters_to_list(Text), []),\n    require(Rest =:= [], trailing_descriptor_input), Forms.\nforms(Cs, Acc) -> case skip(Cs) of\n    [] -> {lists:reverse(Acc), []};\n    [$) | _] = Rest -> {lists:reverse(Acc), Rest};\n    Rest -> {V, Next} = item(Rest), forms(Next, [V | Acc])\nend.\nskip([C | Cs]) when C =:= $\\s; C =:= $\\n; C =:= $\\r; C =:= $\\t -> skip(Cs);\nskip(Cs) -> Cs.\nitem([$( | Cs]) ->\n    {Children, Rest} = forms(Cs, []),\n    case Rest of [$) | Next] -> {Children, Next}; _ -> fail(unclosed_descriptor) end;\nitem([$\" | Cs]) -> quoted(Cs, []);\nitem(Cs) ->\n    {Chars, Rest} = lists:splitwith(fun(C) -> not lists:member(C, \" \\t\\r\\n()\") end, Cs),\n    require(Chars =/= [], empty_descriptor_atom),\n    Value = case Chars of\n        \"_\" -> none;\n        _ -> case string:to_integer(Chars) of\n            {N, []} -> N;\n            _ -> unicode:characters_to_binary(Chars)\n        end\n    end,\n    {Value, Rest}.\nquoted([$\\\\, C | Cs], Acc) -> quoted(Cs, [C | Acc]);\nquoted([$\" | Cs], Acc) -> {{quoted, unicode:characters_to_binary(lists:reverse(Acc))}, Cs};\nquoted([C | Cs], Acc) -> quoted(Cs, [C | Acc]);\nquoted([], _) -> fail(unclosed_descriptor_string).\n\nfrom_text(Text) ->\n    Forms = read_descriptor(Text),\n    require(Forms =/= [], empty_descriptor),\n    {maps:from_list([{unquote(Name), D} || [<<\"data\">>, Name | _] = D <- Forms]), lists:last(Forms)}.\nunquote({quoted, B}) -> B;\nunquote(B) -> B.\nresolve([<<\"ref\">>, Name], Table) -> maps:get(unquote(Name), Table);\nresolve(D, _) -> D.\n\n%% @doc These draws intentionally follow the portable descriptor algorithm,\n%% including each boundary-choice draw, so a seed replays an existing run.\n%% ref:DEC-portable-seeded-generation\ngenerate(D, Table, State, Size) when is_integer(Size), Size >= 0 ->\n    generate_resolved(resolve(D, Table), Table, State, Size).\ngenerate_resolved([<<\"int\">>, _, _, _] = D, _, State, _) ->\n    {Lo, Hi} = generation_bounds(D),\n    {Choice, S1} = lawspec_beam_random:below(10, State),\n    case Choice < 2 of\n        true ->\n            {I, S2} = lawspec_beam_random:below(4, S1),\n            {lists:nth(I + 1, [Lo, Hi, min(max(0, Lo), Hi), min(max(1, Lo), Hi)]), S2};\n        false -> {N, S2} = lawspec_beam_random:below(Hi - Lo + 1, S1), {Lo + N, S2}\n    end;\ngenerate_resolved([<<\"bool\">>], _, State, _) ->\n    {N, Next} = lawspec_beam_random:below(2, State), {N =:= 1, Next};\ngenerate_resolved([<<\"text\">>], _, State, Size) ->\n    {Count, S1} = lawspec_beam_random:below(Size + 1, State),\n    {Chars, S2} = draw_n(Count, fun(S) -> {N, S0} = lawspec_beam_random:below(95, S), {N + 32, S0} end, S1),\n    {list_to_binary(Chars), S2};\ngenerate_resolved([<<\"unit\">>], _, State, _) -> {ls_unit, State};\ngenerate_resolved([<<\"list\">>, D], Table, State, Size) ->\n    {Count, S1} = lawspec_beam_random:below(Size + 1, State),\n    draw_n(Count, fun(S) -> generate(D, Table, S, Size) end, S1);\ngenerate_resolved([<<\"maybe\">>, D], Table, State, Size) ->\n    {Choice, S1} = lawspec_beam_random:below(4, State),\n    case Choice of\n        0 -> {{ls_data, <<\"Maybe::Nothing\">>, []}, S1};\n        _ -> {V, S2} = generate(D, Table, S1, Size), {{ls_data, <<\"Maybe::Just\">>, [V]}, S2}\n    end;\ngenerate_resolved([<<\"either\">>, A, B], Table, State, Size) ->\n    {Choice, S1} = lawspec_beam_random:below(2, State),\n    {Tag, D} = case Choice of 0 -> {<<\"Either::Left\">>, A}; _ -> {<<\"Either::Right\">>, B} end,\n    {V, S2} = generate(D, Table, S1, Size), {{ls_data, Tag, [V]}, S2};\ngenerate_resolved([<<\"data\">>, _ | Cs], Table, State, Size) ->\n    Choices = case Size of 0 -> base(Cs); _ -> Cs end,\n    {I, S1} = lawspec_beam_random:below(length(Choices), State),\n    [<<\"ctor\">>, Tag | Ds] = lists:nth(I + 1, Choices),\n    {Fields, S2} = lists:mapfoldl(fun(D, S) -> generate(D, Table, S, max(Size - 1, 0)) end, S1, Ds),\n    {{ls_data, unquote(Tag), Fields}, S2};\ngenerate_resolved(D, _, _, _) -> fail({unsupported_generation_descriptor, D}).\n\ndraw_n(N, F, State) -> lists:mapfoldl(fun(_, S) -> F(S) end, State, lists:seq(1, N)).\ngeneration_bounds([<<\"int\">>, _, none, none]) -> {-1000000, 1000000};\ngeneration_bounds([<<\"int\">>, _, none, Hi]) -> {min(-1000000, Hi - 2000000), Hi};\ngeneration_bounds([<<\"int\">>, _, Lo, none]) -> {Lo, max(1000000, Lo + 2000000)};\ngeneration_bounds([<<\"int\">>, _, Lo, Hi]) -> {Lo, Hi}.\nbase(Cs) ->\n    Found = [C || [<<\"ctor\">>, _ | Fields] = C <- Cs, not lists:any(fun mentions_data/1, Fields)],\n    case Found of [] -> Cs; _ -> Found end.\nmentions_data([<<\"ref\">> | _]) -> true;\nmentions_data([<<\"data\">> | _]) -> true;\nmentions_data([_ | Fields]) -> lists:any(fun mentions_data/1, Fields);\nmentions_data(_) -> false.\n\nminimal(D, Table) -> minimal_resolved(resolve(D, Table), Table).\nminimal_resolved([<<\"int\">>, _, _, _] = D, _) ->\n    {Lo, Hi} = generation_bounds(D), min(max(0, Lo), Hi);\nminimal_resolved([<<\"bool\">>], _) -> false;\nminimal_resolved([<<\"text\">>], _) -> <<>>;\nminimal_resolved([<<\"unit\">>], _) -> ls_unit;\nminimal_resolved([<<\"list\">>, _], _) -> [];\nminimal_resolved([<<\"maybe\">>, _], _) -> {ls_data, <<\"Maybe::Nothing\">>, []};\nminimal_resolved([<<\"either\">>, A, _], Table) -> {ls_data, <<\"Either::Left\">>, [minimal(A, Table)]};\nminimal_resolved([<<\"data\">>, _ | Cs], Table) ->\n    [[<<\"ctor\">>, Tag | Ds] | _] = base(Cs),\n    {ls_data, unquote(Tag), [minimal(D, Table) || D <- Ds]}.\n\n%% @doc Shrinks are ordered and deduplicated identically to the portable\n%% runtime, and integer candidates remain inside the descriptor's bounds.\n%% ref:DEC-shrink-within-domain\nshrink(D, V, Table) ->\n    Candidates = shrink_resolved(resolve(D, Table), V, Table),\n    unique(Candidates, [V], []).\nunique([], _, Acc) -> lists:reverse(Acc);\nunique([C | Cs], Seen, Acc) -> case lists:member(C, Seen) of\n    true -> unique(Cs, Seen, Acc);\n    false -> unique(Cs, [C | Seen], [C | Acc])\nend.\nshrink_resolved([<<\"int\">>, _, _, _] = D, V, Table) ->\n    Target = minimal(D, Table),\n    case V =:= Target of\n        true -> [];\n        false -> [Target, V - (V - Target) div 2, V - case V > Target of true -> 1; false -> -1 end]\n    end;\nshrink_resolved([<<\"bool\">>], true, _) -> [false];\nshrink_resolved([<<\"bool\">>], false, _) -> [];\nshrink_resolved([<<\"text\">>], V, _) ->\n    [unicode:characters_to_binary(Cs) || Cs <- shrink_sequence(unicode:characters_to_list(V))];\nshrink_resolved([<<\"list\">>, D], Vs, Table) ->\n    shrink_sequence(Vs) ++ replace_shrinks(Vs, fun(V) -> shrink(D, V, Table) end);\nshrink_resolved([<<\"maybe\">>, D], {ls_data, <<\"Maybe::Just\">>, [V]}, Table) ->\n    [{ls_data, <<\"Maybe::Nothing\">>, []} | [{ls_data, <<\"Maybe::Just\">>, [C]} || C <- shrink(D, V, Table)]];\nshrink_resolved([<<\"maybe\">>, _], {ls_data, <<\"Maybe::Nothing\">>, []}, _) -> [];\nshrink_resolved([<<\"either\">>, A, B], {ls_data, Tag, [V]}, Table) ->\n    D = case Tag of <<\"Either::Left\">> -> A; <<\"Either::Right\">> -> B end,\n    [{ls_data, Tag, [C]} || C <- shrink(D, V, Table)];\nshrink_resolved([<<\"data\">>, Name | Cs] = D, {ls_data, Tag, Fields}, Table) ->\n    [<<\"ctor\">>, _ | Ds] = constructor(Tag, Cs),\n    [minimal(D, Table)] ++ [F || {F, FD} <- lists:zip(Fields, Ds), FD =:= [<<\"ref\">>, Name]] ++\n        [{ls_data, Tag, Fs} || Fs <- field_shrinks(Fields, Ds, Table)];\nshrink_resolved([<<\"unit\">>], ls_unit, _) -> [].\nshrink_sequence([]) -> [];\nshrink_sequence(Vs) -> [[], lists:sublist(Vs, length(Vs) div 2)] ++\n    [A ++ Rest || I <- lists:seq(0, length(Vs) - 1), {A, [_ | Rest]} <- [lists:split(I, Vs)]].\nreplace_shrinks(Vs, Shrink) ->\n    [A ++ [C | Rest] || I <- lists:seq(0, length(Vs) - 1),\n        {A, [V | Rest]} <- [lists:split(I, Vs)], C <- Shrink(V)].\nfield_shrinks(Vs, Ds, Table) ->\n    [A ++ [C | Rest] || {I, D} <- lists:zip(lists:seq(0, length(Ds) - 1), Ds),\n        {A, [V | Rest]} <- [lists:split(I, Vs)], C <- shrink(D, V, Table)].\n\nrender(V) -> iolist_to_binary(render_value(V)).\nrender_value(true) -> <<\"true\">>;\nrender_value(false) -> <<\"false\">>;\nrender_value(ls_unit) -> <<\"()\">>;\nrender_value(N) when is_integer(N) -> integer_to_binary(N);\nrender_value(B) when is_binary(B) ->\n    Escaped = binary:replace(binary:replace(B, <<\"\\\\\">>, <<\"\\\\\\\\\">>, [global]), <<\"\\\"\">>, <<\"\\\\\\\"\">>, [global]),\n    [$\", Escaped, $\"];\nrender_value(Vs) when is_list(Vs) -> [$[, lists:join(<<\", \">>, [render_value(V) || V <- Vs]), $]];\nrender_value({ls_data, Tag, Fields}) ->\n    Name = lists:last(binary:split(Tag, <<\"::\">>, [global])),\n    case Fields of [] -> Name; _ -> [Name, $(, lists:join(<<\", \">>, [render_value(V) || V <- Fields]), $)] end.\n\nencode(D, V, Table) -> iolist_to_binary(put(resolve(D, Table), V, Table)).\nput([<<\"int\">>, _, Lo, Hi], V, _) ->\n    check_integer(V, Lo, Hi), varint(case V >= 0 of true -> V * 2; false -> -V * 2 - 1 end);\nput([<<\"bool\">>], V, _) when is_boolean(V) -> case V of true -> <<1>>; false -> <<0>> end;\nput([<<\"unit\">>], ls_unit, _) -> <<>>;\nput([Kind], V, _) when Kind =:= <<\"text\">>; Kind =:= <<\"bytes\">>; Kind =:= <<\"end\">> ->\n    check_binary(Kind, V), [varint(byte_size(V)), V];\nput([<<\"list\">>, D], Vs, Table) when is_list(Vs) ->\n    [varint(length(Vs)), [put(resolve(D, Table), V, Table) || V <- Vs]];\nput([<<\"maybe\">>, _], {ls_data, <<\"Maybe::Nothing\">>, []}, _) -> <<0>>;\nput([<<\"maybe\">>, D], {ls_data, <<\"Maybe::Just\">>, [V]}, Table) ->\n    [1, put(resolve(D, Table), V, Table)];\nput([<<\"either\">>, A, _], {ls_data, <<\"Either::Left\">>, [V]}, Table) ->\n    [0, put(resolve(A, Table), V, Table)];\nput([<<\"either\">>, _, B], {ls_data, <<\"Either::Right\">>, [V]}, Table) ->\n    [1, put(resolve(B, Table), V, Table)];\nput([<<\"data\">>, _ | Cs], {ls_data, Tag, Fields}, Table) ->\n    C = constructor(Tag, Cs), [<<\"ctor\">>, _ | Ds] = C,\n    require(length(Ds) =:= length(Fields), wire_field_count),\n    Index = length(lists:takewhile(fun(Other) -> Other =/= C end, Cs)),\n    [varint(Index), [put(resolve(D, Table), V, Table) || {D, V} <- lists:zip(Ds, Fields)]];\nput(D, _, _) -> fail({invalid_wire_value, D}).\nconstructor(Tag, Cs) ->\n    case [C || [<<\"ctor\">>, T | _] = C <- Cs, unquote(T) =:= Tag] of\n        [C] -> C;\n        _ -> fail({foreign_wire_constructor, Tag})\n    end.\ncheck_integer(V, Lo, Hi) ->\n    require(is_integer(V) andalso (Lo =:= none orelse V >= Lo) andalso\n        (Hi =:= none orelse V =< Hi), wire_integer_out_of_range).\ncheck_binary(Kind, V) ->\n    require(is_binary(V), wire_binary_required),\n    case Kind of\n        <<\"bytes\">> -> ok;\n        _ -> require(is_list(unicode:characters_to_list(V)), wire_invalid_utf8)\n    end.\n\nvarint(N) when is_integer(N), N >= 0, N < 128 -> <<N>>;\nvarint(N) when is_integer(N), N >= 128 -> [(N band 127) bor 128 | varint_list(N bsr 7)].\nvarint_list(N) when N < 128 -> [N];\nvarint_list(N) -> [(N band 127) bor 128 | varint_list(N bsr 7)].\nread_varint(B) -> read_varint(B, 0, 0).\nread_varint(<<Byte, Rest/binary>>, Acc, Shift) ->\n    N = Acc bor ((Byte band 127) bsl Shift),\n    case Byte < 128 of true -> {N, Rest}; false -> read_varint(Rest, N, Shift + 7) end;\nread_varint(<<>>, _, _) -> fail(truncated_wire_value).\n\ndecode(D, Bytes, Table) ->\n    {V, Rest} = decode_prefix(D, Bytes, Table),\n    require(Rest =:= <<>>, trailing_wire_bytes), V.\ndecode_prefix(D, Bytes, Table) -> get(resolve(D, Table), Bytes, Table).\nget([<<\"int\">>, _, Lo, Hi], B, _) ->\n    {Z, Rest} = read_varint(B),\n    V = case Z rem 2 of 0 -> Z div 2; 1 -> -(Z + 1) div 2 end,\n    check_integer(V, Lo, Hi), {V, Rest};\nget([<<\"bool\">>], <<N, Rest/binary>>, _) when N < 2 -> {N =:= 1, Rest};\nget([<<\"unit\">>], B, _) -> {ls_unit, B};\nget([Kind], B, _) when Kind =:= <<\"text\">>; Kind =:= <<\"bytes\">>; Kind =:= <<\"end\">> ->\n    {N, Rest} = read_varint(B),\n    require(byte_size(Rest) >= N, truncated_wire_value),\n    <<V:N/binary, After/binary>> = Rest,\n    check_binary(Kind, V), {V, After};\nget([<<\"list\">>, D], B, Table) ->\n    {N, Rest} = read_varint(B), get_fields(lists:duplicate(N, D), Rest, Table);\nget([<<\"maybe\">>, _], <<0, Rest/binary>>, _) -> {{ls_data, <<\"Maybe::Nothing\">>, []}, Rest};\nget([<<\"maybe\">>, D], <<1, Rest/binary>>, Table) ->\n    {V, After} = get(resolve(D, Table), Rest, Table), {{ls_data, <<\"Maybe::Just\">>, [V]}, After};\nget([<<\"either\">>, A, B], <<N, Rest/binary>>, Table) when N < 2 ->\n    {Tag, D} = case N of 0 -> {<<\"Either::Left\">>, A}; 1 -> {<<\"Either::Right\">>, B} end,\n    {V, After} = get(resolve(D, Table), Rest, Table), {{ls_data, Tag, [V]}, After};\nget([<<\"data\">>, _ | Cs], B, Table) ->\n    {I, Rest} = read_varint(B),\n    require(I < length(Cs), invalid_wire_constructor),\n    [<<\"ctor\">>, Tag | Ds] = lists:nth(I + 1, Cs),\n    {Fields, After} = get_fields(Ds, Rest, Table), {{ls_data, unquote(Tag), Fields}, After};\nget(D, _, _) -> fail({invalid_wire_value, D}).\nget_fields(Ds, B, Table) -> lists:mapfoldl(fun(D, Rest) -> get(resolve(D, Table), Rest, Table) end, B, Ds).\n\nrequire(true, _) -> ok;\nrequire(false, Reason) -> fail(Reason).\nfail(Reason) -> erlang:error({lawspec, Reason}).\n"
runtimeSource "beam-model" = "%% @doc Portable stateful model runs over checked logical callbacks. A fresh\n%% context owns each generation, replay and shrink attempt. Actor models use\n%% the same persistent gen_servers and OTP supervisors as production APIs.\n%% ref:DEC-stateful-models-linearizability ref:DEC-portable-seeded-generation\n-module(lawspec_beam_model).\n-export([new/5, check/1, check/2, generate/5, simulate/2, execute/2,\n    shrink/4, candidates/2, describe/2, command/2, admits/2, shifted/2,\n    with_context/3, with_system/4, initial/2, step/4, invoke/5, check_state/4,\n    callback/3, seed/1]).\n\n%% Callbacks receive the case context and a list of logical arguments. The\n%% generated context factory installs production abilities in a fresh owned\n%% scope; no mutable handlers or workflow state are shared between attempts.\nnew(Spec, {StartRun, StartModel}, Callbacks, Abstract, Invariants) ->\n    Forms = lawspec_beam_values:read_descriptor(Spec),\n    [<<\"machine\">>, Name, Sharing] = hd(Forms),\n    Start = fields(tl(form(<<\"start\">>, Forms))),\n    CommandForms = [F || [<<\"command\">> | _] = F <- Forms],\n    Kinds = tl(form(<<\"invariants\">>, Forms)),\n    require(length(CommandForms) =:= length(Callbacks), model_command_callbacks),\n    require(length(Kinds) =:= length(Invariants), model_invariant_callbacks),\n    All = [read_command(F, C) || {F, C} <- lists:zip(CommandForms, Callbacks)],\n    Restarts = [C || C = #{restart := true} <- All],\n    require(length(Restarts) =< 1, model_restart_callbacks),\n    Commands = [C || C = #{restart := false} <- All],\n    Actor = flag(<<\"actor\">>, Forms),\n    Consistency = hd(tl(form(<<\"consistency\">>, Forms))),\n    require(lists:member(Sharing, [<<\"linear\">>, <<\"shared\">>]), model_invalid_sharing),\n    require(lists:member(Consistency, [<<\"linearizable\">>, <<\"sequential\">>, <<\"causal\">>, <<\"eventual\">>]),\n        model_invalid_consistency),\n    require(Consistency =/= <<\"eventual\">> orelse Abstract =/= none, model_eventual_requires_abstraction),\n    require(not Actor orelse Sharing =:= <<\"shared\">>, model_actor_must_be_shared),\n    require(Actor orelse Restarts =:= [], model_restart_requires_actor),\n    Crash = #{name => <<\"crash\">>, arguments => [], state => 0, unit => true,\n        needs => [], shifts => [], key => none, restart => false, kind => crash},\n    #{name => Name, shared => Sharing =:= <<\"shared\">>, actor => Actor,\n        table => maps:from_list([{N, D} || [<<\"data\">>, N | _] = D <- Forms]),\n        start_arguments => maps:get(<<\"arguments\">>, Start),\n        start_indices => maps:get(<<\"indices\">>, Start),\n        start_run => StartRun, start_model => StartModel,\n        commands => list_to_tuple(Commands),\n        steps => list_to_tuple(Commands ++ [Crash || Actor]),\n        restart => case Restarts of [R] -> R; [] -> none end,\n        abstract => Abstract, invariants => lists:zip(Kinds, Invariants),\n        per_key => flag(<<\"perkey\">>, Forms),\n        consistency => Consistency,\n        context => fun(Body) -> Body(make_ref()) end}.\n\nread_command([<<\"command\">>, Name | Forms], {Run, Reference, When}) ->\n    F = fields(Forms),\n    #{name => Name, arguments => maps:get(<<\"arguments\">>, F),\n        state => one(<<\"state\">>, F), unit => one(<<\"unit\">>, F) =:= <<\"true\">>,\n        needs => maps:get(<<\"needs\">>, F), shifts => maps:get(<<\"shifts\">>, F),\n        key => case one(<<\"key\">>, F) of <<\"none\">> -> none; I -> I end,\n        restart => one(<<\"restart\">>, F) =:= <<\"true\">>, kind => command,\n        run => Run, reference => Reference, 'when' => When}.\nfields(Forms) -> maps:from_list([{K, Vs} || [K | Vs] <- Forms]).\nform(Key, Forms) -> hd([F || [K | _] = F <- Forms, K =:= Key]).\none(Key, Fields) -> [V] = maps:get(Key, Fields), V.\nflag(Key, Forms) -> lists:member([Key, <<\"true\">>], Forms).\nrequire(true, _) -> ok;\nrequire(false, Reason) -> error({lawspec, Reason}).\n\ncommand(#{steps := Steps}, I) when is_integer(I), I >= 0, I < tuple_size(Steps) -> element(I + 1, Steps).\nadmits(#{needs := Needs}, Indices) ->\n    lists:all(fun({[<<\"atleast\">>, N], I}) -> I >= N;\n        ({[<<\"exactly\">>, N], I}) -> I =:= N end, lists:zip(Needs, Indices)).\nshifted(#{shifts := Shifts}, Indices) ->\n    [case Shift of [<<\"by\">>, N] -> I + N; [<<\"to\">>, N] -> N end\n        || {Shift, I} <- lists:zip(Shifts, Indices)].\n\nwith_context(#{context := Factory} = Model, StartArgs, Body) ->\n    Factory(fun(Value) -> Body(#{value => Value, start => StartArgs, model => Model}) end).\ncallback(Fun, #{value := Value}, Arguments) -> Fun(Value, Arguments).\ninitial(#{start_model := Start}, #{start := Args} = Context) -> callback(Start, Context, Args).\n\n%% Invalid references remove a generation/shrink candidate; they never make\n%% the implementation's exception into a passing test.\nstep(#{kind := crash}, Context = #{model := Model}, [], State) ->\n    try\n        Next = case maps:get(restart, Model) of\n            none -> initial(Model, Context);\n            #{reference := Ref} -> callback(Ref, Context, [State])\n        end,\n        {ok, Next, ls_unit}\n    catch _:_ -> invalid end;\nstep(#{reference := Ref, 'when' := When, unit := Unit}, Context, Args, State) ->\n    try\n        case When =:= none orelse callback(When, Context, [State]) =:= true of\n            false -> invalid;\n            true ->\n                Out = callback(Ref, Context, Args ++ [State]),\n                case Unit of\n                    true -> {ok, Out, ls_unit};\n                    false -> {ls_data, _, [Reply, Next]} = Out, {ok, Next, Reply}\n                end\n        end\n    catch _:_ -> invalid end.\n\nsimulate(Model, {StartArgs, Steps}) ->\n    with_context(Model, StartArgs, fun(Context) ->\n        try simulate_steps(Model, Context, Steps, maps:get(start_indices, Model),\n            initial(Model, Context), [])\n        catch _:_ -> invalid end\n    end).\nsimulate_steps(_, _, [], _, State, States) -> {ok, lists:reverse([State | States])};\nsimulate_steps(Model, Context, [{I, Args} | Steps], Indices, State, States) ->\n    Command = command(Model, I),\n    case admits(Command, Indices) of\n        false -> invalid;\n        true -> case step(Command, Context, Args, State) of\n            invalid -> invalid;\n            {ok, Next, _} -> simulate_steps(Model, Context, Steps, shifted(Command, Indices), Next, [State | States])\n        end\n    end.\n\n%% Random state is explicit. The draw order, boundary values and rejected\n%% reference steps match the other runtimes, including one crash in eight.\ngenerate(Model, Random, Length, Size, Crashes) ->\n    {StartArgs, R1} = arguments(Model, maps:get(start_arguments, Model), Random, Size),\n    with_context(Model, StartArgs, fun(Context) ->\n        case attempt(fun() -> initial(Model, Context) end) of\n            {error, _} -> {{StartArgs, []}, R1};\n            {ok, State} ->\n                {Steps, Last} = generate_steps(Model, Context, R1, Length, Size, Crashes,\n                    maps:get(start_indices, Model), State, []),\n                {{StartArgs, Steps}, Last}\n        end\n    end).\narguments(#{table := Table}, Ds, Random, Size) ->\n    lists:mapfoldl(fun(D, R) -> lawspec_beam_values:generate(D, Table, R, Size) end, Random, Ds).\ngenerate_steps(_, _, Random, 0, _, _, _, _, Steps) -> {lists:reverse(Steps), Random};\ngenerate_steps(Model, Context, Random, Remaining, Size, Crashes, Indices, State, Steps) ->\n    Allowed = [I - 1 || {I, C} <- lists:enumerate(tuple_to_list(maps:get(commands, Model))), admits(C, Indices)],\n    case Allowed of\n        [] -> {lists:reverse(Steps), Random};\n        _ ->\n            {Choice, R1} = lawspec_beam_random:below(length(Allowed), Random),\n            {Index, R2} = case Crashes andalso maps:get(actor, Model) of\n                true ->\n                    {Crash, R} = lawspec_beam_random:below(8, R1),\n                    {case Crash of 0 -> tuple_size(maps:get(commands, Model)); _ -> lists:nth(Choice + 1, Allowed) end, R};\n                false -> {lists:nth(Choice + 1, Allowed), R1}\n            end,\n            Command = command(Model, Index),\n            {Args, R3} = arguments(Model, maps:get(arguments, Command), R2, Size),\n            case step(Command, Context, Args, State) of\n                invalid -> generate_steps(Model, Context, R3, Remaining - 1, Size, Crashes, Indices, State, Steps);\n                {ok, Next, _} -> generate_steps(Model, Context, R3, Remaining - 1, Size, Crashes,\n                    shifted(Command, Indices), Next, [{Index, Args} | Steps])\n            end\n    end.\n\n%% An actor run has a single permanent child. Its restart budget is the\n%% number of steps in this case, so injected crashes cannot exhaust it.\n%% A broken restart still terminates rather than looping without a bound.\nwith_system(Model, StartArgs, Restarts, Body) ->\n    with_context(Model, StartArgs, fun(Context) ->\n        Start = fun() -> callback(maps:get(start_run, Model), Context, StartArgs) end,\n        case maps:get(actor, Model) of\n            false -> Body(Context, Start(), initial(Model, Context));\n            true ->\n                Restart = fun(State) -> case maps:get(restart, Model) of\n                    none -> Start();\n                    #{run := Run} -> callback(Run, Context, [State])\n                end end,\n                Spec = lawspec_beam_actors:supervisor(one_for_one, Restarts, 1000000,\n                    [{model, permanent, lawspec_beam_actors:actor(Start, Restart)}]),\n                lawspec_beam_actors:with_spec(Spec, fun(Supervisor) ->\n                    Body(Context, lawspec_beam_actors:child(Supervisor, model), initial(Model, Context))\n                end)\n        end\n    end).\n\ninvoke(_, _, #{kind := crash}, [], Actor) ->\n    ok = lawspec_beam_actors:crash(Actor), {ls_unit, Actor};\ninvoke(#{actor := true}, Context, Command = #{run := Run, unit := Unit}, Args, Actor) ->\n    Reply = lawspec_beam_actors:call(Actor, fun(State) ->\n        Out = callback(Run, Context, insert_state(Command, Args, State)),\n        case Unit of true -> {ls_unit, Out}; false -> pair(Out) end\n    end),\n    {Reply, Actor};\ninvoke(#{shared := Shared}, Context, Command = #{run := Run, unit := Unit}, Args, State) ->\n    Out = callback(Run, Context, insert_state(Command, Args, State)),\n    case {Shared, Unit} of\n        {true, _} -> {Out, State};\n        {false, true} -> {ls_data, _, [Next]} = Out, {ls_unit, Next};\n        {false, false} -> pair(Out)\n    end.\ninsert_state(#{state := Position}, Args, State) ->\n    {Before, After} = lists:split(Position, Args), Before ++ [State | After].\npair({ls_data, _, [Reply, Next]}) -> {Reply, Next}.\n\ncheck_state(Model, Context, System, Expected) ->\n    State = case maps:get(actor, Model) of true -> lawspec_beam_actors:state(System); false -> System end,\n    case maps:get(abstract, Model) of\n        none -> ok;\n        Abstract ->\n            Actual = callback(Abstract, Context, [State]),\n            case lawspec_beam_scalar:equal(Actual, Expected) of\n                true -> ok;\n                false -> throw({model_failure, {state, Actual, Expected}})\n            end\n    end,\n    lists:foreach(fun({Kind, Invariant}) ->\n        Value = case Kind of <<\"model\">> -> Expected; <<\"state\">> -> State end,\n        case callback(Invariant, Context, [Value]) of\n            true -> ok;\n            false -> throw({model_failure, {invariant, Kind}});\n            Other -> throw({model_failure, {non_boolean_invariant, Kind, Other}})\n        end\n    end, maps:get(invariants, Model)).\n\nexecute(Model, {StartArgs, Steps}) ->\n    try with_system(Model, StartArgs, length(Steps), fun(Context, System, Expected) ->\n        execute_steps(Model, Context, Steps, maps:get(start_indices, Model), System, Expected, 0)\n    end)\n    catch Class:Reason:Stack -> failure(0, Class, Reason, Stack) end.\nexecute_steps(Model, Context, Steps, Indices, System, Expected, N) ->\n    try\n        check_state(Model, Context, System, Expected),\n        case Steps of\n            [] -> ok;\n            [{I, Args} | Rest] ->\n                Command = command(Model, I),\n                case admits(Command, Indices) of\n                    false -> throw({model_step_failure, N + 1, invalid_step});\n                    true -> case step(Command, Context, Args, Expected) of\n                        invalid -> throw({model_step_failure, N + 1, invalid_step});\n                        {ok, Next, Wanted} ->\n                            case attempt(fun() -> invoke(Model, Context, Command, Args, System) end) of\n                                {error, Error} -> {error, Error#{step => N + 1}};\n                                {ok, {Result, After}} ->\n                                    case maps:get(unit, Command) orelse lawspec_beam_scalar:equal(Result, Wanted) of\n                                        false -> {error, #{step => N + 1, reason => {returned, Result, Wanted}}};\n                                        true -> execute_steps(Model, Context, Rest, shifted(Command, Indices), After, Next, N + 1)\n                                    end\n                            end\n                    end\n                end\n        end\n    catch Class:Reason:Stack -> failure(N, Class, Reason, Stack) end.\nattempt(Body) -> try {ok, Body()} catch Class:Reason:Stack -> failure(0, Class, Reason, Stack) end.\nfailure(_, throw, {model_step_failure, Step, Reason}, _) -> {error, #{step => Step, reason => Reason}};\nfailure(Step, throw, {model_failure, Reason}, _) -> {error, #{step => Step, reason => Reason}};\nfailure(Step, Class, Reason, Stack) -> {error, #{step => Step, reason => {raised, Class, Reason}, stack => Stack}}.\n\n%% Shrink in portable order: remove command chunks, then shrink each command\n%% argument, then each start argument. Replay the reference before executing\n%% any candidate, preserving typestate and model preconditions.\ncandidates(Model, {StartArgs, Steps}) ->\n    Drops = [{StartArgs, remove(Steps, Begin, Size)} || Size <- halves(length(Steps) div 2),\n        Begin <- lists:seq(0, length(Steps) - 1, Size)],\n    Arguments = [{StartArgs, replace(Steps, K, {I, Smaller})}\n        || {K, {I, Args}} <- numbered(Steps),\n        Smaller <- smaller_args(Model, maps:get(arguments, command(Model, I)), Args)],\n    Starts = [{Smaller, Steps} || Smaller <- smaller_args(Model, maps:get(start_arguments, Model), StartArgs)],\n    Drops ++ Arguments ++ Starts.\nhalves(0) -> [];\nhalves(N) -> [N | halves(N div 2)].\nnumbered(Values) -> lists:zip(lists:seq(0, length(Values) - 1), Values).\nremove(Values, Begin, Size) ->\n    {Before, Rest} = lists:split(Begin, Values), Before ++ lists:nthtail(min(Size, length(Rest)), Rest).\nreplace(Values, I, Value) ->\n    {Before, [_ | Rest]} = lists:split(I, Values), Before ++ [Value | Rest].\nsmaller_args(#{table := Table}, Ds, Args) ->\n    [replace(Args, I, V) || {I, {D, Arg}} <- numbered(lists:zip(Ds, Args)),\n        V <- lawspec_beam_values:shrink(D, Arg, Table)].\n\nshrink(Model, Run, Failure, Budget) when is_integer(Budget), Budget >= 0 ->\n    shrink_candidates(Model, candidates(Model, Run), Run, Failure, Budget).\nshrink_candidates(_, _, Run, Failure, 0) -> {Run, Failure};\nshrink_candidates(_, [], Run, Failure, _) -> {Run, Failure};\nshrink_candidates(Model, [Candidate | Rest], Run, Failure, Budget) ->\n    Result = case simulate(Model, Candidate) of invalid -> ok; {ok, _} -> execute(Model, Candidate) end,\n    case Result of\n        ok -> shrink_candidates(Model, Rest, Run, Failure, Budget - 1);\n        {error, Found} -> shrink(Model, Candidate, Found, Budget - 1)\n    end.\n\ndescribe(Model, {StartArgs, Steps}) ->\n    iolist_to_binary(lists:join(<<\"; \">>, [describe_step(<<\"start\">>, StartArgs) |\n        [describe_step(maps:get(name, command(Model, I)), Args) || {I, Args} <- Steps]])).\ndescribe_step(Name, Args) -> [Name, $(, lists:join(<<\", \">>, [lawspec_beam_values:render(A) || A <- Args]), $)].\n\nseed(Options) -> lawspec_beam_random:seed(case maps:find(seed, Options) of\n    {ok, N} -> N;\n    error -> case os:getenv(\"LAWSPEC_SEED\") of false -> 0; Text -> list_to_integer(Text) end\nend).\ncheck(Model) -> check(Model, #{}).\ncheck(Model, Options) ->\n    Cases = maps:get(cases, Options, 100), MaxLength = maps:get(max_length, Options, 20),\n    Shrinks = maps:get(max_shrinks, Options, 2000), Seed = seed(Options),\n    require(is_integer(Cases) andalso Cases > 0, model_requires_cases),\n    require(is_integer(MaxLength) andalso MaxLength >= 0, model_invalid_length),\n    require(is_integer(Shrinks) andalso Shrinks >= 0, model_invalid_shrinks),\n    check_cases(Model, 0, Cases, MaxLength, Shrinks, Seed, Seed).\ncheck_cases(_, N, N, _, _, _, _) -> ok;\ncheck_cases(Model, N, Cases, MaxLength, Shrinks, Seed, Random) ->\n    {Length, R1} = lawspec_beam_random:below(MaxLength + 1, Random),\n    {Run, R2} = generate(Model, R1, Length, 1 + N rem 8, true),\n    case execute(Model, Run) of\n        ok -> check_cases(Model, N + 1, Cases, MaxLength, Shrinks, Seed, R2);\n        {error, Failure} ->\n            {Smaller, Found} = shrink(Model, Run, Failure, Shrinks),\n            error({lawspec, {model_failed, maps:get(name, Model), #{seed => Seed, 'case' => N,\n                run => Smaller, description => describe(Model, Smaller), failure => Found}}})\n    end.\n"
runtimeSource "beam-model_parallel" = "%% @doc Concurrent model histories, generated from a valid sequential prefix.\n%% Every branch interleaving must be allowed by the reference. Actual calls\n%% run in owned BEAM workers; a shared atomic counter records their intervals.\n%% ref:DEC-stateful-models-linearizability ref:herlihy-wing-linearizability\n%% ref:wing-gong-linearizability ref:DEC-portable-seeded-generation\n-module(lawspec_beam_model_parallel).\n-export([check/1, check/2, generate/5, allowed/2, execute/3, consistent/7,\n    shrink/6, candidates/2, describe/2]).\n\ngenerate(Model, Random, Size, Threads, BranchLength) ->\n    {Length, R1} = lawspec_beam_random:below(4, Random),\n    {Prefix = {Args, _}, R2} = lawspec_beam_model:generate(Model, R1, Length, Size, false),\n    case lawspec_beam_model:simulate(Model, Prefix) of\n        invalid -> {{Prefix, lists:duplicate(Threads, [])}, R2};\n        {ok, States} ->\n            {Branches, R3} = lawspec_beam_model:with_context(Model, Args, fun(Context) ->\n                lists:mapfoldl(fun(_, R) ->\n                    {N, Next} = lawspec_beam_random:below(BranchLength, R),\n                    generate_branch(Model, Context, Next, Size, N + 1, lists:last(States), [])\n                end, R2, lists:seq(1, Threads))\n            end),\n            {trim(Model, {Prefix, Branches}), R3}\n    end.\ngenerate_branch(_, _, Random, _, 0, _, Steps) -> {lists:reverse(Steps), Random};\ngenerate_branch(#{commands := Commands}, _, Random, _, _, _, Steps) when tuple_size(Commands) =:= 0 ->\n    {lists:reverse(Steps), Random};\ngenerate_branch(Model, Context, Random, Size, Remaining, State, Steps) ->\n    {Index, R1} = lawspec_beam_random:below(tuple_size(maps:get(commands, Model)), Random),\n    Command = lawspec_beam_model:command(Model, Index),\n    {Args, R2} = lists:mapfoldl(fun(D, R) -> lawspec_beam_values:generate(D, maps:get(table, Model), R, Size) end,\n        R1, maps:get(arguments, Command)),\n    case lawspec_beam_model:step(Command, Context, Args, State) of\n        invalid -> generate_branch(Model, Context, R2, Size, Remaining - 1, State, Steps);\n        {ok, Next, _} -> generate_branch(Model, Context, R2, Size, Remaining - 1, Next, [{Index, Args} | Steps])\n    end.\ntrim(Model, Case = {Prefix, Branches}) ->\n    case allowed(Model, Case) of\n        true -> Case;\n        false ->\n            Length = lists:max([length(B) || B <- Branches]),\n            %% First longest branch, as on every other target.\n            [I | _] = [K || {K, B} <- numbered(Branches), length(B) =:= Length],\n            trim(Model, {Prefix, replace(Branches, I, lists:sublist(lists:nth(I + 1, Branches), Length - 1))})\n    end.\n\nallowed(Model, {Prefix = {Args, _}, Branches}) ->\n    case lawspec_beam_model:simulate(Model, Prefix) of\n        invalid -> false;\n        {ok, States} -> lawspec_beam_model:with_context(Model, Args, fun(Context) ->\n            {Answer, _} = all_orders(Model, Context, tuple_branches(Branches), positions(Branches), lists:last(States), #{}),\n            Answer\n        end)\n    end.\nall_orders(Model, Context, Branches, Positions, State, Seen) ->\n    Key = {Positions, State},\n    case maps:is_key(Key, Seen) of\n        true -> {true, Seen};\n        false -> all_next(Model, Context, Branches, Positions, State, pending(Branches, Positions), Seen#{Key => true})\n    end.\nall_next(_, _, _, _, _, [], Seen) -> {true, Seen};\nall_next(Model, Context, Branches, Positions, State, [{I, {Index, Args}} | Rest], Seen) ->\n    case lawspec_beam_model:step(lawspec_beam_model:command(Model, Index), Context, Args, State) of\n        invalid -> {false, Seen};\n        {ok, Next, _} -> case all_orders(Model, Context, Branches, advance(Positions, I), Next, Seen) of\n            {false, S} -> {false, S};\n            {true, S} -> all_next(Model, Context, Branches, Positions, State, Rest, S)\n        end\n    end.\n\nexecute(Model, {{StartArgs, Steps}, Branches}, Shake) ->\n    try lawspec_beam_model:with_system(Model, StartArgs, length(Steps), fun(Context, System, Expected) ->\n        FinalPrefix = prefix(Model, Context, Steps, System, Expected),\n        Clock = atomics:new(1, []),\n        History = lawspec_beam_runtime:concurrently([\n            fun() -> run_branch(Model, Context, System, Clock, Branch,\n                lawspec_beam_random:seed(Shake bxor ((I + 1) * 16#9e3779b97f4a7c15))) end\n            || {I, Branch} <- numbered(Branches)]),\n        case [Error || Events <- History, {_, _, {error, _} = Error} <- Events] of\n            [{error, Error} | _] -> {error, Error};\n            [] ->\n                Values = [[{A, B, V} || {A, B, {ok, V}} <- Events] || Events <- History],\n                Final = case maps:get(abstract, Model) of\n                    none -> none;\n                    Abstract -> {some, lawspec_beam_model:callback(Abstract, Context, [system_state(Model, System)])}\n                end,\n                case consistent(Model, Context, Branches, Values, FinalPrefix, Final, System) of\n                    true -> ok;\n                    false -> {error, #{reason => no_consistent_order, history => Values}}\n                end\n        end\n    end)\n    catch Class:Reason:Stack -> {error, #{reason => {raised, Class, Reason}, stack => Stack}} end.\nprefix(Model, Context, [], System, Expected) ->\n    lawspec_beam_model:check_state(Model, Context, System, Expected), Expected;\nprefix(Model, Context, [{I, Args} | Steps], System, Expected) ->\n    lawspec_beam_model:check_state(Model, Context, System, Expected),\n    Command = lawspec_beam_model:command(Model, I),\n    {ok, Next, Wanted} = lawspec_beam_model:step(Command, Context, Args, Expected),\n    {Result, System} = lawspec_beam_model:invoke(Model, Context, Command, Args, System),\n    case maps:get(unit, Command) orelse lawspec_beam_scalar:equal(Result, Wanted) of\n        false -> error({lawspec, {model_prefix_returned, Result, Wanted}});\n        true -> prefix(Model, Context, Steps, System, Next)\n    end.\nsystem_state(#{actor := true}, System) -> lawspec_beam_actors:state(System);\nsystem_state(_, System) -> System.\nrun_branch(Model, Context, System, Clock, Branch, Random) ->\n    {History, _} = lists:mapfoldl(fun({I, Args}, R) ->\n        Command = lawspec_beam_model:command(Model, I),\n        R1 = perturb(R), Called = atomics:add_get(Clock, 1, 1),\n        Result = try\n            {Value, System} = lawspec_beam_model:invoke(Model, Context, Command, Args, System), {ok, Value}\n        catch Class:Reason:Stack -> {error, #{command => maps:get(name, Command),\n            reason => {raised, Class, Reason}, stack => Stack}} end,\n        Returned = atomics:add_get(Clock, 1, 1), R2 = perturb(R1),\n        {{Called, Returned, Result}, R2}\n    end, Random, Branch), History.\nperturb(Random) ->\n    {Choice, Next} = lawspec_beam_random:below(4, Random),\n    case Choice of\n        0 -> ok;\n        1 -> erlang:yield();\n        %% Native BEAM timers round the portable sub-millisecond sleeps up.\n        _ -> receive after 1 -> ok end\n    end,\n    Next.\n\n%% Search all orders consistent with process order and (for linearizability)\n%% real time. Memoization is on complete logical terms and branch positions,\n%% not rendered strings, so distinct states cannot alias through printing.\nconsistent(Model, Context, Branches, History, Expected, Final, System) ->\n    Finish = fun(State) ->\n        try\n            Equal = case Final of none -> true; {some, Actual} -> lawspec_beam_scalar:equal(Actual, State) end,\n            case Equal of false -> false; true ->\n                lawspec_beam_model:check_state(Model#{abstract := none}, Context, System, State), true end\n        catch _:_ -> false end\n    end,\n    case maps:get(consistency, Model) of\n        <<\"causal\">> -> causal(Model, Context, Branches, History, Expected, System);\n        _ ->\n            %% Linearizability composes over independent keys. Sequential and\n            %% eventual orders still need each caller's cross-key ordering;\n            %% partitioning those histories can hide an impossible cycle.\n            CanPartition = maps:get(consistency, Model) =:= <<\"linearizable\">> andalso\n                maps:get(per_key, Model) andalso lists:all(fun({I, _}) ->\n                maps:get(key, lawspec_beam_model:command(Model, I)) =/= none end, lists:append(Branches)),\n            case CanPartition of\n                false -> find_order(Model, Context, Branches, History, Expected, Finish) =/= false;\n                true -> by_key(Model, Context, Branches, History, Expected, Finish)\n            end\n    end.\nfind_order(Model, Context, Branches, History, Expected, Finish) ->\n    {Result, _} = visit(Model, Context, tuple_branches(Branches), tuple_branches(History),\n        positions(Branches), Expected, Finish, #{}), Result.\nvisit(Model, Context, Branches, History, Positions, State, Finish, Seen) ->\n    Key = {Positions, State},\n    case maps:is_key(Key, Seen) of\n        true -> {false, Seen};\n        false ->\n            Updated = Seen#{Key => true},\n            case pending(Branches, Positions) of\n                [] -> {case Finish(State) of true -> {ok, State}; false -> false end, Updated};\n                Next -> visit_next(Model, Context, Branches, History, Positions, State, Finish, Next, Updated)\n            end\n    end.\nvisit_next(_, _, _, _, _, _, _, [], Seen) -> {false, Seen};\nvisit_next(Model, Context, Branches, History, Positions, State, Finish, [{I, {Index, Args}} | Rest], Seen) ->\n    {Called, _, Result} = event(History, Positions, I),\n    Linear = maps:get(consistency, Model) =:= <<\"linearizable\">>,\n    Blocked = Linear andalso lists:any(fun({J, _}) ->\n        {_, Returned, _} = event(History, Positions, J), J =/= I andalso Returned < Called\n    end, pending(Branches, Positions)),\n    Command = lawspec_beam_model:command(Model, Index),\n    Attempt = case Blocked of true -> invalid; false -> lawspec_beam_model:step(Command, Context, Args, State) end,\n    NextSearch = case Attempt of\n        {ok, Next, Wanted} ->\n            Ignore = maps:get(consistency, Model) =:= <<\"eventual\">> orelse maps:get(unit, Command),\n            case Ignore orelse lawspec_beam_scalar:equal(Result, Wanted) of\n                true -> visit(Model, Context, Branches, History, advance(Positions, I), Next, Finish, Seen);\n                false -> {false, Seen}\n            end;\n        invalid -> {false, Seen}\n    end,\n    case NextSearch of\n        {{ok, _}, _} = Found -> Found;\n        {false, S} -> visit_next(Model, Context, Branches, History, Positions, State, Finish, Rest, S)\n    end.\nevent(History, Positions, I) -> element(element(I, Positions) + 1, element(I, History)).\n\n%% With no messages between these branches, a causal view contains that\n%% caller's own operations. Scenarios supply their message dependencies to\n%% their separate history checker. Check model invariants in each view and\n%% state invariants against the completed implementation, without demanding\n%% one global final abstract state for a causal execution.\ncausal(Model, Context, Branches, History, Expected, System) ->\n    lists:all(fun({Branch, Events}) ->\n        try\n            Last = lists:foldl(fun({{I, Args}, {_, _, Result}}, State) ->\n                C = lawspec_beam_model:command(Model, I),\n                {ok, Next, Wanted} = lawspec_beam_model:step(C, Context, Args, State),\n                true = maps:get(unit, C) orelse lawspec_beam_scalar:equal(Result, Wanted), Next\n            end, Expected, lists:zip(Branch, Events)),\n            lawspec_beam_model:check_state(Model#{abstract := none}, Context, System, Last), true\n        catch _:_ -> false end\n    end, lists:zip(Branches, History)).\n\nby_key(Model, Context, Branches, History, Expected, Finish) ->\n    Groups = lists:foldl(fun({I, {Branch, Events}}, Acc) ->\n        lists:foldl(fun({Step = {Index, Args}, Event}, Groups0) ->\n            KeyIndex = maps:get(key, lawspec_beam_model:command(Model, Index)),\n            Key = lawspec_beam_values:render(lists:nth(KeyIndex + 1, Args)),\n            Empty = lists:duplicate(length(Branches), []),\n            Parts = maps:get(Key, Groups0, Empty),\n            Groups0#{Key => replace(Parts, I, lists:nth(I + 1, Parts) ++ [{Step, Event}])}\n        end, Acc, lists:zip(Branch, Events))\n    end, #{}, numbered(lists:zip(Branches, History))),\n    fold_keys(Model, Context, [maps:get(K, Groups) || K <- lists:sort(maps:keys(Groups))], Expected, Finish).\nfold_keys(_, _, [], State, Finish) -> Finish(State);\nfold_keys(Model, Context, [Parts | Rest], State, Finish) ->\n    Branches = [[S || {S, _} <- Part] || Part <- Parts], History = [[E || {_, E} <- Part] || Part <- Parts],\n    %% A key can have several legal final states when an operation returns\n    %% Unit. Continue the remaining keys inside the search's final predicate,\n    %% so the first legal order cannot hide another that matches abstraction.\n    find_order(Model, Context, Branches, History, State,\n        fun(Next) -> fold_keys(Model, Context, Rest, Next, Finish) end) =/= false.\n\ncandidates(Model, {Prefix = {Args, Steps}, Branches}) ->\n    Prefixes = [{{Args, remove(Steps, I)}, Branches} || {I, _} <- numbered(Steps)],\n    Drops = [{Prefix, replace(Branches, I, remove(Branch, K))}\n        || {I, Branch} <- numbered(Branches), {K, _} <- numbered(Branch)],\n    Smaller = [{Prefix, replace(Branches, I, replace(Branch, K, {Index, replace(Values, A, Value)}))}\n        || {I, Branch} <- numbered(Branches), {K, {Index, Values}} <- numbered(Branch),\n        {A, {D, V}} <- numbered(lists:zip(maps:get(arguments, lawspec_beam_model:command(Model, Index)), Values)),\n        Value <- lawspec_beam_values:shrink(D, V, maps:get(table, Model))],\n    Prefixes ++ Drops ++ Smaller.\nshrink(Model, Case, Failure, Repeats, Budget, Shake) ->\n    shrink_next(Model, candidates(Model, Case), Case, Failure, Repeats, Budget, Shake).\nshrink_next(_, _, Case, Failure, _, 0, _) -> {Case, Failure};\nshrink_next(_, [], Case, Failure, _, _, _) -> {Case, Failure};\nshrink_next(Model, [Candidate | Rest], Case, Failure, Repeats, Budget, Shake) ->\n    Found = case allowed(Model, Candidate) of false -> ok; true -> repeats(Model, Candidate, Repeats, Shake) end,\n    case Found of\n        ok -> shrink_next(Model, Rest, Case, Failure, Repeats, Budget - 1, Shake);\n        {error, Reason} -> shrink(Model, Candidate, Reason, Repeats, Budget - 1, Shake)\n    end.\nrepeats(_, _, 0, _) -> ok;\nrepeats(Model, Case, Repeats, Shake) ->\n    case execute(Model, Case, Shake) of ok -> repeats(Model, Case, Repeats - 1, Shake + 1); Error -> Error end.\n\ndescribe(Model, {Prefix, Branches}) ->\n    Parts = [[unicode:characters_to_binary([$A + I]), <<\": \">>, case B of\n        [] -> <<\"nothing\">>;\n        _ -> <<\"start(); \", Commands/binary>> = lawspec_beam_model:describe(Model, {[], B}), Commands\n    end] || {I, B} <- numbered(Branches)],\n    Joined = case Parts of\n        [] -> <<\"nothing\">>;\n        [Only] -> Only;\n        _ -> [lists:join(<<\", \">>, lists:droplast(Parts)), <<\" and \">>, lists:last(Parts)]\n    end,\n    iolist_to_binary([lawspec_beam_model:describe(Model, Prefix), <<\", then \">>, Joined, <<\" at the same time\">>]).\n\ncheck(Model) -> check(Model, #{}).\ncheck(Model, Options) ->\n    Cases = maps:get(cases, Options, 50), Repeats = maps:get(repeats, Options, 10),\n    Shrinks = maps:get(max_shrinks, Options, 300), Threads = maps:get(threads, Options, 3),\n    Length = maps:get(branch_length, Options, 5), Seed = lawspec_beam_model:seed(Options),\n    true = maps:get(shared, Model),\n    true = lists:all(fun(N) -> is_integer(N) andalso N > 0 end, [Cases, Repeats, Threads, Length]),\n    true = is_integer(Shrinks) andalso Shrinks >= 0,\n    check_cases(Model, 0, Cases, Repeats, Shrinks, Threads, Length, Seed, Seed bxor 16#5bd1e995).\ncheck_cases(_, N, N, _, _, _, _, _, _) -> ok;\ncheck_cases(Model, N, Cases, Repeats, Shrinks, Threads, Length, Seed, Random) ->\n    {Case, R1} = generate(Model, Random, 1 + N rem 8, Threads, Length),\n    {Shake, R2} = lawspec_beam_random:next(R1),\n    case repeats(Model, Case, Repeats, Shake) of\n        ok -> check_cases(Model, N + 1, Cases, Repeats, Shrinks, Threads, Length, Seed, R2);\n        {error, Failure} ->\n            {Smaller, Found} = shrink(Model, Case, Failure, max(2, Repeats div 2), Shrinks, Shake),\n            error({lawspec, {model_inconsistent, maps:get(name, Model), maps:get(consistency, Model),\n                #{seed => Seed, 'case' => N, shake => Shake, run => Smaller,\n                    description => describe(Model, Smaller), failure => Found}}})\n    end.\n\nnumbered(Vs) -> lists:zip(lists:seq(0, length(Vs) - 1), Vs).\nremove(Vs, I) -> {Before, [_ | Rest]} = lists:split(I, Vs), Before ++ Rest.\nreplace(Vs, I, V) -> {Before, [_ | Rest]} = lists:split(I, Vs), Before ++ [V | Rest].\ntuple_branches(Branches) -> list_to_tuple([list_to_tuple(B) || B <- Branches]).\npositions(Branches) -> list_to_tuple(lists:duplicate(length(Branches), 0)).\nadvance(Positions, I) -> setelement(I, Positions, element(I, Positions) + 1).\npending(Branches, Positions) -> [{I, element(K + 1, B)}\n    || I <- lists:seq(1, tuple_size(Branches)), B <- [element(I, Branches)],\n        K <- [element(I, Positions)], K < tuple_size(B)].\n"
runtimeSource "beam-history" = "%% @doc Scenario histories carry vector clocks through sends, receives and\n%% fork/join. Consistency depends on these message edges as well as each\n%% caller's own order; real time is required only for linearizability.\n%% ref:DEC-sessions-by-construction ref:DEC-stateful-models-linearizability\n%% ref:wing-gong-linearizability\n-module(lawspec_beam_history).\n-export([consistent/6, happened_before/2]).\n\nhappened_before(#{return_clock := Returned}, #{call_clock := Called}) ->\n    maps:fold(fun(Process, Count, Yes) -> Yes andalso maps:get(Process, Called, 0) >= Count end, true, Returned).\n\n%% Each event has command (the model command index), arguments, result,\n%% called/returned (the atomic interval clock), process, call_clock and\n%% return_clock. Completed calls alone enter the history.\nconsistent(Model, Context, Events, Expected, Final, System) ->\n    History = list_to_tuple(Events), Indices = lists:seq(0, length(Events) - 1),\n    Mode = maps:get(consistency, Model),\n    Preds = list_to_tuple([mask([J || J <- Indices, J =/= I,\n        before(Mode, element(J + 1, History), element(I + 1, History))]) || I <- Indices]),\n    Judge = fun(CompareFinal) -> fun(State) ->\n        try\n            Equal = case {CompareFinal, Final} of\n                {true, {some, Actual}} -> lawspec_beam_scalar:equal(Actual, State);\n                _ -> true\n            end,\n            case Equal of\n                false -> false;\n                true -> lawspec_beam_model:check_state(Model#{abstract := none}, Context, System, State), true\n            end\n        catch _:_ -> false end\n    end end,\n    case Mode of\n        <<\"causal\">> ->\n            Processes = lists:usort([maps:get(process, E) || E <- Events]),\n            case Processes of\n                [] -> (Judge(false))(Expected);\n                _ -> lists:all(fun(Process) ->\n                    Own = [I || I <- Indices, maps:get(process, element(I + 1, History)) =:= Process],\n                    Visible = lists:usort(Own ++ [J || J <- Indices, I <- Own, J =/= I,\n                        happened_before(element(J + 1, History), element(I + 1, History))]),\n                    search(Model, Context, History, Preds, Visible, mask(Own), Expected, Judge(false))\n                end, Processes)\n            end;\n        _ ->\n            Checked = case Mode of <<\"eventual\">> -> 0; _ -> mask(Indices) end,\n            search(Model, Context, History, Preds, Indices, Checked, Expected, Judge(true))\n    end.\nbefore(<<\"linearizable\">>, #{returned := End}, #{called := Begin}) -> End < Begin;\nbefore(_, A, B) -> happened_before(A, B).\nmask(Indices) -> lists:foldl(fun(I, Bits) -> Bits bor (1 bsl I) end, 0, Indices).\n\nsearch(Model, Context, History, Preds, Members, Checked, Expected, Judge) ->\n    Setup = #{model => Model, context => Context, history => History, predecessors => Preds,\n        members => Members, full => mask(Members), checked => Checked, judge => Judge},\n    {Result, _} = visit(Setup, 0, Expected, #{}), Result.\nvisit(#{full := Full, judge := Judge}, Full, State, Seen) -> {Judge(State), Seen};\nvisit(Setup, Done, State, Seen) ->\n    Key = {Done, State},\n    case maps:is_key(Key, Seen) of\n        true -> {false, Seen};\n        false -> choose(Setup, maps:get(members, Setup), Done, State, Seen#{Key => true})\n    end.\nchoose(_, [], _, _, Seen) -> {false, Seen};\nchoose(Setup, [I | Rest], Done, State, Seen) ->\n    Bit = 1 bsl I,\n    Dependencies = element(I + 1, maps:get(predecessors, Setup)) band maps:get(full, Setup),\n    Available = Done band Bit =:= 0 andalso Dependencies band Done =:= Dependencies,\n    Outcome = case Available of\n        false -> {false, Seen};\n        true ->\n            Model = maps:get(model, Setup), Context = maps:get(context, Setup),\n            #{command := Index, arguments := Args, result := Result} = element(I + 1, maps:get(history, Setup)),\n            Command = lawspec_beam_model:command(Model, Index),\n            case lawspec_beam_model:step(Command, Context, Args, State) of\n                invalid -> {false, Seen};\n                {ok, Next, Wanted} ->\n                    Ignore = maps:get(checked, Setup) band Bit =:= 0 orelse maps:get(unit, Command),\n                    case Ignore orelse lawspec_beam_scalar:equal(Result, Wanted) of\n                        true -> visit(Setup, Done bor Bit, Next, Seen);\n                        false -> {false, Seen}\n                    end\n            end\n    end,\n    case Outcome of\n        {true, _} -> Outcome;\n        {false, S} -> choose(Setup, Rest, Done, State, S)\n    end.\n"
runtimeSource "beam-scenario" = "%% @doc Checked scenario programs run real concurrent processes, carrying\n%% vector clocks with messages and joining every child before final checks.\n%% ref:DEC-sessions-by-construction ref:DEC-stateful-models-linearizability\n%% ref:DEC-portable-seeded-generation\n-module(lawspec_beam_scenario).\n-export([new/1, execute/4, run/4, check/2, check/3, victim/2, schedules/2]).\n\nnew(Spec) when is_binary(Spec) ->\n    Forms = lawspec_beam_values:read_descriptor(Spec),\n    [<<\"scenario\">>, {quoted, Title}, _] = hd(Forms),\n    [<<\"process\">> | Body] = form(<<\"process\">>, Forms, []),\n    {Acts, _, Branches} = annotate(Body, 1, true),\n    #{title => Title, channels => tl(form(<<\"channels\">>, Forms, [<<\"channels\">>])),\n        mailboxes => tl(form(<<\"mailboxes\">>, Forms, [<<\"mailboxes\">>])),\n        acts => Acts, branches => Branches, wire => form(<<\"wire\">>, Forms, none)};\nnew(Program) when is_map(Program) -> Program.\nform(Key, Forms, Default) ->\n    case [F || [K | _] = F <- Forms, K =:= Key] of [F] -> F; [] -> Default end.\n\n%% Stable identities follow source order. Pars inside or-else handlers are\n%% real processes too, but portable crash schedules do not select them.\nannotate([], Next, _) -> {[], Next, []};\nannotate([Act | Rest], Next, Eligible) ->\n    {A, N1, B1} = annotate_act(Act, Next, Eligible),\n    {As, N2, B2} = annotate(Rest, N1, Eligible), { [A | As], N2, B1 ++ B2 }.\nannotate_act([<<\"par\">> | Branches], Next, Eligible) ->\n    {Bs, N, Found} = annotate_branches(Branches, Next, Eligible), {{par, Bs}, N, Found};\nannotate_act([<<\"receiveor\">>, Name, Variable, [<<\"process\">> | Body]], Next, _) ->\n    {Acts, N, _} = annotate(Body, Next, false), {{receive_or, Name, Variable, Acts}, N, []};\nannotate_act(Act, Next, _) -> {Act, Next, []}.\nannotate_branches([], Next, _) -> {[], Next, []};\nannotate_branches([[<<\"process\">> | Acts] | Rest], Next, Eligible) ->\n    {Body, N1, B1} = annotate(Acts, Next + 1, Eligible),\n    {Bs, N2, B2} = annotate_branches(Rest, N1, Eligible),\n    {[{Next, Body} | Bs], N2, [{Next, length(Acts)} || Eligible] ++ B1 ++ B2}.\n\nvictim(#{branches := []}, _) -> none;\nvictim(#{branches := Branches}, Shake) ->\n    R0 = lawspec_beam_random:seed(Shake bxor 16#c3a5c85c97cb3127),\n    {I, R1} = lawspec_beam_random:below(length(Branches), R0),\n    {Identity, Length} = lists:nth(I + 1, Branches),\n    {At, _} = lawspec_beam_random:below(Length + 1, R1), {Identity, At}.\nschedules(Seed, Runs) ->\n    {Cases, _} = lists:mapfoldl(fun(I, R) ->\n        {Shake, Next} = lawspec_beam_random:next(R),\n        {{Shake, #{network => I rem 3 =:= 1, crash => I rem 3 =:= 2}}, Next}\n    end, lawspec_beam_random:seed(Seed bxor 16#2545f4914f6cdd1d), lists:seq(0, Runs - 1)), Cases.\n\ncheck(Model, Spec) -> check(Model, Spec, #{}).\ncheck(Model, Spec, Options) ->\n    Program = new(Spec), Seed = lawspec_beam_model:seed(Options), Cases = maps:get(cases, Options, 30),\n    case is_integer(Cases) andalso Cases > 0 of\n        true -> ok; false -> error({lawspec, scenario_requires_cases})\n    end,\n    lists:foreach(fun({Index, {Shake, Schedule}}) ->\n        case run(Model, Program, Shake, maps:merge(Options, Schedule)) of\n            {ok, _} -> ok;\n            {error, Failure} -> error({lawspec, {scenario_failed, maps:get(title, Program),\n                #{seed => Seed, 'case' => Index - 1, shake => Shake, schedule => Schedule, failure => Failure}}})\n        end\n    end, lists:enumerate(schedules(Seed, Cases))).\n\nexecute(Model, Spec, Shake, Options) ->\n    case run(Model, Spec, Shake, Options) of {ok, _} -> ok; {error, _} = Error -> Error end.\nrun(Model, Spec, Shake, Options) ->\n    Program = new(Spec),\n    try\n        true = maps:get(shared, Model),\n        Victim = case maps:find(victim, Options) of\n            {ok, Chosen} -> Chosen;\n            error -> case maps:get(crash, Options, false) of true -> victim(Program, Shake); false -> none end\n        end,\n        case Victim of\n            none -> ok;\n            {Id, At} ->\n                case lists:keyfind(Id, 1, maps:get(branches, Program)) of\n                    {Id, Length} when is_integer(At), At >= 0, At =< Length -> ok;\n                    _ -> error({lawspec, {invalid_scenario_victim, Victim}})\n                end\n        end,\n        Start = [lawspec_beam_values:minimal(D, maps:get(table, Model)) || D <- maps:get(start_arguments, Model)],\n        lawspec_beam_model:with_system(Model, Start, 0, fun(Context, System, Expected) ->\n            lawspec_beam_scenario_io:with_io(maps:get(channels, Program),\n                sends(maps:get(acts, Program), maps:get(mailboxes, Program)),\n                Options#{wire => maps:get(wire, Program), shake => Shake}, fun(Hub) ->\n                History = ets:new(?MODULE, [ordered_set, public]),\n                try\n                    Commands = maps:from_list([{maps:get(name, C), I - 1}\n                        || {I, C} <- lists:enumerate(tuple_to_list(maps:get(commands, Model)))]),\n                    Setup = #{program => Program, model => Model, context => Context, system => System,\n                        hub => Hub, history => History, tick => atomics:new(1, []), commands => Commands,\n                        shake => Shake, victim => Victim, timeout => maps:get(receive_timeout, Options, 5000)},\n                    {Outcome, Clock} = process(Setup, root, maps:get(acts, Program), #{}, #{}, #{},\n                        lawspec_beam_random:seed(Shake)),\n                    Events = [E || {I, E} <- ets:tab2list(History), is_integer(I)],\n                    Report = #{title => maps:get(title, Program), history => Events, outcome => Outcome,\n                        clock => Clock, shake => Shake, victim => Victim,\n                        network => lawspec_beam_scenario_io:network_stats(Hub)},\n                    case ets:lookup(History, failure) of\n                        [{failure, Failure}] -> {error, maps:merge(Report, Failure)};\n                        [] when Outcome =:= failed, Victim =:= none -> {error, Report#{reason => process_failed}};\n                        [] ->\n                            Final = final(Model, Context, System),\n                            case lawspec_beam_history:consistent(Model, Context, Events, Expected, Final, System) of\n                                true -> {ok, Report#{final => Final}};\n                                false -> {error, Report#{reason => no_consistent_order, final => Final}}\n                            end\n                    end\n                after ets:delete(History) end\n            end)\n        end)\n    catch Class:Reason:Stack ->\n        {error, #{title => maps:get(title, Program), shake => Shake,\n            reason => {raised, Class, Reason}, stack => Stack}}\n    end.\nfinal(#{abstract := none}, _, _) -> none;\nfinal(Model = #{abstract := Abstract}, Context, System) ->\n    State = case maps:get(actor, Model) of true -> lawspec_beam_actors:state(System); false -> System end,\n    {some, lawspec_beam_model:callback(Abstract, Context, [State])}.\n\nprocess(Setup, Identity, Acts, Values, Ends, Clock, Random) ->\n    Hub = maps:get(hub, Setup),\n    try\n        case Identity of root -> ok; _ -> lawspec_beam_scenario_io:enter(Hub, Identity) end,\n        State = #{id => Identity, values => Values, ends => Ends, clock => Clock,\n            random => Random, crashable => true},\n        {Outcome, Last} = steps(Setup, Acts, 0, State), {Outcome, maps:get(clock, Last)}\n    catch Class:Reason:Stack ->\n        ets:insert_new(maps:get(history, Setup), {failure, #{process => Identity,\n            reason => {raised, Class, Reason}, stack => Stack}}),\n        {failed, Clock}\n    after lawspec_beam_scenario_io:leave(Hub, Identity) end.\nsteps(Setup, Acts, Index, State) ->\n    Interrupted = ets:member(maps:get(history, Setup), failure) orelse\n        (maps:get(crashable, State) andalso maps:get(victim, Setup) =:= {maps:get(id, State), Index}),\n    case {Interrupted, Acts} of\n        {true, _} -> {failed, State};\n        {false, []} -> {done, State};\n        {false, [Act | Rest]} ->\n            case act(Setup, Act, State) of\n                {continue, Next} -> steps(Setup, Rest, Index + 1, Next);\n                {finish, Result} -> Result\n            end\n    end.\n\nact(Setup, [<<\"call\">>, Name, Bound | Operands], State = #{values := Values}) ->\n    Model = maps:get(model, Setup), Context = maps:get(context, Setup),\n    Index = maps:get(Name, maps:get(commands, Setup)), Command = lawspec_beam_model:command(Model, Index),\n    Args = [value(O, Values) || O <- Operands],\n    S1 = bump(perturb(State)), CallClock = maps:get(clock, S1),\n    Called = tick(Setup), System = maps:get(system, Setup),\n    {Result, System} = lawspec_beam_model:invoke(Model, Context, Command, Args, System),\n    Returned = tick(Setup), S2 = bump(S1),\n    Event = #{command => Index, arguments => Args, result => Result, process => maps:get(id, State),\n        called => Called, returned => Returned, call_clock => CallClock, return_clock => maps:get(clock, S2)},\n    ets:insert(maps:get(history, Setup), {Called, Event}),\n    NextValues = case Bound of none -> Values; _ -> Values#{Bound => Result} end,\n    {continue, S2#{values := NextValues}};\nact(Setup, [<<\"send\">>, Name, Operand], State) ->\n    Destination = destination(Setup, Name, State),\n    {Value, S1} = give(Operand, State), S2 = bump(perturb(S1)),\n    ok = lawspec_beam_scenario_io:send(maps:get(hub, Setup), maps:get(id, State), Destination, Value, maps:get(clock, S2)),\n    {continue, S2};\nact(Setup, [<<\"receive\">>, Name, Variable], State) -> accept(Setup, Name, Variable, none, State);\nact(Setup, {receive_or, Name, Variable, Handler}, State) -> accept(Setup, Name, Variable, Handler, State);\nact(Setup, {par, Branches}, State) ->\n    Program = maps:get(program, Setup),\n    {Plans, Ends} = divide(Branches, maps:get(channels, Program), maps:get(ends, State)),\n    Children = [#{id => Id, ends => maps:values(Mine), sends => sends(Body, maps:get(mailboxes, Program)),\n        receives => [N || N <- maps:get(mailboxes, Program), receives(Body, N)]} || {Id, Body, Mine} <- Plans],\n    ok = lawspec_beam_scenario_io:fork(maps:get(hub, Setup), maps:get(id, State), Children),\n    Outcomes = lawspec_beam_runtime:concurrently([\n        fun() -> process(Setup, Id, Body, maps:get(values, State), Mine, maps:get(clock, State),\n            lawspec_beam_random:seed(maps:get(shake, Setup) bxor (I * 16#9e3779b97f4a7c15))) end\n        || {I, {Id, Body, Mine}} <- lists:enumerate(Plans)]),\n    Clock = lists:foldl(fun({_, C}, Acc) -> merge_clock(Acc, C) end, maps:get(clock, State), Outcomes),\n    Next = bump(State#{ends := Ends, clock := Clock}),\n    case lists:keymember(failed, 1, Outcomes) of\n        true -> {finish, {failed, Next}};\n        false -> {continue, Next}\n    end;\nact(_, [<<\"expect\">>, Variable, Constant], State = #{values := Values}) ->\n    Actual = maps:get(Variable, Values), Wanted = value(Constant, #{}),\n    case lawspec_beam_scalar:equal(Actual, Wanted) of\n        true -> {continue, State};\n        false -> error({lawspec, {scenario_expectation, Variable, Actual, Wanted}})\n    end.\n\naccept(Setup, Name, Variable, Handler, State = #{ends := Ends, values := Values}) ->\n    Destination = destination(Setup, Name, State),\n    Hub = maps:get(hub, Setup), Identity = maps:get(id, State),\n    case lawspec_beam_scenario_io:receive_value(Hub, Identity, Destination, maps:get(timeout, Setup)) of\n        gone when Handler =:= none -> {finish, {failed, State}};\n        gone ->\n            case Destination of {'end', _, _} -> lawspec_beam_scenario_io:abandon(Hub, Identity, Destination); _ -> ok end,\n            {finish, steps(Setup, Handler, 0, State#{ends := maps:remove(Name, Ends), crashable := false})};\n        {value, Value, Sent} ->\n            Next = bump(State#{clock := merge_clock(maps:get(clock, State), Sent)}),\n            case Value of\n                {lawspec_scenario_end, Channel, Side} -> {continue, Next#{ends := Ends#{Variable => {'end', Channel, Side}}}};\n                _ -> {continue, Next#{values := Values#{Variable => Value}}}\n            end\n    end.\ndestination(#{program := #{mailboxes := Boxes}}, Name, #{ends := Ends}) ->\n    case lists:member(Name, Boxes) of true -> {mailbox, Name}; false -> maps:get(Name, Ends) end.\ngive([<<\"var\">>, Name] = Operand, State = #{ends := Ends, values := Values}) ->\n    case maps:take(Name, Ends) of\n        {{'end', Channel, Side}, Rest} -> {{lawspec_scenario_end, Channel, Side}, State#{ends := Rest}};\n        error -> {value(Operand, Values), State}\n    end;\ngive(Operand, State) -> {value(Operand, #{}), State}.\nvalue([<<\"var\">>, Name], Values) -> maps:get(Name, Values);\nvalue([<<\"int\">>, Number], _) -> Number;\nvalue([<<\"bool\">>, Boolean], _) -> Boolean =:= <<\"true\">>;\nvalue([<<\"text\">>, {quoted, Text}], _) -> Text;\nvalue([<<\"tag\">>, Tag], _) -> {ls_data, Tag, []}.\ntick(Setup) -> atomics:add_get(maps:get(tick, Setup), 1, 1).\nbump(State = #{id := Identity, clock := Clock}) -> State#{clock := Clock#{Identity => maps:get(Identity, Clock, 0) + 1}}.\nmerge_clock(A, B) -> maps:fold(fun(P, N, Acc) -> Acc#{P => max(maps:get(P, Acc, 0), N)} end, A, B).\nperturb(State = #{random := Random}) ->\n    {Choice, Next} = lawspec_beam_random:below(4, Random),\n    case Choice of 0 -> ok; 1 -> erlang:yield(); _ -> receive after 1 -> ok end end,\n    State#{random := Next}.\n\ndivide(Branches, Channels, Ends) ->\n    Users = lists:foldl(fun({I, {_, Body}}, Acc) ->\n        lists:foldl(fun(N, A) -> A#{N => maps:get(N, A, []) ++ [I]} end, Acc, names(Body))\n    end, #{}, lists:enumerate(Branches)),\n    lists:mapfoldl(fun({I, {Id, Body}}, Remaining) ->\n        {Mine, Rest} = lists:foldl(fun(N, {Own, Left}) ->\n            case maps:take(N, Left) of\n                {End, More} -> {Own#{N => End}, More};\n                error -> case lists:member(N, Channels) of\n                    false -> {Own, Left};\n                    true ->\n                        Side = length(lists:takewhile(fun(J) -> J =/= I end, maps:get(N, Users))),\n                        {Own#{N => {'end', N, Side}}, Left}\n                end\n            end\n        end, {#{}, Remaining}, names(Body)),\n        {{Id, Body, Mine}, Rest}\n    end, Ends, lists:enumerate(Branches)).\nnames(Acts) -> lists:usort(lists:append([case Act of\n    [<<\"send\">>, N, [<<\"var\">>, V]] -> [N, V];\n    [<<\"send\">>, N, _] -> [N];\n    [<<\"receive\">>, N, _] -> [N];\n    {receive_or, N, _, Handler} -> [N | names(Handler)];\n    {par, Branches} -> lists:append([names(Body) || {_, Body} <- Branches]);\n    _ -> []\nend || Act <- Acts])).\nsends(Acts, Boxes) -> maps:from_list([{N, count_sends(Acts, N)} || N <- Boxes]).\ncount_sends(Acts, Name) -> lists:sum([case Act of\n    [<<\"send\">>, Name, _] -> 1;\n    {par, Branches} -> lists:sum([count_sends(Body, Name) || {_, Body} <- Branches]);\n    _ -> 0\nend || Act <- Acts]).\nreceives(Acts, Name) -> lists:any(fun(Act) -> case Act of\n    [<<\"receive\">>, Name, _] -> true;\n    {par, Branches} -> lists:any(fun({_, Body}) -> receives(Body, Name) end, Branches);\n    _ -> false\nend end, Acts).\n"
runtimeSource "beam-scenario_io" = "%% @doc A scenario's channels, delegated ends and mailbox send obligations\n%% have one owner. A single server transfers them atomically and never runs\n%% application code. Process death releases both current and unforked work.\n%% ref:DEC-sessions-by-construction\n-module(lawspec_beam_scenario_io).\n-behaviour(gen_server).\n-export([start/2, start/3, with_io/3, with_io/4, stop/1, fork/3, enter/2, leave/2,\n    send/5, receive_value/3, receive_value/4, abandon/3, network_stats/1]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2]).\n\nstart(Channels, Mailboxes) -> start(Channels, Mailboxes, #{}).\nstart(Channels, Mailboxes, Options) -> gen_server:start(?MODULE, {self(), Channels, Mailboxes, Options}, []).\nwith_io(Channels, Mailboxes, Body) ->\n    with_io(Channels, Mailboxes, #{}, Body).\nwith_io(Channels, Mailboxes, Options, Body) ->\n    {ok, Hub} = start(Channels, Mailboxes, Options),\n    try Body(Hub) after stop(Hub) end.\nstop(Hub) ->\n    try gen_server:stop(Hub, normal, infinity)\n    catch exit:noproc -> ok; exit:{noproc, _} -> ok end.\nfork(Hub, Parent, Children) -> call(Hub, {fork, Parent, Children}).\nenter(Hub, Identity) -> call(Hub, {enter, Identity}).\nleave(Hub, Identity) -> call(Hub, {leave, Identity}).\nsend(Hub, Identity, Destination, Value, Clock) -> call(Hub, {send, Identity, Destination, Value, Clock}).\nreceive_value(Hub, Identity, Destination) -> receive_value(Hub, Identity, Destination, 5000).\nreceive_value(Hub, Identity, Destination, Timeout) -> call(Hub, {'receive', Identity, Destination, Timeout}).\nabandon(Hub, Identity, End) -> call(Hub, {abandon, Identity, End}).\nnetwork_stats(Hub) -> call(Hub, network_stats).\ncall(Hub, Request) ->\n    case gen_server:call(Hub, Request, infinity) of\n        {error, Reason} -> error({lawspec, {scenario_io, Reason}});\n        Result -> Result\n    end.\n\n%% Ends are {end, Name, Side}; mailboxes are {mailbox, Name}. A payload\n%% {lawspec_scenario_end, Name, Side} moves ownership, rather than copying it.\ninit({Owner, Channels, Mailboxes, Options}) ->\n    try initialize(Owner, Channels, Mailboxes, Options)\n    catch error:{lawspec, Reason} -> {stop, {lawspec, Reason}} end.\ninitialize(Owner, Channels, Mailboxes, Options) ->\n    Ends = maps:from_list([{{'end', Name, Side}, queue_state(root)} || Name <- Channels, Side <- [0, 1]]),\n    Boxes = maps:from_list([{{mailbox, Name}, (queue_state(root))#{outstanding => Count}}\n        || {Name, Count} <- maps:to_list(Mailboxes)]),\n    Network = case maps:get(network, Options, false) of\n        true -> lawspec_beam_scenario_network:new(Channels, Mailboxes, maps:get(wire, Options, none), Options);\n        false -> none\n    end,\n    {ok, #{owner => monitor(process, Owner), queues => maps:merge(Ends, Boxes), monitors => #{}, network => Network,\n        processes => #{root => #{pid => Owner, monitor => none, parent => none, sends => Mailboxes, closed => false}}}}.\nqueue_state(Owner) -> #{owner => Owner, closed => false, items => queue:new(), waiting => none, in_flight => 0, remote_gone => false}.\n\nhandle_call(Request, From = {Caller, _}, State) ->\n    try request(Request, Caller, From, State) catch\n        throw:{invalid, Reason} -> {reply, {error, Reason}, State}\n    end.\nhandle_cast(_, State) -> {noreply, State}.\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{owner := Monitor}) -> {stop, normal, State};\nhandle_info({'DOWN', Monitor, process, _, _} = Message, State = #{monitors := Monitors}) ->\n    case maps:find(Monitor, Monitors) of\n        {ok, Identity} -> {noreply, close_process(Identity, State)};\n        error -> network_message(Message, State)\n    end;\nhandle_info({receive_timeout, Destination, Ref}, State) ->\n    Q = get_queue(Destination, State),\n    case maps:get(waiting, Q) of\n        {From, Ref, _} ->\n            gen_server:reply(From, {error, {receive_timeout, Destination}}),\n            {noreply, put_queue(Destination, Q#{waiting := none}, State)};\n        _ -> {noreply, State}\n    end;\nhandle_info(Message, State) -> network_message(Message, State).\nterminate(_, State) ->\n    maps:foreach(fun(_, Q) -> case maps:get(waiting, Q) of\n        none -> ok; {_, _, Timer} -> erlang:cancel_timer(Timer)\n    end end, maps:get(queues, State)),\n    case maps:get(network, State) of none -> ok; Net -> lawspec_beam_scenario_network:close(Net) end.\nnetwork_message(_, State = #{network := none}) -> {noreply, State};\nnetwork_message(Message, State = #{network := Network}) ->\n    case lawspec_beam_scenario_network:event(Message, Network) of\n        ignore -> {noreply, State};\n        {Events, Next} -> {noreply, lists:foldl(fun network_event/2, State#{network := Next}, Events)}\n    end.\nnetwork_event({delivered, Destination, Value, Clock}, State) ->\n    arrive(Destination, Value, Clock, unflight(Destination, State));\nnetwork_event({lost, Destination, Value}, State) -> wake(Destination, discard(Value, unflight(Destination, State)));\nnetwork_event({gone, Destination}, State) ->\n    Q = get_queue(Destination, State), wake(Destination, put_queue(Destination, Q#{remote_gone := true}, State)).\nunflight(Destination = {mailbox, _}, State) ->\n    Q = get_queue(Destination, State), put_queue(Destination, Q#{in_flight := maps:get(in_flight, Q) - 1}, State);\nunflight(_, State) -> State.\n\nrequest(network_stats, _, _, State) ->\n    Stats = case maps:get(network, State) of none -> none; Net -> lawspec_beam_scenario_network:stats(Net) end,\n    {reply, Stats, State};\nrequest({fork, Identity, Children}, Caller, _, State) ->\n    _ = owned_process(Identity, Caller, State),\n    %% Reserve every child's obligations before any worker can run. A child\n    %% killed before enter/2 still belongs to its parent and will be closed.\n    Updated = lists:foldl(fun(Child, S) -> reserve(Identity, Child, S) end, State, Children),\n    {reply, ok, Updated};\nrequest({enter, Identity}, Caller, _, State = #{processes := Processes, monitors := Monitors}) ->\n    P = get_process(Identity, State),\n    require(not maps:get(closed, P) andalso maps:get(pid, P) =:= none, {cannot_enter, Identity}),\n    Monitor = monitor(process, Caller),\n    {reply, ok, State#{processes := Processes#{Identity := P#{pid := Caller, monitor := Monitor}},\n        monitors := Monitors#{Monitor => Identity}}};\nrequest({leave, Identity}, Caller, _, State) ->\n    P = get_process(Identity, State),\n    require(maps:get(closed, P) orelse maps:get(pid, P) =:= Caller, {not_process_owner, Identity}),\n    {reply, ok, close_process(Identity, State)};\nrequest({abandon, Identity, End = {'end', _, _}}, Caller, _, State) ->\n    _ = owned_process(Identity, Caller, State), _ = owned_queue(Identity, End, State),\n    {reply, ok, close_queue(End, State)};\nrequest({send, Identity, Destination, Value, Clock}, Caller, From, State) ->\n    _ = owned_process(Identity, Caller, State),\n    case delegated(Value) of\n        none -> ok;\n        End ->\n            _ = owned_queue(Identity, End, State),\n            require(End =/= Destination, {self_delegation, End})\n    end,\n    {To, S1} = sending(Identity, Destination, State),\n    S2 = case delegated(Value) of\n        none -> S1;\n        Moved -> change_owner(Moved, {queued, To}, S1)\n    end,\n    case {maps:get(network, S2), maps:get(closed, get_queue(To, S2))} of\n        {_, true} -> {reply, ok, discard(Value, S2)};\n        {none, false} -> {reply, ok, arrive(To, Value, Clock, S2)};\n        {Net, false} ->\n            {Mode, Next} = lawspec_beam_scenario_network:send(Destination, Value, Clock, From, Net),\n            S3 = S2#{network := Next},\n            case Mode of\n                ok -> {reply, ok, S3};\n                pending ->\n                    Q = get_queue(To, S3),\n                    {noreply, put_queue(To, Q#{in_flight := maps:get(in_flight, Q) + 1}, S3)}\n            end\n    end;\nrequest({'receive', Identity, Destination, Timeout}, Caller, From, State) ->\n    _ = owned_process(Identity, Caller, State),\n    Q = owned_queue(Identity, Destination, State),\n    require(maps:get(waiting, Q) =:= none, {already_receiving, Destination}),\n    require(is_integer(Timeout) andalso Timeout >= 0 andalso Timeout =< 16#ffffffff, invalid_timeout),\n    Ref = make_ref(), Timer = erlang:send_after(Timeout, self(), {receive_timeout, Destination, Ref}),\n    {noreply, wake(Destination, put_queue(Destination, Q#{waiting := {From, Ref, Timer}}, State))}.\n\nreserve(Parent, #{id := Identity, ends := Ends, sends := Sends, receives := Receives}, State) ->\n    Processes = maps:get(processes, State),\n    require(not maps:is_key(Identity, Processes), {duplicate_process, Identity}),\n    P = get_process(Parent, State), Quotas = maps:get(sends, P),\n    Remaining = maps:fold(fun(Name, Count, Acc) ->\n        Available = maps:get(Name, Acc, 0),\n        require(is_integer(Count) andalso Count >= 0 andalso Count =< Available, {send_quota, Name}),\n        Acc#{Name => Available - Count}\n    end, Quotas, Sends),\n    S1 = lists:foldl(fun(Destination, S) ->\n        Q = owned_queue(Parent, Destination, S),\n        require(maps:get(waiting, Q) =:= none, {already_receiving, Destination}),\n        change_owner(Destination, Identity, S)\n    end, State, Ends ++ [{mailbox, Name} || Name <- Receives]),\n    Child = #{pid => none, monitor => none, parent => Parent, sends => Sends, closed => false},\n    S1#{processes := Processes#{Parent := P#{sends := Remaining}, Identity => Child}}.\n\nsending(Identity, End = {'end', Name, Side}, State) ->\n    _ = owned_queue(Identity, End, State), {{'end', Name, 1 - Side}, State};\nsending(Identity, Box = {mailbox, Name}, State = #{processes := Processes}) ->\n    P = get_process(Identity, State), Quotas = maps:get(sends, P), Count = maps:get(Name, Quotas, 0),\n    require(Count > 0, {send_quota, Name}),\n    Q = get_queue(Box, State),\n    S = State#{processes := Processes#{Identity := P#{sends := Quotas#{Name => Count - 1}}}},\n    {Box, put_queue(Box, Q#{outstanding := maps:get(outstanding, Q) - 1}, S)}.\n\nget_process(Identity, #{processes := Processes}) ->\n    case maps:find(Identity, Processes) of\n        {ok, P} -> P;\n        error -> throw({invalid, {unknown_process, Identity}})\n    end.\nowned_process(Identity, Caller, State) ->\n    P = get_process(Identity, State),\n    require(not maps:get(closed, P) andalso maps:get(pid, P) =:= Caller, {not_process_owner, Identity}), P.\nget_queue(Destination, #{queues := Queues}) ->\n    case maps:find(Destination, Queues) of\n        {ok, Q} -> Q;\n        error -> throw({invalid, {unknown_destination, Destination}})\n    end.\nowned_queue(Identity, Destination, State) ->\n    Q = get_queue(Destination, State),\n    require(not maps:get(closed, Q) andalso maps:get(owner, Q) =:= Identity,\n        {not_endpoint_owner, Destination}), Q.\nput_queue(Destination, Q, State = #{queues := Queues}) -> State#{queues := Queues#{Destination := Q}}.\nchange_owner(Destination, Owner, State) ->\n    Q = get_queue(Destination, State), put_queue(Destination, Q#{owner := Owner}, State).\nrequire(true, _) -> ok;\nrequire(false, Reason) -> throw({invalid, Reason}).\ndelegated({lawspec_scenario_end, Name, Side}) -> {'end', Name, Side};\ndelegated(_) -> none.\ndiscard(Value, State) ->\n    case delegated(Value) of none -> State; End -> close_queue(End, State) end.\narrive(To, Value, Clock, State) ->\n    Q = get_queue(To, State),\n    case maps:get(closed, Q) of\n        true -> discard(Value, State);\n        false -> wake(To, put_queue(To, Q#{items := queue:in({Value, Clock}, maps:get(items, Q))}, State))\n    end.\n\n%% Drain accepted values before reporting that a sender has gone. A moved\n%% end is owned by the queue until its recipient actually receives it.\nwake(Destination, State) ->\n    Q = get_queue(Destination, State),\n    case maps:get(waiting, Q) of\n        none -> State;\n        Waiting ->\n            case queue:out(maps:get(items, Q)) of\n                {{value, {Value, Clock}}, Remaining} ->\n                    S1 = put_queue(Destination, Q#{items := Remaining, waiting := none}, State),\n                    S2 = case delegated(Value) of\n                        none -> S1;\n                        End -> change_owner(End, maps:get(owner, Q), S1)\n                    end,\n                    reply(Waiting, {value, Value, Clock}), S2;\n                {empty, _} ->\n                    Gone = case Destination of\n                        {mailbox, _} -> maps:get(outstanding, Q) + maps:get(in_flight, Q) =:= 0;\n                        {'end', Name, Side} -> case maps:get(network, State) of\n                            none -> maps:get(closed, get_queue({'end', Name, 1 - Side}, State));\n                            _ -> maps:get(remote_gone, Q)\n                        end\n                    end,\n                    case Gone of\n                        true -> reply(Waiting, gone), put_queue(Destination, Q#{waiting := none}, State);\n                        false -> State\n                    end\n            end\n    end.\nreply(none, _) -> ok;\nreply({From, _, Timer}, Value) -> erlang:cancel_timer(Timer), gen_server:reply(From, Value).\n\nclose_queue(Destination, State) ->\n    Q = get_queue(Destination, State),\n    case maps:get(closed, Q) of\n        true -> State;\n        false ->\n            reply(maps:get(waiting, Q), gone),\n            S1 = put_queue(Destination, Q#{closed := true, items := queue:new(), waiting := none}, State),\n            %% Mark closed before following delegated ends: even cyclic\n            %% queues cannot recurse forever or call another server.\n            S2 = lists:foldl(fun({Value, _}, S) -> discard(Value, S) end, S1, queue:to_list(maps:get(items, Q))),\n            case maps:get(network, S2) of\n                none -> case Destination of\n                    {'end', Name, Side} -> wake({'end', Name, 1 - Side}, S2);\n                    {mailbox, _} -> S2\n                end;\n                Net -> S2#{network := lawspec_beam_scenario_network:abandon(Destination, Net)}\n            end\n    end.\nclose_process(Identity, State) ->\n    P = get_process(Identity, State),\n    case maps:get(closed, P) of\n        true -> State;\n        false ->\n            Monitor = maps:get(monitor, P),\n            case Monitor of none -> ok; _ -> demonitor(Monitor, [flush]) end,\n            Processes = maps:get(processes, State),\n            S1 = State#{processes := Processes#{Identity := P#{closed := true, sends := #{}}},\n                monitors := maps:remove(Monitor, maps:get(monitors, State))},\n            Children = [I || {I, #{parent := Parent}} <- maps:to_list(Processes), Parent =:= Identity],\n            S2 = lists:foldl(fun close_process/2, S1, Children),\n            Destinations = [D || {D, #{owner := Owner}} <- maps:to_list(maps:get(queues, S2)),\n                Owner =:= Identity orelse Identity =:= root],\n            S3 = lists:foldl(fun close_queue/2, S2, Destinations),\n            maps:fold(fun(Name, Count, S) ->\n                Box = {mailbox, Name}, Q = get_queue(Box, S),\n                wake(Box, put_queue(Box, Q#{outstanding := maps:get(outstanding, Q) - Count}, S))\n            end, S3, maps:get(sends, P))\n    end.\n"
runtimeSource "beam-scenario_network" = "%% @doc Scenario values use the same canonical frames, reliable endpoints\n%% and mailbox receipts as native distribution. Only causal metadata stays\n%% beside the transport: channel clocks follow sequence order, and mailbox\n%% clocks follow the actual source/request identity, even after reordering.\n%% ref:DEC-distribution-canonical-wire ref:DEC-stateful-models-linearizability\n-module(lawspec_beam_scenario_network).\n-export([new/4, close/1, send/5, abandon/2, event/2, stats/1]).\n\nnew(Channels, Mailboxes, Wire, Options) ->\n    Forms = case Wire of [<<\"wire\">> | Fs] -> Fs; none when Channels =:= [], map_size(Mailboxes) =:= 0 -> [];\n        _ -> error({lawspec, scenario_wire_required}) end,\n    Steps = maps:from_list([{N, Ss} || [<<\"channel\">>, N | Ss] <- Forms]),\n    Types = maps:from_list([{N, D} || [<<\"mailbox\">>, N, D] <- Forms]),\n    require(lists:sort(maps:keys(Steps)) =:= lists:sort(Channels), channel_wire_required),\n    require(lists:sort(maps:keys(Types)) =:= lists:sort(maps:keys(Mailboxes)), mailbox_wire_required),\n    Table = maps:from_list([{unquote(Name), D} || [<<\"data\">>, Name | _] = D <- Forms]),\n    Defaults = #{seed => maps:get(shake, Options, 0) bxor 16#7f4a7c159e3779b9,\n        loss => 0.1, duplicate => 0.1, delay => 0.002, record => true},\n    {ok, Network} = lawspec_beam_memory_network:start(maps:merge(Defaults, maps:get(faults, Options, #{}))),\n    Base = #{network => Network, nodes => [], ends => #{}, endpoints => #{}, boxes => #{}, inboxes => #{},\n        table => Table, flights => #{}, pending => #{},\n        monitors => #{monitor(process, Network) => Network}, timeout => maps:get(deadline, Options, 5000)},\n    S1 = lists:foldl(fun(Name, S) -> add_channel(Name, maps:get(Name, Steps), S) end, Base, Channels),\n    lists:foldl(fun(Name, S) -> add_mailbox(Name, maps:get(Name, Types), S) end, S1, lists:sort(maps:keys(Mailboxes))).\nunquote({quoted, Name}) -> Name;\nunquote(Name) -> Name.\nrequire(true, _) -> ok;\nrequire(false, Reason) -> error({lawspec, {scenario_network, Reason}}).\n\nadd_node(State = #{network := Net, nodes := Nodes, monitors := Monitors}) ->\n    Name = <<\"scenario-\", (integer_to_binary(length(Nodes)))/binary>>,\n    {ok, Node} = lawspec_beam_node:start_owned(lawspec_beam_memory_network:insecure_transport_for_tests(Net, Name), #{}),\n    {Node, State#{nodes := [Node | Nodes], monitors := Monitors#{monitor(process, Node) => Node}}}.\nadd_channel(Name, Steps, State) ->\n    {A, S1} = add_end(Name, 0, Steps, State), {B, S2} = add_end(Name, 1, Steps, S1),\n    ok = lawspec_beam_endpoint:connect(B, lawspec_beam_endpoint:address(A)), S2.\nadd_end(Name, Side, Steps, State) ->\n    {Node, S1} = add_node(State),\n    {ok, End} = lawspec_beam_endpoint:start(Node, <<\"end\">>, #{deadline => maps:get(timeout, State)}),\n    Sends = [D || [Verb, D] <- Steps, (Verb =:= <<\"send\">>) =:= (Side =:= 0)],\n    Receives = [D || [Verb, D] <- Steps, (Verb =:= <<\"send\">>) =/= (Side =:= 0)],\n    Ticket = lawspec_beam_endpoint:receive_async(End, infinity),\n    Destination = {'end', Name, Side}, Ends = maps:get(ends, S1), Endpoints = maps:get(endpoints, S1),\n    Monitors = maps:get(monitors, S1),\n    Entry = #{endpoint => End, sends => Sends, receives => Receives, clocks => queue:new(), ticket => Ticket},\n    {End, S1#{ends := Ends#{Destination => Entry}, endpoints := Endpoints#{End => Destination},\n        monitors := Monitors#{monitor(process, End) => End}}}.\nadd_mailbox(Name, Type, State) ->\n    {Owner, S1} = add_node(State), {Sender, S2} = add_node(S1),\n    Address = lawspec_beam_node:register_receiver(Owner, <<\"mail\">>, self()),\n    Boxes = maps:get(boxes, S2), Inboxes = maps:get(inboxes, S2),\n    S2#{boxes := Boxes#{{mailbox, Name} => #{sender => Sender, address => Address, type => Type}},\n        inboxes := Inboxes#{Owner => {mailbox, Name}}}.\nclose(State) ->\n    maps:foreach(fun(_, #{from := From}) -> gen_server:reply(From, {error, network_closed}) end, maps:get(pending, State)),\n    lists:foreach(fun lawspec_beam_node:stop/1, maps:get(nodes, State)),\n    lawspec_beam_memory_network:stop(maps:get(network, State)).\n\nsend(Destination = {'end', Name, Side}, Value, Clock, _, State = #{ends := Ends}) ->\n    Entry = maps:get(Destination, Ends),\n    [Type | Rest] = maps:get(sends, Entry),\n    Bytes = encode(Type, Value, State),\n    ok = lawspec_beam_endpoint:send(maps:get(endpoint, Entry), Bytes),\n    Other = {'end', Name, 1 - Side}, Peer = maps:get(Other, Ends),\n    {ok, State#{ends := Ends#{Destination := Entry#{sends := Rest},\n        Other := Peer#{clocks := queue:in({Value, Clock}, maps:get(clocks, Peer))}}}};\nsend(Box = {mailbox, _}, Value, Clock, From, State = #{boxes := Boxes, flights := Flights, pending := Pending}) ->\n    #{sender := Node, address := Address, type := Type} = maps:get(Box, Boxes),\n    Bytes = encode(Type, Value, State),\n    {Ticket, Identity} = lawspec_beam_node:request_async(Node, Address, <<\"mail\">>, Bytes, maps:get(timeout, State)),\n    Key = {lawspec_beam_node:address(Node), Identity},\n    Flight = #{destination => Box, value => Value, clock => Clock},\n    {pending, State#{flights := Flights#{Key => Flight}, pending := Pending#{Ticket => #{from => From, key => Key, node => Node}}}}.\nabandon(Destination = {'end', _, _}, State) ->\n    ok = lawspec_beam_endpoint:abandon(maps:get(endpoint, maps:get(Destination, maps:get(ends, State)))), State;\nabandon({mailbox, _}, State) -> State.\n\nevent({lawspec_channel, End, Ticket, Result}, State = #{endpoints := Endpoints, ends := Ends}) ->\n    case maps:find(End, Endpoints) of\n        {ok, Destination} ->\n            Entry = maps:get(Destination, Ends),\n            case maps:get(ticket, Entry) of Ticket -> channel_event(Destination, Entry, Result, State); _ -> ignore end;\n        error -> ignore\n    end;\nevent({lawspec_frame, Node, Frame = #{source := Source, id := Identity, payload := Bytes}}, State = #{inboxes := Inboxes, flights := Flights}) ->\n    Key = {Source, Identity},\n    case {maps:find(Node, Inboxes), maps:find(Key, Flights)} of\n        {{ok, Box}, {ok, #{destination := Box, clock := Clock}}} ->\n            <<\"mail\">> = maps:get(kind, Frame),\n            Value = decode(maps:get(type, maps:get(Box, maps:get(boxes, State))), Bytes, State),\n            ok = lawspec_beam_node:reply(Node, Source, Identity, 0, <<>>),\n            {[{delivered, Box, Value, Clock}], State#{flights := maps:remove(Key, Flights)}};\n        {{ok, _}, _} ->\n            ok = lawspec_beam_node:reply(Node, Source, Identity, 3, <<\"not a scenario mailbox request\">>), {[], State};\n        _ -> ignore\n    end;\nevent({lawspec_reply, Node, Ticket, Result}, State = #{pending := Pending, flights := Flights}) ->\n    case maps:find(Ticket, Pending) of\n        {ok, #{node := Node, from := From, key := Key}} ->\n            Reply = case Result of {ok, {0, <<>>}} -> ok; _ -> {error, {mailbox_send_failed, Result}} end,\n            gen_server:reply(From, Reply),\n            %% A timed-out request may never have reached its destination.\n            %% Release its in-flight quota and any end it was carrying.\n            Lost = case maps:find(Key, Flights) of\n                error -> [];\n                {ok, #{destination := Box, value := Value}} -> [{lost, Box, Value}]\n            end,\n            {Lost, State#{pending := maps:remove(Ticket, Pending), flights := maps:remove(Key, Flights)}};\n        _ -> ignore\n    end;\nevent({'DOWN', Monitor, process, Pid, Reason}, #{monitors := Monitors}) ->\n    case maps:is_key(Monitor, Monitors) of\n        true -> error({lawspec, {scenario_network, {service_stopped, Pid, Reason}}});\n        false -> ignore\n    end;\nevent(_, _) -> ignore.\n\nchannel_event(Destination, Entry, {value, Bytes}, State = #{ends := Ends}) ->\n    [Type | Types] = maps:get(receives, Entry),\n    {{value, {_, Clock}}, Clocks} = queue:out(maps:get(clocks, Entry)),\n    Value = decode(Type, Bytes, State),\n    Ticket = lawspec_beam_endpoint:receive_async(maps:get(endpoint, Entry), infinity),\n    {[{delivered, Destination, Value, Clock}], State#{ends := Ends#{Destination := Entry#{receives := Types, clocks := Clocks, ticket := Ticket}}}};\nchannel_event(Destination, Entry, {error, _}, State = #{ends := Ends}) ->\n    Lost = [{lost, Destination, Value} || {Value, _} <- queue:to_list(maps:get(clocks, Entry))],\n    {Lost ++ [{gone, Destination}], State#{ends := Ends#{Destination := Entry#{clocks := queue:new(), ticket := none}}}}.\n\nencode([<<\"end\">>], {lawspec_scenario_end, Name, Side}, State) ->\n    require(maps:is_key({'end', Name, Side}, maps:get(ends, State)), unknown_delegated_end),\n    lawspec_beam_values:encode([<<\"text\">>], <<Name/binary, \"#\", (integer_to_binary(Side))/binary>>, #{});\nencode(Type, Value, State) -> lawspec_beam_values:encode(Type, Value, maps:get(table, State)).\ndecode([<<\"end\">>], Bytes, State) ->\n    Address = lawspec_beam_values:decode([<<\"text\">>], Bytes, #{}),\n    [Number | Names] = lists:reverse(binary:split(Address, <<\"#\">>, [global])),\n    Name = iolist_to_binary(lists:join(<<\"#\">>, lists:reverse(Names))), Side = binary_to_integer(Number),\n    require(maps:is_key({'end', Name, Side}, maps:get(ends, State)), unknown_delegated_end),\n    {lawspec_scenario_end, Name, Side};\ndecode(Type, Bytes, State) -> lawspec_beam_values:decode(Type, Bytes, maps:get(table, State)).\n\nstats(State) ->\n    Trace = lawspec_beam_memory_network:trace(maps:get(network, State)),\n    #{frames => length(Trace), lost => length([lost || #{outcome := lost} <- Trace]),\n        duplicated => length([duplicate || #{delay_slots := [_, _]} <- Trace]),\n        pending_requests => map_size(maps:get(pending, State))}.\n"
runtimeSource "beam-wire" = "%% @doc The shared distribution frame format. All identifiers stay binaries;\n%% a received frame never creates a BEAM atom. Values use the same canonical\n%% descriptor codec as generated definitions and the other targets.\n%% ref:DEC-distribution-canonical-wire\n-module(lawspec_beam_wire).\n-export([frame/5, read_frame/1, fields/3, read_fields/3,\n    channel/3, read_channel/1, sequence/1, read_sequence/1, split_address/1]).\n\nframe(Kind, To, Source, Identity, Payload) ->\n    fields(frame_types(), [Kind, To, Source, Identity, Payload], #{}).\nread_frame(Bytes) ->\n    try\n        {Fields, <<>>} = read_fields(frame_types(), Bytes, #{}),\n        [Kind, To, Source, Identity, Payload] = Fields,\n        {ok, #{kind => Kind, to => To, source => Source, id => Identity, payload => Payload}}\n    catch _:_ -> {error, invalid_frame} end.\nframe_types() -> [[<<\"text\">>], [<<\"text\">>], [<<\"text\">>],\n    [<<\"int\">>, <<\"UInt64\">>, 0, 16#ffffffffffffffff], [<<\"bytes\">>]].\nsequence_type() -> [<<\"int\">>, <<\"Int64\">>, -16#8000000000000000, 16#7fffffffffffffff].\nfields(Types, Values, Table) ->\n    true = length(Types) =:= length(Values),\n    iolist_to_binary([lawspec_beam_values:encode(D, V, Table) || {D, V} <- lists:zip(Types, Values)]).\nread_fields(Types, Bytes, Table) ->\n    lists:mapfoldl(fun(D, Rest) -> lawspec_beam_values:decode_prefix(D, Rest, Table) end, Bytes, Types).\nchannel(Sequence, Sender, Body) when is_binary(Body) ->\n    Prefix = fields([sequence_type(), [<<\"text\">>]], [Sequence, Sender], #{}),\n    <<Prefix/binary, Body/binary>>.\nread_channel(Bytes) ->\n    {[Sequence, Sender], Body} = read_fields([sequence_type(), [<<\"text\">>]], Bytes, #{}),\n    {Sequence, Sender, Body}.\nsequence(Number) -> lawspec_beam_values:encode(sequence_type(), Number, #{}).\nread_sequence(Bytes) -> lawspec_beam_values:decode(sequence_type(), Bytes, #{}).\nsplit_address(Address) when is_binary(Address) ->\n    case binary:matches(Address, <<\"/\">>) of\n        [] -> error({lawspec, {invalid_address, Address}});\n        Matches ->\n            {At, 1} = lists:last(Matches),\n            <<Node:At/binary, $/, Name/binary>> = Address,\n            case binary:match(Node, <<\"://\">>) of\n                nomatch -> error({lawspec, {invalid_address, Address}});\n                _ -> {Node, Name}\n            end\n    end.\n"
runtimeSource "beam-memory_network" = "%% @doc Owned in-memory packet transport with seeded loss, duplication and\n%% delay. Frames can overtake each other; reliability belongs to the node\n%% and channel protocol above this layer. No application code runs here.\n%% ref:DEC-distribution-canonical-wire ref:DEC-portable-seeded-generation\n-module(lawspec_beam_memory_network).\n-behaviour(gen_server).\n-export([start/1, with_network/2, stop/1, transport/2, insecure_transport_for_tests/2,\n    register/3, unregister/2, send/4, partition/2, heal/1, recorded/1, trace/1]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2]).\n\n%% Loss and duplication are probabilities; delay is seconds, as on the\n%% other targets. BEAM timers round a positive delay up to a millisecond.\nstart(Options) ->\n    lists:foreach(fun(Key) ->\n        Value = maps:get(Key, Options, 0),\n        valid(is_number(Value) andalso Value >= 0 andalso Value =< 1, {invalid_probability, Key})\n    end, [loss, duplicate]),\n    Delay = maps:get(delay, Options, 0),\n    valid(is_number(Delay) andalso Delay >= 0 andalso Delay =< 4294967, invalid_delay),\n    valid(is_integer(maps:get(seed, Options, 0)), invalid_seed),\n    valid(is_boolean(maps:get(record, Options, false)), invalid_record),\n    gen_server:start(?MODULE, {self(), Options}, []).\nwith_network(Options, Body) ->\n    {ok, Network} = start(Options), try Body(Network) after stop(Network) end.\nstop(Network) ->\n    try gen_server:stop(Network, normal, infinity)\n    catch exit:noproc -> ok; exit:{noproc, _} -> ok end.\ntransport(Network, Name) -> #{module => ?MODULE, network => Network, address => address(Name), insecure_for_tests => false}.\ninsecure_transport_for_tests(Network, Name) -> (transport(Network, Name))#{insecure_for_tests := true}.\nregister(Network, Address, Pid) -> gen_server:call(Network, {register, address(Address), Pid}, infinity).\nunregister(Network, Address) -> gen_server:call(Network, {unregister, address(Address)}, infinity).\nsend(Network, Source, To, Bytes) -> gen_server:call(Network, {send, address(Source), address(To), Bytes}, infinity).\npartition(Network, Groups) -> gen_server:call(Network, {partition, [[address(N) || N <- Group] || Group <- Groups]}, infinity).\nheal(Network) -> gen_server:call(Network, heal, infinity).\nrecorded(Network) -> gen_server:call(Network, recorded, infinity).\ntrace(Network) -> gen_server:call(Network, trace, infinity).\naddress(<<\"mem://\", _/binary>> = Address) -> Address;\naddress(Name) when is_binary(Name), byte_size(Name) > 0 -> <<\"mem://\", Name/binary>>.\nvalid(true, _) -> ok;\nvalid(false, Reason) -> error({lawspec, {memory_network, Reason}}).\n\ninit({Owner, Options}) ->\n    {ok, #{owner => monitor(process, Owner), owner_pid => Owner, options => Options,\n        random => lawspec_beam_random:seed(maps:get(seed, Options, 0)),\n        nodes => #{}, monitors => #{}, pending => #{}, groups => none, trace => []}}.\nhandle_call({register, Address, Pid}, {Caller, _}, State) ->\n    case is_pid(Pid) andalso node(Pid) =:= node() andalso (Caller =:= Pid orelse Caller =:= maps:get(owner_pid, State)) of\n        false -> {reply, {error, not_node_owner}, State};\n        true ->\n            Current = prune(Address, State), Nodes = maps:get(nodes, Current), Monitors = maps:get(monitors, Current),\n            case maps:find(Address, Nodes) of\n                {ok, _} -> {reply, {error, already_registered}, Current};\n                error ->\n                    Monitor = monitor(process, Pid),\n                    {reply, ok, Current#{nodes := Nodes#{Address => {Pid, Monitor}}, monitors := Monitors#{Monitor => Address}}}\n            end\n    end;\nhandle_call({unregister, Address}, {Caller, _}, State = #{nodes := Nodes}) ->\n    case maps:find(Address, Nodes) of\n        error -> {reply, ok, State};\n        {ok, {Pid, _}} ->\n            case Caller =:= Pid orelse Caller =:= maps:get(owner_pid, State) of\n                true -> {reply, ok, remove(Address, State)};\n                false -> {reply, {error, not_node_owner}, State}\n            end\n    end;\nhandle_call({send, Source, To, Bytes}, {Caller, _}, State = #{nodes := Nodes}) ->\n    case maps:find(Source, Nodes) of\n        {ok, {Caller, _}} when is_binary(Bytes) ->\n            {Result, Updated} = transmit(Source, To, Bytes, State), {reply, Result, Updated};\n        _ -> {reply, {error, not_node_owner}, State}\n    end;\nhandle_call({partition, Groups}, _, State) -> {reply, ok, State#{groups := Groups}};\nhandle_call(heal, _, State) -> {reply, ok, State#{groups := none}};\nhandle_call(recorded, _, State = #{trace := Trace}) -> {reply, [maps:get(frame, E) || E <- lists:reverse(Trace)], State};\nhandle_call(trace, _, State = #{trace := Trace}) -> {reply, lists:reverse(Trace), State}.\nhandle_cast(_, State) -> {noreply, State}.\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{owner := Monitor}) -> {stop, normal, State};\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{monitors := Monitors}) ->\n    case maps:find(Monitor, Monitors) of\n        {ok, Address} -> {noreply, remove(Address, State)};\n        error -> {noreply, State}\n    end;\nhandle_info({deliver, Ref, Source, To, Generation, Bytes}, State = #{pending := Pending, nodes := Nodes}) ->\n    case {maps:is_key(Ref, Pending), maps:find(To, Nodes)} of\n        {true, {ok, {Pid, Generation}}} -> Pid ! {lawspec_network, self(), Source, Bytes};\n        _ -> ok\n    end,\n    {noreply, State#{pending := maps:remove(Ref, Pending)}};\nhandle_info(_, State) -> {noreply, State}.\nterminate(_, #{pending := Pending}) ->\n    maps:foreach(fun(_, {Timer, _, _}) -> erlang:cancel_timer(Timer) end, Pending), ok.\n\nprune(Address, State = #{nodes := Nodes}) ->\n    case maps:find(Address, Nodes) of\n        {ok, {Pid, _}} -> case is_process_alive(Pid) of true -> State; false -> remove(Address, State) end;\n        error -> State\n    end.\nremove(Address, State = #{nodes := Nodes, monitors := Monitors, pending := Pending}) ->\n    case maps:take(Address, Nodes) of\n        error -> State;\n        {{_, Monitor}, Rest} ->\n            demonitor(Monitor, [flush]),\n            Remaining = maps:filter(fun(_, {Timer, To, Generation}) ->\n                case To =:= Address andalso Generation =:= Monitor of\n                    true -> erlang:cancel_timer(Timer), false;\n                    false -> true\n                end\n            end, Pending),\n            State#{nodes := Rest, monitors := maps:remove(Monitor, Monitors), pending := Remaining}\n    end.\ntransmit(Source, To, Bytes, State) ->\n    Event = #{source => Source, to => To, frame => Bytes},\n    case maps:find(To, maps:get(nodes, State)) of\n        error -> {{error, {unreachable, To}}, remember(Event#{outcome => unreachable}, State)};\n        {ok, {_, Generation}} ->\n            Groups = maps:get(groups, State),\n            Reachable = Groups =:= none orelse lists:any(fun(G) -> lists:member(Source, G) andalso lists:member(To, G) end, Groups),\n            case Reachable of\n                false -> {ok, remember(Event#{outcome => partitioned}, State)};\n                true ->\n                    {Lost, S1} = chance(loss, State),\n                    case Lost of\n                        true -> {ok, remember(Event#{outcome => lost}, S1)};\n                        false ->\n                            {Duplicate, S2} = chance(duplicate, S1),\n                            Copies = case Duplicate of true -> 2; false -> 1 end,\n                            {Slots, Next} = lists:mapfoldl(fun(_, R) -> lawspec_beam_random:below(1001, R) end,\n                                maps:get(random, S2), lists:seq(1, Copies)),\n                            Delay = maps:get(delay, maps:get(options, S2), 0),\n                            Pending = lists:foldl(fun(Slot, Acc) ->\n                                Ref = make_ref(),\n                                Timer = erlang:send_after(ceil(Slot * Delay), self(), {deliver, Ref, Source, To, Generation, Bytes}),\n                                Acc#{Ref => {Timer, To, Generation}}\n                            end, maps:get(pending, S2), Slots),\n                            {ok, remember(Event#{outcome => sent, delay_slots => Slots}, S2#{random := Next, pending := Pending})}\n                    end\n            end\n    end.\nchance(Key, State = #{options := Options, random := Random}) ->\n    Probability = maps:get(Key, Options, 0),\n    case Probability > 0 of\n        false -> {false, State};\n        true ->\n            {Draw, Next} = lawspec_beam_random:below(1 bsl 30, Random),\n            {Draw < Probability * (1 bsl 30), State#{random := Next}}\n    end.\nremember(Event, State = #{options := Options, trace := Trace}) ->\n    case maps:get(record, Options, false) of true -> State#{trace := [Event | Trace]}; false -> State end.\n"
runtimeSource "beam-channel_protocol" = "%% @doc Pure transitions for a reliable, movable network channel end.\n%% Timers and packet transport belong to its owning process. Application\n%% values enter as canonical bytes and leave in send order, exactly once.\n%% Times are monotonic microseconds; their epoch may be negative on BEAM.\n%% ref:DEC-distribution-canonical-wire ref:DEC-sessions-by-construction\n-module(lawspec_beam_channel_protocol).\n-export([new/2, connect/3, send/3, abandon/2, receive_body/1, accept/3, tick/2,\n    offer/2, take/3, take_status/2]).\n-define(RETRY, 50000).\n\nnew(Address, Deadline) when is_binary(Address), is_integer(Deadline), Deadline > 0 ->\n    _ = lawspec_beam_wire:split_address(Address),\n    #{address => Address, deadline => Deadline, peer => none, out => 0, expected => 0,\n        unacked => #{}, early => #{}, received => queue:new(), failure => none,\n        closed => false, eof => false, used => false, history => [], token => none, moved => none,\n        snapshot => none, taking => none, taken => false, confirmed => false,\n        announcing => false, announced_at => none}.\nconnect(State, Peer, Now) ->\n    usable(State), true = maps:get(peer, State) =:= none,\n    _ = lawspec_beam_wire:split_address(Peer),\n    transmit(State#{peer := Peer}, -1, <<\"hello\">>, Now).\nsend(State = #{out := Sequence}, Bytes, Now) when is_binary(Bytes) ->\n    usable(State),\n    transmit(State#{out := Sequence + 1, used := true}, Sequence, <<0, Bytes/binary>>, Now).\nabandon(State = #{closed := true}, _) -> {State, []};\nabandon(State = #{moved := Moved}, _) when Moved =/= none -> {State, []};\nabandon(State = #{out := Sequence}, Now) ->\n    case maps:get(failure, State) of\n        none -> transmit(State#{out := Sequence + 1, closed := true}, Sequence, <<1>>, Now);\n        _ -> {State#{closed := true}, []}\n    end.\nusable(State) ->\n    case maps:get(eof, State) of true -> error({lawspec, channel_end_unavailable}); false -> ok end,\n    case {maps:get(failure, State), maps:get(closed, State), maps:get(token, State), maps:get(moved, State),\n            maps:get(taking, State), maps:get(taken, State)} of\n        {none, false, none, none, none, _} -> ok;\n        {none, false, none, none, _, true} -> ok;\n        _ -> error({lawspec, channel_end_unavailable})\n    end.\ntransmit(State = #{unacked := Unacked}, Sequence, Body, Now) ->\n    %% Constructing the canonical payload enforces the signed 64-bit range.\n    Frame = channel_frame(State, Sequence, Body),\n    S1 = State#{unacked := Unacked#{Sequence => #{body => Body, first => Now, last => Now}}},\n    {S1, case maps:get(peer, State) of none -> []; _ -> [Frame] end}.\nchannel_frame(State, Sequence, Body) ->\n    message(maps:get(peer, State), <<\"chan\">>, lawspec_beam_wire:channel(Sequence, maps:get(address, State), Body)).\nmessage(To, Kind, Payload) -> #{to => To, kind => Kind, payload => Payload}.\n\nreceive_body(State = #{token := Token, moved := Moved}) when Token =/= none; Moved =/= none ->\n    {{error, <<\"the channel end has been offered or moved\">>}, State};\nreceive_body(State = #{received := Received}) ->\n    case queue:out(Received) of\n        {{value, <<0, Body/binary>>}, Rest} -> {{value, Body}, State#{received := Rest, used := true}};\n        {{value, <<1>>}, _} ->\n            %% The peer's EOF ends this reader, not our outbound delivery.\n            %% In particular, our own EOF may still need retransmission.\n            {{error, eof_reason()}, State#{received := queue:new(), used := true, eof := true}};\n        {empty, _} ->\n            case {maps:get(eof, State), maps:get(failure, State)} of\n                {true, _} -> {{error, eof_reason()}, State};\n                {false, none} -> {empty, State};\n                {false, Reason} -> {{error, Reason}, State}\n            end\n    end.\neof_reason() -> <<\"the other end gave up the conversation\">>.\n\n%% Invalid control frames do not corrupt an end or crash its owner. The\n%% sender keeps retransmitting valid frames until they are acknowledged.\naccept(State, Frame, Now) ->\n    try arriving(State, Frame, Now) catch _:_ -> {State, []} end.\narriving(State, #{kind := <<\"take\">>, payload := Payload}, _) -> give(State, Payload);\narriving(State = #{moved := To}, Frame, _) when To =/= none ->\n    {State, [Frame#{to => To}]};\narriving(State = #{taking := Taking, taken := false}, Frame, Now) when Taking =/= none ->\n    case Frame of\n        #{kind := <<\"state\">>, payload := Payload} -> install(State, Payload, Now);\n        _ -> {State, []}\n    end;\narriving(State = #{failure := Failure}, #{kind := <<\"chan\">>}, _) when Failure =/= none -> {State, []};\narriving(State = #{unacked := Unacked}, #{kind := <<\"ack\">>, payload := Payload}, _) ->\n    Sequence = lawspec_beam_wire:read_sequence(Payload), {State#{unacked := maps:remove(Sequence, Unacked)}, []};\narriving(State, #{kind := <<\"moved\">>, payload := Payload}, _) -> peer_moved(State, Payload);\narriving(State, #{kind := <<\"moved-ack\">>, payload := Payload}, _) ->\n    {[Address], <<>>} = lawspec_beam_wire:read_fields([text_type()], Payload, #{}),\n    case maps:get(address, State) of Address -> {State#{confirmed := true}, []}; _ -> {State, []} end;\narriving(State, #{kind := <<\"chan\">>, payload := Payload}, _) ->\n    {Sequence, Sender, Body} = lawspec_beam_wire:read_channel(Payload),\n    _ = lawspec_beam_wire:split_address(Sender),\n    Updated = case Sequence of\n        -1 ->\n            <<\"hello\">> = Body,\n            case maps:get(peer, State) of none -> State#{peer := Sender}; _ -> State end;\n        _ when Sequence >= 0 ->\n            true = valid_body(Body),\n            Expected = maps:get(expected, State), Early = maps:get(early, State),\n            true = not maps:get(eof, State) orelse Sequence < Expected,\n            case Sequence >= Expected andalso not maps:is_key(Sequence, Early) of\n                true -> drain(State#{early := Early#{Sequence => Body}});\n                false -> State\n            end\n    end,\n    {Updated, [message(Sender, <<\"ack\">>, lawspec_beam_wire:sequence(Sequence))]};\narriving(State, _, _) -> {State, []}.\nvalid_body(<<0, _/binary>>) -> true;\nvalid_body(<<1>>) -> true;\nvalid_body(_) -> false.\ndrain(State = #{expected := Expected, early := Early, received := Received}) ->\n    case maps:take(Expected, Early) of\n        error -> State;\n        {Body, Rest} -> drain(State#{expected := Expected + 1, early := Rest, received := queue:in(Body, Received)})\n    end.\n\ntick(State = #{moved := Moved}, _) when Moved =/= none -> {State, []};\ntick(State = #{failure := Failure}, _) when Failure =/= none -> {State, []};\ntick(State = #{taking := Taking, taken := false}, Now) when Taking =/= none ->\n    #{first := First, last := Last, address := Old, token := Token} = Taking,\n    case Now - First >= maps:get(deadline, State) of\n        true -> {fail(take_failure(), State), []};\n        false when Now - Last > ?RETRY ->\n            Payload = lawspec_beam_wire:fields([text_type(), text_type()], [Token, maps:get(address, State)], #{}),\n            {State#{taking := Taking#{last := Now}}, [message(Old, <<\"take\">>, Payload)]};\n        false -> {State, []}\n    end;\ntick(State = #{unacked := Unacked, peer := Peer}, Now) ->\n    Due = [{N, E} || {N, E = #{last := Last}} <- lists:sort(maps:to_list(Unacked)), Now - Last > ?RETRY],\n    Stale = lists:any(fun({_, #{first := First}}) -> Now - First > maps:get(deadline, State) end, Due),\n    case Stale of\n        true -> {fail(<<\"the other end did not answer in time (unreachable)\">>, State), []};\n        false when Peer =:= none -> {State, []};\n        false ->\n            {S1, Announce} = announce(State, Now),\n            Frames = [channel_frame(S1, N, maps:get(body, E)) || {N, E} <- Due],\n            Updated = lists:foldl(fun({N, E}, Acc) -> Acc#{N := E#{last := Now}} end, Unacked, Due),\n            {S1#{unacked := Updated}, Announce ++ Frames}\n    end.\nannounce(State = #{announcing := true, confirmed := false, announced_at := Last}, Now)\n        when Last =:= none; Now - Last > ?RETRY ->\n    Payload = lawspec_beam_wire:fields([[<<\"list\">>, text_type()], text_type()],\n        [maps:get(history, State), maps:get(address, State)], #{}),\n    {State#{announced_at := Now}, [message(maps:get(peer, State), <<\"moved\">>, Payload)]};\nannounce(State, _) -> {State, []}.\nfail(Reason, State = #{failure := none}) -> State#{failure := Reason, unacked := #{}};\nfail(_, State) -> State.\n\noffer(State, Token) when is_binary(Token), byte_size(Token) > 0 ->\n    true = not maps:get(used, State), true = not maps:get(closed, State), true = maps:get(moved, State) =:= none,\n    true = maps:get(taking, State) =:= none orelse maps:get(taken, State),\n    Chosen = case maps:get(token, State) of none -> Token; Existing -> Existing end,\n    {<<(maps:get(address, State))/binary, \"?take=\", Chosen/binary>>, State#{token := Chosen}}.\ntake(State, Address, Now) ->\n    usable(State), true = not maps:get(used, State),\n    [Old, Token] = binary:split(Address, <<\"?take=\">>), true = byte_size(Token) > 0,\n    _ = lawspec_beam_wire:split_address(Old),\n    tick(State#{taking := #{address => Old, token => Token, first => Now, last => Now - ?RETRY - 1}}, Now).\ntake_status(#{taking := none}, _) -> ready;\ntake_status(State = #{taking := #{first := First}, taken := Taken}, Now) ->\n    case Taken of\n        true -> case maps:get(confirmed, State) orelse maps:get(failure, State) =/= none orelse Now - First >= maps:get(deadline, State) of\n            true -> ready; false -> waiting end;\n        false -> case maps:get(failure, State) =/= none orelse Now - First >= maps:get(deadline, State) of\n            true -> {error, take_failure()}; false -> waiting end\n    end.\ntake_failure() -> <<\"the node the end came from did not hand it over in time (unreachable)\">>.\n\ngive(State, Payload) ->\n    {[Token, Taker], <<>>} = lawspec_beam_wire:read_fields([text_type(), text_type()], Payload, #{}),\n    _ = lawspec_beam_wire:split_address(Taker),\n    case maps:get(token, State) =:= Token andalso Token =/= none of\n        false -> {State, []};\n        true -> case maps:get(moved, State) of\n            none ->\n                Snapshot = snapshot(State),\n                {State#{moved := Taker, snapshot := Snapshot, unacked := #{}, early := #{}},\n                    [message(Taker, <<\"state\">>, Snapshot)]};\n            Taker -> {State, [message(Taker, <<\"state\">>, maps:get(snapshot, State))]};\n            _ -> {State, []}\n        end\n    end.\nsnapshot(State) ->\n    Prefix = lawspec_beam_wire:fields([text_type(), text_type(), text_type(), [<<\"list\">>, text_type()], seq_type(), seq_type()],\n        [maps:get(token, State), empty(maps:get(failure, State)), empty(maps:get(peer, State)),\n         maps:get(history, State) ++ [maps:get(address, State)], maps:get(out, State), maps:get(expected, State)], #{}),\n    Unacked = [{N, maps:get(body, E)} || {N, E} <- lists:sort(maps:to_list(maps:get(unacked, State)))],\n    Early = lists:sort(maps:to_list(maps:get(early, State))),\n    Received = lawspec_beam_values:encode([<<\"list\">>, bytes_type()], queue:to_list(maps:get(received, State)), #{}),\n    iolist_to_binary([Prefix, numbered(Unacked), numbered(Early), Received]).\nnumbered(Entries) -> [lawspec_beam_values:varint(length(Entries)),\n    [lawspec_beam_wire:fields([seq_type(), bytes_type()], [N, Body], #{}) || {N, Body} <- Entries]].\nread_numbered(Bytes) ->\n    {Count, Rest} = lawspec_beam_values:read_varint(Bytes), true = Count =< byte_size(Rest) div 2,\n    lists:mapfoldl(fun(_, B) ->\n        {[N, Body], After} = lawspec_beam_wire:read_fields([seq_type(), bytes_type()], B, #{}), {{N, Body}, After}\n    end, Rest, lists:seq(1, Count)).\nread_binaries(Type, Bytes) ->\n    {Count, Rest} = lawspec_beam_values:read_varint(Bytes), true = Count =< byte_size(Rest),\n    lists:mapfoldl(fun(_, B) -> lawspec_beam_values:decode_prefix(Type, B, #{}) end, Rest, lists:seq(1, Count)).\ninstall(State = #{taking := #{token := Token, address := Old}}, Payload, Now) ->\n    {[Token, Failure, Peer], R1} = lawspec_beam_wire:read_fields([text_type(), text_type(), text_type()], Payload, #{}),\n    {History, R2} = read_binaries(text_type(), R1),\n    Old = lists:last(History),\n    lists:foreach(fun lawspec_beam_wire:split_address/1, History),\n    case Peer of <<>> -> ok; _ -> lawspec_beam_wire:split_address(Peer) end,\n    {[Out, Expected], R3} = lawspec_beam_wire:read_fields([seq_type(), seq_type()], R2, #{}),\n    true = Out >= 0 andalso Expected >= 0,\n    {Unacked, R4} = read_numbered(R3), {Early, R5} = read_numbered(R4),\n    {Received, <<>>} = read_binaries(bytes_type(), R5),\n    true = lists:all(fun valid_body/1, Received),\n    true = lists:all(fun({N, B}) -> N >= Expected andalso valid_body(B) end, Early),\n    true = lists:all(fun({N, B}) -> (N =:= -1 andalso B =:= <<\"hello\">>) orelse (N >= 0 andalso N < Out andalso valid_body(B)) end, Unacked),\n    true = map_size(maps:from_list(Unacked)) =:= length(Unacked),\n    true = map_size(maps:from_list(Early)) =:= length(Early),\n    Pend = maps:from_list([{N, #{body => B, first => Now, last => Now - ?RETRY - 1}} || {N, B} <- Unacked]),\n    S1 = State#{peer := optional(Peer), history := History, out := Out, expected := Expected,\n        unacked := Pend, early := maps:from_list(Early), received := queue:from_list(Received),\n        announcing := true, announced_at := none, taken := true},\n    case Failure of <<>> -> tick(drain(S1), Now); _ -> {fail(Failure, S1), []} end.\npeer_moved(State, Payload) ->\n    {History, Rest} = read_binaries(text_type(), Payload),\n    {[To], <<>>} = lawspec_beam_wire:read_fields([text_type()], Rest, #{}),\n    _ = lawspec_beam_wire:split_address(To),\n    Peer = maps:get(peer, State),\n    S1 = case Peer =:= none orelse lists:member(Peer, History) of true -> State#{peer := To}; false -> State end,\n    case maps:get(peer, S1) of\n        To -> {S1, [message(To, <<\"moved-ack\">>, lawspec_beam_values:encode(text_type(), To, #{}))]};\n        _ -> {S1, []}\n    end.\nempty(none) -> <<>>;\nempty(Value) -> Value.\noptional(<<>>) -> none;\noptional(Value) -> Value.\ntext_type() -> [<<\"text\">>].\nbytes_type() -> [<<\"bytes\">>].\nseq_type() -> [<<\"int\">>, <<\"Int64\">>, -16#8000000000000000, 16#7fffffffffffffff].\n"
runtimeSource "beam-node" = "%% @doc Named frame routing and reliable request/reply over a transport.\n%% Requests are deduplicated by sender and identity, including while their\n%% handler is running. Application handlers run in owned, cancellable tasks.\n%% ref:DEC-distribution-canonical-wire ref:DEC-async-native-tasks\n-module(lawspec_beam_node).\n-behaviour(gen_server).\n-export([start/1, start/2, start_owned/2, with_node/3, stop/1, address/1,\n    register_handler/3, register_receiver/3, register_service/2, unregister/2, send/4, forward/2,\n    request/5, request_async/5, cancel/2, reply/5]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2]).\n\nstart(Transport) -> start(Transport, #{}).\nstart(Transport, Options) -> start_as(none, Transport, Options).\nstart_owned(Transport, Options) -> start_as(self(), Transport, Options).\nwith_node(Transport, Options, Body) ->\n    {ok, Node} = start_owned(Transport, Options), try Body(Node) after stop(Node) end.\nstart_as(Owner, Transport, Options) ->\n    %% Ordinary transports must acquire the secure layer before they can\n    %% carry frames. Until that layer is connected, only the explicit test\n    %% memory transport is usable; there is no cleartext fallback.\n    case Transport of\n        #{module := lawspec_beam_memory_network, insecure_for_tests := true} ->\n            %% A replacement client may reuse its address while a peer still\n            %% caches old replies. Its request stream must not restart at 1.\n            <<Random:64/unsigned>> = crypto:strong_rand_bytes(8),\n            First = maps:get(first_id, Options, (Random band ((1 bsl 61) - 1)) + 1),\n            case is_integer(First) andalso First > 0 andalso First =< 16#ffffffffffffffff of\n                true -> gen_server:start(?MODULE, {Owner, Transport, Options#{first_id => First}}, []);\n                false -> {error, invalid_request_identity}\n            end;\n        _ -> {error, secure_network_not_available}\n    end.\nstop(Node) ->\n    try gen_server:stop(Node, normal, infinity)\n    catch exit:noproc -> ok; exit:{noproc, _} -> ok end.\naddress(Node) -> call(Node, address).\nregister_handler(Node, Name, Handler) when is_function(Handler, 1) ->\n    Context = lists:keydelete({lawspec_beam_tasks, scopes}, 1, lawspec_beam_runtime:worker_context()),\n    call(Node, {register, Name, {handler, Handler, Context}}).\nregister_receiver(Node, Name, Receiver) when is_pid(Receiver) -> call(Node, {register, Name, {receiver, Receiver}}).\n%% Internal endpoint services belong to the node's cancellation scope.\n%% Ordinary receivers remain owned by their application.\nregister_service(Node, Name) -> call(Node, {register, Name, {service, self()}}).\nunregister(Node, Name) -> call(Node, {unregister, Name}).\nsend(Node, Address, Kind, Payload) -> call(Node, {send, #{to => Address, kind => Kind, payload => Payload}}).\nforward(Node, Frame) -> call(Node, {send, Frame}).\nrequest(Node, Address, Kind, Payload, Timeout) -> call(Node, {request, sync, Address, Kind, Payload, Timeout}).\n%% The caller receives {lawspec_reply, Node, Ticket, {ok, {Status, Bytes}}}\n%% or {error, Reason}. The wire identity lets scenario clocks follow exactly\n%% their own mailbox request, even when distinct requests overtake each other.\nrequest_async(Node, Address, Kind, Payload, Timeout) -> call(Node, {request, async, Address, Kind, Payload, Timeout}).\ncancel(Node, Ticket) -> call(Node, {cancel, Ticket}).\nreply(Node, Source, Identity, Status, Body) -> call(Node, {reply, Source, Identity, Status, Body}).\ncall(Node, Request) ->\n    Result = try gen_server:call(Node, Request, infinity)\n        catch exit:{_, {gen_server, call, [Node, _, infinity]}} -> {error, node_closed} end,\n    case Result of\n        {ok, Value} -> Value;\n        {error, Reason} -> error({lawspec, {network, Reason}})\n    end.\n\ninit({Owner, Transport = #{network := Network, address := Address}, Options}) ->\n    case lawspec_beam_memory_network:register(Network, Address, self()) of\n        {error, Reason} -> {stop, {transport_registration, Reason}};\n        ok ->\n            Scope = lawspec_beam_tasks:open(),\n            {ok, #{transport => Transport, address => Address, options => Options,\n                owner => case Owner of none -> none; _ -> monitor(process, Owner) end,\n                network_monitor => monitor(process, Network), scope => Scope, scope_monitor => monitor(process, Scope),\n                entities => #{}, entity_monitors => #{}, pending => #{}, pending_monitors => #{},\n                seen => #{}, jobs => #{}, next_id => maps:get(first_id, Options)}}\n    end.\nhandle_call(Request, From, State) ->\n    try local(Request, From, State) catch\n        throw:{invalid, Reason} -> {reply, {error, Reason}, State}\n    end.\nhandle_cast(_, State) -> {noreply, State}.\nhandle_info({lawspec_network, Network, _, Bytes}, State = #{transport := #{network := Network}}) ->\n    case lawspec_beam_wire:read_frame(Bytes) of\n        {ok, Frame} -> {noreply, arrive(Frame, State)};\n        {error, _} -> {noreply, State}\n    end;\nhandle_info({retry, Identity, Ticket}, State = #{pending := Pending}) ->\n    case maps:find(Identity, Pending) of\n        {ok, P = #{ticket := Ticket, deadline := Deadline}} ->\n            Now = erlang:monotonic_time(millisecond),\n            case Now >= Deadline of\n                true -> {noreply, finish(Identity, {error, {unreachable, maps:get(address, P)}}, State)};\n                false ->\n                    _ = transmit(maps:get(frame, P), State),\n                    Timer = erlang:send_after(min(100, Deadline - Now), self(), {retry, Identity, Ticket}),\n                    {noreply, State#{pending := Pending#{Identity := P#{timer := Timer}}}}\n            end;\n        _ -> {noreply, State}\n    end;\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{owner := Monitor}) -> {stop, normal, State};\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{network_monitor := Monitor}) -> {stop, normal, State};\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{scope_monitor := Monitor}) -> {stop, normal, State};\nhandle_info({'DOWN', Monitor, process, _, Reason}, State = #{jobs := Jobs}) ->\n    case maps:take(Monitor, Jobs) of\n        {Job, Rest} ->\n            Outcome = case Reason of\n                {lawspec_network_result, Status, Body} -> {Status, Body};\n                _ -> {1, printable({handler_exited, Reason})}\n            end,\n            {noreply, answer_job(Job, Outcome, State#{jobs := Rest})};\n        error -> {noreply, monitor_down(Monitor, State)}\n    end;\nhandle_info(_, State) -> {noreply, State}.\nterminate(_, State) ->\n    maps:foreach(fun(_, P) ->\n        erlang:cancel_timer(maps:get(timer, P)), respond(P, {error, node_closed})\n    end, maps:get(pending, State)),\n    %% The scope also performs this cleanup if this server is killed before\n    %% terminate/2 can run. close/1 joins every registered descendant.\n    lawspec_beam_tasks:close(maps:get(scope, State)),\n    #{network := Network, address := Address} = maps:get(transport, State),\n    try lawspec_beam_memory_network:unregister(Network, Address) catch exit:_ -> ok end,\n    ok.\n\nlocal(address, _, State) -> {reply, {ok, maps:get(address, State)}, State};\nlocal({register, Name, Entity}, _, Previous) ->\n    require(is_binary(Name) andalso byte_size(Name) > 0 andalso binary:match(Name, <<\"/\">>) =:= nomatch, invalid_entity_name),\n    %% A replacement may arrive before the receiver's DOWN notification.\n    State = prune_entity(Name, Previous),\n    #{entities := Entities, entity_monitors := Monitors} = State,\n    require(not maps:is_key(Name, Entities), {already_registered, Name}),\n    {Stored, UpdatedMonitors} = case Entity of\n        {service, Pid} ->\n            ok = lawspec_beam_tasks:adopt(maps:get(scope, State), Pid),\n            M = monitor(process, Pid), {{receiver, Pid, M}, Monitors#{M => Name}};\n        {receiver, Pid} ->\n            M = monitor(process, Pid), {{receiver, Pid, M}, Monitors#{M => Name}};\n        _ -> {Entity, Monitors}\n    end,\n    {reply, {ok, <<(maps:get(address, State))/binary, \"/\", Name/binary>>},\n        State#{entities := Entities#{Name => Stored}, entity_monitors := UpdatedMonitors}};\nlocal({unregister, Name}, _, State) -> {reply, {ok, ok}, remove_entity(Name, State)};\nlocal({send, Frame}, _, State) ->\n    validate_frame(Frame),\n    {reply, {ok, transmit(Frame, State)}, State};\nlocal({request, Mode, Address, Kind, Payload, Timeout}, From = {Caller, _}, State = #{next_id := Identity, pending := Pending, pending_monitors := Monitors}) ->\n    require(is_integer(Timeout) andalso Timeout >= 0, invalid_timeout),\n    require(Identity =< 16#ffffffffffffffff, request_identity_exhausted),\n    Frame = #{to => Address, kind => Kind, payload => Payload, id => Identity}, validate_frame(Frame),\n    {Peer, _} = lawspec_beam_wire:split_address(Address),\n    Ticket = make_ref(), Monitor = monitor(process, Caller),\n    Timer = erlang:send_after(min(100, Timeout), self(), {retry, Identity, Ticket}),\n    Delivery = case Mode of sync -> {sync, From}; async -> {async, Caller, self(), Ticket} end,\n    P = #{address => Address, peer => Peer, frame => Frame, ticket => Ticket, caller => Caller, monitor => Monitor,\n        timer => Timer, deadline => erlang:monotonic_time(millisecond) + Timeout, delivery => Delivery},\n    _ = transmit(Frame, State),\n    Next = State#{pending := Pending#{Identity => P}, pending_monitors := Monitors#{Monitor => Identity}, next_id := Identity + 1},\n    case Mode of sync -> {noreply, Next}; async -> {reply, {ok, {Ticket, Identity}}, Next} end;\nlocal({cancel, Ticket}, {Caller, _}, State = #{pending := Pending}) ->\n    Matches = [I || {I, #{ticket := T, caller := C}} <- maps:to_list(Pending), T =:= Ticket, C =:= Caller],\n    {reply, {ok, ok}, lists:foldl(fun(I, S) -> finish(I, cancelled, S) end, State, Matches)};\nlocal({reply, Source, Identity, Status, Body}, {Caller, _}, State = #{seen := Seen}) ->\n    validate_reply(Status, Body),\n    Key = {Source, Identity},\n    case maps:find(Key, Seen) of\n        {ok, #{owner := Caller, response := pending}} -> {reply, {ok, ok}, answer(Key, Status, Body, State)};\n        {ok, #{owner := Caller}} -> {reply, {ok, ok}, State};\n        _ when Identity =:= 0 -> {reply, {ok, ok}, State};\n        _ -> {reply, {error, not_request_owner}, State}\n    end.\nrequire(true, _) -> ok;\nrequire(false, Reason) -> throw({invalid, Reason}).\nvalidate_reply(Status, Body) -> require(is_integer(Status) andalso Status >= 0 andalso Status =< 255 andalso is_binary(Body), invalid_reply).\nvalidate_frame(Frame) ->\n    try\n        {_, _} = lawspec_beam_wire:split_address(maps:get(to, Frame)),\n        _ = lawspec_beam_wire:frame(maps:get(kind, Frame), <<>>, maps:get(source, Frame, <<>>),\n            maps:get(id, Frame, 0), maps:get(payload, Frame)), ok\n    catch _:_ -> throw({invalid, invalid_frame}) end.\ntransmit(Frame, State = #{transport := #{network := Network, address := Address}}) ->\n    {Peer, Name} = lawspec_beam_wire:split_address(maps:get(to, Frame)),\n    Bytes = lawspec_beam_wire:frame(maps:get(kind, Frame), Name, maps:get(source, Frame, maps:get(address, State)),\n        maps:get(id, Frame, 0), maps:get(payload, Frame)),\n    try lawspec_beam_memory_network:send(Network, Address, Peer, Bytes)\n    catch exit:_ -> {error, transport_closed} end.\n\narrive(#{kind := <<\"reply\">>, id := Identity, source := Source, payload := <<Status, Body/binary>>}, State = #{pending := Pending}) ->\n    case maps:find(Identity, Pending) of\n        {ok, #{peer := Source}} -> finish(Identity, {ok, {Status, Body}}, State);\n        _ -> State\n    end;\narrive(#{kind := <<\"reply\">>}, State) -> State;\narrive(Frame = #{to := Name, source := Source, id := Identity}, State = #{seen := Seen}) ->\n    Key = {Source, Identity},\n    case maps:find(Key, Seen) of\n        {ok, #{response := Response, fingerprint := Fingerprint}} when Identity =/= 0 ->\n            case fingerprint(Frame) =:= Fingerprint of\n                false -> send_reply(Source, Identity, <<3, \"a request identity was reused for different content\">>, State);\n                true -> case Response of pending -> ok; _ -> send_reply(Source, Identity, Response, State) end\n            end,\n            State;\n        _ -> dispatch(Name, Key, Frame, State)\n    end.\ndispatch(Name, Key = {Source, Identity}, Frame, State = #{entities := Entities, seen := Seen}) ->\n    case maps:find(Name, Entities) of\n        error ->\n            case Identity of\n                0 -> State;\n                _ ->\n                    Entry = #{owner => none, entity => Name, response => pending, fingerprint => fingerprint(Frame)},\n                    answer(Key, 3, <<\"nothing is registered as \", Name/binary>>, State#{seen := Seen#{Key => Entry}})\n            end;\n        {ok, {receiver, Pid, _}} ->\n            Pid ! {lawspec_frame, self(), Frame},\n            case Identity of\n                0 -> State;\n                _ -> State#{seen := Seen#{Key => #{owner => Pid, entity => Name, response => pending, fingerprint => fingerprint(Frame)}}}\n            end;\n        {ok, {handler, Handler, Context}} ->\n            Scope = maps:get(scope, State),\n            WorkerContext = [{{lawspec_beam_tasks, scopes}, [Scope]} | Context],\n            {Pid, Monitor} = spawn_monitor(fun() ->\n                {Status, Body} = try lawspec_beam_runtime:with_worker_context(WorkerContext, fun() ->\n                    lawspec_beam_tasks:with_scope(fun(_) ->\n                        {Code, Bytes} = Handler(Frame), validate_reply(Code, Bytes), {Code, Bytes}\n                    end)\n                end) catch Class:Reason -> {1, printable({Class, Reason})} end,\n                exit({lawspec_network_result, Status, Body})\n            end),\n            Jobs = maps:get(jobs, State),\n            S1 = State#{jobs := Jobs#{Monitor => #{pid => Pid, key => Key}}},\n            case Identity of\n                0 -> S1;\n                _ -> S1#{seen := Seen#{Key => #{owner => Pid, entity => Name, response => pending, source => Source,\n                    fingerprint => fingerprint(Frame)}}}\n            end\n    end.\nanswer_job(#{key := {_, 0}}, _, State) -> State;\nanswer_job(#{key := Key, pid := Pid}, {Status, Body}, State = #{seen := Seen}) ->\n    case maps:find(Key, Seen) of\n        {ok, #{owner := Pid, response := pending}} -> answer(Key, Status, Body, State);\n        _ -> State\n    end.\nanswer(Key = {Source, Identity}, Status, Body, State = #{seen := Seen}) ->\n    Entry = maps:get(Key, Seen), Payload = <<Status, Body/binary>>,\n    send_reply(Source, Identity, Payload, State), State#{seen := Seen#{Key := Entry#{response := Payload}}}.\nsend_reply(Source, Identity, Payload, State) ->\n    %% A frame source is untrusted input even on the test-only transport.\n    Frame = #{to => <<Source/binary, \"/\">>, kind => <<\"reply\">>, id => Identity, payload => Payload},\n    try validate_frame(Frame), transmit(Frame, State) catch _:_ -> ok end.\nfinish(Identity, Result, State = #{pending := Pending, pending_monitors := Monitors}) ->\n    case maps:take(Identity, Pending) of\n        error -> State;\n        {P = #{monitor := Monitor, timer := Timer}, Rest} ->\n            erlang:cancel_timer(Timer), demonitor(Monitor, [flush]),\n            case Result of cancelled -> ok; _ -> respond(P, Result) end,\n            State#{pending := Rest, pending_monitors := maps:remove(Monitor, Monitors)}\n    end.\nrespond(#{delivery := {sync, From}}, Result) -> gen_server:reply(From, Result);\nrespond(#{delivery := {async, Caller, Node, Ticket}}, Result) -> Caller ! {lawspec_reply, Node, Ticket, Result}.\nmonitor_down(Monitor, State = #{pending_monitors := Pending, entity_monitors := Entities}) ->\n    case maps:find(Monitor, Pending) of\n        {ok, Identity} -> finish(Identity, cancelled, State);\n        error -> case maps:find(Monitor, Entities) of\n            {ok, Name} -> remove_entity(Name, State);\n            error -> State\n        end\n    end.\nremove_entity(Name, State = #{entities := Entities, entity_monitors := Monitors, seen := Seen}) ->\n    case maps:take(Name, Entities) of\n        error -> State;\n        {Entity, Rest} ->\n            Ms = case Entity of\n                {receiver, _, M} -> demonitor(M, [flush]), maps:remove(M, Monitors);\n                _ -> Monitors\n            end,\n            S1 = State#{entities := Rest, entity_monitors := Ms},\n            lists:foldl(fun(Key, S) -> answer(Key, 2, <<\"the receiving entity has stopped\">>, S) end, S1,\n                [K || {K, #{entity := N, response := pending}} <- maps:to_list(Seen), N =:= Name])\n    end.\nprune_entity(Name, State = #{entities := Entities}) ->\n    case maps:find(Name, Entities) of\n        {ok, {receiver, Pid, _}} when node(Pid) =:= node() ->\n            case is_process_alive(Pid) of true -> State; false -> remove_entity(Name, State) end;\n        _ -> State\n    end.\nprintable(Term) -> unicode:characters_to_binary(io_lib:format(\"~tp\", [Term])).\nfingerprint(#{kind := Kind, to := To, source := Source, id := Identity, payload := Payload}) ->\n    crypto:hash(sha256, lawspec_beam_wire:frame(Kind, To, Source, Identity, Payload)).\n"
runtimeSource "beam-endpoint" = "%% @doc A node owns each reliable channel end, its retry timer and pending\n%% readers. Abandonment is an ordered frame; it keeps retrying after the\n%% application leaves. Moving an unused end transfers its protocol state.\n%% ref:DEC-distribution-canonical-wire ref:DEC-sessions-by-construction\n-module(lawspec_beam_endpoint).\n-behaviour(gen_server).\n-export([start/3, stop/1, address/1, connect/2, send/2, abandon/1,\n    receive_body/2, receive_async/2, cancel/2, offer/1, take/2]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2]).\n\nstart(Node, Name, Options) -> gen_server:start(?MODULE, {Node, Name, Options}, []).\n%% stop/1 destroys the service. Normal conversation cleanup uses abandon/1\n%% so accepted sends and EOF can still be acknowledged by the peer.\nstop(End) ->\n    try gen_server:stop(End, normal, infinity)\n    catch exit:noproc -> ok; exit:{noproc, _} -> ok end.\naddress(End) -> call(End, address).\nconnect(End, Peer) -> call(End, {connect, Peer}).\nsend(End, Bytes) -> call(End, {send, Bytes}).\nabandon(End) -> call(End, abandon).\nreceive_body(End, Timeout) -> call(End, {'receive', sync, Timeout}).\n%% Delivers {lawspec_channel, End, Ticket, {value, Bytes} | {error, Reason}}.\nreceive_async(End, Timeout) -> call(End, {'receive', async, Timeout}).\ncancel(End, Ticket) -> call(End, {cancel, Ticket}).\noffer(End) -> call(End, offer).\ntake(End, Address) -> call(End, {take, Address}).\ncall(End, Request) ->\n    Result = try gen_server:call(End, Request, infinity)\n        catch exit:{_, {gen_server, call, [End, _, infinity]}} -> {error, endpoint_closed} end,\n    case Result of {ok, Value} -> Value; {error, Reason} -> error({lawspec, {channel, Reason}}) end.\n\ninit({Node, Name, Options}) ->\n    Deadline = maps:get(deadline, Options, 5000),\n    case is_integer(Deadline) andalso Deadline > 0 of\n        false -> {stop, invalid_deadline};\n        true ->\n            Address = lawspec_beam_node:register_service(Node, Name),\n            {ok, #{node => Node, name => Name, node_monitor => monitor(process, Node),\n                protocol => lawspec_beam_channel_protocol:new(Address, Deadline * 1000),\n                reader => none, taking => none, timer => none}}\n    end.\nhandle_call(Request, From, State) ->\n    try local(Request, From, State) catch\n        throw:{invalid, Reason} -> {reply, {error, Reason}, State};\n        error:{lawspec, Reason} -> {reply, {error, Reason}, State};\n        error:{badmatch, _} -> {reply, {error, invalid_operation}, State};\n        error:badarg -> {reply, {error, invalid_operation}, State}\n    end.\nhandle_cast(_, State) -> {noreply, State}.\nhandle_info({lawspec_frame, Node, Frame}, State = #{node := Node, protocol := Protocol}) ->\n    {noreply, update(lawspec_beam_channel_protocol:accept(Protocol, Frame, now_us()), State)};\nhandle_info({tick, Ref}, State = #{timer := {Ref, _}, protocol := Protocol}) ->\n    {noreply, update(lawspec_beam_channel_protocol:tick(Protocol, now_us()), State#{timer := none})};\nhandle_info({read_timeout, Ticket}, State = #{reader := #{ticket := Ticket}}) ->\n    {noreply, finish(reader, {error, receive_timeout}, State)};\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{node_monitor := Monitor}) -> {stop, normal, State};\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{reader := #{monitor := Monitor}}) ->\n    {noreply, finish(reader, cancelled, State)};\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{taking := #{monitor := Monitor}}) ->\n    {noreply, finish(taking, cancelled, State)};\nhandle_info(_, State) -> {noreply, State}.\nterminate(_, State) ->\n    cancel_timer(maps:get(timer, State)),\n    _ = finish(reader, {error, endpoint_closed}, finish(taking, {error, endpoint_closed}, State)),\n    try lawspec_beam_node:unregister(maps:get(node, State), maps:get(name, State)) catch _:_ -> ok end,\n    ok.\n\nlocal(address, _, State) -> {reply, {ok, maps:get(address, maps:get(protocol, State))}, State};\nlocal({connect, Peer}, _, State = #{protocol := Protocol}) ->\n    require(is_binary(Peer), invalid_address), idle_take(State),\n    Next = lawspec_beam_channel_protocol:connect(Protocol, Peer, now_us()),\n    {reply, {ok, ok}, update(Next, State)};\nlocal({send, Bytes}, _, State = #{protocol := Protocol}) ->\n    require(is_binary(Bytes), invalid_payload), idle_take(State),\n    {reply, {ok, ok}, update(lawspec_beam_channel_protocol:send(Protocol, Bytes, now_us()), State)};\nlocal(abandon, _, State = #{protocol := Protocol}) ->\n    {reply, {ok, ok}, update(lawspec_beam_channel_protocol:abandon(Protocol, now_us()), State)};\nlocal({'receive', Mode, Timeout}, From, State) ->\n    idle_take(State), require(maps:get(reader, State) =:= none, already_receiving),\n    require(Timeout =:= infinity orelse (is_integer(Timeout) andalso Timeout >= 0 andalso Timeout =< 16#ffffffff), invalid_timeout),\n    Waiter = waiting(Mode, From, Timeout),\n    Next = wake(State#{reader := Waiter}),\n    case Mode of\n        sync -> {noreply, Next};\n        async -> {reply, {ok, maps:get(ticket, Waiter)}, Next}\n    end;\nlocal({cancel, Ticket}, {Caller, _}, State) ->\n    Next = case maps:get(reader, State) of\n        #{ticket := Ticket, caller := Caller} -> finish(reader, cancelled, State);\n        _ -> State\n    end,\n    {reply, {ok, ok}, Next};\nlocal(offer, _, State = #{protocol := Protocol}) ->\n    idle_take(State), require(maps:get(reader, State) =:= none, already_receiving),\n    Token = binary:encode_hex(crypto:strong_rand_bytes(24)),\n    {Address, Next} = lawspec_beam_channel_protocol:offer(Protocol, Token),\n    {reply, {ok, Address}, State#{protocol := Next}};\nlocal({take, Address}, From, State = #{protocol := Protocol}) ->\n    idle_take(State), require(maps:get(reader, State) =:= none, already_receiving),\n    require(maps:get(peer, Protocol) =:= none andalso maps:get(unacked, Protocol) =:= #{} andalso\n        maps:get(expected, Protocol) =:= 0 andalso maps:get(taking, Protocol) =:= none, end_not_fresh),\n    Next = lawspec_beam_channel_protocol:take(Protocol, Address, now_us()),\n    {noreply, update(Next, State#{taking := waiting(sync, From, infinity)})}.\nidle_take(State) -> require(maps:get(taking, State) =:= none, taking_in_progress).\nrequire(true, _) -> ok;\nrequire(false, Reason) -> throw({invalid, Reason}).\nnow_us() -> erlang:monotonic_time(microsecond).\n\nwaiting(Mode, From = {Caller, _}, Timeout) ->\n    Ticket = make_ref(),\n    Timer = case Timeout of infinity -> none; _ -> {Ticket, erlang:send_after(Timeout, self(), {read_timeout, Ticket})} end,\n    #{mode => Mode, from => From, caller => Caller, ticket => Ticket, monitor => monitor(process, Caller), timer => Timer}.\nfinish(Key, Result, State) ->\n    case maps:get(Key, State) of\n        none -> State;\n        W ->\n            cancel_timer(maps:get(timer, W)), demonitor(maps:get(monitor, W), [flush]),\n            case {Result, maps:get(mode, W)} of\n                {cancelled, _} -> ok;\n                {_, sync} when Key =:= reader -> gen_server:reply(maps:get(from, W), {ok, Result});\n                {_, sync} -> gen_server:reply(maps:get(from, W), Result);\n                {_, async} -> maps:get(caller, W) ! {lawspec_channel, self(), maps:get(ticket, W), Result}\n            end,\n            State#{Key := none}\n    end.\ncancel_timer(none) -> ok;\ncancel_timer({_, Timer}) -> erlang:cancel_timer(Timer), ok.\n\nupdate({Protocol, Frames}, State) ->\n    Node = maps:get(node, State),\n    lists:foreach(fun(Frame) -> _ = lawspec_beam_node:forward(Node, Frame) end, Frames),\n    schedule(wake(State#{protocol := Protocol})).\nwake(State = #{taking := Taking, protocol := Protocol}) when Taking =/= none ->\n    case lawspec_beam_channel_protocol:take_status(Protocol, now_us()) of\n        waiting -> State;\n        ready -> finish(taking, {ok, ok}, State);\n        {error, _} = Error -> finish(taking, Error, State)\n    end;\nwake(State = #{reader := Reader, protocol := Protocol}) when Reader =/= none ->\n    case lawspec_beam_channel_protocol:receive_body(Protocol) of\n        {empty, _} -> State;\n        {Result, Next} -> finish(reader, Result, State#{protocol := Next})\n    end;\nwake(State) -> State.\nschedule(State = #{timer := Timer, protocol := Protocol}) ->\n    Active = maps:get(failure, Protocol) =:= none andalso maps:get(moved, Protocol) =:= none andalso\n        (map_size(maps:get(unacked, Protocol)) > 0 orelse maps:get(taking, State) =/= none orelse\n         (maps:get(taking, Protocol) =/= none andalso not maps:get(taken, Protocol)) orelse\n         (maps:get(announcing, Protocol) andalso not maps:get(confirmed, Protocol) andalso maps:get(peer, Protocol) =/= none)),\n    case {Active, Timer} of\n        {true, none} ->\n            Ref = make_ref(), State#{timer := {Ref, erlang:send_after(10, self(), {tick, Ref})}};\n        {false, _} -> cancel_timer(Timer), State#{timer := none};\n        _ -> State\n    end.\n"
runtimeSource "beam-mailbox" = "%% @doc A typed mailbox stores logical values. Native conversion and Clock\n%% callbacks run in the caller; the queue never executes application code.\n%% Closing refuses new sends and lets accepted values drain. A served box\n%% belongs to its node; remote sends complete after once-only admission.\n%% ref:DEC-actors-otp-supervision ref:DEC-distribution-canonical-wire\n-module(lawspec_beam_mailbox).\n-behaviour(gen_server).\n-export([open/0, with_mailbox/1, stop/1, close/1, send/2, receive_value/1,\n    receive_within/2, receive_with_clock/3, serve/3, connect/4, send_remote/2, address/1]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2]).\n-export_type([mailbox/0, sender/0]).\n\n-opaque mailbox() :: pid().\n-opaque sender() :: {lawspec_mailbox_sender, pid(), binary(), map(), list(), pos_integer()}.\n\nopen() -> start(none, none).\nwith_mailbox(Body) ->\n    Box = start(self(), none), try Body(Box) after stop(Box) end.\nstart(Owner, Network) -> {ok, Box} = gen_server:start(?MODULE, {Owner, Network}, []), Box.\nstop(Box) ->\n    try gen_server:stop(Box, normal, infinity)\n    catch exit:noproc -> ok; exit:{noproc, _} -> ok; exit:{normal, _} -> ok end.\nclose(Box) ->\n    try call(Box, close) catch error:{lawspec, {mailbox, closed}} -> ok end.\nsend(Box, Value) -> call(Box, {send, Value}).\nreceive_value(Box) -> {value, Value} = call(Box, {'receive', infinity}), Value.\n\n%% Microseconds, matching LawSpec Duration and the native workflow API.\nreceive_within(Box, Micros) when is_integer(Micros) ->\n    maybe_value(call(Box, {'receive', erlang:monotonic_time(microsecond) + max(0, Micros)}));\nreceive_within(_, _) -> fail(invalid_duration).\nmaybe_value(timeout) -> {ls_data, <<\"Maybe::Nothing\">>, []};\nmaybe_value({value, Value}) -> {ls_data, <<\"Maybe::Just\">>, [Value]}.\n\nreceive_with_clock(Box, Micros, Schema) when is_integer(Micros) ->\n    Handler = lawspec_beam_effects:handler(Schema, <<\"lawspec.time::ability::Clock\">>),\n    case real_clock(Handler) of\n        true -> receive_within(Box, Micros);\n        false -> case call(Box, {'receive', erlang:monotonic_time(microsecond)}) of\n            {value, _} = Value -> maybe_value(Value);\n            timeout ->\n                _ = lawspec_beam_effects:invoke(Handler, Schema, <<\"sleep\">>,\n                    [{ls_data, <<\"lawspec.time::type::Duration::Duration\">>, [max(0, Micros)]}]),\n                maybe_value(timeout)\n        end\n    end;\nreceive_with_clock(_, _, _) -> fail(invalid_duration).\nreal_clock({lawspec_recording, _, Inner}) -> real_clock(Inner);\nreal_clock(Handler) -> Handler =:= lawspec_beam_defaults:handler(<<\"lawspec.time::ability::Clock\">>).\n\nserve(Node, Name, Descriptor) ->\n    {Table, Type} = lawspec_beam_values:from_text(Descriptor),\n    start(none, #{node => Node, name => Name, table => Table, type => Type}).\nconnect(Node, Address, Descriptor, Timeout) when is_pid(Node), is_binary(Address), is_integer(Timeout), Timeout > 0 ->\n    {Table, Type} = lawspec_beam_values:from_text(Descriptor),\n    {lawspec_mailbox_sender, Node, Address, Table, Type, Timeout};\nconnect(_, _, _, _) -> fail(invalid_sender).\nsend_remote({lawspec_mailbox_sender, Node, Address, Table, Type, Timeout}, Value) ->\n    Bytes = lawspec_beam_values:encode(Type, Value, Table),\n    case lawspec_beam_node:request(Node, Address, <<\"mail\">>, Bytes, Timeout) of\n        {0, <<>>} -> ok;\n        {2, _} -> fail(closed);\n        {Status, Body} -> fail({remote, Status, Body})\n    end.\naddress(Box) -> call(Box, address).\ncall(Box, Request) ->\n    Result = try gen_server:call(Box, Request, infinity)\n        catch exit:{_, {gen_server, call, [Box, _, infinity]}} -> {error, closed} end,\n    case Result of {ok, Value} -> Value; {error, Reason} -> fail(Reason) end.\nfail(Reason) -> error({lawspec, {mailbox, Reason}}).\n\ninit({Owner, Network}) ->\n    Network1 = case Network of\n        none -> none;\n        #{node := Node, name := Name} -> Network#{address => lawspec_beam_node:register_service(Node, Name),\n            monitor => monitor(process, Node)}\n    end,\n    {ok, #{queue => queue:new(), closed => false, reader => none, network => Network1,\n        owner => case Owner of none -> none; _ -> monitor(process, Owner) end}}.\nhandle_call(close, _, State) -> reply(ok, State#{closed := true});\nhandle_call({send, _}, _, State = #{closed := true}) -> {reply, {error, closed}, State};\nhandle_call({send, Value}, _, State) -> reply(ok, enqueue(Value, State));\nhandle_call(address, _, State = #{network := none}) -> {reply, {error, local_mailbox}, State};\nhandle_call(address, _, State = #{network := #{address := Address}}) -> {reply, {ok, Address}, State};\nhandle_call({'receive', Deadline}, From, State0) ->\n    State = prune(State0),\n    case maps:get(reader, State) of\n        none ->\n            {Caller, _} = From,\n            Reader = #{from => From, caller => Caller, monitor => monitor(process, Caller),\n                deadline => Deadline, token => make_ref(), timer => none},\n            finish(wake(State#{reader := Reader}));\n        _ -> {reply, {error, already_receiving}, State}\n    end;\nhandle_call(_, _, State) -> {reply, {error, invalid_operation}, State}.\nhandle_cast(_, State) -> {noreply, State}.\nhandle_info({read_timeout, Token}, State = #{reader := #{token := Token} = Reader}) ->\n    finish(wake(State#{reader := Reader#{timer := none}}));\nhandle_info({'DOWN', Ref, process, _, _}, State = #{owner := Ref}) -> {stop, normal, State};\nhandle_info({'DOWN', Ref, process, _, _}, State = #{network := #{monitor := Ref}}) -> {stop, normal, State};\nhandle_info({'DOWN', Ref, process, _, _}, State = #{reader := #{monitor := Ref}}) ->\n    finish(clear_reader(State));\nhandle_info({lawspec_frame, Node, Frame}, State = #{network := #{node := Node} = Network}) ->\n    {Status, Body, Next} = incoming(Frame, Network, prune(State)),\n    case maps:get(id, Frame) of\n        0 -> ok;\n        Identity -> ok = lawspec_beam_node:reply(Node, maps:get(source, Frame), Identity, Status, Body)\n    end,\n    finish(wake(Next));\nhandle_info(_, State) -> {noreply, State}.\nterminate(_, State) ->\n    _ = answer({error, closed}, State),\n    case maps:get(network, State) of\n        none -> ok;\n        #{node := Node, name := Name} -> try lawspec_beam_node:unregister(Node, Name) catch _:_ -> ok end\n    end.\n\nincoming(_, _, State = #{closed := true}) -> {2, <<\"the mailbox is closed\">>, State};\nincoming(#{kind := <<\"mail\">>, payload := Bytes}, #{table := Table, type := Type}, State) ->\n    try lawspec_beam_values:decode(Type, Bytes, Table) of\n        Value -> {0, <<>>, enqueue(Value, State)}\n    catch error:_ -> {3, <<\"not a message of this mailbox\">>, State} end;\nincoming(_, _, State) -> {3, <<\"not a mailbox request\">>, State}.\n\nenqueue(Value, State = #{queue := Queue}) -> State#{queue := queue:in(Value, Queue)}.\nprune(State = #{reader := none}) -> State;\nprune(State = #{reader := #{caller := Caller}}) ->\n    case is_process_alive(Caller) of true -> State; false -> clear_reader(State) end.\nreply(Value, State) ->\n    case finish(wake(prune(State))) of\n        {stop, Reason, Next} -> {stop, Reason, {ok, Value}, Next};\n        {noreply, Next} -> {reply, {ok, Value}, Next}\n    end.\nfinish(State = #{closed := true, queue := Queue, network := none}) ->\n    case queue:is_empty(Queue) of true -> {stop, normal, State}; false -> {noreply, State} end;\nfinish(State) -> {noreply, State}.\nwake(State = #{reader := none}) -> State;\nwake(State = #{queue := Queue, closed := Closed, reader := Reader}) ->\n    case queue:out(Queue) of\n        {{value, Value}, Rest} -> answer({ok, {value, Value}}, State#{queue := Rest});\n        {empty, _} when Closed -> answer({error, closed}, State);\n        {empty, _} ->\n            case maps:get(deadline, Reader) of\n                infinity -> State;\n                Deadline ->\n                    Left = Deadline - erlang:monotonic_time(microsecond),\n                    case Left =< 0 of\n                        true -> answer({ok, timeout}, State);\n                        false -> case maps:get(timer, Reader) of\n                            none ->\n                                Timer = erlang:send_after(min(16#ffffffff, (Left + 999) div 1000), self(),\n                                    {read_timeout, maps:get(token, Reader)}),\n                                State#{reader := Reader#{timer := Timer}};\n                            _ -> State\n                        end\n                    end\n            end\n    end.\nanswer(_, State = #{reader := none}) -> State;\nanswer(Result, State = #{reader := #{from := From}}) ->\n    gen_server:reply(From, Result), clear_reader(State).\nclear_reader(State = #{reader := none}) -> State;\nclear_reader(State = #{reader := Reader}) ->\n    demonitor(maps:get(monitor, Reader), [flush]),\n    case maps:get(timer, Reader) of none -> ok; Timer -> erlang:cancel_timer(Timer), ok end,\n    State#{reader := none}.\n"
runtimeSource "beam-gleam-network" = "// A node owns named services and their reliable transport requests.\n// ref:DEC-distribution-canonical-wire\npub type Node\n"
runtimeSource "beam-runtime" = "%% @doc Shared execution services for generated BEAM definitions and laws.\n%% Values stay in the portable domain until an explicit native boundary.\n%% ref:DEC-typed-core-boundary\n-module(lawspec_beam_runtime).\n-export([require/2, assert_equal/3, contextual/2, helper/4, concurrently/1, async_call/1,\n    worker_context/0, with_worker_context/2]).\n\n%% LawSpec's allocator, active handler operation, cancellation scopes and\n%% workflow runtime/frame cross workers. Application entries stay process-local.\nworker_context() -> [{Key, get(Key)} || Key <-\n    [{lawspec_beam_effects, scope}, {lawspec_beam_handler, context}, {lawspec_beam_tasks, scopes},\n     {lawspec_beam_workflow, runtime}, {lawspec_beam_workflow, frame}]].\n\nwith_worker_context(Context, Body) ->\n    Previous = [{Key, put(Key, Value)} || {Key, Value} <- Context],\n    try\n        case get({lawspec_beam_tasks, scopes}) of\n            undefined -> ok;\n            Scopes -> lawspec_beam_tasks:attach(Scopes)\n        end,\n        Body()\n    after\n        lists:foreach(fun({Key, undefined}) -> erase(Key); ({Key, Value}) -> put(Key, Value) end, Previous)\n    end.\n\nrequire(true, _) -> ok;\nrequire(false, Context) -> erlang:error({lawspec, {contract_failed, Context}});\nrequire(_, Context) -> erlang:error({lawspec, {non_boolean_contract, Context}}).\n\nassert_equal(Actual, Expected, Label) ->\n    case lawspec_beam_scalar:equal(Actual, Expected) of\n        true -> true;\n        false -> erlang:error({lawspec, {equation_failed, Label,\n            {actual, Actual}, {expected, Expected}}})\n    end.\n\ncontextual(Identity, Body) ->\n    try Body() catch\n        error:{lawspec, Reason}:Stack -> erlang:raise(error, {lawspec, {Identity, Reason}}, Stack)\n    end.\n\nhelper(<<\"unreachable\">>, _, _, _) -> erlang:error({lawspec, unreachable});\nhelper(Name, Values, Types, Bits) -> lawspec_beam_scalar:helper(Name, Values, Types, Bits).\n\n%% BEAM adapters return ordinary native values. An async declaration runs the\n%% call in its own process, awaiting its value or original exception. Reuse\n%% the parallel group's ownership and context propagation for cancellation.\nasync_call(Body) -> hd(concurrently([Body])).\n\n%% @doc Each parallel step runs in a monitored worker. Results are returned in\n%% source order; exceptions preserve their class and stack. Every sibling\n%% finishes before the first exception in source order is raised. Caller\n%% cancellation joins the cancelled children. The coordinator keeps\n%% messages out of the caller's mailbox. ref:DEC-typed-core-boundary\nconcurrently(Bodies) ->\n    Caller = self(),\n    Context = worker_context(),\n    {Coordinator, Monitor} = spawn_monitor(fun() -> with_worker_context(Context, fun() ->\n        process_flag(trap_exit, true),\n        ParentMonitor = monitor(process, Caller),\n        Workers = [{spawn_opt(fun() ->\n            Result = try {ok, with_worker_context(Context, Body)} catch Class:Reason:Stack -> {exception, Class, Reason, Stack} end,\n            exit({lawspec_result, Result})\n        end, [link, monitor]), I} || {I, Body} <- lists:enumerate(Bodies)],\n        Result = collect(Workers, #{}, ParentMonitor),\n        exit({lawspec_result, Result})\n    end) end),\n    receive\n        {'DOWN', Monitor, process, Coordinator, {lawspec_result, {ok, Results}}} -> Results;\n        {'DOWN', Monitor, process, Coordinator, {lawspec_result, {exception, Class, Reason, Stack}}} ->\n            erlang:raise(Class, Reason, Stack);\n        {'DOWN', Monitor, process, Coordinator, Reason} -> erlang:error({lawspec, {concurrent_group_failed, Reason}})\n    end.\n\ncollect([], Results, ParentMonitor) ->\n    demonitor(ParentMonitor, [flush]),\n    Ordered = [maps:get(I, Results) || I <- lists:seq(1, map_size(Results))],\n    case [Error || Error = {exception, _, _, _} <- Ordered] of\n        [First | _] -> First;\n        [] -> {ok, [Value || {ok, Value} <- Ordered]}\n    end;\ncollect(Workers, Results, ParentMonitor) ->\n    receive\n        {'DOWN', ParentMonitor, process, _, _} -> cancel(Workers), exit(normal);\n        {'DOWN', Monitor, process, Pid, Reason} ->\n            case lists:keytake({Pid, Monitor}, 1, Workers) of\n                {value, {_, I}, Rest} ->\n                    Outcome = case Reason of\n                        {lawspec_result, {ok, _} = Value} -> Value;\n                        {lawspec_result, {exception, _, _, _} = Error} -> Error;\n                        _ -> {exception, error, {lawspec, {concurrent_step_failed, Reason}}, []}\n                    end,\n                    collect(Rest, Results#{I => Outcome}, ParentMonitor)\n            end\n    end.\n\ncancel(Workers) ->\n    lists:foreach(fun({{Pid, _}, _}) -> exit(Pid, kill) end, Workers),\n    lists:foreach(fun({{Pid, Monitor}, _}) ->\n        receive {'DOWN', Monitor, process, Pid, _} -> ok end\n    end, Workers).\n"
runtimeSource "beam-proper" = "%% @doc PropEr generators retain PropEr's own shrink trees. Shrinking a bound\n%% input rebuilds dependent generators and reapplies every domain predicate.\n%% ref:DEC-native-property-frameworks ref:DEC-shrink-within-domain\n-module(lawspec_beam_proper).\n-export([generator/5, generator/6, map/2, bind/2, constrain/2, refine_input/2, complete/1, check/3, exactly/1, sized/1,\n    frequency/1, oneof/1, integer/2, list/1, vector/2, fixed_list/1, binary/0, forall/2]).\n\n%% An empty dependent range retries the whole tuple, including earlier inputs.\n%% Retrying only its final input would never escape the empty range.\nmap(Type, Convert) ->\n    case proper_types:is_raw_type(Type) of\n        true -> proper_types:bind(Type, fun(Value) -> proper_types:exactly(Convert(Value)) end, false);\n        false -> erlang:error({lawspec, expected_proper_generator})\n    end.\nbind(Type, Build) -> proper_types:bind(Type, fun\n    ('$lawspec_empty_domain') -> proper_types:exactly('$lawspec_empty_domain');\n    (Value) -> Build(Value)\nend, false).\nconstrain(Type, Predicate) -> proper_types:add_constraint(Type, fun\n    ('$lawspec_empty_domain') -> true;\n    (Value) -> Predicate(Value)\nend, true).\ncomplete(Type) -> proper_types:add_constraint(Type, fun(V) -> V =/= '$lawspec_empty_domain' end, true).\n\n%% A quantifier's predicate may depend on previous inputs. Reject at the\n%% tuple's root so that an impossible prefix is redrawn and can also shrink.\nrefine_input(Type, Predicate) -> bind(Type, fun(Value) ->\n    case Predicate(Value) of\n        true -> proper_types:exactly(Value);\n        false -> proper_types:exactly('$lawspec_empty_domain')\n    end\nend).\n\ngenerator(T, Schema, Symbols, Bounds, Witnesses) ->\n    lawspec_beam_generators:generator(?MODULE, T, Schema, Symbols, Bounds, Witnesses).\ngenerator(T, Schema, Symbols, Bounds, Witnesses, Index) ->\n    lawspec_beam_generators:generator(?MODULE, T, Schema, Symbols, Bounds, Witnesses, Index).\n\nexactly(Value) -> proper_types:exactly(Value).\nsized(Build) -> proper_types:sized(Build).\nfrequency(Choices) -> proper_types:frequency(Choices).\noneof(Choices) -> proper_types:oneof(Choices).\ninteger(Lo, Hi) -> proper_types:integer(ext(Lo), ext(Hi)).\next(none) -> inf;\next(N) -> N.\nlist(Type) -> proper_types:list(Type).\nvector(Count, Type) -> proper_types:vector(Count, Type).\nfixed_list(Types) -> map(proper_types:fixed_list(Types), fun(Values) ->\n    case lists:member('$lawspec_empty_domain', Values) of true -> '$lawspec_empty_domain'; false -> Values end\nend).\nbinary() -> proper_types:binary().\nforall(Type, Predicate) -> proper:forall(Type, Predicate).\n\n%% @doc Seed the framework once, then let its generator and shrinker run.\n%% A generation error or an exhausted discard budget fails the test.\n%% ref:DEC-never-pass-vacuously\ncheck(Label, Property, Options) ->\n    Seed = case os:getenv(\"LAWSPEC_SEED\") of\n        false -> erlang:system_time(nanosecond) bxor erlang:unique_integer([positive]);\n        Text -> list_to_integer(Text)\n    end,\n    Configured = proper:setup(fun() ->\n        proper_arith:rand_restart({Seed band 16#ffffffff, (Seed bsr 32) band 16#ffffffff, 1}),\n        fun() -> ok end\n    end, Property),\n    lawspec_beam_generators:with_cache(fun() ->\n        case proper:quickcheck(Configured, Options) of\n            true -> ok;\n            Result -> erlang:error({lawspec, {property_failed, Label, {seed, Seed}, Result}})\n        end\n    end).\n"
runtimeSource "beam-effects" = "%% @doc Lexically scoped ability evidence and typed failures on the BEAM.\n%% The schema carries immutable handler choices; symbol identity is unchanged.\n%% Stateful handlers and recordings belong to a monitored scope, so parallel\n%% workers share their state and cancellation cannot leak handler processes.\n%% ref:DEC-typed-core-boundary\n-module(lawspec_beam_effects).\n-behaviour(gen_server).\n-export([with_scope/3, install/2, handler/2, stateless/1, stateful/3,\n    recording/2, perform/4, invoke/4, count_calls/4,\n    fail/1, raise_failure/2, attempt/4, native_failures/4, match_exception/3,\n    native_origin/0, origin/5, recover_handler/5, with_native_context/3,\n    native_cell/1, native_read/1, native_write/2]).\n-export_type([context/0, handler_origin/0]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2]).\n\n-opaque context() :: {lawspec_context, map(), reference()}.\n-opaque handler_origin() :: none | {lawspec_handler_origin, binary(), map(), reference(), term(), [function()]}.\n\nnative_origin() -> none.\n\n%% A native interface can cross back into a checked definition. Retaining its\n%% logical handler lets that definition supply its current lexical context,\n%% including any nested override of another ability used by a spec clause.\norigin(Schema, Symbols, Ability, Handler, Operations) ->\n    {lawspec_handler_origin, Ability, Schema, Symbols, Handler, Operations}.\n\nrecover_handler({lawspec_handler_origin, Ability, _, Symbols, Handler, Operations}, Ability, Symbols, Operations, _) -> Handler;\nrecover_handler(none, _, _, _, Make) -> Make();\nrecover_handler({lawspec_handler_origin, Ability, _, Symbols, _, _}, Ability, Symbols, _, Make) -> Make();\nrecover_handler({lawspec_handler_origin, Ability, _, _, _, _}, Ability, _, _, _) ->\n    erlang:error({lawspec, incompatible_handler_contexts});\nrecover_handler(_, Ability, _, _, _) -> erlang:error({lawspec, {invalid_handler_origin, Ability}}).\n\nwith_native_context(Origins, SchemaFactory, Body) ->\n    Contexts = [{Schema, Symbols} || {lawspec_handler_origin, _, Schema, Symbols, _, _} <- Origins],\n    {Schema, Symbols} = case Contexts of\n        [] -> Fresh = make_ref(), {SchemaFactory(Fresh), Fresh};\n        [{FirstSchema, FirstSymbols} | Rest] ->\n            case lists:all(fun({_, S}) -> S =:= FirstSymbols end, Rest) of\n                true -> {FirstSchema, FirstSymbols};\n                false -> erlang:error({lawspec, incompatible_handler_contexts})\n            end\n    end,\n    with_scope(Schema, #{}, fun(Scoped) -> Body(Scoped, Symbols) end).\n\n%% Factories run inside the scope as well: a later factory failing releases\n%% any state already allocated by earlier factories.\nwith_scope(Schema, Factories, Body) ->\n    {ok, Scope} = gen_server:start(?MODULE, self(), []),\n    Base = Schema#{lawspec_scope => Scope},\n    Previous = put({?MODULE, scope}, Scope),\n    try\n        Handlers = maps:map(fun(_, Make) -> Make(Base) end, Factories),\n        Body(install(Base, Handlers))\n    after\n        case Previous of\n            undefined -> erase({?MODULE, scope});\n            _ -> put({?MODULE, scope}, Previous)\n        end,\n        try gen_server:stop(Scope, normal, infinity)\n        catch exit:noproc -> ok end\n    end.\n\n%% Native production factories may allocate scoped state without receiving a\n%% hidden argument. Only allocation uses this process-local scope; the cell\n%% itself is a shareable process and all access is serialized by its server.\nnative_cell(Initial) ->\n    case get({?MODULE, scope}) of\n        Scope when is_pid(Scope) -> cell(#{lawspec_scope => Scope}, Initial);\n        _ -> erlang:error({lawspec, missing_handler_scope})\n    end.\n\nnative_read(Cell) -> lawspec_beam_handler:call(Cell, fun(Value) -> {Value, Value} end).\nnative_write(Cell, Value) -> lawspec_beam_handler:call(Cell, fun(_) -> {Value, Value} end).\n\ninstall(Schema, Handlers) ->\n    Schema#{lawspec_handlers => maps:merge(maps:get(lawspec_handlers, Schema, #{}), Handlers)}.\n\nhandler(Schema, Ability) ->\n    case maps:find(Ability, maps:get(lawspec_handlers, Schema, #{})) of\n        {ok, Handler} -> Handler;\n        error -> erlang:error({lawspec, {missing_handler, Ability}})\n    end.\n\nstateless(Operations) -> {lawspec_handler, Operations}.\n\nstateful(Schema, Initial, Operations) ->\n    {lawspec_stateful, cell(Schema, Initial), Operations}.\n\nrecording(Schema, Handler) ->\n    {lawspec_recording, cell(Schema, []), Handler}.\n\ncell(#{lawspec_scope := Scope}, Initial) ->\n    gen_server:call(Scope, {cell, Initial}, infinity);\ncell(_, _) -> erlang:error({lawspec, missing_handler_scope}).\n\nperform(Schema, Ability, Operation, Arguments) ->\n    invoke(handler(Schema, Ability), Schema, Operation, Arguments).\n\ninvoke({lawspec_handler, Operations}, Schema, Operation, Arguments) ->\n    Clause = operation(Operations, Operation),\n    Clause(Schema, Arguments);\ninvoke({lawspec_stateful, Cell, Operations}, Schema, Operation, Arguments) ->\n    Clause = operation(Operations, Operation),\n    Path = maps:get(lawspec_effect_path, Schema, []),\n    case lists:member(Cell, Path) of\n        true -> erlang:error({lawspec, {recursive_handler_call, Operation}});\n        false -> lawspec_beam_handler:call(Cell, fun(State) ->\n            Clause(Schema#{lawspec_effect_path => [Cell | Path]}, Arguments, State)\n        end)\n    end;\ninvoke({lawspec_recording, Cell, Inner}, Schema, Operation, Arguments) ->\n    %% Record the attempted call even if the wrapped operation aborts.\n    lawspec_beam_handler:call(Cell, fun(Log) -> {ok, [{Operation, Arguments} | Log]} end),\n    invoke(Inner, Schema, Operation, Arguments).\n\noperation(Operations, Name) ->\n    case maps:find(Name, Operations) of\n        {ok, Clause} -> Clause;\n        error -> erlang:error({lawspec, {missing_handler_operation, Name}})\n    end.\n\ncount_calls(Schema, Ability, Operation, Arguments) ->\n    case handler(Schema, Ability) of\n        {lawspec_recording, Cell, _} ->\n            Calls = lawspec_beam_handler:call(Cell, fun(Log) -> {Log, Log} end),\n            length([ok || {Name, Values} <- Calls, Name =:= Operation,\n                Arguments =:= any orelse lawspec_beam_scalar:equal(Values, Arguments)]);\n        _ -> erlang:error({lawspec, {recording_required, Ability}})\n    end.\n\n%% Native code uses fail/1 with its native failure value. The adapter's\n%% declared Fail ability determines how that value crosses the boundary.\nfail(Value) -> throw({lawspec_native_failure, Value}).\nraise_failure(Ability, Value) -> throw({lawspec_failure, Ability, Value}).\n\nattempt(Ability, Body, Right, Left) ->\n    try Body() of\n        Value -> Right(Value)\n    catch throw:{lawspec_failure, Ability, Value} -> Left(Value) end.\n\n%% Each optional native exception mapping returns no_match or {ok, Value}.\n%% Existing typed failures pass through unchanged, including another ability.\nnative_failures(Ability, Convert, Body, Mappings) ->\n    try Body() catch\n        throw:{lawspec_native_failure, Native} -> raise_failure(Ability, Convert(Native));\n        throw:{lawspec_failure, _, _} = Failure:Stack -> erlang:raise(throw, Failure, Stack);\n        Class:Reason:Stack ->\n            case mapped(Mappings, Class, Reason) of\n                {ok, Value} -> raise_failure(Ability, Value);\n                no_match -> erlang:raise(Class, Reason, Stack)\n            end\n    end.\n\nmapped([], _, _) -> no_match;\nmapped([Map | Rest], Class, Reason) ->\n    case Map(Class, Reason) of\n        no_match -> mapped(Rest, Class, Reason);\n        {ok, _} = Found -> Found\n    end.\n\n%% Native mappings name an Elixir exception module or a tagged Erlang error\n%% reason (also available to Gleam FFI code). They do not catch exits, throws,\n%% or an unrelated error merely because its printed message contains the tag.\nmatch_exception({elixir, Module}, error,\n        #{'__struct__' := Module, '__exception__' := true} = Exception) ->\n    {ok, 'Elixir.Exception':message(Exception)};\nmatch_exception({tag, Tag}, error, Tag) -> {ok, atom_to_binary(Tag, utf8)};\nmatch_exception({tag, Tag}, error, Reason) when is_tuple(Reason), tuple_size(Reason) > 0,\n        element(1, Reason) =:= Tag ->\n    Message = case Reason of\n        {Tag, Text} when is_binary(Text) -> Text;\n        _ -> unicode:characters_to_binary(io_lib:format(\"~tp\", [Reason]))\n    end,\n    {ok, Message};\nmatch_exception(_, _, _) -> no_match.\n\ninit(Owner) -> {ok, #{owner => monitor(process, Owner), cells => #{}}}.\n\nhandle_call({cell, Initial}, _, State = #{cells := Cells}) ->\n    {ok, Cell} = lawspec_beam_handler:start(self(), Initial),\n    Monitor = monitor(process, Cell),\n    {reply, Cell, State#{cells := Cells#{Monitor => Cell}}}.\n\nhandle_cast(_, State) -> {noreply, State}.\n\nhandle_info({'DOWN', Owner, process, _, _}, State = #{owner := Owner}) ->\n    {stop, normal, State};\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{cells := Cells}) ->\n    {noreply, State#{cells := maps:remove(Monitor, Cells)}};\nhandle_info(_, State) -> {noreply, State}.\n\nterminate(_, #{cells := Cells}) ->\n    maps:foreach(fun(_, Cell) -> lawspec_beam_handler:stop(Cell) end, Cells).\n"
runtimeSource "beam-handler" = "%% @doc One spec handler's state, shared by all processes in its scope.\n%% Clauses run outside the server so a blocked clause can still be cancelled.\n%% ref:DEC-typed-core-boundary\n-module(lawspec_beam_handler).\n-behaviour(gen_server).\n-export([start/2, call/2, stop/1]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2]).\n\nstart(Owner, Initial) -> gen_server:start(?MODULE, {Owner, Initial}, []).\n\ncall(Handler, Update) ->\n    Context = lawspec_beam_runtime:worker_context(),\n    case gen_server:call(Handler, {update, make_ref(), Context, Update}, infinity) of\n        {ok, Value} -> Value;\n        {exception, Class, Reason, Stack} -> erlang:raise(Class, Reason, Stack)\n    end.\n\nstop(Handler) ->\n    try gen_server:stop(Handler, normal, infinity)\n    catch exit:noproc -> ok end.\n\ninit({Owner, Initial}) ->\n    process_flag(trap_exit, true),\n    Graph = lawspec_beam_waits:register(self()),\n    {ok, #{owner => monitor(process, Owner), value => Initial,\n        graph => Graph, graph_monitor => monitor(process, Graph),\n        active => none, waiting => queue:new()}}.\n\nhandle_call({update, Token, Context, Update}, From = {Caller, _}, State = #{graph := Graph}) ->\n    Origin = proplists:get_value({?MODULE, context}, Context),\n    case lawspec_beam_waits:request(Graph, Token, self(), Caller, Origin) of\n        ok ->\n            Entry = {From, monitor(process, Caller), Token, Context, Update},\n            {noreply, next(State#{waiting := queue:in(Entry, maps:get(waiting, State))})};\n        {error, Reason} -> {reply, {exception, error, {lawspec, Reason}, []}, State}\n    end.\n\nhandle_cast(_, State) -> {noreply, State}.\n\nhandle_info({'DOWN', Owner, process, _, _}, State = #{owner := Owner}) ->\n    {stop, normal, State};\nhandle_info({'DOWN', Monitor, process, _, Reason}, State = #{graph_monitor := Monitor}) ->\n    {stop, {dependency_tracker_stopped, Reason}, State};\nhandle_info({'DOWN', Monitor, process, Pid, Reason},\n        State = #{active := {Pid, Monitor, From, CallerMonitor, Token}, graph := Graph}) ->\n    demonitor(CallerMonitor, [flush]),\n    lawspec_beam_waits:complete(Graph, Token),\n    %% A cancelled caller cannot commit a half-finished operation. Its DOWN\n    %% signal may still be behind the worker's result in the mailbox.\n    Updated = case is_process_alive(element(1, From)) of\n        false -> State;\n        true -> case Reason of\n            {lawspec_result, {ok, Value, NewState}} ->\n                gen_server:reply(From, {ok, Value}), State#{value := NewState};\n            {lawspec_result, {exception, _, _, _} = Failure} ->\n                gen_server:reply(From, Failure), State;\n            _ ->\n                gen_server:reply(From, {exception, error,\n                    {lawspec, {handler_worker_failed, Reason}}, []}), State\n        end\n    end,\n    {noreply, next(Updated#{active := none})};\nhandle_info({'DOWN', CallerMonitor, process, _, _},\n        State = #{active := {Pid, Monitor, _, CallerMonitor, Token}, graph := Graph}) ->\n    cancel(Pid, Monitor),\n    lawspec_beam_waits:complete(Graph, Token),\n    {noreply, next(State#{active := none})};\nhandle_info({'DOWN', Monitor, process, _, _}, State) ->\n    Waiting = queue:filter(fun({_, M, _, _, _}) -> M =/= Monitor end, maps:get(waiting, State)),\n    {noreply, State#{waiting := Waiting}};\nhandle_info(_, State) -> {noreply, State}.\n\nterminate(_, State) ->\n    case maps:get(active, State) of\n        none -> ok;\n        {Pid, Monitor, _, CallerMonitor, _} ->\n            cancel(Pid, Monitor), demonitor(CallerMonitor, [flush])\n    end,\n    lists:foreach(fun({_, M, _, _, _}) -> demonitor(M, [flush]) end,\n        queue:to_list(maps:get(waiting, State))),\n    lawspec_beam_waits:unregister(maps:get(graph, State), self()).\n\nnext(State = #{active := none, waiting := Waiting, value := Value, graph := Graph}) ->\n    case queue:out(Waiting) of\n        {empty, _} -> State;\n        {{value, {From, CallerMonitor, Token, Context, Update}}, Rest} ->\n            case is_process_alive(element(1, From)) andalso lawspec_beam_waits:activate(Graph, self(), Token) of\n                false -> demonitor(CallerMonitor, [flush]), next(State#{waiting := Rest});\n                true ->\n                    %% The link prevents a worker leaking if the server itself\n                    %% is killed; the monitor carries its result and stack.\n                    Cell = self(),\n                    WorkerContext = lists:keystore({?MODULE, context}, 1, Context, {{?MODULE, context}, {Graph, Cell, Token}}),\n                    {Pid, Monitor} = spawn_opt(fun() ->\n                        Result = try\n                            case lawspec_beam_runtime:with_worker_context(WorkerContext, fun() -> Update(Value) end) of\n                                {Reply, NewState} -> {ok, Reply, NewState};\n                                Other -> erlang:error({lawspec, {invalid_handler_result, Other}})\n                            end\n                        catch Class:Reason:Stack -> {exception, Class, Reason, Stack} end,\n                        exit({lawspec_result, Result})\n                    end, [link, monitor]),\n                    State#{active := {Pid, Monitor, From, CallerMonitor, Token}, waiting := Rest}\n            end\n    end;\nnext(State) -> State.\n\ncancel(Pid, Monitor) ->\n    exit(Pid, kill),\n    receive {'DOWN', Monitor, process, Pid, _} -> ok end.\n"
runtimeSource "beam-waits" = "%% @doc Dependency tracking for stateful handler operations. A graph is shared\n%% while cells are alive, including cells from nested or concurrent scopes.\n%% It holds no handler values and exits when the last cell leaves. Losing the\n%% tracker closes its monitored cells, so lost edges cannot cause a deadlock.\n%% ref:DEC-typed-core-boundary\n-module(lawspec_beam_waits).\n-behaviour(gen_server).\n-export([register/1, request/5, activate/3, complete/2, unregister/2]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2]).\n\nregister(Cell) ->\n    Graph = case gen_server:start({local, ?MODULE}, ?MODULE, [], []) of\n        {ok, Pid} -> Pid;\n        {error, {already_started, Pid}} -> Pid\n    end,\n    try gen_server:call(Graph, {register, Cell}, infinity) of\n        ok -> Graph\n    catch\n        %% The previous last cell may have left between lookup and register.\n        exit:{noproc, _} -> register(Cell);\n        exit:{normal, _} -> register(Cell)\n    end.\n\nrequest(Graph, Token, Target, Caller, Context) ->\n    gen_server:call(Graph, {request, Token, Target, Caller, Context}, infinity).\nactivate(Graph, Cell, Token) -> gen_server:call(Graph, {activate, Cell, Token}, infinity).\ncomplete(Graph, Token) -> gen_server:call(Graph, {complete, Token}, infinity).\nunregister(Graph, Cell) ->\n    try gen_server:call(Graph, {unregister, Cell}, infinity)\n    catch exit:_ -> ok end.\n\ninit([]) ->\n    %% Also clean up if the very first registering caller dies during start.\n    {ok, #{cells => #{}, cell_monitors => #{}, requests => #{}, callers => #{}}, 1000}.\n\nhandle_call({register, Cell}, _, State = #{cells := Cells, cell_monitors := Monitors}) ->\n    Monitor = monitor(process, Cell),\n    {reply, ok, State#{cells := Cells#{Cell => {Monitor, none}}, cell_monitors := Monitors#{Monitor => Cell}}};\nhandle_call({request, Token, Target, Caller, Context}, _, State = #{cells := Cells, requests := Requests, callers := Callers}) ->\n    Source = source(Context, Cells, Requests),\n    case maps:is_key(Target, Cells) andalso not cyclic(Source, Target, Requests, Cells) of\n        false -> {reply, {error, cyclic_handler_dependency}, State};\n        true ->\n            Monitor = monitor(process, Caller),\n            {reply, ok, State#{requests := Requests#{Token => {Target, Caller, Monitor, Source}}, callers := Callers#{Monitor => Token}}}\n    end;\nhandle_call({activate, Cell, Token}, _, State = #{cells := Cells, requests := Requests}) ->\n    case {maps:find(Cell, Cells), maps:find(Token, Requests)} of\n        {{ok, {Monitor, none}}, {ok, {Cell, _, _, _}}} ->\n            {reply, true, State#{cells := Cells#{Cell := {Monitor, Token}}}};\n        _ -> {reply, false, State}\n    end;\nhandle_call({complete, Token}, _, State) ->\n    Updated = forget(Token, State),\n    {reply, ok, Updated, idle(Updated)};\nhandle_call({unregister, Cell}, _, State) ->\n    Updated = remove_cell(Cell, State),\n    {reply, ok, Updated, idle(Updated)}.\n\nhandle_cast(_, State) -> {noreply, State, idle(State)}.\n\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{cell_monitors := Cells, callers := Callers}) ->\n    Updated = case {maps:find(Monitor, Cells), maps:find(Monitor, Callers)} of\n        {{ok, Cell}, _} -> remove_cell(Cell, State);\n        {_, {ok, Token}} -> forget(Token, State);\n        _ -> State\n    end,\n    {noreply, Updated, idle(Updated)};\nhandle_info(timeout, State = #{cells := Cells}) when map_size(Cells) =:= 0 -> {stop, normal, State};\nhandle_info(_, State) -> {noreply, State, idle(State)}.\n\nidle(#{cells := Cells}) when map_size(Cells) =:= 0 -> 0;\nidle(_) -> infinity.\n\n%% A task that outlives a completed operation no longer holds its cell.\nsource({Graph, Cell, Token}, Cells, Requests) when Graph =:= self(), Token =/= none ->\n    case live_source({Cell, Token}, Cells, Requests) of\n        Cell -> {Cell, Token};\n        _ -> none\n    end;\nsource(_, _, _) -> none.\n\ncyclic(none, _, _, _) -> false;\ncyclic({Source, _}, Target, Requests, Cells) ->\n    Edges = maps:fold(fun(_, {To, Caller, _, From}, Acc) ->\n        case is_process_alive(Caller) andalso live_source(From, Cells, Requests) of\n            false -> Acc;\n            none -> Acc;\n            Cell -> Acc#{Cell => [To | maps:get(Cell, Acc, [])]}\n        end\n    end, #{}, Requests),\n    reaches([Target], Source, Edges, #{}).\n\nlive_source({Cell, Token}, Cells, Requests) ->\n    case {maps:find(Cell, Cells), maps:find(Token, Requests)} of\n        {{ok, {_, Token}}, {ok, {Cell, Caller, _, _}}} ->\n            case is_process_alive(Caller) of true -> Cell; false -> none end;\n        _ -> none\n    end;\nlive_source(none, _, _) -> none.\n\nreaches([], _, _, _) -> false;\nreaches([Target | _], Target, _, _) -> true;\nreaches([Cell | Rest], Target, Edges, Seen) ->\n    case maps:is_key(Cell, Seen) of\n        true -> reaches(Rest, Target, Edges, Seen);\n        false -> reaches(maps:get(Cell, Edges, []) ++ Rest, Target, Edges, Seen#{Cell => true})\n    end.\n\n%% Remove a dependency BEFORE returning its result. Removing it in the waiting\n%% caller would leave a stale edge until that caller is scheduled again.\nforget(Token, State = #{requests := Requests, callers := Callers, cells := Cells}) ->\n    case maps:take(Token, Requests) of\n        error -> State;\n        {{Target, _, Monitor, _}, Rest} ->\n            demonitor(Monitor, [flush]),\n            UpdatedCells = case maps:find(Target, Cells) of\n                {ok, {CellMonitor, Token}} -> Cells#{Target := {CellMonitor, none}};\n                _ -> Cells\n            end,\n            State#{requests := Rest, callers := maps:remove(Monitor, Callers), cells := UpdatedCells}\n    end.\n\nremove_cell(Cell, State = #{cells := Cells, cell_monitors := Monitors, requests := Requests}) ->\n    case maps:find(Cell, Cells) of\n        error -> State;\n        {ok, {Monitor, _}} ->\n            demonitor(Monitor, [flush]),\n            Cleared = lists:foldl(fun forget/2, State,\n                [Token || {Token, {Target, _, _, _}} <- maps:to_list(Requests), Target =:= Cell]),\n            Cleared#{cells := maps:remove(Cell, maps:get(cells, Cleared)), cell_monitors := maps:remove(Monitor, Monitors)}\n    end.\n"
runtimeSource "beam-policy" = "%% @doc Portable workflow policy arithmetic and logical failure values.\n%% Durations are integer microseconds. Random state is explicit SplitMix64,\n%% separate from the user-facing Random ability's MMIX stream.\n%% ref:DEC-typed-core-boundary ref:splitmix\n-module(lawspec_beam_policy).\n-export([retry_delay/2, jitter/5, retry_decision/1, failed/1, stage_failure/1]).\n\nretry_delay(immediate, Attempt) when Attempt >= 2 -> 0;\nretry_delay({fixed, Delay}, Attempt) when Attempt >= 2 -> Delay;\nretry_delay({linear, Delay, Step}, Attempt) when Attempt >= 2 -> Delay + Step * (Attempt - 2);\nretry_delay({exponential, Delay, Factor, Cap}, Attempt) when Attempt >= 2 ->\n    Value = Delay * power(Factor, Attempt - 2),\n    case Cap of none -> Value; _ -> min(Value, Cap) end;\nretry_delay({fibonacci, Delay}, Attempt) when Attempt >= 2 -> Delay * fibonacci(Attempt - 1, 1, 1).\n\npower(_, 0) -> 1;\npower(Base, N) when N rem 2 =:= 0 -> power(Base * Base, N div 2);\npower(Base, N) -> Base * power(Base * Base, N div 2).\n\nfibonacci(1, A, _) -> A;\nfibonacci(N, A, B) -> fibonacci(N - 1, B, A + B).\n\njitter(none, Delay, _, _, State) -> {Delay, State};\njitter(full, Delay, _, _, State) -> lawspec_beam_random:below(Delay + 1, State);\njitter(equal, Delay, _, _, State) ->\n    Half = Delay div 2,\n    {Random, Next} = lawspec_beam_random:below(Delay - Half + 1, State),\n    {Half + Random, Next};\njitter(decorrelated, Delay, Previous, Base, State) ->\n    High = max(Base, Previous * 3),\n    {Random, Next} = lawspec_beam_random:below(High - Base + 1, State),\n    {min(Delay, Base + Random), Next}.\n\nretry_decision({ls_data, <<\"lawspec.time::type::RetryDecision::RetryAfter\">>,\n        [{ls_data, <<\"lawspec.time::type::Duration::Duration\">>, [Delay]}]}) -> {wait, Delay};\nretry_decision({ls_data, <<\"lawspec.time::type::RetryDecision::Stop\">>, []}) -> stop.\n\nfailed({ls_data, <<\"Either::Left\">>, [_]}) -> true;\nfailed(_) -> false.\n\nstage_failure(Kind) when Kind =:= <<\"TimedOut\">>; Kind =:= <<\"RateLimited\">>;\n        Kind =:= <<\"CircuitOpen\">>; Kind =:= <<\"Saturated\">> ->\n    {ls_data, <<\"Either::Left\">>, [{ls_data, <<\"lawspec.resilience::type::StageFailure::\", Kind/binary>>, []}]}.\n"
runtimeSource "beam-tasks" = "%% @doc A cancellation scope owns every worker started beneath it, including\n%% nested async calls and parallel groups. Registration precedes application\n%% code, so closing a scope cannot race a new child's first side effect.\n%% ref:DEC-async-native-tasks ref:DEC-typed-core-boundary\n-module(lawspec_beam_tasks).\n-behaviour(gen_server).\n-export([open/0, with_scope/1, attach/1, adopt/2, close/1]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2]).\n\n%% A persistent service can own a scope without installing it in its own\n%% process dictionary. Its workers attach before running application code.\nopen() -> {ok, Scope} = gen_server:start(?MODULE, self(), []), Scope.\n\nwith_scope(Body) ->\n    Scope = open(),\n    Key = {?MODULE, scopes},\n    Previous = get(Key),\n    Parents = case Previous of undefined -> []; _ -> Previous end,\n    put(Key, [Scope | Parents]),\n    try Body(Scope) after\n        case Previous of undefined -> erase(Key); _ -> put(Key, Previous) end,\n        close(Scope)\n    end.\n\n%% A nested worker registers with every enclosing scope. An outer timeout\n%% therefore joins its grandchildren even if their coordinator is blocked.\nattach(Scopes) ->\n    lists:foreach(fun(Scope) ->\n        ok = gen_server:call(Scope, {attach, self()}, infinity)\n    end, Scopes).\n\n%% A service owner may also attach a child before exposing its handle.\nadopt(Scope, Worker) -> gen_server:call(Scope, {adopt, Worker}, infinity).\n\nclose(Scope) ->\n    try gen_server:call(Scope, close, infinity)\n    catch exit:{noproc, _} -> ok; exit:{normal, _} -> ok end.\n\ninit(Owner) ->\n    process_flag(trap_exit, true),\n    {ok, #{owner => Owner, owner_monitor => monitor(process, Owner),\n        workers => #{}, monitors => #{}, closing => false, waiters => []}}.\n\nhandle_call({adopt, Pid}, {Owner, _}, State = #{owner := Owner}) -> handle_call({attach, Pid}, none, State);\nhandle_call({adopt, _}, _, State) -> {reply, {error, not_scope_owner}, State};\nhandle_call({attach, Owner}, _, State = #{owner := Owner, closing := true}) -> {reply, {error, closed}, State};\nhandle_call({attach, Owner}, _, State = #{owner := Owner}) -> {reply, ok, State};\nhandle_call({attach, Pid}, _, State = #{closing := true}) ->\n    exit(Pid, kill), {reply, {error, closed}, State};\nhandle_call({attach, Pid}, _, State = #{workers := Workers, monitors := Monitors}) ->\n    case maps:is_key(Pid, Workers) of\n        true -> {reply, ok, State};\n        false ->\n            Monitor = monitor(process, Pid),\n            link(Pid),\n            {reply, ok, State#{workers := Workers#{Pid => Monitor}, monitors := Monitors#{Monitor => Pid}}}\n    end;\nhandle_call(close, From, State = #{waiters := Waiters}) ->\n    finish(begin_close(State#{waiters := [From | Waiters]})).\n\nhandle_cast(_, State) -> {noreply, State}.\n\nhandle_info({'DOWN', Owner, process, _, _}, State = #{owner_monitor := Owner}) ->\n    finish(begin_close(State));\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{workers := Workers, monitors := Monitors}) ->\n    case maps:take(Monitor, Monitors) of\n        error -> {noreply, State};\n        {Pid, Rest} -> finish(State#{workers := maps:remove(Pid, Workers), monitors := Rest})\n    end;\nhandle_info(_, State) -> {noreply, State}.\n\nbegin_close(State = #{workers := Workers}) ->\n    maps:foreach(fun(Pid, _) -> exit(Pid, kill) end, Workers),\n    State#{closing := true}.\n\nfinish(State = #{closing := true, workers := Workers, waiters := Waiters}) when map_size(Workers) =:= 0 ->\n    lists:foreach(fun(From) -> gen_server:reply(From, ok) end, Waiters),\n    {stop, normal, State};\nfinish(State) -> {noreply, State}.\n"
runtimeSource "beam-attempts" = "%% @doc Real-clock timeout and hedge scheduling. Logical Left values lose a\n%% hedge; the first success wins, or the last failure after every attempt.\n%% Closing the task scope joins losing attempts and their nested workers.\n%% ref:DEC-async-native-tasks ref:DEC-domain-modeling-primitives\n-module(lawspec_beam_attempts).\n-export([run/4]).\n\nrun(Timeout, Hedge, Body, OnHedge) ->\n    lawspec_beam_tasks:with_scope(fun(_) ->\n        Context = lawspec_beam_runtime:worker_context(),\n        {Coordinator, Monitor} = spawn_monitor(fun() ->\n            lawspec_beam_runtime:with_worker_context(Context, fun() ->\n                Start = monotonic(),\n                Deadline = case Timeout of none -> infinity; N when N =< 0 -> infinity; N -> Start + N end,\n                {Delay, Most} = case Hedge of none -> {0, 1}; {D, M} -> {max(0, D), max(1, M)} end,\n                Config = #{body => Body, context => Context, deadline => Deadline,\n                    delay => Delay, most => Most, event => OnHedge},\n                Outcome = try {ok, loop(launch(Config, #{}, 1), Config, 1, Start + Delay)}\n                    catch Class:Reason:Stack -> {exception, Class, Reason, Stack} end,\n                exit({lawspec_attempt, Outcome})\n            end)\n        end),\n        %% The scope monitors the caller and owns the coordinator as well as its\n        %% descendants. Only this private monitor is consumed from its mailbox.\n        receive\n            {'DOWN', Monitor, process, Coordinator, {lawspec_attempt, {ok, Value}}} -> Value;\n            {'DOWN', Monitor, process, Coordinator, {lawspec_attempt, {exception, Class, Reason, Stack}}} ->\n                erlang:raise(Class, Reason, Stack);\n            {'DOWN', Monitor, process, Coordinator, Reason} -> error({lawspec, {attempt_group_failed, Reason}})\n        end\n    end).\n\nmonotonic() -> erlang:monotonic_time(microsecond).\n\nlaunch(#{body := Body, context := Context, event := Event}, Workers, Number) ->\n    case Number > 1 of true -> Event(Number); false -> ok end,\n    {Pid, Monitor} = spawn_monitor(fun() ->\n        Outcome = try lawspec_beam_runtime:with_worker_context(Context, Body) of\n            Value -> {ok, Value}\n        catch Class:Reason:Stack -> {exception, Class, Reason, Stack} end,\n        exit({lawspec_attempt_result, monotonic(), Outcome})\n    end),\n    Workers#{Monitor => Pid}.\n\nloop(Workers, #{deadline := Deadline} = Config, Started, Next) ->\n    Current = monotonic(),\n    Most = maps:get(most, Config),\n    Timer = case Started < Most of true -> min_deadline(Deadline, Next); false -> Deadline end,\n    receive\n        {'DOWN', Monitor, process, Pid, Reason} when is_map_key(Monitor, Workers) ->\n            Pid = maps:get(Monitor, Workers),\n            Rest = maps:remove(Monitor, Workers),\n            case Reason of\n                {lawspec_attempt_result, Ended, _} when Deadline =/= infinity, Ended > Deadline ->\n                    lawspec_beam_policy:stage_failure(<<\"TimedOut\">>);\n                {lawspec_attempt_result, _, {ok, Value}} ->\n                    case lawspec_beam_policy:failed(Value) of\n                        false -> Value;\n                        true when map_size(Rest) =:= 0, Started >= Most -> Value;\n                        true when map_size(Rest) =:= 0 ->\n                            case Deadline =:= infinity orelse monotonic() < Deadline of\n                                true -> loop(launch(Config, Rest, Started + 1), Config, Started + 1,\n                                    monotonic() + maps:get(delay, Config));\n                                false -> lawspec_beam_policy:stage_failure(<<\"TimedOut\">>)\n                            end;\n                        true -> loop(Rest, Config, Started, Next)\n                    end;\n                {lawspec_attempt_result, _, {exception, Class, Why, Stack}} -> erlang:raise(Class, Why, Stack);\n                _ -> error({lawspec, {attempt_failed, Reason}})\n            end\n    after milliseconds(Timer, Current) ->\n        Now = monotonic(),\n        case Deadline =/= infinity andalso Now >= Deadline of\n            true -> lawspec_beam_policy:stage_failure(<<\"TimedOut\">>);\n            false when Started < Most, Now >= Next ->\n                loop(launch(Config, Workers, Started + 1), Config, Started + 1,\n                    monotonic() + maps:get(delay, Config));\n            false -> loop(Workers, Config, Started, Next)\n        end\n    end.\n\nmin_deadline(infinity, Other) -> Other;\nmin_deadline(One, Two) -> min(One, Two).\nmilliseconds(infinity, _) -> infinity;\nmilliseconds(Deadline, Current) -> min(16#ffffffff, max(0, (Deadline - Current + 999) div 1000)).\n"
runtimeSource "beam-workflow_state" = "%% @doc Atomic workflow policy state, virtual time, jitter and compensation\n%% frames. A stage owns its admissions: caller death releases its gates.\n%% Gate callbacks are checked, pure resilience definitions.\n%% ref:DEC-domain-modeling-primitives ref:DEC-portable-seeded-generation\n-module(lawspec_beam_workflow_state).\n-behaviour(gen_server).\n-export([start/1, default/0, stop/1, call/2]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2]).\n\nstart(Options) -> gen_server:start(?MODULE, {self(), Options}, []).\ndefault() ->\n    case gen_server:start({local, ?MODULE}, ?MODULE, {none, #{}}, []) of\n        {ok, Pid} -> Pid;\n        {error, {already_started, Pid}} -> Pid\n    end.\nstop(Pid) ->\n    try gen_server:stop(Pid, normal, infinity)\n    catch exit:noproc -> ok; exit:{noproc, _} -> ok end.\ncall(Pid, Request) ->\n    case gen_server:call(Pid, Request, infinity) of\n        {ok, Value} -> Value;\n        {exception, Class, Reason, Stack} -> erlang:raise(Class, Reason, Stack)\n    end.\n\ninit({Owner, Options}) ->\n    Monitor = case Owner of none -> none; _ -> monitor(process, Owner) end,\n    {ok, #{owner => Monitor, options => Options,\n        time => maps:get(time, Options, 0), random => lawspec_beam_random:seed(maps:get(seed, Options, 0)),\n        trace => [], states => #{}, cache => #{}, frames => #{}, stages => #{}, monitors => #{}}}.\n\nhandle_call(Request, {Caller, _}, State) ->\n    try\n        Current = case Request of\n            {gate, _, _, Now} -> prune_dead_stages(Now, State);\n            _ -> State\n        end,\n        request(Request, Caller, Current)\n    of\n        {Value, Updated} -> {reply, {ok, Value}, Updated}\n    catch Class:Reason:Stack -> {reply, {exception, Class, Reason, Stack}, State} end.\nhandle_cast(_, State) -> {noreply, State}.\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{owner := Monitor}) -> {stop, normal, State};\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{monitors := Monitors}) ->\n    case maps:find(Monitor, Monitors) of\n        {ok, {frame, Ref}} -> {_, Updated} = request({take_frame, Ref}, self(), State), {noreply, Updated};\n        {ok, {stage, Ref}} ->\n            #{time := LastTime} = maps:get(Ref, maps:get(stages, State)),\n            %% Cancellation releases a bulkhead and fails an outstanding\n            %% half-open trial. No application or Clock callback runs here.\n            {noreply, finish_stage(Ref, LastTime, false, State)};\n        error -> {noreply, State}\n    end;\nhandle_info(_, State) -> {noreply, State}.\n\nrequest(options, _, State) -> {maps:get(options, State), State};\nrequest(now, _, State) -> {maps:get(time, State), State};\nrequest({set_time, Time}, _, State) -> {ok, State#{time := Time}};\nrequest({sleep, Delay}, _, State = #{time := Time}) -> {ok, State#{time := Time + max(0, Delay)}};\nrequest({jitter, Kind, Delay, Previous, Base}, _, State = #{random := Random}) ->\n    {Value, Next} = lawspec_beam_policy:jitter(Kind, Delay, Previous, Base, Random),\n    {Value, State#{random := Next}};\nrequest({event, Event}, _, State = #{trace := Trace}) -> {ok, State#{trace := [Event | Trace]}};\nrequest(trace, _, State = #{trace := Trace}) -> {lists:reverse(Trace), State};\nrequest({cached, Key, Input, Now}, _, State = #{cache := Cache}) ->\n    Live = [{K,V,Until} || {K,V,Until} <- maps:get(Key, Cache, []), Now < Until],\n    Value = case [V || {K,V,_} <- Live, lawspec_beam_scalar:equal(K, Input)] of\n        [Found | _] -> {some, Found}; [] -> none\n    end,\n    {Value, State#{cache := Cache#{Key => Live}}};\nrequest({cache, Key, Input, Value, Now, TTL}, _, State = #{cache := Cache}) ->\n    Live = [{K,V,Until} || {K,V,Until} <- maps:get(Key, Cache, []), Now < Until,\n        not lawspec_beam_scalar:equal(K, Input)],\n    {ok, State#{cache := Cache#{Key => [{Input, Value, Now + TTL} | Live]}}};\nrequest(new_frame, Caller, State = #{frames := Frames, monitors := Monitors}) ->\n    Ref = make_ref(), Monitor = monitor(process, Caller),\n    {Ref, State#{frames := Frames#{Ref => {Monitor, []}}, monitors := Monitors#{Monitor => {frame, Ref}}}};\nrequest({undo, Ref, Stage, Undo}, _, State = #{frames := Frames}) ->\n    case maps:find(Ref, Frames) of\n        {ok, {Monitor, Undos}} -> {ok, State#{frames := Frames#{Ref := {Monitor, [{Stage, Undo} | Undos]}}}};\n        error -> {ok, State}\n    end;\nrequest({take_frame, Ref}, _, State = #{frames := Frames, monitors := Monitors}) ->\n    case maps:take(Ref, Frames) of\n        {{Monitor, Undos}, Rest} ->\n            demonitor(Monitor, [flush]),\n            {Undos, State#{frames := Rest, monitors := maps:remove(Monitor, Monitors)}};\n        error -> {[], State}\n    end;\nrequest({new_stage, Key, Now}, Caller, State = #{stages := Stages, monitors := Monitors}) ->\n    Ref = make_ref(), Monitor = monitor(process, Caller),\n    Stage = #{key => Key, owner => Caller, monitor => Monitor, gates => [], time => Now},\n    {Ref, State#{stages := Stages#{Ref => Stage}, monitors := Monitors#{Monitor => {stage, Ref}}}};\nrequest({gate, Ref, Gate, Now}, _, State = #{stages := Stages, states := States}) ->\n    Stage = #{key := Key, gates := Gates, owner := Owner} = maps:get(Ref, Stages),\n    true = is_process_alive(Owner),\n    GateKey = {Key, maps:get(kind, Gate)},\n    Before = case maps:find(GateKey, States) of\n        {ok, Existing} -> Existing;\n        error -> (maps:get(start, Gate))(Now)\n    end,\n    {ls_data, _, [After, Decision]} = (maps:get(admit, Gate))(Before, Now),\n    Passed = case Decision of\n        {ls_data, <<\"lawspec.resilience::type::Gate::Admit\">>, []} -> Gates ++ [{GateKey, Gate}];\n        _ -> Gates\n    end,\n    {Decision, State#{states := States#{GateKey => After}, stages := Stages#{Ref := Stage#{gates := Passed, time := Now}}}};\nrequest({finish_stage, Ref, Now, Succeeded}, _, State) -> {ok, finish_stage(Ref, Now, Succeeded, State)}.\n\nfinish_stage(Ref, Now, Succeeded, State = #{stages := Stages, states := States, monitors := Monitors}) ->\n    case maps:take(Ref, Stages) of\n        error -> State;\n        {#{monitor := Monitor, gates := Gates}, Rest} ->\n            Updated = lists:foldl(fun({Key, Gate}, Values) ->\n                case maps:get(finish, Gate) of\n                    none -> Values;\n                    Finish -> Values#{Key := Finish(maps:get(Key, Values), Now, Succeeded)}\n                end\n            end, States, Gates),\n            demonitor(Monitor, [flush]),\n            State#{states := Updated, stages := Rest, monitors := maps:remove(Monitor, Monitors)}\n    end.\n\n%% A timeout joins the worker before its monitor signal necessarily reaches\n%% this server. Its dead admission must not reject the next live caller.\nprune_dead_stages(Now, State = #{stages := Stages}) ->\n    lists:foldl(fun({Ref, #{owner := Owner}}, Current) ->\n        case is_process_alive(Owner) of\n            true -> Current;\n            false -> finish_stage(Ref, Now, false, Current)\n        end\n    end, State, maps:to_list(Stages)).\n"
runtimeSource "beam-workflow" = "%% @doc Workflow policies over the shared checked definitions and BEAM tasks.\n%% A scoped runtime owns its state. Without one, workflows share the default\n%% runtime; an installed Clock supplies its view of time.\n%% ref:DEC-domain-modeling-primitives ref:DEC-async-native-tasks\n-module(lawspec_beam_workflow).\n-export([with_runtime/2, with_test_runtime/1, with_clock/3, current/1,\n    with_virtual/2, with_real/2, with_clock_callbacks/5, native_trace/1, native_sleep/2, native_set_time/2,\n    now/1, sleep/2, set_time/2, trace/1, run_stage/4, run_workflow/2]).\n\nwith_runtime(Options, Body) -> scoped(Options, true, Body).\nwith_clock(Clock, Seed, Body) -> with_runtime(#{clock => Clock, seed => Seed}, Body).\nwith_virtual(Seed, Body) -> with_clock(virtual, Seed, Body).\nwith_real(Seed, Body) -> with_clock(real, Seed, Body).\nwith_clock_callbacks(Now, Sleep, Virtual, Seed, Body) ->\n    with_clock(#{now => Now, sleep => Sleep, virtual => Virtual}, Seed, Body).\nnative_trace(Runtime) -> [{event, Kind, Stage, Number, Succeeded}\n    || {Kind, Stage, Number, Succeeded} <- trace(Runtime)].\nnative_sleep(Runtime, Delay) -> sleep(Runtime, Delay), nil.\nnative_set_time(Runtime, Time) -> set_time(Runtime, Time), nil.\nwith_test_runtime(Body) ->\n    Seed = try list_to_integer(os:getenv(\"LAWSPEC_SEED\", \"0\")) catch error:badarg -> 0 end,\n    scoped(#{clock => virtual, gates => false, seed => Seed}, false, fun(_) -> Body() end).\n\nscoped(Options, Explicit, Body) ->\n    {ok, Pid} = lawspec_beam_workflow_state:start(Options),\n    Runtime = runtime(Pid, Options, Explicit),\n    Key = {?MODULE, runtime}, Previous = put(Key, Runtime),\n    try Body(Runtime) after restore(Key, Previous), lawspec_beam_workflow_state:stop(Pid) end.\n\nrestore(Key, undefined) -> erase(Key);\nrestore(Key, Previous) -> put(Key, Previous).\nruntime(Pid, Options, Explicit) ->\n    #{state => Pid, clock => maps:get(clock, Options, real),\n        gates => maps:get(gates, Options, true), explicit => Explicit}.\n\ncurrent(Schema) ->\n    Base = case get({?MODULE, runtime}) of\n        undefined -> runtime(lawspec_beam_workflow_state:default(), #{}, false);\n        Given -> Given\n    end,\n    case {maps:get(explicit, Base), maps:find(<<\"lawspec.time::ability::Clock\">>, maps:get(lawspec_handlers, Schema, #{}))} of\n        {false, {ok, Handler}} ->\n            Base#{clock := #{virtual => not real_clock(Handler),\n                now => fun() ->\n                    {ls_data, <<\"lawspec.time::type::Instant::Instant\">>, [Time]} =\n                        lawspec_beam_effects:invoke(Handler, Schema, <<\"now\">>, []), Time\n                end,\n                sleep => fun(Delay) -> lawspec_beam_effects:invoke(Handler, Schema, <<\"sleep\">>,\n                    [{ls_data, <<\"lawspec.time::type::Duration::Duration\">>, [Delay]}]) end}};\n        _ -> Base\n    end.\n\nreal_clock({lawspec_recording, _, Inner}) -> real_clock(Inner);\nreal_clock(Handler) -> Handler =:= lawspec_beam_defaults:handler(<<\"lawspec.time::ability::Clock\">>).\nvirtual(#{clock := virtual}) -> true;\nvirtual(#{clock := real}) -> false;\nvirtual(#{clock := #{virtual := Virtual}}) -> Virtual.\nnow(#{clock := real}) -> lawspec_beam_defaults:now_micros();\nnow(#{clock := virtual} = Runtime) -> state(Runtime, now);\nnow(#{clock := #{now := Read}}) -> Read().\nsleep(_, Delay) when Delay =< 0 -> ok;\nsleep(#{clock := real}, Delay) -> lawspec_beam_defaults:sleep_micros(Delay);\nsleep(#{clock := virtual} = Runtime, Delay) -> state(Runtime, {sleep, Delay});\nsleep(#{clock := #{sleep := Sleep}}, Delay) -> Sleep(Delay), ok.\nset_time(#{clock := virtual} = Runtime, Time) -> state(Runtime, {set_time, Time}).\ntrace(Runtime) -> state(Runtime, trace).\nstate(#{state := Pid}, Request) -> lawspec_beam_workflow_state:call(Pid, Request).\nevent(Runtime, Policy, Kind, Number, Succeeded) ->\n    state(Runtime, {event, {Kind, maps:get(stage, Policy), Number, Succeeded}}).\n\nrun_workflow(Schema, Body) ->\n    Runtime = current(Schema),\n    Ref = state(Runtime, new_frame),\n    Key = {?MODULE, frame}, Previous = put(Key, {maps:get(state, Runtime), Ref}),\n    Outcome = try {ok, Body()} catch Class:Reason:Stack -> {exception, Class, Reason, Stack}\n        after restore(Key, Previous) end,\n    Undos = state(Runtime, {take_frame, Ref}),\n    case Outcome of\n        {ok, Result} ->\n            case lawspec_beam_policy:failed(Result) of\n                false -> ok;\n                true -> lists:foreach(fun({Stage, Undo}) ->\n                    state(Runtime, {event, {<<\"compensate\">>, Stage, 0, true}}), Undo()\n                end, Undos)\n            end,\n            Result;\n        {exception, Class1, Reason1, Stack1} -> erlang:raise(Class1, Reason1, Stack1)\n    end.\n\nrun_stage(Schema, Given, Body, Input) ->\n    Policy = maps:merge(#{key => maps:get(stage, Given), retry => none, timeout => none,\n        gates => [], cache => none, wraps => false, compensate => none, hedge => none}, Given),\n    Runtime = current(Schema),\n    Key = maps:get(key, Policy), TTL = maps:get(cache, Policy), Now = now(Runtime),\n    Caching = maps:get(gates, Runtime) andalso TTL =/= none,\n    Cached = case Caching of true -> state(Runtime, {cached, Key, Input, Now}); false -> none end,\n    case Cached of\n        {some, Value} -> event(Runtime, Policy, <<\"cached\">>, 0, true), Value;\n        none ->\n            Ref = state(Runtime, {new_stage, Key, Now}),\n            Gates = case maps:get(gates, Runtime) of true -> maps:get(gates, Policy); false -> [] end,\n            Outcome = try\n                Result = case pass_gates(Runtime, Ref, Policy, Gates) of\n                    ok -> attempts(Runtime, Policy, Body, 1, 0);\n                    {failed, Kind} -> lawspec_beam_policy:stage_failure(Kind)\n                end,\n                {ok, Result}\n            catch Class:Reason:Stack -> {exception, Class, Reason, Stack} end,\n            Succeeded = case Outcome of {ok, V} -> not lawspec_beam_policy:failed(V); _ -> false end,\n            state(Runtime, {finish_stage, Ref, now(Runtime), Succeeded}),\n            case Outcome of\n                {exception, Class1, Reason1, Stack1} -> erlang:raise(Class1, Reason1, Stack1);\n                {ok, Value} ->\n                    case Succeeded of\n                        false -> ok;\n                        true ->\n                            remember_undo(Runtime, Policy, Value),\n                            case Caching of true -> state(Runtime, {cache, Key, Input, Value, now(Runtime), TTL}); false -> ok end\n                    end,\n                    Value\n            end\n    end.\n\nremember_undo(#{state := Pid} = Runtime, Policy, Result) ->\n    case {get({?MODULE, frame}), maps:get(compensate, Policy)} of\n        {{Pid, Ref}, Undo} when is_function(Undo, 1) ->\n            Value = case Result of {ls_data, <<\"Either::Right\">>, [Inner]} -> Inner; _ -> Result end,\n            state(Runtime, {undo, Ref, maps:get(stage, Policy), fun() -> Undo(Value) end});\n        _ -> ok\n    end.\n\npass_gates(_, _, _, []) -> ok;\npass_gates(Runtime, Ref, Policy, [Gate | Rest]) ->\n    case pass_gate(Runtime, Ref, Policy, Gate, 0) of\n        ok -> pass_gates(Runtime, Ref, Policy, Rest);\n        Failure -> Failure\n    end.\npass_gate(Runtime, Ref, Policy, Gate, Waited) ->\n    Failure = case maps:get(kind, Gate) of breaker -> <<\"CircuitOpen\">>; limit -> <<\"RateLimited\">>; bulkhead -> <<\"Saturated\">> end,\n    Decision = state(Runtime, {gate, Ref, Gate, now(Runtime)}),\n    Wait = maps:get(wait, Gate),\n    case Decision of\n        {ls_data, <<\"lawspec.resilience::type::Gate::Admit\">>, []} -> ok;\n        {ls_data, <<\"lawspec.resilience::type::Gate::Reject\">>, []} -> {failed, Failure};\n        _ when Wait =:= none -> {failed, Failure};\n        {ls_data, <<\"lawspec.resilience::type::Gate::WaitFor\">>, [Delay]} ->\n            case Wait =/= infinity andalso Waited + Delay > Wait of\n                true -> {failed, Failure};\n                false ->\n                    event(Runtime, Policy, <<\"wait\">>, Delay, true), sleep(Runtime, Delay),\n                    pass_gate(Runtime, Ref, Policy, Gate, Waited + Delay)\n            end\n    end.\n\nattempts(Runtime, Policy, Body, Number, Previous) ->\n    event(Runtime, Policy, <<\"start\">>, Number, false),\n    Result = timed(Runtime, Policy, Body),\n    Failed = lawspec_beam_policy:failed(Result),\n    event(Runtime, Policy, <<\"finish\">>, Number, not Failed),\n    case {Failed, maps:get(retry, Policy)} of\n        {true, Retry} when is_map(Retry) ->\n            {ls_data, <<\"Either::Left\">>, [Error]} = Result,\n            case retry_error(maps:get(wraps, Policy), Error) of\n                stop -> Result;\n                {retry, Reason} ->\n                    Count = maps:get(attempts, Retry), Condition = maps:get('when', Retry),\n                    case (Count > 0 andalso Number >= Count) orelse\n                            (Condition =/= none andalso not Condition(Reason)) of\n                        true -> Result;\n                        false -> case retry_wait(Runtime, Retry, Number + 1, Reason, Previous) of\n                            stop -> Result;\n                            {wait, Delay} ->\n                                event(Runtime, Policy, <<\"sleep\">>, Delay, true), sleep(Runtime, Delay),\n                                attempts(Runtime, Policy, Body, Number + 1, Delay)\n                        end\n                    end\n            end;\n        _ -> Result\n    end.\n\nretry_error(false, Error) -> {retry, Error};\nretry_error(true, {ls_data, <<\"lawspec.resilience::type::StageFailure::StepFailed\">>, [Inner]}) -> {retry, Inner};\nretry_error(true, {ls_data, <<\"lawspec.resilience::type::StageFailure::TimedOut\">>, []} = Error) -> {retry, Error};\nretry_error(true, _) -> stop.\nretry_wait(_, #{strategy := {custom, Decide}}, Number, Error, Previous) -> Decide(Number, Error, Previous);\nretry_wait(Runtime, #{strategy := Strategy, jitter := Jitter}, Number, _, Previous) ->\n    Delay = lawspec_beam_policy:retry_delay(Strategy, Number),\n    Base = lawspec_beam_policy:retry_delay(Strategy, 2),\n    {wait, state(Runtime, {jitter, Jitter, Delay, Previous, Base})}.\n\ntimed(Runtime, Policy, Body) ->\n    Timeout = maps:get(timeout, Policy), Hedge = maps:get(hedge, Policy),\n    OnHedge = fun(N) -> event(Runtime, Policy, <<\"hedge\">>, N, true) end,\n    case {virtual(Runtime), maps:get(gates, Runtime)} of\n        {true, _} ->\n            Began = now(Runtime),\n            Result = virtual_hedge(Hedge, Body, OnHedge, 1),\n            case Timeout =/= none andalso Timeout > 0 andalso now(Runtime) - Began > Timeout of\n                true -> lawspec_beam_policy:stage_failure(<<\"TimedOut\">>);\n                false -> Result\n            end;\n        {false, false} -> Body();\n        {false, true} when Timeout =/= none; Hedge =/= none -> lawspec_beam_attempts:run(Timeout, Hedge, Body, OnHedge);\n        _ -> Body()\n    end.\nvirtual_hedge(none, Body, _, _) -> Body();\nvirtual_hedge({_, Most} = Hedge, Body, Event, Started) ->\n    Result = Body(),\n    case lawspec_beam_policy:failed(Result) andalso Started < Most of\n        false -> Result;\n        true -> Event(Started + 1), virtual_hedge(Hedge, Body, Event, Started + 1)\n    end.\n"
runtimeSource "beam-actors" = "%% @doc Stable actor handles backed by gen_server workers and OTP supervisors.\n%% Handles name mailboxes, not worker pids: a supervised restart replaces the\n%% worker without losing its committed checkpoint or waiting messages.\n%% ref:DEC-actors-otp-supervision ref:erlang-otp-supervisors\n-module(lawspec_beam_actors).\n-export([start/1, start/2, start_supervisor/1, start_link/1, from_process/1, with_spec/2, actor/2, supervisor/4,\n    call/2, tell/2, state/1, crash/1, crash/2, stop/1, monitor/2, link/2,\n    child/2, children/1, worker_pid/1, require_worker_pid/1, restart_count/1, metadata/1,\n    receive_event/2, context/0]).\n-export_type([actor/0, supervisor/0, event/0]).\n-opaque actor() :: {lawspec_actor, pid(), [term()]}.\n-opaque supervisor() :: {lawspec_supervisor, pid(), [term()]}.\n-type event() :: {crashed, term()} | {stopped, none}.\n\n-spec start(fun(() -> State)) -> actor() when State :: term().\n-spec start(fun(() -> State), fun((State) -> State)) -> actor().\n-spec call(actor(), fun((State) -> {Reply, State})) -> Reply.\n-spec tell(actor(), fun((State) -> {term(), State})) -> ok.\n-spec stop(actor() | supervisor()) -> ok.\n-spec monitor(actor() | supervisor(), pid()) -> ok.\n\nstart(Start) -> start(Start, fun(_) -> Start() end).\nstart(Start, Restart) -> lawspec_beam_actor_tree:start(actor(Start, Restart)).\nstart_supervisor(Spec = #{kind := supervisor}) -> lawspec_beam_actor_tree:start(Spec).\n\n%% An OTP application's child is the stable mailbox service. It owns the\n%% actual supervisor tree, so replacing a handler does not change this pid.\n%% Its generated child_spec declares a worker; worker_pid exposes the real\n%% handler/supervisor pid when native OTP inspection is needed.\nstart_link(Spec) -> lawspec_beam_actor_tree:start_link(Spec).\nwith_spec(Spec, Body) ->\n    Handle = lawspec_beam_actor_tree:start_owned(Spec),\n    try Body(Handle) after stop(Handle) end.\nfrom_process(Tree) when is_pid(Tree) ->\n    case gen_server:call(Tree, await_start, infinity) of\n        {ok, Handle} -> Handle;\n        {error, Reason} -> error({lawspec, {actor_start_failed, Reason}})\n    end.\n\nactor(Start, Restart) when is_function(Start, 0), is_function(Restart, 1) ->\n    #{kind => actor, start => Start, restart => Restart, context => context()}.\n\nsupervisor(Strategy, Restarts, Period, Children)\n        when is_integer(Restarts), Restarts >= 0, is_integer(Period), Period > 0 ->\n    true = lists:member(Strategy, [one_for_one, one_for_all, rest_for_one]),\n    Names = [Name || {Name, _, _} <- Children],\n    true = length(Names) =:= length(lists:usort(Names)),\n    lists:foreach(fun({_, Lifetime, _}) ->\n        true = lists:member(Lifetime, [permanent, transient, temporary])\n    end, Children),\n    #{kind => supervisor, strategy => Strategy, restarts => Restarts,\n        period => Period, children => Children}.\n\ncall(Actor, Handler) when is_function(Handler, 1) ->\n    request(Actor, {enqueue, call, {handler, Handler, context()}}).\ntell(Actor, Handler) when is_function(Handler, 1) ->\n    request(Actor, {enqueue, tell, {handler, Handler, context()}}).\nstate(Actor) -> call(Actor, fun(State) -> {State, State} end).\ncrash(Actor) -> crash(Actor, crashed_on_purpose).\ncrash(Actor, Cause) -> request(Actor, {enqueue, call, {crash, Cause, make_ref()}}).\nstop(Handle) ->\n    try request(Handle, stop)\n    catch error:{lawspec, actor_stopped} -> ok end.\nmonitor(Handle, Observer) when is_pid(Observer) -> request(Handle, {observe, Observer}).\nlink(Left = {lawspec_actor, _, _}, Right = {lawspec_actor, _, _}) ->\n    ok = request(Left, {link, Right}),\n    request(Right, {link, Left}).\nchild(Supervisor, Name) -> request(Supervisor, {child, Name}).\nchildren(Supervisor) -> request(Supervisor, children).\nworker_pid(Handle) -> request(Handle, worker_pid).\nrequire_worker_pid(Handle) -> case worker_pid(Handle) of\n    Pid when is_pid(Pid) -> Pid;\n    none -> error({lawspec, actor_stopped})\nend.\nmetadata(Handle) -> request(Handle, metadata).\nrestart_count(Supervisor) -> request(Supervisor, restart_count).\n\n%% Gleam's Event and Result constructors have these Erlang representations.\n%% Select only this handle's events, leaving other application messages alone.\nreceive_event(Handle, Milliseconds) when is_integer(Milliseconds), Milliseconds >= 0 ->\n    receive\n        {Tag, Handle, {crashed, Cause}} when Tag =:= lawspec_actor_event; Tag =:= lawspec_supervisor_event ->\n            {ok, {crashed, Cause}};\n        {Tag, Handle, {stopped, none}} when Tag =:= lawspec_actor_event; Tag =:= lawspec_supervisor_event ->\n            {ok, stopped}\n    after Milliseconds -> {error, nil}\n    end.\n\n%% Actors outlive their callers and queued tells still run when their sender\n%% exits. A caller's task cancellation scope must not own a persistent actor.\ncontext() -> lists:keydelete({lawspec_beam_tasks, scopes}, 1,\n    lawspec_beam_runtime:worker_context()).\n\nrequest({Kind, Tree, Id}, Request) when Kind =:= lawspec_actor; Kind =:= lawspec_supervisor ->\n    Result = try gen_server:call(Tree, {request, Id, Request}, infinity)\n        catch exit:{_, {gen_server, call, [Tree, _, infinity]}} -> stopped end,\n    case Result of\n        {ok, Value} -> Value;\n        {crashed, Cause} -> error({lawspec, {actor_crashed, Cause}});\n        stopped -> error({lawspec, actor_stopped});\n        {error, Reason} -> error({lawspec, Reason})\n    end.\n"
runtimeSource "beam-actor" = "%% @doc One actor's state-owning gen_server. A successful handler commits its\n%% checkpoint before replying; an exception never commits a partial state.\n%% ref:DEC-actors-otp-supervision\n-module(lawspec_beam_actor).\n-behaviour(gen_server).\n-export([start_link/2]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2]).\n\nstart_link(Tree, Id) -> gen_server:start_link(?MODULE, {Tree, Id, self()}, []).\n\ninit({Tree, Id, Parent}) ->\n    process_flag(trap_exit, true),\n    Worker = self(),\n    Guard = spawn(fun() -> guard(Tree, Parent, Worker) end),\n    receive {Guard, ready} -> ok end,\n    case gen_server:call(Tree, {actor_started, Id, self()}, infinity) of\n        stopped -> ignore;\n        {ok, Spec, Checkpoint} ->\n            try\n                Initial = scoped(Tree, Id, fun() -> lawspec_beam_runtime:with_worker_context(maps:get(context, Spec), fun() ->\n                    case Checkpoint of\n                        none -> (maps:get(start, Spec))();\n                        {resume, Previous} -> Previous;\n                        {some, Previous} -> (maps:get(restart, Spec))(Previous)\n                    end\n                end) end),\n                ok = gen_server:call(Tree, {ready, Id, self(), Initial}, infinity),\n                {ok, #{tree => Tree, id => Id, value => Initial, spec => Spec, guard => Guard}}\n            catch Class:Reason:Stack ->\n                gen_server:call(Tree, {start_failed, Id, self(), {Class, Reason, Stack}}, infinity),\n                {stop, {actor_start_failed, Class, Reason}}\n            end\n    end.\n\nhandle_call(_, _, State) -> {reply, {error, unsupported}, State}.\nhandle_cast(_, State) -> {noreply, State}.\n\nhandle_info({deliver, Token, Operation}, State = #{tree := Tree, id := Id, value := Value}) ->\n    case gen_server:call(Tree, {begin_message, Id, self(), Token}, infinity) of\n        false -> {noreply, State};\n        true -> execute(Operation, Token, Value, State)\n    end;\nhandle_info(_, State) -> {noreply, State}.\n\nexecute({handler, Handler, Context}, Token, Value, State = #{tree := Tree, id := Id}) ->\n    Result = try\n        case scoped(Tree, Id, fun() -> lawspec_beam_runtime:with_worker_context(Context, fun() -> Handler(Value) end) end) of\n            {Reply, Next} -> {ok, Reply, Next};\n            Other -> error({lawspec, {invalid_actor_handler_result, Other}})\n        end\n    catch Class:Reason:Stack -> {exception, {Class, Reason, Stack}} end,\n    case Result of\n        {ok, ReplyValue, NextValue} ->\n            ok = gen_server:call(Tree, {commit, Id, self(), Token, ReplyValue, NextValue}, infinity),\n            {noreply, State#{value := NextValue}};\n        {exception, Failure} -> fail(Token, Failure, make_ref(), State)\n    end;\nexecute({crash, Cause, Origin}, Token, _, State) -> fail(Token, Cause, Origin, State);\nexecute(restart, Token, Value, State = #{spec := Spec}) ->\n    Handler = fun(Previous) -> {ok, (maps:get(restart, Spec))(Previous)} end,\n    execute({handler, Handler, maps:get(context, Spec)}, Token, Value, State);\nexecute(stop, Token, _, State = #{tree := Tree, id := Id}) ->\n    Action = gen_server:call(Tree, {worker_stopped, Id, self(), Token}, infinity),\n    finish(Action, normal, State).\n\nfail(Token, Cause, Origin, State = #{tree := Tree, id := Id}) ->\n    Action = gen_server:call(Tree, {failed, Id, self(), Token, Cause, Origin}, infinity),\n    finish(Action, {actor_crashed, Cause}, State).\n\nfinish(wait, _, State) -> {noreply, State};\nfinish(exit, Reason, State) -> {stop, Reason, State}.\n\n%% Each operation owns its nested async workers. The stable service joins\n%% this scope on worker death before allowing a replacement to run.\nscoped(Tree, Id, Body) -> lawspec_beam_tasks:with_scope(fun(Scope) ->\n    case gen_server:call(Tree, {scope, Id, self(), Scope}, infinity) of\n        ok -> Body();\n        stopped -> exit(shutdown)\n    end\nend).\n\n%% A killed supervisor cannot enforce its own shutdown timeout. A separate\n%% monitor keeps that bound even while a native handler or init callback is\n%% blocked. It never executes application code and ends with its worker.\nguard(Tree, Parent, Worker) ->\n    WorkerMonitor = erlang:monitor(process, Worker),\n    TreeMonitor = erlang:monitor(process, Tree),\n    ParentMonitor = erlang:monitor(process, Parent),\n    Worker ! {self(), ready},\n    receive\n        {'DOWN', WorkerMonitor, process, Worker, _} -> ok;\n        {'DOWN', Monitor, process, _, _} when Monitor =:= TreeMonitor; Monitor =:= ParentMonitor ->\n            receive\n                {'DOWN', WorkerMonitor, process, Worker, _} -> ok\n            after 5000 ->\n                exit(Worker, kill),\n                receive {'DOWN', WorkerMonitor, process, Worker, _} -> ok end\n            end\n    end.\n"
runtimeSource "beam-actor_sup" = "%% @doc The actual OTP supervision tree. The stable mailbox service retains\n%% checkpoints across replacement of both workers and nested supervisors.\n%% ref:DEC-actors-otp-supervision ref:erlang-otp-supervisors\n-module(lawspec_beam_actor_sup).\n-behaviour(supervisor).\n-export([start_root/2, start_link/2, start_actor/2, child_spec/4]).\n-export([init/1]).\n\nstart_root(Tree, Spec) -> supervisor:start_link(?MODULE, {root, Tree, Spec}).\nstart_link(Tree, Id) ->\n    case supervisor:start_link(?MODULE, {nested, Tree, Id}) of\n        {ok, Pid} = Result ->\n            ok = gen_server:call(Tree, {supervisor_ready, Id, Pid}, infinity),\n            Result;\n        Other -> Other\n    end.\n\nstart_actor(Tree, Id) ->\n    case gen_server:call(Tree, {eligible, Id}, infinity) of\n        true -> lawspec_beam_actor:start_link(Tree, Id);\n        false -> ignore\n    end.\n\nchild_spec(Tree, Id, Lifetime, Kind) ->\n    Function = case Kind of actor -> start_actor; supervisor -> start_link end,\n    #{id => Id, start => {?MODULE, Function, [Tree, Id]}, restart => Lifetime,\n        shutdown => case Kind of actor -> 5000; supervisor -> infinity end,\n        type => case Kind of actor -> worker; supervisor -> supervisor end,\n        modules => [case Kind of actor -> lawspec_beam_actor; supervisor -> ?MODULE end]}.\n\ninit({root, _, Spec}) -> {ok, {flags(Spec), []}};\ninit({nested, Tree, Id}) ->\n    case gen_server:call(Tree, {supervisor_started, Id, self()}, infinity) of\n        {ok, Spec, Children} -> {ok, {flags(Spec), Children}};\n        stopped -> ignore\n    end.\n\nflags(Spec) ->\n    %% OTP's intensity window is measured in whole seconds. LawSpec permits\n    %% microsecond windows, so the mailbox service applies its exact rolling\n    %% budget before releasing a failure to OTP. OTP performs all child\n    %% termination, strategy ordering, lifetime decisions and replacements.\n    %% A one-second OTP window can span almost two real seconds because its\n    %% timestamps are whole seconds. Bound all the exact windows it can\n    %% contain, with room for the final failed attempt that stops the tree.\n    Windows = 2000000 div maps:get(period, Spec, 5000000) + 1,\n    Intensity = max(1, maps:get(restarts, Spec, 3) * Windows + 1),\n    #{strategy => maps:get(strategy, Spec, one_for_one),\n        intensity => Intensity, period => 1}.\n"
runtimeSource "beam-actor_tree" = "%% @doc Stable mailboxes and committed checkpoints for an OTP supervision tree.\n%% No application handler runs here. Real gen_server children own execution;\n%% real OTP supervisors replace them, in their declared strategy and order.\n%% ref:DEC-actors-otp-supervision ref:erlang-otp-supervisors\n-module(lawspec_beam_actor_tree).\n-behaviour(gen_server).\n-export([start/1, start_owned/1, start_link/1]).\n-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2]).\n\nstart(Spec) -> start(Spec, false).\nstart_owned(Spec) -> start(Spec, true).\nstart(Spec, Owned) ->\n    case launch(Spec, start, Owned) of\n        {ok, _, Handle} -> Handle;\n        {error, Reason} -> error({lawspec, {actor_start_failed, Reason}})\n    end.\n\nstart_link(Spec) ->\n    case launch(Spec, start_link, false) of\n        {ok, Tree, _} -> {ok, Tree};\n        {error, Reason} -> {error, Reason}\n    end.\n\nlaunch(Spec, Start, Owned) ->\n    {Root, Public, Standalone} = case maps:get(kind, Spec) of\n        actor -> {lawspec_beam_actors:supervisor(one_for_one, 0, 1, [{actor, temporary, Spec}]), [actor], true};\n        supervisor -> {Spec, [], false}\n    end,\n    case gen_server:Start(?MODULE, {self(), Root, Public, Standalone, Owned}, []) of\n        {ok, Tree} ->\n            case gen_server:call(Tree, await_start, infinity) of\n                {ok, Handle} -> {ok, Tree, Handle};\n                {error, Reason} -> {error, Reason}\n            end;\n        {error, Reason} -> {error, Reason}\n    end.\n\ninit({Owner, Spec, Public, Standalone, Owned}) ->\n    process_flag(trap_exit, true),\n    Nodes = allocate(Spec, [], none, permanent, #{}),\n    {ok, Root} = lawspec_beam_actor_sup:start_root(self(), Spec),\n    RootMonitor = erlang:monitor(process, Root),\n    RootNode = (maps:get([], Nodes))#{pid := Root, monitor := RootMonitor, status := ready},\n    State = #{tree => self(), nodes => Nodes#{[] := RootNode}, public => Public, standalone => Standalone,\n        owner => erlang:monitor(process, Owner), owned => Owned, boot => starting, starters => [], start_delivered => false,\n        stops => #{}, stopping => #{}, root => Root, root_monitor => RootMonitor},\n    Tree = self(),\n    spawn_link(fun() ->\n        Result = try\n            lists:foreach(fun(Child) ->\n                case supervisor:start_child(Root, Child) of\n                    {ok, _} -> ok;\n                    {ok, _, _} -> ok;\n                    {error, Why} -> throw(Why)\n                end\n            end, child_specs([], State)),\n            ok\n        catch Class:Reason -> {error, {Class, Reason}} end,\n        Tree ! {booted, Result}\n    end),\n    {ok, State}.\n\nhandle_call(await_start, From, State = #{boot := starting, starters := Waiters}) ->\n    {noreply, State#{starters := [From | Waiters]}};\nhandle_call(await_start, _, State = #{boot := ready, public := Id}) ->\n    {reply, {ok, handle(Id, State)}, State#{start_delivered := true}};\nhandle_call(await_start, _, State = #{boot := {failed, Reason}}) ->\n    case maps:get(pid, node([], State)) of\n        none -> {stop, normal, {error, Reason}, State#{start_delivered := true}};\n        _ -> {reply, {error, Reason}, State#{start_delivered := true}}\n    end;\nhandle_call({eligible, Id}, _, State) -> {reply, not maps:get(removed, node(Id, State)), State};\nhandle_call({supervisor_started, Id, Pid}, From, State) -> claim(Id, Pid, From, State);\nhandle_call({actor_started, Id, Pid}, From, State) -> claim(Id, Pid, From, State);\nhandle_call({supervisor_ready, Id, Pid}, _, State) ->\n    case node(Id, State) of\n        Node = #{pid := Pid} ->\n            Ready = put_node(Id, Node#{status := ready, restarting := false}, State),\n            {reply, ok, progress(resolve(Id, Ready))};\n        _ -> {reply, ok, State}\n    end;\nhandle_call({ready, Id, Pid, Value}, _, State) ->\n    case node(Id, State) of\n        Node = #{pid := Pid, retiring := Pid} ->\n            {reply, ok, put_node(Id, Node#{checkpoint := {some, Value}, scope := none}, State)};\n        Node = #{pid := Pid} ->\n            Ready = put_node(Id, Node#{checkpoint := {some, Value}, status := ready, restarting := false,\n                restore := restart, scope := none}, State),\n            {reply, ok, progress(resolve(Id, Ready))};\n        _ -> {reply, ok, State}\n    end;\nhandle_call({start_failed, Id, Pid, Cause}, _, State) ->\n    case node(Id, State) of\n        #{pid := Pid, removed := false} ->\n            {_, Updated} = failure(Id, none, Cause, make_ref(), State),\n            {reply, ok, Updated};\n        _ -> {reply, ok, State}\n    end;\nhandle_call({scope, Id, Pid, Scope}, _, State) ->\n    case node(Id, State) of\n        Node = #{pid := Pid, removed := false} -> {reply, ok, put_node(Id, Node#{scope := Scope}, State)};\n        _ -> {reply, stopped, State}\n    end;\nhandle_call({begin_message, Id, Pid, Token}, _, State) ->\n    case node(Id, State) of\n        Node = #{pid := Pid, active := Entry = #{token := Token}} ->\n            {reply, true, put_node(Id, Node#{active := Entry#{begun := true}}, State)};\n        _ -> {reply, false, State}\n    end;\nhandle_call({commit, Id, Pid, Token, Reply, Value}, _, State) ->\n    case node(Id, State) of\n        Node = #{pid := Pid, active := Entry = #{token := Token}} ->\n            reply(Entry, {ok, Reply}),\n            {reply, ok, progress(put_node(Id, Node#{checkpoint := {some, Value}, active := none, scope := none}, State))};\n        _ -> {reply, ok, State}\n    end;\nhandle_call({failed, Id, Pid, Token, Cause, Origin}, _, State) ->\n    case node(Id, State) of\n        #{pid := Pid, active := Entry = #{token := Token}} ->\n            {Action, Updated} = failure(Id, Entry, Cause, Origin, State),\n            {reply, Action, progress(Updated)};\n        _ -> {reply, exit, State}\n    end;\nhandle_call({worker_stopped, Id, Pid, Token}, _, State) ->\n    case node(Id, State) of\n        Node = #{pid := Pid, active := Entry = #{token := Token}} ->\n            Waiting = put_node(Id, Node#{active := none, status := failed,\n                completion := [{Entry, {ok, ok}, none} | maps:get(completion, Node)]}, State),\n            {Target, Updated} = decide(Id, normal, Waiting),\n            {Action, Stopping} = trigger(Target, Id, Updated),\n            {reply, Action, progress(Stopping)};\n        _ -> {reply, exit, State}\n    end;\nhandle_call({request, Id, Request}, From, State) -> request(Id, Request, From, State).\n\nhandle_cast(_, State) -> {noreply, State}.\n\nhandle_info({booted, ok}, State = #{boot := starting, starters := Waiters, public := Id}) ->\n    case maps:get(owned, State) of false -> erlang:demonitor(maps:get(owner, State), [flush]); true -> ok end,\n    lists:foreach(fun(From) -> gen_server:reply(From, {ok, handle(Id, State)}) end, Waiters),\n    {noreply, State#{boot := ready, starters := [], start_delivered := Waiters =/= []}};\nhandle_info({booted, {error, Reason}}, State = #{starters := Waiters}) ->\n    lists:foreach(fun(From) -> gen_server:reply(From, {error, Reason}) end, Waiters),\n    finish_tree(abort_tree(State#{boot := {failed, Reason}, starters := [], start_delivered := Waiters =/= []}));\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{owner := Monitor, boot := starting}) ->\n    finish_tree(abort_tree(State#{boot := {failed, owner_stopped}, start_delivered := true}));\nhandle_info({'DOWN', Monitor, process, _, _}, State = #{owner := Monitor, owned := true}) ->\n    finish_tree(abort_tree(State));\nhandle_info({'DOWN', Monitor, process, Pid, Reason}, State) ->\n    case [Id || {Id, #{pid := P, monitor := M}} <- maps:to_list(maps:get(nodes, State)), P =:= Pid, M =:= Monitor] of\n        [Id] -> finish_tree(progress(activate_claims(down(Id, Reason, State))));\n        [] -> {noreply, State}\n    end;\nhandle_info({linked_crash, Id, Cause, Origin}, State) ->\n    Node = node(Id, State),\n    case maps:get(accepting, Node) andalso not maps:is_key(Origin, maps:get(seen, Node)) of\n        true ->\n            Seen = maps:get(seen, Node),\n            Entry = entry(none, {crash, Cause, Origin}),\n            Updated = put_node(Id, Node#{seen := Seen#{Origin => true},\n                waiting := queue:in(Entry, maps:get(waiting, Node))}, State),\n            {noreply, progress(Updated)};\n        false -> {noreply, State}\n    end;\nhandle_info({stopped_supervisor, Id, Pid}, State = #{stopping := Stopping}) ->\n    Next = case maps:get(Id, Stopping, none) of Pid -> maps:remove(Id, Stopping); _ -> Stopping end,\n    {noreply, State#{stopping := Next}};\nhandle_info({shutdown_observed, Id, ParentPid}, State) ->\n    Node = node(Id, State),\n    case {maps:get(shutdown_wait, Node), maps:get(pid, Node), is_process_alive(ParentPid)} of\n        {ParentPid, none, true} ->\n            %% The parent has finished handling its exit and did not start a\n            %% replacement. A normally stopped transient/temporary is gone.\n            {noreply, progress(halt_subtree(Id, State))};\n        _ -> {noreply, State}\n    end;\nhandle_info(_, State) -> {noreply, State}.\n\nterminate(_, State) ->\n    %% The root is linked to this service as its OTP parent. It shuts its\n    %% children down if the service dies, including an untrappable kill.\n    maps:foreach(fun(_, Node) ->\n        reply(maps:get(active, Node), stopped),\n        lists:foreach(fun(E) -> reply(E, stopped) end, queue:to_list(maps:get(waiting, Node))),\n        lists:foreach(fun({E, Result, _}) -> reply(E, Result) end, maps:get(completion, Node))\n    end, maps:get(nodes, State)).\n\nrequest(Id, {enqueue, call, _} = Request, From = {Caller, _}, State) ->\n    case maps:get(pid, node(Id, State)) of\n        Caller -> {reply, {error, actor_self_call}, State};\n        _ -> enqueue(Id, Request, From, State)\n    end;\nrequest(Id, {enqueue, tell, _} = Request, From, State) -> enqueue(Id, Request, From, State);\nrequest(Id, {observe, Observer}, _, State) ->\n    Node = node(Id, State),\n    {reply, {ok, ok}, put_node(Id, Node#{observers := lists:usort([Observer | maps:get(observers, Node)])}, State)};\nrequest(Id, {link, Other}, _, State) ->\n    Node = node(Id, State),\n    {reply, {ok, ok}, put_node(Id, Node#{links := lists:usort([Other | maps:get(links, Node)])}, State)};\nrequest(Id, worker_pid, _, State) -> {reply, {ok, maps:get(pid, node(Id, State))}, State};\nrequest(Id, metadata, _, State) ->\n    {reply, {ok, maps:get(metadata, maps:get(spec, node(Id, State)), undefined)}, State};\nrequest(Id, restart_count, _, State) -> {reply, {ok, length(maps:get(restarts, node(Id, State)))}, State};\nrequest(Id, children, _, State) ->\n    {reply, {ok, [{Name, handle(Child, State)} || {Name, Child} <- live_children(Id, State)]}, State};\nrequest(Id, {child, Name}, _, State) ->\n    case lists:keyfind(Name, 1, maps:get(children, node(Id, State))) of\n        {Name, Child} -> {reply, {ok, handle(Child, State)}, State};\n        false -> {reply, {error, {unknown_child, Name}}, State}\n    end;\nrequest(Id, stop, From = {Caller, _}, State) ->\n    case lists:any(fun(Child) -> maps:get(pid, node(Child, State)) =:= Caller end, subtree(Id, State)) of\n        true -> {reply, {error, actor_self_stop}, State};\n        false -> request_stop(Id, From, State)\n    end.\n\nenqueue(Id, {enqueue, Mode, Operation}, From, State) ->\n    Node = node(Id, State),\n    case maps:get(kind, Node) =:= actor andalso maps:get(accepting, Node) of\n        false -> {reply, stopped, State};\n        true ->\n            Entry = entry(case Mode of call -> From; tell -> none end, Operation),\n            Updated = progress(put_node(Id, Node#{waiting := queue:in(Entry, maps:get(waiting, Node))}, State)),\n            case Mode of call -> {noreply, Updated}; tell -> {reply, {ok, ok}, Updated} end\n    end.\n\nrequest_stop(Id, From, State) ->\n    Node = node(Id, State),\n    case {maps:get(kind, Node), maps:get(removed, Node), maps:get(closing, Node)} of\n        {_, true, _} -> {reply, {ok, ok}, State};\n        {actor, _, _} ->\n            Permanent = maps:get(parent, Node) =/= none andalso maps:get(lifetime, Node) =:= permanent,\n            Updated = put_node(Id, Node#{accepting := Permanent,\n                waiting := queue:in(entry(From, stop), maps:get(waiting, Node))}, State),\n            {noreply, progress(Updated)};\n        {supervisor, _, _} ->\n            Stops = maps:get(stops, State),\n            Closing = close_subtree(Id, State#{stops := Stops#{Id => [From | maps:get(Id, Stops, [])]}}),\n            {noreply, progress(Closing)}\n    end.\n\nallocate(Spec, Id, Parent, Lifetime, Nodes) ->\n    Children = [{Name, Id ++ [Name]} || {Name, _, _} <- maps:get(children, Spec, [])],\n    Node = #{kind => maps:get(kind, Spec), spec => Spec, parent => Parent, lifetime => Lifetime,\n        children => Children, pid => none, monitor => none, retiring => none, status => dormant,\n        checkpoint => none, restore => restart, waiting => queue:new(), active => none,\n        completion => [], claim => none, scope => none,\n        shutdown_wait => none,\n        accepting => true, removed => false, restarting => false, closing => false,\n        observers => [], links => [], seen => #{}, restarts => [], stop_notified => false},\n    lists:foldl(fun({Name, Life, Child}, Acc) -> allocate(Child, Id ++ [Name], Id, Life, Acc) end,\n        Nodes#{Id => Node}, maps:get(children, Spec, [])).\n\nnode(Id, State) -> maps:get(Id, maps:get(nodes, State)).\nput_node(Id, Node, State) -> State#{nodes := (maps:get(nodes, State))#{Id := Node}}.\neligible(Node) -> not maps:get(removed, Node) andalso not maps:get(closing, Node).\nhandle(Id, State) ->\n    Kind = case maps:get(kind, node(Id, State)) of actor -> lawspec_actor; supervisor -> lawspec_supervisor end,\n    {Kind, maps:get(tree, State), Id}.\nlive_children(Id, State) -> [{Name, Child} || {Name, Child} <- maps:get(children, node(Id, State)),\n    not maps:get(removed, node(Child, State))].\nchild_specs(Id, State) -> [lawspec_beam_actor_sup:child_spec(maps:get(tree, State), Child,\n    maps:get(lifetime, node(Child, State)), maps:get(kind, node(Child, State))) || {_, Child} <- live_children(Id, State)].\n\nregister_pid(Id, Pid, State) ->\n    Node = node(Id, State),\n    case maps:get(monitor, Node) of none -> ok; Monitor -> erlang:demonitor(Monitor, [flush]) end,\n    put_node(Id, Node#{pid := Pid, monitor := erlang:monitor(process, Pid), retiring := none, status := starting}, State).\n\n%% A killed supervisor can be replaced before its old children finish. Hold\n%% replacement init until the previous worker's DOWN has been observed, so a\n%% still-running handler can commit once and no two generations share a state.\nclaim(Id, Pid, From, State) ->\n    Node = node(Id, State),\n    case maps:get(claim, Node) of none -> ok; {_, Previous} -> gen_server:reply(Previous, stopped) end,\n    Claimed = put_node(Id, Node#{claim := {Pid, From}}, State),\n    {noreply, activate_claims(Claimed)}.\n\nactivate_claims(State) ->\n    %% A sibling's shutdown can be observed before the original child's\n    %% failure. Account for every already-dead process before starting any\n    %% replacement, including the first child in a one_for_all restart.\n    PendingDown = lists:any(fun(Node) -> case maps:get(pid, Node) of\n        none -> false;\n        Pid -> not is_process_alive(Pid)\n    end end, maps:values(maps:get(nodes, State))),\n    case PendingDown of\n        true -> State;\n        false -> lists:foldl(fun(Id, Acc) -> case maps:get(pid, node(Id, Acc)) of\n            none -> activate_claim(Id, Acc);\n            _ -> Acc\n        end end, State, maps:keys(maps:get(nodes, State)))\n    end.\n\nactivate_claim(Id, State) ->\n    Node = node(Id, State),\n    case {maps:get(claim, Node), maps:get(shutdown_wait, Node)} of\n        {none, _} -> State;\n        {{_, _}, Waiting} when Waiting =/= none ->\n            %% OTP selected a replacement for a direct shutdown of a\n            %% permanent child. A group restart clears this flag as a unit.\n            {Target, Decided} = decide(Id, normal, put_node(Id, Node#{shutdown_wait := none}, State)),\n            Planned = case Target of Id -> Decided;\n                _ -> stop_supervisor(Target, {lawspec_restart_limit, Target}, Decided)\n            end,\n            activate_claim(Id, Planned);\n        {{Pid, From}, none} ->\n            Cleared = put_node(Id, Node#{claim := none}, State),\n            case {maps:get(removed, Node), is_process_alive(Pid)} of\n                {true, _} -> gen_server:reply(From, stopped), Cleared;\n                {_, false} -> Cleared;\n                {false, true} ->\n                    Registered = register_pid(Id, Pid, Cleared),\n                    case maps:get(kind, Node) of\n                        actor ->\n                            Checkpoint = case {maps:get(restore, Node), maps:get(checkpoint, Node)} of\n                                {resume, {some, Value}} -> {resume, Value};\n                                {_, Previous} -> Previous\n                            end,\n                            gen_server:reply(From, {ok, maps:get(spec, Node), Checkpoint}),\n                            Registered;\n                        supervisor ->\n                            Starting = put_node(Id, (node(Id, Registered))#{restarts := []}, Registered),\n                            gen_server:reply(From, {ok, maps:get(spec, Node), child_specs(Id, Starting)}),\n                            Starting\n                    end\n            end\n    end.\n\nentry(From, Operation) -> #{from => From, operation => Operation, token => make_ref(), begun => false}.\nreply(none, _) -> ok;\nreply(#{from := none}, _) -> ok;\nreply(#{from := From}, Result) -> gen_server:reply(From, Result).\n\nprogress(Initial) ->\n    State = maybe_close_standalone(Initial),\n    Dispatched = maps:fold(fun(Id, Node, Acc) ->\n        case {maps:get(kind, Node), maps:get(status, Node), maps:get(restarting, Node), maps:get(active, Node)} of\n            {actor, ready, false, none} ->\n                case queue:out(maps:get(waiting, Node)) of\n                    {empty, _} -> Acc;\n                    {{value, Entry}, Rest} ->\n                        maps:get(pid, Node) ! {deliver, maps:get(token, Entry), maps:get(operation, Entry)},\n                        put_node(Id, Node#{active := Entry, waiting := Rest}, Acc)\n                end;\n            _ -> Acc\n        end\n    end, State, maps:get(nodes, State)),\n    ReadyStops = [Id || {Id, #{kind := supervisor, closing := true, pid := Pid}} <- maps:to_list(maps:get(nodes, Dispatched)),\n        is_pid(Pid), not maps:is_key(Id, maps:get(stopping, Dispatched)),\n        not parent_closing(Id, Dispatched), idle_subtree(Id, Dispatched)],\n    finish_ready_stops(lists:foldl(fun begin_stop/2, Dispatched, ReadyStops)).\n\nbegin_stop(Id, State) ->\n    Node = node(Id, State),\n    case maps:get(parent, Node) =/= none andalso maps:get(lifetime, Node) =:= permanent of\n        false -> stop_supervisor(Id, normal, State);\n        true ->\n            Reopened = map_subtree(Id, fun(N) -> N#{closing := false, accepting := not maps:get(removed, N)} end, State),\n            {Target, Decided} = decide(Id, normal, Reopened),\n            Reason = case Target of Id -> normal; _ -> {lawspec_restart_limit, Target} end,\n            stop_supervisor(Target, Reason, Decided)\n    end.\n\nfailure(Id, Entry, Cause, Origin, State) ->\n    Node = node(Id, State),\n    Result = case Entry of #{operation := {crash, _, _}} -> {ok, ok}; _ -> {crashed, Cause} end,\n    Seen = maps:get(seen, Node),\n    Failed = put_node(Id, Node#{active := none, status := failed, seen := Seen#{Origin => true}, scope := none,\n        completion := maps:get(completion, Node) ++ [{Entry, Result, {crashed, Cause, Origin}}]}, State),\n    {Target, Updated} = decide(Id, abnormal, Failed),\n    trigger(Target, Id, Updated).\n\n%% Exact rolling restart budgets, including escalation. A failing worker is\n%% held alive when its supervisor must fail: this lets OTP stop the whole\n%% subtree before its parent starts the replacement supervisor.\ndecide(Id, Termination, State) -> decide(Id, Termination, Id, State).\ndecide(Id, Termination, Origin, State) ->\n    Node = node(Id, State),\n    Restart = eligible(Node) andalso (maps:get(lifetime, Node) =:= permanent orelse\n        (maps:get(lifetime, Node) =:= transient andalso Termination =:= abnormal)),\n    case {maps:get(parent, Node), Restart} of\n        {none, _} -> {Id, terminal_failure(Id, Termination, State)};\n        {_, false} -> {Id, terminal_failure(Id, Termination, State)};\n        {Parent, true} ->\n            Supervisor = node(Parent, State),\n            Spec = maps:get(spec, Supervisor),\n            Now = erlang:monotonic_time(microsecond),\n            Recent = [T || T <- maps:get(restarts, Supervisor), Now - T =< maps:get(period, Spec)],\n            case length(Recent) < maps:get(restarts, Spec) andalso eligible(Supervisor) of\n                true ->\n                    Charged = put_node(Parent, Supervisor#{restarts := Recent ++ [Now]}, State),\n                    {Id, restart_group(Parent, Id, Origin, Charged)};\n                false -> decide(Parent, abnormal, Origin, State)\n            end\n    end.\n\n%% OTP replaces sibling processes immediately, but LawSpec's logical sibling\n%% restart belongs after every message already accepted at the time of the\n%% crash. A replacement resumes its checkpoint and drains that prefix before\n%% executing the restart entry; the failed actor itself restarts during init.\n%% Carry the original actor through escalation so the same order holds when\n%% an ancestor supervisor, and therefore its entire subtree, is replaced.\nrestart_group(Parent, Failed, Origin, State) ->\n    Children = [Id || {_, Id} <- live_children(Parent, State)],\n    Group = case maps:get(strategy, maps:get(spec, node(Parent, State))) of\n        one_for_one -> [Failed];\n        one_for_all -> Children;\n        rest_for_one -> lists:dropwhile(fun(Id) -> Id =/= Failed end, Children)\n    end,\n    lists:foldl(fun(Id, Acc) ->\n        case maps:get(lifetime, node(Id, Acc)) of\n            temporary -> halt_subtree(Id, Acc);\n            _ -> lists:foldl(fun(Child, Updated) ->\n                Node = node(Child, Updated),\n                case maps:get(removed, Node) of\n                    true -> Updated;\n                    false ->\n                        Restarting = Node#{restarting := true, retiring := maps:get(pid, Node), closing := false,\n                            accepting := true, shutdown_wait := none},\n                        Next = case maps:get(kind, Node) =:= actor andalso Child =/= Origin of\n                            true -> Restarting#{restore := resume,\n                                waiting := queue:in(entry(none, restart), maps:get(waiting, Node))};\n                            false -> Restarting#{restore := restart}\n                        end,\n                        put_node(Child, Next, Updated)\n                end\n            end, Acc, subtree(Id, Acc))\n        end\n    end, State, Group).\n\ntrigger(Id, Id, State) -> {exit, State};\ntrigger(Target, _, State) -> {wait, stop_supervisor(Target, {lawspec_restart_limit, Target}, State)}.\n\nstop_supervisor(Id, Reason, State = #{stopping := Stopping}) ->\n    Pid = maps:get(pid, node(Id, State)),\n    case maps:get(Id, Stopping, none) =:= Pid of\n        true -> State;\n        false ->\n            Tree = self(),\n            spawn(fun() ->\n                try gen_server:stop(Pid, Reason, infinity) catch exit:_ -> ok end,\n                Tree ! {stopped_supervisor, Id, Pid}\n            end),\n            State#{stopping := Stopping#{Id => Pid}}\n    end.\n\ndown(Id, Reason, State) ->\n    Node = node(Id, State),\n    close_scope(Node),\n    Cleared = put_node(Id, Node#{pid := none, monitor := none, scope := none}, State#{stopping := maps:remove(Id, maps:get(stopping, State))}),\n    Retiring = maps:get(restarting, Node) andalso maps:get(retiring, Node) =:= maps:get(pid, Node),\n    case {Id, maps:get(removed, Node), maps:get(closing, Node), Retiring, maps:get(status, Node)} of\n        {[], Removed, Closing, _, _} ->\n            maps:foreach(fun(_, N) -> close_scope(N) end, maps:get(nodes, Cleared)),\n            Termination = case Removed orelse Closing orelse normal_exit(Reason) of\n                true -> normal; false -> {abnormal, {exit, Reason, []}}\n            end,\n            finish_stops([], terminal_failure([], Termination, Cleared));\n        {_, true, _, _, _} -> maybe_close_standalone(finish_stops(Id, Cleared));\n        {_, _, true, _, _} ->\n            finish_stops(Id, halt_subtree(Id, Cleared));\n        {_, _, _, true, _} -> interrupted(Id, Reason, Cleared);\n        {_, _, _, _, failed} -> Cleared;\n        {_, _, _, _, _} when Reason =:= shutdown -> passive_shutdown(Id, Reason, Cleared);\n        _ ->\n            Interrupted = interrupted(Id, Reason, Cleared),\n            case ancestor_dead(Id, Interrupted) of\n                true ->\n                    WaitingNode = node(Id, Interrupted),\n                    put_node(Id, WaitingNode#{restarting := true}, Interrupted);\n                false -> unexpected_down(Id, Reason, Interrupted)\n            end\n    end.\n\npassive_shutdown(Id, Reason, State) ->\n    Interrupted = interrupted(Id, Reason, State),\n    Node = node(Id, Interrupted), Parent = maps:get(parent, Node),\n    ParentPid = maps:get(pid, node(Parent, Interrupted)),\n    case ParentPid of\n        none -> put_node(Id, Node#{restarting := true}, Interrupted);\n        _ ->\n            %% Never wait for a busy supervisor inside the mailbox service:\n            %% that supervisor may itself be starting a child which needs us.\n            Tree = self(),\n            spawn(fun() ->\n                try supervisor:which_children(ParentPid) catch exit:_ -> ok end,\n                Tree ! {shutdown_observed, Id, ParentPid}\n            end),\n            put_node(Id, Node#{restarting := true, shutdown_wait := ParentPid}, Interrupted)\n    end.\n\nnormal_exit(normal) -> true;\nnormal_exit(shutdown) -> true;\nnormal_exit({shutdown, _}) -> true;\nnormal_exit(_) -> false.\n\nancestor_dead(Id, State) -> case maps:get(parent, node(Id, State)) of\n    none -> false;\n    Parent -> case maps:get(pid, node(Parent, State)) of\n        none -> true;\n        Pid -> not is_process_alive(Pid) orelse ancestor_dead(Parent, State)\n    end\nend.\n\nunexpected_down(Id, Reason, State) ->\n    Node = node(Id, State),\n    Normal = normal_exit(Reason),\n    Observed = case maps:get(completion, Node) =:= [] andalso not Normal of\n        true -> put_node(Id, Node#{completion :=\n            [{none, {crashed, {exit, Reason, []}}, {crashed, {exit, Reason, []}, make_ref()}}]}, State);\n        false -> State\n    end,\n    {Target, Planned} = decide(Id, case Normal of true -> normal; false -> abnormal end, Observed),\n    case Target of Id -> Planned; _ -> stop_supervisor(Target, {lawspec_restart_limit, Target}, Planned) end.\n\ninterrupted(Id, Reason, State) ->\n    Node = node(Id, State),\n    case maps:get(active, Node) of\n        none -> put_node(Id, Node#{status := dormant}, State);\n        Entry = #{begun := false} -> put_node(Id, Node#{active := none, status := dormant,\n            waiting := queue:in_r(Entry, maps:get(waiting, Node))}, State);\n        Entry ->\n            Cause = {exit, Reason, []},\n            put_node(Id, Node#{active := none, status := dormant,\n                completion := maps:get(completion, Node) ++ [{Entry, {crashed, Cause}, {crashed, Cause, make_ref()}}]}, State)\n    end.\n\nresolve(Id, State) ->\n    Node = node(Id, State),\n    lists:foreach(fun({Entry, Result, Event}) ->\n        reply(Entry, Result),\n        case Event of\n            none -> ok;\n            {crashed, Cause, Origin} ->\n                notify(Id, {crashed, Cause}, State),\n                lists:foreach(fun({lawspec_actor, Tree, Other}) ->\n                    Tree ! {linked_crash, Other, Cause, Origin}\n                end, maps:get(links, Node))\n        end\n    end, maps:get(completion, Node)),\n    Seen = lists:foldl(fun({_, _, Event}, Acc) -> case Event of\n        {crashed, _, Origin} -> Acc#{Origin => true};\n        none -> Acc\n    end end, maps:get(seen, Node), maps:get(completion, Node)),\n    put_node(Id, Node#{completion := [], seen := Seen}, State).\n\nnotify(Id, Event, State) ->\n    Tag = case maps:get(kind, node(Id, State)) of actor -> lawspec_actor_event; supervisor -> lawspec_supervisor_event end,\n    lists:foreach(fun(Pid) -> Pid ! {Tag, handle(Id, State), Event} end, maps:get(observers, node(Id, State))).\n\nmap_subtree(Id, Fun, State) ->\n    lists:foldl(fun(Child, Acc) -> put_node(Child, Fun(node(Child, Acc)), Acc) end,\n        State, subtree(Id, State)).\nsubtree(Id, State) -> [Id | lists:append([subtree(Child, State) || {_, Child} <- maps:get(children, node(Id, State))])].\nidle_subtree(Id, State) -> lists:all(fun(Child) ->\n    Node = node(Child, State), maps:get(active, Node) =:= none andalso queue:is_empty(maps:get(waiting, Node))\nend, subtree(Id, State)).\nclose_subtree(Id, State) -> map_subtree(Id, fun(Node) -> Node#{closing := true, accepting := false} end, State).\nparent_closing(Id, State) -> case maps:get(parent, node(Id, State)) of\n    none -> false;\n    Parent -> maps:get(closing, node(Parent, State))\nend.\n\nterminal_failure(Id, Termination, State) ->\n    Node = node(Id, State),\n    case maps:get(kind, Node) =:= supervisor andalso Termination =/= normal of\n        true ->\n            Cause = case Termination of abnormal -> {restart_limit, Id}; {abnormal, Why} -> Why end,\n            notify(Id, {crashed, Cause}, State),\n            halt_subtree(Id, put_node(Id, Node#{stop_notified := true}, State));\n        false -> halt_subtree(Id, State)\n    end.\n\nhalt_subtree(Id, State) ->\n    lists:foldl(fun(Child, Acc) ->\n        Node = node(Child, Acc),\n        HadCrash = lists:any(fun({_, _, E}) -> E =/= none end, maps:get(completion, Node)),\n        Resolved = resolve(Child, Acc),\n        case maps:get(claim, Node) of none -> ok; {_, From} -> gen_server:reply(From, stopped) end,\n        reply(maps:get(active, Node), stopped),\n        lists:foreach(fun(E) -> reply(E, stopped) end, queue:to_list(maps:get(waiting, Node))),\n        case not maps:get(stop_notified, Node) andalso not HadCrash of\n            true -> notify(Child, {stopped, none}, Resolved);\n            false -> ok\n        end,\n        put_node(Child, (node(Child, Resolved))#{removed := true, accepting := false,\n            restarting := false, status := stopped, active := none, waiting := queue:new(), claim := none,\n            shutdown_wait := none, stop_notified := true}, Resolved)\n    end, State, lists:reverse(subtree(Id, State))).\n\nfinish_stops(Id, State = #{stops := Stops}) ->\n    lists:foreach(fun(From) -> gen_server:reply(From, {ok, ok}) end, maps:get(Id, Stops, [])),\n    State#{stops := maps:remove(Id, Stops)}.\nfinish_ready_stops(State) ->\n    lists:foldl(fun(Id, Acc) ->\n        Node = node(Id, Acc),\n        Ready = not maps:get(closing, Node) andalso lists:all(fun(Child) ->\n            N = node(Child, Acc),\n            maps:get(removed, N) orelse (maps:get(status, N) =:= ready andalso\n                not maps:get(restarting, N) andalso not pending_restart(N))\n        end, subtree(Id, Acc)),\n        case Ready of true -> finish_stops(Id, Acc); false -> Acc end\n    end, State, maps:keys(maps:get(stops, State))).\npending_restart(Node) ->\n    lists:any(fun(Entry) -> case Entry of #{operation := restart} -> true; _ -> false end end,\n        [maps:get(active, Node) | queue:to_list(maps:get(waiting, Node))]).\nmaybe_close_standalone(State = #{standalone := true, public := Id}) ->\n    case maps:get(removed, node(Id, State)) of true -> close_subtree([], State); false -> State end;\nmaybe_close_standalone(State) -> State.\nfinish_tree(State) ->\n    case maps:get(pid, node([], State)) of\n        none -> case maps:get(start_delivered, State) of\n            true -> {stop, normal, State};\n            false -> {noreply, State}\n        end;\n        _ -> {noreply, State}\n    end.\nabort_tree(State) ->\n    %% A start callback may not have returned to OTP yet. Cancelling startup\n    %% must release that init handshake before asking the supervisor to stop.\n    maps:foreach(fun(_, Node) -> case Node of\n        #{kind := actor, status := starting, pid := Pid} when is_pid(Pid) -> exit(Pid, kill);\n        _ -> ok\n    end end, maps:get(nodes, State)),\n    stop_supervisor([], shutdown, halt_subtree([], State)).\n\nclose_scope(Node) -> case maps:get(scope, Node) of\n    none -> ok;\n    Scope -> lawspec_beam_tasks:close(Scope)\nend.\n"
runtimeSource "beam-supervision" = "%% @doc Generated supervision evidence exercises actual OTP processes,\n%% restart strategies, lifetimes, escalation, links and stable mailboxes.\n%% Each check owns its tree; monitor messages stay in the checking worker.\n%% ref:DEC-actors-otp-supervision ref:erlang-otp-supervisors\n-module(lawspec_beam_supervision).\n-export([check/0]).\n\ncheck() -> lawspec_beam_runtime:async_call(fun checks/0).\nchecks() ->\n    lawspec_beam_actors:with_spec(counter(), fun(A) ->\n        expect(initial_increment, 1, bump(A)), fail_call(A), stopped(A)\n    end),\n    lists:foreach(fun({Strategy, Expected}) ->\n        tree(Strategy, 5, counters([a, b, c]), fun(Sup) ->\n            As = children(Sup, [a, b, c]),\n            Before = [lawspec_beam_actors:worker_pid(A) || A <- As],\n            lists:foreach(fun(A) ->\n                {status, _, {module, gen_server}, _} = sys:get_status(lawspec_beam_actors:worker_pid(A)), bump(A)\n            end, As),\n            expect(real_otp_supervisor, 3, length(supervisor:which_children(lawspec_beam_actors:worker_pid(Sup)))),\n            fail_call(lists:nth(2, As)),\n            expect(Strategy, Expected, states(As)),\n            After = [lawspec_beam_actors:worker_pid(A) || A <- As],\n            expect({Strategy, replaced_workers}, [V =:= 0 || V <- Expected],\n                [P =/= Q || {P, Q} <- lists:zip(Before, After)])\n        end)\n    end, [{one_for_one, [1, 0, 1]}, {one_for_all, [0, 0, 0]}, {rest_for_one, [1, 0, 0]}]),\n    lifetimes(), limits(), escalation(), links(), checkpoint_and_mailbox(),\n    lists:foreach(fun queued_sibling_restart/1, [one_for_all, rest_for_one]), ok.\n\ncounter() -> lawspec_beam_actors:actor(fun() -> 0 end, fun(_) -> 0 end).\ncounters(Names) -> [{N, permanent, counter()} || N <- Names].\ntree(Strategy, Limit, Children, Body) ->\n    lawspec_beam_actors:with_spec(lawspec_beam_actors:supervisor(Strategy, Limit, 10000000, Children), Body).\nchildren(Sup, Names) -> [lawspec_beam_actors:child(Sup, N) || N <- Names].\nstates(As) -> [lawspec_beam_actors:state(A) || A <- As].\nbump(A) -> lawspec_beam_actors:call(A, fun(S) -> {S + 1, S + 1} end).\nfail_call(A) ->\n    try lawspec_beam_actors:call(A, fun(_) -> error(supervision_probe) end) of\n        Value -> failure(failing_handler, actor_crashed, Value)\n    catch error:{lawspec, {actor_crashed, {error, supervision_probe, _}}} -> ok end.\nstopped(A) ->\n    try lawspec_beam_actors:state(A) of Value -> failure(stopped_actor, actor_stopped, Value)\n    catch error:{lawspec, actor_stopped} -> ok end.\nexpect(_, Wanted, Wanted) -> ok;\nexpect(Label, Wanted, Actual) -> failure(Label, Wanted, Actual).\nfailure(Label, Wanted, Actual) -> error({lawspec, {supervision_failed, Label, #{expected => Wanted, actual => Actual}}}).\ncrashed(Handle) ->\n    case lawspec_beam_actors:receive_event(Handle, 2000) of\n        {ok, {crashed, _}} -> ok;\n        Other -> failure(crash_monitor, crashed, Other)\n    end.\n\nlifetimes() ->\n    tree(one_for_one, 5, [{p, permanent, counter()}, {t, transient, counter()}, {x, temporary, counter()}], fun(Sup) ->\n        [P, T, X] = children(Sup, [p, t, x]),\n        bump(P), lawspec_beam_actors:stop(P), expect(permanent_normal_stop, 0, lawspec_beam_actors:state(P)),\n        bump(T), fail_call(T), expect(transient_crash, 0, lawspec_beam_actors:state(T)),\n        lawspec_beam_actors:stop(T), stopped(T),\n        fail_call(X), stopped(X), expect(remaining_children, [{p, P}], lawspec_beam_actors:children(Sup))\n    end).\nlimits() ->\n    tree(one_for_one, 2, counters([a, b]), fun(Sup) ->\n        [A, B] = children(Sup, [a, b]),\n        lawspec_beam_actors:monitor(Sup, self()),\n        lists:foreach(fun(_) -> fail_call(A) end, lists:seq(1, 3)),\n        stopped(B), crashed(Sup),\n        expect(one_limit_notification, {error, nil}, lawspec_beam_actors:receive_event(Sup, 0))\n    end).\nescalation() ->\n    InnerSpec = lawspec_beam_actors:supervisor(one_for_one, 1, 10000000, counters([a, b])),\n    tree(one_for_one, 5, [{inner, permanent, InnerSpec}, {c, permanent, counter()}], fun(Sup) ->\n        [Inner, C] = children(Sup, [inner, c]), [A, B] = children(Inner, [a, b]),\n        Old = lawspec_beam_actors:worker_pid(Inner),\n        bump(B), bump(C), fail_call(A), fail_call(A),\n        expect(escalated_children, [0, 0, 1], states([A, B, C])),\n        expect(replaced_inner_supervisor, true, Old =/= lawspec_beam_actors:worker_pid(Inner)),\n        expect(outer_restart_count, 1, lawspec_beam_actors:restart_count(Sup)),\n        expect(fresh_inner_budget, 0, lawspec_beam_actors:restart_count(Inner))\n    end).\nlinks() ->\n    lawspec_beam_actors:with_spec(counter(), fun(A) ->\n        lawspec_beam_actors:with_spec(counter(), fun(B) ->\n            lawspec_beam_actors:link(A, B), lawspec_beam_actors:monitor(B, self()),\n            fail_call(A), crashed(B), stopped(B)\n        end)\n    end),\n    tree(one_for_one, 10, counters([a, b, c]), fun(Sup) ->\n        [A, B, C] = As = children(Sup, [a, b, c]),\n        lawspec_beam_actors:link(A, B), lawspec_beam_actors:link(B, C), lawspec_beam_actors:link(C, A),\n        lists:foreach(fun(X) -> bump(X), lawspec_beam_actors:monitor(X, self()) end, As),\n        fail_call(A), lists:foreach(fun crashed/1, As),\n        expect(link_cycle, [0, 0, 0], states(As)),\n        expect(one_restart_per_linked_actor, 3, lawspec_beam_actors:restart_count(Sup))\n    end).\ncheckpoint_and_mailbox() ->\n    Spec = lawspec_beam_actors:actor(fun() -> 0 end, fun(S) -> S end),\n    tree(one_for_one, 5, [{a, permanent, Spec}], fun(Sup) ->\n        [A] = children(Sup, [a]), bump(A), fail_call(A),\n        expect(committed_checkpoint, 1, lawspec_beam_actors:state(A)),\n        Owner = self(), Worker = lawspec_beam_actors:worker_pid(A),\n        lawspec_beam_actors:monitor(A, Owner),\n        lawspec_beam_actors:tell(A, fun(S) -> Owner ! {entered, self()}, receive finish -> {ok, S + 10} end end),\n        receive {entered, Worker} -> ok after 2000 -> failure(mailbox_handler_started, Worker, timeout) end,\n        lawspec_beam_actors:tell(A, fun(S) -> {ok, S + 2} end),\n        exit(Worker, kill), crashed(A),\n        expect(queued_tell_after_external_kill, 3, lawspec_beam_actors:state(A)),\n        expect(stable_mailbox_handle, A, lawspec_beam_actors:child(Sup, a)),\n        expect(replaced_killed_worker, true, Worker =/= lawspec_beam_actors:worker_pid(A))\n    end).\n\nqueued_sibling_restart(Strategy) ->\n    Owner = self(),\n    Sibling = lawspec_beam_actors:actor(fun() -> 0 end, fun(S) -> Owner ! {restored, S}, 0 end),\n    tree(Strategy, 5, [{a, permanent, counter()}, {b, permanent, Sibling}], fun(Sup) ->\n        [A, B] = children(Sup, [a, b]), Worker = lawspec_beam_actors:worker_pid(B),\n        lawspec_beam_actors:tell(B, fun(S) -> Owner ! {entered, self()}, receive finish -> {ok, S + 1} end end),\n        receive {entered, Worker} -> ok after 2000 -> failure(sibling_started, Worker, timeout) end,\n        try\n            lawspec_beam_actors:tell(B, fun(S) -> Owner ! {queued_checkpoint, S}, {ok, S + 3} end),\n            lawspec_beam_actors:tell(A, fun(_) -> error(supervision_probe) end),\n            wait_for_restart(Sup, erlang:monotonic_time(millisecond) + 2000),\n            %% This tell follows the restart; the two accepted earlier\n            %% belong to the old checkpoint. Their order must survive OTP\n            %% replacing the sibling while its first handler is blocked.\n            lawspec_beam_actors:tell(B, fun(S) -> {ok, S + 10} end), Worker ! finish,\n            expect({Strategy, post_restart_tell}, 10, lawspec_beam_actors:state(B)),\n            receive {queued_checkpoint, Before} -> expect({Strategy, queued_checkpoint}, 1, Before)\n                after 2000 -> failure(queued_checkpoint, 1, timeout) end,\n            receive {restored, Checkpoint} -> expect({Strategy, restart_checkpoint}, 4, Checkpoint)\n                after 2000 -> failure(restart_checkpoint, 4, timeout) end\n        after Worker ! finish end\n    end).\nwait_for_restart(Sup, Deadline) ->\n    case lawspec_beam_actors:restart_count(Sup) of\n        0 ->\n            expect(restart_admitted, true, erlang:monotonic_time(millisecond) < Deadline),\n            receive after 1 -> ok end, wait_for_restart(Sup, Deadline);\n        _ -> ok\n    end.\n"
runtimeSource "beam-gleam-actors" = "// Stable actor addresses and native OTP processes are different identities:\n// a handler restart changes the process and preserves the address.\n// ref:DEC-actors-otp-supervision ref:DEC-idiomatic-generated-types\nimport gleam/dynamic\n\npub type Process\npub type Handle\npub type ChildSpec\n\npub type Event {\n  Crashed(dynamic.Dynamic)\n  Stopped\n}\n\n@external(erlang, \"erlang\", \"self\")\npub fn self() -> Process\n\n// Register the current process with an actor's or supervisor's monitor\n// function first. Messages about other handles stay in the mailbox.\n@external(erlang, \"lawspec_beam_actors\", \"receive_event\")\npub fn receive_event(handle: a, timeout_milliseconds: Int) -> Result(Event, Nil)\n"
runtimeSource "beam-elixir-workflow" = "# ref:DEC-domain-modeling-primitives ref:DEC-idiomatic-generated-types\ndefmodule LawSpec.Workflow do\n  @moduledoc \"\"\"\n  Scoped policy state for generated workflows. Calls and their async workers\n  share this runtime until the callback returns. Time is in microseconds.\n  \"\"\"\n  @opaque runtime :: map()\n  @type event :: {String.t(), String.t(), integer(), boolean()}\n\n  @spec with_virtual(integer(), (runtime() -> result)) :: result when result: var\n  def with_virtual(seed \\\\ 0, body), do: :lawspec_beam_workflow.with_virtual(seed, body)\n\n  @spec with_real(integer(), (runtime() -> result)) :: result when result: var\n  def with_real(seed \\\\ 0, body), do: :lawspec_beam_workflow.with_real(seed, body)\n\n  @spec with_clock((-> integer()), (integer() -> term()), boolean(), integer(), (runtime() -> result)) :: result when result: var\n  def with_clock(now, sleep, virtual, seed \\\\ 0, body),\n    do: :lawspec_beam_workflow.with_clock_callbacks(now, sleep, virtual, seed, body)\n\n  @spec now(runtime()) :: integer()\n  def now(runtime), do: :lawspec_beam_workflow.now(runtime)\n\n  @spec sleep(runtime(), integer()) :: :ok\n  def sleep(runtime, micros), do: :lawspec_beam_workflow.sleep(runtime, micros)\n\n  @doc \"Sets the time of a runtime created with with_virtual.\"\n  @spec set_time(runtime(), integer()) :: :ok\n  def set_time(runtime, micros), do: :lawspec_beam_workflow.set_time(runtime, micros)\n\n  @spec trace(runtime()) :: [event()]\n  def trace(runtime), do: :lawspec_beam_workflow.trace(runtime)\nend\n"
runtimeSource "beam-defaults" = "%% @doc Built-in ability defaults shared by Erlang, Elixir and Gleam.\n%% Values here are logical values; generated interfaces check both native\n%% crossings. Mutable random state belongs to the caller's handler scope.\n%% ref:DEC-typed-core-boundary\n-module(lawspec_beam_defaults).\n-export([handler/1, now_micros/0, sleep_micros/1]).\n-on_load(init_clock/0).\n\ninit_clock() ->\n    Key = {?MODULE, clock_offset},\n    persistent_term:put(Key, persistent_term:get(Key, erlang:time_offset(microsecond))),\n    ok.\n\nhandler(<<\"lawspec.crypto::ability::\", _/binary>> = Key) -> lawspec_beam_crypto:handler(Key);\nhandler(<<\"lawspec.time::ability::Clock\">>) ->\n    stateless(#{\n        <<\"now\">> => fun(_, []) ->\n            data(<<\"lawspec.time::type::Instant::Instant\">>, [now_micros()])\n        end,\n        <<\"sleep\">> => fun(_, [{ls_data, <<\"lawspec.time::type::Duration::Duration\">>, [Micros]}]) ->\n            sleep_micros(Micros), ls_unit\n        end});\nhandler(<<\"lawspec.randomness::ability::Random\">>) ->\n    Seed = try list_to_integer(os:getenv(\"LAWSPEC_SEED\", \"0\")) catch error:badarg -> 0 end,\n    Cell = lawspec_beam_effects:native_cell(Seed band 16#FFFFFFFFFFFFFFFF),\n    stateless(#{<<\"randomBelow\">> => fun(_, [Bound]) ->\n        lawspec_beam_handler:call(Cell, fun(State) ->\n            First = random_step(State),\n            Second = random_step(First),\n            Bits = ((First bsr 32) bsl 32) bor (Second bsr 32),\n            Draw = case Bound > 0 of true -> Bits rem Bound; false -> 0 end,\n            {Draw, Second}\n        end)\n    end});\nhandler(<<\"lawspec.randomness::ability::SecureRandom\">>) ->\n    stateless(#{\n        <<\"secureBytes\">> => fun(_, [Count]) -> crypto:strong_rand_bytes(max(0, Count)) end,\n        <<\"secureBelow\">> => fun(_, [Bound]) -> secure_below(Bound) end,\n        <<\"secureToken\">> => fun(_, []) -> binary:encode_hex(crypto:strong_rand_bytes(32), lowercase) end});\nhandler(<<\"lawspec.host::ability::FileSystem\">>) ->\n    stateless(#{\n        <<\"readBytes\">> => fun(_, [Path]) -> case file:read_file(Path) of\n            {ok, Bytes} -> just(Bytes);\n            {error, _} -> nothing()\n        end end,\n        <<\"writeBytes\">> => fun(_, [Path, Bytes]) -> file_result(file:write_file(Path, Bytes)) end,\n        <<\"pathExists\">> => fun(_, [Path]) -> case file:read_link_info(Path) of\n            {ok, _} -> true;\n            {error, _} -> false\n        end end,\n        <<\"removePath\">> => fun(_, [Path]) -> case file:del_dir_r(Path) of\n            {error, enoent} -> ls_unit;\n            Result -> file_result(Result)\n        end end,\n        <<\"temporaryDirectory\">> => fun(_, [Prefix]) -> temporary(directory, Prefix, 100) end,\n        <<\"temporaryFile\">> => fun(_, [Prefix]) -> temporary(file, Prefix, 100) end});\nhandler(<<\"lawspec.host::ability::Environment\">>) ->\n    stateless(#{\n        <<\"environmentVariable\">> => fun(_, [Name]) ->\n            case valid_name(Name) of\n                false -> nothing();\n                true -> case os:getenv(unicode:characters_to_list(Name)) of\n                    false -> nothing();\n                    Value -> just(unicode:characters_to_binary(Value))\n                end\n            end\n        end,\n        <<\"environmentSnapshot\">> => fun(_, []) ->\n            iolist_to_binary(json:encode(maps:from_list([\n                {unicode:characters_to_binary(Name), unicode:characters_to_binary(Value)}\n                || {Name, Value} <- os:env()])))\n        end,\n        <<\"restoreEnvironment\">> => fun(_, [Saved]) -> restore_environment(Saved) end});\nhandler(<<\"lawspec.host::ability::Ports\">>) ->\n    stateless(#{<<\"freePort\">> => fun(_, []) ->\n        {ok, Socket} = gen_tcp:listen(0, [{ip, {127, 0, 0, 1}}, {active, false}]),\n        try\n            {ok, {_, Port}} = inet:sockname(Socket),\n            Port\n        after gen_tcp:close(Socket) end\n    end});\nhandler(<<\"lawspec.logging::ability::Log\">>) ->\n    stateless(#{<<\"logMessage\">> => fun(_, [Level, Message]) ->\n        logger:log(log_level(Level), \"~ts\", [Message], #{domain => [lawspec]}), ls_unit\n    end});\nhandler(<<\"lawspec.logging::ability::Trace\">>) ->\n    stateless(#{<<\"traceEvent\">> => fun(_, [Message]) ->\n        logger:debug(\"~ts\", [Message], #{domain => [lawspec, trace]}), ls_unit\n    end});\nhandler(<<\"lawspec.concurrent::ability::Async\">>) ->\n    stateless(#{<<\"pause\">> => fun(_, []) -> erlang:yield(), ls_unit end});\nhandler(Ability) -> erlang:error({lawspec, {unknown_default_handler, Ability}}).\n\nstateless(Operations) -> lawspec_beam_effects:stateless(Operations).\ndata(Tag, Fields) -> {ls_data, Tag, Fields}.\njust(Value) -> data(<<\"Maybe::Just\">>, [Value]).\nnothing() -> data(<<\"Maybe::Nothing\">>, []).\n\n%% Freeze the VM's wall-clock offset when the module loads. Subsequent clock\n%% corrections cannot move this clock backwards. Sleep deadlines use monotonic\n%% time directly so even a saturated Instant cannot shorten a requested sleep.\nnow_micros() ->\n    min(9223372036854775807, max(0, erlang:monotonic_time(microsecond) +\n        persistent_term:get({?MODULE, clock_offset}))).\n\nsleep_micros(Micros) when is_integer(Micros), Micros >= 0 ->\n    sleep_until(erlang:monotonic_time(microsecond) + Micros).\n\nsleep_until(Deadline) ->\n    case Deadline - erlang:monotonic_time(microsecond) of\n        Left when Left > 0 ->\n            Millis = min(16#FFFFFFFF, (Left + 999) div 1000),\n            receive after Millis -> sleep_until(Deadline) end;\n        _ -> ok\n    end.\n\nrandom_step(State) -> (6364136223846793005 * State + 1442695040888963407) band 16#FFFFFFFFFFFFFFFF.\n\nsecure_below(Bound) when Bound < 1 -> 0;\nsecure_below(Bound) ->\n    %% Rejection sampling avoids modulo bias for every positive Int64 bound.\n    Limit = (1 bsl 64) - ((1 bsl 64) rem Bound),\n    <<Draw:64/unsigned-big>> = crypto:strong_rand_bytes(8),\n    case Draw < Limit of true -> Draw rem Bound; false -> secure_below(Bound) end.\n\nfile_result(ok) -> ls_unit;\nfile_result({error, Reason}) -> erlang:error({lawspec, {filesystem, Reason}}).\n\ntemporary(_, _, 0) -> erlang:error({lawspec, temporary_name_exhausted});\ntemporary(Kind, Prefix, Attempts) ->\n    case binary:match(Prefix, [<<0>>, <<\"/\">>, <<\"\\\\\">>]) of\n        nomatch -> ok;\n        _ -> erlang:error({lawspec, invalid_temporary_prefix})\n    end,\n    Name = <<Prefix/binary, (binary:encode_hex(crypto:strong_rand_bytes(16), lowercase))/binary>>,\n    Path = filename:join(temporary_root(), Name),\n    Created = case Kind of\n        directory -> file:make_dir(Path);\n        file -> case file:open(Path, [write, binary, exclusive, raw]) of\n            {ok, Device} -> file:close(Device);\n            Error -> Error\n        end\n    end,\n    case Created of\n        {error, eexist} -> temporary(Kind, Prefix, Attempts - 1);\n        ok ->\n            Mode = case Kind of directory -> 8#700; file -> 8#600 end,\n            case file:change_mode(Path, Mode) of\n                ok -> Path;\n                Error2 -> file:del_dir_r(Path), file_result(Error2)\n            end;\n        Error3 -> file_result(Error3)\n    end.\n\ntemporary_root() ->\n    Candidates = [unicode:characters_to_binary(P) || Name <- [\"TMPDIR\", \"TMP\", \"TEMP\"],\n        P <- [os:getenv(Name)], P =/= false, P =/= \"\"] ++\n        case os:type() of {win32, _} -> [<<\".\">>]; _ -> [<<\"/tmp\">>] end,\n    case [filename:absname(P) || P <- Candidates, filelib:is_dir(P)] of\n        [Root | _] -> Root;\n        [] -> erlang:error({lawspec, no_temporary_directory})\n    end.\n\nvalid_name(Name) when is_binary(Name), byte_size(Name) > 0 ->\n    binary:match(Name, [<<0>>, <<\"=\">>]) =:= nomatch;\nvalid_name(_) -> false.\n\nrestore_environment(Saved) ->\n    Decoded = json:decode(Saved),\n    %% Validate the entire snapshot before changing any environment variable.\n    Valid = is_map(Decoded) andalso lists:all(fun({Name, Value}) ->\n        valid_name(Name) andalso is_binary(Value) andalso binary:match(Value, <<0>>) =:= nomatch\n    end, maps:to_list(Decoded)),\n    case Valid of\n        false -> erlang:error({lawspec, invalid_environment_snapshot});\n        true ->\n            lists:foreach(fun({Name, _}) ->\n                case maps:is_key(unicode:characters_to_binary(Name), Decoded) of\n                    true -> ok;\n                    false -> os:unsetenv(Name)\n                end\n            end, os:env()),\n            maps:foreach(fun(Name, Value) ->\n                true = os:putenv(unicode:characters_to_list(Name), unicode:characters_to_list(Value))\n            end, Decoded),\n            ls_unit\n    end.\n\nlog_level({ls_data, <<\"lawspec.logging::type::LogLevel::Debug\">>, []}) -> debug;\nlog_level({ls_data, <<\"lawspec.logging::type::LogLevel::Info\">>, []}) -> info;\nlog_level({ls_data, <<\"lawspec.logging::type::LogLevel::Warning\">>, []}) -> warning;\nlog_level({ls_data, <<\"lawspec.logging::type::LogLevel::Error\">>, []}) -> error.\n"
runtimeSource "beam-crypto" = "%% @doc Cryptographic primitives backed by OTP's crypto application.\n%% Logical ability values are converted by the generated native interfaces.\n%% ref:DEC-typed-core-boundary\n-module(lawspec_beam_crypto).\n-export([handler/1, slh_dsa_signature_handler/0, sha3_256/1, shake256/2, derive_aead_key/2,\n    mlkem_keypair/1, mlkem_encapsulate/1, mlkem_decapsulate/2, mlkem_decapsulate_expanded/2,\n    mldsa_public/1, mldsa_sign/2, mldsa_sign/4, mldsa_verify/3, mldsa_verify/4,\n    slh_keypair/0, slh_keypair/1, slh_sign/2, slh_sign/3, slh_verify/3, slh_verify/4,\n    aes256_gcm_encrypt/4, aes256_gcm_decrypt/4, seal/3, unseal/3]).\n\nhandler(<<\"lawspec.crypto::ability::Hash\">>) ->\n    lawspec_beam_effects:stateless(#{\n        <<\"sha3\">> => fun(_, [Message]) -> wrap(<<\"Digest\">>, sha3_256(Message)) end,\n        <<\"shake\">> => fun(_, [Message, Count]) -> shake256(Message, Count) end});\nhandler(<<\"lawspec.crypto::ability::KeyExchange\">>) ->\n    lawspec_beam_effects:stateless(#{\n        <<\"exchangeKeyPair\">> => fun(_, []) ->\n            {Public, Secret} = mlkem_keypair(crypto:strong_rand_bytes(64)),\n            pair(<<\"ExchangeKeyPair\">>, wrap(<<\"ExchangePublicKey\">>, Public), wrap(<<\"ExchangeSecretKey\">>, Secret))\n        end,\n        <<\"encapsulate\">> => fun(_, [Public]) ->\n            {Ciphertext, Shared} = mlkem_encapsulate(unwrap(<<\"ExchangePublicKey\">>, Public)),\n            pair(<<\"Encapsulated\">>, wrap(<<\"Ciphertext\">>, Ciphertext), wrap(<<\"SharedSecret\">>, Shared))\n        end,\n        <<\"decapsulate\">> => fun(_, [Secret, Ciphertext]) ->\n            wrap(<<\"SharedSecret\">>, mlkem_decapsulate(unwrap(<<\"ExchangeSecretKey\">>, Secret), unwrap(<<\"Ciphertext\">>, Ciphertext)))\n        end});\nhandler(<<\"lawspec.crypto::ability::Signature\">>) ->\n    signature_handler(fun() -> Seed = crypto:strong_rand_bytes(32), {mldsa_public(Seed), Seed} end,\n        fun mldsa_sign/2, fun mldsa_verify/3);\nhandler(<<\"lawspec.crypto::ability::Aead\">>) ->\n    lawspec_beam_effects:stateless(#{\n        <<\"aeadKey\">> => fun(_, []) -> wrap(<<\"AeadKey\">>, crypto:strong_rand_bytes(32)) end,\n        <<\"deriveAeadKey\">> => fun(_, [Secret, Context]) ->\n            wrap(<<\"AeadKey\">>, derive_aead_key(unwrap(<<\"SharedSecret\">>, Secret), Context))\n        end,\n        <<\"seal\">> => fun(_, [Key, Message, Associated]) ->\n            wrap(<<\"Sealed\">>, seal(unwrap(<<\"AeadKey\">>, Key), Message, Associated))\n        end,\n        <<\"unseal\">> => fun(_, [Key, Sealed, Associated]) ->\n            case unseal(unwrap(<<\"AeadKey\">>, Key), unwrap(<<\"Sealed\">>, Sealed), Associated) of\n                {ok, Message} -> {ls_data, <<\"Maybe::Just\">>, [Message]};\n                error -> {ls_data, <<\"Maybe::Nothing\">>, []}\n            end\n        end}).\n\nslh_dsa_signature_handler() -> signature_handler(fun slh_keypair/0, fun slh_sign/2, fun slh_verify/3).\n\nsignature_handler(Make, Sign, Verify) ->\n    lawspec_beam_effects:stateless(#{\n        <<\"signingKeyPair\">> => fun(_, []) ->\n            {Public, Secret} = Make(),\n            pair(<<\"SigningKeyPair\">>, wrap(<<\"VerifyingKey\">>, Public), wrap(<<\"SigningKey\">>, Secret))\n        end,\n        <<\"sign\">> => fun(_, [Secret, Message]) ->\n            wrap(<<\"SignatureBytes\">>, Sign(unwrap(<<\"SigningKey\">>, Secret), Message))\n        end,\n        <<\"verify\">> => fun(_, [Public, Message, Signature]) ->\n            Verify(unwrap(<<\"VerifyingKey\">>, Public), Message, unwrap(<<\"SignatureBytes\">>, Signature))\n        end}).\n\npair(Name, First, Second) -> {ls_data, <<\"lawspec.crypto::type::\", Name/binary, \"::\", Name/binary>>, [First, Second]}.\nwrap(Name, Bytes) -> {ls_data, <<\"lawspec.crypto::type::\", Name/binary, \"::\", Name/binary>>, [Bytes]}.\nunwrap(Name, {ls_data, Tag, [Bytes]}) ->\n    Expected = <<\"lawspec.crypto::type::\", Name/binary, \"::\", Name/binary>>,\n    Expected = Tag,\n    Bytes.\n\nsha3_256(Message) -> crypto:hash(sha3_256, Message).\n\n%% OTP's XOF length is in bits; LawSpec's operation counts bytes.\nshake256(_, Count) when Count =< 0 -> <<>>;\nshake256(Message, Count) -> crypto:hash_xof(shake256, Message, Count * 8).\n\nderive_aead_key(Secret, Context) -> shake256([Secret, Context], 32).\n\n%% LawSpec stores the FIPS key-generation seeds, not OTP's expanded private\n%% encodings. Expand at the boundary without changing the portable wire format.\nmlkem_keypair(Seed) ->\n    {Public, _} = lawspec_beam_crypto_native:expand(mlkem768, Seed),\n    {Public, Seed}.\n\nmlkem_encapsulate(Public) ->\n    {Shared, Ciphertext} = crypto:encapsulate_key(mlkem768, Public),\n    {Ciphertext, Shared}.\n\nmlkem_decapsulate(Seed, Ciphertext) ->\n    {_, Private} = lawspec_beam_crypto_native:expand(mlkem768, Seed),\n    mlkem_decapsulate_expanded(Private, Ciphertext).\n\nmlkem_decapsulate_expanded(Private, Ciphertext) -> crypto:decapsulate_key(mlkem768, Private, Ciphertext).\n\nmldsa_public(Seed) ->\n    {Public, _} = lawspec_beam_crypto_native:expand(mldsa65, Seed),\n    Public.\n\nmldsa_sign(Seed, Message) when byte_size(Seed) =:= 32 -> crypto:sign(mldsa65, none, Message, {seed, Seed}).\nmldsa_sign(Seed, Message, <<>>, false) -> mldsa_sign(Seed, Message);\nmldsa_sign(Seed, Message, Context, Deterministic) ->\n    lawspec_beam_crypto_native:sign_context(mldsa65, Seed, Message, Context, Deterministic).\n\nmldsa_verify(Public, Message, Signature) -> mldsa_verify(Public, Message, Signature, <<>>).\nmldsa_verify(Public, Message, Signature, Context) -> verify(mldsa65, 1952, 3309, Public, Message, Signature, Context).\n\nslh_keypair() -> crypto:generate_key(slh_dsa_shake_128f, []).\nslh_keypair(Seed) -> lawspec_beam_crypto_native:expand(slh_dsa_shake_128f, Seed).\nslh_sign(Private, Message) when byte_size(Private) =:= 64 -> crypto:sign(slh_dsa_shake_128f, none, Message, Private).\nslh_sign(Private, Message, <<>>) -> slh_sign(Private, Message);\nslh_sign(Private, Message, Context) ->\n    lawspec_beam_crypto_native:sign_context(slh_dsa_shake_128f, Private, Message, Context, false).\nslh_verify(Public, Message, Signature) -> slh_verify(Public, Message, Signature, <<>>).\nslh_verify(Public, Message, Signature, Context) -> verify(slh_dsa_shake_128f, 32, 17088, Public, Message, Signature, Context).\n\nverify(Algorithm, PublicSize, SignatureSize, Public, Message, Signature, Context)\n        when byte_size(Public) =:= PublicSize, byte_size(Signature) =:= SignatureSize, byte_size(Context) =< 255 ->\n    case Context of\n        <<>> -> crypto:verify(Algorithm, none, Message, Signature, Public);\n        _ -> lawspec_beam_crypto_native:verify_context(Algorithm, Public, Message, Signature, Context)\n    end;\nverify(_, _, _, _, _, _, _) -> false.\n\naes256_gcm_encrypt(Key, Nonce, Message, Associated)\n        when byte_size(Key) =:= 32, byte_size(Nonce) =:= 12 ->\n    {Ciphertext, Tag} = crypto:crypto_one_time_aead(aes_256_gcm, Key, Nonce,\n        Message, Associated, 16, true),\n    <<Ciphertext/binary, Tag/binary>>.\n\naes256_gcm_decrypt(Key, Nonce, Sealed, Associated)\n        when byte_size(Key) =:= 32, byte_size(Nonce) =:= 12, byte_size(Sealed) >= 16 ->\n    Size = byte_size(Sealed) - 16,\n    <<Ciphertext:Size/binary, Tag:16/binary>> = Sealed,\n    case crypto:crypto_one_time_aead(aes_256_gcm, Key, Nonce, Ciphertext, Associated, Tag, false) of\n        error -> error;\n        Plaintext -> {ok, Plaintext}\n    end;\naes256_gcm_decrypt(_, _, _, _) -> error.\n\nseal(Key, Message, Associated) ->\n    Nonce = crypto:strong_rand_bytes(12),\n    Sealed = aes256_gcm_encrypt(Key, Nonce, Message, Associated),\n    <<Nonce/binary, Sealed/binary>>.\n\nunseal(Key, <<Nonce:12/binary, Sealed/binary>>, Associated) ->\n    aes256_gcm_decrypt(Key, Nonce, Sealed, Associated);\nunseal(_, _, _) -> error.\n"
runtimeSource "beam-crypto_native" = "%% @doc The seed and vector bridge to the same OpenSSL ABI as OTP crypto.\n%% Build with escript lawspec_crypto_build.escript; ship the resulting priv/.\n%% ref:DEC-typed-core-boundary\n-module(lawspec_beam_crypto_native).\n-on_load(init/0).\n-export([expand/2, encapsulate_test/2, sign_context/5, verify_context/5]).\n\ninit() ->\n    [{<<\"OpenSSL\">>, Version, _}] = crypto:info_lib(),\n    BeamDir = filename:dirname(code:which(?MODULE)),\n    %% Application layouts (Rebar, Mix, Gleam and releases) put ebin beside\n    %% priv. The second path supports a standalone erlc output directory.\n    Candidates = [filename:join([filename:dirname(BeamDir), \"priv\", \"lawspec_crypto_native\"]),\n        filename:join([BeamDir, \"priv\", \"lawspec_crypto_native\"])],\n    case [Path || Path <- Candidates, filelib:is_regular(Path ++ extension())] of\n        [Library | _] -> erlang:load_nif(Library, Version bsr 28);\n        [] -> {error, {load_failed,\n            \"LawSpec crypto bridge is missing; run escript lawspec_crypto_build.escript before compiling and ship priv/ with the application\"}}\n    end.\n\nextension() -> case os:type() of {win32, _} -> \".dll\"; _ -> \".so\" end.\n\nexpand(_, _) -> erlang:nif_error(lawspec_crypto_native_not_loaded).\nencapsulate_test(_, _) -> erlang:nif_error(lawspec_crypto_native_not_loaded).\nsign_context(_, _, _, _, _) -> erlang:nif_error(lawspec_crypto_native_not_loaded).\nverify_context(_, _, _, _, _) -> erlang:nif_error(lawspec_crypto_native_not_loaded).\n"
runtimeSource "beam-crypto-native-c" = "/* OpenSSL operations not exposed by OTP 29's crypto API: compact key seeds,\n * signature contexts and deterministic known-answer tests. Ordinary random\n * encapsulation, signing, verification and AEAD use OTP directly.\n * ref:DEC-typed-core-boundary\n */\n#include <erl_nif.h>\n#include <openssl/crypto.h>\n#include <openssl/evp.h>\n#include <openssl/err.h>\n#include <openssl/params.h>\n#include <openssl/core_names.h>\n#include <string.h>\n\n#if OPENSSL_VERSION_NUMBER < 0x30500000L\n#error \"LawSpec crypto requires OpenSSL 3.5 or newer\"\n#endif\n#if !defined(LAWSPEC_OPENSSL_MAJOR) || OPENSSL_VERSION_MAJOR != LAWSPEC_OPENSSL_MAJOR\n#error \"Build LawSpec crypto with the same OpenSSL major version as Erlang/OTP\"\n#endif\n\ntypedef struct {\n    const char *tag, *name;\n    size_t seed, public_key, private_key, signature;\n} Algorithm;\n\nstatic const Algorithm algorithms[] = {\n    {\"mlkem768\", \"ML-KEM-768\", 64, 1184, 2400, 0},\n    {\"mldsa65\", \"ML-DSA-65\", 32, 1952, 4032, 3309},\n    {\"slh_dsa_shake_128f\", \"SLH-DSA-SHAKE-128f\", 48, 32, 64, 17088}\n};\n\nstatic const Algorithm *algorithm(ErlNifEnv *env, ERL_NIF_TERM term) {\n    char tag[32];\n    size_t i;\n    if (!enif_get_atom(env, term, tag, sizeof(tag), ERL_NIF_LATIN1)) return NULL;\n    for (i = 0; i < sizeof(algorithms) / sizeof(algorithms[0]); ++i)\n        if (!strcmp(tag, algorithms[i].tag)) return &algorithms[i];\n    return NULL;\n}\n\n/* No key material or provider error strings enter diagnostics. OpenSSL's\n * per-thread error queue must not leak between jobs on a dirty scheduler. */\nstatic ERL_NIF_TERM failure(ErlNifEnv *env, const char *operation) {\n    ERR_clear_error();\n    return enif_raise_exception(env, enif_make_tuple2(env,\n        enif_make_atom(env, \"lawspec_crypto_failure\"), enif_make_atom(env, operation)));\n}\n\nstatic EVP_PKEY *import_key(const Algorithm *alg, const char *parameter,\n                           const ErlNifBinary *bytes, int selection) {\n    EVP_PKEY *key = NULL;\n    EVP_PKEY_CTX *ctx = EVP_PKEY_CTX_new_from_name(NULL, alg->name, NULL);\n    OSSL_PARAM params[] = {\n        OSSL_PARAM_construct_octet_string(parameter, bytes->data, bytes->size),\n        OSSL_PARAM_construct_end()\n    };\n    if (!ctx || EVP_PKEY_fromdata_init(ctx) <= 0\n        || EVP_PKEY_fromdata(ctx, &key, selection, params) <= 0) {\n        EVP_PKEY_free(key);\n        key = NULL;\n    }\n    EVP_PKEY_CTX_free(ctx);\n    return key;\n}\n\nstatic ERL_NIF_TERM expand(ErlNifEnv *env, int argc, const ERL_NIF_TERM argv[]) {\n    const Algorithm *alg;\n    ErlNifBinary seed, pub = {0}, priv = {0};\n    EVP_PKEY_CTX *ctx = NULL;\n    EVP_PKEY *key = NULL;\n    size_t written;\n    int pub_allocated = 0, priv_allocated = 0, ok = 0;\n    ERL_NIF_TERM result;\n    if (argc != 2 || !(alg = algorithm(env, argv[0]))\n        || !enif_inspect_binary(env, argv[1], &seed) || seed.size != alg->seed)\n        return enif_make_badarg(env);\n    ERR_clear_error();\n    if (alg == &algorithms[2]) {\n        /* SLH's seed parameter is used only for the NIST key-generation tests. */\n        OSSL_PARAM params[] = {\n            OSSL_PARAM_construct_octet_string(\"seed\", seed.data, seed.size),\n            OSSL_PARAM_construct_end()\n        };\n        ctx = EVP_PKEY_CTX_new_from_name(NULL, alg->name, NULL);\n        if (!ctx || EVP_PKEY_keygen_init(ctx) <= 0\n            || EVP_PKEY_CTX_set_params(ctx, params) <= 0\n            || EVP_PKEY_generate(ctx, &key) <= 0) goto done;\n    } else {\n        key = import_key(alg, \"seed\", &seed, EVP_PKEY_KEYPAIR);\n        if (!key) goto done;\n    }\n    if (!(pub_allocated = enif_alloc_binary(alg->public_key, &pub))\n        || !(priv_allocated = enif_alloc_binary(alg->private_key, &priv))) goto done;\n    if (!EVP_PKEY_get_octet_string_param(key, OSSL_PKEY_PARAM_PUB_KEY,\n            pub.data, pub.size, &written) || written != pub.size\n        || !EVP_PKEY_get_octet_string_param(key, OSSL_PKEY_PARAM_PRIV_KEY,\n            priv.data, priv.size, &written) || written != priv.size) goto done;\n    ok = 1;\ndone:\n    EVP_PKEY_free(key);\n    EVP_PKEY_CTX_free(ctx);\n    if (ok) {\n        result = enif_make_tuple2(env, enif_make_binary(env, &pub), enif_make_binary(env, &priv));\n        ERR_clear_error();\n        return result;\n    }\n    if (pub_allocated) enif_release_binary(&pub);\n    if (priv_allocated) { OPENSSL_cleanse(priv.data, priv.size); enif_release_binary(&priv); }\n    return failure(env, \"expand_seed\");\n}\n\n/* FIPS 203 deterministic encapsulation for known-answer tests only. */\nstatic ERL_NIF_TERM encapsulate_test(ErlNifEnv *env, int argc, const ERL_NIF_TERM argv[]) {\n    ErlNifBinary pub, randomness, ciphertext = {0}, secret = {0};\n    EVP_PKEY *key = NULL;\n    EVP_PKEY_CTX *ctx = NULL;\n    size_t ciphertext_size = 1088, secret_size = 32;\n    int ciphertext_allocated = 0, secret_allocated = 0, ok = 0;\n    ERL_NIF_TERM result;\n    if (argc != 2 || !enif_inspect_binary(env, argv[0], &pub) || pub.size != 1184\n        || !enif_inspect_binary(env, argv[1], &randomness) || randomness.size != 32)\n        return enif_make_badarg(env);\n    ERR_clear_error();\n    OSSL_PARAM params[] = {\n        OSSL_PARAM_construct_octet_string(OSSL_KEM_PARAM_IKME, randomness.data, randomness.size),\n        OSSL_PARAM_construct_end()\n    };\n    key = import_key(&algorithms[0], OSSL_PKEY_PARAM_PUB_KEY, &pub, EVP_PKEY_PUBLIC_KEY);\n    if (!key || !(ctx = EVP_PKEY_CTX_new_from_pkey(NULL, key, NULL))\n        || EVP_PKEY_encapsulate_init(ctx, params) <= 0) goto done;\n    if (!(ciphertext_allocated = enif_alloc_binary(ciphertext_size, &ciphertext))\n        || !(secret_allocated = enif_alloc_binary(secret_size, &secret))) goto done;\n    if (EVP_PKEY_encapsulate(ctx, ciphertext.data, &ciphertext_size, secret.data, &secret_size) <= 0\n        || ciphertext_size != ciphertext.size || secret_size != secret.size) goto done;\n    ok = 1;\ndone:\n    EVP_PKEY_CTX_free(ctx);\n    EVP_PKEY_free(key);\n    if (ok) {\n        result = enif_make_tuple2(env, enif_make_binary(env, &ciphertext), enif_make_binary(env, &secret));\n        ERR_clear_error();\n        return result;\n    }\n    if (ciphertext_allocated) enif_release_binary(&ciphertext);\n    if (secret_allocated) { OPENSSL_cleanse(secret.data, secret.size); enif_release_binary(&secret); }\n    return failure(env, \"encapsulate_test\");\n}\n\nstatic ERL_NIF_TERM sign_context(ErlNifEnv *env, int argc, const ERL_NIF_TERM argv[]) {\n    const Algorithm *alg;\n    ErlNifBinary secret, message, context, signature = {0};\n    EVP_PKEY *key = NULL;\n    EVP_PKEY_CTX *ctx = NULL;\n    EVP_SIGNATURE *scheme = NULL;\n    int deterministic, allocated = 0, ok = 0;\n    size_t length;\n    ERL_NIF_TERM result;\n    if (argc != 5 || !(alg = algorithm(env, argv[0])) || !alg->signature\n        || !enif_inspect_binary(env, argv[1], &secret)\n        || secret.size != (alg == &algorithms[1] ? alg->seed : alg->private_key)\n        || !enif_inspect_binary(env, argv[2], &message)\n        || !enif_inspect_binary(env, argv[3], &context) || context.size > 255)\n        return enif_make_badarg(env);\n    if (enif_is_identical(argv[4], enif_make_atom(env, \"true\"))) deterministic = 1;\n    else if (enif_is_identical(argv[4], enif_make_atom(env, \"false\"))) deterministic = 0;\n    else return enif_make_badarg(env);\n    ERR_clear_error();\n    OSSL_PARAM params[] = {\n        OSSL_PARAM_construct_octet_string(OSSL_SIGNATURE_PARAM_CONTEXT_STRING, context.data, context.size),\n        OSSL_PARAM_construct_int(OSSL_SIGNATURE_PARAM_DETERMINISTIC, &deterministic),\n        OSSL_PARAM_construct_end()\n    };\n    key = import_key(alg, alg == &algorithms[1] ? \"seed\" : OSSL_PKEY_PARAM_PRIV_KEY,\n        &secret, EVP_PKEY_KEYPAIR);\n    if (!key || !(ctx = EVP_PKEY_CTX_new_from_pkey(NULL, key, NULL))\n        || !(scheme = EVP_SIGNATURE_fetch(NULL, alg->name, NULL))\n        || EVP_PKEY_sign_message_init(ctx, scheme, params) <= 0) goto done;\n    length = alg->signature;\n    if (!(allocated = enif_alloc_binary(length, &signature))) goto done;\n    if (EVP_PKEY_sign(ctx, signature.data, &length, message.data, message.size) <= 0\n        || length != signature.size) goto done;\n    ok = 1;\ndone:\n    EVP_SIGNATURE_free(scheme);\n    EVP_PKEY_CTX_free(ctx);\n    EVP_PKEY_free(key);\n    if (ok) {\n        result = enif_make_binary(env, &signature);\n        ERR_clear_error();\n        return result;\n    }\n    if (allocated) enif_release_binary(&signature);\n    return failure(env, \"sign_context\");\n}\n\nstatic ERL_NIF_TERM verify_context(ErlNifEnv *env, int argc, const ERL_NIF_TERM argv[]) {\n    const Algorithm *alg;\n    ErlNifBinary pub, message, signature, context;\n    EVP_PKEY *key = NULL;\n    EVP_PKEY_CTX *ctx = NULL;\n    EVP_SIGNATURE *scheme = NULL;\n    int verified = -1;\n    if (argc != 5 || !(alg = algorithm(env, argv[0])) || !alg->signature\n        || !enif_inspect_binary(env, argv[1], &pub)\n        || !enif_inspect_binary(env, argv[2], &message)\n        || !enif_inspect_binary(env, argv[3], &signature)\n        || !enif_inspect_binary(env, argv[4], &context)) return enif_make_badarg(env);\n    if (pub.size != alg->public_key || signature.size != alg->signature || context.size > 255)\n        return enif_make_atom(env, \"false\");\n    ERR_clear_error();\n    OSSL_PARAM params[] = {\n        OSSL_PARAM_construct_octet_string(OSSL_SIGNATURE_PARAM_CONTEXT_STRING, context.data, context.size),\n        OSSL_PARAM_construct_end()\n    };\n    key = import_key(alg, OSSL_PKEY_PARAM_PUB_KEY, &pub, EVP_PKEY_PUBLIC_KEY);\n    if (!key || !(ctx = EVP_PKEY_CTX_new_from_pkey(NULL, key, NULL))\n        || !(scheme = EVP_SIGNATURE_fetch(NULL, alg->name, NULL))\n        || EVP_PKEY_verify_message_init(ctx, scheme, params) <= 0) goto done;\n    verified = EVP_PKEY_verify(ctx, signature.data, signature.size, message.data, message.size);\ndone:\n    EVP_SIGNATURE_free(scheme);\n    EVP_PKEY_CTX_free(ctx);\n    EVP_PKEY_free(key);\n    if (verified < 0) return failure(env, \"verify_context\");\n    ERR_clear_error();\n    return enif_make_atom(env, verified == 1 ? \"true\" : \"false\");\n}\n\nstatic int load(ErlNifEnv *env, void **private_data, ERL_NIF_TERM info) {\n    unsigned int expected;\n    (void)private_data;\n    return !enif_get_uint(env, info, &expected) || expected != OPENSSL_VERSION_MAJOR\n        || OPENSSL_version_major() != expected || OpenSSL_version_num() < 0x30500000L;\n}\n\nstatic ErlNifFunc functions[] = {\n    {\"expand\", 2, expand, ERL_NIF_DIRTY_JOB_CPU_BOUND},\n    {\"encapsulate_test\", 2, encapsulate_test, ERL_NIF_DIRTY_JOB_CPU_BOUND},\n    {\"sign_context\", 5, sign_context, ERL_NIF_DIRTY_JOB_CPU_BOUND},\n    {\"verify_context\", 5, verify_context, ERL_NIF_DIRTY_JOB_CPU_BOUND}\n};\nERL_NIF_INIT(lawspec_beam_crypto_native, functions, load, NULL, NULL, NULL)\n"
runtimeSource "beam-crypto-build" = "#!/usr/bin/env escript\n%%! -noshell\n%% Build once before Rebar/Mix/Gleam compilation; no compiler runs at application\n%% startup. CC names one executable. LAWSPEC_OPENSSL_PREFIX selects a development\n%% installation matching OTP's OpenSSL major version (3.5+).\n%% ref:DEC-typed-core-boundary\n-mode(compile).\n\nmain(Arguments) ->\n    try\n        Project = case Arguments of\n            [] -> filename:dirname(filename:absname(escript:script_name()));\n            [Directory] -> filename:absname(Directory);\n            _ -> fail(\"usage: escript lawspec_crypto_build.escript [project-directory]\")\n        end,\n        build(Project)\n    catch\n        throw:{build_error, Message} -> io:format(standard_error, \"LawSpec crypto: ~ts~n\", [Message]), halt(1);\n        error:Reason -> io:format(standard_error, \"LawSpec crypto build failed: ~tp~n\", [Reason]), halt(1)\n    end.\n\nbuild(Project) ->\n    case list_to_integer(erlang:system_info(otp_release)) >= 29 of\n        true -> ok;\n        false -> fail(\"Erlang/OTP 29 or newer is required\")\n    end,\n    [{<<\"OpenSSL\">>, Version, Description}] = crypto:info_lib(),\n    Major = Version bsr 28,\n    MissingAlgorithms = lists:append([Expected -- crypto:supports(Kind) || {Kind, Expected} <-\n        [{kems, [mlkem768]}, {public_keys, [mldsa65, slh_dsa_shake_128f]},\n         {hashs, [sha3_256, shake256]}, {ciphers, [aes_256_gcm]}]]),\n    case MissingAlgorithms of\n        [] -> ok;\n        Missing -> fail(io_lib:format(\"OTP crypto lacks ~tp; install OTP with OpenSSL 3.5+\", [Missing]))\n    end,\n    Compiler = executable(env(\"CC\", \"cc\")),\n    {Include, Library, ProviderVersion} = openssl(Major),\n    OtpInclude = filename:join([code:root_dir(), \"usr\", \"include\"]),\n    Source = filename:join([Project, \"priv\", \"lawspec_crypto_native.c\"]),\n    Output = filename:join([Project, \"priv\", \"lawspec_crypto_native.so\"]),\n    Stamp = Output ++ \".build\",\n    SourceBytes = read(Source),\n    Args = [\"-std=c11\", \"-O2\", \"-Wall\", \"-Wextra\", \"-Werror\", \"-fPIC\", \"-shared\"] ++\n        platform_flags() ++ [\"-DLAWSPEC_OPENSSL_MAJOR=\" ++ integer_to_list(Major),\n        \"-I\" ++ OtpInclude, \"-I\" ++ Include, Source, \"-L\" ++ Library,\n        \"-Xlinker\", \"-rpath\", \"-Xlinker\", Library, \"-lcrypto\"],\n    Fingerprint = crypto:hash(sha3_256, term_to_binary({SourceBytes,\n        read(escript:script_name()), read(filename:join(Include, \"openssl/opensslv.h\")),\n        read(filename:join(OtpInclude, \"erl_nif.h\")),\n        erlang:system_info(system_architecture), erlang:system_info(nif_version),\n        Version, Description, ProviderVersion, Compiler, Args})),\n    case current(Stamp, Output, Fingerprint) of\n        true -> ok;\n        false ->\n            %% A failed or concurrent build cannot replace a working library.\n            Temporary = Output ++ \".\" ++ os:getpid() ++ \".tmp\",\n            try\n                checked(Compiler, Args ++ [\"-o\", Temporary]),\n                ok = file:rename(Temporary, Output),\n                ok = file:write_file(Stamp, term_to_binary({Fingerprint, crypto:hash(sha3_256, read(Output))})),\n                io:format(\"Built LawSpec crypto bridge (~ts).~n\", [Description])\n            after\n                file:delete(Temporary)\n            end\n    end.\n\nplatform_flags() ->\n    case os:type() of\n        {unix, darwin} -> [\"-undefined\", \"dynamic_lookup\"];\n        {unix, _} -> [];\n        _ -> fail(\"the crypto bridge build requires a Unix C toolchain; use WSL on Windows\")\n    end.\n\nopenssl(Major) ->\n    case os:getenv(\"LAWSPEC_OPENSSL_PREFIX\") of\n        false -> discover_openssl(Major);\n        Prefix -> prefix(Prefix, \"explicit prefix\")\n    end.\n\ndiscover_openssl(Major) ->\n    case os:find_executable(\"pkg-config\") of\n        false -> homebrew_openssl(Major);\n        Pkg ->\n            case run(Pkg, [\"--modversion\", \"libcrypto\"]) of\n                {0, Text} ->\n                    Version = string:trim(binary_to_list(Text)),\n                    case string:prefix(Version, integer_to_list(Major) ++ \".\") of\n                        nomatch -> homebrew_openssl(Major);\n                        _ -> {query(Pkg, [\"--variable=includedir\", \"libcrypto\"]),\n                              query(Pkg, [\"--variable=libdir\", \"libcrypto\"]), Version}\n                    end;\n                _ -> homebrew_openssl(Major)\n            end\n    end.\n\nhomebrew_openssl(Major) ->\n    case os:find_executable(\"brew\") of\n        false -> missing_openssl(Major);\n        Brew ->\n            case run(Brew, [\"--prefix\", \"openssl@\" ++ integer_to_list(Major)]) of\n                {0, Text} -> prefix(string:trim(binary_to_list(Text)), \"Homebrew\");\n                _ -> missing_openssl(Major)\n            end\n    end.\n\nprefix(Prefix, Origin) ->\n    Absolute = filename:absname(Prefix),\n    Include = filename:join(Absolute, \"include\"),\n    case filelib:is_regular(filename:join(Include, \"openssl/evp.h\")) of\n        true ->\n            Libraries = [filename:join(Absolute, Subdir) || Subdir <- [\"lib\", \"lib64\"],\n                lists:any(fun(Name) -> filelib:is_regular(filename:join([Absolute, Subdir, Name])) end,\n                    [\"libcrypto.so\", \"libcrypto.dylib\"])],\n            case Libraries of\n                [Library | _] -> {Include, Library, Origin};\n                [] -> fail(\"OpenSSL shared library missing under \" ++ Absolute)\n            end;\n        false -> fail(\"OpenSSL headers missing under \" ++ Absolute)\n    end.\n\nmissing_openssl(Major) -> fail(io_lib:format(\n    \"install pkg-config and OpenSSL ~B development headers/libraries (3.5+), or set LAWSPEC_OPENSSL_PREFIX to that installation\", [Major])).\n\ncurrent(Stamp, Output, Fingerprint) ->\n    case {file:read_file(Stamp), file:read_file(Output)} of\n        {{ok, StampBytes}, {ok, OutputBytes}} ->\n            try binary_to_term(StampBytes, [safe]) =:= {Fingerprint, crypto:hash(sha3_256, OutputBytes)}\n            catch error:badarg -> false end;\n        _ -> false\n    end.\n\nenv(Key, Default) -> case os:getenv(Key) of false -> Default; Value -> Value end.\nexecutable(Name) -> case os:find_executable(Name) of\n    false -> fail(\"executable not found: \" ++ Name ++ \" (CC must name one compiler executable)\");\n    Path -> Path\nend.\n\nread(Path) -> case file:read_file(Path) of\n    {ok, Bytes} -> Bytes;\n    {error, Reason} -> fail(io_lib:format(\"cannot read ~ts: ~tp\", [Path, Reason]))\nend.\n\nquery(Command, Args) -> string:trim(binary_to_list(checked(Command, Args))).\nchecked(Command, Args) -> case run(Command, Args) of\n    {0, Output} -> Output;\n    {Status, Output} -> fail(io_lib:format(\"~ts exited ~B:~n~ts\", [Command, Status, Output]))\nend.\n\n%% Argument arrays, never a shell: project and installation paths may contain\n%% spaces, quotes, dollar signs or other shell metacharacters.\nrun(Command, Args) ->\n    Port = open_port({spawn_executable, Command}, [binary, exit_status, use_stdio, stderr_to_stdout, {args, Args}]),\n    collect(Port, []).\n\ncollect(Port, Parts) ->\n    receive\n        {Port, {data, Bytes}} -> collect(Port, [Bytes | Parts]);\n        {Port, {exit_status, Status}} -> {Status, iolist_to_binary(lists:reverse(Parts))}\n    end.\n\nfail(Message) -> throw({build_error, lists:flatten(Message)}).\n"
runtimeSource "beam-generators" = "%% @doc Structural/scalar generator composition, shared across native frameworks.\n%% The framework supplies every generator and shrink tree; no portable seed or\n%% custom shrinker replaces PropEr, StreamData or qcheck.\n%% ref:DEC-native-property-frameworks ref:DEC-structural-size-budget\n-module(lawspec_beam_generators).\n-export([generator/6, generator/7, with_cache/1, with_native/3]).\n\n%% Factories live exclusively in test code. The canonical schema still owns\n%% every logical contract; the native schema only converts representations.\n%% ref:DEC-native-bindings-typed-identity\nwith_native(Schema, Native, Factories) ->\n    maps:foreach(fun(Name, Factory) ->\n        case maps:is_key(Name, maps:get(arities, Schema)) andalso is_function(Factory, 1) of\n            true -> ok;\n            false -> erlang:error({lawspec, {invalid_native_generator, Name}})\n        end\n    end, Factories),\n    Schema#{native_generators => Factories, native_generator_schema => Native}.\n\ngenerator(F, T, Schema, Symbols, Bounds, Witnesses) ->\n    generator(F, T, Schema, Symbols, Bounds, Witnesses, none).\ngenerator(F, T, Schema, Symbols, Bounds, Witnesses, Index) ->\n    F:sized(fun(Size) ->\n        case factory(T, Schema) of\n            {ok, Factory} -> custom(F, T, Schema, Symbols, Size + 1, Bounds, Index, Factory);\n            error -> automatic(F, T, Schema, Symbols, Size, Bounds, Witnesses, Index)\n        end\n    end).\n\nautomatic(F, T, Schema, Symbols, Size, Bounds, Witnesses, Index) ->\n        Limit = lists:max([64 | [value_nodes(V) || V <- Witnesses]]),\n        Minimum = minimum(T, Schema, Limit),\n        case Minimum of\n            none -> erlang:error({lawspec, {no_structural_generator, T}});\n            _ ->\n                Budget = max(Minimum, Size + 1),\n                case Index of\n                    {Target, Equations} -> lawspec_beam_index:generator(F, T, Schema, Target, Equations, Budget,\n                        fun(Child) -> minimum(Child, Schema, Limit) end,\n                        fun(Child, Available) -> build(F, Child, Schema, Symbols, Available, []) end,\n                        fun(Child, Value) -> accepted(Value, Child, Schema) end,\n                        fun(Child, K, Available) -> case factory(Child, Schema) of\n                            error -> none;\n                            {ok, Factory} -> {custom, custom(F, Child, Schema, Symbols, Available, [], {K, Equations}, Factory)}\n                        end end);\n                    none ->\n                        Native = build(F, T, Schema, Symbols, Budget, Bounds),\n                        case Witnesses of\n                            [] -> Native;\n                            _ -> F:frequency([{1, F:oneof([F:exactly(V) || V <- Witnesses])}, {9, Native}])\n                        end\n                end\n        end.\n\nfactory({Name, _}, S) -> maps:find(Name, maps:get(native_generators, S, #{})).\n\ncustom(F, {Name, Args} = T, S, Symbols, Budget, Bounds, Index, Factory) ->\n    Native = maps:get(native_generator_schema, S),\n    Label = <<\"native generator \", Name/binary>>,\n    Children = [F:sized(fun(_) ->\n        Available = max(1, Budget - 1),\n        case minimum(Child, S, Available) of\n            none -> F:constrain(F:exactly('$lawspec_uninhabited'), fun(_) -> false end);\n            _ -> F:map(build(F, Child, S, Symbols, Available, []),\n                fun(V) -> lawspec_beam_schema:to_native(V, Child, Native) end)\n        end\n    end) || Child <- Args],\n    Checked = lawspec_beam_runtime:contextual(Label, fun() ->\n        F:map(Factory(Children), fun(Value) ->\n            lawspec_beam_runtime:contextual(Label, fun() ->\n                lawspec_beam_schema:validate(lawspec_beam_schema:from_native(Value, T, Native), T, S)\n            end)\n        end)\n    end),\n    %% Refinements constrain valid values, after validation of each sample and\n    %% shrink. They must never hide a broken native factory or codec.\n    case {Bounds, Index} of\n        {[], none} -> Checked;\n        _ -> F:refine_input(Checked, fun(V) ->\n            lists:all(fun({Op, Bound}) -> lawspec_beam_scalar:binary(Op, V, Bound, Name, Name) end, Bounds)\n                andalso case Index of\n                    none -> true;\n                    {Target, _} when Target < 0 -> true;\n                    {Target, _} -> lawspec_beam_schema:index(V, T, 0, S) =:= Target\n                end\n        end)\n    end.\n\nvalue_nodes({ls_data, _, Fields}) -> 1 + lists:sum([value_nodes(V) || V <- Fields]);\nvalue_nodes({ls_presence, _, {some, V}}) -> 1 + value_nodes(V);\nvalue_nodes(Vs) when is_list(Vs) -> 1 + lists:sum([1 + value_nodes(V) || V <- Vs]);\nvalue_nodes(_) -> 1.\n\nbuild(F, T, S, Symbols, Budget, Bounds) ->\n    case factory(T, S) of\n        {ok, Factory} -> custom(F, T, S, Symbols, Budget, Bounds, none, Factory);\n        error -> build_native(F, T, S, Symbols, Budget, Bounds)\n    end.\n\nbuild_native(F, {<<\"List\">>, [T]}, S, Symbols, Budget, _) ->\n    case minimum(T, S, Budget - 1) of\n        none -> F:exactly([]);\n        Cost -> F:bind(F:integer(0, (Budget - 1) div Cost), fun\n            (0) -> F:exactly([]);\n            (Count) -> F:vector(Count, build(F, T, S, Symbols, (Budget - 1) div Count, []))\n        end)\n    end;\nbuild_native(F, {Name, [T]}, S, Symbols, Budget, _) when Name =:= <<\"Optional\">>; Name =:= <<\"Nullable\">> ->\n    Empty = F:exactly({ls_presence, Name, none}),\n    case minimum(T, S, Budget - 1) of\n        none -> Empty;\n        _ -> F:oneof([Empty, F:bind(build(F, T, S, Symbols, Budget - 1, []),\n            fun(V) -> {ls_presence, Name, {some, V}} end)])\n    end;\nbuild_native(F, T, S, Symbols, Budget, Bounds) ->\n    case lawspec_beam_schema:constructors(T, S) of\n        none -> scalar(F, T, maps:get(bits, S), Symbols, Bounds);\n        Constructors ->\n            Choices = [constructor(F, C, Allocation, S, Symbols) || Raw <- Constructors,\n                C <- lawspec_beam_schema:witness_instances(Raw),\n                Allocation <- [allocation(maps:get(fields, C), S, Budget - 1 - length(maps:get(witness_values, C)))],\n                Allocation =/= none],\n            F:constrain(F:oneof(Choices), fun(V) -> accepted(V, T, S) end)\n    end.\n\nconstructor(F, C, Allocation, S, Symbols) ->\n    Fields = maps:get(fields, C),\n    Types = [build(F, T, S, Symbols, Budget, []) || {{_, T}, Budget} <- lists:zip(Fields, Allocation)],\n    F:bind(F:fixed_list(Types), fun(Values) -> {ls_data, maps:get(tag, C), Values ++ maps:get(witness_values, C)} end).\n\naccepted(V, T, S) ->\n    try lawspec_beam_schema:validate(V, T, S), true catch\n        error:{lawspec, {refinement_violation, _}} -> false\n    end.\n\n%% The budget counts structural nodes, including scalar leaves. Searching the\n%% finite budget terminates for recursive types without assuming a base case.\n%% ref:DEC-structural-size-budget\nminimum(_, _, Limit) when Limit < 1 -> none;\nminimum(T, S, Limit) ->\n    Key = {T, S, Limit},\n    Cache = case get({?MODULE, minimum}) of undefined -> #{}; Existing -> Existing end,\n    case maps:find(Key, Cache) of\n        {ok, Cost} -> Cost;\n        error ->\n            Cost = minimum(T, S, 1, Limit),\n            %% Recursive calls have filled entries too; preserve them.\n            Current = case get({?MODULE, minimum}) of undefined -> #{}; Populated -> Populated end,\n            put({?MODULE, minimum}, Current#{Key => Cost}),\n            Cost\n    end.\nminimum(_, _, Cost, Limit) when Cost > Limit -> none;\nminimum(T, S, Cost, Limit) ->\n    case inhabited(T, S, Cost) of true -> Cost; false -> minimum(T, S, Cost + 1, Limit) end.\n\ninhabited(_, _, Budget) when Budget < 1 -> false;\ninhabited({Name, _}, _, _) when Name =:= <<\"List\">>; Name =:= <<\"Optional\">>; Name =:= <<\"Nullable\">> -> true;\ninhabited(T, S, Budget) ->\n    case factory(T, S) of\n        {ok, _} -> true;\n        error -> inhabited_native(T, S, Budget)\n    end.\ninhabited_native(T, S, Budget) ->\n    case lawspec_beam_schema:constructors(T, S) of\n        none -> true;\n        Cs -> lists:any(fun(C) -> allocation(maps:get(fields, C), S,\n            Budget - 1 - length(maps:get(witness_values, C))) =/= none end,\n            lists:append([lawspec_beam_schema:witness_instances(C) || C <- Cs]))\n    end.\n\nallocation(Fields, S, Budget) ->\n    case costs(Fields, S, Budget) of\n        none -> none;\n        [] -> [];\n        Minimums ->\n            Extra = Budget - lists:sum(Minimums), Count = length(Minimums),\n            [Cost + Extra div Count + case I =< Extra rem Count of true -> 1; false -> 0 end\n                || {I, Cost} <- lists:enumerate(Minimums)]\n    end.\ncosts([], _, Budget) when Budget >= 0 -> [];\ncosts(_, _, Budget) when Budget < 1 -> none;\ncosts([{_, T} | Fields], S, Budget) ->\n    case minimum(T, S, Budget) of\n        none -> none;\n        Cost -> case costs(Fields, S, Budget - Cost) of none -> none; Rest -> [Cost | Rest] end\n    end.\n\nscalar(F, {<<\"Bool\">>, []}, _, _, _) -> F:oneof([F:exactly(false), F:exactly(true)]);\nscalar(F, {<<\"Unit\">>, []}, _, _, _) -> F:exactly(ls_unit);\nscalar(F, {<<\"Null\">>, []}, _, _, _) -> F:exactly(ls_null);\nscalar(F, {<<\"Undefined\">>, []}, _, _, _) -> F:exactly(ls_undefined);\nscalar(F, {<<\"Rational\">>, []}, _, _, _) ->\n    F:bind(F:fixed_list([F:integer(none, none), F:integer(1, none)]), fun([N, D]) -> lawspec_beam_scalar:ratio(N, D) end);\nscalar(F, {<<\"Decimal\">>, []}, _, _, _) ->\n    F:bind(F:fixed_list([F:integer(none, none), F:sized(fun(Size) -> F:integer(-Size, Size) end)]),\n        fun([C, E]) -> lawspec_beam_scalar:decimal(C, E) end);\nscalar(F, {<<\"Float32\">>, []}, _, _, _) -> ieee(F, 32);\nscalar(F, {<<\"Float64\">>, []}, _, _, _) -> ieee(F, 64);\nscalar(F, {Name, []}, _, _, _) when Name =:= <<\"Complex64\">>; Name =:= <<\"Complex128\">> ->\n    W = case Name of <<\"Complex64\">> -> 32; _ -> 64 end,\n    F:bind(F:fixed_list([ieee(F, W), ieee(F, W)]), fun([R, I]) -> {ls_complex, W, R, I} end);\nscalar(F, {<<\"Char\">>, []}, _, _, _) -> unicode_scalar(F);\nscalar(F, {<<\"CodePoint\">>, []}, _, _, _) -> F:integer(0, 16#10ffff);\nscalar(F, {<<\"CodeUnit16\">>, []}, _, _, _) -> F:integer(0, 16#ffff);\nscalar(F, {<<\"Text\">>, []}, _, _, _) -> F:bind(F:list(unicode_scalar(F)), fun unicode:characters_to_binary/1);\nscalar(F, {<<\"Bytes\">>, []}, _, _, _) -> F:binary();\nscalar(F, {Name, []}, _, _, _) when Name =:= <<\"CodePointText\">>; Name =:= <<\"Utf16Text\">> ->\n    Max = case Name of <<\"CodePointText\">> -> 16#10ffff; _ -> 16#ffff end,\n    F:bind(F:list(F:integer(0, Max)), fun(Units) -> {ls_raw, Name, Units} end);\nscalar(F, {<<\"Symbol\">>, []}, _, Symbols, _) ->\n    F:bind(F:integer(0, none), fun(N) ->\n        Key = integer_to_binary(N), {ls_symbol, {{Symbols, generated}, Key}, Key}\n    end);\nscalar(F, {Name, []}, Bits, _, Bounds) ->\n    {Lo, Hi} = lists:foldl(fun limit/2, lawspec_beam_scalar:bounds(Name, Bits), Bounds),\n    case Lo =/= none andalso Hi =/= none andalso Lo > Hi of\n        true -> F:exactly('$lawspec_empty_domain');\n        false -> F:integer(Lo, Hi)\n    end.\n\nieee(F, Width) -> F:bind(F:integer(0, (1 bsl Width) - 1),\n    fun(Bits) -> lawspec_beam_scalar:float_bits(Width, Bits) end).\nunicode_scalar(F) -> F:oneof([F:integer(0, 16#d7ff), F:integer(16#e000, 16#10ffff)]).\n\nlimit({Op, V}, {Lo, Hi}) ->\n    {N, D} = lawspec_beam_scalar:exact(V),\n    Floor = N div D - case N < 0 andalso N rem D =/= 0 of true -> 1; false -> 0 end,\n    Ceil = Floor + case N rem D =/= 0 of true -> 1; false -> 0 end,\n    case Op of\n        <<\">\">> -> {lower(Lo, Floor + 1), Hi};\n        <<\">=\">> -> {lower(Lo, Ceil), Hi};\n        <<\"<\">> -> {Lo, upper(Hi, Ceil - 1)};\n        <<\"<=\">> -> {Lo, upper(Hi, Floor)};\n        <<\"==\">> -> {lower(Lo, Ceil), upper(Hi, Floor)};\n        _ -> {Lo, Hi}\n    end.\nlower(none, N) -> N;\nlower(L, N) -> max(L, N).\nupper(none, N) -> N;\nupper(H, N) -> min(H, N).\n\nwith_cache(Run) ->\n    Previous = erase({?MODULE, minimum}),\n    try lawspec_beam_index:with_cache(Run)\n    after\n        case Previous of\n            undefined -> erase({?MODULE, minimum});\n            _ -> put({?MODULE, minimum}, Previous)\n        end\n    end.\n"
runtimeSource "beam-stream-data" = "# Native StreamData generation and shrinking for the shared checked Core.\n# ref:DEC-native-property-frameworks ref:DEC-shrink-within-domain\ndefmodule LawSpec.Beam.StreamData do\n  @moduledoc false\n  alias StreamData, as: SD\n  @empty :\"$lawspec_empty_domain\"\n\n  def generator(type, schema, symbols, bounds, witnesses) do\n    :lawspec_beam_generators.generator(__MODULE__, type, schema, symbols, bounds, witnesses)\n  end\n\n  def generator(type, schema, symbols, bounds, witnesses, index) do\n    :lawspec_beam_generators.generator(__MODULE__, type, schema, symbols, bounds, witnesses, index)\n  end\n\n  def exactly(value), do: SD.constant(value)\n  def map(%SD{} = type, convert), do: SD.map(type, convert)\n  def map(_, _), do: :erlang.error({:lawspec, :expected_stream_data_generator})\n  def sized(build), do: SD.sized(build)\n  def frequency(choices), do: SD.frequency(choices)\n  def oneof(choices), do: SD.one_of(choices)\n  def list(type), do: SD.list_of(type)\n  def vector(count, type), do: SD.list_of(type, length: count)\n  def fixed_list(types), do: SD.map(SD.fixed_list(types), fn values ->\n    if @empty in values, do: @empty, else: values\n  end)\n  def binary(), do: SD.binary()\n\n  def integer(:none, :none), do: SD.integer()\n  def integer(lo, :none), do: SD.map(SD.non_negative_integer(), &(&1 + lo))\n  def integer(:none, hi), do: SD.map(SD.non_negative_integer(), &(hi - &1))\n  def integer(lo, hi), do: SD.integer(lo..hi)\n\n  def bind(type, build) do\n    SD.bind(type, fn\n      @empty -> exactly(@empty)\n      value ->\n        case build.(value) do\n          %SD{} = generator -> generator\n          constant -> exactly(constant)\n        end\n    end)\n  end\n\n  def constrain(type, predicate) do\n    filter(type, fn value -> value == @empty or predicate.(value) end)\n  end\n\n  def refine_input(type, predicate) do\n    bind(type, fn value -> if predicate.(value), do: value, else: @empty end)\n  end\n\n  def complete(type), do: filter(type, &(&1 != @empty))\n  def forall(type, predicate), do: {type, predicate}\n\n  defp filter(type, predicate) do\n    SD.sized(fn _ -> SD.filter(type, predicate, Process.get({__MODULE__, :attempts}, 100)) end)\n  end\n\n  # Catch failures inside check_all so StreamData can shrink them with its\n  # own tree. Preserve the smallest arguments and the native exception.\n  # ref:DEC-never-pass-vacuously ref:DEC-portable-seeded-generation\n  def check(label, {type, predicate}, options) do\n    seed = case System.get_env(\"LAWSPEC_SEED\") do\n      nil -> :erlang.bxor(System.system_time(:nanosecond), System.unique_integer([:positive]))\n      text -> String.to_integer(text)\n    end\n    settings = [\n      initial_seed: {:erlang.band(seed, 0xFFFFFFFF), :erlang.band(:erlang.bsr(seed, 32), 0xFFFFFFFF), 1},\n      max_runs: Keyword.fetch!(options, :numtests),\n      max_shrinking_steps: Keyword.fetch!(options, :max_shrinks)\n    ]\n    previous = Process.get({__MODULE__, :attempts})\n    Process.put({__MODULE__, :attempts}, Keyword.fetch!(options, :constraint_tries))\n    try do\n      result = :lawspec_beam_generators.with_cache(fn ->\n        SD.check_all(type, settings, fn values ->\n          try do\n            case predicate.(values) do\n              true -> {:ok, values}\n              false -> {:error, {:counterexample, values}}\n              other -> :erlang.error({:lawspec, {:non_boolean_property, other}})\n            end\n          catch\n            kind, reason -> {:error, {:counterexample, values, kind, reason, __STACKTRACE__}}\n          end\n        end)\n      end)\n      case result do\n        {:ok, _} -> :ok\n        {:error, failure} -> :erlang.error({:lawspec, {:property_failed, label, {:seed, seed}, failure}})\n      end\n    catch\n      :error, {:lawspec, {:property_failed, _, _, _}} = failure -> :erlang.error(failure)\n      kind, reason ->\n        :erlang.raise(:error, {:lawspec, {:property_failed, label, {:seed, seed}, {kind, reason}}}, __STACKTRACE__)\n    after\n      if previous == nil do\n        Process.delete({__MODULE__, :attempts})\n      else\n        Process.put({__MODULE__, :attempts}, previous)\n      end\n    end\n  end\nend\n"
runtimeSource "beam-index" = "%% @doc Solve structural indices before generating native framework trees.\n%% Reachability carries minimum node costs, so equal-index recursive branches\n%% also terminate within the structural budget. Children may have a larger\n%% index than their parent (subtraction, division, remainder and powers).\n%% ref:DEC-indexed-families-as-evidence ref:DEC-structural-size-budget\n-module(lawspec_beam_index).\n-export([generator/9, generator/10, with_cache/1]).\n\ngenerator(F, Type, Schema, Target, Equations, Budget, Minimum, Build, Accepted) ->\n    generator(F, Type, Schema, Target, Equations, Budget, Minimum, Build, Accepted, fun(_, _, _) -> none end).\ngenerator(F, Type, Schema, Target, Equations, Budget, Minimum, Build, Accepted, Override)\n        when is_integer(Target) ->\n    Parsed = maps:map(fun(_, Texts) -> equation(Texts) end, Equations),\n    Families = families([Type], #{}, Schema, Parsed),\n    Plain = maps:from_list([{T, Minimum(T)} || Cs <- maps:values(Families), C <- Cs,\n        {I, {_, T}} <- lists:enumerate(0, maps:get(fields, C)),\n        not lists:member(I, positions(C, Parsed))]),\n    Key = {Type, Schema, Equations, Plain},\n    Limit = max(0, Target) + 16,\n    Cache = case get({?MODULE, tables}) of undefined -> #{}; Existing -> Existing end,\n    {Costs, Choices} = case maps:find(Key, Cache) of\n        {ok, {Previous, Found, Solutions}} when Previous >= Limit -> {Found, Solutions};\n        _ ->\n            Found = reach(Families, Parsed, Plain, Limit, #{}),\n            Solutions = solutions(Families, Parsed, Plain, Limit, Found),\n            put({?MODULE, tables}, Cache#{Key => {Limit, Found, Solutions}}),\n            {Found, Solutions}\n    end,\n    Levels = case Target < 0 of\n        true -> lists:sublist(lists:sort([K || {T, K} <- maps:keys(Costs), T =:= Type]), 6);\n        false -> [Target || maps:is_key({Type, Target}, Costs)]\n    end,\n    case Levels of\n        [] when Target < 0 -> erlang:error({lawspec, {no_indexed_generator, Type}});\n        [] -> F:exactly('$lawspec_empty_domain');\n        _ -> F:bind(F:oneof([F:exactly(K) || K <- Levels]), fun(K) ->\n            Available = max(Budget, maps:get({Type, K}, Costs)),\n            indexed(F, Type, K, Available, Choices, Build, Accepted, Override)\n        end)\n    end.\n\nindexed(F, Type, K, Budget, Solutions, Build, Accepted, Override) ->\n    case Override(Type, K, Budget) of\n        {custom, Generator} -> Generator;\n        none -> indexed_native(F, Type, K, Budget, Solutions, Build, Accepted, Override)\n    end.\n\nindexed_native(F, Type, K, Budget, Solutions, Build, Accepted, Override) ->\n    Choices = [{C, Targets, Costs} || {C, Targets, Costs} <- maps:get({Type, K}, Solutions),\n        1 + length(maps:get(witness_values, C, [])) + lists:sum(Costs) =< Budget],\n    F:constrain(F:bind(F:oneof([F:exactly(Choice) || Choice <- Choices]),\n        fun({C, Targets, Costs}) ->\n            Witnesses = maps:get(witness_values, C, []),\n            Count = length(Costs),\n            Extra = Budget - 1 - length(Witnesses) - lists:sum(Costs),\n            Children = [begin\n                Share = Cost + Extra div Count + case I < Extra rem Count of true -> 1; false -> 0 end,\n                case maps:find(I, Targets) of\n                    {ok, Index} -> indexed(F, T, Index, Share, Solutions, Build, Accepted, Override);\n                    error -> Build(T, Share)\n                end\n            end || {I, {{_, T}, Cost}} <- lists:enumerate(0, lists:zip(maps:get(fields, C), Costs))],\n            F:bind(F:fixed_list(Children), fun(Values) ->\n                {ls_data, maps:get(tag, C), Values ++ Witnesses}\n            end)\n        end), fun(V) -> Accepted(Type, V) end).\n\nfamilies([], Found, _, _) -> Found;\nfamilies([T | Pending], Found, S, Equations) ->\n    case maps:is_key(T, Found) of\n        true -> families(Pending, Found, S, Equations);\n        false ->\n            Cs = case lawspec_beam_schema:constructors(T, S) of\n                none -> erlang:error({lawspec, {indexed_type_requires_data, T}});\n                Constructors -> lists:append([lawspec_beam_schema:witness_instances(C) || C <- Constructors])\n            end,\n            Children = [element(2, lists:nth(I + 1, maps:get(fields, C))) || C <- Cs,\n                I <- positions(C, Equations)],\n            families(Children ++ Pending, Found#{T => Cs}, S, Equations)\n    end.\n\npositions(C, Equations) -> element(3, maps:get(maps:get(tag, C), Equations)).\n\n%% The finite forward fixpoint supplies the least cost for each reachable\n%% index. Positive node costs make cycles harmless; later passes may find a\n%% cheaper construction and its parents then inherit that improvement.\nreach(Families, Equations, Plain, Limit, Costs) ->\n    Next = maps:fold(fun(T, Cs, Acc) ->\n        lists:foldl(fun(C, Current) ->\n            lists:foldl(fun({K, _, Fields}, Table) ->\n                Cost = 1 + length(maps:get(witness_values, C, [])) + lists:sum(Fields),\n                Key = {T, K},\n                case maps:find(Key, Table) of\n                    {ok, Existing} when Existing =< Cost -> Table;\n                    _ -> Table#{Key => Cost}\n                end\n            end, Current, assignments(C, Equations, Plain, Limit, Costs))\n        end, Acc, Cs)\n    end, Costs, Families),\n    case Next =:= Costs of true -> Costs; false -> reach(Families, Equations, Plain, Limit, Next) end.\n\nsolutions(Families, Equations, Plain, Limit, Costs) ->\n    maps:fold(fun(T, Cs, Table) ->\n        lists:foldl(fun(C, Acc) ->\n            lists:foldl(fun({K, Targets, Fields}, Current) ->\n                Key = {T, K},\n                Current#{Key => maps:get(Key, Current, []) ++ [{C, Targets, Fields}]}\n            end, Acc, assignments(C, Equations, Plain, Limit, Costs))\n        end, Table, Cs)\n    end, #{}, Families).\n\nassignments(C, Equations, Plain, Limit, Costs) ->\n    {Term, Guards, Positions} = maps:get(maps:get(tag, C), Equations),\n    Fields = maps:get(fields, C),\n    case lists:all(fun({I, {_, T}}) -> lists:member(I, Positions) orelse maps:get(T, Plain) =/= none end,\n            lists:enumerate(0, Fields)) of\n        false -> [];\n        true ->\n            Choices = [{I, lists:sort([K || {T0, K} <- maps:keys(Costs), T0 =:= T])} || I <- Positions,\n                {_, T} <- [lists:nth(I + 1, Fields)]],\n            [begin\n                Required = [case maps:find(I, Assigned) of\n                    {ok, K} -> maps:get({T, K}, Costs);\n                    error -> maps:get(T, Plain)\n                end || {I, {_, T}} <- lists:enumerate(0, Fields)],\n                {Value, Assigned, Required}\n            end || Assigned <- assign(Choices, Guards, #{}),\n                Value <- [evaluate(Term, Assigned)], is_integer(Value), Value >= 0, Value =< Limit]\n    end.\n\nassign(Choices, Guards, Assigned) ->\n    Ready = [G || G = {_, A, B} <- Guards,\n        lists:all(fun(I) -> maps:is_key(I, Assigned) end, fields(A) ++ fields(B))],\n    case lists:all(fun(G) -> holds(G, Assigned) end, Ready) of\n        false -> [];\n        true -> case Choices of\n            [] -> [Assigned];\n            [{I, Values} | Rest] -> lists:append([assign(Rest, Guards, Assigned#{I => V}) || V <- Values])\n        end\n    end.\n\nequation([Text | Guards]) ->\n    {Term, []} = parse(tokens(Text)),\n    Parsed = [guard(G) || G <- Guards],\n    Positions = lists:usort(fields(Term) ++ lists:append([fields(A) ++ fields(B) || {_, A, B} <- Parsed])),\n    {Term, Parsed, Positions}.\n\nguard(Text) ->\n    [Op | Rest] = tokens(Text),\n    true = Op =:= <<\"==\">> orelse Op =:= <<\">=\">>,\n    {A, Next} = parse(Rest),\n    {B, []} = parse(Next),\n    {Op, A, B}.\n\ntokens(Text) -> binary:split(Text, <<\" \">>, [global, trim_all]).\nparse([<<\"c\", N/binary>> | Rest]) -> {{constant, binary_to_integer(N)}, Rest};\nparse([<<\"f\", N/binary>> | Rest]) -> {{field, binary_to_integer(N)}, Rest};\nparse([Op | Rest]) ->\n    true = lists:member(Op, [<<\"+\">>, <<\"-\">>, <<\"*\">>, <<\"div\">>, <<\"mod\">>, <<\"^\">>]),\n    {A, Next} = parse(Rest),\n    {B, After} = parse(Next),\n    {{Op, A, B}, After}.\n\nfields({constant, _}) -> [];\nfields({field, I}) -> [I];\nfields({_, A, B}) -> fields(A) ++ fields(B).\n\nevaluate({constant, N}, _) -> N;\nevaluate({field, I}, Assigned) -> maps:get(I, Assigned, undefined);\nevaluate({Op, A, B}, Assigned) -> binary(Op, evaluate(A, Assigned), evaluate(B, Assigned)).\n\nbinary(_, undefined, _) -> undefined;\nbinary(_, _, undefined) -> undefined;\nbinary(<<\"+\">>, A, B) -> A + B;\nbinary(<<\"-\">>, A, B) when A >= B -> A - B;\nbinary(<<\"*\">>, A, B) -> A * B;\nbinary(<<\"div\">>, A, B) when B > 0 -> A div B;\nbinary(<<\"mod\">>, A, B) when B > 0 -> A rem B;\nbinary(<<\"^\">>, A, B) when B >= 0, B =< 64 -> power(A, B);\nbinary(_, _, _) -> undefined.\npower(_, 0) -> 1;\npower(A, B) when B rem 2 =:= 0 -> power(A * A, B div 2);\npower(A, B) -> A * power(A, B - 1).\n\nholds({Relation, A, B}, Assigned) ->\n    X = evaluate(A, Assigned), Y = evaluate(B, Assigned),\n    is_integer(X) andalso is_integer(Y) andalso\n        case Relation of <<\"==\">> -> X =:= Y; <<\">=\">> -> X >= Y end.\n\nwith_cache(Run) ->\n    Previous = erase({?MODULE, tables}),\n    try Run()\n    after\n        case Previous of undefined -> erase({?MODULE, tables}); _ -> put({?MODULE, tables}, Previous) end\n    end.\n"
runtimeSource "beam-qcheck" = "%% @doc Native qcheck combinators and shrink trees. The bounded filter removes\n%% invalid shrink candidates; the lazy cap limits qcheck's own shrink traversal.\n%% ref:DEC-native-property-frameworks ref:DEC-shrink-within-domain\n-module(lawspec_beam_qcheck).\n-export([generator/5, generator/6, map/2, bind/2, constrain/2, refine_input/2, complete/1, check/3,\n    exactly/1, sized/1, frequency/1, oneof/1, integer/2, list/1, vector/2,\n    fixed_list/1, binary/0, forall/2]).\n\ngenerator(T, Schema, Symbols, Bounds, Witnesses) ->\n    lawspec_beam_generators:generator(?MODULE, T, Schema, Symbols, Bounds, Witnesses).\ngenerator(T, Schema, Symbols, Bounds, Witnesses, Index) ->\n    lawspec_beam_generators:generator(?MODULE, T, Schema, Symbols, Bounds, Witnesses, Index).\nexactly(V) -> qcheck:constant(V).\nsized(Build) -> qcheck:sized_from(Build, qcheck:small_non_negative_int()).\nfrequency([Choice | Choices]) -> qcheck:from_weighted_generators(Choice, Choices).\noneof([Choice | Choices]) -> qcheck:from_generators(Choice, Choices).\nlist(Type) -> qcheck:list_from(Type).\nvector(Count, Type) -> qcheck:fixed_length_list_from(Type, Count).\nfixed_list(Types) -> qcheck:map(lists:foldr(fun(Type, Tail) ->\n    qcheck:map2(Type, Tail, fun(H, T) -> [H | T] end)\nend, exactly([]), Types), fun(Values) ->\n    case lists:member('$lawspec_empty_domain', Values) of true -> '$lawspec_empty_domain'; false -> Values end\nend).\nbinary() -> qcheck:byte_aligned_bit_array().\nforall(Type, Predicate) -> {Type, Predicate}.\n\nmap({generator, Build} = Type, Convert) when is_function(Build, 1) -> qcheck:map(Type, Convert);\nmap(_, _) -> erlang:error({lawspec, expected_qcheck_generator}).\n\nbind(Type, Build) -> qcheck:bind(Type, fun\n    ('$lawspec_empty_domain') -> exactly('$lawspec_empty_domain');\n    (Value) -> case Build(Value) of\n        {generator, F} = Generator when is_function(F, 1) -> Generator;\n        Constant -> exactly(Constant)\n    end\nend).\nconstrain(Type, Predicate) -> filter(Type, fun\n    ('$lawspec_empty_domain') -> true;\n    (Value) -> Predicate(Value)\nend).\ncomplete(Type) -> filter(Type, fun(V) -> V =/= '$lawspec_empty_domain' end).\nrefine_input(Type, Predicate) -> bind(Type, fun(Value) ->\n    case Predicate(Value) of true -> Value; false -> '$lawspec_empty_domain' end\nend).\n\nfilter(Type, Predicate) -> {generator, fun(Seed) ->\n    filtered(Type, Predicate, setting(attempts, 100), Seed)\nend}.\nfiltered(_, _, 0, _) -> erlang:error({lawspec, exhausted_generator_attempts});\nfiltered(Type, Predicate, Attempts, Seed) ->\n    {{tree, Value, _} = Tree, Next} = qcheck:generate_tree(Type, Seed),\n    case Predicate(Value) of\n        true -> {prune(Tree, Predicate), Next};\n        false -> filtered(Type, Predicate, Attempts - 1, Next)\n    end.\nprune({tree, Value, Children}, Predicate) ->\n    Valid = 'gleam@yielder':filter(Children, fun({tree, V, _}) -> Predicate(V) end),\n    {tree, Value, 'gleam@yielder':map(Valid, fun(Child) -> prune(Child, Predicate) end)}.\n\n%% qcheck's PRNG documents a 32-bit native integer range. Compose its native\n%% limb generators for wider values; do not truncate Int64, UInt64 or IEEE bits.\n%% Every limb still carries qcheck's shrink tree, and the map stays in-domain.\n%% ref:DEC-portable-exact-arithmetic\ninteger(none, none) -> bind(oneof([exactly(1), exactly(-1)]), fun(Sign) ->\n    qcheck:map(non_negative(), fun(N) -> Sign * N end)\nend);\ninteger(Lo, none) -> qcheck:map(non_negative(), fun(N) -> Lo + N end);\ninteger(none, Hi) -> qcheck:map(non_negative(), fun(N) -> Hi - N end);\ninteger(Lo, Hi) when Lo > Hi -> exactly('$lawspec_empty_domain');\ninteger(Lo, Hi) when Hi - Lo < 16#100000000 -> qcheck:bounded_int(Lo, Hi);\ninteger(Lo, Hi) when Lo >= 0 -> qcheck:map(magnitude(Hi - Lo + 1), fun(N) -> Lo + N end);\ninteger(Lo, Hi) when Hi =< 0 -> qcheck:map(magnitude(Hi - Lo + 1), fun(N) -> Hi - N end);\ninteger(Lo, Hi) -> oneof([magnitude(Hi + 1), qcheck:map(magnitude(1 - Lo), fun(N) -> -N end)]).\n\nnon_negative() -> sized(fun(Size) -> magnitude(1 bsl (8 * (Size + 1))) end).\nmagnitude(Max) when Max =< 16#100000000 -> qcheck:bounded_int(0, Max - 1);\nmagnitude(Max) ->\n    Limbs = vector(limb_count(Max - 1), qcheck:bounded_int(0, 16#ffff)),\n    qcheck:map(Limbs, fun(Values) ->\n        lists:foldl(fun(Limb, N) -> (N bsl 16) bor Limb end, 0, Values) rem Max\n    end).\nlimb_count(0) -> 0;\nlimb_count(N) -> 1 + limb_count(N bsr 16).\n\n%% The framework has no max-shrinks option. Stop yielding native candidates\n%% after the budget, across siblings and descendants of the entire tree.\nlimit(Type, Maximum) -> {generator, fun(Seed) ->\n    {Tree, Next} = qcheck:generate_tree(Type, Seed),\n    put({?MODULE, remaining}, Maximum),\n    {limit_tree(Tree), Next}\nend}.\nlimit_tree({tree, Value, Children}) ->\n    {tree, Value, 'gleam@yielder':unfold(Children, fun(Rest) ->\n        case setting(remaining, 0) of\n            0 -> done;\n            N -> case 'gleam@yielder':step(Rest) of\n                done -> done;\n                {next, Child, Tail} ->\n                    put({?MODULE, remaining}, N - 1),\n                    {next, limit_tree(Child), Tail}\n            end\n        end\n    end)}.\n\nsetting(Key, Default) -> case get({?MODULE, Key}) of undefined -> Default; Value -> Value end.\n\n%% ref:DEC-never-pass-vacuously ref:DEC-portable-seeded-generation\ncheck(Label, {Type, Predicate}, Options) ->\n    Seed = case os:getenv(\"LAWSPEC_SEED\") of\n        false -> erlang:system_time(nanosecond) bxor erlang:unique_integer([positive]);\n        Text -> list_to_integer(Text)\n    end,\n    Keys = [attempts, remaining, failure],\n    Previous = [{K, erase({?MODULE, K})} || K <- Keys],\n    put({?MODULE, attempts}, proplists:get_value(constraint_tries, Options, 100)),\n    try\n        lawspec_beam_generators:with_cache(fun() ->\n            Config = qcheck:config(proplists:get_value(numtests, Options, 100), 1, qcheck:seed(Seed)),\n            qcheck:run(Config, limit(Type, proplists:get_value(max_shrinks, Options, 1000)), fun(Value) ->\n                try\n                    case Predicate(Value) of\n                        true -> nil;\n                        false -> erlang:error({lawspec, false_property});\n                        Other -> erlang:error({lawspec, {non_boolean_property, Other}})\n                    end\n                catch Kind:Reason:Stack ->\n                    put({?MODULE, failure}, {counterexample, Value, Kind, Reason}),\n                    erlang:raise(Kind, Reason, Stack)\n                end\n            end),\n            ok\n        end)\n    catch Kind:Reason:Stack ->\n        erlang:raise(error, {lawspec, {property_failed, Label, {seed, Seed},\n            {Kind, Reason}, setting(failure, none)}}, Stack)\n    after\n        lists:foreach(fun({K, undefined}) -> erase({?MODULE, K});\n            ({K, V}) -> put({?MODULE, K}, V) end, Previous)\n    end.\n"
runtimeSource "beam-gleam" = "%% @doc Native Gleam representations and typed scalar facade entry points.\n%% ref:DEC-native-bindings-typed-identity ref:DEC-portable-exact-arithmetic\n-module(lawspec_beam_gleam).\n-export([codecs/0, float32_from_bits/1, float64_from_bits/1, float_bits/1,\n    float32_from_native/1, float64_from_native/1, float_to_native/1,\n    complex64/2, complex128/2, complex_parts/1, decimal_parts/1,\n    scalar_binary/4, scalar_compare/2, symbol_description/1, run_case/2]).\n\ncodecs() -> #{\n    <<\"Unit\">> => #{encode => fun(ls_unit, []) -> nil end,\n        decode => fun(nil, []) -> ls_unit; (_, _) -> fail(unit) end},\n    <<\"Maybe\">> => #{encode => fun\n        ({ls_data, <<\"Maybe::Nothing\">>, []}, [_]) -> none;\n        ({ls_data, <<\"Maybe::Just\">>, [V]}, [F]) -> {some, F(V)} end,\n        decode => fun\n            (none, [_]) -> {ls_data, <<\"Maybe::Nothing\">>, []};\n            ({some, V}, [F]) -> {ls_data, <<\"Maybe::Just\">>, [F(V)]};\n            (_, _) -> fail('maybe') end},\n    <<\"Either\">> => #{encode => fun\n        ({ls_data, <<\"Either::Left\">>, [V]}, [F, _]) -> {error, F(V)};\n        ({ls_data, <<\"Either::Right\">>, [V]}, [_, F]) -> {ok, F(V)} end,\n        decode => fun\n            ({error, V}, [F, _]) -> {ls_data, <<\"Either::Left\">>, [F(V)]};\n            ({ok, V}, [_, F]) -> {ls_data, <<\"Either::Right\">>, [F(V)]};\n            (_, _) -> fail(either) end},\n    <<\"Optional\">> => presence_codec(<<\"Optional\">>, absent, present),\n    <<\"Nullable\">> => presence_codec(<<\"Nullable\">>, null_value, non_null)\n}.\n\npresence_codec(Name, Empty, Present) -> #{\n    encode => fun\n        ({ls_presence, N, none}, [_]) when N =:= Name -> Empty;\n        ({ls_presence, N, {some, V}}, [F]) when N =:= Name -> {Present, F(V)} end,\n    decode => fun\n        (E, [_]) when E =:= Empty -> {ls_presence, Name, none};\n        ({P, V}, [F]) when P =:= Present -> {ls_presence, Name, {some, F(V)}};\n        (_, _) -> fail(Name) end\n}.\nfail(Type) -> erlang:error({lawspec, {invalid_gleam_value, Type}}).\n\nfloat32_from_bits(Bits) -> lawspec_beam_scalar:float_bits(32, Bits).\nfloat64_from_bits(Bits) -> lawspec_beam_scalar:float_bits(64, Bits).\nfloat_bits({ls_float, _, Bits}) -> Bits.\nfloat32_from_native(Value) -> lawspec_beam_scalar:float_from_native(32, Value).\nfloat64_from_native(Value) -> lawspec_beam_scalar:float_from_native(64, Value).\nfloat_to_native(Value) ->\n    case lawspec_beam_scalar:float_class(Value) of\n        nan -> {error, <<\"NaN has no native BEAM float representation\">>};\n        infinity -> {error, <<\"Infinity has no native BEAM float representation\">>};\n        _ -> {ok, lawspec_beam_scalar:float_to_native(Value)}\n    end.\ncomplex64(R, I) -> complex(32, R, I).\ncomplex128(R, I) -> complex(64, R, I).\ncomplex(W, {ls_float, W, _} = R, {ls_float, W, _} = I) -> {ls_complex, W, R, I}.\ncomplex_parts({ls_complex, _, R, I}) -> {R, I}.\ndecimal_parts({ls_decimal, C, E}) -> {C, E}.\nscalar_binary(Op, Type, A, B) -> lawspec_beam_scalar:binary(Op, A, B, Type, Type).\nscalar_compare(A, B) -> case lawspec_beam_scalar:float_compare(A, B) of\n    unordered -> none;\n    Value -> {some, Value}\nend.\nsymbol_description({ls_symbol, _, Description}) -> Description.\n\n%% Called by native Gleeunit functions, after the factory has initialized the\n%% checked Core case. The Erlang case returns true/ok; Gleam functions return Nil.\nrun_case(Cases, Index) ->\n    {_, Run} = lists:nth(Index + 1, Cases), Run(), nil.\n"
runtimeSource "beam-gleam-types" = "//// Native values for portable scalars that BEAM cannot represent directly.\n//// All arithmetic and checked conversion use the shared exact runtime.\n//// ref:DEC-portable-exact-arithmetic ref:DEC-idiomatic-generated-types\n\npub type Float32\npub type Float64\npub type Complex64\npub type Complex128\npub type Rational\npub type Decimal\npub type Symbol\n\npub type Null {\n  Null\n}\n\npub type Undefined {\n  Undefined\n}\n\npub type Optional(a) {\n  Absent\n  Present(a)\n}\n\npub type Nullable(a) {\n  NullValue\n  NonNull(a)\n}\n"
runtimeSource "beam-gleam-scalar" = "//// Typed operations on the portable exact and IEEE scalar values.\n//// ref:DEC-portable-exact-arithmetic ref:DEC-idiomatic-generated-types\n\nimport lawspec/types\nimport gleam/option\n\n@external(erlang, \"lawspec_beam_scalar\", \"ratio\")\npub fn rational(numerator: Int, denominator: Int) -> types.Rational\n\n@external(erlang, \"lawspec_beam_scalar\", \"exact\")\npub fn rational_parts(value: types.Rational) -> #(Int, Int)\n\n@external(erlang, \"lawspec_beam_scalar\", \"decimal\")\npub fn decimal(coefficient: Int, exponent: Int) -> types.Decimal\n\n@external(erlang, \"lawspec_beam_gleam\", \"decimal_parts\")\npub fn decimal_parts(value: types.Decimal) -> #(Int, Int)\n\n@external(erlang, \"lawspec_beam_gleam\", \"float32_from_bits\")\npub fn float32_from_bits(bits: Int) -> types.Float32\n\n@external(erlang, \"lawspec_beam_gleam\", \"float_bits\")\npub fn float32_bits(value: types.Float32) -> Int\n\n@external(erlang, \"lawspec_beam_gleam\", \"float32_from_native\")\npub fn float32_from_float(value: Float) -> types.Float32\n\n@external(erlang, \"lawspec_beam_gleam\", \"float_to_native\")\npub fn float32_to_float(value: types.Float32) -> Result(Float, String)\n\n@external(erlang, \"lawspec_beam_gleam\", \"scalar_compare\")\npub fn float32_compare(a: types.Float32, b: types.Float32) -> option.Option(Int)\n\n@external(erlang, \"lawspec_beam_gleam\", \"float64_from_bits\")\npub fn float64_from_bits(bits: Int) -> types.Float64\n\n@external(erlang, \"lawspec_beam_gleam\", \"float_bits\")\npub fn float64_bits(value: types.Float64) -> Int\n\n@external(erlang, \"lawspec_beam_gleam\", \"float64_from_native\")\npub fn float64_from_float(value: Float) -> types.Float64\n\n@external(erlang, \"lawspec_beam_gleam\", \"float_to_native\")\npub fn float64_to_float(value: types.Float64) -> Result(Float, String)\n\n@external(erlang, \"lawspec_beam_gleam\", \"scalar_compare\")\npub fn float64_compare(a: types.Float64, b: types.Float64) -> option.Option(Int)\n\n@external(erlang, \"lawspec_beam_gleam\", \"complex64\")\npub fn complex64(real: types.Float32, imaginary: types.Float32) -> types.Complex64\n\n@external(erlang, \"lawspec_beam_gleam\", \"complex_parts\")\npub fn complex64_parts(value: types.Complex64) -> #(types.Float32, types.Float32)\n\n@external(erlang, \"lawspec_beam_gleam\", \"complex128\")\npub fn complex128(real: types.Float64, imaginary: types.Float64) -> types.Complex128\n\n@external(erlang, \"lawspec_beam_gleam\", \"complex_parts\")\npub fn complex128_parts(value: types.Complex128) -> #(types.Float64, types.Float64)\n\n@external(erlang, \"lawspec_beam_scalar\", \"new_symbol\")\npub fn symbol(description: String) -> types.Symbol\n\n@external(erlang, \"lawspec_beam_gleam\", \"symbol_description\")\npub fn symbol_description(value: types.Symbol) -> String\n\n@external(erlang, \"lawspec_beam_scalar\", \"equal\")\npub fn symbol_equal(a: types.Symbol, b: types.Symbol) -> Bool\n\n@external(erlang, \"lawspec_beam_gleam\", \"scalar_binary\")\nfn binary(op: String, kind: String, a: value, b: value) -> value\n\npub fn rational_add(a: types.Rational, b: types.Rational) -> types.Rational {\n  binary(\"+\", \"Rational\", a, b)\n}\n\npub fn rational_subtract(a: types.Rational, b: types.Rational) -> types.Rational {\n  binary(\"-\", \"Rational\", a, b)\n}\n\npub fn rational_multiply(a: types.Rational, b: types.Rational) -> types.Rational {\n  binary(\"*\", \"Rational\", a, b)\n}\n\npub fn rational_divide(a: types.Rational, b: types.Rational) -> types.Rational {\n  binary(\"/\", \"Rational\", a, b)\n}\n\n@external(erlang, \"lawspec_beam_scalar\", \"equal\")\npub fn rational_equal(a: types.Rational, b: types.Rational) -> Bool\n\n@external(erlang, \"lawspec_beam_scalar\", \"negate\")\npub fn rational_negate(value: types.Rational) -> types.Rational\n\npub fn decimal_add(a: types.Decimal, b: types.Decimal) -> types.Decimal {\n  binary(\"+\", \"Decimal\", a, b)\n}\n\npub fn decimal_subtract(a: types.Decimal, b: types.Decimal) -> types.Decimal {\n  binary(\"-\", \"Decimal\", a, b)\n}\n\npub fn decimal_multiply(a: types.Decimal, b: types.Decimal) -> types.Decimal {\n  binary(\"*\", \"Decimal\", a, b)\n}\n\n@external(erlang, \"lawspec_beam_scalar\", \"equal\")\npub fn decimal_equal(a: types.Decimal, b: types.Decimal) -> Bool\n\n@external(erlang, \"lawspec_beam_scalar\", \"negate\")\npub fn decimal_negate(value: types.Decimal) -> types.Decimal\n\npub fn float32_add(a: types.Float32, b: types.Float32) -> types.Float32 {\n  binary(\"+\", \"Float32\", a, b)\n}\n\npub fn float32_subtract(a: types.Float32, b: types.Float32) -> types.Float32 {\n  binary(\"-\", \"Float32\", a, b)\n}\n\npub fn float32_multiply(a: types.Float32, b: types.Float32) -> types.Float32 {\n  binary(\"*\", \"Float32\", a, b)\n}\n\npub fn float32_divide(a: types.Float32, b: types.Float32) -> types.Float32 {\n  binary(\"/\", \"Float32\", a, b)\n}\n\n@external(erlang, \"lawspec_beam_scalar\", \"equal\")\npub fn float32_equal(a: types.Float32, b: types.Float32) -> Bool\n\n@external(erlang, \"lawspec_beam_scalar\", \"negate\")\npub fn float32_negate(value: types.Float32) -> types.Float32\n\npub fn float64_add(a: types.Float64, b: types.Float64) -> types.Float64 {\n  binary(\"+\", \"Float64\", a, b)\n}\n\npub fn float64_subtract(a: types.Float64, b: types.Float64) -> types.Float64 {\n  binary(\"-\", \"Float64\", a, b)\n}\n\npub fn float64_multiply(a: types.Float64, b: types.Float64) -> types.Float64 {\n  binary(\"*\", \"Float64\", a, b)\n}\n\npub fn float64_divide(a: types.Float64, b: types.Float64) -> types.Float64 {\n  binary(\"/\", \"Float64\", a, b)\n}\n\n@external(erlang, \"lawspec_beam_scalar\", \"equal\")\npub fn float64_equal(a: types.Float64, b: types.Float64) -> Bool\n\n@external(erlang, \"lawspec_beam_scalar\", \"negate\")\npub fn float64_negate(value: types.Float64) -> types.Float64\n\npub fn complex64_add(a: types.Complex64, b: types.Complex64) -> types.Complex64 {\n  binary(\"+\", \"Complex64\", a, b)\n}\n\npub fn complex64_subtract(a: types.Complex64, b: types.Complex64) -> types.Complex64 {\n  binary(\"-\", \"Complex64\", a, b)\n}\n\npub fn complex64_multiply(a: types.Complex64, b: types.Complex64) -> types.Complex64 {\n  binary(\"*\", \"Complex64\", a, b)\n}\n\npub fn complex64_divide(a: types.Complex64, b: types.Complex64) -> types.Complex64 {\n  binary(\"/\", \"Complex64\", a, b)\n}\n\n@external(erlang, \"lawspec_beam_scalar\", \"equal\")\npub fn complex64_equal(a: types.Complex64, b: types.Complex64) -> Bool\n\n@external(erlang, \"lawspec_beam_scalar\", \"negate\")\npub fn complex64_negate(value: types.Complex64) -> types.Complex64\n\npub fn complex128_add(a: types.Complex128, b: types.Complex128) -> types.Complex128 {\n  binary(\"+\", \"Complex128\", a, b)\n}\n\npub fn complex128_subtract(a: types.Complex128, b: types.Complex128) -> types.Complex128 {\n  binary(\"-\", \"Complex128\", a, b)\n}\n\npub fn complex128_multiply(a: types.Complex128, b: types.Complex128) -> types.Complex128 {\n  binary(\"*\", \"Complex128\", a, b)\n}\n\npub fn complex128_divide(a: types.Complex128, b: types.Complex128) -> types.Complex128 {\n  binary(\"/\", \"Complex128\", a, b)\n}\n\n@external(erlang, \"lawspec_beam_scalar\", \"equal\")\npub fn complex128_equal(a: types.Complex128, b: types.Complex128) -> Bool\n\n@external(erlang, \"lawspec_beam_scalar\", \"negate\")\npub fn complex128_negate(value: types.Complex128) -> types.Complex128\n"
runtimeSource "beam-gleam-failures" = "// Native adapters raise a value of the failure type in their declaration.\n// The generated boundary validates it before the Fail ability carries it.\n// ref:DEC-typed-core-boundary\n@external(erlang, \"lawspec_beam_effects\", \"fail\")\npub fn fail(value: a) -> b\n"
runtimeSource "beam-gleam-effects" = "// Scoped native handlers retain their logical context across checked calls.\n// ref:DEC-typed-core-boundary\npub type Context\n\npub type HandlerOrigin\n\n// Cells allocated by a native production factory or with_context belong to\n// that scope. Their storage is shared by concurrent callers and released when\n// the scope ends, including failure and cancellation.\npub type Cell(a)\n\n@external(erlang, \"lawspec_beam_effects\", \"native_cell\")\npub fn new_cell(initial: a) -> Cell(a)\n\n@external(erlang, \"lawspec_beam_effects\", \"native_read\")\npub fn read_cell(cell: Cell(a)) -> a\n\n@external(erlang, \"lawspec_beam_effects\", \"native_write\")\nfn store_cell(cell: Cell(a), value: a) -> a\n\npub fn write_cell(cell: Cell(a), value: a) -> Nil {\n  let _ = store_cell(cell, value)\n  Nil\n}\n\n@external(erlang, \"lawspec_beam_effects\", \"native_origin\")\npub fn native_origin() -> HandlerOrigin\n\n@external(erlang, \"lawspec_abilities\", \"with_context\")\npub fn with_context(body: fn(Context) -> a) -> a\n"
runtimeSource "beam-gleam-workflow" = "// Scoped workflow state is shared by generated calls and their async workers.\n// The callback owns the runtime; it must not escape that callback.\n// ref:DEC-domain-modeling-primitives ref:DEC-idiomatic-generated-types\npub type Runtime\n\npub type Event {\n  Event(kind: String, stage: String, number: Int, succeeded: Bool)\n}\n\n@external(erlang, \"lawspec_beam_workflow\", \"with_virtual\")\npub fn with_virtual(seed: Int, body: fn(Runtime) -> a) -> a\n\n@external(erlang, \"lawspec_beam_workflow\", \"with_real\")\npub fn with_real(seed: Int, body: fn(Runtime) -> a) -> a\n\n@external(erlang, \"lawspec_beam_workflow\", \"with_clock_callbacks\")\npub fn with_clock(\n  now: fn() -> Int,\n  sleep: fn(Int) -> Nil,\n  virtual: Bool,\n  seed: Int,\n  body: fn(Runtime) -> a,\n) -> a\n\n@external(erlang, \"lawspec_beam_workflow\", \"now\")\npub fn now(runtime: Runtime) -> Int\n\n@external(erlang, \"lawspec_beam_workflow\", \"native_sleep\")\npub fn sleep(runtime: Runtime, micros: Int) -> Nil\n\n// Only a runtime created with with_virtual has a directly adjustable clock.\n@external(erlang, \"lawspec_beam_workflow\", \"native_set_time\")\npub fn set_time(runtime: Runtime, micros: Int) -> Nil\n\n@external(erlang, \"lawspec_beam_workflow\", \"native_trace\")\npub fn trace(runtime: Runtime) -> List(Event)\n"
runtimeSource "python" = "\"\"\"LawSpec's runtime for Python: the portable scalar domain, seeded generation,\nmodels, actors, sessions and nodes, with no test-framework dependency.\n\nA law must mean the same thing on every target, so this module implements\nLawSpec's own arithmetic, equality and conversions instead of Python's:\nintegers are exact and reach a bounded type only through a checked conversion,\nexact division gives a Fraction, decimals ignore the ambient context, and\nfloats follow IEEE 754 at their declared precision.\nref:DEC-portable-exact-arithmetic ref:ieee-754 ref:decimal-arithmetic\n\nIt is emitted unchanged into every generated Python project, so the generated\ntests and the adapters share one definition of the domain.\nref:DEC-typed-core-boundary\n\"\"\"\nfrom collections import deque  # noqa: F401  (native Queue, Stack, Deque)\nfrom datetime import timedelta  # noqa: F401  (native Duration)\nfrom dataclasses import dataclass\nfrom fractions import Fraction\nfrom decimal import Decimal\nimport math\nimport struct\nimport threading\n\n\n@dataclass(frozen=True)\nclass Presence:\n    kind: str\n    present: bool\n    value: object = None\n\n\n@dataclass(eq=False, frozen=True)\nclass DataValue:\n    tag: str\n    fields: tuple\n\n    def __post_init__(self):\n        object.__setattr__(self, 'fields', tuple(self.fields))\n\n\n@dataclass(frozen=True)\nclass Raw:\n    kind: str\n    units: tuple\n\n    def __post_init__(self):\n        object.__setattr__(self, 'units', tuple(self.units))\n\n\n@dataclass(eq=False, frozen=True)\nclass Symbol:\n    description: str\n\n\n@dataclass(frozen=True)\nclass Absence:\n    kind: str\n\n\n(UNIT, NULL, UNDEFINED) = (Absence(t) for t in ('Unit', 'Null', 'Undefined'))\n\n\ndef integer_type(t):\n    return t.startswith(('Int', 'UInt')) or t in ('BigInt', 'BigUInt')\n\n\ndef exact_type(t):\n    return integer_type(t) or t in ('Decimal', 'Rational')\n\n\ndef bounds(t, bits=64):\n    if t in ('Integer', 'BigInt', 'BigUInt'):\n        return (0 if t == 'BigUInt' else None, None)\n    width = (bits if t in ('IntSize', 'UIntSize', 'UIntPtr') else\n             int(t[4:] if t.startswith('UInt') else t[3:]))\n    return ((0, 2 ** width - 1) if t.startswith('U') else\n            (-2 ** (width - 1), 2 ** (width - 1) - 1))\n\n\ndef f32(x):\n    try:\n        return struct.unpack('>f', struct.pack('>f', x))[0]\n    except OverflowError:\n        return math.copysign(math.inf, x)\n\n\ndef ratio(x):\n    if isinstance(x, bool):\n        raise ValueError('Bool is not an integer')\n    return Fraction(x)\n\n\ndef finite_decimal(r):\n    r = ratio(r)\n    (d, a, b) = (r.denominator, 0, 0)\n    while d % 2 == 0:\n        d //= 2\n        a += 1\n    while d % 5 == 0:\n        d //= 5\n        b += 1\n    if d != 1:\n        raise ValueError('Decimal conversion is not finite; use round')\n    scale = max(a, b)\n    c = r.numerator * 2 ** (scale - a) * 5 ** (scale - b)\n    return Decimal((int(c < 0), tuple(map(int, integer_text(abs(c)))), -scale))\n\n\ndef convert(x, t, bits=64):\n    \"\"\"Moves a value into the declared type, failing instead of wrapping or\n    rounding silently, because a bounded type is only ever reached through a\n    checked conversion. ref:DEC-portable-exact-arithmetic\"\"\"\n    if integer_type(t):\n        r = ratio(x)\n        if r.denominator != 1:\n            raise ValueError('fractional conversion to ' + t)\n        x = r.numerator\n        (lo, hi) = bounds(t, bits)\n        if lo is not None and x < lo or (hi is not None and x > hi):\n            raise ValueError('integer outside ' + t + ' range')\n        return x\n    if t == 'Rational':\n        return ratio(x)\n    if t == 'Decimal':\n        return finite_decimal(x)\n    if t in ('Float32', 'Float64'):\n        if not isinstance(x, float):\n            return exact_float(ratio(x), t)\n        try:\n            v = float(x)\n        except OverflowError:\n            v = math.copysign(math.inf, -1 if x < 0 else 1)\n        return f32(v) if t == 'Float32' else v\n    if t in ('Complex64', 'Complex128'):\n        z = (x if isinstance(x, complex) else\n             complex(\n                 convert(x, 'Float32' if t == 'Complex64' else 'Float64'), 0))\n        return complex(f32(z.real), f32(z.imag)) if t == 'Complex64' else z\n    return validate(x, t, bits)\n\n\ndef valid_unit(t, c):\n    maximum = (255 if t == 'Bytes' else\n               65535 if t in ('Utf16Text', 'CodeUnit16') else 1114111)\n    return (type(c) is int and 0 <= c <= maximum and\n            (t not in ('Text', 'Char') or not 55296 <= c <= 57343))\n\n\ndef validate(x, t, bits=64):\n    \"\"\"Checks a value an adapter produced against its declared domain: native\n    code may return anything its own type allows, and a law quantifies only\n    over the declared domain. ref:DEC-portable-exact-arithmetic\"\"\"\n    if t.startswith('Either '):\n        types = either_arguments(t)\n        if (not isinstance(x, DataValue) or len(x.fields) != 1 or\n                x.tag not in ('Either::Left', 'Either::Right')):\n            raise ValueError('invalid Either constructor or arity')\n        inner = types[0 if x.tag == 'Either::Left' else 1]\n        return DataValue(x.tag, (validate(x.fields[0], inner, bits),))\n    if t.startswith('Maybe '):\n        if not isinstance(x, DataValue):\n            raise TypeError('expected Maybe')\n        if x.tag == 'Maybe::Nothing' and (not x.fields):\n            return x\n        if x.tag == 'Maybe::Just' and len(x.fields) == 1:\n            return DataValue(x.tag, (validate(x.fields[0], t[6:], bits),))\n        raise ValueError('invalid Maybe constructor or arity')\n    if t.startswith('List '):\n        if not isinstance(x, list):\n            raise TypeError('expected List')\n        return [validate(value, t[5:], bits) for value in x]\n    if t.startswith(('Nullable ', 'Optional ')):\n        (k, inner) = t.split(' ', 1)\n        if (not isinstance(x, Presence) or x.kind != k or\n                type(x.present) is not bool):\n            raise ValueError('tagged presence required for ' + t)\n        if x.present:\n            return Presence(k, True, validate(x.value, inner, bits))\n    elif integer_type(t):\n        if type(x) is not int:\n            raise ValueError('integer required for ' + t)\n        convert(x, t, bits)\n    elif t == 'Bool':\n        if type(x) is not bool:\n            raise ValueError('Bool required')\n    elif t in ('Text', 'Char'):\n        if (not isinstance(x, str) or (t == 'Char' and len(x) != 1) or\n                not all(valid_unit(t, ord(c)) for c in x)):\n            raise ValueError('invalid ' + t)\n    elif t in ('CodePoint', 'CodeUnit16'):\n        if not valid_unit(t, x):\n            raise ValueError('invalid ' + t)\n    elif t == 'Bytes':\n        if type(x) is not bytes:\n            raise ValueError('Bytes required')\n    elif t in ('CodePointText', 'Utf16Text'):\n        if (not isinstance(x, Raw) or x.kind != t or\n                not all(valid_unit(t, c) for c in x.units)):\n            raise ValueError('invalid ' + t)\n    elif t in ('Unit', 'Null', 'Undefined'):\n        if x != Absence(t):\n            raise ValueError('invalid ' + t)\n    elif t == 'Symbol':\n        if not isinstance(x, Symbol):\n            raise ValueError('Symbol required')\n    elif t == 'Decimal':\n        if not isinstance(x, Decimal) or not x.is_finite():\n            raise ValueError('finite Decimal required')\n    elif t == 'Rational':\n        if not isinstance(x, Fraction):\n            raise ValueError('Rational required')\n    elif t in ('Float32', 'Float64'):\n        if (type(x) is not float or\n                (t == 'Float32' and not math.isnan(x) and f32(x) != x)):\n            raise ValueError('invalid ' + t)\n    elif t in ('Complex64', 'Complex128'):\n        if type(x) is not complex:\n            raise ValueError('complex required')\n        if t == 'Complex64':\n            validate(x.real, 'Float32')\n            validate(x.imag, 'Float32')\n    else:\n        raise ValueError('unknown scalar type ' + t)\n    return x\n\n\ndef literal(v, symbols=None):\n    t = v['type']\n    if integer_type(t):\n        return parse_integer(v['value'])\n    if t == 'Bool':\n        return v['value']\n    if t == 'Decimal':\n        c = parse_integer(v['coefficient'])\n        return Decimal((int(c < 0), tuple(map(int, integer_text(abs(c)))),\n                        int(v['exponent'])))\n    if t == 'Rational':\n        return Fraction(parse_integer(v['numerator']),\n                        parse_integer(v['denominator']))\n    if t.startswith('Float'):\n        return struct.unpack('>f' if t == 'Float32' else '>d',\n                             bytes.fromhex(v['bits']))[0]\n    if t.startswith('Complex'):\n        return complex(literal(v['real']), literal(v['imaginary']))\n    if t == 'Text':\n        return ''.join(map(chr, v['units']))\n    if t == 'Char':\n        return chr(v['value'])\n    if t in ('CodePoint', 'CodeUnit16'):\n        return v['value']\n    if t == 'Bytes':\n        return bytes(v['units'])\n    if t in ('CodePointText', 'Utf16Text'):\n        return Raw(t, tuple(v['units']))\n    if t == 'Symbol':\n        if symbols is None:\n            symbols = {}\n        return symbols.setdefault(v['id'], Symbol(v['description']))\n    if t in ('Nullable', 'Optional'):\n        return Presence(\n            t, v['value'] is not None,\n            literal(v['value'], symbols) if v['value'] is not None else None)\n    return Absence(t)\n\n\ndef promote(a, b, op):\n    if exact_type(a) != exact_type(b):\n        raise ValueError('exact/inexact mixing requires explicit conversion')\n    if exact_type(a):\n        return ('Rational' if op == '/' or 'Rational' in (a, b) else\n                'Decimal' if 'Decimal' in (a, b) else 'Integer')\n    if a.startswith('Complex') or b.startswith('Complex'):\n        return ('Complex128' if a in ('Float64', 'Complex128') or\n                b in ('Float64', 'Complex128') else 'Complex64')\n    return 'Float64' if 'Float64' in (a, b) else 'Float32'\n\n\ndef ieee_div(a, b):\n    if b != 0:\n        return a / b\n    if a == 0 or math.isnan(a):\n        return math.nan\n    return math.copysign(math.inf, math.copysign(1, a) * math.copysign(1, b))\n\n\ndef binary(op, a, b, ta, tb):\n    \"\"\"Applies a LawSpec operator with LawSpec's semantics rather than\n    Python's, so a law computes the same result on every target.\n    ref:DEC-portable-exact-arithmetic ref:ieee-754\"\"\"\n    if (op in ('==', '!=') and not exact_type(ta) and\n            ta not in ('Float32', 'Float64', 'Complex64', 'Complex128')):\n        result = equal(a, b, ta, tb)\n        return result if op == '==' else not result\n    t = promote(ta, tb, op)\n    if exact_type(ta):\n        (a, b) = (ratio(a), ratio(b))\n    elif t.startswith('Complex'):\n        (a, b) = (complex(a), complex(b))\n        rnd = f32 if t == 'Complex64' else float\n        if op == '+':\n            return complex(rnd(a.real + b.real), rnd(a.imag + b.imag))\n        if op == '-':\n            return complex(rnd(a.real - b.real), rnd(a.imag - b.imag))\n        if op == '*':\n            return complex(\n                rnd(rnd(a.real * b.real) - rnd(a.imag * b.imag)),\n                rnd(rnd(a.real * b.imag) + rnd(a.imag * b.real)))\n        if op == '/':\n            d = rnd(rnd(b.real * b.real) + rnd(b.imag * b.imag))\n            return complex(\n                rnd(ieee_div(\n                    rnd(rnd(a.real * b.real) + rnd(a.imag * b.imag)), d)),\n                rnd(ieee_div(\n                    rnd(rnd(a.imag * b.real) - rnd(a.real * b.imag)), d)))\n    if op == 'pow':\n        if a.denominator != 1 or b.denominator != 1:\n            raise TypeError('pow requires integer operands')\n        if b < 0:\n            raise ValueError('negative exponent')\n        return a.numerator ** b.numerator\n    if op in ('quot', 'rem'):\n        q = abs(a.numerator) // abs(b.numerator)\n        if (a < 0) != (b < 0):\n            q = -q\n        return q if op == 'quot' else a.numerator - q * b.numerator\n    if op in ('<', '<=', '>', '>=', '==', '!='):\n        return {\n            '<': lambda: a < b,\n            '<=': lambda: a <= b,\n            '>': lambda: a > b,\n            '>=': lambda: a >= b,\n            '==': lambda: a == b,\n            '!=': lambda: a != b,\n        }[op]()\n    if op == '+':\n        v = a + b\n    elif op == '-':\n        v = a - b\n    elif op == '*':\n        v = a * b\n    elif op == '/':\n        v = a / b if exact_type(ta) else ieee_div(a, b)\n    else:\n        raise ValueError('unknown operation ' + op)\n    return convert(v, t)\n\n\n# Handles are values only adapters create, passed along unopened. The schema\n# registers each one as it crosses into LawSpec, so the runtime knows it: it\n# is equal only to itself, has no portable order, and renders as a stable\n# label numbered by first appearance in the process (Jobs#1).\n_handles = {}\n_handle_counts = {}\n_handle_lock = threading.Lock()\n\n\ndef handle(value, name):\n    \"\"\"Registers a handle of the named type; returns it unchanged.\"\"\"\n    if id(value) not in _handles:\n        with _handle_lock:\n            if id(value) not in _handles:\n                short = name.rsplit('::', 1)[-1]\n                count = _handle_counts.get(short, 0) + 1\n                _handle_counts[short] = count\n                # The entry keeps the value alive, so its id stays its own.\n                _handles[id(value)] = (value, short + '#' + str(count))\n    return value\n\n\ndef is_handle(value):\n    entry = _handles.get(id(value))\n    return entry is not None and entry[0] is value\n\n\ndef handle_label(value):\n    return _handles[id(value)][1]\n\n\ndef equal(a, b, ta, tb):\n    \"\"\"Equality defined once for all targets instead of borrowed from each\n    language's: NaN differs from itself, signed zeros are equal, handles and\n    symbols compare by identity, and data compares field by field.\n    ref:DEC-portable-exact-arithmetic\"\"\"\n    if is_handle(a) or is_handle(b):\n        return a is b\n    if ta.startswith('Either ') and tb.startswith('Either '):\n        if a.tag != b.tag:\n            return False\n        index = 0 if a.tag == 'Either::Left' else 1\n        return equal(a.fields[0], b.fields[0],\n                     either_arguments(ta)[index], either_arguments(tb)[index])\n    if ta.startswith('Maybe ') and tb.startswith('Maybe '):\n        return (a.tag == b.tag and\n                (a.tag == 'Maybe::Nothing' or\n                 equal(a.fields[0], b.fields[0], ta[6:], tb[6:])))\n    if ta.startswith('List ') and tb.startswith('List '):\n        return (len(a) == len(b) and\n                all(equal(x, y, ta[5:], tb[5:]) for x, y in zip(a, b)))\n    if exact_type(ta) and exact_type(tb):\n        return ratio(a) == ratio(b)\n    if isinstance(a, Presence) and isinstance(b, Presence):\n        return (a.kind == b.kind and a.present == b.present and\n                (not a.present or\n                 equal(a.value, b.value,\n                       ta.split(' ', 1)[1], tb.split(' ', 1)[1])))\n    if isinstance(a, complex) and isinstance(b, complex):\n        return a.real == b.real and a.imag == b.imag\n    return a == b\n\n\ndef _run_blocking(main):\n    \"\"\"Runs a coroutine to completion and returns its result. Called where an\n    event loop is already running (a synchronous definition called from an\n    asynchronous adapter), it runs on a thread of its own.\"\"\"\n    import asyncio\n    try:\n        asyncio.get_running_loop()\n    except RuntimeError:\n        return asyncio.run(main)\n    import concurrent.futures\n    with concurrent.futures.ThreadPoolExecutor(max_workers=1) as pool:\n        return pool.submit(asyncio.run, main).result()\n\n\ndef await_task(task):\n    \"\"\"An async adapter's result: run its coroutine (or awaitable) to completion.\"\"\"\n    async def result():\n        return await task\n    return _run_blocking(result())\n\n\nORDERING = 'lawspec.collections::type::Ordering::'\n\n\ndef compare_values(a, b):\n    \"\"\"The portable total order: -1, 0 or 1.\n\n    Exact numbers by value, text and raw sequences by unit, False before True,\n    absence before presence, lists element by element, Nothing before Just,\n    and other data by constructor identity, then fields left to right.\n    Handles have no order: one equals only itself.\n    \"\"\"\n    if is_handle(a) and is_handle(b):\n        if a is b:\n            return 0\n        raise TypeError('handles have no portable order')\n    if isinstance(a, bool) and isinstance(b, bool):\n        return (a > b) - (a < b)\n    if isinstance(a, (int, Fraction, Decimal)) and not isinstance(a, bool):\n        x, y = ratio(a), ratio(b)\n        return (x > y) - (x < y)\n    if isinstance(a, str) and isinstance(b, str):\n        return (a > b) - (a < b)\n    if isinstance(a, Raw) and isinstance(b, Raw):\n        return (a.units > b.units) - (a.units < b.units)\n    if isinstance(a, Absence) and isinstance(b, Absence):\n        return 0\n    if isinstance(a, Presence) and isinstance(b, Presence):\n        if a.present != b.present:\n            return 1 if a.present else -1\n        return compare_values(a.value, b.value) if a.present else 0\n    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):\n        for x, y in zip(a, b):\n            order = compare_values(x, y)\n            if order:\n                return order\n        return (len(a) > len(b)) - (len(a) < len(b))\n    if isinstance(a, DataValue) and isinstance(b, DataValue):\n        if a.tag != b.tag:\n            if {a.tag, b.tag} == {'Maybe::Nothing', 'Maybe::Just'}:\n                return -1 if a.tag == 'Maybe::Nothing' else 1\n            return (a.tag > b.tag) - (a.tag < b.tag)\n        return compare_values(list(a.fields), list(b.fields))\n    raise TypeError('values have no portable order')\n\n\ndef helper(n, args, types, bits=64):\n    x = args[0]\n    if n == 'startsWith':\n        return args[0].startswith(args[1])\n    if n == 'endsWith':\n        return args[0].endswith(args[1])\n    if n == 'textContains':\n        return args[1] in args[0]\n    if n == 'regexMatches':\n        return regex_matches(args[0], args[1])\n    if n == 'recorded':\n        return recorded(args[0], args[1])\n    if n == 'acquireResource':\n        return acquire_resource(args[0])\n    if n == 'releaseResource':\n        return release_resource(args[0], args[1])\n    if n == 'freePort':\n        return free_port()\n    if n == 'checked':\n        return True\n    if n == 'select':\n        return args[1] if args[0] else args[2]\n    if n == 'compare':\n        order = compare_values(args[0], args[1])\n        return DataValue(ORDERING + ('Less', 'Equal', 'Greater')[order + 1], ())\n    if n == 'length':\n        return len(x.units) if isinstance(x, Raw) else len(x)\n    if n == 'isPresent':\n        return x.present\n    if n == 'presentValue':\n        if not x.present:\n            raise ValueError('absent presence value')\n        return x.value\n    if n == 'real':\n        return x.real\n    if n == 'imag':\n        return x.imag\n    if n == 'negate':\n        if exact_type(types[0]):\n            return binary('-', 0, x, 'BigInt', types[0])\n        return convert(-x, types[0])\n    if n in ('quot', 'rem', 'pow'):\n        return binary(n, *args, *types)\n    if n == 'isNaN':\n        return math.isnan(x)\n    if n == 'isInfinite':\n        return math.isinf(x)\n    if n == 'isFinite':\n        return math.isfinite(x)\n    if n == 'isNegativeZero':\n        return x == 0 and math.copysign(1, x) < 0\n    if n == 'round':\n        scale = convert(args[1], 'Int32', bits)\n        factor = (Fraction(10 ** scale) if scale >= 0 else\n                  Fraction(1, 10 ** (-scale)))\n        return finite_decimal(Fraction(round(ratio(x) * factor), 1) / factor)\n    return convert(x, n, bits)\n\n\n# Portable regular expressions (see LawSpec.Regex): the subset of RE2 and\n# ECMAScript that means the same in both, matched against a whole text, code\n# point by code point. The compiler has checked every pattern; a pattern\n# that is not portable raises ValueError here too.\n_REGEX_DIGITS = [(48, 57)]\n_REGEX_WORD = [(48, 57), (65, 90), (95, 95), (97, 122)]\n_REGEX_SPACE = [(9, 13), (32, 32)]\n_REGEX_CACHE = {}\n\n\ndef _regex_parse(pattern):\n    cs = [ord(c) for c in pattern]\n    n = len(cs)\n    pos = [0]\n\n    def peek():\n        return cs[pos[0]] if pos[0] < n else None\n\n    def fail(message):\n        raise ValueError(f'regex {pattern!r} is not portable: {message}')\n\n    def escape(in_class):\n        pos[0] += 1\n        c = peek()\n        if c is None:\n            fail('the regex ends with a lone \\\\')\n        pos[0] += 1\n        ch = chr(c)\n        classes = {'d': (False, _REGEX_DIGITS), 'D': (True, _REGEX_DIGITS),\n                   'w': (False, _REGEX_WORD), 'W': (True, _REGEX_WORD),\n                   's': (False, _REGEX_SPACE), 'S': (True, _REGEX_SPACE)}\n        if ch in classes:\n            return classes[ch]\n        controls = {'n': 10, 't': 9, 'r': 13, 'f': 12, 'v': 11}\n        if ch in controls:\n            return (False, [(controls[ch], controls[ch])])\n        if ch in '\\\\.^$|?*+()[]{}-/':\n            return (False, [(c, c)])\n        fail(f'\\\\{ch} is not a portable escape')\n\n    def char_class():\n        pos[0] += 1\n        negated = peek() == ord('^')\n        if negated:\n            pos[0] += 1\n        items = []\n        first = True\n        while True:\n            c = peek()\n            if c is None:\n                fail('a [ is never closed')\n            if c == ord(']'):\n                if first:\n                    fail('an empty class is not portable')\n                pos[0] += 1\n                return ('set', negated, items)\n            first = False\n            item = escape(True) if c == ord('\\\\') else _literal()\n            if (not item[0] and len(item[1]) == 1 and item[1][0][0] == item[1][0][1]\n                    and peek() == ord('-') and pos[0] + 1 < n and cs[pos[0] + 1] != ord(']')):\n                pos[0] += 1\n                high = escape(True) if peek() == ord('\\\\') else _literal()\n                if high[0] or len(high[1]) != 1 or high[1][0][0] != high[1][0][1]:\n                    fail('a range ends with one character')\n                if high[1][0][0] < item[1][0][0]:\n                    fail('a range must run from low to high')\n                items.append((False, [(item[1][0][0], high[1][0][0])]))\n            else:\n                items.append(item)\n\n    def _literal():\n        c = peek()\n        if c == ord('['):\n            fail('write \\\\[ for the character inside a class')\n        pos[0] += 1\n        return (False, [(c, c)])\n\n    def atom():\n        c = peek()\n        if c == ord('('):\n            pos[0] += 1\n            if peek() == ord('?'):\n                if pos[0] + 1 < n and cs[pos[0] + 1] == ord(':'):\n                    pos[0] += 2\n                else:\n                    fail('only (?: ...) groups are portable')\n            node = alternatives()\n            if peek() != ord(')'):\n                fail('a ( is never closed')\n            pos[0] += 1\n            return node\n        if c == ord('['):\n            return char_class()\n        if c == ord('.'):\n            pos[0] += 1\n            return ('set', True, [(False, [(10, 10)])])\n        if c == ord('\\\\'):\n            return ('set', False, [escape(False)])\n        if chr(c) in '*+?{^$]}':\n            fail(f'unexpected {chr(c)}')\n        pos[0] += 1\n        return ('set', False, [(False, [(c, c)])])\n\n    def quantified(node):\n        c = peek()\n        if c is None or chr(c) not in '*+?{':\n            return node\n        pos[0] += 1\n        if c == ord('*'):\n            node = ('repeat', node, 0, None)\n        elif c == ord('+'):\n            node = ('repeat', node, 1, None)\n        elif c == ord('?'):\n            node = ('repeat', node, 0, 1)\n        else:\n            start = pos[0]\n            while peek() is not None and chr(peek()).isdigit():\n                pos[0] += 1\n            low_text = pattern[start:pos[0]]\n            high = None\n            if peek() == ord('}'):\n                high = low_text\n            elif peek() == ord(','):\n                pos[0] += 1\n                start = pos[0]\n                while peek() is not None and chr(peek()).isdigit():\n                    pos[0] += 1\n                high = pattern[start:pos[0]] or None\n                if peek() != ord('}'):\n                    fail('a repetition is {n}, {n,} or {n,m}')\n            else:\n                fail('a repetition is {n}, {n,} or {n,m}')\n            pos[0] += 1\n            if not low_text:\n                fail('a repetition is {n}, {n,} or {n,m}')\n            low = int(low_text)\n            high = None if high is None else int(high)\n            if low > 1000 or (high is not None and (high > 1000 or high < low)):\n                fail('a repetition count is at most 1000, and n must not exceed m')\n            node = ('repeat', node, low, high)\n        if peek() is not None and chr(peek()) in '*+?{':\n            fail('a repetition cannot itself be repeated')\n        return node\n\n    def sequence():\n        items = []\n        while peek() is not None and peek() not in (ord('|'), ord(')')):\n            items.append(quantified(atom()))\n        return ('seq', items)\n\n    def alternatives():\n        branches = [sequence()]\n        while peek() == ord('|'):\n            pos[0] += 1\n            branches.append(sequence())\n        return branches[0] if len(branches) == 1 else ('alt', branches)\n\n    node = alternatives()\n    if pos[0] != n:\n        fail('a ) has no ( before it')\n    return node\n\n\ndef _regex_reach(node, text, positions):\n    kind = node[0]\n    if kind == 'set':\n        _, negated, items = node\n        result = set()\n        for p in positions:\n            if p < len(text):\n                c = text[p]\n                inside = any(item_negated != any(lo <= c <= hi for lo, hi in ranges)\n                             for item_negated, ranges in items)\n                if inside != negated:\n                    result.add(p + 1)\n        return result\n    if kind == 'seq':\n        for item in node[1]:\n            positions = _regex_reach(item, text, positions)\n        return positions\n    if kind == 'alt':\n        result = set()\n        for branch in node[1]:\n            result |= _regex_reach(branch, text, positions)\n        return result\n    _, body, low, high = node\n    for _ in range(low):\n        positions = _regex_reach(body, text, positions)\n    seen = set(positions)\n    frontier = set(positions)\n    limit = None if high is None else high - low\n    while frontier and limit != 0:\n        frontier = _regex_reach(body, text, frontier) - seen\n        seen |= frontier\n        if limit is not None:\n            limit -= 1\n    return seen\n\n\ndef regex_matches(pattern, text):\n    \"\"\"Whether the portable regex matches the whole text.\"\"\"\n    node = _REGEX_CACHE.get(pattern)\n    if node is None:\n        node = _REGEX_CACHE[pattern] = _regex_parse(pattern)\n    points = [ord(c) for c in text]\n    return len(points) in _regex_reach(node, points, {0})\n\n\n# Recorded values: a law compares a value's portable rendering with the\n# text stored under recorded/<unit>/<name> in the project. LAWSPEC_RECORDED\n# names the folder; otherwise it is recorded/ in the nearest folder, from\n# the working one up, that holds lawspec.json or recorded/. With\n# LAWSPEC_UPDATE_RECORDED=1 (lawspec test --update-recorded) a law records\n# the value instead.\ndef recorded_root():\n    import os\n    given = os.environ.get('LAWSPEC_RECORDED')\n    if given:\n        return given\n    folder = os.path.abspath(os.getcwd())\n    while True:\n        if (os.path.isfile(os.path.join(folder, 'lawspec.json'))\n                or os.path.isdir(os.path.join(folder, 'recorded'))):\n            return os.path.join(folder, 'recorded')\n        parent = os.path.dirname(folder)\n        if parent == folder:\n            return os.path.join(os.path.abspath(os.getcwd()), 'recorded')\n        folder = parent\n\n\ndef recorded(key, value):\n    import os\n    text = render(value)\n    path = os.path.join(recorded_root(), *key.split('/'))\n    if os.environ.get('LAWSPEC_UPDATE_RECORDED') == '1':\n        os.makedirs(os.path.dirname(path), exist_ok=True)\n        with open(path, 'w', encoding='utf-8', newline='\\n') as f:\n            f.write(text + '\\n')\n        return True\n    if not os.path.isfile(path):\n        raise AssertionError(\n            f'no recording recorded/{key}; run lawspec test --update-recorded '\n            f'to record {text}')\n    with open(path, encoding='utf-8', newline='') as f:\n        stored = f.read()\n    if stored.endswith('\\n'):\n        stored = stored[:-1]\n    if stored != text:\n        raise AssertionError(\n            f'recorded/{key} differs: expected {stored}, actual {text}'\n            ' (lawspec test --update-recorded records the new value)')\n    return True\n\n\n# Built-in resources (see LawSpec.Resources): a law acquires them before\n# each case and releases them after it.\ndef acquire_resource(kind):\n    import json\n    import os\n    import tempfile\n    if kind == 'temporaryDirectory':\n        return tempfile.mkdtemp(prefix='lawspec-')\n    if kind == 'temporaryFile':\n        handle, path = tempfile.mkstemp(prefix='lawspec-')\n        os.close(handle)\n        return path\n    if kind == 'environment':\n        return json.dumps(dict(os.environ), sort_keys=True)\n    raise ValueError(f'unknown resource kind {kind}')\n\n\ndef release_resource(kind, value):\n    import json\n    import os\n    import shutil\n    if kind == 'temporaryDirectory':\n        shutil.rmtree(value, ignore_errors=True)\n    elif kind == 'temporaryFile':\n        if os.path.exists(value):\n            os.remove(value)\n    elif kind == 'environment':\n        saved = json.loads(value)\n        for name in list(os.environ):\n            if name not in saved:\n                del os.environ[name]\n        for name, text in saved.items():\n            if os.environ.get(name) != text:\n                os.environ[name] = text\n    else:\n        raise ValueError(f'unknown resource kind {kind}')\n    return True\n\n\n# Shared resources (share R per group | unit | run, in a harness): one value\n# per scope key. The first use acquires it; every later use resets it first,\n# so no case sees what another left. One case holds it at a time, and it is\n# released when the test process ends.\n_shared = {}\n_shared_guard = threading.Lock()\n\n\ndef share(key, acquire, reset, release, concurrent=False):\n    \"\"\"A concurrent resource (resource T is concurrent) is held by any\n    number of cases at once, and reset only when none holds it.\"\"\"\n    import atexit\n    with _shared_guard:\n        entry = _shared.setdefault(key, {'lock': threading.Lock(), 'held': False, 'users': 0,\n                                         'concurrent': concurrent})\n    if concurrent:\n        with entry['lock']:\n            if entry['held'] and entry['users'] == 0:\n                reset(entry['value'])\n            elif not entry['held']:\n                entry['value'] = acquire()\n                entry['held'] = True\n                atexit.register(lambda: release(entry['value']))\n            entry['users'] += 1\n        return entry['value']\n    entry['lock'].acquire()\n    try:\n        if entry['held']:\n            reset(entry['value'])\n        else:\n            entry['value'] = acquire()\n            entry['held'] = True\n            atexit.register(lambda: release(entry['value']))\n    except BaseException:\n        entry['lock'].release()\n        raise\n    return entry['value']\n\n\ndef unshare(key):\n    entry = _shared[key]\n    if entry['concurrent']:\n        with entry['lock']:\n            entry['users'] -= 1\n    else:\n        entry['lock'].release()\n\n\ndef free_port():\n    import socket\n    with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:\n        s.bind(('127.0.0.1', 0))\n        return s.getsockname()[1]\n\n\ndef make_decimal(c, e):\n    return Decimal((int(c < 0), tuple(map(int, integer_text(abs(c)))), e))\n\n\ndef exact_float(r, t):\n    if not r:\n        return 0.0\n    negative = r < 0\n    (n, d) = (abs(r.numerator), r.denominator)\n    single = t == 'Float32'\n    (p, bias) = (24, 127) if single else (53, 1023)\n    (emin, emax) = (1 - bias, bias)\n    e = n.bit_length() - d.bit_length()\n    if n < d << e if e >= 0 else n << -e < d:\n        e -= 1\n    if e > emax:\n        return -math.inf if negative else math.inf\n    scale = max(e, emin) - (p - 1)\n    (num, den) = (n << -scale if scale < 0 else n,\n                  d << scale if scale > 0 else d)\n    (q, rem) = divmod(num, den)\n    if 2 * rem > den or (2 * rem == den and q % 2):\n        q += 1\n    e = max(e, emin)\n    if q == 1 << p:\n        q >>= 1\n        e += 1\n    if e > emax:\n        return -math.inf if negative else math.inf\n    hidden = 1 << p - 1\n    exponent = 0 if q < hidden else e + bias\n    mantissa = q if q < hidden else q - hidden\n    bits = (int(negative) << (31 if single else 63) |\n            exponent << p - 1 | mantissa)\n    return struct.unpack('>f' if single else '>d',\n                         bits.to_bytes(4 if single else 8, 'big'))[0]\n\n\ndef parse_integer(text):\n    negative = text.startswith('-')\n    text = text.lstrip('+-')\n    if not text or not text.isascii() or (not text.isdigit()):\n        raise ValueError('invalid integer representation')\n    result = 0\n    for start in range(0, len(text), 9):\n        chunk = text[start:start + 9]\n        result = result * 10 ** len(chunk) + int(chunk)\n    return -result if negative else result\n\n\ndef integer_text(value):\n    if value == 0:\n        return '0'\n    (negative, value) = (value < 0, abs(value))\n    chunks = []\n    while value:\n        (value, rest) = divmod(value, 1000000000)\n        chunks.append(rest)\n    return (('-' if negative else '') + str(chunks[-1]) +\n            ''.join(f'{n:09d}' for n in reversed(chunks[:-1])))\n\n\ndef unit_result(value):\n    return UNIT if value is None else validate(value, 'Unit')\n\n\n# Abilities (docs/explanation/abilities.md). Handlers travel in the symbols\n# context generated code passes to every definition: that context is the\n# evidence of evidence-passing compilation. A law installs one handler per\n# ability; an operation finds the handler of its ability there. The Fail\n# ability's handlers abort, so raise is an exception and attempt catches it.\n_HANDLERS = \"_lawspec_handlers\"\n\n\nclass Failure(Exception):\n    \"\"\"A failure raised with the Fail ability, aborting to the nearest\n    attempt of the same ability.\"\"\"\n\n    def __init__(self, ability, value):\n        super().__init__(f\"failed with {value!r} ({ability})\")\n        self.ability = ability\n        self.value = value\n\n\ndef install_handlers(symbols, handlers):\n    table = dict(symbols.get(_HANDLERS, {}))\n    table.update(handlers)\n    symbols[_HANDLERS] = table\n    return symbols\n\n\ndef handler(symbols, ability):\n    table = symbols.get(_HANDLERS) if isinstance(symbols, dict) else None\n    if not table or ability not in table:\n        raise LookupError(f\"no handler for the ability {ability}: a law \"\n                          \"names one with `using`, or runs under each \"\n                          \"lawful handler\")\n    return table[ability]\n\n\ndef raise_failure(ability, value):\n    raise Failure(ability, value)\n\n\ndef attempt(ability, body, right, left):\n    try:\n        value = body()\n    except Failure as failure:\n        if failure.ability != ability:\n            raise\n        return left(failure.value)\n    return right(value)\n\n\ndef native_handler(module, name):\n    \"\"\"A production handler bound in lawspec.json: its class (or function of\n    no arguments), called.\"\"\"\n    import importlib\n    return getattr(importlib.import_module(module), name)()\n\n\n_HANDLER_SCHEMA = None\n\n\ndef set_handler_schema(schema):\n    \"\"\"The schema a handler's values cross with: lawspec_native sets it to\n    the bound native types when lawspec.json binds them.\"\"\"\n    global _HANDLER_SCHEMA\n    _HANDLER_SCHEMA = schema\n\n\ndef handler_schema(default):\n    return default if _HANDLER_SCHEMA is None else _HANDLER_SCHEMA\n\n\ndef with_handlers(symbols, handlers, body):\n    \"\"\"handle e with h end: runs body with these handlers installed, then\n    puts back the ones they replaced.\"\"\"\n    previous = symbols.get(_HANDLERS)\n    table = dict(previous or {})\n    table.update(handlers)\n    symbols[_HANDLERS] = table\n    try:\n        return body()\n    finally:\n        if previous is None:\n            symbols.pop(_HANDLERS, None)\n        else:\n            symbols[_HANDLERS] = previous\n\n\ndef native_class(module, name):\n    \"\"\"A class of a generated or user-owned module, by name.\"\"\"\n    import importlib\n    return getattr(importlib.import_module(module), name)\n\n\ndef unknown_handler(name):\n    raise LookupError(f\"no spec handler called {name}\")\n\n\nclass Fail(Exception):\n    \"\"\"Raised by native code (an adapter, or a production handler) to fail\n    with a value of the failure type its signature names: `fails with E`.\n    The generated code turns it into the Fail ability's failure.\"\"\"\n\n    def __init__(self, value):\n        super().__init__(f\"failed with {value!r}\")\n        self.value = value\n\n\ndef native_failures(ability, convert, body, mapped=()):\n    \"\"\"Calls native code that may fail: ls.Fail(value), or an exception\n    lawspec.json maps to a failure (mapped holds (class, make) pairs),\n    becomes a failure of the ability.\"\"\"\n    try:\n        return body()\n    except Fail as failure:\n        raise Failure(ability, convert(failure.value)) from failure\n    except Exception as error:\n        for (kind, make) in mapped:\n            if isinstance(error, kind):\n                raise Failure(ability, make(error)) from error\n        raise\n\n\ndef count_calls(recording, operation, matches=None):\n    calls = getattr(recording, \"calls\", None)\n    if calls is None:\n        raise TypeError(\"calls of needs a recording handler: `using recording`\")\n    return sum(1 for (name, arguments) in calls\n               if name == operation and (matches is None or matches(arguments)))\n\n\n# Dependent-domain operations are independent of test frameworks.\ndef sample(t, seed, bits=64):\n    \"\"\"Draws a value of a scalar type from a seed, the same value every target\n    draws, so a failing seed reproduces anywhere.\n    ref:DEC-portable-seeded-generation\"\"\"\n    import random\n    r = random.Random(seed)\n    if t.startswith(('Nullable ', 'Optional ')):\n        (kind, inner) = t.split(' ', 1)\n        return Presence(kind, bool(seed % 2),\n                        sample(inner, seed // 2, bits) if seed % 2 else None)\n    if integer_type(t):\n        (lo, hi) = bounds(t, bits)\n        return r.randint(lo if lo is not None else -2 ** 256,\n                         hi if hi is not None else 2 ** 256)\n    if t == 'Bool':\n        return bool(seed % 2)\n    if t == 'Decimal':\n        return make_decimal(r.randint(-2 ** 128, 2 ** 128), r.randint(-20, 20))\n    if t == 'Rational':\n        return Fraction(r.randint(-2 ** 128, 2 ** 128), r.randint(1, 2 ** 128))\n    if t.startswith('Float'):\n        return literal({\n            'type': t,\n            'bits': format(r.getrandbits(32 if t == 'Float32' else 64),\n                           '08x' if t == 'Float32' else '016x'),\n        })\n    if t.startswith('Complex'):\n        c = 'Float32' if t == 'Complex64' else 'Float64'\n        return complex(sample(c, seed, bits), sample(c, seed + 1, bits))\n    if t in ('Unit', 'Null', 'Undefined'):\n        return {'Unit': UNIT, 'Null': NULL, 'Undefined': UNDEFINED}[t]\n    if t == 'Symbol':\n        return Symbol('same')\n    maximum = (255 if t == 'Bytes' else\n               65535 if t in ('Utf16Text', 'CodeUnit16') else 1114111)\n\n    def unit():\n        while True:\n            c = r.randint(0, maximum)\n            if t not in ('Text', 'Char') or not 55296 <= c <= 57343:\n                return c\n    if t == 'Char':\n        return chr(unit())\n    if t in ('CodePoint', 'CodeUnit16'):\n        return unit()\n    units = tuple((unit() for _ in range(r.randint(0, 39))))\n    if t == 'Text':\n        return ''.join(map(chr, units))\n    if t == 'Bytes':\n        return bytes(units)\n    return Raw(t, units)\n\n\ndef domain_candidates(t, seed, bits, restrictions, hints):\n    candidates = []\n    for hint in hints:\n        try:\n            candidates.append(convert(hint, t, bits))\n        except (ValueError, TypeError, OverflowError):\n            pass\n    if integer_type(t):\n        (lo, hi) = bounds(t, bits)\n        for (op, value) in restrictions:\n            r = ratio(value)\n            if op in ('>', '>=', '=='):\n                bound = math.floor(r) + 1 if op == '>' else math.ceil(r)\n                lo = bound if lo is None else max(lo, bound)\n            if op in ('<', '<=', '=='):\n                bound = math.ceil(r) - 1 if op == '<' else math.floor(r)\n                hi = bound if hi is None else min(hi, bound)\n        if lo is not None and hi is not None and (lo > hi):\n            return []\n        lower = lo if lo is not None else min(-2 ** 256, (hi or 0) - 2 ** 256)\n        upper = hi if hi is not None else max(2 ** 256, (lo or 0) + 2 ** 256)\n        candidates += [lower, upper, 0, 1, -1, lower + 1, upper - 1]\n        import random\n        r = random.Random(seed)\n        candidates += [r.randint(lower, upper) for _ in range(8)]\n        candidates = [\n            v for v in candidates\n            if isinstance(v, int) and not isinstance(v, bool)\n            and lower <= v <= upper\n        ]\n    else:\n        candidates += [sample(t, seed + j * 7919, bits) for j in range(8)]\n    if candidates:\n        offset = seed % len(candidates)\n        candidates = candidates[offset:] + candidates[:offset]\n    return candidates\n\n\ndef generate_tuple(domains, seed, attempts, prefix=()):\n    used = 0\n    last_prefix = list(prefix)\n\n    def search(values):\n        nonlocal used, last_prefix\n        last_prefix = values\n        if len(values) == len(domains):\n            return values\n        if used >= attempts:\n            return None\n        used += 1\n        (candidates, accept) = domains[len(values)]\n        for value in candidates(values, seed + used * 7919):\n            if used >= attempts:\n                break\n            used += 1\n            next_values = values + [value]\n            if accept(next_values):\n                result = search(next_values)\n                if result is not None:\n                    return result\n        return None\n    while used < attempts:\n        result = search(list(prefix))\n        if result is not None:\n            return result\n    raise ValueError(\n        f'refinement-generation-exhausted after {used} attempts; '\n        f'prefix={last_prefix!r}; seed={seed}')\n\n\ndef require_contract(condition, context):\n    if condition is not True:\n        raise ValueError(context)\n\n\ndef refined_case(\n        domains, seed, attempts, shrinks, check, context='refinement'):\n    try:\n        values = generate_tuple(domains, seed, attempts)\n    except Exception as error:\n        raise ValueError(f'{context}: {error}') from error\n    try:\n        check(values)\n    except Exception as original:\n        best = values\n        budget = shrinks\n        for index in range(len(best)):\n            value = best[index]\n            candidates = domains[index][0](best[:index], 0)\n            if isinstance(value, int) and (not isinstance(value, bool)):\n                candidates = [0, 1 if value > 0 else -1] + candidates\n                reduced = value\n                while abs(reduced) > 1:\n                    reduced = abs(reduced) // 2 * (1 if reduced > 0 else -1)\n                    candidates.insert(2, reduced)\n            for candidate in candidates:\n                if budget <= 0:\n                    break\n                budget -= 1\n                if complexity(candidate) >= complexity(best[index]):\n                    continue\n                prefix = best[:index] + [candidate]\n                if not domains[index][1](prefix):\n                    continue\n                try:\n                    trial = generate_tuple(domains, seed,\n                                           min(attempts, 100), prefix)\n                except ValueError as error:\n                    if str(error).startswith(\n                            'refinement-generation-exhausted'):\n                        continue\n                    raise\n                try:\n                    check(trial)\n                except Exception:\n                    best = trial\n        raise AssertionError(\n            f'{context}: {original}; refined counterexample={best!r}; '\n            f'seed={seed}') from original\n\n\ndef complexity(value):\n    if isinstance(value, Presence):\n        return 1 + complexity(value.value) if value.present else 0\n    if isinstance(value, Raw):\n        return len(value.units)\n    if isinstance(value, (str, bytes)):\n        return len(value)\n    if isinstance(value, Absence):\n        return 0\n    if isinstance(value, Symbol):\n        return 1\n    if isinstance(value, (Fraction, Decimal)):\n        r = ratio(value)\n        return abs(r.numerator) + r.denominator - 1\n    if isinstance(value, complex):\n        return complexity(value.real) + complexity(value.imag)\n    if isinstance(value, float):\n        return struct.unpack('>Q', struct.pack('>d', abs(value)))[0]\n    return abs(value)\n\n\ndef construct(tag, fields):\n    if (tag == 'Maybe::Nothing' and not fields or\n            (tag in ('Maybe::Just', 'Either::Left', 'Either::Right') and\n             len(fields) == 1)):\n        return DataValue(tag, fields)\n    if tag == 'List::Nil' and (not fields):\n        return []\n    if (tag == 'List::Cons' and len(fields) == 2\n            and isinstance(fields[1], list)):\n        return [fields[0], *fields[1]]\n    raise ValueError('invalid constructor or arity: ' + tag)\n\n\ndef all_elements(value, predicate):\n    if not isinstance(value, list):\n        raise TypeError('expected List in element predicate')\n    for (index, item) in enumerate(value):\n        try:\n            accepted = predicate(item)\n            if type(accepted) is not bool:\n                raise TypeError('element predicate must return Bool')\n            if not accepted:\n                return False\n        except Exception as error:\n            raise ValueError(f'List element {index}: {error}') from error\n    return True\n\n\ndef match_list(value, branches):\n    if not isinstance(value, list):\n        raise TypeError('expected List in match')\n    tag = 'List::Cons' if value else 'List::Nil'\n    for (candidate, branch) in branches:\n        if candidate == tag:\n            return branch(value[0], value[1:]) if value else branch()\n    raise ValueError('missing match branch: ' + tag)\n\n\ndef match_value(value, branches):\n    if isinstance(value, list):\n        return match_list(value, branches)\n    if not isinstance(value, DataValue):\n        raise TypeError('expected data in match')\n    arity = {\n        'Maybe::Nothing': 0,\n        'Maybe::Just': 1,\n        'Either::Left': 1,\n        'Either::Right': 1,\n    }.get(value.tag, -1)\n    if len(value.fields) != arity:\n        raise ValueError('invalid match constructor or arity')\n    for (tag, branch) in branches:\n        if tag == value.tag:\n            return branch(*value.fields)\n    raise ValueError('missing match branch: ' + value.tag)\n\n\ndef either_arguments(type_key):\n    \"\"\"Decode a parenthesized, two-argument runtime type key.\"\"\"\n    args = []\n    depth = 0\n    start = 0\n    for index in range(7, len(type_key)):\n        char = type_key[index]\n        if char == '(':\n            if depth == 0:\n                start = index + 1\n            depth += 1\n        elif char == ')':\n            depth -= 1\n            if depth < 0:\n                raise ValueError('invalid Either type key')\n            if depth == 0:\n                args.append(type_key[start:index])\n        elif depth == 0 and char != ' ':\n            raise ValueError('invalid Either type key')\n    if depth != 0 or len(args) != 2 or any((not arg.strip() for arg in args)):\n        raise ValueError('invalid Either type key')\n    return args\n\n\ndef integer_literal(value):\n    \"\"\"Decode an arbitrary integer without a host-sized intermediate.\"\"\"\n    return int(value)\n\n\ndef bytes_literal(values):\n    \"\"\"Construct octets without text encoding or replacement.\"\"\"\n    return bytes(values)\n\n\n# Workflow runtime. A workflow runs under a runtime: a clock, a seeded\n# random source, a trace of what happened, and the state of stateful stages.\n# The runtime travels in the symbols context every generated function takes;\n# without one, the default runtime applies (real time, unless the tests\n# installed a virtual clock). Durations are whole microseconds.\n\nimport time as _time\n\n_WORKFLOW = '\\x00lawspec.workflow'\n_MASK64 = (1 << 64) - 1\n\n\nclass RealClock:\n    virtual = False\n\n    def now(self):\n        return _time.monotonic_ns() // 1000\n\n    def sleep(self, micros):\n        _time.sleep(micros / 1_000_000)\n\n\nclass VirtualClock:\n    \"\"\"Sleeping advances the clock and returns at once.\"\"\"\n\n    virtual = True\n\n    def __init__(self, start=0):\n        self.time = start\n\n    def now(self):\n        return self.time\n\n    def sleep(self, micros):\n        self.time += micros\n\n\nclass SplitMix64:\n    \"\"\"The same sequence on every target for the same seed.\n\n    SplitMix64 is small, fast and specified exactly, so every runtime\n    implements the same generator and a seed names the same case everywhere.\n    ref:splitmix ref:DEC-portable-seeded-generation\"\"\"\n\n    def __init__(self, seed=0):\n        self.state = seed & _MASK64\n\n    def next(self):\n        self.state = (self.state + 0x9E3779B97F4A7C15) & _MASK64\n        z = self.state\n        z = ((z ^ (z >> 30)) * 0xBF58476D1CE4E5B9) & _MASK64\n        z = ((z ^ (z >> 27)) * 0x94D049BB133111EB) & _MASK64\n        return z ^ (z >> 31)\n\n    def below(self, bound):\n        \"\"\"Uniform in [0, bound); 0 when bound is 0.\"\"\"\n        return self.next() % bound if bound > 0 else 0\n\n\nclass WorkflowRuntime:\n    \"\"\"gates: whether rate limits, breakers, bulkheads and caches apply. The\n    runtime generated tests install has them off: a workflow law calls the\n    workflow and its composition, which would see each other's state.\"\"\"\n\n    def __init__(self, clock=None, seed=0, gates=True):\n        self.clock = RealClock() if clock is None else clock\n        self.random = SplitMix64(seed)\n        self.trace = []\n        self.state = {}\n        self.gates = gates\n        # A frame per running workflow: the undos of its completed stages.\n        self.frames = []\n        # When the running attempt of a stage with a timeout must end\n        # (time.monotonic seconds), or None.\n        self.deadline = None\n        # The running attempt's stage and hedge (delay, most), or None.\n        self.hedge = None\n\n    def context(self, symbols=None):\n        \"\"\"A symbols context that runs workflows under this runtime.\"\"\"\n        symbols = {} if symbols is None else symbols\n        symbols[_WORKFLOW] = self\n        return symbols\n\n\n_default_runtime = [None]\n_CLOCK_KEY = 'lawspec.time::ability::Clock'\n_CLOCK_VIEW = '\\x00lawspec.workflow.clock'\n\n\n_CLOCK_READER = [None]\n\n\ndef register_clock_ability(now, sleep, real_time):\n    \"\"\"How the runtime reads a Clock handler, registered by lawspec.time's\n    register_clock (the generated tests call it): now(handler) gives\n    microseconds, sleep(handler, micros) waits, and real_time(handler) says\n    whether the handler is the default real clock.\"\"\"\n    _CLOCK_READER[0] = (now, sleep, real_time)\n\n\ndef _ability_clock(handler):\n    reader = _CLOCK_READER[0]\n    return None if reader is None or handler is None else AbilityClock(handler, reader)\n\n\nclass AbilityClock:\n    \"\"\"A workflow runtime's clock read through the Clock ability: the handler\n    a law installs (the virtual clock, or the default real one). Every handler\n    but the default real clock is virtual: waits pass at once, and timeouts\n    and hedges count only the time it reports.\"\"\"\n\n    def __init__(self, handler, reader):\n        self.handler = handler\n        self._now, self._sleep, real_time = reader\n        self.virtual = not real_time(handler)\n\n    def now(self):\n        return self._now(self.handler)\n\n    def sleep(self, micros):\n        self._sleep(self.handler, micros)\n\n\ndef use_virtual_clock(seed=0):\n    \"\"\"Make the default runtime virtual, as generated tests do. Timeouts and\n    hedges stay on: they count virtual time (see _scoped).\"\"\"\n    _default_runtime[0] = WorkflowRuntime(VirtualClock(), seed, gates=False)\n\n\ndef workflow_runtime(symbols):\n    runtime = symbols.get(_WORKFLOW) if isinstance(symbols, dict) else None\n    if runtime is not None:\n        return runtime\n    if _default_runtime[0] is None:\n        _default_runtime[0] = WorkflowRuntime()\n    runtime = _default_runtime[0]\n    # Workflow time is the Clock ability's: where a law has installed a\n    # Clock handler, the default runtime waits and times out on it.\n    table = symbols.get(_HANDLERS) if isinstance(symbols, dict) else None\n    clock = _ability_clock(table.get(_CLOCK_KEY) if table else None)\n    if clock is None:\n        return runtime\n    view = symbols.get(_CLOCK_VIEW)\n    if view is None or view[0] is not clock.handler or view[1] is not runtime:\n        under = WorkflowRuntime.__new__(WorkflowRuntime)\n        under.__dict__.update(runtime.__dict__)\n        under.clock = clock\n        view = (clock.handler, runtime, under)\n        symbols[_CLOCK_VIEW] = view\n    return view[2]\n\n\n@dataclass(frozen=True)\nclass Retry:\n    # ('immediate',), ('fixed', d), ('linear', d, step),\n    # ('exponential', d, factor, cap or None), ('fibonacci', d) or\n    # ('custom', decide), where decide(attempt, error, previous) returns a\n    # delay in microseconds or None to stop.\n    strategy: tuple\n    attempts: int\n    jitter: str\n    when: object = None\n\n\n@dataclass(frozen=True)\nclass Gate:\n    \"\"\"A stateful policy: start(now) gives its state, admit(state, now) a\n    Step of the next state and a Gate (Admit, WaitFor or Reject), and\n    finish(state, now, succeeded) the state after the call. wait is None to\n    fail at once when not admitted, or the most it waits (-1 for no bound).\"\"\"\n    kind: str\n    start: object\n    admit: object\n    finish: object\n    wait: object = None\n\n\n@dataclass(frozen=True)\nclass StagePolicy:\n    stage: str\n    retry: object = None\n    timeout: object = None\n    # The stage's state key, its gates (breaker, limit, bulkhead), how long\n    # a success is cached (or None), and whether failures are StageFailures.\n    key: str = ''\n    gates: tuple = ()\n    cache: object = None\n    wraps: bool = False\n    # Undoes the stage's success value when its workflow fails.\n    compensate: object = None\n    # (delay, most): when an attempt has not succeeded after delay, another\n    # starts beside it, up to most in all; the first success wins.\n    hedge: object = None\n\n\ndef _fibonacci(n):\n    a, b = 1, 1\n    for _ in range(n - 1):\n        a, b = b, a + b\n    return a\n\n\ndef retry_delay(strategy, attempt):\n    \"\"\"The delay before attempt (2 or more), before jitter.\"\"\"\n    kind, n = strategy[0], attempt - 1\n    if kind == 'immediate':\n        return 0\n    if kind == 'fixed':\n        return strategy[1]\n    if kind == 'linear':\n        return strategy[1] + strategy[2] * (n - 1)\n    if kind == 'exponential':\n        delay = strategy[1] * strategy[2] ** (n - 1)\n        return delay if strategy[3] is None else min(delay, strategy[3])\n    if kind == 'fibonacci':\n        return strategy[1] * _fibonacci(n)\n    raise ValueError('unknown retry strategy: ' + kind)\n\n\ndef jittered(jitter, delay, previous, base, random):\n    \"\"\"Full: [0, delay]; equal: delay/2 + [0, delay/2]; decorrelated:\n    [base, previous * 3], capped at delay.\"\"\"\n    if jitter == 'full':\n        return random.below(delay + 1)\n    if jitter == 'equal':\n        half = delay // 2\n        return half + random.below(delay - half + 1)\n    if jitter == 'decorrelated':\n        high = max(base, previous * 3)\n        return min(delay, base + random.below(high - base + 1))\n    return delay\n\n\n_STAGE_FAILURE = 'lawspec.resilience::type::StageFailure::'\n_GATE = 'lawspec.resilience::type::Gate::'\n\n\ndef stage_failure(kind):\n    return DataValue('Either::Left', (DataValue(_STAGE_FAILURE + kind, ()),))\n\n\ndef _pass_gate(runtime, policy, gate):\n    \"\"\"Admits the call or returns the failure to give instead.\"\"\"\n    key = policy.key + '/' + gate.kind\n    waited = 0\n    while True:\n        now = runtime.clock.now()\n        state = runtime.state.get(key)\n        if state is None:\n            state = gate.start(now)\n        step = gate.admit(state, now)\n        runtime.state[key] = step.fields[0]\n        decision = step.fields[1]\n        if decision.tag == _GATE + 'Admit':\n            return None\n        failure = {'breaker': 'CircuitOpen', 'limit': 'RateLimited', 'bulkhead': 'Saturated'}[gate.kind]\n        if decision.tag == _GATE + 'Reject' or gate.wait is None:\n            return failure\n        delay = decision.fields[0]\n        if gate.wait >= 0 and waited + delay > gate.wait:\n            return failure\n        runtime.trace.append(('wait', policy.stage, delay))\n        runtime.clock.sleep(delay)\n        waited += delay\n\n\ndef run_stage(symbols, policy, attempt, key=None):\n    \"\"\"Runs a stage's attempts under its policy; a Left is a failure.\n    attempt() returns the stage's Either; key is its input, for the cache.\"\"\"\n    runtime = workflow_runtime(symbols)\n    gates = policy.gates if runtime.gates else ()\n    cached = runtime.state.setdefault(policy.key + '/cache', []) if policy.cache is not None and runtime.gates else None\n    if cached is not None:\n        now = runtime.clock.now()\n        for entry_key, value, expires in cached:\n            if now < expires and equal_values(entry_key, key):\n                runtime.trace.append(('cached', policy.stage, 0))\n                return value\n    for gate in gates:\n        failure = _pass_gate(runtime, policy, gate)\n        if failure is not None:\n            for passed in gates[:gates.index(gate)]:\n                _finish(runtime, policy, passed, False)\n            return stage_failure(failure)\n    result = _attempts(runtime, policy, attempt)\n    succeeded = not (isinstance(result, DataValue) and result.tag == 'Either::Left')\n    for gate in gates:\n        _finish(runtime, policy, gate, succeeded)\n    if succeeded and policy.compensate is not None and runtime.frames:\n        value = result.fields[0]\n        runtime.frames[-1].append((policy.stage, lambda: policy.compensate(value)))\n    if cached is not None and succeeded:\n        cached[:] = [entry for entry in cached if not equal_values(entry[0], key)]\n        cached.append((key, result, runtime.clock.now() + policy.cache))\n    return result\n\n\ndef run_workflow(symbols, attempt):\n    \"\"\"Runs a workflow whose stages compensate: when it fails, the undos of\n    its completed stages run, last first.\"\"\"\n    runtime = workflow_runtime(symbols)\n    frame = []\n    runtime.frames.append(frame)\n    try:\n        result = attempt()\n    finally:\n        runtime.frames.pop()\n    if isinstance(result, DataValue) and result.tag == 'Either::Left':\n        for stage, undo in reversed(frame):\n            runtime.trace.append(('compensate', stage, 0))\n            undo()\n    return result\n\n\ndef _finish(runtime, policy, gate, succeeded):\n    if gate.finish is not None:\n        key = policy.key + '/' + gate.kind\n        runtime.state[key] = gate.finish(runtime.state[key], runtime.clock.now(), succeeded)\n\n\ndef equal_values(a, b):\n    return a == b\n\n\nclass StageTimedOut(Exception):\n    \"\"\"An attempt outlived its stage's timeout.\"\"\"\n\n\ndef await_step(symbols, start, convert):\n    \"\"\"An asynchronous step's logical result: start() begins the step and\n    convert turns its native result into a logical value. The step runs\n    within its stage's timeout and hedge, if any.\"\"\"\n    runtime = workflow_runtime(symbols)\n    deadline, hedge = runtime.deadline, runtime.hedge\n    if deadline is None and hedge is None:\n        return convert(await_task(start()))\n    if isinstance(hedge, _VirtualHedge):\n        return _virtual_hedge(runtime, hedge, start, convert)\n    import asyncio\n\n    def left():\n        return None if deadline is None else max(0.0, deadline - _time.monotonic())\n\n    async def within():\n        return convert(await asyncio.wait_for(start(), left()))\n\n    async def hedged():\n        (stage, (delay, most)) = hedge\n        pending, started, last = set(), 0, None\n\n        def launch():\n            nonlocal started\n            started += 1\n            if started > 1:\n                runtime.trace.append(('hedge', stage, started))\n            pending.add(asyncio.ensure_future(start()))\n        launch()\n        try:\n            while True:\n                wait = delay / 1_000_000 if started < most else None\n                if deadline is not None:\n                    wait = left() if wait is None else min(wait, left())\n                done, _ = await asyncio.wait(pending, timeout=wait, return_when=asyncio.FIRST_COMPLETED)\n                for task in done:\n                    pending.discard(task)\n                    value = convert(task.result())\n                    if not (isinstance(value, DataValue) and value.tag == 'Either::Left'):\n                        return value\n                    last = value\n                if deadline is not None and _time.monotonic() >= deadline:\n                    raise asyncio.TimeoutError()\n                if pending and done:\n                    continue\n                if not pending and started >= most:\n                    return last\n                launch()\n        finally:\n            for task in pending:\n                task.cancel()\n    try:\n        return _run_blocking(within() if hedge is None else hedged())\n    except asyncio.TimeoutError:\n        raise StageTimedOut() from None\n\n\nclass NativeAsync:\n    \"\"\"The Async ability's default handler: the interpreter's own threads and\n    asyncio. LawSpec code performs pause; workflows reach the rest natively:\n    spawn starts a function as a task, wait gives a task's result (a\n    coroutine is run to completion), and all runs functions side by side and\n    gives their results in order. An `async` adapter is an adapter that uses\n    Async, so its coroutine is awaited with wait.\"\"\"\n\n    def pause(self):\n        _time.sleep(0)\n\n    def spawn(self, fn):\n        import concurrent.futures\n        future = concurrent.futures.Future()\n\n        def run():\n            try:\n                future.set_result(fn())\n            except BaseException as error:  # given back by wait\n                future.set_exception(error)\n        threading.Thread(target=run, daemon=True).start()\n        return future\n\n    def wait(self, task):\n        if hasattr(task, 'result') and hasattr(task, 'done') and not hasattr(task, '__await__'):\n            return task.result()\n        return await_task(task)\n\n    def all(self, fns):\n        \"\"\"Every function's result, in order; all finish before the first\n        exception (in order) is raised.\"\"\"\n        tasks = [self.spawn(fn) for fn in fns]\n        import concurrent.futures\n        concurrent.futures.wait(tasks)\n        return [task.result() for task in tasks]\n\n\nASYNC = NativeAsync()\n\n\ndef concurrently(steps):\n    \"\"\"An all group's step results, in declaration order. The steps run side\n    by side as tasks of the Async ability's default handler, so an\n    asynchronous step waits only for itself. Every step finishes before a\n    step's exception (the first, in declaration order) is raised.\"\"\"\n    return ASYNC.all(steps)\n\n\n@dataclass(frozen=True)\nclass _VirtualHedge:\n    stage: str\n    delay: int\n    most: int\n\n\ndef _is_left(value):\n    return isinstance(value, DataValue) and value.tag == 'Either::Left'\n\n\ndef _virtual_hedge(runtime, hedge, start, convert):\n    \"\"\"A hedge on a virtual clock: attempts run one after another, and the\n    next starts when one fails, so the first success wins as it would in\n    real time when no attempt outlives the delay.\"\"\"\n    started = 1\n    value = convert(await_task(start()))\n    while _is_left(value) and started < hedge.most:\n        started += 1\n        runtime.trace.append(('hedge', hedge.stage, started))\n        value = convert(await_task(start()))\n    return value\n\n\ndef _scoped(runtime, policy, attempt):\n    \"\"\"An attempt under its stage's timeout (failing with TimedOut when it\n    outlives it) and hedge: the Timeout and Hedge transformers of the Async\n    ability, measured on the runtime's Clock. On a virtual clock (generated\n    tests, or a law using virtual clock) an attempt takes the virtual time\n    that passes while it runs, so both are deterministic.\"\"\"\n    timeout = policy.timeout is not None and policy.timeout > 0\n    if not timeout and policy.hedge is None:\n        return attempt()\n    if getattr(runtime.clock, 'virtual', False):\n        return _virtually_scoped(runtime, policy, attempt, timeout)\n    if not runtime.gates:\n        return attempt()\n    outer = (runtime.deadline, runtime.hedge)\n    if timeout:\n        runtime.deadline = _time.monotonic() + policy.timeout / 1_000_000\n    runtime.hedge = None if policy.hedge is None else (policy.stage, policy.hedge)\n    try:\n        return attempt()\n    except StageTimedOut:\n        return stage_failure('TimedOut')\n    finally:\n        (runtime.deadline, runtime.hedge) = outer\n\n\ndef _virtually_scoped(runtime, policy, attempt, timeout):\n    outer = (runtime.deadline, runtime.hedge)\n    began = runtime.clock.now()\n    runtime.deadline = None\n    runtime.hedge = None if policy.hedge is None else _VirtualHedge(policy.stage, *policy.hedge)\n    try:\n        result = attempt()\n    except StageTimedOut:\n        return stage_failure('TimedOut')\n    finally:\n        (runtime.deadline, runtime.hedge) = outer\n    if timeout and runtime.clock.now() - began > policy.timeout:\n        return stage_failure('TimedOut')\n    return result\n\n\ndef _attempts(runtime, policy, attempt):\n    retry = policy.retry\n    number, previous = 1, 0\n    while True:\n        runtime.trace.append(('start', policy.stage, number))\n        result = _scoped(runtime, policy, attempt)\n        failed = isinstance(result, DataValue) and result.tag == 'Either::Left'\n        runtime.trace.append(('finish', policy.stage, number, not failed))\n        if not failed or retry is None:\n            return result\n        if retry.attempts > 0 and number >= retry.attempts:\n            return result\n        error = result.fields[0]\n        if policy.wraps:\n            # Only the step's own failures and timeouts are retried.\n            if error.tag == _STAGE_FAILURE + 'StepFailed':\n                error = error.fields[0]\n            elif error.tag != _STAGE_FAILURE + 'TimedOut':\n                return result\n        if retry.when is not None and not retry.when(error):\n            return result\n        number += 1\n        if retry.strategy[0] == 'custom':\n            delay = retry.strategy[1](number, error, previous)\n            if delay is None:\n                return result\n        else:\n            base = retry_delay(retry.strategy, 2) if retry.strategy[0] != 'immediate' else 0\n            delay = jittered(retry.jitter, retry_delay(retry.strategy, number),\n                             previous, base, runtime.random)\n        runtime.trace.append(('sleep', policy.stage, delay))\n        runtime.clock.sleep(delay)\n        previous = delay\n\n\ndef retry_decision(decision):\n    \"\"\"A RetryDecision's delay in microseconds, or None to stop.\"\"\"\n    if decision.tag != 'lawspec.time::type::RetryDecision::RetryAfter':\n        return None\n    return decision.fields[0].fields[0]\n\n\n\n# Portable generation for stateful models. A type descriptor is an\n# s-expression: (int T lo hi) with _ for no bound, (bool), (text), (unit),\n# (list D), (maybe D), (either L R), (data NAME (ctor TAG D...) ...) and\n# (ref NAME) for a data type declared in the model's table. Every target\n# generates, shrinks and renders the same values for the same seed.\n\nclass Quoted(str):\n    \"\"\"A string atom of a descriptor.\"\"\"\n\n\ndef read_descriptor(text):\n    \"\"\"Parses s-expressions: lists, integers, strings, symbols and _ (None).\"\"\"\n    position = [0]\n\n    def skip():\n        while position[0] < len(text) and text[position[0]] in ' \\t\\r\\n':\n            position[0] += 1\n\n    def item():\n        skip()\n        c = text[position[0]]\n        if c == '(':\n            position[0] += 1\n            items = []\n            skip()\n            while text[position[0]] != ')':\n                items.append(item())\n                skip()\n            position[0] += 1\n            return items\n        if c == '\"':\n            position[0] += 1\n            out = []\n            while text[position[0]] != '\"':\n                if text[position[0]] == '\\\\':\n                    position[0] += 1\n                out.append(text[position[0]])\n                position[0] += 1\n            position[0] += 1\n            return Quoted(''.join(out))\n        start = position[0]\n        while position[0] < len(text) and text[position[0]] not in ' \\t\\r\\n()':\n            position[0] += 1\n        atom = text[start:position[0]]\n        if atom == '_':\n            return None\n        if atom.lstrip('-').isdigit():\n            return int(atom)\n        return atom\n\n    items = []\n    skip()\n    while position[0] < len(text):\n        items.append(item())\n        skip()\n    return items\n\n\n_UNBOUNDED = 1_000_000\n\n\nclass Values:\n    \"\"\"Generation, shrinking and rendering over a table of data types.\n\n    Shrinking stays inside the declared domain, so a reported counterexample\n    is always a value the law quantifies over. ref:DEC-shrink-within-domain\n    ref:DEC-structural-size-budget\"\"\"\n\n    def __init__(self, table):\n        self.table = table\n\n    def resolve(self, d):\n        return self.table[d[1]] if d[0] == 'ref' else d\n\n    def bounds(self, d):\n        \"\"\"An integer's range: a missing bound is 1,000,000 from zero, or\n        2,000,000 from the other bound when that is beyond it.\"\"\"\n        lo, hi = d[2], d[3]\n        if lo is None and hi is None:\n            return -_UNBOUNDED, _UNBOUNDED\n        if lo is None:\n            return min(-_UNBOUNDED, hi - 2 * _UNBOUNDED), hi\n        if hi is None:\n            return lo, max(_UNBOUNDED, lo + 2 * _UNBOUNDED)\n        return lo, hi\n\n    def base(self, d):\n        \"\"\"The constructors whose fields mention no data type.\"\"\"\n        found = [c for c in d[2:] if not any(_mentions_data(f) for f in c[2:])]\n        return found or d[2:]\n\n    def generate(self, d, random, size):\n        d = self.resolve(d)\n        kind = d[0]\n        if kind == 'int':\n            lo, hi = self.bounds(d)\n            if random.below(10) < 2:\n                specials = [lo, hi, min(max(0, lo), hi), min(max(1, lo), hi)]\n                return specials[random.below(4)]\n            return lo + random.below(hi - lo + 1)\n        if kind == 'bool':\n            return random.below(2) == 1\n        if kind == 'text':\n            return ''.join(chr(32 + random.below(95)) for _ in range(random.below(size + 1)))\n        if kind == 'unit':\n            return UNIT\n        if kind == 'list':\n            return [self.generate(d[1], random, size) for _ in range(random.below(size + 1))]\n        if kind == 'maybe':\n            if random.below(4) == 0:\n                return DataValue('Maybe::Nothing', ())\n            return DataValue('Maybe::Just', (self.generate(d[1], random, size),))\n        if kind == 'either':\n            if random.below(2) == 0:\n                return DataValue('Either::Left', (self.generate(d[1], random, size),))\n            return DataValue('Either::Right', (self.generate(d[2], random, size),))\n        if kind == 'data':\n            choices = self.base(d) if size <= 0 else d[2:]\n            ctor = choices[random.below(len(choices))]\n            return DataValue(str(ctor[1]), tuple(self.generate(f, random, max(size - 1, 0)) for f in ctor[2:]))\n        raise ValueError('unknown descriptor ' + str(d))\n\n    def minimal(self, d):\n        d = self.resolve(d)\n        kind = d[0]\n        if kind == 'int':\n            lo, hi = self.bounds(d)\n            return min(max(0, lo), hi)\n        if kind == 'bool':\n            return False\n        if kind == 'text':\n            return ''\n        if kind == 'unit':\n            return UNIT\n        if kind == 'list':\n            return []\n        if kind == 'maybe':\n            return DataValue('Maybe::Nothing', ())\n        if kind == 'either':\n            return DataValue('Either::Left', (self.minimal(d[1]),))\n        ctor = self.base(d)[0]\n        return DataValue(str(ctor[1]), tuple(self.minimal(f) for f in ctor[2:]))\n\n    def shrink(self, d, v):\n        \"\"\"Smaller candidates for v, most aggressive first.\"\"\"\n        d = self.resolve(d)\n        kind = d[0]\n        out = []\n        if kind == 'int':\n            target = self.minimal(d)\n            if v != target:\n                out = [target, v - _toward_zero(v - target, 2), v - (1 if v > target else -1)]\n        elif kind == 'bool':\n            out = [False] if v else []\n        elif kind == 'text':\n            if v:\n                out = [''] + [v[:len(v) // 2]] + [v[:i] + v[i + 1:] for i in range(len(v))]\n        elif kind == 'list':\n            if v:\n                out = [[]] + [v[:len(v) // 2]] + [v[:i] + v[i + 1:] for i in range(len(v))]\n                for i, item in enumerate(v):\n                    out += [v[:i] + [c] + v[i + 1:] for c in self.shrink(d[1], item)]\n        elif kind == 'maybe':\n            if v.tag == 'Maybe::Just':\n                out = [DataValue('Maybe::Nothing', ())] + [DataValue('Maybe::Just', (c,)) for c in self.shrink(d[1], v.fields[0])]\n        elif kind == 'either':\n            inner = d[1] if v.tag == 'Either::Left' else d[2]\n            out = [DataValue(v.tag, (c,)) for c in self.shrink(inner, v.fields[0])]\n        elif kind == 'data':\n            ctor = next(c for c in d[2:] if str(c[1]) == v.tag)\n            out = [self.minimal(d)]\n            # A field of the same type is a smaller value of it.\n            out += [f for f, fd in zip(v.fields, ctor[2:]) if fd == ['ref', d[1]]]\n            for i, (field, fd) in enumerate(zip(v.fields, ctor[2:])):\n                out += [DataValue(v.tag, v.fields[:i] + (c,) + v.fields[i + 1:]) for c in self.shrink(fd, field)]\n        seen, unique = [], []\n        for c in out:\n            if not _same(c, v) and not any(_same(c, s) for s in seen):\n                seen.append(c)\n                unique.append(c)\n        return unique\n\n\ndef _toward_zero(n, d):\n    q = abs(n) // d\n    return q if n >= 0 else -q\n\n\ndef _mentions_data(d):\n    return isinstance(d, list) and (d[0] in ('ref', 'data') or any(_mentions_data(x) for x in d[1:]))\n\n\ndef _same(a, b):\n    return render(a) == render(b)\n\n\ndef render(v):\n    \"\"\"A value's canonical text, the same on every target.\"\"\"\n    if is_handle(v):\n        return handle_label(v)\n    if isinstance(v, bool):\n        return 'true' if v else 'false'\n    if isinstance(v, int):\n        return str(v)\n    if isinstance(v, str):\n        return '\"' + v.replace('\\\\', '\\\\\\\\').replace('\"', '\\\\\"') + '\"'\n    if v is UNIT:\n        return '()'\n    if isinstance(v, (list, tuple)):\n        return '[' + ', '.join(render(x) for x in v) + ']'\n    if isinstance(v, DataValue):\n        name = v.tag.split('::')[-1]\n        return name if not v.fields else name + '(' + ', '.join(render(x) for x in v.fields) + ')'\n    return str(v)\n\n\ndef difference(actual, expected):\n    \"\"\"Where a structured actual value first differs from the expected one,\n    by the portable rendering: '' when they agree or neither has parts.\"\"\"\n    path = []\n    a, b = actual, expected\n    while True:\n        if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):\n            for i, (x, y) in enumerate(zip(a, b)):\n                if render(x) != render(y):\n                    path.append(f'item {i + 1}')\n                    a, b = x, y\n                    break\n            else:\n                if len(a) == len(b):\n                    return ''\n                path.append('length')\n                a, b = len(a), len(b)\n                break\n        elif (isinstance(a, DataValue) and isinstance(b, DataValue) and a.tag == b.tag\n                and len(a.fields) == len(b.fields)):\n            name = a.tag.split('::')[-1]\n            for i, (x, y) in enumerate(zip(a.fields, b.fields)):\n                if render(x) != render(y):\n                    path.append(f'field {i + 1} of {name}')\n                    a, b = x, y\n                    break\n            else:\n                return ''\n        else:\n            break\n    if not path:\n        return ''\n    shown = (lambda v: str(v)) if path[-1] == 'length' else render\n    return (f' | first difference at {\", \".join(path)}: expected '\n            f'{shown(b)}, actual {shown(a)}')\n\n\ndef values_from(text):\n    \"\"\"A descriptor text's data types and its last form, the one generated.\"\"\"\n    forms = read_descriptor(text)\n    table = {str(f[1]): f for f in forms if isinstance(f, list) and f[0] == 'data'}\n    return Values(table), forms[-1]\n\n\ndef generated(text, seed, size, count):\n    \"\"\"count values generated from one SplitMix64 seed, rendered.\"\"\"\n    values, d = values_from(text)\n    random = SplitMix64(seed)\n    return [render(values.generate(d, random, size)) for _ in range(count)]\n\n\ndef shrunk(text, seed, size):\n    \"\"\"The shrink candidates of the first value generated, rendered.\"\"\"\n    values, d = values_from(text)\n    return [render(c) for c in values.shrink(d, values.generate(d, SplitMix64(seed), size))]\n\n\n# Actors. An actor owns a state and handles one message at a time, in the\n# order they arrive. It is not a thread: a message sent to an idle actor\n# starts a short-lived worker that drains its mailbox and then stops, so an\n# idle actor costs only its state and queue.\n\nclass ActorStopped(Exception):\n    \"\"\"A message sent to an actor that has stopped.\"\"\"\n\n\nclass ActorCrashed(Exception):\n    \"\"\"A handler failed, so the actor crashed; the cause is the handler's\n    exception. A supervised actor restarts; any other stops.\"\"\"\n\n    def __init__(self, cause):\n        super().__init__(f'the actor crashed: {cause!r}')\n        self.cause = cause\n\n\nclass _Restart(Exception):\n    \"\"\"A message that crashes the actor on purpose (crash, links).\"\"\"\n\n    def __init__(self, cause, origin):\n        super().__init__(cause)\n        self.cause, self.origin = cause, origin\n\n\n_crash_ids = iter(range(1, 1 << 62))\n_crash_lock = threading.Lock()\n\n\ndef _next_crash():\n    with _crash_lock:\n        return next(_crash_ids)\n\n\nclass Actor:\n    \"\"\"An actor: a state, a mailbox, and one message handled at a time.\n\n    restart(last state) gives the state after a crash; without it, a crash\n    stops the actor even under a supervisor. A supervised actor restarts in\n    place: it keeps its address and the messages waiting for it.\"\"\"\n\n    def __init__(self, state, restart=None):\n        self._state = state\n        self._restart_state = restart\n        self._mailbox = deque()\n        self._lock = threading.Lock()\n        self._draining = False\n        self._stopped = False\n        self._supervisor = None\n        self._monitors = []\n        self._links = []\n        self._seen = set()\n\n    def _post(self, message):\n        with self._lock:\n            if self._stopped:\n                raise ActorStopped('the actor has stopped')\n            self._mailbox.append(message)\n            if self._draining:\n                return\n            self._draining = True\n        threading.Thread(target=self._drain, daemon=True).start()\n\n    def _drain(self):\n        while True:\n            with self._lock:\n                if not self._mailbox:\n                    self._draining = False\n                    return\n                handler, reply = self._mailbox.popleft()\n            try:\n                result, self._state = handler(self._state)\n                outcome = (True, result)\n            except _Restart as crash:\n                outcome = (True, None)\n                self._crashed(crash.cause, crash.origin)\n            except BaseException as error:  # noqa: BLE001 - the actor crashes\n                outcome = (False, ActorCrashed(error))\n                self._crashed(error, _next_crash())\n            if reply is not None:\n                reply.append(outcome)\n                reply.event.set()\n\n    def _crashed(self, cause, origin):\n        \"\"\"Runs on the actor's turn: restart or stop, then tell monitors and\n        links. origin names the first crash, so a crash crosses each link once.\"\"\"\n        self._seen.add(origin)\n        restarted = self._supervisor is not None and self._restart_state is not None and \\\n            self._supervisor._child_crashed(self, cause)\n        if not restarted:\n            self._halt()\n        for monitor in list(self._monitors):\n            monitor(('crashed', cause))\n        for other in list(self._links):\n            other._link_crash(cause, origin)\n\n    def _restart_now(self):\n        \"\"\"On the actor's turn: the restarted state from the last one.\"\"\"\n        self._state = self._restart_state(self._state)\n\n    def _restart_later(self):\n        \"\"\"A restart a supervisor asks of a sibling, in mailbox order.\"\"\"\n        def restart(s):\n            return None, self._restart_state(s)\n        try:\n            self._post((restart, None))\n        except ActorStopped:\n            pass\n\n    def _link_crash(self, cause, origin):\n        if origin in self._seen:\n            return\n\n        def crash(s):\n            # The same crash can arrive by two links before either is handled.\n            if origin in self._seen:\n                return None, s\n            raise _Restart(cause, origin)\n        try:\n            self._post((crash, None))\n        except ActorStopped:\n            pass\n\n    def _halt(self):\n        \"\"\"Stops the actor; messages still waiting fail with ActorStopped.\"\"\"\n        with self._lock:\n            self._stopped = True\n            waiting, self._mailbox = list(self._mailbox), deque()\n        for _, reply in waiting:\n            if reply is not None:\n                reply.append((False, ActorStopped('the actor has stopped')))\n                reply.event.set()\n\n    def call(self, handler):\n        \"\"\"Runs handler(state) -> (result, next state) in turn and returns\n        the result. A handler that raises crashes the actor, and call raises\n        ActorCrashed.\"\"\"\n        reply = _Reply()\n        self._post((handler, reply))\n        reply.event.wait()\n        ok, value = reply[0]\n        if not ok:\n            raise value\n        return value\n\n    def cast(self, handler):\n        \"\"\"Queues handler(state) -> (result, next state) without waiting.\"\"\"\n        self._post((handler, None))\n\n    def crash(self, cause='crashed on purpose'):\n        \"\"\"Crashes the actor once the messages before this one are handled,\n        as a failing handler would: for testing supervision.\"\"\"\n        origin = _next_crash()\n\n        def crash(s):\n            raise _Restart(cause, origin)\n        self.call(crash)\n\n    def restart(self, restart):\n        \"\"\"Replaces the state by restart(last state) between messages, as a\n        supervised restart does (crash injection in model runs).\"\"\"\n        self.call(lambda s: (None, restart(s)))\n\n    def state(self):\n        \"\"\"The state after every message sent before this call.\"\"\"\n        return self.call(lambda s: (s, s))\n\n    def monitor(self, notify):\n        \"\"\"notify(('crashed', cause)) after each crash, and\n        notify(('stopped', None)) once it stops.\"\"\"\n        self._monitors.append(notify)\n\n    def link(self, other):\n        \"\"\"Links two actors: when either crashes, the other crashes too.\"\"\"\n        self._links.append(other)\n        other._links.append(self)\n\n    def stop(self):\n        \"\"\"Refuses further messages; those already queued still run. A\n        permanent child of a supervisor restarts instead.\"\"\"\n        if self._supervisor is not None and self._supervisor._child_stopped(self):\n            return\n        with self._lock:\n            already = self._stopped\n            self._stopped = True\n        if not already:\n            for monitor in list(self._monitors):\n                monitor(('stopped', None))\n\n\nclass Supervisor:\n    \"\"\"Starts children (actors or supervisors) and restarts them after a\n    crash. strategy 'one_for_one' restarts the child that crashed,\n    'one_for_all' every child, 'rest_for_one' it and those added after it.\n    A child's lifetime: 'permanent' restarts after a crash or a stop,\n    'transient' only after a crash, 'temporary' never. More than\n    max_restarts within period seconds is the supervisor's own crash: its\n    supervisor restarts all of its children, or, at the top, every child\n    stops.\n\n    Supervision follows OTP's strategies and restart types, so a supervision\n    tree means what an Erlang programmer expects on every target.\n    ref:DEC-actors-otp-supervision ref:erlang-otp-supervisors\"\"\"\n\n    def __init__(self, strategy='one_for_one', max_restarts=3, period=5.0):\n        if strategy not in ('one_for_one', 'one_for_all', 'rest_for_one'):\n            raise ValueError(f'unknown strategy {strategy!r}')\n        self.strategy, self.max_restarts, self.period = strategy, max_restarts, period\n        self._children = []\n        self._restarts = deque()\n        self._lock = threading.RLock()\n        self._supervisor = None\n        self._stopped = False\n        self._monitors = []\n\n    def supervise(self, child, lifetime='permanent'):\n        \"\"\"Adds a started child, and returns it.\"\"\"\n        if lifetime not in ('permanent', 'transient', 'temporary'):\n            raise ValueError(f'unknown lifetime {lifetime!r}')\n        with self._lock:\n            child._supervisor = self\n            self._children.append([child, lifetime])\n        return child\n\n    def children(self):\n        return [c for c, _ in self._children]\n\n    def _allow_restart(self):\n        import time\n        now = time.monotonic()\n        while self._restarts and now - self._restarts[0] > self.period:\n            self._restarts.popleft()\n        if len(self._restarts) >= self.max_restarts:\n            return False\n        self._restarts.append(now)\n        return True\n\n    def _entry(self, child):\n        return next((e for e in self._children if e[0] is child), None)\n\n    def _restarting(self, entry, cause, crashed):\n        \"\"\"Under the lock: the children to restart for entry's crash, or\n        None when the supervisor gives up.\"\"\"\n        if self._allow_restart():\n            index = self._children.index(entry)\n            return {'one_for_one': [entry], 'one_for_all': list(self._children),\n                    'rest_for_one': self._children[index:]}[self.strategy]\n        parent = self._supervisor\n        if parent is not None and parent._child_failed(self, cause):\n            self._restarts.clear()\n            return list(self._children)\n        self._fail(crashed, cause)\n        return None\n\n    def _child_crashed(self, child, cause):\n        \"\"\"On child's turn: True when it restarts now.\"\"\"\n        with self._lock:\n            entry = self._entry(child)\n            if self._stopped or entry is None:\n                return False\n            if entry[1] == 'temporary':\n                self._children.remove(entry)\n                return False\n            group = self._restarting(entry, cause, child)\n            if group is None:\n                return False\n        for other, _ in group:\n            if other is not child:\n                other._restart_later()\n        child._restart_now()\n        return True\n\n    def _child_failed(self, child, cause):\n        \"\"\"A child supervisor gave up: True when it may restart its children.\"\"\"\n        with self._lock:\n            entry = self._entry(child)\n            if self._stopped or entry is None:\n                return False\n            if entry[1] == 'temporary':\n                self._children.remove(entry)\n                return False\n            group = self._restarting(entry, cause, child)\n            if group is None:\n                return False\n        for other, _ in group:\n            if other is not child:\n                other._restart_later()\n        return True\n\n    def _child_stopped(self, child):\n        \"\"\"True when a stopped child is permanent and restarts instead.\"\"\"\n        with self._lock:\n            entry = self._entry(child)\n            if entry is None or self._stopped:\n                return False\n            if entry[1] != 'permanent':\n                self._children.remove(entry)\n                return False\n            group = self._restarting(entry, 'stopped', child)\n            if group is None:\n                return False\n        for other, _ in group:\n            other._restart_later()\n        return True\n\n    def _fail(self, crashed, cause):\n        \"\"\"Under the lock: every child but the one crashing (which stops\n        itself) stops, and so does the supervisor.\"\"\"\n        children, self._children = self._children, []\n        self._stopped = True\n        for other, _ in reversed(children):\n            other._supervisor = None\n            if other is not crashed:\n                other._halt()\n        for monitor in list(self._monitors):\n            monitor(('crashed', cause))\n\n    def _restart_later(self):\n        \"\"\"Restarted by its own supervisor: every child restarts.\"\"\"\n        with self._lock:\n            self._restarts.clear()\n            children = list(self._children)\n        for child, _ in children:\n            child._restart_later()\n\n    def _halt(self):\n        self.stop()\n\n    def monitor(self, notify):\n        \"\"\"notify(('crashed', cause)) when it gives up, and\n        notify(('stopped', None)) once stopped.\"\"\"\n        self._monitors.append(notify)\n\n    def stop(self):\n        \"\"\"Stops every child, last added first, without restarting them.\"\"\"\n        with self._lock:\n            if self._stopped:\n                return\n            self._stopped = True\n            children, self._children = list(self._children), []\n        for child, _ in reversed(children):\n            child._supervisor = None\n            child.stop()\n        for monitor in list(self._monitors):\n            monitor(('stopped', None))\n\n\ndef check_supervision():\n    \"\"\"The runtime's own check of crashes, links, monitors and supervision:\n    every strategy, lifetime, the restart limit and escalation. Raises\n    AssertionError naming the first behaviour that differs.\"\"\"\n    import time\n\n    def counter():\n        return Actor(0, restart=lambda s: 0)\n\n    def bump(a):\n        return a.call(lambda s: (s + 1, s + 1))\n\n    def fail(a):\n        try:\n            a.call(lambda s: 1 // 0)\n        except ActorCrashed:\n            return\n        raise AssertionError('a failing handler did not raise ActorCrashed')\n\n    def stopped(a, what):\n        try:\n            a.state()\n        except ActorStopped:\n            return\n        raise AssertionError(what + ' should have stopped')\n\n    def expect(actual, wanted, what):\n        if actual != wanted:\n            raise AssertionError(f'{what}: got {actual!r}, expected {wanted!r}')\n\n    a = counter()\n    bump(a)\n    fail(a)\n    stopped(a, 'an unsupervised actor that crashed')\n    sup = Supervisor('one_for_one')\n    x, y = sup.supervise(counter()), sup.supervise(counter())\n    bump(x), bump(y), bump(y)\n    fail(x)\n    expect((x.state(), y.state()), (0, 2), 'one for one restarts only the crashed child')\n    sup = Supervisor('one_for_all')\n    x, y = sup.supervise(counter()), sup.supervise(counter())\n    bump(x), bump(y)\n    fail(x)\n    expect((x.state(), y.state()), (0, 0), 'one for all restarts every child')\n    sup = Supervisor('rest_for_one')\n    x, y, z = [sup.supervise(counter()) for _ in range(3)]\n    bump(x), bump(y), bump(z)\n    fail(y)\n    expect((x.state(), y.state(), z.state()), (1, 0, 0), 'rest for one restarts the child and later ones')\n    sup = Supervisor()\n    t = sup.supervise(counter(), 'temporary')\n    fail(t)\n    stopped(t, 'a temporary child that crashed')\n    sup = Supervisor()\n    p, q = sup.supervise(counter(), 'permanent'), sup.supervise(counter(), 'transient')\n    bump(p)\n    p.stop()\n    expect(p.state(), 0, 'a permanent child restarts after a stop')\n    q.stop()\n    stopped(q, 'a transient child that was stopped')\n    events = []\n    sup = Supervisor('one_for_one', max_restarts=2, period=10)\n    sup.monitor(events.append)\n    x, y = sup.supervise(counter()), sup.supervise(counter())\n    fail(x), fail(x), fail(x)\n    stopped(y, 'a child of a supervisor past its restart limit')\n    expect([e[0] for e in events], ['crashed'], 'a supervisor past its limit tells its monitors')\n    outer = Supervisor('one_for_one', max_restarts=5, period=10)\n    inner = outer.supervise(Supervisor('one_for_one', max_restarts=1, period=10))\n    x, y = inner.supervise(counter()), inner.supervise(counter())\n    bump(y)\n    fail(x), fail(x)\n    expect((x.state(), y.state()), (0, 0), 'a supervisor past its limit is restarted by its own')\n    seen = []\n    a, b = counter(), counter()\n    a.link(b)\n    b.monitor(seen.append)\n    fail(a)\n    for _ in range(100):\n        if seen:\n            break\n        time.sleep(0.01)\n    stopped(b, 'an unsupervised actor linked to one that crashed')\n    expect([e[0] for e in seen], ['crashed'], 'a monitor hears of a crash')\n    sup = Supervisor(max_restarts=10)\n    a, b, c = [sup.supervise(counter()) for _ in range(3)]\n    a.link(b), b.link(c), c.link(a)\n    bump(a), bump(b), bump(c)\n    fail(a)\n    for _ in range(100):\n        if len(sup._restarts) >= 3:\n            break\n        time.sleep(0.01)\n    time.sleep(0.05)\n    expect((a.state(), b.state(), c.state(), len(sup._restarts)), (0, 0, 0, 3),\n           'a crash crosses each link once')\n\n\nclass Mailbox:\n    \"\"\"A queue with many senders and one receiver: the channel form of an\n    actor. A process that loops over receive() and answers each message is\n    an actor written by hand; send() never waits.\"\"\"\n\n    def __init__(self):\n        self._items = deque()\n        self._ready = threading.Condition()\n        self._closed = False\n\n    def send(self, value):\n        with self._ready:\n            if self._closed:\n                raise ActorStopped('the mailbox is closed')\n            self._items.append(value)\n            self._ready.notify()\n\n    def receive(self, timeout=None):\n        \"\"\"The next message; waits up to timeout seconds (forever when None)\n        and raises TimeoutError, or ActorStopped once closed and empty.\"\"\"\n        with self._ready:\n            if not self._ready.wait_for(lambda: self._items or self._closed, timeout):\n                raise TimeoutError('no message arrived in time')\n            if not self._items:\n                raise ActorStopped('the mailbox is closed')\n            return self._items.popleft()\n\n    def receive_within(self, micros, clock=None):\n        \"\"\"The Mailbox ability's receive ... within d: the next message, or\n        None when none arrives within micros microseconds. On a virtual\n        clock (any Clock handler but the default real one, as lawspec.time's\n        register_clock tells) it waits no real time:\n        it takes a message already sent, or lets the time pass on that clock\n        and gives None. Raises ActorStopped once closed and empty.\"\"\"\n        read = _ability_clock(clock)\n        if read is not None and read.virtual:\n            with self._ready:\n                if self._items:\n                    return self._items.popleft()\n                if self._closed:\n                    raise ActorStopped('the mailbox is closed')\n            read.sleep(micros)\n            return None\n        try:\n            return self.receive(max(0, micros) / 1_000_000)\n        except TimeoutError:\n            return None\n\n    def close(self):\n        \"\"\"Refuses further messages; those already sent can still be received.\"\"\"\n        with self._ready:\n            self._closed = True\n            self._ready.notify_all()\n\n\nclass _Crash:\n    \"\"\"An injected crash of an actor model, as a step with no arguments.\"\"\"\n    name = 'crash'\n    arguments = []\n    state = 0\n    unit = True\n    when = None\n    key = None\n    restart = False\n\n    def __init__(self, start_run, start_model, restart):\n        self._start_run, self._start_model, self._restart = start_run, start_model, restart\n\n    def admits(self, indices):\n        return True\n\n    def shifted(self, indices):\n        return indices\n\n    def run(self, symbols, actor):\n        if self._restart is not None:\n            actor.restart(lambda s: self._restart.run(symbols, s))\n        else:\n            actor.restart(lambda s: self._start_run(symbols, *symbols['_lawspec_start']))\n        return UNIT\n\n    def reference(self, symbols, state):\n        if self._restart is not None:\n            return self._restart.reference(symbols, state)\n        return self._start_model(symbols, *symbols['_lawspec_start'])\n\n\nclass _Reply(list):\n    def __init__(self):\n        super().__init__()\n        self.event = threading.Event()\n\n\ndef _actor_command(run, unit):\n    \"\"\"A handler bridge (state first, returning Pair result state, or the\n    state alone for a Unit result) as a command on an actor.\"\"\"\n    if unit:\n        return lambda symbols, actor, *args: actor.call(lambda s: (UNIT, run(symbols, s, *args)))\n    return lambda symbols, actor, *args: actor.call(lambda s: tuple(run(symbols, s, *args).fields))\n\n\n# Stateful models. A model's spec (see LawSpec.MachineSpec) lists its data\n# types, start and commands; the callbacks beside it are the generated\n# definitions that call the adapters, the references over the model state,\n# preconditions, the abstraction and invariants, each taking symbols first.\n# A run is generated by simulating the pure model, so every command in it is\n# allowed by typestate, its precondition and its reference; it is then\n# executed against the adapters and every result, abstracted state and\n# invariant is checked. A failing run is shrunk by dropping commands and\n# shrinking arguments, replaying the model to keep each candidate valid.\n\nclass ModelCommand:\n    def __init__(self, form, callbacks):\n        fields = {f[0]: f[1:] for f in form[2:]}\n        self.name = str(form[1])\n        self.arguments = fields['arguments']\n        self.state = fields['state'][0]\n        self.unit = fields['unit'][0] == 'true'\n        self.needs = fields['needs']\n        self.shifts = fields['shifts']\n        # The argument naming the key the command touches, for per-key checks.\n        key = fields.get('key', ['none'])[0]\n        self.key = None if key == 'none' else key\n        self.restart = fields.get('restart', ['false'])[0] == 'true'\n        self.run, self.reference, self.when = callbacks\n\n    def admits(self, indices):\n        return all((i >= n[1]) if n[0] == 'atleast' else (i == n[1]) for n, i in zip(self.needs, indices))\n\n    def shifted(self, indices):\n        return [i + s[1] if s[0] == 'by' else s[1] for s, i in zip(self.shifts, indices)]\n\n\nclass Model:\n    def __init__(self, spec, start, commands, abstract=None, invariants=()):\n        forms = read_descriptor(spec)\n        self.name = str(forms[0][1])\n        self.shared = forms[0][2] == 'shared'\n        self.values = Values({str(f[1]): f for f in forms if f[0] == 'data'})\n        start_form = next(f for f in forms if f[0] == 'start')\n        start_fields = {f[0]: f[1:] for f in start_form[1:]}\n        self.start_indices = start_fields.get('indices', [])\n        self.start_arguments = start_fields.get('arguments', [])\n        self.start_run, self.start_model = start\n        self.commands = [ModelCommand(f, c) for f, c in zip((f for f in forms if f[0] == 'command'), commands)]\n        self.abstract = abstract\n        kinds = next(f for f in forms if f[0] == 'invariants')[1:]\n        self.invariants = list(zip(kinds, invariants))\n        self.per_key = any(f[0] == 'perkey' and f[1] == 'true' for f in forms)\n        self.consistency = next((str(f[1]) for f in forms if f[0] == 'consistency'), 'linearizable')\n        # An actor model's start and handlers run inside an actor; the\n        # abstraction and state invariants read its state between messages.\n        # Sequential runs of an actor also inject crashes: the actor restarts\n        # from its last state (restart from) or its start, and the model\n        # follows the restart's reference (or the start's model state).\n        restarts = [c for c in self.commands if c.restart]\n        self.commands = [c for c in self.commands if not c.restart]\n        self.steps = self.commands\n        if any(f[0] == 'actor' and f[1] == 'true' for f in forms):\n            run, begin = self.start_run, self.start_model\n\n            def start_run(symbols, *args):\n                symbols['_lawspec_start'] = args\n                return Actor(run(symbols, *args))\n\n            def start_model(symbols, *args):\n                symbols['_lawspec_start'] = args\n                return begin(symbols, *args)\n\n            self.start_run, self.start_model = start_run, start_model\n            for c in self.commands:\n                c.run = _actor_command(c.run, c.unit)\n            self.steps = self.commands + [_Crash(run, begin, restarts[0] if restarts else None)]\n            if abstract is not None:\n                self.abstract = lambda symbols, actor: abstract(symbols, actor.state())\n            self.invariants = [(k, (lambda p: lambda symbols, s: p(symbols, s.state()))(p) if k == 'state' else p)\n                               for k, p in self.invariants]\n\n\nclass _Invalid(Exception):\n    \"\"\"A command the model does not allow here.\"\"\"\n\n\ndef _simulate(model, symbols, run):\n    \"\"\"The model states along a run, or _Invalid.\"\"\"\n    start_args, steps = run\n    try:\n        state = model.start_model(symbols, *start_args)\n    except Exception:\n        raise _Invalid()\n    indices = list(model.start_indices)\n    states = [state]\n    for index, args in steps:\n        command = model.steps[index]\n        if not command.admits(indices):\n            raise _Invalid()\n        state, _ = _step_model(command, symbols, args, state)\n        indices = command.shifted(indices)\n        states.append(state)\n    return states\n\n\ndef _step_model(command, symbols, args, state):\n    try:\n        if command.when is not None and not command.when(symbols, state):\n            raise _Invalid()\n        out = command.reference(symbols, *args, state)\n    except _Invalid:\n        raise\n    except Exception:\n        raise _Invalid()\n    if command.unit:\n        return out, UNIT\n    return out.fields[1], out.fields[0]\n\n\ndef _generate_run(model, random, length, size, crashes=False):\n    symbols = {}\n    start_args = [model.values.generate(d, random, size) for d in model.start_arguments]\n    try:\n        state = model.start_model(symbols, *start_args)\n    except Exception:\n        return (start_args, [])\n    indices = list(model.start_indices)\n    steps = []\n    for _ in range(length):\n        allowed = [i for i, c in enumerate(model.commands) if c.admits(indices)]\n        if not allowed:\n            break\n        index = allowed[random.below(len(allowed))]\n        # One step in eight of an actor's run is a crash.\n        if crashes and len(model.steps) > len(model.commands) and random.below(8) == 0:\n            index = len(model.commands)\n        command = model.steps[index]\n        args = [model.values.generate(d, random, size) for d in command.arguments]\n        try:\n            state, _ = _step_model(command, symbols, args, state)\n        except _Invalid:\n            continue\n        steps.append((index, args))\n        indices = command.shifted(indices)\n    return (start_args, steps)\n\n\ndef _execute(model, run):\n    \"\"\"None when the system agrees with the model along the run; otherwise\n    the failing step's number and what went wrong.\"\"\"\n    start_args, steps = run\n    symbols = {}\n    step = 0\n    try:\n        state = model.start_run(symbols, *start_args)\n        expected = model.start_model(symbols, *start_args)\n        failure = _check_state(model, symbols, state, expected)\n        if failure:\n            return step, failure\n        for index, args in steps:\n            step += 1\n            command = model.steps[index]\n            full = list(args)\n            full.insert(command.state, state)\n            out = command.run(symbols, *full)\n            if model.shared:\n                result = out\n            else:\n                result = UNIT if command.unit else out.fields[0]\n                state = out.fields[-1]\n            expected, wanted = _step_model(command, symbols, args, expected)\n            if not command.unit and compare_values(result, wanted) != 0:\n                return step, f'returned {render(result)}; the model returns {render(wanted)}'\n            failure = _check_state(model, symbols, state, expected)\n            if failure:\n                return step, failure\n    except _Invalid:\n        return step, 'the model does not allow this step'\n    except Exception as error:\n        return step, f'raised {type(error).__name__}: {error}'\n    return None\n\n\ndef _check_state(model, symbols, state, expected):\n    if model.abstract is not None:\n        actual = model.abstract(symbols, state)\n        if compare_values(actual, expected) != 0:\n            return f'the state is {render(actual)}; the model is {render(expected)}'\n    for kind, invariant in model.invariants:\n        if not invariant(symbols, expected if kind == 'model' else state):\n            return f'an invariant on the {kind} fails'\n    return None\n\n\ndef _shrink_candidates(model, run):\n    start_args, steps = run\n    n = len(steps)\n    size = n // 2\n    while size >= 1:\n        for begin in range(0, n, size):\n            yield (start_args, steps[:begin] + steps[begin + size:])\n        size //= 2\n    for k, (index, args) in enumerate(steps):\n        command = model.steps[index]\n        for j, (d, arg) in enumerate(zip(command.arguments, args)):\n            for c in model.values.shrink(d, arg):\n                yield (start_args, steps[:k] + [(index, args[:j] + [c] + args[j + 1:])] + steps[k + 1:])\n    for j, (d, arg) in enumerate(zip(model.start_arguments, start_args)):\n        for c in model.values.shrink(d, arg):\n            yield (start_args[:j] + [c] + start_args[j + 1:], steps)\n\n\ndef _shrink_run(model, run, failure, budget):\n    while budget > 0:\n        for candidate in _shrink_candidates(model, run):\n            budget -= 1\n            if budget <= 0:\n                break\n            try:\n                _simulate(model, {}, candidate)\n            except _Invalid:\n                continue\n            found = _execute(model, candidate)\n            if found is not None:\n                run, failure = candidate, found\n                break\n        else:\n            break\n    return run, failure\n\n\ndef _describe_run(model, run):\n    start_args, steps = run\n    parts = ['start(' + ', '.join(render(a) for a in start_args) + ')']\n    parts += [model.steps[i].name + '(' + ', '.join(render(a) for a in args) + ')' for i, args in steps]\n    return '; '.join(parts)\n\n\ndef check_model(model, cases=100, max_length=20, max_shrinks=2000, seed=None):\n    \"\"\"Checks the system against its model on generated runs; a failure\n    raises AssertionError naming the shortest failing run found.\n\n    A stateful model is checked by running generated command sequences\n    against the system and the model side by side, then shrinking a failing\n    run. ref:DEC-stateful-models-linearizability\"\"\"\n    import os\n    if seed is None:\n        seed = int(os.environ.get('LAWSPEC_SEED', '0'))\n    random = SplitMix64(seed)\n    for case in range(cases):\n        run = _generate_run(model, random, random.below(max_length + 1), 1 + case % 8, crashes=True)\n        failure = _execute(model, run)\n        if failure is not None:\n            run, (step, message) = _shrink_run(model, run, failure, max_shrinks)\n            raise AssertionError(f'model {model.name} fails at step {step} of '\n                                 f'{_describe_run(model, run)}: {message}')\n\n\n# Parallel runs of a shared model. A case is a sequential prefix and one\n# branch per thread, generated so that the model allows every interleaving\n# of the branches (a search over each thread's position and the model state,\n# memoized). The system runs the branches at the same time, each call's start\n# and return recorded on one counter, with random yields and short sleeps\n# around calls to shake out rare schedules. The history must be\n# linearizable: some interleaving that keeps every call after those that\n# returned before it started must give every result the model gives and\n# leave the state it leaves (a Wing-Gong search, memoized on the same\n# positions and model state). Each case runs several times.\n\n_THREADS = 3\n_BRANCH = 5\n\n\ndef _parallel_allowed(model, prefix, branches):\n    \"\"\"Whether the model allows the prefix then every interleaving.\"\"\"\n    symbols = {}\n    try:\n        state = _simulate(model, symbols, prefix)[-1]\n    except _Invalid:\n        return False\n    seen = set()\n\n    def visit(positions, state):\n        key = (positions, render(state))\n        if key in seen:\n            return True\n        seen.add(key)\n        for i, branch in enumerate(branches):\n            k = positions[i]\n            if k < len(branch):\n                index, args = branch[k]\n                try:\n                    after, _ = _step_model(model.commands[index], symbols, args, state)\n                except _Invalid:\n                    return False\n                if not visit(positions[:i] + (k + 1,) + positions[i + 1:], after):\n                    return False\n        return True\n    return visit(tuple(0 for _ in branches), state)\n\n\ndef _generate_branch(model, random, state, length, size):\n    symbols = {}\n    steps = []\n    for _ in range(length):\n        index = random.below(len(model.commands))\n        command = model.commands[index]\n        args = [model.values.generate(d, random, size) for d in command.arguments]\n        try:\n            state, _ = _step_model(command, symbols, args, state)\n        except _Invalid:\n            continue\n        steps.append((index, args))\n    return steps\n\n\ndef _generate_parallel(model, random, size, threads, branch_length):\n    prefix = _generate_run(model, random, random.below(4), size)\n    try:\n        state = _simulate(model, {}, prefix)[-1]\n    except _Invalid:\n        return prefix, [[] for _ in range(threads)]\n    branches = [_generate_branch(model, random, state, 1 + random.below(branch_length), size)\n                for _ in range(threads)]\n    # Drop the last step of the longest branch (the first, among equals)\n    # until every interleaving is allowed.\n    while not _parallel_allowed(model, prefix, branches):\n        longest = max(range(threads), key=lambda i: (len(branches[i]), -i))\n        branches[longest] = branches[longest][:-1]\n    return prefix, branches\n\n\ndef _perturb(random):\n    \"\"\"Nothing, a yield, or a sleep of 10 or 100 microseconds.\"\"\"\n    import time\n    choice = random.below(4)\n    if choice == 1:\n        time.sleep(0)\n    elif choice >= 2:\n        time.sleep(1e-5 if choice == 2 else 1e-4)\n\n\ndef _execute_parallel(model, case, shake):\n    \"\"\"None when the history is linearizable; otherwise what went wrong.\"\"\"\n    import threading\n    prefix, branches = case\n    start_args, steps = prefix\n    symbols = {}\n    try:\n        state = model.start_run(symbols, *start_args)\n        for index, args in steps:\n            command = model.commands[index]\n            full = list(args)\n            full.insert(command.state, state)\n            command.run(symbols, *full)\n    except Exception as error:\n        return f'the prefix raised {type(error).__name__}: {error}'\n    clock = [0]\n    lock = threading.Lock()\n    history = [[None] * len(b) for b in branches]\n    errors = []\n\n    def tick():\n        with lock:\n            clock[0] += 1\n            return clock[0]\n\n    def branch(i):\n        own = {}\n        random = SplitMix64(shake ^ ((i + 1) * 0x9E3779B97F4A7C15))\n        for k, (index, args) in enumerate(branches[i]):\n            command = model.commands[index]\n            full = list(args)\n            full.insert(command.state, state)\n            _perturb(random)\n            called = tick()\n            try:\n                result = command.run(own, *full)\n            except Exception as error:\n                with lock:\n                    errors.append(f'{command.name} raised {type(error).__name__}: {error}')\n                result = None\n            history[i][k] = (called, tick(), result)\n            _perturb(random)\n\n    threads = [threading.Thread(target=branch, args=(i,)) for i in range(len(branches))]\n    for t in threads:\n        t.start()\n    for t in threads:\n        t.join()\n    if errors:\n        return errors[0]\n    expected = _simulate(model, symbols, prefix)[-1]\n    final = model.abstract(symbols, state) if model.abstract is not None else None\n    if _linearizable(model, symbols, branches, history, expected, final, state):\n        return None\n    observed = '; '.join(\n        f'{_branch_name(i)}: {model.commands[branches[i][k][0]].name}() returned {render(history[i][k][2])}'\n        for i in range(len(branches)) for k in range(len(branches[i])))\n    return f'no order of the parallel calls agrees with the model ({observed})'\n\n\ndef _branch_name(i):\n    return chr(ord('A') + i)\n\n\ndef _linearizable(model, symbols, branches, history, expected, final, state):\n    \"\"\"Whether the history linearizes, with the final state and invariants\n    the model gives. For a set or map whose every call touches one key, each\n    key's calls are linearized separately (the keys are independent), one\n    group after another; otherwise all calls at once.\"\"\"\n    def finish(model_state):\n        if final is not None and compare_values(final, model_state) != 0:\n            return False\n        for kind, invariant in model.invariants:\n            if not invariant(symbols, model_state if kind == 'model' else state):\n                return False\n        return True\n    if not model.per_key:\n        return _linearize(model, symbols, branches, history, expected, finish)\n    groups = {}\n    for i, branch in enumerate(branches):\n        for k, (index, args) in enumerate(branch):\n            key = render(args[model.commands[index].key])\n            groups.setdefault(key, [[] for _ in branches])[i].append((branch[k], history[i][k]))\n    model_state = expected\n    for key in sorted(groups):\n        parts = groups[key]\n        ends = []\n        if not _linearize(model, symbols, [[s for s, _ in p] for p in parts], [[h for _, h in p] for p in parts],\n                          model_state, lambda end: ends.append(end) or True):\n            return False\n        model_state = ends[0]\n    return finish(model_state)\n\n\n_CONSISTENT = {'linearizable': 'linearizable', 'sequential': 'sequentially consistent',\n               'causal': 'causally consistent', 'eventual': 'eventually consistent'}\n\n\ndef _linearize(model, symbols, branches, history, expected, finish):\n    \"\"\"A Wing-Gong search: linearize, next, a call no pending call on another\n    thread returned before; memoized on positions and the model state.\n    finish judges each complete order's final model state.\n\n    With weaker consistency: sequential drops real time (each thread's own\n    order remains); causal checks each thread's results alone, since threads\n    that never message each other see only their own calls; eventual checks\n    no results, only the final state.\n\n    ref:wing-gong-linearizability\"\"\"\n    mode = model.consistency\n    if mode == 'causal':\n        for i, branch in enumerate(branches):\n            state = expected\n            for k, (index, args) in enumerate(branch):\n                command = model.commands[index]\n                try:\n                    state, wanted = _step_model(command, symbols, args, state)\n                except _Invalid:\n                    return False\n                if not command.unit and compare_values(history[i][k][2], wanted) != 0:\n                    return False\n        return True\n    seen = set()\n\n    def visit(positions, model_state):\n        key = (positions, render(model_state))\n        if key in seen:\n            return False\n        seen.add(key)\n        if all(k == len(b) for k, b in zip(positions, branches)):\n            return finish(model_state)\n        for i, branch in enumerate(branches):\n            k = positions[i]\n            if k == len(branch):\n                continue\n            called = history[i][k][0]\n            if mode == 'linearizable' and any(positions[j] < len(branches[j]) and history[j][positions[j]][1] < called\n                                              for j in range(len(branches)) if j != i):\n                continue\n            index, args = branch[k]\n            command = model.commands[index]\n            try:\n                after, wanted = _step_model(command, symbols, args, model_state)\n            except _Invalid:\n                continue\n            if mode != 'eventual' and not command.unit and compare_values(history[i][k][2], wanted) != 0:\n                continue\n            if visit(positions[:i] + (k + 1,) + positions[i + 1:], after):\n                return True\n        return False\n    return visit(tuple(0 for _ in branches), expected)\n\n\ndef _parallel_fails(model, case, repeats, shake):\n    for attempt in range(repeats):\n        failure = _execute_parallel(model, case, shake + attempt)\n        if failure is not None:\n            return failure\n    return None\n\n\ndef _shrink_parallel(model, case, failure, repeats, budget, shake):\n    while budget > 0:\n        prefix, branches = case\n        candidates = []\n        start_args, steps = prefix\n        for k in range(len(steps)):\n            candidates.append(((start_args, steps[:k] + steps[k + 1:]), branches))\n        for i in range(len(branches)):\n            for k in range(len(branches[i])):\n                shorter = [b if j != i else b[:k] + b[k + 1:] for j, b in enumerate(branches)]\n                candidates.append((prefix, shorter))\n        # Then smaller arguments, branch by branch, step by step.\n        for i in range(len(branches)):\n            for k, (index, args) in enumerate(branches[i]):\n                command = model.commands[index]\n                for a, (d, arg) in enumerate(zip(command.arguments, args)):\n                    for c in model.values.shrink(d, arg):\n                        step = (index, args[:a] + [c] + args[a + 1:])\n                        changed = [b if j != i else b[:k] + [step] + b[k + 1:] for j, b in enumerate(branches)]\n                        candidates.append((prefix, changed))\n        for candidate in candidates:\n            budget -= 1\n            if budget <= 0:\n                break\n            if not _parallel_allowed(model, *candidate):\n                continue\n            found = _parallel_fails(model, candidate, repeats, shake)\n            if found is not None:\n                case, failure = candidate, found\n                break\n        else:\n            break\n    return case, failure\n\n\ndef _describe_parallel(model, case):\n    prefix, branches = case\n    describe = lambda steps: '; '.join(model.commands[i].name + '(' + ', '.join(render(a) for a in args) + ')' for i, args in steps)\n    parts = [f'{_branch_name(i)}: {describe(b) or \"nothing\"}' for i, b in enumerate(branches)]\n    return f'{_describe_run(model, prefix)}, then {\", \".join(parts[:-1])} and {parts[-1]} at the same time'\n\n\ndef check_model_parallel(model, cases=50, repeats=10, max_shrinks=300, seed=None,\n                         threads=_THREADS, branch_length=_BRANCH):\n    \"\"\"Checks a shared model's histories under concurrency; a failure\n    raises AssertionError naming the smallest failing case found.\n\n    A shared model promises linearizability unless it names a weaker\n    consistency, so concurrent histories are judged against some sequential\n    order of the calls. ref:herlihy-wing-linearizability\n    ref:DEC-stateful-models-linearizability\"\"\"\n    import os\n    if seed is None:\n        seed = int(os.environ.get('LAWSPEC_SEED', '0'))\n    random = SplitMix64(seed ^ 0x5BD1E995)\n    for case_number in range(cases):\n        case = _generate_parallel(model, random, 1 + case_number % 8, threads, branch_length)\n        shake = random.next()\n        failure = _parallel_fails(model, case, repeats, shake)\n        if failure is not None:\n            case, failure = _shrink_parallel(model, case, failure, max(2, repeats // 2), max_shrinks, shake)\n            raise AssertionError(f'model {model.name} is not {_CONSISTENT[model.consistency]}: {_describe_parallel(model, case)}: {failure}')\n\n\n# Scenarios: processes that drive a shared model's commands at the same time\n# and talk over channels (see LawSpec.Core.Program for the spec). Each\n# channel has a queue per direction; a process holds an end of a channel as\n# (channel, side), the first branch of a par to use a channel taking side 0.\n# A channel end sent over a channel moves to the receiver. Every command's\n# call and return are stamped on one counter; the history must linearize\n# against the model, and every expect must hold, on each of many schedules.\n\nclass _Channel:\n    def __init__(self):\n        import queue\n        self.queues = (queue.Queue(), queue.Queue())\n        self.ended = [False, False]\n        self.lock = threading.Lock()\n\n    def receive(self, side):\n        \"\"\"The next value for side, _GONE once the other side has ended.\"\"\"\n        value = self.queues[1 - side].get(timeout=5)\n        if value is _GONE:\n            self.queues[1 - side].put(_GONE)\n        return value\n\n    def send(self, side, value):\n        \"\"\"A channel end sent to a process that has ended is given up.\"\"\"\n        with self.lock:\n            if not (self.ended[1 - side] and isinstance(value, _End)):\n                self.queues[side].put(value)\n                return\n        value.channel.gone(value.side)\n\n    def gone(self, side):\n        \"\"\"side's process has ended: the other side's receives that find\n        nothing more fail instead of waiting (again and again), and channel\n        ends on their way to side are given up too.\"\"\"\n        import queue\n        stranded = []\n        with self.lock:\n            if self.ended[side]:\n                return\n            self.ended[side] = True\n            self.queues[side].put(_GONE)\n            while True:\n                try:\n                    value = self.queues[1 - side].get_nowait()\n                except queue.Empty:\n                    break\n                if isinstance(value, _End):\n                    stranded.append(value)\n                elif value is _GONE:\n                    self.queues[1 - side].put(value)\n                    break\n        for end in stranded:\n            end.channel.gone(end.side)\n\n\n_GONE = object()\n\n\nclass _NetScenarioChannel:\n    \"\"\"A scenario channel whose two sides are endpoints on two nodes of a\n    faulty in-memory network. A channel end sent over it travels as its\n    name, and the receiver uses the end where it is (its owner).\"\"\"\n\n    def __init__(self, network, name, steps, values, registry):\n        self.name, self.registry = name, registry\n        self.nodes = [Node(network.insecure_transport_for_tests(f'{name}-{side}')) for side in (0, 1)]\n        def wire(sends, d):\n            return (sends, ['text'] if d == ['end'] else d)\n        self.ends = [self.nodes[0].listen(name, [wire(s, d) for s, d in steps], values)]\n        self.ends.append(self.nodes[1].dial(f'{self.nodes[0].address}/{name}', [wire(not s, d) for s, d in steps], values))\n        self.done = [False, False]\n        registry[name] = self\n\n    def send(self, side, value):\n        if isinstance(value, _End):\n            value = f'{value.channel.name}#{value.side}'\n        self.ends[side].send(side, value)\n\n    def receive(self, side):\n        try:\n            value = self.ends[side].receive(side, timeout=5)\n        except PeerFailed:\n            return _GONE\n        if isinstance(value, str) and '#' in value and value.rpartition('#')[0] in self.registry:\n            owner, _, which = value.rpartition('#')\n            return _End(self.registry[owner], int(which))\n        return value\n\n    def gone(self, side):\n        if not self.done[side]:\n            self.done[side] = True\n            self.ends[side].abandon(side)\n\n    def close(self):\n        for node in self.nodes:\n            node.close()\n\n\nclass _ScenarioMailbox:\n    \"\"\"A scenario's mailbox: any process sends, one receives. expected is\n    how many sends the scenario makes; a process that ends gives up the\n    sends it did not make, and a receive with nothing left to come fails\n    (_GONE) instead of waiting. Over a network, messages go from a sender\n    node to the receiver's node, each send waiting until it is delivered.\"\"\"\n\n    def __init__(self, name, expected, network=None, descriptor=None, values=None, registry=None):\n        self.name, self.expected = name, expected\n        self.received, self.abandoned = 0, 0\n        self.ready = threading.Condition()\n        self.items = deque()\n        self.registry = registry\n        self.nodes = []\n        if network is not None:\n            owner, senders = (Node(network.insecure_transport_for_tests(f'{name}-owner')),\n                              Node(network.insecure_transport_for_tests(f'{name}-senders')))\n            self.nodes = [owner, senders]\n            d = ['text'] if descriptor == ['end'] else descriptor\n            self.inbox = owner.mailbox(name, d, values)\n            self.remote = senders.remote_mailbox(f'{owner.address}/{name}', d, values, timeout=5.0)\n        else:\n            self.inbox = None\n\n    def send(self, value, clock):\n        if self.inbox is None:\n            with self.ready:\n                self.items.append((value, clock))\n                self.ready.notify_all()\n            return\n        if isinstance(value, _End):\n            value = f'{value.channel.name}#{value.side}'\n        # The clock travels beside the network, in send order.\n        with self.ready:\n            self.items.append((None, clock))\n        self.remote.send(value)\n        with self.ready:\n            self.ready.notify_all()\n\n    def give_up(self, count):\n        with self.ready:\n            self.abandoned += count\n            self.ready.notify_all()\n\n    def receive(self):\n        \"\"\"(value, sender's clock), or (_GONE, {}).\"\"\"\n        import time\n        give_up = time.monotonic() + 5\n        while True:\n            with self.ready:\n                if self.inbox is None and self.items:\n                    self.received += 1\n                    return self.items.popleft()\n                if self.received + self.abandoned >= self.expected and (self.inbox is None or not self.items):\n                    return _GONE, {}\n            if self.inbox is not None:\n                try:\n                    value = self.inbox.receive(timeout=0.02)\n                except TimeoutError:\n                    value = None\n                    if time.monotonic() > give_up:\n                        raise TimeoutError('a mailbox receive waited too long')\n                else:\n                    with self.ready:\n                        self.received += 1\n                        clock = self.items.popleft()[1] if self.items else {}\n                    if isinstance(value, str) and '#' in value and value.rpartition('#')[0] in self.registry:\n                        owner, _, which = value.rpartition('#')\n                        value = _End(self.registry[owner], int(which))\n                    return value, clock\n            else:\n                with self.ready:\n                    if not self.ready.wait(timeout=max(0.0, give_up - time.monotonic())):\n                        raise TimeoutError('a mailbox receive waited too long')\n\n    def close(self):\n        for node in self.nodes:\n            node.close()\n\n\ndef _scenario_sends(acts, name):\n    \"\"\"How many times these acts (not nested pars) send to name.\"\"\"\n    return sum(1 for act in acts if act[0] == 'send' and str(act[1]) == name)\n\n\ndef _all_sends(acts, name):\n    \"\"\"How many sends to name the whole program makes.\"\"\"\n    total = 0\n    for act in acts:\n        if act[0] == 'send' and str(act[1]) == name:\n            total += 1\n        elif act[0] == 'par':\n            total += sum(_all_sends(branch[1:], name) for branch in act[1:])\n    return total\n\n\ndef _scenario_processes(acts, found):\n    \"\"\"Every process of a par, outermost and first first (not or else).\"\"\"\n    for act in acts:\n        if act[0] == 'par':\n            for branch in act[1:]:\n                found.append(id(branch))\n                _scenario_processes(branch[1:], found)\n    return found\n\n\nclass _End:\n    \"\"\"A channel end in transit or held by a process.\"\"\"\n\n    def __init__(self, channel, side):\n        self.channel, self.side = channel, side\n\n\ndef _acts_channels(acts):\n    \"\"\"The names an act list sends, receives or sends away, with nested pars.\"\"\"\n    names = []\n    for act in acts:\n        if act[0] == 'send':\n            names.append(str(act[1]))\n            if act[2][0] == 'var':\n                names.append(str(act[2][1]))\n        elif act[0] == 'receive':\n            names.append(str(act[1]))\n        elif act[0] == 'receiveor':\n            names.append(str(act[1]))\n            names += _acts_channels(act[3][1:])\n        elif act[0] == 'par':\n            for branch in act[1:]:\n                names += _acts_channels(branch[1:])\n    return names\n\n\ndef _constant(form):\n    kind = form[0]\n    if kind == 'int':\n        return form[1]\n    if kind == 'text':\n        return str(form[1])\n    if kind == 'bool':\n        return form[1] == 'true'\n    return DataValue(str(form[1]), ())\n\n\ndef _run_scenario(model, spec, shake, crash=False, network=False):\n    import threading\n    forms = read_descriptor(spec)\n    title = str(forms[0][1])\n    names = [str(c) for c in next(f for f in forms if f[0] == 'channels')[1:]]\n    body = next(f for f in forms if f[0] == 'process')[1:]\n    wire = next((f for f in forms if f[0] == 'wire'), None)\n    boxes = [str(m) for f in forms if f[0] == 'mailboxes' for m in f[1:]]\n    if network and wire is not None:\n        # Loss, duplication and delay (which reorders); the channels'\n        # numbered, acknowledged frames must hide them all.\n        net = MemoryNetwork(seed=shake ^ 0x7F4A7C159E3779B9, loss=0.1, duplicate=0.1, delay=0.002)\n        types = Values({str(f[1]): f for f in wire[1:] if f[0] == 'data'})\n        steps = {str(f[1]): [(s[0] == 'send', s[1]) for s in f[2:]] for f in wire[1:] if f[0] == 'channel'}\n        kinds = {str(f[1]): f[2] for f in wire[1:] if f[0] == 'mailbox'}\n        registry = {}\n        channels = {name: _NetScenarioChannel(net, name, steps[name], types, registry) for name in names}\n        mailboxes = {m: _ScenarioMailbox(m, _all_sends(body, m), net, kinds[m], types, registry) if m in kinds\n                     else _ScenarioMailbox(m, _all_sends(body, m)) for m in boxes}\n    else:\n        channels = {name: _Channel() for name in names}\n        mailboxes = {m: _ScenarioMailbox(m, _all_sends(body, m)) for m in boxes}\n    commands = {c.name: c for c in model.commands}\n    symbols = {}\n    start_args = [model.values.minimal(d) for d in model.start_arguments]\n    state = model.start_run(symbols, *start_args)\n    expected = model.start_model(symbols, *start_args)\n    lock = threading.Lock()\n    clock = [0]\n    history = []\n    failures = []\n    # The crashed process (a par's branch) and the act it crashes before.\n    processes = _scenario_processes(body, [])\n    victim = None\n    if crash and processes:\n        chooser = SplitMix64(shake ^ 0xC3A5C85C97CB3127)\n        branch = processes[chooser.below(len(processes))]\n        victim = (branch, chooser.below(_branch_length(body, branch) + 1))\n\n    def tick():\n        with lock:\n            clock[0] += 1\n            return clock[0]\n\n    # Vector clocks: each value sent carries its sender's clock (kept here,\n    # in order per channel direction), so calls can be ordered by what\n    # happened before what.\n    stamps = {}\n\n    def stamp(channel, side, clock):\n        with lock:\n            stamps.setdefault((id(channel), side), deque()).append(dict(clock))\n\n    def unstamp(channel, side, clock, me):\n        with lock:\n            queue_ = stamps.get((id(channel), 1 - side))\n            sent = queue_.popleft() if queue_ else {}\n        for p, n in sent.items():\n            clock[p] = max(clock.get(p, 0), n)\n        clock[me] = clock.get(me, 0) + 1\n\n    def process(acts, env, ends, random, identity=None, clock=None):\n        \"\"\"'done' or 'failed'; either way, the ends still held are given up.\"\"\"\n        clock = {} if clock is None else clock\n        sent = {m: 0 for m in mailboxes}\n        try:\n            return steps(acts, env, ends, random, identity, clock, 'root' if identity is None else identity, sent)\n        finally:\n            for channel, side in ends.values():\n                channel.gone(side)\n            # Sends this process will never make.\n            for m, box in mailboxes.items():\n                missing = _scenario_sends(acts, m) - sent[m]\n                if missing > 0:\n                    box.give_up(missing)\n\n    def steps(acts, env, ends, random, identity, clock, me, sent):\n        own = {}\n        for index, act in enumerate(acts):\n            if failures:\n                return 'failed'\n            if victim is not None and victim == (identity, index):\n                return 'failed'\n            kind = act[0]\n            if kind == 'call':\n                command = commands[str(act[1])]\n                args = [env[str(o[1])] if o[0] == 'var' else _constant(o) for o in act[3:]]\n                full = list(args)\n                full.insert(command.state, state)\n                _perturb(random)\n                clock[me] = clock.get(me, 0) + 1\n                at_call = dict(clock)\n                called = tick()\n                try:\n                    result = command.run(own, *full)\n                except Exception as error:\n                    failures.append(f'{command.name} raised {type(error).__name__}: {error}')\n                    return 'failed'\n                returned = tick()\n                clock[me] += 1\n                with lock:\n                    history.append((command, args, result, called, returned, me, at_call, dict(clock)))\n                if act[2] != '_':\n                    env[str(act[2])] = result\n            elif kind == 'send' and str(act[1]) in mailboxes:\n                operand = act[2]\n                if operand[0] == 'var' and str(operand[1]) in ends:\n                    value = _End(*ends.pop(str(operand[1])))\n                else:\n                    value = env[str(operand[1])] if operand[0] == 'var' else _constant(operand)\n                _perturb(random)\n                clock[me] = clock.get(me, 0) + 1\n                try:\n                    mailboxes[str(act[1])].send(value, dict(clock))\n                except Unreachable as error:\n                    failures.append(f'a send to mailbox {act[1]} failed: {error}')\n                    return 'failed'\n                sent[str(act[1])] += 1\n            elif kind in ('receive', 'receiveor') and str(act[1]) in mailboxes:\n                try:\n                    value, carried = mailboxes[str(act[1])].receive()\n                except TimeoutError:\n                    failures.append(f'a receive on mailbox {act[1]} waited too long: the processes are blocked')\n                    return 'failed'\n                if value is _GONE:\n                    if kind == 'receive':\n                        return 'failed'\n                    return steps(act[3][1:], env, ends, random, None, clock, me, sent)\n                for p, n in carried.items():\n                    clock[p] = max(clock.get(p, 0), n)\n                clock[me] = clock.get(me, 0) + 1\n                if isinstance(value, _End):\n                    ends[str(act[2])] = (value.channel, value.side)\n                else:\n                    env[str(act[2])] = value\n            elif kind == 'send':\n                channel, side = ends[str(act[1])]\n                operand = act[2]\n                if operand[0] == 'var' and str(operand[1]) in ends:\n                    value = _End(*ends.pop(str(operand[1])))\n                else:\n                    value = env[str(operand[1])] if operand[0] == 'var' else _constant(operand)\n                _perturb(random)\n                clock[me] = clock.get(me, 0) + 1\n                stamp(channel, side, clock)\n                channel.send(side, value)\n            elif kind in ('receive', 'receiveor'):\n                channel, side = ends[str(act[1])]\n                try:\n                    value = channel.receive(side)\n                except Exception:\n                    failures.append(f'a receive on {act[1]} waited too long: the processes are blocked')\n                    return 'failed'\n                if value is _GONE:\n                    # The other process ended: or else runs instead of the\n                    # rest; without it, this process fails too.\n                    if kind == 'receive':\n                        return 'failed'\n                    del ends[str(act[1])]\n                    return steps(act[3][1:], env, ends, random, None, clock, me, sent)\n                unstamp(channel, side, clock, me)\n                if isinstance(value, _End):\n                    ends[str(act[2])] = (value.channel, value.side)\n                else:\n                    env[str(act[2])] = value\n            elif kind == 'par':\n                branches = act[1:]\n                owned = {}\n                for i, branch in enumerate(branches):\n                    for name in _acts_channels(branch[1:]):\n                        if name not in owned:\n                            owned[name] = []\n                        if i not in owned[name]:\n                            owned[name].append(i)\n                threads = []\n                outcomes = [None] * len(branches)\n                clocks = [dict(clock) for _ in branches]\n                for i, branch in enumerate(branches):\n                    mine = {}\n                    for name, users in owned.items():\n                        if i in users:\n                            if name in ends:\n                                mine[name] = ends.pop(name)\n                            elif name in channels:\n                                mine[name] = (channels[name], users.index(i))\n\n                    def run(i=i, branch=branch, mine=mine, random=SplitMix64(shake ^ ((len(threads) + 1) * 0x9E3779B97F4A7C15))):\n                        outcomes[i] = process(branch[1:], dict(env), mine, random, id(branch), clocks[i])\n                    threads.append(threading.Thread(target=run))\n                for t in threads:\n                    t.start()\n                for t in threads:\n                    t.join()\n                for child in clocks:\n                    for p, n in child.items():\n                        clock[p] = max(clock.get(p, 0), n)\n                clock[me] = clock.get(me, 0) + 1\n                # A failed branch fails the process that ran the par.\n                if 'failed' in outcomes:\n                    return 'failed'\n            elif kind == 'expect':\n                actual, wanted = env.get(str(act[1])), _constant(act[2])\n                if actual is None or compare_values(actual, wanted) != 0:\n                    failures.append(f'expect {act[1]} = {render(wanted)} failed: {act[1]} is {render(actual)}')\n                    return 'failed'\n        if victim is not None and victim == (identity, len(acts)):\n            return 'failed'\n        return 'done'\n\n    outcome = process(body, {}, {}, SplitMix64(shake))\n    for channel in channels.values():\n        if isinstance(channel, _NetScenarioChannel):\n            channel.close()\n    for box in mailboxes.values():\n        box.close()\n    if failures:\n        return title, failures[0] + (' (with a process crashed)' if victim is not None else '')\n    if outcome == 'failed' and victim is None:\n        return title, 'a process failed'\n    final = model.abstract(symbols, state) if model.abstract is not None else None\n    if not _linearizes_history(model, symbols, history, expected, final, state):\n        observed = '; '.join(f'{c.name}({\", \".join(render(a) for a in args)}) returned {render(r)}'\n                             for c, args, r, *_ in sorted(history, key=lambda h: h[3]))\n        return title, f'the calls are not {_CONSISTENT[model.consistency]} with the model ({observed})'\n    return title, None\n\n\ndef _branch_length(acts, identity):\n    \"\"\"How many acts the branch with this identity has.\"\"\"\n    for act in acts:\n        if act[0] == 'par':\n            for branch in act[1:]:\n                if id(branch) == identity:\n                    return len(branch) - 1\n                found = _branch_length(branch[1:], identity)\n                if found is not None:\n                    return found\n    return None\n\n\ndef _happened_before(a, b):\n    \"\"\"Whether call a returned before call b began, as far as messages tell:\n    a's return clock is at or below b's call clock everywhere.\"\"\"\n    return all(b[6].get(p, 0) >= n for p, n in a[7].items())\n\n\ndef _linearizes_history(model, symbols, history, expected, final, state):\n    \"\"\"A Wing-Gong search over the scenario's calls, memoized on the calls\n    done and the state. Each call is (command, args, result, called,\n    returned, process, call clock, return clock). Linearizable: next, a call\n    no pending call returned before (real time). Sequential: next, a call\n    every call that happened before it (its process's order, and messages)\n    is done. Causal: each process's results from an order of what happened\n    before them. Eventual: no results, only the final state.\"\"\"\n    mode = model.consistency\n    count = len(history)\n\n    def before(j, i):\n        if mode == 'linearizable':\n            return history[j][4] < history[i][3]\n        return _happened_before(history[j], history[i])\n\n    def search(members, checked, judge_final):\n        seen = set()\n        full = 0\n        for i in members:\n            full |= 1 << i\n\n        def visit(done, model_state):\n            key = (done, render(model_state))\n            if key in seen:\n                return False\n            seen.add(key)\n            if done == full:\n                if not judge_final:\n                    return True\n                if final is not None and compare_values(final, model_state) != 0:\n                    return False\n                return all(invariant(symbols, model_state if kind == 'model' else state)\n                           for kind, invariant in model.invariants)\n            for i in members:\n                if done & (1 << i):\n                    continue\n                if any(not done & (1 << j) and before(j, i) for j in members if j != i):\n                    continue\n                command, args, result = history[i][0], history[i][1], history[i][2]\n                try:\n                    after, wanted = _step_model(command, symbols, args, model_state)\n                except _Invalid:\n                    continue\n                if i in checked and not command.unit and compare_values(result, wanted) != 0:\n                    continue\n                if visit(done | (1 << i), after):\n                    return True\n            return False\n        return visit(0, expected)\n\n    everything = list(range(count))\n    if mode == 'causal':\n        for process in {h[5] for h in history}:\n            own = [i for i in everything if history[i][5] == process]\n            seen_by = sorted(set(own) | {j for j in everything for i in own if j != i and _happened_before(history[j], history[i])})\n            if not search(seen_by, set(own), False):\n                return False\n        return True\n    return search(everything, set() if mode == 'eventual' else set(everything), True)\n\n\ndef check_scenario(model, spec, runs=30, seed=None):\n    \"\"\"Runs a scenario on many schedules; a failure raises AssertionError.\"\"\"\n    import os\n    if seed is None:\n        seed = int(os.environ.get('LAWSPEC_SEED', '0'))\n    random = SplitMix64(seed ^ 0x2545F4914F6CDD1D)\n    for run in range(runs):\n        # Every third run crashes one process of a par at a random point, and\n        # every third other one sends each channel over a faulty network.\n        title, failure = _run_scenario(model, spec, random.next(), crash=run % 3 == 2, network=run % 3 == 1)\n        if failure is not None:\n            raise AssertionError(f'scenario {title} fails: {failure}')\n\n\n# Sessions: typed channel ends for implementation code. The generated\n# lawspec_sessions module gives every protocol step its own class; these are\n# the pieces those classes share.\n\nclass SessionError(Exception):\n    \"\"\"An end of a session channel was used wrongly.\"\"\"\n\n\nclass Channel:\n    \"\"\"A two-way channel between side 0 and side 1, one queue per direction.\n\n    Ends talk to it only through send(side, value) and receive(side), so a\n    network transport can stand in for it by providing the same two methods.\n    \"\"\"\n\n    def __init__(self):\n        import queue\n        self._queues = (queue.Queue(), queue.Queue())\n\n    def send(self, side, value):\n        \"\"\"Sends value from side to the other side.\"\"\"\n        self._queues[side].put(value)\n\n    def receive(self, side):\n        \"\"\"Waits for the next value the other side sent to side; raises\n        PeerFailed once the other side has given up and nothing is left.\"\"\"\n        value = self._queues[1 - side].get()\n        if value is _ABANDONED:\n            self._queues[1 - side].put(value)\n            raise PeerFailed('the other end gave up the conversation (its process failed or abandoned it)')\n        return value\n\n    def abandon(self, side):\n        \"\"\"side gives up: the other side's receives fail after the values\n        already sent.\"\"\"\n        self._queues[side].put(_ABANDONED)\n\n\n_ABANDONED = object()\n\n\nclass PeerFailed(Exception):\n    \"\"\"A receive whose other end gave up: its process failed, or it called\n    abandon(). Catch it to handle the failure (or else); otherwise this\n    process fails too.\"\"\"\n\n\nclass SessionEnd:\n    \"\"\"One end of a channel, before one step of its protocol. An end can be\n    used once: each send or receive returns the end for the next step.\n\n    Using an end exactly once is what makes a session follow its protocol;\n    with channels joined in a tree, scenarios are deadlock-free by\n    construction. ref:DEC-sessions-by-construction\n    ref:caires-pfenning-session-types ref:wadler-propositions-as-sessions\"\"\"\n\n    def __init__(self, channel, side):\n        self._channel = channel\n        self._side = side\n        self._used = False\n        self._lock = threading.Lock()\n\n    def _take(self):\n        with self._lock:\n            if self._used:\n                raise SessionError(\n                    f'{type(self).__qualname__}: this end was already used; '\n                    'use the end its last step returned')\n            self._used = True\n        return self._channel\n\n    def _send(self, value, after):\n        channel = self._take()\n        channel.send(self._side, value)\n        return after(channel, self._side)\n\n    def _send_end(self, end, start, after):\n        \"\"\"Sends end, which must be an unused start end of class start; the\n        receiver gets it, and this side must not use it any more.\"\"\"\n        if not isinstance(end, start):\n            raise TypeError(f'{type(self).__qualname__}.send expects a '\n                            f'{start.__qualname__}, not {type(end).__qualname__}')\n        moved = start(end._take(), end._side)\n        return self._send(moved, after)\n\n    def _receive(self, after):\n        channel = self._take()\n        value = channel.receive(self._side)\n        return value, after(channel, self._side)\n\n    def abandon(self):\n        \"\"\"Gives up the conversation: the other end's receives fail with\n        PeerFailed once it has received what was already sent.\"\"\"\n        self._take().abandon(self._side)\n\n\ndef check_send(value, t):\n    \"\"\"Checks that value is a native value of the scalar type t.\"\"\"\n    try:\n        validate(value, t)\n    except (TypeError, ValueError) as error:\n        raise TypeError(f'cannot send {value!r} as {t}: {error}') from None\n    return value\n\n\nclass Spawned:\n    \"\"\"A function running in its own thread; join() waits for it.\"\"\"\n\n    def __init__(self, fn, args):\n        self._result = None\n        self._error = None\n\n        def run():\n            try:\n                self._result = fn(*args)\n            except BaseException as error:  # re-raised by join()\n                self._error = error\n                # A failed process gives up the channel ends it was given.\n                for arg in args:\n                    if isinstance(arg, SessionEnd):\n                        arg._channel.abandon(arg._side)\n        self._thread = threading.Thread(target=run, daemon=True)\n        self._thread.start()\n\n    def join(self):\n        \"\"\"Waits for the function; returns its result or raises its error.\"\"\"\n        self._thread.join()\n        if self._error is not None:\n            raise self._error\n        return self._result\n\n\ndef spawn(fn, *args):\n    \"\"\"Runs fn(*args) in a new thread and returns a handle with join().\"\"\"\n    return Spawned(fn, args)\n\n\ndef par(*fns):\n    \"\"\"Runs the functions at once, waits for all of them and returns their\n    results in order; if any fails, raises the first failure.\"\"\"\n    handles = [spawn(fn) for fn in fns]\n    results, failure = [], None\n    for handle in handles:\n        try:\n            results.append(handle.join())\n        except BaseException as error:\n            if failure is None:\n                failure = error\n            results.append(None)\n    if failure is not None:\n        raise failure\n    return results\n\n\n# Distribution. Values cross the network in a canonical binary encoding\n# driven by their type descriptor (the same descriptors as generation), so\n# no tags are sent and every target writes the same bytes:\n#   int: zigzag LEB128 of the integer (any size)      bool: 0 or 1\n#   text, bytes: LEB128 length, then UTF-8 or raw     unit: nothing\n#   list: LEB128 count, then items                     maybe: 0, or 1 then the value\n#   either: 0 then left, or 1 then right               data: LEB128 constructor index, then fields\n# A node sends frames over a Transport (in memory, TCP or HTTP): kind,\n# entity name, the sender's address, an id and a payload.\n\nclass WireError(ValueError):\n    \"\"\"Bytes that are not an encoding of a value of the expected type.\"\"\"\n\n\nclass Unreachable(Exception):\n    \"\"\"A node could not be reached, or did not answer in time.\"\"\"\n\n\ndef _put_varint(out, n):\n    while True:\n        byte = n & 0x7F\n        n >>= 7\n        if n:\n            out.append(byte | 0x80)\n        else:\n            out.append(byte)\n            return\n\n\ndef _get_varint(buf, pos):\n    result, shift = 0, 0\n    while True:\n        if pos >= len(buf):\n            raise WireError('the bytes end in the middle of a value')\n        byte = buf[pos]\n        pos += 1\n        result |= (byte & 0x7F) << shift\n        if byte < 0x80:\n            return result, pos\n        shift += 7\n\n\ndef _wire_put(values, d, v, out):\n    d = values.resolve(d)\n    kind = d[0]\n    if kind == 'int':\n        lo, hi = d[2], d[3]\n        if isinstance(v, bool) or not isinstance(v, int) or (lo is not None and v < lo) or (hi is not None and v > hi):\n            raise WireError(f'{v!r} is not a {d[1]}')\n        _put_varint(out, v * 2 if v >= 0 else -v * 2 - 1)\n    elif kind == 'bool':\n        out.append(1 if v else 0)\n    elif kind in ('text', 'bytes'):\n        raw = v.encode('utf-8') if kind == 'text' else bytes(v)\n        _put_varint(out, len(raw))\n        out.extend(raw)\n    elif kind == 'unit':\n        pass\n    elif kind == 'list':\n        _put_varint(out, len(v))\n        for item in v:\n            _wire_put(values, d[1], item, out)\n    elif kind == 'maybe':\n        if v.tag.endswith('Nothing'):\n            out.append(0)\n        else:\n            out.append(1)\n            _wire_put(values, d[1], v.fields[0], out)\n    elif kind == 'either':\n        left = v.tag.endswith('Left')\n        out.append(0 if left else 1)\n        _wire_put(values, d[1] if left else d[2], v.fields[0], out)\n    elif kind == 'data':\n        for index, ctor in enumerate(d[2:]):\n            if str(ctor[1]) == v.tag:\n                _put_varint(out, index)\n                for field, fd in zip(v.fields, ctor[2:]):\n                    _wire_put(values, fd, field, out)\n                return\n        raise WireError(f'{v.tag} is not a constructor of {d[1]}')\n    elif kind == 'end':\n        _wire_put(values, ['text'], v, out)\n    else:\n        raise WireError('unknown descriptor ' + str(d))\n\n\ndef _wire_get(values, d, buf, pos):\n    d = values.resolve(d)\n    kind = d[0]\n    if kind == 'int':\n        z, pos = _get_varint(buf, pos)\n        v = z // 2 if z % 2 == 0 else -(z + 1) // 2\n        lo, hi = d[2], d[3]\n        if (lo is not None and v < lo) or (hi is not None and v > hi):\n            raise WireError(f'{v} is out of range for {d[1]}')\n        return v, pos\n    if kind == 'bool':\n        if pos >= len(buf) or buf[pos] > 1:\n            raise WireError('not a Bool')\n        return buf[pos] == 1, pos + 1\n    if kind in ('text', 'bytes', 'end'):\n        n, pos = _get_varint(buf, pos)\n        if pos + n > len(buf):\n            raise WireError('the bytes end in the middle of a value')\n        raw = bytes(buf[pos:pos + n])\n        if kind == 'bytes':\n            return raw, pos + n\n        try:\n            return raw.decode('utf-8'), pos + n\n        except UnicodeDecodeError:\n            raise WireError('text that is not UTF-8') from None\n    if kind == 'unit':\n        return UNIT, pos\n    if kind == 'list':\n        n, pos = _get_varint(buf, pos)\n        items = []\n        for _ in range(n):\n            item, pos = _wire_get(values, d[1], buf, pos)\n            items.append(item)\n        return items, pos\n    if kind in ('maybe', 'either'):\n        if pos >= len(buf) or buf[pos] > 1:\n            raise WireError(f'not a {kind.capitalize()}')\n        which = buf[pos]\n        pos += 1\n        if kind == 'maybe':\n            if which == 0:\n                return DataValue('Maybe::Nothing', ()), pos\n            v, pos = _wire_get(values, d[1], buf, pos)\n            return DataValue('Maybe::Just', (v,)), pos\n        v, pos = _wire_get(values, d[1] if which == 0 else d[2], buf, pos)\n        return DataValue('Either::Left' if which == 0 else 'Either::Right', (v,)), pos\n    if kind == 'data':\n        index, pos = _get_varint(buf, pos)\n        ctors = d[2:]\n        if index >= len(ctors):\n            raise WireError(f'no constructor {index} in {d[1]}')\n        fields = []\n        for fd in ctors[index][2:]:\n            v, pos = _wire_get(values, fd, buf, pos)\n            fields.append(v)\n        return DataValue(str(ctors[index][1]), tuple(fields)), pos\n    raise WireError('unknown descriptor ' + str(d))\n\n\ndef wire_encode(values, d, v):\n    \"\"\"The value's canonical bytes.\"\"\"\n    out = bytearray()\n    _wire_put(values, d, v, out)\n    return bytes(out)\n\n\ndef wire_decode(values, d, data):\n    \"\"\"The value encoded by exactly these bytes.\"\"\"\n    v, pos = _wire_get(values, d, data, 0)\n    if pos != len(data):\n        raise WireError('extra bytes after the value')\n    return v\n\n\ndef wire_encoded(text, seed, size, count):\n    \"\"\"count values generated from one seed, encoded, in hexadecimal.\"\"\"\n    values, d = values_from(text)\n    random = SplitMix64(seed)\n    return [wire_encode(values, d, values.generate(d, random, size)).hex() for _ in range(count)]\n\n\n# The failure database's inputs (see LawSpec.Search): a failing case's\n# inputs, each in the wire encoding of its descriptor, kept under\n# LAWSPEC_FAILURES/inputs and replayed before the law's next generated cases.\ndef _search_file(law):\n    import os\n    directory = os.environ.get('LAWSPEC_FAILURES')\n    if not directory:\n        return None\n    safe = ''.join(c if c.isalnum() or c in '-_' else '_' for c in law)\n    return os.path.join(directory, 'inputs', safe + '.json')\n\n\ndef search_remember(law, descriptors, values):\n    \"\"\"Keeps a failing case's inputs; the last one kept is the smallest the\n    property library found.\"\"\"\n    import json\n    import os\n    path = _search_file(law)\n    if path is None:\n        return\n    try:\n        encoded = []\n        for text, value in zip(descriptors, values):\n            table, d = values_from(text)\n            encoded.append(wire_encode(table, d, value).hex())\n    except Exception:  # noqa: BLE001 - kept by seed only\n        return\n    os.makedirs(os.path.dirname(path), exist_ok=True)\n    with open(path, 'w', encoding='utf-8') as out:\n        json.dump({'law': law, 'inputs': encoded}, out)\n\n\ndef search_replay(law, descriptors, case):\n    \"\"\"Runs the law on the inputs its last failure kept, if any; they leave\n    the database once the law holds for them.\"\"\"\n    import json\n    import os\n    path = _search_file(law)\n    if path is None or not os.path.exists(path):\n        return\n    with open(path, encoding='utf-8') as source:\n        entry = json.load(source)\n    try:\n        values = []\n        for text, encoded in zip(descriptors, entry.get('inputs', [])):\n            table, d = values_from(text)\n            values.append(wire_decode(table, d, bytes.fromhex(encoded)))\n    except (WireError, ValueError):\n        values = []\n    if len(values) == len(descriptors):\n        print(f'{law}: replaying the failing inputs kept in .lawspec/failures')\n        case(values)\n    os.remove(path)\n\n\ndef wire_round_trips(text, seed, size, count):\n    \"\"\"Whether count generated values decode to themselves.\"\"\"\n    values, d = values_from(text)\n    random = SplitMix64(seed)\n    for _ in range(count):\n        v = values.generate(d, random, size)\n        if not _same(wire_decode(values, d, wire_encode(values, d, v)), v):\n            return False\n    return True\n\n\n_NO_TYPES = Values({})\n_FRAME = [['text'], ['text'], ['text'], ['int', 'UInt64', 0, None], ['bytes']]\n\n\ndef _frame_encode(kind, to, source, ident, payload):\n    out = bytearray()\n    for d, v in zip(_FRAME, (kind, to, source, ident, payload)):\n        _wire_put(_NO_TYPES, d, v, out)\n    return bytes(out)\n\n\ndef _frame_decode(data):\n    pos, fields = 0, []\n    for d in _FRAME:\n        v, pos = _wire_get(_NO_TYPES, d, data, pos)\n        fields.append(v)\n    if pos != len(data):\n        raise WireError('extra bytes after a frame')\n    return fields\n\n\ndef _split_address(address):\n    \"\"\"'tcp://host:port/name' as ('tcp://host:port', 'name').\"\"\"\n    node, _, name = address.rpartition('/')\n    if not node or '://' not in node:\n        raise ValueError(f'{address!r} is not an address such as tcp://127.0.0.1:7000/name')\n    return node, name\n\n\nclass Transport:\n    \"\"\"Moves frames between nodes. start(deliver) begins calling\n    deliver(frame) for every frame that arrives; send(node, frame) sends one\n    to the node at that address, best effort; close() stops.\"\"\"\n\n    address = None\n\n    def start(self, deliver):\n        raise NotImplementedError\n\n    def send(self, node, frame):\n        raise NotImplementedError\n\n    def close(self):\n        pass\n\n\nclass MemoryNetwork:\n    \"\"\"Nodes in one process, with faults for testing: each frame may be lost\n    or duplicated, and is delayed by up to delay seconds (so frames can\n    overtake each other); partition(...) cuts nodes off until heal().\"\"\"\n\n    def __init__(self, seed=0, loss=0.0, duplicate=0.0, delay=0.0, record=False):\n        self._random = SplitMix64(seed)\n        self.loss, self.duplicate, self.delay = loss, duplicate, delay\n        # With record, every record sent, as the network saw it.\n        self.recorded = [] if record else None\n        self._nodes = {}\n        self._groups = None\n        self._lock = threading.Lock()\n\n    def transport(self, name):\n        return _MemoryTransport(self, 'mem://' + name)\n\n    def insecure_transport_for_tests(self, name):\n        \"\"\"A transport whose node skips the handshake and sends frames in\n        the clear: for tests of the frame layer only. Only an in-memory\n        network makes one, and no configuration selects it.\"\"\"\n        return InsecureMemoryTransport(self, 'mem://' + name)\n\n    def partition(self, *groups):\n        \"\"\"Only nodes named in the same group reach each other.\"\"\"\n        with self._lock:\n            self._groups = [set('mem://' + n for n in g) for g in groups]\n\n    def heal(self):\n        with self._lock:\n            self._groups = None\n\n    def _chance(self, p):\n        return p > 0 and self._random.below(1 << 30) < p * (1 << 30)\n\n    def _send(self, source, node, frame):\n        with self._lock:\n            if self.recorded is not None:\n                self.recorded.append(bytes(frame))\n            deliver = self._nodes.get(node)\n            if deliver is None:\n                raise Unreachable(f'no node at {node}')\n            if self._groups is not None and not any(source in g and node in g for g in self._groups):\n                return\n            if self._chance(self.loss):\n                return\n            copies = 2 if self._chance(self.duplicate) else 1\n            delays = [self._random.below(1001) * self.delay / 1000 for _ in range(copies)]\n        for wait in delays:\n            if wait <= 0:\n                threading.Thread(target=deliver, args=(frame,), daemon=True).start()\n            else:\n                timer = threading.Timer(wait, deliver, args=(frame,))\n                timer.daemon = True\n                timer.start()\n\n\nclass _MemoryTransport(Transport):\n    insecure_for_tests = False\n\n    def __init__(self, network, address):\n        self._network, self.address = network, address\n\n    def start(self, deliver):\n        with self._network._lock:\n            self._network._nodes[self.address] = deliver\n\n    def send(self, node, frame):\n        self._network._send(self.address, node, frame)\n\n    def close(self):\n        with self._network._lock:\n            self._network._nodes.pop(self.address, None)\n\n\nclass InsecureMemoryTransport(_MemoryTransport):\n    \"\"\"In memory, without the handshake: tests only.\"\"\"\n\n    insecure_for_tests = True\n\n\nclass TcpTransport(Transport):\n    \"\"\"Frames over TCP, each a 4-byte big-endian length then the frame.\n    port 0 picks a free port; the address is tcp://host:port.\"\"\"\n\n    def __init__(self, host='127.0.0.1', port=0):\n        import socket\n        self._server = socket.create_server((host, port))\n        self.address = f'tcp://{host}:{self._server.getsockname()[1]}'\n        self._connections = {}\n        self._lock = threading.Lock()\n        self._closed = False\n\n    def start(self, deliver):\n        def accept():\n            while not self._closed:\n                try:\n                    connection, _ = self._server.accept()\n                except OSError:\n                    return\n                threading.Thread(target=self._read, args=(connection, deliver), daemon=True).start()\n        threading.Thread(target=accept, daemon=True).start()\n\n    @staticmethod\n    def _read(connection, deliver):\n        def exactly(n):\n            data = bytearray()\n            while len(data) < n:\n                chunk = connection.recv(n - len(data))\n                if not chunk:\n                    return None\n                data.extend(chunk)\n            return bytes(data)\n        with connection:\n            while True:\n                header = exactly(4)\n                if header is None:\n                    return\n                frame = exactly(int.from_bytes(header, 'big'))\n                if frame is None:\n                    return\n                deliver(frame)\n\n    def send(self, node, frame):\n        import socket\n        host, _, port = node[len('tcp://'):].rpartition(':')\n        data = len(frame).to_bytes(4, 'big') + frame\n        with self._lock:\n            for attempt in range(2):\n                connection = self._connections.get(node)\n                try:\n                    if connection is None:\n                        connection = socket.create_connection((host, int(port)), timeout=5)\n                        self._connections[node] = connection\n                    connection.sendall(data)\n                    return\n                except OSError as error:\n                    self._connections.pop(node, None)\n                    if attempt == 1:\n                        raise Unreachable(f'cannot reach {node}: {error}') from None\n\n    def close(self):\n        self._closed = True\n        self._server.close()\n        with self._lock:\n            for connection in self._connections.values():\n                connection.close()\n            self._connections.clear()\n\n\nclass HttpTransport(Transport):\n    \"\"\"Frames as HTTP POST bodies to /lawspec; the address is http://host:port.\"\"\"\n\n    def __init__(self, host='127.0.0.1', port=0):\n        from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer\n        transport = self\n\n        class Handler(BaseHTTPRequestHandler):\n            def do_POST(self):\n                body = self.rfile.read(int(self.headers.get('Content-Length', '0')))\n                self.send_response(204 if self.path == '/lawspec' else 404)\n                self.end_headers()\n                if self.path == '/lawspec' and transport._deliver is not None:\n                    transport._deliver(body)\n\n            def log_message(self, *args):\n                pass\n\n        self._server = ThreadingHTTPServer((host, port), Handler)\n        self._server.daemon_threads = True\n        self.address = f'http://{host}:{self._server.server_address[1]}'\n        self._deliver = None\n\n    def start(self, deliver):\n        self._deliver = deliver\n        threading.Thread(target=self._server.serve_forever, kwargs={'poll_interval': 0.05}, daemon=True).start()\n\n    def send(self, node, frame):\n        import urllib.request\n        request = urllib.request.Request(node + '/lawspec', data=frame, method='POST',\n                                         headers={'Content-Type': 'application/octet-stream'})\n        try:\n            with urllib.request.urlopen(request, timeout=5):\n                pass\n        except OSError as error:\n            raise Unreachable(f'cannot reach {node}: {error}') from None\n\n    def close(self):\n        self._server.shutdown()\n        self._server.server_close()\n\n\n# The secure network handler lives in lawspec_network, which the compiler\n# writes beside this runtime when a program imports lawspec.network: it needs\n# the crypto libraries, which programs without nodes do without. It\n# registers itself here when imported (register_secure_network).\n_SECURE_NETWORK = [None]\n\n\ndef register_secure_network(provider):\n    \"\"\"provider.layer(node, identity, trusted) makes a node's secure layer:\n    send(peer, frame) and receive(record) -> frame or None.\"\"\"\n    _SECURE_NETWORK[0] = provider\n\n\ndef _secure_network():\n    if _SECURE_NETWORK[0] is None:\n        try:\n            import lawspec_network  # noqa: F401  (registers itself)\n        except ImportError as error:\n            if getattr(error, 'name', None) not in (None, 'lawspec_network'):\n                raise\n    if _SECURE_NETWORK[0] is None:\n        raise LookupError('a node needs the secure network handler: add `import lawspec.network` '\n                          'to a unit of the program, so lawspec_network is generated')\n    return _SECURE_NETWORK[0]\n\n\ndef _secure_random(n):\n    import os\n    return os.urandom(n)\n\n\ndef secure_token():\n    \"\"\"A one-time token from the operating system's secure generator: 32\n    bytes as 64 hexadecimal digits, as SecureRandom's secureToken gives.\"\"\"\n    return _secure_random(32).hex()\n\n\nclass Node:\n    \"\"\"A process's presence on a network: it names local mailboxes, actors,\n    channel ends and definitions, so other nodes can reach them at\n    <node address>/<name>, and it sends to theirs.\n\n    Order is kept within one channel; a mailbox or an actor call is best\n    effort: a lost call fails with Unreachable after its timeout.\n\n    Every target's node speaks the same frames, so nodes written in\n    different languages talk to each other.\n    ref:DEC-distribution-canonical-wire\"\"\"\n\n    def __init__(self, transport, identity=None, trusted=None):\n        \"\"\"identity: a NodeIdentity (by default the one lawspec.json binds,\n        or a fresh one); trusted: the fingerprints of the only peers to talk\n        to (by default any peer, each address keeping the first identity it\n        shows). A transport made for tests only (insecure_for_tests) skips\n        the handshake; no other transport can.\"\"\"\n        self.transport = transport\n        self.address = transport.address\n        self._secure = None if getattr(transport, 'insecure_for_tests', False) else \\\n            _secure_network().layer(self, identity, trusted)\n        self.identity = None if self._secure is None else self._secure.identity\n        self._entities = {}\n        self._pending = {}\n        # Requests already seen, by sender and id, with their reply once\n        # sent: a request sent again (lost reply, duplicated frame) is\n        # answered again without running twice.\n        self._seen = {}\n        self._ids = iter(range(1, 1 << 62))\n        self._lock = threading.Lock()\n        self.closed = False\n        transport.start(self._arrive)\n\n    def _arrive(self, record):\n        if self._secure is None:\n            self._deliver(record)\n            return\n        frame = self._secure.receive(record)\n        if frame is not None:\n            self._deliver(frame)\n\n    def _transmit(self, node, frame):\n        if self._secure is None:\n            self.transport.send(node, frame)\n        else:\n            self._secure.send(node, frame)\n\n    def close(self):\n        self.closed = True\n        self.transport.close()\n\n    def _next_id(self):\n        with self._lock:\n            return next(self._ids)\n\n    def _send(self, address, kind, payload, ident=0):\n        node, name = _split_address(address)\n        self._transmit(node, _frame_encode(kind, name, self.address, ident, payload))\n\n    def _forward(self, address, kind, source, ident, payload):\n        \"\"\"Passes a frame on to address unchanged, keeping its source.\"\"\"\n        node, name = _split_address(address)\n        try:\n            self._transmit(node, _frame_encode(kind, name, source, ident, payload))\n        except Unreachable:\n            pass\n\n    def _register(self, name, entity):\n        if '/' in name or not name:\n            raise ValueError(f'{name!r} is not a name: use letters, digits and dashes')\n        with self._lock:\n            if name in self._entities:\n                raise ValueError(f'{name} is already registered on {self.address}')\n            self._entities[name] = entity\n        return f'{self.address}/{name}'\n\n    def _deliver(self, frame):\n        try:\n            kind, to, source, ident, payload = _frame_decode(frame)\n        except WireError:\n            return\n        if kind == 'reply':\n            with self._lock:\n                slot = self._pending.pop(ident, None)\n            if slot is not None:\n                slot.append(payload)\n                slot.event.set()\n            return\n        entity = self._entities.get(to)\n        if entity is None:\n            if ident:\n                self._reply(source, ident, 3, f'nothing is registered as {to} on {self.address}')\n            return\n        if ident:\n            key = (source, ident)\n            with self._lock:\n                if key in self._seen:\n                    answer = self._seen[key]\n                    if answer is not None:\n                        threading.Thread(target=self._send, args=(source + '/', 'reply', answer, ident), daemon=True).start()\n                    return\n                self._seen[key] = None\n                if len(self._seen) > 10000:\n                    for old in list(self._seen)[:5000]:\n                        del self._seen[old]\n        # Handled off the transport's thread, so a slow handler does not\n        # hold up other frames.\n        threading.Thread(target=entity._receive, args=(self, kind, source, ident, payload), daemon=True).start()\n\n    def _reply(self, source, ident, status, body):\n        payload = bytes([status]) + (body if isinstance(body, bytes) else body.encode('utf-8'))\n        with self._lock:\n            if (source, ident) in self._seen:\n                self._seen[(source, ident)] = payload\n        try:\n            self._send(source + '/', 'reply', payload, ident)\n        except Unreachable:\n            pass\n\n    def _request(self, address, kind, payload, timeout):\n        \"\"\"Sends a request and waits for its reply: (status, body).\"\"\"\n        ident = self._next_id()\n        slot = _Reply()\n        with self._lock:\n            self._pending[ident] = slot\n        import time\n        # Sent again until answered: the receiver runs it once.\n        give_up = time.monotonic() + timeout\n        while True:\n            try:\n                self._send(address, kind, payload, ident)\n            except Unreachable:\n                pass\n            if slot.event.wait(min(0.1, max(0.0, give_up - time.monotonic()))):\n                return slot[0][0], slot[0][1:]\n            if time.monotonic() >= give_up:\n                with self._lock:\n                    self._pending.pop(ident, None)\n                raise Unreachable(f'{address} did not answer within {timeout}s')\n\n    # Mailboxes: values of one type sent by any node.\n    def mailbox(self, name, descriptor, values=_NO_TYPES):\n        \"\"\"A local Mailbox that other nodes send to at <address>/name.\"\"\"\n        box = Mailbox()\n        self._register(name, _MailEntity(box, values, descriptor))\n        return box\n\n    def remote_mailbox(self, address, descriptor, values=_NO_TYPES, timeout=5.0):\n        return RemoteMailbox(self, address, descriptor, values, timeout)\n\n    # Actors: calls by message name, with each message's types.\n    def serve(self, name, actor, handlers, values=_NO_TYPES):\n        \"\"\"Lets other nodes call actor at <address>/name. handlers maps a\n        message name to (handler(state, *args) -> (reply, state), argument\n        descriptors, reply descriptor).\"\"\"\n        return self._register(name, _ActorEntity(actor, handlers, values))\n\n    def remote_actor(self, address, signatures, values=_NO_TYPES, timeout=5.0):\n        \"\"\"A proxy calling the actor at address; signatures maps a message\n        name to (argument descriptors, reply descriptor).\"\"\"\n        return RemoteActor(self, address, signatures, values, timeout)\n\n    # Definitions, by content hash.\n    def serve_definitions(self, table, values=_NO_TYPES, name='definitions'):\n        \"\"\"Lets other nodes evaluate definitions: table maps a content hash\n        to (function, argument descriptors, result descriptor).\"\"\"\n        return self._register(name, _DefinitionEntity(table, values))\n\n    def evaluate(self, node, digest, args, arguments, result, values=_NO_TYPES, timeout=5.0, name='definitions'):\n        \"\"\"Evaluates the definition with this content hash on another node.\"\"\"\n        payload = bytearray()\n        _wire_put(_NO_TYPES, ['text'], digest, payload)\n        for d, v in zip(arguments, args):\n            _wire_put(values, d, v, payload)\n        status, body = self._request(f'{node}/{name}', 'eval', bytes(payload), timeout)\n        return _reply_value(status, body, values, result)\n\n    # Channels: one side here, the other on any node.\n    def listen(self, name, steps, values=_NO_TYPES, deadline=5.0):\n        \"\"\"The first end of a channel named name here; its other end is\n        dial(...)ed from any node. steps: (sends, descriptor) per step, from\n        this end's side.\"\"\"\n        endpoint = _NetEndpoint(self, steps, values, 0, deadline)\n        endpoint.address = self._register(name, endpoint)\n        return endpoint\n\n    def dial(self, address, steps, values=_NO_TYPES, deadline=5.0):\n        \"\"\"The second end of the channel listening at address. steps are from\n        this end's side.\"\"\"\n        endpoint = _NetEndpoint(self, steps, values, 1, deadline)\n        endpoint.address = self._register(f'end-{self._next_id()}', endpoint)\n        endpoint._connect(address)\n        return endpoint\n\n    def take(self, address, steps, values=_NO_TYPES, deadline=5.0):\n        \"\"\"Takes over a channel end another node moves here: address is\n        <old address>?take=<token>, as that node offered it. Returns once the\n        end's state has arrived and its peer has been told (or after the\n        deadline; the old node then forwards to the end).\"\"\"\n        endpoint = _NetEndpoint(self, steps, values, 0, deadline)\n        endpoint.address = self._register(f'end-{self._next_id()}', endpoint)\n        endpoint._take_over(address)\n        return endpoint\n\n\ndef _reply_value(status, body, values, d):\n    if status == 0:\n        return wire_decode(values, d, body)\n    message = body.decode('utf-8', 'replace')\n    if status == 1:\n        raise ActorCrashed(message)\n    if status == 2:\n        raise ActorStopped(message)\n    raise Unreachable(message)\n\n\nclass _MailEntity:\n    def __init__(self, box, values, descriptor):\n        self.box, self.values, self.descriptor = box, values, descriptor\n\n    def _receive(self, node, kind, source, ident, payload):\n        if kind == 'mail':\n            try:\n                self.box.send(wire_decode(self.values, self.descriptor, payload))\n                status, body = 0, b''\n            except WireError as error:\n                status, body = 3, f'not a message of this mailbox: {error}'\n            except ActorStopped as error:\n                status, body = 2, str(error)\n            if ident:\n                node._reply(source, ident, status, body)\n\n\nclass RemoteMailbox:\n    \"\"\"Sends to a mailbox on another node. A send waits until the mailbox\n    has the message (resending a lost one; the mailbox takes it once), and\n    raises Unreachable after the timeout, or ActorStopped if it is closed.\"\"\"\n\n    def __init__(self, node, address, descriptor, values, timeout=5.0):\n        self._node, self.address, self._descriptor, self._values = node, address, descriptor, values\n        self.timeout = timeout\n\n    def send(self, value):\n        status, body = self._node._request(self.address, 'mail', wire_encode(self._values, self._descriptor, value), self.timeout)\n        if status != 0:\n            _reply_value(status, body, self._values, ['unit'])\n\n\nclass _ActorEntity:\n    def __init__(self, actor, handlers, values):\n        self.actor, self.handlers, self.values = actor, handlers, values\n\n    def _receive(self, node, kind, source, ident, payload):\n        if kind != 'call':\n            return\n        try:\n            message, pos = _wire_get(_NO_TYPES, ['text'], payload, 0)\n            handler, arguments, reply = self.handlers[message]\n            args = []\n            for d in arguments:\n                v, pos = _wire_get(self.values, d, payload, pos)\n                args.append(v)\n            if pos != len(payload):\n                raise WireError('extra bytes after the arguments')\n        except (WireError, KeyError) as error:\n            node._reply(source, ident, 3, f'not a message this actor handles: {error}')\n            return\n        try:\n            result = self.actor.call(lambda s: handler(s, *args))\n            node._reply(source, ident, 0, wire_encode(self.values, reply, result))\n        except ActorCrashed as error:\n            node._reply(source, ident, 1, str(error))\n        except ActorStopped as error:\n            node._reply(source, ident, 2, str(error))\n\n\nclass RemoteActor:\n    \"\"\"Calls an actor on another node: call(message, *args) sends the\n    message and waits for the reply, raising Unreachable after the timeout,\n    or what the actor's call raised (ActorCrashed, ActorStopped).\"\"\"\n\n    def __init__(self, node, address, signatures, values, timeout):\n        self._node, self.address = node, address\n        self._signatures, self._values, self.timeout = signatures, values, timeout\n\n    def call(self, message, *args):\n        arguments, reply = self._signatures[message]\n        payload = bytearray()\n        _wire_put(_NO_TYPES, ['text'], message, payload)\n        for d, v in zip(arguments, args):\n            _wire_put(self._values, d, v, payload)\n        status, body = self._node._request(self.address, 'call', bytes(payload), self.timeout)\n        return _reply_value(status, body, self._values, reply)\n\n\nclass _DefinitionEntity:\n    def __init__(self, table, values):\n        self.table, self.values = table, values\n\n    def _receive(self, node, kind, source, ident, payload):\n        if kind != 'eval':\n            return\n        try:\n            digest, pos = _wire_get(_NO_TYPES, ['text'], payload, 0)\n            function, arguments, result = self.table[digest]\n            args = []\n            for d in arguments:\n                v, pos = _wire_get(self.values, d, payload, pos)\n                args.append(v)\n        except (WireError, KeyError):\n            node._reply(source, ident, 3, 'this node has no definition with that content hash')\n            return\n        try:\n            node._reply(source, ident, 0, wire_encode(self.values, result, function(*args)))\n        except Exception as error:  # noqa: BLE001 - reported to the caller\n            node._reply(source, ident, 1, f'{type(error).__name__}: {error}')\n\n\n_SEQ = ['int', 'Int64', None, None]\n_TEXT = ['text']\n_BYTES = ['bytes']\n\n\ndef _put_texts(out, texts):\n    _put_varint(out, len(texts))\n    for t in texts:\n        _wire_put(_NO_TYPES, _TEXT, t, out)\n\n\ndef _get_texts(buf, pos):\n    count, pos = _get_varint(buf, pos)\n    texts = []\n    for _ in range(count):\n        t, pos = _wire_get(_NO_TYPES, _TEXT, buf, pos)\n        texts.append(t)\n    return texts, pos\n\n\ndef _put_numbered(out, items):\n    _put_varint(out, len(items))\n    for seq, body in items:\n        _wire_put(_NO_TYPES, _SEQ, seq, out)\n        _wire_put(_NO_TYPES, _BYTES, body, out)\n\n\ndef _get_numbered(buf, pos):\n    count, pos = _get_varint(buf, pos)\n    items = []\n    for _ in range(count):\n        seq, pos = _wire_get(_NO_TYPES, _SEQ, buf, pos)\n        body, pos = _wire_get(_NO_TYPES, _BYTES, buf, pos)\n        items.append((seq, bytes(body)))\n    return items, pos\n\n\nclass _NetEndpoint:\n    \"\"\"One end of a channel between nodes, with the Channel interface\n    (send(side, value), receive(side)). Each value travels in a numbered\n    frame that is sent again until acknowledged, so loss, duplication and\n    reordering are repaired; a peer silent for deadline seconds is treated\n    as failed (PeerFailed). Order is kept within the channel.\n\n    An unused end can move to another node: offer() gives the address the\n    new node takes it over from (<address>?take=<token>). On a take frame\n    with that token, this end hands its state over (a state frame) and from\n    then on forwards every frame it gets to the new end; the new end tells\n    the peer (a moved frame) so the peer sends to it directly.\"\"\"\n\n    def __init__(self, node, steps, values, side, deadline):\n        import queue\n        self._node, self._steps, self._values, self.side = node, steps, values, side\n        self._deadline = deadline\n        self.address = None\n        self._peer = None\n        self._peer_known = threading.Event()\n        self._out = 0\n        self._unacked = {}\n        self._expected = 0\n        self._early = {}\n        self._inbox = queue.Queue()\n        self._lock = threading.Lock()\n        self._step = 0\n        self._gone = False\n        self._failure = None\n        # Moving: the addresses this end had before (oldest first), the\n        # token a taker must show, where the end went and the state frame\n        # it was given, and, on the new node, the takeover in progress.\n        self._history = []\n        self._token = None\n        self._moved_to = None\n        self._state = None\n        self._taking = None\n        self._taken = threading.Event()\n        self._announcing = False\n        self._announced_at = 0.0\n        self._confirmed = threading.Event()\n        threading.Thread(target=self._resend, daemon=True).start()\n\n    def _connect(self, address):\n        with self._lock:\n            self._peer = address\n        self._peer_known.set()\n        self._transmit(-1, b'hello')\n\n    def _frame(self, seq, body):\n        payload = bytearray()\n        _wire_put(_NO_TYPES, _SEQ, seq, payload)\n        _wire_put(_NO_TYPES, _TEXT, self.address, payload)\n        payload.extend(body)\n        return bytes(payload)\n\n    def _transmit(self, seq, body):\n        \"\"\"Sends a numbered frame (seq -1 is the hello) until it is acked.\"\"\"\n        import time\n        payload = self._frame(seq, body)\n        with self._lock:\n            self._unacked[seq] = [payload, time.monotonic(), time.monotonic(), body]\n            peer = self._peer\n        if peer is not None:\n            try:\n                self._node._send(peer, 'chan', payload)\n            except Unreachable:\n                pass\n\n    def _resend(self):\n        import time\n        while not self._gone and not self._node.closed:\n            time.sleep(0.02)\n            now = time.monotonic()\n            with self._lock:\n                if self._moved_to is not None:\n                    return\n                if self._taking is not None and not self._taken.is_set():\n                    continue\n                peer = self._peer\n                due = [(seq, entry) for seq, entry in self._unacked.items() if now - entry[2] > 0.05]\n                stale = any(now - entry[1] > self._deadline for _, entry in due)\n                announce = (self._announcing and peer is not None and not self._confirmed.is_set()\n                            and now - self._announced_at > 0.05)\n                if announce:\n                    self._announced_at = now\n                    moved = bytearray()\n                    _put_texts(moved, self._history)\n                    _wire_put(_NO_TYPES, _TEXT, self.address, moved)\n            if stale:\n                self._fail('the other end did not answer in time (unreachable)')\n                return\n            if peer is None:\n                continue\n            if announce:\n                try:\n                    self._node._send(peer, 'moved', bytes(moved))\n                except Unreachable:\n                    pass\n            for seq, entry in due:\n                entry[2] = now\n                try:\n                    self._node._send(peer, 'chan', entry[0])\n                except Unreachable:\n                    pass\n\n    def _fail(self, reason):\n        with self._lock:\n            if self._gone:\n                return\n            self._gone = True\n            self._failure = reason\n            self._unacked.clear()\n            self._inbox.put((_ABANDONED, reason))\n\n    def _receive(self, node, kind, source, ident, payload):\n        if kind == 'take':\n            self._give(payload)\n            return\n        with self._lock:\n            forward = self._moved_to\n            waiting = self._taking is not None and not self._taken.is_set()\n        if forward is not None:\n            self._node._forward(forward, kind, source, ident, payload)\n            return\n        if waiting:\n            # Until the state arrives, frames are dropped: their senders send\n            # them again.\n            if kind == 'state':\n                self._install(payload)\n            return\n        if kind == 'ack':\n            seq, _ = _wire_get(_NO_TYPES, _SEQ, payload, 0)\n            with self._lock:\n                self._unacked.pop(seq, None)\n            return\n        if kind == 'moved':\n            self._peer_moved(payload)\n            return\n        if kind == 'moved-ack':\n            to, _ = _wire_get(_NO_TYPES, _TEXT, payload, 0)\n            if to == self.address:\n                self._confirmed.set()\n            return\n        if kind != 'chan':\n            return\n        seq, pos = _wire_get(_NO_TYPES, _SEQ, payload, 0)\n        sender, pos = _wire_get(_NO_TYPES, _TEXT, payload, pos)\n        body = payload[pos:]\n        with self._lock:\n            forward = self._moved_to\n            if forward is None:\n                if seq == -1:\n                    if self._peer is None:\n                        self._peer = sender\n                    self._peer_known.set()\n                elif seq >= self._expected and seq not in self._early:\n                    self._early[seq] = body\n                    while self._expected in self._early:\n                        self._inbox.put((None, self._early.pop(self._expected)))\n                        self._expected += 1\n        if forward is not None:\n            # Moved meanwhile: the new end acknowledges it.\n            self._node._forward(forward, kind, source, ident, payload)\n            return\n        ack = bytearray()\n        _wire_put(_NO_TYPES, _SEQ, seq, ack)\n        try:\n            self._node._send(sender, 'ack', bytes(ack))\n        except Unreachable:\n            pass\n\n    # Moving an end to another node.\n    def _offer(self):\n        \"\"\"The address another node takes this unused end over from.\"\"\"\n        with self._lock:\n            if self._token is None:\n                self._token = secure_token()\n            return f'{self.address}?take={self._token}'\n\n    def _give(self, payload):\n        \"\"\"A take frame: hands the state over once, to the first taker with\n        the token, and answers that taker's repeats with the same state.\"\"\"\n        try:\n            token, pos = _wire_get(_NO_TYPES, _TEXT, payload, 0)\n            taker, _ = _wire_get(_NO_TYPES, _TEXT, payload, pos)\n        except WireError:\n            return\n        with self._lock:\n            if self._token is None or token != self._token:\n                return\n            if self._moved_to is None:\n                received = [body for marker, body in list(self._inbox.queue) if marker is None]\n                state = bytearray()\n                _wire_put(_NO_TYPES, _TEXT, token, state)\n                _wire_put(_NO_TYPES, _TEXT, self._failure or '', state)\n                _wire_put(_NO_TYPES, _TEXT, self._peer or '', state)\n                _put_texts(state, self._history + [self.address])\n                _wire_put(_NO_TYPES, _SEQ, self._out, state)\n                _wire_put(_NO_TYPES, _SEQ, self._expected, state)\n                _put_numbered(state, sorted((seq, entry[3]) for seq, entry in self._unacked.items()))\n                _put_numbered(state, sorted(self._early.items()))\n                _put_varint(state, len(received))\n                for body in received:\n                    _wire_put(_NO_TYPES, _BYTES, body, state)\n                self._moved_to, self._state = taker, bytes(state)\n                self._unacked.clear()\n                self._early.clear()\n            elif self._moved_to != taker:\n                return\n            state = self._state\n        try:\n            self._node._send(taker, 'state', state)\n        except Unreachable:\n            pass\n\n    def _take_over(self, address):\n        \"\"\"Takes over the end offered at address (<old address>?take=<token>):\n        asks for its state until it comes, then tells the peer where the end\n        is now. Returns once the peer knows, or after the deadline (the old\n        node then keeps forwarding to this end, as a relay would).\"\"\"\n        import time\n        old, _, query = address.partition('?')\n        token = query[len('take='):]\n        with self._lock:\n            self._taking = (old, token)\n        request = bytearray()\n        _wire_put(_NO_TYPES, _TEXT, token, request)\n        _wire_put(_NO_TYPES, _TEXT, self.address, request)\n        give_up = time.monotonic() + self._deadline\n        while not self._taken.is_set():\n            try:\n                self._node._send(old, 'take', bytes(request))\n            except Unreachable:\n                pass\n            if self._taken.wait(0.05):\n                break\n            if time.monotonic() >= give_up:\n                with self._lock:\n                    self._taking = None\n                self._fail('the node the end came from did not hand it over in time (unreachable)')\n                return\n        self._confirmed.wait(max(0.0, give_up - time.monotonic()))\n\n    def _install(self, payload):\n        import time\n        try:\n            token, pos = _wire_get(_NO_TYPES, _TEXT, payload, 0)\n            failure, pos = _wire_get(_NO_TYPES, _TEXT, payload, pos)\n            peer, pos = _wire_get(_NO_TYPES, _TEXT, payload, pos)\n            history, pos = _get_texts(payload, pos)\n            out, pos = _wire_get(_NO_TYPES, _SEQ, payload, pos)\n            expected, pos = _wire_get(_NO_TYPES, _SEQ, payload, pos)\n            unacked, pos = _get_numbered(payload, pos)\n            early, pos = _get_numbered(payload, pos)\n            count, pos = _get_varint(payload, pos)\n            received = []\n            for _ in range(count):\n                body, pos = _wire_get(_NO_TYPES, _BYTES, payload, pos)\n                received.append(bytes(body))\n        except WireError:\n            return\n        now = time.monotonic()\n        with self._lock:\n            if self._taking is None or token != self._taking[1] or self._taken.is_set():\n                return\n            self._peer = peer or None\n            self._history = history\n            self._out, self._expected = out, expected\n            # Sent again from here at once, under this end's address.\n            self._unacked = {seq: [self._frame(seq, body), now, 0.0, body] for seq, body in unacked}\n            self._early = dict(early)\n            for body in received:\n                self._inbox.put((None, body))\n            self._announcing = True\n            self._taken.set()\n        if peer:\n            self._peer_known.set()\n        if failure:\n            self._fail(failure)\n\n    def _peer_moved(self, payload):\n        \"\"\"The peer moved: from now on send to its new address.\"\"\"\n        try:\n            history, pos = _get_texts(payload, 0)\n            to, _ = _wire_get(_NO_TYPES, _TEXT, payload, pos)\n        except WireError:\n            return\n        with self._lock:\n            if self._peer is None or self._peer in history:\n                self._peer = to\n            known = self._peer == to\n        if known:\n            answer = bytearray()\n            _wire_put(_NO_TYPES, _TEXT, to, answer)\n            try:\n                self._node._send(to, 'moved-ack', bytes(answer))\n            except Unreachable:\n                pass\n\n    def _step_descriptor(self, sends):\n        if self._step >= len(self._steps):\n            raise SessionError('this channel\\'s protocol has ended')\n        step_sends, d = self._steps[self._step]\n        if step_sends != sends:\n            raise SessionError('this step ' + ('receives' if step_sends == 0 or not step_sends else 'sends'))\n        self._step += 1\n        return d\n\n    def send(self, side, value):\n        if self._gone:\n            raise PeerFailed('the other end has failed')\n        d = self._step_descriptor(True)\n        body = bytearray([0])\n        _wire_put(self._values, d, value, body)\n        with self._lock:\n            seq = self._out\n            self._out += 1\n        self._transmit(seq, bytes(body))\n\n    def receive(self, side, timeout=None):\n        import queue\n        d = self._step_descriptor(False)\n        try:\n            marker, body = self._inbox.get(timeout=timeout)\n        except queue.Empty:\n            raise TimeoutError('no message arrived in time') from None\n        if marker is _ABANDONED:\n            self._inbox.put((marker, body))\n            raise PeerFailed(body)\n        if body[0] == 1:\n            self._fail('the other end gave up the conversation')\n            raise PeerFailed('the other end gave up the conversation (its process failed or abandoned it)')\n        return wire_decode(self._values, d, bytes(body[1:]))\n\n    def abandon(self, side):\n        \"\"\"Gives up: the other end's receives fail after what was sent.\"\"\"\n        with self._lock:\n            seq = self._out\n            self._out += 1\n        self._transmit(seq, b'\\x01')\n\n\nclass EndPart:\n    \"\"\"A step that sends another protocol's first end: start() is that end's\n    start class, and wire() that protocol's (steps, parts) from it.\"\"\"\n\n    def __init__(self, start, wire):\n        self.start, self.wire = start, wire\n\n\nclass NativeChannel:\n    \"\"\"A network channel end seen through native values: each step's part\n    converts its value with the schema (None needs no conversion), or, for\n    an EndPart, sends a channel end and receives one. A network end moves\n    to the receiving node (the value is <address>?take=<token>); a local\n    end stays here behind a relay (the value is the relay's address).\"\"\"\n\n    def __init__(self, endpoint, parts, schema=None):\n        self._endpoint, self._parts, self._schema = endpoint, parts, schema\n        self._step = 0\n        self.address = endpoint.address\n\n    def _part(self):\n        part = self._parts[self._step] if self._step < len(self._parts) else None\n        self._step += 1\n        return part\n\n    def send(self, side, value):\n        part = self._part()\n        if isinstance(part, EndPart):\n            value = _offer_end(self._endpoint._node, self._endpoint._values, value, part, self._schema)\n        elif part is not None:\n            value = self._schema.from_native(part, value)\n        self._endpoint.send(side, value)\n\n    def receive(self, side):\n        part = self._part()\n        value = self._endpoint.receive(side)\n        if isinstance(part, EndPart):\n            steps, parts = part.wire()\n            node = self._endpoint._node\n            if '?take=' in value:\n                endpoint = node.take(value, steps, self._endpoint._values)\n            else:\n                endpoint = node.dial(value, steps, self._endpoint._values)\n            return part.start()(NativeChannel(endpoint, parts, self._schema), 0)\n        return value if part is None else self._schema.to_native(part, value)\n\n    def abandon(self, side):\n        self._endpoint.abandon(side)\n\n\ndef _offer_end(node, values, end, part, schema):\n    \"\"\"The text that gives an unused channel end to another node. An end\n    that is itself between nodes moves there; a local end stays here and a\n    relay on node carries its conversation.\"\"\"\n    channel, side = end._take(), end._side\n    if isinstance(channel, NativeChannel) and channel._step == 0:\n        return channel._endpoint._offer()\n    return _relay_end(node, values, channel, side, part, schema)\n\n\ndef _relay_end(node, values, channel, side, part, schema):\n    \"\"\"Offers a local channel end to another node: a relay on node listens\n    for the receiver and passes each step between it and the end, which\n    stays here. Returns the relay's address. A failure on either side gives\n    up the other.\"\"\"\n    steps, parts = part.wire()\n    relay = node.listen(f'relay-{node._next_id()}', [(not s, d) for s, d in steps], values)\n    relayed = NativeChannel(relay, parts, schema)\n\n    def pump():\n        try:\n            for sends, _ in steps:\n                if sends:\n                    channel.send(side, relayed.receive(0))\n                else:\n                    relayed.send(0, channel.receive(side))\n        except (PeerFailed, SessionError, Unreachable, TimeoutError, ActorStopped):\n            for give_up in (lambda: channel.abandon(side), lambda: relay.abandon(0)):\n                try:\n                    give_up()\n                except Exception:  # noqa: BLE001 - already failed\n                    pass\n    threading.Thread(target=pump, daemon=True).start()\n    return relay.address\n"
runtimeSource "python-schema" = "\"\"\"Typed data validation and native bridges for Python, with no test-framework\ndependency.\n\nGenerated data types are described once, as Core schemas, and every value\ncrossing between a law and native code is validated against them, so an adapter\ncannot hand a law a value outside its declared type.\nref:DEC-typed-core-boundary ref:DEC-native-bindings-typed-identity\n\"\"\"\n\nfrom collections import deque\nfrom dataclasses import dataclass, replace\n\nimport lawspec_runtime as ls\n\n\n@dataclass(frozen=True)\nclass Parameter:\n    index: int\n\n\n@dataclass(frozen=True)\nclass Named:\n    name: str\n    arguments: tuple = ()\n\n    def __post_init__(self):\n        object.__setattr__(self, \"arguments\", tuple(self.arguments))\n\n\n@dataclass(frozen=True)\nclass Field:\n    name: str\n    type: object\n\n\ndef parse_index_term(tokens, at):\n    \"\"\"Parse a prefix index term: c<n>, f<field>[.<index>] or an operator.\"\"\"\n    token = tokens[at]\n    if token[0] == 'c':\n        return ('c', int(token[1:])), at + 1\n    if token[0] == 'f':\n        position, _, index = token[1:].partition('.')\n        return ('f', int(position), int(index or 0)), at + 1\n    if token in ('+', '-', '*', 'div', 'mod', '^'):\n        left, at = parse_index_term(tokens, at + 1)\n        right, at = parse_index_term(tokens, at)\n        return (token, left, right), at\n    raise ValueError('malformed index term')\n\n\ndef eval_index_term(term, field):\n    \"\"\"Natural index arithmetic; None when an operation has no value.\"\"\"\n    if term[0] == 'c':\n        return term[1]\n    if term[0] == 'f':\n        return field(term[1], term[2])\n    x = eval_index_term(term[1], field)\n    y = eval_index_term(term[2], field)\n    if x is None or y is None:\n        return None\n    if term[0] == '+':\n        return x + y\n    if term[0] == '-':\n        return x - y if x >= y else None\n    if term[0] == '*':\n        return x * y\n    if term[0] == 'div':\n        return x // y if y > 0 else None\n    if term[0] == 'mod':\n        return x % y if y > 0 else None\n    return x ** y if 0 <= y <= 64 else None\n\n\n@dataclass(frozen=True)\nclass Constructor:\n    tag: str\n    fields: tuple\n    native: type\n    predicates: tuple = ()\n    native_fields: tuple | None = None\n    indices: tuple = ()\n    # A GADT constructor fixes parameters to patterns; its existentials are\n    # the parameters numbered after the definition's own.\n    refinements: tuple = ()\n    existentials: int = 0\n    # Existentials only a value determines (parameter numbers); their types\n    # travel as the trailing Text witness fields.\n    witnesses: tuple = ()\n\n    def __post_init__(self):\n        object.__setattr__(self, \"fields\", tuple(self.fields))\n        object.__setattr__(self, \"predicates\", tuple(self.predicates))\n        object.__setattr__(self, \"indices\", tuple(self.indices))\n        object.__setattr__(self, \"refinements\", tuple(\n            (index, pattern) for index, pattern in self.refinements))\n        if self.native_fields is not None:\n            object.__setattr__(\n                self, \"native_fields\", tuple(self.native_fields))\n\n\n@dataclass(frozen=True)\nclass Definition:\n    name: str\n    parameters: int\n    constructors: tuple\n    # A handle has no constructors: its values are adapters' own objects,\n    # passed along unopened and equal only to themselves.\n    handle: bool = False\n\n    def __post_init__(self):\n        object.__setattr__(self, \"constructors\", tuple(self.constructors))\n\n\nclass Maybe[T]:\n    \"\"\"Distinct Nothing and Just states, including nested absence.\n\n    Python's None cannot tell Nothing from Just(None), so Maybe is its own\n    type with nested absence kept distinct. ref:DEC-algebraic-maybe-either\"\"\"\n\n    __slots__ = ()\n\n    def __new__(cls, *args, **kwargs):\n        if cls is Maybe:\n            raise TypeError(\"construct Nothing or Just\")\n        return object.__new__(cls)\n\n\n@dataclass(frozen=True, slots=True, eq=False)\nclass Nothing[T](Maybe[T]):\n    pass\n\n\n@dataclass(frozen=True, slots=True, eq=False)\nclass Just[T](Maybe[T]):\n    value: T\n\n\nclass Either[L, R]:\n    \"\"\"Base for distinct Left and Right alternatives.\n\n    Either is a real sum rather than an exception, so a law can state what\n    happens on each side. ref:DEC-algebraic-maybe-either\"\"\"\n\n    __slots__ = ()\n\n    def __new__(cls, *args, **kwargs):\n        if cls is Either:\n            raise TypeError(\"construct Left or Right\")\n        return object.__new__(cls)\n\n\n@dataclass(frozen=True, slots=True, eq=False)\nclass Left[L, R](Either[L, R]):\n    value: L\n\n\n@dataclass(frozen=True, slots=True, eq=False)\nclass Right[L, R](Either[L, R]):\n    value: R\n\n\n# Built-in collections and their single constructors. Natively a Set is a\n# frozenset and a KeyVal a dict when Python compares their elements or keys by\n# value, and otherwise a tuple of items or of (key, value) pairs in canonical\n# order; Queue, Stack and Deque are deques (a Stack's top last, so append\n# and pop use it).\n_COLLECTIONS_UNIT = \"lawspec.collections::type::\"\nCOLLECTIONS = {\n    _COLLECTIONS_UNIT + name: _COLLECTIONS_UNIT + name + \"::\" + tag\n    for name, tag in ((\"Set\", \"SetItems\"), (\"KeyVal\", \"KeyValEntries\"),\n                      (\"Queue\", \"QueueItems\"), (\"Stack\", \"StackItems\"),\n                      (\"Deque\", \"DequeItems\"))}\n_ENTRY = _COLLECTIONS_UNIT + \"Entry::Entry\"\n_HASHABLE = frozenset(\n    [\"Bool\", \"Char\", \"Text\", \"Bytes\", \"Decimal\", \"Rational\", \"BigInt\",\n     \"BigUInt\", \"Integer\", \"Natural\", \"CodePoint\", \"CodeUnit16\", \"Unit\"] +\n    [f\"{sign}Int{width}\" for sign in (\"\", \"U\")\n     for width in (8, 16, 32, 64, 128, \"Size\")] + [\"UIntPtr\"])\n\n\n# A Duration, whole microseconds from 0 to about 146 years, is natively a\n# timedelta, which holds that range exactly.\n_DURATION = \"lawspec.time::type::Duration\"\n_DURATION_TAG = _DURATION + \"::Duration\"\n_DURATION_LIMIT = 4611686018426999\n\n\ndef hashable(reference):\n    \"\"\"Whether Python compares this type's natives by value.\"\"\"\n    return isinstance(reference, Named) and not reference.arguments and (\n        reference.name in _HASHABLE)\n\n\ndef canonical_items(items, key):\n    \"\"\"Sorted by key, keeping the last of equal keys.\"\"\"\n    from functools import cmp_to_key\n    ordered = sorted(items, key=cmp_to_key(\n        lambda a, b: ls.compare_values(key(a), key(b))))\n    result = []\n    for item in ordered:\n        if result and ls.compare_values(key(result[-1]), key(item)) == 0:\n            result[-1] = item\n        else:\n            result.append(item)\n    return result\n\n\ndef witness_key(reference):\n    \"\"\"Spell a type as its name, or a parenthesized application.\"\"\"\n    if not reference.arguments:\n        return reference.name\n    return \"(\" + \" \".join(\n        [reference.name] + [witness_key(a) for a in reference.arguments]) + \")\"\n\n\ndef parse_witness(text):\n    \"\"\"Read a witness key back into a type reference.\"\"\"\n    tokens = text.replace(\"(\", \" ( \").replace(\")\", \" ) \").split()\n\n    def read(at):\n        if tokens[at] == \"(\":\n            name, at = tokens[at + 1], at + 2\n            arguments = []\n            while tokens[at] != \")\":\n                child, at = read(at)\n                arguments.append(child)\n            return Named(name, tuple(arguments)), at + 1\n        return Named(tokens[at]), at + 1\n\n    if not tokens:\n        raise ValueError(\"empty type witness\")\n    reference, at = read(0)\n    if at != len(tokens):\n        raise ValueError(\"malformed type witness\")\n    return reference\n\n\ndef witnessed(constructor, fields):\n    \"\"\"Field types with witnessed existentials read from a value's fields.\"\"\"\n    if not constructor.witnesses:\n        return [field.type for field in constructor.fields]\n    known = {}\n    for index, text in zip(constructor.witnesses,\n                           fields[-len(constructor.witnesses):]):\n        if not isinstance(text, str):\n            raise TypeError(\"type witness must be text\")\n        known[index] = parse_witness(text)\n    arguments = [known.get(i) for i in range(max(known) + 1)]\n    return [substitute(field.type, arguments) for field in constructor.fields]\n\n\n# Types a generator may choose for an existential that only a value fixes.\nWITNESS_POOL = (Named(\"Bool\"), Named(\"Int32\"))\n\n\ndef witness_instances(constructor):\n    \"\"\"Each choice of witnesses: (declared fields at it, witness texts).\"\"\"\n    count = len(constructor.witnesses)\n    declared = constructor.fields[:len(constructor.fields) - count]\n    if not count:\n        return [(declared, ())]\n    from itertools import product\n    found = []\n    for choice in product(WITNESS_POOL, repeat=count):\n        known = dict(zip(constructor.witnesses, choice))\n        arguments = [known.get(i) for i in range(max(known) + 1)]\n        found.append((tuple(Field(field.name, substitute(field.type, arguments))\n                            for field in declared),\n                      tuple(witness_key(item) for item in choice)))\n    return found\n\n\ndef refine(constructor, arguments, parameters):\n    \"\"\"Arguments extended with the existentials a constructor's refinements\n    bind; None when the refinements do not match.\"\"\"\n    bound = {}\n\n    def match(pattern, actual):\n        if isinstance(pattern, Parameter):\n            if pattern.index < parameters:\n                return arguments[pattern.index] == actual\n            previous = bound.setdefault(pattern.index, actual)\n            return previous == actual\n        return (isinstance(actual, Named) and actual.name == pattern.name\n                and len(actual.arguments) == len(pattern.arguments)\n                and all(match(p, a) for p, a in\n                        zip(pattern.arguments, actual.arguments)))\n\n    for index, pattern in constructor.refinements:\n        if not match(pattern, arguments[index]):\n            return None\n    return tuple(arguments) + tuple(\n        bound.get(parameters + k) for k in range(constructor.existentials))\n\n\ndef substitute(reference, arguments):\n    if isinstance(reference, Parameter):\n        # A witnessed existential stays open until a value supplies it.\n        if (reference.index >= len(arguments)\n                or arguments[reference.index] is None):\n            return reference\n        return arguments[reference.index]\n    return Named(reference.name, tuple(\n        substitute(child, arguments) for child in reference.arguments))\n\n\ndef type_key(reference):\n    \"\"\"Produce a scalar-runtime key with concrete type arguments.\"\"\"\n    if not isinstance(reference, Named):\n        raise TypeError(\"type key requires an instantiated reference\")\n    arguments = tuple(map(type_key, reference.arguments))\n    if not arguments:\n        return reference.name\n    if reference.name == \"Either\" and len(arguments) == 2:\n        return f\"Either ({arguments[0]}) ({arguments[1]})\"\n    if len(arguments) == 1:\n        return reference.name + \" \" + arguments[0]\n\n    def pretty(value):\n        return value.name + \"\".join(\n            \" (\" + pretty(child) + \")\" for child in value.arguments)\n\n    return pretty(reference)\n\n\nclass RefinementViolation(ValueError):\n    \"\"\"A well-formed candidate failed a Boolean field predicate.\"\"\"\n\n\nclass Schema:\n    \"\"\"Validated Core metadata and native constructor classes.\n\n    One schema serves validation, construction, matching and conversion to\n    and from native classes, so these cannot disagree about a type.\n    ref:DEC-native-bindings-typed-identity\"\"\"\n\n    def __init__(self, definitions, primitives):\n        self._native_codecs = {}\n        self._canonical = None\n        self._definitions = {}\n        self._arity = dict.fromkeys(primitives, 0)\n        self._arity.update(List=1, Maybe=1, Either=2, Nullable=1, Optional=1)\n        for definition in definitions:\n            if definition.name in self._arity:\n                raise ValueError(\"duplicate type: \" + definition.name)\n            if (type(definition.parameters) is not int\n                    or definition.parameters < 0):\n                raise ValueError(\"invalid parameter count: \" + definition.name)\n            self._definitions[definition.name] = definition\n            self._arity[definition.name] = definition.parameters\n        tags, native_classes = set(), set()\n        for definition in self._definitions.values():\n            for constructor in definition.constructors:\n                if constructor.tag in tags:\n                    raise ValueError(\n                        \"duplicate constructor: \" + constructor.tag)\n                tags.add(constructor.tag)\n                if definition.name in COLLECTIONS or definition.name == _DURATION:\n                    continue  # Native collections and durations convert separately.\n                if not isinstance(constructor.native, type):\n                    raise TypeError(\"native constructor must be a class\")\n                if constructor.native in native_classes:\n                    raise ValueError(\"duplicate native constructor class\")\n                native_classes.add(constructor.native)\n                names = [field.name for field in constructor.fields]\n                if len(names) != len(set(names)):\n                    raise ValueError(\"duplicate constructor field\")\n                if constructor.native_fields is not None:\n                    native_names = constructor.native_fields\n                    if (len(native_names) != len(names)\n                            or len(set(native_names)) != len(native_names)\n                            or not all(isinstance(name, str)\n                                       and name.isidentifier()\n                                       for name in native_names)):\n                        raise ValueError(\"invalid native field mapping\")\n                scope = definition.parameters + constructor.existentials\n                for field in constructor.fields:\n                    self._check(field.type, scope)\n                for index, pattern in constructor.refinements:\n                    if not 0 <= index < definition.parameters:\n                        raise ValueError(\"invalid refined parameter\")\n                    self._check(pattern, scope)\n                if not all(callable(test) for test in constructor.predicates):\n                    raise TypeError(\"constructor predicate must be callable\")\n\n    def _check(self, reference, parameters=0):\n        if isinstance(reference, Parameter):\n            if (type(reference.index) is not int\n                    or not 0 <= reference.index < parameters):\n                raise ValueError(\"unbound schema parameter\")\n        elif isinstance(reference, Named):\n            if self._arity.get(reference.name) != len(reference.arguments):\n                raise ValueError(\n                    \"unknown type or wrong arity: \" + reference.name)\n            for child in reference.arguments:\n                self._check(child, parameters)\n        else:\n            raise TypeError(\"invalid schema type reference\")\n\n    def constructors(self, reference):\n        \"\"\"Return instantiated fields, or None for a built-in type.\"\"\"\n        self._check(reference)\n        definition = self._definitions.get(reference.name)\n        if definition is None:\n            return None\n        found = []\n        for constructor in definition.constructors:\n            # A GADT constructor whose refinements do not match these\n            # arguments builds no value of this type.\n            arguments = refine(constructor, reference.arguments,\n                               definition.parameters)\n            if arguments is None:\n                continue\n            found.append(Constructor(constructor.tag, tuple(\n                Field(field.name, substitute(field.type, arguments))\n                for field in constructor.fields), constructor.native,\n                constructor.predicates, constructor.native_fields,\n                constructor.indices, witnesses=constructor.witnesses))\n        return tuple(found)\n\n    def with_native_bindings(self, bindings, codecs=None):\n        \"\"\"Copy this schema with application classes and field names.\n\n        Keys are resolved constructor tags. Values pair a class with its\n        field names in LawSpec declaration order. Predicates retain their\n        logical fields and run against the same checked values. Optional codec\n        entries map a type identity to (native class, to_native, from_native).\n        Hooks use canonical values and receive directional child converters.\n        \"\"\"\n        bindings = dict(bindings)\n        hooks = dict(self._native_codecs)\n        hooks.update({} if codecs is None else codecs)\n        for name, hook in hooks.items():\n            definition = self._definitions.get(name)\n            if definition is None or not definition.constructors:\n                raise ValueError(\"unknown or empty native codec type: \" + name)\n            if (not isinstance(hook, tuple) or len(hook) != 3\n                    or not isinstance(hook[0], type)\n                    or not all(callable(part) for part in hook[1:])):\n                raise TypeError(\"invalid native codec: \" + name)\n            if any(item.tag in bindings for item in definition.constructors):\n                raise ValueError(\n                    \"codec conflicts with native mapping: \" + name)\n        definitions = []\n        for definition in self._definitions.values():\n            constructors = []\n            for constructor in definition.constructors:\n                mapped = bindings.pop(constructor.tag, None)\n                if mapped is not None:\n                    native, fields = mapped\n                    constructor = replace(\n                        constructor, native=native, native_fields=fields)\n                constructors.append(constructor)\n            definitions.append(replace(\n                definition, constructors=tuple(constructors)))\n        if bindings:\n            raise ValueError(\"unknown native constructor binding\")\n        primitives = set(self._arity) - set(self._definitions)\n        primitives -= {\"List\", \"Maybe\", \"Either\", \"Nullable\", \"Optional\"}\n        result = Schema(definitions, primitives)\n        result._canonical = self._canonical or self\n        result._native_codecs = hooks\n        return result\n\n    @staticmethod\n    def _bits(bits):\n        if type(bits) is not int or bits not in (32, 64):\n            raise ValueError(\"machineBits must be 32 or 64\")\n\n    def _check_indices(self, constructor, fields):\n        \"\"\"Check an indexed family's guards against its fields' indices.\"\"\"\n        for text in constructor.indices:\n            tokens = text.split()\n            if tokens[0] not in ('==', '>='):\n                continue\n            left, at = parse_index_term(tokens, 1)\n            right, _ = parse_index_term(tokens, at)\n\n            def field(position, index):\n                return self._index_of(constructor.fields[position].type,\n                                      fields[position], index)\n            x = eval_index_term(left, field)\n            y = eval_index_term(right, field)\n            if x is None or y is None or (\n                    x != y if tokens[0] == '==' else x < y):\n                raise RefinementViolation(\n                    f\"{constructor.tag}: index guard {text} failed\")\n\n    def _index_of(self, reference, value, index):\n        constructors = self.constructors(reference)\n        constructor = next((item for item in constructors or ()\n                            if item.tag == value.tag), None)\n        terms = [text for text in (constructor.indices if constructor else ())\n                 if text.split()[0] not in ('==', '>=')]\n        if index >= len(terms):\n            raise ValueError(\"no index for \" + reference.name)\n        term, _ = parse_index_term(terms[index].split(), 0)\n        return eval_index_term(term, lambda position, child: self._index_of(\n            constructor.fields[position].type, value.fields[position], child))\n\n    def validate(self, reference, value, bits=64, symbols=None):\n        \"\"\"Rejects a value outside the declared type, refinements included,\n        because native code may return anything its own type allows.\n        ref:DEC-portable-exact-arithmetic\"\"\"\n        self._check(reference)\n        self._bits(bits)\n        return self._walk(reference, value, bits, \"validate\",\n                          {} if symbols is None else symbols)\n\n    def all_payloads(self, reference, value, predicates, bits=64,\n                     symbols=None):\n        \"\"\"Check stored arguments, preserving parameter provenance.\"\"\"\n        self._check(reference)\n        structural = (\"List\", \"Maybe\", \"Either\", \"Nullable\", \"Optional\")\n        if (reference.name not in self._definitions\n                and reference.name not in structural):\n            raise ValueError(\"payload predicates require a data type\")\n        predicates = tuple(predicates)\n        if len(predicates) != len(reference.arguments):\n            raise ValueError(\"payload predicate arity mismatch\")\n        if not all(callable(predicate) for predicate in predicates):\n            raise TypeError(\"payload predicate must be callable\")\n        checked = self.validate(reference, value, bits, symbols)\n\n        def recipe(field, arguments):\n            if isinstance(field, Parameter):\n                return arguments[field.index]\n            children = tuple(recipe(child, arguments)\n                             for child in field.arguments)\n            return (Named(field.name, children)\n                    if any(child is not None for child in children)\n                    else None)\n\n        def contextual(plan, child, context):\n            try:\n                return walk(plan, child)\n            except (ValueError, TypeError, ArithmeticError) as error:\n                raise ValueError(f\"{context}: {error}\") from error\n\n        def walk(plan, child):\n            if plan is None:\n                return True\n            if isinstance(plan, Parameter):\n                result = predicates[plan.index](child)\n                if type(result) is not bool:\n                    raise TypeError(\"payload predicate did not produce Bool\")\n                return result\n            name, arguments = plan.name, plan.arguments\n            if name == \"List\":\n                return all(contextual(arguments[0], item, f\"List[{index}]\")\n                           for index, item in enumerate(child))\n            if name in (\"Nullable\", \"Optional\"):\n                return (not child.present or contextual(\n                    arguments[0], child.value, name + \".value\"))\n            if name == \"Maybe\":\n                return (child.tag == \"Maybe::Nothing\" or contextual(\n                    arguments[0], child.fields[0], \"Maybe::Just.value\"))\n            if name == \"Either\":\n                index = 0 if child.tag == \"Either::Left\" else 1\n                return contextual(arguments[index], child.fields[0],\n                                  child.tag + \".value\")\n            definition = self._definitions[name]\n            constructor = next(item for item in definition.constructors\n                               if item.tag == child.tag)\n            return all(contextual(recipe(field.type, arguments), item,\n                                  constructor.tag + \".\" + field.name)\n                       for field, item in zip(constructor.fields,\n                                              child.fields))\n\n        plan = Named(reference.name, tuple(\n            Parameter(index) for index in range(len(predicates))))\n        return walk(plan, checked)\n\n    def to_native(self, reference, value, bits=64, symbols=None):\n        \"\"\"Converts a checked value into the class the adapter declared, so\n        adapters work with their own types and never with LawSpec's.\n        ref:DEC-native-bindings-typed-identity\"\"\"\n        symbols = {} if symbols is None else symbols\n        checked = self.validate(reference, value, bits, symbols)\n        return self._walk(reference, checked, bits, \"native\", symbols)\n\n    def from_native(self, reference, value, bits=64, symbols=None):\n        \"\"\"Converts and checks a value an adapter returned, so a law never sees\n        a native value that is outside its domain.\n        ref:DEC-native-bindings-typed-identity\"\"\"\n        self._check(reference)\n        self._bits(bits)\n        symbols = {} if symbols is None else symbols\n        logical = self._walk(reference, value, bits, \"logical\", symbols)\n        return self.validate(reference, logical, bits, symbols)\n\n    def _codec_walk(self, reference, value, bits, mode, symbols):\n        native, to_native, from_native = self._native_codecs[reference.name]\n        canonical = self._canonical\n        direction = \"toNative\" if mode == \"native\" else \"fromNative\"\n\n        def converter(argument):\n            if mode == \"native\":\n                return lambda child: self.to_native(\n                    argument, canonical.from_native(\n                        argument, child, bits, symbols), bits, symbols)\n            return lambda child: canonical.to_native(\n                argument, self.from_native(\n                    argument, child, bits, symbols), bits, symbols)\n\n        try:\n            children = tuple(map(converter, reference.arguments))\n            if mode == \"native\":\n                logical = canonical.to_native(reference, value, bits, symbols)\n                result = to_native(logical, *children)\n                if not isinstance(result, native):\n                    raise TypeError(\"hook returned the wrong native type\")\n                return result\n            if not isinstance(value, native):\n                raise TypeError(\"expected the bound native type\")\n            result = from_native(value, *children)\n            return canonical.from_native(reference, result, bits, symbols)\n        except Exception as error:\n            raise ValueError(\n                f\"native codec {reference.name} {direction}: {error}\"\n            ) from error\n\n    def _collection_walk(self, reference, value, bits, mode, symbols):\n        short = reference.name[len(_COLLECTIONS_UNIT):]\n        arguments = reference.arguments\n        tag = COLLECTIONS[reference.name]\n\n        def walk(ty, child):\n            return self._walk(ty, child, bits, mode, symbols)\n        if mode == \"native\":\n            if not isinstance(value, ls.DataValue) or value.tag != tag:\n                raise TypeError(\"expected \" + short)\n            items = value.fields[0]\n            if short == \"KeyVal\":\n                pairs = [(walk(arguments[0], entry.fields[0]),\n                          walk(arguments[1], entry.fields[1]))\n                         for entry in items]\n                return dict(pairs) if hashable(arguments[0]) else tuple(pairs)\n            natives = [walk(arguments[0], item) for item in items]\n            if short == \"Set\":\n                return (frozenset(natives) if hashable(arguments[0])\n                        else tuple(natives))\n            return deque(reversed(natives) if short == \"Stack\" else natives)\n        if short == \"KeyVal\":\n            if isinstance(value, dict):\n                pairs = list(value.items())\n            elif isinstance(value, (tuple, list)):\n                pairs = list(value)\n            else:\n                raise TypeError(\"expected a dict or (key, value) pairs\")\n            entries = []\n            for pair in pairs:\n                if not isinstance(pair, tuple) or len(pair) != 2:\n                    raise TypeError(\"expected (key, value) pairs\")\n                entries.append(ls.DataValue(_ENTRY, (\n                    walk(arguments[0], pair[0]), walk(arguments[1], pair[1]))))\n            items = canonical_items(entries, lambda entry: entry.fields[0])\n        else:\n            if not isinstance(value, (frozenset, set, tuple, list, deque)):\n                raise TypeError(\"expected a collection for \" + short)\n            items = [walk(arguments[0], item) for item in value]\n            if short == \"Set\":\n                items = canonical_items(items, lambda item: item)\n            elif short == \"Stack\":\n                items.reverse()\n        return ls.DataValue(tag, (items,))\n\n    def _walk(self, reference, value, bits, mode, symbols):\n        definition = self._definitions.get(reference.name)\n        if definition is not None and definition.handle:\n            return ls.handle(value, reference.name)\n        if mode in (\"native\", \"logical\") and reference.name in self._native_codecs:\n            return self._codec_walk(reference, value, bits, mode, symbols)\n        if mode in (\"native\", \"logical\") and reference.name in COLLECTIONS:\n            return self._collection_walk(reference, value, bits, mode, symbols)\n        if mode in (\"native\", \"logical\") and reference.name == _DURATION:\n            return _duration_walk(value, mode)\n        constructors = self.constructors(reference)\n        if constructors is not None:\n            if mode == \"logical\":\n                constructor = next((item for item in constructors\n                                    if type(value) is item.native), None)\n                if constructor is None:\n                    raise TypeError(\"invalid native \" + reference.name)\n                names = (constructor.native_fields\n                         if constructor.native_fields is not None\n                         else tuple(field.name\n                                    for field in constructor.fields))\n                fields = tuple(getattr(value, name) for name in names)\n            else:\n                if not isinstance(value, ls.DataValue):\n                    raise TypeError(\"expected \" + reference.name)\n                constructor = next((item for item in constructors\n                                    if value.tag == item.tag), None)\n                if constructor is None:\n                    raise ValueError(\n                        \"foreign constructor for \" + reference.name)\n                fields = value.fields\n            if len(fields) != len(constructor.fields):\n                raise ValueError(\"wrong field count: \" + constructor.tag)\n            converted = []\n            types = witnessed(constructor, fields)\n            # A shallow check trusts fields, which were checked when built.\n            for field, field_type, child in zip(\n                    constructor.fields, types, fields):\n                if mode == \"shallow\":\n                    converted.append(child)\n                    continue\n                try:\n                    if field_type != field.type:\n                        self._check(field_type)\n                    converted.append(self._walk(\n                        field_type, child, bits, mode, symbols))\n                except (ValueError, TypeError, OverflowError) as error:\n                    error_type = (RefinementViolation if isinstance(\n                        error, RefinementViolation) else ValueError)\n                    raise error_type(\n                        constructor.tag + \".\" + field.name + \": \" + str(error)\n                    ) from error\n            if mode == \"native\":\n                if constructor.native_fields is not None:\n                    return constructor.native(**dict(zip(\n                        constructor.native_fields, converted)))\n                return constructor.native(*converted)\n            if mode in (\"validate\", \"shallow\"):\n                # Check shapes first. Failed conditions stop before\n                # predicates whose definedness depends on them.\n                for index, predicate in enumerate(constructor.predicates):\n                    context = (\n                        f\"{constructor.tag}: field refinement {index + 1}\")\n                    try:\n                        accepted = predicate(self, reference.arguments,\n                                             tuple(converted), bits, symbols)\n                    except (ValueError, TypeError, ArithmeticError) as error:\n                        raise ValueError(f\"{context}: {error}\") from error\n                    if accepted is False:\n                        raise RefinementViolation(f\"{context} failed\")\n                    if accepted is not True:\n                        raise ValueError(f\"{context} did not produce Bool\")\n                self._check_indices(constructor, converted)\n            return ls.DataValue(constructor.tag, converted)\n        name, arguments = reference.name, reference.arguments\n        if not arguments:\n            return ls.validate(value, name, bits)\n        if name == \"List\":\n            if not isinstance(value, list):\n                raise TypeError(\"expected List\")\n            result = []\n            for index, child in enumerate(value):\n                try:\n                    result.append(self._walk(\n                        arguments[0], child, bits, mode, symbols))\n                except (ValueError, TypeError, OverflowError) as error:\n                    error_type = (RefinementViolation if isinstance(\n                        error, RefinementViolation) else ValueError)\n                    raise error_type(f\"List[{index}]: {error}\") from error\n            return result\n        if name in (\"Nullable\", \"Optional\"):\n            if (not isinstance(value, ls.Presence) or value.kind != name\n                    or type(value.present) is not bool):\n                raise TypeError(\"invalid tagged presence: \" + name)\n            payload = None\n            if value.present:\n                payload = self._walk(\n                    arguments[0], value.value, bits, mode, symbols)\n            return ls.Presence(name, value.present, payload)\n        if name in (\"Maybe\", \"Either\"):\n            classes = ((Nothing, Just) if name == \"Maybe\" else (Left, Right))\n            tags = ((\"Maybe::Nothing\", \"Maybe::Just\") if name == \"Maybe\"\n                    else (\"Either::Left\", \"Either::Right\"))\n            if mode == \"logical\":\n                if type(value) not in classes:\n                    raise TypeError(\"invalid native \" + name)\n                index = classes.index(type(value))\n                fields = (() if name == \"Maybe\" and index == 0\n                          else (value.value,))\n            else:\n                if (not isinstance(value, ls.DataValue)\n                        or value.tag not in tags):\n                    raise ValueError(\"invalid constructor for \" + name)\n                index, fields = tags.index(value.tag), value.fields\n            expected = 0 if name == \"Maybe\" and index == 0 else 1\n            if len(fields) != expected:\n                raise ValueError(\"wrong constructor arity for \" + name)\n            converted = (() if not expected else (self._walk(\n                arguments[0 if name == \"Maybe\" else index], fields[0], bits,\n                mode, symbols),))\n            return (classes[index](*converted) if mode == \"native\"\n                    else ls.DataValue(tags[index], converted))\n        raise ValueError(\"unsupported type: \" + name)\n\n    # Values in generated code are checked where they are built, decoded or\n    # drawn, so constructing checks only the new node and matching only\n    # dispatches; a deep check of each would make recursion quadratic.\n    def construct(self, reference, tag, fields, bits=64, symbols=None):\n        if reference.name == \"List\":\n            return ls.construct(tag, fields)\n        self._check(reference)\n        self._bits(bits)\n        return self._walk(reference, ls.DataValue(tag, fields), bits,\n                          \"shallow\", {} if symbols is None else symbols)\n\n    def match(self, reference, value, branches, bits=64, symbols=None):\n        checked = value\n        if reference.name == \"List\":\n            return ls.match_list(checked, branches)\n        for tag, branch in branches:\n            if checked.tag == tag:\n                return branch(*checked.fields)\n        raise ValueError(\"missing match branch: \" + checked.tag)\n\n    def equal(self, reference, left, right, bits=64, symbols=None):\n        symbols = {} if symbols is None else symbols\n        left = self.validate(reference, left, bits, symbols)\n        right = self.validate(reference, right, bits, symbols)\n        definition = self._definitions.get(reference.name)\n        if definition is not None and definition.handle:\n            return left is right\n        constructors = self.constructors(reference)\n        if constructors is not None:\n            if left.tag != right.tag:\n                return False\n            constructor = next(item for item in constructors\n                               if item.tag == left.tag)\n            return all(self.equal(field.type, a, b, bits, symbols)\n                       for field, a, b in zip(\n                           constructor.fields, left.fields, right.fields))\n        name, arguments = reference.name, reference.arguments\n        if not arguments:\n            return ls.equal(left, right, name, name)\n        if name == \"List\":\n            return len(left) == len(right) and all(\n                self.equal(arguments[0], a, b, bits, symbols)\n                for a, b in zip(left, right))\n        if name in (\"Nullable\", \"Optional\"):\n            return (left.present == right.present and\n                    (not left.present or\n                     self.equal(arguments[0], left.value, right.value,\n                                bits, symbols)))\n        if left.tag != right.tag:\n            return False\n        if not left.fields:\n            return True\n        index = 1 if left.tag == \"Either::Right\" else 0\n        return self.equal(\n            arguments[index], left.fields[0], right.fields[0], bits, symbols)\n\n\ndef _duration_walk(value, mode):\n    if mode == \"native\":\n        if not isinstance(value, ls.DataValue) or value.tag != _DURATION_TAG:\n            raise TypeError(\"expected Duration\")\n        return ls.timedelta(microseconds=value.fields[0])\n    if type(value) is not ls.timedelta:\n        raise TypeError(\"expected a timedelta for Duration\")\n    micros = (value.days * 86400 + value.seconds) * 1000000 + value.microseconds\n    if not 0 <= micros <= _DURATION_LIMIT:\n        raise ValueError(\"Duration outside 0 to \"\n                         + str(_DURATION_LIMIT) + \" microseconds\")\n    return ls.DataValue(_DURATION_TAG, (micros,))\n"
runtimeSource "python-data-strategies" = "\"\"\"Native Hypothesis strategies for instantiated Core data schemas.\n\nGenerated tests run in Hypothesis, the framework Python developers already use,\nso failures shrink, replay and report as they expect; LawSpec supplies only the\nstrategies for its own types. ref:DEC-native-property-frameworks ref:hypothesis\n\"\"\"\n\nfrom functools import cache, cmp_to_key\n\nfrom hypothesis import strategies as st\n\nimport lawspec_runtime as ls\nfrom lawspec_schema import (RefinementViolation, witness_instances,\n                            witnessed)\n\n\ndef strategy(schema, reference, bits, budget, scalar, symbols=None,\n             witnesses=(), native_generators=None, native_schema=None,\n             index=None):\n    \"\"\"Generate values with native strategies and checked witnesses.\n\n    Witness subvalues seed nested domains in the given Symbol context.\n    Sampled witnesses supplement native generators and their shrinkers;\n    sampled alternatives need not shrink to a globally minimal value.\n    Only witnesses fitting the current node budget can be drawn.\n\n\n    Strategies are built from Hypothesis's own combinators so that its\n    shrinker, not a second one, reduces counterexamples, and shrinking stays\n    within the declared domain. ref:DEC-shrink-within-domain\"\"\"\n    if type(budget) is not int or budget < 1:\n        raise ValueError(\"structural node budget must be positive\")\n    schema._check(reference)\n    schema._bits(bits)\n    symbols = {} if symbols is None else symbols\n    native_generators = ({} if native_generators is None\n                         else dict(native_generators))\n    native_schema = schema if native_schema is None else native_schema\n    for name, factory in native_generators.items():\n        if name not in schema._arity or not callable(factory):\n            raise ValueError(\"invalid native generator binding: \" + str(name))\n\n    seeds = {}\n\n    def remember(ty, value):\n        constructors = schema.constructors(ty)\n        children = []\n        if constructors is not None:\n            constructor = next(item for item in constructors\n                               if item.tag == value.tag)\n            children = list(zip(witnessed(constructor, value.fields),\n                                value.fields))\n        elif ty.name == \"List\":\n            children = [(ty.arguments[0], child) for child in value]\n        elif ty.name in (\"Nullable\", \"Optional\") and value.present:\n            children = [(ty.arguments[0], value.value)]\n        elif ty.name == \"Maybe\" and value.tag == \"Maybe::Just\":\n            children = [(ty.arguments[0], value.fields[0])]\n        elif ty.name == \"Either\":\n            index = 0 if value.tag == \"Either::Left\" else 1\n            children = [(ty.arguments[index], value.fields[0])]\n        cost = 1 + sum(remember(child_type, child)\n                       for child_type, child in children)\n        seeds.setdefault(ty, []).append((cost, value))\n        return cost\n\n    for witness in witnesses:\n        remember(reference, schema.validate(reference, witness, bits, symbols))\n\n    def valid(ty, value):\n        try:\n            schema.validate(ty, value, bits, symbols)\n            return True\n        except RefinementViolation:\n            return False\n\n    @cache\n    def minimum(ty, limit):\n        return next((cost for cost in range(1, limit + 1)\n                     if inhabited(ty, cost)), None)\n\n    def allocation(fields, available):\n        costs = []\n        for field in fields:\n            cost = minimum(field.type, available)\n            if cost is None:\n                return None\n            costs.append(cost)\n            available -= cost\n        count = len(costs)\n        return tuple(cost + available // count + (index < available % count)\n                     for index, cost in enumerate(costs))\n\n    @cache\n    def inhabited(ty, available):\n        if available < 1:\n            return False\n        if ty.name in native_generators:\n            return True\n        constructors = schema.constructors(ty)\n        if constructors is not None:\n            return any(allocation(fields, available - 1) is not None\n                       for item in constructors\n                       for fields, _ in witness_instances(item))\n        if not ty.arguments or ty.name in (\n                \"List\", \"Maybe\", \"Nullable\", \"Optional\"):\n            return True\n        if ty.name == \"Either\":\n            return any(inhabited(child, available - 1)\n                       for child in ty.arguments)\n        raise ValueError(\"unsupported generator type: \" + ty.name)\n\n    @cache\n    def build(ty, available):\n        if ty.name in native_generators:\n            def native_child(child):\n                remaining = max(1, available - 1)\n                # A parameter need not be stored (Phantom Empty), and native\n                # containers may be inhabited without an element (List Empty).\n                if not inhabited(child, remaining):\n                    return st.nothing()\n                return build(child, remaining).map(\n                    lambda value: native_schema.to_native(\n                        child, value, bits, symbols))\n\n            def checked(value):\n                try:\n                    return native_schema.from_native(ty, value, bits, symbols)\n                except (ValueError, TypeError, ArithmeticError,\n                        AttributeError) as error:\n                    raise ValueError(\n                        f\"native generator {ty.name}: {error}\") from error\n\n            factory = native_generators[ty.name]\n            generated = factory(*(native_child(child)\n                                  for child in ty.arguments))\n            if not isinstance(generated, st.SearchStrategy):\n                raise TypeError(\n                    f\"native generator {ty.name} must return a strategy\")\n            # Mapping retains Hypothesis's shrink choices. Invalid samples\n            # and shrinks fail; they are never filtered into rejections.\n            return generated.map(checked)\n        native = build_native(ty, available)\n        candidates = [value for cost, value in seeds.get(ty, ())\n                      if cost <= available]\n        if candidates:\n            return st.one_of(native, st.sampled_from(candidates))\n        return native\n\n    def build_native(ty, available):\n        if not inhabited(ty, available):\n            raise ValueError(\n                f\"no value of {ty} within structural node budget {available}\")\n        constructors = schema.constructors(ty)\n        if constructors is not None:\n            alternatives = []\n            for constructor in constructors:\n                for fields, keys in witness_instances(constructor):\n                    costs = allocation(fields, available - 1)\n                    if costs is None:\n                        continue\n                    children = [build(field.type, cost)\n                                for field, cost in zip(fields, costs)]\n                    values = st.tuples(*children).map(\n                        lambda values, tag=constructor.tag, keys=keys:\n                        ls.DataValue(tag, tuple(values) + keys))\n                    if constructor.predicates:\n                        values = values.filter(lambda value: valid(ty, value))\n                    alternatives.append(values)\n            if ty.name in CANONICAL:\n                return st.one_of(*alternatives).map(CANONICAL[ty.name])\n            return st.one_of(*alternatives)\n        if not ty.arguments:\n            return scalar(ty.name).map(\n                lambda value: schema.validate(ty, value, bits, symbols))\n        name, arguments = ty.name, ty.arguments\n        if name == \"List\":\n            remaining = available - 1\n            cost = minimum(arguments[0], remaining)\n            maximum = 0 if cost is None else remaining // cost\n\n            def sized(length):\n                if length == 0:\n                    return st.just([])\n                return st.lists(build(arguments[0], remaining // length),\n                                min_size=length, max_size=length)\n\n            return st.integers(0, maximum).flatmap(sized)\n        if name in (\"Nullable\", \"Optional\", \"Maybe\"):\n            absent = (ls.DataValue(\"Maybe::Nothing\", ()) if name == \"Maybe\"\n                      else ls.Presence(name, False))\n            if not inhabited(arguments[0], available - 1):\n                return st.just(absent)\n            present = build(arguments[0], available - 1).map(\n                lambda value: ls.DataValue(\"Maybe::Just\", (value,))\n                if name == \"Maybe\" else ls.Presence(name, True, value))\n            return st.one_of(st.just(absent), present)\n        if name == \"Either\":\n            return st.one_of(*[\n                build(child, available - 1).map(\n                    lambda value, tag=tag: ls.DataValue(tag, (value,)))\n                for tag, child in zip(\n                    (\"Either::Left\", \"Either::Right\"), arguments)\n                if inhabited(child, available - 1)])\n        raise ValueError(\"unsupported generator type: \" + name)\n\n    if index is not None:\n        target, equations = index\n        return indexed_strategy(schema, reference, int(target), equations,\n                                budget, build, inhabited, valid)\n    return build(reference, budget)\n\n\ndef _canonical(key):\n    \"\"\"Sorted items without repeated keys: a Set's or a KeyVal's invariant.\"\"\"\n    def canonical(value):\n        items = sorted(value.fields[0], key=cmp_to_key(\n            lambda a, b: ls.compare_values(key(a), key(b))))\n        distinct = [item for index, item in enumerate(items)\n                    if index == 0 or ls.compare_values(\n                        key(items[index - 1]), key(item)) != 0]\n        return ls.DataValue(value.tag, (distinct,))\n    return canonical\n\n\n# Generated collections are canonicalised rather than filtered.\nCANONICAL = {\n    \"lawspec.collections::type::Set\": _canonical(lambda item: item),\n    \"lawspec.collections::type::KeyVal\": _canonical(lambda entry: entry.fields[0]),\n}\n\n\nINDEX_SLACK = 16\nINDEX_CHOICES = 6\nINDEX_OPERATORS = ('+', '-', '*', 'div', 'mod', '^')\n# Solved reachability is shared by strategies over the same equations, so a\n# target drawn per example does not repeat the fixpoint.\n_INDEX_TABLES = {}\n\n\ndef parse_index_term(tokens, at=0):\n    \"\"\"Parse a prefix index term: f<field>, c<literal> or an operator.\"\"\"\n    token = tokens[at]\n    if token[0] == 'c':\n        return ('c', int(token[1:])), at + 1\n    if token[0] == 'f':\n        return ('f', int(token[1:])), at + 1\n    if token in INDEX_OPERATORS:\n        left, at = parse_index_term(tokens, at + 1)\n        right, at = parse_index_term(tokens, at)\n        return (token, left, right), at\n    raise ValueError('malformed index term')\n\n\ndef eval_index_term(term, fields):\n    \"\"\"Natural index arithmetic; None when an operation has no natural value.\"\"\"\n    kind = term[0]\n    if kind == 'c':\n        return term[1]\n    if kind == 'f':\n        return fields.get(term[1])\n    x = eval_index_term(term[1], fields)\n    y = eval_index_term(term[2], fields)\n    if x is None or y is None:\n        return None\n    if kind == '+':\n        return x + y\n    if kind == '-':\n        return x - y if x >= y else None\n    if kind == '*':\n        return x * y\n    if kind == 'div':\n        return x // y if y > 0 else None\n    if kind == 'mod':\n        return x % y if y > 0 else None\n    return x ** y if 0 <= y <= 64 else None\n\n\ndef index_term_fields(term):\n    if term[0] == 'c':\n        return []\n    if term[0] == 'f':\n        return [term[1]]\n    return index_term_fields(term[1]) + index_term_fields(term[2])\n\n\ndef indexed_strategy(schema, reference, target, equations, budget, build,\n                     inhabited, valid):\n    \"\"\"Construct values whose structural index equals target.\n\n    Each constructor carries its index term then its guards, in prefix\n    notation over field indices. Reachability is a forward fixpoint over\n    levels 0..target+slack, so a child may exceed its parent's index; the\n    target is then solved backwards, and nothing is filtered away.\n\n\n    Generating an indexed family by construction, rather than filtering,\n    keeps generation from discarding almost every candidate.\n    ref:DEC-indexed-families-as-evidence\"\"\"\n    limit = max(target, 0) + INDEX_SLACK\n\n    def parse(texts):\n        tokens = texts[0].split()\n        term, at = parse_index_term(tokens)\n        if at != len(tokens):\n            raise ValueError('malformed index term')\n        guards = []\n        for text in texts[1:]:\n            tokens = text.split()\n            if tokens[0] not in ('==', '>='):\n                raise ValueError('malformed index guard')\n            left, at = parse_index_term(tokens, 1)\n            right, at = parse_index_term(tokens, at)\n            guards.append((tokens[0], left, right))\n        fields = index_term_fields(term)\n        for _, left, right in guards:\n            fields += index_term_fields(left) + index_term_fields(right)\n        return term, guards, tuple(dict.fromkeys(fields))\n\n    tables = {tag: parse(texts) for tag, texts in equations.items()}\n\n    def equation(constructor):\n        if constructor.tag not in tables:\n            raise ValueError(\"missing index equation for \" + constructor.tag)\n        return tables[constructor.tag]\n\n    def plain_fields(constructor, positions):\n        return all(inhabited(field.type, budget)\n                   for index, field in enumerate(constructor.fields)\n                   if index not in positions)\n\n    families = []\n    pending = [reference]\n    while pending:\n        ty = pending.pop()\n        if ty in families:\n            continue\n        constructors = schema.constructors(ty)\n        if constructors is None:\n            raise ValueError(\"indexed generation requires a data type\")\n        families.append(ty)\n        for constructor in constructors:\n            _, _, positions = equation(constructor)\n            pending.extend(constructor.fields[p].type for p in positions)\n\n    def holds(guard, fields):\n        relation, left, right = guard\n        x = eval_index_term(left, fields)\n        y = eval_index_term(right, fields)\n        if x is None or y is None:\n            return False\n        return x == y if relation == '==' else x >= y\n\n    def assignments(constructor, reach):\n        term, guards, positions = equation(constructor)\n        choices = [[(p, v) for v in range(limit + 1)\n                    if (constructor.fields[p].type, v) in reach]\n                   for p in positions]\n        found = []\n\n        # A guard is checked as soon as its fields are assigned, so an\n        # equality between siblings prunes every mismatched pair at once.\n        assigned_by = {}\n        for guard in guards:\n            needed = set(index_term_fields(guard[1]) +\n                         index_term_fields(guard[2]))\n            at = max((positions.index(p) for p in needed), default=-1)\n            assigned_by.setdefault(at, []).append(guard)\n\n        def extend(at, current):\n            if at == len(choices):\n                value = eval_index_term(term, dict(current))\n                if value is not None and value <= limit:\n                    found.append((value, tuple(current)))\n                return\n            for choice in choices[at]:\n                following = current + [choice]\n                fields = dict(following)\n                if all(holds(guard, fields)\n                       for guard in assigned_by.get(at, ())):\n                    extend(at + 1, following)\n        if not all(holds(guard, {}) for guard in assigned_by.get(-1, ())):\n            return found\n        extend(0, [])\n        return found\n\n    # Keep the schema in the entry so its id cannot be reused while cached.\n    table_key = (id(schema), reference,\n                 tuple(sorted((tag, tuple(texts))\n                              for tag, texts in equations.items())))\n    cached = _INDEX_TABLES.get(table_key)\n    if cached is not None and cached[1] >= limit:\n        limit = cached[1]\n    else:\n        reach = set()\n        while True:\n            grown = set(reach)\n            for ty in families:\n                for constructor in schema.constructors(ty):\n                    _, _, positions = equation(constructor)\n                    if not plain_fields(constructor, positions):\n                        continue\n                    for value, _ in assignments(constructor, reach):\n                        grown.add((ty, value))\n            if grown == reach:\n                break\n            reach = grown\n        cached = _INDEX_TABLES[table_key] = (schema, limit, reach, {})\n    _, _, reach, solutions = cached\n\n    def solve(constructor, k):\n        key = (constructor.tag, k)\n        if key not in solutions:\n            solutions[key] = [assignment\n                              for value, assignment in\n                              assignments(constructor, reach) if value == k]\n        return solutions[key]\n\n    @cache\n    def indexed(ty, k):\n        alternatives = []\n        for constructor in schema.constructors(ty):\n            _, _, positions = equation(constructor)\n            if not plain_fields(constructor, positions):\n                continue\n            choices = solve(constructor, k)\n            if not choices:\n                continue\n\n            def assemble(assignment, constructor=constructor):\n                targets = dict(assignment)\n                children = [\n                    indexed(field.type, targets[index])\n                    if index in targets else build(field.type, budget)\n                    for index, field in enumerate(constructor.fields)]\n                return st.tuples(*children).map(\n                    lambda fields, tag=constructor.tag:\n                    ls.DataValue(tag, fields))\n\n            values = st.sampled_from(choices).flatmap(assemble)\n            if constructor.predicates:\n                values = values.filter(lambda value, ty=ty: valid(ty, value))\n            alternatives.append(values)\n        if not alternatives:\n            raise ValueError(f\"no value of {ty} has index {k}\")\n        return st.one_of(*alternatives)\n\n    if (reference, target) not in reach:\n        # An open target (negative), or one drawn from earlier inputs that\n        # breaks their preconditions or names no value, generates from the\n        # smallest reachable indices; an index claim rejects a mismatch.\n        levels = sorted(level for ty, level in reach\n                        if ty == reference)[:INDEX_CHOICES]\n        if not levels:\n            raise ValueError(f\"no value of {reference} has an index\")\n        return st.sampled_from(levels).flatmap(\n            lambda level: indexed(reference, level))\n    return indexed(reference, target)\n"
runtimeSource "javascript" = "/**\n * LawSpec's runtime for JavaScript and TypeScript: the portable scalar domain,\n * seeded generation, models, actors, sessions and nodes, with no test-framework\n * dependency.\n *\n * A law must mean the same thing on every target, so this module implements\n * LawSpec's own arithmetic, equality and conversions instead of JavaScript's\n * doubles: integers are exact BigInts that reach a bounded type only through a\n * checked conversion, exact division gives a Rational, decimals are exact, and\n * floats follow IEEE 754 at their declared precision.\n * ref:DEC-portable-exact-arithmetic ref:ieee-754 ref:decimal-arithmetic\n *\n * It is emitted unchanged into every generated JavaScript and TypeScript\n * project, so the generated tests and the adapters share one definition of the\n * domain. ref:DEC-typed-core-boundary\n */\n\nexport class Rational {\n  constructor(n, d = 1n) {\n    n = BigInt(n);\n    d = BigInt(d);\n    if (!d) throw new RangeError('exact division by zero');\n    if (d < 0n) {\n      n = -n;\n      d = -d;\n    }\n    let a = n < 0n ? -n : n,\n        b = d;\n    while (b) [a, b] = [b, a % b];\n    this.n = n / a;\n    this.d = d / a;\n    Object.freeze(this);\n  }\n  toString() {\n    return `${this.n}/${this.d}`;\n  }\n}\nexport class Decimal {\n  constructor(coefficient, exponent = 0n) {\n    this.coefficient = BigInt(coefficient);\n    this.exponent = BigInt(exponent);\n    Object.freeze(this);\n  }\n  toString() {\n    return `${this.coefficient}e${this.exponent}`;\n  }\n}\nexport class Complex {\n  constructor(real, imaginary) {\n    this.real = real;\n    this.imaginary = imaginary;\n    Object.freeze(this);\n  }\n}\nexport class Raw {\n  constructor(kind, units) {\n    this.kind = kind;\n    this.units = Object.freeze([...units]);\n    Object.freeze(this);\n  }\n}\nexport class Presence {\n  constructor(kind, present, value) {\n    this.kind = kind;\n    this.present = present;\n    this.value = value;\n    Object.freeze(this);\n  }\n}\n\nexport class DataValue {\n  constructor(tag, fields) {\n    this.tag = tag;\n    this.fields = Object.freeze([...fields]);\n    Object.freeze(this);\n  }\n}\nexport const UNIT = Object.freeze({kind: 'Unit'});\nexport const integerType = (t) =>\n    /^(U?Int(8|16|32|64|Size)|UIntPtr|BigU?Int|Integer)$/.test(t);\nexport const exactType = (t) =>\n    integerType(t) || ['Decimal', 'Rational'].includes(t);\nexport function ratio(x) {\n  if (x instanceof Rational) return x;\n  if (x instanceof Decimal)\n    return x.exponent >= 0n\n      ? new Rational(x.coefficient * 10n ** x.exponent)\n      : new Rational(x.coefficient, 10n ** -x.exponent);\n  if (typeof x === 'bigint') return new Rational(x);\n  if (typeof x === 'number' && Number.isInteger(x))\n    return new Rational(BigInt(x));\n  throw new TypeError('exact numeric value required');\n}\nexport function bounds(t, bits = 64) {\n  if (t === 'BigInt' || t === 'Integer') return [null, null];\n  if (t === 'BigUInt') return [0n, null];\n  const w = BigInt(\n      ['IntSize', 'UIntSize', 'UIntPtr'].includes(t)\n        ? bits\n        : t.match(/\\d+/)[0],\n  );\n  return t.startsWith('U')\n    ? [0n, 2n ** w - 1n]\n    : [-(2n ** (w - 1n)), 2n ** (w - 1n) - 1n];\n}\nfunction decimal(x) {\n  const r = ratio(x);\n  let d = r.d,\n      a = 0n,\n      b = 0n;\n  while (d % 2n === 0n) {\n    d /= 2n;\n    a++;\n  }\n  while (d % 5n === 0n) {\n    d /= 5n;\n    b++;\n  }\n  if (d !== 1n)\n    throw new RangeError('Decimal conversion is not finite; use round');\n  const scale = a > b ? a : b;\n  return new Decimal(r.n * 2n ** (scale - a) * 5n ** (scale - b), -scale);\n}\n/**\n * Moves a value into the declared type, failing instead of wrapping or rounding\n * silently, because a bounded type is only ever reached through a checked\n * conversion. ref:DEC-portable-exact-arithmetic\n */\nexport function convert(x, t, bits = 64) {\n  if (integerType(t)) {\n    const r =\n        typeof x === 'number' && Number.isFinite(x)\n          ? floatRatio(x)\n          : ratio(x);\n    if (r.d !== 1n) throw new RangeError('fractional conversion to ' + t);\n    const [lo, hi] = bounds(t, bits);\n    if ((lo !== null && r.n < lo) || (hi !== null && r.n > hi))\n      throw new RangeError('integer outside ' + t + ' range');\n    return ['Int8', 'Int16', 'Int32', 'UInt8', 'UInt16', 'UInt32'].includes(\n        t,\n    )\n      ? Number(r.n)\n      : r.n;\n  }\n  if (t === 'Rational')\n    return typeof x === 'number' ? floatRatio(x) : ratio(x);\n  if (t === 'Decimal')\n    return decimal(typeof x === 'number' ? floatRatio(x) : x);\n  if (t === 'Float32' || t === 'Float64') {\n    let v;\n    if (typeof x === 'number') v = x;\n    else v = exactFloat(ratio(x), t);\n    return t === 'Float32' ? Math.fround(v) : v;\n  }\n  if (t === 'Complex64' || t === 'Complex128') {\n    const z =\n        x instanceof Complex\n          ? x\n          : new Complex(\n              convert(x, t === 'Complex64' ? 'Float32' : 'Float64'),\n              0,\n            );\n    return t === 'Complex64'\n      ? new Complex(Math.fround(z.real), Math.fround(z.imaginary))\n      : z;\n  }\n  return validate(x, t, bits);\n}\nfunction floatRatio(x) {\n  if (!Number.isFinite(x))\n    throw new RangeError('non-finite exact conversion');\n  if (x === 0) return new Rational(0n);\n  const a = new DataView(new ArrayBuffer(8));\n  a.setFloat64(0, x);\n  const bits = a.getBigUint64(0),\n      sign = bits >> 63n ? -1n : 1n;\n  const exp = (bits >> 52n) & 2047n,\n      mant = (bits & ((1n << 52n) - 1n)) + (exp ? 1n << 52n : 0n),\n      shift = (exp || 1n) - 1075n;\n  return shift >= 0\n    ? new Rational(sign * mant * 2n ** shift)\n    : new Rational(sign * mant, 2n ** -shift);\n}\nfunction validUnit(t, c) {\n  return (\n    Number.isInteger(c) &&\n      c >= 0 &&\n      c <=\n        (t === 'Bytes'\n          ? 255\n          : ['Utf16Text', 'CodeUnit16'].includes(t)\n            ? 65535\n            : 1114111) &&\n      (!['Text', 'Char'].includes(t) || c < 55296 || c > 57343)\n  );\n}\n/**\n * Checks a value an adapter produced against its declared domain: native code\n * may return anything its own type allows, and a law quantifies only over the\n * declared domain. ref:DEC-portable-exact-arithmetic\n */\nexport function validate(x, t, bits = 64) {\n  if (t.startsWith('Either ')) {\n    const types = eitherArguments(t);\n    if (\n        !(x instanceof DataValue) ||\n        x.fields.length !== 1 ||\n        !['Either::Left', 'Either::Right'].includes(x.tag)\n    ) {\n      throw new TypeError('invalid Either constructor or arity');\n    }\n    const inner = types[x.tag === 'Either::Left' ? 0 : 1];\n    return new DataValue(x.tag, [validate(x.fields[0], inner, bits)]);\n  }\n  if (t.startsWith('Maybe ')) {\n    if (!(x instanceof DataValue)) throw new TypeError('expected Maybe');\n    if (x.tag === 'Maybe::Nothing' && x.fields.length === 0) return x;\n    if (x.tag === 'Maybe::Just' && x.fields.length === 1) {\n      return new DataValue(x.tag, [\n        validate(x.fields[0], t.slice(6), bits),\n      ]);\n    }\n    throw new TypeError('invalid Maybe constructor or arity');\n  }\n  if (t.startsWith('List ')) {\n    if (!Array.isArray(x)) throw new TypeError('expected List');\n    return Array.from(x, (value, index) => {\n      if (!Object.hasOwn(x, index))\n        throw new TypeError('List cannot contain array holes');\n      return validate(value, t.slice(5), bits);\n    });\n  }\n  const fail = () => {\n    throw new TypeError('invalid ' + t + ' value');\n  };\n  if (t.startsWith('Nullable ') || t.startsWith('Optional ')) {\n    const i = t.indexOf(' '),\n        kind = t.slice(0, i);\n    if (\n        !(x instanceof Presence) ||\n        x.kind !== kind ||\n        typeof x.present !== 'boolean'\n    )\n      fail();\n    if (x.present)\n      return new Presence(\n          kind,\n          true,\n          validate(x.value, t.slice(i + 1), bits),\n      );