 : more | close == ord '}' -> pure (Just lowDigits, more)\n              comma : more | comma == ord ',' ->\n                let (highDigits, afterDigits) = span (isDigit . chr) more\n                in case afterDigits of\n                  close : more' | close == ord '}' -> pure (if null highDigits then Nothing else Just highDigits, more')\n                  _ -> failure \"a repetition is {n}, {n,} or {n,m}\"\n              _ -> failure \"a repetition is {n}, {n,} or {n,m}\"\n            if null lowDigits then failure \"a repetition is {n}, {n,} or {n,m}\" else pure ()\n            let low = read (map chr lowDigits) :: Integer\n                highValue = fmap (\\ds -> read (map chr ds) :: Integer) high\n            if low > 1000 || maybe False (\\h -> h > 1000 || h < low) highValue\n              then failure \"a repetition count is at most 1000, and n must not exceed m\"\n              else pure (RegexRepeat r (fromInteger low) (fromInteger <$> highValue), afterHigh)\n        case rest' of\n          c' : _ | quantifier c' -> failure \"a repetition cannot itself be repeated\"\n          _ -> pure (node, rest')\n      _ -> pure (r, input)\n    escape input = case input of\n      c : rest -> case chr c of\n        'd' -> pure ((False, digits), rest)\n        'D' -> pure ((True, digits), rest)\n        'w' -> pure ((False, word), rest)\n        'W' -> pure ((True, word), rest)\n        's' -> pure ((False, space), rest)\n        'S' -> pure ((True, space), rest)\n        'n' -> pure ((False, [(10, 10)]), rest)\n        't' -> pure ((False, [(9, 9)]), rest)\n        'r' -> pure ((False, [(13, 13)]), rest)\n        'f' -> pure ((False, [(12, 12)]), rest)\n        'v' -> pure ((False, [(11, 11)]), rest)\n        ch | ch `elem` \"\\\\.^$|?*+()[]{}-/\" -> pure ((False, [(c, c)]), rest)\n           | otherwise -> failure (\"\\\\\" ++ [ch] ++ \" is not a portable escape\")\n      [] -> failure \"the regex ends with a lone \\\\\"\n    single (False, [(lo, hi)]) = lo == hi\n    single _ = False\n    classAtom input = case input of\n      c : rest | c == ord '\\\\' -> escape rest\n               | c == ord '[' -> failure \"write \\\\[ for the character inside a class\"\n               | otherwise -> pure ((False, [(c, c)]), rest)\n      [] -> failure \"a [ is never closed\"\n    characterClass input = do\n      let (negated, body) = case input of\n            c : rest | c == ord '^' -> (True, rest)\n            _ -> (False, input)\n          items acc first inp = case inp of\n            [] -> failure \"a [ is never closed\"\n            c : rest | c == ord ']' -> if first then failure \"an empty class is not portable\" else pure (reverse acc, rest)\n            _ -> do\n              (item, rest) <- classAtom inp\n              case rest of\n                dash : next : _ | single item && dash == ord '-' && next /= ord ']' -> do\n                  (high, rest') <- classAtom (drop 1 rest)\n                  if not (single high) then failure \"a range ends with one character\" else pure ()\n                  let low = fst (head (snd item))\n                      top = fst (head (snd high))\n                  if top < low then failure \"a range must run from low to high\" else pure ()\n                  items ((False, [(low, top)]) : acc) False rest'\n                _ -> items (item : acc) False rest\n      (classItems, rest) <- items [] True body\n      pure (RegexSet negated classItems, rest)\n    digits = [(48, 57)]\n    word = [(48, 57), (65, 90), (95, 95), (97, 122)]\n    space = [(9, 13), (32, 32)]\n\n-- | Whether the portable regex matches all of the code points.\nregexMatches :: String -> [Int] -> Either String Bool\nregexMatches pattern text = do\n  node <- regexParse pattern\n  pure (length text `elem` reach node [0])\n  where\n    n = length text\n    indexed = zip [0 ..] text\n    at p = lookup p indexed\n    normal = sort . nub\n    reach node positions = case node of\n      RegexSet negated items -> normal [p + 1 | p <- positions, p < n, Just c <- [at p],\n        negated /= any (\\(itemNegated, ranges) -> itemNegated /= any (\\(lo, hi) -> lo <= c && c <= hi) ranges) items]\n      RegexSequence rs -> foldl (flip reach) positions rs\n      RegexAlternatives rs -> normal (concatMap (`reach` positions) rs)\n      RegexRepeat body low high ->\n        let required = iterate (reach body) positions !! low\n            more seen frontier limit\n              | null frontier || limit == Just 0 = seen\n              | otherwise =\n                  let next = [p | p <- reach body frontier, p `notElem` seen]\n                  in more (normal (seen ++ next)) next (subtract 1 <$> limit)\n        in more (normal required) required (subtract low <$> high)\n\n-- Recorded values: a law compares a value's portable rendering with the\n-- text stored under recorded/<unit>/<name> in the project. LAWSPEC_RECORDED\n-- names the folder; otherwise it is recorded/ in the nearest folder, from\n-- the working one up, that holds lawspec.json or recorded/. With\n-- LAWSPEC_UPDATE_RECORDED=1 (lawspec test --update-recorded) a law records\n-- the value instead.\nrecordedRoot :: IO FilePath\nrecordedRoot = do\n  given <- lookupEnv \"LAWSPEC_RECORDED\"\n  case given of\n    Just folder | not (null folder) -> pure folder\n    _ -> do\n      start <- Directory.getCurrentDirectory\n      let search folder = do\n            config <- Directory.doesFileExist (folder ++ \"/lawspec.json\")\n            recordings <- Directory.doesDirectoryExist (folder ++ \"/recorded\")\n            let parent = reverse (drop 1 (dropWhile (/= '/') (reverse folder)))\n            if config || recordings then pure (folder ++ \"/recorded\")\n              else if null parent || parent == folder then pure (start ++ \"/recorded\")\n              else search parent\n      search start\n\nrecorded :: String -> Scalar -> IO Scalar\nrecorded key value = do\n  let text = renderValue value\n  root <- recordedRoot\n  let path = root ++ \"/\" ++ key\n  update <- lookupEnv \"LAWSPEC_UPDATE_RECORDED\"\n  if update == Just \"1\"\n    then do\n      Directory.createDirectoryIfMissing True (reverse (drop 1 (dropWhile (/= '/') (reverse path))))\n      B.writeFile path (TE.encodeUtf8 (T.pack (text ++ \"\\n\")))\n      pure (SBool True)\n    else do\n      exists <- Directory.doesFileExist path\n      if not exists\n        then throwIO (ErrorCall (\"no recording recorded/\" ++ key ++ \"; run lawspec test --update-recorded to record \" ++ text))\n        else do\n          contents <- T.unpack . TE.decodeUtf8 <$> B.readFile path\n          let stored = if not (null contents) && last contents == '\\n' then init contents else contents\n          if stored /= text\n            then throwIO (ErrorCall (\"recorded/\" ++ key ++ \" differs: expected \" ++ stored ++ \", actual \" ++ text ++\n              \" (lawspec test --update-recorded records the new value)\"))\n            else pure (SBool True)\n\n-- Built-in resources (see LawSpec.Resources): a law acquires them before\n-- each case and releases them after it.\n{-# NOINLINE temporaryCount #-}\ntemporaryCount :: IORef Int\ntemporaryCount = unsafePerformIO (newIORef 0)\n\nacquireResource :: String -> IO String\nacquireResource kind = case kind of\n  _ | kind `elem` [\"temporaryDirectory\", \"temporaryFile\"] -> do\n    folder <- Directory.getTemporaryDirectory\n    unique <- atomicModifyIORef' temporaryCount (\\n -> (n + 1, n))\n    now <- getMonotonicTimeNSec\n    let path = folder ++ \"/lawspec-\" ++ show now ++ \"-\" ++ show unique\n    if kind == \"temporaryDirectory\" then Directory.createDirectory path else writeFile path \"\"\n    pure path\n  \"environment\" -> do\n    saved <- Environment.getEnvironment\n    pure (concat [name ++ \"\\0\" ++ value ++ \"\\0\" | (name, value) <- sort saved])\n  _ -> throwIO (ErrorCall (\"unknown resource kind \" ++ kind))\n\nreleaseResource :: String -> String -> IO ()\nreleaseResource kind value = case kind of\n  \"temporaryDirectory\" -> Directory.removePathForcibly value\n  \"temporaryFile\" -> Directory.removePathForcibly value\n  \"environment\" -> do\n    let pairs xs = case break (== '\\0') xs of\n          (name, '\\0' : rest) -> case break (== '\\0') rest of\n            (text, '\\0' : more) -> (name, text) : pairs more\n            _ -> []\n          _ -> []\n        saved = pairs value\n    current <- Environment.getEnvironment\n    forM_ current $ \\(name, _) -> case lookup name saved of\n      Nothing -> Environment.unsetEnv name\n      Just _ -> pure ()\n    forM_ saved $ \\(name, text) -> do\n      now <- lookupEnv name\n      if now == Just text then pure () else Environment.setEnv name text\n  _ -> throwIO (ErrorCall (\"unknown resource kind \" ++ kind))\n\n-- | A TCP port on the local host that is free now.\nfreePort :: IO Int\nfreePort = do\n  let hints = Socket.defaultHints { Socket.addrSocketType = Socket.Stream }\n  address : _ <- Socket.getAddrInfo (Just hints) (Just \"127.0.0.1\") (Just \"0\")\n  socket <- Socket.openSocket address\n  Socket.bind socket (Socket.addrAddress address)\n  port <- Socket.socketPort socket\n  Socket.close socket\n  pure (fromIntegral port)\n\n-- | A law's resource: acquire it, run the case with it, and release it,\n-- even when the case fails.\nwithResource :: IO Scalar -> (Scalar -> IO ()) -> (Scalar -> IO a) -> IO a\nwithResource acquire release body = do\n  resource <- acquire >>= \\value -> evaluate (forceScalar value `seq` value)\n  body resource `finally` release resource\n\n-- | Shared resources (share R per group | unit | run, in a harness): one\n-- value per scope key. The first use acquires it; every later use resets it\n-- first, so no case sees what another left. One case holds it at a time,\n-- and releaseShared (after the unit's spec) releases every one.\ndata SharedEntry = SharedEntry (MVar (Maybe Scalar)) (IORef Int) (Scalar -> IO ())\n\n{-# NOINLINE sharedResources #-}\nsharedResources :: IORef [(String, SharedEntry)]\nsharedResources = unsafePerformIO (newIORef [])\n\n-- | A concurrent resource (resource T is concurrent) is held by any number\n-- of cases at once, and reset only when none holds it.\nwithShared :: String -> Bool -> IO Scalar -> (Scalar -> IO ()) -> (Scalar -> IO ()) -> (Scalar -> IO a) -> IO a\nwithShared key concurrent acquire reset release body = do\n  fresh <- newMVar Nothing\n  users <- newIORef 0\n  SharedEntry slot holders _ <- atomicModifyIORef' sharedResources $ \\entries -> case lookup key entries of\n    Just entry -> (entries, entry)\n    Nothing -> let entry = SharedEntry fresh users release in (entries ++ [(key, entry)], entry)\n  if concurrent then do\n    value <- modifyMVar slot $ \\held -> do\n      count <- readIORef holders\n      v <- case held of\n        Just v -> v <$ (if count == 0 then reset v else pure ())\n        Nothing -> acquire >>= \\v -> evaluate (forceScalar v `seq` v)\n      atomicModifyIORef' holders (\\n -> (n + 1, ()))\n      pure (Just v, v)\n    body value `finally` atomicModifyIORef' holders (\\n -> (n - 1, ()))\n  else do\n   held <- takeMVar slot\n   value <- (case held of\n     Just value -> value <$ reset value\n     Nothing -> acquire >>= \\value -> evaluate (forceScalar value `seq` value))\n     `onFailure` putMVar slot held\n   body value `finally` putMVar slot (Just value)\n  where onFailure action handler = action `catch` \\e -> handler >> throwIO (e :: SomeException)\n\nreleaseShared :: IO ()\nreleaseShared = do\n  entries <- atomicModifyIORef' sharedResources (\\entries -> ([], entries))\n  forM_ (reverse entries) $ \\(_, SharedEntry slot _ release) ->\n    takeMVar slot >>= maybe (pure ()) release\n\n-- | A built-in resource of the kind, built by its constructor.\nacquireBuiltin :: String -> String -> IO Scalar\nacquireBuiltin kind tag\n  | kind == \"freePort\" = (\\port -> SData tag [SInteger \"Int32\" (fromIntegral port)]) <$> freePort\n  | otherwise = (\\value -> SData tag [textScalar value]) <$> acquireResource kind\n\nreleaseBuiltin :: String -> Scalar -> IO ()\nreleaseBuiltin kind resource = case (kind, resource) of\n  (\"freePort\", _) -> pure ()\n  (_, SData _ [SSequence _ value]) -> releaseResource kind (map chr value)\n  _ -> throwIO (ErrorCall (\"not a \" ++ kind ++ \" resource\"))\n\n-- | Standalone contracts must observe their result even when\n-- the predicate is true.\nforceScalar :: Scalar -> ()\nforceScalar (SInteger _ n) = n `seq` ()\nforceScalar (SBool b) = b `seq` ()\nforceScalar (SDecimal c e) = c `seq` e `seq` ()\nforceScalar (SRational n d) = n `seq` d `seq` ()\nforceScalar (SFloat _ bs) = foldr seq () bs\nforceScalar (SComplex _ r i) = forceScalar r `seq` forceScalar i\nforceScalar (SSequence _ xs) = foldr seq () xs\nforceScalar (SList xs) =\n  foldr (\\value rest -> forceScalar value `seq` rest) () xs\nforceScalar (SData tag xs) = foldr seq () tag `seq`\n  foldr (\\value rest -> forceScalar value `seq` rest) () xs\nforceScalar (SCharacter _ c) = c `seq` ()\nforceScalar (SSymbol ident description) =\n  foldr seq () ident `seq` foldr seq () description\nforceScalar (SScopedSymbol scope ident description) =\n  scope `seq` foldr seq () ident `seq` foldr seq () description\nforceScalar (SPresent _ (Just v)) = forceScalar v\nforceScalar (SHandle t h) = foldr seq () t `seq` h `seq` ()\nforceScalar _ = ()\n\n-- Workflow runtime. A workflow runs under a runtime: a clock, a seeded\n-- random source, a trace of what happened, and the state of stateful\n-- stages. A runtime is attached to a symbol context (workflowContext);\n-- without one, the default runtime applies (real time, unless the tests\n-- installed a virtual clock). Durations are Integer microseconds. Workflow\n-- bodies are pure, so a stage's waits run through unsafePerformIO.\n\n-- | Tells the time and waits, in microseconds. A clock is virtual unless it\n-- is real time: on a virtual clock waits pass at once, and timeouts and\n-- hedges count only the time it reports.\ndata Clock = Clock { clockNow :: IO Integer, clockSleep :: Integer -> IO (), clockVirtual :: Bool }\n\nrealClock :: Clock\nrealClock = Clock\n  { clockNow = (`div` 1000) . toInteger <$> getMonotonicTimeNSec\n  , clockSleep = \\micros -> threadDelay (fromInteger micros)\n  , clockVirtual = False }\n\n-- | Advances when slept on and returns at once.\nvirtualClock :: IO (Clock, IORef Integer)\nvirtualClock = do\n  time <- newIORef 0\n  pure (Clock (readIORef time) (\\micros -> modifyIORef' time (+ micros)) True, time)\n\n-- | The same sequence on every target for the same seed: (output, next state).\n--\n-- SplitMix64 is small, fast and specified exactly, so every runtime implements\n-- the same generator and a seed names the same case everywhere. ref:splitmix\n-- ref:DEC-portable-seeded-generation\nsplitMix64 :: Word64 -> (Word64, Word64)\nsplitMix64 state =\n  let next = state + 0x9E3779B97F4A7C15\n      z1 = (next `xor` (next `shiftR` 30)) * 0xBF58476D1CE4E5B9\n      z2 = (z1 `xor` (z1 `shiftR` 27)) * 0x94D049BB133111EB\n  in (z2 `xor` (z2 `shiftR` 31), next)\n\n-- | A stage starting or finishing an attempt, or a wait.\ndata TraceEvent = TraceEvent { traceKind :: String, traceStage :: String, traceNumber :: Integer, traceSucceeded :: Bool }\n  deriving (Eq, Show)\n\n-- | runtimeGates: whether rate limits, breakers, bulkheads and caches apply.\n-- The runtime generated tests install has them off: a workflow law calls the\n-- workflow and its composition, which would see each other's state.\ndata WorkflowRuntime = WorkflowRuntime\n  { runtimeClock :: Clock, runtimeRandom :: IORef Word64\n  , runtimeTrace :: IORef [TraceEvent], runtimeState :: IORef [(String, Scalar)]\n  , runtimeGates :: Bool, runtimeCache :: IORef [(String, [(Scalar, Scalar, Integer)])]\n  -- A frame per running workflow: the undos of its completed stages.\n  , runtimeFrames :: IORef [[(String, IO ())]]\n  -- The running attempt's hedge.\n  , runtimeHedge :: IORef (Maybe Hedge) }\n\n-- | A running attempt's hedge: its stage, delay and most attempts. A\n-- virtual hedge (on a virtual clock) runs its attempts one after another.\ndata Hedge = Hedge { hedgeStage :: String, hedgeDelay :: Integer, hedgeMost :: Integer, hedgeVirtual :: Bool }\n\nnewWorkflowRuntime :: Clock -> Word64 -> IO WorkflowRuntime\nnewWorkflowRuntime clock seed = do\n  random <- newIORef seed\n  trace <- newIORef []\n  state <- newIORef []\n  cache <- newIORef []\n  frames <- newIORef []\n  hedge <- newIORef Nothing\n  pure (WorkflowRuntime clock random trace state True cache frames hedge)\n\n-- | Uniform in [0, bound); 0 when bound is 0.\nrandomBelow :: WorkflowRuntime -> Integer -> IO Integer\nrandomBelow runtime bound\n  | bound <= 0 = pure 0\n  | otherwise = do\n      (value, next) <- splitMix64 <$> readIORef (runtimeRandom runtime)\n      writeIORef (runtimeRandom runtime) next\n      pure (toInteger value `mod` bound)\n\n{-# NOINLINE workflowTable #-}\nworkflowTable :: IORef [(Unique, WorkflowRuntime)]\nworkflowTable = unsafePerformIO (newIORef [])\n\n{-# NOINLINE defaultWorkflow #-}\ndefaultWorkflow :: IORef (Maybe WorkflowRuntime)\ndefaultWorkflow = unsafePerformIO (newIORef Nothing)\n\n-- | A symbol context whose workflows run under the runtime.\nworkflowContext :: WorkflowRuntime -> IO SymbolContext\nworkflowContext runtime = do\n  unique <- newUnique\n  modifyIORef' workflowTable ((unique, runtime) :)\n  pure (SymbolContext unique)\n\n-- | Makes the default runtime virtual, as generated tests do. Timeouts and\n-- hedges stay on: they count virtual time (see runStage).\nuseVirtualClock :: Word64 -> IO ()\nuseVirtualClock seed = do\n  (clock, _) <- virtualClock\n  runtime <- newWorkflowRuntime clock seed\n  writeIORef defaultWorkflow (Just runtime { runtimeGates = False })\n\n-- | The runtime a context's workflows run under: the one attached to it\n-- (workflowContext), which keeps its own clock, or else the default one.\n-- Workflow time is the Clock ability's: where a law has installed a Clock\n-- handler, the default runtime waits and times out on it. That view shares\n-- the default runtime's state (trace, gates, hedge), so runStage and\n-- awaitStep, which look it up separately, see the same runtime.\nworkflowRuntime :: SymbolContext -> IO WorkflowRuntime\nworkflowRuntime symbols@(SymbolContext unique) = do\n  table <- readIORef workflowTable\n  case lookup unique table of\n    Just runtime -> pure runtime\n    Nothing -> do\n      runtime <- readIORef defaultWorkflow >>= \\current -> case current of\n        Just runtime -> pure runtime\n        Nothing -> do\n          runtime <- newWorkflowRuntime realClock 0\n          writeIORef defaultWorkflow (Just runtime)\n          pure runtime\n      clock <- abilityClock symbols\n      pure (maybe runtime (\\c -> runtime { runtimeClock = c }) clock)\n\n-- The Clock ability's key, as every target names it.\nclockAbilityKey :: String\nclockAbilityKey = \"lawspec.time::ability::Clock\"\n\n-- | How to read an installed Clock handler (the generated record, held as a\n-- Dynamic) as a workflow Clock: its now (Instant microseconds) and sleep\n-- (microseconds). The runtime cannot name the record's type, so\n-- lawspec.time's registerClock registers it (registerClockAbility; the\n-- generated tests of laws that install a Clock handler call it); until then\n-- workflows and mailboxes keep the runtime's clock.\n{-# NOINLINE clockAbilityReader #-}\nclockAbilityReader :: IORef (Maybe (Dynamic -> Bool -> Maybe Clock))\nclockAbilityReader = unsafePerformIO (newIORef Nothing)\n\n-- | Registers how to read a Clock handler of type h. Whether a handler is\n-- real time is not the record's to say: it is the installation's\n-- (installedRealClock, which the generated tests use for lawspec.time's\n-- default handler). Every other Clock handler is virtual.\nregisterClockAbility :: forall h. Typeable h => (h -> IO Integer) -> (h -> Integer -> IO ()) -> IO ()\nregisterClockAbility now sleep = writeIORef clockAbilityReader (Just reader)\n  where\n    reader dynamic real = case fromDynamic dynamic :: Maybe h of\n      Just handler -> Just (Clock (now handler) (sleep handler) (not real))\n      Nothing -> Nothing\n\n-- | The workflow clock of the Clock handler installed with a context, if\n-- its reader is registered.\nabilityClock :: SymbolContext -> IO (Maybe Clock)\nabilityClock (SymbolContext unique) = do\n  table <- readIORef handlerTable\n  case [(value, real) | Just handlers <- [lookup unique table], Installed k value _ real <- handlers, k == clockAbilityKey] of\n    [] -> pure Nothing\n    (value, real) : _ -> (\\reader -> reader >>= \\r -> r value real) <$> readIORef clockAbilityReader\n\n-- | retryStrategy is immediate, fixed, linear, exponential, fibonacci or\n-- custom; delay, step, factor and cap (negative for none) are its parameters.\ndata Retry = Retry\n  { retryStrategy :: String, retryDelayOf :: Integer, retryStep :: Integer, retryFactor :: Integer, retryCap :: Integer\n  , retryAttempts :: Integer, retryJitter :: String\n  , retryWhen :: Maybe (Scalar -> Bool)\n  , retryDecide :: Maybe (Integer -> Scalar -> Integer -> Maybe Integer) }\n\n-- | A stateful policy: gateStart gives its state, gateAdmit a Step of the\n-- next state and a Gate (Admit, WaitFor or Reject), and gateFinish (when\n-- set) the state after the call. gateWait is -2 to fail at once when not\n-- admitted, -1 to wait without bound, or the most it waits.\ndata Gate = Gate\n  { gateKind :: String, gateStart :: Integer -> Scalar, gateAdmit :: Scalar -> Integer -> Scalar\n  , gateFinish :: Maybe (Scalar -> Integer -> Bool -> Scalar), gateWait :: Integer }\n\n-- | policyKey names the stage's state; policyCache is how long a success is\n-- reused (0 or less for none); policyWraps says failures are StageFailures.\ndata StagePolicy = StagePolicy\n  { policyStage :: String, policyRetry :: Maybe Retry, policyTimeout :: Integer\n  , policyKey :: String, policyGates :: [Gate], policyCache :: Integer, policyWraps :: Bool\n  , policyCompensate :: Maybe (Scalar -> Scalar)\n  -- (delay, most): when an attempt has not succeeded after delay, another\n  -- starts beside it, up to most in all; the first success wins.\n  , policyHedge :: Maybe (Integer, Integer) }\n\n-- | A policy with only a stage name and retries, as built by hand.\nretryPolicy :: String -> Maybe Retry -> StagePolicy\nretryPolicy stage retry = StagePolicy stage retry (-1) stage [] (-1) False Nothing Nothing\n\n-- | Runs a workflow whose stages compensate: when it fails, the undos of its\n-- completed stages run, last first.\n{-# NOINLINE runWorkflow #-}\nrunWorkflow :: SymbolContext -> (() -> Scalar) -> Scalar\nrunWorkflow symbols attempt = unsafePerformIO $ do\n  runtime <- workflowRuntime symbols\n  modifyIORef' (runtimeFrames runtime) ([] :)\n  result <- evaluate (attempt ())\n  frames <- readIORef (runtimeFrames runtime)\n  let (frame, rest) = case frames of\n        top : others -> (top, others)\n        [] -> ([], [])\n  writeIORef (runtimeFrames runtime) rest\n  case result of\n    SData \"Either::Left\" _ -> mapM_ (\\(stage, undo) -> do\n      modifyIORef' (runtimeTrace runtime) (++ [TraceEvent \"compensate\" stage 0 True])\n      undo) frame\n    _ -> pure ()\n  pure result\n\n-- | The delay before attempt (2 or more), before jitter.\nretryDelay :: Retry -> Integer -> Integer\nretryDelay retry attempt = case retryStrategy retry of\n  \"immediate\" -> 0\n  \"fixed\" -> retryDelayOf retry\n  \"linear\" -> retryDelayOf retry + retryStep retry * (n - 1)\n  \"exponential\" ->\n    let delay = retryDelayOf retry * retryFactor retry ^ (n - 1)\n    in if retryCap retry >= 0 && delay > retryCap retry then retryCap retry else delay\n  \"fibonacci\" -> retryDelayOf retry * fibonacci n\n  other -> error (\"unknown retry strategy: \" ++ other)\n  where\n    n = attempt - 1\n    fibonacci k = fst (foldl (\\(a, b) _ -> (b, a + b)) (1, 1) [2 .. k])\n\n-- | Full: [0, delay]; equal: delay/2 + [0, delay/2]; decorrelated:\n-- [base, previous * 3], capped at delay.\njittered :: WorkflowRuntime -> String -> Integer -> Integer -> Integer -> IO Integer\njittered runtime jitter delay previous base = case jitter of\n  \"full\" -> randomBelow runtime (delay + 1)\n  \"equal\" -> let half = delay `div` 2 in (half +) <$> randomBelow runtime (delay - half + 1)\n  \"decorrelated\" -> do\n    let high = max base (previous * 3)\n    value <- (base +) <$> randomBelow runtime (high - base + 1)\n    pure (min delay value)\n  _ -> pure delay\n\nstageFailurePrefix :: String\nstageFailurePrefix = \"lawspec.resilience::type::StageFailure::\"\n\ngatePrefix :: String\ngatePrefix = \"lawspec.resilience::type::Gate::\"\n\n-- | Admits the call (Nothing) or gives the failure to return instead.\npassGate :: WorkflowRuntime -> StagePolicy -> Gate -> IO (Maybe String)\npassGate runtime policy gate = go 0\n  where\n    key = policyKey policy ++ \"/\" ++ gateKind gate\n    failure = case gateKind gate of\n      \"breaker\" -> \"CircuitOpen\"\n      \"limit\" -> \"RateLimited\"\n      _ -> \"Saturated\"\n    go waited = do\n      now <- clockNow (runtimeClock runtime)\n      states <- readIORef (runtimeState runtime)\n      let state = maybe (gateStart gate now) id (lookup key states)\n      step <- evaluate (gateAdmit gate state now)\n      case step of\n        SData _ [next, SData decision fields] -> do\n          modifyIORef' (runtimeState runtime) (((key, next) :) . filter ((/= key) . fst))\n          case (decision, fields) of\n            _ | decision == gatePrefix ++ \"Admit\" -> pure Nothing\n              | decision == gatePrefix ++ \"Reject\" || gateWait gate == -2 -> pure (Just failure)\n            (_, [SInteger _ delay])\n              | gateWait gate >= 0 && waited + delay > gateWait gate -> pure (Just failure)\n              | otherwise -> do\n                  modifyIORef' (runtimeTrace runtime) (++ [TraceEvent \"wait\" (policyStage policy) delay True])\n                  clockSleep (runtimeClock runtime) delay\n                  go (waited + delay)\n            _ -> error \"expected a Gate\"\n        _ -> error \"expected a Step\"\n\nfinishGate :: WorkflowRuntime -> StagePolicy -> Bool -> Gate -> IO ()\nfinishGate runtime policy succeeded gate = case gateFinish gate of\n  Nothing -> pure ()\n  Just finish -> do\n    let key = policyKey policy ++ \"/\" ++ gateKind gate\n    now <- clockNow (runtimeClock runtime)\n    states <- readIORef (runtimeState runtime)\n    case lookup key states of\n      Just state -> do\n        next <- evaluate (finish state now succeeded)\n        modifyIORef' (runtimeState runtime) (((key, next) :) . filter ((/= key) . fst))\n      Nothing -> pure ()\n\n-- | Runs a stage's attempts under its policy; a Left is a failure. key is the\n-- stage's input, for the cache.\n{-# NOINLINE runStage #-}\nrunStage :: SymbolContext -> StagePolicy -> (() -> Scalar) -> Scalar -> Scalar\nrunStage symbols policy attempt key = unsafePerformIO $ do\n  runtime <- workflowRuntime symbols\n  let gates = if runtimeGates runtime then policyGates policy else []\n      cacheKey = policyKey policy ++ \"/cache\"\n      caching = policyCache policy > 0 && runtimeGates runtime\n  now <- clockNow (runtimeClock runtime)\n  entries <- maybe [] id . lookup cacheKey <$> readIORef (runtimeCache runtime)\n  case [value | caching, (entry, value, expires) <- entries, now < expires, entry == key] of\n    value : _ -> do\n      modifyIORef' (runtimeTrace runtime) (++ [TraceEvent \"cached\" (policyStage policy) 0 True])\n      pure value\n    [] -> gated runtime gates [] caching cacheKey\n  where\n    gated runtime (gate : rest) passed caching cacheKey = do\n      outcome <- passGate runtime policy gate\n      case outcome of\n        Just failure -> do\n          mapM_ (finishGate runtime policy False) passed\n          pure (SData \"Either::Left\" [SData (stageFailurePrefix ++ failure) []])\n        Nothing -> gated runtime rest (passed ++ [gate]) caching cacheKey\n    gated runtime [] passed caching cacheKey = do\n      result <- attempts runtime 1 0\n      let succeeded = case result of\n            SData \"Either::Left\" _ -> False\n            _ -> True\n      mapM_ (finishGate runtime policy succeeded) passed\n      case (result, policyCompensate policy) of\n        (SData \"Either::Right\" [value], Just undo) ->\n          -- The newest undo first, so a frame runs last-completed first.\n          modifyIORef' (runtimeFrames runtime) $ \\frames -> case frames of\n            top : others -> ((policyStage policy, () <$ evaluate (undo value)) : top) : others\n            [] -> []\n        _ -> pure ()\n      when' (caching && succeeded) $ do\n        now <- clockNow (runtimeClock runtime)\n        modifyIORef' (runtimeCache runtime) $ \\caches ->\n          let kept = [entry | entry@(entryKey, _, _) <- maybe [] id (lookup cacheKey caches), entryKey /= key]\n          in (cacheKey, kept ++ [(key, result, now + policyCache policy)]) : filter ((/= cacheKey) . fst) caches\n      pure result\n    when' condition action = if condition then action else pure ()\n    timedOut = SData \"Either::Left\" [SData (stageFailurePrefix ++ \"TimedOut\") []]\n    -- An attempt, evaluated in full under its stage's timeout (failing\n    -- with TimedOut when it outlives it) and hedge: the Timeout and Hedge\n    -- transformers of the Async ability, measured on the runtime's Clock.\n    -- On a virtual clock (generated tests, or a law using virtual clock)\n    -- an attempt takes the virtual time that passes while it runs, so both\n    -- are deterministic. On a real clock with gates off, both are off.\n    timed runtime\n      | policyTimeout policy <= 0 && policyHedge policy == Nothing = evaluate (attempt ())\n      | clockVirtual (runtimeClock runtime) = virtuallyTimed runtime\n      | not (runtimeGates runtime) = evaluate (attempt ())\n      | otherwise = do\n          outer <- readIORef (runtimeHedge runtime)\n          writeIORef (runtimeHedge runtime) ((\\(delay, most) -> Hedge (policyStage policy) delay most False) <$> policyHedge policy)\n          let full = do\n                result <- evaluate (attempt ())\n                result <$ evaluate (deepScalar result)\n              limited = if policyTimeout policy > 0 then timeout (fromInteger (policyTimeout policy)) full else Just <$> full\n          outcome <- limited `finally` writeIORef (runtimeHedge runtime) outer\n          pure (maybe timedOut id outcome)\n    virtuallyTimed runtime = do\n      outer <- readIORef (runtimeHedge runtime)\n      began <- clockNow (runtimeClock runtime)\n      writeIORef (runtimeHedge runtime) ((\\(delay, most) -> Hedge (policyStage policy) delay most True) <$> policyHedge policy)\n      result <- (do\n        value <- evaluate (attempt ())\n        value <$ evaluate (deepScalar value)) `finally` writeIORef (runtimeHedge runtime) outer\n      ended <- clockNow (runtimeClock runtime)\n      pure (if policyTimeout policy > 0 && ended - began > policyTimeout policy then timedOut else result)\n    event runtime kind number succeeded =\n      modifyIORef' (runtimeTrace runtime) (++ [TraceEvent kind (policyStage policy) number succeeded])\n    attempts runtime number previous = do\n      event runtime \"start\" number False\n      result <- timed runtime\n      let failure = case result of\n            SData \"Either::Left\" [value] -> Just value\n            _ -> Nothing\n      event runtime \"finish\" number (failure == Nothing)\n      -- Only the step's own failures and timeouts are retried.\n      let retried = case failure of\n            Just value | policyWraps policy -> case value of\n              SData tag [inner] | tag == stageFailurePrefix ++ \"StepFailed\" -> Just inner\n              SData tag [] | tag == stageFailurePrefix ++ \"TimedOut\" -> Just value\n              _ -> Nothing\n            other -> other\n      case (retried, policyRetry policy) of\n        (Just value, Just retry)\n          | retryAttempts retry > 0 && number >= retryAttempts retry -> pure result\n          | maybe False (\\when -> not (when value)) (retryWhen retry) -> pure result\n          | otherwise -> do\n              let next = number + 1\n              wait <- case retryStrategy retry of\n                \"custom\" -> pure (maybe Nothing (\\decide -> decide next value previous) (retryDecide retry))\n                _ -> do\n                  let base = if retryStrategy retry == \"immediate\" then 0 else retryDelay retry 2\n                  Just <$> jittered runtime (retryJitter retry) (retryDelay retry next) previous base\n              case wait of\n                Nothing -> pure result\n                Just delay -> do\n                  event runtime \"sleep\" delay True\n                  clockSleep (runtimeClock runtime) delay\n                  attempts runtime next delay\n        _ -> pure result\n\n-- | An asynchronous step's logical result: start runs the step and convert\n-- turns its native result into a logical value. Under a hedge, attempts run\n-- on threads of their own; the first success wins. Under a virtual hedge\n-- they run one after another, the next starting when one fails, so the\n-- first success wins as it would in real time when no attempt outlives the\n-- delay.\n{-# NOINLINE awaitStep #-}\nawaitStep :: SymbolContext -> IO a -> (a -> Scalar) -> Scalar\nawaitStep symbols start convert = unsafePerformIO $ do\n  runtime <- workflowRuntime symbols\n  hedge <- readIORef (runtimeHedge runtime)\n  case hedge of\n    Nothing -> convert <$> start\n    Just (Hedge stage _ most True) -> do\n      let run = start >>= \\native -> let value = convert native in value <$ evaluate (deepScalar value)\n          loop started value = case value of\n            SData \"Either::Left\" _ | started < most -> do\n              modifyIORef' (runtimeTrace runtime) (++ [TraceEvent \"hedge\" stage (started + 1) True])\n              run >>= loop (started + 1)\n            _ -> pure value\n      run >>= loop 1\n    Just (Hedge stage delay most False) -> do\n      results <- newChan\n      threads <- newIORef []\n      let launch number = do\n            if number > 1 then modifyIORef' (runtimeTrace runtime) (++ [TraceEvent \"hedge\" stage number True]) else pure ()\n            thread <- forkIO $ do\n              outcome <- try (start >>= \\native -> let value = convert native in value <$ evaluate (deepScalar value))\n              writeChan results (outcome :: Either SomeException Scalar)\n            modifyIORef' threads (thread :)\n          loop started pending = do\n            outcome <- if started < most then timeout (fromInteger delay) (readChan results) else Just <$> readChan results\n            case outcome of\n              Nothing -> launch (started + 1) >> loop (started + 1) (pending + 1)\n              Just (Left failure) -> throwIO failure\n              Just (Right value@(SData \"Either::Left\" _))\n                | pending > (1 :: Integer) -> loop started (pending - 1)\n                | started >= most -> pure value\n                | otherwise -> launch (started + 1) >> loop (started + 1) 1\n              Just (Right value) -> pure value\n      (launch 1 >> loop 1 1) `finally` (readIORef threads >>= mapM_ killThread)\n\n-- | The Async ability's default handler, natively: GHC's threads. LawSpec\n-- code performs pause; workflows reach the rest natively: asyncSpawn starts\n-- an action as a task, asyncWait gives a task's result (rethrowing what it\n-- threw), and asyncAll runs actions side by side and gives their results in\n-- order. lawspec.concurrent's default handler is this one.\ndata NativeAsync = NativeAsync\n  { asyncPause :: IO ()\n  , asyncSpawn :: forall a. IO a -> IO (Process a)\n  , asyncWait :: forall a. Process a -> IO a\n  -- Every action's result, in order; all finish before the first\n  -- exception (in order) is thrown.\n  , asyncAll :: forall a. [IO a] -> IO [a] }\n\nnativeAsync :: NativeAsync\nnativeAsync = NativeAsync\n  { asyncPause = yield\n  , asyncSpawn = spawn\n  , asyncWait = join\n  , asyncAll = \\actions -> do\n      tasks <- mapM spawn actions\n      outcomes <- mapM (\\(Process result) -> readMVar result) tasks\n      mapM (either throwIO pure) outcomes }\n\n-- | An all group's step results, in declaration order. The steps run side\n-- by side as tasks of the Async ability's default handler (nativeAsync),\n-- each evaluated in full. Every step finishes before a step's exception\n-- (the first, in declaration order) is thrown.\n{-# NOINLINE concurrently #-}\nconcurrently :: [Scalar] -> [Scalar]\nconcurrently steps = unsafePerformIO $\n  asyncAll nativeAsync [step <$ evaluate (deepScalar step) | step <- steps]\n\n-- | Evaluates a value in full.\ndeepScalar :: Scalar -> ()\ndeepScalar value = case value of\n  SComplex _ a b -> deepScalar a `seq` deepScalar b\n  SPresent _ (Just inner) -> deepScalar inner\n  SList items -> foldr (seq . deepScalar) () items\n  SData tag fields -> length tag `seq` foldr (seq . deepScalar) () fields\n  SHandle t h -> length t `seq` h `seq` ()\n  other -> other `seq` ()\n\n-- | A logical Duration of whole microseconds.\ndurationScalar :: Integer -> Scalar\ndurationScalar micros = SData \"lawspec.time::type::Duration::Duration\" [SInteger \"Integer\" micros]\n\n-- | A RetryDecision's delay, or Nothing to stop.\nretryDecision :: Scalar -> Maybe Integer\nretryDecision decision = case decision of\n  SData \"lawspec.time::type::RetryDecision::RetryAfter\" [SData _ [SInteger _ micros]] -> Just micros\n  _ -> Nothing\n\n\n-- Portable generation for stateful models. A type descriptor is an\n-- s-expression: (int T lo hi) with _ for no bound, (bool), (text), (unit),\n-- (list D), (maybe D), (either L R), (data NAME (ctor TAG D...) ...) and\n-- (ref NAME) for a data type declared in the model's table. Every target\n-- generates, shrinks and renders the same values for the same seed.\n\n-- | A descriptor form: a list, an integer, a symbol or string, or _.\ndata Descriptor = DescList [Descriptor] | DescInteger Integer | DescAtom String | DescNone\n  deriving (Eq, Show)\n\n-- | Parses s-expressions: lists, integers, strings, symbols and _.\nreadDescriptor :: String -> [Descriptor]\nreadDescriptor = forms . skipBlank where\n  skipBlank = dropWhile (`elem` \" \\t\\r\\n\")\n  forms \"\" = []\n  forms text = let (form, rest) = item text in form : forms (skipBlank rest)\n  item ('(' : rest) = list [] (skipBlank rest)\n  item ('\"' : rest) = quoted [] rest\n  item text =\n    let (atom, rest) = break (`elem` \" \\t\\r\\n()\") text\n        digits = dropWhile (== '-') atom\n    in (if atom == \"_\" then DescNone\n        else if not (null digits) && all isDigit digits\n          then DescInteger (read (if take 1 atom == \"-\" then '-' : digits else digits))\n          else DescAtom atom, rest)\n  list acc (')' : rest) = (DescList (reverse acc), rest)\n  list acc text = let (form, rest) = item text in list (form : acc) (skipBlank rest)\n  quoted acc ('\"' : rest) = (DescAtom (reverse acc), rest)\n  quoted acc ('\\\\' : c : rest) = quoted (c : acc) rest\n  quoted acc (c : rest) = quoted (c : acc) rest\n  quoted _ [] = error \"unterminated descriptor string\"\n\n-- | A descriptor atom's text.\ndescriptorName :: Descriptor -> String\ndescriptorName (DescAtom s) = s\ndescriptorName (DescInteger n) = show n\ndescriptorName DescNone = \"None\"\ndescriptorName (DescList _) = error \"descriptor name expected\"\n\n-- | The data types of a descriptor text, by name.\ntype DataTable = [(String, Descriptor)]\n\n-- | SplitMix64 draws threaded through a generation.\nnewtype Draw a = Draw { runDraw :: Word64 -> (a, Word64) }\ninstance Functor Draw where\n  fmap f (Draw g) = Draw (\\s -> let (a, s') = g s in (f a, s'))\ninstance Applicative Draw where\n  pure a = Draw (\\s -> (a, s))\n  Draw f <*> Draw g = Draw (\\s -> let (h, s1) = f s; (a, s2) = g s1 in (h a, s2))\ninstance Monad Draw where\n  Draw g >>= k = Draw (\\s -> let (a, s1) = g s in runDraw (k a) s1)\n\n-- | Uniform in [0, bound); 0, with no draw, when bound is 0.\ndrawBelow :: Integer -> Draw Integer\ndrawBelow bound\n  | bound <= 0 = pure 0\n  | otherwise = Draw (\\s -> let (value, next) = splitMix64 s in (toInteger value `mod` bound, next))\n\nresolveDescriptor :: DataTable -> Descriptor -> Descriptor\nresolveDescriptor table (DescList [DescAtom \"ref\", name]) =\n  case lookup (descriptorName name) (reverse table) of\n    Just d -> d\n    Nothing -> error (\"unknown data type \" ++ descriptorName name)\nresolveDescriptor _ d = d\n\nunboundedRange :: Integer\nunboundedRange = 1000000\n\n-- | An integer's range: a missing bound is 1,000,000 from zero, or\n-- 2,000,000 from the other bound when that is beyond it.\ndescriptorBounds :: Descriptor -> (Integer, Integer)\ndescriptorBounds (DescList (_ : _ : lo : hi : _)) = case (lo, hi) of\n  (DescNone, DescNone) -> (negate unboundedRange, unboundedRange)\n  (DescNone, DescInteger h) -> (min (negate unboundedRange) (h - 2 * unboundedRange), h)\n  (DescInteger l, DescNone) -> (l, max unboundedRange (l + 2 * unboundedRange))\n  (DescInteger l, DescInteger h) -> (l, h)\n  _ -> error \"invalid integer bounds\"\ndescriptorBounds d = error (\"invalid integer descriptor \" ++ show d)\n\n-- | The constructors of a data descriptor.\nconstructorsOf :: Descriptor -> [Descriptor]\nconstructorsOf (DescList (_ : _ : ctors)) = ctors\nconstructorsOf d = error (\"invalid data descriptor \" ++ show d)\n\n-- | A constructor's tag and field descriptors.\nconstructorParts :: Descriptor -> (String, [Descriptor])\nconstructorParts (DescList (_ : tag : fields)) = (descriptorName tag, fields)\nconstructorParts d = error (\"invalid constructor descriptor \" ++ show d)\n\n-- | The constructors whose fields mention no data type.\nbaseConstructors :: Descriptor -> [Descriptor]\nbaseConstructors d =\n  let ctors = constructorsOf d\n      found = [c | c <- ctors, not (any mentionsData (snd (constructorParts c)))]\n  in if null found then ctors else found\n\nmentionsData :: Descriptor -> Bool\nmentionsData (DescList (kind : rest)) = kind `elem` [DescAtom \"ref\", DescAtom \"data\"] || any mentionsData rest\nmentionsData _ = False\n\ndescriptorKind :: Descriptor -> String\ndescriptorKind (DescList (DescAtom kind : _)) = kind\ndescriptorKind d = error (\"unknown descriptor \" ++ show d)\n\ndescriptorArgument :: Int -> Descriptor -> Descriptor\ndescriptorArgument i (DescList xs) | i < length xs = xs !! i\ndescriptorArgument _ d = error (\"invalid descriptor \" ++ show d)\n\ngenerateValue :: DataTable -> Descriptor -> Integer -> Draw Scalar\ngenerateValue table d0 size = case descriptorKind d of\n  \"int\" -> do\n    let (lo, hi) = descriptorBounds d\n    special <- drawBelow 10\n    if special < 2\n      then do\n        i <- drawBelow 4\n        pure (SInteger t ([lo, hi, min (max 0 lo) hi, min (max 1 lo) hi] !! fromInteger i))\n      else SInteger t . (lo +) <$> drawBelow (hi - lo + 1)\n  \"bool\" -> SBool . (== 1) <$> drawBelow 2\n  \"text\" -> do\n    n <- drawBelow (size + 1)\n    SSequence \"Text\" <$> replicateM (fromInteger n) ((fromInteger . (32 +)) <$> drawBelow 95)\n  \"unit\" -> pure (SAbsent \"Unit\")\n  \"list\" -> do\n    n <- drawBelow (size + 1)\n    SList <$> replicateM (fromInteger n) (generateValue table (arg 1) size)\n  \"maybe\" -> do\n    r <- drawBelow 4\n    if r == 0 then pure (SData \"Maybe::Nothing\" [])\n      else (\\v -> SData \"Maybe::Just\" [v]) <$> generateValue table (arg 1) size\n  \"either\" -> do\n    r <- drawBelow 2\n    if r == 0 then (\\v -> SData \"Either::Left\" [v]) <$> generateValue table (arg 1) size\n      else (\\v -> SData \"Either::Right\" [v]) <$> generateValue table (arg 2) size\n  \"data\" -> do\n    let choices = if size <= 0 then baseConstructors d else constructorsOf d\n    i <- drawBelow (toInteger (length choices))\n    let (tag, fields) = constructorParts (choices !! fromInteger i)\n    SData tag <$> mapM (\\f -> generateValue table f (max (size - 1) 0)) fields\n  _ -> error (\"unknown descriptor \" ++ show d)\n  where d = resolveDescriptor table d0\n        t = descriptorName (arg 1)\n        arg i = descriptorArgument i d\n\nminimalValue :: DataTable -> Descriptor -> Scalar\nminimalValue table d0 = case descriptorKind d of\n  \"int\" -> let (lo, hi) = descriptorBounds d in SInteger (descriptorName (arg 1)) (min (max 0 lo) hi)\n  \"bool\" -> SBool False\n  \"text\" -> SSequence \"Text\" []\n  \"unit\" -> SAbsent \"Unit\"\n  \"list\" -> SList []\n  \"maybe\" -> SData \"Maybe::Nothing\" []\n  \"either\" -> SData \"Either::Left\" [minimalValue table (arg 1)]\n  _ -> case baseConstructors d of\n    ctor : _ -> let (tag, fields) = constructorParts ctor in SData tag (map (minimalValue table) fields)\n    [] -> error (\"data type without constructors \" ++ show d)\n  where d = resolveDescriptor table d0\n        arg i = descriptorArgument i d\n\n-- | Toward zero integer division.\ntowardZero :: Integer -> Integer -> Integer\ntowardZero n divisor = let q = abs n `div` divisor in if n >= 0 then q else negate q\n\n-- | The empty sequence, the first half, then each with one item removed.\nhalfAndRemovals :: [a] -> [[a]]\nhalfAndRemovals xs = [] : take (length xs `div` 2) xs : [take i xs ++ drop (i + 1) xs | i <- [0 .. length xs - 1]]\n\n-- | Smaller candidates for a value, most aggressive first.\nshrinkValue :: DataTable -> Descriptor -> Scalar -> [Scalar]\nshrinkValue table d0 v = uniqueRendered $ case (descriptorKind d, v) of\n  (\"int\", SInteger t n) -> case minimalValue table d of\n    SInteger _ target | n /= target ->\n      map (SInteger t) [target, n - towardZero (n - target) 2, n - (if n > target then 1 else -1)]\n    _ -> []\n  (\"bool\", SBool True) -> [SBool False]\n  (\"text\", SSequence t xs) | not (null xs) -> map (SSequence t) (halfAndRemovals xs)\n  (\"list\", SList xs) | not (null xs) ->\n    map SList (halfAndRemovals xs)\n      ++ concat [[SList (take i xs ++ [c] ++ drop (i + 1) xs) | c <- shrinkValue table (arg 1) x]\n                | (i, x) <- zip [0 ..] xs]\n  (\"maybe\", SData \"Maybe::Just\" [x]) ->\n    SData \"Maybe::Nothing\" [] : [SData \"Maybe::Just\" [c] | c <- shrinkValue table (arg 1) x]\n  (\"either\", SData tag [x]) ->\n    [SData tag [c] | c <- shrinkValue table (arg (if tag == \"Either::Left\" then 1 else 2)) x]\n  (\"data\", SData tag fields) ->\n    let ctorFields = case find ((== tag) . fst) (map constructorParts (constructorsOf d)) of\n          Just (_, fs) -> fs\n          Nothing -> error (\"unknown constructor \" ++ tag)\n        pairs = zip fields ctorFields\n    in minimalValue table d\n         -- A field of the same type is a smaller value of it.\n         : [f | (f, fd) <- pairs, fd == DescList [DescAtom \"ref\", arg 1]]\n         ++ concat [[SData tag (take i fields ++ [c] ++ drop (i + 1) fields) | c <- shrinkValue table fd field]\n                   | (i, (field, fd)) <- zip [0 ..] pairs]\n  _ -> []\n  where d = resolveDescriptor table d0\n        arg i = descriptorArgument i d\n        uniqueRendered candidates = go [renderValue v] candidates\n        go _ [] = []\n        go seen (c : cs) = let r = renderValue c in\n          if r `elem` seen then go seen cs else c : go (r : seen) cs\n\n-- | A value's canonical text, the same on every target.\nrenderValue :: Scalar -> String\nrenderValue value = case value of\n  SBool b -> if b then \"true\" else \"false\"\n  SInteger _ n -> show n\n  SSequence _ xs -> '\"' : concatMap escape (map chr xs) ++ \"\\\"\"\n  SAbsent _ -> \"()\"\n  SList xs -> \"[\" ++ commas xs ++ \"]\"\n  SData tag fields ->\n    let name = T.unpack (last (T.splitOn (T.pack \"::\") (T.pack tag)))\n    in if null fields then name else name ++ \"(\" ++ commas fields ++ \")\"\n  SHandle t h -> T.unpack (last (T.splitOn (T.pack \"::\") (T.pack t))) ++ \"#\" ++ show (handleNumber h)\n  other -> show other\n  where escape c = if c == '\\\\' || c == '\"' then ['\\\\', c] else [c]\n        commas xs = foldr1' (map renderValue xs)\n        foldr1' [] = \"\"\n        foldr1' parts = foldr1 (\\a b -> a ++ \", \" ++ b) parts\n\n-- | A descriptor text's data types and its last form, the one generated.\nvaluesFrom :: String -> (DataTable, Descriptor)\nvaluesFrom text =\n  let forms = readDescriptor text\n      table = [(descriptorName name, f) | f@(DescList (DescAtom \"data\" : name : _)) <- forms]\n  in (table, last forms)\n\n-- | count values generated from one SplitMix64 seed, rendered.\ngeneratedValues :: String -> Word64 -> Integer -> Integer -> [String]\ngeneratedValues text seed size count =\n  let (table, d) = valuesFrom text\n  in map renderValue (fst (runDraw (replicateM (fromInteger count) (generateValue table d size)) seed))\n\n-- | The shrink candidates of the first value generated, rendered.\nshrunkValues :: String -> Word64 -> Integer -> [String]\nshrunkValues text seed size =\n  let (table, d) = valuesFrom text\n      first = fst (runDraw (generateValue table d size) seed)\n  in map renderValue (shrinkValue table d first)\n\n-- Stateful models. A model's spec (see LawSpec.MachineSpec) lists its data\n-- types, start and commands; the callbacks beside it are the generated\n-- definitions that call the adapters, the references over the model state,\n-- preconditions, the abstraction and invariants, each taking symbols first.\n-- A run is generated by simulating the pure model, so every command in it is\n-- allowed by typestate, its precondition and its reference; it is then\n-- executed against the adapters and every result, abstracted state and\n-- invariant is checked. A failing run is shrunk by dropping commands and\n-- shrinking arguments, replaying the model to keep each candidate valid.\n-- Draws, shrink candidates and messages match every other target.\n\n-- | A generated definition: symbols, then its arguments in order.\ntype ModelCallback = SymbolContext -> [Scalar] -> Either String Scalar\n\n-- | A model: its spec, (start system, start model), each command's (system,\n-- reference, precondition), the abstraction and the invariants, in the\n-- spec's order.\ndata Model = Model\n  { modelSpec :: String\n  , modelStart :: (ModelCallback, ModelCallback)\n  , modelCommands :: [(ModelCallback, ModelCallback, Maybe ModelCallback)]\n  , modelAbstract :: Maybe ModelCallback\n  , modelInvariants :: [ModelCallback]\n  }\n\ndata ModelCommand = ModelCommand\n  { mcName :: String\n  , mcArguments :: [Descriptor]\n  , mcState :: Int\n  , mcUnit :: Bool\n  , mcNeeds :: [(String, Integer)]\n  , mcShifts :: [(String, Integer)]\n  -- The argument naming the key the command touches, for per-key checks.\n  , mcKey :: Maybe Int\n  , mcRun :: ModelCallback\n  , mcReference :: ModelCallback\n  , mcWhen :: Maybe ModelCallback\n  -- An actor's restart: never a generated step; injected crashes run it.\n  , mcRestart :: Bool\n  }\n\n-- | An injected crash of an actor model, given the run's start arguments:\n-- restarting the system's actor, and the model state after the restart.\ndata CrashStep = CrashStep\n  { crashSystem :: [Scalar] -> SymbolContext -> Scalar -> IO ()\n  , crashModel :: [Scalar] -> SymbolContext -> Scalar -> IO Scalar\n  }\n\ndata ModelPlan = ModelPlan\n  { planName :: String\n  , planShared :: Bool\n  , planTable :: DataTable\n  , planStartIndices :: [Integer]\n  , planStartArguments :: [Descriptor]\n  , planStartRun :: ModelCallback\n  , planStartModel :: ModelCallback\n  , planCommands :: [ModelCommand]\n  , planAbstract :: Maybe ModelCallback\n  , planInvariants :: [(String, ModelCallback)]\n  , planPerKey :: Bool\n  -- An actor model's crash step, numbered after the commands.\n  , planCrash :: Maybe CrashStep\n  -- linearizable, sequential, causal or eventual.\n  , planConsistency :: String\n  }\n\n-- | Start arguments, then each step's command index and arguments.\ntype ModelRun = ([Scalar], [(Int, [Scalar])])\n\n-- | A command the model does not allow here, or a callback's failure.\ndata ModelStop = ModelInvalid | ModelRaised String deriving Show\ninstance Exception ModelStop\n\nmodelPlan :: Model -> ModelPlan\nmodelPlan model = asActor $ ModelPlan\n  { planName = name\n  , planShared = kind == \"shared\"\n  , planTable = [(descriptorName n, f) | f@(DescList (DescAtom \"data\" : n : _)) <- forms]\n  , planStartIndices = integers (field \"indices\" startFields)\n  , planStartArguments = field \"arguments\" startFields\n  , planStartRun = fst (modelStart model)\n  , planStartModel = snd (modelStart model)\n  , planCommands = filter (not . mcRestart) allCommands\n  , planAbstract = modelAbstract model\n  , planInvariants = zip kinds (modelInvariants model)\n  , planPerKey = not (null [() | DescList [DescAtom \"perkey\", DescAtom \"true\"] <- forms])\n  , planCrash = Nothing\n  , planConsistency = case [descriptorName c | DescList [DescAtom \"consistency\", c] <- forms] of\n      c : _ -> c\n      [] -> \"linearizable\"\n  }\n  where\n    allCommands = zipWith command [rest | DescList (DescAtom \"command\" : rest) <- forms] (modelCommands model)\n    restart = find mcRestart allCommands\n    -- An actor model's start and handlers run inside an actor; the\n    -- abstraction and state invariants read its state between messages.\n    actor = not (null [() | DescList [DescAtom \"actor\", DescAtom \"true\"] <- forms])\n    asActor plan\n      | not actor = plan\n      | otherwise = plan\n          { planStartRun = actorStartCallback (planStartRun plan)\n          , planCrash = Just (actorCrashStep (planStartRun plan) (planStartModel plan) restart)\n          , planCommands = [c { mcRun = actorCommandCallback (mcUnit c) (mcRun c) } | c <- planCommands plan]\n          , planAbstract = fmap actorStateCallback (planAbstract plan)\n          , planInvariants = [(k, if k == \"model\" then p else actorStateCallback p) | (k, p) <- planInvariants plan] }\n    forms = readDescriptor (modelSpec model)\n    (name, kind) = case forms of\n      DescList (_ : n : k : _) : _ -> (descriptorName n, descriptorName k)\n      _ -> error \"invalid model spec\"\n    startFields = case [rest | DescList (DescAtom \"start\" : rest) <- forms] of\n      rest : _ -> rest\n      [] -> error \"model spec without a start\"\n    kinds = case [map descriptorName rest | DescList (DescAtom \"invariants\" : rest) <- forms] of\n      ks : _ -> ks\n      [] -> []\n    field key fs = case [rest | DescList (k : rest) <- reverse fs, k == DescAtom key] of\n      rest : _ -> rest\n      [] -> []\n    integers = map (\\d -> case d of DescInteger k -> k; _ -> error \"integer expected in model spec\")\n    pair d = case d of\n      DescList [DescAtom k, DescInteger v] -> (k, v)\n      _ -> error (\"invalid model typestate \" ++ show d)\n    command (nameForm : fs) (run, reference, precondition) = ModelCommand\n      { mcName = descriptorName nameForm\n      , mcArguments = field \"arguments\" fs\n      , mcState = case field \"state\" fs of\n          [DescInteger p] -> fromInteger p\n          _ -> error \"invalid command state position\"\n      , mcUnit = field \"unit\" fs == [DescAtom \"true\"]\n      , mcNeeds = map pair (field \"needs\" fs)\n      , mcShifts = map pair (field \"shifts\" fs)\n      , mcKey = case field \"key\" fs of\n          [DescInteger k] -> Just (fromInteger k)\n          _ -> Nothing\n      , mcRun = run\n      , mcReference = reference\n      , mcWhen = precondition\n      , mcRestart = field \"restart\" fs == [DescAtom \"true\"]\n      }\n    command [] _ = error \"invalid command form\"\n\n-- | Whether a step index is an actor's injected crash.\nisCrashStep :: ModelPlan -> Int -> Bool\nisCrashStep plan index = index >= length (planCommands plan)\n\nstepName :: ModelPlan -> Int -> String\nstepName plan index = if isCrashStep plan index then \"crash\" else mcName (planCommands plan !! index)\n\nstepArguments :: ModelPlan -> Int -> [Descriptor]\nstepArguments plan index = if isCrashStep plan index then [] else mcArguments (planCommands plan !! index)\n\n-- | The model state after an injected crash, or ModelInvalid.\ncrashModelState :: ModelPlan -> [Scalar] -> SymbolContext -> Scalar -> IO Scalar\ncrashModelState plan startArgs symbols state = case planCrash plan of\n  Just crash -> crashModel crash startArgs symbols state\n  Nothing -> throwIO ModelInvalid\n\nadmits :: ModelCommand -> [Integer] -> Bool\nadmits command indices = and (zipWith needs (mcNeeds command) indices)\n  where needs (kind, k) i = if kind == \"atleast\" then i >= k else i == k\n\nshifted :: ModelCommand -> [Integer] -> [Integer]\nshifted command = zipWith shift (mcShifts command)\n  where shift (kind, d) i = if kind == \"by\" then i + d else d\n\n-- | An exception's message, without the location or context GHC adds.\nexceptionText :: SomeException -> String\nexceptionText e = case fromException e of\n  Just (ErrorCall message) -> message\n  Nothing -> case e of SomeException inner -> displayException inner\n\n-- | Calls a callback, evaluating its result in full; a thrown exception is\n-- a Left like any other failure.\ncallModel :: ModelCallback -> SymbolContext -> [Scalar] -> IO (Either String Scalar)\ncallModel f symbols args = do\n  outcome <- try (evaluate (case f symbols args of\n    Left message -> length message `seq` Left message\n    Right value -> deepScalar value `seq` Right value))\n  pure (either (Left . exceptionText) id outcome)\n\n-- | A callback's result, or ModelRaised.\ncallOrRaise :: ModelCallback -> SymbolContext -> [Scalar] -> IO Scalar\ncallOrRaise f symbols args = callModel f symbols args >>= either (throwIO . ModelRaised) pure\n\nproductField :: Bool -> Scalar -> Scalar\nproductField lastField value = case value of\n  SData _ fields@(first : _) -> if lastField then last fields else first\n  _ -> error (\"expected a product, got \" ++ renderValue value)\n\n-- | The model state and result after a command, or ModelInvalid.\nstepModel :: ModelCommand -> SymbolContext -> [Scalar] -> Scalar -> IO (Scalar, Scalar)\nstepModel command symbols args state = do\n  case mcWhen command of\n    Nothing -> pure ()\n    Just precondition -> do\n      allowed <- callModel precondition symbols [state]\n      case allowed of\n        Right (SBool True) -> pure ()\n        _ -> throwIO ModelInvalid\n  out <- callModel (mcReference command) symbols (args ++ [state])\n  case out of\n    Left _ -> throwIO ModelInvalid\n    Right value\n      | mcUnit command -> pure (value, SAbsent \"Unit\")\n      | otherwise -> case value of\n          SData _ (result : next : _) -> pure (next, result)\n          _ -> throwIO (ErrorCall (\"expected a product, got \" ++ renderValue value))\n\n-- | Whether the model allows every step of a run.\nsimulateRun :: ModelPlan -> ModelRun -> IO Bool\nsimulateRun plan run = do\n  symbols <- newSymbolContext\n  maybe False (const True) <$> simulateFinal plan symbols run\n\n-- | The model state after a run, or Nothing when the model does not allow\n-- every step of it.\nsimulateFinal :: ModelPlan -> SymbolContext -> ModelRun -> IO (Maybe Scalar)\nsimulateFinal plan symbols (startArgs, steps) = do\n  started <- callModel (planStartModel plan) symbols startArgs\n  case started of\n    Left _ -> pure Nothing\n    Right state0 -> do\n      let go state _ [] = pure (Just state)\n          go state indices ((index, _) : rest) | isCrashStep plan index = do\n            stepped <- try (crashModelState plan startArgs symbols state)\n            case stepped of\n              Left (_ :: ModelStop) -> pure Nothing\n              Right next -> go next indices rest\n          go state indices ((index, args) : rest) = do\n            let command = planCommands plan !! index\n            if not (admits command indices) then pure Nothing else do\n              stepped <- try (stepModel command symbols args state)\n              case stepped of\n                Left ModelInvalid -> pure Nothing\n                Left (ModelRaised _) -> pure Nothing\n                Right (next, _) -> go next (shifted command indices) rest\n      go state0 (planStartIndices plan) steps\n\ndrawIO :: IORef Word64 -> Draw a -> IO a\ndrawIO source draw = do\n  seed <- readIORef source\n  let (value, next) = runDraw draw seed\n  writeIORef source next\n  pure value\n\ngenerateRun :: ModelPlan -> IORef Word64 -> Integer -> Integer -> IO ModelRun\ngenerateRun plan = generateRunWith False plan\n\n-- | A generated run; with crashes, one step in eight of an actor's run is\n-- an injected crash (drawn right after the command, as on every target).\ngenerateRunWith :: Bool -> ModelPlan -> IORef Word64 -> Integer -> Integer -> IO ModelRun\ngenerateRunWith crashes plan source len size = do\n  symbols <- newSymbolContext\n  startArgs <- mapM (\\d -> drawIO source (generateValue (planTable plan) d size)) (planStartArguments plan)\n  started <- callModel (planStartModel plan) symbols startArgs\n  case started of\n    Left _ -> pure (startArgs, [])\n    Right state0 -> do\n      let go 0 _ _ acc = pure (reverse acc)\n          go n state indices acc = do\n            let allowed = [i | (i, c) <- zip [0 ..] (planCommands plan), admits c indices]\n            if null allowed then pure (reverse acc) else do\n              pick <- drawIO source (drawBelow (toInteger (length allowed)))\n              crash <- case planCrash plan of\n                Just _ | crashes -> (== 0) <$> drawIO source (drawBelow 8)\n                _ -> pure False\n              let index = allowed !! fromInteger pick\n                  command = planCommands plan !! index\n              if crash then do\n                stepped <- try (crashModelState plan startArgs symbols state)\n                case stepped of\n                  Left (_ :: ModelStop) -> go (n - 1) state indices acc\n                  Right next -> go (n - 1) next indices ((length (planCommands plan), []) : acc)\n              else do\n               args <- mapM (\\d -> drawIO source (generateValue (planTable plan) d size)) (mcArguments command)\n               stepped <- try (stepModel command symbols args state)\n               case stepped of\n                 Left ModelInvalid -> go (n - 1) state indices acc\n                 Left (ModelRaised _) -> go (n - 1) state indices acc\n                 Right (next, _) -> go (n - 1) next (shifted command indices) ((index, args) : acc)\n      steps <- go len state0 (planStartIndices plan) []\n      pure (startArgs, steps)\n\n-- | Nothing when the system agrees with the model along the run; otherwise\n-- the failing step's number and what went wrong.\nexecuteRun :: ModelPlan -> ModelRun -> IO (Maybe (Int, String))\nexecuteRun plan (startArgs, steps) = do\n  symbols <- newSymbolContext\n  stepRef <- newIORef 0\n  outcome <- try (do\n    state0 <- callOrRaise (planStartRun plan) symbols startArgs\n    expected0 <- callOrRaise (planStartModel plan) symbols startArgs\n    failure0 <- checkModelState plan symbols state0 expected0\n    case failure0 of\n      Just failure -> pure (Just failure)\n      Nothing -> do\n        let go _ _ [] = pure Nothing\n            go state expected ((index, _) : rest) | isCrashStep plan index = do\n              modifyIORef' stepRef (+ 1)\n              forM_ (planCrash plan) (\\crash -> crashSystem crash startArgs symbols state)\n              expected' <- crashModelState plan startArgs symbols expected\n              failure <- checkModelState plan symbols state expected'\n              case failure of\n                Just _ -> pure failure\n                Nothing -> go state expected' rest\n            go state expected ((index, args) : rest) = do\n              modifyIORef' stepRef (+ 1)\n              let command = planCommands plan !! index\n                  position = mcState command\n              out <- callOrRaise (mcRun command) symbols (take position args ++ [state] ++ drop position args)\n              let (result, state') = if planShared plan then (out, state)\n                    else (if mcUnit command then SAbsent \"Unit\" else productField False out, productField True out)\n              _ <- evaluate (deepScalar result `seq` deepScalar state')\n              (expected', wanted) <- stepModel command symbols args expected\n              order <- if mcUnit command then pure EQ\n                else either (throwIO . ModelRaised) pure (compareValues result wanted)\n              if order /= EQ\n                then pure (Just (\"returned \" ++ renderValue result ++ \"; the model returns \" ++ renderValue wanted))\n                else do\n                  failure <- checkModelState plan symbols state' expected'\n                  case failure of\n                    Just _ -> pure failure\n                    Nothing -> go state' expected' rest\n        go state0 expected0 steps)\n  step <- readIORef stepRef\n  pure $ case outcome of\n    Right Nothing -> Nothing\n    Right (Just message) -> Just (step, message)\n    Left e -> Just (step, case fromException e of\n      Just ModelInvalid -> \"the model does not allow this step\"\n      Just (ModelRaised message) -> \"raised error: \" ++ message\n      Nothing -> \"raised error: \" ++ exceptionText e)\n\ncheckModelState :: ModelPlan -> SymbolContext -> Scalar -> Scalar -> IO (Maybe String)\ncheckModelState plan symbols state expected = do\n  abstracted <- case planAbstract plan of\n    Nothing -> pure Nothing\n    Just abstract -> do\n      actual <- callOrRaise abstract symbols [state]\n      order <- either (throwIO . ModelRaised) pure (compareValues actual expected)\n      pure (if order /= EQ\n        then Just (\"the state is \" ++ renderValue actual ++ \"; the model is \" ++ renderValue expected)\n        else Nothing)\n  case abstracted of\n    Just _ -> pure abstracted\n    Nothing -> invariants (planInvariants plan)\n  where\n    invariants [] = pure Nothing\n    invariants ((kind, invariant) : rest) = do\n      holds <- callOrRaise invariant symbols [if kind == \"model\" then expected else state]\n      case holds of\n        SBool True -> invariants rest\n        SBool False -> pure (Just (\"an invariant on the \" ++ kind ++ \" fails\"))\n        _ -> throwIO (ModelRaised \"Bool required\")\n\n-- | Smaller runs: dropping halves, quarters and so on of the steps, then\n-- shrinking each step's arguments, then the start's.\nrunCandidates :: ModelPlan -> ModelRun -> [ModelRun]\nrunCandidates plan (startArgs, steps) =\n  [ (startArgs, take begin steps ++ drop (begin + size) steps)\n  | size <- takeWhile (>= 1) (iterate (`div` 2) (n `div` 2)), begin <- [0, size .. n - 1] ]\n  ++ [ (startArgs, take k steps ++ [(index, replace j c args)] ++ drop (k + 1) steps)\n     | (k, (index, args)) <- zip [0 ..] steps\n     , (j, (d, arg)) <- zip [0 ..] (zip (stepArguments plan index) args)\n     , c <- shrinkValue (planTable plan) d arg ]\n  ++ [ (replace j c startArgs, steps)\n     | (j, (d, arg)) <- zip [0 ..] (zip (planStartArguments plan) startArgs)\n     , c <- shrinkValue (planTable plan) d arg ]\n  where n = length steps\n        replace j c xs = take j xs ++ [c] ++ drop (j + 1) xs\n\nshrinkRun :: ModelPlan -> ModelRun -> (Int, String) -> Int -> IO (ModelRun, (Int, String))\nshrinkRun plan run failure budget\n  | budget <= 0 = pure (run, failure)\n  | otherwise = go (runCandidates plan run) budget\n  where\n    go [] _ = pure (run, failure)\n    go (candidate : rest) b = do\n      let b' = b - 1\n      if b' <= 0 then pure (run, failure) else do\n        valid <- simulateRun plan candidate\n        if not valid then go rest b' else do\n          found <- executeRun plan candidate\n          case found of\n            Just failure' -> shrinkRun plan candidate failure' b'\n            Nothing -> go rest b'\n\ndescribeRun :: ModelPlan -> ModelRun -> String\ndescribeRun plan (startArgs, steps) =\n  let call name args = name ++ \"(\" ++ joinComma (map renderValue args) ++ \")\"\n      joinComma [] = \"\"\n      joinComma texts = foldr1 (\\a b -> a ++ \", \" ++ b) texts\n      parts = call \"start\" startArgs : [call (stepName plan i) args | (i, args) <- steps]\n  in foldr1 (\\a b -> a ++ \"; \" ++ b) parts\n\n-- | Checks the system against its model on generated runs: Nothing, or the\n-- failure naming the shortest failing run found. 100 cases of up to 20\n-- steps, 2000 shrinks, seeded from LAWSPEC_SEED or 0.\n--\n-- A stateful model is checked by running generated command sequences against\n-- the system and the model side by side, then shrinking a failing run.\n-- ref:DEC-stateful-models-linearizability\ncheckModel :: Model -> IO (Maybe String)\ncheckModel = checkModelWith 100 20 2000 Nothing\n\n-- | checkModel with the number of cases, the longest run, the shrink\n-- budget and the seed (Nothing: LAWSPEC_SEED, else 0).\ncheckModelWith :: Int -> Int -> Int -> Maybe Word64 -> Model -> IO (Maybe String)\ncheckModelWith cases maxLength maxShrinks seedOverride model = do\n  seed <- case seedOverride of\n    Just s -> pure s\n    Nothing -> maybe 0 (fromInteger . read) <$> lookupEnv \"LAWSPEC_SEED\"\n  source <- newIORef seed\n  let plan = modelPlan model\n      loop c\n        | c >= cases = pure Nothing\n        | otherwise = do\n            len <- drawIO source (drawBelow (toInteger maxLength + 1))\n            run <- generateRunWith True plan source len (1 + toInteger (c `mod` 8))\n            failure <- executeRun plan run\n            case failure of\n              Nothing -> loop (c + 1)\n              Just found -> do\n                (run', (step, message)) <- shrinkRun plan run found maxShrinks\n                pure (Just (\"model \" ++ planName plan ++ \" fails at step \" ++ show step ++ \" of \"\n                  ++ describeRun plan run' ++ \": \" ++ message))\n  loop 0\n\n-- Parallel runs of a shared model. A case is a sequential prefix and one\n-- branch per thread, generated so that the model allows every interleaving\n-- of the branches (a search over each thread's position and the model state,\n-- memoized). The system runs the branches at the same time, each call's start\n-- and return recorded on one counter, with random yields and short sleeps\n-- around calls to shake out rare schedules. The history must be\n-- linearizable: some interleaving that keeps every call after those that\n-- returned before it started must give every result the model gives and\n-- leave the state it leaves (a Wing-Gong search, memoized on the same\n-- positions and model state). Each case runs several times.\n\n-- | A sequential prefix, then each thread's branch of steps.\ntype ParallelCase = (ModelRun, [[(Int, [Scalar])]])\n\n-- | The default number of threads and the longest branch.\nparallelThreads, parallelBranch :: Int\nparallelThreads = 3\nparallelBranch = 5\n\nallM :: (a -> IO Bool) -> [a] -> IO Bool\nallM _ [] = pure True\nallM p (x : xs) = p x >>= \\ok -> if ok then allM p xs else pure False\n\nanyM :: (a -> IO Bool) -> [a] -> IO Bool\nanyM _ [] = pure False\nanyM p (x : xs) = p x >>= \\ok -> if ok then pure True else anyM p xs\n\n-- | Whether a search key was seen before; records it if not.\nseenBefore :: IORef [([Int], String)] -> ([Int], String) -> IO Bool\nseenBefore seen key = do\n  keys <- readIORef seen\n  if key `elem` keys then pure True else writeIORef seen (key : keys) >> pure False\n\n-- | The positions with thread i one step further.\nadvanceAt :: Int -> [Int] -> [Int]\nadvanceAt i positions = [if j == i then k + 1 else k | (j, k) <- zip [0 ..] positions]\n\n-- | Whether the model allows the prefix then every interleaving.\nparallelAllowed :: ModelPlan -> ParallelCase -> IO Bool\nparallelAllowed plan (prefix, branches) = do\n  symbols <- newSymbolContext\n  final <- simulateFinal plan symbols prefix\n  case final of\n    Nothing -> pure False\n    Just state0 -> do\n      seen <- newIORef []\n      let visit positions state = do\n            old <- seenBefore seen (positions, renderValue state)\n            if old then pure True else allM (stepFrom positions state) (zip [0 ..] branches)\n          stepFrom positions state (i, branch) = do\n            let k = positions !! i\n            if k >= length branch then pure True else do\n              let (index, args) = branch !! k\n              stepped <- try (stepModel (planCommands plan !! index) symbols args state)\n              case stepped of\n                Left ModelInvalid -> pure False\n                Left (ModelRaised _) -> pure False\n                Right (next, _) -> visit (advanceAt i positions) next\n      visit (map (const 0) branches) state0\n\ngenerateBranch :: ModelPlan -> IORef Word64 -> Scalar -> Integer -> Integer -> IO [(Int, [Scalar])]\ngenerateBranch plan source state0 len size = do\n  symbols <- newSymbolContext\n  let go 0 _ acc = pure (reverse acc)\n      go n state acc = do\n        pick <- drawIO source (drawBelow (toInteger (length (planCommands plan))))\n        let index = fromInteger pick\n            command = planCommands plan !! index\n        args <- mapM (\\d -> drawIO source (generateValue (planTable plan) d size)) (mcArguments command)\n        stepped <- try (stepModel command symbols args state)\n        case stepped of\n          Left ModelInvalid -> go (n - 1) state acc\n          Left (ModelRaised _) -> go (n - 1) state acc\n          Right (next, _) -> go (n - 1) next ((index, args) : acc)\n  go len state0 []\n\ngenerateParallel :: ModelPlan -> IORef Word64 -> Integer -> Int -> Int -> IO ParallelCase\ngenerateParallel plan source size threads branchLength = do\n  prefixLength <- drawIO source (drawBelow 4)\n  prefix <- generateRun plan source prefixLength size\n  symbols <- newSymbolContext\n  final <- simulateFinal plan symbols prefix\n  case final of\n    Nothing -> pure (prefix, replicate threads [])\n    Just state -> do\n      branches <- forM [1 .. threads] $ \\_ -> do\n        n <- drawIO source (drawBelow (toInteger branchLength))\n        generateBranch plan source state (1 + n) size\n      -- Drop the last step of the longest branch (the first, among equals)\n      -- until every interleaving is allowed.\n      let trim bs = do\n            allowed <- parallelAllowed plan (prefix, bs)\n            if allowed then pure (prefix, bs) else do\n              let longest = maximum (map length bs)\n                  i = length (takeWhile ((/= longest) . length) bs)\n              trim [if j == i then init b else b | (j, b) <- zip [0 :: Int ..] bs]\n      trim branches\n\n-- | Nothing, a yield, or a sleep of 10 or 100 microseconds.\nperturb :: IORef Word64 -> IO ()\nperturb source = do\n  choice <- drawIO source (drawBelow 4)\n  case choice of\n    0 -> pure ()\n    1 -> yield\n    2 -> threadDelay 10\n    _ -> threadDelay 100\n\nbranchName :: Int -> String\nbranchName i = [chr (ord 'A' + i)]\n\n-- | Nothing when the history is linearizable; otherwise what went wrong.\nexecuteParallel :: ModelPlan -> ParallelCase -> Word64 -> IO (Maybe String)\nexecuteParallel plan (prefix@(startArgs, steps), branches) shake = do\n  symbols <- newSymbolContext\n  let withState command state args = take (mcState command) args ++ [state] ++ drop (mcState command) args\n  prepared <- try (do\n    state <- callOrRaise (planStartRun plan) symbols startArgs\n    mapM_ (\\(index, args) -> let command = planCommands plan !! index\n      in callOrRaise (mcRun command) symbols (withState command state args)) steps\n    pure state)\n  case prepared of\n    Left e -> pure (Just (\"the prefix raised error: \" ++ case fromException e of\n      Just (ModelRaised message) -> message\n      _ -> exceptionText e))\n    Right state -> do\n      clock <- newIORef (0 :: Int)\n      errors <- newIORef []\n      let tick = atomicModifyIORef' clock (\\c -> (c + 1, c + 1))\n          branch i steps' = do\n            own <- newSymbolContext\n            source <- newIORef (shake `xor` (fromIntegral (i + 1) * 0x9E3779B97F4A7C15))\n            forM steps' $ \\(index, args) -> do\n              let command = planCommands plan !! index\n              perturb source\n              called <- tick\n              -- callModel forces the result in full, so the effect happens here.\n              out <- callModel (mcRun command) own (withState command state args)\n              result <- case out of\n                Left message -> do\n                  atomicModifyIORef' errors (\\es -> (es ++ [mcName command ++ \" raised error: \" ++ message], ()))\n                  pure (SAbsent \"Unit\")\n                Right value -> pure value\n              returned <- tick\n              perturb source\n              pure (called, returned, result)\n      dones <- forM (zip [0 :: Int ..] branches) $ \\(i, steps') -> do\n        done <- newEmptyMVar\n        _ <- forkIO (try (branch i steps') >>= putMVar done)\n        pure done\n      outcomes <- mapM takeMVar dones\n      raised <- readIORef errors\n      case (raised, [e | Left e <- outcomes]) of\n        (message : _, _) -> pure (Just message)\n        ([], e : _) -> pure (Just (\"raised error: \" ++ exceptionText e))\n        ([], []) -> do\n          let history = [h | Right h <- outcomes]\n          expectedFinal <- simulateFinal plan symbols prefix\n          final <- case planAbstract plan of\n            Nothing -> pure (Right Nothing)\n            Just abstract -> fmap Just <$> callModel abstract symbols [state]\n          case (expectedFinal, final) of\n            (Nothing, _) -> pure (Just \"the model does not allow this step\")\n            (_, Left message) -> pure (Just (\"raised error: \" ++ message))\n            (Just expected, Right actual) -> do\n              found <- linearizable plan symbols branches history expected actual state\n              let observed = intercalate \"; \"\n                    [ branchName i ++ \": \" ++ mcName (planCommands plan !! fst (branches !! i !! k))\n                      ++ \"() returned \" ++ renderValue result\n                    | (i, h) <- zip [0 ..] history, (k, (_, _, result)) <- zip [0 ..] h ]\n              pure (if found then Nothing\n                else Just (\"no order of the parallel calls agrees with the model (\" ++ observed ++ \")\"))\n\n-- | Whether the history linearizes, with the final state and invariants the\n-- model gives. For a set or map whose every call touches one key, each key's\n-- calls are linearized separately (the keys are independent), one group\n-- after another; otherwise all calls at once.\nlinearizable :: ModelPlan -> SymbolContext -> [[(Int, [Scalar])]] -> [[(Int, Int, Scalar)]]\n             -> Scalar -> Maybe Scalar -> Scalar -> IO Bool\nlinearizable plan symbols branches history expected0 final state\n  | not (planPerKey plan) = linearize plan symbols branches history expected0 finish\n  | otherwise = groups keys expected0\n  where\n    finish modelState =\n      if maybe False (\\actual -> compareValues actual modelState /= Right EQ) final then pure False\n      else allM (\\(kind, invariant) -> do\n        holds <- callModel invariant symbols [if kind == \"model\" then modelState else state]\n        pure (case holds of Right (SBool True) -> True; _ -> False)) (planInvariants plan)\n    keyOf (index, args) = case mcKey (planCommands plan !! index) of\n      Just a -> renderValue (args !! a)\n      Nothing -> error \"per-key model command without a key\"\n    calls = [zip branch h | (branch, h) <- zip branches history]\n    keys = sort (nub [keyOf step | branch <- branches, step <- branch])\n    groups [] modelState = finish modelState\n    groups (key : rest) modelState = do\n      let parts = [[c | c@(step, _) <- branch, keyOf step == key] | branch <- calls]\n      ends <- newIORef Nothing\n      found <- linearize plan symbols (map (map fst) parts) (map (map snd) parts) modelState\n        (\\end -> writeIORef ends (Just end) >> pure True)\n      if not found then pure False else do\n        end <- readIORef ends\n        maybe (pure False) (groups rest) end\n\n-- | A Wing-Gong search: linearize, next, a call no pending call on another\n-- thread returned before; memoized on positions and the model state. The\n-- last argument judges each complete order's final model state.\n--\n-- ref:wing-gong-linearizability\nlinearize :: ModelPlan -> SymbolContext -> [[(Int, [Scalar])]] -> [[(Int, Int, Scalar)]]\n              -> Scalar -> (Scalar -> IO Bool) -> IO Bool\nlinearize plan symbols branches history expected0 finish\n  -- Threads that never message each other see only their own calls.\n  | mode == \"causal\" = allM replay (zip branches history)\n  | otherwise = search\n  where\n    mode = planConsistency plan\n    replay (branch, calls) = go expected0 (zip branch calls)\n      where\n        go _ [] = pure True\n        go state (((index, args), (_, _, result)) : rest) = do\n          let command = planCommands plan !! index\n          stepped <- try (stepModel command symbols args state)\n          case stepped of\n            Left (_ :: ModelStop) -> pure False\n            Right (after, wanted)\n              | not (mcUnit command) && compareValues result wanted /= Right EQ -> pure False\n              | otherwise -> go after rest\n    search = searchOrders plan symbols branches history expected0 finish\n\n-- | The Wing-Gong search itself, by the plan's consistency: sequential\n-- drops real time, eventual checks no results.\nsearchOrders :: ModelPlan -> SymbolContext -> [[(Int, [Scalar])]] -> [[(Int, Int, Scalar)]]\n              -> Scalar -> (Scalar -> IO Bool) -> IO Bool\nsearchOrders plan symbols branches history expected0 finish = do\n  seen <- newIORef []\n  let threads = length branches\n      lengths = map length branches\n      returnedAt j k = let (_, r, _) = history !! j !! k in r\n      visit positions modelState = do\n        old <- seenBefore seen (positions, renderValue modelState)\n        if old then pure False\n        else if and (zipWith (==) positions lengths) then finish modelState\n        else anyM (next positions modelState) [0 .. threads - 1]\n      next positions modelState i = do\n        let k = positions !! i\n        if k == lengths !! i then pure False else do\n          let (called, _, result) = history !! i !! k\n              blocked = planConsistency plan == \"linearizable\" &&\n                or [ positions !! j < lengths !! j && returnedAt j (positions !! j) < called\n                   | j <- [0 .. threads - 1], j /= i ]\n          if blocked then pure False else do\n            let (index, args) = branches !! i !! k\n                command = planCommands plan !! index\n            stepped <- try (stepModel command symbols args modelState)\n            case stepped of\n              Left ModelInvalid -> pure False\n              Left (ModelRaised _) -> pure False\n              Right (after, wanted)\n                | planConsistency plan /= \"eventual\" && not (mcUnit command) && compareValues result wanted /= Right EQ -> pure False\n                | otherwise -> visit (advanceAt i positions) after\n  visit (map (const 0) branches) expected0\n\n-- | How a failure names a consistency model.\nconsistentWord :: String -> String\nconsistentWord mode = case mode of\n  \"sequential\" -> \"sequentially consistent\"\n  \"causal\" -> \"causally consistent\"\n  \"eventual\" -> \"eventually consistent\"\n  _ -> \"linearizable\"\n\n-- | The first failure of repeated runs, run k shaken with shake + k.\nparallelFails :: ModelPlan -> ParallelCase -> Int -> Word64 -> IO (Maybe String)\nparallelFails plan parallelCase repeats shake = go 0\n  where\n    go attempt\n      | attempt >= repeats = pure Nothing\n      | otherwise = do\n          failure <- executeParallel plan parallelCase (shake + fromIntegral attempt)\n          case failure of\n            Just _ -> pure failure\n            Nothing -> go (attempt + 1)\n\n-- | Smaller cases: dropping each prefix step, then each branch step, then\n-- smaller arguments, branch by branch, step by step.\nparallelCandidates :: ModelPlan -> ParallelCase -> [ParallelCase]\nparallelCandidates plan (prefix@(startArgs, steps), branches) =\n  [ ((startArgs, dropAt k steps), branches) | k <- [0 .. length steps - 1] ]\n  ++ [ (prefix, [if j == i then dropAt k b else b | (j, b) <- zip [0 :: Int ..] branches])\n     | (i, branch) <- zip [0 ..] branches, k <- [0 .. length branch - 1] ]\n  ++ [ (prefix, [if j == i then replace k (index, replace a c args) b else b | (j, b) <- zip [0 :: Int ..] branches])\n     | (i, branch) <- zip [0 ..] branches\n     , (k, (index, args)) <- zip [0 ..] branch\n     , (a, (d, arg)) <- zip [0 ..] (zip (mcArguments (planCommands plan !! index)) args)\n     , c <- shrinkValue (planTable plan) d arg ]\n  where dropAt k xs = take k xs ++ drop (k + 1) xs\n        replace k x xs = take k xs ++ [x] ++ drop (k + 1) xs\n\nshrinkParallel :: ModelPlan -> ParallelCase -> String -> Int -> Int -> Word64 -> IO (ParallelCase, String)\nshrinkParallel plan parallelCase failure repeats budget shake\n  | budget <= 0 = pure (parallelCase, failure)\n  | otherwise = go (parallelCandidates plan parallelCase) budget\n  where\n    go [] _ = pure (parallelCase, failure)\n    go (candidate : rest) b = do\n      let b' = b - 1\n      if b' <= 0 then pure (parallelCase, failure) else do\n        allowed <- parallelAllowed plan candidate\n        if not allowed then go rest b' else do\n          found <- parallelFails plan candidate repeats shake\n          case found of\n            Just failure' -> shrinkParallel plan candidate failure' repeats b' shake\n            Nothing -> go rest b'\n\ndescribeParallel :: ModelPlan -> ParallelCase -> String\ndescribeParallel plan (prefix, branches) =\n  let call (i, args) = mcName (planCommands plan !! i) ++ \"(\" ++ intercalate \", \" (map renderValue args) ++ \")\"\n      describe steps = if null steps then \"nothing\" else intercalate \"; \" (map call steps)\n      parts = [branchName i ++ \": \" ++ describe b | (i, b) <- zip [0 ..] branches]\n  in describeRun plan prefix ++ \", then \" ++ intercalate \", \" (init parts) ++ \" and \" ++ last parts\n       ++ \" at the same time\"\n\n-- | Checks a shared model's histories under concurrency: Nothing, or the\n-- failure naming the smallest failing case found. 50 cases, each run 10\n-- times, 300 shrinks, 3 threads of up to 5 steps, seeded from LAWSPEC_SEED\n-- or 0.\n--\n-- A shared model promises linearizability unless it names a weaker consistency,\n-- so concurrent histories are judged against some sequential order of the\n-- calls. ref:herlihy-wing-linearizability\n-- ref:DEC-stateful-models-linearizability\ncheckModelParallel :: Model -> IO (Maybe String)\ncheckModelParallel = checkModelParallelWith 50 10 300 parallelThreads parallelBranch Nothing\n\n-- | checkModelParallel with the number of cases, the runs of each case, the\n-- shrink budget, the threads, the longest branch and the seed (Nothing:\n-- LAWSPEC_SEED, else 0).\ncheckModelParallelWith :: Int -> Int -> Int -> Int -> Int -> Maybe Word64 -> Model -> IO (Maybe String)\ncheckModelParallelWith cases repeats maxShrinks threads branchLength seedOverride model = do\n  seed <- case seedOverride of\n    Just s -> pure s\n    Nothing -> maybe 0 (fromInteger . read) <$> lookupEnv \"LAWSPEC_SEED\"\n  source <- newIORef (seed `xor` 0x5BD1E995)\n  let plan = modelPlan model\n      loop c\n        | c >= cases = pure Nothing\n        | otherwise = do\n            parallelCase <- generateParallel plan source (1 + toInteger (c `mod` 8)) threads branchLength\n            shake <- drawIO source (Draw splitMix64)\n            failure <- parallelFails plan parallelCase repeats shake\n            case failure of\n              Nothing -> loop (c + 1)\n              Just found -> do\n                (parallelCase', message) <- shrinkParallel plan parallelCase found (max 2 (repeats `div` 2)) maxShrinks shake\n                pure (Just (\"model \" ++ planName plan ++ \" is not \" ++ consistentWord (planConsistency plan) ++ \": \"\n                  ++ describeParallel plan parallelCase' ++ \": \" ++ message))\n  loop 0\n\n-- Scenarios: processes that drive a shared model's commands at the same time\n-- and talk over channels (see LawSpec.Core.Program for the spec). Each\n-- channel has a queue per direction; a process holds an end of a channel as\n-- (channel, side), the first branch of a par to use a channel taking side 0.\n-- A channel end sent over a channel moves to the receiver. Every command's\n-- call and return are stamped on one counter; the history must linearize\n-- against the model, and every expect must hold, on each of many schedules.\n-- A process that ends, or fails, gives up the ends it still holds (and ends\n-- on their way to it): the other side's receives then fail instead of\n-- waiting, unless written with or else. Every third run crashes one\n-- process of a par at a random point.\n\n-- | A blocking queue with one reader at a time.\ndata ScenarioQueue = ScenarioQueue (MVar ([ScenarioItem], [ScenarioItem])) (MVar ())\n\nnewScenarioQueue :: IO ScenarioQueue\nnewScenarioQueue = ScenarioQueue <$> newMVar ([], []) <*> newEmptyMVar\n\npushQueue :: ScenarioQueue -> ScenarioItem -> IO ()\npushQueue (ScenarioQueue items signal) item = do\n  modifyMVar items (\\(front, back) -> pure ((front, item : back), ()))\n  _ <- tryPutMVar signal ()\n  pure ()\n\ntryPopQueue :: ScenarioQueue -> IO (Maybe ScenarioItem)\ntryPopQueue (ScenarioQueue items _) = modifyMVar items (\\(front, back) -> pure (case front of\n  x : rest -> ((rest, back), Just x)\n  [] -> case reverse back of\n    x : rest -> ((rest, []), Just x)\n    [] -> (([], []), Nothing)))\n\n-- | The next item, waiting up to the given microseconds.\npopQueue :: ScenarioQueue -> Int -> IO (Maybe ScenarioItem)\npopQueue queue@(ScenarioQueue _ signal) micros = do\n  item <- tryPopQueue queue\n  case item of\n    Just x -> pure (Just x)\n    Nothing -> do\n      woke <- timeout micros (takeMVar signal)\n      case woke of\n        Nothing -> tryPopQueue queue\n        Just () -> popQueue queue micros\n\n-- | A scenario channel: its number and name, then either two queues (side\n-- s sends on queue s and receives from queue 1 - s) and whether each side's\n-- process has ended, or, in a network run, an end per side on two nodes of\n-- a faulty in-memory network, with the run's channels by name (a channel end\n-- sent over the network travels as \"<name>#<side>\").\ndata ScenarioChannel = ScenarioChannel\n  { channelNumber :: Int\n  , channelName :: String\n  , channelKind :: ChannelKind\n  }\n\ndata ChannelKind\n  = LocalChannel ScenarioQueue ScenarioQueue (MVar (Bool, Bool))\n  | NetChannel [Node] [NetEndpoint] (MVar (Bool, Bool)) (IORef [(String, ScenarioChannel)])\n\n-- | A value, a channel end in transit, or the mark that the sender ended.\ndata ScenarioItem = ScenarioValue Scalar | ScenarioEnd (ScenarioChannel, Int) | ScenarioGone\n\nnewScenarioChannel :: Int -> String -> IO ScenarioChannel\nnewScenarioChannel n name = ScenarioChannel n name <$> (LocalChannel <$> newScenarioQueue <*> newScenarioQueue <*> newMVar (False, False))\n\n-- | A channel whose sides are ends on two nodes of the network.\nnewNetScenarioChannel :: MemoryNetwork -> IORef [(String, ScenarioChannel)] -> DataTable -> [(Bool, Descriptor)]\n                      -> Int -> String -> IO ScenarioChannel\nnewNetScenarioChannel network registry table steps n name = do\n  let wire (sends, d) = (sends, if d == DescList [DescAtom \"end\"] then DescList [DescAtom \"text\"] else d)\n  first <- newNode (insecureTransportForTests network (name ++ \"-0\"))\n  second <- newNode (insecureTransportForTests network (name ++ \"-1\"))\n  listener <- listenOn first name (map wire steps) table\n  dialer <- dialTo second (nodeAddress first ++ \"/\" ++ name) [wire (not s, d) | (s, d) <- steps] table\n  channel <- ScenarioChannel n name <$> (NetChannel [first, second] [listener, dialer] <$> newMVar (False, False) <*> pure registry)\n  atomicModifyIORef' registry (\\r -> ((name, channel) : r, ()))\n  pure channel\n\ncloseScenarioChannel :: ScenarioChannel -> IO ()\ncloseScenarioChannel channel = case channelKind channel of\n  NetChannel nodes _ _ _ -> mapM_ closeNode nodes\n  _ -> pure ()\n\nscenarioQueue :: ScenarioChannel -> Int -> ScenarioQueue\nscenarioQueue channel side = case channelKind channel of\n  LocalChannel first second _ -> if side == 0 then first else second\n  _ -> error \"a network channel has no queues\"\n\nsideEnded :: (Bool, Bool) -> Int -> Bool\nsideEnded (a, b) side = if side == 0 then a else b\n\n-- | Sends from side; a channel end sent to a process that has ended is\n-- given up.\nscenarioSend :: ScenarioChannel -> Int -> ScenarioItem -> IO ()\nscenarioSend channel side item = case channelKind channel of\n  LocalChannel _ _ ended -> do\n    stranded <- modifyMVar ended (\\flags -> case item of\n      ScenarioEnd end | sideEnded flags (1 - side) -> pure (flags, Just end)\n      _ -> pushQueue (scenarioQueue channel side) item >> pure (flags, Nothing))\n    forM_ stranded (\\(c, s) -> scenarioGone c s)\n  NetChannel _ ends _ _ -> case item of\n    ScenarioValue v -> endpointSend (ends !! side) v\n    ScenarioEnd (c, s) -> endpointSend (ends !! side) (textScalar (channelName c ++ \"#\" ++ show s))\n    ScenarioGone -> pure ()\n\n-- | The next item for side, waiting up to the given microseconds (Nothing\n-- when none arrives); once the other side has ended, ScenarioGone, again\n-- and again.\nscenarioReceive :: ScenarioChannel -> Int -> Int -> IO (Maybe ScenarioItem)\nscenarioReceive channel side micros = case channelKind channel of\n  LocalChannel {} -> do\n    let queue = scenarioQueue channel (1 - side)\n    got <- popQueue queue micros\n    case got of\n      Just ScenarioGone -> pushQueue queue ScenarioGone >> pure (Just ScenarioGone)\n      other -> pure other\n  NetChannel _ ends _ registry -> do\n    got <- try (endpointReceiveValue (ends !! side) (Just micros))\n    case got of\n      Left e | Just PeerFailed <- fromException e -> pure (Just ScenarioGone)\n             | otherwise -> pure Nothing\n      Right value@(SSequence _ cps) -> do\n        let text = map chr cps\n            (sideRev, rest) = break (== '#') (reverse text)\n            owner = reverse (drop 1 rest)\n        known <- lookup owner <$> readIORef registry\n        pure (Just (case known of\n          Just c | not (null rest), all isDigit sideRev, not (null sideRev) -> ScenarioEnd (c, read (reverse sideRev))\n          _ -> ScenarioValue value))\n      Right value -> pure (Just (ScenarioValue value))\n\n-- | side's process has ended: the other side's receives that find nothing\n-- more fail instead of waiting, and channel ends on their way to side are\n-- given up too.\nscenarioGone :: ScenarioChannel -> Int -> IO ()\nscenarioGone channel side = case channelKind channel of\n  LocalChannel _ _ ended -> do\n    stranded <- modifyMVar ended (\\flags -> if sideEnded flags side then pure (flags, []) else do\n      pushQueue (scenarioQueue channel side) ScenarioGone\n      let drain acc = do\n            item <- tryPopQueue (scenarioQueue channel (1 - side))\n            case item of\n              Nothing -> pure acc\n              Just (ScenarioEnd end) -> drain (end : acc)\n              Just ScenarioGone -> pushQueue (scenarioQueue channel (1 - side)) ScenarioGone >> pure acc\n              Just _ -> drain acc\n      found <- drain []\n      pure (if side == 0 then (True, snd flags) else (fst flags, True), reverse found))\n    mapM_ (\\(c, s) -> scenarioGone c s) stranded\n  NetChannel _ ends ended _ -> do\n    first <- modifyMVar ended (\\flags -> pure (if sideEnded flags side then (flags, False)\n      else (if side == 0 then (True, snd flags) else (fst flags, True), True)))\n    if first then endpointAbandon (ends !! side) else pure ()\n\n-- | A scenario's mailbox: any process sends, one receives. expected is how\n-- many sends the scenario makes; a process that ends gives up the sends it\n-- did not make, and a receive with nothing left to come is ScenarioGone\n-- instead of waiting. Over a network, messages go from a sender node to the\n-- receiver's node, each send waiting until it is delivered; the senders'\n-- clocks travel beside the network, in send order.\ndata ScenarioMailbox = ScenarioMailbox\n  { boxExpected :: Int\n  -- (received, abandoned)\n  , boxCounts :: MVar (Int, Int)\n  , boxItems :: MVar [(ScenarioItem, VectorClock)]\n  , boxSignal :: MVar ()\n  , boxNet :: Maybe ([Node], Mailbox Scalar, RemoteMailbox, IORef [(String, ScenarioChannel)])\n  }\n\nnewScenarioMailbox :: Int -> IO ScenarioMailbox\nnewScenarioMailbox expected = ScenarioMailbox expected <$> newMVar (0, 0) <*> newMVar [] <*> newEmptyMVar <*> pure Nothing\n\nnewNetScenarioMailbox :: MemoryNetwork -> IORef [(String, ScenarioChannel)] -> DataTable -> Descriptor -> String -> Int -> IO ScenarioMailbox\nnewNetScenarioMailbox network registry table d0 name expected = do\n  let d = if d0 == DescList [DescAtom \"end\"] then DescList [DescAtom \"text\"] else d0\n  owner <- newNode (insecureTransportForTests network (name ++ \"-owner\"))\n  senders <- newNode (insecureTransportForTests network (name ++ \"-senders\"))\n  inbox <- nodeMailbox owner name table d\n  let remote = remoteMailboxWithin senders (nodeAddress owner ++ \"/\" ++ name) table d 5\n  box <- newScenarioMailbox expected\n  pure box { boxNet = Just ([owner, senders], inbox, remote, registry) }\n\ncloseScenarioMailbox :: ScenarioMailbox -> IO ()\ncloseScenarioMailbox box = forM_ (boxNet box) (\\(nodes, _, _, _) -> mapM_ closeNode nodes)\n\nmailboxSend :: ScenarioMailbox -> ScenarioItem -> VectorClock -> IO ()\nmailboxSend box item clock = case boxNet box of\n  Nothing -> do\n    modifyMVar (boxItems box) (\\items -> pure (items ++ [(item, clock)], ()))\n    () <$ tryPutMVar (boxSignal box) ()\n  Just (_, _, remote, _) -> do\n    modifyMVar (boxItems box) (\\items -> pure (items ++ [(ScenarioGone, clock)], ()))\n    sendRemote remote (case item of\n      ScenarioEnd (c, s) -> textScalar (channelName c ++ \"#\" ++ show s)\n      ScenarioValue v -> v\n      ScenarioGone -> textScalar \"\")\n    () <$ tryPutMVar (boxSignal box) ()\n\nmailboxGiveUp :: ScenarioMailbox -> Int -> IO ()\nmailboxGiveUp box count = do\n  modifyMVar (boxCounts box) (\\(r, a) -> pure ((r, a + count), ()))\n  () <$ tryPutMVar (boxSignal box) ()\n\n-- | The next message with its sender's clock, or ScenarioGone; Nothing after\n-- the given microseconds.\nmailboxReceive :: ScenarioMailbox -> Int -> IO (Maybe (ScenarioItem, VectorClock))\nmailboxReceive box micros = do\n  start <- getMonotonicTimeNSec\n  let deadline = start + fromIntegral micros * 1000\n      loop = do\n        (received, abandoned) <- readMVar (boxCounts box)\n        items <- readMVar (boxItems box)\n        case boxNet box of\n          Nothing -> case items of\n            first : _ -> do\n              modifyMVar (boxItems box) (\\is -> pure (drop 1 is, ()))\n              modifyMVar (boxCounts box) (\\(r, a) -> pure ((r + 1, a), ()))\n              pure (Just first)\n            []\n              | received + abandoned >= boxExpected box -> pure (Just (ScenarioGone, []))\n              | otherwise -> wait\n          Just (_, inbox, _, registry)\n            | received + abandoned >= boxExpected box && null items -> pure (Just (ScenarioGone, []))\n            | otherwise -> do\n                got <- receiveMailboxWithin 20000 inbox\n                case got of\n                  Nothing -> again\n                  Just value -> do\n                    modifyMVar (boxCounts box) (\\(r, a) -> pure ((r + 1, a), ()))\n                    clock <- modifyMVar (boxItems box) (\\is -> pure (case is of\n                      (_, c) : rest -> (rest, c)\n                      [] -> ([], [])))\n                    item <- case value of\n                      SSequence _ cps -> do\n                        let text = map chr cps\n                            (sideRev, rest) = break (== '#') (reverse text)\n                            owner = reverse (drop 1 rest)\n                        known <- lookup owner <$> readIORef registry\n                        pure (case known of\n                          Just c | not (null rest), all isDigit sideRev, not (null sideRev) -> ScenarioEnd (c, read (reverse sideRev))\n                          _ -> ScenarioValue value)\n                      _ -> pure (ScenarioValue value)\n                    pure (Just (item, clock))\n      wait = do\n        now <- getMonotonicTimeNSec\n        if now >= deadline then pure Nothing else do\n          _ <- timeout (max 1 (min 20000 (fromIntegral ((deadline - now) `div` 1000)))) (takeMVar (boxSignal box))\n          loop\n      again = do\n        now <- getMonotonicTimeNSec\n        if now >= deadline then pure Nothing else loop\n  loop\n\n-- | How many times these acts (not nested pars) send to name.\nscenarioSends :: [Descriptor] -> String -> Int\nscenarioSends acts name = length [() | DescList [DescAtom \"send\", c, _] <- acts, descriptorName c == name]\n\n-- | How many sends to name the whole program makes.\nallSends :: [Descriptor] -> String -> Int\nallSends acts name = sum (map one acts)\n  where\n    one act = case act of\n      DescList [DescAtom \"send\", c, _] | descriptorName c == name -> 1\n      DescList (DescAtom \"par\" : branches) -> sum [allSends (branchActs b) name | b <- branches]\n      _ -> 0\n\n-- | The names an act list sends, receives or sends away, with nested pars.\nactsChannels :: [Descriptor] -> [String]\nactsChannels = concatMap names\n  where\n    names act = case act of\n      DescList [DescAtom \"send\", c, operand] -> descriptorName c : case operand of\n        DescList [DescAtom \"var\", x] -> [descriptorName x]\n        _ -> []\n      DescList (DescAtom \"receive\" : c : _) -> [descriptorName c]\n      DescList [DescAtom \"receiveor\", c, _, DescList (_ : handler)] -> descriptorName c : actsChannels handler\n      DescList (DescAtom \"par\" : branches) -> concat [actsChannels (branchActs b) | b <- branches]\n      _ -> []\n\n-- | A par branch's acts (numbered branches carry their number first).\nbranchActs :: Descriptor -> [Descriptor]\nbranchActs form = case form of\n  DescList (_ : DescInteger _ : acts) -> acts\n  DescList (_ : acts) -> acts\n  _ -> []\n\n-- | Numbers every par branch, outermost and first first (not inside or\n-- else), as (process n acts...); and how many acts each has.\nnumberBranches :: [Descriptor] -> ([Descriptor], [Int])\nnumberBranches body = let (acts, (_, lengths)) = goActs body (0, []) in (acts, reverse lengths)\n  where\n    goActs [] st = ([], st)\n    goActs (act : rest) st =\n      let (act', st') = goAct act st\n          (rest', st'') = goActs rest st'\n      in (act' : rest', st'')\n    goAct (DescList (DescAtom \"par\" : branches)) st =\n      let step (acc, s) (DescList (h : acts)) =\n            let (n, ls) = s\n                (acts', s') = goActs acts (n + 1, length acts : ls)\n            in (acc ++ [DescList (h : DescInteger (toInteger n) : acts')], s')\n          step (acc, s) other = (acc ++ [other], s)\n          (branches', st') = foldl step ([], st) branches\n      in (DescList (DescAtom \"par\" : branches'), st')\n    goAct other st = (other, st)\n\nscenarioConstant :: Descriptor -> Scalar\nscenarioConstant form = case form of\n  DescList [DescAtom \"int\", DescInteger n] -> SInteger \"Integer\" n\n  DescList [DescAtom \"text\", t] -> textScalar (descriptorName t)\n  DescList [DescAtom \"bool\", b] -> SBool (descriptorName b == \"true\")\n  DescList [_, t] -> SData (descriptorName t) []\n  _ -> error (\"invalid scenario constant \" ++ show form)\n\n-- | A call in a scenario's history: command, arguments, result, called,\n-- returned, its process, and the process's vector clock at the call and at\n-- the return.\ntype ScenarioCall = (ModelCommand, [Scalar], Scalar, Int, Int, String, VectorClock, VectorClock)\n\n-- | Each process's count of its events, as far as this process knows.\ntype VectorClock = [(String, Int)]\n\ntickClock :: String -> VectorClock -> VectorClock\ntickClock me clock = (me, maybe 1 (+ 1) (lookup me clock)) : filter ((/= me) . fst) clock\n\nmergeClock :: VectorClock -> VectorClock -> VectorClock\nmergeClock a b = [(p, max (maybe 0 id (lookup p a)) (maybe 0 id (lookup p b))) | p <- nub (map fst a ++ map fst b)]\n\n-- | The scenario's title and its failure on one schedule, if any.\nrunScenario :: Model -> String -> Word64 -> IO (String, Maybe String)\nrunScenario model spec shake = runScenarioWith False False model spec shake\n\n-- | runScenario, with crash: one process of a par crashes before a random act.\n-- With network, each channel's two sides are ends on two nodes of a\n-- faulty in-memory network (when the spec gives the channels' types).\nrunScenarioWith :: Bool -> Bool -> Model -> String -> Word64 -> IO (String, Maybe String)\nrunScenarioWith crash network model spec shake = do\n  let forms = readDescriptor spec\n      title = case forms of\n        DescList (_ : t : _) : _ -> descriptorName t\n        _ -> error \"invalid scenario spec\"\n      names = concat (take 1 [map descriptorName rest | DescList (DescAtom \"channels\" : rest) <- forms])\n      (body, lengths) = numberBranches (concat (take 1 [rest | DescList (DescAtom \"process\" : rest) <- forms]))\n      plan = modelPlan model\n      commandNamed n = case find ((== n) . mcName) (planCommands plan) of\n        Just command -> command\n        Nothing -> error (\"unknown command \" ++ n)\n  victim <- if crash && not (null lengths) then do\n      chooser <- newIORef (shake `xor` 0xC3A5C85C97CB3127)\n      branch <- drawIO chooser (drawBelow (toInteger (length lengths)))\n      at <- drawIO chooser (drawBelow (toInteger (lengths !! fromInteger branch) + 1))\n      pure (Just (fromInteger branch :: Int, fromInteger at :: Int))\n    else pure Nothing\n  let wire = concat (take 1 [rest | DescList (DescAtom \"wire\" : rest) <- forms])\n      wireTable = [(descriptorName n, f) | f@(DescList (DescAtom \"data\" : n : _)) <- wire]\n      wireSteps = [ (descriptorName c, [(descriptorName k == \"send\", d) | DescList [k, d] <- steps])\n                  | DescList (DescAtom \"channel\" : c : steps) <- wire ]\n  let boxNames = concat (take 1 [map descriptorName rest | DescList (DescAtom \"mailboxes\" : rest) <- forms])\n      wireBoxes = [(descriptorName m, d) | DescList [DescAtom \"mailbox\", m, d] <- wire]\n  (channels, mailboxes) <- if network && not (null [() | DescList (DescAtom \"wire\" : _) <- forms])\n    then do\n      -- Loss, duplication and delay (which reorders); the channels'\n      -- numbered, acknowledged frames must hide them all.\n      net <- newMemoryNetwork (shake `xor` 0x7F4A7C159E3779B9) 0.1 0.1 0.002\n      registry <- newIORef []\n      cs <- forM (zip [0 ..] names) $ \\(i, n) ->\n        (,) n <$> newNetScenarioChannel net registry wireTable (maybe [] id (lookup n wireSteps)) i n\n      bs <- forM boxNames $ \\m -> (,) m <$> case lookup m wireBoxes of\n        Just d -> newNetScenarioMailbox net registry wireTable d m (allSends body m)\n        Nothing -> newScenarioMailbox (allSends body m)\n      pure (cs, bs)\n    else do\n      cs <- forM (zip [0 ..] names) $ \\(i, n) -> (,) n <$> newScenarioChannel i n\n      bs <- forM boxNames $ \\m -> (,) m <$> newScenarioMailbox (allSends body m)\n      pure (cs, bs)\n  symbols <- newSymbolContext\n  let startArgs = map (minimalValue (planTable plan)) (planStartArguments plan)\n  outcome <- try $ do\n    state <- callOrRaise (planStartRun plan) symbols startArgs\n    expected <- callOrRaise (planStartModel plan) symbols startArgs\n    clock <- newIORef (0 :: Int)\n    history <- newIORef ([] :: [ScenarioCall])\n    stamps <- newIORef ([] :: [((Int, Int), [VectorClock])])\n    failures <- newIORef ([] :: [String])\n    let tick = atomicModifyIORef' clock (\\c -> (c + 1, c + 1))\n        failWith message = atomicModifyIORef' failures (\\fs -> (fs ++ [message], ())) >> pure False\n        bind name value pairs = (name, value) : filter ((/= name) . fst) pairs\n        valueOf env operand = case operand of\n          DescList [DescAtom \"var\", x] -> case lookup (descriptorName x) env of\n            Just value -> value\n            Nothing -> error (\"unbound scenario variable \" ++ descriptorName x)\n          _ -> scenarioConstant operand\n        endOf ends c = case lookup (descriptorName c) ends of\n          Just end -> end\n          Nothing -> error (\"no end of channel \" ++ descriptorName c)\n        -- True when the process finished, False when it failed; either way\n        -- the ends it still holds are given up.\n        -- Vector clocks: each value sent carries its sender's clock (kept\n        -- here, in order per channel direction), so calls can be ordered by\n        -- what happened before what.\n        stamp channel side clock = atomicModifyIORef' stamps (\\st ->\n          let key = (channelNumber channel, side) in ((key, maybe [] id (lookup key st) ++ [clock]) : filter ((/= key) . fst) st, ()))\n        unstamp channel side clockRef me = do\n          sent <- atomicModifyIORef' stamps (\\st ->\n            let key = (channelNumber channel, 1 - side) in case lookup key st of\n              Just (c : rest) -> ((key, rest) : filter ((/= key) . fst) st, c)\n              _ -> (st, []))\n          modifyIORef' clockRef (tickClock me . mergeClock sent)\n        process acts env0 ends0 source identity clockRef = do\n          held <- newIORef ends0\n          sentRef <- newIORef ([] :: [(String, Int)])\n          let me = maybe \"root\" show identity\n              -- Sends this process will never make.\n              giveUp = forM_ mailboxes $ \\(m, box) -> do\n                made <- maybe 0 id . lookup m <$> readIORef sentRef\n                let missing = scenarioSends acts m - made\n                if missing > 0 then mailboxGiveUp box missing else pure ()\n          done <- (steps acts env0 ends0 source identity held clockRef me sentRef\n            `catch` \\(e :: SomeException) -> failWith (\"raised error: \" ++ exceptionText e))\n            `finally` (readIORef held >>= mapM_ (\\(_, (c, s)) -> scenarioGone c s)) `finally` giveUp\n          pure done\n        steps acts env0 ends0 source identity held clockRef me sentRef = do\n          own <- newSymbolContext\n          let crashesAt index = case (victim, identity) of\n                (Just v, Just i) -> v == (i, index)\n                _ -> False\n              go index [] _ ends = writeIORef held ends >> pure (not (crashesAt index))\n              go index (act : rest) env ends = do\n                writeIORef held ends\n                failed <- not . null <$> readIORef failures\n                if failed || crashesAt index then pure False else case act of\n                  DescList (DescAtom \"call\" : nameForm : bound : operands) -> do\n                    let command = commandNamed (descriptorName nameForm)\n                        -- An integer constant takes the argument's own type.\n                        typed d value = case (d, value) of\n                          (DescList (DescAtom \"int\" : t : _), SInteger _ n) -> SInteger (descriptorName t) n\n                          _ -> value\n                        args = zipWith typed (mcArguments command ++ repeat DescNone) (map (valueOf env) operands)\n                        position = mcState command\n                        full = take position args ++ [state] ++ drop position args\n                    perturb source\n                    modifyIORef' clockRef (tickClock me)\n                    atCall <- readIORef clockRef\n                    called <- tick\n                    -- The result is forced in full here, so the effect (or its\n                    -- error) happens between the call and return stamps.\n                    let run symbols' args' = case mcRun command symbols' args' of\n                          Right value -> forceScalar value `seq` Right value\n                          failure -> failure\n                    out <- callModel run own full\n                    case out of\n                      Left message -> failWith (mcName command ++ \" raised error: \" ++ message)\n                      Right result -> do\n                        returned <- tick\n                        modifyIORef' clockRef (tickClock me)\n                        atReturn <- readIORef clockRef\n                        atomicModifyIORef' history (\\h -> (h ++ [(command, args, result, called, returned, me, atCall, atReturn)], ()))\n                        let env' = case bound of\n                              DescNone -> env\n                              DescAtom \"_\" -> env\n                              _ -> bind (descriptorName bound) result env\n                        go (index + 1) rest env' ends\n                  DescList [DescAtom \"send\", c, operand] | Just box <- lookup (descriptorName c) mailboxes -> do\n                    let (item, ends') = case operand of\n                          DescList [DescAtom \"var\", x] | Just end <- lookup (descriptorName x) ends ->\n                            (ScenarioEnd end, filter ((/= descriptorName x) . fst) ends)\n                          _ -> (ScenarioValue (valueOf env operand), ends)\n                    perturb source\n                    writeIORef held ends'\n                    modifyIORef' clockRef (tickClock me)\n                    sentClock <- readIORef clockRef\n                    outcome <- try (mailboxSend box item sentClock)\n                    case outcome of\n                      Left (e :: SomeException) -> failWith (\"a send to mailbox \" ++ descriptorName c ++ \" failed: \" ++ exceptionText e)\n                      Right () -> do\n                        modifyIORef' sentRef (\\counts -> (descriptorName c, maybe 1 (+ 1) (lookup (descriptorName c) counts))\n                          : filter ((/= descriptorName c) . fst) counts)\n                        go (index + 1) rest env ends'\n                  DescList (DescAtom kind : c : x : handler) | kind == \"receive\" || kind == \"receiveor\"\n                                                            , Just box <- lookup (descriptorName c) mailboxes -> do\n                    got <- mailboxReceive box 5000000\n                    case got of\n                      Nothing -> failWith (\"a receive on mailbox \" ++ descriptorName c\n                        ++ \" waited too long: the processes are blocked\")\n                      Just (ScenarioGone, _) -> case handler of\n                        [DescList (_ : handlerActs)] | kind == \"receiveor\" ->\n                          steps handlerActs env ends source Nothing held clockRef me sentRef\n                        _ -> pure False\n                      Just (item, carried) -> do\n                        modifyIORef' clockRef (tickClock me . mergeClock carried)\n                        case item of\n                          ScenarioEnd end -> go (index + 1) rest env (bind (descriptorName x) end ends)\n                          ScenarioValue value -> go (index + 1) rest (bind (descriptorName x) value env) ends\n                  DescList [DescAtom \"send\", c, operand] -> do\n                    let (channel, side) = endOf ends c\n                        (item, ends') = case operand of\n                          DescList [DescAtom \"var\", x] | Just end <- lookup (descriptorName x) ends ->\n                            (ScenarioEnd end, filter ((/= descriptorName x) . fst) ends)\n                          _ -> (ScenarioValue (valueOf env operand), ends)\n                    perturb source\n                    writeIORef held ends'\n                    modifyIORef' clockRef (tickClock me)\n                    readIORef clockRef >>= stamp channel side\n                    scenarioSend channel side item\n                    go (index + 1) rest env ends'\n                  DescList (DescAtom kind : c : x : handler) | kind == \"receive\" || kind == \"receiveor\" -> do\n                    let (channel, side) = endOf ends c\n                    got <- scenarioReceive channel side 5000000\n                    case got of\n                      Nothing -> failWith (\"a receive on \" ++ descriptorName c\n                        ++ \" waited too long: the processes are blocked\")\n                      -- The other process ended: or else runs instead of the\n                      -- rest; without it, this process fails too.\n                      Just ScenarioGone ->\n                        case handler of\n                          [DescList (_ : handlerActs)] | kind == \"receiveor\" -> do\n                            let ends' = filter ((/= descriptorName c) . fst) ends\n                            writeIORef held ends'\n                            steps handlerActs env ends' source Nothing held clockRef me sentRef\n                          _ -> pure False\n                      Just (ScenarioEnd end) -> do\n                        unstamp channel side clockRef me\n                        go (index + 1) rest env (bind (descriptorName x) end ends)\n                      Just (ScenarioValue value) -> do\n                        unstamp channel side clockRef me\n                        go (index + 1) rest (bind (descriptorName x) value env) ends\n                  DescList (DescAtom \"par\" : branchForms) -> do\n                    let branches = [ case form of\n                                       DescList (_ : DescInteger n : acts) -> (Just (fromInteger n), acts)\n                                       _ -> (Nothing, branchActs form)\n                                   | form <- branchForms ]\n                        addUser owned (name, i) = case lookup name owned of\n                          Nothing -> owned ++ [(name, [i])]\n                          Just users\n                            | i `elem` users -> owned\n                            | otherwise -> [(n, if n == name then us ++ [i] else us) | (n, us) <- owned]\n                        owned = foldl addUser [] [(name, i) | (i, (_, b)) <- zip [0 :: Int ..] branches, name <- actsChannels b]\n                        mine i = [ (name, end) | (name, users) <- owned, i `elem` users\n                                 , end <- case lookup name ends of\n                                     Just held' -> [held']\n                                     Nothing -> case lookup name channels of\n                                       Just channel -> [(channel, length (takeWhile (/= i) users))]\n                                       Nothing -> [] ]\n                        -- Ends handed to the branches are theirs now.\n                        ends' = filter ((`notElem` map fst owned) . fst) ends\n                    writeIORef held ends'\n                    parent <- readIORef clockRef\n                    clocks <- mapM (const (newIORef parent)) branches\n                    dones <- forM (zip3 [0 :: Int ..] branches clocks) $ \\(i, (n, b), branchClock) -> do\n                      finished <- newEmptyMVar\n                      branchSource <- newIORef (shake `xor` (fromIntegral (i + 1) * 0x9E3779B97F4A7C15))\n                      _ <- forkIO (do\n                        ok <- process b env (mine i) branchSource n branchClock `catch` \\(_ :: SomeException) -> pure False\n                        putMVar finished ok)\n                      pure finished\n                    results <- mapM takeMVar dones\n                    children <- mapM readIORef clocks\n                    writeIORef clockRef (tickClock me (foldr mergeClock parent children))\n                    -- A failed branch fails the process that ran the par.\n                    if and results then go (index + 1) rest env ends' else pure False\n                  DescList [DescAtom \"expect\", x, c] -> do\n                    let name = descriptorName x\n                        wanted = scenarioConstant c\n                        actual = lookup name env\n                    if maybe True (\\a -> compareValues a wanted /= Right EQ) actual\n                      then failWith (\"expect \" ++ name ++ \" = \" ++ renderValue wanted ++ \" failed: \"\n                        ++ name ++ \" is \" ++ maybe \"None\" renderValue actual)\n                      else go (index + 1) rest env ends\n                  _ -> error (\"unknown scenario act \" ++ show act)\n          go (0 :: Int) acts env0 ends0\n    root <- newIORef shake\n    rootClock <- newIORef []\n    finished <- process body [] [] root Nothing rootClock\n      `finally` mapM_ (closeScenarioChannel . snd) channels `finally` mapM_ (closeScenarioMailbox . snd) mailboxes\n    found <- readIORef failures\n    case found of\n      failure : _ -> pure (Just (failure ++ (if victim /= Nothing then \" (with a process crashed)\" else \"\")))\n      [] | not finished && victim == Nothing -> pure (Just \"a process failed\")\n      [] -> do\n        final <- case planAbstract plan of\n          Nothing -> pure Nothing\n          Just abstract -> Just <$> callOrRaise abstract symbols [state]\n        calls <- readIORef history\n        linearizes <- linearizesHistory plan symbols calls expected final state\n        let calledAt (_, _, _, c, _, _, _, _) = c\n            observed = intercalate \"; \"\n              [ mcName command ++ \"(\" ++ intercalate \", \" (map renderValue args) ++ \") returned \" ++ renderValue result\n              | (command, args, result, _, _, _, _, _) <- sortBy (\\a b -> compare (calledAt a) (calledAt b)) calls ]\n        pure (if linearizes then Nothing\n          else Just (\"the calls are not \" ++ consistentWord (planConsistency plan) ++ \" with the model (\" ++ observed ++ \")\"))\n  pure (title, case outcome of\n    Right failure -> failure\n    Left e -> Just (\"raised error: \" ++ case fromException e of\n      Just (ModelRaised message) -> message\n      _ -> exceptionText e))\n\n-- | Whether call a returned before call b began, as far as messages tell:\n-- a's return clock is at or below b's call clock everywhere.\nhappenedBefore :: ScenarioCall -> ScenarioCall -> Bool\nhappenedBefore (_, _, _, _, _, _, _, returnedA) (_, _, _, _, _, _, calledB, _) =\n  and [maybe 0 id (lookup p calledB) >= n | (p, n) <- returnedA]\n\n-- | A Wing-Gong search over the scenario's calls, memoized on the calls done\n-- and the state. Linearizable: next, a call no pending call returned before\n-- (real time). Sequential: next, a call every call that happened before it\n-- (its process's order, and messages) is done. Causal: each process's\n-- results from an order of what happened before them. Eventual: no\n-- results, only the final state.\nlinearizesHistory :: ModelPlan -> SymbolContext -> [ScenarioCall] -> Scalar -> Maybe Scalar -> Scalar -> IO Bool\nlinearizesHistory plan symbols calls expected final state = case mode of\n  \"causal\" -> allM (\\process -> do\n      let own = [i | (i, c) <- indexed, processOf c == process]\n          seenBy = nub (sort (own ++ [j | (j, cj) <- indexed, i <- own, j /= i, happenedBefore cj (calls !! i)]))\n      search seenBy own False) (nub (map processOf calls))\n  \"eventual\" -> search everything [] True\n  _ -> search everything everything True\n  where\n    mode = planConsistency plan\n    indexed = zip [0 :: Int ..] calls\n    everything = map fst indexed\n    processOf (_, _, _, _, _, p, _, _) = p\n    before j i\n      | mode == \"linearizable\" = let (_, _, _, _, returned, _, _, _) = calls !! j\n                                     (_, _, _, called, _, _, _, _) = calls !! i\n                                 in returned < called\n      | otherwise = happenedBefore (calls !! j) (calls !! i)\n    search members checked judgeFinal = do\n      seen <- newIORef ([] :: [(Integer, String)])\n      let complete = foldl setBit (0 :: Integer) members\n          visit done modelState = do\n            let key = (done, renderValue modelState)\n            keys <- readIORef seen\n            if key `elem` keys then pure False else do\n              writeIORef seen (key : keys)\n              if done == complete then (if judgeFinal then finish modelState else pure True)\n              else anyM (next done modelState) members\n          next done modelState i\n            | testBit done i = pure False\n            | or [not (testBit done j) && before j i | j <- members, j /= i] = pure False\n            | otherwise = do\n                let (command, args, result, _, _, _, _, _) = calls !! i\n                stepped <- try (stepModel command symbols args modelState)\n                case stepped of\n                  Left (_ :: ModelStop) -> pure False\n                  Right (after, wanted)\n                    | i `elem` checked && not (mcUnit command) && compareValues result wanted /= Right EQ -> pure False\n                    | otherwise -> visit (setBit done i) after\n      visit 0 expected\n    finish modelState\n      | maybe False (\\actual -> compareValues actual modelState /= Right EQ) final = pure False\n      | otherwise = allM (\\(kind, invariant) -> do\n          holds <- callModel invariant symbols [if kind == \"model\" then modelState else state]\n          pure (case holds of Right (SBool True) -> True; _ -> False)) (planInvariants plan)\n\n-- | Runs a scenario on 30 schedules, seeded from LAWSPEC_SEED or 0: Nothing,\n-- or the first failure.\ncheckScenario :: Model -> String -> IO (Maybe String)\ncheckScenario model spec = do\n  seed <- maybe 0 (fromInteger . read) <$> lookupEnv \"LAWSPEC_SEED\"\n  source <- newIORef (seed `xor` 0x2545F4914F6CDD1D)\n  let loop :: Int -> IO (Maybe String)\n      loop run\n        | run >= 30 = pure Nothing\n        | otherwise = do\n            shake <- drawIO source (Draw splitMix64)\n            -- Every third run crashes one process of a par at a random\n            -- point, and every third other one sends each channel over a\n            -- faulty network.\n            (title, failure) <- runScenarioWith (run `mod` 3 == 2) (run `mod` 3 == 1) model spec shake\n            case failure of\n              Just message -> pure (Just (\"scenario \" ++ title ++ \" fails: \" ++ message))\n              Nothing -> loop (run + 1)\n  loop 0\n\n-- Actors. An actor owns a state and handles one message at a time, in the\n-- order they arrive. It is not a thread: a message sent to an idle actor\n-- forks a short-lived worker that drains its mailbox and then stops, so an\n-- idle actor costs only its state and queue. A handler that throws crashes\n-- the actor: the caller gets ActorCrashed, and a supervised actor restarts\n-- in place (keeping its address and the messages waiting for it) while any\n-- other stops.\n\n-- | A message sent to an actor (or mailbox) that has stopped.\ndata ActorStopped = ActorStopped deriving Show\ninstance Exception ActorStopped\n\n-- | A handler failed, so the actor crashed; the cause is what it threw.\nnewtype ActorCrashed = ActorCrashed SomeException deriving Show\ninstance Exception ActorCrashed\n\n-- | Why an actor or supervisor exited, as its monitors hear it.\ndata Exit = Crashed String | Stopped deriving (Eq, Show)\n\n-- | What a message does to the actor: the next state, or a crash with its\n-- cause and the crash it started from (so a crash crosses each link once).\ndata Outcome s = Next s | Crash String Integer\n\n-- | A queued message, and how to refuse it once the actor has stopped.\ndata Message s = Message (s -> IO (Outcome s)) (IO ())\n\ndata Actor s = Actor\n  { actorRef :: IORef s\n  , actorBox :: MVar (ActorBox s)\n  , actorRestartWith :: Maybe (s -> IO s)\n  , actorSupervisor :: IORef (Maybe Supervisor)\n  , actorMonitors :: IORef [Exit -> IO ()]\n  , actorLinks :: IORef [String -> Integer -> IO ()]\n  , actorSeen :: IORef [Integer]\n  , actorKey :: Unique\n  }\n\n-- | Queued messages (front, then back reversed), whether a worker is\n-- draining them, and whether the actor has stopped.\ndata ActorBox s = ActorBox [Message s] [Message s] Bool Bool\n\ncrashCounter :: IORef Integer\ncrashCounter = unsafePerformIO (newIORef 0)\n{-# NOINLINE crashCounter #-}\n\nnextCrash :: IO Integer\nnextCrash = atomicModifyIORef' crashCounter (\\n -> (n + 1, n + 1))\n\n-- | An actor owning the given state; a crash stops it.\nnewActor :: s -> IO (Actor s)\nnewActor = newActorWith Nothing\n\n-- | An actor whose state after a crash is restart (last state), so a\n-- supervisor can restart it.\nnewRestartableActor :: (s -> IO s) -> s -> IO (Actor s)\nnewRestartableActor restart = newActorWith (Just restart)\n\nnewActorWith :: Maybe (s -> IO s) -> s -> IO (Actor s)\nnewActorWith restart state = Actor <$> newIORef state <*> newMVar (ActorBox [] [] False False) <*> pure restart\n  <*> newIORef Nothing <*> newIORef [] <*> newIORef [] <*> newIORef [] <*> newUnique\n\npostActor :: Actor s -> Message s -> IO ()\npostActor actor message = do\n  start <- modifyMVar (actorBox actor) (\\(ActorBox front back draining stopped) ->\n    if stopped then throwIO ActorStopped\n    else pure (ActorBox front (message : back) True stopped, not draining))\n  if start then () <$ forkIO (drainActor actor) else pure ()\n\n-- | Posts a message, ignoring an actor that has stopped.\npostQuietly :: Actor s -> Message s -> IO ()\npostQuietly actor message = postActor actor message `catch` \\ActorStopped -> pure ()\n\ndrainActor :: Actor s -> IO ()\ndrainActor actor = loop\n  where\n    loop = do\n      next <- modifyMVar (actorBox actor) (\\(ActorBox front back _ stopped) -> pure (case front of\n        m : rest -> (ActorBox rest back True stopped, Just m)\n        [] -> case reverse back of\n          m : rest -> (ActorBox rest [] True stopped, Just m)\n          [] -> (ActorBox [] [] False stopped, Nothing)))\n      case next of\n        Nothing -> pure ()\n        Just (Message run _) -> do\n          outcome <- readIORef (actorRef actor) >>= run\n          case outcome of\n            Next state -> writeIORef (actorRef actor) state\n            Crash cause origin -> actorCrashed actor cause origin\n          loop\n\n-- | On the actor's turn: restart or stop, then tell monitors and links.\nactorCrashed :: Actor s -> String -> Integer -> IO ()\nactorCrashed actor cause origin = do\n  modifyIORef' (actorSeen actor) (origin :)\n  supervisor <- readIORef (actorSupervisor actor)\n  restarted <- case (supervisor, actorRestartWith actor) of\n    (Just s, Just _) -> supervisorChildCrashed s (actorChild actor) cause\n    _ -> pure False\n  if restarted then pure () else haltActor actor\n  readIORef (actorMonitors actor) >>= mapM_ ($ Crashed cause)\n  readIORef (actorLinks actor) >>= mapM_ (\\crash -> crash cause origin)\n\n-- | On the actor's turn: the restarted state from the last one; a restart\n-- that throws stops the actor.\nrestartNow :: Actor s -> IO ()\nrestartNow actor = case actorRestartWith actor of\n  Nothing -> haltActor actor\n  Just restart -> do\n    outcome <- try (readIORef (actorRef actor) >>= restart >>= evaluate)\n    case outcome of\n      Right state -> writeIORef (actorRef actor) state\n      Left (_ :: SomeException) -> haltActor actor\n\n-- | A restart a supervisor asks of a sibling, in mailbox order.\nrestartLater :: Actor s -> IO ()\nrestartLater actor = case actorRestartWith actor of\n  Nothing -> pure ()\n  Just restart -> postQuietly actor (Message (\\state -> do\n    outcome <- try (restart state >>= evaluate)\n    pure (either (\\e -> Crash (exceptionText e) 0) Next outcome)) (pure ()))\n\n-- | Stops the actor; messages still waiting fail with ActorStopped.\nhaltActor :: Actor s -> IO ()\nhaltActor actor = do\n  waiting <- modifyMVar (actorBox actor) (\\(ActorBox front back draining _) ->\n    pure (ActorBox [] [] draining True, front ++ reverse back))\n  mapM_ (\\(Message _ refuse) -> refuse) waiting\n\n-- | Runs handler state -> (reply, next state) in turn and returns the\n-- reply. A handler that throws crashes the actor, and callActor throws\n-- ActorCrashed.\ncallActor :: Actor s -> (s -> IO (r, s)) -> IO r\ncallActor actor handler = do\n  reply <- newEmptyMVar\n  postActor actor (Message (\\state -> do\n    outcome <- try (handler state >>= \\(r, next) -> next `seq` pure (r, next))\n    case outcome of\n      Left e -> do\n        origin <- nextCrash\n        putMVar reply (Left (toException (ActorCrashed e)))\n        pure (Crash (exceptionText e) origin)\n      Right (r, next) -> putMVar reply (Right r) >> pure (Next next))\n    (putMVar reply (Left (toException ActorStopped))))\n  takeMVar reply >>= either throwIO pure\n\n-- | Queues handler state -> (reply, next state) without waiting; a handler\n-- that throws crashes the actor.\ncastActor :: Actor s -> (s -> IO (r, s)) -> IO ()\ncastActor actor handler = postActor actor (Message (\\state -> do\n  outcome <- try (handler state >>= \\(r, next) -> next `seq` pure (r, next))\n  case outcome of\n    Left e -> Crash (exceptionText (e :: SomeException)) <$> nextCrash\n    Right (_, next) -> pure (Next next)) (pure ()))\n\n-- | Crashes the actor once the messages before this one are handled, as a\n-- failing handler would: for testing supervision.\ncrashActor :: Actor s -> String -> IO ()\ncrashActor actor cause = do\n  origin <- nextCrash\n  reply <- newEmptyMVar\n  postActor actor (Message (\\_ -> putMVar reply (Right ()) >> pure (Crash cause origin))\n    (putMVar reply (Left (toException ActorStopped))))\n  takeMVar reply >>= either throwIO pure\n\n-- | Replaces the state by restart (last state) between messages, as a\n-- supervised restart does (crash injection in model runs).\nrestartActor :: Actor s -> (s -> IO s) -> IO ()\nrestartActor actor restart = callActor actor (\\state -> (,) () <$> restart state)\n\n-- | The state after every message sent before this call.\nactorState :: Actor s -> IO s\nactorState actor = callActor actor (\\s -> pure (s, s))\n\n-- | Calls notify with Crashed cause after each crash, and Stopped once the\n-- actor stops.\nmonitorActor :: Actor s -> (Exit -> IO ()) -> IO ()\nmonitorActor actor notify = modifyIORef' (actorMonitors actor) (++ [notify])\n\n-- | Links two actors: when either crashes, the other crashes too.\nlinkActors :: Actor a -> Actor b -> IO ()\nlinkActors = link\n\nlinkCrash :: Actor s -> String -> Integer -> IO ()\nlinkCrash actor cause origin = do\n  seen <- readIORef (actorSeen actor)\n  if origin `elem` seen then pure ()\n    -- Checked again on the actor's turn: another link may have brought the\n    -- same crash first.\n    else postQuietly actor (Message (\\state -> do\n      again <- readIORef (actorSeen actor)\n      pure (if origin `elem` again then Next state else Crash cause origin)) (pure ()))\n\n-- | Refuses further messages; those already queued still run. A permanent\n-- child of a supervisor restarts instead.\nstopActor :: Actor s -> IO ()\nstopActor actor = do\n  supervisor <- readIORef (actorSupervisor actor)\n  restarted <- maybe (pure False) (\\s -> supervisorChildStopped s (actorChild actor)) supervisor\n  if restarted then pure () else do\n    already <- modifyMVar (actorBox actor) (\\(ActorBox front back draining stopped) ->\n      pure (ActorBox front back draining True, stopped))\n    if already then pure () else readIORef (actorMonitors actor) >>= mapM_ ($ Stopped)\n\n-- Supervision.\n\ndata SupervisionStrategy = OneForOne | OneForAll | RestForOne deriving (Eq, Show)\ndata Lifetime = Permanent | Transient | Temporary deriving (Eq, Show)\n\n-- | What a supervisor needs of a child, actor or supervisor.\ndata SupervisedChild = SupervisedChild\n  { childKey :: Unique\n  , childRestartNow :: IO ()\n  , childRestartLater :: IO ()\n  , childHalt :: IO ()\n  , childStop :: IO ()\n  , childAdopt :: Maybe Supervisor -> IO ()\n  }\n\nactorChild :: Actor s -> SupervisedChild\nactorChild actor = SupervisedChild (actorKey actor) (restartNow actor) (restartLater actor)\n  (haltActor actor) (stopActor actor) (writeIORef (actorSupervisor actor))\n\nsupervisorChild :: Supervisor -> SupervisedChild\nsupervisorChild s = SupervisedChild (supervisorKey s) (pure ()) (supervisorRestartLater s)\n  (stopSupervisor s) (stopSupervisor s) (writeIORef (supervisorParent s))\n\n-- | Starts children (actors or supervisors) and restarts them after a\n-- crash. OneForOne restarts the child that crashed, OneForAll every child,\n-- RestForOne it and those added after it. A Permanent child restarts after\n-- a crash or a stop, a Transient one only after a crash, a Temporary one\n-- never. More restarts than allowed within the period is the supervisor's\n-- own crash: its supervisor restarts all of its children, or, at the top,\n-- every child stops.\n--\n-- Supervision follows OTP's strategies and restart types, so a supervision tree\n-- means what an Erlang programmer expects on every target.\n-- ref:DEC-actors-otp-supervision ref:erlang-otp-supervisors\ndata Supervisor = Supervisor\n  { supervisorStrategy :: SupervisionStrategy\n  , supervisorMaxRestarts :: Int\n  , supervisorPeriodMicros :: Integer\n  , supervisorLock :: MVar ()\n  , supervisorChildren :: IORef [(SupervisedChild, Lifetime)]\n  , supervisorRestarts :: IORef [Word64]\n  , supervisorParent :: IORef (Maybe Supervisor)\n  , supervisorStopped :: IORef Bool\n  , supervisorMonitors :: IORef [Exit -> IO ()]\n  , supervisorKey :: Unique\n  }\n\n-- | A supervisor with a strategy, allowing at most so many restarts within\n-- a period in microseconds.\nnewSupervisor :: SupervisionStrategy -> Int -> Integer -> IO Supervisor\nnewSupervisor strategy maxRestarts period = Supervisor strategy maxRestarts period <$> newMVar ()\n  <*> newIORef [] <*> newIORef [] <*> newIORef Nothing <*> newIORef False <*> newIORef [] <*> newUnique\n\n-- | Adds a started child.\nsupervise :: Supervisor -> SupervisedChild -> Lifetime -> IO ()\nsupervise s child lifetime = withMVar' (supervisorLock s) $ do\n  childAdopt child (Just s)\n  modifyIORef' (supervisorChildren s) (++ [(child, lifetime)])\n\n-- | Adds a started actor.\nsuperviseActor :: Supervisor -> Actor a -> Lifetime -> IO ()\nsuperviseActor s actor = supervise s (actorChild actor)\n\n-- | Adds a started supervisor.\nsuperviseSupervisor :: Supervisor -> Supervisor -> Lifetime -> IO ()\nsuperviseSupervisor s child = supervise s (supervisorChild child)\n\nwithMVar' :: MVar () -> IO a -> IO a\nwithMVar' lock action = modifyMVar lock (\\() -> (,) () <$> action)\n\nallowRestart :: Supervisor -> IO Bool\nallowRestart s = do\n  now <- getMonotonicTimeNSec\n  let window = fromInteger (supervisorPeriodMicros s * 1000)\n  recent <- filter (\\t -> now - t <= window) <$> readIORef (supervisorRestarts s)\n  if length recent >= supervisorMaxRestarts s\n    then writeIORef (supervisorRestarts s) recent >> pure False\n    else writeIORef (supervisorRestarts s) (recent ++ [now]) >> pure True\n\n-- | Under the lock: the children to restart for a child's crash, or\n-- Nothing when the supervisor gives up.\nrestarting :: Supervisor -> Unique -> String -> IO (Maybe [SupervisedChild])\nrestarting s key cause = do\n  allowed <- allowRestart s\n  children <- readIORef (supervisorChildren s)\n  if allowed then pure (Just (case supervisorStrategy s of\n      OneForOne -> [c | (c, _) <- children, childKey c == key]\n      OneForAll -> map fst children\n      RestForOne -> map fst (dropWhile ((/= key) . childKey . fst) children)))\n  else do\n    parent <- readIORef (supervisorParent s)\n    escalated <- maybe (pure False) (\\p -> supervisorChildFailed p (supervisorChild s) cause) parent\n    if escalated\n      then writeIORef (supervisorRestarts s) [] >> pure (Just (map fst children))\n      else failSupervisor s key cause >> pure Nothing\n\n-- | The child's entry, unless the supervisor stopped; a Temporary child is\n-- dropped and gets nothing.\nentryOf :: Supervisor -> Unique -> IO (Maybe Lifetime)\nentryOf s key = do\n  stopped <- readIORef (supervisorStopped s)\n  children <- readIORef (supervisorChildren s)\n  case lookup key [(childKey c, l) | (c, l) <- children] of\n    Just lifetime | not stopped -> pure (Just lifetime)\n    _ -> pure Nothing\n\ndropChild :: Supervisor -> Unique -> IO ()\ndropChild s key = modifyIORef' (supervisorChildren s) (filter ((/= key) . childKey . fst))\n\n-- | On the child's turn: True when it restarts now.\nsupervisorChildCrashed :: Supervisor -> SupervisedChild -> String -> IO Bool\nsupervisorChildCrashed s child cause = do\n  group <- withMVar' (supervisorLock s) $ do\n    entry <- entryOf s (childKey child)\n    case entry of\n      Nothing -> pure Nothing\n      Just Temporary -> dropChild s (childKey child) >> pure Nothing\n      Just _ -> restarting s (childKey child) cause\n  case group of\n    Nothing -> pure False\n    Just children -> do\n      mapM_ childRestartLater [c | c <- children, childKey c /= childKey child]\n      childRestartNow child\n      pure True\n\n-- | A child supervisor gave up: True when it may restart its children.\nsupervisorChildFailed :: Supervisor -> SupervisedChild -> String -> IO Bool\nsupervisorChildFailed s child cause = do\n  group <- withMVar' (supervisorLock s) $ do\n    entry <- entryOf s (childKey child)\n    case entry of\n      Nothing -> pure Nothing\n      Just Temporary -> dropChild s (childKey child) >> pure Nothing\n      Just _ -> restarting s (childKey child) cause\n  case group of\n    Nothing -> pure False\n    Just children -> do\n      mapM_ childRestartLater [c | c <- children, childKey c /= childKey child]\n      pure True\n\n-- | True when a stopped child is Permanent and restarts instead.\nsupervisorChildStopped :: Supervisor -> SupervisedChild -> IO Bool\nsupervisorChildStopped s child = do\n  group <- withMVar' (supervisorLock s) $ do\n    entry <- entryOf s (childKey child)\n    case entry of\n      Just Permanent -> restarting s (childKey child) \"stopped\"\n      Just _ -> dropChild s (childKey child) >> pure Nothing\n      Nothing -> pure Nothing\n  case group of\n    Nothing -> pure False\n    Just children -> mapM_ childRestartLater children >> pure True\n\n-- | Under the lock: every child but the one crashing (which stops itself)\n-- stops, and so does the supervisor.\nfailSupervisor :: Supervisor -> Unique -> String -> IO ()\nfailSupervisor s crashed cause = do\n  children <- readIORef (supervisorChildren s)\n  writeIORef (supervisorChildren s) []\n  writeIORef (supervisorStopped s) True\n  forM_ (reverse children) $ \\(c, _) -> do\n    childAdopt c Nothing\n    if childKey c == crashed then pure () else childHalt c\n  readIORef (supervisorMonitors s) >>= mapM_ ($ Crashed cause)\n\n-- | Restarted by its own supervisor: every child restarts.\nsupervisorRestartLater :: Supervisor -> IO ()\nsupervisorRestartLater s = do\n  children <- withMVar' (supervisorLock s) $ do\n    writeIORef (supervisorRestarts s) []\n    readIORef (supervisorChildren s)\n  mapM_ (childRestartLater . fst) children\n\n-- | Calls notify with Crashed cause when it passes its restart limit, and\n-- Stopped once stopped.\nmonitorSupervisor :: Supervisor -> (Exit -> IO ()) -> IO ()\nmonitorSupervisor s notify = modifyIORef' (supervisorMonitors s) (++ [notify])\n\n-- | Stops every child, last added first, without restarting them.\nstopSupervisor :: Supervisor -> IO ()\nstopSupervisor s = do\n  children <- withMVar' (supervisorLock s) $ do\n    stopped <- readIORef (supervisorStopped s)\n    if stopped then pure Nothing else do\n      writeIORef (supervisorStopped s) True\n      children <- readIORef (supervisorChildren s)\n      writeIORef (supervisorChildren s) []\n      pure (Just children)\n  case children of\n    Nothing -> pure ()\n    Just cs -> do\n      forM_ (reverse cs) $ \\(c, _) -> childAdopt c Nothing >> childStop c\n      readIORef (supervisorMonitors s) >>= mapM_ ($ Stopped)\n\n-- | Anything a supervisor can supervise: actors, supervisors, and the\n-- generated typed actors and supervisors.\nclass Supervisable t where\n  asChild :: t -> SupervisedChild\n\ninstance Supervisable (Actor s) where\n  asChild = actorChild\n\ninstance Supervisable Supervisor where\n  asChild = supervisorChild\n\n-- | Adds a started child (an actor or a supervisor) to a supervisor.\nsuperviseChild :: Supervisable t => Supervisor -> t -> Lifetime -> IO ()\nsuperviseChild s child = supervise s (asChild child)\n\n-- | Where a crash arrives for an actor that is linked to: its links, and\n-- how to crash it.\ndata LinkPoint = LinkPoint (IORef [String -> Integer -> IO ()]) (String -> Integer -> IO ())\n\n-- | Anything that can be linked: actors and the generated typed actors.\nclass Linkable t where\n  linkPoint :: t -> LinkPoint\n\ninstance Linkable (Actor s) where\n  linkPoint actor = LinkPoint (actorLinks actor) (linkCrash actor)\n\n-- | Links two actors: when either crashes, the other crashes too.\nlink :: (Linkable a, Linkable b) => a -> b -> IO ()\nlink a b = do\n  let LinkPoint linksA crashA = linkPoint a\n      LinkPoint linksB crashB = linkPoint b\n  modifyIORef' linksA (++ [crashB])\n  modifyIORef' linksB (++ [crashA])\n\n-- | Anything whose exits can be watched.\nclass Monitorable t where\n  -- | Calls notify with Crashed cause after each crash (for a supervisor,\n  -- when it passes its restart limit), and Stopped once it stops.\n  monitor :: t -> (Exit -> IO ()) -> IO ()\n\ninstance Monitorable (Actor s) where\n  monitor = monitorActor\n\ninstance Monitorable Supervisor where\n  monitor = monitorSupervisor\n\n-- | The runtime's own check of crashes, links, monitors and supervision:\n-- every strategy, lifetime, the restart limit and escalation. Nothing, or\n-- the first behaviour that differs.\ncheckSupervision :: IO (Maybe String)\ncheckSupervision = do\n  outcome <- try checks\n  pure (case outcome of\n    Right () -> Nothing\n    Left (ErrorCall message) -> Just message)\n  where\n    counter = newRestartableActor (\\_ -> pure (0 :: Int)) 0\n    bump a = callActor a (\\s -> pure (s + 1, s + 1))\n    failing a = do\n      outcome <- try (callActor a (\\s -> if s >= 0 then throwIO (ErrorCall \"a failing handler\") else pure ((), s)))\n      case outcome of\n        Left (ActorCrashed _) -> pure ()\n        Right () -> throwIO (ErrorCall \"a failing handler did not throw ActorCrashed\")\n    stopped a what = do\n      outcome <- try (actorState a)\n      case outcome of\n        Left ActorStopped -> pure ()\n        Right _ -> throwIO (ErrorCall (what ++ \" should have stopped\"))\n    expect :: (Eq a, Show a) => a -> a -> String -> IO ()\n    expect actual wanted what = if actual == wanted then pure ()\n      else throwIO (ErrorCall (what ++ \": got \" ++ show actual ++ \", expected \" ++ show wanted))\n    under s lifetime = do\n      a <- counter\n      superviseActor s a lifetime\n      pure a\n    waitFor condition = loop (100 :: Int)\n      where loop n = do\n              ok <- condition\n              if ok || n <= 0 then pure () else threadDelay 10000 >> loop (n - 1)\n    checks = do\n      a <- counter\n      _ <- bump a\n      failing a\n      stopped a \"an unsupervised actor that crashed\"\n      s1 <- newSupervisor OneForOne 3 5000000\n      x1 <- under s1 Permanent\n      y1 <- under s1 Permanent\n      _ <- bump x1 >> bump y1 >> bump y1\n      failing x1\n      states1 <- (,) <$> actorState x1 <*> actorState y1\n      expect states1 (0, 2) \"one for one restarts only the crashed child\"\n      s2 <- newSupervisor OneForAll 3 5000000\n      x2 <- under s2 Permanent\n      y2 <- under s2 Permanent\n      _ <- bump x2 >> bump y2\n      failing x2\n      states2 <- (,) <$> actorState x2 <*> actorState y2\n      expect states2 (0, 0) \"one for all restarts every child\"\n      s3 <- newSupervisor RestForOne 3 5000000\n      x3 <- under s3 Permanent\n      y3 <- under s3 Permanent\n      z3 <- under s3 Permanent\n      _ <- bump x3 >> bump y3 >> bump z3\n      failing y3\n      states3 <- (,,) <$> actorState x3 <*> actorState y3 <*> actorState z3\n      expect states3 (1, 0, 0) \"rest for one restarts the child and later ones\"\n      s4 <- newSupervisor OneForOne 3 5000000\n      t4 <- under s4 Temporary\n      failing t4\n      stopped t4 \"a temporary child that crashed\"\n      s5 <- newSupervisor OneForOne 3 5000000\n      p5 <- under s5 Permanent\n      q5 <- under s5 Transient\n      _ <- bump p5\n      stopActor p5\n      state5 <- actorState p5\n      expect state5 0 \"a permanent child restarts after a stop\"\n      stopActor q5\n      stopped q5 \"a transient child that was stopped\"\n      events <- newIORef []\n      s6 <- newSupervisor OneForOne 2 10000000\n      monitorSupervisor s6 (\\e -> modifyIORef' events (++ [e]))\n      x6 <- under s6 Permanent\n      y6 <- under s6 Permanent\n      failing x6 >> failing x6 >> failing x6\n      stopped y6 \"a child of a supervisor past its restart limit\"\n      heard <- map (\\e -> case e of Crashed _ -> \"crashed\"; Stopped -> \"stopped\") <$> readIORef events\n      expect heard [\"crashed\"] \"a supervisor past its limit tells its monitors\"\n      outer <- newSupervisor OneForOne 5 10000000\n      inner <- newSupervisor OneForOne 1 10000000\n      superviseSupervisor outer inner Permanent\n      x7 <- under inner Permanent\n      y7 <- under inner Permanent\n      _ <- bump y7\n      failing x7 >> failing x7\n      states7 <- (,) <$> actorState x7 <*> actorState y7\n      expect states7 (0, 0) \"a supervisor past its limit is restarted by its own\"\n      seen <- newIORef []\n      a8 <- counter\n      b8 <- counter\n      linkActors a8 b8\n      monitorActor b8 (\\e -> modifyIORef' seen (++ [e]))\n      failing a8\n      waitFor (not . null <$> readIORef seen)\n      stopped b8 \"an unsupervised actor linked to one that crashed\"\n      heard8 <- map (\\e -> case e of Crashed _ -> \"crashed\"; Stopped -> \"stopped\") <$> readIORef seen\n      expect heard8 [\"crashed\"] \"a monitor hears of a crash\"\n      s9 <- newSupervisor OneForOne 10 5000000\n      a9 <- under s9 Permanent\n      b9 <- under s9 Permanent\n      c9 <- under s9 Permanent\n      linkActors a9 b9 >> linkActors b9 c9 >> linkActors c9 a9\n      _ <- bump a9 >> bump b9 >> bump c9\n      failing a9\n      waitFor ((>= 3) . length <$> readIORef (supervisorRestarts s9))\n      threadDelay 50000\n      states9 <- (,,) <$> actorState a9 <*> actorState b9 <*> actorState c9\n      restarts9 <- length <$> readIORef (supervisorRestarts s9)\n      expect (states9, restarts9) ((0, 0, 0), 3) \"a crash crosses each link once\"\n\n-- | A queue with many senders and one receiver: the channel form of an\n-- actor. A process that loops over receiveMailbox and answers each message\n-- is an actor written by hand; sendMailbox never waits. The queue (front,\n-- then back reversed) and whether it is closed are kept together; the\n-- signal wakes a waiting receiver after a send or the close.\ndata Mailbox a = Mailbox (MVar ([a], [a], Bool)) (MVar ())\n\n-- | What a receive found without waiting.\ndata MailTaken a = MailTook a | MailEmpty | MailClosed\n\nnewMailbox :: IO (Mailbox a)\nnewMailbox = Mailbox <$> newMVar ([], [], False) <*> newEmptyMVar\n\nsendMailbox :: Mailbox a -> a -> IO ()\nsendMailbox (Mailbox state signal) value = do\n  sent <- modifyMVar state (\\(front, back, closed) ->\n    pure (if closed then ((front, back, closed), False) else ((front, value : back, closed), True)))\n  if sent then () <$ tryPutMVar signal () else throwIO ActorStopped\n\n-- | The next message without waiting. Another waiting receiver is woken\n-- while messages remain (or the mailbox is closed), so no wakeup is lost.\ntakeMailbox :: Mailbox a -> IO (MailTaken a)\ntakeMailbox (Mailbox state signal) = do\n  (taken, more) <- modifyMVar state (\\(front, back, closed) -> pure (case (front, reverse back) of\n    (x : rest, _) -> ((rest, back, closed), (MailTook x, not (null rest) || not (null back) || closed))\n    ([], x : rest) -> ((rest, [], closed), (MailTook x, not (null rest) || closed))\n    ([], []) -> ((front, back, closed), (if closed then MailClosed else MailEmpty, closed))))\n  if more then () <$ tryPutMVar signal () else pure ()\n  pure taken\n\n-- | The next message, waiting for it; throws ActorStopped once the mailbox\n-- is closed and empty.\nreceiveMailbox :: Mailbox a -> IO a\nreceiveMailbox mailbox@(Mailbox _ signal) = do\n  taken <- takeMailbox mailbox\n  case taken of\n    MailTook value -> pure value\n    MailClosed -> throwIO ActorStopped\n    MailEmpty -> takeMVar signal >> receiveMailbox mailbox\n\n-- | The next message, waiting up to the given microseconds of real time\n-- (Nothing when none arrives in time); throws ActorStopped once the mailbox\n-- is closed and empty.\nreceiveMailboxWithin :: Int -> Mailbox a -> IO (Maybe a)\nreceiveMailboxWithin micros mailbox@(Mailbox _ signal) = do\n  start <- getMonotonicTimeNSec\n  let deadline = start + fromIntegral (max 0 micros) * 1000\n      loop = do\n        taken <- takeMailbox mailbox\n        case taken of\n          MailTook value -> pure (Just value)\n          MailClosed -> throwIO ActorStopped\n          MailEmpty -> do\n            now <- getMonotonicTimeNSec\n            if now >= deadline then pure Nothing else do\n              -- A message that arrives as this times out is found by the\n              -- take that follows.\n              _ <- timeout (max 1 (fromIntegral ((deadline - now) `div` 1000))) (takeMVar signal)\n              loop\n  loop\n\n-- | The Mailbox ability's receive ... within d, on the Clock handler\n-- installed with the context: on a virtual clock (any Clock handler but\n-- lawspec.time's default real one) it waits no real time: it takes a\n-- message already sent, or lets the time pass on that clock and gives\n-- Nothing. Otherwise (the real clock, or none installed) it waits in real\n-- time, as receiveMailboxWithin.\nreceiveMailboxWithinOn :: SymbolContext -> Int -> Mailbox a -> IO (Maybe a)\nreceiveMailboxWithinOn symbols micros mailbox = do\n  clock <- abilityClock symbols\n  case clock of\n    Just c | clockVirtual c -> do\n      taken <- takeMailbox mailbox\n      case taken of\n        MailTook value -> pure (Just value)\n        MailClosed -> throwIO ActorStopped\n        MailEmpty -> Nothing <$ clockSleep c (toInteger (max 0 micros))\n    _ -> receiveMailboxWithin micros mailbox\n\n-- | Refuses further messages; those already sent can still be received.\ncloseMailbox :: Mailbox a -> IO ()\ncloseMailbox (Mailbox state signal) = do\n  modifyMVar state (\\(front, back, _) -> pure ((front, back, True), ()))\n  () <$ tryPutMVar signal ()\n\n-- | Actor models: the generated callbacks are pure, so these run the actor's\n-- IO inside them, each call its own effect.\nactorStartCallback :: ModelCallback -> ModelCallback\nactorStartCallback run symbols args = case run symbols args of\n  Left message -> Left message\n  Right state -> Right (unsafePerformIO (do\n    _ <- evaluate (deepScalar state)\n    actor <- newActor state\n    SHandle \"lawspec::actor\" <$> handle actor))\n{-# NOINLINE actorStartCallback #-}\n\nactorCommandCallback :: Bool -> ModelCallback -> ModelCallback\nactorCommandCallback unit run symbols args = case args of\n  SHandle _ h : rest -> unsafePerformIO (do\n    outcome <- try (callActor (fromHandle h :: Actor Scalar) (\\state -> case run symbols (state : rest) of\n      Left message -> throwIO (ModelRaised message)\n      Right out -> do\n        _ <- evaluate (deepScalar out)\n        pure (if unit then (SAbsent \"Unit\", out) else (productField False out, productField True out))))\n    pure (case outcome of\n      Right reply -> Right reply\n      Left e -> Left (case fromException e of\n        Just (ActorCrashed cause) -> case fromException cause of\n          Just (ModelRaised message) -> message\n          _ -> exceptionText cause\n        _ -> exceptionText e)))\n  _ -> Left \"an actor command needs its actor first\"\n{-# NOINLINE actorCommandCallback #-}\n\n-- | An actor model's crash step: the actor restarts from the restart\n-- command (its run on the system, its reference on the model) or, without\n-- one, from the start with the run's start arguments.\nactorCrashStep :: ModelCallback -> ModelCallback -> Maybe ModelCommand -> CrashStep\nactorCrashStep startRun startModel restart = CrashStep system model\n  where\n    system startArgs symbols handleValue = case handleValue of\n      SHandle _ h -> restartActor (fromHandle h :: Actor Scalar) (\\state ->\n        either (throwIO . ModelRaised) (\\v -> evaluate (deepScalar v) >> pure v)\n          (case restart of\n            Just r -> mcRun r symbols [state]\n            Nothing -> startRun symbols startArgs))\n      _ -> throwIO (ModelRaised \"an actor crash needs its actor\")\n    model startArgs symbols state = do\n      out <- callModel (maybe (\\s _ -> startModel s startArgs) mcReference restart) symbols [state]\n      either (const (throwIO ModelInvalid)) pure out\n\nactorStateCallback :: ModelCallback -> ModelCallback\nactorStateCallback f symbols args = case args of\n  [SHandle _ h] -> f symbols [unsafePerformIO (actorState (fromHandle h :: Actor Scalar))]\n  _ -> f symbols args\n{-# NOINLINE actorStateCallback #-}\n\n-- Sessions: typed channel ends for implementation code. Each generated\n-- protocol module (LawSpecSessions.*) wraps a SessionEnd in a type per step\n-- and makes it an instance of Send or Receive, so steps out of order do not\n-- compile; a SessionEnd is single use, so a stale end fails when used.\n\n-- | One side of a channel, as a transport implements it: sending a value to\n-- the other side and receiving the next value from it. localChannel joins two\n-- sides in process; a network transport could implement the same record.\ndata ChannelSide = ChannelSide\n  { sideSend :: Dynamic -> IO ()\n  -- The next value; throws PeerFailed once the other side has given up\n  -- and nothing it sent is left.\n  , sideReceive :: IO Dynamic\n  -- Gives up: the other side's receives fail after the values already sent.\n  , sideAbandon :: IO ()\n  -- For an unused end between nodes, the address another node takes it\n  -- over from; Nothing for a local end.\n  , sideHandOver :: IO (Maybe String)\n  }\n\n-- | A receive whose other end gave up: its process failed, or it called\n-- abandon. Catch it (or use tryReceive) to handle the failure; otherwise\n-- this process fails too.\ndata PeerFailed = PeerFailed deriving Show\ninstance Exception PeerFailed\n\n-- | The mark a side that gave up leaves for the other.\ndata Abandoned = Abandoned\n\n-- | Two connected sides, with one queue per direction.\nlocalChannel :: IO (ChannelSide, ChannelSide)\nlocalChannel = do\n  forward <- newChan\n  backward <- newChan\n  let receiving chan = do\n        message <- readChan chan\n        case fromDynamic message of\n          Just Abandoned -> writeChan chan message >> throwIO PeerFailed\n          Nothing -> pure message\n  pure ( ChannelSide (writeChan forward) (receiving backward) (writeChan forward (toDyn Abandoned)) (pure Nothing)\n       , ChannelSide (writeChan backward) (receiving forward) (writeChan backward (toDyn Abandoned)) (pure Nothing) )\n\n-- | A channel side at one step of a protocol, usable once: each step returns\n-- a fresh end for the next.\n--\n-- Using an end exactly once is what makes a session follow its protocol; with\n-- channels joined in a tree, scenarios are deadlock-free by construction.\n-- ref:DEC-sessions-by-construction ref:caires-pfenning-session-types\n-- ref:wadler-propositions-as-sessions\ndata SessionEnd = SessionEnd ChannelSide (IORef Bool)\n\n-- | A channel's two ends, at their first step.\nopenSession :: IO (SessionEnd, SessionEnd)\nopenSession = do\n  (first, second) <- localChannel\n  (,) <$> sessionEnd first <*> sessionEnd second\n\nsessionEnd :: ChannelSide -> IO SessionEnd\nsessionEnd side = SessionEnd side <$> newIORef False\n\n-- | Marks an end used, failing if it already was, and returns its side.\nuseEnd :: SessionEnd -> IO ChannelSide\nuseEnd (SessionEnd side used) = do\n  already <- atomicModifyIORef' used (\\was -> (True, was))\n  if already\n    then throwIO (ErrorCall \"this end was already used; use the end its last step returned\")\n    else pure side\n\n-- | Sends a value on an end, wrapping the side's fresh end as the next step.\nsendOn :: Typeable a => (SessionEnd -> next) -> SessionEnd -> a -> IO next\nsendOn next end value = do\n  side <- useEnd end\n  sideSend side (toDyn value)\n  next <$> sessionEnd side\n\n-- | Receives a value on an end, with the side's fresh end as the next step.\nreceiveOn :: forall a next. Typeable a => (SessionEnd -> next) -> SessionEnd -> IO (a, next)\nreceiveOn next end = do\n  side <- useEnd end\n  message <- sideReceive side\n  value <- maybe (throwIO (ErrorCall (\"a session received \" ++ show (dynTypeRep message)\n    ++ \" where it expected \" ++ show (typeRep (Proxy :: Proxy a))))) pure (fromDynamic message)\n  (,) value . next <$> sessionEnd side\n\n-- | An end whose next step sends a message; the end type determines what it\n-- sends and the end that follows.\nclass Send end message next | end -> message next where\n  send :: end -> message -> IO next\n\n-- | An end whose next step receives a message, returned with the end that\n-- follows. receive throws PeerFailed when the other end gave up and nothing\n-- it sent is left.\nclass Receive end message next | end -> message next where\n  receive :: end -> IO (message, next)\n\n-- | receive, with the other end's failure as a Left.\ntryReceive :: Receive end message next => end -> IO (Either PeerFailed (message, next))\ntryReceive end = try (receive end)\n\n-- | An end that can give up its conversation: the other end's receives then\n-- fail with PeerFailed, after the values already sent. A process that fails\n-- while holding an end should abandon it (with finally or bracket), so the\n-- other process does not wait for ever.\nclass Abandon end where\n  abandon :: end -> IO ()\n\n-- | Gives up the channel an end belongs to.\nabandonEnd :: SessionEnd -> IO ()\nabandonEnd end = useEnd end >>= sideAbandon\n\n-- | A running thread whose result join waits for.\nnewtype Process a = Process (MVar (Either SomeException a))\n\n-- | Runs an action in its own thread.\nspawn :: IO a -> IO (Process a)\nspawn action = do\n  result <- newEmptyMVar\n  _ <- forkIO (try action >>= putMVar result)\n  pure (Process result)\n\n-- | Waits for a process, rethrowing what it threw.\njoin :: Process a -> IO a\njoin (Process result) = readMVar result >>= either throwIO pure\n\n-- | Runs actions in parallel and waits for all of them, rethrowing the first\n-- failure in list order.\npar :: [IO ()] -> IO ()\npar actions = mapM spawn actions >>= mapM_ join\n\n-- Distribution. Values cross the network in a canonical binary encoding\n-- driven by their type descriptor (the same descriptors as generation), so\n-- no tags are sent and every target writes the same bytes:\n--   int: zigzag LEB128 of the integer (any size)      bool: 0 or 1\n--   text, bytes: LEB128 length, then UTF-8 or raw     unit: nothing\n--   list: LEB128 count, then items                     maybe: 0, or 1 then the value\n--   either: 0 then left, or 1 then right               data: LEB128 constructor index, then fields\n-- A node sends frames over a Transport (in memory, TCP or HTTP; TCP and\n-- HTTP are in LawSpecTransports): kind, entity name, the sender's address,\n-- an id and a payload.\n\n-- | Bytes that are not an encoding of a value of the expected type.\nnewtype WireError = WireError String deriving Show\ninstance Exception WireError\n\n-- | A node could not be reached, or did not answer in time.\nnewtype Unreachable = Unreachable String deriving Show\ninstance Exception Unreachable\n\nputVarint :: Integer -> BB.Builder\nputVarint n =\n  let low = fromInteger (n .&. 0x7F) :: Word8\n      rest = n `shiftR` 7\n  in if rest /= 0 then BB.word8 (low .|. 0x80) <> putVarint rest else BB.word8 low\n\ngetVarint :: ByteString -> Int -> Either String (Integer, Int)\ngetVarint buf = go 0 0\n  where\n    go acc shift pos\n      | pos >= B.length buf = Left \"the bytes end in the middle of a value\"\n      | otherwise =\n          let byte = B.index buf pos\n              acc' = acc .|. (toInteger (byte .&. 0x7F) `shiftL` shift)\n          in if byte < 0x80 then Right (acc', pos + 1) else go acc' (shift + 7) (pos + 1)\n\nzigzag :: Integer -> Integer\nzigzag v = if v >= 0 then v * 2 else negate v * 2 - 1\n\nunzigzag :: Integer -> Integer\nunzigzag z = if even z then z `div` 2 else negate ((z + 1) `div` 2)\n\nputBytes :: ByteString -> BB.Builder\nputBytes raw = putVarint (toInteger (B.length raw)) <> BB.byteString raw\n\ngetBytes :: ByteString -> Int -> Either String (ByteString, Int)\ngetBytes buf pos = do\n  (n, pos') <- getVarint buf pos\n  let end = pos' + fromInteger n\n  if end > B.length buf then Left \"the bytes end in the middle of a value\"\n    else Right (B.take (fromInteger n) (B.drop pos' buf), end)\n\n-- | An integer descriptor's declared bounds (None: no bound).\ndeclaredBounds :: Descriptor -> (Maybe Integer, Maybe Integer)\ndeclaredBounds (DescList (_ : _ : lo : hi : _)) = (bound lo, bound hi)\n  where bound b = case b of DescInteger k -> Just k; _ -> Nothing\ndeclaredBounds _ = (Nothing, Nothing)\n\nutf8Of :: [Int] -> ByteString\nutf8Of = TE.encodeUtf8 . T.pack . map chr\n\nwirePut :: DataTable -> Descriptor -> Scalar -> Either String BB.Builder\nwirePut table d0 v = case (descriptorKind d, v) of\n  (\"int\", SInteger _ n) -> do\n    let (lo, hi) = declaredBounds d\n    if maybe False (n <) lo || maybe False (n >) hi\n      then Left (show n ++ \" is not a \" ++ descriptorName (arg 1)) else Right (putVarint (zigzag n))\n  (\"bool\", SBool b) -> Right (BB.word8 (if b then 1 else 0))\n  (kind, SSequence _ cps) | kind `elem` [\"text\", \"end\"] -> Right (putBytes (utf8Of cps))\n  (\"unit\", _) -> Right mempty\n  (\"list\", SList xs) -> (putVarint (toInteger (length xs)) <>) . mconcat <$> mapM (wirePut table (arg 1)) xs\n  (\"maybe\", SData \"Maybe::Nothing\" []) -> Right (BB.word8 0)\n  (\"maybe\", SData \"Maybe::Just\" [x]) -> (BB.word8 1 <>) <$> wirePut table (arg 1) x\n  (\"either\", SData \"Either::Left\" [x]) -> (BB.word8 0 <>) <$> wirePut table (arg 1) x\n  (\"either\", SData \"Either::Right\" [x]) -> (BB.word8 1 <>) <$> wirePut table (arg 2) x\n  (\"data\", SData tag fields) ->\n    case [(i, fs) | (i, c) <- zip [0 :: Integer ..] (constructorsOf d), let (t, fs) = constructorParts c, t == tag] of\n      (i, fs) : _ -> (putVarint i <>) . mconcat <$> sequence (zipWith (wirePut table) fs fields)\n      [] -> Left (tag ++ \" is not a constructor of \" ++ descriptorName (arg 1))\n  (kind, _) -> Left (renderValue v ++ \" is not a value of \" ++ kind)\n  where d = resolveDescriptor table d0\n        arg i = descriptorArgument i d\n\nwireGet :: DataTable -> Descriptor -> ByteString -> Int -> Either String (Scalar, Int)\nwireGet table d0 buf pos = case descriptorKind d of\n  \"int\" -> do\n    (z, pos') <- getVarint buf pos\n    let n = unzigzag z\n        (lo, hi) = declaredBounds d\n    if maybe False (n <) lo || maybe False (n >) hi\n      then Left (show n ++ \" is out of range for \" ++ descriptorName (arg 1))\n      else Right (SInteger (descriptorName (arg 1)) n, pos')\n  \"bool\" -> case byteAt pos of\n    Just b | b <= 1 -> Right (SBool (b == 1), pos + 1)\n    _ -> Left \"not a Bool\"\n  kind | kind `elem` [\"text\", \"end\"] -> do\n    (raw, pos') <- getBytes buf pos\n    case TE.decodeUtf8' raw of\n      Right t -> Right (SSequence \"Text\" (map ord (T.unpack t)), pos')\n      Left _ -> Left \"text that is not UTF-8\"\n  \"unit\" -> Right (SAbsent \"Unit\", pos)\n  \"list\" -> do\n    (n, pos') <- getVarint buf pos\n    let items 0 p acc = Right (SList (reverse acc), p)\n        items k p acc = do\n          (x, p') <- wireGet table (arg 1) buf p\n          items (k - 1 :: Integer) p' (x : acc)\n    items n pos' []\n  \"maybe\" -> case byteAt pos of\n    Just 0 -> Right (SData \"Maybe::Nothing\" [], pos + 1)\n    Just 1 -> (\\(x, p) -> (SData \"Maybe::Just\" [x], p)) <$> wireGet table (arg 1) buf (pos + 1)\n    _ -> Left \"not a Maybe\"\n  \"either\" -> case byteAt pos of\n    Just 0 -> (\\(x, p) -> (SData \"Either::Left\" [x], p)) <$> wireGet table (arg 1) buf (pos + 1)\n    Just 1 -> (\\(x, p) -> (SData \"Either::Right\" [x], p)) <$> wireGet table (arg 2) buf (pos + 1)\n    _ -> Left \"not an Either\"\n  \"data\" -> do\n    (i, pos') <- getVarint buf pos\n    let ctors = constructorsOf d\n    if i >= toInteger (length ctors) then Left (\"no constructor \" ++ show i ++ \" in \" ++ descriptorName (arg 1)) else do\n      let (tag, fs) = constructorParts (ctors !! fromInteger i)\n          fields [] p acc = Right (SData tag (reverse acc), p)\n          fields (f : rest) p acc = do\n            (x, p') <- wireGet table f buf p\n            fields rest p' (x : acc)\n      fields fs pos' []\n  kind -> Left (\"unknown descriptor \" ++ kind)\n  where d = resolveDescriptor table d0\n        arg i = descriptorArgument i d\n        byteAt p = if p < B.length buf then Just (B.index buf p) else Nothing\n\n-- | The value's canonical bytes.\n--\n-- Every target encodes a value to the same bytes, so nodes written in different\n-- languages talk to each other. ref:DEC-distribution-canonical-wire\nwireEncode :: DataTable -> Descriptor -> Scalar -> Either String ByteString\nwireEncode table d v = BL.toStrict . BB.toLazyByteString <$> wirePut table d v\n\n-- | The value encoded by exactly these bytes.\nwireDecode :: DataTable -> Descriptor -> ByteString -> Either String Scalar\nwireDecode table d bytes = do\n  (v, pos) <- wireGet table d bytes 0\n  if pos /= B.length bytes then Left \"extra bytes after the value\" else Right v\n\nhexOf :: ByteString -> String\nhexOf = concatMap (\\w -> let h = showHex w \"\" in if length h < 2 then '0' : h else h) . B.unpack\n\n-- | LawSpec's own search over a law's inputs (see LawSpec.Search). The\n-- failure database keeps a failing case's inputs in the wire encoding,\n-- under LAWSPEC_FAILURES/inputs, and they are replayed before the law's\n-- next generated cases. target maximize climbs: it generates inputs from\n-- seeds, keeps the best-scoring case, and moves its integers (one step,\n-- doubling, halving the distance to a bound), keeping the best move while\n-- the score rises and drawing afresh when it does not, checking the law on\n-- every case it tries (at most 400). A case gives its score, or Nothing\n-- when its inputs fall outside the law's refinements.\nsearchFile :: String -> IO (Maybe FilePath)\nsearchFile law = do\n  directory <- lookupEnv \"LAWSPEC_FAILURES\"\n  let safe = map (\\c -> if c `elem` (['a'..'z'] ++ ['A'..'Z'] ++ ['0'..'9'] ++ \"-_\") then c else '_') law\n  pure (case directory of\n    Just d | not (null d) -> Just (d ++ \"/inputs/\" ++ safe ++ \".json\")\n    _ -> Nothing)\n\nsearchRemember :: String -> [String] -> [Scalar] -> IO ()\nsearchRemember law descriptors values = do\n  file <- searchFile law\n  case (file, mapM encode (zip descriptors values)) of\n    (Just path, Right inputs) -> do\n      Directory.createDirectoryIfMissing True (reverse (dropWhile (/= '/') (reverse path)))\n      writeFile path (\"{\\\"law\\\": \" ++ show law ++ \", \\\"inputs\\\": [\" ++ intercalate \", \" (map show inputs) ++ \"]}\")\n    _ -> pure ()\n  where encode (text, v) = let (table, d) = valuesFrom text in hexOf <$> wireEncode table d v\n\n-- | Runs a law's check while remembering its inputs if it fails.\nsearchGuard :: String -> [String] -> [Scalar] -> IO a -> IO a\nsearchGuard law descriptors values action =\n  action `catch` \\(e :: SomeException) -> searchRemember law descriptors values >> throwIO e\n\nsearchReplay :: String -> [String] -> ([Scalar] -> IO (Maybe Double)) -> IO ()\nsearchReplay law descriptors check = do\n  file <- searchFile law\n  case file of\n    Nothing -> pure ()\n    Just path -> do\n      present <- Directory.doesFileExist path\n      if not present then pure () else do\n        text <- readFile path\n        length text `seq` pure ()\n        let after = snd (breakOn \"\\\"inputs\\\"\" text)\n            encoded = everyOther (drop 1 (splitQuotes (drop 8 after)))\n            decode (descriptor, hex) = do\n              bytes <- maybe (Left \"bad hex\") Right (unhex hex)\n              let (table, d) = valuesFrom descriptor\n              wireDecode table d (B.pack bytes)\n        case mapM decode (zip descriptors encoded) of\n          Right values | length values == length descriptors -> do\n            putStrLn (law ++ \": replaying the failing inputs kept in .lawspec/failures\")\n            _ <- check values\n            pure ()\n          _ -> pure ()\n        Directory.removeFile path\n  where\n    breakOn needle haystack = case haystack of\n      [] -> ([], [])\n      _ | needle `isPrefixOf` haystack -> ([], haystack)\n      c : rest -> let (a, b) = breakOn needle rest in (c : a, b)\n    splitQuotes t = case break (== '\"') t of\n      (a, []) -> [a]\n      (a, _ : rest) -> a : splitQuotes rest\n    everyOther (x : _ : rest) = x : everyOther rest\n    everyOther xs = xs\n    unhex (a : b : rest) = case readHex [a, b] of\n      [(w, \"\")] -> (fromInteger w :) <$> unhex rest\n      _ -> Nothing\n    unhex [] = Just []\n    unhex _ = Nothing\n\n-- | Each value with one integer moved, wherever it sits in the value.\nsearchMoves :: DataTable -> Descriptor -> Scalar -> [Scalar]\nsearchMoves table d0 v = case (descriptorKind d, v) of\n  (\"int\", SInteger t x) ->\n    let (lo, hi) = descriptorBounds d\n    in [SInteger t c | c <- nub [x + 1, x - 1, x * 2, x `quot` 2, x + (hi - x) `quot` 2, x - (x - lo) `quot` 2], c /= x, c >= lo, c <= hi]\n  (\"list\", SList xs) -> [SList (replace i m xs) | (i, item) <- zip [0 ..] xs, m <- searchMoves table (descriptorArgument 1 d) item]\n  (\"maybe\", SData tag [inner]) -> [SData tag [m] | m <- searchMoves table (descriptorArgument 1 d) inner]\n  (\"either\", SData tag [inner]) -> [SData tag [m] | m <- searchMoves table (descriptorArgument (if tag == \"Either::Left\" then 1 else 2) d) inner]\n  (\"data\", SData tag fields) -> case [fs | c <- constructorsOf d, let (t', fs) = constructorParts c, t' == tag] of\n    forms : _ -> [SData tag (replace i m fields) | (i, (f, field)) <- zip [0 ..] (zip forms fields), m <- searchMoves table f field]\n    [] -> []\n  _ -> []\n  where\n    d = resolveDescriptor table d0\n    replace :: Int -> a -> [a] -> [a]\n    replace i m xs = take i xs ++ [m] ++ drop (i + 1) xs\n\nsearchClimb :: String -> [String] -> ([Scalar] -> IO (Maybe Double)) -> IO ()\nsearchClimb law descriptors check = do\n  seedText <- lookupEnv \"LAWSPEC_SEED\"\n  let tables = map valuesFrom descriptors\n      base = maybe 0 (\\t -> case reads t of [(n, \"\")] -> n; _ -> 0) seedText :: Word64\n      generate seed = fst (runDraw (mapM (\\(table, d) -> generateValue table d 8) tables) seed)\n  best <- newIORef (Nothing :: Maybe (Double, [Scalar]))\n  tried <- newIORef (0 :: Int)\n  let attempt values = do\n        n <- readIORef tried\n        if n >= 400 then pure False else do\n          writeIORef tried (n + 1)\n          score <- check values `catch` \\(e :: SomeException) -> searchRemember law descriptors values >> throwIO e\n          current <- readIORef best\n          case (score, current) of\n            (Just s, Just (b, _)) | not (s > b) -> pure False\n            (Just s, _) -> writeIORef best (Just (s, values)) >> pure True\n            (Nothing, _) -> pure False\n  forM_ [0 .. 9] $ \\k -> attempt (generate (base + k))\n  forM_ [0 .. 59 :: Word64] $ \\step -> do\n    n <- readIORef tried\n    if n >= 400 then pure () else do\n      current <- readIORef best\n      rose <- case current of\n        Nothing -> pure False\n        Just (_, values) -> do\n          let moves = take 24 [ take i values ++ [m] ++ drop (i + 1) values\n                              | (i, ((table, d), v)) <- zip [0 ..] (zip tables values), m <- searchMoves table d v ]\n          or <$> mapM attempt moves\n      if rose then pure () else () <$ attempt (generate (base + 1000 + step))\n  n <- readIORef tried\n  final <- readIORef best\n  putStrLn (law ++ \": targeted search tried \" ++ show n ++ \" case(s)\" ++ maybe \"\" (\\(s, _) -> \"; best score \" ++ show s) final)\n\n-- | A score as a Double: the targeted search maximizes it.\nsearchNumber :: Scalar -> Double\nsearchNumber v = case v of\n  SInteger _ n -> fromInteger n\n  _ -> case reads (renderValue v) of\n    [(d, \"\")] -> d\n    _ -> 0 / 0\n\n-- | count values generated from one seed, encoded, in hexadecimal.\nwireEncoded :: String -> Word64 -> Integer -> Integer -> [String]\nwireEncoded text seed size count =\n  let (table, d) = valuesFrom text\n      values = fst (runDraw (replicateM (fromInteger count) (generateValue table d size)) seed)\n  in map (either error hexOf . wireEncode table d) values\n\n-- | Whether count generated values decode to themselves.\nwireRoundTrips :: String -> Word64 -> Integer -> Integer -> Bool\nwireRoundTrips text seed size count =\n  let (table, d) = valuesFrom text\n      values = fst (runDraw (replicateM (fromInteger count) (generateValue table d size)) seed)\n  in all (\\v -> fmap renderValue (wireEncode table d v >>= wireDecode table d) == Right (renderValue v)) values\n\norWire :: Either String a -> IO a\norWire = either (throwIO . WireError) pure\n\ntextOf :: String -> BB.Builder\ntextOf = putBytes . TE.encodeUtf8 . T.pack\n\ngetText :: ByteString -> Int -> Either String (String, Int)\ngetText buf pos = do\n  (raw, pos') <- getBytes buf pos\n  either (const (Left \"text that is not UTF-8\")) (\\t -> Right (T.unpack t, pos')) (TE.decodeUtf8' raw)\n\nbuild :: BB.Builder -> ByteString\nbuild = BL.toStrict . BB.toLazyByteString\n\n-- | A frame: kind, entity name, the sender's address, an id, a payload.\nencodeFrame :: String -> String -> String -> Integer -> ByteString -> ByteString\nencodeFrame kind to source ident payload =\n  build (textOf kind <> textOf to <> textOf source <> putVarint (zigzag ident) <> putBytes payload)\n\ndecodeFrame :: ByteString -> Either String (String, String, String, Integer, ByteString)\ndecodeFrame buf = do\n  (kind, p1) <- getText buf 0\n  (to, p2) <- getText buf p1\n  (source, p3) <- getText buf p2\n  (z, p4) <- getVarint buf p3\n  (payload, p5) <- getBytes buf p4\n  if p5 /= B.length buf then Left \"extra bytes after a frame\" else Right (kind, to, source, unzigzag z, payload)\n\n-- | 'tcp://host:port/name' as ('tcp://host:port', 'name').\nsplitAddress :: String -> IO (String, String)\nsplitAddress address =\n  let (nameRev, rest) = break (== '/') (reverse address)\n      node = reverse (drop 1 rest)\n  in if null rest || not (T.isInfixOf (T.pack \"://\") (T.pack node))\n       then throwIO (ErrorCall (show address ++ \" is not an address such as tcp://127.0.0.1:7000/name\"))\n       else pure (node, reverse nameRev)\n\n-- | Moves frames between nodes: start begins delivering every frame that\n-- arrives; send sends one to the node at an address, best effort (throwing\n-- Unreachable when it cannot); close stops.\ndata Transport = Transport\n  { transportAddress :: String\n  , transportStart :: (ByteString -> IO ()) -> IO ()\n  , transportSend :: String -> ByteString -> IO ()\n  , transportClose :: IO ()\n  }\n\n-- | Nodes in one process, with faults for testing: each frame may be lost\n-- or duplicated, and is delayed by up to the delay (so frames overtake each\n-- other); partitionNetwork cuts nodes off until healNetwork.\ndata MemoryNetwork = MemoryNetwork\n  { networkState :: MVar (Word64, [(String, ByteString -> IO ())], Maybe [[String]])\n  , networkLoss :: Double\n  , networkDuplicate :: Double\n  -- The longest delay, in seconds.\n  , networkDelay :: Double\n  -- Every record sent, newest first, when the network records them.\n  , networkRecording :: Maybe (IORef [ByteString])\n  }\n\nnewMemoryNetwork :: Word64 -> Double -> Double -> Double -> IO MemoryNetwork\nnewMemoryNetwork seed loss duplicate delay = do\n  state <- newMVar (seed, [], Nothing)\n  pure (MemoryNetwork state loss duplicate delay Nothing)\n\n-- | A memory network that records every record sent, as it saw them\n-- (networkRecorded).\nnewRecordingMemoryNetwork :: Word64 -> Double -> Double -> Double -> IO MemoryNetwork\nnewRecordingMemoryNetwork seed loss duplicate delay = do\n  network <- newMemoryNetwork seed loss duplicate delay\n  recording <- newIORef []\n  pure network { networkRecording = Just recording }\n\n-- | Every record sent so far, in order (none when the network does not\n-- record).\nnetworkRecorded :: MemoryNetwork -> IO [ByteString]\nnetworkRecorded network = maybe (pure []) (fmap reverse . readIORef) (networkRecording network)\n\nmemoryTransport :: MemoryNetwork -> String -> Transport\nmemoryTransport network name = Transport\n  { transportAddress = address\n  , transportStart = \\deliver -> modifyMVar (networkState network) (\\(r, nodes, groups) ->\n      pure ((r, (address, deliver) : filter ((/= address) . fst) nodes, groups), ()))\n  , transportSend = memorySend network address\n  , transportClose = modifyMVar (networkState network) (\\(r, nodes, groups) ->\n      pure ((r, filter ((/= address) . fst) nodes, groups), ()))\n  }\n  where address = \"mem://\" ++ name\n\n-- | Only nodes named in the same group reach each other.\npartitionNetwork :: MemoryNetwork -> [[String]] -> IO ()\npartitionNetwork network groups = modifyMVar (networkState network) (\\(r, nodes, _) ->\n  pure ((r, nodes, Just (map (map (\"mem://\" ++)) groups)), ()))\n\nhealNetwork :: MemoryNetwork -> IO ()\nhealNetwork network = modifyMVar (networkState network) (\\(r, nodes, _) -> pure ((r, nodes, Nothing), ()))\n\nmemorySend :: MemoryNetwork -> String -> String -> ByteString -> IO ()\nmemorySend network source node frame = do\n  plan <- modifyMVar (networkState network) $ \\(r0, nodes, groups) -> do\n    forM_ (networkRecording network) (\\recording -> modifyIORef' recording (frame :))\n    case lookup node nodes of\n      Nothing -> pure ((r0, nodes, groups), Left ())\n      Just deliver\n        | maybe False (\\gs -> not (any (\\g -> source `elem` g && node `elem` g) gs)) groups -> pure ((r0, nodes, groups), Right [])\n        | otherwise -> do\n            let below k r = let (x, r') = splitMix64 r in (toInteger x `mod` k, r')\n                chance p r = if p <= 0 then (False, r) else\n                  let (x, r') = below (bit 30) r in (fromInteger x < p * 2 ^ (30 :: Int), r')\n                (lost, r1) = chance (networkLoss network) r0\n                (twice, r2) = chance (networkDuplicate network) r1\n                copies = if twice then 2 else 1 :: Int\n                (delays, r3) = foldl (\\(acc, r) _ -> let (k, r') = below 1001 r in (acc ++ [k], r')) ([], r2) [1 .. copies]\n            pure ((r3, nodes, groups), Right (if lost then [] else [(deliver, k) | k <- delays]))\n  case plan of\n    Left () -> throwIO (Unreachable (\"no node at \" ++ node))\n    Right sends -> forM_ sends $ \\(deliver, k) -> forkIO (do\n      let micros = round (fromInteger k * networkDelay network * 1000) :: Int\n      if micros > 0 then threadDelay micros else yield\n      deliver frame `catch` \\(_ :: SomeException) -> pure ())\n\n-- The secure network handler lives in LawSpecNetwork, which the compiler\n-- writes beside this runtime when a program imports lawspec.network: it\n-- needs the crypto libraries (crypton and the ML-KEM and ML-DSA packages), which programs without\n-- nodes do without. LawSpecNetwork.install registers it here (the generated\n-- tests call it); a node on any transport but the insecure one made for\n-- tests asks it for its layer.\n\n-- | A node's secure layer: send seals a frame to the node at an address\n-- (after a handshake), receive gives the frame a record carries, or Nothing\n-- (a handshake record, or one that fails to verify or open), and identity\n-- is the node's identity (a LawSpecNetwork.NodeIdentity).\ndata NodeLayer = NodeLayer\n  { layerSend :: String -> ByteString -> IO ()\n  , layerReceive :: ByteString -> IO (Maybe ByteString)\n  , layerIdentity :: Dynamic }\n\n-- | The secure network handler: a node's layer, from its transport and the\n-- flag closeNode sets; and one-time tokens from the secure generator.\ndata SecureNetwork = SecureNetwork\n  { secureLayerFor :: Transport -> IORef Bool -> IO NodeLayer\n  , secureNetworkToken :: IO String }\n\n{-# NOINLINE secureNetworkSlot #-}\nsecureNetworkSlot :: IORef (Maybe SecureNetwork)\nsecureNetworkSlot = unsafePerformIO (newIORef Nothing)\n\n-- | Installs the secure network handler (LawSpecNetwork.install does).\nregisterSecureNetwork :: SecureNetwork -> IO ()\nregisterSecureNetwork = writeIORef secureNetworkSlot . Just\n\n-- | The installed secure network handler, or a clear failure.\nsecureNetwork :: IO SecureNetwork\nsecureNetwork = readIORef secureNetworkSlot >>= maybe (throwIO (ErrorCall\n  (\"a node needs the secure network handler: add `import lawspec.network` to a unit of the program, \"\n    ++ \"and call LawSpecNetwork.install\"))) pure\n\n-- | A one-time token from a secure generator: 32 bytes as 64 hexadecimal\n-- digits, as SecureRandom's secureToken gives. From the secure network\n-- handler when one is installed, else from /dev/urandom (base has no secure\n-- generator of its own).\nsecureToken :: IO String\nsecureToken = readIORef secureNetworkSlot >>= \\installed -> case installed of\n  Just network -> secureNetworkToken network\n  Nothing -> do\n    bytes <- try (withBinaryFile \"/dev/urandom\" ReadMode (\\h -> B.hGet h 32))\n    case bytes of\n      Right raw | B.length raw == 32 -> pure (hexOf raw)\n      Right _ -> failed \"it gave too few bytes\"\n      Left (e :: SomeException) -> failed (displayException e)\n  where\n    failed why = throwIO (ErrorCall (\"no secure generator for a one-time token: /dev/urandom failed (\" ++ why\n      ++ \"); add `import lawspec.network` to a unit of the program and call LawSpecNetwork.install\"))\n\n-- | A transport whose node skips the handshake and sends frames in the\n-- clear: for tests of the frame layer only. Only an in-memory network makes\n-- one (insecureTransportForTests), and no configuration selects it.\ndata InsecureMemoryTransport = InsecureMemoryTransport MemoryNetwork String\n\ninsecureTransportForTests :: MemoryNetwork -> String -> InsecureMemoryTransport\ninsecureTransportForTests = InsecureMemoryTransport\n\n-- | What a node can be made on: a Transport (secure), or the in-memory\n-- transport made for tests only (insecure).\nclass NodeTransport t where\n  nodeLink :: t -> Either InsecureMemoryTransport Transport\n\ninstance NodeTransport Transport where\n  nodeLink = Right\n\ninstance NodeTransport InsecureMemoryTransport where\n  nodeLink = Left\n\n-- | A process's presence on a network: it names local mailboxes, actors,\n-- channel ends and definitions, so other nodes reach them at\n-- <node address>/<name>, and sends to theirs. Order is kept within one\n-- channel; an actor call or an evaluation is sent again until answered\n-- (the receiver runs it once), failing with Unreachable after its timeout.\n--\n-- Every target's node speaks the same frames, so nodes written in different\n-- languages talk to each other. ref:DEC-distribution-canonical-wire\n-- Frames cross sealed, after a handshake (the secure network handler's\n-- NodeLayer), unless the node is on the in-memory transport made for tests\n-- only.\ndata Node = Node\n  { nodeTransport :: Transport\n  , nodeAddress :: String\n  , nodeEntities :: IORef [(String, Entity)]\n  , nodePending :: IORef [(Integer, MVar ByteString)]\n  -- Requests already seen, by sender and id, with the reply once sent.\n  , nodeSeen :: IORef [((String, Integer), Maybe ByteString)]\n  , nodeIds :: IORef Integer\n  , nodeClosed :: IORef Bool\n  -- Nothing on the insecure transport made for tests.\n  , nodeSecure :: Maybe NodeLayer\n  }\n\n-- | What a registered name does with a frame: kind, source, id, payload.\nnewtype Entity = Entity (Node -> String -> String -> Integer -> ByteString -> IO ())\n\n-- | A node on a transport, with the identity lawspec.json binds (or a fresh\n-- one), talking to any peer: its layer comes from the installed secure\n-- network handler (LawSpecNetwork.install). LawSpecNetwork.newNodeWith\n-- takes an identity and trusted peers.\nnewNode :: NodeTransport t => t -> IO Node\nnewNode = newNodeLayered (\\transport closed -> secureNetwork >>= \\network -> secureLayerFor network transport closed)\n\n-- | A node whose layer the function makes from its transport and closed\n-- flag. The in-memory transport made for tests only\n-- (insecureTransportForTests) skips the layer, and so the handshake; no\n-- other transport can.\nnewNodeLayered :: NodeTransport t => (Transport -> IORef Bool -> IO NodeLayer) -> t -> IO Node\nnewNodeLayered layered made = do\n  closed <- newIORef False\n  (transport, secure) <- case nodeLink made of\n    Left (InsecureMemoryTransport network name) -> pure (memoryTransport network name, Nothing)\n    Right transport -> (\\layer -> (transport, Just layer)) <$> layered transport closed\n  node <- Node transport (transportAddress transport) <$> newIORef [] <*> newIORef [] <*> newIORef [] <*> newIORef 0\n    <*> pure closed <*> pure secure\n  transportStart transport (arriveRecord node)\n  pure node\n\narriveRecord :: Node -> ByteString -> IO ()\narriveRecord node record = case nodeSecure node of\n  Nothing -> deliverFrame node record\n  Just layer -> layerReceive layer record >>= maybe (pure ()) (deliverFrame node)\n\n-- | Sends a frame to the node at target: sealed, or in the clear on the\n-- insecure transport made for tests.\ntransmitFrame :: Node -> String -> ByteString -> IO ()\ntransmitFrame node target frame = case nodeSecure node of\n  Nothing -> transportSend (nodeTransport node) target frame\n  Just layer -> layerSend layer target frame\n\ncloseNode :: Node -> IO ()\ncloseNode node = writeIORef (nodeClosed node) True >> transportClose (nodeTransport node)\n\n-- | Passes a frame on to address unchanged, keeping its source.\nforwardFrame :: Node -> String -> String -> String -> Integer -> ByteString -> IO ()\nforwardFrame node address kind source ident payload = (do\n  (target, name) <- splitAddress address\n  transmitFrame node target (encodeFrame kind name source ident payload))\n  `catch` \\(_ :: SomeException) -> pure ()\n\nnextId :: Node -> IO Integer\nnextId node = atomicModifyIORef' (nodeIds node) (\\i -> (i + 1, i + 1))\n\nsendFrame :: Node -> String -> String -> ByteString -> Integer -> IO ()\nsendFrame node address kind payload ident = do\n  (target, name) <- splitAddress address\n  transmitFrame node target (encodeFrame kind name (nodeAddress node) ident payload)\n\nregister :: Node -> String -> Entity -> IO String\nregister node name entity = do\n  if null name || '/' `elem` name then throwIO (ErrorCall (show name ++ \" is not a name: use letters, digits and dashes\")) else pure ()\n  taken <- atomicModifyIORef' (nodeEntities node) (\\es -> case lookup name es of\n    Just _ -> (es, True)\n    Nothing -> ((name, entity) : es, False))\n  if taken then throwIO (ErrorCall (name ++ \" is already registered on \" ++ nodeAddress node)) else pure ()\n  pure (nodeAddress node ++ \"/\" ++ name)\n\ndeliverFrame :: Node -> ByteString -> IO ()\ndeliverFrame node frame = case decodeFrame frame of\n  Left _ -> pure ()\n  Right (kind, to, source, ident, payload)\n    | kind == \"reply\" -> do\n        slot <- atomicModifyIORef' (nodePending node) (\\ps -> (filter ((/= ident) . fst) ps, lookup ident ps))\n        forM_ slot (\\s -> tryPutMVar s payload)\n    | otherwise -> do\n        entities <- readIORef (nodeEntities node)\n        case lookup to entities of\n          Nothing -> if ident /= 0 then replyTo node source ident 3 (utf8Of (map ord (\"nothing is registered as \" ++ to ++ \" on \" ++ nodeAddress node))) else pure ()\n          Just (Entity receive) -> do\n            fresh <- if ident == 0 then pure True else do\n              let key = (source, ident)\n              found <- atomicModifyIORef' (nodeSeen node) (\\seen -> case lookup key seen of\n                Just answer -> (seen, Just answer)\n                Nothing -> (take 4000 ((key, Nothing) : seen), Nothing))\n              case found of\n                Just (Just answer) -> forkIO (sendFrame node (source ++ \"/\") \"reply\" answer ident\n                  `catch` \\(_ :: SomeException) -> pure ()) >> pure False\n                Just Nothing -> pure False\n                Nothing -> pure True\n            -- Handled off the transport's thread, so a slow handler does\n            -- not hold up other frames.\n            if fresh then () <$ forkIO (receive node kind source ident payload `catch` \\(_ :: SomeException) -> pure ()) else pure ()\n\nreplyTo :: Node -> String -> Integer -> Word8 -> ByteString -> IO ()\nreplyTo node source ident status body = do\n  let payload = B.cons status body\n  atomicModifyIORef' (nodeSeen node) (\\seen -> ([(k, if k == (source, ident) then Just payload else a) | (k, a) <- seen], ()))\n  sendFrame node (source ++ \"/\") \"reply\" payload ident `catch` \\(_ :: SomeException) -> pure ()\n\n-- | Sends a request until its reply arrives: (status, body).\nrequest :: Node -> String -> String -> ByteString -> Double -> IO (Word8, ByteString)\nrequest node address kind payload seconds = do\n  ident <- nextId node\n  slot <- newEmptyMVar\n  atomicModifyIORef' (nodePending node) (\\ps -> ((ident, slot) : ps, ()))\n  start <- getMonotonicTimeNSec\n  let deadline = start + round (seconds * 1e9)\n      loop = do\n        sendFrame node address kind payload ident `catch` \\(_ :: SomeException) -> pure ()\n        now <- getMonotonicTimeNSec\n        let left = if deadline > now then fromIntegral ((deadline - now) `div` 1000) else 0\n        got <- timeout (max 1 (min 100000 left)) (readMVar slot)\n        case got of\n          Just answer -> pure (B.head answer, B.tail answer)\n          Nothing -> do\n            now' <- getMonotonicTimeNSec\n            if now' >= deadline then do\n              atomicModifyIORef' (nodePending node) (\\ps -> (filter ((/= ident) . fst) ps, ()))\n              throwIO (Unreachable (address ++ \" did not answer within \" ++ show seconds ++ \"s\"))\n            else loop\n  loop\n\nreplyValue :: DataTable -> Descriptor -> (Word8, ByteString) -> IO Scalar\nreplyValue table d (status, body) = case status of\n  0 -> orWire (wireDecode table d body)\n  1 -> throwIO (ActorCrashed (toException (ErrorCall message)))\n  2 -> throwIO ActorStopped\n  _ -> throwIO (Unreachable message)\n  where message = either (const \"\") T.unpack (TE.decodeUtf8' body)\n\nencodeAll :: DataTable -> [Descriptor] -> [Scalar] -> Either String BB.Builder\nencodeAll table ds vs\n  | length ds /= length vs = Left \"wrong number of arguments\"\n  | otherwise = mconcat <$> sequence (zipWith (wirePut table) ds vs)\n\ndecodeAll :: DataTable -> [Descriptor] -> ByteString -> Int -> Either String [Scalar]\ndecodeAll table ds buf pos0 = go ds pos0 []\n  where\n    go [] p acc = if p /= B.length buf then Left \"extra bytes after the arguments\" else Right (reverse acc)\n    go (d : rest) p acc = do\n      (v, p') <- wireGet table d buf p\n      go rest p' (v : acc)\n\n-- | A local mailbox that other nodes send to at <address>/name. Each\n-- message is acknowledged once it is in the mailbox.\nnodeMailbox :: Node -> String -> DataTable -> Descriptor -> IO (Mailbox Scalar)\nnodeMailbox node name table d = do\n  box <- newMailbox\n  _ <- register node name (Entity (\\_ kind source ident payload ->\n    if kind /= \"mail\" then pure () else do\n      outcome <- case wireDecode table d payload of\n        Left e -> pure (3, \"not a message of this mailbox: \" ++ e)\n        Right v -> (sendMailbox box v >> pure (0, \"\")) `catch` \\ActorStopped -> pure (2, \"the mailbox is closed\")\n      if ident /= 0 then replyTo node source ident (fst outcome) (utf8Of (map ord (snd outcome))) else pure ()))\n  pure box\n\n-- | Sends to a mailbox on another node. A send waits until the mailbox has\n-- the message (resending a lost one; the mailbox takes it once), and throws\n-- Unreachable after the timeout (seconds), or ActorStopped if it is closed.\ndata RemoteMailbox = RemoteMailbox Node String DataTable Descriptor Double\n\nremoteMailbox :: Node -> String -> DataTable -> Descriptor -> RemoteMailbox\nremoteMailbox node address table d = RemoteMailbox node address table d 5\n\nremoteMailboxWithin :: Node -> String -> DataTable -> Descriptor -> Double -> RemoteMailbox\nremoteMailboxWithin = RemoteMailbox\n\nsendRemote :: RemoteMailbox -> Scalar -> IO ()\nsendRemote (RemoteMailbox node address table d seconds) v = do\n  payload <- orWire (wireEncode table d v)\n  answer <- request node address \"mail\" payload seconds\n  if fst answer == 0 then pure () else () <$ replyValue table (DescList [DescAtom \"unit\"]) answer\n\n-- | A message an actor serves to other nodes: its name, argument and reply\n-- descriptors, and the handler on logical values (state first).\ntype ServedMessage s = (String, [Descriptor], Descriptor, s -> [Scalar] -> IO (Scalar, s))\n\n-- | Lets other nodes call an actor at <address>/name; returns that address.\nserveActor :: Node -> String -> Actor s -> DataTable -> [ServedMessage s] -> IO String\nserveActor node name actor table messages = register node name (Entity receive)\n  where\n    receive _ kind source ident payload\n      | kind /= \"call\" = pure ()\n      | otherwise = case getText payload 0 of\n          Left e -> replyTo node source ident 3 (utf8Of (map ord e))\n          Right (message, pos) -> case [m | m@(n, _, _, _) <- messages, n == message] of\n            [] -> replyTo node source ident 3 (utf8Of (map ord (\"not a message this actor handles: \" ++ message)))\n            (_, ds, r, handler) : _ -> case decodeAll table ds payload pos of\n              Left e -> replyTo node source ident 3 (utf8Of (map ord (\"not a message this actor handles: \" ++ e)))\n              Right args -> do\n                outcome <- try (callActor actor (\\state -> handler state args))\n                case outcome of\n                  Right value -> case wireEncode table r value of\n                    Right bytes -> replyTo node source ident 0 bytes\n                    Left e -> replyTo node source ident 1 (utf8Of (map ord e))\n                  Left e -> case fromException e of\n                    Just ActorStopped -> replyTo node source ident 2 (utf8Of (map ord \"the actor has stopped\"))\n                    Nothing -> replyTo node source ident 1 (utf8Of (map ord (exceptionText e)))\n\n-- | An actor on another node: each call sends its message and waits for the\n-- reply, throwing Unreachable after the timeout (seconds), or what the\n-- actor's call threw (ActorCrashed, ActorStopped).\ndata RemoteActor = RemoteActor Node String DataTable [(String, ([Descriptor], Descriptor))] Double\n\nremoteActor :: Node -> String -> DataTable -> [(String, ([Descriptor], Descriptor))] -> Double -> RemoteActor\nremoteActor = RemoteActor\n\ncallRemote :: RemoteActor -> String -> [Scalar] -> IO Scalar\ncallRemote (RemoteActor node address table signatures seconds) message args = case lookup message signatures of\n  Nothing -> throwIO (ErrorCall (\"no message \" ++ message))\n  Just (ds, r) -> do\n    payload <- build . (textOf message <>) <$> orWire (encodeAll table ds args)\n    request node address \"call\" payload seconds >>= replyValue table r\n\n-- | Lets other nodes evaluate definitions, each by its content hash:\n-- (hash, function, argument descriptors, result descriptor).\nserveDefinitions :: Node -> DataTable -> [(String, [Scalar] -> IO Scalar, [Descriptor], Descriptor)] -> IO String\nserveDefinitions node table definitions = register node \"definitions\" (Entity receive)\n  where\n    receive _ kind source ident payload\n      | kind /= \"eval\" = pure ()\n      | otherwise = case getText payload 0 of\n          Right (digest, pos) | ((_, f, ds, r) : _) <- [x | x@(h, _, _, _) <- definitions, h == digest]\n                              , Right args <- decodeAll table ds payload pos -> do\n            outcome <- try (f args >>= \\v -> evaluate (deepScalar v) >> pure v)\n            case outcome of\n              Right value -> either (\\e -> replyTo node source ident 1 (utf8Of (map ord e))) (replyTo node source ident 0) (wireEncode table r value)\n              Left e -> replyTo node source ident 1 (utf8Of (map ord (exceptionText e)))\n          _ -> replyTo node source ident 3 (utf8Of (map ord \"this node has no definition with that content hash\"))\n\n-- | Evaluates the definition with this content hash on another node.\nevaluateRemote :: Node -> String -> String -> [Scalar] -> [Descriptor] -> Descriptor -> DataTable -> Double -> IO Scalar\nevaluateRemote node target digest args ds r table seconds = do\n  payload <- build . (textOf digest <>) <$> orWire (encodeAll table ds args)\n  request node (target ++ \"/definitions\") \"eval\" payload seconds >>= replyValue table r\n\n-- | One end of a channel between nodes. Each value travels in a numbered\n-- frame sent again until acknowledged, so loss, duplication and reordering\n-- are repaired; a peer silent past the deadline fails the end (PeerFailed).\n-- Order is kept within the channel.\n--\n-- An unused end can move to another node: offerEndpoint gives the address\n-- the new node takes it over from (<address>?take=<token>). On a take frame\n-- with that token, this end hands its state over (a state frame) and from\n-- then on forwards every frame it gets to the new end; the new end tells\n-- the peer (a moved frame) so the peer sends to it directly.\ndata NetEndpoint = NetEndpoint\n  { endpointNode :: Node\n  , endpointSteps :: [(Bool, Descriptor)]\n  , endpointTable :: DataTable\n  , endpointDeadline :: Double\n  , endpointAddress :: IORef String\n  , endpointState :: MVar EndpointState\n  , endpointInbox :: Chan (Either String ByteString)\n  , endpointStep :: IORef Int\n  , endpointTaken :: MVar ()\n  , endpointConfirmed :: MVar ()\n  }\n\ndata EndpointState = EndpointState\n  { esPeer :: Maybe String\n  , esOut :: Integer\n  -- seq -> (payload, first sent, last sent, body), monotonic nanoseconds.\n  , esUnacked :: [(Integer, (ByteString, Word64, Word64, ByteString))]\n  , esExpected :: Integer\n  , esEarly :: [(Integer, ByteString)]\n  , esGone :: Bool\n  , esFailure :: String\n  -- Values delivered before the first receive, newest first: what an\n  -- unused end hands over when it moves.\n  , esDelivered :: [ByteString]\n  -- Moving: the addresses this end had before (oldest first), the token a\n  -- taker must show, where the end went and the state frame it was given,\n  -- and, on the new node, the token of the takeover in progress.\n  , esHistory :: [String]\n  , esToken :: Maybe String\n  , esMovedTo :: Maybe String\n  , esHanded :: ByteString\n  , esTaking :: Maybe String\n  , esTaken :: Bool\n  , esAnnouncing :: Bool\n  , esAnnouncedAt :: Word64\n  , esConfirmed :: Bool\n  }\n\nnewEndpoint :: Node -> [(Bool, Descriptor)] -> DataTable -> Double -> IO NetEndpoint\nnewEndpoint node steps table deadline = do\n  endpoint <- NetEndpoint node steps table deadline <$> newIORef \"\"\n    <*> newMVar (EndpointState Nothing 0 [] 0 [] False \"\" [] [] Nothing Nothing B.empty Nothing False False 0 False)\n    <*> newChan <*> newIORef 0 <*> newEmptyMVar <*> newEmptyMVar\n  _ <- forkIO (resendLoop endpoint deadline)\n  pure endpoint\n\n-- | The first end of a channel named name here; its other end is dialed\n-- from any node. steps: (sends, descriptor) per step, from this end's side.\nlistenOn :: Node -> String -> [(Bool, Descriptor)] -> DataTable -> IO NetEndpoint\nlistenOn node name steps table = do\n  endpoint <- newEndpoint node steps table 5\n  address <- register node name (Entity (endpointReceive endpoint))\n  writeIORef (endpointAddress endpoint) address\n  pure endpoint\n\n-- | The second end of the channel listening at address; steps are from\n-- this end's side.\ndialTo :: Node -> String -> [(Bool, Descriptor)] -> DataTable -> IO NetEndpoint\ndialTo node address steps table = do\n  endpoint <- newEndpoint node steps table 5\n  n <- nextId node\n  own <- register node (\"end-\" ++ show n) (Entity (endpointReceive endpoint))\n  writeIORef (endpointAddress endpoint) own\n  modifyMVar (endpointState endpoint) (\\st -> pure (st { esPeer = Just address }, ()))\n  transmit endpoint (-1) (utf8Of (map ord \"hello\"))\n  pure endpoint\n\n-- | Takes over a channel end another node moves here: address is\n-- <old address>?take=<token>, as that node offered it. Returns once the\n-- end's state has arrived and its peer has been told (or after the\n-- deadline; the old node then forwards to the end).\ntakeFrom :: Node -> String -> [(Bool, Descriptor)] -> DataTable -> IO NetEndpoint\ntakeFrom node address steps table = do\n  endpoint <- newEndpoint node steps table 5\n  n <- nextId node\n  own <- register node (\"end-\" ++ show n) (Entity (endpointReceive endpoint))\n  writeIORef (endpointAddress endpoint) own\n  let (old, query) = break (== '?') address\n      token = drop (length \"?take=\") query\n  modifyMVar (endpointState endpoint) (\\st -> pure (st { esTaking = Just token }, ()))\n  let asking = build (textOf token <> textOf own)\n      micros = round (endpointDeadline endpoint * 1e6) :: Int\n  start <- getMonotonicTimeNSec\n  let giveUp = start + round (endpointDeadline endpoint * 1e9)\n      left = do\n        now <- getMonotonicTimeNSec\n        pure (if giveUp > now then fromIntegral ((giveUp - now) `div` 1000) else 0)\n      ask = do\n        sendFrame node old \"take\" asking 0 `catch` \\(_ :: SomeException) -> pure ()\n        got <- timeout 50000 (readMVar (endpointTaken endpoint))\n        case got of\n          Just () -> do\n            wait <- left\n            _ <- timeout (max 0 (min micros wait)) (readMVar (endpointConfirmed endpoint))\n            pure ()\n          Nothing -> do\n            wait <- left\n            if wait <= 0\n              then do\n                modifyMVar (endpointState endpoint) (\\st -> pure (st { esTaking = Nothing }, ()))\n                failEndpoint endpoint \"the node the end came from did not hand it over in time (unreachable)\"\n              else ask\n  ask\n  pure endpoint\n\n-- | The address another node takes this unused end over from.\nofferEndpoint :: NetEndpoint -> IO String\nofferEndpoint endpoint = do\n  address <- readIORef (endpointAddress endpoint)\n  fresh <- secureToken\n  token <- modifyMVar (endpointState endpoint) (\\st -> case esToken st of\n    Just t -> pure (st, t)\n    Nothing -> pure (st { esToken = Just fresh }, fresh))\n  pure (address ++ \"?take=\" ++ token)\n\nseqBytes :: Integer -> BB.Builder\nseqBytes = putVarint . zigzag\n\ngetSeq :: ByteString -> Int -> Either String (Integer, Int)\ngetSeq buf pos = (\\(z, p) -> (unzigzag z, p)) <$> getVarint buf pos\n\nputTexts :: [String] -> BB.Builder\nputTexts texts = putVarint (toInteger (length texts)) <> foldMap textOf texts\n\ngetMany :: (ByteString -> Int -> Either String (a, Int)) -> ByteString -> Int -> Either String ([a], Int)\ngetMany one buf pos0 = do\n  (count, pos1) <- getVarint buf pos0\n  let go 0 p acc = Right (reverse acc, p)\n      go k p acc = one buf p >>= \\(x, p') -> go (k - 1 :: Integer) p' (x : acc)\n  go count pos1 []\n\nputNumbered :: [(Integer, ByteString)] -> BB.Builder\nputNumbered items =\n  let sorted = sortBy (\\x y -> compare (fst x) (fst y)) items\n  in putVarint (toInteger (length sorted)) <> foldMap (\\(s, b) -> seqBytes s <> putBytes b) sorted\n\ngetNumbered :: ByteString -> Int -> Either String ([(Integer, ByteString)], Int)\ngetNumbered = getMany (\\buf p -> do\n  (s, p1) <- getSeq buf p\n  (b, p2) <- getBytes buf p1\n  pure ((s, b), p2))\n\nframePayload :: NetEndpoint -> Integer -> ByteString -> IO ByteString\nframePayload endpoint seqNo body = do\n  address <- readIORef (endpointAddress endpoint)\n  pure (build (seqBytes seqNo <> textOf address <> BB.byteString body))\n\ntransmit :: NetEndpoint -> Integer -> ByteString -> IO ()\ntransmit endpoint seqNo body = do\n  payload <- framePayload endpoint seqNo body\n  now <- getMonotonicTimeNSec\n  peer <- modifyMVar (endpointState endpoint) (\\st ->\n    pure (st { esUnacked = (seqNo, (payload, now, now, body)) : filter ((/= seqNo) . fst) (esUnacked st) }, esPeer st))\n  forM_ peer (\\p -> sendFrame (endpointNode endpoint) p \"chan\" payload 0 `catch` \\(_ :: SomeException) -> pure ())\n\nresendLoop :: NetEndpoint -> Double -> IO ()\nresendLoop endpoint deadline = do\n  threadDelay 20000\n  closed <- readIORef (nodeClosed (endpointNode endpoint))\n  address <- readIORef (endpointAddress endpoint)\n  now <- getMonotonicTimeNSec\n  (stop, waiting, stale, peer, due, moved) <- modifyMVar (endpointState endpoint) $ \\st -> do\n    let due = [(s, payload) | (s, (payload, _, lastSent, _)) <- esUnacked st, now - lastSent > 50000000]\n        stale = or [now - first > round (deadline * 1e9) | (_, (_, first, lastSent, _)) <- esUnacked st, now - lastSent > 50000000]\n        touched = [(s, (payload, first, if any ((== s) . fst) due then now else lastSent, body)) | (s, (payload, first, lastSent, body)) <- esUnacked st]\n        announce = esAnnouncing st && esPeer st /= Nothing && not (esConfirmed st) && now - esAnnouncedAt st > 50000000\n        moved = if announce then Just (build (putTexts (esHistory st) <> textOf address)) else Nothing\n        waiting = esTaking st /= Nothing && not (esTaken st)\n        stop = closed || esGone st || esMovedTo st /= Nothing\n    if stop || waiting then pure (st, (stop, waiting, False, Nothing, [], Nothing))\n    else pure (st { esUnacked = touched, esAnnouncedAt = if announce then now else esAnnouncedAt st }, (False, False, stale, esPeer st, due, moved))\n  if stop then pure ()\n  else if waiting then resendLoop endpoint deadline\n  else if stale then failEndpoint endpoint \"the other end did not answer in time (unreachable)\"\n  else do\n    let quietly action = action `catch` \\(_ :: SomeException) -> pure ()\n    forM_ peer (\\p -> do\n      forM_ moved (\\payload -> quietly (sendFrame (endpointNode endpoint) p \"moved\" payload 0))\n      forM_ due (\\(_, payload) -> quietly (sendFrame (endpointNode endpoint) p \"chan\" payload 0)))\n    resendLoop endpoint deadline\n\nfailEndpoint :: NetEndpoint -> String -> IO ()\nfailEndpoint endpoint reason = do\n  first <- modifyMVar (endpointState endpoint) (\\st ->\n    pure (if esGone st then (st, False) else (st { esGone = True, esFailure = reason, esUnacked = [] }, True)))\n  if first then writeChan (endpointInbox endpoint) (Left reason) else pure ()\n\nendpointReceive :: NetEndpoint -> Node -> String -> String -> Integer -> ByteString -> IO ()\nendpointReceive endpoint node kind source ident payload\n  | kind == \"take\" = giveEndpoint endpoint payload\n  | otherwise = do\n      st0 <- readMVar (endpointState endpoint)\n      case esMovedTo st0 of\n        Just to -> forwardFrame node to kind source ident payload\n        Nothing\n          | esTaking st0 /= Nothing && not (esTaken st0) ->\n              -- Until the state arrives, frames are dropped: their senders\n              -- send them again.\n              if kind == \"state\" then installEndpoint endpoint payload else pure ()\n          | kind == \"ack\" -> case getSeq payload 0 of\n              Right (seqNo, _) -> modifyMVar (endpointState endpoint) (\\st ->\n                pure (st { esUnacked = filter ((/= seqNo) . fst) (esUnacked st) }, ()))\n              Left _ -> pure ()\n          | kind == \"moved\" -> peerMoved endpoint payload\n          | kind == \"moved-ack\" -> do\n              address <- readIORef (endpointAddress endpoint)\n              case getText payload 0 of\n                Right (to, _) | to == address -> do\n                  modifyMVar (endpointState endpoint) (\\st -> pure (st { esConfirmed = True }, ()))\n                  () <$ tryPutMVar (endpointConfirmed endpoint) ()\n                _ -> pure ()\n          | kind /= \"chan\" -> pure ()\n          | otherwise -> case parsed of\n              Left _ -> pure ()\n              Right (seqNo, sender, body) -> do\n                unused <- (== 0) <$> readIORef (endpointStep endpoint)\n                forward <- modifyMVar (endpointState endpoint) $ \\st -> case esMovedTo st of\n                  Just to -> pure (st, Just to)\n                  Nothing\n                    | seqNo == -1 -> pure (st { esPeer = maybe (Just sender) Just (esPeer st) }, Nothing)\n                    | seqNo < esExpected st || any ((== seqNo) . fst) (esEarly st) -> pure (st, Nothing)\n                    | otherwise -> do\n                        let early = (seqNo, body) : esEarly st\n                            collect expected held acc = case lookup expected held of\n                              Just b -> collect (expected + 1) (filter ((/= expected) . fst) held) (b : acc)\n                              Nothing -> (expected, held, reverse acc)\n                            (expected', held', out) = collect (esExpected st) early []\n                        mapM_ (writeChan (endpointInbox endpoint) . Right) out\n                        pure (st { esExpected = expected', esEarly = held'\n                                 , esDelivered = if unused then reverse out ++ esDelivered st else [] }, Nothing)\n                case forward of\n                  -- Moved meanwhile: the new end acknowledges it.\n                  Just to -> forwardFrame node to kind source ident payload\n                  Nothing -> sendFrame node sender \"ack\" (build (seqBytes seqNo)) 0 `catch` \\(_ :: SomeException) -> pure ()\n  where\n    parsed = do\n      (seqNo, p1) <- getSeq payload 0\n      (sender, p2) <- getText payload p1\n      pure (seqNo, sender, B.drop p2 payload)\n\n-- | A take frame: hands the state over once, to the first taker with the\n-- token, and answers that taker's repeats with the same state.\ngiveEndpoint :: NetEndpoint -> ByteString -> IO ()\ngiveEndpoint endpoint payload = case parsed of\n  Left _ -> pure ()\n  Right (token, taker) -> do\n    address <- readIORef (endpointAddress endpoint)\n    handed <- modifyMVar (endpointState endpoint) $ \\st ->\n      if esToken st /= Just token then pure (st, Nothing) else case esMovedTo st of\n        Just to | to /= taker -> pure (st, Nothing)\n                | otherwise -> pure (st, Just (esHanded st))\n        Nothing -> do\n          let state = build (textOf token <> textOf (esFailure st) <> textOf (maybe \"\" id (esPeer st))\n                <> putTexts (esHistory st ++ [address]) <> seqBytes (esOut st) <> seqBytes (esExpected st)\n                <> putNumbered [(s, body) | (s, (_, _, _, body)) <- esUnacked st]\n                <> putNumbered (esEarly st)\n                <> putVarint (toInteger (length (esDelivered st))) <> foldMap putBytes (reverse (esDelivered st)))\n          pure (st { esMovedTo = Just taker, esHanded = state, esUnacked = [], esEarly = [] }, Just state)\n    forM_ handed (\\state -> sendFrame (endpointNode endpoint) taker \"state\" state 0 `catch` \\(_ :: SomeException) -> pure ())\n  where\n    parsed = do\n      (token, p1) <- getText payload 0\n      (taker, _) <- getText payload p1\n      pure (token, taker)\n\ninstallEndpoint :: NetEndpoint -> ByteString -> IO ()\ninstallEndpoint endpoint payload = case parsed of\n  Left _ -> pure ()\n  Right (token, failure, peer, history, out, expected, unacked, early, received) -> do\n    now <- getMonotonicTimeNSec\n    frames <- mapM (\\(s, body) -> (\\p -> (s, (p, now, 0, body))) <$> framePayload endpoint s body) unacked\n    installed <- modifyMVar (endpointState endpoint) $ \\st ->\n      if esTaking st /= Just token || esTaken st then pure (st, False) else do\n        mapM_ (writeChan (endpointInbox endpoint) . Right) received\n        pure (st { esPeer = if null peer then Nothing else Just peer, esHistory = history, esOut = out\n                 , esExpected = expected, esUnacked = frames, esEarly = early, esDelivered = reverse received\n                 , esAnnouncing = True, esTaken = True }, True)\n    if installed then do\n      _ <- tryPutMVar (endpointTaken endpoint) ()\n      if null failure then pure () else failEndpoint endpoint failure\n    else pure ()\n  where\n    parsed = do\n      (token, p1) <- getText payload 0\n      (failure, p2) <- getText payload p1\n      (peer, p3) <- getText payload p2\n      (history, p4) <- getMany getText payload p3\n      (out, p5) <- getSeq payload p4\n      (expected, p6) <- getSeq payload p5\n      (unacked, p7) <- getNumbered payload p6\n      (early, p8) <- getNumbered payload p7\n      (received, _) <- getMany getBytes payload p8\n      pure (token, failure, peer, history, out, expected, unacked, early, received)\n\n-- | The peer moved: from now on send to its new address.\npeerMoved :: NetEndpoint -> ByteString -> IO ()\npeerMoved endpoint payload = case parsed of\n  Left _ -> pure ()\n  Right (history, to) -> do\n    known <- modifyMVar (endpointState endpoint) $ \\st -> do\n      let peer = case esPeer st of\n            Nothing -> Just to\n            Just p | p `elem` history -> Just to\n                   | otherwise -> Just p\n      pure (st { esPeer = peer }, peer == Just to)\n    if known\n      then sendFrame (endpointNode endpoint) to \"moved-ack\" (build (textOf to)) 0 `catch` \\(_ :: SomeException) -> pure ()\n      else pure ()\n  where\n    parsed = do\n      (history, p1) <- getMany getText payload 0\n      (to, _) <- getText payload p1\n      pure (history, to)\n\nstepDescriptor :: NetEndpoint -> Bool -> IO Descriptor\nstepDescriptor endpoint sends = do\n  k <- readIORef (endpointStep endpoint)\n  if k >= length (endpointSteps endpoint) then throwIO (ErrorCall \"this channel's protocol has ended\") else do\n    let (stepSends, d) = endpointSteps endpoint !! k\n    if stepSends /= sends then throwIO (ErrorCall (if stepSends then \"this step sends\" else \"this step receives\")) else do\n      writeIORef (endpointStep endpoint) (k + 1)\n      pure d\n\n-- | Sends the next step's value.\nendpointSend :: NetEndpoint -> Scalar -> IO ()\nendpointSend endpoint value = do\n  gone <- esGone <$> readMVar (endpointState endpoint)\n  if gone then throwIO PeerFailed else do\n    d <- stepDescriptor endpoint True\n    bytes <- orWire (wireEncode (endpointTable endpoint) d value)\n    seqNo <- modifyMVar (endpointState endpoint) (\\st -> pure (st { esOut = esOut st + 1 }, esOut st))\n    transmit endpoint seqNo (B.cons 0 bytes)\n\n-- | Receives the next step's value, waiting up to the given microseconds\n-- (forever when Nothing); throws PeerFailed when the other end gave up or\n-- failed, after what it sent.\nendpointReceiveValue :: NetEndpoint -> Maybe Int -> IO Scalar\nendpointReceiveValue endpoint micros = do\n  d <- stepDescriptor endpoint False\n  item <- maybe (Just <$> readChan (endpointInbox endpoint)) (\\m -> timeout m (readChan (endpointInbox endpoint))) micros\n  case item of\n    Nothing -> throwIO (ErrorCall \"no message arrived in time\")\n    Just (Left reason) -> writeChan (endpointInbox endpoint) (Left reason) >> throwIO PeerFailed\n    Just (Right body)\n      | B.null body || B.head body == 1 -> do\n          failEndpoint endpoint \"the other end gave up the conversation\"\n          throwIO PeerFailed\n      | otherwise -> orWire (wireDecode (endpointTable endpoint) d (B.tail body))\n\n-- | Gives up: the other end's receives fail after what was sent.\nendpointAbandon :: NetEndpoint -> IO ()\nendpointAbandon endpoint = do\n  seqNo <- modifyMVar (endpointState endpoint) (\\st -> pure (st { esOut = esOut st + 1 }, esOut st))\n  transmit endpoint seqNo (B.singleton 1)\n\n-- | How one step's native value crosses the network: to its logical value\n-- and back, given the network end it travels on. A step that sends a channel\n-- end moves or relays it (endConversion); any other converts with its codec.\ntype Conversion = (NetEndpoint -> Dynamic -> IO Scalar, NetEndpoint -> Scalar -> IO Dynamic)\n\n-- | A channel side over a network end, converting each step's native value\n-- (in order) with the given conversions, for typed sessions.\nnetChannelSide :: NetEndpoint -> [Conversion] -> IO ChannelSide\nnetChannelSide endpoint conversions = do\n  step <- newIORef (0 :: Int)\n  let conversionAt = do\n        k <- atomicModifyIORef' step (\\i -> (i + 1, i))\n        if k < length conversions then pure (conversions !! k) else throwIO (ErrorCall \"this channel's protocol has ended\")\n  pure ChannelSide\n    { sideSend = \\dynamic -> do\n        (toLogical, _) <- conversionAt\n        toLogical endpoint dynamic >>= endpointSend endpoint\n    , sideReceive = do\n        (_, toNative') <- conversionAt\n        value <- endpointReceiveValue endpoint Nothing\n        toNative' endpoint value\n    , sideAbandon = endpointAbandon endpoint\n    , sideHandOver = do\n        k <- readIORef step\n        if k == 0 then Just <$> offerEndpoint endpoint else pure Nothing\n    }\n\n-- | A step's conversion for netChannelSide, from its codec's encode and\n-- decode.\nconversion :: forall a. Typeable a => (a -> Either String Scalar) -> (Scalar -> Either String a) -> Conversion\nconversion toLogical fromLogical =\n  ( \\_ dynamic -> either (throwIO . ErrorCall) pure (maybe (Left (\"a session sent \" ++ show (dynTypeRep dynamic) ++ \" where it expected \"\n      ++ show (typeRep (Proxy :: Proxy a)))) toLogical (fromDynamic dynamic))\n  , \\_ value -> either (throwIO . ErrorCall) (pure . toDyn) (fromLogical value) )\n\n-- | A step that sends another protocol's first end between nodes. An end\n-- that is itself between nodes moves to the receiver, which takes it over\n-- (the text sent is <address>?take=<token>). A local end stays on the\n-- sending node, and a relay there (named relay-<n>) passes each of its\n-- steps between it and the receiver, which dials the relay's address; a\n-- failure on either side gives up the other. wire is that protocol's steps\n-- and conversions, from its first end; unwrap and wrap convert between its\n-- start type and a SessionEnd.\nendConversion :: forall end. Typeable end => (end -> SessionEnd) -> (SessionEnd -> end)\n              -> ([(Bool, Descriptor)], [Conversion]) -> Conversion\nendConversion unwrap wrap (steps, conversions) = (sending, receiving)\n  where\n    sending endpoint dynamic = case fromDynamic dynamic of\n      Nothing -> throwIO (ErrorCall (\"a session sent \" ++ show (dynTypeRep dynamic) ++ \" where it expected \"\n        ++ show (typeRep (Proxy :: Proxy end))))\n      Just end -> do\n        side <- useEnd (unwrap end)\n        handed <- sideHandOver side\n        maybe (relayFrom endpoint side) (pure . textScalar) handed\n    relayFrom endpoint side = do\n        let node = endpointNode endpoint\n        n <- nextId node\n        relay <- listenOn node (\"relay-\" ++ show n) [(not s, d) | (s, d) <- steps] (endpointTable endpoint)\n        relayed <- netChannelSide relay conversions\n        let pump = forM_ steps (\\(sends, _) ->\n              if sends then sideReceive relayed >>= sideSend side else sideReceive side >>= sideSend relayed)\n            quietly action = action `catch` \\(_ :: SomeException) -> pure ()\n        _ <- forkIO (pump `catch` \\(_ :: SomeException) -> quietly (sideAbandon side) >> quietly (sideAbandon relayed))\n        textScalar <$> readIORef (endpointAddress relay)\n    receiving endpoint value = case value of\n      SSequence _ cps -> do\n        let address = map chr cps\n            open = if \"?take=\" `isInfixOf` address then takeFrom else dialTo\n        remote <- open (endpointNode endpoint) address steps (endpointTable endpoint)\n        side <- netChannelSide remote conversions\n        toDyn . wrap <$> sessionEnd side\n      _ -> throwIO (ErrorCall \"a channel end's address is not text\")\n\n-- Abilities (docs/explanation/abilities.md). Handlers travel with the symbol\n-- context that generated code passes to every definition: that context is\n-- the evidence of evidence-passing compilation. A law installs one handler\n-- per ability (a record of IO operations); a performed operation finds the\n-- handler of its ability with handlerOf and runs with performIO. The Fail\n-- ability's handlers abort, so raise throws a Failure and attempt catches it.\n\n-- | A handler installed for an ability, with its calls when it records\n-- them, and whether it is the real clock (lawspec.time's default Clock\n-- handler: workflows and mailboxes then wait in real time under it).\ndata Installed = Installed String Dynamic (Maybe Calls) Bool\n\n-- | The calls a recording handler has seen.\nnewtype Calls = Calls (IORef [(String, [Scalar])])\n\nnewCalls :: IO Calls\nnewCalls = Calls <$> newIORef []\n\nrecordCall :: Calls -> String -> [Scalar] -> IO ()\nrecordCall (Calls ref) operation arguments = atomicModifyIORef' ref (\\calls -> (calls ++ [(operation, arguments)], ()))\n\n-- | A handler clause's codec and evaluation errors, as IO errors.\nrunClause :: Either String a -> IO a\nrunClause = either (throwIO . ErrorCall) pure\n\ninstalled :: Typeable h => String -> h -> Installed\ninstalled key handler = Installed key (toDyn handler) Nothing False\n\n-- | lawspec.time's default Clock handler, installed as the real clock: the\n-- generated tests install it so. Every other Clock handler is virtual.\ninstalledRealClock :: Typeable h => String -> h -> Installed\ninstalledRealClock key handler = Installed key (toDyn handler) Nothing True\n\ninstalledRecording :: Typeable h => String -> (h, Calls) -> Installed\ninstalledRecording key (handler, calls) = Installed key (toDyn handler) (Just calls) False\n\n{-# NOINLINE handlerTable #-}\nhandlerTable :: IORef [(Unique, [Installed])]\nhandlerTable = unsafePerformIO (newIORef [])\n\ninstallHandlers :: SymbolContext -> [Installed] -> IO ()\ninstallHandlers (SymbolContext unique) handlers = atomicModifyIORef' handlerTable\n  (\\table -> ((unique, handlers ++ maybe [] id (lookup unique table)) : filter ((/= unique) . fst) table, ()))\n\ninstalledFor :: SymbolContext -> String -> Installed\ninstalledFor (SymbolContext unique) key = unsafePerformIO $ do\n  table <- readIORef handlerTable\n  case [i | Just handlers <- [lookup unique table], i@(Installed k _ _ _) <- handlers, k == key] of\n    i : _ -> pure i\n    [] -> throwIO (ErrorCall (\"no handler for the ability \" ++ key ++ \": a law names one with `using`, or runs under each lawful handler\"))\n{-# NOINLINE installedFor #-}\n\n-- | The handler installed for an ability, at the type its operation needs.\nhandlerOf :: forall h. Typeable h => SymbolContext -> String -> h\nhandlerOf symbols key = case installedFor symbols key of\n  Installed _ value _ _ -> maybe (error (\"the handler for \" ++ key ++ \" is a \" ++ show (dynTypeRep value) ++ \", not a \" ++ show (typeRep (Proxy :: Proxy h)))) id (fromDynamic value)\n\n-- | An operation's result, where generated code needs a value.\nperformIO :: IO a -> a\nperformIO = unsafePerformIO\n{-# NOINLINE performIO #-}\n\n-- | A failure raised with the Fail ability.\ndata Failure = Failure String Scalar deriving Show\ninstance Exception Failure\n\nraiseFailure :: String -> Scalar -> a\nraiseFailure ability value = throw' (Failure ability value)\n  where throw' failure = unsafePerformIO (throwIO failure)\n\n-- | Right of the body, or Left of the failure it raised with this ability.\nattempt :: String -> Scalar -> (Scalar -> Scalar) -> (Scalar -> Scalar) -> Scalar\nattempt ability body right left = unsafePerformIO $ do\n  outcome <- try (evaluate (forceScalar body `seq` body))\n  case outcome of\n    Right value -> pure (right value)\n    Left failure@(Failure raised value)\n      | raised == ability -> pure (left value)\n      | otherwise -> throwIO failure\n{-# NOINLINE attempt #-}\n\n-- | How many times a recording handler saw an operation (with arguments).\ncountCalls :: SymbolContext -> String -> String -> Maybe ([Scalar] -> Bool) -> Scalar\ncountCalls symbols key operation matches = unsafePerformIO $ case installedFor symbols key of\n  Installed _ _ (Just (Calls ref)) _ -> do\n    calls <- readIORef ref\n    pure (SInteger \"Int64\" (fromIntegral (length [() | (name, arguments) <- calls, name == operation, maybe True ($ arguments) matches])))\n  _ -> throwIO (ErrorCall \"calls of needs a recording handler: `using recording`\")\n{-# NOINLINE countCalls #-}\n\n-- | let x = e in body: e runs first, once.\nletIn :: Scalar -> (Scalar -> Scalar) -> Scalar\nletIn value body = forceScalar value `seq` body value\n\n-- | handle e with h end: the body runs with these handlers installed, then\n-- the ones they replaced come back.\nwithHandlers :: SymbolContext -> IO [Installed] -> (() -> Scalar) -> Scalar\nwithHandlers symbols@(SymbolContext unique) make body = unsafePerformIO $ do\n  before <- readIORef handlerTable\n  handlers <- make\n  installHandlers symbols handlers\n  let restore = atomicModifyIORef' handlerTable (\\table ->\n        (maybe id (\\previous -> ((unique, previous) :)) (lookup unique before) (filter ((/= unique) . fst) table), ()))\n  (do value <- evaluate (body ())\n      _ <- evaluate (forceScalar value)\n      pure value) `finally` restore\n{-# NOINLINE withHandlers #-}\n\n-- | What native code (an adapter, or a production handler) throws to fail\n-- with a value of the failure type its signature names: throwIO (LS.Fail v)\n-- for `fails with E`, v a native E.\ndata Fail = forall a. (Typeable a, Show a) => Fail a\ninstance Show Fail where\n  show (Fail value) = \"failed with \" ++ show value\ninstance Exception Fail\n\n-- | A native exception lawspec.json maps to a failure.\nnewtype MappedFailure = MappedFailure (SomeException -> Maybe Scalar)\n\nmappedFailure :: Exception e => (e -> Scalar) -> MappedFailure\nmappedFailure make = MappedFailure (fmap make . fromException)\n\n-- | Native code that may fail: a Fail it throws (with a native E), or an\n-- exception lawspec.json maps, becomes a failure of the ability.\nnativeFailures :: forall e. Typeable e => String -> (e -> Scalar) -> (() -> Scalar) -> [MappedFailure] -> Scalar\nnativeFailures ability convert body mapped = unsafePerformIO $ do\n  outcome <- try (do value <- evaluate (body ()); _ <- evaluate (forceScalar value); pure value)\n  case outcome of\n    Right value -> pure value\n    Left problem -> case fromException problem of\n      Just (Fail native) | Just value <- cast native -> throwIO (Failure ability (convert (value :: e)))\n      _ -> case [scalar | MappedFailure make <- mapped, Just scalar <- [make problem]] of\n        scalar : _ -> throwIO (Failure ability scalar)\n        [] -> throwIO problem\n{-# NOINLINE nativeFailures #-}\n\n-- | A Pair's two fields: a stateful handler clause's result and next state.\npairFields :: Scalar -> (Scalar, Scalar)\npairFields (SData _ [result, next]) = (result, next)\npairFields _ = error \"a handler clause must give Pair result state\"\n"
runtimeSource "haskell-schema" = "-- | Checked structural values; no property-framework dependencies.\n--\n-- Generated data types are described once, as Core schemas, and every value\n-- crossing between a law and native code is validated against them, so an\n-- adapter cannot hand a law a value outside its declared type.\n-- ref:DEC-typed-core-boundary ref:DEC-native-bindings-typed-identity\nmodule LawSpecSchema\n  ( TypeRef(..), Field(..), Constructor(..), Definition(..), Schema\n  , FieldPredicate, ValidationFailure(..), failureMessage\n  , create, createWithContracts, createIndexed, createRefined, withWitnesses, witnessedSchema, witnessText, hasContracts, checkType, fieldType\n  , fieldTypeAt, witnessKeys, witnessed, witnessChoices, witnessPool, witnessKey, parseWitness\n  , constructors, substitute\n  , validate, validateWith, validateChecked\n  , allPayloads, allPayloadsWith\n  , construct, constructWith, equal, equalWith, match, matchWith\n  ) where\n\nimport Control.Monad (unless, forM_, zipWithM, foldM)\nimport Data.List (find, nub)\nimport qualified LawSpecRuntime as LS\n\ndata TypeRef = Parameter Int | Named String [TypeRef]\n  deriving (Eq, Ord, Show)\ndata Field = Field String TypeRef deriving (Eq, Show)\ndata Constructor = Constructor String [Field] deriving (Eq, Show)\ndata Definition = Definition String Int [Constructor] deriving (Eq, Show)\ntype FieldPredicate =\n  Schema -> [TypeRef] -> [LS.Scalar] -> Int -> Maybe LS.SymbolContext\n  -> Either String Bool\n\ndata ValidationFailure\n  = Rejected String\n  | EvaluationFailure String\n  deriving (Eq, Show)\n\nfailureMessage :: ValidationFailure -> String\nfailureMessage (Rejected message) = message\nfailureMessage (EvaluationFailure message) = message\n\n-- | Indexed families add, per constructor, their index terms then guards in\n-- prefix notation over field indices; validation checks the guards.\n-- GADT constructors add refinements (parameter, pattern) and an existential\n-- count; existentials are parameters numbered after the definition's own.\n-- Witnessed existentials (parameter numbers), by tag, are those only a value\n-- determines; their types travel as the trailing Text witness fields.\ndata Schema = Schema [Definition] [(String, Int)] [(String, [FieldPredicate])] [(String, [String])]\n  [(String, ([(Int, TypeRef)], Int))] [(String, [Int])]\n\nhasContracts :: Schema -> Bool\nhasContracts (Schema _ _ contracts _ _ _) = any (not . null . snd) contracts\n\ncreate :: [Definition] -> [String] -> Either String Schema\ncreate definitions primitives = createWithContracts definitions primitives []\n\ncreateWithContracts :: [Definition] -> [String] -> [(String, [FieldPredicate])]\n                    -> Either String Schema\ncreateWithContracts definitions primitives contracts = createIndexed definitions primitives contracts []\n\ncreateIndexed :: [Definition] -> [String] -> [(String, [FieldPredicate])] -> [(String, [String])]\n              -> Either String Schema\ncreateIndexed definitions primitives contracts indices = createRefined definitions primitives contracts indices []\n\ncreateRefined :: [Definition] -> [String] -> [(String, [FieldPredicate])] -> [(String, [String])]\n              -> [(String, ([(Int, TypeRef)], Int))] -> Either String Schema\ncreateRefined definitions primitives contracts indices refinements = do\n  let builtins = [(name, 0) | name <- primitives] ++\n        [(\"List\", 1), (\"Maybe\", 1), (\"Either\", 2),\n         (\"Nullable\", 1), (\"Optional\", 1)]\n      arities = builtins ++\n        [(name, count) | Definition name count _ <- definitions]\n      names = map fst arities\n      tags = [tag | Definition _ _ variants <- definitions,\n                    Constructor tag _ <- variants]\n      schema = Schema definitions arities contracts indices refinements []\n  unless (all (not . null) names && length names == length (nub names))\n    (Left \"duplicate or empty schema type\")\n  unless (all (not . null) tags && length tags == length (nub tags))\n    (Left \"duplicate or empty constructor identity\")\n  let contractTags = map fst contracts\n  unless (length contractTags == length (nub contractTags) &&\n          all (`elem` tags) contractTags)\n    (Left \"duplicate or unknown constructor contract\")\n  forM_ definitions $ \\(Definition name parameters variants) -> do\n    unless (parameters >= 0) (Left (\"negative parameter count: \" ++ name))\n    forM_ variants $ \\(Constructor tag fields) -> do\n      let fieldNames = [field | Field field _ <- fields]\n      unless (all (not . null) fieldNames &&\n              length fieldNames == length (nub fieldNames))\n        (Left (\"duplicate or empty field: \" ++ tag))\n      let existentials = maybe 0 snd (lookup tag refinements)\n      forM_ fields $ \\(Field _ typeRef) -> checkType schema (parameters + existentials) typeRef\n  pure schema\n\ncheckType :: Schema -> Int -> TypeRef -> Either String ()\ncheckType _ count (Parameter index) =\n  unless (index >= 0 && index < count) (Left \"unbound schema parameter\")\ncheckType schema@(Schema _ arities _ _ _ _) count (Named name arguments) = do\n  unless (lookup name arities == Just (length arguments))\n    (Left (\"unknown type or wrong arity: \" ++ name))\n  mapM_ (checkType schema count) arguments\n\nsubstitute :: [TypeRef] -> TypeRef -> TypeRef\n-- A witnessed existential stays open until a value supplies it.\nsubstitute arguments (Parameter index)\n  | index < length arguments = arguments !! index\n  | otherwise = Parameter index\nsubstitute arguments (Named name children) =\n  Named name (map (substitute arguments) children)\n\nconstructors :: Schema -> TypeRef -> Either String (Maybe [Constructor])\nconstructors schema@(Schema definitions _ _ _ refinements _) typeRef = do\n  checkType schema 0 typeRef\n  case typeRef of\n    Named name arguments -> case\n        find (\\(Definition n _ _) -> n == name) definitions of\n      Nothing -> pure Nothing\n      -- A GADT constructor whose refinements do not match these arguments\n      -- builds no value of this type.\n      Just (Definition _ parameters variants) -> pure (Just\n        [Constructor tag [Field field (substitute extended ty) |\n                          Field field ty <- fields] |\n         Constructor tag fields <- variants,\n         Just extended <- [refine (lookup tag refinements) parameters arguments]])\n    Parameter _ -> Left \"unbound schema parameter\"\n\n-- | Arguments extended with the existentials a constructor's refinements bind;\n-- Nothing when the refinements do not match.\nrefine :: Maybe ([(Int, TypeRef)], Int) -> Int -> [TypeRef] -> Maybe [TypeRef]\nrefine Nothing _ arguments = Just arguments\nrefine (Just (patterns, existentials)) parameters arguments = do\n  bound <- foldM (\\acc (index, pattern) -> match acc pattern (arguments !! index)) [] patterns\n  let extra = [maybe (Parameter (parameters + k)) id (lookup (parameters + k) bound) | k <- [0 .. existentials - 1]]\n  pure (arguments ++ extra)\n  where\n    match acc (Parameter index) actual\n      | index < parameters = if arguments !! index == actual then Just acc else Nothing\n      | otherwise = case lookup index acc of\n          Just previous -> if previous == actual then Just acc else Nothing\n          Nothing -> Just ((index, actual) : acc)\n    match acc (Named name children) (Named other values)\n      | name == other && length children == length values = foldM (\\a (c, v) -> match a c v) acc (zip children values)\n    match _ _ _ = Nothing\n\n-- | A constructor field's type at an instantiated type, its existentials\n-- substituted.\nfieldType :: Schema -> TypeRef -> String -> Int -> TypeRef\nfieldType schema typeRef tag index = case constructors schema typeRef of\n  Right (Just variants) | Constructor _ fields : _ <- [v | v@(Constructor t _) <- variants, t == tag]\n                        , Field _ ty : _ <- drop index fields -> ty\n  _ -> error (\"constructor \" ++ tag ++ \" is not a value of \" ++ show typeRef)\n\nwitnessedSchema :: [(String, [Int])] -> Either String Schema -> Either String Schema\nwitnessedSchema witnesses = fmap (withWitnesses witnesses)\n\n-- | A witness field's key, for generated codecs; the schema has checked it.\nwitnessText :: LS.Scalar -> String\nwitnessText (LS.SSequence \"Text\" units) = map toEnum units\nwitnessText _ = error \"type witness must be text\"\n\nwithWitnesses :: [(String, [Int])] -> Schema -> Schema\nwithWitnesses witnesses (Schema a b c d e w) = Schema a b c d e (w ++ witnesses)\n\n-- | Types a generator may choose for an existential that only a value fixes.\nwitnessPool :: [TypeRef]\nwitnessPool = [Named \"Bool\" [], Named \"Int32\" []]\n\n-- | A witness spells a type as its name, or a parenthesized application.\nwitnessKey :: TypeRef -> String\nwitnessKey (Named name []) = name\nwitnessKey (Named name arguments) = \"(\" ++ unwords (name : map witnessKey arguments) ++ \")\"\nwitnessKey (Parameter index) = \"?\" ++ show index\n\nparseWitness :: String -> Either String TypeRef\nparseWitness text = case readType (words (concatMap spaced text)) of\n  Just (ty, []) -> Right ty\n  _ -> Left \"malformed type witness\"\n  where\n    spaced c = if c `elem` \"()\" then [' ', c, ' '] else [c]\n    readType (\"(\" : name : rest) = arguments [] rest\n      where\n        arguments acc (\")\" : more) = Just (Named name (reverse acc), more)\n        arguments acc more = readType more >>= \\(child, after) -> arguments (child : acc) after\n    readType (token : rest) | token /= \")\" = Just (Named token [], rest)\n    readType _ = Nothing\n\n-- | The trailing witness keys of a value's fields.\nwitnessKeys :: Schema -> String -> [LS.Scalar] -> Either String [String]\nwitnessKeys (Schema _ _ _ _ _ witnesses) tag fields = case lookup tag witnesses of\n  Nothing -> Right []\n  Just indices -> mapM key (drop (length fields - length indices) fields)\n  where\n    key (LS.SSequence \"Text\" units) = Right (map toEnum units)\n    key _ = Left \"type witness must be text\"\n\n-- | Field types with witnessed existentials read from the given keys.\nwitnessed :: Schema -> String -> [TypeRef] -> [String] -> Either String [TypeRef]\nwitnessed schema@(Schema _ _ _ _ _ witnesses) tag types keys = case lookup tag witnesses of\n  Nothing -> Right types\n  Just indices -> do\n    parsed <- mapM parseWitness keys\n    mapM_ (checkType schema 0) parsed\n    let size = if null indices then 0 else maximum indices + 1\n        known = [maybe (Parameter i) id (lookup i (zip indices parsed)) | i <- [0 .. size - 1]]\n    pure (map (substitute known) types)\n\n-- | Each choice of witnesses from the pool: the declared fields at it, and the\n-- witness values.\nwitnessChoices :: Schema -> Constructor -> Either String [([Field], [LS.Scalar])]\nwitnessChoices schema@(Schema _ _ _ _ _ witnesses) (Constructor tag fields) = case lookup tag witnesses of\n  Nothing -> Right [(fields, [])]\n  Just indices -> do\n    let declared = take (length fields - length indices) fields\n    mapM (\\choice -> do\n      let keys = map witnessKey choice\n      types <- witnessed schema tag [ty | Field _ ty <- declared] keys\n      pure ([Field name ty | (Field name _, ty) <- zip declared types], map LS.textScalar keys))\n      (mapM (const witnessPool) indices)\n\n-- | A field's type at a value's witness keys, for generated codecs.\nfieldTypeAt :: Schema -> TypeRef -> String -> Int -> [String] -> TypeRef\nfieldTypeAt schema typeRef tag index keys = case constructors schema typeRef of\n  Right (Just variants) | Constructor _ fields : _ <- [v | v@(Constructor t _) <- variants, t == tag]\n                        , Right types <- witnessed schema tag [ty | Field _ ty <- fields] keys\n                        , ty : _ <- drop index types -> ty\n  _ -> error (\"constructor \" ++ tag ++ \" is not a value of \" ++ show typeRef)\n\nvalidate :: Schema -> TypeRef -> Int -> LS.Scalar -> Either String LS.Scalar\nvalidate schema = validateWith Nothing schema\n\nvalidateWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int -> LS.Scalar\n             -> Either String LS.Scalar\nvalidateWith scope schema typeRef bits value =\n  either (Left . failureMessage) Right\n    (validateChecked scope schema typeRef bits value)\n\nfromEvaluation :: Either String a -> Either ValidationFailure a\nfromEvaluation = either (Left . EvaluationFailure) Right\n\nfailureContext :: String -> Either ValidationFailure a\n               -> Either ValidationFailure a\nfailureContext label = either (Left . decorate) Right\n  where\n    decorate (Rejected message) = Rejected (label ++ \": \" ++ message)\n    decorate (EvaluationFailure message) =\n      EvaluationFailure (label ++ \": \" ++ message)\n\n-- | Prefix index terms: c<n>, f<field>[.<index>] and natural operators.\ndata IndexTerm = IndexConstant Integer | IndexField Int Int | IndexOp String IndexTerm IndexTerm\n\nisIndexGuard :: String -> Bool\nisIndexGuard text = take 1 (words text) `elem` [[\"==\"], [\">=\"]]\n\nfieldTypes :: [Field] -> [TypeRef]\nfieldTypes fields = [ty | Field _ ty <- fields]\n\nparseIndexTerm :: [String] -> Either String (IndexTerm, [String])\nparseIndexTerm tokens = case tokens of\n  ('c' : digits) : rest -> Right (IndexConstant (read digits), rest)\n  ('f' : digits) : rest -> case break (== '.') digits of\n    (position, '.' : index) -> Right (IndexField (read position) (read index), rest)\n    (position, _) -> Right (IndexField (read position) 0, rest)\n  op : rest | op `elem` [\"+\", \"-\", \"*\", \"div\", \"mod\", \"^\"] -> do\n    (a, afterA) <- parseIndexTerm rest\n    (b, afterB) <- parseIndexTerm afterA\n    Right (IndexOp op a b, afterB)\n  _ -> Left \"malformed index term\"\n\n-- | Natural arithmetic; Nothing when an operation has no natural value.\nevalIndexTerm :: (Int -> Int -> Either String Integer) -> IndexTerm -> Either String (Maybe Integer)\nevalIndexTerm field term = case term of\n  IndexConstant n -> Right (Just n)\n  IndexField position index -> Just <$> field position index\n  IndexOp op a b -> do\n    left <- evalIndexTerm field a\n    right <- evalIndexTerm field b\n    pure $ do\n      x <- left\n      y <- right\n      case op of\n        \"+\" -> Just (x + y)\n        \"-\" | x >= y -> Just (x - y)\n        \"*\" -> Just (x * y)\n        \"div\" | y > 0 -> Just (x `div` y)\n        \"mod\" | y > 0 -> Just (x `mod` y)\n        \"^\" | y >= 0 && y <= 64 -> Just (x ^ y)\n        _ -> Nothing\n\nindexGuard :: (Int -> Int -> Either String Integer) -> String -> Either String Bool\nindexGuard field text = case words text of\n  relation : rest -> do\n    (a, afterA) <- parseIndexTerm rest\n    (b, _) <- parseIndexTerm afterA\n    x <- evalIndexTerm field a\n    y <- evalIndexTerm field b\n    pure $ case (x, y) of\n      (Just l, Just r) -> if relation == \"==\" then l == r else l >= r\n      _ -> False\n  [] -> Left \"malformed index guard\"\n\n-- | The index of a checked value, computed from its constructor's term.\nindexOf :: Schema -> TypeRef -> LS.Scalar -> Int -> Either String Integer\nindexOf schema@(Schema _ _ _ indices _ _) typeRef value index = case value of\n  LS.SData tag children -> do\n    variants <- constructors schema typeRef\n    expected <- case [fields | Just choices <- [variants], Constructor name fields <- choices, name == tag] of\n      fields : _ -> Right fields\n      [] -> Left (\"no index for \" ++ show typeRef)\n    let terms = filter (not . isIndexGuard) (maybe [] id (lookup tag indices))\n    text <- if index < length terms then Right (terms !! index) else Left (\"no index for \" ++ show typeRef)\n    (term, _) <- parseIndexTerm (words text)\n    result <- evalIndexTerm (\\position child -> indexOf schema (fieldTypes expected !! position) (children !! position) child) term\n    maybe (Left (\"index of \" ++ tag ++ \" has no natural value\")) Right result\n  _ -> Left (\"no index for \" ++ show typeRef)\n\nvalidateChecked :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int\n                -> LS.Scalar -> Either ValidationFailure LS.Scalar\nvalidateChecked scope schema@(Schema _ _ contracts indices _ _) typeRef bits value = do\n  unless (bits == 32 || bits == 64)\n    (Left (EvaluationFailure \"machineBits must be 32 or 64\"))\n  variants <- fromEvaluation (constructors schema typeRef)\n  case (variants, value) of\n    -- A handle is checked by its type alone; LawSpec never looks inside.\n    (_, LS.SHandle label _) -> case typeRef of\n      Named name [] | name == label -> pure value\n      _ -> Left (EvaluationFailure (\"a \" ++ label ++ \" handle is not a \" ++ show typeRef))\n    (Just choices, _) -> dataValue choices\n    (Nothing, _) -> case (typeRef, value) of\n      (Named \"List\" [element], LS.SList values) ->\n        LS.SList <$> zipWithM (\\index child ->\n          failureContext (\"List[\" ++ show index ++ \"]\")\n            (validateChecked scope schema element bits child))\n          [0 :: Int ..] values\n      (Named \"Maybe\" [element], _) -> dataValue\n        [Constructor \"Maybe::Nothing\" [],\n         Constructor \"Maybe::Just\" [Field \"value\" element]]\n      (Named \"Either\" [left, right], _) -> dataValue\n        [Constructor \"Either::Left\" [Field \"value\" left],\n         Constructor \"Either::Right\" [Field \"value\" right]]\n      (Named name [element], LS.SPresent wrapper payload)\n        | name `elem` [\"Nullable\", \"Optional\"] && name == wrapper ->\n          LS.SPresent wrapper <$> traverse\n            (failureContext name . validateChecked scope schema element bits)\n            payload\n      (Named name [], _) | scalarPayload value && LS.scalarName value == name ->\n        fromEvaluation (LS.validateScalar bits value)\n      _ -> Left (EvaluationFailure\n        (\"invalid representation for \" ++ show typeRef))\n  where\n    scalarPayload LS.SData{} = False\n    scalarPayload LS.SList{} = False\n    scalarPayload LS.SPresent{} = False\n    scalarPayload _ = True\n    dataValue choices = case value of\n      LS.SData tag fields -> case\n          find (\\(Constructor name _) -> name == tag) choices of\n        Nothing -> Left (EvaluationFailure\n          (\"unknown constructor \" ++ tag ++ \" for \" ++ show typeRef))\n        Just (Constructor _ expected) -> do\n          unless (length fields == length expected)\n            (Left (EvaluationFailure (\"wrong field count: \" ++ tag)))\n          types <- fromEvaluation (witnessKeys schema tag fields >>= witnessed schema tag [ty | Field _ ty <- expected])\n          checked <- zipWithM\n            (\\(Field name _, ty) field -> failureContext (tag ++ \".\" ++ name)\n              (validateChecked scope schema ty bits field)) (zip expected types) fields\n          let arguments = case typeRef of\n                Named _ values -> values\n                Parameter _ -> []\n              predicates = maybe [] id (lookup tag contracts)\n          forM_ (zip [1 :: Int ..] predicates) $ \\(index, predicate) ->\n            failureContext (tag ++ \" predicate \" ++ show index) $ do\n              accepted <- fromEvaluation\n                (predicate schema arguments checked bits scope)\n              unless accepted\n                (Left (Rejected \"constructor field contract rejected\"))\n          forM_ [text | text <- maybe [] id (lookup tag indices), isIndexGuard text] $ \\text -> do\n            let field position index = indexOf schema (fieldTypes expected !! position) (checked !! position) index\n            holds <- fromEvaluation (indexGuard field text)\n            unless holds (Left (Rejected (tag ++ \": index guard \" ++ text ++ \" failed\")))\n          pure (LS.SData tag checked)\n      _ -> Left (EvaluationFailure\n        (\"expected constructor payload for \" ++ show typeRef))\n\n\n-- | Recipes follow declared parameters, not equality of instantiated types.\ndata PayloadPlan\n  = IgnorePayload\n  | PayloadSlot Int\n  | PayloadApplication String [PayloadPlan]\n\npayloadRecipe :: [PayloadPlan] -> TypeRef -> PayloadPlan\npayloadRecipe arguments (Parameter index) = arguments !! index\npayloadRecipe arguments (Named name children) =\n  let plans = map (payloadRecipe arguments) children\n  in if all ignored plans then IgnorePayload else PayloadApplication name plans\n  where\n    ignored IgnorePayload = True\n    ignored _ = False\n\nallPayloads :: Schema -> TypeRef -> Int -> LS.Scalar\n            -> [LS.Scalar -> Either String LS.Scalar]\n            -> Either String LS.Scalar\nallPayloads = allPayloadsWith Nothing\n\n-- | Either sequences full representation/contract validation before callbacks.\nallPayloadsWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int\n                -> LS.Scalar -> [LS.Scalar -> Either String LS.Scalar]\n                -> Either String LS.Scalar\nallPayloadsWith scope schema@(Schema definitions _ _ _ _ _) typeRef bits value\n                predicates = do\n  checkType schema 0 typeRef\n  (name, arguments) <- case typeRef of\n    Named name arguments\n      | name `elem` [\"List\", \"Maybe\", \"Either\", \"Nullable\", \"Optional\"] ||\n        any (\\(Definition n _ _) -> n == name) definitions ->\n          Right (name, arguments)\n    _ -> Left \"payload predicates require a data type\"\n  unless (length arguments == length predicates)\n    (Left \"payload predicate arity mismatch\")\n  checked <- validateWith scope schema typeRef bits value\n  LS.SBool <$> walk\n    (PayloadApplication name (map PayloadSlot [0 .. length arguments - 1]))\n    checked\n  where\n    context label = either (Left . ((label ++ \": \") ++)) Right\n    every [] = Right True\n    every (step : steps) = do\n      accepted <- step\n      if accepted then every steps else Right False\n    walk IgnorePayload _ = Right True\n    walk (PayloadSlot index) stored = do\n      result <- (predicates !! index) stored\n      case result of\n        LS.SBool accepted -> Right accepted\n        _ -> Left \"Bool required in payload predicate\"\n    walk (PayloadApplication name arguments) stored = case (name, stored) of\n      (\"List\", LS.SList values) -> every\n        [context (\"List[\" ++ show index ++ \"]\") (walk (head arguments) child)\n        | (index, child) <- zip [0 :: Int ..] values]\n      (_, LS.SPresent wrapper payload)\n        | name `elem` [\"Nullable\", \"Optional\"] && wrapper == name ->\n          maybe (Right True)\n            (context (name ++ \".value\") . walk (head arguments)) payload\n      (_, LS.SHandle _ _) -> Right True\n      (\"Maybe\", LS.SData \"Maybe::Nothing\" []) -> Right True\n      (\"Maybe\", LS.SData \"Maybe::Just\" [child]) ->\n        context \"Maybe::Just.value\" (walk (head arguments) child)\n      (\"Either\", LS.SData tag [child]) ->\n        let index = if tag == \"Either::Left\" then 0 else 1\n        in context (tag ++ \".value\") (walk (arguments !! index) child)\n      (_, LS.SData tag fields) -> do\n        variants <- case find (\\(Definition n _ _) -> n == name) definitions of\n          Just (Definition _ _ variants) -> Right variants\n          Nothing -> Left \"unknown checked payload type\"\n        expected <- case find (\\(Constructor n _) -> n == tag) variants of\n          Just (Constructor _ expected) -> Right expected\n          Nothing -> Left \"unknown checked payload constructor\"\n        every [context (tag ++ \".\" ++ field)\n          (walk (payloadRecipe arguments ty) child)\n          | (Field field ty, child) <- zip expected fields]\n      _ -> Left \"invalid checked payload representation\"\n\nconstruct :: Schema -> TypeRef -> Int -> String -> [LS.Scalar]\n          -> Either String LS.Scalar\nconstruct = constructWith Nothing\n\nconstructWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int\n              -> String -> [LS.Scalar] -> Either String LS.Scalar\nconstructWith scope schema typeRef bits tag fields = case typeRef of\n  Named \"List\" [_] -> case (tag, fields) of\n    (\"List::Nil\", []) -> pure (LS.SList [])\n    (\"List::Cons\", [headValue, LS.SList values]) -> pure (LS.SList (headValue : values))\n    _ -> Left \"invalid List constructor or field count\"\n  _ -> either (Left . failureMessage) Right (shallowChecked scope schema typeRef bits (LS.SData tag fields))\n\n-- | A newly built node: its fields were checked when they were built, decoded\n-- or drawn, and a deep check of each node would make recursion quadratic.\nshallowChecked :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int -> LS.Scalar\n               -> Either ValidationFailure LS.Scalar\nshallowChecked scope schema@(Schema _ _ contracts indices _ _) typeRef bits value = do\n  variants <- fromEvaluation (constructors schema typeRef)\n  case (variants, value) of\n    (Just choices, LS.SData tag fields) -> case find (\\(Constructor name _) -> name == tag) choices of\n      Nothing -> Left (EvaluationFailure (\"unknown constructor \" ++ tag ++ \" for \" ++ show typeRef))\n      Just (Constructor _ expected) -> do\n        unless (length fields == length expected)\n          (Left (EvaluationFailure (\"wrong field count: \" ++ tag)))\n        let arguments = case typeRef of\n              Named _ values -> values\n              Parameter _ -> []\n        forM_ (zip [1 :: Int ..] (maybe [] id (lookup tag contracts))) $ \\(index, predicate) ->\n          failureContext (tag ++ \" predicate \" ++ show index) $ do\n            accepted <- fromEvaluation (predicate schema arguments fields bits scope)\n            unless accepted (Left (Rejected \"constructor field contract rejected\"))\n        forM_ [text | text <- maybe [] id (lookup tag indices), isIndexGuard text] $ \\text -> do\n          let field position index = indexOf schema (fieldTypes expected !! position) (fields !! position) index\n          holds <- fromEvaluation (indexGuard field text)\n          unless holds (Left (Rejected (tag ++ \": index guard \" ++ text ++ \" failed\")))\n        pure value\n    _ -> validateChecked scope schema typeRef bits value\n\nequal :: Schema -> TypeRef -> Int -> LS.Scalar -> LS.Scalar\n      -> Either String Bool\nequal = equalWith Nothing\n\nequalWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int\n          -> LS.Scalar -> LS.Scalar -> Either String Bool\nequalWith scope schema typeRef bits left right = do\n  a <- validateWith scope schema typeRef bits left\n  b <- validateWith scope schema typeRef bits right\n  pure (LS.equal a b)\n\n-- | Validation precedes branch selection; unselected branch functions stay lazy.\nmatch :: Schema -> TypeRef -> Int -> LS.Scalar\n      -> [(String, [LS.Scalar] -> a)] -> Either String a\nmatch = matchWith Nothing\n\nmatchWith :: Maybe LS.SymbolContext -> Schema -> TypeRef -> Int -> LS.Scalar\n          -> [(String, [LS.Scalar] -> a)] -> Either String a\nmatchWith _ _ _ _ value branches = do\n  -- Values are checked where they are built, decoded or drawn.\n  let checked = value\n  (tag, fields) <- case checked of\n    LS.SData name payload -> pure (name, payload)\n    LS.SList [] -> pure (\"List::Nil\", [])\n    LS.SList (headValue : tailValue) ->\n      pure (\"List::Cons\", [headValue, LS.SList tailValue])\n    _ -> Left \"matching requires a data constructor\"\n  case lookup tag branches of\n    Nothing -> Left (\"missing checked match branch: \" ++ tag)\n    Just action -> pure (action fields)\n"
runtimeSource "haskell-codecs" = "-- | Typed native bridges with checked, contextual conversions.\n--\n-- Adapters work with their own Haskell types; each codec converts between them\n-- and LawSpec's values and checks the result, so a law never sees a native\n-- value outside its domain. ref:DEC-native-bindings-typed-identity\nmodule LawSpecCodecs\n  ( Codec, reference, decode, encode, codec, codecWith, context\n  , integerCodec, boolCodec, decimalCodec, rationalCodec\n  , float32Codec, float64Codec, complex64Codec, complex128Codec\n  , characterCodec, codeUnitCodec, textCodec, bytesCodec\n  , codePointTextCodec, utf16TextCodec, symbolCodec\n  , unitCodec, nullCodec, undefinedCodec\n  , listCodec, maybeCodec, eitherCodec, nullableCodec, optionalCodec\n  , listCodecWith, maybeCodecWith, eitherCodecWith\n  , nullableCodecWith, optionalCodecWith\n  ) where\n\nimport Control.Monad (unless, foldM, zipWithM)\nimport Data.Bits (finiteBitSize)\nimport Data.Char (ord)\nimport Data.Complex (Complex((:+)))\nimport Data.Ratio (numerator, denominator)\nimport Data.Word (Word16)\nimport qualified Data.ByteString as B\nimport qualified Data.Text as T\nimport GHC.Float (float2Double)\nimport qualified LawSpecRuntime as LS\nimport qualified LawSpecSchema as S\n\ndata Codec a = Codec\n  { reference :: S.TypeRef\n  , decode :: LS.Scalar -> Either String a\n  , encode :: a -> Either String LS.Scalar\n  }\n\ncontext :: String -> Either String a -> Either String a\ncontext label = either (Left . ((label ++ \": \") ++)) Right\n\ncheckNativeProfile :: S.Schema -> S.TypeRef -> Int -> Either String ()\ncheckNativeProfile schema typeRef bits = do\n  unless (bits == 32 || bits == 64) (Left \"machineBits must be 32 or 64\")\n  S.checkType schema 0 typeRef\n  _ <- visit [] typeRef\n  pure ()\n  where\n    -- A witnessed existential takes a witness pool type, which every profile\n    -- supports.\n    visit seen (S.Parameter _) = pure seen\n    visit seen current@(S.Named name arguments) = do\n      previous <- foldM visit seen arguments\n      unless (name `notElem` [\"IntSize\", \"UIntSize\", \"UIntPtr\"] ||\n              bits == finiteBitSize (0 :: Int))\n        (Left \"machineBits does not match native architecture\")\n      if name `elem` previous then pure previous else do\n        variants <- S.constructors schema current\n        let fields = [ty | S.Constructor _ items <- maybe [] id variants,\n                           S.Field _ ty <- items]\n        foldM visit (name : previous) fields\n\ncodec :: S.Schema -> Int -> S.TypeRef\n      -> (LS.Scalar -> Either String a)\n      -> (a -> Either String LS.Scalar) -> Codec a\ncodec = codecWith Nothing\n\ncodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int -> S.TypeRef\n          -> (LS.Scalar -> Either String a)\n          -> (a -> Either String LS.Scalar) -> Codec a\ncodecWith scope schema bits typeRef decoder encoder =\n  Codec typeRef fromValue toValue\n  where\n    checked = checkNativeProfile schema typeRef bits\n    fromValue value = context (show typeRef) $ do\n      checked\n      validated <- S.validateWith scope schema typeRef bits value\n      decoder validated\n    toValue value = context (show typeRef) $ do\n      checked\n      encoded <- encoder value\n      S.validateWith scope schema typeRef bits encoded\n\nscalar :: LS.Native a => S.Schema -> Int -> String\n       -> (a -> Either String LS.Scalar) -> Codec a\nscalar schema bits name encoder = codec schema bits (S.Named name [])\n  (\\value -> Right (LS.toNative name value bits)) encoder\n\nintegerCodec :: (Integral a, LS.Native a)\n             => S.Schema -> Int -> String -> Codec a\nintegerCodec schema bits name = scalar schema bits name\n  (Right . LS.SInteger name . toInteger)\n\nboolCodec :: S.Schema -> Int -> Codec Bool\nboolCodec schema bits = scalar schema bits \"Bool\" (Right . LS.SBool)\n\ndecimalCodec :: S.Schema -> Int -> Codec LS.Decimal\ndecimalCodec schema bits = scalar schema bits \"Decimal\"\n  (\\(LS.Decimal value) -> LS.decimal value)\n\nrationalCodec :: S.Schema -> Int -> Codec Rational\nrationalCodec schema bits = scalar schema bits \"Rational\"\n  (\\value -> Right (LS.SRational (numerator value) (denominator value)))\n\nfloat32Codec :: S.Schema -> Int -> Codec Float\nfloat32Codec schema bits = scalar schema bits \"Float32\"\n  (Right . LS.floatScalar \"Float32\" . float2Double)\n\nfloat64Codec :: S.Schema -> Int -> Codec Double\nfloat64Codec schema bits = scalar schema bits \"Float64\"\n  (Right . LS.floatScalar \"Float64\")\n\ncomplex64Codec :: S.Schema -> Int -> Codec (Complex Float)\ncomplex64Codec schema bits = scalar schema bits \"Complex64\"\n  (\\(r :+ i) -> Right (LS.SComplex \"Complex64\"\n    (LS.floatScalar \"Float32\" (float2Double r))\n    (LS.floatScalar \"Float32\" (float2Double i))))\n\ncomplex128Codec :: S.Schema -> Int -> Codec (Complex Double)\ncomplex128Codec schema bits = scalar schema bits \"Complex128\"\n  (\\(r :+ i) -> Right (LS.SComplex \"Complex128\"\n    (LS.floatScalar \"Float64\" r) (LS.floatScalar \"Float64\" i)))\n\ncharacterCodec :: S.Schema -> Int -> String -> Codec Char\ncharacterCodec schema bits name = scalar schema bits name\n  (Right . LS.SCharacter name . ord)\n\ncodeUnitCodec :: S.Schema -> Int -> Codec Word16\ncodeUnitCodec schema bits = scalar schema bits \"CodeUnit16\"\n  (Right . LS.SCharacter \"CodeUnit16\" . fromIntegral)\n\ntextCodec :: S.Schema -> Int -> Codec T.Text\ntextCodec schema bits = scalar schema bits \"Text\"\n  (Right . LS.SSequence \"Text\" . map ord . T.unpack)\n\nbytesCodec :: S.Schema -> Int -> Codec B.ByteString\nbytesCodec schema bits = scalar schema bits \"Bytes\"\n  (Right . LS.SSequence \"Bytes\" . map fromIntegral . B.unpack)\n\ncodePointTextCodec :: S.Schema -> Int -> Codec LS.CodePointText\ncodePointTextCodec schema bits = scalar schema bits \"CodePointText\"\n  (\\(LS.CodePointText value) ->\n    Right (LS.SSequence \"CodePointText\" (map ord value)))\n\nutf16TextCodec :: S.Schema -> Int -> Codec LS.Utf16Text\nutf16TextCodec schema bits = scalar schema bits \"Utf16Text\"\n  (\\(LS.Utf16Text value) ->\n    Right (LS.SSequence \"Utf16Text\" (map fromIntegral value)))\n\nsymbolCodec :: S.Schema -> Int -> Codec LS.Symbol\nsymbolCodec schema bits = scalar schema bits \"Symbol\"\n  encodeSymbol\n  where\n    encodeSymbol (LS.Symbol identity description) =\n      Right (LS.SSymbol identity description)\n    encodeSymbol (LS.ScopedSymbol scope identity description) =\n      Right (LS.SScopedSymbol scope identity description)\n\nunitCodec :: S.Schema -> Int -> Codec ()\nunitCodec schema bits = scalar schema bits \"Unit\"\n  (\\() -> Right (LS.SAbsent \"Unit\"))\n\nnullCodec :: S.Schema -> Int -> Codec LS.Null\nnullCodec schema bits = scalar schema bits \"Null\"\n  (\\LS.Null -> Right (LS.SAbsent \"Null\"))\n\nundefinedCodec :: S.Schema -> Int -> Codec LS.Undefined\nundefinedCodec schema bits = scalar schema bits \"Undefined\"\n  (\\LS.Undefined -> Right (LS.SAbsent \"Undefined\"))\n\nlistCodec :: S.Schema -> Int -> Codec a -> Codec [a]\nlistCodec = listCodecWith Nothing\n\nlistCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n              -> Codec a -> Codec [a]\nlistCodecWith scope schema bits element = codecWith scope schema bits\n  (S.Named \"List\" [reference element]) fromValue toValue\n  where\n    fromValue (LS.SList values) = zipWithM\n      (\\index value -> context (\"List[\" ++ show index ++ \"]\")\n        (decode element value)) [0 :: Int ..] values\n    fromValue _ = Left \"invalid checked List\"\n    toValue values = LS.SList <$> zipWithM\n      (\\index value -> context (\"List[\" ++ show index ++ \"]\")\n        (encode element value)) [0 :: Int ..] values\n\nmaybeCodec :: S.Schema -> Int -> Codec a -> Codec (Maybe a)\nmaybeCodec = maybeCodecWith Nothing\n\nmaybeCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n               -> Codec a -> Codec (Maybe a)\nmaybeCodecWith scope schema bits element = codecWith scope schema bits\n  (S.Named \"Maybe\" [reference element]) fromValue toValue\n  where\n    fromValue (LS.SData \"Maybe::Nothing\" []) = Right Nothing\n    fromValue (LS.SData \"Maybe::Just\" [value]) =\n      Just <$> context \"Maybe::Just.value\" (decode element value)\n    fromValue _ = Left \"invalid checked Maybe\"\n    toValue Nothing = Right (LS.SData \"Maybe::Nothing\" [])\n    toValue (Just value) = do\n      field <- context \"Maybe::Just.value\" (encode element value)\n      pure (LS.SData \"Maybe::Just\" [field])\n\neitherCodec :: S.Schema -> Int -> Codec a -> Codec b -> Codec (Either a b)\neitherCodec = eitherCodecWith Nothing\n\neitherCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n                -> Codec a -> Codec b -> Codec (Either a b)\neitherCodecWith scope schema bits left right = codecWith scope schema bits\n  (S.Named \"Either\" [reference left, reference right]) fromValue toValue\n  where\n    fromValue (LS.SData \"Either::Left\" [value]) =\n      Left <$> context \"Either::Left.value\" (decode left value)\n    fromValue (LS.SData \"Either::Right\" [value]) =\n      Right <$> context \"Either::Right.value\" (decode right value)\n    fromValue _ = Left \"invalid checked Either\"\n    toValue (Left value) = do\n      field <- context \"Either::Left.value\" (encode left value)\n      pure (LS.SData \"Either::Left\" [field])\n    toValue (Right value) = do\n      field <- context \"Either::Right.value\" (encode right value)\n      pure (LS.SData \"Either::Right\" [field])\n\nnullableCodec :: S.Schema -> Int -> Codec a -> Codec (LS.Nullable a)\nnullableCodec = nullableCodecWith Nothing\n\nnullableCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n                  -> Codec a -> Codec (LS.Nullable a)\nnullableCodecWith scope schema bits element = codecWith scope schema bits\n  (S.Named \"Nullable\" [reference element]) fromValue toValue\n  where\n    fromValue (LS.SPresent \"Nullable\" Nothing) = Right LS.NullValue\n    fromValue (LS.SPresent \"Nullable\" (Just value)) =\n      LS.NullableValue <$> context \"Nullable.value\" (decode element value)\n    fromValue _ = Left \"invalid checked Nullable\"\n    toValue LS.NullValue = Right (LS.SPresent \"Nullable\" Nothing)\n    toValue (LS.NullableValue value) = do\n      field <- context \"Nullable.value\" (encode element value)\n      pure (LS.SPresent \"Nullable\" (Just field))\n\noptionalCodec :: S.Schema -> Int -> Codec a -> Codec (LS.Optional a)\noptionalCodec = optionalCodecWith Nothing\n\noptionalCodecWith :: Maybe LS.SymbolContext -> S.Schema -> Int\n                  -> Codec a -> Codec (LS.Optional a)\noptionalCodecWith scope schema bits element = codecWith scope schema bits\n  (S.Named \"Optional\" [reference element]) fromValue toValue\n  where\n    fromValue (LS.SPresent \"Optional\" Nothing) = Right LS.UndefinedValue\n    fromValue (LS.SPresent \"Optional\" (Just value)) =\n      LS.OptionalValue <$> context \"Optional.value\" (decode element value)\n    fromValue _ = Left \"invalid checked Optional\"\n    toValue LS.UndefinedValue = Right (LS.SPresent \"Optional\" Nothing)\n    toValue (LS.OptionalValue value) = do\n      field <- context \"Optional.value\" (encode element value)\n      pure (LS.SPresent \"Optional\" (Just field))\n"
runtimeSource "haskell-collection-codecs" = "-- | Native bridges for the built-in collections: a Set is a Data.Set.Set, a\n-- KeyVal a Data.Map.Map, and a Queue, Stack or Deque a Data.Sequence.Seq\n-- from its first item (a Stack's top). These need the containers package.\n--\n-- They live apart from LawSpecCodecs because only they need containers, and\n-- they keep LawSpec's canonical order of a collection's items rather than the\n-- host's. ref:DEC-portable-total-order-collections\nmodule LawSpecCollectionCodecs\n  ( setCodecWith, keyValCodecWith, sequenceCodecWith\n  ) where\n\nimport Data.Foldable (toList)\nimport qualified Data.Map.Strict as Map\nimport qualified Data.Sequence as Seq\nimport qualified Data.Set as Set\nimport qualified LawSpecRuntime as LS\nimport qualified LawSpecSchema as S\nimport LawSpecCodecs (Codec, codecWith, decode, encode, reference)\n\ncollections :: String\ncollections = \"lawspec.collections::type::\"\n\nitems :: LS.Scalar -> Either String [LS.Scalar]\nitems (LS.SData _ [LS.SList values]) = Right values\nitems _ = Left \"invalid checked collection\"\n\nsetCodecWith :: Ord a => Maybe LS.SymbolContext -> S.Schema -> Int -> Codec a -> Codec (Set.Set a)\nsetCodecWith scope schema bits element = codecWith scope schema bits\n  (S.Named (collections ++ \"Set\") [reference element]) fromValue toValue\n  where\n    fromValue value = Set.fromList <$> (items value >>= mapM (decode element))\n    toValue set = do\n      values <- mapM (encode element) (Set.toList set)\n      pure (LS.SData (collections ++ \"Set::SetItems\") [LS.SList (LS.canonicalItems False values)])\n\nkeyValCodecWith :: Ord k => Maybe LS.SymbolContext -> S.Schema -> Int -> Codec k -> Codec v -> Codec (Map.Map k v)\nkeyValCodecWith scope schema bits keys values = codecWith scope schema bits\n  (S.Named (collections ++ \"KeyVal\") [reference keys, reference values]) fromValue toValue\n  where\n    fromValue value = Map.fromList <$> (items value >>= mapM entry)\n    entry (LS.SData _ [k, v]) = (,) <$> decode keys k <*> decode values v\n    entry _ = Left \"invalid checked KeyVal entry\"\n    toValue map' = do\n      entries <- mapM (\\(k, v) -> (\\a b -> LS.SData (collections ++ \"Entry::Entry\") [a, b]) <$> encode keys k <*> encode values v)\n        (Map.toList map')\n      pure (LS.SData (collections ++ \"KeyVal::KeyValEntries\") [LS.SList (LS.canonicalItems True entries)])\n\nsequenceCodecWith :: String -> Maybe LS.SymbolContext -> S.Schema -> Int -> Codec a -> Codec (Seq.Seq a)\nsequenceCodecWith name scope schema bits element = codecWith scope schema bits\n  (S.Named (collections ++ name) [reference element]) fromValue toValue\n  where\n    fromValue value = Seq.fromList <$> (items value >>= mapM (decode element))\n    toValue sequence' = do\n      values <- mapM (encode element) (toList sequence')\n      pure (LS.SData (collections ++ name ++ \"::\" ++ name ++ \"Items\") [LS.SList values])\n"
runtimeSource "haskell-transports" = "{-# LANGUAGE ScopedTypeVariables #-}\n-- | Network transports for LawSpecRuntime's nodes: frames over TCP (each a\n-- 4-byte big-endian length, then the frame) and HTTP (POST /lawspec with\n-- the frame as the body). Both speak the same bytes as every other target.\n--\n-- Speaking the same bytes as every other target is what lets nodes written in\n-- different languages talk to each other. ref:DEC-distribution-canonical-wire\nmodule LawSpecTransports (tcpTransport, httpTransport) where\n\nimport Control.Concurrent (forkIO, MVar, newMVar, modifyMVar)\nimport Control.Exception (SomeException, bracket, catch, throwIO, try)\nimport Control.Monad (forever, unless)\nimport Data.Bits (shiftL, shiftR, (.&.), (.|.))\nimport qualified Data.ByteString as B\nimport qualified Data.ByteString.Char8 as BC\nimport Data.ByteString (ByteString)\nimport Data.Char (isDigit, toLower)\nimport Data.IORef (IORef, newIORef, readIORef, writeIORef)\nimport Data.List (isPrefixOf)\nimport Network.Socket\nimport qualified Network.Socket.ByteString as NB\nimport LawSpecRuntime (Transport(..), Unreachable(..))\n\n-- | Frames over TCP on host (port 0 picks a free port); the address is\n-- tcp://host:port.\ntcpTransport :: String -> Int -> IO Transport\ntcpTransport host port = do\n  server <- listening host port\n  bound <- socketPort server\n  connections <- newMVar []\n  closed <- newIORef False\n  let address = \"tcp://\" ++ host ++ \":\" ++ show bound\n      send node frame = modifyMVar connections $ \\cached -> do\n        let header = B.pack [fromIntegral (B.length frame `shiftR` s) | s <- [24, 16, 8, 0]]\n            attempt existing = do\n              sock <- maybe (connectTo node \"tcp://\") pure existing\n              NB.sendAll sock (header <> frame)\n              pure sock\n        first <- try (attempt (lookup node cached))\n        case first of\n          Right sock -> pure ((node, sock) : filter ((/= node) . fst) cached, ())\n          Left (_ :: SomeException) -> do\n            maybe (pure ()) (\\s -> close s `catch` \\(_ :: SomeException) -> pure ()) (lookup node cached)\n            second <- try (attempt Nothing)\n            case second of\n              Right sock -> pure ((node, sock) : filter ((/= node) . fst) cached, ())\n              Left (e :: SomeException) -> throwIO (Unreachable (\"cannot reach \" ++ node ++ \": \" ++ show e))\n      start deliver = () <$ forkIO (acceptLoop server closed (\\sock -> readFrames sock deliver))\n      stop = do\n        stopListening server address \"tcp://\" closed\n        modifyMVar connections (\\cached -> do\n          mapM_ (\\(_, s) -> close s `catch` \\(_ :: SomeException) -> pure ()) cached\n          pure ([], ()))\n  pure (Transport address start send stop)\n\n-- | Frames as HTTP POST bodies to /lawspec; the address is http://host:port.\nhttpTransport :: String -> Int -> IO Transport\nhttpTransport host port = do\n  server <- listening host port\n  bound <- socketPort server\n  closed <- newIORef False\n  let address = \"http://\" ++ host ++ \":\" ++ show bound\n      start deliver = () <$ forkIO (acceptLoop server closed (\\sock -> serveRequest sock deliver))\n      send node frame = do\n        outcome <- try (bracket (connectTo node \"http://\") close (\\sock -> do\n          let (h, p) = hostPort (drop (length \"http://\") node)\n              headers = \"POST /lawspec HTTP/1.1\\r\\nHost: \" ++ h ++ \":\" ++ p\n                ++ \"\\r\\nContent-Type: application/octet-stream\\r\\nContent-Length: \" ++ show (B.length frame)\n                ++ \"\\r\\nConnection: close\\r\\n\\r\\n\"\n          NB.sendAll sock (BC.pack headers <> frame)\n          response <- readHead sock B.empty\n          let status = words (BC.unpack (BC.takeWhile (/= '\\r') response))\n          unless (take 1 (drop 1 status) `elem` [[\"204\"], [\"200\"]])\n            (throwIO (userError (\"the node answered \" ++ unwords (take 3 status))))))\n        case outcome of\n          Right () -> pure ()\n          Left (e :: SomeException) -> throwIO (Unreachable (\"cannot reach \" ++ node ++ \": \" ++ show e))\n      stop = stopListening server address \"http://\" closed\n  pure (Transport address start send stop)\n\nlistening :: String -> Int -> IO Socket\nlistening host port = do\n  info : _ <- getAddrInfo (Just defaultHints { addrSocketType = Stream, addrFlags = [AI_NUMERICSERV] }) (Just host) (Just (show port))\n  sock <- socket (addrFamily info) Stream defaultProtocol\n  setSocketOption sock ReuseAddr 1\n  bind sock (addrAddress info)\n  listen sock 64\n  pure sock\n\n-- | Stops accepting. Closing a socket that accept is waiting on can stall\n-- GHC's non-threaded runtime, so the accept loop is woken by a connection\n-- of our own and closes the socket itself.\nstopListening :: Socket -> String -> String -> IORefBool -> IO ()\nstopListening _ address scheme closed = do\n  already <- readIORef closed\n  unless already $ do\n    writeIORef closed True\n    woken <- try (connectTo address scheme)\n    case woken of\n      Right sock -> close sock\n      Left (_ :: SomeException) -> pure ()\n\nacceptLoop :: Socket -> IORefBool -> (Socket -> IO ()) -> IO ()\nacceptLoop server closed handler = loop\n  where\n    finish = close server `catch` \\(_ :: SomeException) -> pure ()\n    loop = do\n      accepted <- try (accept server)\n      done <- readIORef closed\n      case accepted of\n        _ | done -> do\n          either (\\(_ :: SomeException) -> pure ()) (\\(sock, _) -> close sock) accepted\n          finish\n        Left (_ :: SomeException) -> loop\n        Right (sock, _) -> do\n          _ <- forkIO ((handler sock `catch` \\(_ :: SomeException) -> pure ()) >> (close sock `catch` \\(_ :: SomeException) -> pure ()))\n          loop\n\ntype IORefBool = IORef Bool\n\nhostPort :: String -> (String, String)\nhostPort rest = let (h, p) = break (== ':') (reverse (takeWhile (/= '/') rest))\n                in (reverse (drop 1 p), reverse h)\n\nconnectTo :: String -> String -> IO Socket\nconnectTo node scheme = do\n  let (h, p) = hostPort (drop (length scheme) node)\n  info : _ <- getAddrInfo (Just defaultHints { addrSocketType = Stream }) (Just h) (Just p)\n  sock <- socket (addrFamily info) Stream defaultProtocol\n  connect sock (addrAddress info) `catch` \\(e :: SomeException) -> close sock >> throwIO e\n  pure sock\n\n-- | Exactly n bytes, or Nothing at the end of the stream.\nreadExactly :: Socket -> Int -> IO (Maybe ByteString)\nreadExactly sock n = go B.empty\n  where\n    go acc\n      | B.length acc >= n = pure (Just acc)\n      | otherwise = do\n          chunk <- NB.recv sock (n - B.length acc)\n          if B.null chunk then pure Nothing else go (acc <> chunk)\n\nreadFrames :: Socket -> (ByteString -> IO ()) -> IO ()\nreadFrames sock deliver = do\n  header <- readExactly sock 4\n  case header of\n    Nothing -> pure ()\n    Just h -> do\n      let n = foldl (\\acc b -> (acc `shiftL` 8) .|. fromIntegral b) 0 (B.unpack h) :: Int\n      frame <- readExactly sock (n .&. 0x7FFFFFFF)\n      case frame of\n        Nothing -> pure ()\n        Just f -> deliver f >> readFrames sock deliver\n\n-- | The bytes up to and including the blank line after the headers.\nreadHead :: Socket -> ByteString -> IO ByteString\nreadHead sock acc\n  | BC.pack \"\\r\\n\\r\\n\" `B.isInfixOf` acc = pure acc\n  | otherwise = do\n      chunk <- NB.recv sock 4096\n      if B.null chunk then pure acc else readHead sock (acc <> chunk)\n\nserveRequest :: Socket -> (ByteString -> IO ()) -> IO ()\nserveRequest sock deliver = do\n  raw <- readHead sock B.empty\n  let (headPart, rest) = B.breakSubstring (BC.pack \"\\r\\n\\r\\n\") raw\n      body0 = B.drop 4 rest\n      ls = lines (filter (/= '\\r') (BC.unpack headPart))\n      requestLine = words (concat (take 1 ls))\n      lengthOf = [read (takeWhile isDigit (dropWhile (== ' ') (drop 1 (dropWhile (/= ':') l)))) :: Int\n                 | l <- drop 1 ls, \"content-length\" `isPrefixOf` map toLower l]\n      wanted = case lengthOf of n : _ -> n; [] -> 0\n  more <- readExactly sock (max 0 (wanted - B.length body0))\n  let body = B.take wanted (body0 <> maybe B.empty id more)\n      ok = take 2 requestLine == [\"POST\", \"/lawspec\"]\n  NB.sendAll sock (BC.pack (if ok then \"HTTP/1.1 204 No Content\\r\\nContent-Length: 0\\r\\nConnection: close\\r\\n\\r\\n\"\n    else \"HTTP/1.1 404 Not Found\\r\\nContent-Length: 0\\r\\nConnection: close\\r\\n\\r\\n\"))\n  if ok then deliver body else pure ()\n"
runtimeSource "haskell-data-strategies" = "-- | Native Hedgehog generation and shrinking for checked Core schemas.\n--\n-- Generated tests run in Hedgehog, under Hspec, so failures shrink and report\n-- as Haskell developers expect; the generators are built from Hedgehog's own so\n-- its integrated shrinking reduces counterexamples and shrinking stays within\n-- the declared domain. ref:DEC-native-property-frameworks ref:hedgehog\n-- ref:DEC-shrink-within-domain\nmodule LawSpecDataStrategies\n  (strategy, checkedStrategy, checkedStrategyWith, primitiveStrategy\n  , indexedStrategy, NativeFactory, nativeValues, nativeArguments) where\n\nimport Control.Monad (unless, when, foldM)\nimport Control.Monad.State.Strict (StateT, evalStateT, get, modify, lift)\nimport Data.List (nub)\nimport Data.Maybe (catMaybes)\nimport Numeric (showHex)\nimport Data.Char (chr)\nimport Data.Ratio (numerator, denominator, (%))\nimport qualified Data.Map.Strict as Map\nimport Hedgehog (Gen)\nimport qualified Hedgehog.Gen as Gen\nimport qualified Hedgehog.Range as Range\nimport qualified LawSpecRuntime as LS\nimport qualified LawSpecSchema as S\nimport qualified LawSpecCodecs as Codec\n\n-- | Factories return native Hedgehog trees; fmap preserves their shrink structure.\ntype NativeFactory = S.TypeRef -> [Gen LS.Scalar]\n                   -> Either String (Gen LS.Scalar)\n\nnativeValues :: Codec.Codec a -> Gen a -> Gen LS.Scalar\nnativeValues codec = fmap $ \\value ->\n  case Codec.encode codec value of\n    Left message -> error (\"native generator: \" ++ message)\n    Right logical -> LS.forceScalar logical `seq` logical\n\nnativeArguments :: Codec.Codec a -> Gen LS.Scalar -> Gen a\nnativeArguments codec = fmap $ \\value ->\n  either (error . (\"native generator argument: \" ++)) id\n    (Codec.decode codec value)\n\ntype Cache = Map.Map (S.TypeRef, Int) (Maybe (Gen LS.Scalar))\ntype Build = StateT Cache (Either String)\n\nstrategy :: S.Schema -> S.TypeRef -> Int -> Int\n         -> (String -> Either String (Gen LS.Scalar))\n         -> Either String (Gen LS.Scalar)\nstrategy schema reference bits budget scalar = do\n  when (S.hasContracts schema)\n    (Left \"constructor contracts require checked strategies\")\n  buildStrategy schema reference bits budget scalar (\\_ _ -> id)\n\n-- | Predicate failures are native discards. Evaluation errors remain exceptions,\n-- which Hedgehog reports as property failures rather than retrying them.\n-- filterT prunes rejected shrink subtrees: searching every descendant of a\n-- sparse identity predicate can otherwise make shrinking effectively unbounded.\ncheckedStrategy :: S.Schema -> S.TypeRef -> Int -> Int -> Maybe LS.SymbolContext\n                -> [LS.Scalar] -> (String -> Either String (Gen LS.Scalar))\n                -> Either String (Gen LS.Scalar)\ncheckedStrategy = checkedStrategyWith []\n\ncheckedStrategyWith :: [(String, NativeFactory)]\n                    -> S.Schema -> S.TypeRef -> Int -> Int -> Maybe LS.SymbolContext\n                    -> [LS.Scalar] -> (String -> Either String (Gen LS.Scalar))\n                    -> Either String (Gen LS.Scalar)\ncheckedStrategyWith factories schema reference bits budget scope witnesses scalar = do\n  checked <- mapM (S.validateWith scope schema reference bits) witnesses\n  seeds <- foldM (indexWitness schema reference) Map.empty checked\n  let scoped = maybe id LS.scopeSymbols scope\n      accepted ty value = case S.validateChecked scope schema ty bits value of\n        Right _ -> True\n        Left (S.Rejected _) -> False\n        Left (S.EvaluationFailure message) -> error message\n      finish ty available generator =\n        let values = filter ((<= available) . valueNodes)\n              (Map.findWithDefault [] ty seeds)\n            native = scoped <$> generator\n            choices = if null values then native\n              else Gen.choice [native, Gen.element values]\n        in Gen.filterT (accepted ty) choices\n  generated <- buildStrategyWith factories schema reference bits budget scalar finish\n  pure\n    (either error id . S.validateWith scope schema reference bits <$> generated)\n\nvalueNodes :: LS.Scalar -> Int\nvalueNodes value = 1 + sum (map valueNodes (case value of\n  LS.SData _ fields -> fields\n  LS.SList values -> values\n  LS.SPresent _ payload -> maybe [] pure payload\n  _ -> []))\n\nindexWitness :: S.Schema -> S.TypeRef -> Map.Map S.TypeRef [LS.Scalar]\n             -> LS.Scalar -> Either String (Map.Map S.TypeRef [LS.Scalar])\nindexWitness schema reference witnesses value = do\n  let indexed = Map.insertWith (++) reference [value] witnesses\n      descend ty values = foldM (indexWitness schema ty) indexed values\n  case (reference, value) of\n    (S.Named \"List\" [element], LS.SList values) -> descend element values\n    (S.Named name [element], LS.SPresent _ payload)\n      | name `elem` [\"Nullable\", \"Optional\"] ->\n        descend element (maybe [] pure payload)\n    (S.Named \"Maybe\" [element], LS.SData \"Maybe::Just\" [child]) ->\n      descend element [child]\n    (S.Named \"Either\" [left, _], LS.SData \"Either::Left\" [child]) ->\n      descend left [child]\n    (S.Named \"Either\" [_, right], LS.SData \"Either::Right\" [child]) ->\n      descend right [child]\n    (_, LS.SData tag fields) -> do\n      constructors <- S.constructors schema reference\n      let matches =\n            [expected | S.Constructor name expected <- maybe [] id constructors,\n                        name == tag]\n      case matches of\n        expected:_ -> do\n          types <- S.witnessKeys schema tag fields >>= S.witnessed schema tag [ty | S.Field _ ty <- expected]\n          foldM (\\acc (ty, child) -> indexWitness schema ty acc child)\n            indexed (zip types fields)\n        [] -> pure indexed\n    _ -> pure indexed\n\nbuildStrategy :: S.Schema -> S.TypeRef -> Int -> Int\n              -> (String -> Either String (Gen LS.Scalar))\n              -> (S.TypeRef -> Int -> Gen LS.Scalar -> Gen LS.Scalar)\n              -> Either String (Gen LS.Scalar)\nbuildStrategy = buildStrategyWith []\n\nbuildStrategyWith :: [(String, NativeFactory)]\n                  -> S.Schema -> S.TypeRef -> Int -> Int\n                  -> (String -> Either String (Gen LS.Scalar))\n                  -> (S.TypeRef -> Int -> Gen LS.Scalar -> Gen LS.Scalar)\n                  -> Either String (Gen LS.Scalar)\nbuildStrategyWith factories schema reference bits budget scalar finish = do\n  unless (budget > 0) (Left \"structural node budget must be positive\")\n  unless (bits == 32 || bits == 64) (Left \"machineBits must be 32 or 64\")\n  S.checkType schema 0 reference\n  result <- evalStateT (build reference budget) Map.empty\n  maybe (Left (\"no value of \" ++ show reference ++\n               \" within structural node budget \" ++ show budget)) Right result\n  where\n    build :: S.TypeRef -> Int -> Build (Maybe (Gen LS.Scalar))\n    build _ available | available < 1 = pure Nothing\n    build ty available = do\n      cached <- Map.lookup (ty, available) <$> get\n      case cached of\n        Just result -> pure result\n        Nothing -> do\n          -- A custom distribution owns its samples and shrink tree. It must\n          -- never acquire fallback witnesses or discard invalid native values.\n          result <- case ty of\n            S.Named name arguments | Just factory <- lookup name factories -> do\n              -- A native factory may ignore a phantom parameter. Discard only\n              -- if it actually requests a value from an uninhabited child.\n              children <- mapM (\\child -> maybe Gen.discard id <$>\n                build child (available - 1)) arguments\n              Just <$> lift (factory ty children)\n            _ -> fmap (finish ty available) <$> assemble ty available\n          modify (Map.insert (ty, available) result)\n          pure result\n\n    minimumCost ty limit = search 1\n      where\n        search cost | cost > limit = pure Nothing\n        search cost = do\n          candidate <- build ty cost\n          case candidate of\n            Just _ -> pure (Just cost)\n            Nothing -> search (cost + 1)\n\n    -- Reserve every field's minimum before distributing spare nodes.\n    allocation [] _ = pure (Just [])\n    allocation fields available = do\n      minima <- reserve fields available\n      pure $ fmap distribute minima\n      where\n        reserve [] _ = pure (Just [])\n        reserve (S.Field _ ty : rest) remaining = do\n          cost <- minimumCost ty remaining\n          case cost of\n            Nothing -> pure Nothing\n            Just amount -> fmap (amount :) <$> reserve rest (remaining - amount)\n        distribute costs =\n          let (share, extra) = (available - sum costs) `divMod` length costs\n          in zipWith (\\index cost -> cost + share + fromEnum (index < extra))\n               [0 ..] costs\n\n    alternatives = pure . choose . catMaybes\n    choose [] = Nothing\n    choose [only] = Just only\n    choose choices = Just (Gen.choice choices)\n\n    variant available (S.Constructor tag fields) = variantWith available tag fields []\n\n    -- Witness values follow the generated declared fields.\n    variantWith available tag fields witnesses = do\n      costs <- allocation fields (available - 1)\n      case costs of\n        Nothing -> pure Nothing\n        Just amounts -> do\n          children <- sequence <$> sequence\n            [build ty amount | (S.Field _ ty, amount) <- zip fields amounts]\n          pure\n            ((\\generators -> LS.SData tag . (++ witnesses) <$> sequence generators) <$> children)\n\n    -- A field-only existential takes each type of the witness pool.\n    witnessVariants available constructor@(S.Constructor tag _) = do\n      choices <- lift (S.witnessChoices schema constructor)\n      mapM (\\(fields, witnesses) -> variantWith available tag fields witnesses) choices\n\n    assemble ty available = do\n      constructors <- lift (S.constructors schema ty)\n      case constructors of\n        Just variants -> do\n          generator <- concat <$> mapM (witnessVariants available) variants >>= alternatives\n          -- Generated collections are canonicalised rather than filtered.\n          pure (case ty of\n            S.Named name _ | name `elem` [\"lawspec.collections::type::Set\", \"lawspec.collections::type::KeyVal\"] ->\n              fmap (fmap (canonical (name == \"lawspec.collections::type::KeyVal\"))) generator\n            _ -> generator)\n        Nothing -> builtin ty available\n\n    builtin (S.Named name []) _ = do\n      generator <- lift (scalar name)\n      -- Scalar generators come from the target's typed primitive registry.\n      pure (Just generator)\n    builtin (S.Named \"List\" [element]) available = do\n      cost <- minimumCost element (available - 1)\n      let maximumLength = maybe 0 ((available - 1) `div`) cost\n      sized <- mapM (listOfLength element (available - 1)) [1 .. maximumLength]\n      let generators = pure (LS.SList []) : sized\n      pure (Just (Gen.int (Range.linear 0 maximumLength) >>= (generators !!)))\n    builtin (S.Named name [element]) available\n      | name `elem` [\"Maybe\", \"Nullable\", \"Optional\"] = do\n          child <- build element (available - 1)\n          let absent = if name == \"Maybe\"\n                then LS.SData \"Maybe::Nothing\" [] else LS.SPresent name Nothing\n              present value = if name == \"Maybe\"\n                then LS.SData \"Maybe::Just\" [value]\n                else LS.SPresent name (Just value)\n          alternatives [Just (pure absent), fmap (fmap present) child]\n    builtin (S.Named \"Either\" [left, right]) available =\n      mapM (variant available)\n        [S.Constructor \"Either::Left\" [S.Field \"value\" left],\n         S.Constructor \"Either::Right\" [S.Field \"value\" right]] >>= alternatives\n    builtin ty _ = lift (Left (\"unsupported generator type: \" ++ show ty))\n\n    listOfLength element remaining count = do\n      child <- build element (remaining `div` count)\n      case child of\n        Nothing -> lift (Left \"internal list budget allocation failure\")\n        Just generator -> pure\n          (LS.SList <$> Gen.list (Range.singleton count) generator)\n\n-- | Values whose structural index equals the target. Each constructor carries\n-- its index term then its guards, in prefix notation over field indices\n-- (f<i>), literals (c<n>) and + - * div mod ^, with == and >= guards. Indices\n-- are naturals: subtraction never goes below zero. Reachability is a forward\n-- least fixpoint over levels 0..target+slack, so children may exceed their\n-- parent's index; generation then solves the target backwards, never filters,\n-- and Gen.element shrinks each choice toward smaller field indices.\ndata IndexTerm = IndexConstant Integer | IndexField Int | IndexOp String IndexTerm IndexTerm\n\nparseIndexTerm :: [String] -> Either String (IndexTerm, [String])\nparseIndexTerm tokens = case tokens of\n  ('c' : digits) : rest -> Right (IndexConstant (read digits), rest)\n  ('f' : digits) : rest -> Right (IndexField (read digits), rest)\n  op : rest | op `elem` [\"+\", \"-\", \"*\", \"div\", \"mod\", \"^\"] -> do\n    (a, afterA) <- parseIndexTerm rest\n    (b, afterB) <- parseIndexTerm afterA\n    Right (IndexOp op a b, afterB)\n  _ -> Left \"malformed index term\"\n\nevalIndexTerm :: Map.Map Int Integer -> IndexTerm -> Maybe Integer\nevalIndexTerm fields term = case term of\n  IndexConstant n -> Just n\n  IndexField i -> Map.lookup i fields\n  IndexOp op a b -> do\n    x <- evalIndexTerm fields a\n    y <- evalIndexTerm fields b\n    case op of\n      \"+\" -> Just (x + y)\n      \"-\" | x >= y -> Just (x - y)\n      \"*\" -> Just (x * y)\n      \"div\" | y > 0 -> Just (x `div` y)\n      \"mod\" | y > 0 -> Just (x `mod` y)\n      \"^\" | y >= 0 && y <= 64 -> Just (x ^ y)\n      _ -> Nothing\n\nindexTermFields :: IndexTerm -> [Int]\nindexTermFields term = case term of\n  IndexField i -> [i]\n  IndexOp _ a b -> indexTermFields a ++ indexTermFields b\n  _ -> []\n\nindexSlack :: Integer\nindexSlack = 16\n\nindexChoices :: Int\nindexChoices = 6\n\nindexedStrategy :: S.Schema -> S.TypeRef -> Int -> Int -> LS.Scalar\n                -> [(String, [String])]\n                -> (String -> Either String (Gen LS.Scalar))\n                -> Either String (Gen LS.Scalar)\nindexedStrategy schema reference bits budget target equations scalar = do\n  requested <- case target of\n    LS.SInteger _ n -> Right n\n    _ -> Left \"index target must be an integer\"\n  let limit = max requested 0 + indexSlack\n      parse text = do\n        (term, rest) <- parseIndexTerm (words text)\n        unless (null rest) (Left \"malformed index term\")\n        Right term\n      guardOf text = case words text of\n        relation : rest | relation `elem` [\"==\", \">=\"] -> do\n          (a, afterA) <- parseIndexTerm rest\n          (b, afterB) <- parseIndexTerm afterA\n          unless (null afterB) (Left \"malformed index guard\")\n          Right (relation, a, b)\n        _ -> Left \"malformed index guard\"\n      details ty = do\n        constructors <- S.constructors schema ty\n        variants <- maybe (Left \"indexed generation requires a data type\") Right constructors\n        mapM (\\(S.Constructor tag fields) -> do\n          texts <- maybe (Left (\"missing index equation for \" ++ tag)) Right (lookup tag equations)\n          (term, guards) <- case texts of\n            first : rest -> (,) <$> parse first <*> mapM guardOf rest\n            [] -> Left (\"missing index equation for \" ++ tag)\n          let positions = nub (indexTermFields term ++ concat [indexTermFields a ++ indexTermFields b | (_, a, b) <- guards])\n          pure (tag, fields, term, guards, positions)) variants\n      indexTypes (_, fields, _, _, positions) = [ty | (i, S.Field _ ty) <- zip [0 ..] fields, i `elem` positions]\n      explore seen [] = pure seen\n      explore seen (ty : rest)\n        | ty `elem` map fst seen = explore seen rest\n        | otherwise = do\n            variants <- details ty\n            explore ((ty, variants) : seen) (concatMap indexTypes variants ++ rest)\n  families <- explore [] [reference]\n  let plainFields (_, fields, _, _, positions) =\n        [ty | (i, S.Field _ ty) <- zip [0 ..] fields, i `notElem` positions]\n      plain = Map.fromList [(ty, either (const Nothing) Just\n        (buildStrategy schema ty bits budget scalar (\\_ _ -> id)))\n        | ty <- nub (concatMap plainFields (concatMap snd families))]\n      plainReady variant = all (\\ty -> maybe False (const True)\n        (Map.findWithDefault Nothing ty plain)) (plainFields variant)\n      fieldType (_, fields, _, _, _) i = case drop i fields of\n        S.Field _ ty : _ -> ty\n        [] -> error \"index field out of range\"\n      -- Every assignment of reachable indices to the variant's index fields\n      -- that satisfies its guards, with the index it produces.\n      assignments table variant@(_, _, term, guards, positions) =\n        [ (value, assignment)\n        | assignment <- mapM (\\i -> [(i, v) | v <- [0 .. limit],\n            Map.findWithDefault False (fieldType variant i, v) table]) positions\n        , let fields = Map.fromList assignment\n        , all (holds fields) guards\n        , Just value <- [evalIndexTerm fields term]\n        , value <= limit ]\n      holds fields (relation, a, b) = case (evalIndexTerm fields a, evalIndexTerm fields b) of\n        (Just x, Just y) -> if relation == \"==\" then x == y else x >= y\n        _ -> False\n      step table = foldr (\\(ty, variants) acc -> foldr (\\variant inner ->\n          if plainReady variant\n            then foldr (\\(value, _) t -> Map.insert (ty, value) True t) inner (assignments table variant)\n            else inner) acc variants) table families\n      fixpoint table = let next = step table in if next == table then table else fixpoint next\n      table = fixpoint Map.empty\n      variantsOf ty = maybe [] id (lookup ty families)\n      generate ty j = do\n        let options = [ (variant, choices) | variant <- variantsOf ty, plainReady variant\n                      , let choices = [assignment | (value, assignment) <- assignments table variant, value == j]\n                      , not (null choices) ]\n        ((tag, fields, _, _, _), choices) <- Gen.element options\n        assignment <- Gen.element choices\n        values <- mapM (\\(i, S.Field _ ty) -> case lookup i assignment of\n          Just index -> generate ty index\n          Nothing -> maybe (error \"uninhabited field in indexed generation\") id\n            (Map.findWithDefault Nothing ty plain)) (zip [0 ..] fields)\n        pure (LS.SData tag values)\n  -- An open target (negative), or one drawn from earlier inputs that breaks\n  -- their preconditions or names no value, generates from the smallest\n  -- reachable indices; an index claim rejects a mismatch.\n  let reachable level = Map.findWithDefault False (reference, level) table\n      levels = if reachable requested then [requested]\n        else take indexChoices (filter reachable [0 .. limit])\n  when (null levels) (Left (\"no value of \" ++ show reference ++ \" has an index\"))\n  pure (either error id . S.validateWith Nothing schema reference bits <$> (Gen.element levels >>= generate reference))\n\n-- | Primitive shrinkers remain in Hedgehog: integers, lists, and IEEE bit words.\nprimitiveStrategy :: Int -> String -> Either String (Gen LS.Scalar)\nprimitiveStrategy bits name\n  | bits /= 32 && bits /= 64 = Left \"machineBits must be 32 or 64\"\n  | LS.isInteger name =\n      let (lo, hi) = maybe\n            (if name == \"BigUInt\" then (0, 2^(256 :: Int))\n             else (-2^(256 :: Int), 2^(256 :: Int))) id\n            (LS.integerBounds bits name)\n      in Right (LS.SInteger name <$> Gen.integral (Range.linearFrom 0 lo hi))\n  | name == \"Bool\" = Right (LS.SBool <$> Gen.bool)\n  | name `elem` [\"Unit\", \"Null\", \"Undefined\"] =\n      Right (pure (LS.SAbsent name))\n  | name `elem` [\"Char\", \"CodePoint\", \"CodeUnit16\"] =\n      Right (LS.SCharacter name <$> unit name)\n  | name `elem` [\"Text\", \"CodePointText\", \"Utf16Text\", \"Bytes\"] =\n      Right (LS.SSequence name <$> Gen.list (Range.linear 0 100) (unit name))\n  | name == \"Decimal\" = Right\n      (LS.SDecimal <$> integer <*> Gen.integral (Range.linearFrom 0 (-20) 20))\n  | name == \"Rational\" = Right $ do\n      n <- integer\n      d <- Gen.integral (Range.linear 1 (2^(256 :: Int)))\n      let reduced = n % d\n      pure (LS.SRational (numerator reduced) (denominator reduced))\n  | name `elem` [\"Float32\", \"Float64\"] =\n      let digits = if name == \"Float32\" then 8 else 16\n          patternGenerator = Gen.integral (Range.constant 0 (16^digits - 1))\n          encode word =\n            let hex = showHex (word :: Integer) \"\"\n            in LS.SFloat name (replicate (digits - length hex) '0' ++ hex)\n      in Right (encode <$> patternGenerator)\n  | name `elem` [\"Complex64\", \"Complex128\"] = do\n      component <- primitiveStrategy bits\n        (if name == \"Complex64\" then \"Float32\" else \"Float64\")\n      Right (LS.SComplex name <$> component <*> component)\n  | name == \"Symbol\" = Right\n      (LS.SSymbol <$> Gen.string (Range.linear 0 40) Gen.alphaNum <*>\n        (map chr <$> Gen.list (Range.linear 0 40) (unit \"Text\")))\n  | otherwise = Left (\"unknown scalar generator: \" ++ name)\n  where\n    integer = Gen.integral (Range.linearFrom 0\n      (-2^(256 :: Int)) (2^(256 :: Int)))\n    unit kind =\n      let upper = if kind == \"Bytes\" then 255\n                  else if kind `elem` [\"CodeUnit16\", \"Utf16Text\"] then 65535\n                  else 1114111\n          generator = Gen.int (Range.linear 0 upper)\n      in if kind `elem` [\"Char\", \"Text\"]\n         then Gen.filter (\\point -> point < 55296 || point > 57343) generator\n         else generator\n\n-- | A Set's or KeyVal's items in canonical order.\ncanonical :: Bool -> LS.Scalar -> LS.Scalar\ncanonical keyed value = case value of\n  LS.SData tag [LS.SList items] -> LS.SData tag [LS.SList (LS.canonicalItems keyed items)]\n  _ -> value\n"
runtimeSource "rust" = "//! Portable scalar semantics for Rust, with no dependency on a test framework.\n//!\n//! A law must mean the same thing on every target, so this crate module\n//! implements LawSpec's own arithmetic, equality and conversions instead of\n//! Rust's machine integers and floats: integers are exact and reach a bounded\n//! type only through a checked conversion, exact division gives a rational,\n//! decimals are exact, and floats follow IEEE 754 at their declared precision.\n//! ref:DEC-portable-exact-arithmetic ref:ieee-754 ref:decimal-arithmetic\n//!\n//! It is emitted into every generated Rust crate, so the generated tests and\n//! the adapters share one definition of the domain. ref:DEC-typed-core-boundary\npub use num_bigint::{BigInt, BigUint};\npub use num_complex::{Complex32, Complex64};\npub use num_rational::BigRational;\nuse num_traits::{FromPrimitive, One, Signed, ToPrimitive, Zero};\nuse std::collections::HashMap;\nuse std::sync::Arc;\n\npub type Result<T> = std::result::Result<T, String>;\n\n/// Runs a generated test on a thread with a large stack: generated values of\n/// deep data, in debug builds, can exceed the default test thread's stack.\npub fn with_stack<T: Send + 'static>(body: impl FnOnce() -> T + Send + 'static) -> T {\n    std::thread::Builder::new()\n        .stack_size(64 * 1024 * 1024)\n        .spawn(body)\n        .expect(\"test thread\")\n        .join()\n        .unwrap_or_else(|panic| std::panic::resume_unwind(panic))\n}\n\n/// A logical Integer result accepts any native integer without losing bits.\n#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]\npub struct Integer(pub BigInt);\nmacro_rules! integer_from {\n    ($($t:ty),*) => {$ (impl From<$t> for Integer {\n        fn from(value: $t) -> Self { Self(BigInt::from(value)) }\n    })*};\n}\ninteger_from!(\n    i8, i16, i32, i64, i128, isize, u8, u16, u32, u64, u128, usize, BigInt, BigUint\n);\n\n/// Finite base-ten value; arithmetic is independent of ambient rounding modes.\n#[derive(Clone, Debug)]\npub struct Decimal {\n    pub coefficient: BigInt,\n    pub exponent: BigInt,\n}\n// Decimals compare by value, so 1.0 and 1.00 are one key.\nimpl Eq for Decimal {}\nimpl PartialOrd for Decimal {\n    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {\n        Some(self.cmp(other))\n    }\n}\nimpl Ord for Decimal {\n    fn cmp(&self, other: &Self) -> std::cmp::Ordering {\n        match (self.ratio(), other.ratio()) {\n            (Ok(a), Ok(b)) => a.cmp(&b),\n            _ => (&self.coefficient, &self.exponent).cmp(&(&other.coefficient, &other.exponent)),\n        }\n    }\n}\n\nimpl Decimal {\n    pub fn new(coefficient: BigInt, exponent: BigInt) -> Self {\n        Self {\n            coefficient,\n            exponent,\n        }\n    }\n    pub fn ratio(&self) -> Result<BigRational> {\n        let exponent = self\n            .exponent\n            .abs()\n            .to_u32()\n            .ok_or(\"decimal exponent exceeds runtime capacity\")?;\n        let power = BigInt::from(10u8).pow(exponent);\n        Ok(if self.exponent.is_negative() {\n            BigRational::new(self.coefficient.clone(), power)\n        } else {\n            BigRational::from_integer(&self.coefficient * power)\n        })\n    }\n    pub fn from_ratio(value: BigRational) -> Result<Self> {\n        let mut denominator = value.denom().clone();\n        let mut twos = 0u32;\n        let mut fives = 0u32;\n        while (&denominator % 2u8).is_zero() {\n            denominator /= 2u8;\n            twos += 1;\n        }\n        while (&denominator % 5u8).is_zero() {\n            denominator /= 5u8;\n            fives += 1;\n        }\n        if !denominator.is_one() {\n            return Err(\"conversion to Decimal is not finite; use prelude.round\".into());\n        }\n        let scale = twos.max(fives);\n        Ok(Self::new(\n            value.numer()\n                * BigInt::from(2u8).pow(scale - twos)\n                * BigInt::from(5u8).pow(scale - fives),\n            -BigInt::from(scale),\n        ))\n    }\n    pub fn add(&self, other: &Self) -> Result<Self> {\n        Self::from_ratio(self.ratio()? + other.ratio()?)\n    }\n    pub fn sub(&self, other: &Self) -> Result<Self> {\n        Self::from_ratio(self.ratio()? - other.ratio()?)\n    }\n    pub fn mul(&self, other: &Self) -> Result<Self> {\n        Self::from_ratio(self.ratio()? * other.ratio()?)\n    }\n    pub fn round(value: BigRational, scale: i32) -> Result<Self> {\n        let power = BigInt::from(10u8).pow(scale.unsigned_abs());\n        let factor = if scale < 0 {\n            BigRational::new(BigInt::one(), power)\n        } else {\n            BigRational::from_integer(power)\n        };\n        let scaled = &value * &factor;\n        let quotient = scaled.numer() / scaled.denom();\n        let remainder = scaled.numer() % scaled.denom();\n        let twice = remainder.abs() * 2u8;\n        let rounded = if twice > *scaled.denom()\n            || twice == *scaled.denom() && !(&quotient % 2u8).is_zero()\n        {\n            quotient\n                + if scaled.is_negative() {\n                    -BigInt::one()\n                } else {\n                    BigInt::one()\n                }\n        } else {\n            quotient\n        };\n        Self::from_ratio(BigRational::from_integer(rounded) / factor)\n    }\n}\nimpl PartialEq for Decimal {\n    fn eq(&self, other: &Self) -> bool {\n        matches!((self.ratio(),other.ratio()), (Ok(a),Ok(b)) if a==b)\n    }\n}\n\n#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]\npub struct CodePoint(pub u32);\n#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]\npub struct CodePointText(pub Vec<u32>);\n#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]\npub struct Utf16Text(pub Vec<u16>);\n#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]\npub struct Null;\n#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]\npub struct Undefined;\n#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]\npub enum Nullable<T> {\n    Null,\n    Present(T),\n}\n#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]\npub enum Optional<T> {\n    Undefined,\n    Present(T),\n}\n#[derive(Clone, Debug)]\npub struct Symbol(Arc<String>);\nimpl Symbol {\n    pub fn new(description: String) -> Self {\n        Self(Arc::new(description))\n    }\n    pub fn description(&self) -> &str {\n        &self.0\n    }\n}\nimpl PartialEq for Symbol {\n    fn eq(&self, other: &Self) -> bool {\n        Arc::ptr_eq(&self.0, &other.0)\n    }\n}\nimpl Eq for Symbol {}\n#[derive(Clone, Debug, Default)]\npub struct Context {\n    symbols: HashMap<String, Symbol>,\n    /// The workflow runtime this call runs under; None is the default one.\n    pub workflow: Option<Arc<std::sync::Mutex<WorkflowRuntime>>>,\n    /// The handler installed for each ability, by its key (evidence passing).\n    /// Copies of a context share it, so a spec handler (which keeps a copy)\n    /// sees the handlers installed after it, for the abilities its clauses use.\n    pub handlers: Arc<std::sync::RwLock<HashMap<String, Installed>>>,\n    // The default runtime's view under the installed Clock handler.\n    clock_view: ClockView,\n}\nimpl Context {\n    /// A context whose workflows run under the given runtime.\n    pub fn with_workflow(runtime: WorkflowRuntime) -> Context {\n        Context { workflow: Some(Arc::new(std::sync::Mutex::new(runtime))), ..Context::default() }\n    }\n    /// A context for a generated test: workflows wait on a virtual clock, and\n    /// gates are off (a workflow law calls the workflow and its composition,\n    /// which would see each other's state). Timeouts and hedges stay on: they\n    /// count virtual time (see scoped).\n    pub fn testing() -> Context {\n        let mut runtime = WorkflowRuntime::new(Box::new(VirtualClock::default()), 0);\n        runtime.gates = false;\n        Context::with_workflow(runtime)\n    }\n    pub fn symbol(&mut self, id: &str, description: &str) -> Symbol {\n        self.symbols\n            .entry(id.into())\n            .or_insert_with(|| Symbol::new(description.into()))\n            .clone()\n    }\n}\n\n/// A value of a LawSpec type, tagged with that type, because a Rust value alone\n/// cannot say whether it is an Int32, a BigInt or a Decimal, and the law's\n/// semantics depend on which. ref:DEC-portable-exact-arithmetic\n#[derive(Clone, Debug, PartialEq)]\npub enum Value {\n    Integer(BigInt),\n    Decimal(Decimal),\n    Rational(BigRational),\n    Float32(f32),\n    Float64(f64),\n    Complex32(Complex32),\n    Complex64(Complex64),\n    Bool(bool),\n    Char(char),\n    CodePoint(u32),\n    CodeUnit16(u16),\n    Text(String),\n    CodePointText(Vec<u32>),\n    Utf16Text(Vec<u16>),\n    Bytes(Vec<u8>),\n    Symbol(Symbol),\n    Unit,\n    Null,\n    Undefined,\n    Nullable(Option<Box<Value>>),\n    Optional(Option<Box<Value>>),\n    List(Vec<Value>),\n    Maybe(Option<Box<Value>>),\n    Left(Box<Value>),\n    Right(Box<Value>),\n    // The compiler supplies unit-qualified constructor identities. Payloads are\n    // checked by the generated typed bridges, preserving nested sum states.\n    Data(String, Vec<Value>),\n    // A value only adapters create, passed along unopened.\n    Handle(Handle),\n}\n\n/// A handle: a value only adapters create, such as a concurrent queue.\n/// LawSpec never builds, generates or looks inside one; two handles are equal\n/// only when they are the same, and they have no portable order. Clones share\n/// the native value, so a handle stays itself however often it is passed.\n#[derive(Clone)]\npub struct Handle(Arc<HandleCell>);\n\nstruct HandleCell {\n    value: Box<dyn std::any::Any + Send + Sync>,\n    // The handle type's name, recorded when a schema first checks it, and\n    // its number among that type's handles, given when it is first shown.\n    name: std::sync::OnceLock<&'static str>,\n    number: std::sync::OnceLock<u64>,\n}\n\nimpl Handle {\n    /// A new handle around a native value.\n    pub fn new<T: std::any::Any + Send + Sync>(value: T) -> Self {\n        Handle(Arc::new(HandleCell {\n            value: Box::new(value),\n            name: std::sync::OnceLock::new(),\n            number: std::sync::OnceLock::new(),\n        }))\n    }\n\n    /// The native value, when it is a T.\n    pub fn downcast_ref<T: std::any::Any>(&self) -> Option<&T> {\n        self.0.value.downcast_ref::<T>()\n    }\n\n    /// The native value as a T, or an error naming both.\n    pub fn native<T: std::any::Any>(&self) -> Result<&T> {\n        self.downcast_ref::<T>()\n            .ok_or_else(|| format!(\"handle {} does not hold a {}\", self.label(), std::any::type_name::<T>()))\n    }\n\n    /// Whether two handles are the same one.\n    pub fn same(&self, other: &Handle) -> bool {\n        Arc::ptr_eq(&self.0, &other.0)\n    }\n\n    fn named(&self, name: &'static str) {\n        let _ = self.0.name.set(name);\n    }\n\n    /// A stable label, such as Jobs#1: the type's name, then the handle's\n    /// number among that type's handles in order of first appearance.\n    pub fn label(&self) -> String {\n        use std::sync::{Mutex, OnceLock};\n        static COUNTS: OnceLock<Mutex<HashMap<&'static str, u64>>> = OnceLock::new();\n        let full = self.0.name.get().copied().unwrap_or(\"Handle\");\n        let name = full.rsplit(\"::\").next().unwrap_or(full);\n        let number = *self.0.number.get_or_init(|| {\n            let mut counts = COUNTS.get_or_init(|| Mutex::new(HashMap::new())).lock().unwrap_or_else(|e| e.into_inner());\n            let count = counts.entry(name).or_insert(0);\n            *count += 1;\n            *count\n        });\n        format!(\"{name}#{number}\")\n    }\n}\n\nimpl PartialEq for Handle {\n    fn eq(&self, other: &Self) -> bool {\n        self.same(other)\n    }\n}\nimpl Eq for Handle {}\nimpl std::hash::Hash for Handle {\n    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {\n        (Arc::as_ptr(&self.0) as *const () as usize).hash(state);\n    }\n}\nimpl std::fmt::Debug for Handle {\n    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {\n        f.write_str(&self.label())\n    }\n}\n\nimpl Value {\n    pub fn exact(&self) -> Result<BigRational> {\n        match self {\n            Self::Integer(n) => Ok(BigRational::from_integer(n.clone())),\n            Self::Decimal(d) => d.ratio(),\n            Self::Rational(r) => Ok(r.clone()),\n            _ => Err(\"requires exact number\".into()),\n        }\n    }\n    pub fn integer(&self) -> Result<BigInt> {\n        let r = self.exact()?;\n        if !r.is_integer() {\n            return Err(\"fractional integer conversion\".into());\n        }\n        Ok(r.to_integer())\n    }\n    pub fn boolean(&self) -> Result<bool> {\n        match self {\n            Self::Bool(b) => Ok(*b),\n            _ => Err(\"expected Bool\".into()),\n        }\n    }\n    fn real64(&self) -> Result<f64> {\n        match self {\n            Self::Float32(f) => Ok(f64::from(*f)),\n            Self::Float64(f) => Ok(*f),\n            _ => Ok(f64::from_bits(exact_float_bits(&self.exact()?, false)?)),\n        }\n    }\n    fn complex64(&self) -> Result<Complex64> {\n        match self {\n            Self::Complex32(c) => Ok(Complex64::new(f64::from(c.re), f64::from(c.im))),\n            Self::Complex64(c) => Ok(*c),\n            _ => Ok(Complex64::new(self.real64()?, 0.0)),\n        }\n    }\n    pub fn convert(self, target: &str, machine_bits: u32) -> Result<Self> {\n        if target == \"Float32\" {\n            // Rational-to-f32 is direct, avoiding double rounding through f64.\n            return Ok(Self::Float32(match &self {\n                Self::Float32(x) => *x,\n                Self::Float64(x) => *x as f32,\n                _ => f32::from_bits(exact_float_bits(&self.exact()?, true)? as u32),\n            }));\n        }\n        if target == \"Float64\" {\n            return Ok(Self::Float64(self.real64()?));\n        }\n        if target == \"Complex64\" || target == \"Complex128\" {\n            if target == \"Complex128\" {\n                return Ok(Self::Complex64(self.complex64()?));\n            }\n            let (real, imag) = match self {\n                Self::Complex32(c) => return Ok(Self::Complex32(c)),\n                Self::Complex64(c) => (Self::Float64(c.re), Self::Float64(c.im)),\n                x => (x, Self::Float32(0.0)),\n            };\n            return Ok(Self::Complex32(Complex32::new(\n                f32::from_value(real.convert(\"Float32\", machine_bits)?)?,\n                f32::from_value(imag.convert(\"Float32\", machine_bits)?)?,\n            )));\n        }\n        let exact = match self {\n            Self::Float32(f) => {\n                Self::Rational(BigRational::from_f32(f).ok_or(\"non-finite exact conversion\")?)\n            }\n            Self::Float64(f) => {\n                Self::Rational(BigRational::from_f64(f).ok_or(\"non-finite exact conversion\")?)\n            }\n            x => x,\n        };\n        if target == \"Decimal\" {\n            return Ok(Self::Decimal(Decimal::from_ratio(exact.exact()?)?));\n        }\n        if target == \"Rational\" {\n            return Ok(Self::Rational(exact.exact()?));\n        }\n        let (signed, width) = match target {\n            \"Int8\" => (true, 8),\n            \"Int16\" => (true, 16),\n            \"Int32\" => (true, 32),\n            \"Int64\" => (true, 64),\n            \"UInt8\" => (false, 8),\n            \"UInt16\" => (false, 16),\n            \"UInt32\" => (false, 32),\n            \"UInt64\" => (false, 64),\n            \"IntSize\" => (true, machine_bits),\n            \"UIntSize\" | \"UIntPtr\" => (false, machine_bits),\n            \"Integer\" | \"BigInt\" => return Ok(Self::Integer(exact.integer()?)),\n            \"BigUInt\" => {\n                let n = exact.integer()?;\n                if n.is_negative() {\n                    return Err(\"BigUInt cannot be negative\".into());\n                }\n                return Ok(Self::Integer(n));\n            }\n            _ => return Err(format!(\"unsupported numeric conversion: {target}\")),\n        };\n        let n = exact.integer()?;\n        let (lo, hi) = if signed {\n            let bound = BigInt::one() << (width - 1);\n            (-&bound, &bound - 1u8)\n        } else {\n            (BigInt::zero(), (BigInt::one() << width) - 1u8)\n        };\n        if n < lo || n > hi {\n            return Err(format!(\"integer outside {target} range\"));\n        }\n        Ok(Self::Integer(n))\n    }\n}\n\n/// Round the exact ratio once, directly into an IEEE significand and exponent.\npub fn exact_float_bits(ratio: &BigRational, single: bool) -> Result<u64> {\n    let (precision, bias, sign_shift) = if single {\n        (24i64, 127i64, 31)\n    } else {\n        (53i64, 1023i64, 63)\n    };\n    let sign = u64::from(ratio.is_negative()) << sign_shift;\n    if ratio.is_zero() {\n        return Ok(sign);\n    }\n    let n = ratio.numer().abs();\n    let d = ratio.denom().clone();\n    let mut exponent = n.bits() as i64 - d.bits() as i64;\n    if if exponent >= 0 {\n        n < (&d << exponent as usize)\n    } else {\n        (&n << (-exponent) as usize) < d\n    } {\n        exponent -= 1;\n    }\n    let infinity = sign | (((2 * bias + 1) as u64) << (precision - 1));\n    if exponent > bias {\n        return Ok(infinity);\n    }\n    let minimum = 1 - bias;\n    if exponent < minimum - precision {\n        return Ok(sign);\n    }\n    let scale = exponent.max(minimum) - (precision - 1);\n    let num = if scale < 0 { n << (-scale) as usize } else { n };\n    let den = if scale > 0 { d << scale as usize } else { d };\n    let mut q = &num / &den;\n    let twice = (&num % &den) * 2u8;\n    if twice > den || twice == den && !(&q % 2u8).is_zero() {\n        q += 1u8;\n    }\n    exponent = exponent.max(minimum);\n    if q == (BigInt::one() << precision as usize) {\n        q >>= 1usize;\n        exponent += 1;\n    }\n    if exponent > bias {\n        return Ok(infinity);\n    }\n    let hidden = 1u64 << (precision - 1);\n    let significand = q.to_u64().ok_or(\"invalid IEEE significand\")?;\n    let (exp, mantissa) = if significand < hidden {\n        (0, significand)\n    } else {\n        ((exponent + bias) as u64, significand - hidden)\n    };\n    Ok(sign | (exp << (precision - 1)) | mantissa)\n}\n\nfn numeric_class(value: &Value) -> Option<bool> {\n    match value {\n        Value::Integer(_) | Value::Decimal(_) | Value::Rational(_) => Some(true),\n        Value::Float32(_) | Value::Float64(_) | Value::Complex32(_) | Value::Complex64(_) => {\n            Some(false)\n        }\n        _ => None,\n    }\n}\n\n/// Equality defined once for all targets: NaN differs from itself, signed zeros\n/// are equal, handles and symbols compare by identity, and data compares field\n/// by field. ref:DEC-portable-exact-arithmetic\npub fn equal(a: &Value, b: &Value) -> Result<bool> {\n    if let (Some(x), Some(y)) = (numeric_class(a), numeric_class(b)) {\n        if x != y {\n            return Err(\"exact/inexact mixing requires an explicit conversion\".into());\n        }\n    }\n    match (a, b) {\n        (\n            Value::Integer(_) | Value::Decimal(_) | Value::Rational(_),\n            Value::Integer(_) | Value::Decimal(_) | Value::Rational(_),\n        ) => Ok(a.exact()? == b.exact()?),\n        (Value::Float32(_) | Value::Float64(_), Value::Float32(_) | Value::Float64(_)) => {\n            Ok(a.real64()? == b.real64()?)\n        }\n        (\n            Value::Complex32(_) | Value::Complex64(_) | Value::Float32(_) | Value::Float64(_),\n            Value::Complex32(_) | Value::Complex64(_) | Value::Float32(_) | Value::Float64(_),\n        ) => Ok(a.complex64()? == b.complex64()?),\n        (Value::Nullable(Some(x)), Value::Nullable(Some(y)))\n        | (Value::Optional(Some(x)), Value::Optional(Some(y)))\n        | (Value::Maybe(Some(x)), Value::Maybe(Some(y)))\n        | (Value::Left(x), Value::Left(y))\n        | (Value::Right(x), Value::Right(y)) => equal(x, y),\n        (Value::Data(left_tag, _), Value::Data(right_tag, _)) if left_tag != right_tag => Ok(false),\n        (Value::List(xs), Value::List(ys)) | (Value::Data(_, xs), Value::Data(_, ys)) => {\n            if xs.len() != ys.len() {\n                return Ok(false);\n            }\n            for (x, y) in xs.iter().zip(ys) {\n                if !equal(x, y)? {\n                    return Ok(false);\n                }\n            }\n            Ok(true)\n        }\n        _ => Ok(a == b),\n    }\n}\n\n/// `domain` is the compiler-resolved arithmetic evidence, never inferred here.\n///\n/// The operator has LawSpec's semantics rather than Rust's, so a law computes\n/// the same result on every target. ref:DEC-portable-exact-arithmetic\n/// ref:ieee-754\npub fn binary(op: &str, domain: &str, a: Value, b: Value) -> Result<Value> {\n    use Value::*;\n    if op == \"==\" || op == \"!=\" {\n        return Ok(Bool(equal(&a, &b)? == (op == \"==\")));\n    }\n    let exact_domain = !matches!(domain, \"Float32\" | \"Float64\" | \"Complex64\" | \"Complex128\");\n    if numeric_class(&a) != Some(exact_domain) || numeric_class(&b) != Some(exact_domain) {\n        return Err(\"numeric operands must match the resolved arithmetic domain; use an explicit conversion\".into());\n    }\n    macro_rules! calculate {\n        ($x:expr,$y:expr,$variant:ident) => {{\n            let x = $x;\n            let y = $y;\n            match op {\n                \"+\" => Ok($variant(x + y)),\n                \"-\" => Ok($variant(x - y)),\n                \"*\" => Ok($variant(x * y)),\n                \"/\" => Ok($variant(x / y)),\n                \"<\" => Ok(Bool(x < y)),\n                \"<=\" => Ok(Bool(x <= y)),\n                \">\" => Ok(Bool(x > y)),\n                \">=\" => Ok(Bool(x >= y)),\n                _ => Err(\"invalid arithmetic operation\".into()),\n            }\n        }};\n    }\n    if domain == \"Float32\" {\n        return calculate!(\n            f32::from_value(a.convert(\"Float32\", 64)?)?,\n            f32::from_value(b.convert(\"Float32\", 64)?)?,\n            Float32\n        );\n    }\n    if domain == \"Float64\" {\n        return calculate!(a.real64()?, b.real64()?, Float64);\n    }\n    macro_rules! complex {\n        ($x:expr,$y:expr,$variant:ident) => {{\n            let x = $x;\n            let y = $y;\n            match op {\n                \"+\" => Ok($variant(x + y)),\n                \"-\" => Ok($variant(x - y)),\n                \"*\" => Ok($variant(x * y)),\n                \"/\" => {\n                    // Match portable componentwise IEEE operations at declared precision.\n                    let d = y.re * y.re + y.im * y.im;\n                    Ok($variant(num_complex::Complex::new(\n                        (x.re * y.re + x.im * y.im) / d,\n                        (x.im * y.re - x.re * y.im) / d,\n                    )))\n                }\n                _ => Err(\"complex values are not ordered\".into()),\n            }\n        }};\n    }\n    if domain == \"Complex64\" {\n        return complex!(\n            num_complex::Complex32::from_value(a.convert(\"Complex64\", 64)?)?,\n            num_complex::Complex32::from_value(b.convert(\"Complex64\", 64)?)?,\n            Complex32\n        );\n    }\n    if domain == \"Complex128\" {\n        return complex!(a.complex64()?, b.complex64()?, Complex64);\n    }\n    let x = a.exact()?;\n    let y = b.exact()?;\n    if matches!(op, \"/\" | \"quot\" | \"rem\") && y.is_zero() {\n        return Err(\"exact division by zero\".into());\n    }\n    let result = match op {\n        \"+\" => x + y,\n        \"-\" => x - y,\n        \"*\" => x * y,\n        \"/\" => x / y,\n        \"quot\" => return Ok(Integer(a.integer()? / b.integer()?)),\n        \"rem\" => return Ok(Integer(a.integer()? % b.integer()?)),\n        \"pow\" => {\n            let exponent = b.integer()?;\n            if exponent.is_negative() {\n                return Err(\"negative exponent\".into());\n            }\n            let exponent = exponent.to_u32().ok_or_else(|| \"exponent too large\".to_string())?;\n            return Ok(Integer(num_traits::Pow::pow(a.integer()?, exponent)));\n        }\n        \"<\" => return Ok(Bool(x < y)),\n        \"<=\" => return Ok(Bool(x <= y)),\n        \">\" => return Ok(Bool(x > y)),\n        \">=\" => return Ok(Bool(x >= y)),\n        _ => return Err(\"invalid arithmetic operation\".into()),\n    };\n    Rational(result).convert(domain, 64)\n}\n\npub fn negate(value: Value) -> Result<Value> {\n    Ok(match value {\n        Value::Integer(x) => Value::Integer(-x),\n        Value::Rational(x) => Value::Rational(-x),\n        Value::Decimal(x) => Value::Decimal(Decimal::new(-x.coefficient, x.exponent)),\n        Value::Float32(x) => Value::Float32(-x),\n        Value::Float64(x) => Value::Float64(-x),\n        Value::Complex32(x) => Value::Complex32(-x),\n        Value::Complex64(x) => Value::Complex64(-x),\n        _ => return Err(\"negation requires numeric operand\".into()),\n    })\n}\n\npub trait IntoValue {\n    fn into_value(self) -> Value;\n}\npub trait FromValue: Sized {\n    fn from_value(value: Value) -> Result<Self>;\n}\nmacro_rules! native {\n    ($t:ty,$variant:ident) => {\n        impl IntoValue for $t {\n            fn into_value(self) -> Value {\n                Value::$variant(self)\n            }\n        }\n        impl FromValue for $t {\n            fn from_value(value: Value) -> Result<Self> {\n                if let Value::$variant(x) = value {\n                    Ok(x)\n                } else {\n                    Err(concat!(\"expected \", stringify!($t)).into())\n                }\n            }\n        }\n    };\n}\nnative!(BigInt, Integer);\nnative!(Decimal, Decimal);\nnative!(BigRational, Rational);\nnative!(f32, Float32);\nnative!(f64, Float64);\nnative!(Complex32, Complex32);\nnative!(Complex64, Complex64);\nnative!(bool, Bool);\nnative!(char, Char);\nnative!(String, Text);\n\nnative!(Symbol, Symbol);\nnative!(Handle, Handle);\nimpl IntoValue for Integer {\n    fn into_value(self) -> Value {\n        Value::Integer(self.0)\n    }\n}\nimpl FromValue for Integer {\n    fn from_value(value: Value) -> Result<Self> {\n        Ok(Self(value.integer()?))\n    }\n}\nimpl IntoValue for BigUint {\n    fn into_value(self) -> Value {\n        Value::Integer(self.into())\n    }\n}\nimpl FromValue for BigUint {\n    fn from_value(value: Value) -> Result<Self> {\n        value\n            .integer()?\n            .to_biguint()\n            .ok_or_else(|| \"BigUInt cannot be negative\".into())\n    }\n}\nmacro_rules! primitive_int {\n    ($($t:ty),*) => {$ (\n        impl IntoValue for $t { fn into_value(self)->Value { Value::Integer(BigInt::from(self)) } }\n        impl FromValue for $t { fn from_value(value:Value)->Result<Self> {\n            Self::try_from(value.integer()?).map_err(|_|concat!(\"integer outside \",stringify!($t),\" range\").into())\n        } }\n    )*};\n}\nprimitive_int!(\n    i8, i16, i32, i64, i128, isize, u8, u16, u32, u64, u128, usize\n);\nmacro_rules! raw {\n    ($t:ident,$variant:ident,$valid:expr) => {\n        impl IntoValue for $t {\n            fn into_value(self) -> Value {\n                Value::$variant(self.0)\n            }\n        }\n        impl FromValue for $t {\n            fn from_value(value: Value) -> Result<Self> {\n                match value {\n                    Value::$variant(x) if ($valid)(&x) => Ok(Self(x)),\n                    _ => Err(concat!(\"invalid \", stringify!($t)).into()),\n                }\n            }\n        }\n    };\n}\nraw!(CodePoint, CodePoint, |x: &u32| *x <= 0x10ffff);\nraw!(CodePointText, CodePointText, |x: &Vec<u32>| x\n    .iter()\n    .all(|c| *c <= 0x10ffff));\nraw!(Utf16Text, Utf16Text, |_: &Vec<u16>| true);\nmacro_rules! absence {\n    ($t:ty,$variant:ident,$value:expr) => {\n        impl IntoValue for $t {\n            fn into_value(self) -> Value {\n                Value::$variant\n            }\n        }\n        impl FromValue for $t {\n            fn from_value(value: Value) -> Result<Self> {\n                if matches!(value, Value::$variant) {\n                    Ok($value)\n                } else {\n                    Err(concat!(\"expected \", stringify!($t)).into())\n                }\n            }\n        }\n    };\n}\nabsence!((), Unit, ());\nabsence!(Null, Null, Null);\nabsence!(Undefined, Undefined, Undefined);\nmacro_rules! presence {\n    ($t:ident,$absent:ident) => {\n        impl<T: IntoValue> IntoValue for $t<T> {\n            fn into_value(self) -> Value {\n                Value::$t(match self {\n                    Self::$absent => None,\n                    Self::Present(x) => Some(Box::new(x.into_value())),\n                })\n            }\n        }\n        impl<T: FromValue> FromValue for $t<T> {\n            fn from_value(value: Value) -> Result<Self> {\n                match value {\n                    Value::$t(None) => Ok(Self::$absent),\n                    Value::$t(Some(x)) => Ok(Self::Present(T::from_value(*x)?)),\n                    _ => Err(\"presence type mismatch\".into()),\n                }\n            }\n        }\n    };\n}\npresence!(Nullable, Null);\npresence!(Optional, Undefined);\n\n/// Algebraic Either is independent of interoperability absence wrappers.\n#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]\npub enum Either<L, R> {\n    Left(L),\n    Right(R),\n}\nimpl<T: IntoValue> IntoValue for Box<T> {\n    fn into_value(self) -> Value {\n        (*self).into_value()\n    }\n}\nimpl<T: FromValue> FromValue for Box<T> {\n    fn from_value(value: Value) -> Result<Self> {\n        T::from_value(value).map(Box::new)\n    }\n}\nimpl<T: IntoValue> IntoValue for Vec<T> {\n    fn into_value(self) -> Value {\n        Value::List(self.into_iter().map(IntoValue::into_value).collect())\n    }\n}\nimpl<T: FromValue> FromValue for Vec<T> {\n    fn from_value(value: Value) -> Result<Self> {\n        let values = match value {\n            Value::List(values) => values,\n            // A Stack, whose top is last natively.\n            value @ Value::Data(..) => collection_items(value)?,\n            Value::Bytes(values) => values\n                .into_iter()\n                .map(|v| Value::Integer(v.into()))\n                .collect(),\n            _ => return Err(\"expected List or Bytes\".into()),\n        };\n        values.into_iter().map(T::from_value).collect()\n    }\n}\nimpl<T: IntoValue> IntoValue for Option<T> {\n    fn into_value(self) -> Value {\n        Value::Maybe(self.map(|x| Box::new(x.into_value())))\n    }\n}\nimpl<T: FromValue> FromValue for Option<T> {\n    fn from_value(value: Value) -> Result<Self> {\n        match value {\n            Value::Maybe(value) => value.map(|x| T::from_value(*x)).transpose(),\n            _ => Err(\"expected Maybe\".into()),\n        }\n    }\n}\nimpl<L: IntoValue, R: IntoValue> IntoValue for Either<L, R> {\n    fn into_value(self) -> Value {\n        match self {\n            Self::Left(x) => Value::Left(Box::new(x.into_value())),\n            Self::Right(x) => Value::Right(Box::new(x.into_value())),\n        }\n    }\n}\nimpl<L: FromValue, R: FromValue> FromValue for Either<L, R> {\n    fn from_value(value: Value) -> Result<Self> {\n        match value {\n            Value::Left(x) => Ok(Self::Left(L::from_value(*x)?)),\n            Value::Right(x) => Ok(Self::Right(R::from_value(*x)?)),\n            _ => Err(\"expected Either\".into()),\n        }\n    }\n}\n\n// A GADT case's existential fields hold checked dynamic values.\nimpl IntoValue for Value {\n    fn into_value(self) -> Value {\n        self\n    }\n}\nimpl FromValue for Value {\n    fn from_value(value: Value) -> Result<Self> {\n        Ok(value)\n    }\n}\n\n/// A fully applied type, or a parameter in a constructor's field schema.\n#[derive(Clone, Debug, PartialEq, Eq, Hash)]\npub enum TypeRef {\n    Named(&'static str, Vec<TypeRef>),\n    Parameter(usize),\n}\n\nimpl TypeRef {\n    pub fn named(name: &'static str, arguments: Vec<TypeRef>) -> Self {\n        Self::Named(name, arguments)\n    }\n\n    /// Expression runtime spelling, after schema type arguments are substituted.\n    pub fn expression_key(&self) -> Result<String> {\n        match self {\n            Self::Parameter(index) => Err(format!(\"unbound expression type parameter {index}\")),\n            Self::Named(name, arguments) => {\n                let mut parts = vec![(*name).to_owned()];\n                for argument in arguments {\n                    parts.push(argument.expression_key()?);\n                }\n                Ok(parts.join(\" \"))\n            }\n        }\n    }\n\n    pub fn instantiate(&self, arguments: &[TypeRef]) -> Result<Self> {\n        match self {\n            Self::Parameter(index) => arguments\n                .get(*index)\n                .cloned()\n                .ok_or_else(|| format!(\"unbound data type parameter {index}\")),\n            Self::Named(name, fields) => Ok(Self::Named(\n                name,\n                fields\n                    .iter()\n                    .map(|field| field.instantiate(arguments))\n                    .collect::<Result<_>>()?,\n            )),\n        }\n    }\n}\n\n/// Substitute known types, leaving open parameters in place.\nfn substitute_open(ty: &TypeRef, known: &[TypeRef]) -> Result<TypeRef> {\n    Ok(match ty {\n        TypeRef::Parameter(index) => known.get(*index).cloned().unwrap_or(TypeRef::Parameter(*index)),\n        TypeRef::Named(name, arguments) => TypeRef::Named(\n            name,\n            arguments.iter().map(|argument| substitute_open(argument, known)).collect::<Result<_>>()?,\n        ),\n    })\n}\n\n#[derive(Clone, Debug)]\npub struct ConstructorSchema {\n    pub tag: &'static str,\n    pub fields: Vec<TypeRef>,\n}\n\n#[derive(Clone, Debug)]\npub struct DataSchema {\n    pub name: &'static str,\n    pub parameters: usize,\n    pub constructors: Vec<ConstructorSchema>,\n}\n\n/// Typed constructor predicates receive instantiated type arguments and logical\n/// fields. A false result rejects a candidate; an error is an evaluation failure.\npub type FieldPredicate = fn(&Schema, &[TypeRef], &[Value], u32, &mut Context) -> Result<bool>;\n\n#[derive(Clone, Debug)]\npub struct ConstructorContract {\n    pub tag: &'static str,\n    pub predicates: Vec<FieldPredicate>,\n}\n\n#[derive(Clone, Debug, PartialEq)]\npub enum ValueCheck {\n    Accepted(Value),\n    Rejected(String),\n}\n\n#[derive(Debug)]\nenum ValidationFailure {\n    Rejected(String),\n    Error(String),\n}\n\nimpl ValidationFailure {\n    fn context(self, prefix: String) -> Self {\n        match self {\n            Self::Rejected(message) => Self::Rejected(format!(\"{prefix}: {message}\")),\n            Self::Error(message) => Self::Error(format!(\"{prefix}: {message}\")),\n        }\n    }\n\n    fn message(self) -> String {\n        match self {\n            Self::Rejected(message) | Self::Error(message) => message,\n        }\n    }\n}\n\nimpl From<String> for ValidationFailure {\n    fn from(message: String) -> Self {\n        Self::Error(message)\n    }\n}\n\n/// Compiler-provided data definitions. Validation is framework-independent and\n/// follows instantiated field types, rather than guessing from Rust payloads.\n#[derive(Clone, Debug)]\npub struct Schema {\n    definitions: HashMap<&'static str, DataSchema>,\n    contracts: HashMap<&'static str, Vec<FieldPredicate>>,\n    // Indexed families: per constructor, index terms then guards, in prefix\n    // notation over field indices. Validation checks the guards.\n    indices: HashMap<&'static str, &'static [&'static str]>,\n    // GADT constructors: refinements fixing parameters to patterns, and the\n    // number of existentials (parameters numbered after the definition's own).\n    refinements: HashMap<&'static str, (Vec<(usize, TypeRef)>, usize)>,\n    // Existentials only a value determines (parameter numbers), by tag; their\n    // types travel as the trailing Text witness fields.\n    witnesses: HashMap<&'static str, &'static [usize]>,\n    // Handle types: their values are handles, passed along unopened.\n    handles: std::collections::HashSet<&'static str>,\n}\n\n/// Types a generator may choose for an existential that only a value fixes.\npub fn witness_pool() -> Vec<TypeRef> {\n    vec![TypeRef::Named(\"Bool\", vec![]), TypeRef::Named(\"Int32\", vec![])]\n}\n\n/// A witness spells a type as its name, or a parenthesized application.\npub fn witness_key(ty: &TypeRef) -> String {\n    match ty {\n        TypeRef::Named(name, arguments) if arguments.is_empty() => (*name).to_owned(),\n        TypeRef::Named(name, arguments) => {\n            let mut parts = vec![(*name).to_owned()];\n            parts.extend(arguments.iter().map(witness_key));\n            format!(\"({})\", parts.join(\" \"))\n        }\n        TypeRef::Parameter(index) => format!(\"?{index}\"),\n    }\n}\n\n/// Reads a witness key back into a type reference. Type names are interned:\n/// a name the schema does not know is rejected by the caller's type check.\npub fn parse_witness(text: &str) -> Result<TypeRef> {\n    let spaced = text.replace('(', \" ( \").replace(')', \" ) \");\n    let tokens: Vec<&str> = spaced.split_whitespace().collect();\n    fn read(tokens: &[&str], at: &mut usize) -> Result<TypeRef> {\n        let token = *tokens.get(*at).ok_or(\"malformed type witness\")?;\n        *at += 1;\n        if token != \"(\" {\n            return Ok(TypeRef::Named(intern(token), vec![]));\n        }\n        let name = *tokens.get(*at).ok_or(\"malformed type witness\")?;\n        *at += 1;\n        let mut arguments = Vec::new();\n        while *tokens.get(*at).ok_or(\"malformed type witness\")? != \")\" {\n            arguments.push(read(tokens, at)?);\n        }\n        *at += 1;\n        Ok(TypeRef::Named(intern(name), arguments))\n    }\n    let mut at = 0;\n    let result = read(&tokens, &mut at)?;\n    if at != tokens.len() {\n        return Err(\"malformed type witness\".into());\n    }\n    Ok(result)\n}\n\n/// Witness type names are few; leaking each distinct name once is bounded.\nfn intern(name: &str) -> &'static str {\n    use std::sync::{Mutex, OnceLock};\n    static NAMES: OnceLock<Mutex<std::collections::HashSet<&'static str>>> = OnceLock::new();\n    let mut names = NAMES.get_or_init(|| Mutex::new(std::collections::HashSet::new())).lock().unwrap();\n    if let Some(found) = names.get(name) {\n        return found;\n    }\n    let leaked: &'static str = Box::leak(name.to_owned().into_boxed_str());\n    names.insert(leaked);\n    leaked\n}\n\n/// A GADT constructor's refinements and existential count, by tag.\npub type Refinements = Vec<(&'static str, Vec<(usize, TypeRef)>, usize)>;\n\n/// A prefix index term: `c<n>`, `f<field>[.<index>]` or an operator.\nenum SchemaIndexTerm {\n    Constant(BigInt),\n    Field(usize, usize),\n    Apply(&'static str, Box<SchemaIndexTerm>, Box<SchemaIndexTerm>),\n}\n\nfn parse_schema_index(tokens: &[&'static str], at: &mut usize) -> Result<SchemaIndexTerm> {\n    let token = *tokens.get(*at).ok_or(\"malformed index term\")?;\n    *at += 1;\n    if let Some(digits) = token.strip_prefix('c') {\n        return Ok(SchemaIndexTerm::Constant(\n            digits.parse().map_err(|_| \"malformed index term\".to_string())?,\n        ));\n    }\n    if let Some(reference) = token.strip_prefix('f') {\n        let mut parts = reference.splitn(2, '.');\n        let position = parts.next().unwrap_or(\"\").parse().map_err(|_| \"malformed index term\".to_string())?;\n        let index = match parts.next() {\n            Some(index) => index.parse().map_err(|_| \"malformed index term\".to_string())?,\n            None => 0,\n        };\n        return Ok(SchemaIndexTerm::Field(position, index));\n    }\n    let left = parse_schema_index(tokens, at)?;\n    let right = parse_schema_index(tokens, at)?;\n    Ok(SchemaIndexTerm::Apply(token, Box::new(left), Box::new(right)))\n}\n\n/// Natural index arithmetic; `None` when an operation has no natural value.\nfn eval_schema_index(\n    term: &SchemaIndexTerm,\n    field: &mut dyn FnMut(usize, usize) -> Result<BigInt>,\n) -> Result<Option<BigInt>> {\n    Ok(match term {\n        SchemaIndexTerm::Constant(value) => Some(value.clone()),\n        SchemaIndexTerm::Field(position, index) => Some(field(*position, *index)?),\n        SchemaIndexTerm::Apply(op, left, right) => {\n            let (Some(x), Some(y)) = (eval_schema_index(left, field)?, eval_schema_index(right, field)?) else {\n                return Ok(None);\n            };\n            match *op {\n                \"+\" => Some(x + y),\n                \"-\" => (x >= y).then(|| x - y),\n                \"*\" => Some(x * y),\n                \"div\" => (y.is_positive()).then(|| x / y),\n                \"mod\" => (y.is_positive()).then(|| x % y),\n                \"^\" => y.to_u32().filter(|e| *e <= 64).map(|e| num_traits::Pow::pow(x, e)),\n                _ => return Err(\"malformed index term\".into()),\n            }\n        }\n    })\n}\n\nfn is_index_guard(text: &str) -> bool {\n    text.starts_with(\"== \") || text.starts_with(\">= \")\n}\n\nfn builtin_arity(name: &str) -> Option<usize> {\n    match name {\n        \"List\" | \"Maybe\" | \"Nullable\" | \"Optional\" => Some(1),\n        \"Either\" => Some(2),\n        \"Bool\" | \"Int8\" | \"Int16\" | \"Int32\" | \"Int64\" | \"UInt8\" | \"UInt16\" | \"UInt32\"\n        | \"UInt64\" | \"IntSize\" | \"UIntSize\" | \"UIntPtr\" | \"Integer\" | \"BigInt\" | \"BigUInt\"\n        | \"Decimal\" | \"Rational\" | \"Float32\" | \"Float64\" | \"Complex64\" | \"Complex128\" | \"Char\"\n        | \"CodePoint\" | \"CodeUnit16\" | \"Text\" | \"CodePointText\" | \"Utf16Text\" | \"Bytes\"\n        | \"Symbol\" | \"Unit\" | \"Null\" | \"Undefined\" => Some(0),\n        _ => None,\n    }\n}\n\n// Recipes describe parameter positions rather than instantiated field types.\n#[derive(Clone, Debug)]\nenum PayloadPlan {\n    Ignore,\n    Parameter(usize),\n    Applied(&'static str, Vec<PayloadPlan>),\n}\n\nimpl PayloadPlan {\n    fn field(ty: &TypeRef, arguments: &[Self]) -> Result<Self> {\n        match ty {\n            TypeRef::Parameter(index) => arguments\n                .get(*index)\n                .cloned()\n                .ok_or_else(|| \"unbound payload parameter\".into()),\n            TypeRef::Named(name, fields) => {\n                let children = fields\n                    .iter()\n                    .map(|field| Self::field(field, arguments))\n                    .collect::<Result<Vec<_>>>()?;\n                Ok(\n                    if children.iter().all(|child| matches!(child, Self::Ignore)) {\n                        Self::Ignore\n                    } else {\n                        Self::Applied(name, children)\n                    },\n                )\n            }\n        }\n    }\n}\n\nimpl Schema {\n    pub fn has_contracts(&self) -> bool {\n        self.contracts\n            .values()\n            .any(|predicates| !predicates.is_empty())\n    }\n\n    pub fn new(definitions: Vec<DataSchema>) -> Result<Self> {\n        Self::with_contracts(definitions, vec![])\n    }\n\n    /// Attach indexed families' index terms and guards, keyed by constructor.\n    pub fn with_indices(mut self, indices: &[(&'static str, &'static [&'static str])]) -> Self {\n        self.indices.extend(indices.iter().copied());\n        self\n    }\n\n    /// Mark handle types, whose values are handles rather than data.\n    pub fn with_handles(mut self, handles: &[&'static str]) -> Self {\n        for name in handles {\n            if self.definitions.get(name).is_some_and(|d| d.constructors.is_empty()) {\n                self.handles.insert(*name);\n            }\n        }\n        self\n    }\n\n    /// Attach constructors' witnessed existentials (parameter numbers).\n    pub fn with_witnesses(mut self, witnesses: &[(&'static str, &'static [usize])]) -> Self {\n        self.witnesses.extend(witnesses.iter().copied());\n        self\n    }\n\n    /// Field types with witnessed existentials read from the trailing witness\n    /// fields of a value.\n    pub fn witnessed_fields(&self, tag: &str, fields: &[TypeRef], values: &[Value]) -> Result<Vec<TypeRef>> {\n        let Some(witnesses) = self.witnesses.get(tag) else {\n            return Ok(fields.to_vec());\n        };\n        if values.len() < witnesses.len() {\n            return Err(\"missing type witness\".into());\n        }\n        let mut keys = Vec::new();\n        for value in &values[values.len() - witnesses.len()..] {\n            let Value::Text(text) = value else {\n                return Err(\"type witness must be text\".into());\n            };\n            keys.push(text.clone());\n        }\n        self.fields_at_witnesses(tag, fields, &keys)\n    }\n\n    /// Field types at the given witness keys; generated codecs use this too.\n    pub fn fields_at_witnesses(&self, tag: &str, fields: &[TypeRef], keys: &[String]) -> Result<Vec<TypeRef>> {\n        let witnesses = self.witnesses.get(tag).copied().unwrap_or(&[]);\n        let size = witnesses.iter().copied().max().map_or(0, |m| m + 1);\n        let mut known: Vec<TypeRef> = (0..size).map(TypeRef::Parameter).collect();\n        for (index, key) in witnesses.iter().zip(keys) {\n            let ty = parse_witness(key)?;\n            self.check_type(&ty, 0)?;\n            known[*index] = ty;\n        }\n        fields.iter().map(|field| substitute_open(field, &known)).collect()\n    }\n\n    /// Each choice of witnesses from the pool: the declared fields at it and\n    /// the witness values.\n    pub fn witness_choices(&self, constructor: &ConstructorSchema) -> Result<Vec<(Vec<TypeRef>, Vec<Value>)>> {\n        let Some(witnesses) = self.witnesses.get(constructor.tag) else {\n            return Ok(vec![(constructor.fields.clone(), vec![])]);\n        };\n        let declared = &constructor.fields[..constructor.fields.len() - witnesses.len()];\n        let mut choices: Vec<Vec<String>> = vec![vec![]];\n        for _ in 0..witnesses.len() {\n            choices = choices\n                .into_iter()\n                .flat_map(|choice| {\n                    witness_pool().into_iter().map(move |ty| {\n                        let mut next = choice.clone();\n                        next.push(witness_key(&ty));\n                        next\n                    })\n                })\n                .collect();\n        }\n        choices\n            .into_iter()\n            .map(|keys| {\n                let fields = self.fields_at_witnesses(constructor.tag, declared, &keys)?;\n                Ok((fields, keys.into_iter().map(Value::Text).collect()))\n            })\n            .collect()\n    }\n\n    /// The index of a checked value, computed from its constructor's term.\n    fn index_of(&self, ty: &TypeRef, value: &Value, index: usize) -> Result<BigInt> {\n        let (TypeRef::Named(name, arguments), Value::Data(tag, fields)) = (ty, value) else {\n            return Err(\"no index for this value\".into());\n        };\n        let definition = self.definitions.get(name).ok_or(\"no index for this type\")?;\n        let constructor = definition\n            .constructors\n            .iter()\n            .find(|constructor| constructor.tag == tag)\n            .ok_or(\"unknown constructor\")?;\n        let texts = self.indices.get(constructor.tag).copied().unwrap_or(&[]);\n        let text = texts\n            .iter()\n            .filter(|text| !is_index_guard(text))\n            .nth(index)\n            .ok_or_else(|| format!(\"no index for {name}\"))?;\n        let tokens: Vec<&'static str> = text.split(' ').collect();\n        let term = parse_schema_index(&tokens, &mut 0)?;\n        let mut field = |position: usize, child: usize| -> Result<BigInt> {\n            let field_type = constructor.fields.get(position).ok_or(\"malformed index term\")?.instantiate(arguments)?;\n            self.index_of(&field_type, &fields[position], child)\n        };\n        eval_schema_index(&term, &mut field)?.ok_or_else(|| format!(\"index of {tag} has no natural value\"))\n    }\n\n    pub fn with_contracts(\n        definitions: Vec<DataSchema>,\n        contracts: Vec<ConstructorContract>,\n    ) -> Result<Self> {\n        Self::with_refinements(definitions, contracts, vec![])\n    }\n\n    pub fn with_refinements(\n        definitions: Vec<DataSchema>,\n        contracts: Vec<ConstructorContract>,\n        refinements: Refinements,\n    ) -> Result<Self> {\n        let mut types = HashMap::new();\n        let mut tags = std::collections::HashSet::new();\n        for definition in definitions {\n            let name = definition.name;\n            if builtin_arity(name).is_some() || types.contains_key(name) {\n                return Err(format!(\"duplicate or reserved data type: {name}\"));\n            }\n            for constructor in &definition.constructors {\n                if !tags.insert(constructor.tag) {\n                    return Err(format!(\"duplicate constructor: {}\", constructor.tag));\n                }\n            }\n            types.insert(name, definition);\n        }\n        let mut predicates = HashMap::new();\n        for contract in contracts {\n            if !tags.contains(contract.tag) {\n                return Err(format!(\"unknown constructor contract: {}\", contract.tag));\n            }\n            if predicates\n                .insert(contract.tag, contract.predicates)\n                .is_some()\n            {\n                return Err(format!(\"duplicate constructor contract: {}\", contract.tag));\n            }\n        }\n        let schema = Self {\n            definitions: types,\n            contracts: predicates,\n            indices: HashMap::new(),\n            witnesses: HashMap::new(),\n            handles: std::collections::HashSet::new(),\n            refinements: refinements\n                .into_iter()\n                .map(|(tag, patterns, existentials)| (tag, (patterns, existentials)))\n                .collect(),\n        };\n        for definition in schema.definitions.values() {\n            for constructor in &definition.constructors {\n                let existentials = schema.refinements.get(constructor.tag).map_or(0, |(_, count)| *count);\n                for field in &constructor.fields {\n                    schema.check_type(field, definition.parameters + existentials)?;\n                }\n            }\n        }\n        Ok(schema)\n    }\n\n    fn check_type(&self, ty: &TypeRef, parameters: usize) -> Result<()> {\n        match ty {\n            TypeRef::Parameter(index) if *index < parameters => Ok(()),\n            TypeRef::Parameter(index) => Err(format!(\"unbound data type parameter {index}\")),\n            TypeRef::Named(name, arguments) => {\n                let arity = builtin_arity(name)\n                    .or_else(|| self.definitions.get(name).map(|d| d.parameters))\n                    .ok_or_else(|| format!(\"unknown data type: {name}\"))?;\n                if arity != arguments.len() {\n                    return Err(format!(\"expected {arity} type arguments for {name}\"));\n                }\n                for argument in arguments {\n                    self.check_type(argument, parameters)?;\n                }\n                Ok(())\n            }\n        }\n    }\n\n    /// Instantiated fields for composing native generators. None denotes a\n    /// built-in type; an empty list denotes a user type with no constructors.\n    pub fn constructor_fields(&self, ty: &TypeRef) -> Result<Option<Vec<ConstructorSchema>>> {\n        self.check_type(ty, 0)?;\n        let TypeRef::Named(name, arguments) = ty else {\n            return Err(\"uninstantiated generator type\".into());\n        };\n        self.definitions\n            .get(name)\n            .map(|definition| {\n                definition\n                    .constructors\n                    .iter()\n                    // A GADT constructor whose refinements do not match these\n                    // arguments builds no value of this type.\n                    .filter_map(|constructor| {\n                        self.refine(constructor, arguments, definition.parameters)\n                            .map(|extended| (constructor, extended))\n                    })\n                    .map(|(constructor, extended)| {\n                        Ok(ConstructorSchema {\n                            tag: constructor.tag,\n                            fields: constructor\n                                .fields\n                                .iter()\n                                .map(|field| field.instantiate(&extended))\n                                .collect::<Result<_>>()?,\n                        })\n                    })\n                    .collect::<Result<_>>()\n            })\n            .transpose()\n    }\n\n    /// Arguments extended with the existentials a constructor's refinements\n    /// bind; None when the refinements do not match.\n    fn refine(&self, constructor: &ConstructorSchema, arguments: &[TypeRef], parameters: usize) -> Option<Vec<TypeRef>> {\n        let Some((patterns, existentials)) = self.refinements.get(constructor.tag) else {\n            return Some(arguments.to_vec());\n        };\n        fn matches(\n            pattern: &TypeRef,\n            actual: &TypeRef,\n            arguments: &[TypeRef],\n            parameters: usize,\n            bound: &mut HashMap<usize, TypeRef>,\n        ) -> bool {\n            match (pattern, actual) {\n                (TypeRef::Parameter(index), _) if *index < parameters => arguments.get(*index) == Some(actual),\n                (TypeRef::Parameter(index), _) => bound.entry(*index).or_insert_with(|| actual.clone()) == actual,\n                (TypeRef::Named(name, children), TypeRef::Named(other, values)) => {\n                    name == other\n                        && children.len() == values.len()\n                        && children.iter().zip(values).all(|(child, value)| matches(child, value, arguments, parameters, bound))\n                }\n                _ => false,\n            }\n        }\n        let mut bound = HashMap::new();\n        for (index, pattern) in patterns {\n            if !matches(pattern, arguments.get(*index)?, arguments, parameters, &mut bound) {\n                return None;\n            }\n        }\n        let mut extended = arguments.to_vec();\n        for k in 0..*existentials {\n            // A witnessed existential stays open until a value supplies it.\n            extended.push(bound.get(&(parameters + k)).cloned().unwrap_or(TypeRef::Parameter(parameters + k)));\n        }\n        Some(extended)\n    }\n\n    /// Validate first, then check only stored occurrences of type arguments.\n    /// The dispatcher shares one mutable context without aliasing callback borrows.\n    pub fn all_payloads_with_context(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        predicate_count: usize,\n        bits: u32,\n        context: &mut Context,\n        mut predicate: impl FnMut(usize, Value, &mut Context) -> Result<Value>,\n    ) -> Result<Value> {\n        self.check_type(ty, 0)?;\n        let TypeRef::Named(name, arguments) = ty else {\n            return Err(\"payload predicates require an instantiated data type\".into());\n        };\n        if !self.definitions.contains_key(name)\n            && !matches!(*name, \"List\" | \"Maybe\" | \"Either\" | \"Nullable\" | \"Optional\")\n        {\n            return Err(\"payload predicates require a data type\".into());\n        }\n        if arguments.len() != predicate_count {\n            return Err(\"payload predicate arity mismatch\".into());\n        }\n        let checked = self.validate_with_context(value, ty, bits, context)?;\n        let plan = PayloadPlan::Applied(\n            name,\n            (0..predicate_count).map(PayloadPlan::Parameter).collect(),\n        );\n        self.walk_payload(&plan, checked, context, &mut predicate)\n            .map(Value::Bool)\n    }\n\n    fn walk_payload(\n        &self,\n        plan: &PayloadPlan,\n        value: Value,\n        context: &mut Context,\n        predicate: &mut impl FnMut(usize, Value, &mut Context) -> Result<Value>,\n    ) -> Result<bool> {\n        let (name, arguments) = match plan {\n            PayloadPlan::Ignore => return Ok(true),\n            PayloadPlan::Parameter(index) => return predicate(*index, value, context)?.boolean(),\n            PayloadPlan::Applied(name, arguments) => (*name, arguments),\n        };\n        match (name, value) {\n            (\"List\", Value::List(values)) => {\n                for (index, value) in values.into_iter().enumerate() {\n                    if !self\n                        .walk_payload(&arguments[0], value, context, predicate)\n                        .map_err(|error| format!(\"List element {index}: {error}\"))?\n                    {\n                        return Ok(false);\n                    }\n                }\n                Ok(true)\n            }\n            (\"Maybe\", Value::Maybe(value))\n            | (\"Nullable\", Value::Nullable(value))\n            | (\"Optional\", Value::Optional(value)) => match value {\n                None => Ok(true),\n                Some(value) => self\n                    .walk_payload(&arguments[0], *value, context, predicate)\n                    .map_err(|error| format!(\"{name} payload: {error}\")),\n            },\n            (\"Either\", Value::Left(value)) => self\n                .walk_payload(&arguments[0], *value, context, predicate)\n                .map_err(|error| format!(\"Either Left payload: {error}\")),\n            (\"Either\", Value::Right(value)) => self\n                .walk_payload(&arguments[1], *value, context, predicate)\n                .map_err(|error| format!(\"Either Right payload: {error}\")),\n            (_, Value::Data(tag, values)) => {\n                let definition = self\n                    .definitions\n                    .get(name)\n                    .ok_or_else(|| format!(\"unknown payload data type: {name}\"))?;\n                let constructor = definition\n                    .constructors\n                    .iter()\n                    .find(|item| item.tag == tag)\n                    .ok_or_else(|| format!(\"unknown payload constructor: {tag}\"))?;\n                for (index, (field, value)) in constructor.fields.iter().zip(values).enumerate() {\n                    let plan = PayloadPlan::field(field, arguments)?;\n                    if !self\n                        .walk_payload(&plan, value, context, predicate)\n                        .map_err(|error| format!(\"{tag} field {index}: {error}\"))?\n                    {\n                        return Ok(false);\n                    }\n                }\n                Ok(true)\n            }\n            _ => Err(\"payload traversal requires a matching structural value\".into()),\n        }\n    }\n\n    pub fn validate(&self, value: Value, ty: &TypeRef, bits: u32) -> Result<Value> {\n        self.validate_with_context(value, ty, bits, &mut Context::default())\n    }\n\n    pub fn check_with_context(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        bits: u32,\n        context: &mut Context,\n    ) -> Result<ValueCheck> {\n        self.check_type(ty, 0)?;\n        if !matches!(bits, 32 | 64) {\n            return Err(\"machineBits must be 32 or 64\".into());\n        }\n        match self.walk(value, ty, bits, false, context) {\n            Ok(value) => Ok(ValueCheck::Accepted(value)),\n            Err(ValidationFailure::Rejected(message)) => Ok(ValueCheck::Rejected(message)),\n            Err(ValidationFailure::Error(message)) => Err(message),\n        }\n    }\n\n    pub fn validate_with_context(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        bits: u32,\n        context: &mut Context,\n    ) -> Result<Value> {\n        match self.check_with_context(value, ty, bits, context)? {\n            ValueCheck::Accepted(value) => Ok(value),\n            ValueCheck::Rejected(message) => Err(message),\n        }\n    }\n\n    /// Check logical fields before adapting raw code units to native integers.\n    pub fn native_value(&self, value: Value, ty: &TypeRef, bits: u32) -> Result<Value> {\n        self.native_value_with_context(value, ty, bits, &mut Context::default())\n    }\n\n    pub fn native_value_with_context(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        bits: u32,\n        context: &mut Context,\n    ) -> Result<Value> {\n        let checked = self.validate_with_context(value, ty, bits, context)?;\n        self.walk(checked, ty, bits, true, context)\n            .map_err(ValidationFailure::message)\n    }\n\n    fn walk(\n        &self,\n        value: Value,\n        ty: &TypeRef,\n        bits: u32,\n        native: bool,\n        context: &mut Context,\n    ) -> std::result::Result<Value, ValidationFailure> {\n        let TypeRef::Named(name, arguments) = ty else {\n            return Err(\"uninstantiated data type parameter\".to_string().into());\n        };\n        // A native collection arrives as a plain list: retag it, put a Set\n        // or KeyVal in canonical order, and a Stack's top first.\n        let value = match (collection_tag(name), value) {\n            (Some(tag), Value::List(mut items)) => {\n                if name.ends_with(\"::Set\") || name.ends_with(\"::KeyVal\") {\n                    items = canonical_items(items, name.ends_with(\"::KeyVal\"))?;\n                } else if name.ends_with(\"::Stack\") {\n                    items.reverse();\n                }\n                Value::Data(tag.into(), vec![Value::List(items)])\n            }\n            (_, value) => value,\n        };\n        if self.handles.contains(name) {\n            let Value::Handle(handle) = value else {\n                return Err(format!(\"expected a handle of type {name}\").into());\n            };\n            handle.named(name);\n            return Ok(Value::Handle(handle));\n        }\n        if let Some(definition) = self.definitions.get(name) {\n            let Value::Data(tag, fields) = value else {\n                return Err(format!(\"expected data value of type {name}\").into());\n            };\n            let constructor = definition\n                .constructors\n                .iter()\n                .find(|constructor| constructor.tag == tag)\n                .ok_or_else(|| format!(\"constructor {tag} does not belong to {name}\"))?;\n            if fields.len() != constructor.fields.len() {\n                return Err(format!(\"wrong field count for {tag}\").into());\n            }\n            let arguments = &self\n                .refine(constructor, arguments, definition.parameters)\n                .ok_or_else(|| format!(\"constructor {tag} is not a value of {name}\"))?;\n            let instantiated = constructor\n                .fields\n                .iter()\n                .map(|field| field.instantiate(arguments))\n                .collect::<Result<Vec<_>>>()?;\n            let field_types = self.witnessed_fields(&tag, &instantiated, &fields)?;\n            let checked: Vec<Value> = fields\n                .into_iter()\n                .zip(&field_types)\n                .enumerate()\n                .map(|(index, (field, field_type))| {\n                    self.walk(\n                        field,\n                        field_type,\n                        bits,\n                        native,\n                        context,\n                    )\n                    .map_err(|error| error.context(format!(\"{tag} field {index}\")))\n                })\n                .collect::<std::result::Result<_, ValidationFailure>>()?;\n            if !native {\n                if let Some(predicates) = self.contracts.get(constructor.tag) {\n                    for (index, predicate) in predicates.iter().enumerate() {\n                        let label = format!(\"{tag}: field refinement {}\", index + 1);\n                        let accepted = predicate(self, arguments, &checked, bits, context)\n                            .map_err(|message| {\n                                ValidationFailure::Error(format!(\"{label}: {message}\"))\n                            })?;\n                        if !accepted {\n                            return Err(ValidationFailure::Rejected(format!(\"{label} failed\")));\n                        }\n                    }\n                }\n                for text in self.indices.get(constructor.tag).copied().unwrap_or(&[]) {\n                    if !is_index_guard(text) {\n                        continue;\n                    }\n                    let tokens: Vec<&'static str> = text.split(' ').collect();\n                    let mut at = 1;\n                    let left = parse_schema_index(&tokens, &mut at)?;\n                    let right = parse_schema_index(&tokens, &mut at)?;\n                    let mut field = |position: usize, child: usize| -> Result<BigInt> {\n                        let field_type = constructor.fields.get(position).ok_or(\"malformed index term\")?.instantiate(arguments)?;\n                        self.index_of(&field_type, &checked[position], child)\n                    };\n                    let x = eval_schema_index(&left, &mut field)?;\n                    let y = eval_schema_index(&right, &mut field)?;\n                    let holds = match (x, y) {\n                        (Some(x), Some(y)) => if tokens[0] == \"==\" { x == y } else { x >= y },\n                        _ => false,\n                    };\n                    if !holds {\n                        return Err(ValidationFailure::Rejected(format!(\"{tag}: index guard {text} failed\")));\n                    }\n                }\n            }\n            return Ok(Value::Data(tag, checked));\n        }\n        if arguments.is_empty() {\n            let checked = validate(value, name, bits)?;\n            return if native {\n                native_value(checked, name).map_err(ValidationFailure::Error)\n            } else {\n                Ok(checked)\n            };\n        }\n        match (*name, arguments.as_slice(), value) {\n            (\"List\", [element], Value::List(values)) => Ok(Value::List(\n                values\n                    .into_iter()\n                    .enumerate()\n                    .map(|(index, value)| {\n                        self.walk(value, element, bits, native, context)\n                            .map_err(|error| error.context(format!(\"List element {index}\")))\n                    })\n                    .collect::<std::result::Result<_, ValidationFailure>>()?,\n            )),\n            (\"Maybe\", [element], Value::Maybe(value)) => Ok(Value::Maybe(\n                value\n                    .map(|value| {\n                        self.walk(*value, element, bits, native, context)\n                            .map(Box::new)\n                    })\n                    .transpose()?,\n            )),\n            (\"Nullable\", [element], Value::Nullable(value)) => Ok(Value::Nullable(\n                value\n                    .map(|value| {\n                        self.walk(*value, element, bits, native, context)\n                            .map(Box::new)\n                    })\n                    .transpose()?,\n            )),\n            (\"Optional\", [element], Value::Optional(value)) => Ok(Value::Optional(\n                value\n                    .map(|value| {\n                        self.walk(*value, element, bits, native, context)\n                            .map(Box::new)\n                    })\n                    .transpose()?,\n            )),\n            (\"Either\", [left, _], Value::Left(value)) => Ok(Value::Left(Box::new(\n                self.walk(*value, left, bits, native, context)?,\n            ))),\n            (\"Either\", [_, right], Value::Right(value)) => Ok(Value::Right(Box::new(\n                self.walk(*value, right, bits, native, context)?,\n            ))),\n            _ => Err(format!(\"invalid value for {name}\").into()),\n        }\n    }\n}\n\n/// Build a user constructor selected and typed by the compiler. This does not\n/// validate its payload; generated bridges check each field at native boundaries.\npub fn construct_data(tag: &str, fields: Vec<Value>) -> Value {\n    Value::Data(tag.into(), fields)\n}\n\n/// Extract exactly one constructor's fields before typed field conversion.\n/// Tag and arity checks prevent cross-constructor coercion and dropped fields.\npub fn data_fields(value: Value, tag: &str, arity: usize) -> Result<Vec<Value>> {\n    match value {\n        Value::Data(actual, fields) if actual == tag && fields.len() == arity => Ok(fields),\n        Value::Data(actual, fields) => Err(format!(\n            \"expected {tag} with {arity} fields, found {actual} with {} fields\",\n            fields.len()\n        )),\n        _ => Err(format!(\"expected data constructor {tag}\")),\n    }\n}\n\npub fn all_elements(\n    value: Value,\n    mut predicate: impl FnMut(Value) -> Result<Value>,\n) -> Result<Value> {\n    let Value::List(values) = value else {\n        return Err(\"expected List in element predicate\".into());\n    };\n    for (index, item) in values.into_iter().enumerate() {\n        let accepted = predicate(item)\n            .and_then(|result| result.boolean())\n            .map_err(|error| format!(\"List element {index}: {error}\"))?;\n        if !accepted {\n            return Ok(Value::Bool(false));\n        }\n    }\n    Ok(Value::Bool(true))\n}\n\npub fn construct(tag: &str, mut fields: Vec<Value>) -> Result<Value> {\n    Ok(match (tag, fields.len()) {\n        (\"List::Nil\", 0) => Value::List(vec![]),\n        (\"List::Cons\", 2) => {\n            let Value::List(mut tail) = fields.pop().unwrap() else {\n                return Err(\"expected List tail\".into());\n            };\n            tail.insert(0, fields.pop().unwrap());\n            Value::List(tail)\n        }\n        (\"Maybe::Nothing\", 0) => Value::Maybe(None),\n        (\"Maybe::Just\", 1) => Value::Maybe(Some(Box::new(fields.pop().unwrap()))),\n        (\"Either::Left\", 1) => Value::Left(Box::new(fields.pop().unwrap())),\n        (\"Either::Right\", 1) => Value::Right(Box::new(fields.pop().unwrap())),\n        _ => return Err(format!(\"invalid constructor or arity: {tag}\")),\n    })\n}\n\n// Read one saturated type from the compiler's prefix encoding. Both arguments\n// of Either may themselves contain binary and unary type constructors.\nfn split_type(input: &str) -> Result<(&str, &str)> {\n    let (head, mut remaining) = input.split_once(' ').unwrap_or((input, \"\"));\n    if head.is_empty() {\n        return Err(\"missing type argument\".into());\n    }\n    let arity = match head {\n        \"Either\" => 2,\n        \"List\" | \"Maybe\" | \"Nullable\" | \"Optional\" => 1,\n        _ => 0,\n    };\n    for _ in 0..arity {\n        remaining = split_type(remaining)?.1;\n    }\n    Ok((input[..input.len() - remaining.len()].trim_end(), remaining))\n}\npub fn either_types(arguments: &str) -> Result<(&str, &str)> {\n    let (left, rest) = split_type(arguments)?;\n    let (right, extra) = split_type(rest)?;\n    if !extra.is_empty() {\n        return Err(\"extra Either type arguments\".into());\n    }\n    Ok((left, right))\n}\n\npub fn require_architecture(machine_bits: u32) -> Result<()> {\n    if usize::BITS == machine_bits {\n        Ok(())\n    } else {\n        Err(format!(\n            \"machineBits does not match native architecture: profile {machine_bits}, native {}\",\n            usize::BITS\n        ))\n    }\n}\n\n/// Run an async adapter's future to completion on this thread. A waker that\n/// unparks the thread is enough: adapters own whatever executor they need.\npub fn block_on<F: std::future::Future>(future: F) -> F::Output {\n    struct Unpark(std::thread::Thread);\n    impl std::task::Wake for Unpark {\n        fn wake(self: Arc<Self>) {\n            self.0.unpark();\n        }\n    }\n    let waker = std::task::Waker::from(Arc::new(Unpark(std::thread::current())));\n    let mut context = std::task::Context::from_waker(&waker);\n    let mut future = std::pin::pin!(future);\n    loop {\n        match future.as_mut().poll(&mut context) {\n            std::task::Poll::Ready(value) => return value,\n            std::task::Poll::Pending => std::thread::park(),\n        }\n    }\n}\n\n/// The portable total order. Exact numbers by value, text by code point,\n/// sequences by unit, false before true, absence before presence, lists\n/// element by element, Nothing before Just, Left before Right, and other data\n/// by constructor identity, then fields left to right.\npub fn compare_values(a: &Value, b: &Value) -> Result<std::cmp::Ordering> {\n    use std::cmp::Ordering::*;\n    use Value::*;\n    fn items(a: &[Value], b: &[Value]) -> Result<std::cmp::Ordering> {\n        for (x, y) in a.iter().zip(b) {\n            let order = compare_values(x, y)?;\n            if order != Equal {\n                return Ok(order);\n            }\n        }\n        Ok(a.len().cmp(&b.len()))\n    }\n    fn optional(a: &Option<Box<Value>>, b: &Option<Box<Value>>) -> Result<std::cmp::Ordering> {\n        match (a, b) {\n            (None, None) => Ok(Equal),\n            (None, Some(_)) => Ok(Less),\n            (Some(_), None) => Ok(Greater),\n            (Some(x), Some(y)) => compare_values(x, y),\n        }\n    }\n    Ok(match (a, b) {\n        (Bool(x), Bool(y)) => x.cmp(y),\n        (Integer(_) | Decimal(_) | Rational(_), Integer(_) | Decimal(_) | Rational(_)) => a.exact()?.cmp(&b.exact()?),\n        (Text(x), Text(y)) => x.chars().cmp(y.chars()),\n        (Char(x), Char(y)) => x.cmp(y),\n        (CodePoint(x), CodePoint(y)) => x.cmp(y),\n        (CodeUnit16(x), CodeUnit16(y)) => x.cmp(y),\n        (CodePointText(x), CodePointText(y)) => x.cmp(y),\n        (Utf16Text(x), Utf16Text(y)) => x.cmp(y),\n        (Bytes(x), Bytes(y)) => x.cmp(y),\n        (Unit, Unit) | (Null, Null) | (Undefined, Undefined) => Equal,\n        (Nullable(x), Nullable(y)) | (Optional(x), Optional(y)) | (Maybe(x), Maybe(y)) => optional(x, y)?,\n        (Left(_), Right(_)) => Less,\n        (Right(_), Left(_)) => Greater,\n        (Left(x), Left(y)) | (Right(x), Right(y)) => compare_values(x, y)?,\n        (List(x), List(y)) => items(x, y)?,\n        (Data(s, x), Data(t, y)) if s == t => items(x, y)?,\n        (Data(s, _), Data(t, _)) => s.cmp(t),\n        (Handle(x), Handle(y)) if x == y => Equal,\n        (Handle(_), Handle(_)) => return Err(\"handles have no portable order\".into()),\n        _ => return Err(\"values have no portable order\".into()),\n    })\n}\n\n/// A Set's items or a KeyVal's entries sorted by key, keeping the last of\n/// equal keys.\npub fn canonical_items(items: Vec<Value>, keyed: bool) -> Result<Vec<Value>> {\n    let key = |item: &Value| -> Value {\n        match (keyed, item) {\n            (true, Value::Data(_, fields)) if !fields.is_empty() => fields[0].clone(),\n            _ => item.clone(),\n        }\n    };\n    let mut ordered = items;\n    let mut failure = None;\n    ordered.sort_by(|a, b| match compare_values(&key(a), &key(b)) {\n        Ok(order) => order,\n        Err(error) => {\n            failure = Some(error);\n            std::cmp::Ordering::Equal\n        }\n    });\n    if let Some(error) = failure {\n        return Err(error);\n    }\n    let mut result: Vec<Value> = Vec::new();\n    for item in ordered {\n        if let Some(last) = result.last() {\n            if compare_values(&key(last), &key(&item))? == std::cmp::Ordering::Equal {\n                *result.last_mut().unwrap() = item;\n                continue;\n            }\n        }\n        result.push(item);\n    }\n    Ok(result)\n}\n\n// Workflow runtime. A workflow runs under a runtime: a clock, a seeded\n// random source, a trace of what happened, and the state of stateful stages.\n// The runtime travels in the Context every generated function takes; without\n// one, the default runtime applies (real time). Durations are i64\n// microseconds.\n\n/// Tells the time and waits, in microseconds.\npub trait Clock: Send {\n    fn now(&self) -> i64;\n    fn sleep(&mut self, micros: i64);\n    /// A virtual clock's waits pass at once, and timeouts and hedges count\n    /// only the time it reports (see scoped). Real time unless it says so.\n    fn is_virtual(&self) -> bool {\n        false\n    }\n}\n\n/// Monotonic wall time.\npub struct RealClock(std::time::Instant);\nimpl Default for RealClock {\n    fn default() -> Self {\n        RealClock(std::time::Instant::now())\n    }\n}\nimpl Clock for RealClock {\n    fn now(&self) -> i64 {\n        self.0.elapsed().as_micros() as i64\n    }\n    fn sleep(&mut self, micros: i64) {\n        std::thread::sleep(std::time::Duration::from_micros(micros.max(0) as u64));\n    }\n}\n\n/// Advances when slept on and returns at once.\n#[derive(Default)]\npub struct VirtualClock {\n    pub time: i64,\n}\nimpl Clock for VirtualClock {\n    fn now(&self) -> i64 {\n        self.time\n    }\n    fn sleep(&mut self, micros: i64) {\n        self.time += micros;\n    }\n    fn is_virtual(&self) -> bool {\n        true\n    }\n}\n\n/// The Clock ability (lawspec.time's Clock) as the runtime reads it: the\n/// handler a law installs, in microseconds. real_time is true only for the\n/// default handler (the system clock, installed with installed_native); any\n/// other handler is virtual.\npub trait ClockAbility: Send + Sync {\n    fn now_micros(&self) -> i64;\n    fn sleep_micros(&self, micros: i64);\n    fn real_time(&self) -> bool;\n}\n\n/// The key the Clock ability's handler is installed under.\npub const CLOCK_KEY: &str = \"lawspec.time::ability::Clock\";\n\n/// Turns the handler installed for the Clock ability into a ClockAbility.\n/// The runtime cannot name the generated Clock trait, so lawspec.time's\n/// default handlers module registers one (lawspec_time::\n/// register_clock_ability, which the generated tests of a unit whose laws\n/// install a Clock handler call); without it, workflow time is the\n/// runtime's own.\npub type ClockAbilityReader = fn(&Installed) -> Option<Arc<dyn ClockAbility>>;\n\nstatic CLOCK_READER: std::sync::OnceLock<ClockAbilityReader> = std::sync::OnceLock::new();\n\n/// Registers how to read the Clock ability's handler; the first one stays.\npub fn register_clock_ability(reader: ClockAbilityReader) {\n    let _ = CLOCK_READER.set(reader);\n}\n\n/// The Clock handler installed in ctx, as the runtime reads it, if any.\npub fn clock_ability(ctx: &Context) -> Option<Arc<dyn ClockAbility>> {\n    let reader = CLOCK_READER.get()?;\n    reader(&ctx.installed_for(CLOCK_KEY)?)\n}\n\n/// A workflow runtime's clock read through the Clock ability: the handler a\n/// law installs (the virtual clock, or the default real one). A handler that\n/// is not real time is virtual: waits pass at once, and timeouts and hedges\n/// count only the time it reports.\npub struct AbilityClock(pub Arc<dyn ClockAbility>);\nimpl Clock for AbilityClock {\n    fn now(&self) -> i64 {\n        self.0.now_micros()\n    }\n    fn sleep(&mut self, micros: i64) {\n        self.0.sleep_micros(micros)\n    }\n    fn is_virtual(&self) -> bool {\n        !self.0.real_time()\n    }\n}\n\n/// The same sequence on every target for the same seed.\n///\n/// SplitMix64 is small, fast and specified exactly, so every runtime implements\n/// the same generator and a seed names the same case everywhere. ref:splitmix\n/// ref:DEC-portable-seeded-generation\npub struct SplitMix64 {\n    state: u64,\n}\nimpl SplitMix64 {\n    pub fn new(seed: u64) -> Self {\n        SplitMix64 { state: seed }\n    }\n    pub fn next(&mut self) -> u64 {\n        self.state = self.state.wrapping_add(0x9E3779B97F4A7C15);\n        let mut z = self.state;\n        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);\n        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);\n        z ^ (z >> 31)\n    }\n    /// Uniform in [0, bound); 0 when bound is 0.\n    pub fn below(&mut self, bound: u64) -> u64 {\n        if bound == 0 { 0 } else { self.next() % bound }\n    }\n}\n\n/// A stage starting or finishing an attempt, or a wait.\n#[derive(Clone, Debug, PartialEq)]\npub struct TraceEvent {\n    pub kind: &'static str,\n    pub stage: String,\n    pub number: i64,\n    pub succeeded: bool,\n}\n\npub struct WorkflowRuntime {\n    pub clock: Box<dyn Clock>,\n    pub random: SplitMix64,\n    pub trace: Vec<TraceEvent>,\n    pub state: HashMap<String, Value>,\n    /// Whether rate limits, breakers, bulkheads and caches apply.\n    pub gates: bool,\n    cache: HashMap<String, Vec<(Value, Value, i64)>>,\n    // A frame per running workflow: the undos of its completed stages.\n    frames: Vec<Vec<(&'static str, Value, fn(&mut Context, Value) -> Result<Value>)>>,\n    // When the running attempt of a stage with a timeout must end.\n    deadline: Option<std::time::Instant>,\n    // The running attempt's stage and hedge (delay, most).\n    hedge: Option<(&'static str, (i64, i64))>,\n    // The same, on a virtual clock: attempts run one after another.\n    virtual_hedge: Option<(&'static str, (i64, i64))>,\n}\nimpl std::fmt::Debug for WorkflowRuntime {\n    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {\n        write!(f, \"WorkflowRuntime {{ trace: {:?} }}\", self.trace)\n    }\n}\nimpl WorkflowRuntime {\n    pub fn new(clock: Box<dyn Clock>, seed: u64) -> Self {\n        WorkflowRuntime { clock, random: SplitMix64::new(seed), trace: Vec::new(), state: HashMap::new(), gates: true, cache: HashMap::new(), frames: Vec::new(), deadline: None, hedge: None, virtual_hedge: None }\n    }\n}\n\nstatic DEFAULT_RUNTIME: std::sync::OnceLock<Arc<std::sync::Mutex<WorkflowRuntime>>> = std::sync::OnceLock::new();\n\n// A runtime attached to the context keeps its own clock. Otherwise workflow\n// time is the Clock ability's: where a law has installed a Clock handler,\n// workflows wait and time out on it, under a view of the default runtime\n// (its gates; its own trace and state) kept per context and handler, so\n// run_stage and await_step share it.\nfn workflow_runtime(ctx: &Context) -> Arc<std::sync::Mutex<WorkflowRuntime>> {\n    if let Some(runtime) = &ctx.workflow {\n        return runtime.clone();\n    }\n    let runtime = DEFAULT_RUNTIME\n        .get_or_init(|| Arc::new(std::sync::Mutex::new(WorkflowRuntime::new(Box::new(RealClock::default()), 0))))\n        .clone();\n    let Some(installed) = ctx.installed_for(CLOCK_KEY) else { return runtime };\n    let Some(reader) = CLOCK_READER.get() else { return runtime };\n    let mut view = ctx.clock_view.0.lock().unwrap();\n    if let Some((handler, under)) = view.as_ref() {\n        if Arc::ptr_eq(handler, &installed.handler) {\n            return under.clone();\n        }\n    }\n    let Some(clock) = reader(&installed) else { return runtime };\n    let mut under = WorkflowRuntime::new(Box::new(AbilityClock(clock)), 0);\n    under.gates = runtime.lock().unwrap().gates;\n    let under = Arc::new(std::sync::Mutex::new(under));\n    *view = Some((installed.handler.clone(), under.clone()));\n    under\n}\n\n// The workflow runtime a context's Clock handler gives (workflow_runtime).\n#[derive(Clone, Default)]\nstruct ClockView(Arc<std::sync::Mutex<Option<(Arc<dyn std::any::Any + Send + Sync>, Arc<std::sync::Mutex<WorkflowRuntime>>)>>>);\nimpl std::fmt::Debug for ClockView {\n    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {\n        f.write_str(\"ClockView\")\n    }\n}\n\n/// strategy is immediate, fixed, linear, exponential, fibonacci or custom;\n/// delay, step, factor and cap (negative for none) are its parameters.\npub struct Retry {\n    pub strategy: &'static str,\n    pub delay: i64,\n    pub step: i64,\n    pub factor: i64,\n    pub cap: i64,\n    pub attempts: i64,\n    pub jitter: &'static str,\n    pub when: Option<fn(&mut Context, Value) -> Result<bool>>,\n    pub decide: Option<fn(&mut Context, i64, Value, i64) -> Result<Option<i64>>>,\n}\n\n/// A stateful policy: start gives its state, admit a Step of the next state\n/// and a Gate (Admit, WaitFor or Reject), and finish (when set) the state\n/// after the call. wait is -2 to fail at once when not admitted, -1 to wait\n/// without bound, or the most it waits.\npub struct Gate {\n    pub kind: &'static str,\n    pub start: fn(&mut Context, i64) -> Result<Value>,\n    pub admit: fn(&mut Context, Value, i64) -> Result<Value>,\n    pub finish: Option<fn(&mut Context, Value, i64, bool) -> Result<Value>>,\n    pub wait: i64,\n}\n\n/// key names the stage's state; cache is how long a success is reused (0\n/// or less for none); wraps says failures are StageFailures.\npub struct StagePolicy {\n    pub stage: &'static str,\n    pub retry: Option<Retry>,\n    pub timeout: i64,\n    pub key: &'static str,\n    pub gates: Vec<Gate>,\n    pub cache: i64,\n    pub wraps: bool,\n    /// Undoes the stage's success value when its workflow fails.\n    pub compensate: Option<fn(&mut Context, Value) -> Result<Value>>,\n    /// (delay, most): when an attempt has not succeeded after delay, another\n    /// starts beside it, up to most in all; the first success wins.\n    pub hedge: Option<(i64, i64)>,\n}\n\n/// Runs a workflow whose stages compensate: when it fails, the undos of its\n/// completed stages run, last first.\npub fn run_workflow(ctx: &mut Context, mut attempt: impl FnMut(&mut Context) -> Result<Value>) -> Result<Value> {\n    let runtime = workflow_runtime(ctx);\n    runtime.lock().unwrap().frames.push(Vec::new());\n    let result = attempt(ctx);\n    let frame = runtime.lock().unwrap().frames.pop().unwrap_or_default();\n    let result = result?;\n    if matches!(result, Value::Left(_)) {\n        for (stage, value, undo) in frame.into_iter().rev() {\n            runtime.lock().unwrap().trace.push(TraceEvent { kind: \"compensate\", stage: stage.into(), number: 0, succeeded: true });\n            undo(ctx, value)?;\n        }\n    }\n    Ok(result)\n}\n\nconst STAGE_FAILURE: &str = \"lawspec.resilience::type::StageFailure::\";\nconst GATE: &str = \"lawspec.resilience::type::Gate::\";\n\nfn stage_failure(kind: &str) -> Value {\n    Value::Left(Box::new(Value::Data(format!(\"{STAGE_FAILURE}{kind}\"), vec![])))\n}\n\nfn gate_key(policy: &StagePolicy, gate: &Gate) -> String {\n    format!(\"{}/{}\", if policy.key.is_empty() { policy.stage } else { policy.key }, gate.kind)\n}\n\n/// Admits the call (None) or gives the failure to return instead.\nfn pass_gate(ctx: &mut Context, runtime: &Arc<std::sync::Mutex<WorkflowRuntime>>, policy: &StagePolicy, gate: &Gate) -> Result<Option<&'static str>> {\n    let key = gate_key(policy, gate);\n    let failure = match gate.kind { \"breaker\" => \"CircuitOpen\", \"limit\" => \"RateLimited\", _ => \"Saturated\" };\n    let mut waited = 0i64;\n    loop {\n        let (now, state) = {\n            let guard = runtime.lock().unwrap();\n            (guard.clock.now(), guard.state.get(&key).cloned())\n        };\n        let state = match state { Some(state) => state, None => (gate.start)(ctx, now)? };\n        let Value::Data(_, mut step) = (gate.admit)(ctx, state, now)? else { return Err(\"expected a Step\".into()) };\n        let decision = step.pop().unwrap();\n        runtime.lock().unwrap().state.insert(key.clone(), step.pop().unwrap());\n        let Value::Data(tag, fields) = decision else { return Err(\"expected a Gate\".into()) };\n        if tag == format!(\"{GATE}Admit\") {\n            return Ok(None);\n        }\n        if tag == format!(\"{GATE}Reject\") || gate.wait == -2 {\n            return Ok(Some(failure));\n        }\n        let delay = match fields.first() {\n            Some(Value::Integer(n)) => n.to_i64().ok_or(\"wait outside i64\")?,\n            _ => return Err(\"expected a wait\".into()),\n        };\n        if gate.wait >= 0 && waited + delay > gate.wait {\n            return Ok(Some(failure));\n        }\n        let mut guard = runtime.lock().unwrap();\n        guard.trace.push(TraceEvent { kind: \"wait\", stage: policy.stage.into(), number: delay, succeeded: true });\n        guard.clock.sleep(delay);\n        waited += delay;\n    }\n}\n\nfn finish_gate(ctx: &mut Context, runtime: &Arc<std::sync::Mutex<WorkflowRuntime>>, policy: &StagePolicy, gate: &Gate, succeeded: bool) -> Result<()> {\n    if let Some(finish) = gate.finish {\n        let key = gate_key(policy, gate);\n        let (now, state) = {\n            let guard = runtime.lock().unwrap();\n            (guard.clock.now(), guard.state.get(&key).cloned().ok_or(\"missing gate state\")?)\n        };\n        let next = finish(ctx, state, now, succeeded)?;\n        runtime.lock().unwrap().state.insert(key, next);\n    }\n    Ok(())\n}\n\nfn fibonacci(n: i64) -> i64 {\n    let (mut a, mut b) = (1i64, 1i64);\n    for _ in 1..n {\n        let next = a + b;\n        a = b;\n        b = next;\n    }\n    a\n}\n\n/// The delay before attempt (2 or more), before jitter.\npub fn retry_delay(retry: &Retry, attempt: i64) -> i64 {\n    let n = attempt - 1;\n    match retry.strategy {\n        \"immediate\" => 0,\n        \"fixed\" => retry.delay,\n        \"linear\" => retry.delay + retry.step * (n - 1),\n        \"exponential\" => {\n            let mut delay = retry.delay;\n            for _ in 1..n {\n                delay *= retry.factor;\n                if retry.cap >= 0 && delay >= retry.cap {\n                    return retry.cap;\n                }\n            }\n            if retry.cap >= 0 && delay > retry.cap { retry.cap } else { delay }\n        }\n        \"fibonacci\" => retry.delay * fibonacci(n),\n        other => panic!(\"unknown retry strategy: {other}\"),\n    }\n}\n\n/// Full: [0, delay]; equal: delay/2 + [0, delay/2]; decorrelated:\n/// [base, previous * 3], capped at delay.\npub fn jittered(jitter: &str, delay: i64, previous: i64, base: i64, random: &mut SplitMix64) -> i64 {\n    match jitter {\n        \"full\" => random.below((delay + 1) as u64) as i64,\n        \"equal\" => {\n            let half = delay / 2;\n            half + random.below((delay - half + 1) as u64) as i64\n        }\n        \"decorrelated\" => {\n            let high = base.max(previous * 3);\n            delay.min(base + random.below((high - base + 1) as u64) as i64)\n        }\n        _ => delay,\n    }\n}\n\n/// Runs a stage's attempts under its policy; a Left is a failure. key is the\n/// stage's input, for the cache.\npub fn run_stage(\n    ctx: &mut Context,\n    policy: &StagePolicy,\n    attempt: impl FnMut(&mut Context) -> Result<Value>,\n    key: Value,\n) -> Result<Value> {\n    let runtime = workflow_runtime(ctx);\n    let gating = runtime.lock().unwrap().gates;\n    let cache_key = format!(\"{}/cache\", if policy.key.is_empty() { policy.stage } else { policy.key });\n    let caching = policy.cache > 0 && gating;\n    if caching {\n        let mut guard = runtime.lock().unwrap();\n        let now = guard.clock.now();\n        let hit = guard.cache.get(&cache_key).and_then(|entries| {\n            entries.iter().find(|(entry, _, expires)| now < *expires && equal(entry, &key).unwrap_or(false)).map(|(_, value, _)| value.clone())\n        });\n        if let Some(value) = hit {\n            guard.trace.push(TraceEvent { kind: \"cached\", stage: policy.stage.into(), number: 0, succeeded: true });\n            return Ok(value);\n        }\n    }\n    let gates: &[Gate] = if gating { &policy.gates } else { &[] };\n    for (i, gate) in gates.iter().enumerate() {\n        if let Some(failure) = pass_gate(ctx, &runtime, policy, gate)? {\n            for passed in &gates[..i] {\n                finish_gate(ctx, &runtime, policy, passed, false)?;\n            }\n            return Ok(stage_failure(failure));\n        }\n    }\n    let result = attempts(ctx, &runtime, policy, attempt)?;\n    let succeeded = !matches!(result, Value::Left(_));\n    for gate in gates {\n        finish_gate(ctx, &runtime, policy, gate, succeeded)?;\n    }\n    if let (Value::Right(value), Some(undo)) = (&result, policy.compensate) {\n        if let Some(frame) = runtime.lock().unwrap().frames.last_mut() {\n            frame.push((policy.stage, (**value).clone(), undo));\n        }\n    }\n    if caching && succeeded {\n        let mut guard = runtime.lock().unwrap();\n        let expires = guard.clock.now() + policy.cache;\n        let entries = guard.cache.entry(cache_key).or_default();\n        entries.retain(|(entry, _, _)| !equal(entry, &key).unwrap_or(false));\n        entries.push((key, result.clone(), expires));\n    }\n    Ok(result)\n}\n\n// The error block_on_within gives when an attempt outlives its stage's\n// timeout; the stage turns it into TimedOut.\nconst TIMED_OUT: &str = \"\\0lawspec: timed out\";\n\n/// The Async ability's default handler: native threads. LawSpec code\n/// performs pause; workflows reach the rest natively: spawn starts a function\n/// as a task (a thread), wait gives a task's result, wait_future runs a\n/// future to completion on this thread, and all runs functions side by side\n/// and gives their results in order. An `async` adapter is an adapter that\n/// uses Async, so its future is awaited with wait_future.\n/// (lawspec.concurrent's default AsyncHandler delegates to it.)\n#[derive(Clone, Copy, Debug, Default)]\npub struct NativeAsync;\n\n/// The runtime's NativeAsync.\npub static ASYNC: NativeAsync = NativeAsync;\n\nimpl NativeAsync {\n    /// Lets other threads run.\n    pub fn pause(&self) {\n        std::thread::yield_now();\n    }\n\n    /// Starts body as a task of its own.\n    pub fn spawn<T: Send + 'static>(&self, body: impl FnOnce() -> T + Send + 'static) -> std::thread::JoinHandle<T> {\n        std::thread::spawn(body)\n    }\n\n    /// The task's result; a panic in it is resumed here.\n    pub fn wait<T>(&self, task: std::thread::JoinHandle<T>) -> T {\n        task.join().unwrap_or_else(|panic| std::panic::resume_unwind(panic))\n    }\n\n    /// A future's output, polled on this thread (see block_on).\n    pub fn wait_future<F: std::future::Future>(&self, future: F) -> F::Output {\n        block_on(future)\n    }\n\n    /// Every function's result, in order: they run side by side, each on a\n    /// scoped thread, and all finish before the first panic (in order) is\n    /// resumed.\n    pub fn all<'a, T: Send + 'a>(&self, bodies: Vec<Box<dyn FnOnce() -> T + Send + 'a>>) -> Vec<T> {\n        let results: Vec<std::thread::Result<T>> = std::thread::scope(|scope| {\n            let tasks: Vec<_> = bodies.into_iter().map(|body| scope.spawn(body)).collect();\n            tasks.into_iter().map(|task| task.join()).collect()\n        });\n        results.into_iter().map(|result| result.unwrap_or_else(|panic| std::panic::resume_unwind(panic))).collect()\n    }\n}\n\n/// An all group's step results, in declaration order, as the runtime's\n/// NativeAsync runs them: every step finishes before the first failure (or\n/// panic), in declaration order, is the group's.\npub fn concurrently<'a>(steps: Vec<Box<dyn FnOnce() -> Result<Value> + Send + 'a>>) -> Result<Vec<Value>> {\n    ASYNC.all(steps).into_iter().collect()\n}\n\n/// An all group's step results, joined from their scoped threads, in\n/// declaration order. Every step has finished; the first failure (or panic),\n/// in declaration order, is the group's.\npub fn joined(results: Vec<std::thread::Result<Result<Value>>>) -> Result<Vec<Value>> {\n    let mut values = Vec::with_capacity(results.len());\n    for result in results {\n        match result {\n            Ok(value) => values.push(value?),\n            Err(panic) => std::panic::resume_unwind(panic),\n        }\n    }\n    Ok(values)\n}\n\n/// An async step's logical result: start begins the step and convert turns\n/// its native result into a logical value. The step runs within its stage's\n/// timeout and hedge, if any, polling its attempts on this thread.\npub fn await_step<F: std::future::Future>(\n    ctx: &Context,\n    mut start: impl FnMut() -> F,\n    convert: impl Fn(F::Output) -> Value,\n) -> Result<Value> {\n    let runtime = workflow_runtime(ctx);\n    let (deadline, hedge, virtual_hedge) = {\n        let guard = runtime.lock().unwrap();\n        (guard.deadline, guard.hedge, guard.virtual_hedge)\n    };\n    if let Some((stage, (_, most))) = virtual_hedge {\n        return Ok(virtually_hedged(&runtime, stage, most, start, convert));\n    }\n    if deadline.is_none() && hedge.is_none() {\n        return Ok(convert(ASYNC.wait_future(start())));\n    }\n    let (stage, delay, most) = match hedge {\n        Some((stage, (delay, most))) => (stage, std::time::Duration::from_micros(delay as u64), most),\n        None => (\"\", std::time::Duration::ZERO, 1),\n    };\n    struct Unpark(std::thread::Thread);\n    impl std::task::Wake for Unpark {\n        fn wake(self: Arc<Self>) {\n            self.0.unpark();\n        }\n    }\n    let waker = std::task::Waker::from(Arc::new(Unpark(std::thread::current())));\n    let mut context = std::task::Context::from_waker(&waker);\n    let mut pending: Vec<std::pin::Pin<Box<F>>> = Vec::new();\n    let (mut started, mut next, mut launch) = (0i64, None, true);\n    loop {\n        if launch {\n            started += 1;\n            if started > 1 {\n                runtime.lock().unwrap().trace.push(TraceEvent { kind: \"hedge\", stage: stage.into(), number: started, succeeded: true });\n            }\n            pending.push(Box::pin(start()));\n            next = if started < most { Some(std::time::Instant::now() + delay) } else { None };\n            launch = false;\n        }\n        let mut last = None;\n        let mut i = 0;\n        while i < pending.len() {\n            match pending[i].as_mut().poll(&mut context) {\n                std::task::Poll::Ready(output) => {\n                    pending.remove(i);\n                    let value = convert(output);\n                    if !matches!(value, Value::Left(_)) {\n                        return Ok(value);\n                    }\n                    last = Some(value);\n                }\n                std::task::Poll::Pending => i += 1,\n            }\n        }\n        let now = std::time::Instant::now();\n        if deadline.is_some_and(|deadline| now >= deadline) {\n            return Err(TIMED_OUT.into());\n        }\n        if pending.is_empty() {\n            if started >= most {\n                return Ok(last.expect(\"the last attempt failed\"));\n            }\n            launch = true;\n        } else if next.is_some_and(|next| now >= next) {\n            launch = true;\n        } else {\n            match [deadline, next].into_iter().flatten().min() {\n                Some(until) => std::thread::park_timeout(until - now),\n                None => std::thread::park(),\n            }\n        }\n    }\n}\n\n/// A hedge on a virtual clock: attempts run one after another, and the next\n/// starts when one fails, so the first success wins as it would in real time\n/// when no attempt outlives the delay.\nfn virtually_hedged<F: std::future::Future>(\n    runtime: &Arc<std::sync::Mutex<WorkflowRuntime>>,\n    stage: &'static str,\n    most: i64,\n    mut start: impl FnMut() -> F,\n    convert: impl Fn(F::Output) -> Value,\n) -> Value {\n    let mut started = 1i64;\n    let mut value = convert(ASYNC.wait_future(start()));\n    while matches!(value, Value::Left(_)) && started < most {\n        started += 1;\n        runtime.lock().unwrap().trace.push(TraceEvent { kind: \"hedge\", stage: stage.into(), number: started, succeeded: true });\n        value = convert(ASYNC.wait_future(start()));\n    }\n    value\n}\n\n/// An attempt under its stage's timeout (failing with TimedOut when it\n/// outlives it) and hedge: the Timeout and Hedge transformers of the Async\n/// ability, measured on the runtime's Clock. On a virtual clock (generated\n/// tests, or a law using virtual clock) an attempt takes the virtual time\n/// that passes while it runs, so both are deterministic. On a real clock\n/// with gates off, both are off.\nfn scoped(\n    ctx: &mut Context,\n    runtime: &Arc<std::sync::Mutex<WorkflowRuntime>>,\n    policy: &StagePolicy,\n    attempt: &mut impl FnMut(&mut Context) -> Result<Value>,\n) -> Result<Value> {\n    if policy.timeout <= 0 && policy.hedge.is_none() {\n        return attempt(ctx);\n    }\n    let (is_virtual, gates) = {\n        let guard = runtime.lock().unwrap();\n        (guard.clock.is_virtual(), guard.gates)\n    };\n    if is_virtual {\n        return virtually_scoped(ctx, runtime, policy, attempt);\n    }\n    if !gates {\n        return attempt(ctx);\n    }\n    let outer = {\n        let mut guard = runtime.lock().unwrap();\n        let outer = (guard.deadline, guard.hedge, guard.virtual_hedge);\n        if policy.timeout > 0 {\n            guard.deadline = Some(std::time::Instant::now() + std::time::Duration::from_micros(policy.timeout as u64));\n        }\n        guard.hedge = policy.hedge.map(|hedge| (policy.stage, hedge));\n        guard.virtual_hedge = None;\n        outer\n    };\n    let result = attempt(ctx);\n    {\n        let mut guard = runtime.lock().unwrap();\n        (guard.deadline, guard.hedge, guard.virtual_hedge) = outer;\n    }\n    match result {\n        // Callers may have added context to the marker.\n        Err(error) if error.contains(TIMED_OUT) => Ok(stage_failure(\"TimedOut\")),\n        other => other,\n    }\n}\n\nfn virtually_scoped(\n    ctx: &mut Context,\n    runtime: &Arc<std::sync::Mutex<WorkflowRuntime>>,\n    policy: &StagePolicy,\n    attempt: &mut impl FnMut(&mut Context) -> Result<Value>,\n) -> Result<Value> {\n    let (outer, began) = {\n        let mut guard = runtime.lock().unwrap();\n        let outer = (guard.deadline, guard.hedge, guard.virtual_hedge);\n        let began = guard.clock.now();\n        guard.deadline = None;\n        guard.hedge = None;\n        guard.virtual_hedge = policy.hedge.map(|hedge| (policy.stage, hedge));\n        (outer, began)\n    };\n    let result = attempt(ctx);\n    let ended = {\n        let mut guard = runtime.lock().unwrap();\n        (guard.deadline, guard.hedge, guard.virtual_hedge) = outer;\n        guard.clock.now()\n    };\n    match result {\n        Err(error) if error.contains(TIMED_OUT) => Ok(stage_failure(\"TimedOut\")),\n        Ok(_) if policy.timeout > 0 && ended - began > policy.timeout => Ok(stage_failure(\"TimedOut\")),\n        other => other,\n    }\n}\n\nfn attempts(\n    ctx: &mut Context,\n    runtime: &Arc<std::sync::Mutex<WorkflowRuntime>>,\n    policy: &StagePolicy,\n    mut attempt: impl FnMut(&mut Context) -> Result<Value>,\n) -> Result<Value> {\n    let event = |kind: &'static str, number: i64, succeeded: bool| TraceEvent { kind, stage: policy.stage.into(), number, succeeded };\n    let (mut number, mut previous) = (1i64, 0i64);\n    loop {\n        runtime.lock().unwrap().trace.push(event(\"start\", number, false));\n        let result = scoped(ctx, runtime, policy, &mut attempt)?;\n        let failure = match &result {\n            Value::Left(error) => Some((**error).clone()),\n            _ => None,\n        };\n        runtime.lock().unwrap().trace.push(event(\"finish\", number, failure.is_none()));\n        let (Some(mut failure), Some(retry)) = (failure, &policy.retry) else { return Ok(result) };\n        if retry.attempts > 0 && number >= retry.attempts {\n            return Ok(result);\n        }\n        if policy.wraps {\n            // Only the step's own failures and timeouts are retried.\n            match failure {\n                Value::Data(ref tag, ref mut fields) if *tag == format!(\"{STAGE_FAILURE}StepFailed\") && fields.len() == 1 => {\n                    failure = fields.pop().unwrap();\n                }\n                Value::Data(ref tag, _) if *tag == format!(\"{STAGE_FAILURE}TimedOut\") => {}\n                _ => return Ok(result),\n            }\n        }\n        if let Some(when) = retry.when {\n            if !when(ctx, failure.clone())? {\n                return Ok(result);\n            }\n        }\n        number += 1;\n        let delay = if retry.strategy == \"custom\" {\n            match (retry.decide.expect(\"a custom strategy decides\"))(ctx, number, failure, previous)? {\n                Some(delay) => delay,\n                None => return Ok(result),\n            }\n        } else {\n            let base = if retry.strategy == \"immediate\" { 0 } else { retry_delay(retry, 2) };\n            let mut guard = runtime.lock().unwrap();\n            jittered(retry.jitter, retry_delay(retry, number), previous, base, &mut guard.random)\n        };\n        let mut guard = runtime.lock().unwrap();\n        guard.trace.push(event(\"sleep\", delay, true));\n        guard.clock.sleep(delay);\n        previous = delay;\n    }\n}\n\n/// A logical Duration of whole microseconds.\npub fn duration(micros: i64) -> Value {\n    Value::Data(DURATION_TAG.into(), vec![Value::Integer(BigInt::from(micros))])\n}\n\n/// A RetryDecision's delay, or None to stop.\npub fn retry_decision(decision: Value) -> Result<Option<i64>> {\n    match decision {\n        Value::Data(tag, mut fields) if tag == \"lawspec.time::type::RetryDecision::RetryAfter\" && fields.len() == 1 => {\n            match fields.pop().unwrap() {\n                Value::Data(_, mut micros) if micros.len() == 1 => match micros.pop().unwrap() {\n                    Value::Integer(n) => n.to_i64().map(Some).ok_or_else(|| \"delay outside i64\".into()),\n                    _ => Err(\"expected Duration microseconds\".into()),\n                },\n                _ => Err(\"expected a Duration\".into()),\n            }\n        }\n        Value::Data(..) => Ok(None),\n        _ => Err(\"expected a RetryDecision\".into()),\n    }\n}\n\n/// A Duration, whole microseconds from 0 to about 146 years, is natively a\n/// std::time::Duration. One with a fraction of a microsecond is not a\n/// Duration; IntoValue cannot fail, so converting one panics.\npub const DURATION_TAG: &str = \"lawspec.time::type::Duration::Duration\";\n\nimpl IntoValue for std::time::Duration {\n    fn into_value(self) -> Value {\n        assert!(\n            self.subsec_nanos() % 1000 == 0,\n            \"a Duration is a non-negative whole number of microseconds\"\n        );\n        Value::Data(DURATION_TAG.into(), vec![Value::Integer(BigInt::from(self.as_micros()))])\n    }\n}\nimpl FromValue for std::time::Duration {\n    fn from_value(value: Value) -> Result<Self> {\n        match value {\n            Value::Data(tag, fields) if tag == DURATION_TAG && fields.len() == 1 => match &fields[0] {\n                Value::Integer(micros) => u64::try_from(micros)\n                    .map(std::time::Duration::from_micros)\n                    .map_err(|_| \"Duration outside the native range\".into()),\n                _ => Err(\"expected Duration microseconds\".into()),\n            },\n            _ => Err(\"expected Duration\".into()),\n        }\n    }\n}\n\n/// Built-in collections: natively a BTreeSet, a BTreeMap, a VecDeque (Queue\n/// and Deque) or a Vec whose top is last (Stack). Natives convert to plain\n/// lists; the schema retags them by the expected type.\npub const COLLECTIONS: &str = \"lawspec.collections::type::\";\n\npub fn collection_tag(name: &str) -> Option<&'static str> {\n    Some(match name.strip_prefix(COLLECTIONS)? {\n        \"Set\" => \"lawspec.collections::type::Set::SetItems\",\n        \"KeyVal\" => \"lawspec.collections::type::KeyVal::KeyValEntries\",\n        \"Queue\" => \"lawspec.collections::type::Queue::QueueItems\",\n        \"Stack\" => \"lawspec.collections::type::Stack::StackItems\",\n        \"Deque\" => \"lawspec.collections::type::Deque::DequeItems\",\n        _ => return None,\n    })\n}\n\nfn collection_items(value: Value) -> Result<Vec<Value>> {\n    match value {\n        Value::List(items) => Ok(items),\n        Value::Data(tag, mut fields) if tag.starts_with(COLLECTIONS) && fields.len() == 1 => {\n            let reverse = tag.ends_with(\"::StackItems\");\n            match fields.pop().unwrap() {\n                Value::List(mut items) => {\n                    if reverse {\n                        items.reverse();\n                    }\n                    Ok(items)\n                }\n                _ => Err(\"expected collection items\".into()),\n            }\n        }\n        _ => Err(\"expected a collection\".into()),\n    }\n}\n\nimpl<T: IntoValue> IntoValue for std::collections::BTreeSet<T> {\n    fn into_value(self) -> Value {\n        Value::List(self.into_iter().map(IntoValue::into_value).collect())\n    }\n}\nimpl<T: FromValue + Ord> FromValue for std::collections::BTreeSet<T> {\n    fn from_value(value: Value) -> Result<Self> {\n        collection_items(value)?.into_iter().map(T::from_value).collect()\n    }\n}\nimpl<K: IntoValue, V: IntoValue> IntoValue for std::collections::BTreeMap<K, V> {\n    fn into_value(self) -> Value {\n        Value::List(\n            self.into_iter()\n                .map(|(k, v)| Value::Data(\"lawspec.collections::type::Entry::Entry\".into(), vec![k.into_value(), v.into_value()]))\n                .collect(),\n        )\n    }\n}\nimpl<K: FromValue + Ord, V: FromValue> FromValue for std::collections::BTreeMap<K, V> {\n    fn from_value(value: Value) -> Result<Self> {\n        collection_items(value)?\n            .into_iter()\n            .map(|entry| match entry {\n                Value::Data(_, fields) if fields.len() == 2 => {\n                    let mut fields = fields.into_iter();\n                    Ok((K::from_value(fields.next().unwrap())?, V::from_value(fields.next().unwrap())?))\n                }\n                _ => Err(\"expected a KeyVal entry\".into()),\n            })\n            .collect()\n    }\n}\nimpl<T: IntoValue> IntoValue for std::collections::VecDeque<T> {\n    fn into_value(self) -> Value {\n        Value::List(self.into_iter().map(IntoValue::into_value).collect())\n    }\n}\nimpl<T: FromValue> FromValue for std::collections::VecDeque<T> {\n    fn from_value(value: Value) -> Result<Self> {\n        collection_items(value)?.into_iter().map(T::from_value).collect()\n    }\n}\n\npub fn helper(name: &str, mut args: Vec<Value>) -> Result<Value> {\n    use Value::*;\n    if let Some(value) = matcher_helper(name, &args)? {\n        return Ok(value);\n    }\n    if name == \"select\" && args.len() == 3 {\n        let other = args.pop().unwrap();\n        let chosen = args.pop().unwrap();\n        return Ok(if matches!(args[0], Bool(true)) { chosen } else { other });\n    }\n    if name == \"compare\" && args.len() == 2 {\n        let tag = match compare_values(&args[0], &args[1])? {\n            std::cmp::Ordering::Less => \"Less\",\n            std::cmp::Ordering::Equal => \"Equal\",\n            std::cmp::Ordering::Greater => \"Greater\",\n        };\n        return Ok(Data(format!(\"lawspec.collections::type::Ordering::{tag}\"), vec![]));\n    }\n    if name == \"round\" && args.len() == 2 {\n        let scale = i32::from_value(args.pop().unwrap())?;\n        return Ok(Decimal(self::Decimal::round(args[0].exact()?, scale)?));\n    }\n    if args.len() != 1 {\n        return Err(format!(\"invalid {name} arguments\"));\n    }\n    let value = args.pop().unwrap();\n    Ok(match name {\n        \"checked\" => Bool(true),\n        \"length\" => Integer(BigInt::from(match value {\n            Text(s) => s.chars().count(),\n            CodePointText(s) => s.len(),\n            Utf16Text(s) => s.len(),\n            Bytes(s) => s.len(),\n            List(s) => s.len(),\n            _ => return Err(\"length requires sequence\".into()),\n        })),\n        \"isPresent\" => Bool(match value {\n            Nullable(v) | Optional(v) => v.is_some(),\n            _ => return Err(\"expected presence\".into()),\n        }),\n        \"presentValue\" => match value {\n            Nullable(Some(v)) | Optional(Some(v)) => *v,\n            _ => return Err(\"absent value has no payload\".into()),\n        },\n        \"real\" => match value {\n            Complex32(c) => Float32(c.re),\n            Complex64(c) => Float64(c.re),\n            _ => return Err(\"expected complex value\".into()),\n        },\n        \"imag\" => match value {\n            Complex32(c) => Float32(c.im),\n            Complex64(c) => Float64(c.im),\n            _ => return Err(\"expected complex value\".into()),\n        },\n        \"isNaN\" => Bool(value.real64()?.is_nan()),\n        \"isInfinite\" => Bool(value.real64()?.is_infinite()),\n        \"isFinite\" => Bool(value.real64()?.is_finite()),\n        \"isNegativeZero\" => {\n            let x = value.real64()?;\n            Bool(x == 0.0 && x.is_sign_negative())\n        }\n        _ => return Err(format!(\"unknown helper: {name}\")),\n    })\n}\n\n/// Where a structured actual value first differs from the expected one, by\n/// the portable rendering: \"\" when they agree or neither has parts.\npub fn difference(actual: &Value, expected: &Value) -> String {\n    fn parts(v: &Value) -> Option<(Option<String>, Vec<&Value>)> {\n        match v {\n            Value::List(xs) => Some((None, xs.iter().collect())),\n            Value::Data(tag, fields) => Some((Some(tag.clone()), fields.iter().collect())),\n            Value::Maybe(Some(x)) => Some((Some(\"Just\".into()), vec![x.as_ref()])),\n            Value::Left(x) => Some((Some(\"Left\".into()), vec![x.as_ref()])),\n            Value::Right(x) => Some((Some(\"Right\".into()), vec![x.as_ref()])),\n            _ => None,\n        }\n    }\n    let mut path = vec![];\n    let (mut a, mut b) = (actual, expected);\n    let mut lengths = None;\n    while let (Some((ta, xs)), Some((tb, ys))) = (parts(a), parts(b)) {\n        if ta != tb || (ta.is_some() && xs.len() != ys.len()) {\n            break;\n        }\n        match xs.iter().zip(ys.iter()).position(|(x, y)| render(x) != render(y)) {\n            Some(i) => {\n                path.push(match &ta {\n                    None => format!(\"item {}\", i + 1),\n                    Some(tag) => format!(\"field {} of {}\", i + 1, tag.rsplit(\"::\").next().unwrap_or(tag)),\n                });\n                (a, b) = (xs[i], ys[i]);\n            }\n            None if xs.len() == ys.len() => return String::new(),\n            None => {\n                path.push(\"length\".to_string());\n                lengths = Some((xs.len(), ys.len()));\n                break;\n            }\n        }\n    }\n    if path.is_empty() {\n        return String::new();\n    }\n    let (shown_a, shown_b) = match lengths {\n        Some((x, y)) => (x.to_string(), y.to_string()),\n        None => (render(a), render(b)),\n    };\n    format!(\" | first difference at {}: expected {shown_b}, actual {shown_a}\", path.join(\", \"))\n}\n\n/// The matcher, recording and resource helpers, or None for another helper.\nfn matcher_helper(name: &str, args: &[Value]) -> Result<Option<Value>> {\n    let text = |i: usize| -> Result<&str> {\n        match args.get(i) {\n            Some(Value::Text(s)) => Ok(s.as_str()),\n            _ => Err(format!(\"{name} expects text\")),\n        }\n    };\n    Ok(Some(match name {\n        \"startsWith\" => Value::Bool(text(0)?.starts_with(text(1)?)),\n        \"endsWith\" => Value::Bool(text(0)?.ends_with(text(1)?)),\n        \"textContains\" => Value::Bool(text(0)?.contains(text(1)?)),\n        \"regexMatches\" => Value::Bool(regex_matches(text(0)?, text(1)?)?),\n        \"recorded\" => Value::Bool(recorded(text(0)?, args.get(1).ok_or(\"recorded expects a value\")?)?),\n        \"acquireResource\" => Value::Text(acquire_resource(text(0)?)?),\n        \"releaseResource\" => {\n            release_resource(text(0)?, text(1)?)?;\n            Value::Bool(true)\n        }\n        \"freePort\" => Value::Integer(BigInt::from(free_port()?)),\n        _ => return Ok(None),\n    }))\n}\n\n// Portable regular expressions (see LawSpec.Regex): the subset of RE2 and\n// ECMAScript that means the same in both, matched against a whole text, code\n// point by code point. The compiler has checked every pattern; a pattern\n// that is not portable is an error here too.\n#[derive(Clone, Debug)]\nstruct RegexItem {\n    negated: bool,\n    ranges: Vec<(u32, u32)>,\n}\n\n#[derive(Clone, Debug)]\nenum RegexNode {\n    Set(bool, Vec<RegexItem>),\n    Sequence(Vec<RegexNode>),\n    Alternatives(Vec<RegexNode>),\n    Repeat(Box<RegexNode>, usize, Option<usize>),\n}\n\nconst REGEX_DIGITS: &[(u32, u32)] = &[(48, 57)];\nconst REGEX_WORD: &[(u32, u32)] = &[(48, 57), (65, 90), (95, 95), (97, 122)];\nconst REGEX_SPACE: &[(u32, u32)] = &[(9, 13), (32, 32)];\n\nstruct RegexParser<'a> {\n    pattern: &'a str,\n    cs: Vec<u32>,\n    pos: usize,\n}\n\nimpl RegexParser<'_> {\n    fn peek(&self) -> Option<u32> {\n        self.cs.get(self.pos).copied()\n    }\n\n    fn fail<T>(&self, message: &str) -> Result<T> {\n        Err(format!(\"regex {:?} is not portable: {message}\", self.pattern))\n    }\n\n    fn escape(&mut self) -> Result<RegexItem> {\n        self.pos += 1;\n        let Some(c) = self.peek() else { return self.fail(\"the regex ends with a lone \\\\\") };\n        self.pos += 1;\n        let item = |negated: bool, ranges: &[(u32, u32)]| RegexItem { negated, ranges: ranges.to_vec() };\n        Ok(match char::from_u32(c).unwrap_or('\\0') {\n            'd' => item(false, REGEX_DIGITS),\n            'D' => item(true, REGEX_DIGITS),\n            'w' => item(false, REGEX_WORD),\n            'W' => item(true, REGEX_WORD),\n            's' => item(false, REGEX_SPACE),\n            'S' => item(true, REGEX_SPACE),\n            'n' => item(false, &[(10, 10)]),\n            't' => item(false, &[(9, 9)]),\n            'r' => item(false, &[(13, 13)]),\n            'f' => item(false, &[(12, 12)]),\n            'v' => item(false, &[(11, 11)]),\n            ch if \"\\\\.^$|?*+()[]{}-/\".contains(ch) => item(false, &[(c, c)]),\n            ch => return self.fail(&format!(\"\\\\{ch} is not a portable escape\")),\n        })\n    }\n\n    fn literal(&mut self) -> Result<RegexItem> {\n        let c = self.peek().unwrap_or(0);\n        if c == '[' as u32 {\n            return self.fail(\"write \\\\[ for the character inside a class\");\n        }\n        self.pos += 1;\n        Ok(RegexItem { negated: false, ranges: vec![(c, c)] })\n    }\n\n    fn single(item: &RegexItem) -> bool {\n        !item.negated && item.ranges.len() == 1 && item.ranges[0].0 == item.ranges[0].1\n    }\n\n    fn class(&mut self) -> Result<RegexNode> {\n        self.pos += 1;\n        let negated = self.peek() == Some('^' as u32);\n        if negated {\n            self.pos += 1;\n        }\n        let mut items = vec![];\n        let mut first = true;\n        loop {\n            let Some(c) = self.peek() else { return self.fail(\"a [ is never closed\") };\n            if c == ']' as u32 {\n                if first {\n                    return self.fail(\"an empty class is not portable\");\n                }\n                self.pos += 1;\n                return Ok(RegexNode::Set(negated, items));\n            }\n            first = false;\n            let item = if c == '\\\\' as u32 { self.escape()? } else { self.literal()? };\n            if Self::single(&item)\n                && self.peek() == Some('-' as u32)\n                && self.cs.get(self.pos + 1).is_some_and(|&next| next != ']' as u32)\n            {\n                self.pos += 1;\n                let high = if self.peek() == Some('\\\\' as u32) { self.escape()? } else { self.literal()? };\n                if !Self::single(&high) {\n                    return self.fail(\"a range ends with one character\");\n                }\n                if high.ranges[0].0 < item.ranges[0].0 {\n                    return self.fail(\"a range must run from low to high\");\n                }\n                items.push(RegexItem { negated: false, ranges: vec![(item.ranges[0].0, high.ranges[0].0)] });\n            } else {\n                items.push(item);\n            }\n        }\n    }\n\n    fn digits(&mut self) -> String {\n        let start = self.pos;\n        while self.peek().is_some_and(|c| ('0' as u32..='9' as u32).contains(&c)) {\n            self.pos += 1;\n        }\n        self.cs[start..self.pos].iter().filter_map(|&c| char::from_u32(c)).collect()\n    }\n\n    fn atom(&mut self) -> Result<RegexNode> {\n        let c = self.peek().unwrap_or(0);\n        let ch = char::from_u32(c).unwrap_or('\\0');\n        match ch {\n            '(' => {\n                self.pos += 1;\n                if self.peek() == Some('?' as u32) {\n                    if self.cs.get(self.pos + 1) == Some(&(':' as u32)) {\n                        self.pos += 2;\n                    } else {\n                        return self.fail(\"only (?: ...) groups are portable\");\n                    }\n                }\n                let node = self.alternatives()?;\n                if self.peek() != Some(')' as u32) {\n                    return self.fail(\"a ( is never closed\");\n                }\n                self.pos += 1;\n                Ok(node)\n            }\n            '[' => self.class(),\n            '.' => {\n                self.pos += 1;\n                Ok(RegexNode::Set(true, vec![RegexItem { negated: false, ranges: vec![(10, 10)] }]))\n            }\n            '\\\\' => Ok(RegexNode::Set(false, vec![self.escape()?])),\n            _ if \"*+?{^$]}\".contains(ch) => self.fail(&format!(\"unexpected {ch}\")),\n            _ => {\n                self.pos += 1;\n                Ok(RegexNode::Set(false, vec![RegexItem { negated: false, ranges: vec![(c, c)] }]))\n            }\n        }\n    }\n\n    fn quantifier(c: Option<u32>) -> bool {\n        c.and_then(char::from_u32).is_some_and(|ch| \"*+?{\".contains(ch))\n    }\n\n    fn quantified(&mut self, node: RegexNode) -> Result<RegexNode> {\n        let c = self.peek();\n        if !Self::quantifier(c) {\n            return Ok(node);\n        }\n        self.pos += 1;\n        let repeat = |low, high| RegexNode::Repeat(Box::new(node.clone()), low, high);\n        let result = match char::from_u32(c.unwrap_or(0)).unwrap_or('\\0') {\n            '*' => repeat(0, None),\n            '+' => repeat(1, None),\n            '?' => repeat(0, Some(1)),\n            _ => {\n                let low_text = self.digits();\n                let high_text;\n                if self.peek() == Some('}' as u32) {\n                    high_text = Some(low_text.clone());\n                } else if self.peek() == Some(',' as u32) {\n                    self.pos += 1;\n                    let text = self.digits();\n                    high_text = if text.is_empty() { None } else { Some(text) };\n                    if self.peek() != Some('}' as u32) {\n                        return self.fail(\"a repetition is {n}, {n,} or {n,m}\");\n                    }\n                } else {\n                    return self.fail(\"a repetition is {n}, {n,} or {n,m}\");\n                }\n                self.pos += 1;\n                if low_text.is_empty() {\n                    return self.fail(\"a repetition is {n}, {n,} or {n,m}\");\n                }\n                let low: usize = low_text.parse().unwrap_or(usize::MAX);\n                let high: Option<usize> = high_text.map(|t| t.parse().unwrap_or(usize::MAX));\n                if low > 1000 || high.is_some_and(|h| h > 1000 || h < low) {\n                    return self.fail(\"a repetition count is at most 1000, and n must not exceed m\");\n                }\n                repeat(low, high)\n            }\n        };\n        if Self::quantifier(self.peek()) {\n            return self.fail(\"a repetition cannot itself be repeated\");\n        }\n        Ok(result)\n    }\n\n    fn sequence(&mut self) -> Result<RegexNode> {\n        let mut items = vec![];\n        while let Some(c) = self.peek() {\n            if c == '|' as u32 || c == ')' as u32 {\n                break;\n            }\n            let atom = self.atom()?;\n            items.push(self.quantified(atom)?);\n        }\n        Ok(RegexNode::Sequence(items))\n    }\n\n    fn alternatives(&mut self) -> Result<RegexNode> {\n        let mut branches = vec![self.sequence()?];\n        while self.peek() == Some('|' as u32) {\n            self.pos += 1;\n            branches.push(self.sequence()?);\n        }\n        Ok(if branches.len() == 1 { branches.pop().unwrap() } else { RegexNode::Alternatives(branches) })\n    }\n}\n\nfn regex_parse(pattern: &str) -> Result<RegexNode> {\n    let mut parser = RegexParser { pattern, cs: pattern.chars().map(|c| c as u32).collect(), pos: 0 };\n    let node = parser.alternatives()?;\n    if parser.pos != parser.cs.len() {\n        return parser.fail(\"a ) has no ( before it\");\n    }\n    Ok(node)\n}\n\nfn regex_reach(node: &RegexNode, text: &[u32], positions: Vec<bool>) -> Vec<bool> {\n    let mut next = vec![false; text.len() + 1];\n    match node {\n        RegexNode::Set(negated, items) => {\n            for (p, &at) in positions.iter().enumerate() {\n                if !at || p >= text.len() {\n                    continue;\n                }\n                let c = text[p];\n                let inside = items\n                    .iter()\n                    .any(|item| item.negated != item.ranges.iter().any(|&(lo, hi)| lo <= c && c <= hi));\n                if inside != *negated {\n                    next[p + 1] = true;\n                }\n            }\n            next\n        }\n        RegexNode::Sequence(items) => items.iter().fold(positions, |at, item| regex_reach(item, text, at)),\n        RegexNode::Alternatives(branches) => {\n            for branch in branches {\n                for (p, at) in regex_reach(branch, text, positions.clone()).into_iter().enumerate() {\n                    next[p] |= at;\n                }\n            }\n            next\n        }\n        RegexNode::Repeat(body, low, high) => {\n            let mut positions = positions;\n            for _ in 0..*low {\n                positions = regex_reach(body, text, positions);\n            }\n            let mut seen = positions.clone();\n            let mut frontier = positions;\n            let mut limit = high.map(|h| h - low);\n            while limit != Some(0) {\n                let reached = regex_reach(body, text, frontier);\n                frontier = vec![false; text.len() + 1];\n                let mut any = false;\n                for (p, at) in reached.into_iter().enumerate() {\n                    if at && !seen[p] {\n                        frontier[p] = true;\n                        seen[p] = true;\n                        any = true;\n                    }\n                }\n                if !any {\n                    break;\n                }\n                limit = limit.map(|l| l - 1);\n            }\n            seen\n        }\n    }\n}\n\nstatic REGEX_CACHE: std::sync::LazyLock<std::sync::Mutex<HashMap<String, RegexNode>>> =\n    std::sync::LazyLock::new(|| std::sync::Mutex::new(HashMap::new()));\n\n/// Whether the portable regex matches the whole text.\npub fn regex_matches(pattern: &str, text: &str) -> Result<bool> {\n    let cached = REGEX_CACHE.lock().unwrap().get(pattern).cloned();\n    let node = match cached {\n        Some(node) => node,\n        None => {\n            let node = regex_parse(pattern)?;\n            REGEX_CACHE.lock().unwrap().insert(pattern.to_string(), node.clone());\n            node\n        }\n    };\n    let points: Vec<u32> = text.chars().map(|c| c as u32).collect();\n    let mut start = vec![false; points.len() + 1];\n    start[0] = true;\n    Ok(regex_reach(&node, &points, start)[points.len()])\n}\n\n// Recorded values: a law compares a value's portable rendering with the\n// text stored under recorded/<unit>/<name> in the project. LAWSPEC_RECORDED\n// names the folder; otherwise it is recorded/ in the nearest folder, from\n// the working one up, that holds lawspec.json or recorded/. With\n// LAWSPEC_UPDATE_RECORDED=1 (lawspec test --update-recorded) a law records\n// the value instead.\npub fn recorded_root() -> std::path::PathBuf {\n    if let Ok(given) = std::env::var(\"LAWSPEC_RECORDED\") {\n        if !given.is_empty() {\n            return given.into();\n        }\n    }\n    let start = std::env::current_dir().unwrap_or_default();\n    let mut folder = start.as_path();\n    loop {\n        if folder.join(\"lawspec.json\").exists() || folder.join(\"recorded\").is_dir() {\n            return folder.join(\"recorded\");\n        }\n        match folder.parent() {\n            Some(parent) => folder = parent,\n            None => return start.join(\"recorded\"),\n        }\n    }\n}\n\npub fn recorded(key: &str, value: &Value) -> Result<bool> {\n    let text = render(value);\n    let mut path = recorded_root();\n    for part in key.split('/') {\n        path.push(part);\n    }\n    if std::env::var(\"LAWSPEC_UPDATE_RECORDED\").as_deref() == Ok(\"1\") {\n        if let Some(parent) = path.parent() {\n            std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;\n        }\n        std::fs::write(&path, format!(\"{text}\\n\")).map_err(|e| e.to_string())?;\n        return Ok(true);\n    }\n    let Ok(stored) = std::fs::read_to_string(&path) else {\n        return Err(format!(\"no recording recorded/{key}; run lawspec test --update-recorded to record {text}\"));\n    };\n    let stored = stored.strip_suffix('\\n').unwrap_or(&stored);\n    if stored != text {\n        return Err(format!(\n            \"recorded/{key} differs: expected {stored}, actual {text} (lawspec test --update-recorded records the new value)\"\n        ));\n    }\n    Ok(true)\n}\n\n// Shared resources (share R per group | unit | run, in a harness): one value\n// per scope key. The first use acquires it; every later use resets it first,\n// so no case sees what another left. One case holds it at a time (until its\n// SharedGuard drops, even on a panic), and it is released when the test\n// process exits.\nstruct SharedEntry {\n    busy: bool,\n    users: usize,\n    concurrent: bool,\n    value: Option<Value>,\n}\nstatic SHARED: std::sync::Mutex<Option<HashMap<String, SharedEntry>>> = std::sync::Mutex::new(None);\nstatic SHARED_FREE: std::sync::Condvar = std::sync::Condvar::new();\ntype SharedRelease = Box<dyn FnOnce() + Send>;\nstatic SHARED_RELEASES: std::sync::Mutex<Vec<SharedRelease>> = std::sync::Mutex::new(Vec::new());\n\nunsafe extern \"C\" {\n    fn atexit(callback: extern \"C\" fn()) -> std::os::raw::c_int;\n}\n\nextern \"C\" fn release_shared() {\n    let releases: Vec<SharedRelease> = match SHARED_RELEASES.lock() {\n        Ok(mut list) => list.drain(..).rev().collect(),\n        Err(_) => return,\n    };\n    for release in releases {\n        let _ = std::panic::catch_unwind(std::panic::AssertUnwindSafe(release));\n    }\n}\n\npub struct SharedGuard(String);\n\nimpl Drop for SharedGuard {\n    fn drop(&mut self) {\n        let mut shared = SHARED.lock().unwrap_or_else(|e| e.into_inner());\n        if let Some(entry) = shared.get_or_insert_with(HashMap::new).get_mut(&self.0) {\n            if entry.concurrent {\n                entry.users = entry.users.saturating_sub(1);\n                if entry.users == 0 {\n                    entry.busy = false;\n                }\n            } else {\n                entry.busy = false;\n            }\n        }\n        SHARED_FREE.notify_all();\n    }\n}\n\n/// A concurrent resource (resource T is concurrent) is held by any number of\n/// cases at once, and reset only when none holds it.\npub fn share<A, R, F>(key: &str, ctx: &mut Context, acquire: A, reset: R, release: F, concurrent: bool) -> Result<(Value, SharedGuard)>\nwhere\n    A: FnOnce(&mut Context) -> Result<Value>,\n    R: FnOnce(&mut Context, Value) -> Result<Value>,\n    F: FnOnce(&mut Context, Value) -> Result<Value> + Send + 'static,\n{\n    if concurrent {\n        let mut shared = SHARED.lock().unwrap_or_else(|e| e.into_inner());\n        let entry = shared.get_or_insert_with(HashMap::new).entry(key.to_string())\n            .or_insert(SharedEntry { busy: false, users: 0, concurrent: true, value: None });\n        let value = match entry.value.clone() {\n            Some(value) => {\n                if entry.users == 0 {\n                    reset(ctx, value.clone())?;\n                }\n                value\n            }\n            None => {\n                let value = acquire(ctx)?;\n                entry.value = Some(value.clone());\n                let kept = value.clone();\n                let mut releases = SHARED_RELEASES.lock().unwrap_or_else(|e| e.into_inner());\n                if releases.is_empty() {\n                    unsafe { atexit(release_shared); }\n                }\n                releases.push(Box::new(move || {\n                    let ctx = &mut Context::testing();\n                    let _ = release(ctx, kept);\n                }));\n                value\n            }\n        };\n        entry.users += 1;\n        entry.busy = true;\n        return Ok((value, SharedGuard(key.to_string())));\n    }\n    let held = {\n        let mut shared = SHARED.lock().unwrap_or_else(|e| e.into_inner());\n        loop {\n            let entry = shared.get_or_insert_with(HashMap::new).entry(key.to_string())\n                .or_insert(SharedEntry { busy: false, users: 0, concurrent: false, value: None });\n            if !entry.busy {\n                entry.busy = true;\n                break entry.value.clone();\n            }\n            shared = SHARED_FREE.wait(shared).unwrap_or_else(|e| e.into_inner());\n        }\n    };\n    let guard = SharedGuard(key.to_string());\n    match held {\n        Some(value) => {\n            reset(ctx, value.clone())?;\n            Ok((value, guard))\n        }\n        None => {\n            let value = acquire(ctx)?;\n            {\n                let mut shared = SHARED.lock().unwrap_or_else(|e| e.into_inner());\n                if let Some(entry) = shared.get_or_insert_with(HashMap::new).get_mut(key) {\n                    entry.value = Some(value.clone());\n                }\n            }\n            let kept = value.clone();\n            let mut releases = SHARED_RELEASES.lock().unwrap_or_else(|e| e.into_inner());\n            if releases.is_empty() {\n                unsafe { atexit(release_shared); }\n            }\n            releases.push(Box::new(move || {\n                let ctx = &mut Context::testing();\n                let _ = release(ctx, kept);\n            }));\n            Ok((value, guard))\n        }\n    }\n}\n\n// Built-in resources (see LawSpec.Resources): a law acquires them before\n// each case and releases them after it. Tests run on several threads, so a\n// saved environment also holds the environment for its case alone.\nstatic ENVIRONMENT_HELD: std::sync::Mutex<bool> = std::sync::Mutex::new(false);\nstatic ENVIRONMENT_FREE: std::sync::Condvar = std::sync::Condvar::new();\nstatic TEMPORARY_COUNT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);\n\npub fn acquire_resource(kind: &str) -> Result<String> {\n    match kind {\n        \"temporaryDirectory\" | \"temporaryFile\" => {\n            let unique = TEMPORARY_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);\n            let nanos = std::time::SystemTime::now()\n                .duration_since(std::time::UNIX_EPOCH)\n                .map(|d| d.as_nanos())\n                .unwrap_or(0);\n            let path = std::env::temp_dir().join(format!(\"lawspec-{}-{nanos}-{unique}\", std::process::id()));\n            if kind == \"temporaryDirectory\" {\n                std::fs::create_dir(&path).map_err(|e| e.to_string())?;\n            } else {\n                std::fs::write(&path, \"\").map_err(|e| e.to_string())?;\n            }\n            Ok(path.to_string_lossy().into_owned())\n        }\n        \"environment\" => {\n            let mut held = ENVIRONMENT_HELD.lock().unwrap();\n            while *held {\n                held = ENVIRONMENT_FREE.wait(held).unwrap();\n            }\n            *held = true;\n            let mut saved: Vec<(String, String)> = std::env::vars().collect();\n            saved.sort();\n            Ok(saved.into_iter().map(|(k, v)| format!(\"{k}\\0{v}\\0\")).collect())\n        }\n        _ => Err(format!(\"unknown resource kind {kind}\")),\n    }\n}\n\npub fn release_resource(kind: &str, value: &str) -> Result<()> {\n    match kind {\n        \"temporaryDirectory\" => {\n            let _ = std::fs::remove_dir_all(value);\n        }\n        \"temporaryFile\" => {\n            let _ = std::fs::remove_file(value);\n        }\n        \"environment\" => {\n            let parts: Vec<&str> = value.split('\\0').collect();\n            let saved: HashMap<&str, &str> = parts.chunks(2).filter(|c| c.len() == 2).map(|c| (c[0], c[1])).collect();\n            for (name, _) in std::env::vars() {\n                if !saved.contains_key(name.as_str()) {\n                    // SAFETY: the saved environment holds the environment for\n                    // this case alone (ENVIRONMENT_HELD).\n                    unsafe { std::env::remove_var(&name) };\n                }\n            }\n            for (name, text) in &saved {\n                if std::env::var(name).as_deref() != Ok(*text) {\n                    // SAFETY: as above.\n                    unsafe { std::env::set_var(name, text) };\n                }\n            }\n            *ENVIRONMENT_HELD.lock().unwrap() = false;\n            ENVIRONMENT_FREE.notify_one();\n        }\n        _ => return Err(format!(\"unknown resource kind {kind}\")),\n    }\n    Ok(())\n}\n\n/// A TCP port on the local host that is free now.\npub fn free_port() -> Result<u16> {\n    let listener = std::net::TcpListener::bind(\"127.0.0.1:0\").map_err(|e| e.to_string())?;\n    listener.local_addr().map(|a| a.port()).map_err(|e| e.to_string())\n}\n\n// Portable generation for stateful models. A type descriptor is an\n// s-expression: (int T lo hi) with _ for no bound, (bool), (text), (unit),\n// (list D), (maybe D), (either L R), (data NAME (ctor TAG D...) ...) and\n// (ref NAME) for a data type declared in the model's table. Every target\n// generates, shrinks and renders the same values for the same seed, so the\n// draws, candidate order and rendering below follow the Python reference.\n\n/// A descriptor form. Quoted strings and symbols are one atom: the reference\n/// compares them as equal strings.\n#[derive(Clone, Debug, PartialEq)]\npub enum Sexp {\n    List(Vec<Sexp>),\n    Int(BigInt),\n    Atom(String),\n    Blank,\n}\n\nimpl Sexp {\n    fn items(&self) -> &[Sexp] {\n        match self {\n            Sexp::List(items) => items,\n            other => panic!(\"expected a descriptor form, got {other:?}\"),\n        }\n    }\n\n    fn kind(&self) -> &str {\n        match self.items().first() {\n            Some(Sexp::Atom(kind)) => kind,\n            _ => \"\",\n        }\n    }\n\n    fn name(&self) -> String {\n        match self {\n            Sexp::Atom(s) => s.clone(),\n            Sexp::Int(n) => n.to_string(),\n            Sexp::Blank => \"None\".into(),\n            Sexp::List(_) => format!(\"{self:?}\"),\n        }\n    }\n\n    fn bound(&self) -> Option<BigInt> {\n        match self {\n            Sexp::Int(n) => Some(n.clone()),\n            Sexp::Blank => None,\n            other => panic!(\"expected an integer bound, got {other:?}\"),\n        }\n    }\n}\n\n/// Parses s-expressions: lists, integers, strings, symbols and _ (Blank).\npub fn read_descriptor(text: &str) -> Vec<Sexp> {\n    let chars: Vec<char> = text.chars().collect();\n    let space = |c: char| matches!(c, ' ' | '\\t' | '\\r' | '\\n');\n    fn skip(chars: &[char], at: &mut usize, space: &dyn Fn(char) -> bool) {\n        while *at < chars.len() && space(chars[*at]) {\n            *at += 1;\n        }\n    }\n    fn item(chars: &[char], at: &mut usize, space: &dyn Fn(char) -> bool) -> Sexp {\n        skip(chars, at, space);\n        match chars[*at] {\n            '(' => {\n                *at += 1;\n                let mut items = Vec::new();\n                skip(chars, at, space);\n                while chars[*at] != ')' {\n                    items.push(item(chars, at, space));\n                    skip(chars, at, space);\n                }\n                *at += 1;\n                Sexp::List(items)\n            }\n            '\"' => {\n                *at += 1;\n                let mut out = String::new();\n                while chars[*at] != '\"' {\n                    if chars[*at] == '\\\\' {\n                        *at += 1;\n                    }\n                    out.push(chars[*at]);\n                    *at += 1;\n                }\n                *at += 1;\n                Sexp::Atom(out)\n            }\n            _ => {\n                let start = *at;\n                while *at < chars.len() && !space(chars[*at]) && chars[*at] != '(' && chars[*at] != ')' {\n                    *at += 1;\n                }\n                let atom: String = chars[start..*at].iter().collect();\n                let digits = atom.trim_start_matches('-');\n                if atom == \"_\" {\n                    Sexp::Blank\n                } else if !digits.is_empty() && digits.chars().all(|c| c.is_ascii_digit()) {\n                    atom.parse::<BigInt>().map(Sexp::Int).unwrap_or(Sexp::Atom(atom))\n                } else {\n                    Sexp::Atom(atom)\n                }\n            }\n        }\n    }\n    let mut at = 0;\n    let mut forms = Vec::new();\n    skip(&chars, &mut at, &space);\n    while at < chars.len() {\n        forms.push(item(&chars, &mut at, &space));\n        skip(&chars, &mut at, &space);\n    }\n    forms\n}\n\nconst UNBOUNDED: i64 = 1_000_000;\n\n// Uniform in [0, bound) like SplitMix64::below, but for any bound: a range\n// such as UInt64's is 2^64 wide.\nfn below_big(random: &mut SplitMix64, bound: &BigInt) -> BigInt {\n    if bound.is_positive() { BigInt::from(random.next()) % bound } else { BigInt::zero() }\n}\n\nfn below_len(random: &mut SplitMix64, bound: i64) -> usize {\n    if bound > 0 { random.below(bound as u64) as usize } else { 0 }\n}\n\n/// Generation, shrinking and rendering over a table of data types.\n#[derive(Clone, Debug)]\npub struct Values {\n    pub table: HashMap<String, Sexp>,\n}\n\nimpl Values {\n    pub fn new(table: HashMap<String, Sexp>) -> Self {\n        Values { table }\n    }\n\n    pub fn resolve<'a>(&'a self, d: &'a Sexp) -> &'a Sexp {\n        if d.kind() == \"ref\" {\n            let name = d.items()[1].name();\n            self.table.get(&name).unwrap_or_else(|| panic!(\"unknown data type {name}\"))\n        } else {\n            d\n        }\n    }\n\n    /// An integer's range: a missing bound is 1,000,000 from zero, or\n    /// 2,000,000 from the other bound when that is beyond it.\n    pub fn bounds(&self, d: &Sexp) -> (BigInt, BigInt) {\n        let items = d.items();\n        let far = BigInt::from(UNBOUNDED);\n        match (items[2].bound(), items[3].bound()) {\n            (None, None) => (-far.clone(), far),\n            (None, Some(hi)) => ((-far.clone()).min(&hi - 2 * &far), hi),\n            (Some(lo), None) => (lo.clone(), far.clone().max(&lo + 2 * &far)),\n            (Some(lo), Some(hi)) => (lo, hi),\n        }\n    }\n\n    /// The constructors whose fields mention no data type.\n    pub fn base<'a>(&self, d: &'a Sexp) -> Vec<&'a Sexp> {\n        let ctors = &d.items()[2..];\n        let found: Vec<&Sexp> = ctors.iter().filter(|c| !c.items()[2..].iter().any(mentions_data)).collect();\n        if found.is_empty() { ctors.iter().collect() } else { found }\n    }\n\n    pub fn generate(&self, d: &Sexp, random: &mut SplitMix64, size: i64) -> Value {\n        let d = self.resolve(d);\n        let items = d.items();\n        match d.kind() {\n            \"int\" => {\n                let (lo, hi) = self.bounds(d);\n                if random.below(10) < 2 {\n                    let specials = [lo.clone(), hi.clone(), clamp(0, &lo, &hi), clamp(1, &lo, &hi)];\n                    return Value::Integer(specials[random.below(4) as usize].clone());\n                }\n                let offset = below_big(random, &(&hi - &lo + 1));\n                Value::Integer(lo + offset)\n            }\n            \"bool\" => Value::Bool(random.below(2) == 1),\n            \"text\" => {\n                let n = below_len(random, size + 1);\n                Value::Text((0..n).map(|_| char::from(32 + random.below(95) as u8)).collect())\n            }\n            \"unit\" => Value::Unit,\n            \"list\" => {\n                let n = below_len(random, size + 1);\n                Value::List((0..n).map(|_| self.generate(&items[1], random, size)).collect())\n            }\n            \"maybe\" => {\n                if random.below(4) == 0 {\n                    return Value::Maybe(None);\n                }\n                Value::Maybe(Some(Box::new(self.generate(&items[1], random, size))))\n            }\n            \"either\" => {\n                if random.below(2) == 0 {\n                    return Value::Left(Box::new(self.generate(&items[1], random, size)));\n                }\n                Value::Right(Box::new(self.generate(&items[2], random, size)))\n            }\n            \"data\" => {\n                let choices: Vec<&Sexp> = if size <= 0 { self.base(d) } else { items[2..].iter().collect() };\n                let ctor = choices[random.below(choices.len() as u64) as usize].items();\n                let fields = ctor[2..].iter().map(|f| self.generate(f, random, (size - 1).max(0))).collect();\n                Value::Data(ctor[1].name(), fields)\n            }\n            _ => panic!(\"unknown descriptor {d:?}\"),\n        }\n    }\n\n    pub fn minimal(&self, d: &Sexp) -> Value {\n        let d = self.resolve(d);\n        let items = d.items();\n        match d.kind() {\n            \"int\" => {\n                let (lo, hi) = self.bounds(d);\n                Value::Integer(clamp(0, &lo, &hi))\n            }\n            \"bool\" => Value::Bool(false),\n            \"text\" => Value::Text(String::new()),\n            \"unit\" => Value::Unit,\n            \"list\" => Value::List(Vec::new()),\n            \"maybe\" => Value::Maybe(None),\n            \"either\" => Value::Left(Box::new(self.minimal(&items[1]))),\n            _ => {\n                let ctor = self.base(d)[0].items();\n                Value::Data(ctor[1].name(), ctor[2..].iter().map(|f| self.minimal(f)).collect())\n            }\n        }\n    }\n\n    /// Smaller candidates for v, most aggressive first.\n    pub fn shrink(&self, d: &Sexp, v: &Value) -> Vec<Value> {\n        let d = self.resolve(d);\n        let items = d.items();\n        let mut out: Vec<Value> = Vec::new();\n        match (d.kind(), v) {\n            (\"int\", Value::Integer(n)) => {\n                let target = match self.minimal(d) {\n                    Value::Integer(t) => t,\n                    _ => unreachable!(),\n                };\n                if *n != target {\n                    let step = if *n > target { BigInt::one() } else { -BigInt::one() };\n                    out = vec![\n                        Value::Integer(target.clone()),\n                        Value::Integer(n - toward_zero(&(n - &target), 2)),\n                        Value::Integer(n - step),\n                    ];\n                }\n            }\n            (\"bool\", Value::Bool(b)) => {\n                if *b {\n                    out = vec![Value::Bool(false)];\n                }\n            }\n            (\"text\", Value::Text(s)) => {\n                let cs: Vec<char> = s.chars().collect();\n                if !cs.is_empty() {\n                    out.push(Value::Text(String::new()));\n                    out.push(Value::Text(cs[..cs.len() / 2].iter().collect()));\n                    for i in 0..cs.len() {\n                        out.push(Value::Text(cs[..i].iter().chain(&cs[i + 1..]).collect()));\n                    }\n                }\n            }\n            (\"list\", Value::List(xs)) => {\n                if !xs.is_empty() {\n                    out.push(Value::List(Vec::new()));\n                    out.push(Value::List(xs[..xs.len() / 2].to_vec()));\n                    for i in 0..xs.len() {\n                        out.push(Value::List(xs[..i].iter().chain(&xs[i + 1..]).cloned().collect()));\n                    }\n                    for (i, x) in xs.iter().enumerate() {\n                        for c in self.shrink(&items[1], x) {\n                            let mut ys = xs.clone();\n                            ys[i] = c;\n                            out.push(Value::List(ys));\n                        }\n                    }\n                }\n            }\n            (\"maybe\", Value::Maybe(Some(x))) => {\n                out.push(Value::Maybe(None));\n                out.extend(self.shrink(&items[1], x).into_iter().map(|c| Value::Maybe(Some(Box::new(c)))));\n            }\n            (\"either\", Value::Left(x)) => {\n                out = self.shrink(&items[1], x).into_iter().map(|c| Value::Left(Box::new(c))).collect();\n            }\n            (\"either\", Value::Right(x)) => {\n                out = self.shrink(&items[2], x).into_iter().map(|c| Value::Right(Box::new(c))).collect();\n            }\n            (\"data\", Value::Data(tag, fields)) => {\n                let ctor = items[2..]\n                    .iter()\n                    .find(|c| c.items()[1].name() == *tag)\n                    .unwrap_or_else(|| panic!(\"no constructor {tag}\"))\n                    .items();\n                let own = Sexp::List(vec![Sexp::Atom(\"ref\".into()), items[1].clone()]);\n                out.push(self.minimal(d));\n                // A field of the same type is a smaller value of it.\n                out.extend(fields.iter().zip(&ctor[2..]).filter(|(_, fd)| **fd == own).map(|(f, _)| f.clone()));\n                for (i, (field, fd)) in fields.iter().zip(&ctor[2..]).enumerate() {\n                    for c in self.shrink(fd, field) {\n                        let mut fs = fields.clone();\n                        fs[i] = c;\n                        out.push(Value::Data(tag.clone(), fs));\n                    }\n                }\n            }\n            _ => {}\n        }\n        let own = render(v);\n        let mut seen: Vec<String> = Vec::new();\n        let mut unique = Vec::new();\n        for c in out {\n            let text = render(&c);\n            if text != own && !seen.contains(&text) {\n                seen.push(text);\n                unique.push(c);\n            }\n        }\n        unique\n    }\n}\n\nfn clamp(n: i64, lo: &BigInt, hi: &BigInt) -> BigInt {\n    BigInt::from(n).max(lo.clone()).min(hi.clone())\n}\n\nfn toward_zero(n: &BigInt, d: i64) -> BigInt {\n    let q = n.abs() / d;\n    if n.is_negative() { -q } else { q }\n}\n\nfn mentions_data(d: &Sexp) -> bool {\n    match d {\n        Sexp::List(items) => {\n            matches!(items.first(), Some(Sexp::Atom(k)) if k == \"ref\" || k == \"data\")\n                || items.iter().skip(1).any(mentions_data)\n        }\n        _ => false,\n    }\n}\n\n/// A value's canonical text, the same on every target.\npub fn render(v: &Value) -> String {\n    let all = |xs: &[Value]| xs.iter().map(render).collect::<Vec<_>>().join(\", \");\n    match v {\n        Value::Bool(b) => (if *b { \"true\" } else { \"false\" }).into(),\n        Value::Integer(n) => n.to_string(),\n        Value::Text(s) => format!(\"\\\"{}\\\"\", s.replace('\\\\', \"\\\\\\\\\").replace('\"', \"\\\\\\\"\")),\n        Value::Unit => \"()\".into(),\n        Value::List(xs) => format!(\"[{}]\", all(xs)),\n        Value::Maybe(None) => \"Nothing\".into(),\n        Value::Maybe(Some(x)) => format!(\"Just({})\", render(x)),\n        Value::Left(x) => format!(\"Left({})\", render(x)),\n        Value::Right(x) => format!(\"Right({})\", render(x)),\n        Value::Data(tag, fields) => {\n            let name = tag.rsplit(\"::\").next().unwrap_or(tag);\n            if fields.is_empty() { name.into() } else { format!(\"{name}({})\", all(fields)) }\n        }\n        Value::Handle(h) => h.label(),\n        other => format!(\"{other:?}\"),\n    }\n}\n\n/// A descriptor text's data types and its last form, the one generated.\npub fn values_from(text: &str) -> (Values, Sexp) {\n    let mut forms = read_descriptor(text);\n    let table = forms\n        .iter()\n        .filter(|f| matches!(f, Sexp::List(_)) && f.kind() == \"data\")\n        .map(|f| (f.items()[1].name(), f.clone()))\n        .collect();\n    let last = forms.pop().expect(\"a descriptor\");\n    (Values::new(table), last)\n}\n\n// LawSpec's own search over a law's inputs (see LawSpec.Search). The\n// failure database keeps a failing case's inputs in the wire encoding, under\n// LAWSPEC_FAILURES/inputs, and they are replayed before the law's next\n// generated cases. target maximize climbs: it generates inputs from seeds,\n// keeps the best-scoring case, and moves its integers (one step, doubling,\n// halving the distance to a bound), keeping the best move while the score\n// rises and drawing afresh when it does not, checking the law on every case\n// it tries (at most 400). A case gives its score, or None when its inputs\n// fall outside the law's refinements.\nfn search_file(law: &str) -> Option<std::path::PathBuf> {\n    let directory = std::env::var(\"LAWSPEC_FAILURES\").ok().filter(|d| !d.is_empty())?;\n    let safe: String = law.chars().map(|c| if c.is_ascii_alphanumeric() || c == '-' || c == '_' { c } else { '_' }).collect();\n    Some(std::path::Path::new(&directory).join(\"inputs\").join(safe + \".json\"))\n}\n\npub fn search_remember(law: &str, descriptors: &[&str], values: &[Value]) {\n    let Some(file) = search_file(law) else { return };\n    let mut inputs = Vec::new();\n    for (text, value) in descriptors.iter().zip(values) {\n        let (table, d) = values_from(text);\n        match net::wire_encode(&table, &d, value) {\n            Ok(bytes) => inputs.push(format!(\"\\\"{}\\\"\", bytes.iter().map(|b| format!(\"{b:02x}\")).collect::<String>())),\n            Err(_) => return,\n        }\n    }\n    let quoted = law.replace('\\\\', \"\\\\\\\\\").replace('\"', \"\\\\\\\"\");\n    if let Some(parent) = file.parent() {\n        let _ = std::fs::create_dir_all(parent);\n    }\n    let _ = std::fs::write(&file, format!(\"{{\\\"law\\\": \\\"{quoted}\\\", \\\"inputs\\\": [{}]}}\", inputs.join(\", \")));\n}\n\npub fn search_replay(law: &str, descriptors: &[&str], mut check: impl FnMut(&[Value]) -> Result<Option<f64>>) -> Result<()> {\n    let Some(file) = search_file(law) else { return Ok(()) };\n    let Ok(text) = std::fs::read_to_string(&file) else { return Ok(()) };\n    let after = text.find(\"\\\"inputs\\\"\").map(|i| &text[i + 8..]).unwrap_or(\"\");\n    let encoded: Vec<&str> = after.split('\"').skip(1).step_by(2).collect();\n    let mut values = Vec::new();\n    for (i, d) in descriptors.iter().enumerate() {\n        let Some(hex) = encoded.get(i) else { break };\n        let bytes: Option<Vec<u8>> = (0..hex.len() / 2).map(|k| u8::from_str_radix(&hex[2 * k..2 * k + 2], 16).ok()).collect();\n        let (table, descriptor) = values_from(d);\n        match bytes.map(|b| net::wire_decode(&table, &descriptor, &b)) {\n            Some(Ok(value)) => values.push(value),\n            _ => break,\n        }\n    }\n    if values.len() == descriptors.len() {\n        println!(\"{law}: replaying the failing inputs kept in .lawspec/failures\");\n        check(&values)?;\n    }\n    let _ = std::fs::remove_file(&file);\n    Ok(())\n}\n\n// Each value with one integer moved, wherever it sits in the value.\nfn search_moves(table: &Values, d: &Sexp, v: &Value) -> Vec<Value> {\n    let d = table.resolve(d);\n    let items = d.items();\n    match (d.kind(), v) {\n        (\"int\", Value::Integer(x)) => {\n            let (lo, hi) = table.bounds(d);\n            let two = BigInt::from(2);\n            let candidates = [x + 1, x - 1, x * &two, x / &two, x + (&hi - x) / &two, x - (x - &lo) / &two];\n            let mut out: Vec<Value> = Vec::new();\n            for c in candidates {\n                if c >= lo && c <= hi && &c != x && !out.contains(&Value::Integer(c.clone())) {\n                    out.push(Value::Integer(c));\n                }\n            }\n            out\n        }\n        (\"list\", Value::List(xs)) => (0..xs.len())\n            .flat_map(|i| search_moves(table, &items[1], &xs[i]).into_iter().map(move |m| (i, m)))\n            .map(|(i, m)| { let mut changed = xs.clone(); changed[i] = m; Value::List(changed) })\n            .collect(),\n        (\"maybe\", Value::Maybe(Some(inner))) => search_moves(table, &items[1], inner).into_iter().map(|m| Value::Maybe(Some(Box::new(m)))).collect(),\n        (\"either\", Value::Left(inner)) => search_moves(table, &items[1], inner).into_iter().map(|m| Value::Left(Box::new(m))).collect(),\n        (\"either\", Value::Right(inner)) => search_moves(table, &items[2], inner).into_iter().map(|m| Value::Right(Box::new(m))).collect(),\n        (\"data\", Value::Data(tag, fields)) => {\n            let Some(ctor) = items[2..].iter().find(|c| &c.items()[1].name() == tag) else { return Vec::new() };\n            let field_forms = &ctor.items()[2..];\n            (0..fields.len().min(field_forms.len()))\n                .flat_map(|i| search_moves(table, &field_forms[i], &fields[i]).into_iter().map(move |m| (i, m)))\n                .map(|(i, m)| { let mut changed = fields.clone(); changed[i] = m; Value::Data(tag.clone(), changed) })\n                .collect()\n        }\n        _ => Vec::new(),\n    }\n}\n\npub fn search_climb(law: &str, descriptors: &[&str], mut check: impl FnMut(&[Value]) -> Result<Option<f64>>) -> Result<()> {\n    let tables: Vec<(Values, Sexp)> = descriptors.iter().map(|d| values_from(d)).collect();\n    let base: u64 = std::env::var(\"LAWSPEC_SEED\").ok().and_then(|s| s.parse().ok()).unwrap_or(0);\n    let generate = |seed: u64| -> Vec<Value> {\n        let mut random = SplitMix64::new(seed);\n        tables.iter().map(|(table, d)| table.generate(d, &mut random, 8)).collect()\n    };\n    let mut best: Option<(f64, Vec<Value>)> = None;\n    let mut tried = 0;\n    let mut attempt = |values: Vec<Value>, best: &mut Option<(f64, Vec<Value>)>, tried: &mut usize| -> Result<bool> {\n        if *tried >= 400 {\n            return Ok(false);\n        }\n        *tried += 1;\n        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| check(&values)));\n        let score = match outcome {\n            Ok(Ok(score)) => score,\n            Ok(Err(error)) => { search_remember(law, descriptors, &values); return Err(error) }\n            Err(panic) => { search_remember(law, descriptors, &values); std::panic::resume_unwind(panic) }\n        };\n        match (score, best.as_ref()) {\n            (Some(s), Some((b, _))) if !(s > *b) => Ok(false),\n            (Some(s), _) => { *best = Some((s, values)); Ok(true) }\n            (None, _) => Ok(false),\n        }\n    };\n    for k in 0..10u64 {\n        attempt(generate(base.wrapping_add(k)), &mut best, &mut tried)?;\n    }\n    for step in 0..60u64 {\n        if tried >= 400 {\n            break;\n        }\n        let mut rose = false;\n        if let Some((_, current)) = best.clone() {\n            let mut moves = Vec::new();\n            for (i, v) in current.iter().enumerate() {\n                for m in search_moves(&tables[i].0, &tables[i].1, v) {\n                    let mut changed = current.clone();\n                    changed[i] = m;\n                    moves.push(changed);\n                }\n            }\n            moves.truncate(24);\n            for candidate in moves {\n                if attempt(candidate, &mut best, &mut tried)? {\n                    rose = true;\n                }\n            }\n        }\n        if !rose {\n            attempt(generate(base.wrapping_add(1000 + step)), &mut best, &mut tried)?;\n        }\n    }\n    match &best {\n        Some((score, _)) => println!(\"{law}: targeted search tried {tried} case(s); best score {score}\"),\n        None => println!(\"{law}: targeted search tried {tried} case(s)\"),\n    }\n    Ok(())\n}\n\n/// A score as a float: the targeted search maximizes it.\npub fn search_number(v: &Value) -> f64 {\n    match v {\n        Value::Integer(n) => n.to_f64().unwrap_or(f64::NAN),\n        Value::Float32(x) => *x as f64,\n        Value::Float64(x) => *x,\n        Value::Rational(r) => r.to_f64().unwrap_or(f64::NAN),\n        Value::Decimal(d) => format!(\"{d:?}\").parse().unwrap_or(f64::NAN),\n        _ => f64::NAN,\n    }\n}\n\n/// count values generated from one SplitMix64 seed, rendered.\npub fn generated(text: &str, seed: u64, size: i64, count: i64) -> Vec<String> {\n    let (values, d) = values_from(text);\n    let mut random = SplitMix64::new(seed);\n    (0..count).map(|_| render(&values.generate(&d, &mut random, size))).collect()\n}\n\n/// The shrink candidates of the first value generated, rendered.\npub fn shrunk(text: &str, seed: u64, size: i64) -> Vec<String> {\n    let (values, d) = values_from(text);\n    let first = values.generate(&d, &mut SplitMix64::new(seed), size);\n    values.shrink(&d, &first).iter().map(render).collect()\n}\n\n// Stateful models. A model's spec (see LawSpec.MachineSpec) lists its data\n// types, start and commands; the callbacks beside it are the generated\n// definitions that call the adapters, the references over the model state,\n// preconditions, the abstraction and invariants. A run is generated by\n// simulating the pure model, so every command in it is allowed by typestate,\n// its precondition and its reference; it is then executed against the\n// adapters and every result, abstracted state and invariant is checked. A\n// failing run is shrunk by dropping commands and shrinking arguments,\n// replaying the model to keep each candidate valid. The draws, candidate\n// order and messages follow the Python reference.\n\n/// A generated definition: the context, then its arguments.\npub type ModelCallback = fn(&mut Context, Vec<Value>) -> Result<Value>;\n\n/// A stateful model: its spec and the callbacks in the order the spec lists\n/// them. start is [run, model]; each command is (run, reference, when).\npub struct Model {\n    pub spec: &'static str,\n    pub start: [ModelCallback; 2],\n    pub commands: Vec<(ModelCallback, ModelCallback, Option<ModelCallback>)>,\n    pub abstract_state: Option<ModelCallback>,\n    pub invariants: Vec<ModelCallback>,\n}\n\nenum ModelNeed {\n    AtLeast(i64),\n    Exactly(i64),\n}\n\nenum ModelShift {\n    By(i64),\n    To(i64),\n}\n\nstruct ModelCommand {\n    name: String,\n    arguments: Vec<Sexp>,\n    state: usize,\n    unit: bool,\n    needs: Vec<ModelNeed>,\n    shifts: Vec<ModelShift>,\n    // The argument naming the key the command touches, for per-key checks.\n    key: Option<usize>,\n    // An actor's restart (restart from): never generated as a step; the\n    // injected crash runs it.\n    restart: bool,\n    run: ModelCallback,\n    reference: ModelCallback,\n    when: Option<ModelCallback>,\n}\n\nfn sexp_i64(s: &Sexp) -> i64 {\n    match s {\n        Sexp::Int(n) => n.to_i64().unwrap_or_else(|| panic!(\"index {n} out of range\")),\n        other => panic!(\"expected an integer, got {other:?}\"),\n    }\n}\n\n// The fields of a form, by their first atom.\nfn form_fields(items: &[Sexp]) -> HashMap<String, Vec<Sexp>> {\n    items.iter().map(|f| (f.kind().to_string(), f.items()[1..].to_vec())).collect()\n}\n\nimpl ModelCommand {\n    fn new(form: &Sexp, callbacks: &(ModelCallback, ModelCallback, Option<ModelCallback>)) -> Self {\n        let items = form.items();\n        let fields = form_fields(&items[2..]);\n        let field = |name: &str| fields.get(name).unwrap_or_else(|| panic!(\"command without {name}\")).clone();\n        let pair = |f: &Sexp| (f.kind().to_string(), sexp_i64(&f.items()[1]));\n        ModelCommand {\n            name: items[1].name(),\n            arguments: field(\"arguments\"),\n            state: sexp_i64(&field(\"state\")[0]) as usize,\n            unit: field(\"unit\")[0].name() == \"true\",\n            needs: field(\"needs\")\n                .iter()\n                .map(|n| match pair(n) {\n                    (k, i) if k == \"atleast\" => ModelNeed::AtLeast(i),\n                    (_, i) => ModelNeed::Exactly(i),\n                })\n                .collect(),\n            shifts: field(\"shifts\")\n                .iter()\n                .map(|s| match pair(s) {\n                    (k, d) if k == \"by\" => ModelShift::By(d),\n                    (_, k) => ModelShift::To(k),\n                })\n                .collect(),\n            key: match fields.get(\"key\").and_then(|k| k.first()) {\n                Some(Sexp::Int(n)) => Some(n.to_usize().unwrap_or_else(|| panic!(\"key {n} out of range\"))),\n                _ => None,\n            },\n            restart: fields.get(\"restart\").and_then(|r| r.first()).map(Sexp::name).as_deref() == Some(\"true\"),\n            run: callbacks.0,\n            reference: callbacks.1,\n            when: callbacks.2,\n        }\n    }\n\n    fn admits(&self, indices: &[i64]) -> bool {\n        self.needs.iter().zip(indices).all(|(n, i)| match n {\n            ModelNeed::AtLeast(k) => i >= k,\n            ModelNeed::Exactly(k) => i == k,\n        })\n    }\n\n    fn shifted(&self, indices: &[i64]) -> Vec<i64> {\n        self.shifts\n            .iter()\n            .zip(indices)\n            .map(|(s, i)| match s {\n                ModelShift::By(d) => i + d,\n                ModelShift::To(k) => *k,\n            })\n            .collect()\n    }\n}\n\n// Why a model step did not go through: the model does not allow it, or a\n// callback failed.\nenum ModelFault {\n    Invalid,\n    Error(String),\n}\n\n// A run: the start's arguments, then each command's index and arguments.\ntype ModelRun = (Vec<Value>, Vec<(usize, Vec<Value>)>);\n\nstruct Machine<'a> {\n    model: &'a Model,\n    name: String,\n    shared: bool,\n    values: Values,\n    start_indices: Vec<i64>,\n    start_arguments: Vec<Sexp>,\n    commands: Vec<ModelCommand>,\n    invariants: Vec<(String, ModelCallback)>,\n    per_key: bool,\n    // An actor model: the start's state runs inside an actor, and each\n    // command's handler bridge runs inside it in turn.\n    actor: bool,\n    // An actor's restart command (restart from), whose run and reference an\n    // injected crash uses; without one, a crash restarts from the start.\n    restart: Option<(ModelCallback, ModelCallback)>,\n    // What histories must agree with the model by: linearizable,\n    // sequential, causal or eventual.\n    consistency: String,\n}\n\n/// How a history that is not consistent is described.\nfn consistent_words(consistency: &str) -> &'static str {\n    match consistency {\n        \"sequential\" => \"sequentially consistent\",\n        \"causal\" => \"causally consistent\",\n        \"eventual\" => \"eventually consistent\",\n        _ => \"linearizable\",\n    }\n}\n\n// Calls a command: on an actor, its handler bridge (the state first,\n// returning Pair reply state, or the state alone for a Unit reply) runs in\n// the actor's turn, on this thread, so it can use this thread's Context.\nfn call_command(actor: bool, run: ModelCallback, unit: bool, ctx: &mut Context, mut full: Vec<Value>) -> Result<Value> {\n    if !actor {\n        return run(ctx, full);\n    }\n    let Some(Value::Handle(handle)) = full.first().cloned() else {\n        return Err(\"an actor's command was not given its actor\".into());\n    };\n    handle.native::<actors::Actor<Value>>()?.call(|state| {\n        full[0] = state;\n        let out = run(ctx, full)?;\n        if unit {\n            return Ok((Value::Unit, out));\n        }\n        match out {\n            Value::Data(_, fields) if fields.len() == 2 => {\n                let mut fields = fields.into_iter();\n                let reply = fields.next().unwrap();\n                Ok((reply, fields.next().unwrap()))\n            }\n            other => Err(format!(\"a handler returned {}, not a reply and a state\", render(&other))),\n        }\n    })\n}\n\nimpl<'a> Machine<'a> {\n    fn new(model: &'a Model) -> Self {\n        let forms = read_descriptor(model.spec);\n        let head = forms[0].items();\n        let table = forms\n            .iter()\n            .filter(|f| f.kind() == \"data\")\n            .map(|f| (f.items()[1].name(), f.clone()))\n            .collect();\n        let start = forms.iter().find(|f| f.kind() == \"start\").expect(\"a model start\");\n        let start_fields = form_fields(&start.items()[1..]);\n        let kinds = forms.iter().find(|f| f.kind() == \"invariants\").expect(\"model invariants\").items()[1..].to_vec();\n        let (restarts, commands): (Vec<ModelCommand>, Vec<ModelCommand>) = forms\n            .iter()\n            .filter(|f| f.kind() == \"command\")\n            .zip(&model.commands)\n            .map(|(f, c)| ModelCommand::new(f, c))\n            .partition(|c| c.restart);\n        Machine {\n            model,\n            name: head[1].name(),\n            shared: head[2].name() == \"shared\",\n            values: Values::new(table),\n            start_indices: start_fields.get(\"indices\").map(|is| is.iter().map(sexp_i64).collect()).unwrap_or_default(),\n            start_arguments: start_fields.get(\"arguments\").cloned().unwrap_or_default(),\n            commands,\n            restart: restarts.first().map(|c| (c.run, c.reference)),\n            invariants: kinds.iter().map(Sexp::name).zip(model.invariants.iter().copied()).collect(),\n            per_key: forms.iter().any(|f| f.kind() == \"perkey\" && f.items().get(1).map(Sexp::name).as_deref() == Some(\"true\")),\n            actor: forms.iter().any(|f| f.kind() == \"actor\" && f.items().get(1).map(Sexp::name).as_deref() == Some(\"true\")),\n            consistency: forms\n                .iter()\n                .find(|f| f.kind() == \"consistency\")\n                .and_then(|f| f.items().get(1).map(Sexp::name))\n                .unwrap_or_else(|| \"linearizable\".into()),\n        }\n    }\n\n    /// Starts the system: an actor model's start state runs in a new actor.\n    fn start_system(&self, ctx: &mut Context, args: Vec<Value>) -> Result<Value> {\n        let state = (self.model.start[0])(ctx, args)?;\n        Ok(if self.actor { Value::Handle(Handle::new(actors::Actor::new(state))) } else { state })\n    }\n\n    fn run_command(&self, command: &ModelCommand, ctx: &mut Context, full: Vec<Value>) -> Result<Value> {\n        call_command(self.actor, command.run, command.unit, ctx, full)\n    }\n\n    /// The system state the abstraction and invariants see: an actor's own\n    /// state, read between messages.\n    fn system_state(&self, state: &Value) -> Result<Value> {\n        match (self.actor, state) {\n            (true, Value::Handle(handle)) => handle.native::<actors::Actor<Value>>()?.state(),\n            _ => Ok(state.clone()),\n        }\n    }\n\n    /// Whether the model allows every step of a run.\n    fn simulate(&self, run: &ModelRun) -> bool {\n        let mut ctx = Context::testing();\n        let Ok(mut state) = (self.model.start[1])(&mut ctx, run.0.clone()) else {\n            return false;\n        };\n        let mut indices = self.start_indices.clone();\n        for (index, args) in &run.1 {\n            if *index == self.commands.len() {\n                match self.crash_model(&mut ctx, &run.0, state) {\n                    Ok(next) => state = next,\n                    Err(_) => return false,\n                }\n                continue;\n            }\n            let command = &self.commands[*index];\n            if !command.admits(&indices) {\n                return false;\n            }\n            match step_model(command, &mut ctx, args, state) {\n                Ok((next, _)) => state = next,\n                Err(ModelFault::Invalid) => return false,\n                Err(ModelFault::Error(e)) => panic!(\"model {}: {e}\", self.name),\n            }\n            indices = command.shifted(&indices);\n        }\n        true\n    }\n\n    /// An injected crash, on the model: the restart's reference, or the\n    /// start's model state.\n    fn crash_model(&self, ctx: &mut Context, start_args: &[Value], state: Value) -> Result<Value> {\n        match self.restart {\n            Some((_, reference)) => reference(ctx, vec![state]),\n            None => (self.model.start[1])(ctx, start_args.to_vec()),\n        }\n    }\n\n    /// An injected crash, on the system: the actor's state is replaced\n    /// between messages by the restart's run, or the start's run.\n    fn crash_system(&self, ctx: &mut Context, start_args: &[Value], state: &Value) -> Result<()> {\n        let Value::Handle(handle) = state else {\n            return Err(\"a crash was injected into a model that is not an actor\".into());\n        };\n        let actor = handle.native::<actors::Actor<Value>>()?;\n        match self.restart {\n            Some((run, _)) => actor.restart(|s| run(ctx, vec![s])),\n            None => {\n                let begin = self.model.start[0];\n                actor.restart(|_| begin(ctx, start_args.to_vec()))\n            }\n        }\n    }\n\n    fn generate_run(&self, random: &mut SplitMix64, length: u64, size: i64, crashes: bool) -> ModelRun {\n        let mut ctx = Context::testing();\n        let start_args: Vec<Value> = self.start_arguments.iter().map(|d| self.values.generate(d, random, size)).collect();\n        let Ok(mut state) = (self.model.start[1])(&mut ctx, start_args.clone()) else {\n            return (start_args, Vec::new());\n        };\n        let mut indices = self.start_indices.clone();\n        let mut steps = Vec::new();\n        for _ in 0..length {\n            let allowed: Vec<usize> = (0..self.commands.len()).filter(|&i| self.commands[i].admits(&indices)).collect();\n            if allowed.is_empty() {\n                break;\n            }\n            let index = allowed[random.below(allowed.len() as u64) as usize];\n            // One step in eight of an actor's run is a crash.\n            if crashes && self.actor && random.below(8) == 0 {\n                match self.crash_model(&mut ctx, &start_args, state.clone()) {\n                    Ok(next) => state = next,\n                    Err(_) => continue,\n                }\n                steps.push((self.commands.len(), Vec::new()));\n                continue;\n            }\n            let command = &self.commands[index];\n            let args: Vec<Value> = command.arguments.iter().map(|d| self.values.generate(d, random, size)).collect();\n            match step_model(command, &mut ctx, &args, state.clone()) {\n                Ok((next, _)) => state = next,\n                Err(ModelFault::Invalid) => continue,\n                Err(ModelFault::Error(e)) => panic!(\"model {}: {e}\", self.name),\n            }\n            steps.push((index, args));\n            indices = command.shifted(&indices);\n        }\n        (start_args, steps)\n    }\n\n    /// None when the system agrees with the model along the run; otherwise\n    /// the failing step's number and what went wrong.\n    fn execute(&self, run: &ModelRun) -> Option<(usize, String)> {\n        let mut step = 0;\n        match self.execute_steps(run, &mut step) {\n            Ok(None) => None,\n            Ok(Some(message)) => Some((step, message)),\n            Err(ModelFault::Invalid) => Some((step, \"the model does not allow this step\".into())),\n            Err(ModelFault::Error(e)) => Some((step, format!(\"raised error: {e}\"))),\n        }\n    }\n\n    fn execute_steps(&self, run: &ModelRun, step: &mut usize) -> std::result::Result<Option<String>, ModelFault> {\n        let mut ctx = Context::testing();\n        let mut state = self.start_system(&mut ctx, run.0.clone()).map_err(ModelFault::Error)?;\n        let mut expected = (self.model.start[1])(&mut ctx, run.0.clone()).map_err(ModelFault::Error)?;\n        if let Some(failure) = self.check_state(&mut ctx, &state, &expected)? {\n            return Ok(Some(failure));\n        }\n        for (index, args) in &run.1 {\n            *step += 1;\n            if *index == self.commands.len() {\n                self.crash_system(&mut ctx, &run.0, &state).map_err(ModelFault::Error)?;\n                expected = self.crash_model(&mut ctx, &run.0, expected).map_err(|_| ModelFault::Invalid)?;\n                if let Some(failure) = self.check_state(&mut ctx, &state, &expected)? {\n                    return Ok(Some(failure));\n                }\n                continue;\n            }\n            let command = &self.commands[*index];\n            let mut full = args.clone();\n            full.insert(command.state, state.clone());\n            let out = self.run_command(command, &mut ctx, full).map_err(ModelFault::Error)?;\n            let result = if self.shared {\n                out\n            } else {\n                let Value::Data(_, mut fields) = out else {\n                    return Err(ModelFault::Error(format!(\"command {} did not return its state\", command.name)));\n                };\n                let Some(last) = fields.pop() else {\n                    return Err(ModelFault::Error(format!(\"command {} did not return its state\", command.name)));\n                };\n                let result = if command.unit { Value::Unit } else { fields.into_iter().next().unwrap_or(last.clone()) };\n                state = last;\n                result\n            };\n            let (next, wanted) = step_model(command, &mut ctx, args, expected)?;\n            expected = next;\n            if !command.unit\n                && compare_values(&result, &wanted).map_err(ModelFault::Error)? != std::cmp::Ordering::Equal\n            {\n                return Ok(Some(format!(\"returned {}; the model returns {}\", render(&result), render(&wanted))));\n            }\n            if let Some(failure) = self.check_state(&mut ctx, &state, &expected)? {\n                return Ok(Some(failure));\n            }\n        }\n        Ok(None)\n    }\n\n    fn check_state(\n        &self,\n        ctx: &mut Context,\n        state: &Value,\n        expected: &Value,\n    ) -> std::result::Result<Option<String>, ModelFault> {\n        let state = &self.system_state(state).map_err(ModelFault::Error)?;\n        if let Some(abstraction) = self.model.abstract_state {\n            let actual = abstraction(ctx, vec![state.clone()]).map_err(ModelFault::Error)?;\n            if compare_values(&actual, expected).map_err(ModelFault::Error)? != std::cmp::Ordering::Equal {\n                return Ok(Some(format!(\"the state is {}; the model is {}\", render(&actual), render(expected))));\n            }\n        }\n        for (kind, invariant) in &self.invariants {\n            let subject = if kind == \"model\" { expected } else { state };\n            let holds = invariant(ctx, vec![subject.clone()]).and_then(|v| v.boolean()).map_err(ModelFault::Error)?;\n            if !holds {\n                return Ok(Some(format!(\"an invariant on the {kind} fails\")));\n            }\n        }\n        Ok(None)\n    }\n\n    fn shrink_candidates(&self, run: &ModelRun) -> Vec<ModelRun> {\n        let (start_args, steps) = run;\n        let mut out = Vec::new();\n        let n = steps.len();\n        let mut size = n / 2;\n        while size >= 1 {\n            for begin in (0..n).step_by(size) {\n                let kept = steps[..begin].iter().chain(steps.get(begin + size..).unwrap_or(&[])).cloned().collect();\n                out.push((start_args.clone(), kept));\n            }\n            size /= 2;\n        }\n        for (k, (index, args)) in steps.iter().enumerate() {\n            let Some(command) = self.commands.get(*index) else {\n                continue;\n            };\n            for (j, (d, arg)) in command.arguments.iter().zip(args).enumerate() {\n                for c in self.values.shrink(d, arg) {\n                    let mut changed = steps.clone();\n                    changed[k].1[j] = c;\n                    out.push((start_args.clone(), changed));\n                }\n            }\n        }\n        for (j, (d, arg)) in self.start_arguments.iter().zip(start_args).enumerate() {\n            for c in self.values.shrink(d, arg) {\n                let mut changed = start_args.clone();\n                changed[j] = c;\n                out.push((changed, steps.clone()));\n            }\n        }\n        out\n    }\n\n    fn shrink_run(&self, mut run: ModelRun, mut failure: (usize, String), max_shrinks: i64) -> (ModelRun, (usize, String)) {\n        let mut budget = max_shrinks;\n        'shrinking: while budget > 0 {\n            let mut improved = false;\n            for candidate in self.shrink_candidates(&run) {\n                budget -= 1;\n                if budget <= 0 {\n                    break 'shrinking;\n                }\n                if !self.simulate(&candidate) {\n                    continue;\n                }\n                if let Some(found) = self.execute(&candidate) {\n                    run = candidate;\n                    failure = found;\n                    improved = true;\n                    break;\n                }\n            }\n            if !improved {\n                break;\n            }\n        }\n        (run, failure)\n    }\n\n    fn describe_run(&self, run: &ModelRun) -> String {\n        let all = |xs: &[Value]| xs.iter().map(render).collect::<Vec<_>>().join(\", \");\n        let mut parts = vec![format!(\"start({})\", all(&run.0))];\n        parts.extend(run.1.iter().map(|(i, args)| {\n            format!(\"{}({})\", self.commands.get(*i).map_or(\"crash\", |c| c.name.as_str()), all(args))\n        }));\n        parts.join(\"; \")\n    }\n}\n\n// A reference step over the model state: the next state and the result.\nfn step_model(\n    command: &ModelCommand,\n    ctx: &mut Context,\n    args: &[Value],\n    state: Value,\n) -> std::result::Result<(Value, Value), ModelFault> {\n    if let Some(when) = command.when {\n        match when(ctx, vec![state.clone()]).and_then(|v| v.boolean()) {\n            Ok(true) => {}\n            _ => return Err(ModelFault::Invalid),\n        }\n    }\n    let mut full = args.to_vec();\n    full.push(state);\n    let out = (command.reference)(ctx, full).map_err(|_| ModelFault::Invalid)?;\n    if command.unit {\n        return Ok((out, Value::Unit));\n    }\n    match out {\n        Value::Data(_, fields) if fields.len() >= 2 => {\n            let mut fields = fields.into_iter();\n            let result = fields.next().unwrap();\n            Ok((fields.next().unwrap(), result))\n        }\n        other => Err(ModelFault::Error(format!(\n            \"the reference for {} returned {}, not a pair\",\n            command.name,\n            render(&other)\n        ))),\n    }\n}\n\n/// Checks the system against its model on generated runs (100 cases of up\n/// to 20 commands, seeded by LAWSPEC_SEED); a failure names the shortest\n/// failing run found.\n///\n/// A stateful model is checked by running generated command sequences against\n/// the system and the model side by side, then shrinking a failing run.\n/// ref:DEC-stateful-models-linearizability\npub fn check_model(model: &Model) -> std::result::Result<(), String> {\n    let (cases, max_length, max_shrinks) = (100u64, 20u64, 2000i64);\n    let seed = std::env::var(\"LAWSPEC_SEED\").ok().and_then(|s| s.trim().parse::<u64>().ok()).unwrap_or(0);\n    let machine = Machine::new(model);\n    let mut random = SplitMix64::new(seed);\n    for case in 0..cases {\n        let length = random.below(max_length + 1);\n        let run = machine.generate_run(&mut random, length, 1 + (case % 8) as i64, true);\n        if let Some(failure) = machine.execute(&run) {\n            let (run, (step, message)) = machine.shrink_run(run, failure, max_shrinks);\n            return Err(format!(\n                \"model {} fails at step {} of {}: {}\",\n                machine.name,\n                step,\n                machine.describe_run(&run),\n                message\n            ));\n        }\n    }\n    Ok(())\n}\n\n// Parallel runs of a shared model. A case is a sequential prefix and one\n// branch per thread, generated so that the model allows every interleaving\n// of the branches (a search over each thread's position and the model\n// state, memoized). The system runs the branches at the same time, each\n// call's start and return recorded on one counter, with random yields and\n// short sleeps around calls to shake out rare schedules. The history must\n// be linearizable: some interleaving that keeps every call after those that\n// returned before it started must give every result the model gives and\n// leave the state it leaves (a Wing-Gong search, memoized on the same\n// positions and model state). Each case runs several times. The draws,\n// candidate order and messages follow the Python reference.\n\nconst PARALLEL_THREADS: usize = 3;\nconst PARALLEL_BRANCH: u64 = 5;\n\n// A branch: each command's index and arguments.\ntype ModelBranch = Vec<(usize, Vec<Value>)>;\ntype ParallelCase = (ModelRun, Vec<ModelBranch>);\n// One call of a branch: when it started, when it returned, and its result.\ntype ParallelCall = (u64, u64, Value);\n\nfn branch_name(i: usize) -> char {\n    (b'A' + i as u8) as char\n}\n\n// Positions with thread i's moved one step on.\nfn advanced(positions: &[usize], i: usize) -> Vec<usize> {\n    let mut next = positions.to_vec();\n    next[i] += 1;\n    next\n}\n\n/// Nothing, a yield, or a sleep of 10 or 100 microseconds.\nfn perturb(random: &mut SplitMix64) {\n    match random.below(4) {\n        0 => {}\n        1 => std::thread::yield_now(),\n        2 => std::thread::sleep(std::time::Duration::from_micros(10)),\n        _ => std::thread::sleep(std::time::Duration::from_micros(100)),\n    }\n}\n\nimpl<'a> Machine<'a> {\n    /// The model state after a run, or None when the model does not allow it.\n    fn simulate_state(&self, ctx: &mut Context, run: &ModelRun) -> Option<Value> {\n        let mut state = (self.model.start[1])(ctx, run.0.clone()).ok()?;\n        let mut indices = self.start_indices.clone();\n        for (index, args) in &run.1 {\n            let command = &self.commands[*index];\n            if !command.admits(&indices) {\n                return None;\n            }\n            match step_model(command, ctx, args, state) {\n                Ok((next, _)) => state = next,\n                Err(ModelFault::Invalid) => return None,\n                Err(ModelFault::Error(e)) => panic!(\"model {}: {e}\", self.name),\n            }\n            indices = command.shifted(&indices);\n        }\n        Some(state)\n    }\n\n    /// Whether the model allows the prefix then every interleaving.\n    fn parallel_allowed(&self, prefix: &ModelRun, branches: &[ModelBranch]) -> bool {\n        let mut ctx = Context::testing();\n        let Some(start) = self.simulate_state(&mut ctx, prefix) else {\n            return false;\n        };\n        let mut seen = std::collections::HashSet::new();\n        self.allowed_from(&mut ctx, branches, &mut seen, vec![0; branches.len()], start)\n    }\n\n    fn allowed_from(\n        &self,\n        ctx: &mut Context,\n        branches: &[ModelBranch],\n        seen: &mut std::collections::HashSet<(Vec<usize>, String)>,\n        positions: Vec<usize>,\n        state: Value,\n    ) -> bool {\n        if !seen.insert((positions.clone(), render(&state))) {\n            return true;\n        }\n        for (i, branch) in branches.iter().enumerate() {\n            let k = positions[i];\n            if k < branch.len() {\n                let (index, args) = &branch[k];\n                let after = match step_model(&self.commands[*index], ctx, args, state.clone()) {\n                    Ok((next, _)) => next,\n                    Err(ModelFault::Invalid) => return false,\n                    Err(ModelFault::Error(e)) => panic!(\"model {}: {e}\", self.name),\n                };\n                if !self.allowed_from(ctx, branches, seen, advanced(&positions, i), after) {\n                    return false;\n                }\n            }\n        }\n        true\n    }\n\n    fn generate_branch(&self, random: &mut SplitMix64, mut state: Value, length: u64, size: i64) -> ModelBranch {\n        let mut ctx = Context::testing();\n        let mut steps = Vec::new();\n        for _ in 0..length {\n            let index = random.below(self.commands.len() as u64) as usize;\n            let command = &self.commands[index];\n            let args: Vec<Value> = command.arguments.iter().map(|d| self.values.generate(d, random, size)).collect();\n            match step_model(command, &mut ctx, &args, state.clone()) {\n                Ok((next, _)) => state = next,\n                Err(ModelFault::Invalid) => continue,\n                Err(ModelFault::Error(e)) => panic!(\"model {}: {e}\", self.name),\n            }\n            steps.push((index, args));\n        }\n        steps\n    }\n\n    fn generate_parallel(&self, random: &mut SplitMix64, size: i64, threads: usize, branch_length: u64) -> ParallelCase {\n        let length = random.below(4);\n        let prefix = self.generate_run(random, length, size, false);\n        let Some(state) = self.simulate_state(&mut Context::testing(), &prefix) else {\n            return (prefix, vec![Vec::new(); threads]);\n        };\n        let mut branches = Vec::new();\n        for _ in 0..threads {\n            let length = 1 + random.below(branch_length);\n            branches.push(self.generate_branch(random, state.clone(), length, size));\n        }\n        // Drop the last step of the longest branch (the first, among equals)\n        // until every interleaving is allowed.\n        while !self.parallel_allowed(&prefix, &branches) {\n            let mut longest = 0;\n            for i in 1..threads {\n                if branches[i].len() > branches[longest].len() {\n                    longest = i;\n                }\n            }\n            branches[longest].pop();\n        }\n        (prefix, branches)\n    }\n\n    /// None when the history is linearizable; otherwise what went wrong.\n    fn execute_parallel(&self, case: &ParallelCase, shake: u64) -> Option<String> {\n        let (prefix, branches) = case;\n        let mut ctx = Context::testing();\n        let state = match self.run_prefix(&mut ctx, prefix) {\n            Ok(state) => state,\n            Err(e) => return Some(format!(\"the prefix raised error: {e}\")),\n        };\n        // What each thread needs: the call, the command's name and the full\n        // arguments, all Send.\n        let calls: Vec<Vec<(ModelCallback, bool, String, Vec<Value>)>> = branches\n            .iter()\n            .map(|branch| {\n                branch\n                    .iter()\n                    .map(|(index, args)| {\n                        let command = &self.commands[*index];\n                        let mut full = args.clone();\n                        full.insert(command.state, state.clone());\n                        (command.run, command.unit, command.name.clone(), full)\n                    })\n                    .collect()\n            })\n            .collect();\n        let clock = std::sync::atomic::AtomicU64::new(0);\n        let errors = std::sync::Mutex::new(Vec::<String>::new());\n        let actor = self.actor;\n        let tick = || clock.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1;\n        let history: Vec<Vec<ParallelCall>> = std::thread::scope(|scope| {\n            let handles: Vec<_> = calls\n                .into_iter()\n                .enumerate()\n                .map(|(i, branch)| {\n                    let (tick, errors) = (&tick, &errors);\n                    scope.spawn(move || {\n                        let mut own = Context::testing();\n                        let mut random = SplitMix64::new(shake ^ ((i as u64 + 1).wrapping_mul(0x9E3779B97F4A7C15)));\n                        let mut out = Vec::new();\n                        for (run, unit, name, full) in branch {\n                            perturb(&mut random);\n                            let called = tick();\n                            let result = match call_command(actor, run, unit, &mut own, full) {\n                                Ok(result) => result,\n                                Err(e) => {\n                                    errors.lock().unwrap_or_else(|p| p.into_inner()).push(format!(\"{name} raised error: {e}\"));\n                                    Value::Unit\n                                }\n                            };\n                            out.push((called, tick(), result));\n                            perturb(&mut random);\n                        }\n                        out\n                    })\n                })\n                .collect();\n            handles.into_iter().map(|h| h.join().unwrap_or_else(|p| std::panic::resume_unwind(p))).collect()\n        });\n        if let Some(error) = errors.into_inner().unwrap_or_else(|p| p.into_inner()).into_iter().next() {\n            return Some(error);\n        }\n        let expected = self.simulate_state(&mut ctx, prefix).expect(\"the model allows the prefix\");\n        let state = match self.system_state(&state) {\n            Ok(state) => state,\n            Err(e) => return Some(format!(\"raised error: {e}\")),\n        };\n        let fin = match self.model.abstract_state {\n            Some(abstraction) => match abstraction(&mut ctx, vec![state.clone()]) {\n                Ok(v) => Some(v),\n                Err(e) => return Some(format!(\"raised error: {e}\")),\n            },\n            None => None,\n        };\n        if self.linearizable(&mut ctx, branches, &history, expected, fin.as_ref(), &state) {\n            return None;\n        }\n        let mut observed = Vec::new();\n        for (i, branch) in branches.iter().enumerate() {\n            for (k, (index, _)) in branch.iter().enumerate() {\n                observed.push(format!(\n                    \"{}: {}() returned {}\",\n                    branch_name(i),\n                    self.commands[*index].name,\n                    render(&history[i][k].2)\n                ));\n            }\n        }\n        Some(format!(\"no order of the parallel calls agrees with the model ({})\", observed.join(\"; \")))\n    }\n\n    // Starts the system and runs the prefix's commands, giving the state.\n    fn run_prefix(&self, ctx: &mut Context, prefix: &ModelRun) -> Result<Value> {\n        let state = self.start_system(ctx, prefix.0.clone())?;\n        for (index, args) in &prefix.1 {\n            let command = &self.commands[*index];\n            let mut full = args.clone();\n            full.insert(command.state, state.clone());\n            self.run_command(command, ctx, full)?;\n        }\n        Ok(state)\n    }\n\n    /// Whether the history linearizes, with the final state and invariants\n    /// the model gives. For a set or map whose every call touches one key,\n    /// each key's calls are linearized separately (the keys are\n    /// independent), one group after another; otherwise all calls at once.\n    fn linearizable(\n        &self,\n        ctx: &mut Context,\n        branches: &[ModelBranch],\n        history: &[Vec<ParallelCall>],\n        expected: Value,\n        fin: Option<&Value>,\n        state: &Value,\n    ) -> bool {\n        let finish = |ctx: &mut Context, model_state: &Value| -> bool {\n            if let Some(fin) = fin {\n                if !matches!(compare_values(fin, model_state), Ok(std::cmp::Ordering::Equal)) {\n                    return false;\n                }\n            }\n            for (kind, invariant) in &self.invariants {\n                let subject = if kind == \"model\" { model_state } else { state };\n                if !matches!(invariant(ctx, vec![subject.clone()]).and_then(|v| v.boolean()), Ok(true)) {\n                    return false;\n                }\n            }\n            true\n        };\n        if !self.per_key {\n            return self.linearize(ctx, branches, history, expected, &mut |c, s| finish(c, s));\n        }\n        // Each key's calls, thread by thread, ordered by the rendered key.\n        let mut groups: std::collections::BTreeMap<String, Vec<(ModelBranch, Vec<ParallelCall>)>> =\n            std::collections::BTreeMap::new();\n        for (i, branch) in branches.iter().enumerate() {\n            for (k, (index, args)) in branch.iter().enumerate() {\n                let position = self.commands[*index].key.expect(\"a per-key command names its key\");\n                let parts = groups\n                    .entry(render(&args[position]))\n                    .or_insert_with(|| vec![(Vec::new(), Vec::new()); branches.len()]);\n                parts[i].0.push(branch[k].clone());\n                parts[i].1.push(history[i][k].clone());\n            }\n        }\n        let mut model_state = expected;\n        for parts in groups.values() {\n            let (steps, calls): (Vec<ModelBranch>, Vec<Vec<ParallelCall>>) = parts.iter().cloned().unzip();\n            let mut ends = Vec::new();\n            if !self.linearize(ctx, &steps, &calls, model_state, &mut |_, end| {\n                ends.push(end.clone());\n                true\n            }) {\n                return false;\n            }\n            model_state = ends.swap_remove(0);\n        }\n        finish(ctx, &model_state)\n    }\n\n    /// A Wing-Gong search: linearize, next, a call no pending call on\n    /// another thread returned before; memoized on positions and the model\n    /// state. finish judges each complete order's final model state.\n    ///\n    /// ref:wing-gong-linearizability\n    fn linearize(\n        &self,\n        ctx: &mut Context,\n        branches: &[ModelBranch],\n        history: &[Vec<ParallelCall>],\n        expected: Value,\n        finish: &mut dyn FnMut(&mut Context, &Value) -> bool,\n    ) -> bool {\n        // Causal: threads that never message each other see only their own\n        // calls, so each thread's results replay alone.\n        if self.consistency == \"causal\" {\n            for (i, branch) in branches.iter().enumerate() {\n                let mut state = expected.clone();\n                for (k, (index, args)) in branch.iter().enumerate() {\n                    let command = &self.commands[*index];\n                    let (after, wanted) = match step_model(command, ctx, args, state) {\n                        Ok(stepped) => stepped,\n                        Err(ModelFault::Invalid) => return false,\n                        Err(ModelFault::Error(e)) => panic!(\"model {}: {e}\", self.name),\n                    };\n                    if !command.unit && !matches!(compare_values(&history[i][k].2, &wanted), Ok(std::cmp::Ordering::Equal)) {\n                        return false;\n                    }\n                    state = after;\n                }\n            }\n            return true;\n        }\n        let mut seen = std::collections::HashSet::new();\n        self.visit(ctx, branches, history, &mut seen, vec![0; branches.len()], expected, finish)\n    }\n\n    #[allow(clippy::too_many_arguments)]\n    fn visit(\n        &self,\n        ctx: &mut Context,\n        branches: &[ModelBranch],\n        history: &[Vec<ParallelCall>],\n        seen: &mut std::collections::HashSet<(Vec<usize>, String)>,\n        positions: Vec<usize>,\n        model_state: Value,\n        finish: &mut dyn FnMut(&mut Context, &Value) -> bool,\n    ) -> bool {\n        if !seen.insert((positions.clone(), render(&model_state))) {\n            return false;\n        }\n        if positions.iter().zip(branches).all(|(k, b)| *k == b.len()) {\n            return finish(ctx, &model_state);\n        }\n        for (i, branch) in branches.iter().enumerate() {\n            let k = positions[i];\n            if k == branch.len() {\n                continue;\n            }\n            let called = history[i][k].0;\n            // Sequential and eventual drop real time; each thread's own\n            // order remains.\n            if self.consistency == \"linearizable\"\n                && (0..branches.len()).any(|j| j != i && positions[j] < branches[j].len() && history[j][positions[j]].1 < called)\n            {\n                continue;\n            }\n            let (index, args) = &branch[k];\n            let command = &self.commands[*index];\n            let (after, wanted) = match step_model(command, ctx, args, model_state.clone()) {\n                Ok(stepped) => stepped,\n                Err(ModelFault::Invalid) => continue,\n                Err(ModelFault::Error(e)) => panic!(\"model {}: {e}\", self.name),\n            };\n            if self.consistency != \"eventual\"\n                && !command.unit\n                && !matches!(compare_values(&history[i][k].2, &wanted), Ok(std::cmp::Ordering::Equal))\n            {\n                continue;\n            }\n            if self.visit(ctx, branches, history, seen, advanced(&positions, i), after, finish) {\n                return true;\n            }\n        }\n        false\n    }\n\n    fn parallel_fails(&self, case: &ParallelCase, repeats: u64, shake: u64) -> Option<String> {\n        (0..repeats).find_map(|attempt| self.execute_parallel(case, shake.wrapping_add(attempt)))\n    }\n\n    fn shrink_parallel(\n        &self,\n        mut case: ParallelCase,\n        mut failure: String,\n        repeats: u64,\n        mut budget: i64,\n        shake: u64,\n    ) -> (ParallelCase, String) {\n        'shrinking: while budget > 0 {\n            let (prefix, branches) = &case;\n            let mut candidates: Vec<ParallelCase> = Vec::new();\n            for k in 0..prefix.1.len() {\n                let mut steps = prefix.1.clone();\n                steps.remove(k);\n                candidates.push(((prefix.0.clone(), steps), branches.clone()));\n            }\n            for i in 0..branches.len() {\n                for k in 0..branches[i].len() {\n                    let mut shorter = branches.clone();\n                    shorter[i].remove(k);\n                    candidates.push((prefix.clone(), shorter));\n                }\n            }\n            // Then smaller arguments, branch by branch, step by step.\n            for i in 0..branches.len() {\n                for (k, (index, args)) in branches[i].iter().enumerate() {\n                    let command = &self.commands[*index];\n                    for (a, (d, arg)) in command.arguments.iter().zip(args).enumerate() {\n                        for c in self.values.shrink(d, arg) {\n                            let mut changed = branches.clone();\n                            changed[i][k].1[a] = c;\n                            candidates.push((prefix.clone(), changed));\n                        }\n                    }\n                }\n            }\n            let mut improved = false;\n            for candidate in candidates {\n                budget -= 1;\n                if budget <= 0 {\n                    break 'shrinking;\n                }\n                if !self.parallel_allowed(&candidate.0, &candidate.1) {\n                    continue;\n                }\n                if let Some(found) = self.parallel_fails(&candidate, repeats, shake) {\n                    case = candidate;\n                    failure = found;\n                    improved = true;\n                    break;\n                }\n            }\n            if !improved {\n                break;\n            }\n        }\n        (case, failure)\n    }\n\n    fn describe_parallel(&self, case: &ParallelCase) -> String {\n        let describe = |steps: &ModelBranch| {\n            let text = steps\n                .iter()\n                .map(|(i, args)| {\n                    format!(\"{}({})\", self.commands[*i].name, args.iter().map(render).collect::<Vec<_>>().join(\", \"))\n                })\n                .collect::<Vec<_>>()\n                .join(\"; \");\n            if text.is_empty() { \"nothing\".to_string() } else { text }\n        };\n        let parts: Vec<String> =\n            case.1.iter().enumerate().map(|(i, b)| format!(\"{}: {}\", branch_name(i), describe(b))).collect();\n        let (last, rest) = parts.split_last().map(|(l, r)| (l.as_str(), r)).unwrap_or((\"\", &[]));\n        format!(\"{}, then {} and {} at the same time\", self.describe_run(&case.0), rest.join(\", \"), last)\n    }\n}\n\n/// Checks a shared model's histories under concurrency (50 cases of three\n/// branches, each case run 10 times, seeded by LAWSPEC_SEED); a failure\n/// names the smallest failing case found.\n///\n/// A shared model promises linearizability unless it names a weaker\n/// consistency, so concurrent histories are judged against some sequential\n/// order of the calls. ref:herlihy-wing-linearizability\n/// ref:DEC-stateful-models-linearizability\npub fn check_model_parallel(model: &Model) -> std::result::Result<(), String> {\n    let seed = std::env::var(\"LAWSPEC_SEED\").ok().and_then(|s| s.trim().parse::<u64>().ok()).unwrap_or(0);\n    check_model_parallel_with(model, 50, 10, 300, seed, PARALLEL_THREADS, PARALLEL_BRANCH)\n}\n\n/// check_model_parallel with every parameter given.\npub fn check_model_parallel_with(\n    model: &Model,\n    cases: u64,\n    repeats: u64,\n    max_shrinks: i64,\n    seed: u64,\n    threads: usize,\n    branch_length: u64,\n) -> std::result::Result<(), String> {\n    let machine = Machine::new(model);\n    let mut random = SplitMix64::new(seed ^ 0x5BD1E995);\n    for case_number in 0..cases {\n        let case = machine.generate_parallel(&mut random, 1 + (case_number % 8) as i64, threads, branch_length);\n        let shake = random.next();\n        if let Some(failure) = machine.parallel_fails(&case, repeats, shake) {\n            let (case, failure) = machine.shrink_parallel(case, failure, (repeats / 2).max(2), max_shrinks, shake);\n            return Err(format!(\n                \"model {} is not {}: {}: {}\",\n                machine.name,\n                consistent_words(&machine.consistency),\n                machine.describe_parallel(&case),\n                failure\n            ));\n        }\n    }\n    Ok(())\n}\n\n// Scenarios: processes that drive a shared model's commands at the same time\n// and talk over channels (see LawSpec.Core.Program for the spec). Each\n// channel has a queue per direction; a process holds an end of a channel as\n// (channel, side), the first branch of a par to use a channel taking side 0.\n// A channel end sent over a channel moves to the receiver. Every command's\n// call and return are stamped on one counter; the history must linearize\n// against the model, and every expect must hold, on each of many schedules.\n// The draws, search order and messages follow the Python reference.\n\n// What travels over a channel: a value, or a channel end (channel, side).\nenum Carried {\n    Value(Value),\n    End(usize, usize),\n    // The sending side's process has ended.\n    Gone,\n}\n\n// A queue per direction: side s sends on queues[s] and receives on\n// queues[1 - s]. ended[s] once side s's process has ended.\nstruct ScenarioQueues {\n    queues: [std::collections::VecDeque<Carried>; 2],\n    ended: [bool; 2],\n}\n\nstruct ScenarioChannel {\n    state: std::sync::Mutex<ScenarioQueues>,\n    ready: std::sync::Condvar,\n    // In a network run: the channel's two sides as ends on two nodes of a\n    // faulty in-memory network, instead of the queues.\n    net: Option<NetChannel>,\n}\n\nstruct NetChannel {\n    nodes: [net::Node; 2],\n    ends: [net::NetEndpoint; 2],\n    done: [std::sync::atomic::AtomicBool; 2],\n}\n\n// A vector clock: each process's count of its own events.\ntype VectorClock = HashMap<usize, u64>;\n\n// A scenario's mailbox: any process sends, one receives. expected is how\n// many sends the scenario makes; a process that ends gives up the sends it\n// did not make, and a receive with nothing left to come finds Gone instead\n// of waiting. Over a network, messages go from a sender node to the\n// receiver's node, each send waiting until it is delivered; the senders'\n// clocks travel beside the network, in send order.\nstruct ScenarioMailbox {\n    expected: usize,\n    state: std::sync::Mutex<MailboxState>,\n    ready: std::sync::Condvar,\n    net: Option<NetMailbox>,\n}\n\n#[derive(Default)]\nstruct MailboxState {\n    items: std::collections::VecDeque<(Carried, VectorClock)>,\n    clocks: std::collections::VecDeque<VectorClock>,\n    received: usize,\n    abandoned: usize,\n}\n\nstruct NetMailbox {\n    nodes: [net::Node; 2],\n    inbox: actors::Mailbox<Value>,\n    remote: net::RemoteMailbox,\n}\n\n/// How many times these acts (not nested pars) send to name.\nfn scenario_sends(acts: &[Sexp], name: &str) -> usize {\n    acts.iter().filter(|a| a.kind() == \"send\" && a.items()[1].name() == name).count()\n}\n\n/// How many sends to name the whole program makes.\nfn all_sends(acts: &[Sexp], name: &str) -> usize {\n    let mut total = 0;\n    for act in acts {\n        if act.kind() == \"send\" && act.items()[1].name() == name {\n            total += 1;\n        } else if act.kind() == \"par\" {\n            total += act.items()[1..].iter().map(|b| all_sends(&b.items()[1..], name)).sum::<usize>();\n        }\n    }\n    total\n}\n\n// A channel end a process holds: the channel's number and its side.\ntype ScenarioEnds = HashMap<String, (usize, usize)>;\n// One call: the command, its arguments, its result, when it started and\n// when it returned, its process, and its process's clock at the call and\n// at the return.\ntype ScenarioCall = (usize, Vec<Value>, Value, u64, u64, usize, VectorClock, VectorClock);\n\nstruct ScenarioRun<'m> {\n    machine: &'m Machine<'m>,\n    commands: HashMap<String, usize>,\n    channels: Vec<ScenarioChannel>,\n    channel_numbers: HashMap<String, usize>,\n    channel_names: Vec<String>,\n    // Each value sent carries its sender's clock, kept here in order per\n    // channel and sending side.\n    stamps: std::sync::Mutex<HashMap<(usize, usize), std::collections::VecDeque<VectorClock>>>,\n    state: Value,\n    shake: u64,\n    clock: std::sync::atomic::AtomicU64,\n    history: std::sync::Mutex<Vec<ScenarioCall>>,\n    failures: std::sync::Mutex<Vec<String>>,\n    // The crashed process (a par's branch) and the act it crashes before.\n    victim: Option<(usize, usize)>,\n    mailboxes: HashMap<String, ScenarioMailbox>,\n}\n\n/// Every process of a par, outermost and first first (not or else).\nfn scenario_processes<'s>(acts: &'s [Sexp], found: &mut Vec<&'s Sexp>) {\n    for act in acts {\n        if act.kind() == \"par\" {\n            for branch in &act.items()[1..] {\n                found.push(branch);\n                scenario_processes(&branch.items()[1..], found);\n            }\n        }\n    }\n}\n\n/// The names an act list sends, receives or sends away, with nested pars.\nfn scenario_channels(acts: &[Sexp]) -> Vec<String> {\n    let mut names = Vec::new();\n    for act in acts {\n        let items = act.items();\n        match act.kind() {\n            \"send\" => {\n                names.push(items[1].name());\n                if items[2].kind() == \"var\" {\n                    names.push(items[2].items()[1].name());\n                }\n            }\n            \"receive\" => names.push(items[1].name()),\n            \"receiveor\" => {\n                names.push(items[1].name());\n                names.extend(scenario_channels(&items[3].items()[1..]));\n            }\n            \"par\" => {\n                for branch in &items[1..] {\n                    names.extend(scenario_channels(&branch.items()[1..]));\n                }\n            }\n            _ => {}\n        }\n    }\n    names\n}\n\nfn scenario_constant(form: &Sexp) -> Value {\n    let items = form.items();\n    match form.kind() {\n        \"int\" => match &items[1] {\n            Sexp::Int(n) => Value::Integer(n.clone()),\n            other => Value::Integer(other.name().parse().unwrap_or_else(|_| panic!(\"expected an integer, got {other:?}\"))),\n        },\n        \"text\" => Value::Text(items[1].name()),\n        \"bool\" => Value::Bool(items[1].name() == \"true\"),\n        _ => Value::Data(items[1].name(), Vec::new()),\n    }\n}\n\nimpl<'m> ScenarioRun<'m> {\n    fn fail(&self, message: String) {\n        self.failures.lock().unwrap_or_else(|p| p.into_inner()).push(message);\n    }\n\n    fn failed(&self) -> bool {\n        !self.failures.lock().unwrap_or_else(|p| p.into_inner()).is_empty()\n    }\n\n    fn tick(&self) -> u64 {\n        self.clock.fetch_add(1, std::sync::atomic::Ordering::SeqCst) + 1\n    }\n\n    fn operand(&self, operand: &Sexp, env: &HashMap<String, Value>) -> Option<Value> {\n        if operand.kind() == \"var\" {\n            env.get(&operand.items()[1].name()).cloned()\n        } else {\n            Some(scenario_constant(operand))\n        }\n    }\n\n    fn end(&self, name: &str, ends: &ScenarioEnds) -> Option<(usize, usize)> {\n        let found = ends.get(name).copied();\n        if found.is_none() {\n            self.fail(format!(\"{name} is not a channel end this process holds\"));\n        }\n        found\n    }\n\n    fn queues(&self, channel: usize) -> std::sync::MutexGuard<'_, ScenarioQueues> {\n        self.channels[channel].state.lock().unwrap_or_else(|p| p.into_inner())\n    }\n\n    /// Sends from side; a channel end sent to a process that has ended is\n    /// given up.\n    fn send_on(&self, channel: usize, side: usize, value: Carried) {\n        if let Some(net) = &self.channels[channel].net {\n            let value = match value {\n                Carried::End(c, s) => Value::Text(format!(\"{}#{s}\", self.channel_names[c])),\n                Carried::Value(v) => v,\n                Carried::Gone => return,\n            };\n            if let Err(e) = net.ends[side].send(&value) {\n                if !net::is_peer_failed(&e) {\n                    self.fail(format!(\"a send failed: {e}\"));\n                }\n            }\n            return;\n        }\n        let mut queues = self.queues(channel);\n        if let (true, Carried::End(c, s)) = (queues.ended[1 - side], &value) {\n            let (c, s) = (*c, *s);\n            drop(queues);\n            return self.gone(c, s);\n        }\n        queues.queues[side].push_back(value);\n        self.channels[channel].ready.notify_all();\n    }\n\n    /// side's process has ended: the other side's receives that find\n    /// nothing more fail instead of waiting, and channel ends on their way\n    /// to side are given up too.\n    fn gone(&self, channel: usize, side: usize) {\n        if let Some(net) = &self.channels[channel].net {\n            if !net.done[side].swap(true, std::sync::atomic::Ordering::SeqCst) {\n                net.ends[side].abandon();\n            }\n            return;\n        }\n        let mut stranded = Vec::new();\n        {\n            let mut queues = self.queues(channel);\n            if queues.ended[side] {\n                return;\n            }\n            queues.ended[side] = true;\n            queues.queues[side].push_back(Carried::Gone);\n            while let Some(value) = queues.queues[1 - side].pop_front() {\n                match value {\n                    Carried::End(c, s) => stranded.push((c, s)),\n                    Carried::Gone => {\n                        queues.queues[1 - side].push_back(Carried::Gone);\n                        break;\n                    }\n                    Carried::Value(_) => {}\n                }\n            }\n            self.channels[channel].ready.notify_all();\n        }\n        for (c, s) in stranded {\n            self.gone(c, s);\n        }\n    }\n\n    /// The next thing side receives on channel: None when nothing came in\n    /// time.\n    fn receive_on(&self, channel: usize, side: usize) -> Option<Carried> {\n        if let Some(net) = &self.channels[channel].net {\n            return match net.ends[side].receive(Some(std::time::Duration::from_secs(5))) {\n                Ok(Value::Text(t)) => match t.rsplit_once('#').and_then(|(c, s)| Some((self.channel_numbers.get(c)?, s.parse::<usize>().ok()?))) {\n                    Some((c, s)) => Some(Carried::End(*c, s)),\n                    None => Some(Carried::Value(Value::Text(t))),\n                },\n                Ok(v) => Some(Carried::Value(v)),\n                Err(e) if net::is_peer_failed(&e) => Some(Carried::Gone),\n                Err(_) => None,\n            };\n        }\n        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);\n        let mut waiting = self.queues(channel);\n        loop {\n            if let Some(v) = waiting.queues[1 - side].pop_front() {\n                if let Carried::Gone = v {\n                    waiting.queues[1 - side].push_back(Carried::Gone);\n                }\n                return Some(v);\n            }\n            let now = std::time::Instant::now();\n            if now >= deadline {\n                return None;\n            }\n            waiting = self.channels[channel].ready.wait_timeout(waiting, deadline - now).unwrap_or_else(|p| p.into_inner()).0;\n        }\n    }\n\n    fn mailbox_send(&self, name: &str, value: Carried, clock: VectorClock) -> bool {\n        let mailbox = &self.mailboxes[name];\n        match &mailbox.net {\n            None => {\n                mailbox.state.lock().unwrap_or_else(|p| p.into_inner()).items.push_back((value, clock));\n                mailbox.ready.notify_all();\n                true\n            }\n            Some(net) => {\n                let value = match value {\n                    Carried::End(c, s) => Value::Text(format!(\"{}#{s}\", self.channel_names[c])),\n                    Carried::Value(v) => v,\n                    Carried::Gone => return true,\n                };\n                mailbox.state.lock().unwrap_or_else(|p| p.into_inner()).clocks.push_back(clock);\n                if let Err(e) = net.remote.send(&value) {\n                    self.fail(format!(\"a send to mailbox {name} failed: {e}\"));\n                    return false;\n                }\n                mailbox.ready.notify_all();\n                true\n            }\n        }\n    }\n\n    fn mailbox_give_up(&self, name: &str, count: usize) {\n        let mailbox = &self.mailboxes[name];\n        mailbox.state.lock().unwrap_or_else(|p| p.into_inner()).abandoned += count;\n        mailbox.ready.notify_all();\n    }\n\n    /// The next message and its sender's clock, Gone when no message is\n    /// left to come, or None when nothing came in time.\n    fn mailbox_receive(&self, name: &str) -> Option<(Carried, VectorClock)> {\n        let mailbox = &self.mailboxes[name];\n        let deadline = std::time::Instant::now() + std::time::Duration::from_secs(5);\n        loop {\n            {\n                let mut state = mailbox.state.lock().unwrap_or_else(|p| p.into_inner());\n                if mailbox.net.is_none() {\n                    if let Some(item) = state.items.pop_front() {\n                        state.received += 1;\n                        return Some(item);\n                    }\n                }\n                if state.received + state.abandoned >= mailbox.expected {\n                    return Some((Carried::Gone, VectorClock::new()));\n                }\n                if mailbox.net.is_none() {\n                    let now = std::time::Instant::now();\n                    if now >= deadline {\n                        return None;\n                    }\n                    drop(mailbox.ready.wait_timeout(state, (deadline - now).min(std::time::Duration::from_millis(50))));\n                    continue;\n                }\n            }\n            let net = mailbox.net.as_ref().expect(\"a network mailbox\");\n            match net.inbox.receive(Some(std::time::Duration::from_millis(20))) {\n                Ok(value) => {\n                    let clock = {\n                        let mut state = mailbox.state.lock().unwrap_or_else(|p| p.into_inner());\n                        state.received += 1;\n                        state.clocks.pop_front().unwrap_or_default()\n                    };\n                    let carried = match value {\n                        Value::Text(t) => match t.rsplit_once('#').and_then(|(c, s)| Some((self.channel_numbers.get(c)?, s.parse::<usize>().ok()?))) {\n                            Some((c, s)) => Carried::End(*c, s),\n                            None => Carried::Value(Value::Text(t)),\n                        },\n                        other => Carried::Value(other),\n                    };\n                    return Some((carried, clock));\n                }\n                Err(_) if std::time::Instant::now() >= deadline => return None,\n                Err(_) => {}\n            }\n        }\n    }\n\n    fn stamp(&self, channel: usize, side: usize, clock: &VectorClock) {\n        self.stamps.lock().unwrap_or_else(|p| p.into_inner()).entry((channel, side)).or_default().push_back(clock.clone());\n    }\n\n    fn unstamp(&self, channel: usize, side: usize, clock: &mut VectorClock, me: usize) {\n        let sent = self\n            .stamps\n            .lock()\n            .unwrap_or_else(|p| p.into_inner())\n            .get_mut(&(channel, 1 - side))\n            .and_then(|q| q.pop_front())\n            .unwrap_or_default();\n        for (p, n) in sent {\n            let mine = clock.entry(p).or_insert(0);\n            *mine = (*mine).max(n);\n        }\n        *clock.entry(me).or_insert(0) += 1;\n    }\n\n    /// Runs a process: true when it finished, false when it failed; either\n    /// way, the ends it still holds are given up.\n    fn process(\n        &self,\n        acts: &[Sexp],\n        env: &mut HashMap<String, Value>,\n        ends: &mut ScenarioEnds,\n        random: &mut SplitMix64,\n        identity: usize,\n        clock: &mut VectorClock,\n    ) -> bool {\n        let mut sent: HashMap<String, usize> = self.mailboxes.keys().map(|m| (m.clone(), 0)).collect();\n        let done = self.steps(acts, env, ends, random, identity, clock, identity, &mut sent);\n        for (channel, side) in ends.drain().map(|(_, end)| end).collect::<Vec<_>>() {\n            self.gone(channel, side);\n        }\n        // Sends this process will never make.\n        for (name, count) in &sent {\n            let missing = scenario_sends(acts, name).saturating_sub(*count);\n            if missing > 0 {\n                self.mailbox_give_up(name, missing);\n            }\n        }\n        done\n    }\n\n    fn steps(\n        &self,\n        acts: &[Sexp],\n        env: &mut HashMap<String, Value>,\n        ends: &mut ScenarioEnds,\n        random: &mut SplitMix64,\n        identity: usize,\n        clock: &mut VectorClock,\n        me: usize,\n        sent: &mut HashMap<String, usize>,\n    ) -> bool {\n        let mut own = Context::testing();\n        for (index, act) in acts.iter().enumerate() {\n            if self.failed() {\n                return false;\n            }\n            if self.victim == Some((identity, index)) {\n                return false;\n            }\n            let items = act.items();\n            match act.kind() {\n                \"call\" => {\n                    let name = items[1].name();\n                    let command_index = *self.commands.get(&name).unwrap_or_else(|| panic!(\"no command {name}\"));\n                    let command = &self.machine.commands[command_index];\n                    let mut args = Vec::new();\n                    for o in &items[3..] {\n                        match self.operand(o, env) {\n                            Some(v) => args.push(v),\n                            None => {\n                                self.fail(format!(\"{} is not bound\", o.items()[1].name()));\n                                return false;\n                            }\n                        }\n                    }\n                    let mut full = args.clone();\n                    full.insert(command.state, self.state.clone());\n                    perturb(random);\n                    *clock.entry(me).or_insert(0) += 1;\n                    let at_call = clock.clone();\n                    let called = self.tick();\n                    let result = match self.machine.run_command(command, &mut own, full) {\n                        Ok(result) => result,\n                        Err(e) => {\n                            self.fail(format!(\"{} raised error: {e}\", command.name));\n                            return false;\n                        }\n                    };\n                    let returned = self.tick();\n                    *clock.entry(me).or_insert(0) += 1;\n                    self.history.lock().unwrap_or_else(|p| p.into_inner()).push((\n                        command_index,\n                        args,\n                        result.clone(),\n                        called,\n                        returned,\n                        me,\n                        at_call,\n                        clock.clone(),\n                    ));\n                    if items[2] != Sexp::Blank {\n                        env.insert(items[2].name(), result);\n                    }\n                }\n                \"send\" if self.mailboxes.contains_key(&items[1].name()) => {\n                    let name = items[1].name();\n                    let operand = &items[2];\n                    let held = if operand.kind() == \"var\" { ends.remove(&operand.items()[1].name()) } else { None };\n                    let value = match held {\n                        Some((c, s)) => Carried::End(c, s),\n                        None => match self.operand(operand, env) {\n                            Some(v) => Carried::Value(v),\n                            None => {\n                                self.fail(format!(\"{} is not bound\", operand.items()[1].name()));\n                                return false;\n                            }\n                        },\n                    };\n                    perturb(random);\n                    *clock.entry(me).or_insert(0) += 1;\n                    if !self.mailbox_send(&name, value, clock.clone()) {\n                        return false;\n                    }\n                    *sent.entry(name).or_insert(0) += 1;\n                }\n                \"receive\" | \"receiveor\" if self.mailboxes.contains_key(&items[1].name()) => {\n                    let name = items[1].name();\n                    match self.mailbox_receive(&name) {\n                        None => {\n                            self.fail(format!(\"a receive on mailbox {name} waited too long: the processes are blocked\"));\n                            return false;\n                        }\n                        Some((Carried::Gone, _)) => {\n                            if act.kind() == \"receive\" {\n                                return false;\n                            }\n                            return self.steps(&items[3].items()[1..], env, ends, random, usize::MAX, clock, me, sent);\n                        }\n                        Some((value, carried)) => {\n                            for (p, n) in carried {\n                                let mine = clock.entry(p).or_insert(0);\n                                *mine = (*mine).max(n);\n                            }\n                            *clock.entry(me).or_insert(0) += 1;\n                            match value {\n                                Carried::End(c, s) => {\n                                    ends.insert(items[2].name(), (c, s));\n                                }\n                                Carried::Value(v) => {\n                                    env.insert(items[2].name(), v);\n                                }\n                                Carried::Gone => {}\n                            }\n                        }\n                    }\n                }\n                \"send\" => {\n                    let Some((channel, side)) = self.end(&items[1].name(), ends) else { return false };\n                    let operand = &items[2];\n                    let held = if operand.kind() == \"var\" { ends.remove(&operand.items()[1].name()) } else { None };\n                    let value = match held {\n                        Some((c, s)) => Carried::End(c, s),\n                        None => match self.operand(operand, env) {\n                            Some(v) => Carried::Value(v),\n                            None => {\n                                self.fail(format!(\"{} is not bound\", operand.items()[1].name()));\n                                return false;\n                            }\n                        },\n                    };\n                    perturb(random);\n                    *clock.entry(me).or_insert(0) += 1;\n                    self.stamp(channel, side, clock);\n                    self.send_on(channel, side, value);\n                }\n                \"receive\" | \"receiveor\" => {\n                    let name = items[1].name();\n                    let Some((channel, side)) = self.end(&name, ends) else { return false };\n                    let value = self.receive_on(channel, side);\n                    if !matches!(value, None | Some(Carried::Gone)) {\n                        self.unstamp(channel, side, clock, me);\n                    }\n                    match value {\n                        None => {\n                            self.fail(format!(\"a receive on {name} waited too long: the processes are blocked\"));\n                            return false;\n                        }\n                        // The other process ended: or else runs instead of\n                        // the rest; without it, this process fails too.\n                        Some(Carried::Gone) => {\n                            if act.kind() == \"receive\" {\n                                return false;\n                            }\n                            ends.remove(&name);\n                            return self.steps(&items[3].items()[1..], env, ends, random, usize::MAX, clock, me, sent);\n                        }\n                        Some(Carried::End(c, s)) => {\n                            ends.insert(items[2].name(), (c, s));\n                        }\n                        Some(Carried::Value(v)) => {\n                            env.insert(items[2].name(), v);\n                        }\n                    }\n                }\n                \"par\" => {\n                    let branches: Vec<&[Sexp]> = items[1..].iter().map(|b| &b.items()[1..]).collect();\n                    // Each name's users, in branch order.\n                    let mut owned: Vec<(String, Vec<usize>)> = Vec::new();\n                    for (i, branch) in branches.iter().enumerate() {\n                        for name in scenario_channels(branch) {\n                            let at = match owned.iter().position(|(n, _)| *n == name) {\n                                Some(at) => at,\n                                None => {\n                                    owned.push((name, Vec::new()));\n                                    owned.len() - 1\n                                }\n                            };\n                            if !owned[at].1.contains(&i) {\n                                owned[at].1.push(i);\n                            }\n                        }\n                    }\n                    let mut handed = Vec::new();\n                    for i in 0..branches.len() {\n                        let mut mine = ScenarioEnds::new();\n                        for (name, users) in &owned {\n                            if let Some(side) = users.iter().position(|u| *u == i) {\n                                if let Some(end) = ends.remove(name) {\n                                    mine.insert(name.clone(), end);\n                                } else if let Some(channel) = self.channel_numbers.get(name) {\n                                    mine.insert(name.clone(), (*channel, side));\n                                }\n                            }\n                        }\n                        handed.push(mine);\n                    }\n                    let parent = clock.clone();\n                    let outcomes: Vec<(bool, VectorClock)> = std::thread::scope(|scope| {\n                        let running: Vec<_> = items[1..]\n                            .iter()\n                            .zip(handed)\n                            .enumerate()\n                            .map(|(i, (branch, mut mine))| {\n                                let mut env = env.clone();\n                                let mut child = parent.clone();\n                                let mut random =\n                                    SplitMix64::new(self.shake ^ ((i as u64 + 1).wrapping_mul(0x9E3779B97F4A7C15)));\n                                let identity = branch as *const Sexp as usize;\n                                scope.spawn(move || {\n                                    let done = self.process(&branch.items()[1..], &mut env, &mut mine, &mut random, identity, &mut child);\n                                    (done, child)\n                                })\n                            })\n                            .collect();\n                        running.into_iter().map(|t| t.join().unwrap_or((false, VectorClock::new()))).collect()\n                    });\n                    let mut finished = Vec::new();\n                    for (done, child) in outcomes {\n                        finished.push(done);\n                        for (p, n) in child {\n                            let mine = clock.entry(p).or_insert(0);\n                            *mine = (*mine).max(n);\n                        }\n                    }\n                    *clock.entry(me).or_insert(0) += 1;\n                    // A failed branch fails the process that ran the par.\n                    if finished.contains(&false) {\n                        return false;\n                    }\n                }\n                \"expect\" => {\n                    let name = items[1].name();\n                    let wanted = scenario_constant(&items[2]);\n                    let actual = env.get(&name);\n                    let agrees = actual\n                        .map(|a| matches!(compare_values(a, &wanted), Ok(std::cmp::Ordering::Equal)))\n                        .unwrap_or(false);\n                    if !agrees {\n                        let shown = actual.map(render).unwrap_or_else(|| \"None\".into());\n                        self.fail(format!(\"expect {name} = {} failed: {name} is {shown}\", render(&wanted)));\n                        return false;\n                    }\n                }\n                other => panic!(\"unknown scenario act {other}\"),\n            }\n        }\n        self.victim != Some((identity, acts.len()))\n    }\n}\n\n// One run of a scenario: its title, and what went wrong if anything did.\nfn run_scenario(machine: &Machine, spec: &str, shake: u64, crash: bool, network: bool) -> (String, Option<String>) {\n    let forms = read_descriptor(spec);\n    let title = forms[0].items()[1].name();\n    let names: Vec<String> = forms\n        .iter()\n        .find(|f| f.kind() == \"channels\")\n        .map(|f| f.items()[1..].iter().map(Sexp::name).collect())\n        .unwrap_or_default();\n    let body = forms.iter().find(|f| f.kind() == \"process\").map(|f| &f.items()[1..]).unwrap_or(&[]);\n    let mut symbols = Context::testing();\n    let start_args: Vec<Value> = machine.start_arguments.iter().map(|d| machine.values.minimal(d)).collect();\n    let state = match machine.start_system(&mut symbols, start_args.clone()) {\n        Ok(state) => state,\n        Err(e) => return (title, Some(format!(\"the start raised error: {e}\"))),\n    };\n    let expected = match (machine.model.start[1])(&mut symbols, start_args) {\n        Ok(expected) => expected,\n        Err(e) => return (title, Some(format!(\"the start raised error: {e}\"))),\n    };\n    // Some runs crash one process of a par before a random act.\n    let mut processes = Vec::new();\n    scenario_processes(body, &mut processes);\n    let victim = if crash && !processes.is_empty() {\n        let mut chooser = SplitMix64::new(shake ^ 0xC3A5C85C97CB3127);\n        let branch = processes[chooser.below(processes.len() as u64) as usize];\n        let acts = branch.items().len() as u64 - 1;\n        Some((branch as *const Sexp as usize, chooser.below(acts + 1) as usize))\n    } else {\n        None\n    };\n    // Network runs: loss, duplication and delay (which reorders); the\n    // channels' numbered, acknowledged frames must hide them all.\n    let wire = forms.iter().find(|f| f.kind() == \"wire\").filter(|_| network);\n    let faulty = wire.map(|_| net::MemoryNetwork::new(shake ^ 0x7F4A7C159E3779B9, 0.1, 0.1, std::time::Duration::from_millis(2)));\n    let types = Values::new(\n        wire.map(|w| w.items()[1..].iter().filter(|f| f.kind() == \"data\").map(|f| (f.items()[1].name(), f.clone())).collect())\n            .unwrap_or_default(),\n    );\n    let new_channel = |name: &String| {\n        let net = match (&faulty, wire) {\n            (Some(network), Some(w)) => w.items()[1..].iter().find(|f| f.kind() == \"channel\" && f.items()[1].name() == *name).map(|f| {\n                let steps: Vec<(bool, Sexp)> = f.items()[2..].iter().map(|s| (s.kind() == \"send\", s.items()[1].clone())).collect();\n                let nodes = [net::Node::new(network.insecure_transport_for_tests(&format!(\"{name}-0\"))), net::Node::new(network.insecure_transport_for_tests(&format!(\"{name}-1\")))];\n                let deadline = std::time::Duration::from_secs(5);\n                let first = nodes[0].listen(name, steps.clone(), types.clone(), deadline).expect(\"a fresh node\");\n                let second = nodes[1]\n                    .dial(&first.address(), steps.into_iter().map(|(s, d)| (!s, d)).collect(), types.clone(), deadline)\n                    .expect(\"a fresh node\");\n                NetChannel {\n                    nodes,\n                    ends: [first, second],\n                    done: [std::sync::atomic::AtomicBool::new(false), std::sync::atomic::AtomicBool::new(false)],\n                }\n            }),\n            _ => None,\n        };\n        ScenarioChannel {\n            state: std::sync::Mutex::new(ScenarioQueues {\n                queues: [std::collections::VecDeque::new(), std::collections::VecDeque::new()],\n                ended: [false, false],\n            }),\n            ready: std::sync::Condvar::new(),\n            net,\n        }\n    };\n    let boxes: Vec<String> = forms\n        .iter()\n        .filter(|f| f.kind() == \"mailboxes\")\n        .flat_map(|f| f.items()[1..].iter().map(Sexp::name).collect::<Vec<_>>())\n        .collect();\n    let new_mailbox = |name: &String| {\n        let net = match (&faulty, wire) {\n            (Some(network), Some(w)) => w.items()[1..].iter().find(|f| f.kind() == \"mailbox\" && f.items()[1].name() == *name).map(|f| {\n                let d = f.items()[2].clone();\n                let d = if d.kind() == \"end\" { descriptor(\"(text)\") } else { d };\n                let nodes = [\n                    net::Node::new(network.insecure_transport_for_tests(&format!(\"{name}-owner\"))),\n                    net::Node::new(network.insecure_transport_for_tests(&format!(\"{name}-senders\"))),\n                ];\n                let inbox = nodes[0].mailbox(name, d.clone(), types.clone()).expect(\"a fresh node\");\n                let remote = nodes[1].remote_mailbox_within(\n                    &format!(\"{}/{name}\", nodes[0].address()),\n                    d,\n                    types.clone(),\n                    std::time::Duration::from_secs(5),\n                );\n                NetMailbox { nodes, inbox, remote }\n            }),\n            _ => None,\n        };\n        ScenarioMailbox {\n            expected: all_sends(body, name),\n            state: std::sync::Mutex::new(MailboxState::default()),\n            ready: std::sync::Condvar::new(),\n            net,\n        }\n    };\n    let run = ScenarioRun {\n        mailboxes: boxes.iter().map(|m| (m.clone(), new_mailbox(m))).collect(),\n        machine,\n        commands: machine.commands.iter().enumerate().map(|(i, c)| (c.name.clone(), i)).collect(),\n        channels: names.iter().map(new_channel).collect(),\n        channel_numbers: names.iter().enumerate().map(|(i, n)| (n.clone(), i)).collect(),\n        channel_names: names.clone(),\n        stamps: std::sync::Mutex::new(HashMap::new()),\n        state: state.clone(),\n        shake,\n        clock: std::sync::atomic::AtomicU64::new(0),\n        history: std::sync::Mutex::new(Vec::new()),\n        failures: std::sync::Mutex::new(Vec::new()),\n        victim,\n    };\n    let finished = run.process(body, &mut HashMap::new(), &mut ScenarioEnds::new(), &mut SplitMix64::new(shake), 0, &mut VectorClock::new());\n    for channel in &run.channels {\n        if let Some(net) = &channel.net {\n            for node in &net.nodes {\n                node.close();\n            }\n        }\n    }\n    for mailbox in run.mailboxes.values() {\n        if let Some(net) = &mailbox.net {\n            for node in &net.nodes {\n                node.close();\n            }\n        }\n    }\n    if let Some(failure) = run.failures.into_inner().unwrap_or_else(|p| p.into_inner()).into_iter().next() {\n        let crashed = if victim.is_some() { \" (with a process crashed)\" } else { \"\" };\n        return (title, Some(format!(\"{failure}{crashed}\")));\n    }\n    if !finished && victim.is_none() {\n        return (title, Some(\"a process failed\".into()));\n    }\n    let history = run.history.into_inner().unwrap_or_else(|p| p.into_inner());\n    let state = match machine.system_state(&state) {\n        Ok(state) => state,\n        Err(e) => return (title, Some(format!(\"raised error: {e}\"))),\n    };\n    let fin = match machine.model.abstract_state {\n        Some(abstraction) => match abstraction(&mut symbols, vec![state.clone()]) {\n            Ok(v) => Some(v),\n            Err(e) => return (title, Some(format!(\"raised error: {e}\"))),\n        },\n        None => None,\n    };\n    if !machine.scenario_linearizes(&mut symbols, &history, expected, fin.as_ref(), &state) {\n        let mut ordered: Vec<&ScenarioCall> = history.iter().collect();\n        ordered.sort_by_key(|h| h.3);\n        let observed: Vec<String> = ordered\n            .iter()\n            .map(|(index, args, result, ..)| {\n                format!(\n                    \"{}({}) returned {}\",\n                    machine.commands[*index].name,\n                    args.iter().map(render).collect::<Vec<_>>().join(\", \"),\n                    render(result)\n                )\n            })\n            .collect();\n        return (\n            title,\n            Some(format!(\n                \"the calls are not {} with the model ({})\",\n                consistent_words(&machine.consistency),\n                observed.join(\"; \")\n            )),\n        );\n    }\n    (title, None)\n}\n\n// Whether call a returned before call b began, as far as messages tell:\n// a's return clock is at or below b's call clock everywhere.\nfn happened_before(a: &ScenarioCall, b: &ScenarioCall) -> bool {\n    a.7.iter().all(|(p, n)| b.6.get(p).copied().unwrap_or(0) >= *n)\n}\n\nimpl<'a> Machine<'a> {\n    /// A Wing-Gong search over the scenario's calls, memoized on the calls\n    /// done and the state. Linearizable: next, a call no pending call\n    /// returned before (real time). Sequential: next, a call every call that\n    /// happened before it (its process's order, and messages) is done.\n    /// Causal: each process's results from an order of what happened before\n    /// them. Eventual: no results, only the final state.\n    fn scenario_linearizes(\n        &self,\n        ctx: &mut Context,\n        history: &[ScenarioCall],\n        expected: Value,\n        fin: Option<&Value>,\n        state: &Value,\n    ) -> bool {\n        let everything: Vec<usize> = (0..history.len()).collect();\n        if self.consistency == \"causal\" {\n            let mut processes: Vec<usize> = history.iter().map(|h| h.5).collect();\n            processes.sort_unstable();\n            processes.dedup();\n            for process in processes {\n                let own: Vec<usize> = everything.iter().copied().filter(|i| history[*i].5 == process).collect();\n                let members: Vec<usize> = everything\n                    .iter()\n                    .copied()\n                    .filter(|j| own.contains(j) || own.iter().any(|i| i != j && happened_before(&history[*j], &history[*i])))\n                    .collect();\n                let checked: std::collections::HashSet<usize> = own.into_iter().collect();\n                let mut seen = std::collections::HashSet::new();\n                if !self.scenario_visit(ctx, history, &members, &checked, false, &mut seen, Vec::new(), expected.clone(), fin, state) {\n                    return false;\n                }\n            }\n            return true;\n        }\n        let checked: std::collections::HashSet<usize> =\n            if self.consistency == \"eventual\" { Default::default() } else { everything.iter().copied().collect() };\n        let mut seen = std::collections::HashSet::new();\n        self.scenario_visit(ctx, history, &everything, &checked, true, &mut seen, Vec::new(), expected, fin, state)\n    }\n\n    fn before(&self, history: &[ScenarioCall], j: usize, i: usize) -> bool {\n        if self.consistency == \"linearizable\" {\n            history[j].4 < history[i].3\n        } else {\n            happened_before(&history[j], &history[i])\n        }\n    }\n\n    #[allow(clippy::too_many_arguments)]\n    fn scenario_visit(\n        &self,\n        ctx: &mut Context,\n        history: &[ScenarioCall],\n        members: &[usize],\n        checked: &std::collections::HashSet<usize>,\n        judge_final: bool,\n        seen: &mut std::collections::HashSet<(Vec<usize>, String)>,\n        done: Vec<usize>,\n        model_state: Value,\n        fin: Option<&Value>,\n        state: &Value,\n    ) -> bool {\n        let mut key = done.clone();\n        key.sort_unstable();\n        if !seen.insert((key, render(&model_state))) {\n            return false;\n        }\n        if done.len() == members.len() {\n            if !judge_final {\n                return true;\n            }\n            if let Some(fin) = fin {\n                if !matches!(compare_values(fin, &model_state), Ok(std::cmp::Ordering::Equal)) {\n                    return false;\n                }\n            }\n            return self.invariants.iter().all(|(kind, invariant)| {\n                let subject = if kind == \"model\" { &model_state } else { state };\n                matches!(invariant(ctx, vec![subject.clone()]).and_then(|v| v.boolean()), Ok(true))\n            });\n        }\n        for &i in members {\n            if done.contains(&i) {\n                continue;\n            }\n            if members.iter().any(|&j| j != i && !done.contains(&j) && self.before(history, j, i)) {\n                continue;\n            }\n            let (index, args, result) = (&history[i].0, &history[i].1, &history[i].2);\n            let command = &self.commands[*index];\n            let (after, wanted) = match step_model(command, ctx, args, model_state.clone()) {\n                Ok(stepped) => stepped,\n                Err(ModelFault::Invalid) => continue,\n                Err(ModelFault::Error(e)) => panic!(\"model {}: {e}\", self.name),\n            };\n            if checked.contains(&i) && !command.unit && !matches!(compare_values(result, &wanted), Ok(std::cmp::Ordering::Equal)) {\n                continue;\n            }\n            let mut next = done.clone();\n            next.push(i);\n            if self.scenario_visit(ctx, history, members, checked, judge_final, seen, next, after, fin, state) {\n                return true;\n            }\n        }\n        false\n    }\n}\n\n/// Runs a scenario on many schedules (30 runs, seeded by LAWSPEC_SEED);\n/// a failure names the scenario and what went wrong.\npub fn check_scenario(model: &Model, spec: &str) -> std::result::Result<(), String> {\n    let seed = std::env::var(\"LAWSPEC_SEED\").ok().and_then(|s| s.trim().parse::<u64>().ok()).unwrap_or(0);\n    let machine = Machine::new(model);\n    let mut random = SplitMix64::new(seed ^ 0x2545F4914F6CDD1D);\n    for run in 0..30 {\n        // Every third run crashes one process of a par at a random point, and\n        // every third other one sends each channel over a faulty network.\n        let (title, failure) = run_scenario(&machine, spec, random.next(), run % 3 == 2, run % 3 == 1);\n        if let Some(failure) = failure {\n            return Err(format!(\"scenario {title} fails: {failure}\"));\n        }\n    }\n    Ok(())\n}\n\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    fn int(n: i64) -> Value {\n        Value::Integer(n.into())\n    }\n    fn decimal(c: i64, e: i64) -> Value {\n        Value::Decimal(Decimal::new(c.into(), e.into()))\n    }\n    #[test]\n    fn data_bridges_check_constructor_identity_arity_and_typed_fields() {\n        let tag = \"example::type::Pair::Pair\";\n        let value = construct_data(tag, vec![int(127), Value::Bool(true)]);\n        let fields = data_fields(value.clone(), tag, 2).unwrap();\n        assert_eq!(i8::from_value(fields[0].clone()).unwrap(), 127);\n        assert!(data_fields(value.clone(), \"other::type::Pair::Pair\", 2).is_err());\n        assert!(data_fields(value.clone(), tag, 1).is_err());\n        assert!(data_fields(value, tag, 3).is_err());\n        assert!(data_fields(Value::List(vec![]), tag, 0).is_err());\n        let overflow = data_fields(construct_data(tag, vec![int(128)]), tag, 1).unwrap();\n        assert!(i8::from_value(overflow[0].clone()).is_err());\n    }\n\n    #[test]\n    fn data_equality_preserves_ieee_and_constructor_semantics() {\n        let tag = \"example::type::Box::Box\";\n        let boxed = |value| construct_data(tag, vec![value]);\n        let nan = boxed(Value::List(vec![Value::Float32(f32::NAN)]));\n        assert!(!equal(&nan, &nan).unwrap());\n        assert!(equal(&boxed(Value::Float64(-0.0)), &boxed(Value::Float64(0.0))).unwrap());\n        assert!(!equal(&boxed(int(1)), &construct_data(tag, vec![int(1), int(2)])).unwrap());\n        assert!(\n            !equal(\n                &boxed(int(1)),\n                &construct_data(\"example::type::Other::Box\", vec![int(1)])\n            )\n            .unwrap()\n        );\n        assert!(equal(&boxed(int(1)), &boxed(Value::Float64(1.0))).is_err());\n    }\n\n    #[test]\n    fn nested_data_keeps_absence_raw_units_and_symbol_identity() {\n        let tag = \"example::type::Record::Record\";\n        let symbol = Symbol::new(\"same description\".into());\n        let record = |symbol| {\n            construct_data(\n                tag,\n                vec![\n                    Value::Maybe(Some(Box::new(Value::Maybe(None)))),\n                    Value::Utf16Text(vec![0xd800, 0, 0xdfff]),\n                    Value::Bytes(vec![0, 0xff]),\n                    Value::Symbol(symbol),\n                ],\n            )\n        };\n        let original = record(symbol.clone());\n        assert!(equal(&original, &record(symbol)).unwrap());\n        assert!(!equal(&original, &record(Symbol::new(\"same description\".into()))).unwrap());\n        let mut fields = data_fields(original.clone(), tag, 4).unwrap();\n        fields[0] = Value::Maybe(None);\n        assert!(!equal(&original, &construct_data(tag, fields)).unwrap());\n    }\n\n    #[test]\n    fn integer_promotion_and_checked_bridges() {\n        let result = binary(\"+\", \"Integer\", 127i8.into_value(), int(1)).unwrap();\n        assert_eq!(result, int(128));\n        assert!(i8::from_value(result).is_err());\n        assert_eq!(\n            u64::from_value(Value::Integer(u64::MAX.into())).unwrap(),\n            u64::MAX\n        );\n        assert_eq!(Integer::from(u128::MAX).0, BigInt::from(u128::MAX));\n        assert!(u64::from_value(int(-1)).is_err());\n        assert!(i32::from_value(Value::Rational(BigRational::new(1.into(), 2.into()))).is_err());\n    }\n    #[test]\n    fn exact_decimal_and_rational_arithmetic() {\n        assert!(\n            equal(\n                &binary(\"+\", \"Decimal\", decimal(1, -1), decimal(2, -1)).unwrap(),\n                &decimal(3, -1)\n            )\n            .unwrap()\n        );\n        let half = binary(\"/\", \"Rational\", int(1), int(2)).unwrap();\n        assert_eq!(half, Value::Rational(BigRational::new(1.into(), 2.into())));\n        assert!(binary(\"/\", \"Rational\", int(1), int(0)).is_err());\n        assert!(\n            Value::Rational(BigRational::new(1.into(), 3.into()))\n                .convert(\"Decimal\", 64)\n                .is_err()\n        );\n        assert_eq!(binary(\"quot\", \"Integer\", int(-7), int(3)).unwrap(), int(-2));\n        assert_eq!(binary(\"rem\", \"Integer\", int(-7), int(3)).unwrap(), int(-1));\n    }\n    #[test]\n    fn decimal_rounds_half_even_at_requested_scale() {\n        for (numerator, expected) in [(125, 12), (135, 14), (-125, -12), (-135, -14)] {\n            let d = Decimal::round(BigRational::new(numerator.into(), 100.into()), 1).unwrap();\n            assert!(equal(&Value::Decimal(d), &decimal(expected, -1)).unwrap());\n        }\n        let hundred = Decimal::round(BigRational::from_integer(250.into()), -2).unwrap();\n        assert!(equal(&Value::Decimal(hundred), &int(200)).unwrap());\n    }\n    #[test]\n    fn ieee_equality_classification_and_precision() {\n        assert!(binary(\"+\", \"Float32\", int(1), Value::Float32(1.0)).is_err());\n        assert!(equal(&int(1), &Value::Float32(1.0)).is_err());\n        assert!(!equal(&Value::Float32(f32::NAN), &Value::Float32(f32::NAN)).unwrap());\n        assert!(equal(&Value::Float64(0.0), &Value::Float64(-0.0)).unwrap());\n        assert_eq!(\n            helper(\"isNegativeZero\", vec![Value::Float32(-0.0)]).unwrap(),\n            Value::Bool(true)\n        );\n        assert_eq!(\n            binary(\n                \"+\",\n                \"Float32\",\n                Value::Float32(16777216.0),\n                Value::Float32(1.0)\n            )\n            .unwrap(),\n            Value::Float32(16777216.0)\n        );\n        assert_eq!(\n            binary(\"/\", \"Float64\", Value::Float64(1.0), Value::Float64(0.0)).unwrap(),\n            Value::Float64(f64::INFINITY)\n        );\n        assert!(\n            Value::Float64(f64::INFINITY)\n                .convert(\"Integer\", 64)\n                .is_err()\n        );\n        assert_eq!(\n            Value::Float64(0.5).convert(\"Rational\", 64).unwrap(),\n            Value::Rational(BigRational::new(1.into(), 2.into()))\n        );\n    }\n    #[test]\n    fn nested_code_units_cross_native_bridges_without_losing_the_domain() {\n        let native: Optional<Nullable<u16>> = Optional::Present(Nullable::Present(0xd800));\n        let value = validate(\n            native.clone().into_value(),\n            \"Optional Nullable CodeUnit16\",\n            64,\n        )\n        .unwrap();\n        assert_eq!(\n            value,\n            Value::Optional(Some(Box::new(Value::Nullable(Some(Box::new(\n                Value::CodeUnit16(0xd800)\n            ))))))\n        );\n        let round_trip = Optional::<Nullable<u16>>::from_value(\n            native_value(value, \"Optional Nullable CodeUnit16\").unwrap(),\n        )\n        .unwrap();\n        assert_eq!(round_trip, native);\n        assert!(validate(Value::CodePoint(0x110000), \"CodePoint\", 64).is_err());\n    }\n    #[test]\n    fn exact_float_conversion_avoids_double_rounding() {\n        let n = BigInt::parse_bytes(b\"1208925891672223212634113\", 10).unwrap();\n        let d = BigInt::parse_bytes(b\"1208925819614629174706176\", 10).unwrap();\n        assert_eq!(\n            exact_float_bits(&BigRational::new(n, d), true).unwrap(),\n            0x3f800001\n        );\n        assert_eq!(\n            exact_float_bits(&BigRational::new(16777217.into(), 16777216.into()), true).unwrap(),\n            0x3f800000\n        );\n        assert_eq!(\n            exact_float_bits(&BigRational::new(1.into(), BigInt::one() << 150usize), true).unwrap(),\n            0\n        );\n        assert_eq!(\n            exact_float_bits(\n                &BigRational::new((-1).into(), BigInt::one() << 150usize),\n                true\n            )\n            .unwrap(),\n            0x80000000\n        );\n        assert_eq!(\n            exact_float_bits(\n                &BigRational::from_integer(BigInt::one() << 1024usize),\n                false\n            )\n            .unwrap(),\n            f64::INFINITY.to_bits()\n        );\n    }\n    #[test]\n    fn raw_text_symbols_and_nested_presence_remain_distinct() {\n        let raw = Utf16Text(vec![0xd800, 0, 0xdc00]);\n        assert_eq!(\n            Utf16Text::from_value(raw.clone().into_value()).unwrap(),\n            raw\n        );\n        assert!(CodePoint::from_value(Value::CodePoint(0xd800)).is_ok());\n        assert!(CodePoint::from_value(Value::CodePoint(0x110000)).is_err());\n        let mut context = Context::default();\n        assert_eq!(context.symbol(\"a\", \"same\"), context.symbol(\"a\", \"same\"));\n        assert_ne!(context.symbol(\"a\", \"same\"), context.symbol(\"b\", \"same\"));\n        let absent: Optional<Nullable<i8>> = Optional::Undefined;\n        let null: Optional<Nullable<i8>> = Optional::Present(Nullable::Null);\n        let some: Optional<Nullable<i8>> = Optional::Present(Nullable::Present(0));\n        assert_ne!(absent.clone().into_value(), null.clone().into_value());\n        assert_ne!(null.clone().into_value(), some.clone().into_value());\n        for x in [absent, null, some] {\n            assert_eq!(\n                Optional::<Nullable<i8>>::from_value(x.clone().into_value()).unwrap(),\n                x\n            );\n        }\n    }\n}\n\n/// Checks a value an adapter produced against its declared domain: native code\n/// may return anything its own type allows, and a law quantifies only over the\n/// declared domain. ref:DEC-portable-exact-arithmetic\npub fn validate(value: Value, name: &str, bits: u32) -> Result<Value> {\n    if let Some(inner) = name.strip_prefix(\"List \") {\n        return match value {\n            Value::List(values) => Ok(Value::List(\n                values\n                    .into_iter()\n                    .map(|x| validate(x, inner, bits))\n                    .collect::<Result<_>>()?,\n            )),\n            _ => Err(\"expected List\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Maybe \") {\n        return match value {\n            Value::Maybe(value) => Ok(Value::Maybe(\n                value\n                    .map(|x| validate(*x, inner, bits).map(Box::new))\n                    .transpose()?,\n            )),\n            _ => Err(\"expected Maybe\".into()),\n        };\n    }\n    if let Some(arguments) = name.strip_prefix(\"Either \") {\n        let (left, right) = either_types(arguments)?;\n        return match value {\n            Value::Left(x) => Ok(Value::Left(Box::new(validate(*x, left, bits)?))),\n            Value::Right(x) => Ok(Value::Right(Box::new(validate(*x, right, bits)?))),\n            _ => Err(\"expected Either\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Nullable \") {\n        return match value {\n            Value::Nullable(None) => Ok(Value::Nullable(None)),\n            Value::Nullable(Some(x)) => {\n                Ok(Value::Nullable(Some(Box::new(validate(*x, inner, bits)?))))\n            }\n            _ => Err(\"expected Nullable\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Optional \") {\n        return match value {\n            Value::Optional(None) => Ok(Value::Optional(None)),\n            Value::Optional(Some(x)) => {\n                Ok(Value::Optional(Some(Box::new(validate(*x, inner, bits)?))))\n            }\n            _ => Err(\"expected Optional\".into()),\n        };\n    }\n    if name == \"Bytes\" {\n        if let Value::List(values) = value {\n            return Ok(Value::Bytes(\n                values\n                    .into_iter()\n                    .map(u8::from_value)\n                    .collect::<Result<_>>()?,\n            ));\n        }\n    }\n    if name == \"CodeUnit16\" {\n        return match value {\n            Value::CodeUnit16(x) => Ok(Value::CodeUnit16(x)),\n            x => Ok(Value::CodeUnit16(u16::from_value(x)?)),\n        };\n    }\n    let valid = match (&value, name) {\n        (Value::Integer(_), _) => return value.convert(name, bits),\n        (Value::Decimal(d), \"Decimal\") => {\n            d.ratio()?;\n            true\n        }\n        (Value::Rational(_), \"Rational\")\n        | (Value::Float32(_), \"Float32\")\n        | (Value::Float64(_), \"Float64\")\n        | (Value::Complex32(_), \"Complex64\")\n        | (Value::Complex64(_), \"Complex128\")\n        | (Value::Bool(_), \"Bool\")\n        | (Value::Char(_), \"Char\")\n        | (Value::CodeUnit16(_), \"CodeUnit16\")\n        | (Value::Text(_), \"Text\")\n        | (Value::Bytes(_), \"Bytes\")\n        | (Value::Utf16Text(_), \"Utf16Text\")\n        | (Value::Symbol(_), \"Symbol\")\n        | (Value::Unit, \"Unit\")\n        | (Value::Null, \"Null\")\n        | (Value::Undefined, \"Undefined\") => true,\n        (Value::CodePoint(c), \"CodePoint\") => *c <= 0x10ffff,\n        (Value::CodePointText(cs), \"CodePointText\") => cs.iter().all(|c| *c <= 0x10ffff),\n        _ => false,\n    };\n    if valid {\n        Ok(value)\n    } else {\n        Err(format!(\"invalid {name} representation returned by adapter\"))\n    }\n}\n\n/// Type-directed native bridge for nested domains that share a Rust primitive.\npub fn native_value(value: Value, name: &str) -> Result<Value> {\n    if let Some(inner) = name.strip_prefix(\"List \") {\n        return match value {\n            Value::List(values) => Ok(Value::List(\n                values\n                    .into_iter()\n                    .map(|x| native_value(x, inner))\n                    .collect::<Result<_>>()?,\n            )),\n            _ => Err(\"expected List\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Maybe \") {\n        return match value {\n            Value::Maybe(value) => Ok(Value::Maybe(\n                value\n                    .map(|x| native_value(*x, inner).map(Box::new))\n                    .transpose()?,\n            )),\n            _ => Err(\"expected Maybe\".into()),\n        };\n    }\n    if let Some(arguments) = name.strip_prefix(\"Either \") {\n        let (left, right) = either_types(arguments)?;\n        return match value {\n            Value::Left(x) => Ok(Value::Left(Box::new(native_value(*x, left)?))),\n            Value::Right(x) => Ok(Value::Right(Box::new(native_value(*x, right)?))),\n            _ => Err(\"expected Either\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Nullable \") {\n        return match value {\n            Value::Nullable(Some(x)) => {\n                Ok(Value::Nullable(Some(Box::new(native_value(*x, inner)?))))\n            }\n            Value::Nullable(None) => Ok(Value::Nullable(None)),\n            _ => Err(\"expected Nullable\".into()),\n        };\n    }\n    if let Some(inner) = name.strip_prefix(\"Optional \") {\n        return match value {\n            Value::Optional(Some(x)) => {\n                Ok(Value::Optional(Some(Box::new(native_value(*x, inner)?))))\n            }\n            Value::Optional(None) => Ok(Value::Optional(None)),\n            _ => Err(\"expected Optional\".into()),\n        };\n    }\n    match (value, name) {\n        (Value::CodeUnit16(x), \"CodeUnit16\") => Ok(Value::Integer(x.into())),\n        (v, _) => Ok(v),\n    }\n}\n\n#[cfg(test)]\nmod handle_tests {\n    use super::*;\n\n    #[test]\n    fn handles_are_equal_by_identity_and_have_no_order() {\n        let a = Value::Handle(Handle::new(std::sync::Mutex::new(vec![1i32])));\n        let b = Value::Handle(Handle::new(std::sync::Mutex::new(vec![1i32])));\n        assert!(equal(&a, &a.clone()).unwrap());\n        assert!(!equal(&a, &b).unwrap());\n        assert_eq!(compare_values(&a, &a.clone()).unwrap(), std::cmp::Ordering::Equal);\n        assert!(compare_values(&a, &b).unwrap_err().contains(\"no portable order\"));\n        fn send<T: Send + Sync>(_: &T) {}\n        send(&a);\n    }\n\n    #[test]\n    fn a_schema_names_and_passes_handles() {\n        let schema = Schema::new(vec![DataSchema { name: \"unit::type::Jobs\", parameters: 0, constructors: vec![] }])\n            .unwrap()\n            .with_handles(&[\"unit::type::Jobs\"]);\n        let ty = TypeRef::named(\"unit::type::Jobs\", vec![]);\n        let handle = Handle::new(7i32);\n        let checked = schema.validate(Value::Handle(handle.clone()), &ty, 64).unwrap();\n        assert_eq!(checked, Value::Handle(handle.clone()));\n        assert!(render(&checked).starts_with(\"Jobs#\"));\n        assert_eq!(render(&checked), render(&Value::Handle(handle.clone())));\n        assert_eq!(*handle.native::<i32>().unwrap(), 7);\n        assert!(handle.native::<String>().is_err());\n        assert!(schema.validate(Value::Unit, &ty, 64).is_err());\n    }\n}\n\n#[cfg(test)]\nmod collection_tests {\n    use super::*;\n\n    #[test]\n    fn nested_collections_preserve_code_units_and_bytes() {\n        let native: Vec<Option<Either<u16, Vec<u8>>>> = vec![\n            None,\n            Some(Either::Left(0xd800)),\n            Some(Either::Right(vec![0, 255])),\n        ];\n        let domain = \"List Maybe Either CodeUnit16 Bytes\";\n        let value = validate(native.clone().into_value(), domain, 64).unwrap();\n        let Value::List(ref items) = value else {\n            panic!(\"expected List\");\n        };\n        assert_eq!(items[0], Value::Maybe(None));\n        assert_eq!(\n            items[1],\n            Value::Maybe(Some(Box::new(Value::Left(Box::new(Value::CodeUnit16(\n                0xd800\n            ))))))\n        );\n        assert_eq!(\n            items[2],\n            Value::Maybe(Some(Box::new(Value::Right(Box::new(Value::Bytes(vec![\n                0, 255\n            ]))))))\n        );\n        let actual =\n            Vec::<Option<Either<u16, Vec<u8>>>>::from_value(native_value(value, domain).unwrap())\n                .unwrap();\n        assert_eq!(actual, native);\n    }\n\n    #[test]\n    fn structural_equality_preserves_tags_ieee_rules_and_length() {\n        let nan = Value::List(vec![Value::Float32(f32::NAN)]);\n        assert!(!equal(&nan, &nan).unwrap());\n        assert!(\n            equal(\n                &Value::List(vec![Value::Float64(-0.0)]),\n                &Value::List(vec![Value::Float64(0.0)])\n            )\n            .unwrap()\n        );\n        assert!(\n            !equal(\n                &Value::Left(Box::new(Value::Bool(true))),\n                &Value::Right(Box::new(Value::Bool(true)))\n            )\n            .unwrap()\n        );\n        assert!(!equal(&Value::List(vec![]), &Value::List(vec![Value::Unit])).unwrap());\n        assert!(\n            !equal(\n                &Value::Maybe(None),\n                &Value::Maybe(Some(Box::new(Value::Maybe(None))))\n            )\n            .unwrap()\n        );\n    }\n\n    #[test]\n    fn collection_domains_reject_bad_payloads_and_do_not_collapse_presence() {\n        assert!(\n            validate(\n                Value::List(vec![Value::Integer(128.into())]),\n                \"List Int8\",\n                64\n            )\n            .is_err()\n        );\n        assert!(validate(Value::Nullable(None), \"Maybe Bool\", 64).is_err());\n        assert!(validate(Value::Maybe(None), \"Nullable Bool\", 64).is_err());\n        assert!(\n            validate(\n                Value::Left(Box::new(Value::Bool(true))),\n                \"Either Int8 Bool\",\n                64\n            )\n            .is_err()\n        );\n        assert!(construct(\"List::Cons\", vec![Value::Bool(true), Value::Bool(false)]).is_err());\n        assert_eq!(\n            validate(vec![0u8, 255].into_value(), \"Bytes\", 64).unwrap(),\n            Value::Bytes(vec![0, 255])\n        );\n        assert!(matches!(\n            validate(vec![0u8, 255].into_value(), \"List UInt8\", 64).unwrap(),\n            Value::List(_)\n        ));\n        assert_eq!(\n            either_types(\"Either Bool Unit List Maybe Int8\").unwrap(),\n            (\"Either Bool Unit\", \"List Maybe Int8\")\n        );\n    }\n}\n\n#[cfg(test)]\nmod schema_tests {\n    use super::*;\n\n    fn ty(name: &'static str) -> TypeRef {\n        TypeRef::named(name, vec![])\n    }\n\n    fn box_type(element: TypeRef) -> TypeRef {\n        TypeRef::named(\"example::Box\", vec![element])\n    }\n\n    fn schema() -> Schema {\n        Schema::new(vec![\n            DataSchema {\n                name: \"example::Box\",\n                parameters: 1,\n                constructors: vec![ConstructorSchema {\n                    tag: \"example::Box::Box\",\n                    fields: vec![TypeRef::Parameter(0)],\n                }],\n            },\n            DataSchema {\n                name: \"example::Tree\",\n                parameters: 1,\n                constructors: vec![\n                    ConstructorSchema {\n                        tag: \"example::Tree::Leaf\",\n                        fields: vec![TypeRef::Parameter(0)],\n                    },\n                    ConstructorSchema {\n                        tag: \"example::Tree::Branch\",\n                        fields: vec![TypeRef::named(\n                            \"List\",\n                            vec![TypeRef::named(\"example::Tree\", vec![TypeRef::Parameter(0)])],\n                        )],\n                    },\n                ],\n            },\n        ])\n        .unwrap()\n    }\n\n    #[test]\n    fn validates_recursive_instantiated_fields_and_reports_the_payload_path() {\n        let schema = schema();\n        let tree = TypeRef::named(\"example::Tree\", vec![ty(\"Int8\")]);\n        let value = |integer: i64| {\n            construct_data(\n                \"example::Tree::Branch\",\n                vec![Value::List(vec![construct_data(\n                    \"example::Tree::Leaf\",\n                    vec![Value::Integer(integer.into())],\n                )])],\n            )\n        };\n        assert_eq!(schema.validate(value(127), &tree, 64).unwrap(), value(127));\n        let error = schema.validate(value(128), &tree, 64).unwrap_err();\n        assert!(error.contains(\"example::Tree::Branch field 0\"));\n        assert!(error.contains(\"List element 0\"));\n        assert!(error.contains(\"example::Tree::Leaf field 0\"));\n        assert!(\n            schema\n                .validate(\n                    construct_data(\"example::Box::Box\", vec![Value::Integer(1.into())]),\n                    &tree,\n                    64,\n                )\n                .is_err()\n        );\n        assert!(\n            schema\n                .validate(construct_data(\"example::Tree::Leaf\", vec![]), &tree, 64)\n                .is_err()\n        );\n    }\n\n    #[test]\n    fn preserves_nested_raw_domains_across_native_bridges() {\n        let schema = schema();\n        let element = box_type(ty(\"CodeUnit16\"));\n        let logical = TypeRef::named(\"Maybe\", vec![TypeRef::named(\"List\", vec![element])]);\n        let value = Value::Maybe(Some(Box::new(Value::List(vec![construct_data(\n            \"example::Box::Box\",\n            vec![Value::CodeUnit16(0xd800)],\n        )]))));\n        let native = schema.native_value(value.clone(), &logical, 64).unwrap();\n        assert_ne!(value, native);\n        assert_eq!(schema.validate(native, &logical, 64).unwrap(), value);\n        let bytes = box_type(ty(\"Bytes\"));\n        let native_bytes = construct_data(\"example::Box::Box\", vec![vec![0u8, 255u8].into_value()]);\n        assert_eq!(\n            schema.validate(native_bytes, &bytes, 64).unwrap(),\n            construct_data(\"example::Box::Box\", vec![Value::Bytes(vec![0, 255])])\n        );\n        assert!(schema.validate(Value::Maybe(None), &logical, 64).is_ok());\n    }\n\n    #[test]\n    fn checks_machine_width_and_scalar_domains_inside_user_values() {\n        let schema = schema();\n        let value = construct_data(\n            \"example::Box::Box\",\n            vec![Value::Integer((1u64 << 32).into())],\n        );\n        let target = box_type(ty(\"UIntSize\"));\n        assert!(schema.validate(value.clone(), &target, 32).is_err());\n        assert!(schema.validate(value.clone(), &target, 64).is_ok());\n        assert!(schema.validate(value.clone(), &target, 16).is_err());\n        assert!(schema.native_value(value, &target, 16).is_err());\n        assert!(\n            schema\n                .validate(\n                    construct_data(\"example::Box::Box\", vec![Value::Float32(1.0)]),\n                    &box_type(ty(\"Int8\")),\n                    64,\n                )\n                .is_err()\n        );\n    }\n\n    #[test]\n    fn rejects_corrupt_schemas_and_unapplied_types() {\n        let definition = |name, field| DataSchema {\n            name,\n            parameters: 1,\n            constructors: vec![ConstructorSchema {\n                tag: \"unique::Tag\",\n                fields: vec![field],\n            }],\n        };\n        assert!(Schema::new(vec![definition(\"Bad\", TypeRef::Parameter(1))]).is_err());\n        assert!(Schema::new(vec![definition(\"Bad\", ty(\"Unknown\"))]).is_err());\n        assert!(Schema::new(vec![definition(\"Bad\", ty(\"Maybe\"))]).is_err());\n        assert!(Schema::new(vec![definition(\"Bool\", TypeRef::Parameter(0))]).is_err());\n        assert!(\n            Schema::new(vec![\n                definition(\"First\", TypeRef::Parameter(0)),\n                definition(\"Second\", TypeRef::Parameter(0)),\n            ])\n            .is_err()\n        );\n        let schema = schema();\n        let value = construct_data(\"example::Box::Box\", vec![Value::Bool(true)]);\n        assert!(\n            schema\n                .validate(value.clone(), &ty(\"example::Box\"), 64)\n                .is_err()\n        );\n        assert!(schema.validate(value, &TypeRef::Parameter(0), 64).is_err());\n    }\n}\n\n#[cfg(test)]\nmod constructor_contract_tests {\n    use super::*;\n\n    fn ty(name: &'static str) -> TypeRef {\n        TypeRef::named(name, vec![])\n    }\n\n    fn schema(predicates: Vec<FieldPredicate>, element: &'static str) -> Schema {\n        Schema::with_contracts(\n            vec![DataSchema {\n                name: \"Box\",\n                parameters: 1,\n                constructors: vec![ConstructorSchema {\n                    tag: \"Box::Box\",\n                    fields: vec![TypeRef::Parameter(0)],\n                }],\n            }],\n            vec![ConstructorContract {\n                tag: \"Box::Box\",\n                predicates,\n            }],\n        )\n        .and_then(|schema| {\n            schema.check_type(&TypeRef::named(\"Box\", vec![ty(element)]), 0)?;\n            Ok(schema)\n        })\n        .unwrap()\n    }\n\n    fn value(field: Value) -> Value {\n        construct_data(\"Box::Box\", vec![field])\n    }\n\n    fn positive(\n        _: &Schema,\n        arguments: &[TypeRef],\n        fields: &[Value],\n        bits: u32,\n        _: &mut Context,\n    ) -> Result<bool> {\n        assert_eq!(arguments, &[ty(\"IntSize\")]);\n        assert!(matches!(bits, 32 | 64));\n        let [Value::Integer(n)] = fields else {\n            return Err(\"expected logical integer\".into());\n        };\n        Ok(n > &BigInt::zero())\n    }\n\n    #[test]\n    fn contracts_check_native_and_logical_boundaries_at_both_widths() {\n        let schema = schema(vec![positive], \"IntSize\");\n        let ty = TypeRef::named(\"Box\", vec![ty(\"IntSize\")]);\n        for bits in [32, 64] {\n            let good = value(Value::Integer(1.into()));\n            let bad = value(Value::Integer(0.into()));\n            assert_eq!(schema.validate(good.clone(), &ty, bits).unwrap(), good);\n            assert_eq!(schema.native_value(good.clone(), &ty, bits).unwrap(), good);\n            assert!(schema.validate(bad.clone(), &ty, bits).is_err());\n            assert!(schema.native_value(bad.clone(), &ty, bits).is_err());\n            assert!(matches!(\n                schema\n                    .check_with_context(bad, &ty, bits, &mut Context::default())\n                    .unwrap(),\n                ValueCheck::Rejected(_)\n            ));\n        }\n        let large = value(Value::Integer(BigInt::from(1u64 << 40)));\n        assert!(schema.validate(large.clone(), &ty, 32).is_err());\n        assert!(schema.validate(large, &ty, 64).is_ok());\n    }\n\n    #[test]\n    fn predicates_short_circuit_and_do_not_hide_evaluator_errors() {\n        fn reject(_: &Schema, _: &[TypeRef], _: &[Value], _: u32, _: &mut Context) -> Result<bool> {\n            Ok(false)\n        }\n        fn broken(_: &Schema, _: &[TypeRef], _: &[Value], _: u32, _: &mut Context) -> Result<bool> {\n            Err(\"broken predicate\".into())\n        }\n        let ty = TypeRef::named(\"Box\", vec![ty(\"Bool\")]);\n        let good = value(Value::Bool(true));\n        assert!(matches!(\n            schema(vec![reject, broken], \"Bool\")\n                .check_with_context(good.clone(), &ty, 64, &mut Context::default())\n                .unwrap(),\n            ValueCheck::Rejected(_)\n        ));\n        let error = schema(vec![broken], \"Bool\")\n            .check_with_context(good, &ty, 64, &mut Context::default())\n            .unwrap_err();\n        assert!(error.contains(\"field refinement 1: broken predicate\"));\n        assert!(\n            schema(vec![reject], \"Bool\")\n                .check_with_context(\n                    value(Value::Text(\"wrong\".into())),\n                    &ty,\n                    64,\n                    &mut Context::default()\n                )\n                .is_err()\n        );\n    }\n\n    #[test]\n    fn native_code_unit_conversion_follows_contract_validation() {\n        fn surrogate(\n            _: &Schema,\n            _: &[TypeRef],\n            fields: &[Value],\n            _: u32,\n            _: &mut Context,\n        ) -> Result<bool> {\n            match fields {\n                [Value::CodeUnit16(value)] => Ok(*value == 0xd800),\n                _ => Err(\"predicate must receive a logical code unit\".into()),\n            }\n        }\n        let schema = schema(vec![surrogate], \"CodeUnit16\");\n        let ty = TypeRef::named(\"Box\", vec![ty(\"CodeUnit16\")]);\n        let logical = value(Value::CodeUnit16(0xd800));\n        let native = schema.native_value(logical.clone(), &ty, 64).unwrap();\n        assert_eq!(native, value(Value::Integer(0xd800.into())));\n        assert_eq!(schema.validate(native, &ty, 64).unwrap(), logical);\n        assert!(\n            schema\n                .native_value(value(Value::CodeUnit16(0)), &ty, 64)\n                .is_err()\n        );\n    }\n\n    #[test]\n    fn nested_symbols_share_context_and_keep_rejection_paths() {\n        fn fixture(\n            _: &Schema,\n            _: &[TypeRef],\n            fields: &[Value],\n            _: u32,\n            context: &mut Context,\n        ) -> Result<bool> {\n            equal(\n                &fields[0],\n                &Value::Symbol(context.symbol(\"fixture\", \"same\")),\n            )\n        }\n        let schema = schema(vec![fixture], \"Symbol\");\n        let mut context = Context::default();\n        let box_type = TypeRef::named(\"Box\", vec![ty(\"Symbol\")]);\n        let expected = value(Value::Symbol(context.symbol(\"fixture\", \"same\")));\n        let cases = vec![\n            (\n                TypeRef::named(\"List\", vec![box_type.clone()]),\n                Value::List(vec![expected.clone()]),\n            ),\n            (\n                TypeRef::named(\"Maybe\", vec![box_type.clone()]),\n                Value::Maybe(Some(Box::new(expected.clone()))),\n            ),\n            (\n                TypeRef::named(\"Nullable\", vec![box_type.clone()]),\n                Value::Nullable(Some(Box::new(expected.clone()))),\n            ),\n            (\n                TypeRef::named(\"Optional\", vec![box_type.clone()]),\n                Value::Optional(Some(Box::new(expected.clone()))),\n            ),\n            (\n                TypeRef::named(\"Either\", vec![box_type.clone(), box_type.clone()]),\n                Value::Right(Box::new(expected.clone())),\n            ),\n        ];\n        for (ty, logical) in cases {\n            let native = schema\n                .native_value_with_context(logical.clone(), &ty, 64, &mut context)\n                .unwrap();\n            let restored = schema\n                .validate_with_context(native, &ty, 64, &mut context)\n                .unwrap();\n            assert!(equal(&logical, &restored).unwrap());\n            assert!(matches!(\n                schema\n                    .check_with_context(logical, &ty, 64, &mut Context::default())\n                    .unwrap(),\n                ValueCheck::Rejected(_)\n            ));\n        }\n        let list = TypeRef::named(\"List\", vec![box_type.clone()]);\n        let outcome = schema\n            .check_with_context(\n                Value::List(vec![expected]),\n                &list,\n                64,\n                &mut Context::default(),\n            )\n            .unwrap();\n        let ValueCheck::Rejected(message) = outcome else {\n            panic!(\"expected rejection\")\n        };\n        assert!(message.contains(\"List element 0\"));\n        assert!(matches!(\n            schema\n                .check_with_context(\n                    value(Value::Symbol(Symbol::new(\"same\".into()))),\n                    &box_type,\n                    64,\n                    &mut context\n                )\n                .unwrap(),\n            ValueCheck::Rejected(_)\n        ));\n    }\n\n    #[test]\n    fn contract_metadata_rejects_unknown_and_duplicate_constructor_tags() {\n        assert!(\n            Schema::with_contracts(\n                vec![],\n                vec![ConstructorContract {\n                    tag: \"Unknown\",\n                    predicates: vec![positive],\n                }]\n            )\n            .is_err()\n        );\n        let definitions = vec![DataSchema {\n            name: \"Box\",\n            parameters: 0,\n            constructors: vec![ConstructorSchema {\n                tag: \"Box\",\n                fields: vec![],\n            }],\n        }];\n        assert!(\n            Schema::with_contracts(\n                definitions,\n                vec![\n                    ConstructorContract {\n                        tag: \"Box\",\n                        predicates: vec![]\n                    },\n                    ConstructorContract {\n                        tag: \"Box\",\n                        predicates: vec![]\n                    },\n                ]\n            )\n            .is_err()\n        );\n    }\n}\n\n/// Channels and processes for the typed channel ends LawSpec generates from\n/// protocols (lawspec_sessions). Generated ends move one Endpoint from step\n/// to step; implementation code only opens, spawns and joins.\npub mod sessions {\n    use std::any::Any;\n    use std::collections::VecDeque;\n    use std::sync::{Arc, Condvar, Mutex};\n\n    /// A value in flight. Generated ends fix each step's type, so a receive\n    /// knows what it takes off the channel.\n    pub type Message = Box<dyn Any + Send>;\n\n    /// One end of a two-ended channel.\n    #[derive(Clone, Copy, Debug, PartialEq, Eq)]\n    pub enum Side {\n        First,\n        Second,\n    }\n\n    impl Side {\n        fn index(self) -> usize {\n            match self {\n                Side::First => 0,\n                Side::Second => 1,\n            }\n        }\n\n        fn other(self) -> Side {\n            match self {\n                Side::First => Side::Second,\n                Side::Second => Side::First,\n            }\n        }\n    }\n\n    /// A receive whose other end gave up: its process failed (a panic drops\n    /// its ends), it was dropped, or abandon was called. try_receive returns\n    /// it; receive panics with it, failing this process too.\n    #[derive(Clone, Copy, Debug, PartialEq, Eq)]\n    pub struct PeerFailed;\n\n    impl std::fmt::Display for PeerFailed {\n        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {\n            f.write_str(\"the other end gave up the conversation (its process failed or abandoned it)\")\n        }\n    }\n\n    impl std::error::Error for PeerFailed {}\n\n    /// What carries messages between a channel's two ends. The local channel\n    /// is in memory; a networked transport can implement the same interface.\n    pub trait Transport: Send + Sync {\n        /// Sends a message from `side` to the other end.\n        fn send(&self, side: Side, message: Message);\n        /// Takes the next message sent to `side`, waiting for one; PeerFailed\n        /// once the other end has closed and nothing it sent is left.\n        fn receive(&self, side: Side) -> Result<Message, PeerFailed>;\n        /// Closes `side`: the other end's pending receives fail.\n        fn close(&self, side: Side);\n        /// For an unused network channel end, the address another node\n        /// takes it over from (closing it afterwards does not give it up);\n        /// None for a local channel.\n        fn hand_over(&self) -> Option<String> {\n            None\n        }\n    }\n\n    /// An in-memory channel: one queue per direction.\n    #[derive(Default)]\n    pub struct LocalChannel {\n        state: Mutex<LocalState>,\n        changed: Condvar,\n    }\n\n    #[derive(Default)]\n    struct LocalState {\n        // queues[i] holds messages sent to side i.\n        queues: [VecDeque<Message>; 2],\n        closed: [bool; 2],\n    }\n\n    impl Transport for LocalChannel {\n        fn send(&self, side: Side, message: Message) {\n            let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());\n            state.queues[side.other().index()].push_back(message);\n            self.changed.notify_all();\n        }\n\n        fn receive(&self, side: Side) -> Result<Message, PeerFailed> {\n            let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());\n            loop {\n                if let Some(message) = state.queues[side.index()].pop_front() {\n                    return Ok(message);\n                }\n                if state.closed[side.other().index()] {\n                    return Err(PeerFailed);\n                }\n                state = self.changed.wait(state).unwrap_or_else(|e| e.into_inner());\n            }\n        }\n\n        fn close(&self, side: Side) {\n            let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());\n            state.closed[side.index()] = true;\n            self.changed.notify_all();\n        }\n    }\n\n    /// One side of a channel, untyped: generated ends wrap it, and closing\n    /// it (by dropping) wakes a peer waiting on it.\n    pub struct Endpoint {\n        transport: Arc<dyn Transport>,\n        side: Side,\n    }\n\n    impl Endpoint {\n        /// The ends of a channel over the given transport.\n        pub fn pair(transport: Arc<dyn Transport>) -> (Endpoint, Endpoint) {\n            (\n                Endpoint { transport: transport.clone(), side: Side::First },\n                Endpoint { transport, side: Side::Second },\n            )\n        }\n\n        /// One end of a channel over the given transport, such as a\n        /// network channel end's (see net::NetSession).\n        pub fn on(transport: Arc<dyn Transport>, side: Side) -> Endpoint {\n            Endpoint { transport, side }\n        }\n\n        pub fn send<T: Any + Send>(&self, value: T) {\n            self.transport.send(self.side, Box::new(value));\n        }\n\n        /// The next value; panics with PeerFailed when the other end gave up.\n        pub fn receive<T: Any + Send>(&self) -> T {\n            self.try_receive().unwrap_or_else(|failed| panic!(\"{failed}\"))\n        }\n\n        /// The next value, or PeerFailed once the other end gave up and\n        /// nothing it sent is left.\n        pub fn try_receive<T: Any + Send>(&self) -> Result<T, PeerFailed> {\n            match self.transport.receive(self.side)?.downcast::<T>() {\n                Ok(value) => Ok(*value),\n                Err(_) => panic!(\"a session received a value of an unexpected type\"),\n            }\n        }\n\n        /// Gives up the conversation: the other end's receives fail with\n        /// PeerFailed once it has received what was already sent. Dropping\n        /// an end does the same.\n        pub fn abandon(self) {}\n\n        /// Sends a value already boxed (a relay passing one step on).\n        pub fn send_message(&self, message: Message) {\n            self.transport.send(self.side, message);\n        }\n\n        /// The next value, still boxed (a relay passing one step on).\n        pub fn receive_message(&self) -> Result<Message, PeerFailed> {\n            self.transport.receive(self.side)\n        }\n\n        /// For an unused end between nodes, the address another node takes\n        /// it over from; None for a local end.\n        pub fn hand_over(&self) -> Option<String> {\n            self.transport.hand_over()\n        }\n    }\n\n    impl Drop for Endpoint {\n        fn drop(&mut self) {\n            self.transport.close(self.side);\n        }\n    }\n\n    /// The ends of a fresh in-memory channel.\n    pub fn channel() -> (Endpoint, Endpoint) {\n        Endpoint::pair(Arc::new(LocalChannel::default()))\n    }\n\n    /// A running process: a thread whose result join returns.\n    pub struct Process<T>(std::thread::JoinHandle<T>);\n\n    impl<T> Process<T> {\n        /// Waits for the process; its panic, if any, continues here.\n        pub fn join(self) -> T {\n            self.0.join().unwrap_or_else(|panic| std::panic::resume_unwind(panic))\n        }\n    }\n\n    /// Runs `body` as a new process.\n    pub fn spawn<T: Send + 'static>(body: impl FnOnce() -> T + Send + 'static) -> Process<T> {\n        Process(std::thread::spawn(body))\n    }\n\n    /// Runs two closures in parallel and returns both results; a panic in\n    /// either continues here.\n    pub fn par<A: Send, B: Send>(\n        left: impl FnOnce() -> A + Send,\n        right: impl FnOnce() -> B + Send,\n    ) -> (A, B) {\n        std::thread::scope(|scope| {\n            let right = scope.spawn(right);\n            let left = left();\n            let right = right.join().unwrap_or_else(|panic| std::panic::resume_unwind(panic));\n            (left, right)\n        })\n    }\n}\n\n// Actors. An actor owns a state and handles one message at a time, in the\n// order they arrive. It is not a thread: each message takes a ticket when it\n// is sent, and runs when the actor's turn reaches it. A call runs its handler\n// on the caller's own thread once its turn comes, so it may borrow from the\n// caller (the model runner's Context, say) and costs no thread handoff; a\n// tell is queued, and a worker thread runs while there are queued tells and\n// stops when there are none, so an idle actor costs only its state.\n//\n// A handler that fails (an Err or a panic) crashes the actor: the caller\n// gets an error starting \"the actor crashed: \". A supervised actor with a\n// restart function restarts in place, keeping its address and the messages\n// waiting for it; any other actor stops, and later messages fail with \"the\n// actor has stopped\". Monitors hear of each crash and of the stop; links\n// carry a crash to the linked actor, crossing each link once.\npub mod actors {\n    use std::collections::{HashSet, VecDeque};\n    use std::sync::atomic::{AtomicU64, Ordering};\n    use std::sync::{Arc, Condvar, Mutex, MutexGuard, Weak};\n    use std::time::{Duration, Instant};\n\n    /// The start of the error a call returns when its handler crashed the actor.\n    pub const CRASHED: &str = \"the actor crashed: \";\n    /// The error of a message sent to an actor that has stopped.\n    pub const STOPPED: &str = \"the actor has stopped\";\n\n    /// Whether an error says the handler crashed the actor.\n    pub fn is_crashed(error: &str) -> bool {\n        error.starts_with(CRASHED)\n    }\n\n    /// Whether an error says the actor had stopped.\n    pub fn is_stopped(error: &str) -> bool {\n        error == STOPPED\n    }\n\n    /// What a monitor hears: a crash and its cause, or the stop.\n    #[derive(Clone, Debug, PartialEq, Eq)]\n    pub enum Exit {\n        Crashed(String),\n        Stopped,\n    }\n\n    static CRASHES: AtomicU64 = AtomicU64::new(1);\n\n    // Each first crash is numbered, so a crash crosses each link once.\n    fn next_crash() -> u64 {\n        CRASHES.fetch_add(1, Ordering::Relaxed)\n    }\n\n    fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {\n        m.lock().unwrap_or_else(|e| e.into_inner())\n    }\n\n    fn panic_text(panic: Box<dyn std::any::Any + Send>) -> String {\n        if let Some(s) = panic.downcast_ref::<&str>() {\n            format!(\"a handler panicked: {s}\")\n        } else if let Some(s) = panic.downcast_ref::<String>() {\n            format!(\"a handler panicked: {s}\")\n        } else {\n            \"a handler panicked\".into()\n        }\n    }\n\n    type Tell<S> = Box<dyn FnOnce(S) -> super::Result<S> + Send>;\n    type Restart<S> = Arc<dyn Fn(S) -> super::Result<S> + Send + Sync>;\n    type Keep<S> = Arc<dyn Fn(&S) -> S + Send + Sync>;\n    type Notify = Arc<dyn Fn(Exit) + Send + Sync>;\n    type LinkCrash = Arc<dyn Fn(&str, u64) + Send + Sync>;\n\n    enum Message<S> {\n        Run(Tell<S>),\n        // A crash on purpose (crash, a link), with its first crash's number.\n        Crash(String, u64),\n        // A restart a supervisor asks of a sibling.\n        Restart,\n    }\n\n    /// An actor over a state S. Clones share the actor.\n    pub struct Actor<S> {\n        inner: Arc<Inner<S>>,\n    }\n\n    impl<S> Clone for Actor<S> {\n        fn clone(&self) -> Self {\n            Actor { inner: self.inner.clone() }\n        }\n    }\n\n    struct Inner<S> {\n        lock: Mutex<Turns<S>>,\n        changed: Condvar,\n        restart: Option<Restart<S>>,\n        // Copies the state before each handler, so a restart can start from\n        // the last state even when the handler failed.\n        keep: Option<Keep<S>>,\n        links: Mutex<Vec<LinkCrash>>,\n        monitors: Mutex<Vec<Notify>>,\n        supervisor: Mutex<Option<Weak<SupervisorInner>>>,\n        seen: Mutex<HashSet<u64>>,\n    }\n\n    struct Turns<S> {\n        // The state between messages; None while a handler holds it, or\n        // once the actor has halted.\n        state: Option<S>,\n        next_ticket: u64,\n        serving: u64,\n        tells: VecDeque<(u64, Message<S>)>,\n        draining: bool,\n        stopped: bool,\n        halted: bool,\n    }\n\n    impl<S: Send + 'static> Actor<S> {\n        /// Starts an actor owning `state`. It cannot restart: a crash stops\n        /// it, even under a supervisor.\n        pub fn new(state: S) -> Self {\n            Self::make(state, None, None)\n        }\n\n        fn make(state: S, restart: Option<Restart<S>>, keep: Option<Keep<S>>) -> Self {\n            Actor {\n                inner: Arc::new(Inner {\n                    lock: Mutex::new(Turns {\n                        state: Some(state),\n                        next_ticket: 0,\n                        serving: 0,\n                        tells: VecDeque::new(),\n                        draining: false,\n                        stopped: false,\n                        halted: false,\n                    }),\n                    changed: Condvar::new(),\n                    restart,\n                    keep,\n                    links: Mutex::new(Vec::new()),\n                    monitors: Mutex::new(Vec::new()),\n                    supervisor: Mutex::new(None),\n                    seen: Mutex::new(HashSet::new()),\n                }),\n            }\n        }\n\n        fn id(&self) -> usize {\n            Arc::as_ptr(&self.inner) as *const () as usize\n        }\n\n        fn turns(&self) -> MutexGuard<'_, Turns<S>> {\n            lock(&self.inner.lock)\n        }\n\n        fn ticket(&self) -> super::Result<u64> {\n            let mut turns = self.turns();\n            if turns.stopped {\n                return Err(STOPPED.into());\n            }\n            let ticket = turns.next_ticket;\n            turns.next_ticket += 1;\n            Ok(ticket)\n        }\n\n        /// Waits for `ticket`'s turn and takes the state.\n        fn take(&self, ticket: u64) -> std::result::Result<S, String> {\n            let mut turns = self.turns();\n            while turns.serving != ticket {\n                turns = self.inner.changed.wait(turns).unwrap_or_else(|e| e.into_inner());\n            }\n            if turns.halted {\n                return Err(STOPPED.into());\n            }\n            turns.state.take().ok_or_else(|| STOPPED.to_string())\n        }\n\n        /// Ends the current turn, leaving `state` unless the actor halted.\n        fn finish(&self, state: Option<S>) {\n            let mut turns = self.turns();\n            if !turns.halted {\n                if let Some(state) = state {\n                    turns.state = Some(state);\n                }\n            }\n            turns.serving += 1;\n            self.inner.changed.notify_all();\n        }\n\n        fn queue(&self, message: Message<S>) -> super::Result<()> {\n            let start = {\n                let mut turns = self.turns();\n                if turns.stopped {\n                    return Err(STOPPED.into());\n                }\n                let ticket = turns.next_ticket;\n                turns.next_ticket += 1;\n                turns.tells.push_back((ticket, message));\n                !std::mem::replace(&mut turns.draining, true)\n            };\n            if start {\n                let actor = self.clone();\n                std::thread::spawn(move || actor.drain());\n            }\n            Ok(())\n        }\n\n        /// Stops at once: the state is dropped, and messages still waiting\n        /// fail with \"the actor has stopped\".\n        fn halt_now(&self) {\n            let mut turns = self.turns();\n            turns.halted = true;\n            turns.stopped = true;\n            turns.state = None;\n            self.inner.changed.notify_all();\n        }\n\n        /// On the actor's turn, with the last state if it is known: restart\n        /// or halt, end the turn, then tell monitors and links.\n        fn crashed(&self, cause: String, origin: u64, last: Option<S>) {\n            lock(&self.inner.seen).insert(origin);\n            let supervisor = lock(&self.inner.supervisor).clone().and_then(|w| w.upgrade());\n            let mut next = None;\n            if let (Some(supervisor), Some(restart), Some(last)) = (supervisor, self.inner.restart.clone(), last) {\n                if supervisor.child_crashed(self.id(), &cause) {\n                    next = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| restart(last))).ok().and_then(|r| r.ok());\n                }\n            }\n            if next.is_none() {\n                self.halt_now();\n            }\n            self.finish(next);\n            for monitor in lock(&self.inner.monitors).clone() {\n                monitor(Exit::Crashed(cause.clone()));\n            }\n            for link in lock(&self.inner.links).clone() {\n                link(&cause, origin);\n            }\n        }\n\n        /// Runs one turn's body over the state; a failure crashes the actor.\n        fn turn<R>(&self, state: S, body: impl FnOnce(S) -> super::Result<(R, S)>) -> super::Result<R> {\n            let snapshot = self.inner.keep.as_ref().map(|keep| keep(&state));\n            let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| body(state)))\n                .unwrap_or_else(|panic| Err(panic_text(panic)));\n            match outcome {\n                Ok((reply, next)) => {\n                    self.finish(Some(next));\n                    Ok(reply)\n                }\n                Err(cause) => {\n                    self.crashed(cause.clone(), next_crash(), snapshot);\n                    Err(format!(\"{CRASHED}{cause}\"))\n                }\n            }\n        }\n\n        /// Runs handler(state) -> (reply, next state) in turn and returns the\n        /// reply. A handler that fails or panics crashes the actor, and call\n        /// returns an error starting \"the actor crashed: \".\n        pub fn call<R>(&self, handler: impl FnOnce(S) -> super::Result<(R, S)>) -> super::Result<R> {\n            let ticket = self.ticket()?;\n            match self.take(ticket) {\n                Ok(state) => self.turn(state, handler),\n                Err(e) => {\n                    self.finish(None);\n                    Err(e)\n                }\n            }\n        }\n\n        /// Queues handler(state) -> (reply, next state) without waiting; the\n        /// reply is dropped.\n        pub fn tell<R>(&self, handler: impl FnOnce(S) -> super::Result<(R, S)> + Send + 'static) -> super::Result<()> {\n            self.queue(Message::Run(Box::new(move |s| handler(s).map(|(_, next)| next))))\n        }\n\n        fn drain(&self) {\n            loop {\n                let (ticket, message) = {\n                    let mut turns = self.turns();\n                    match turns.tells.pop_front() {\n                        Some(next) => next,\n                        None => {\n                            turns.draining = false;\n                            return;\n                        }\n                    }\n                };\n                let state = match self.take(ticket) {\n                    Ok(state) => state,\n                    Err(_) => {\n                        self.finish(None);\n                        continue;\n                    }\n                };\n                match message {\n                    Message::Run(handler) => {\n                        let _ = self.turn(state, |s| handler(s).map(|next| ((), next)));\n                    }\n                    // A crash that already reached this actor by another\n                    // link is not repeated.\n                    Message::Crash(_, origin) if lock(&self.inner.seen).contains(&origin) => self.finish(Some(state)),\n                    Message::Crash(cause, origin) => self.crashed(cause, origin, Some(state)),\n                    Message::Restart => match &self.inner.restart {\n                        Some(restart) => {\n                            let restart = restart.clone();\n                            let _ = self.turn(state, |s| restart(s).map(|next| ((), next)));\n                        }\n                        None => self.finish(Some(state)),\n                    },\n                }\n            }\n        }\n\n        /// Crashes the actor once the messages sent before are handled, as a\n        /// failing handler would: for testing supervision.\n        pub fn crash(&self, cause: &str) -> super::Result<()> {\n            let ticket = self.ticket()?;\n            match self.take(ticket) {\n                Ok(state) => {\n                    self.crashed(cause.to_string(), next_crash(), Some(state));\n                    Ok(())\n                }\n                Err(e) => {\n                    self.finish(None);\n                    Err(e)\n                }\n            }\n        }\n\n        /// Replaces the state by restart(last state) between messages, as a\n        /// supervised restart does (crash injection in model runs).\n        pub fn restart(&self, restart: impl FnOnce(S) -> super::Result<S>) -> super::Result<()> {\n            self.call(|s| restart(s).map(|next| ((), next)))\n        }\n\n        /// notify(Exit::Crashed(cause)) after each crash, and\n        /// notify(Exit::Stopped) once it stops.\n        pub fn monitor(&self, notify: impl Fn(Exit) + Send + Sync + 'static) {\n            lock(&self.inner.monitors).push(Arc::new(notify));\n        }\n\n        /// Links two actors: when either crashes, the other crashes too.\n        pub fn link<T: Send + 'static>(&self, other: &Actor<T>) {\n            lock(&self.inner.links).push(other.link_target());\n            lock(&other.inner.links).push(self.link_target());\n        }\n\n        fn link_target(&self) -> LinkCrash {\n            let weak = Arc::downgrade(&self.inner);\n            Arc::new(move |cause: &str, origin: u64| {\n                if let Some(inner) = weak.upgrade() {\n                    let actor = Actor { inner };\n                    if !lock(&actor.inner.seen).contains(&origin) {\n                        let _ = actor.queue(Message::Crash(cause.to_string(), origin));\n                    }\n                }\n            })\n        }\n\n        /// Refuses further messages; those already sent are still handled. A\n        /// permanent child of a supervisor restarts instead.\n        pub fn stop(&self) {\n            let supervisor = lock(&self.inner.supervisor).clone().and_then(|w| w.upgrade());\n            if let Some(supervisor) = supervisor {\n                if supervisor.child_stopped(self.id()) {\n                    return;\n                }\n            }\n            let already = std::mem::replace(&mut self.turns().stopped, true);\n            if !already {\n                for monitor in lock(&self.inner.monitors).clone() {\n                    monitor(Exit::Stopped);\n                }\n            }\n        }\n    }\n\n    impl<S: Clone + Send + 'static> Actor<S> {\n        /// Starts an actor owning `state` that restarts after a crash, under\n        /// a supervisor, with restart(last state).\n        pub fn with_restart(state: S, restart: impl Fn(S) -> super::Result<S> + Send + Sync + 'static) -> Self {\n            Self::make(state, Some(Arc::new(restart)), Some(Arc::new(S::clone)))\n        }\n\n        /// The state after every message sent before this call.\n        pub fn state(&self) -> super::Result<S> {\n            self.call(|s: S| Ok((s.clone(), s)))\n        }\n    }\n\n    /// A child a supervisor can hold: an actor or another supervisor.\n    pub trait Supervised: Send + Sync {\n        /// Identifies the child: clones share it.\n        fn child_id(&self) -> usize;\n        /// Restarts in mailbox order (an actor) or restarts every child (a\n        /// supervisor).\n        fn restart_later(&self);\n        /// Stops at once.\n        fn halt(&self);\n        /// Stops as asked (see stop).\n        fn stop_child(&self);\n        /// Sets or clears the child's supervisor.\n        fn attach(&self, supervisor: Option<&Supervisor>);\n    }\n\n    impl<S: Send + 'static> Supervised for Actor<S> {\n        fn child_id(&self) -> usize {\n            self.id()\n        }\n\n        fn restart_later(&self) {\n            let _ = self.queue(Message::Restart);\n        }\n\n        fn halt(&self) {\n            self.halt_now();\n        }\n\n        fn stop_child(&self) {\n            self.stop();\n        }\n\n        fn attach(&self, supervisor: Option<&Supervisor>) {\n            *lock(&self.inner.supervisor) = supervisor.map(|s| Arc::downgrade(&s.inner));\n        }\n    }\n\n    /// Which children restart after one crashes.\n    #[derive(Clone, Copy, Debug, PartialEq, Eq)]\n    pub enum Strategy {\n        /// Only the child that crashed.\n        OneForOne,\n        /// Every child.\n        OneForAll,\n        /// The child that crashed and those added after it.\n        RestForOne,\n    }\n\n    /// Whether a child restarts.\n    #[derive(Clone, Copy, Debug, PartialEq, Eq)]\n    pub enum Lifetime {\n        /// After a crash or a stop.\n        Permanent,\n        /// Only after a crash.\n        Transient,\n        /// Never.\n        Temporary,\n    }\n\n    struct Child {\n        child: Arc<dyn Supervised>,\n        lifetime: Lifetime,\n    }\n\n    struct SupervisorState {\n        children: Vec<Child>,\n        restarts: VecDeque<Instant>,\n        stopped: bool,\n    }\n\n    struct SupervisorInner {\n        strategy: Strategy,\n        max_restarts: usize,\n        period: Duration,\n        state: Mutex<SupervisorState>,\n        parent: Mutex<Option<Weak<SupervisorInner>>>,\n        monitors: Mutex<Vec<Notify>>,\n    }\n\n    /// Starts nothing itself: children (actors or supervisors) are added\n    /// with supervise, and restarted after a crash by the strategy and each\n    /// child's lifetime. More than max_restarts within period is the\n    /// supervisor's own crash: its supervisor restarts all of its children,\n    /// or, at the top, every child stops. Clones share the supervisor.\n    #[derive(Clone)]\n    pub struct Supervisor {\n        inner: Arc<SupervisorInner>,\n    }\n\n    impl Supervisor {\n        pub fn new(strategy: Strategy, max_restarts: usize, period: Duration) -> Self {\n            Supervisor {\n                inner: Arc::new(SupervisorInner {\n                    strategy,\n                    max_restarts,\n                    period,\n                    state: Mutex::new(SupervisorState { children: Vec::new(), restarts: VecDeque::new(), stopped: false }),\n                    parent: Mutex::new(None),\n                    monitors: Mutex::new(Vec::new()),\n                }),\n            }\n        }\n\n        /// Adds a started child (a clone of an actor or a supervisor).\n        pub fn supervise(&self, child: impl Supervised + 'static, lifetime: Lifetime) {\n            child.attach(Some(self));\n            lock(&self.inner.state).children.push(Child { child: Arc::new(child), lifetime });\n        }\n\n        /// notify(Exit::Crashed(cause)) when it passes its restart limit, and\n        /// notify(Exit::Stopped) once stopped.\n        pub fn monitor(&self, notify: impl Fn(Exit) + Send + Sync + 'static) {\n            lock(&self.inner.monitors).push(Arc::new(notify));\n        }\n\n        /// Stops every child, last added first, without restarting them.\n        pub fn stop(&self) {\n            self.inner.stop();\n        }\n    }\n\n    impl SupervisorInner {\n        fn id(self: &Arc<Self>) -> usize {\n            Arc::as_ptr(self) as *const () as usize\n        }\n\n        fn allow_restart(&self, state: &mut SupervisorState) -> bool {\n            let now = Instant::now();\n            while state.restarts.front().is_some_and(|at| now.duration_since(*at) > self.period) {\n                state.restarts.pop_front();\n            }\n            if state.restarts.len() >= self.max_restarts {\n                return false;\n            }\n            state.restarts.push_back(now);\n            true\n        }\n\n        /// Under the lock: the children to restart for the crash of the\n        /// child at `index`, or None when the supervisor gives up.\n        fn restarting(\n            self: &Arc<Self>,\n            state: &mut SupervisorState,\n            index: usize,\n            cause: &str,\n            crashed: usize,\n        ) -> Option<Vec<Arc<dyn Supervised>>> {\n            if self.allow_restart(state) {\n                let group: Vec<&Child> = match self.strategy {\n                    Strategy::OneForOne => vec![&state.children[index]],\n                    Strategy::OneForAll => state.children.iter().collect(),\n                    Strategy::RestForOne => state.children[index..].iter().collect(),\n                };\n                return Some(group.into_iter().map(|c| c.child.clone()).collect());\n            }\n            let parent = lock(&self.parent).clone().and_then(|w| w.upgrade());\n            if let Some(parent) = parent {\n                if parent.child_failed(self.id(), cause) {\n                    state.restarts.clear();\n                    return Some(state.children.iter().map(|c| c.child.clone()).collect());\n                }\n            }\n            self.fail(state, crashed, cause);\n            None\n        }\n\n        fn entry(state: &SupervisorState, id: usize) -> Option<usize> {\n            state.children.iter().position(|c| c.child.child_id() == id)\n        }\n\n        /// On the child's turn: whether it restarts now.\n        fn child_crashed(self: &Arc<Self>, id: usize, cause: &str) -> bool {\n            let group = {\n                let mut state = lock(&self.state);\n                let Some(index) = Self::entry(&state, id) else {\n                    return false;\n                };\n                if state.stopped {\n                    return false;\n                }\n                if state.children[index].lifetime == Lifetime::Temporary {\n                    state.children.remove(index);\n                    return false;\n                }\n                match self.restarting(&mut state, index, cause, id) {\n                    Some(group) => group,\n                    None => return false,\n                }\n            };\n            for other in group {\n                if other.child_id() != id {\n                    other.restart_later();\n                }\n            }\n            true\n        }\n\n        /// A child supervisor gave up: whether it may restart its children.\n        fn child_failed(self: &Arc<Self>, id: usize, cause: &str) -> bool {\n            let group = {\n                let mut state = lock(&self.state);\n                let Some(index) = Self::entry(&state, id) else {\n                    return false;\n                };\n                if state.stopped {\n                    return false;\n                }\n                if state.children[index].lifetime == Lifetime::Temporary {\n                    state.children.remove(index);\n                    return false;\n                }\n                match self.restarting(&mut state, index, cause, id) {\n                    Some(group) => group,\n                    None => return false,\n                }\n            };\n            for other in group {\n                if other.child_id() != id {\n                    other.restart_later();\n                }\n            }\n            true\n        }\n\n        /// Whether a stopped child is permanent and restarts instead.\n        fn child_stopped(self: &Arc<Self>, id: usize) -> bool {\n            let group = {\n                let mut state = lock(&self.state);\n                let Some(index) = Self::entry(&state, id) else {\n                    return false;\n                };\n                if state.stopped {\n                    return false;\n                }\n                if state.children[index].lifetime != Lifetime::Permanent {\n                    state.children.remove(index);\n                    return false;\n                }\n                match self.restarting(&mut state, index, \"stopped\", id) {\n                    Some(group) => group,\n                    None => return false,\n                }\n            };\n            for other in group {\n                other.restart_later();\n            }\n            true\n        }\n\n        /// Under the lock: every child but the one crashing (which halts\n        /// itself) stops, and so does the supervisor.\n        fn fail(&self, state: &mut SupervisorState, crashed: usize, cause: &str) {\n            let children = std::mem::take(&mut state.children);\n            state.stopped = true;\n            for c in children.iter().rev() {\n                c.child.attach(None);\n                if c.child.child_id() != crashed {\n                    c.child.halt();\n                }\n            }\n            for monitor in lock(&self.monitors).clone() {\n                monitor(Exit::Crashed(cause.to_string()));\n            }\n        }\n\n        fn stop(&self) {\n            let children = {\n                let mut state = lock(&self.state);\n                if state.stopped {\n                    return;\n                }\n                state.stopped = true;\n                std::mem::take(&mut state.children)\n            };\n            for c in children.iter().rev() {\n                c.child.attach(None);\n                c.child.stop_child();\n            }\n            for monitor in lock(&self.monitors).clone() {\n                monitor(Exit::Stopped);\n            }\n        }\n    }\n\n    impl Supervised for Supervisor {\n        fn child_id(&self) -> usize {\n            self.inner.id()\n        }\n\n        /// Restarted by its own supervisor: every child restarts.\n        fn restart_later(&self) {\n            let children: Vec<Arc<dyn Supervised>> = {\n                let mut state = lock(&self.inner.state);\n                state.restarts.clear();\n                state.children.iter().map(|c| c.child.clone()).collect()\n            };\n            for child in children {\n                child.restart_later();\n            }\n        }\n\n        fn halt(&self) {\n            self.inner.stop();\n        }\n\n        fn stop_child(&self) {\n            self.inner.stop();\n        }\n\n        fn attach(&self, supervisor: Option<&Supervisor>) {\n            *lock(&self.inner.parent) = supervisor.map(|s| Arc::downgrade(&s.inner));\n        }\n    }\n\n    /// The runtime's own check of crashes, links, monitors and supervision:\n    /// every strategy, lifetime, the restart limit and escalation. Fails\n    /// naming the first behaviour that differs.\n    pub fn check_supervision() -> super::Result<()> {\n        fn counter() -> Actor<i64> {\n            Actor::with_restart(0, |_| Ok(0))\n        }\n        fn bump(a: &Actor<i64>) -> super::Result<i64> {\n            a.call(|s| Ok((s + 1, s + 1)))\n        }\n        fn fail(a: &Actor<i64>) -> super::Result<()> {\n            match a.call(|_| -> super::Result<((), i64)> { Err(\"division by zero\".into()) }) {\n                Err(e) if is_crashed(&e) => Ok(()),\n                _ => Err(\"a failing handler did not crash the actor\".into()),\n            }\n        }\n        fn stopped(a: &Actor<i64>, what: &str) -> super::Result<()> {\n            match a.state() {\n                Err(e) if is_stopped(&e) => Ok(()),\n                _ => Err(format!(\"{what} should have stopped\")),\n            }\n        }\n        fn expect<T: PartialEq + std::fmt::Debug>(actual: T, wanted: T, what: &str) -> super::Result<()> {\n            if actual != wanted {\n                return Err(format!(\"{what}: got {actual:?}, expected {wanted:?}\"));\n            }\n            Ok(())\n        }\n        fn wait_until(mut done: impl FnMut() -> bool) {\n            for _ in 0..100 {\n                if done() {\n                    return;\n                }\n                std::thread::sleep(Duration::from_millis(10));\n            }\n        }\n        let long = Duration::from_secs(10);\n        let a = counter();\n        bump(&a)?;\n        fail(&a)?;\n        stopped(&a, \"an unsupervised actor that crashed\")?;\n        let sup = Supervisor::new(Strategy::OneForOne, 3, Duration::from_secs(5));\n        let (x, y) = (counter(), counter());\n        sup.supervise(x.clone(), Lifetime::Permanent);\n        sup.supervise(y.clone(), Lifetime::Permanent);\n        bump(&x)?;\n        bump(&y)?;\n        bump(&y)?;\n        fail(&x)?;\n        expect((x.state()?, y.state()?), (0, 2), \"one for one restarts only the crashed child\")?;\n        let sup = Supervisor::new(Strategy::OneForAll, 3, Duration::from_secs(5));\n        let (x, y) = (counter(), counter());\n        sup.supervise(x.clone(), Lifetime::Permanent);\n        sup.supervise(y.clone(), Lifetime::Permanent);\n        bump(&x)?;\n        bump(&y)?;\n        fail(&x)?;\n        expect((x.state()?, y.state()?), (0, 0), \"one for all restarts every child\")?;\n        let sup = Supervisor::new(Strategy::RestForOne, 3, Duration::from_secs(5));\n        let (x, y, z) = (counter(), counter(), counter());\n        for c in [&x, &y, &z] {\n            sup.supervise(c.clone(), Lifetime::Permanent);\n            bump(c)?;\n        }\n        fail(&y)?;\n        expect((x.state()?, y.state()?, z.state()?), (1, 0, 0), \"rest for one restarts the child and later ones\")?;\n        let sup = Supervisor::new(Strategy::OneForOne, 3, Duration::from_secs(5));\n        let t = counter();\n        sup.supervise(t.clone(), Lifetime::Temporary);\n        fail(&t)?;\n        stopped(&t, \"a temporary child that crashed\")?;\n        let sup = Supervisor::new(Strategy::OneForOne, 3, Duration::from_secs(5));\n        let (p, q) = (counter(), counter());\n        sup.supervise(p.clone(), Lifetime::Permanent);\n        sup.supervise(q.clone(), Lifetime::Transient);\n        bump(&p)?;\n        p.stop();\n        expect(p.state()?, 0, \"a permanent child restarts after a stop\")?;\n        q.stop();\n        stopped(&q, \"a transient child that was stopped\")?;\n        let events = Arc::new(Mutex::new(Vec::new()));\n        let sup = Supervisor::new(Strategy::OneForOne, 2, long);\n        let heard = events.clone();\n        sup.monitor(move |e| lock(&heard).push(e));\n        let (x, y) = (counter(), counter());\n        sup.supervise(x.clone(), Lifetime::Permanent);\n        sup.supervise(y.clone(), Lifetime::Permanent);\n        fail(&x)?;\n        fail(&x)?;\n        fail(&x)?;\n        stopped(&y, \"a child of a supervisor past its restart limit\")?;\n        expect(\n            lock(&events).iter().map(|e| matches!(e, Exit::Crashed(_))).collect::<Vec<_>>(),\n            vec![true],\n            \"a supervisor past its limit tells its monitors\",\n        )?;\n        let outer = Supervisor::new(Strategy::OneForOne, 5, long);\n        let inner = Supervisor::new(Strategy::OneForOne, 1, long);\n        outer.supervise(inner.clone(), Lifetime::Permanent);\n        let (x, y) = (counter(), counter());\n        inner.supervise(x.clone(), Lifetime::Permanent);\n        inner.supervise(y.clone(), Lifetime::Permanent);\n        bump(&y)?;\n        fail(&x)?;\n        fail(&x)?;\n        expect((x.state()?, y.state()?), (0, 0), \"a supervisor past its limit is restarted by its own\")?;\n        let seen = Arc::new(Mutex::new(Vec::new()));\n        let (a, b) = (counter(), counter());\n        a.link(&b);\n        let heard = seen.clone();\n        b.monitor(move |e| lock(&heard).push(e));\n        fail(&a)?;\n        wait_until(|| !lock(&seen).is_empty());\n        stopped(&b, \"an unsupervised actor linked to one that crashed\")?;\n        expect(\n            lock(&seen).iter().map(|e| matches!(e, Exit::Crashed(_))).collect::<Vec<_>>(),\n            vec![true],\n            \"a monitor hears of a crash\",\n        )?;\n        let sup = Supervisor::new(Strategy::OneForOne, 10, Duration::from_secs(5));\n        let (a, b, c) = (counter(), counter(), counter());\n        for x in [&a, &b, &c] {\n            sup.supervise(x.clone(), Lifetime::Permanent);\n        }\n        a.link(&b);\n        b.link(&c);\n        c.link(&a);\n        bump(&a)?;\n        bump(&b)?;\n        bump(&c)?;\n        fail(&a)?;\n        wait_until(|| lock(&sup.inner.state).restarts.len() >= 3);\n        std::thread::sleep(Duration::from_millis(50));\n        expect(\n            (a.state()?, b.state()?, c.state()?, lock(&sup.inner.state).restarts.len()),\n            (0, 0, 0, 3),\n            \"a crash crosses each link once\",\n        )?;\n        Ok(())\n    }\n\n    /// A queue with many senders and one receiver: the channel form of an\n    /// actor. A process that loops over receive and answers each message is\n    /// an actor written by hand; send never waits. Clones share the mailbox.\n    pub struct Mailbox<T> {\n        inner: Arc<(Mutex<(VecDeque<T>, bool)>, Condvar)>,\n    }\n\n    impl<T> Clone for Mailbox<T> {\n        fn clone(&self) -> Self {\n            Mailbox { inner: self.inner.clone() }\n        }\n    }\n\n    impl<T> Default for Mailbox<T> {\n        fn default() -> Self {\n            Mailbox { inner: Arc::new((Mutex::new((VecDeque::new(), false)), Condvar::new())) }\n        }\n    }\n\n    impl<T> Mailbox<T> {\n        pub fn new() -> Self {\n            Self::default()\n        }\n\n        /// Sends a message; fails once the mailbox is closed.\n        pub fn send(&self, value: T) -> super::Result<()> {\n            let mut items = self.inner.0.lock().unwrap_or_else(|e| e.into_inner());\n            if items.1 {\n                return Err(\"the mailbox is closed\".into());\n            }\n            items.0.push_back(value);\n            self.inner.1.notify_one();\n            Ok(())\n        }\n\n        /// The next message, waiting up to `timeout` (forever when None);\n        /// fails on timing out, or once closed and empty.\n        pub fn receive(&self, timeout: Option<std::time::Duration>) -> super::Result<T> {\n            let deadline = timeout.map(|t| std::time::Instant::now() + t);\n            let mut items = self.inner.0.lock().unwrap_or_else(|e| e.into_inner());\n            loop {\n                if let Some(value) = items.0.pop_front() {\n                    return Ok(value);\n                }\n                if items.1 {\n                    return Err(\"the mailbox is closed\".into());\n                }\n                items = match deadline {\n                    None => self.inner.1.wait(items).unwrap_or_else(|e| e.into_inner()),\n                    Some(at) => {\n                        let now = std::time::Instant::now();\n                        if now >= at {\n                            return Err(\"no message arrived in time\".into());\n                        }\n                        self.inner.1.wait_timeout(items, at - now).unwrap_or_else(|e| e.into_inner()).0\n                    }\n                };\n            }\n        }\n\n        /// The Mailbox ability's receive ... within d: the next message, or\n        /// None when none arrives within `within`. On a virtual clock (a\n        /// Clock handler that is not real time) it waits no real time: it\n        /// takes a message already sent, or lets the time pass on that clock\n        /// and gives None. With no clock, or the real one, it waits real\n        /// time. Fails once closed and empty.\n        pub fn receive_within(\n            &self,\n            within: std::time::Duration,\n            clock: Option<&dyn super::ClockAbility>,\n        ) -> super::Result<Option<T>> {\n            if let Some(clock) = clock.filter(|clock| !clock.real_time()) {\n                {\n                    let mut items = self.inner.0.lock().unwrap_or_else(|e| e.into_inner());\n                    if let Some(value) = items.0.pop_front() {\n                        return Ok(Some(value));\n                    }\n                    if items.1 {\n                        return Err(\"the mailbox is closed\".into());\n                    }\n                }\n                clock.sleep_micros(i64::try_from(within.as_micros()).unwrap_or(i64::MAX));\n                return Ok(None);\n            }\n            let deadline = std::time::Instant::now().checked_add(within);\n            let mut items = self.inner.0.lock().unwrap_or_else(|e| e.into_inner());\n            loop {\n                if let Some(value) = items.0.pop_front() {\n                    return Ok(Some(value));\n                }\n                if items.1 {\n                    return Err(\"the mailbox is closed\".into());\n                }\n                items = match deadline {\n                    None => self.inner.1.wait(items).unwrap_or_else(|e| e.into_inner()),\n                    Some(at) => {\n                        let now = std::time::Instant::now();\n                        if now >= at {\n                            return Ok(None);\n                        }\n                        self.inner.1.wait_timeout(items, at - now).unwrap_or_else(|e| e.into_inner()).0\n                    }\n                };\n            }\n        }\n\n        /// Refuses further messages; those already sent can still be received.\n        pub fn close(&self) {\n            self.inner.0.lock().unwrap_or_else(|e| e.into_inner()).1 = true;\n            self.inner.1.notify_all();\n        }\n    }\n}\n\n#[cfg(test)]\nmod actor_tests {\n    use super::ClockAbility as _;\n    use super::actors::{Actor, Mailbox};\n\n    struct Virtual(std::sync::atomic::AtomicI64);\n    impl super::ClockAbility for Virtual {\n        fn now_micros(&self) -> i64 {\n            self.0.load(std::sync::atomic::Ordering::SeqCst)\n        }\n        fn sleep_micros(&self, micros: i64) {\n            self.0.fetch_add(micros, std::sync::atomic::Ordering::SeqCst);\n        }\n        fn real_time(&self) -> bool {\n            false\n        }\n    }\n\n    #[test]\n    fn receive_within_waits_on_the_clock() {\n        let mailbox = Mailbox::new();\n        let clock = Virtual(std::sync::atomic::AtomicI64::new(0));\n        mailbox.send(7).unwrap();\n        let within = std::time::Duration::from_secs(60);\n        assert_eq!(mailbox.receive_within(within, Some(&clock)).unwrap(), Some(7));\n        assert_eq!(mailbox.receive_within(within, Some(&clock)).unwrap(), None);\n        assert_eq!(clock.now_micros(), 60_000_000);\n        assert_eq!(mailbox.receive_within(std::time::Duration::from_millis(10), None).unwrap(), None);\n        mailbox.close();\n        assert!(mailbox.receive_within(within, Some(&clock)).is_err());\n    }\n\n    #[test]\n    fn calls_run_one_at_a_time_in_order() {\n        let actor = Actor::new(0i64);\n        let threads: Vec<_> = (0..4)\n            .map(|_| {\n                let a = actor.clone();\n                std::thread::spawn(move || {\n                    for _ in 0..100 {\n                        a.call(|s| Ok(((), s + 1))).unwrap();\n                    }\n                })\n            })\n            .collect();\n        for t in threads {\n            t.join().unwrap();\n        }\n        actor.tell(|s| Ok(((), s * 2))).unwrap();\n        assert_eq!(actor.state().unwrap(), 800);\n        actor.stop();\n        assert!(actor.call(|s| Ok(((), s))).is_err());\n    }\n\n    #[test]\n    fn supervision_behaves_as_documented() {\n        super::actors::check_supervision().unwrap();\n    }\n\n    #[test]\n    fn mailboxes_deliver_in_order_and_close() {\n        let m = Mailbox::new();\n        m.send(1).unwrap();\n        m.send(2).unwrap();\n        m.close();\n        assert_eq!(m.receive(None).unwrap(), 1);\n        assert_eq!(m.receive(None).unwrap(), 2);\n        assert!(m.receive(None).is_err());\n        assert!(m.send(3).is_err());\n    }\n}\n\n#[cfg(test)]\nmod session_tests {\n    use super::sessions::{channel, par, spawn};\n\n    #[test]\n    fn messages_cross_in_order_both_ways() {\n        let (first, second) = channel();\n        let process = spawn(move || {\n            let a: i32 = first.receive();\n            let b: i32 = first.receive();\n            first.send(i64::from(a) + i64::from(b));\n        });\n        second.send(2i32);\n        second.send(3i32);\n        assert_eq!(second.receive::<i64>(), 5);\n        process.join();\n    }\n\n    #[test]\n    fn a_failed_process_gives_up_its_ends() {\n        let (first, second) = channel();\n        let worker = spawn(move || {\n            first.send(1i32);\n            panic!(\"boom\");\n        });\n        assert_eq!(second.receive::<i32>(), 1);\n        assert_eq!(second.try_receive::<i32>(), Err(super::sessions::PeerFailed));\n        assert!(std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| worker.join())).is_err());\n    }\n\n    #[test]\n    fn a_closed_peer_fails_a_waiting_receive() {\n        let (first, second) = channel();\n        let ((), outcome) = par(\n            move || drop(first),\n            move || std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| second.receive::<i32>())),\n        );\n        assert!(outcome.is_err());\n    }\n}\n\n/// A descriptor text's data types, for decoding and encoding values whose\n/// descriptors name them.\npub fn values_table(text: &str) -> Values {\n    Values::new(\n        read_descriptor(text)\n            .into_iter()\n            .filter(|f| matches!(f, Sexp::List(_)) && f.kind() == \"data\")\n            .map(|f| (f.items()[1].name(), f))\n            .collect(),\n    )\n}\n\n/// The first form of a descriptor text.\npub fn descriptor(text: &str) -> Sexp {\n    read_descriptor(text).into_iter().next().expect(\"a descriptor\")\n}\n\n// Distribution. Values cross the network in a canonical binary encoding\n// driven by their type descriptor (the same descriptors as generation), so\n// no tags are sent and every target writes the same bytes:\n//   int: zigzag LEB128 of the integer (any size)      bool: 0 or 1\n//   text, bytes: LEB128 length, then UTF-8 or raw     unit: nothing\n//   list: LEB128 count, then items                     maybe: 0, or 1 then the value\n//   either: 0 then left, or 1 then right               data: LEB128 constructor index, then fields\n// A node sends frames over a Transport (in memory, TCP or HTTP): kind,\n// entity name, the sender's address, an id and a payload. The protocol and\n// the bytes follow the Python reference, so nodes on different targets\n// interoperate.\npub mod net {\n    use super::{BigInt, Result, SplitMix64, Sexp, Value, Values, actors, read_descriptor, render, values_from};\n    use num_traits::{One, Signed, ToPrimitive, Zero};\n    use std::collections::{HashMap, HashSet, VecDeque};\n    use std::io::{Read, Write};\n    use std::sync::atomic::{AtomicBool, AtomicU64, Ordering};\n    use std::sync::{Arc, Condvar, Mutex, MutexGuard, Weak};\n    use std::time::{Duration, Instant};\n\n    /// The start of the error of a node that could not be reached, or did\n    /// not answer in time.\n    pub const UNREACHABLE: &str = \"unreachable: \";\n    /// The start of the error of a channel end whose other end failed.\n    pub const PEER_FAILED: &str = \"peer failed: \";\n    /// The start of the error of bytes that are not a value of the type.\n    pub const WIRE: &str = \"wire: \";\n\n    pub fn is_unreachable(error: &str) -> bool {\n        error.starts_with(UNREACHABLE)\n    }\n\n    pub fn is_peer_failed(error: &str) -> bool {\n        error.starts_with(PEER_FAILED)\n    }\n\n    fn lock<T>(m: &Mutex<T>) -> MutexGuard<'_, T> {\n        m.lock().unwrap_or_else(|e| e.into_inner())\n    }\n\n    fn wire_error<T>(message: impl std::fmt::Display) -> Result<T> {\n        Err(format!(\"{WIRE}{message}\"))\n    }\n\n    fn put_varint(out: &mut Vec<u8>, n: &BigInt) {\n        let mut n = n.clone();\n        let mask = BigInt::from(0x7F);\n        loop {\n            let byte = (&n & &mask).to_u8().unwrap_or(0);\n            n >>= 7;\n            if n.is_zero() {\n                out.push(byte);\n                return;\n            }\n            out.push(byte | 0x80);\n        }\n    }\n\n    fn get_varint(buf: &[u8], pos: &mut usize) -> Result<BigInt> {\n        let mut result = BigInt::zero();\n        let mut shift = 0usize;\n        loop {\n            let Some(&byte) = buf.get(*pos) else {\n                return wire_error(\"the bytes end in the middle of a value\");\n            };\n            *pos += 1;\n            result |= BigInt::from(byte & 0x7F) << shift;\n            if byte < 0x80 {\n                return Ok(result);\n            }\n            shift += 7;\n        }\n    }\n\n    fn put_len(out: &mut Vec<u8>, n: usize) {\n        put_varint(out, &BigInt::from(n));\n    }\n\n    fn get_len(buf: &[u8], pos: &mut usize) -> Result<usize> {\n        match get_varint(buf, pos)?.to_usize() {\n            Some(n) => Ok(n),\n            None => wire_error(\"a length too large\"),\n        }\n    }\n\n    fn kind(d: &Sexp) -> &str {\n        d.kind()\n    }\n\n    /// Appends the encoding of v, a value of descriptor d.\n    pub fn wire_put(values: &Values, d: &Sexp, v: &Value, out: &mut Vec<u8>) -> Result<()> {\n        let d = values.resolve(d);\n        let items = d.items();\n        match (kind(d), v) {\n            (\"int\", Value::Integer(n)) => {\n                let below = items[2].bound().is_some_and(|lo| *n < lo);\n                let above = items[3].bound().is_some_and(|hi| *n > hi);\n                if below || above {\n                    return wire_error(format!(\"{n} is not a {}\", items[1].name()));\n                }\n                let z = if n.is_negative() { -n * 2 - 1 } else { n * 2 };\n                put_varint(out, &z);\n            }\n            (\"bool\", Value::Bool(b)) => out.push(u8::from(*b)),\n            (\"text\" | \"end\", Value::Text(s)) => {\n                put_len(out, s.len());\n                out.extend_from_slice(s.as_bytes());\n            }\n            (\"bytes\", Value::Bytes(b)) => {\n                put_len(out, b.len());\n                out.extend_from_slice(b);\n            }\n            (\"unit\", _) => {}\n            (\"list\", Value::List(xs)) => {\n                put_len(out, xs.len());\n                for x in xs {\n                    wire_put(values, &items[1], x, out)?;\n                }\n            }\n            (\"maybe\", Value::Maybe(None)) => out.push(0),\n            (\"maybe\", Value::Maybe(Some(x))) => {\n                out.push(1);\n                wire_put(values, &items[1], x, out)?;\n            }\n            (\"either\", Value::Left(x)) => {\n                out.push(0);\n                wire_put(values, &items[1], x, out)?;\n            }\n            (\"either\", Value::Right(x)) => {\n                out.push(1);\n                wire_put(values, &items[2], x, out)?;\n            }\n            (\"data\", Value::Data(tag, fields)) => {\n                let Some(index) = items[2..].iter().position(|c| c.items()[1].name() == *tag) else {\n                    return wire_error(format!(\"{tag} is not a constructor of {}\", items[1].name()));\n                };\n                put_len(out, index);\n                for (field, fd) in fields.iter().zip(&items[2 + index].items()[2..]) {\n                    wire_put(values, fd, field, out)?;\n                }\n            }\n            (k, other) => return wire_error(format!(\"{} is not a {k}\", render(other))),\n        }\n        Ok(())\n    }\n\n    /// The value of descriptor d encoded at pos, moving pos past it.\n    pub fn wire_get(values: &Values, d: &Sexp, buf: &[u8], pos: &mut usize) -> Result<Value> {\n        let d = values.resolve(d);\n        let items = d.items();\n        let flag = |pos: &mut usize, what: &str| -> Result<bool> {\n            match buf.get(*pos) {\n                Some(b) if *b <= 1 => {\n                    *pos += 1;\n                    Ok(*b == 1)\n                }\n                _ => wire_error(format!(\"not a {what}\")),\n            }\n        };\n        Ok(match kind(d) {\n            \"int\" => {\n                let z = get_varint(buf, pos)?;\n                let two = BigInt::from(2);\n                let v = if (&z % &two).is_zero() { &z / &two } else { -((&z + BigInt::one()) / &two) };\n                let below = items[2].bound().is_some_and(|lo| v < lo);\n                let above = items[3].bound().is_some_and(|hi| v > hi);\n                if below || above {\n                    return wire_error(format!(\"{v} is out of range for {}\", items[1].name()));\n                }\n                Value::Integer(v)\n            }\n            \"bool\" => Value::Bool(flag(pos, \"Bool\")?),\n            k @ (\"text\" | \"bytes\" | \"end\") => {\n                let n = get_len(buf, pos)?;\n                if *pos + n > buf.len() {\n                    return wire_error(\"the bytes end in the middle of a value\");\n                }\n                let raw = buf[*pos..*pos + n].to_vec();\n                *pos += n;\n                if k == \"bytes\" {\n                    Value::Bytes(raw)\n                } else {\n                    match String::from_utf8(raw) {\n                        Ok(s) => Value::Text(s),\n                        Err(_) => return wire_error(\"text that is not UTF-8\"),\n                    }\n                }\n            }\n            \"unit\" => Value::Unit,\n            \"list\" => {\n                let n = get_len(buf, pos)?;\n                let mut xs = Vec::new();\n                for _ in 0..n {\n                    xs.push(wire_get(values, &items[1], buf, pos)?);\n                }\n                Value::List(xs)\n            }\n            \"maybe\" => {\n                if flag(pos, \"Maybe\")? {\n                    Value::Maybe(Some(Box::new(wire_get(values, &items[1], buf, pos)?)))\n                } else {\n                    Value::Maybe(None)\n                }\n            }\n            \"either\" => {\n                if flag(pos, \"Either\")? {\n                    Value::Right(Box::new(wire_get(values, &items[2], buf, pos)?))\n                } else {\n                    Value::Left(Box::new(wire_get(values, &items[1], buf, pos)?))\n                }\n            }\n            \"data\" => {\n                let index = get_len(buf, pos)?;\n                let ctors = &items[2..];\n                let Some(ctor) = ctors.get(index) else {\n                    return wire_error(format!(\"no constructor {index} in {}\", items[1].name()));\n                };\n                let mut fields = Vec::new();\n                for fd in &ctor.items()[2..] {\n                    fields.push(wire_get(values, fd, buf, pos)?);\n                }\n                Value::Data(ctor.items()[1].name(), fields)\n            }\n            other => return wire_error(format!(\"unknown descriptor {other}\")),\n        })\n    }\n\n    /// The value's canonical bytes.\n    pub fn wire_encode(values: &Values, d: &Sexp, v: &Value) -> Result<Vec<u8>> {\n        let mut out = Vec::new();\n        wire_put(values, d, v, &mut out)?;\n        Ok(out)\n    }\n\n    /// The value encoded by exactly these bytes.\n    pub fn wire_decode(values: &Values, d: &Sexp, data: &[u8]) -> Result<Value> {\n        let mut pos = 0;\n        let v = wire_get(values, d, data, &mut pos)?;\n        if pos != data.len() {\n            return wire_error(\"extra bytes after the value\");\n        }\n        Ok(v)\n    }\n\n    fn hex(bytes: &[u8]) -> String {\n        bytes.iter().map(|b| format!(\"{b:02x}\")).collect()\n    }\n\n    /// count values generated from one seed, encoded, in hexadecimal.\n    pub fn wire_encoded(text: &str, seed: u64, size: i64, count: i64) -> Vec<String> {\n        let (values, d) = values_from(text);\n        let mut random = SplitMix64::new(seed);\n        (0..count)\n            .map(|_| {\n                let v = values.generate(&d, &mut random, size);\n                hex(&wire_encode(&values, &d, &v).unwrap_or_else(|e| panic!(\"{e}\")))\n            })\n            .collect()\n    }\n\n    /// Whether count generated values decode to themselves.\n    pub fn wire_round_trips(text: &str, seed: u64, size: i64, count: i64) -> bool {\n        let (values, d) = values_from(text);\n        let mut random = SplitMix64::new(seed);\n        (0..count).all(|_| {\n            let v = values.generate(&d, &mut random, size);\n            match wire_encode(&values, &d, &v).and_then(|bytes| wire_decode(&values, &d, &bytes)) {\n                Ok(back) => render(&back) == render(&v),\n                Err(_) => false,\n            }\n        })\n    }\n\n    fn text_d() -> Sexp {\n        Sexp::List(vec![Sexp::Atom(\"text\".into())])\n    }\n\n    fn seq_d() -> Sexp {\n        Sexp::List(vec![Sexp::Atom(\"int\".into()), Sexp::Atom(\"Int64\".into()), Sexp::Blank, Sexp::Blank])\n    }\n\n    fn id_d() -> Sexp {\n        Sexp::List(vec![Sexp::Atom(\"int\".into()), Sexp::Atom(\"UInt64\".into()), Sexp::Int(BigInt::zero()), Sexp::Blank])\n    }\n\n    fn bytes_d() -> Sexp {\n        Sexp::List(vec![Sexp::Atom(\"bytes\".into())])\n    }\n\n    fn no_types() -> Values {\n        Values::new(HashMap::new())\n    }\n\n    fn put_text(out: &mut Vec<u8>, s: &str) {\n        put_len(out, s.len());\n        out.extend_from_slice(s.as_bytes());\n    }\n\n    fn get_text(buf: &[u8], pos: &mut usize) -> Result<String> {\n        match wire_get(&no_types(), &text_d(), buf, pos)? {\n            Value::Text(s) => Ok(s),\n            _ => wire_error(\"not text\"),\n        }\n    }\n\n    fn put_seq(out: &mut Vec<u8>, seq: i64) {\n        let _ = wire_put(&no_types(), &seq_d(), &Value::Integer(seq.into()), out);\n    }\n\n    fn get_seq(buf: &[u8], pos: &mut usize) -> Result<i64> {\n        match wire_get(&no_types(), &seq_d(), buf, pos)? {\n            Value::Integer(n) => n.to_i64().map_or_else(|| wire_error(\"a sequence number too large\"), Ok),\n            _ => wire_error(\"not a sequence number\"),\n        }\n    }\n\n    fn frame_encode(kind: &str, to: &str, source: &str, id: u64, payload: &[u8]) -> Vec<u8> {\n        let mut out = Vec::new();\n        put_text(&mut out, kind);\n        put_text(&mut out, to);\n        put_text(&mut out, source);\n        let _ = wire_put(&no_types(), &id_d(), &Value::Integer(id.into()), &mut out);\n        put_len(&mut out, payload.len());\n        out.extend_from_slice(payload);\n        out\n    }\n\n    struct Frame {\n        kind: String,\n        to: String,\n        source: String,\n        id: u64,\n        payload: Vec<u8>,\n    }\n\n    fn frame_decode(data: &[u8]) -> Result<Frame> {\n        let mut pos = 0;\n        let kind = get_text(data, &mut pos)?;\n        let to = get_text(data, &mut pos)?;\n        let source = get_text(data, &mut pos)?;\n        let id = match wire_get(&no_types(), &id_d(), data, &mut pos)? {\n            Value::Integer(n) => n.to_u64().unwrap_or(0),\n            _ => 0,\n        };\n        let payload = match wire_get(&no_types(), &bytes_d(), data, &mut pos)? {\n            Value::Bytes(b) => b,\n            _ => Vec::new(),\n        };\n        if pos != data.len() {\n            return wire_error(\"extra bytes after a frame\");\n        }\n        Ok(Frame { kind, to, source, id, payload })\n    }\n\n    /// \"tcp://host:port/name\" as (\"tcp://host:port\", \"name\").\n    fn split_address(address: &str) -> Result<(String, String)> {\n        match address.rsplit_once('/') {\n            Some((node, name)) if node.contains(\"://\") && !node.ends_with(':') && !node.ends_with('/') => {\n                Ok((node.to_string(), name.to_string()))\n            }\n            _ => Err(format!(\"{address:?} is not an address such as tcp://127.0.0.1:7000/name\")),\n        }\n    }\n\n    /// What a transport calls with each frame that arrives.\n    pub type Deliver = Arc<dyn Fn(Vec<u8>) + Send + Sync>;\n\n    /// Moves frames between nodes: start begins calling deliver for every\n    /// frame that arrives; send sends one to the node at that address, best\n    /// effort (an error starting UNREACHABLE when it cannot); close stops.\n    pub trait Transport: Send + Sync {\n        fn address(&self) -> String;\n        fn start(&self, deliver: Deliver);\n        fn send(&self, node: &str, frame: Vec<u8>) -> Result<()>;\n        fn close(&self);\n        /// Whether a node on this transport skips the handshake and sends\n        /// frames in the clear. Only the transport that\n        /// MemoryNetwork::insecure_transport_for_tests makes says so: no\n        /// other transport can name the marker.\n        #[doc(hidden)]\n        fn insecure_for_tests(&self) -> Option<sealed::InsecureForTests> {\n            None\n        }\n    }\n\n    mod sealed {\n        /// The marker of the in-memory transport made for tests only.\n        pub struct InsecureForTests;\n    }\n\n    /// Nodes in one process, with faults for testing: each frame may be lost\n    /// or duplicated, and is delayed by up to delay (so frames can overtake\n    /// each other); partition cuts nodes off until heal. Clones share it.\n    #[derive(Clone)]\n    pub struct MemoryNetwork {\n        inner: Arc<NetworkInner>,\n    }\n\n    struct NetworkInner {\n        state: Mutex<NetworkState>,\n        loss: f64,\n        duplicate: f64,\n        delay: Duration,\n        // With recording, every record sent, as the network saw it.\n        recorded: Mutex<Option<Vec<Vec<u8>>>>,\n    }\n\n    struct NetworkState {\n        random: SplitMix64,\n        nodes: HashMap<String, Deliver>,\n        groups: Option<Vec<HashSet<String>>>,\n    }\n\n    impl MemoryNetwork {\n        pub fn new(seed: u64, loss: f64, duplicate: f64, delay: Duration) -> Self {\n            MemoryNetwork {\n                inner: Arc::new(NetworkInner {\n                    state: Mutex::new(NetworkState { random: SplitMix64::new(seed), nodes: HashMap::new(), groups: None }),\n                    loss,\n                    duplicate,\n                    delay,\n                    recorded: Mutex::new(None),\n                }),\n            }\n        }\n\n        /// The network, recording every record sent on it from now on, as\n        /// the network saw it (see recorded): MemoryNetwork::new(...)\n        /// .with_recording().\n        pub fn with_recording(self) -> Self {\n            lock(&self.inner.recorded).get_or_insert_with(Vec::new);\n            self\n        }\n\n        /// Every record sent since with_recording, in order.\n        pub fn recorded(&self) -> Vec<Vec<u8>> {\n            lock(&self.inner.recorded).clone().unwrap_or_default()\n        }\n\n        /// A transport whose node skips the handshake and sends frames in\n        /// the clear: for tests of the frame layer only. Only an in-memory\n        /// network makes one, and no configuration selects it.\n        pub fn insecure_transport_for_tests(&self, name: &str) -> Arc<dyn Transport> {\n            Arc::new(InsecureMemoryTransport(MemoryTransport { network: self.clone(), address: format!(\"mem://{name}\") }))\n        }\n\n        /// A network without faults.\n        pub fn reliable() -> Self {\n            Self::new(0, 0.0, 0.0, Duration::ZERO)\n        }\n\n        /// A transport for a node named name, at mem://name.\n        pub fn transport(&self, name: &str) -> Arc<dyn Transport> {\n            Arc::new(MemoryTransport { network: self.clone(), address: format!(\"mem://{name}\") })\n        }\n\n        /// Only nodes named in the same group reach each other.\n        pub fn partition(&self, groups: &[&[&str]]) {\n            lock(&self.inner.state).groups =\n                Some(groups.iter().map(|g| g.iter().map(|n| format!(\"mem://{n}\")).collect()).collect());\n        }\n\n        pub fn heal(&self) {\n            lock(&self.inner.state).groups = None;\n        }\n\n        fn send(&self, source: &str, node: &str, frame: Vec<u8>) -> Result<()> {\n            if let Some(recorded) = lock(&self.inner.recorded).as_mut() {\n                recorded.push(frame.clone());\n            }\n            let (deliver, delays) = {\n                let mut state = lock(&self.inner.state);\n                let Some(deliver) = state.nodes.get(node).cloned() else {\n                    return Err(format!(\"{UNREACHABLE}no node at {node}\"));\n                };\n                if let Some(groups) = &state.groups {\n                    if !groups.iter().any(|g| g.contains(source) && g.contains(node)) {\n                        return Ok(());\n                    }\n                }\n                let chance = |random: &mut SplitMix64, p: f64| p > 0.0 && (random.below(1 << 30) as f64) < p * (1u64 << 30) as f64;\n                if chance(&mut state.random, self.inner.loss) {\n                    return Ok(());\n                }\n                let copies = if chance(&mut state.random, self.inner.duplicate) { 2 } else { 1 };\n                let delays: Vec<Duration> =\n                    (0..copies).map(|_| self.inner.delay.mul_f64(state.random.below(1001) as f64 / 1000.0)).collect();\n                (deliver, delays)\n            };\n            for wait in delays {\n                let (deliver, frame) = (deliver.clone(), frame.clone());\n                std::thread::spawn(move || {\n                    if !wait.is_zero() {\n                        std::thread::sleep(wait);\n                    }\n                    deliver(frame);\n                });\n            }\n            Ok(())\n        }\n    }\n\n    struct MemoryTransport {\n        network: MemoryNetwork,\n        address: String,\n    }\n\n    impl Transport for MemoryTransport {\n        fn address(&self) -> String {\n            self.address.clone()\n        }\n\n        fn start(&self, deliver: Deliver) {\n            lock(&self.network.inner.state).nodes.insert(self.address.clone(), deliver);\n        }\n\n        fn send(&self, node: &str, frame: Vec<u8>) -> Result<()> {\n            self.network.send(&self.address, node, frame)\n        }\n\n        fn close(&self) {\n            lock(&self.network.inner.state).nodes.remove(&self.address);\n        }\n    }\n\n    /// In memory, without the handshake: tests only (see\n    /// MemoryNetwork::insecure_transport_for_tests).\n    pub struct InsecureMemoryTransport(MemoryTransport);\n\n    impl Transport for InsecureMemoryTransport {\n        fn address(&self) -> String {\n            self.0.address()\n        }\n\n        fn start(&self, deliver: Deliver) {\n            self.0.start(deliver)\n        }\n\n        fn send(&self, node: &str, frame: Vec<u8>) -> Result<()> {\n            self.0.send(node, frame)\n        }\n\n        fn close(&self) {\n            self.0.close()\n        }\n\n        fn insecure_for_tests(&self) -> Option<sealed::InsecureForTests> {\n            Some(sealed::InsecureForTests)\n        }\n    }\n\n    // A listening socket polled until closed, so close needs no wake-up.\n    struct Listener {\n        socket: std::net::TcpListener,\n        closed: Arc<AtomicBool>,\n        accepted: Arc<Mutex<Vec<std::net::TcpStream>>>,\n    }\n\n    impl Listener {\n        fn bind(host: &str, port: u16) -> Result<(Listener, u16)> {\n            let socket = std::net::TcpListener::bind((host, port)).map_err(|e| format!(\"cannot listen on {host}:{port}: {e}\"))?;\n            let port = socket.local_addr().map_err(|e| e.to_string())?.port();\n            socket.set_nonblocking(true).map_err(|e| e.to_string())?;\n            Ok((Listener { socket, closed: Arc::new(AtomicBool::new(false)), accepted: Arc::new(Mutex::new(Vec::new())) }, port))\n        }\n\n        // Accepts connections until closed, handing each to serve on its own thread.\n        fn run(&self, serve: Arc<dyn Fn(std::net::TcpStream) + Send + Sync>) {\n            let socket = match self.socket.try_clone() {\n                Ok(socket) => socket,\n                Err(_) => return,\n            };\n            let (closed, accepted) = (self.closed.clone(), self.accepted.clone());\n            std::thread::spawn(move || {\n                while !closed.load(Ordering::SeqCst) {\n                    match socket.accept() {\n                        Ok((stream, _)) => {\n                            let _ = stream.set_nonblocking(false);\n                            if let Ok(copy) = stream.try_clone() {\n                                lock(&accepted).push(copy);\n                            }\n                            let serve = serve.clone();\n                            std::thread::spawn(move || serve(stream));\n                        }\n                        Err(_) => std::thread::sleep(Duration::from_millis(5)),\n                    }\n                }\n            });\n        }\n\n        fn close(&self) {\n            self.closed.store(true, Ordering::SeqCst);\n            for stream in lock(&self.accepted).drain(..) {\n                let _ = stream.shutdown(std::net::Shutdown::Both);\n            }\n        }\n    }\n\n    fn read_exactly(stream: &mut std::net::TcpStream, n: usize) -> Option<Vec<u8>> {\n        let mut data = vec![0u8; n];\n        stream.read_exact(&mut data).ok()?;\n        Some(data)\n    }\n\n    fn host_port(rest: &str) -> Result<(String, u16)> {\n        let rest = rest.split('/').next().unwrap_or(rest);\n        match rest.rsplit_once(':') {\n            Some((host, port)) => Ok((host.to_string(), port.parse().map_err(|_| format!(\"{UNREACHABLE}bad port in {rest}\"))?)),\n            None => Err(format!(\"{UNREACHABLE}no port in {rest}\")),\n        }\n    }\n\n    fn connect(host: &str, port: u16) -> std::io::Result<std::net::TcpStream> {\n        use std::net::ToSocketAddrs;\n        let mut last = std::io::Error::other(\"no address\");\n        for address in (host, port).to_socket_addrs()? {\n            match std::net::TcpStream::connect_timeout(&address, Duration::from_secs(5)) {\n                Ok(stream) => {\n                    let _ = stream.set_nodelay(true);\n                    return Ok(stream);\n                }\n                Err(e) => last = e,\n            }\n        }\n        Err(last)\n    }\n\n    /// Frames over TCP, each a 4-byte big-endian length then the frame.\n    /// Port 0 picks a free port; the address is tcp://host:port.\n    pub struct TcpTransport {\n        listener: Listener,\n        address: String,\n        connections: Mutex<HashMap<String, std::net::TcpStream>>,\n    }\n\n    impl TcpTransport {\n        pub fn new(host: &str, port: u16) -> Result<Arc<dyn Transport>> {\n            let (listener, port) = Listener::bind(host, port)?;\n            Ok(Arc::new(TcpTransport { listener, address: format!(\"tcp://{host}:{port}\"), connections: Mutex::new(HashMap::new()) }))\n        }\n\n        /// On 127.0.0.1, at a free port.\n        pub fn local() -> Result<Arc<dyn Transport>> {\n            Self::new(\"127.0.0.1\", 0)\n        }\n    }\n\n    impl Transport for TcpTransport {\n        fn address(&self) -> String {\n            self.address.clone()\n        }\n\n        fn start(&self, deliver: Deliver) {\n            self.listener.run(Arc::new(move |mut stream: std::net::TcpStream| {\n                while let Some(header) = read_exactly(&mut stream, 4) {\n                    let n = u32::from_be_bytes([header[0], header[1], header[2], header[3]]) as usize;\n                    let Some(frame) = read_exactly(&mut stream, n) else { return };\n                    deliver(frame);\n                }\n            }));\n        }\n\n        fn send(&self, node: &str, frame: Vec<u8>) -> Result<()> {\n            let (host, port) = host_port(node.trim_start_matches(\"tcp://\"))?;\n            let mut data = (frame.len() as u32).to_be_bytes().to_vec();\n            data.extend_from_slice(&frame);\n            let mut connections = lock(&self.connections);\n            for attempt in 0..2 {\n                let stream = match connections.get_mut(node) {\n                    Some(stream) => stream,\n                    None => match connect(&host, port) {\n                        Ok(stream) => connections.entry(node.to_string()).or_insert(stream),\n                        Err(e) if attempt == 1 => return Err(format!(\"{UNREACHABLE}cannot reach {node}: {e}\")),\n                        Err(_) => continue,\n                    },\n                };\n                match stream.write_all(&data) {\n                    Ok(()) => return Ok(()),\n                    Err(e) => {\n                        connections.remove(node);\n                        if attempt == 1 {\n                            return Err(format!(\"{UNREACHABLE}cannot reach {node}: {e}\"));\n                        }\n                    }\n                }\n            }\n            Ok(())\n        }\n\n        fn close(&self) {\n            self.listener.close();\n            for (_, stream) in lock(&self.connections).drain() {\n                let _ = stream.shutdown(std::net::Shutdown::Both);\n            }\n        }\n    }\n\n    /// Frames as HTTP POST bodies to /lawspec; the address is http://host:port.\n    pub struct HttpTransport {\n        listener: Listener,\n        address: String,\n    }\n\n    impl HttpTransport {\n        pub fn new(host: &str, port: u16) -> Result<Arc<dyn Transport>> {\n            let (listener, port) = Listener::bind(host, port)?;\n            Ok(Arc::new(HttpTransport { listener, address: format!(\"http://{host}:{port}\") }))\n        }\n\n        /// On 127.0.0.1, at a free port.\n        pub fn local() -> Result<Arc<dyn Transport>> {\n            Self::new(\"127.0.0.1\", 0)\n        }\n    }\n\n    // An HTTP/1.1 message's head (start line and headers) and its body.\n    fn read_http(stream: &mut std::net::TcpStream) -> Option<(String, Vec<u8>)> {\n        let mut head = Vec::new();\n        let mut byte = [0u8; 1];\n        while !head.ends_with(b\"\\r\\n\\r\\n\") {\n            if stream.read(&mut byte).ok()? == 0 {\n                return None;\n            }\n            head.push(byte[0]);\n            if head.len() > 65536 {\n                return None;\n            }\n        }\n        let head = String::from_utf8_lossy(&head).to_string();\n        let length = head\n            .lines()\n            .filter_map(|l| l.split_once(':'))\n            .find(|(k, _)| k.trim().eq_ignore_ascii_case(\"content-length\"))\n            .and_then(|(_, v)| v.trim().parse::<usize>().ok())\n            .unwrap_or(0);\n        let body = read_exactly(stream, length)?;\n        Some((head, body))\n    }\n\n    impl Transport for HttpTransport {\n        fn address(&self) -> String {\n            self.address.clone()\n        }\n\n        fn start(&self, deliver: Deliver) {\n            self.listener.run(Arc::new(move |mut stream: std::net::TcpStream| {\n                while let Some((head, body)) = read_http(&mut stream) {\n                    let first = head.lines().next().unwrap_or(\"\").to_string();\n                    let ours = first.starts_with(\"POST /lawspec \");\n                    let status = if ours { \"204 No Content\" } else { \"404 Not Found\" };\n                    if stream.write_all(format!(\"HTTP/1.1 {status}\\r\\nContent-Length: 0\\r\\n\\r\\n\").as_bytes()).is_err() {\n                        return;\n                    }\n                    if ours {\n                        deliver(body);\n                    }\n                    if head.to_ascii_lowercase().contains(\"connection: close\") {\n                        return;\n                    }\n                }\n            }));\n        }\n\n        fn send(&self, node: &str, frame: Vec<u8>) -> Result<()> {\n            let (host, port) = host_port(node.trim_start_matches(\"http://\"))?;\n            let unreachable = |e: &dyn std::fmt::Display| format!(\"{UNREACHABLE}cannot reach {node}: {e}\");\n            let mut stream = connect(&host, port).map_err(|e| unreachable(&e))?;\n            let _ = stream.set_read_timeout(Some(Duration::from_secs(5)));\n            let request = format!(\n                \"POST /lawspec HTTP/1.1\\r\\nHost: {host}:{port}\\r\\nContent-Type: application/octet-stream\\r\\nContent-Length: {}\\r\\nConnection: close\\r\\n\\r\\n\",\n                frame.len()\n            );\n            stream.write_all(request.as_bytes()).map_err(|e| unreachable(&e))?;\n            stream.write_all(&frame).map_err(|e| unreachable(&e))?;\n            let (head, _) = read_http(&mut stream).ok_or_else(|| unreachable(&\"no answer\"))?;\n            let status = head.split_whitespace().nth(1).unwrap_or(\"\");\n            if status.starts_with('2') { Ok(()) } else { Err(unreachable(&format!(\"HTTP {status}\"))) }\n        }\n\n        fn close(&self) {\n            self.listener.close();\n        }\n    }\n\n    // The secure network handler lives in lawspec_network, which the compiler\n    // writes beside this runtime when a program imports lawspec.network: it\n    // needs the crypto libraries, which programs without nodes do without.\n    // Its install registers it here (register_secure_network); the generated\n    // tests of such a program call it.\n\n    /// A node's secure layer (lawspec_network's): send seals a frame for a\n    /// peer (or queues it while a handshake runs); receive gives the frame a\n    /// record carries, or None for a handshake record or one that fails.\n    pub trait SecureLayer: Send + Sync {\n        fn send(&self, peer: &str, frame: Vec<u8>) -> Result<()>;\n        fn receive(&self, record: &[u8]) -> Option<Vec<u8>>;\n        fn as_any(&self) -> &dyn std::any::Any;\n    }\n\n    /// The secure network handler: layer makes a node's secure layer (by\n    /// default identity and trust), token a one-time take token from its\n    /// secure generator.\n    pub trait SecureNetwork: Send + Sync {\n        fn layer(&self, node: NodeLink) -> Result<Box<dyn SecureLayer>>;\n        fn token(&self) -> String;\n    }\n\n    static SECURE_NETWORK: std::sync::OnceLock<Arc<dyn SecureNetwork>> = std::sync::OnceLock::new();\n\n    /// Registers the secure network handler; the first one stays.\n    pub fn register_secure_network(provider: Arc<dyn SecureNetwork>) {\n        let _ = SECURE_NETWORK.set(provider);\n    }\n\n    /// The error of a node made without the secure network handler.\n    pub const NO_SECURE_NETWORK: &str = \"a node needs the secure network handler: add `import lawspec.network` \\\n        to a unit of the program, and call lawspec_network::install()\";\n\n    fn secure_network() -> Result<Arc<dyn SecureNetwork>> {\n        SECURE_NETWORK.get().cloned().ok_or_else(|| NO_SECURE_NETWORK.to_string())\n    }\n\n    /// What a secure layer holds of its node: its address, sending a record\n    /// to a peer node, and whether the node has closed. It does not keep the\n    /// node alive.\n    #[derive(Clone)]\n    pub struct NodeLink {\n        node: Weak<NodeInner>,\n        address: String,\n    }\n\n    impl NodeLink {\n        pub fn address(&self) -> &str {\n            &self.address\n        }\n\n        /// Sends a record as it is (an error starting UNREACHABLE when it\n        /// cannot, or once the node is gone).\n        pub fn send(&self, peer: &str, record: Vec<u8>) -> Result<()> {\n            match self.node.upgrade() {\n                Some(node) => node.transport.send(peer, record),\n                None => Err(format!(\"{UNREACHABLE}{} has closed\", self.address)),\n            }\n        }\n\n        pub fn closed(&self) -> bool {\n            self.node.upgrade().is_none_or(|node| node.closed.load(Ordering::SeqCst))\n        }\n    }\n\n    /// A one-time token from a secure generator: 32 bytes as 64 lowercase\n    /// hexadecimal digits, as SecureRandom's secureToken gives. The secure\n    /// network handler's generator when it is installed, else the operating\n    /// system's (/dev/urandom).\n    pub fn secure_token() -> String {\n        if let Some(provider) = SECURE_NETWORK.get() {\n            return provider.token();\n        }\n        let mut bytes = [0u8; 32];\n        match std::fs::File::open(\"/dev/urandom\").and_then(|mut f| f.read_exact(&mut bytes)) {\n            Ok(()) => hex(&bytes),\n            Err(error) => panic!(\n                \"a take token needs a secure generator: /dev/urandom ({error}); add `import lawspec.network` and call lawspec_network::install()\"\n            ),\n        }\n    }\n\n    // Something a node names: it handles the frames sent to it.\n    trait Entity: Send + Sync {\n        fn receive(&self, node: &Node, kind: &str, source: &str, id: u64, payload: Vec<u8>);\n    }\n\n    struct Slot {\n        reply: Mutex<Option<Vec<u8>>>,\n        ready: Condvar,\n    }\n\n    /// A process's presence on a network: it names local mailboxes, actors,\n    /// channel ends and definitions, so other nodes can reach them at\n    /// <node address>/<name>, and it sends to theirs. Order is kept within one\n    /// channel; a mailbox send is best effort, and a request is sent again\n    /// until answered (the receiver runs it once), failing with UNREACHABLE\n    /// after its timeout. Clones share the node.\n    #[derive(Clone)]\n    pub struct Node {\n        inner: Arc<NodeInner>,\n    }\n\n    struct NodeInner {\n        transport: Arc<dyn Transport>,\n        address: String,\n        // None only on the transport made for tests that skips the handshake.\n        secure: Option<Box<dyn SecureLayer>>,\n        entities: Mutex<HashMap<String, Arc<dyn Entity>>>,\n        pending: Mutex<HashMap<u64, Arc<Slot>>>,\n        // Requests seen, by sender and id, with their reply once sent.\n        seen: Mutex<(HashMap<(String, u64), Option<Vec<u8>>>, VecDeque<(String, u64)>)>,\n        ids: AtomicU64,\n        closed: AtomicBool,\n    }\n\n    impl Node {\n        /// A node on transport. Unless it is the transport made for tests\n        /// only (MemoryNetwork::insecure_transport_for_tests), the node is\n        /// secure: the secure network handler (lawspec_network, installed)\n        /// gives it the identity lawspec.json binds, or a fresh one. Panics\n        /// without that handler, or when lawspec-network.conf is unreadable;\n        /// lawspec_network::node takes an identity and trusted peers.\n        pub fn new(transport: Arc<dyn Transport>) -> Node {\n            Node::with_secure_layer(transport, |link| {\n                secure_network().and_then(|provider| provider.layer(link)).unwrap_or_else(|error| panic!(\"{error}\"))\n            })\n        }\n\n        /// A node whose secure layer make gives (it is not called for the\n        /// transport made for tests only, whose node sends frames in the\n        /// clear; no other transport can skip the layer).\n        pub fn with_secure_layer(transport: Arc<dyn Transport>, make: impl FnOnce(NodeLink) -> Box<dyn SecureLayer>) -> Node {\n            let insecure = transport.insecure_for_tests().is_some();\n            let address = transport.address();\n            let inner = Arc::new_cyclic(|weak: &Weak<NodeInner>| NodeInner {\n                secure: if insecure { None } else { Some(make(NodeLink { node: weak.clone(), address: address.clone() })) },\n                address,\n                transport: transport.clone(),\n                entities: Mutex::new(HashMap::new()),\n                pending: Mutex::new(HashMap::new()),\n                seen: Mutex::new((HashMap::new(), VecDeque::new())),\n                ids: AtomicU64::new(1),\n                closed: AtomicBool::new(false),\n            });\n            let weak: Weak<NodeInner> = Arc::downgrade(&inner);\n            transport.start(Arc::new(move |record| {\n                if let Some(inner) = weak.upgrade() {\n                    Node { inner }.arrive(record);\n                }\n            }));\n            Node { inner }\n        }\n\n        pub fn address(&self) -> String {\n            self.inner.address.clone()\n        }\n\n        /// The node's secure layer; None on the transport made for tests only.\n        pub fn secure_layer(&self) -> Option<&dyn SecureLayer> {\n            self.inner.secure.as_deref()\n        }\n\n        // A record from the transport: a frame in the clear on the transport\n        // made for tests, else a handshake or sealed record.\n        fn arrive(&self, record: Vec<u8>) {\n            match &self.inner.secure {\n                None => self.deliver(record),\n                Some(secure) => {\n                    if let Some(frame) = secure.receive(&record) {\n                        self.deliver(frame);\n                    }\n                }\n            }\n        }\n\n        fn transmit(&self, node: &str, frame: Vec<u8>) -> Result<()> {\n            match &self.inner.secure {\n                None => self.inner.transport.send(node, frame),\n                Some(secure) => secure.send(node, frame),\n            }\n        }\n\n        pub fn close(&self) {\n            self.inner.closed.store(true, Ordering::SeqCst);\n            self.inner.transport.close();\n        }\n\n        fn closed(&self) -> bool {\n            self.inner.closed.load(Ordering::SeqCst)\n        }\n\n        fn next_id(&self) -> u64 {\n            self.inner.ids.fetch_add(1, Ordering::SeqCst)\n        }\n\n        fn send_frame(&self, address: &str, kind: &str, payload: &[u8], id: u64) -> Result<()> {\n            let (node, name) = split_address(address)?;\n            self.transmit(&node, frame_encode(kind, &name, &self.inner.address, id, payload))\n        }\n\n        fn register(&self, name: &str, entity: Arc<dyn Entity>) -> Result<String> {\n            if name.is_empty() || name.contains('/') {\n                return Err(format!(\"{name:?} is not a name: use letters, digits and dashes\"));\n            }\n            let mut entities = lock(&self.inner.entities);\n            if entities.contains_key(name) {\n                return Err(format!(\"{name} is already registered on {}\", self.inner.address));\n            }\n            entities.insert(name.to_string(), entity);\n            Ok(format!(\"{}/{name}\", self.inner.address))\n        }\n\n        fn deliver(&self, frame: Vec<u8>) {\n            let Ok(Frame { kind, to, source, id, payload }) = frame_decode(&frame) else { return };\n            if kind == \"reply\" {\n                if let Some(slot) = lock(&self.inner.pending).remove(&id) {\n                    *lock(&slot.reply) = Some(payload);\n                    slot.ready.notify_all();\n                }\n                return;\n            }\n            let entity = lock(&self.inner.entities).get(&to).cloned();\n            let Some(entity) = entity else {\n                if id != 0 {\n                    self.reply(&source, id, 3, format!(\"nothing is registered as {to} on {}\", self.inner.address).as_bytes());\n                }\n                return;\n            };\n            if id != 0 {\n                let key = (source.clone(), id);\n                let mut seen = lock(&self.inner.seen);\n                if let Some(answer) = seen.0.get(&key) {\n                    if let Some(answer) = answer.clone() {\n                        let node = self.clone();\n                        std::thread::spawn(move || {\n                            let _ = node.send_frame(&format!(\"{source}/\"), \"reply\", &answer, id);\n                        });\n                    }\n                    return;\n                }\n                seen.0.insert(key.clone(), None);\n                seen.1.push_back(key);\n                while seen.1.len() > 10000 {\n                    if let Some(old) = seen.1.pop_front() {\n                        seen.0.remove(&old);\n                    }\n                }\n            }\n            // Handled off the transport's thread, so a slow handler does not\n            // hold up other frames.\n            let node = self.clone();\n            std::thread::spawn(move || entity.receive(&node, &kind, &source, id, payload));\n        }\n\n        fn reply(&self, source: &str, id: u64, status: u8, body: &[u8]) {\n            let mut payload = vec![status];\n            payload.extend_from_slice(body);\n            {\n                let mut seen = lock(&self.inner.seen);\n                if let Some(answer) = seen.0.get_mut(&(source.to_string(), id)) {\n                    *answer = Some(payload.clone());\n                }\n            }\n            let _ = self.send_frame(&format!(\"{source}/\"), \"reply\", &payload, id);\n        }\n\n        /// Sends a request again until answered: (status, body).\n        fn request(&self, address: &str, kind: &str, payload: &[u8], timeout: Duration) -> Result<(u8, Vec<u8>)> {\n            let id = self.next_id();\n            let slot = Arc::new(Slot { reply: Mutex::new(None), ready: Condvar::new() });\n            lock(&self.inner.pending).insert(id, slot.clone());\n            let give_up = Instant::now() + timeout;\n            loop {\n                if let Err(e) = self.send_frame(address, kind, payload, id) {\n                    if !is_unreachable(&e) {\n                        lock(&self.inner.pending).remove(&id);\n                        return Err(e);\n                    }\n                }\n                let now = Instant::now();\n                let wait = Duration::from_millis(100).min(give_up.saturating_duration_since(now));\n                let mut reply = lock(&slot.reply);\n                if reply.is_none() {\n                    reply = slot.ready.wait_timeout(reply, wait).unwrap_or_else(|e| e.into_inner()).0;\n                }\n                if let Some(answer) = reply.take() {\n                    if answer.is_empty() {\n                        return Err(format!(\"{UNREACHABLE}an empty reply from {address}\"));\n                    }\n                    return Ok((answer[0], answer[1..].to_vec()));\n                }\n                drop(reply);\n                if Instant::now() >= give_up {\n                    lock(&self.inner.pending).remove(&id);\n                    return Err(format!(\"{UNREACHABLE}{address} did not answer within {:?}\", timeout));\n                }\n            }\n        }\n\n        // Mailboxes: values of one type sent by any node.\n\n        /// A local mailbox that other nodes send to at <address>/name.\n        pub fn mailbox(&self, name: &str, descriptor: Sexp, values: Values) -> Result<actors::Mailbox<Value>> {\n            let mailbox = actors::Mailbox::new();\n            self.register(name, Arc::new(MailEntity { mailbox: mailbox.clone(), descriptor, values }))?;\n            Ok(mailbox)\n        }\n\n        pub fn remote_mailbox(&self, address: &str, descriptor: Sexp, values: Values) -> RemoteMailbox {\n            self.remote_mailbox_within(address, descriptor, values, Duration::from_secs(5))\n        }\n\n        /// A remote mailbox whose sends wait up to timeout for delivery.\n        pub fn remote_mailbox_within(&self, address: &str, descriptor: Sexp, values: Values, timeout: Duration) -> RemoteMailbox {\n            RemoteMailbox { node: self.clone(), address: address.to_string(), descriptor, values, timeout }\n        }\n\n        // Actors: calls by message name, with each message's types.\n\n        /// Lets other nodes call handlers at <address>/name; returns that\n        /// address. Each handler takes the message's logical arguments and\n        /// gives its logical reply (typically by calling a local actor).\n        pub fn serve(&self, name: &str, handlers: Vec<RemoteHandler>, values: Values) -> Result<String> {\n            self.register(name, Arc::new(ActorEntity { handlers, values }))\n        }\n\n        /// A proxy calling the actor at address.\n        pub fn remote_actor(&self, address: &str, signatures: Vec<Signature>, values: Values, timeout: Duration) -> RemoteActor {\n            RemoteActor { node: self.clone(), address: address.to_string(), signatures, values, timeout }\n        }\n\n        // Definitions, by content hash.\n\n        /// Lets other nodes evaluate definitions, by content hash.\n        pub fn serve_definitions(&self, table: Vec<RemoteDefinition>, values: Values, name: &str) -> Result<String> {\n            self.register(name, Arc::new(DefinitionEntity { table, values }))\n        }\n\n        /// Evaluates the definition with this content hash on another node.\n        #[allow(clippy::too_many_arguments)]\n        pub fn evaluate(\n            &self,\n            node: &str,\n            digest: &str,\n            args: &[Value],\n            arguments: &[Sexp],\n            result: &Sexp,\n            values: &Values,\n            timeout: Duration,\n            name: &str,\n        ) -> Result<Value> {\n            let mut payload = Vec::new();\n            put_text(&mut payload, digest);\n            for (d, v) in arguments.iter().zip(args) {\n                wire_put(values, d, v, &mut payload)?;\n            }\n            let (status, body) = self.request(&format!(\"{node}/{name}\"), \"eval\", &payload, timeout)?;\n            reply_value(status, &body, values, result)\n        }\n\n        // Channels: one side here, the other on any node.\n\n        /// The first end of a channel named name here; its other end is\n        /// dialed from any node. steps: (sends, descriptor) per step, from\n        /// this end's side.\n        pub fn listen(&self, name: &str, steps: Vec<(bool, Sexp)>, values: Values, deadline: Duration) -> Result<NetEndpoint> {\n            let endpoint = NetEndpoint::new(self, steps, values, deadline);\n            let address = self.register(name, endpoint.inner.clone())?;\n            *lock(&endpoint.inner.address) = address;\n            Ok(endpoint)\n        }\n\n        /// The second end of the channel listening at address; steps are\n        /// from this end's side.\n        pub fn dial(&self, address: &str, steps: Vec<(bool, Sexp)>, values: Values, deadline: Duration) -> Result<NetEndpoint> {\n            let endpoint = NetEndpoint::new(self, steps, values, deadline);\n            let own = self.register(&format!(\"end-{}\", self.next_id()), endpoint.inner.clone())?;\n            *lock(&endpoint.inner.address) = own;\n            endpoint.connect(address);\n            Ok(endpoint)\n        }\n\n        /// Takes over a channel end another node moves here: address is\n        /// <old address>?take=<token>, as that node offered it. Returns once\n        /// the end's state has arrived and its peer has been told (or after\n        /// the deadline; the old node then forwards to the end).\n        pub fn take(&self, address: &str, steps: Vec<(bool, Sexp)>, values: Values, deadline: Duration) -> Result<NetEndpoint> {\n            let endpoint = NetEndpoint::new(self, steps, values, deadline);\n            let own = self.register(&format!(\"end-{}\", self.next_id()), endpoint.inner.clone())?;\n            *lock(&endpoint.inner.address) = own;\n            endpoint.take_over(address);\n            Ok(endpoint)\n        }\n\n        /// Passes a frame on to address unchanged, keeping its source.\n        fn forward(&self, address: &str, kind: &str, source: &str, id: u64, payload: &[u8]) {\n            if let Ok((node, name)) = split_address(address) {\n                let _ = self.transmit(&node, frame_encode(kind, &name, source, id, payload));\n            }\n        }\n    }\n\n    fn reply_value(status: u8, body: &[u8], values: &Values, d: &Sexp) -> Result<Value> {\n        let message = String::from_utf8_lossy(body).to_string();\n        match status {\n            0 => wire_decode(values, d, body),\n            1 if message.starts_with(actors::CRASHED) => Err(message),\n            1 => Err(format!(\"{}{message}\", actors::CRASHED)),\n            2 => Err(actors::STOPPED.to_string()),\n            _ if is_unreachable(&message) => Err(message),\n            _ => Err(format!(\"{UNREACHABLE}{message}\")),\n        }\n    }\n\n    struct MailEntity {\n        mailbox: actors::Mailbox<Value>,\n        descriptor: Sexp,\n        values: Values,\n    }\n\n    impl Entity for MailEntity {\n        fn receive(&self, node: &Node, kind: &str, source: &str, id: u64, payload: Vec<u8>) {\n            if kind != \"mail\" {\n                return;\n            }\n            let (status, body) = match wire_decode(&self.values, &self.descriptor, &payload) {\n                Ok(value) => match self.mailbox.send(value) {\n                    Ok(()) => (0u8, Vec::new()),\n                    Err(e) => (2, e.into_bytes()),\n                },\n                Err(e) => (3, format!(\"not a message of this mailbox: {e}\").into_bytes()),\n            };\n            if id != 0 {\n                node.reply(source, id, status, &body);\n            }\n        }\n    }\n\n    /// Sends to a mailbox on another node. A send waits until the mailbox\n    /// has the message (resending a lost one; the mailbox takes it once),\n    /// and fails with UNREACHABLE after the timeout, or as stopped if the\n    /// mailbox is closed.\n    pub struct RemoteMailbox {\n        node: Node,\n        pub address: String,\n        descriptor: Sexp,\n        values: Values,\n        pub timeout: Duration,\n    }\n\n    impl RemoteMailbox {\n        pub fn send(&self, value: &Value) -> Result<()> {\n            let bytes = wire_encode(&self.values, &self.descriptor, value)?;\n            let (status, body) = self.node.request(&self.address, \"mail\", &bytes, self.timeout)?;\n            if status == 0 {\n                Ok(())\n            } else {\n                reply_value(status, &body, &self.values, &Sexp::List(vec![Sexp::Atom(\"unit\".into())])).map(|_| ())\n            }\n        }\n    }\n\n    /// A served message: its name, argument and reply descriptors, and\n    /// what handles it (logical arguments in, logical reply out).\n    pub type RemoteHandler = (String, Vec<Sexp>, Sexp, Arc<dyn Fn(Vec<Value>) -> Result<Value> + Send + Sync>);\n    /// A message's name, argument descriptors and reply descriptor.\n    pub type Signature = (String, Vec<Sexp>, Sexp);\n    /// A definition other nodes evaluate: its content hash, the function\n    /// (logical arguments in, logical result out), and its descriptors.\n    pub type RemoteDefinition = (String, Arc<dyn Fn(Vec<Value>) -> Result<Value> + Send + Sync>, Vec<Sexp>, Sexp);\n\n    struct ActorEntity {\n        handlers: Vec<RemoteHandler>,\n        values: Values,\n    }\n\n    impl Entity for ActorEntity {\n        fn receive(&self, node: &Node, kind: &str, source: &str, id: u64, payload: Vec<u8>) {\n            if kind != \"call\" {\n                return;\n            }\n            let mut pos = 0;\n            let decoded = get_text(&payload, &mut pos).and_then(|message| {\n                let handler = self.handlers.iter().find(|h| h.0 == message).ok_or_else(|| format!(\"no message {message}\"))?;\n                let mut args = Vec::new();\n                for d in &handler.1 {\n                    args.push(wire_get(&self.values, d, &payload, &mut pos)?);\n                }\n                if pos != payload.len() {\n                    return wire_error(\"extra bytes after the arguments\");\n                }\n                Ok((handler, args))\n            });\n            let (handler, args) = match decoded {\n                Ok(found) => found,\n                Err(e) => return node.reply(source, id, 3, format!(\"not a message this actor handles: {e}\").as_bytes()),\n            };\n            match (handler.3)(args).and_then(|reply| wire_encode(&self.values, &handler.2, &reply)) {\n                Ok(bytes) => node.reply(source, id, 0, &bytes),\n                Err(e) if actors::is_stopped(&e) => node.reply(source, id, 2, e.as_bytes()),\n                Err(e) if actors::is_crashed(&e) => node.reply(source, id, 1, e.as_bytes()),\n                Err(e) => node.reply(source, id, 1, format!(\"{}{e}\", actors::CRASHED).as_bytes()),\n            }\n        }\n    }\n\n    /// Calls an actor on another node: call sends the message and waits for\n    /// the reply, failing with UNREACHABLE after the timeout, or as the\n    /// actor's call failed (crashed, stopped).\n    pub struct RemoteActor {\n        node: Node,\n        pub address: String,\n        signatures: Vec<Signature>,\n        values: Values,\n        pub timeout: Duration,\n    }\n\n    impl RemoteActor {\n        pub fn call(&self, message: &str, args: &[Value]) -> Result<Value> {\n            let (_, arguments, reply) =\n                self.signatures.iter().find(|s| s.0 == message).ok_or_else(|| format!(\"no message {message}\"))?;\n            let mut payload = Vec::new();\n            put_text(&mut payload, message);\n            for (d, v) in arguments.iter().zip(args) {\n                wire_put(&self.values, d, v, &mut payload)?;\n            }\n            let (status, body) = self.node.request(&self.address, \"call\", &payload, self.timeout)?;\n            reply_value(status, &body, &self.values, reply)\n        }\n    }\n\n    struct DefinitionEntity {\n        table: Vec<RemoteDefinition>,\n        values: Values,\n    }\n\n    impl Entity for DefinitionEntity {\n        fn receive(&self, node: &Node, kind: &str, source: &str, id: u64, payload: Vec<u8>) {\n            if kind != \"eval\" {\n                return;\n            }\n            let mut pos = 0;\n            let decoded = get_text(&payload, &mut pos).and_then(|digest| {\n                let entry = self.table.iter().find(|e| e.0 == digest).ok_or_else(|| \"no such definition\".to_string())?;\n                let mut args = Vec::new();\n                for d in &entry.2 {\n                    args.push(wire_get(&self.values, d, &payload, &mut pos)?);\n                }\n                Ok((entry, args))\n            });\n            let (entry, args) = match decoded {\n                Ok(found) => found,\n                Err(_) => return node.reply(source, id, 3, b\"this node has no definition with that content hash\"),\n            };\n            match (entry.1)(args).and_then(|result| wire_encode(&self.values, &entry.3, &result)) {\n                Ok(bytes) => node.reply(source, id, 0, &bytes),\n                Err(e) => node.reply(source, id, 1, e.as_bytes()),\n            }\n        }\n    }\n\n    enum Inbox {\n        Value(Vec<u8>),\n        Failed(String),\n    }\n\n    struct Unacked {\n        payload: Vec<u8>,\n        first: Instant,\n        last: Instant,\n        body: Vec<u8>,\n    }\n\n    struct EndpointState {\n        peer: Option<String>,\n        out: i64,\n        unacked: HashMap<i64, Unacked>,\n        expected: i64,\n        early: HashMap<i64, Vec<u8>>,\n        step: usize,\n        gone: bool,\n        failure: String,\n        // Moving: the addresses this end had before (oldest first), the\n        // token a taker must show, where the end went and the state frame it\n        // was given, and, on the new node, the takeover in progress.\n        history: Vec<String>,\n        token: Option<String>,\n        moved_to: Option<String>,\n        handed: Vec<u8>,\n        taking: Option<String>,\n        taken: bool,\n        announcing: bool,\n        announced_at: Option<Instant>,\n        confirmed: bool,\n    }\n\n    struct EndpointInner {\n        node: Node,\n        steps: Vec<(bool, Sexp)>,\n        values: Values,\n        deadline: Duration,\n        address: Mutex<String>,\n        state: Mutex<EndpointState>,\n        changed: Condvar,\n        inbox: Mutex<VecDeque<Inbox>>,\n        arrived: Condvar,\n    }\n\n    /// One end of a channel between nodes. Each value travels in a numbered\n    /// frame that is sent again until acknowledged, so loss, duplication\n    /// and reordering are repaired; a peer silent past the deadline fails\n    /// the end (PEER_FAILED). Order is kept within the channel. Clones share\n    /// the end.\n    ///\n    /// An unused end can move to another node: offer gives the address the\n    /// new node takes it over from (<address>?take=<token>). On a take frame\n    /// with that token, this end hands its state over (a state frame) and\n    /// from then on forwards every frame it gets to the new end; the new end\n    /// tells the peer (a moved frame) so the peer sends to it directly.\n    #[derive(Clone)]\n    pub struct NetEndpoint {\n        inner: Arc<EndpointInner>,\n    }\n\n    impl NetEndpoint {\n        fn new(node: &Node, steps: Vec<(bool, Sexp)>, values: Values, deadline: Duration) -> NetEndpoint {\n            let inner = Arc::new(EndpointInner {\n                node: node.clone(),\n                steps,\n                values,\n                deadline,\n                address: Mutex::new(String::new()),\n                state: Mutex::new(EndpointState {\n                    peer: None,\n                    out: 0,\n                    unacked: HashMap::new(),\n                    expected: 0,\n                    early: HashMap::new(),\n                    step: 0,\n                    gone: false,\n                    failure: String::new(),\n                    history: Vec::new(),\n                    token: None,\n                    moved_to: None,\n                    handed: Vec::new(),\n                    taking: None,\n                    taken: false,\n                    announcing: false,\n                    announced_at: None,\n                    confirmed: false,\n                }),\n                changed: Condvar::new(),\n                inbox: Mutex::new(VecDeque::new()),\n                arrived: Condvar::new(),\n            });\n            let weak = Arc::downgrade(&inner);\n            std::thread::spawn(move || resend(weak));\n            NetEndpoint { inner }\n        }\n\n        /// This end's address.\n        pub fn address(&self) -> String {\n            lock(&self.inner.address).clone()\n        }\n\n        fn connect(&self, address: &str) {\n            lock(&self.inner.state).peer = Some(address.to_string());\n            self.inner.transmit(-1, b\"hello\".to_vec());\n        }\n\n        fn step_descriptor(&self, sends: bool) -> Result<Sexp> {\n            let mut state = lock(&self.inner.state);\n            let Some((step_sends, d)) = self.inner.steps.get(state.step) else {\n                return Err(\"this channel's protocol has ended\".into());\n            };\n            if *step_sends != sends {\n                return Err(format!(\"this step {}\", if *step_sends { \"sends\" } else { \"receives\" }));\n            }\n            state.step += 1;\n            Ok(d.clone())\n        }\n\n        /// Sends the next step's value.\n        pub fn send(&self, value: &Value) -> Result<()> {\n            if lock(&self.inner.state).gone {\n                return Err(format!(\"{PEER_FAILED}the other end has failed\"));\n            }\n            let d = self.step_descriptor(true)?;\n            let mut body = vec![0u8];\n            wire_put(&self.inner.values, &d, value, &mut body)?;\n            let seq = {\n                let mut state = lock(&self.inner.state);\n                state.out += 1;\n                state.out - 1\n            };\n            self.inner.transmit(seq, body);\n            Ok(())\n        }\n\n        /// The next step's value, waiting up to timeout (forever when None);\n        /// fails with PEER_FAILED once the other end gave up or failed.\n        pub fn receive(&self, timeout: Option<Duration>) -> Result<Value> {\n            let d = self.step_descriptor(false)?;\n            let until = timeout.map(|t| Instant::now() + t);\n            let mut inbox = lock(&self.inner.inbox);\n            let item = loop {\n                if let Some(item) = inbox.pop_front() {\n                    break item;\n                }\n                inbox = match until {\n                    None => self.inner.arrived.wait(inbox).unwrap_or_else(|e| e.into_inner()),\n                    Some(at) => {\n                        let now = Instant::now();\n                        if now >= at {\n                            return Err(\"no message arrived in time\".into());\n                        }\n                        self.inner.arrived.wait_timeout(inbox, at - now).unwrap_or_else(|e| e.into_inner()).0\n                    }\n                };\n            };\n            match item {\n                Inbox::Failed(reason) => {\n                    inbox.push_front(Inbox::Failed(reason.clone()));\n                    Err(format!(\"{PEER_FAILED}{reason}\"))\n                }\n                Inbox::Value(body) => {\n                    drop(inbox);\n                    if body.first() == Some(&1) {\n                        self.inner.fail(\"the other end gave up the conversation\");\n                        return Err(format!(\n                            \"{PEER_FAILED}the other end gave up the conversation (its process failed or abandoned it)\"\n                        ));\n                    }\n                    wire_decode(&self.inner.values, &d, body.get(1..).unwrap_or(&[]))\n                }\n            }\n        }\n\n        /// Gives up: the other end's receives fail after what was sent.\n        pub fn abandon(&self) {\n            let seq = {\n                let mut state = lock(&self.inner.state);\n                state.out += 1;\n                state.out - 1\n            };\n            self.inner.transmit(seq, vec![1]);\n        }\n\n        /// The address another node takes this unused end over from.\n        fn offer(&self) -> String {\n            let mut state = lock(&self.inner.state);\n            let token = state.token.get_or_insert_with(secure_token);\n            format!(\"{}?take={token}\", lock(&self.inner.address))\n        }\n\n        /// Takes over the end offered at address (<old address>?take=<token>):\n        /// asks for its state until it comes, then tells the peer where the\n        /// end is now. Returns once the peer knows, or after the deadline (the\n        /// old node then keeps forwarding to this end, as a relay would).\n        fn take_over(&self, address: &str) {\n            let (old, query) = address.split_once('?').unwrap_or((address, \"\"));\n            let token = query.strip_prefix(\"take=\").unwrap_or(query).to_string();\n            lock(&self.inner.state).taking = Some(token.clone());\n            let mut request = Vec::new();\n            put_text(&mut request, &token);\n            put_text(&mut request, &self.address());\n            let give_up = Instant::now() + self.inner.deadline;\n            loop {\n                let _ = self.inner.node.send_frame(old, \"take\", &request, 0);\n                let state = lock(&self.inner.state);\n                let (state, _) = self\n                    .inner\n                    .changed\n                    .wait_timeout_while(state, Duration::from_millis(50), |s| !s.taken)\n                    .unwrap_or_else(|e| e.into_inner());\n                if state.taken {\n                    break;\n                }\n                drop(state);\n                if Instant::now() >= give_up {\n                    lock(&self.inner.state).taking = None;\n                    self.inner.fail(\"the node the end came from did not hand it over in time (unreachable)\");\n                    return;\n                }\n            }\n            let state = lock(&self.inner.state);\n            let _ = self\n                .inner\n                .changed\n                .wait_timeout_while(state, give_up.saturating_duration_since(Instant::now()), |s| !s.confirmed)\n                .unwrap_or_else(|e| e.into_inner());\n        }\n    }\n\n    fn put_texts(out: &mut Vec<u8>, texts: &[String]) {\n        put_len(out, texts.len());\n        for t in texts {\n            put_text(out, t);\n        }\n    }\n\n    fn get_texts(buf: &[u8], pos: &mut usize) -> Result<Vec<String>> {\n        let count = get_len(buf, pos)?;\n        (0..count).map(|_| get_text(buf, pos)).collect()\n    }\n\n    fn put_bytes(out: &mut Vec<u8>, bytes: &[u8]) {\n        put_len(out, bytes.len());\n        out.extend_from_slice(bytes);\n    }\n\n    fn get_bytes(buf: &[u8], pos: &mut usize) -> Result<Vec<u8>> {\n        match wire_get(&no_types(), &bytes_d(), buf, pos)? {\n            Value::Bytes(b) => Ok(b),\n            _ => wire_error(\"not bytes\"),\n        }\n    }\n\n    fn put_numbered(out: &mut Vec<u8>, mut items: Vec<(i64, Vec<u8>)>) {\n        items.sort_by_key(|(seq, _)| *seq);\n        put_len(out, items.len());\n        for (seq, body) in items {\n            put_seq(out, seq);\n            put_bytes(out, &body);\n        }\n    }\n\n    fn get_numbered(buf: &[u8], pos: &mut usize) -> Result<Vec<(i64, Vec<u8>)>> {\n        let count = get_len(buf, pos)?;\n        (0..count).map(|_| Ok((get_seq(buf, pos)?, get_bytes(buf, pos)?))).collect()\n    }\n\n    impl EndpointInner {\n        fn frame(&self, seq: i64, body: &[u8]) -> Vec<u8> {\n            let mut payload = Vec::new();\n            put_seq(&mut payload, seq);\n            put_text(&mut payload, &lock(&self.address));\n            payload.extend_from_slice(body);\n            payload\n        }\n\n        fn transmit(&self, seq: i64, body: Vec<u8>) {\n            let payload = self.frame(seq, &body);\n            let peer = {\n                let mut state = lock(&self.state);\n                let now = Instant::now();\n                state.unacked.insert(seq, Unacked { payload: payload.clone(), first: now, last: now, body });\n                state.peer.clone()\n            };\n            if let Some(peer) = peer {\n                let _ = self.node.send_frame(&peer, \"chan\", &payload, 0);\n            }\n        }\n\n        fn fail(&self, reason: &str) {\n            {\n                let mut state = lock(&self.state);\n                if state.gone {\n                    return;\n                }\n                state.gone = true;\n                state.failure = reason.to_string();\n                state.unacked.clear();\n                lock(&self.inbox).push_back(Inbox::Failed(reason.to_string()));\n            }\n            self.arrived.notify_all();\n        }\n\n        /// A take frame: hands the state over once, to the first taker with\n        /// the token, and answers that taker's repeats with the same state.\n        fn give(&self, payload: &[u8]) {\n            let mut pos = 0;\n            let Ok(token) = get_text(payload, &mut pos) else { return };\n            let Ok(taker) = get_text(payload, &mut pos) else { return };\n            let handed = {\n                let mut state = lock(&self.state);\n                if state.token.as_deref() != Some(token.as_str()) {\n                    return;\n                }\n                match state.moved_to.clone() {\n                    Some(to) if to != taker => return,\n                    Some(_) => {}\n                    None => {\n                        let address = lock(&self.address).clone();\n                        let received: Vec<Vec<u8>> = lock(&self.inbox)\n                            .iter()\n                            .filter_map(|item| match item {\n                                Inbox::Value(body) => Some(body.clone()),\n                                Inbox::Failed(_) => None,\n                            })\n                            .collect();\n                        let mut out = Vec::new();\n                        put_text(&mut out, &token);\n                        put_text(&mut out, &state.failure);\n                        put_text(&mut out, state.peer.as_deref().unwrap_or(\"\"));\n                        let mut former = state.history.clone();\n                        former.push(address);\n                        put_texts(&mut out, &former);\n                        put_seq(&mut out, state.out);\n                        put_seq(&mut out, state.expected);\n                        put_numbered(&mut out, state.unacked.iter().map(|(seq, u)| (*seq, u.body.clone())).collect());\n                        put_numbered(&mut out, state.early.iter().map(|(seq, b)| (*seq, b.clone())).collect());\n                        put_len(&mut out, received.len());\n                        for body in &received {\n                            put_bytes(&mut out, body);\n                        }\n                        state.moved_to = Some(taker.clone());\n                        state.handed = out;\n                        state.unacked.clear();\n                        state.early.clear();\n                    }\n                }\n                state.handed.clone()\n            };\n            let _ = self.node.send_frame(&taker, \"state\", &handed, 0);\n        }\n\n        fn install(&self, payload: &[u8]) {\n            let parsed = (|| -> Result<_> {\n                let mut pos = 0;\n                let token = get_text(payload, &mut pos)?;\n                let failure = get_text(payload, &mut pos)?;\n                let peer = get_text(payload, &mut pos)?;\n                let history = get_texts(payload, &mut pos)?;\n                let out = get_seq(payload, &mut pos)?;\n                let expected = get_seq(payload, &mut pos)?;\n                let unacked = get_numbered(payload, &mut pos)?;\n                let early = get_numbered(payload, &mut pos)?;\n                let count = get_len(payload, &mut pos)?;\n                let received = (0..count).map(|_| get_bytes(payload, &mut pos)).collect::<Result<Vec<_>>>()?;\n                Ok((token, failure, peer, history, out, expected, unacked, early, received))\n            })();\n            let Ok((token, failure, peer, history, out, expected, unacked, early, received)) = parsed else { return };\n            {\n                let mut state = lock(&self.state);\n                if state.taking.as_deref() != Some(token.as_str()) || state.taken {\n                    return;\n                }\n                let now = Instant::now();\n                let long_ago = now.checked_sub(Duration::from_secs(1)).unwrap_or(now);\n                state.peer = if peer.is_empty() { None } else { Some(peer) };\n                state.history = history;\n                state.out = out;\n                state.expected = expected;\n                // Sent again from here at once, under this end's address.\n                for (seq, body) in unacked {\n                    let payload = self.frame(seq, &body);\n                    state.unacked.insert(seq, Unacked { payload, first: now, last: long_ago, body });\n                }\n                state.early.extend(early);\n                lock(&self.inbox).extend(received.into_iter().map(Inbox::Value));\n                state.announcing = true;\n                state.taken = true;\n            }\n            self.arrived.notify_all();\n            self.changed.notify_all();\n            if !failure.is_empty() {\n                self.fail(&failure);\n            }\n        }\n\n        /// The peer moved: from now on send to its new address.\n        fn peer_moved(&self, payload: &[u8]) {\n            let mut pos = 0;\n            let Ok(history) = get_texts(payload, &mut pos) else { return };\n            let Ok(to) = get_text(payload, &mut pos) else { return };\n            let known = {\n                let mut state = lock(&self.state);\n                if state.peer.as_ref().is_none_or(|p| history.contains(p)) {\n                    state.peer = Some(to.clone());\n                }\n                state.peer.as_deref() == Some(to.as_str())\n            };\n            if known {\n                let mut answer = Vec::new();\n                put_text(&mut answer, &to);\n                let _ = self.node.send_frame(&to, \"moved-ack\", &answer, 0);\n            }\n        }\n    }\n\n    // Sends unacknowledged frames again until the end fails or goes away.\n    fn resend(weak: Weak<EndpointInner>) {\n        loop {\n            std::thread::sleep(Duration::from_millis(20));\n            let Some(inner) = weak.upgrade() else { return };\n            if inner.node.closed() {\n                return;\n            }\n            let now = Instant::now();\n            let address = lock(&inner.address).clone();\n            let (peer, due, stale, moved) = {\n                let mut state = lock(&inner.state);\n                if state.gone || state.moved_to.is_some() {\n                    return;\n                }\n                if state.taking.is_some() && !state.taken {\n                    continue;\n                }\n                let stale = state.unacked.values().any(|u| now.duration_since(u.last) > Duration::from_millis(50) && now.duration_since(u.first) > inner.deadline);\n                let mut due = Vec::new();\n                for u in state.unacked.values_mut() {\n                    if now.duration_since(u.last) > Duration::from_millis(50) {\n                        u.last = now;\n                        due.push(u.payload.clone());\n                    }\n                }\n                let mut moved = None;\n                if state.announcing\n                    && state.peer.is_some()\n                    && !state.confirmed\n                    && state.announced_at.is_none_or(|at| now.duration_since(at) > Duration::from_millis(50))\n                {\n                    state.announced_at = Some(now);\n                    let mut payload = Vec::new();\n                    put_texts(&mut payload, &state.history);\n                    put_text(&mut payload, &address);\n                    moved = Some(payload);\n                }\n                (state.peer.clone(), due, stale, moved)\n            };\n            if stale {\n                inner.fail(\"the other end did not answer in time (unreachable)\");\n                return;\n            }\n            if let Some(peer) = peer {\n                if let Some(moved) = moved {\n                    let _ = inner.node.send_frame(&peer, \"moved\", &moved, 0);\n                }\n                for payload in due {\n                    let _ = inner.node.send_frame(&peer, \"chan\", &payload, 0);\n                }\n            }\n        }\n    }\n\n    impl Entity for EndpointInner {\n        fn receive(&self, node: &Node, kind: &str, source: &str, id: u64, payload: Vec<u8>) {\n            if kind == \"take\" {\n                self.give(&payload);\n                return;\n            }\n            let (forward, waiting) = {\n                let state = lock(&self.state);\n                (state.moved_to.clone(), state.taking.is_some() && !state.taken)\n            };\n            if let Some(to) = forward {\n                node.forward(&to, kind, source, id, &payload);\n                return;\n            }\n            if waiting {\n                // Until the state arrives, frames are dropped: their senders\n                // send them again.\n                if kind == \"state\" {\n                    self.install(&payload);\n                }\n                return;\n            }\n            let mut pos = 0;\n            match kind {\n                \"ack\" => {\n                    if let Ok(seq) = get_seq(&payload, &mut pos) {\n                        lock(&self.state).unacked.remove(&seq);\n                    }\n                    return;\n                }\n                \"moved\" => {\n                    self.peer_moved(&payload);\n                    return;\n                }\n                \"moved-ack\" => {\n                    if get_text(&payload, &mut pos).is_ok_and(|to| to == *lock(&self.address)) {\n                        lock(&self.state).confirmed = true;\n                        self.changed.notify_all();\n                    }\n                    return;\n                }\n                \"chan\" => {}\n                _ => return,\n            }\n            let Ok(seq) = get_seq(&payload, &mut pos) else { return };\n            let Ok(sender) = get_text(&payload, &mut pos) else { return };\n            let body = payload[pos..].to_vec();\n            let forward = {\n                let mut state = lock(&self.state);\n                if state.moved_to.is_none() {\n                    if seq == -1 {\n                        if state.peer.is_none() {\n                            state.peer = Some(sender.clone());\n                        }\n                    } else if seq >= state.expected && !state.early.contains_key(&seq) {\n                        state.early.insert(seq, body);\n                        let mut inbox = lock(&self.inbox);\n                        loop {\n                            let next = state.expected;\n                            match state.early.remove(&next) {\n                                Some(body) => {\n                                    inbox.push_back(Inbox::Value(body));\n                                    state.expected += 1;\n                                }\n                                None => break,\n                            }\n                        }\n                    }\n                }\n                state.moved_to.clone()\n            };\n            if let Some(to) = forward {\n                // Moved meanwhile: the new end acknowledges it.\n                node.forward(&to, kind, source, id, &payload);\n                return;\n            }\n            self.arrived.notify_all();\n            let mut ack = Vec::new();\n            put_seq(&mut ack, seq);\n            let _ = node.send_frame(&sender, \"ack\", &ack, 0);\n        }\n    }\n\n    /// Converts one session step's native value to and from its logical\n    /// form, for typed ends over a network. A step that sends another\n    /// protocol's first end (end_codec) carries the address the receiver\n    /// takes the end over from, or a relay's for a local end, instead.\n    pub struct StepCodec {\n        kind: CodecKind,\n    }\n\n    /// A protocol's wire form from its first end: each step's direction and\n    /// descriptor, and its codec.\n    pub type Wire = fn() -> (Vec<(bool, Sexp)>, Vec<StepCodec>);\n\n    enum CodecKind {\n        Value {\n            to_logical: Box<dyn Fn(super::sessions::Message) -> Value + Send + Sync>,\n            from_logical: Box<dyn Fn(Value) -> Result<super::sessions::Message> + Send + Sync>,\n        },\n        End {\n            wire: Wire,\n            into_endpoint: Box<dyn Fn(super::sessions::Message) -> super::sessions::Endpoint + Send + Sync>,\n            from_endpoint: Box<dyn Fn(super::sessions::Endpoint) -> super::sessions::Message + Send + Sync>,\n        },\n    }\n\n    /// The codec of a step whose native type is T.\n    pub fn step_codec<T: super::IntoValue + super::FromValue + Send + 'static>() -> StepCodec {\n        StepCodec {\n            kind: CodecKind::Value {\n                to_logical: Box::new(|message| match message.downcast::<T>() {\n                    Ok(value) => super::IntoValue::into_value(*value),\n                    Err(_) => panic!(\"a session sent a value of an unexpected type\"),\n                }),\n                from_logical: Box::new(|value| {\n                    let native: T = super::FromValue::from_value(value)?;\n                    Ok(Box::new(native) as super::sessions::Message)\n                }),\n            },\n        }\n    }\n\n    /// The codec of a step that sends another protocol's first end E: wire\n    /// is that protocol's wire form, and into/from turn E into its untyped\n    /// endpoint and back.\n    pub fn end_codec<E: Send + 'static>(\n        wire: Wire,\n        into: fn(E) -> super::sessions::Endpoint,\n        from: fn(super::sessions::Endpoint) -> E,\n    ) -> StepCodec {\n        StepCodec {\n            kind: CodecKind::End {\n                wire,\n                into_endpoint: Box::new(move |message| match message.downcast::<E>() {\n                    Ok(end) => into(*end),\n                    Err(_) => panic!(\"a session sent a channel end of an unexpected protocol\"),\n                }),\n                from_endpoint: Box::new(move |endpoint| Box::new(from(endpoint)) as super::sessions::Message),\n            },\n        }\n    }\n\n    /// A typed session end's transport over a network channel end: values\n    /// are converted step by step, natively on this side.\n    pub struct NetSession {\n        endpoint: NetEndpoint,\n        codecs: Vec<StepCodec>,\n        step: AtomicU64,\n        moved: AtomicBool,\n    }\n\n    impl NetSession {\n        pub fn new(endpoint: NetEndpoint, codecs: Vec<StepCodec>) -> Arc<NetSession> {\n            Arc::new(NetSession { endpoint, codecs, step: AtomicU64::new(0), moved: AtomicBool::new(false) })\n        }\n\n        fn codec(&self) -> &StepCodec {\n            let step = self.step.fetch_add(1, Ordering::SeqCst) as usize;\n            self.codecs.get(step).unwrap_or_else(|| panic!(\"this channel's protocol has ended\"))\n        }\n    }\n\n    /// The text that gives an unused channel end to another node. An end\n    /// that is itself between nodes moves there; a local end stays here and\n    /// a relay on node carries its conversation.\n    fn offer_end(node: &Node, values: &Values, end: super::sessions::Endpoint, wire: Wire) -> Result<String> {\n        match end.hand_over() {\n            Some(address) => Ok(address),\n            None => relay_end(node, values, end, wire),\n        }\n    }\n\n    /// Offers a local channel end to another node: a relay on node listens\n    /// for the receiver and passes each step between it and the end, which\n    /// stays here. Returns the relay's address. A failure on either side\n    /// gives up the other.\n    fn relay_end(node: &Node, values: &Values, end: super::sessions::Endpoint, wire: Wire) -> Result<String> {\n        let (steps, codecs) = wire();\n        let relay = node.listen(\n            &format!(\"relay-{}\", node.next_id()),\n            steps.iter().map(|(s, d)| (!s, d.clone())).collect(),\n            values.clone(),\n            Duration::from_secs(5),\n        )?;\n        let address = relay.address();\n        let relayed = NetSession::new(relay, codecs);\n        let directions: Vec<bool> = steps.iter().map(|(s, _)| *s).collect();\n        std::thread::spawn(move || {\n            use super::sessions::{Side, Transport};\n            for sends in directions {\n                let passed = if sends {\n                    relayed.receive(Side::First).map(|m| end.send_message(m))\n                } else {\n                    end.receive_message().map(|m| relayed.send(Side::First, m))\n                };\n                if passed.is_err() {\n                    relayed.close(Side::First);\n                    return;\n                }\n            }\n        });\n        Ok(address)\n    }\n\n    impl super::sessions::Transport for NetSession {\n        fn send(&self, _: super::sessions::Side, message: super::sessions::Message) {\n            let value = match &self.codec().kind {\n                CodecKind::Value { to_logical, .. } => to_logical(message),\n                CodecKind::End { wire, into_endpoint, .. } => {\n                    let inner = &self.endpoint.inner;\n                    match offer_end(&inner.node, &inner.values, into_endpoint(message), *wire) {\n                        Ok(address) => Value::Text(address),\n                        Err(e) => panic!(\"{e}\"),\n                    }\n                }\n            };\n            if let Err(e) = self.endpoint.send(&value) {\n                if !is_peer_failed(&e) {\n                    panic!(\"{e}\");\n                }\n            }\n        }\n\n        fn receive(&self, _: super::sessions::Side) -> std::result::Result<super::sessions::Message, super::sessions::PeerFailed> {\n            let codec = self.codec();\n            let value = match self.endpoint.receive(None) {\n                Ok(value) => value,\n                Err(e) if is_peer_failed(&e) => return Err(super::sessions::PeerFailed),\n                Err(e) => panic!(\"{e}\"),\n            };\n            match &codec.kind {\n                CodecKind::Value { from_logical, .. } => Ok(from_logical(value).unwrap_or_else(|e| panic!(\"{e}\"))),\n                CodecKind::End { wire, from_endpoint, .. } => {\n                    let Value::Text(address) = value else { panic!(\"a channel end arrived without its address\") };\n                    let (steps, codecs) = wire();\n                    let inner = &self.endpoint.inner;\n                    let dialed = if address.contains(\"?take=\") {\n                        inner.node.take(&address, steps, inner.values.clone(), Duration::from_secs(5))\n                    } else {\n                        inner.node.dial(&address, steps, inner.values.clone(), Duration::from_secs(5))\n                    }\n                    .unwrap_or_else(|e| panic!(\"{e}\"));\n                    let session = NetSession::new(dialed, codecs);\n                    Ok(from_endpoint(super::sessions::Endpoint::on(session, super::sessions::Side::First)))\n                }\n            }\n        }\n\n        fn close(&self, _: super::sessions::Side) {\n            if !self.moved.load(Ordering::SeqCst) {\n                self.endpoint.abandon();\n            }\n        }\n\n        fn hand_over(&self) -> Option<String> {\n            if self.step.load(Ordering::SeqCst) != 0 {\n                return None;\n            }\n            self.moved.store(true, Ordering::SeqCst);\n            Some(self.endpoint.offer())\n        }\n    }\n\n    // Keeps descriptor helpers reachable for generated code.\n    pub fn parse(text: &str) -> Sexp {\n        read_descriptor(text).into_iter().next().expect(\"a descriptor\")\n    }\n}\n\n#[cfg(test)]\nmod net_tests {\n    use super::net::*;\n    use super::*;\n    use std::sync::Arc;\n    use std::time::Duration;\n\n    fn int64() -> Sexp {\n        descriptor(\"(int Int64 _ _)\")\n    }\n\n    #[test]\n    fn wire_vectors_match_python() {\n        assert_eq!(wire_encoded(\"(int Integer _ _)\", 7, 4, 4), vec![\"9ddc4f\", \"eefb17\", \"8fc703\", \"8ee709\"]);\n        assert_eq!(wire_encoded(\"(int Int8 -128 127)\", 42, 4, 5), vec![\"f901\", \"28\", \"00\", \"48\", \"5c\"]);\n        assert_eq!(wire_encoded(\"(text)\", 3, 4, 3), vec![\"037b5b2c\", \"0134\", \"024d54\"]);\n        assert_eq!(wire_encoded(\"(list (maybe (bool)))\", 5, 3, 3), vec![\"02000101\", \"0100\", \"010100\"]);\n        assert_eq!(wire_encoded(\"(either (int UInt8 0 255) (text))\", 9, 3, 4), vec![\"00ec02\", \"0000\", \"00d201\", \"0100\"]);\n        let shape = \"(data Shape (ctor Shape::Circle (int Int32 0 100)) (ctor Shape::Box (int Int32 0 100) (int Int32 0 100)) (ctor Shape::Group (list (ref Shape))))\";\n        assert_eq!(wire_encoded(shape, 11, 3, 3), vec![\"0030\", \"020201b80100015ac801\", \"014808\"]);\n        for seed in 0..20 {\n            assert!(wire_round_trips(shape, seed, 5, 10));\n        }\n    }\n\n    fn exercise(a: Arc<dyn Transport>, b: Arc<dyn Transport>, lossy: bool) {\n        let (here, there) = (Node::new(a), Node::new(b));\n        let counter = actors::Actor::new(BigInt::from(0));\n        let served = counter.clone();\n        let handler: Arc<dyn Fn(Vec<Value>) -> Result<Value> + Send + Sync> = Arc::new(move |args| {\n            let n = args[0].integer()?;\n            served.call(|s: BigInt| {\n                let next = s + n;\n                Ok((Value::Integer(next.clone()), next))\n            })\n        });\n        let address = there.serve(\"counter\", vec![(\"add\".into(), vec![int64()], int64(), handler)], values_table(\"\")).unwrap();\n        let remote = here.remote_actor(&address, vec![(\"add\".into(), vec![int64()], int64())], values_table(\"\"), Duration::from_secs(3));\n        let replies: Vec<String> = (1..=3).map(|n| render(&remote.call(\"add\", &[Value::Integer(n.into())]).unwrap())).collect();\n        assert_eq!(replies, vec![\"1\", \"3\", \"6\"]);\n        let double: Arc<dyn Fn(Vec<Value>) -> Result<Value> + Send + Sync> =\n            Arc::new(|args| Ok(Value::Integer(args[0].integer()? * 2)));\n        there.serve_definitions(vec![(\"h\".into(), double, vec![int64()], int64())], values_table(\"\"), \"definitions\").unwrap();\n        let got = here\n            .evaluate(&there.address(), \"h\", &[Value::Integer(21.into())], &[int64()], &int64(), &values_table(\"\"), Duration::from_secs(3), \"definitions\")\n            .unwrap();\n        assert_eq!(render(&got), \"42\");\n        if !lossy {\n            let box_ = there.mailbox(\"jobs\", int64(), values_table(\"\")).unwrap();\n            here.remote_mailbox(&format!(\"{}/jobs\", there.address()), int64(), values_table(\"\")).send(&Value::Integer(41.into())).unwrap();\n            assert_eq!(render(&box_.receive(Some(Duration::from_secs(3))).unwrap()), \"41\");\n        }\n        let steps = vec![(true, int64()), (false, descriptor(\"(text)\")), (true, int64())];\n        let listener = there.listen(\"chat\", steps.clone(), values_table(\"\"), Duration::from_secs(5)).unwrap();\n        let dialer = here\n            .dial(&format!(\"{}/chat\", there.address()), steps.iter().map(|(s, d)| (!s, d.clone())).collect(), values_table(\"\"), Duration::from_secs(5))\n            .unwrap();\n        let worker = std::thread::spawn(move || {\n            listener.send(&Value::Integer(10.into())).unwrap();\n            let said = listener.receive(Some(Duration::from_secs(5))).unwrap();\n            listener.send(&Value::Integer(20.into())).unwrap();\n            said\n        });\n        assert_eq!(render(&dialer.receive(Some(Duration::from_secs(5))).unwrap()), \"10\");\n        dialer.send(&Value::Text(\"hi\".into())).unwrap();\n        assert_eq!(render(&dialer.receive(Some(Duration::from_secs(5))).unwrap()), \"20\");\n        assert_eq!(render(&worker.join().unwrap()), \"\\\"hi\\\"\");\n        here.close();\n        there.close();\n    }\n\n    #[test]\n    fn nodes_over_the_insecure_memory_transport() {\n        // The frame layer alone; lawspec_network's tests cover secure nodes\n        // over memory, TCP and HTTP.\n        let net = MemoryNetwork::new(3, 0.2, 0.2, Duration::from_millis(10)).with_recording();\n        exercise(net.insecure_transport_for_tests(\"a\"), net.insecure_transport_for_tests(\"b\"), true);\n        assert!(!net.recorded().is_empty());\n    }\n\n    #[test]\n    fn take_tokens_are_secure() {\n        let token = secure_token();\n        assert_eq!(token.len(), 64);\n        assert!(token.chars().all(|c| c.is_ascii_hexdigit() && !c.is_ascii_uppercase()));\n        assert_ne!(token, secure_token());\n    }\n}\n\n\n// Abilities (docs/explanation/abilities.md). Handlers travel in the Context\n// generated code passes to every definition: that context is the evidence of\n// evidence-passing compilation. A law installs one handler per ability; an\n// operation's bridge finds the handler of its ability there. The Fail\n// ability's handlers abort, so raise panics with a Failure and attempt\n// catches it.\n\n/// A handler installed for an ability: an `Arc<dyn Trait>`, and its calls\n/// when it records them.\n#[derive(Clone)]\npub struct Installed {\n    pub handler: Arc<dyn std::any::Any + Send + Sync>,\n    pub calls: Option<Calls>,\n    /// The handler's own type, when it is an ability's default (production)\n    /// handler: how a reader such as lawspec.time's tells the real clock.\n    pub native: Option<std::any::TypeId>,\n}\nimpl std::fmt::Debug for Installed {\n    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {\n        f.write_str(if self.calls.is_some() { \"<recording handler>\" } else { \"<handler>\" })\n    }\n}\n\n/// The calls a recording handler has seen.\n#[derive(Clone, Default, Debug)]\npub struct Calls(Arc<std::sync::Mutex<Vec<(String, Vec<Value>)>>>);\nimpl Calls {\n    pub fn record(&self, operation: &str, arguments: Vec<Value>) {\n        self.0.lock().unwrap().push((operation.to_string(), arguments));\n    }\n}\n\npub fn installed<H: Send + Sync + 'static>(handler: H) -> Installed {\n    Installed { handler: Arc::new(handler), calls: None, native: None }\n}\n/// A default handler of type N, installed as H (its `Arc<dyn Trait>`).\npub fn installed_native<N: 'static, H: Send + Sync + 'static>(handler: H) -> Installed {\n    Installed { handler: Arc::new(handler), calls: None, native: Some(std::any::TypeId::of::<N>()) }\n}\npub fn installed_recording<H: Send + Sync + 'static>(handler: H, calls: Calls) -> Installed {\n    Installed { handler: Arc::new(handler), calls: Some(calls), native: None }\n}\n\nimpl Context {\n    pub fn install_handlers(&mut self, handlers: Vec<(String, Installed)>) {\n        let mut table = self.handlers.write().unwrap();\n        for (key, handler) in handlers {\n            table.insert(key, handler);\n        }\n    }\n    /// The handler installed for an ability, as the type its bridge needs.\n    pub fn handler<H: Clone + 'static>(&self, ability: &str) -> Result<H> {\n        let table = self.handlers.read().unwrap();\n        let installed = table.get(ability).ok_or_else(|| {\n            format!(\"no handler for the ability {ability}: a law names one with `using`, or runs under each lawful handler\")\n        })?;\n        installed.handler.downcast_ref::<H>().cloned()\n            .ok_or_else(|| format!(\"the handler for {ability} has another type\"))\n    }\n    fn installed_for(&self, ability: &str) -> Option<Installed> {\n        self.handlers.read().unwrap().get(ability).cloned()\n    }\n}\n\n/// handle e with h end: the body runs with these handlers installed, then\n/// the ones they replaced come back.\npub fn with_handlers(\n    ctx: &mut Context,\n    handlers: Vec<(String, Installed)>,\n    body: impl FnOnce(&mut Context) -> Result<Value>,\n) -> Result<Value> {\n    let previous: Vec<(String, Option<Installed>)> =\n        handlers.iter().map(|(key, _)| (key.clone(), ctx.installed_for(key))).collect();\n    ctx.install_handlers(handlers);\n    let restore = |ctx: &mut Context| {\n        let mut table = ctx.handlers.write().unwrap();\n        for (key, before) in &previous {\n            match before {\n                Some(handler) => { table.insert(key.clone(), handler.clone()); }\n                None => { table.remove(key); }\n            }\n        }\n    };\n    let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| body(ctx)));\n    restore(ctx);\n    match outcome {\n        Ok(result) => result,\n        Err(payload) => std::panic::resume_unwind(payload),\n    }\n}\n\n/// What native code (an adapter, or a production handler) panics with to\n/// fail with a value of the failure type its signature names:\n/// `ls::fail(value)` for `fails with E`, the value a native E.\npub struct Fail(pub Box<dyn std::any::Any + Send>);\n\npub fn fail<E: Send + 'static>(value: E) -> ! {\n    quiet_failures();\n    std::panic::panic_any(Fail(Box::new(value)))\n}\n\n/// A native panic payload lawspec.json maps to a failure.\npub type MappedFailure = Box<dyn Fn(&(dyn std::any::Any + Send)) -> Option<Value>>;\n\n/// Native code that may fail: a Fail it panics with (holding a native E), or\n/// a panic payload lawspec.json maps, becomes a failure of the ability.\npub fn native_failures<E: 'static, T>(\n    ability: &str,\n    convert: impl FnOnce(E) -> Value,\n    body: impl FnOnce() -> T,\n    mapped: Vec<MappedFailure>,\n) -> T {\n    quiet_failures();\n    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(body)) {\n        Ok(value) => value,\n        Err(payload) => {\n            let payload = match payload.downcast::<Fail>() {\n                Ok(fail) => match fail.0.downcast::<E>() {\n                    Ok(native) => std::panic::panic_any(Failure { ability: ability.to_string(), value: convert(*native) }),\n                    Err(other) => other,\n                },\n                Err(other) => other,\n            };\n            for make in &mapped {\n                if let Some(value) = make(payload.as_ref()) {\n                    std::panic::panic_any(Failure { ability: ability.to_string(), value });\n                }\n            }\n            std::panic::resume_unwind(payload)\n        }\n    }\n}\n\n/// A failure raised with the Fail ability.\n#[derive(Debug)]\npub struct Failure {\n    pub ability: String,\n    pub value: Value,\n}\n\nfn quiet_failures() {\n    static HOOK: std::sync::Once = std::sync::Once::new();\n    HOOK.call_once(|| {\n        let previous = std::panic::take_hook();\n        std::panic::set_hook(Box::new(move |info| {\n            if info.payload().downcast_ref::<Failure>().is_none() && info.payload().downcast_ref::<Fail>().is_none() {\n                previous(info);\n            }\n        }));\n    });\n}\n\npub fn raise_failure(ability: &str, value: Value) -> Value {\n    quiet_failures();\n    std::panic::panic_any(Failure { ability: ability.to_string(), value })\n}\n\n/// Right of the body, or Left of the failure it raised with this ability.\npub fn attempt(\n    ctx: &mut Context,\n    ability: &str,\n    body: impl FnOnce(&mut Context) -> Result<Value>,\n    right: impl FnOnce(Value) -> Result<Value>,\n    left: impl FnOnce(Value) -> Result<Value>,\n) -> Result<Value> {\n    quiet_failures();\n    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| body(ctx))) {\n        Ok(result) => right(result?),\n        Err(payload) => match payload.downcast::<Failure>() {\n            Ok(failure) if failure.ability == ability => left(failure.value),\n            Ok(failure) => std::panic::panic_any(*failure),\n            Err(other) => std::panic::resume_unwind(other),\n        },\n    }\n}\n\n/// How many times a recording handler saw an operation (with arguments).\npub fn count_calls(\n    ctx: &Context,\n    ability: &str,\n    operation: &str,\n    matches: Option<&dyn Fn(&[Value]) -> Result<bool>>,\n) -> Result<Value> {\n    let installed = ctx.installed_for(ability).ok_or_else(|| format!(\"no handler for the ability {ability}\"))?;\n    let calls = installed.calls.as_ref().ok_or(\"calls of needs a recording handler: `using recording`\")?;\n    let recorded = calls.0.lock().unwrap().clone();\n    let mut count = 0i64;\n    for (name, arguments) in recorded {\n        if name == operation && match matches { None => true, Some(test) => test(&arguments)? } {\n            count += 1;\n        }\n    }\n    Ok(Value::Integer(BigInt::from(count)))\n}\n\n/// A Pair's two fields: a stateful handler clause's result and next state.\npub fn pair_fields(pair: Value) -> Result<(Value, Value)> {\n    match pair {\n        Value::Data(_, fields) if fields.len() == 2 => {\n            let mut fields = fields.into_iter();\n            Ok((fields.next().unwrap(), fields.next().unwrap()))\n        }\n        _ => Err(\"a handler clause must give Pair result state\".into()),\n    }\n}\n"
runtimeSource "rust-strategies" = "//! Proptest support, separate from the reusable numeric runtime.\n//!\n//! Generated tests run in Proptest, the framework Rust developers already use,\n//! so failures shrink, persist and report as they expect; LawSpec supplies only\n//! the strategies for its own types, and shrinking stays within the declared\n//! domain. ref:DEC-native-property-frameworks ref:proptest\n//! ref:DEC-shrink-within-domain\nuse crate::lawspec_runtime::{self as ls, IntoValue, Value};\nuse proptest::prelude::*;\n\n/// A framework-native factory. Child strategies correspond to type parameters,\n/// not constructor fields. Mapping the returned strategy retains its ValueTree.\npub type NativeFactory = fn(\n    &ls::Schema,\n    &ls::TypeRef,\n    u32,\n    &ls::Context,\n    Vec<BoxedStrategy<Value>>,\n) -> ls::Result<BoxedStrategy<Value>>;\n\n#[derive(Default)]\npub struct NativeGenerators {\n    factories: std::collections::HashMap<&'static str, NativeFactory>,\n}\n\nimpl NativeGenerators {\n    pub fn new(entries: Vec<(&'static str, NativeFactory)>) -> ls::Result<Self> {\n        let mut factories = std::collections::HashMap::new();\n        for (name, factory) in entries {\n            if name.is_empty() || factories.insert(name, factory).is_some() {\n                return Err(format!(\"duplicate or empty native generator: {name}\"));\n            }\n        }\n        Ok(Self { factories })\n    }\n\n    fn factory(&self, ty: &ls::TypeRef) -> Option<NativeFactory> {\n        match ty {\n            ls::TypeRef::Named(name, _) => self.factories.get(name).copied(),\n            _ => None,\n        }\n    }\n}\n\npub fn schema_strategy_with_generators(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    context: &ls::Context,\n    native: &NativeGenerators,\n) -> ls::Result<BoxedStrategy<Value>> {\n    if schema.has_contracts() {\n        return Err(\"constructor contracts require checked_schema_strategy_with_generators\".into());\n    }\n    shape_strategy_with_generators(\n        schema,\n        ty,\n        bits,\n        budget,\n        Default::default(),\n        context,\n        native,\n    )\n}\n\npub fn strategy(name: &str) -> ls::Result<BoxedStrategy<Value>> {\n    strategy_with_profile(name, usize::BITS)\n}\n\nfn scalar_strategy(name: &str) -> ls::Result<BoxedStrategy<Value>> {\n    if let Some(inner) = name.strip_prefix(\"Nullable \") {\n        return Ok(proptest::option::of(strategy(inner)?)\n            .prop_map(|x| Value::Nullable(x.map(Box::new)))\n            .boxed());\n    }\n    if let Some(inner) = name.strip_prefix(\"Optional \") {\n        return Ok(proptest::option::of(strategy(inner)?)\n            .prop_map(|x| Value::Optional(x.map(Box::new)))\n            .boxed());\n    }\n    macro_rules! integer {\n        ($t:ty) => {\n            any::<$t>().prop_map(IntoValue::into_value).boxed()\n        };\n    }\n    Ok(match name {\n        \"Bool\" => any::<bool>().prop_map(Value::Bool).boxed(),\n        \"Int8\" => integer!(i8),\n        \"Int16\" => integer!(i16),\n        \"Int32\" => integer!(i32),\n        \"Int64\" => integer!(i64),\n        \"UInt8\" => integer!(u8),\n        \"UInt16\" => integer!(u16),\n        \"UInt32\" => integer!(u32),\n        \"UInt64\" => integer!(u64),\n        \"IntSize\" => integer!(isize),\n        \"UIntSize\" | \"UIntPtr\" => integer!(usize),\n        \"Integer\" | \"BigInt\" => bigint().prop_map(Value::Integer).boxed(),\n        \"BigUInt\" => proptest::collection::vec(any::<u8>(), 0..65)\n            .prop_map(|bytes| {\n                Value::Integer(ls::BigInt::from_bytes_le(num_bigint::Sign::Plus, &bytes))\n            })\n            .boxed(),\n        \"Decimal\" => (bigint(), -100i32..101)\n            .prop_map(|(c, e)| Value::Decimal(ls::Decimal::new(c, e.into())))\n            .boxed(),\n        \"Rational\" => (bigint(), 1u64..=u64::MAX)\n            .prop_map(|(n, d)| Value::Rational(ls::BigRational::new(n, d.into())))\n            .boxed(),\n        \"Float32\" => any::<u32>()\n            .prop_map(|b| Value::Float32(f32::from_bits(b)))\n            .boxed(),\n        \"Float64\" => any::<u64>()\n            .prop_map(|b| Value::Float64(f64::from_bits(b)))\n            .boxed(),\n        \"Complex64\" => (any::<u32>(), any::<u32>())\n            .prop_map(|(r, i)| {\n                Value::Complex32(ls::Complex32::new(f32::from_bits(r), f32::from_bits(i)))\n            })\n            .boxed(),\n        \"Complex128\" => (any::<u64>(), any::<u64>())\n            .prop_map(|(r, i)| {\n                Value::Complex64(ls::Complex64::new(f64::from_bits(r), f64::from_bits(i)))\n            })\n            .boxed(),\n        \"Char\" => any::<char>().prop_map(Value::Char).boxed(),\n        \"CodePoint\" => (0u32..=0x10ffff).prop_map(Value::CodePoint).boxed(),\n        \"CodeUnit16\" => any::<u16>().prop_map(Value::CodeUnit16).boxed(),\n        \"Text\" => proptest::collection::vec(any::<char>(), 0..65)\n            .prop_map(|cs| Value::Text(cs.into_iter().collect()))\n            .boxed(),\n        \"CodePointText\" => proptest::collection::vec(0u32..=0x10ffff, 0..65)\n            .prop_map(Value::CodePointText)\n            .boxed(),\n        \"Utf16Text\" => proptest::collection::vec(any::<u16>(), 0..65)\n            .prop_map(Value::Utf16Text)\n            .boxed(),\n        \"Bytes\" => proptest::collection::vec(any::<u8>(), 0..65)\n            .prop_map(Value::Bytes)\n            .boxed(),\n        \"Symbol\" => any::<u64>()\n            .prop_map(|id| Value::Symbol(ls::Symbol::new(format!(\"symbol-{id}\"))))\n            .boxed(),\n        \"Unit\" => Just(Value::Unit).boxed(),\n        \"Null\" => Just(Value::Null).boxed(),\n        \"Undefined\" => Just(Value::Undefined).boxed(),\n        _ => return Err(format!(\"no Rust generator for {name}\")),\n    })\n}\nfn bigint() -> BoxedStrategy<ls::BigInt> {\n    (any::<bool>(), proptest::collection::vec(any::<u8>(), 0..65))\n        .prop_map(|(negative, bytes)| {\n            ls::BigInt::from_bytes_le(\n                if negative {\n                    num_bigint::Sign::Minus\n                } else {\n                    num_bigint::Sign::Plus\n                },\n                &bytes,\n            )\n        })\n        .boxed()\n}\npub fn tuple(types: &[&str]) -> ls::Result<BoxedStrategy<Vec<Value>>> {\n    let mut result = Just(Vec::new()).boxed();\n    for name in types {\n        result = (result, strategy(name)?)\n            .prop_map(|(mut xs, x)| {\n                xs.push(x);\n                xs\n            })\n            .boxed();\n    }\n    Ok(result)\n}\n\n/// Construct the affine integer domain after preceding inputs are known.\n/// An empty continuation returns None so the native flat-map/filter combination\n/// retries the preceding inputs and recomputes the domain during shrinking.\npub fn bounded_integer(\n    name: &str,\n    bounds: Vec<(&str, Value)>,\n    machine_bits: u32,\n) -> ls::Result<Option<BoxedStrategy<Value>>> {\n    use num_traits::{One, Signed, Zero};\n    let width = match name {\n        \"Int8\" | \"UInt8\" => Some(8),\n        \"Int16\" | \"UInt16\" => Some(16),\n        \"Int32\" | \"UInt32\" => Some(32),\n        \"Int64\" | \"UInt64\" => Some(64),\n        \"IntSize\" | \"UIntSize\" | \"UIntPtr\" => Some(machine_bits),\n        _ => None,\n    };\n    let unsigned = name.starts_with(\"UInt\") || name == \"BigUInt\";\n    let mut lo = if unsigned {\n        Some(ls::BigInt::zero())\n    } else {\n        width.map(|w| -(ls::BigInt::one() << (w - 1)))\n    };\n    let mut hi = width.map(|w| (ls::BigInt::one() << (if unsigned { w } else { w - 1 })) - 1u8);\n    for (op, value) in bounds {\n        let r = value.exact()?;\n        let floor = r.floor().to_integer();\n        let ceil = r.ceil().to_integer();\n        let (lower, upper) = match op {\n            \">\" => (Some(floor + 1u8), None),\n            \">=\" => (Some(ceil), None),\n            \"<\" => (None, Some(ceil - 1u8)),\n            \"<=\" => (None, Some(floor)),\n            \"==\" => {\n                if !r.is_integer() {\n                    return Ok(None);\n                }\n                let n = r.to_integer();\n                (Some(n.clone()), Some(n))\n            }\n            _ => return Err(\"invalid planned integer bound\".into()),\n        };\n        if let Some(n) = lower {\n            lo = Some(lo.map_or(n.clone(), |old| old.max(n)));\n        }\n        if let Some(n) = upper {\n            hi = Some(hi.map_or(n.clone(), |old| old.min(n)));\n        }\n    }\n    let span = ls::BigInt::one() << 512usize;\n    let lower = lo.unwrap_or_else(|| hi.as_ref().map_or(-&span, |upper| upper - &span));\n    let upper = hi.unwrap_or_else(|| &lower + &span);\n    if lower > upper {\n        return Ok(None);\n    }\n    let count = &upper - &lower + 1u8;\n    let offset = lower.clone();\n    Ok(Some(\n        prop_oneof![\n            Just(Value::Integer(lower)),\n            Just(Value::Integer(upper)),\n            bigint().prop_map(move |n| Value::Integer(&offset + n.abs() % &count))\n        ]\n        .boxed(),\n    ))\n}\n\npub fn strategy_with_profile(name: &str, bits: u32) -> ls::Result<BoxedStrategy<Value>> {\n    if let Some(inner) = name.strip_prefix(\"List \") {\n        return Ok(\n            proptest::collection::vec(strategy_with_profile(inner, bits)?, 0..65)\n                .prop_map(Value::List)\n                .boxed(),\n        );\n    }\n    if let Some(inner) = name.strip_prefix(\"Maybe \") {\n        return Ok(proptest::option::of(strategy_with_profile(inner, bits)?)\n            .prop_map(|x| Value::Maybe(x.map(Box::new)))\n            .boxed());\n    }\n    if let Some(arguments) = name.strip_prefix(\"Either \") {\n        let (left, right) = ls::either_types(arguments)?;\n        return Ok(prop_oneof![\n            strategy_with_profile(left, bits)?.prop_map(|x| Value::Left(Box::new(x))),\n            strategy_with_profile(right, bits)?.prop_map(|x| Value::Right(Box::new(x)))\n        ]\n        .boxed());\n    }\n    if let Some(inner) = name.strip_prefix(\"Nullable \") {\n        return Ok(proptest::option::of(strategy_with_profile(inner, bits)?)\n            .prop_map(|x| Value::Nullable(x.map(Box::new)))\n            .boxed());\n    }\n    if let Some(inner) = name.strip_prefix(\"Optional \") {\n        return Ok(proptest::option::of(strategy_with_profile(inner, bits)?)\n            .prop_map(|x| Value::Optional(x.map(Box::new)))\n            .boxed());\n    }\n    scalar_strategy(match (name, bits) {\n        (\"IntSize\", 32) => \"Int32\",\n        (\"IntSize\", 64) => \"Int64\",\n        (\"UIntSize\" | \"UIntPtr\", 32) => \"UInt32\",\n        (\"UIntSize\" | \"UIntPtr\", 64) => \"UInt64\",\n        _ => name,\n    })\n}\n\n#[derive(Clone, Debug)]\npub struct Case {\n    pub context: ls::Context,\n    pub values: Vec<Value>,\n    pub error: Option<String>,\n}\n// A case's workflows wait on a virtual clock, as every generated test's do.\nimpl Default for Case {\n    fn default() -> Self {\n        Case { context: ls::Context::testing(), values: Vec::new(), error: None }\n    }\n}\npub fn seeded(strategy: BoxedStrategy<Value>, seeds: Vec<Value>) -> BoxedStrategy<Value> {\n    if seeds.is_empty() {\n        strategy\n    } else {\n        prop_oneof![strategy, proptest::sample::select(seeds)].boxed()\n    }\n}\n\n/// Compose native proptest generators from instantiated Core data schemas.\n/// The structural budget limits samples, not the mathematical input domain.\n/// Memoization shares strategies for repeated fields in recursive products.\npub fn schema_strategy(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n) -> ls::Result<BoxedStrategy<Value>> {\n    if schema.has_contracts() {\n        return Err(\n            \"constructor contracts require checked_schema_strategy and a Symbol context\".into(),\n        );\n    }\n    shape_strategy(schema, ty, bits, budget, Default::default())\n}\n\ntype Witnesses = std::collections::HashMap<ls::TypeRef, Vec<Value>>;\n\nfn value_cost(value: &Value) -> usize {\n    match value {\n        Value::Data(_, fields) | Value::List(fields) => {\n            1 + fields.iter().map(value_cost).sum::<usize>()\n        }\n        Value::Maybe(Some(value))\n        | Value::Nullable(Some(value))\n        | Value::Optional(Some(value))\n        | Value::Left(value)\n        | Value::Right(value) => 1 + value_cost(value),\n        _ => 1,\n    }\n}\n\n// Witnesses are validated before traversal. Keep their instantiated types so a\n// Symbol seed cannot leak into unrelated fields with the same representation.\nfn collect_witnesses(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    value: &Value,\n    seeds: &mut Witnesses,\n) -> ls::Result<()> {\n    // Builtin containers must use their native structural generators so a\n    // witness list can still shrink its length. Seed payloads recursively;\n    // retain named values as fallbacks for uneven recursive node allocations.\n    if !matches!(\n        value,\n        Value::List(_)\n            | Value::Maybe(_)\n            | Value::Nullable(_)\n            | Value::Optional(_)\n            | Value::Left(_)\n            | Value::Right(_)\n    ) {\n        seeds.entry(ty.clone()).or_default().push(value.clone());\n    }\n    if let Some(constructors) = schema.constructor_fields(ty)? {\n        let Value::Data(tag, fields) = value else {\n            return Err(\"invalid data witness\".into());\n        };\n        let constructor = constructors\n            .iter()\n            .find(|c| c.tag == tag)\n            .ok_or(\"unknown witness constructor\")?;\n        let field_types = schema.witnessed_fields(constructor.tag, &constructor.fields, fields)?;\n        for (field_type, field) in field_types.iter().zip(fields) {\n            collect_witnesses(schema, field_type, field, seeds)?;\n        }\n    } else if let ls::TypeRef::Named(_, arguments) = ty {\n        match value {\n            Value::List(values) => {\n                for value in values {\n                    collect_witnesses(schema, &arguments[0], value, seeds)?;\n                }\n            }\n            Value::Maybe(Some(value))\n            | Value::Nullable(Some(value))\n            | Value::Optional(Some(value))\n            | Value::Left(value) => {\n                collect_witnesses(schema, &arguments[0], value, seeds)?;\n            }\n            Value::Right(value) => collect_witnesses(schema, &arguments[1], value, seeds)?,\n            _ => {}\n        }\n    }\n    Ok(())\n}\n\n/// Reject only false predicates, across whole candidates rather than individual\n/// branches. Native proptest filtering bounds retries and preserves shrinking.\n/// Evaluation errors remain Err values that the property must report as failures.\n/// Context clones preserve Symbol identity without mutating it during shrinking.\npub fn checked_schema_strategy(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    context: &ls::Context,\n    witnesses: Vec<Value>,\n) -> ls::Result<BoxedStrategy<ls::Result<Value>>> {\n    checked_schema_strategy_with_generators(\n        schema,\n        ty,\n        bits,\n        budget,\n        context,\n        witnesses,\n        &NativeGenerators::default(),\n    )\n}\n\npub fn checked_schema_strategy_with_generators(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    context: &ls::Context,\n    witnesses: Vec<Value>,\n    native: &NativeGenerators,\n) -> ls::Result<BoxedStrategy<ls::Result<Value>>> {\n    let mut seeds = Witnesses::new();\n    for witness in witnesses {\n        let value = schema.validate_with_context(witness, ty, bits, &mut context.clone())?;\n        if value_cost(&value) > budget {\n            return Err(\"constructor witness exceeds structural node budget\".into());\n        }\n        collect_witnesses(schema, ty, &value, &mut seeds)?;\n    }\n    let strategy =\n        shape_strategy_with_generators(schema, ty, bits, budget, seeds, context, native)?;\n    let schema = schema.clone();\n    let ty = ty.clone();\n    let context = context.clone();\n    Ok(strategy\n        .prop_filter_map(\"constructor field refinement\", move |value| {\n            match schema.check_with_context(value, &ty, bits, &mut context.clone()) {\n                Ok(ls::ValueCheck::Accepted(value)) => Some(Ok(value)),\n                Ok(ls::ValueCheck::Rejected(_)) => None,\n                Err(error) => Some(Err(error)),\n            }\n        })\n        .boxed())\n}\n\nfn shape_strategy(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    witnesses: Witnesses,\n) -> ls::Result<BoxedStrategy<Value>> {\n    shape_strategy_with_generators(\n        schema,\n        ty,\n        bits,\n        budget,\n        witnesses,\n        &ls::Context::default(),\n        &NativeGenerators::default(),\n    )\n}\n\nfn shape_strategy_with_generators(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    witnesses: Witnesses,\n    context: &ls::Context,\n    native: &NativeGenerators,\n) -> ls::Result<BoxedStrategy<Value>> {\n    type Request = (ls::TypeRef, usize);\n    struct Builder<'a> {\n        schema: &'a ls::Schema,\n        context: &'a ls::Context,\n        native: &'a NativeGenerators,\n        bits: u32,\n        witnesses: Witnesses,\n        inhabited: std::collections::HashMap<Request, bool>,\n        generators: std::collections::HashMap<Request, BoxedStrategy<Value>>,\n    }\n\n    impl Builder<'_> {\n        fn can_generate(&mut self, ty: &ls::TypeRef, budget: usize) -> ls::Result<bool> {\n            if budget == 0 {\n                return Ok(false);\n            }\n            let key = (ty.clone(), budget);\n            if let Some(result) = self.inhabited.get(&key) {\n                return Ok(*result);\n            }\n            let result = if self.native.factory(ty).is_some() {\n                true\n            } else if let Some(constructors) = self.schema.constructor_fields(ty)? {\n                let mut found = false;\n                for constructor in constructors {\n                    for (fields, _) in self.schema.witness_choices(&constructor)? {\n                        if self.allocate(&fields, budget - 1)?.is_some() {\n                            found = true;\n                        }\n                    }\n                }\n                found\n            } else {\n                let ls::TypeRef::Named(name, arguments) = ty else {\n                    return Err(\"uninstantiated generator type\".into());\n                };\n                match (*name, arguments.as_slice()) {\n                    (\"List\" | \"Maybe\" | \"Nullable\" | \"Optional\", [_]) => true,\n                    (\"Either\", [left, right]) => {\n                        self.can_generate(left, budget - 1)?\n                            || self.can_generate(right, budget - 1)?\n                    }\n                    (_, []) => true,\n                    _ => return Err(format!(\"unsupported generator type: {ty:?}\")),\n                }\n            };\n            self.inhabited.insert(key, result);\n            Ok(result)\n        }\n\n        fn minimum(&mut self, ty: &ls::TypeRef, limit: usize) -> ls::Result<Option<usize>> {\n            for cost in 1..=limit {\n                if self.can_generate(ty, cost)? {\n                    return Ok(Some(cost));\n                }\n            }\n            Ok(None)\n        }\n\n        // Reserve every field's minimum before sharing the remaining nodes.\n        // A deep field must not disappear merely because its siblings are small.\n        fn allocate(\n            &mut self,\n            fields: &[ls::TypeRef],\n            budget: usize,\n        ) -> ls::Result<Option<Vec<usize>>> {\n            let mut remaining = budget;\n            let mut costs = Vec::new();\n            for field in fields {\n                let Some(cost) = self.minimum(field, remaining)? else {\n                    return Ok(None);\n                };\n                costs.push(cost);\n                remaining -= cost;\n            }\n            let count = costs.len();\n            for (index, cost) in costs.iter_mut().enumerate() {\n                *cost += remaining / count + usize::from(index < remaining % count);\n            }\n            Ok(Some(costs))\n        }\n\n        fn generate(\n            &mut self,\n            ty: &ls::TypeRef,\n            budget: usize,\n        ) -> ls::Result<BoxedStrategy<Value>> {\n            if !self.can_generate(ty, budget)? {\n                return Err(format!(\n                    \"no value within structural node budget {budget}: {ty:?}\"\n                ));\n            }\n            let key = (ty.clone(), budget);\n            if let Some(cached) = self.generators.get(&key) {\n                return Ok(cached.clone());\n            }\n            let result = if let Some(factory) = self.native.factory(ty) {\n                let ls::TypeRef::Named(_, arguments) = ty else {\n                    return Err(\"uninstantiated native generator type\".into());\n                };\n                let mut children = Vec::new();\n                for argument in arguments {\n                    let remaining = budget.saturating_sub(1).max(1);\n                    let child = if self.can_generate(argument, remaining)? {\n                        self.generate(argument, remaining)?\n                    } else {\n                        // Phantom parameters may be uninhabited. Keep a native\n                        // strategy argument that rejects if actually sampled.\n                        Just(Value::Unit)\n                            .prop_filter(\n                                format!(\"no native generator argument within node budget {remaining}: {argument:?}\"),\n                                |_| false,\n                            )\n                            .boxed()\n                    };\n                    children.push(child);\n                }\n                let strategy = factory(self.schema, ty, self.bits, self.context, children)?;\n                let schema = self.schema.clone();\n                let ty = ty.clone();\n                let bits = self.bits;\n                let context = self.context.clone();\n                strategy\n                    .prop_map(move |value| {\n                        schema\n                            .validate_with_context(value, &ty, bits, &mut context.clone())\n                            .unwrap_or_else(|error| panic!(\"native generator {ty:?}: {error}\"))\n                    })\n                    .boxed()\n            } else if let Some(constructors) = self.schema.constructor_fields(ty)? {\n                let mut alternatives = Vec::new();\n                for constructor in constructors {\n                  // A field-only existential takes each type of the witness pool.\n                  for (declared, witnesses) in self.schema.witness_choices(&constructor)? {\n                    let Some(costs) = self.allocate(&declared, budget - 1)? else {\n                        continue;\n                    };\n                    let mut fields = Just(Vec::<Value>::new()).boxed();\n                    for (field, cost) in declared.iter().zip(costs) {\n                        let next = self.generate(field, cost)?;\n                        fields = (fields, next)\n                            .prop_map(|(mut values, value)| {\n                                values.push(value);\n                                values\n                            })\n                            .boxed();\n                    }\n                    let tag = constructor.tag;\n                    alternatives.push(\n                        fields\n                            .prop_map(move |mut fields| {\n                                fields.extend(witnesses.iter().cloned());\n                                ls::construct_data(tag, fields)\n                            })\n                            .boxed(),\n                    );\n                  }\n                }\n                let union = proptest::strategy::Union::new(alternatives).boxed();\n                // Generated collections are canonicalised rather than filtered.\n                match ty {\n                    ls::TypeRef::Named(name, _)\n                        if name.starts_with(ls::COLLECTIONS) && (name.ends_with(\"::Set\") || name.ends_with(\"::KeyVal\")) =>\n                    {\n                        let keyed = name.ends_with(\"::KeyVal\");\n                        union\n                            .prop_map(move |value| match value {\n                                Value::Data(tag, mut fields) if fields.len() == 1 => match fields.pop().unwrap() {\n                                    Value::List(items) => Value::Data(\n                                        tag,\n                                        vec![Value::List(ls::canonical_items(items, keyed).expect(\"keyed values have an order\"))],\n                                    ),\n                                    other => Value::Data(tag, vec![other]),\n                                },\n                                other => other,\n                            })\n                            .boxed()\n                    }\n                    _ => union,\n                }\n            } else {\n                let ls::TypeRef::Named(name, arguments) = ty else {\n                    return Err(\"uninstantiated generator type\".into());\n                };\n                match (*name, arguments.as_slice()) {\n                    (\"List\", [element]) => {\n                        let remaining = budget - 1;\n                        let maximum = self\n                            .minimum(element, remaining)?\n                            .map_or(0, |cost| remaining / cost);\n                        let mut lengths = vec![Just(Value::List(vec![])).boxed()];\n                        for length in 1..=maximum {\n                            let elements = self.generate(element, remaining / length)?;\n                            lengths.push(\n                                proptest::collection::vec(elements, length..=length)\n                                    .prop_map(Value::List)\n                                    .boxed(),\n                            );\n                        }\n                        // Native dependent shrinking changes length and then\n                        // shrinks elements under the recomputed size bound.\n                        (0..=maximum)\n                            .prop_flat_map(move |length| lengths[length].clone())\n                            .boxed()\n                    }\n                    (\"Maybe\" | \"Nullable\" | \"Optional\", [element]) => {\n                        let values = if self.can_generate(element, budget - 1)? {\n                            proptest::option::of(self.generate(element, budget - 1)?).boxed()\n                        } else {\n                            Just(None).boxed()\n                        };\n                        let name = *name;\n                        values\n                            .prop_map(move |value| match name {\n                                \"Maybe\" => Value::Maybe(value.map(Box::new)),\n                                \"Nullable\" => Value::Nullable(value.map(Box::new)),\n                                _ => Value::Optional(value.map(Box::new)),\n                            })\n                            .boxed()\n                    }\n                    (\"Either\", [left, right]) => {\n                        let mut alternatives = Vec::new();\n                        if self.can_generate(left, budget - 1)? {\n                            alternatives.push(\n                                self.generate(left, budget - 1)?\n                                    .prop_map(|value| Value::Left(Box::new(value)))\n                                    .boxed(),\n                            );\n                        }\n                        if self.can_generate(right, budget - 1)? {\n                            alternatives.push(\n                                self.generate(right, budget - 1)?\n                                    .prop_map(|value| Value::Right(Box::new(value)))\n                                    .boxed(),\n                            );\n                        }\n                        proptest::strategy::Union::new(alternatives).boxed()\n                    }\n                    (_, []) => strategy_with_profile(name, self.bits)?,\n                    _ => return Err(format!(\"unsupported generator type: {ty:?}\")),\n                }\n            };\n            let seeds = self\n                .witnesses\n                .get(ty)\n                .into_iter()\n                .flatten()\n                .filter(|value| value_cost(value) <= budget)\n                .cloned()\n                .collect();\n            let result = if self.native.factory(ty).is_some() {\n                result\n            } else {\n                seeded(result, seeds)\n            };\n            self.generators.insert(key, result.clone());\n            Ok(result)\n        }\n    }\n\n    if !matches!(bits, 32 | 64) {\n        return Err(\"machineBits must be 32 or 64\".into());\n    }\n    Builder {\n        schema,\n        context,\n        native,\n        bits,\n        witnesses,\n        inhabited: Default::default(),\n        generators: Default::default(),\n    }\n    .generate(ty, budget)\n}\n\nconst INDEX_SLACK: u64 = 16;\nconst INDEX_CHOICES: usize = 6;\n\n/// A prefix index term over field indices (`f<i>`), literals (`c<n>`) and the\n/// natural operators `+ - * div mod ^`.\n#[derive(Clone, Debug)]\nenum IndexTerm {\n    Constant(u64),\n    Field(usize),\n    Apply(String, Box<IndexTerm>, Box<IndexTerm>),\n}\n\nfn parse_index_term(tokens: &[&str], at: &mut usize) -> ls::Result<IndexTerm> {\n    let token = *tokens.get(*at).ok_or(\"malformed index term\")?;\n    *at += 1;\n    if let Some(digits) = token.strip_prefix('c') {\n        return Ok(IndexTerm::Constant(digits.parse().map_err(|_| \"malformed index term\")?));\n    }\n    if let Some(digits) = token.strip_prefix('f') {\n        return Ok(IndexTerm::Field(digits.parse().map_err(|_| \"malformed index term\")?));\n    }\n    if ![\"+\", \"-\", \"*\", \"div\", \"mod\", \"^\"].contains(&token) {\n        return Err(\"malformed index term\".into());\n    }\n    let left = parse_index_term(tokens, at)?;\n    let right = parse_index_term(tokens, at)?;\n    Ok(IndexTerm::Apply(token.to_string(), Box::new(left), Box::new(right)))\n}\n\n/// Natural index arithmetic; `None` when an operation has no natural value.\nfn eval_index_term(term: &IndexTerm, fields: &[(usize, u64)]) -> Option<u64> {\n    match term {\n        IndexTerm::Constant(value) => Some(*value),\n        IndexTerm::Field(position) => fields.iter().find(|(p, _)| p == position).map(|(_, v)| *v),\n        IndexTerm::Apply(op, left, right) => {\n            let x = eval_index_term(left, fields)?;\n            let y = eval_index_term(right, fields)?;\n            match op.as_str() {\n                \"+\" => x.checked_add(y),\n                \"-\" => x.checked_sub(y),\n                \"*\" => x.checked_mul(y),\n                \"div\" => x.checked_div(y),\n                \"mod\" => x.checked_rem(y),\n                _ => u32::try_from(y).ok().filter(|e| *e <= 64).and_then(|e| x.checked_pow(e)),\n            }\n        }\n    }\n}\n\nfn index_term_fields(term: &IndexTerm, into: &mut Vec<usize>) {\n    match term {\n        IndexTerm::Constant(_) => {}\n        IndexTerm::Field(position) => {\n            if !into.contains(position) {\n                into.push(*position);\n            }\n        }\n        IndexTerm::Apply(_, left, right) => {\n            index_term_fields(left, into);\n            index_term_fields(right, into);\n        }\n    }\n}\n\ntype IndexAssignment = Vec<(usize, u64)>;\n\nstruct IndexVariant {\n    tag: &'static str,\n    fields: Vec<ls::TypeRef>,\n    plain: Vec<Option<BoxedStrategy<Value>>>,\n    term: IndexTerm,\n    guards: Vec<(bool, IndexTerm, IndexTerm)>,\n    positions: Vec<usize>,\n}\n\nimpl IndexVariant {\n    fn ready(&self) -> bool {\n        self.plain\n            .iter()\n            .enumerate()\n            .all(|(index, strategy)| self.positions.contains(&index) || strategy.is_some())\n    }\n\n    /// Every guard-satisfying assignment of reachable indices to the index\n    /// fields, with the index it produces.\n    fn assignments(\n        &self,\n        reach: &std::collections::HashSet<(ls::TypeRef, u64)>,\n        limit: u64,\n    ) -> Vec<(u64, IndexAssignment)> {\n        let mut found = Vec::new();\n        let mut current = Vec::new();\n        self.extend(reach, limit, 0, &mut current, &mut found);\n        found\n    }\n\n    fn extend(\n        &self,\n        reach: &std::collections::HashSet<(ls::TypeRef, u64)>,\n        limit: u64,\n        at: usize,\n        current: &mut IndexAssignment,\n        found: &mut Vec<(u64, IndexAssignment)>,\n    ) {\n        if at == self.positions.len() {\n            let holds = self.guards.iter().all(|(equal, left, right)| {\n                match (eval_index_term(left, current), eval_index_term(right, current)) {\n                    (Some(x), Some(y)) => if *equal { x == y } else { x >= y },\n                    _ => false,\n                }\n            });\n            if holds {\n                if let Some(value) = eval_index_term(&self.term, current).filter(|v| *v <= limit) {\n                    found.push((value, current.clone()));\n                }\n            }\n            return;\n        }\n        let position = self.positions[at];\n        for value in 0..=limit {\n            if reach.contains(&(self.fields[position].clone(), value)) {\n                current.push((position, value));\n                self.extend(reach, limit, at + 1, current, found);\n                current.pop();\n            }\n        }\n    }\n}\n\n/// Solved index levels: per family and level, each feasible variant with the\n/// field-index assignments that produce that level.\nstruct IndexTable {\n    variants: std::collections::HashMap<ls::TypeRef, Vec<IndexVariant>>,\n    solutions: std::collections::HashMap<(ls::TypeRef, u64), Vec<(usize, Vec<IndexAssignment>)>>,\n}\n\n/// A lazily built strategy for one family at one level, so children may sit\n/// at higher levels than their parents.\n#[derive(Clone)]\nstruct IndexedValue {\n    table: std::sync::Arc<IndexTable>,\n    family: ls::TypeRef,\n    level: u64,\n}\n\nimpl std::fmt::Debug for IndexedValue {\n    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {\n        write!(f, \"IndexedValue({:?}, {})\", self.family, self.level)\n    }\n}\n\nimpl Strategy for IndexedValue {\n    type Tree = Box<dyn proptest::strategy::ValueTree<Value = Value>>;\n    type Value = Value;\n\n    fn new_tree(&self, runner: &mut proptest::test_runner::TestRunner) -> proptest::strategy::NewTree<Self> {\n        let variants = &self.table.variants[&self.family];\n        let alternatives: Vec<BoxedStrategy<Value>> = self.table.solutions\n            [&(self.family.clone(), self.level)]\n            .iter()\n            .map(|(index, choices)| {\n                let variant = &variants[*index];\n                let table = self.table.clone();\n                let fields = variant.fields.clone();\n                let plain = variant.plain.clone();\n                let tag = variant.tag;\n                proptest::sample::select(choices.clone())\n                    .prop_flat_map(move |assignment| {\n                        let children: Vec<BoxedStrategy<Value>> = fields\n                            .iter()\n                            .enumerate()\n                            .map(|(index, field)| {\n                                match assignment.iter().find(|(p, _)| *p == index) {\n                                    Some((_, level)) => IndexedValue {\n                                        table: table.clone(),\n                                        family: field.clone(),\n                                        level: *level,\n                                    }\n                                    .boxed(),\n                                    None => plain[index].clone().unwrap(),\n                                }\n                            })\n                            .collect();\n                        children.prop_map(move |values| ls::construct_data(tag, values))\n                    })\n                    .boxed()\n            })\n            .collect();\n        proptest::strategy::Union::new(alternatives)\n            .new_tree(runner)\n            .map(|tree| Box::new(tree) as Box<dyn proptest::strategy::ValueTree<Value = Value>>)\n    }\n}\n\n/// Values whose structural index equals `target`. Each constructor carries its\n/// index term then its guards, in prefix notation over field indices.\n/// Reachability is a forward fixpoint over levels 0..target+slack, so a child\n/// may exceed its parent's index; the target is then solved backwards, and\n/// generation never filters. Assignments shrink toward the first.\npub fn indexed_strategy(\n    schema: &ls::Schema,\n    ty: &ls::TypeRef,\n    bits: u32,\n    budget: usize,\n    target: &Value,\n    equations: &[(&str, &[&str])],\n) -> ls::Result<BoxedStrategy<Value>> {\n    let Value::Integer(target) = target else {\n        return Err(\"index target must be a natural number\".into());\n    };\n    let requested: Option<u64> = target.to_string().parse().ok();\n    let limit = requested.unwrap_or(0).saturating_add(INDEX_SLACK);\n    let parse = |tag: &str| -> ls::Result<(IndexTerm, Vec<(bool, IndexTerm, IndexTerm)>, Vec<usize>)> {\n        let (_, texts) = equations\n            .iter()\n            .find(|(name, _)| *name == tag)\n            .ok_or_else(|| format!(\"missing index equation for {tag}\"))?;\n        let first = texts.first().ok_or_else(|| format!(\"missing index equation for {tag}\"))?;\n        let tokens: Vec<&str> = first.split(' ').collect();\n        let mut at = 0;\n        let term = parse_index_term(&tokens, &mut at)?;\n        if at != tokens.len() {\n            return Err(\"malformed index term\".into());\n        }\n        let mut positions = Vec::new();\n        index_term_fields(&term, &mut positions);\n        let mut guards = Vec::new();\n        for text in &texts[1..] {\n            let parts: Vec<&str> = text.split(' ').collect();\n            let equal = match parts.first() {\n                Some(&\"==\") => true,\n                Some(&\">=\") => false,\n                _ => return Err(\"malformed index guard\".into()),\n            };\n            let mut at = 1;\n            let left = parse_index_term(&parts, &mut at)?;\n            let right = parse_index_term(&parts, &mut at)?;\n            index_term_fields(&left, &mut positions);\n            index_term_fields(&right, &mut positions);\n            guards.push((equal, left, right));\n        }\n        Ok((term, guards, positions))\n    };\n    let mut variants: std::collections::HashMap<ls::TypeRef, Vec<IndexVariant>> =\n        std::collections::HashMap::new();\n    let mut plain: std::collections::HashMap<ls::TypeRef, Option<BoxedStrategy<Value>>> =\n        std::collections::HashMap::new();\n    let mut pending = vec![ty.clone()];\n    while let Some(next) = pending.pop() {\n        if variants.contains_key(&next) {\n            continue;\n        }\n        let constructors = schema\n            .constructor_fields(&next)?\n            .ok_or(\"indexed generation requires a data type\")?;\n        let mut family = Vec::new();\n        for constructor in constructors {\n            let (term, guards, positions) = parse(constructor.tag)?;\n            pending.extend(positions.iter().map(|p| constructor.fields[*p].clone()));\n            let mut strategies = Vec::new();\n            for (index, field) in constructor.fields.iter().enumerate() {\n                if positions.contains(&index) {\n                    strategies.push(None);\n                    continue;\n                }\n                if !plain.contains_key(field) {\n                    let strategy = shape_strategy(schema, field, bits, budget, Witnesses::new()).ok();\n                    plain.insert(field.clone(), strategy);\n                }\n                strategies.push(plain[field].clone());\n            }\n            family.push(IndexVariant {\n                tag: constructor.tag,\n                fields: constructor.fields.clone(),\n                plain: strategies,\n                term,\n                guards,\n                positions,\n            });\n        }\n        variants.insert(next, family);\n    }\n    let mut reach = std::collections::HashSet::new();\n    loop {\n        let mut next = reach.clone();\n        for (family, list) in &variants {\n            for variant in list.iter().filter(|variant| variant.ready()) {\n                for (value, _) in variant.assignments(&reach, limit) {\n                    next.insert((family.clone(), value));\n                }\n            }\n        }\n        if next.len() == reach.len() {\n            break;\n        }\n        reach = next;\n    }\n    // An open target (negative), or one that names no value, generates from the\n    // smallest reachable indices; an index claim rejects a mismatch.\n    let levels: Vec<u64> = match requested.filter(|k| reach.contains(&(ty.clone(), *k))) {\n        Some(k) => vec![k],\n        None => (0..=limit)\n            .filter(|level| reach.contains(&(ty.clone(), *level)))\n            .take(INDEX_CHOICES)\n            .collect(),\n    };\n    if levels.is_empty() {\n        return Err(format!(\"no value of {ty:?} has an index\"));\n    }\n    let mut solutions: std::collections::HashMap<(ls::TypeRef, u64), Vec<(usize, Vec<IndexAssignment>)>> =\n        std::collections::HashMap::new();\n    for (family, list) in &variants {\n        for (index, variant) in list.iter().enumerate().filter(|(_, variant)| variant.ready()) {\n            let mut by_level: std::collections::BTreeMap<u64, Vec<IndexAssignment>> =\n                std::collections::BTreeMap::new();\n            for (value, assignment) in variant.assignments(&reach, limit) {\n                by_level.entry(value).or_default().push(assignment);\n            }\n            for (level, choices) in by_level {\n                solutions.entry((family.clone(), level)).or_default().push((index, choices));\n            }\n        }\n    }\n    let table = std::sync::Arc::new(IndexTable { variants, solutions });\n    let family = ty.clone();\n    Ok(proptest::sample::select(levels)\n        .prop_flat_map(move |level| IndexedValue { table: table.clone(), family: family.clone(), level })\n        .boxed())\n}\n"
runtimeSource "kotlin-strategies" = "/**\n * Kotest combinators that keep native shrink trees, which LawSpec's generated arbitraries rely on\n * so that Kotest's shrinker, not a second one, reduces counterexamples.\n * ref:DEC-native-property-frameworks ref:kotest ref:DEC-shrink-within-domain\n */\npackage lawspec.testing\n\nimport io.kotest.property.Arb\nimport io.kotest.property.RTree\nimport io.kotest.property.RandomSource\nimport io.kotest.property.Sample\nimport io.kotest.property.arbitrary.list\nimport io.kotest.property.arbitrary.merge\n\n/** Kotest's merge preserves branch samples; choice in 5.9 keeps only values. */\nfun <A> lawspecChoice(first: Arb<A>, second: Arb<A>): Arb<A> = first.merge(second)\n\n/** Composes Kotest's list shrink tree with the native trees of its elements. */\nfun <A> lawspecList(element: Arb<A>, range: IntRange): Arb<List<A>> {\n    // Kotest 5.9's list generator keeps structural shrinking but discards element\n    // samples. Retain those samples as the list payload and compose both trees.\n    val sampledElements = object : Arb<Sample<A>>() {\n        // Arb.edgecase returns only a value, so it cannot preserve a shrink tree.\n        // LawSpec emits element boundary cases separately from random properties.\n        override fun edgecase(rs: RandomSource): Sample<A>? = null\n\n        override fun sample(rs: RandomSource): Sample<Sample<A>> = Sample(element.sample(rs))\n    }\n    val lists = Arb.list(sampledElements, range)\n    return object : Arb<List<A>>() {\n        override fun edgecase(rs: RandomSource): List<A>? =\n          lists.edgecase(rs)?.map { it.value }\n\n        override fun sample(rs: RandomSource): Sample<List<A>> {\n            val tree = composeListTree(lists.sample(rs).shrinks)\n            return Sample(tree.value(), tree)\n        }\n    }\n}\n\nprivate fun <A> composeListTree(source: RTree<List<Sample<A>>>): RTree<List<A>> =\n  RTree(\n      { source.value().map { it.value } },\n      lazy {\n          source.children.value.map { composeListTree(it) } +\n            source.value().flatMap { sample ->\n                sample.shrinks.children.value.map { child ->\n                    composeListTree(replaceSample(source, sample, Sample(child.value(), child)))\n                }\n            }\n      },\n  )\n\nprivate fun <A> replaceSample(\n    source: RTree<List<Sample<A>>>,\n    original: Sample<A>,\n    replacement: Sample<A>,\n): RTree<List<Sample<A>>> =\n  RTree(\n      { source.value().map { if (it === original) replacement else it } },\n      lazy { source.children.value.map { replaceSample(it, original, replacement) } },\n  )\n\n/** Preserve both native shrink trees when a later arbitrary depends on a value.\n *\n * Kotest 5.9's flatMap passes only Sample.value to its continuation. Keep the\n * source tree as well, so list lengths and constructor choices can still shrink.\n */\nfun <A, B> lawspecFlatMap(source: Arb<A>, next: (A) -> Arb<B>): Arb<B> =\n  object : Arb<B>() {\n      override fun edgecase(rs: RandomSource): B? = null\n\n      override fun sample(rs: RandomSource): Sample<B> {\n          val sourceTree = source.sample(rs).shrinks\n          val seed = rs.random.nextLong()\n          fun draw(tree: RTree<A>): RTree<B> =\n            next(tree.value()).sample(RandomSource.seeded(seed)).shrinks\n\n          fun compose(sourceNode: RTree<A>, result: RTree<B>): RTree<B> =\n            RTree(\n                { result.value() },\n                lazy {\n                    sourceNode.children.value.map { compose(it, draw(it)) } +\n                      result.children.value.map { compose(sourceNode, it) }\n                },\n            )\n\n          val tree = compose(sourceTree, draw(sourceTree))\n          return Sample(tree.value(), tree)\n      }\n  }\n"
runtimeSource "kotlin-native" = "package lawspec.runtime\n\n/**\n * Native support types whose domains differ from Kotlin's built-in types.\n *\n * Kotlin's null cannot tell an absent value from a present null, so Nullable keeps the two apart,\n * as a law's Maybe and Nullable types require. ref:DEC-algebraic-maybe-either\n */\nobject LawSpecKotlin {\n    sealed interface Nullable<T> {\n        class Null<T> : Nullable<T>\n\n        class Present<T>(val value: T) : Nullable<T>\n    }\n\n    sealed interface Optional<T> {\n        class Undefined<T> : Optional<T>\n\n        class Present<T>(val value: T) : Optional<T>\n    }\n\n    object Null\n\n    object Undefined\n\n    /** Equality follows the fixture identity, even after a checked round trip. */\n    class Symbol internal constructor(internal val token: LawSpecRuntime.SymbolValue) {\n        constructor(description: String) : this(LawSpecRuntime.SymbolValue(description))\n\n        val description: String\n            get() = token.description()\n\n        override fun equals(other: Any?): Boolean = other is Symbol && token === other.token\n\n        override fun hashCode(): Int = System.identityHashCode(token)\n    }\n}\n"
runtimeSource "kotlin-codecs" = "package lawspec.runtime\n\nimport lawspec.runtime.LawSpecKotlin as Native\nimport lawspec.runtime.LawSpecRuntime as Runtime\nimport lawspec.runtime.LawSpecSchema.Codec\nimport lawspec.runtime.LawSpecSchema.Named\nimport kotlin.time.toJavaDuration\nimport kotlin.time.toKotlinDuration\n\n/**\n * Framework-independent bridges for Kotlin-specific native representations.\n *\n * Adapters work with Kotlin's own types, such as kotlin.time.Duration and Set; each codec converts\n * between them and LawSpec's values and checks the result, so a law never sees a native value\n * outside its domain. ref:DEC-native-bindings-typed-identity\n */\nobject LawSpecKotlinCodecs {\n    fun construct(\n        schema: LawSpecSchema,\n        type: Named,\n        tag: String,\n        fields: List<Runtime.Value>,\n        bits: Int,\n        symbols: MutableMap<String, Any> = mutableMapOf(),\n    ): Runtime.Value {\n        if (type.name() != \"List\") return schema.construct(type, tag, fields, bits, symbols)\n        val values = when {\n            tag == \"List::Nil\" && fields.isEmpty() -> emptyList()\n            tag == \"List::Cons\" && fields.size == 2 -> {\n                val tail = fields[1].data() as List<*>\n                listOf(fields[0]) + tail.map { it as Runtime.Value }\n            }\n            else -> throw IllegalArgumentException(\"invalid List constructor or field count\")\n        }\n        return Runtime.Value(LawSpecSchema.key(type), values)\n    }\n\n    fun match(\n        schema: LawSpecSchema,\n        type: Named,\n        value: Runtime.Value,\n        bits: Int,\n        branch: (String, List<Runtime.Value>) -> Runtime.Value,\n    ): Runtime.Value = match(schema, type, value, bits, mutableMapOf(), branch)\n\n    fun match(\n        schema: LawSpecSchema,\n        type: Named,\n        value: Runtime.Value,\n        bits: Int,\n        symbols: MutableMap<String, Any>,\n        branch: (String, List<Runtime.Value>) -> Runtime.Value,\n    ): Runtime.Value {\n        // Values in generated code are checked where they are built, decoded\n        // or drawn, so matching only dispatches.\n        val checked = value\n        if (type.name() == \"List\") {\n            val values = (checked.data() as List<*>).map { it as Runtime.Value }\n            return if (values.isEmpty()) {\n                branch(\"List::Nil\", emptyList())\n            } else {\n                branch(\n                    \"List::Cons\",\n                    listOf(values[0], Runtime.Value(checked.type(), values.drop(1))),\n                )\n            }\n        }\n        val data = checked.data() as Runtime.Data\n        return branch(data.tag(), data.fields())\n    }\n\n    /** A Duration natively: a kotlin.time.Duration of whole microseconds. */\n    fun duration(schema: LawSpecSchema, bits: Int, symbols: MutableMap<String, Any> = mutableMapOf()): Codec<kotlin.time.Duration> {\n        val codec = schema.duration(bits, symbols)\n        return schema.codec(codec.type(), bits, symbols, { codec.encode(it.toJavaDuration()) }, { codec.decode(it).toKotlinDuration() })\n    }\n\n    /** A Set natively, in canonical order when LawSpec builds it. */\n    fun <T> set(schema: LawSpecSchema, bits: Int, element: Codec<T>, symbols: MutableMap<String, Any> = mutableMapOf()): Codec<Set<T>> {\n        val codec = schema.set(element, bits, symbols)\n        return schema.codec(codec.type(), bits, symbols, { codec.encode(it) }, { codec.decode(it) })\n    }\n\n    /** A KeyVal natively, in canonical key order when LawSpec builds it. */\n    fun <K, V> keyVal(\n        schema: LawSpecSchema, bits: Int, keys: Codec<K>, values: Codec<V>,\n        symbols: MutableMap<String, Any> = mutableMapOf(),\n    ): Codec<Map<K, V>> {\n        val codec = schema.keyVal(keys, values, bits, symbols)\n        return schema.codec(codec.type(), bits, symbols, { codec.encode(it) }, { codec.decode(it) })\n    }\n\n    /** A Queue, Stack or Deque natively: an ArrayDeque from its first item (a Stack's top is last). */\n    fun <T> sequence(\n        schema: LawSpecSchema, bits: Int, name: String, element: Codec<T>,\n        symbols: MutableMap<String, Any> = mutableMapOf(),\n    ): Codec<ArrayDeque<T>> {\n        val codec = schema.sequence(name, element, bits, symbols)\n        val stack = name == \"Stack\"\n        return schema.codec(\n            codec.type(), bits, symbols,\n            { deque -> codec.encode(java.util.ArrayDeque(if (stack) deque.reversed() else deque)) },\n            { value -> codec.decode(value).toList().let { if (stack) it.reversed() else it }.let { ArrayDeque(it) } },\n        )\n    }\n\n    fun unit(schema: LawSpecSchema, bits: Int): Codec<Unit> =\n      schema.codec(Named(\"Unit\"), bits, { Runtime.absent(\"Unit\") }, { })\n\n    fun nullValue(schema: LawSpecSchema, bits: Int): Codec<Native.Null> =\n      schema.codec(Named(\"Null\"), bits, { Runtime.absent(\"Null\") }, { Native.Null })\n\n    fun undefined(schema: LawSpecSchema, bits: Int): Codec<Native.Undefined> =\n      schema.codec(\n          Named(\"Undefined\"), bits, { Runtime.absent(\"Undefined\") }, { Native.Undefined },\n      )\n\n    fun symbol(schema: LawSpecSchema, bits: Int): Codec<Native.Symbol> =\n      schema.codec(\n          Named(\"Symbol\"),\n          bits,\n          { Runtime.Value(\"Symbol\", it.token) },\n          { Native.Symbol(it.data() as Runtime.SymbolValue) },\n      )\n\n    fun codePointText(schema: LawSpecSchema, bits: Int): Codec<IntArray> =\n      schema.codec(\n          Named(\"CodePointText\"),\n          bits,\n          { Runtime.sequence(\"CodePointText\", it) },\n          { value -> (value.data() as List<*>).map { it as Int }.toIntArray() },\n      )\n\n    fun <T> nullable(\n        schema: LawSpecSchema,\n        bits: Int,\n        element: Codec<T>,\n        symbols: MutableMap<String, Any> = mutableMapOf(),\n    ): Codec<Native.Nullable<T>> {\n        val type = Named(\"Nullable\", element.type())\n        return schema.codec(\n            type,\n            bits,\n            symbols,\n            { value ->\n                val payload = when (value) {\n                    is Native.Nullable.Null -> Runtime.Presence(false, null)\n                    is Native.Nullable.Present -> {\n                        Runtime.Presence(\n                            true, LawSpecSchema.encodeField(element, value.value, \"present\"),\n                        )\n                    }\n                }\n                Runtime.Value(LawSpecSchema.key(type), payload)\n            },\n            { value ->\n                val payload = value.data() as Runtime.Presence\n                if (payload.present()) {\n                    Native.Nullable.Present(element.decode(payload.value()))\n                } else {\n                    Native.Nullable.Null()\n                }\n            },\n        )\n    }\n\n    fun <T> optional(\n        schema: LawSpecSchema,\n        bits: Int,\n        element: Codec<T>,\n        symbols: MutableMap<String, Any> = mutableMapOf(),\n    ): Codec<Native.Optional<T>> {\n        val type = Named(\"Optional\", element.type())\n        return schema.codec(\n            type,\n            bits,\n            symbols,\n            { value ->\n                val payload = when (value) {\n                    is Native.Optional.Undefined -> Runtime.Presence(false, null)\n                    is Native.Optional.Present -> {\n                        Runtime.Presence(\n                            true, LawSpecSchema.encodeField(element, value.value, \"present\"),\n                        )\n                    }\n                }\n                Runtime.Value(LawSpecSchema.key(type), payload)\n            },\n            { value ->\n                val payload = value.data() as Runtime.Presence\n                if (payload.present()) {\n                    Native.Optional.Present(element.decode(payload.value()))\n                } else {\n                    Native.Optional.Undefined()\n                }\n            },\n        )\n    }\n}\n"
runtimeSource "kotlin-data-strategies" = "package lawspec.testing\n\nimport io.kotest.property.Arb\nimport io.kotest.property.RTree\nimport io.kotest.property.RandomSource\nimport io.kotest.property.Sample\nimport io.kotest.property.arbitrary.bind\nimport io.kotest.property.arbitrary.constant\nimport io.kotest.property.arbitrary.int\nimport io.kotest.property.arbitrary.map\nimport io.kotest.property.filter\nimport lawspec.runtime.LawSpecRuntime.Data\nimport lawspec.runtime.LawSpecRuntime.Presence\nimport lawspec.runtime.LawSpecRuntime.Value\nimport lawspec.runtime.LawSpecSchema\nimport lawspec.runtime.LawSpecSchema.Named\n\n/**\n * Native Kotest generation and shrinking for instantiated Core data schemas.\n *\n * Generated tests run in Kotest, the framework Kotlin developers already use, so failures shrink\n * and report as they expect; the arbitraries are built from Kotest's own so its shrinker reduces\n * counterexamples and shrinking stays within the declared domain.\n * ref:DEC-native-property-frameworks ref:kotest ref:DEC-shrink-within-domain\n */\nobject LawSpecKotlinStrategies {\n    fun generator(\n        schema: LawSpecSchema,\n        type: Named,\n        bits: Int,\n        budget: Int,\n        scalar: (String) -> Arb<Value>,\n    ): Arb<Value> {\n        require(!schema.hasContracts()) { \"constructor contracts require checked generation\" }\n        require(budget > 0) { \"structural node budget must be positive\" }\n        require(bits == 32 || bits == 64) { \"machineBits must be 32 or 64\" }\n        schema.isScalar(type) // Validate the entire type application before planning.\n        return requireNotNull(Builder(schema, bits, scalar).build(type, budget)) {\n            \"no value of ${LawSpecSchema.key(type)} within structural node budget $budget\"\n        }\n    }\n\n    data class Case(\n        val values: List<Value>,\n        val symbols: MutableMap<String, Any>,\n        val error: RuntimeException? = null,\n    ) {\n        fun requireValues(): List<Value> {\n            error?.let { throw it }\n            return values\n        }\n    }\n\n    fun cases(): Arb<Case> = object : Arb<Case>() {\n        override fun edgecase(rs: RandomSource): Case? = null\n\n        override fun sample(rs: RandomSource): Sample<Case> =\n            Sample(Case(emptyList(), mutableMapOf()))\n    }\n\n    fun filterCases(source: Arb<Case>, attempts: Int, predicate: (Case) -> Boolean): Arb<Case> {\n        require(attempts > 0) { \"maxAttempts must be positive\" }\n        return bounded(source, attempts, \"property inputs\") { it.error != null || predicate(it) }\n    }\n\n    data class Checked(val value: Value?, val error: RuntimeException?) {\n        fun requireValue(): Value {\n            error?.let { throw it }\n            return requireNotNull(value)\n        }\n    }\n\n    fun interface NativeFactory {\n        fun create(\n            schema: LawSpecSchema,\n            type: Named,\n            bits: Int,\n            symbols: MutableMap<String, Any>,\n            arguments: List<Arb<Value>>,\n        ): Arb<Value>\n    }\n\n    private class NativeFailure(type: Named, cause: RuntimeException) :\n        IllegalArgumentException(\n            \"native generator ${LawSpecSchema.key(type)}: ${cause.message}\", cause,\n        )\n\n    fun <T> nativeValues(codec: LawSpecSchema.Codec<T>, source: Arb<T>): Arb<Value> =\n        source.map { value ->\n            try {\n                codec.encode(value)\n            } catch (error: RuntimeException) {\n                throw NativeFailure(codec.type(), error)\n            }\n        }\n\n    fun <T> nativeArguments(codec: LawSpecSchema.Codec<T>, source: Arb<Value>): Arb<T> =\n        source.map { value ->\n            try {\n                codec.decode(value)\n            } catch (error: RuntimeException) {\n                throw NativeFailure(codec.type(), error)\n            }\n        }\n\n    // Retain the native tree, including failures encountered while evaluating a\n    // shrink node or enumerating its children. Report those in property callbacks.\n    private fun capture(source: Arb<Checked>): Arb<Checked> = object : Arb<Checked>() {\n        override fun edgecase(rs: RandomSource): Checked? = null\n\n        fun failure(error: NativeFailure) = RTree({ Checked(null, error) })\n\n        fun tree(source: RTree<Checked>): RTree<Checked> {\n            val value = try {\n                source.value()\n            } catch (error: NativeFailure) {\n                return failure(error)\n            }\n            return RTree({ value }, lazy {\n                try {\n                    source.children.value.map(::tree)\n                } catch (error: NativeFailure) {\n                    listOf(failure(error))\n                }\n            })\n        }\n\n        override fun sample(rs: RandomSource): Sample<Checked> {\n            val result = try {\n                tree(source.sample(rs).shrinks)\n            } catch (error: NativeFailure) {\n                failure(error)\n            }\n            return Sample(result.value(), result)\n        }\n    }\n\n    fun checkedGenerator(\n        schema: LawSpecSchema,\n        type: Named,\n        bits: Int,\n        budget: Int,\n        maxAttempts: Int,\n        symbols: MutableMap<String, Any>,\n        witnesses: List<Value>,\n        scalar: (String) -> Arb<Value>,\n    ): Arb<Checked> = checkedGenerator(\n        schema, type, bits, budget, maxAttempts, symbols, witnesses, emptyMap(), scalar,\n    )\n\n    fun checkedGenerator(\n        schema: LawSpecSchema,\n        type: Named,\n        bits: Int,\n        budget: Int,\n        maxAttempts: Int,\n        symbols: MutableMap<String, Any>,\n        witnesses: List<Value>,\n        factories: Map<String, NativeFactory>,\n        scalar: (String) -> Arb<Value>,\n    ): Arb<Checked> {\n        require(budget > 0) { \"structural node budget must be positive\" }\n        require(bits == 32 || bits == 64) { \"machineBits must be 32 or 64\" }\n        require(maxAttempts > 0) { \"maxAttempts must be positive\" }\n        schema.isScalar(type)\n        val builder = Builder(schema, bits, scalar, symbols, maxAttempts, factories)\n        witnesses.forEach { builder.addWitness(type, schema.validate(type, it, bits, symbols)) }\n        val source = requireNotNull(builder.build(type, budget)) {\n            \"no value of ${LawSpecSchema.key(type)} within structural node budget $budget\"\n        }\n        return capture(source.map { value ->\n            try {\n                Checked(schema.validate(type, value, bits, symbols), null)\n            } catch (error: RuntimeException) {\n                Checked(null, error)\n            }\n        })\n    }\n\n    private fun nodes(value: Value): Int = 1 + when (val data = value.data()) {\n        is Data -> data.fields().sumOf(::nodes)\n        is Presence -> if (data.present()) nodes(data.value()) else 0\n        is List<*> -> {\n            if (value.type().startsWith(\"List \")) {\n                data.sumOf { nodes(it as Value) }\n            } else {\n                0\n            }\n        }\n        else -> 0\n    }\n\n    private fun <T> bounded(\n        source: Arb<T>,\n        attempts: Int,\n        label: String,\n        accepted: (T) -> Boolean,\n    ): Arb<T> = object : Arb<T>() {\n        override fun edgecase(rs: RandomSource): T? = null\n\n        override fun sample(rs: RandomSource): Sample<T> {\n            repeat(attempts) {\n                val sample = source.sample(rs)\n                val tree = sample.shrinks.filter(accepted)\n                if (tree != null) return Sample(tree.value(), tree)\n            }\n            throw IllegalArgumentException(\n                \"constructor generation exhausted $attempts attempts for $label\",\n            )\n        }\n    }\n\n    private const val INDEX_SLACK = 16L\n    private const val INDEX_CHOICES = 6\n\n    /**\n     * Values whose structural index equals [target]. Each constructor carries its index term then\n     * its guards, in prefix notation over field indices (`f<i>`), literals (`c<n>`) and the natural\n     * operators. Reachability is a forward fixpoint over levels 0..target+slack, so a child may\n     * exceed its parent's index; the target is then solved backwards, and nothing is filtered away.\n     */\n    fun indexedGenerator(\n        schema: LawSpecSchema,\n        type: Named,\n        bits: Int,\n        budget: Int,\n        symbols: MutableMap<String, Any>,\n        target: Any,\n        equations: Map<String, List<String>>,\n        scalar: (String) -> Arb<Value>,\n    ): Arb<Checked> {\n        val k = when (target) {\n            is Value -> (target.data() as Number).toLong()\n            is Number -> target.toLong()\n            else -> throw IllegalArgumentException(\"index target must be a natural number\")\n        }\n        require(!schema.isScalar(type)) { \"indexed generation requires a data type\" }\n        val limit = maxOf(k, 0L) + INDEX_SLACK\n        val indexed = Indexed(schema, bits, budget, limit, equations, Builder(schema, bits, scalar))\n        indexed.explore(type)\n        // An open target (negative), or one drawn from earlier inputs that breaks their\n        // preconditions or names no value, generates from the smallest reachable indices; an index\n        // claim rejects a mismatch.\n        val levels = if ((type to k) in indexed.reach) {\n            listOf(k)\n        } else {\n            (0..limit).filter { (type to it) in indexed.reach }.take(INDEX_CHOICES)\n        }\n        require(levels.isNotEmpty()) { \"no value of ${LawSpecSchema.key(type)} has an index\" }\n        val source = if (levels.size == 1) {\n            indexed.generate(type, levels[0])\n        } else {\n            lawspecFlatMap(Arb.int(levels.indices)) { indexed.generate(type, levels[it]) }\n        }\n        return capture(source.map { value ->\n            try {\n                Checked(schema.validate(type, value, bits, symbols), null)\n            } catch (error: RuntimeException) {\n                Checked(null, error)\n            }\n        })\n    }\n\n    /** A prefix index term: kind is \"c\", \"f\" or an operator. */\n    private class IndexTerm(val kind: String, val value: Long, val left: IndexTerm?, val right: IndexTerm?) {\n        /** Natural index arithmetic; null when an operation has no natural value. */\n        fun evaluate(fields: Map<Int, Long>): Long? {\n            if (kind == \"c\") return value\n            if (kind == \"f\") return fields[value.toInt()]\n            val x = left!!.evaluate(fields) ?: return null\n            val y = right!!.evaluate(fields) ?: return null\n            val a = java.math.BigInteger.valueOf(x)\n            val b = java.math.BigInteger.valueOf(y)\n            val result = when (kind) {\n                \"+\" -> a.add(b)\n                \"-\" -> if (x >= y) a.subtract(b) else null\n                \"*\" -> a.multiply(b)\n                \"div\" -> if (y > 0) a.divide(b) else null\n                \"mod\" -> if (y > 0) a.mod(b) else null\n                else -> if (y <= 64) a.pow(y.toInt()) else null\n            } ?: return null\n            return if (result.bitLength() > 63) null else result.toLong()\n        }\n\n        fun fields(into: MutableList<Int>) {\n            if (kind == \"f\") {\n                if (value.toInt() !in into) into.add(value.toInt())\n            } else if (left != null) {\n                left.fields(into)\n                right!!.fields(into)\n            }\n        }\n\n        companion object {\n            private val OPERATORS = listOf(\"+\", \"-\", \"*\", \"div\", \"mod\", \"^\")\n\n            fun parse(tokens: List<String>, at: IntArray): IndexTerm {\n                require(at[0] < tokens.size) { \"malformed index term\" }\n                val token = tokens[at[0]++]\n                if (token.startsWith(\"c\") || token.startsWith(\"f\")) {\n                    return IndexTerm(token.substring(0, 1), token.substring(1).toLong(), null, null)\n                }\n                require(token in OPERATORS) { \"malformed index term\" }\n                val left = parse(tokens, at)\n                val right = parse(tokens, at)\n                return IndexTerm(token, 0, left, right)\n            }\n        }\n    }\n\n    private class IndexGuard(val relation: String, val left: IndexTerm, val right: IndexTerm) {\n        fun holds(fields: Map<Int, Long>): Boolean {\n            val x = left.evaluate(fields) ?: return false\n            val y = right.evaluate(fields) ?: return false\n            return if (relation == \"==\") x == y else x >= y\n        }\n    }\n\n    private class IndexEquation(val term: IndexTerm, val guards: List<IndexGuard>, val positions: List<Int>)\n\n    private class Indexed(\n        val schema: LawSpecSchema,\n        val bits: Int,\n        val budget: Int,\n        val limit: Long,\n        val equations: Map<String, List<String>>,\n        val builder: Builder,\n    ) {\n        val parsed = mutableMapOf<String, IndexEquation>()\n        val families = mutableListOf<Named>()\n        val reach = mutableSetOf<Pair<Named, Long>>()\n        val solutions = mutableMapOf<Triple<Named, String, Long>, List<Map<Int, Long>>>()\n        val cache = mutableMapOf<Pair<Named, Long>, Arb<Value>>()\n\n        fun equation(tag: String): IndexEquation = parsed.getOrPut(tag) {\n            val texts = requireNotNull(equations[tag]) { \"missing index equation for $tag\" }\n            require(texts.isNotEmpty()) { \"missing index equation for $tag\" }\n            val tokens = texts[0].split(\" \")\n            val at = intArrayOf(0)\n            val term = IndexTerm.parse(tokens, at)\n            require(at[0] == tokens.size) { \"malformed index term\" }\n            val positions = mutableListOf<Int>()\n            term.fields(positions)\n            val guards = texts.drop(1).map { text ->\n                val parts = text.split(\" \")\n                require(parts[0] == \"==\" || parts[0] == \">=\") { \"malformed index guard\" }\n                val position = intArrayOf(1)\n                val left = IndexTerm.parse(parts, position)\n                val right = IndexTerm.parse(parts, position)\n                left.fields(positions)\n                right.fields(positions)\n                IndexGuard(parts[0], left, right)\n            }\n            IndexEquation(term, guards, positions)\n        }\n\n        fun plainFields(type: Named, tag: String): Boolean {\n            val fields = schema.fields(type, tag)\n            val positions = equation(tag).positions\n            return fields.indices.all {\n                it in positions || builder.build(fields[it].type() as Named, budget) != null\n            }\n        }\n\n        // Every guard-satisfying assignment of reachable indices to the index fields.\n        fun assignments(type: Named, tag: String): List<Pair<Long, Map<Int, Long>>> {\n            val found = equation(tag)\n            val fields = schema.fields(type, tag)\n            val results = mutableListOf<Pair<Long, Map<Int, Long>>>()\n            fun extend(at: Int, current: MutableMap<Int, Long>) {\n                if (at == found.positions.size) {\n                    if (!found.guards.all { it.holds(current) }) return\n                    val value = found.term.evaluate(current) ?: return\n                    if (value <= limit) results.add(value to current.toMap())\n                    return\n                }\n                val position = found.positions[at]\n                val fieldType = fields[position].type() as Named\n                for (value in 0..limit) {\n                    if ((fieldType to value) in reach) {\n                        current[position] = value\n                        extend(at + 1, current)\n                    }\n                }\n                current.remove(position)\n            }\n            extend(0, mutableMapOf())\n            return results\n        }\n\n        fun explore(root: Named) {\n            val pending = mutableListOf(root)\n            while (pending.isNotEmpty()) {\n                val type = pending.removeAt(pending.size - 1)\n                if (type in families) continue\n                families.add(type)\n                for (tag in schema.constructors(type)) {\n                    val fields = schema.fields(type, tag)\n                    equation(tag).positions.forEach { pending.add(fields[it].type() as Named) }\n                }\n            }\n            do {\n                val next = mutableSetOf<Pair<Named, Long>>()\n                for (type in families) {\n                    for (tag in schema.constructors(type)) {\n                        if (!plainFields(type, tag)) continue\n                        assignments(type, tag).forEach { next.add(type to it.first) }\n                    }\n                }\n            } while (reach.addAll(next))\n        }\n\n        fun solve(type: Named, tag: String, k: Long): List<Map<Int, Long>> =\n            solutions.getOrPut(Triple(type, tag, k)) {\n                assignments(type, tag).filter { it.first == k }.map { it.second }\n            }\n\n        // Assignments are chosen by index, which shrinks toward the first.\n        fun generate(type: Named, k: Long): Arb<Value> {\n            cache[type to k]?.let { return it }\n            val variants = schema.constructors(type)\n                .filter { plainFields(type, it) && solve(type, it, k).isNotEmpty() }\n                .map { tag ->\n                    val fields = schema.fields(type, tag)\n                    val choices = solve(type, tag, k)\n                    lawspecFlatMap(Arb.int(choices.indices)) { choice ->\n                        val targets = choices[choice]\n                        val children = fields.mapIndexed { index, field ->\n                            val target = targets[index]\n                            if (target != null) {\n                                generate(field.type() as Named, target)\n                            } else {\n                                requireNotNull(builder.build(field.type() as Named, budget))\n                            }\n                        }\n                        children.fold(Arb.constant(emptyList<Value>())) { prior, child ->\n                            Arb.bind(prior, child) { values, value -> values + value }\n                        }.map { schema.construct(type, tag, it, bits) }\n                    }\n                }\n            require(variants.isNotEmpty()) {\n                \"no value of ${LawSpecSchema.key(type)} has index $k\"\n            }\n            val result = if (variants.size == 1) {\n                variants[0]\n            } else {\n                lawspecFlatMap(Arb.int(variants.indices)) { variants[it] }\n            }\n            cache[type to k] = result\n            return result\n        }\n    }\n\n    private data class Request(val type: Named, val budget: Int)\n\n    private class Builder(\n        val schema: LawSpecSchema,\n        val bits: Int,\n        val scalar: (String) -> Arb<Value>,\n        val symbols: MutableMap<String, Any>? = null,\n        val maxAttempts: Int = 100,\n        val factories: Map<String, NativeFactory> = emptyMap(),\n    ) {\n        val witnesses = mutableMapOf<Named, MutableList<Value>>()\n        val cache = mutableMapOf<Request, Arb<Value>?>()\n\n        fun addWitness(type: Named, value: Value) {\n            witnesses.getOrPut(type) { mutableListOf() }.add(value)\n            when {\n                schema.isScalar(type) -> Unit\n                type.name() == \"List\" -> {\n                    (value.data() as List<*>).forEach {\n                        addWitness(type.arguments()[0] as Named, it as Value)\n                    }\n                }\n                type.name() in listOf(\"Nullable\", \"Optional\") -> {\n                    val presence = value.data() as Presence\n                    if (presence.present()) {\n                        addWitness(type.arguments()[0] as Named, presence.value())\n                    }\n                }\n                else -> {\n                    val data = value.data() as Data\n                    schema.fieldsOf(type, data.tag(), data.fields()).forEachIndexed { index, field ->\n                        addWitness(field.type() as Named, data.fields()[index])\n                    }\n                }\n            }\n        }\n\n        fun minimum(type: Named, limit: Int): Int? =\n          (1..limit).firstOrNull { build(type, it) != null }\n\n        fun allocation(fields: List<LawSpecSchema.Field>, available: Int): List<Int>? {\n            var remaining = available\n            val minima = fields.map { field ->\n                val cost = minimum(field.type() as Named, remaining) ?: return null\n                remaining -= cost\n                cost\n            }\n            return minima.mapIndexed { index, cost ->\n                cost + remaining / minima.size + if (index < remaining % minima.size) 1 else 0\n            }\n        }\n\n        fun build(type: Named, available: Int): Arb<Value>? {\n            if (available < 1) return null\n            val request = Request(type, available)\n            if (cache.containsKey(request)) return cache[request]\n            factories[type.name()]?.let { factory ->\n                val arguments = type.arguments().map {\n                    build(it as Named, available) ?: object : Arb<Value>() {\n                        // A phantom parameter can be uninhabited. Fail only if\n                        // its factory actually asks this arbitrary for a value.\n                        override fun edgecase(rs: RandomSource): Value? = null\n                        override fun sample(rs: RandomSource): Sample<Value> =\n                            error(\"no native generator argument for ${LawSpecSchema.key(it)} within node budget $available\")\n                    }\n                }\n                val context = requireNotNull(symbols)\n                val result = factory.create(schema, type, bits, context, arguments).map { value ->\n                    try {\n                        schema.validate(type, value, bits, context)\n                    } catch (error: RuntimeException) {\n                        throw NativeFailure(type, error)\n                    }\n                }\n                cache[request] = result\n                return result\n            }\n            var result = when {\n                schema.isScalar(type) -> scalar(type.name()).map { schema.validate(type, it, bits) }\n                type.name() == \"List\" -> list(type, available)\n                type.name() in listOf(\"Nullable\", \"Optional\") -> presence(type, available)\n                else -> {\n                    // A field-only existential takes each type of the witness pool.\n                    choice(schema.constructors(type).flatMap { tag ->\n                      schema.instances(type, tag).mapNotNull { instance ->\n                        val fields = instance.fields()\n                        val witnessValues = instance.keys().map { LawSpecSchema.witnessText(it) }\n                        val costs = allocation(fields, available - 1) ?: return@mapNotNull null\n                        val children = fields.mapIndexed { index, field ->\n                            requireNotNull(build(field.type() as Named, costs[index]))\n                        }\n                        val product =\n                            children.fold(Arb.constant(emptyList<Value>())) { prior, child ->\n                                Arb.bind(prior, child) { values, value -> values + value }\n                            }\n                        product.map { it + witnessValues }.map {\n                            val value = if (symbols == null) {\n                                schema.construct(type, tag, it, bits)\n                            } else {\n                                Value(LawSpecSchema.key(type), Data(tag, it))\n                            }\n                            // Generated collections are canonicalised rather than filtered.\n                            if (LawSpecSchema.canonicalCollection(type.name())) LawSpecSchema.canonical(value) else value\n                        }\n                      }\n                    })\n                }\n            }\n            if (result != null && symbols != null) {\n                val seeds = witnesses[type].orEmpty().filter { nodes(it) <= available }\n                if (seeds.isNotEmpty()) {\n                    val sample = Arb.int(seeds.indices).map { seeds[it] }\n                    result = lawspecChoice(result, sample)\n                }\n                result = bounded(result, maxAttempts, LawSpecSchema.key(type)) { value ->\n                    try {\n                        schema.check(type, value, bits, symbols) is LawSpecSchema.Accepted\n                    } catch (error: RuntimeException) {\n                        // Keep evaluator errors for the outer checked result to report.\n                        true\n                    }\n                }\n            }\n            cache[request] = result\n            return result\n        }\n\n        fun list(type: Named, available: Int): Arb<Value> {\n            val element = type.arguments()[0] as Named\n            val remaining = available - 1\n            val cost = minimum(element, remaining)\n            val maximum = if (cost == null) 0 else remaining / cost\n            // Plan before sampling: callbacks only select immutable native arbitraries.\n            val sizes = (0..maximum).map { length ->\n                if (length == 0) {\n                    Arb.constant(Value(LawSpecSchema.key(type), emptyList<Value>()))\n                } else {\n                    lawspecList(requireNotNull(build(element, remaining / length)), length..length)\n                        .map { Value(LawSpecSchema.key(type), it) }\n                }\n            }\n            return lawspecFlatMap(Arb.int(0..maximum)) { sizes[it] }\n        }\n\n        fun presence(type: Named, available: Int): Arb<Value> {\n            val absent = Arb.constant(Value(LawSpecSchema.key(type), Presence(false, null)))\n            val child = build(type.arguments()[0] as Named, available - 1) ?: return absent\n            val present = child.map { Value(LawSpecSchema.key(type), Presence(true, it)) }\n            return requireNotNull(choice(listOf(absent, present)))\n        }\n\n        fun choice(alternatives: List<Arb<Value>>): Arb<Value>? = when (alternatives.size) {\n            0 -> null\n            1 -> alternatives[0]\n            else -> lawspecFlatMap(Arb.int(alternatives.indices)) { alternatives[it] }\n        }\n    }\n}\n"
runtimeSource "python-harness" = "# The harness plane at run time (see docs/reference/language/harness.md):\n# how a law's tests run, never what the law means. Generated tests call it\n# for strategies (frequency, such that, bind), adequacy (cover, classify,\n# label), run metadata (skip, known failing, timeout, repeat, retry flaky,\n# order random) and benchmarks.\n#\n# Statistics go to standard output, and, when LAWSPEC_STATS names a\n# directory, to one JSON file per test there, which lawspec test reads.\nimport json\nimport os\nimport random\nimport threading\nimport time\nimport warnings\n\nfrom hypothesis import strategies as st\n\n_cases = {}\n\n\nclass HarnessError(AssertionError):\n    \"\"\"A harness requirement failed: a strategy or an adequacy check.\"\"\"\n\n\ndef _record(name, entry):\n    directory = os.environ.get(\"LAWSPEC_STATS\")\n    if not directory:\n        return\n    os.makedirs(directory, exist_ok=True)\n    safe = \"\".join(c if c.isalnum() or c in \"-_\" else \"_\" for c in name)\n    with open(os.path.join(directory, safe + \".json\"), \"w\", encoding=\"utf-8\") as out:\n        json.dump(entry, out, sort_keys=True)\n\n\n# Strategies. Each draws through Hypothesis, so failures shrink.\n\n# A choice among n: a wide integer, reduced, so every example is new to\n# Hypothesis (which never repeats one) and the weights hold; it still shrinks\n# toward the first choice.\ndef _choice(data, n):\n    return data.draw(st.integers(min_value=0, max_value=2 ** 32 - 1)) % n\n\n\ndef draw_frequency(data, alternatives):\n    total = sum(weight for weight, _ in alternatives)\n    pick = _choice(data, total)\n    for weight, draw in alternatives:\n        if pick < weight:\n            return draw()\n        pick -= weight\n    return alternatives[-1][1]()\n\n\ndef draw_one_of(data, values):\n    return values[_choice(data, len(values))]()\n\n\ndef draw_such_that(draw, predicate, limit, strategy):\n    for _ in range(limit + 1):\n        value = draw()\n        if predicate(value):\n            return value\n    raise HarnessError(\n        f\"the strategy {strategy} discarded more than {limit} values; \"\n        \"draw closer to what `such that` keeps, or allow more discards\")\n\n\ndef check_drawn(strategy, name, holds, value):\n    \"\"\"A drawn value must satisfy its input's refinements: a strategy may\n    only produce values the law is about.\"\"\"\n    if not holds(value):\n        raise HarnessError(\n            f\"the strategy {strategy} produced {value!r} for {name}, \"\n            \"which is outside the input's refinement; a strategy may only \"\n            \"produce values of its type\")\n    return value\n\n\n# Adequacy: what the generated cases covered.\n\ndef target(score, law):\n    \"\"\"target maximize: steer generation toward cases that score higher.\"\"\"\n    import hypothesis\n    hypothesis.target(float(score), label=law)\n\n\ndef observe(law, covers=(), classes=(), labels=()):\n    stats = _cases.setdefault(law, {\"cases\": 0, \"cover\": {}, \"classes\": {}, \"labels\": {}})\n    stats[\"cases\"] += 1\n    for label, holds in covers:\n        stats[\"cover\"][label] = stats[\"cover\"].get(label, 0) + (1 if holds else 0)\n    for label, holds in classes:\n        if holds:\n            stats[\"classes\"][label] = stats[\"classes\"].get(label, 0) + 1\n    for value in labels:\n        key = str(value)\n        stats[\"labels\"][key] = stats[\"labels\"].get(key, 0) + 1\n\n\ndef _adequacy(law, covers):\n    stats = _cases.pop(law, {\"cases\": 0, \"cover\": {}, \"classes\": {}, \"labels\": {}})\n    cases = stats[\"cases\"]\n    results = []\n    for percent, label in covers:\n        hits = stats[\"cover\"].get(label, 0)\n        observed = 100.0 * hits / cases if cases else 0.0\n        results.append({\"label\": label, \"required\": percent, \"observed\": round(observed, 2), \"met\": cases > 0 and observed >= percent})\n    report = {\"law\": law, \"cases\": cases, \"cover\": results,\n              \"classes\": stats[\"classes\"], \"labels\": stats[\"labels\"]}\n    lines = [f\"{law}: {cases} generated case(s)\"]\n    for r in results:\n        lines.append(f\"  cover {r['required']}% \\\"{r['label']}\\\": {r['observed']}%\" + (\"\" if r[\"met\"] else \" (not met)\"))\n    for label, count in sorted(stats[\"classes\"].items()):\n        lines.append(f\"  {label}: {100.0 * count / cases if cases else 0:.1f}%\")\n    for label, count in sorted(stats[\"labels\"].items(), key=lambda kv: -kv[1]):\n        lines.append(f\"  label {label}: {100.0 * count / cases if cases else 0:.1f}%\")\n    if len(lines) > 1:\n        print(\"\\n\".join(lines))\n    return report\n\n\n# Run metadata.\n\ndef _with_timeout(test, milliseconds, law):\n    if milliseconds is None:\n        return test()\n    outcome = {}\n\n    def run():\n        try:\n            test()\n        except BaseException as error:  # noqa: BLE001 - reported below\n            outcome[\"error\"] = error\n    worker = threading.Thread(target=run, daemon=True)\n    worker.start()\n    worker.join(milliseconds / 1000)\n    if worker.is_alive():\n        raise HarnessError(f\"{law} took longer than its timeout of {milliseconds} ms\")\n    if \"error\" in outcome:\n        raise outcome[\"error\"]\n\n\ndef run(law, name, test, timeout=None, repeat=1, retries=0, covers=(), observed=False):\n    \"\"\"Run one generated test of a law under its harness settings.\"\"\"\n    attempts = 0\n    flaky = False\n    while True:\n        attempts += 1\n        try:\n            for _ in range(repeat):\n                _cases.pop(law, None)\n                _with_timeout(test, timeout, law)\n                report = _adequacy(law, covers) if observed else None\n                if report is not None:\n                    unmet = [r for r in report[\"cover\"] if not r[\"met\"]]\n                    if unmet:\n                        _record(name, {**report, \"test\": name, \"outcome\": \"failed\"})\n                        raise HarnessError(\"; \".join(\n                            f\"{law}: cover {r['required']}% \\\"{r['label']}\\\" was not met \"\n                            f\"({r['observed']}% of {report['cases']} generated cases)\" for r in unmet))\n            break\n        except HarnessError:\n            raise\n        except BaseException:\n            if attempts > retries:\n                _record(name, {\"law\": law, \"test\": name, \"outcome\": \"failed\", \"attempts\": attempts})\n                raise\n            flaky = True\n    entry = {\"law\": law, \"test\": name, \"outcome\": \"flaky\" if flaky else \"passed\", \"attempts\": attempts}\n    if observed and report is not None:\n        entry.update(report)\n    _record(name, entry)\n    if flaky:\n        warnings.warn(f\"{law} is flaky: it failed, then passed on attempt {attempts}\")\n\n\ndef skip(law, reason):\n    import pytest\n    _record(law, {\"law\": law, \"outcome\": \"skipped\", \"reason\": reason})\n    pytest.skip(f\"{law}: {reason}\")\n\n\ndef known_failing(law, name, reason, tests):\n    \"\"\"A known-failing law's tests must fail. One that passes is reported:\n    the harness should no longer say it is known to fail.\"\"\"\n    import pytest\n    for test in tests:\n        try:\n            test()\n        except BaseException as error:  # noqa: BLE001 - the expected failure\n            _record(name, {\"law\": law, \"test\": name, \"outcome\": \"known-failing\", \"reason\": reason})\n            pytest.xfail(f\"{law} is known to fail ({reason}): {type(error).__name__}\")\n    _record(name, {\"law\": law, \"test\": name, \"outcome\": \"known-failing-passed\", \"reason\": reason})\n    raise HarnessError(\n        f\"{law} is marked known failing ({reason}), but it passes; \"\n        \"remove `known failing` from its harness\")\n\n\n# Scheduling: the harness driver owns the order and parallelism of a unit's\n# tests; pytest hosts and reports them. A test module whose harness says\n# `order random` sets _LAWSPEC_ORDER_RANDOM, and `parallel` _LAWSPEC_PARALLEL;\n# the conftest beside the tests imports these hooks.\n\ndef _order_seed():\n    global _ORDER_SEED\n    if _ORDER_SEED is None:\n        given = os.environ.get(\"LAWSPEC_SEED\")\n        _ORDER_SEED = int(given) if given else random.randrange(2 ** 31)\n    return _ORDER_SEED\n\n\n_ORDER_SEED = None\n_shuffled_modules = []\n_parallel_items = {}\n_parallel_runs = {}\n_parallel_lock = threading.Lock()\n\n\ndef _module_flag(item, name):\n    module = getattr(item, \"module\", None)\n    return bool(getattr(module, name, False))\n\n\ndef pytest_collection_modifyitems(session, config, items):\n    \"\"\"order random: each such module's tests, in their places among the\n    others, in an order the run's seed chooses (LAWSPEC_SEED replays it).\n    parallel: the selected tests of each such module, for the driver.\"\"\"\n    by_module = {}\n    for index, item in enumerate(items):\n        if _module_flag(item, \"_LAWSPEC_ORDER_RANDOM\"):\n            by_module.setdefault(item.module.__name__, []).append(index)\n    for module, positions in sorted(by_module.items()):\n        chosen = [items[i] for i in positions]\n        random.Random(f\"{_order_seed()}:{module}\").shuffle(chosen)\n        for position, item in zip(positions, chosen):\n            items[position] = item\n        _shuffled_modules.append(module)\n    parallel = sorted({item.module.__name__ for item in items if _module_flag(item, \"_LAWSPEC_PARALLEL\")})\n    if _xdist(config):\n        for module in parallel:\n            _parallelism(module, \"processes (pytest-xdist)\", config.option.numprocesses)\n        return\n    for item in items:\n        if _module_flag(item, \"_LAWSPEC_PARALLEL\"):\n            _parallel_items.setdefault(item.module.__name__, []).append(item)\n\n\ndef _xdist(config):\n    return config.pluginmanager.hasplugin(\"xdist\") and bool(getattr(config.option, \"numprocesses\", None))\n\n\ndef _parallelism(module, mode, workers):\n    _record(\"parallel \" + module, {\"parallel\": module, \"mode\": mode, \"workers\": workers})\n    print(f\"{module} runs in parallel: {mode}, {workers} worker(s)\")\n\n\ndef pytest_pyfunc_call(pyfuncitem):\n    \"\"\"parallel without pytest-xdist: the first test of a module starts all\n    its selected tests on a thread pool, in their (perhaps shuffled) order;\n    each test then waits for its own result. Threads run truly in parallel\n    on free-threaded CPython (3.13t and later); otherwise they interleave\n    (sleeps and I/O overlap, computation takes turns).\"\"\"\n    module = pyfuncitem.module.__name__ if getattr(pyfuncitem, \"module\", None) else None\n    group = _parallel_items.get(module)\n    if not group or pyfuncitem not in group:\n        return None\n    import concurrent.futures\n    import sys\n    with _parallel_lock:\n        runs = _parallel_runs.get(module)\n        if runs is None:\n            pool = concurrent.futures.ThreadPoolExecutor(max_workers=len(group))\n            runs = {item.nodeid: pool.submit(item.obj) for item in group}\n            _parallel_runs[module] = runs\n            free = hasattr(sys, \"_is_gil_enabled\") and not sys._is_gil_enabled()\n            _parallelism(module, \"threads (free-threaded)\" if free else\n                         \"threads, interleaved under the GIL (free-threaded CPython runs them truly in parallel)\",\n                         len(group))\n    runs[pyfuncitem.nodeid].result()\n    return True\n\n\ndef pytest_terminal_summary(terminalreporter, exitstatus, config):\n    if _shuffled_modules:\n        terminalreporter.write_line(\n            f\"order random seed {_order_seed()}: LAWSPEC_SEED={_order_seed()} replays this order\"\n            + (\"\" if exitstatus == 0 else \" (the run failed)\"))\n\n\ndef benchmark(name, body, budget=0.2, limit=100000):\n    \"\"\"Measured, never asserted: the mean and fastest time of body.\"\"\"\n    times = []\n    started = time.perf_counter()\n    while len(times) < limit and (time.perf_counter() - started < budget or len(times) < 3):\n        before = time.perf_counter()\n        body()\n        times.append(time.perf_counter() - before)\n    mean = sum(times) / len(times)\n    entry = {\"benchmark\": name, \"iterations\": len(times), \"mean_ns\": int(mean * 1e9), \"min_ns\": int(min(times) * 1e9)}\n    print(f\"benchmark {name}: {len(times)} iteration(s), mean {mean * 1e6:.2f} us, fastest {min(times) * 1e6:.2f} us\")\n    _record(\"benchmark \" + name, entry)\n"
runtimeSource "web-harness" = "// The harness plane at run time (see docs/reference/language/harness.md):\n// how a law's tests run, never what the law means. Generated tests call it\n// for strategies' refinement checks, adequacy (cover, classify,\n// label), run metadata (skip, known failing, timeout, repeat, retry flaky,\n// order random) and benchmarks.\n//\n// Statistics go to standard output, and, when LAWSPEC_STATS names a\n// directory, to one JSON file per test there, which lawspec test reads.\nimport { mkdirSync, writeFileSync } from 'node:fs';\nimport { join } from 'node:path';\n\nexport class HarnessError extends Error {}\n\nfunction record(name, entry) {\n  const directory = globalThis.process?.env?.LAWSPEC_STATS;\n  if (!directory) return;\n  mkdirSync(directory, { recursive: true });\n  const safe = name.replace(/[^A-Za-z0-9_-]/g, '_');\n  writeFileSync(join(directory, `${safe}.json`), JSON.stringify(entry));\n}\n\n// Strategies are composed into fast-check arbitraries by the generated test.\n// A drawn value must satisfy its input's refinements: a strategy may only\n// produce values the law is about.\nexport function checkDrawn(strategy, name, holds, value) {\n  if (!holds(value))\n    throw new HarnessError(`the strategy ${strategy} produced ${show(value)} for ${name}, ` +\n      \"which is outside the input's refinement; a strategy may only produce values of its type\");\n  return value;\n}\n\nconst show = (value) => {\n  try { return JSON.stringify(value, (_, v) => typeof v === 'bigint' ? v.toString() : v) ?? String(value); }\n  catch { return String(value); }\n};\n\n// Adequacy: what the generated cases covered.\nconst cases = new Map();\nconst best = new Map();\n\nexport function observe(law, { covers = [], classes = [], labels = [] } = {}) {\n  const stats = cases.get(law) ?? { cases: 0, cover: {}, classes: {}, labels: {} };\n  cases.set(law, stats);\n  stats.cases += 1;\n  for (const [label, holds] of covers) stats.cover[label] = (stats.cover[label] ?? 0) + (holds ? 1 : 0);\n  for (const [label, holds] of classes) if (holds) stats.classes[label] = (stats.classes[label] ?? 0) + 1;\n  for (const value of labels) stats.labels[String(value)] = (stats.labels[String(value)] ?? 0) + 1;\n}\n\n// target maximize: fast-check has no targeted search, so the best score is\n// reported with the law's statistics.\nexport function target(score, law) {\n  const value = Number(score);\n  if (!best.has(law) || value > best.get(law)) best.set(law, value);\n}\n\nfunction adequacy(law, covers) {\n  const stats = cases.get(law) ?? { cases: 0, cover: {}, classes: {}, labels: {} };\n  cases.delete(law);\n  const n = stats.cases;\n  const results = covers.map(([percent, label]) => {\n    const observed = n ? Math.round(10000 * (stats.cover[label] ?? 0) / n) / 100 : 0;\n    return { label, required: percent, observed, met: n > 0 && observed >= percent };\n  });\n  const report = { law, cases: n, cover: results, classes: stats.classes, labels: stats.labels,\n    ...(best.has(law) ? { best: best.get(law) } : {}) };\n  best.delete(law);\n  const lines = [`${law}: ${n} generated case(s)`];\n  for (const r of results) lines.push(`  cover ${r.required}% \"${r.label}\": ${r.observed}%${r.met ? '' : ' (not met)'}`);\n  for (const [label, count] of Object.entries(stats.classes)) lines.push(`  ${label}: ${(100 * count / (n || 1)).toFixed(1)}%`);\n  for (const [label, count] of Object.entries(stats.labels)) lines.push(`  label ${label}: ${(100 * count / (n || 1)).toFixed(1)}%`);\n  if (report.best !== undefined) lines.push(`  best target score: ${report.best}`);\n  if (lines.length > 1) console.log(lines.join('\\n'));\n  return report;\n}\n\nasync function withTimeout(test, milliseconds, law) {\n  if (milliseconds === undefined) return test();\n  let timer;\n  const timeout = new Promise((_, reject) => {\n    timer = setTimeout(() => reject(new HarnessError(`${law} took longer than its timeout of ${milliseconds} ms`)), milliseconds);\n  });\n  try { return await Promise.race([Promise.resolve().then(test), timeout]); }\n  finally { clearTimeout(timer); }\n}\n\n// Run one generated test of a law under its harness settings.\nexport async function run(law, name, test, { timeout, repeat = 1, retries = 0, covers = [], observed = false } = {}) {\n  let attempts = 0;\n  let flaky = false;\n  let report = null;\n  for (;;) {\n    attempts += 1;\n    try {\n      for (let i = 0; i < repeat; i++) {\n        cases.delete(law);\n        await withTimeout(test, timeout, law);\n        report = observed ? adequacy(law, covers) : null;\n        const unmet = report ? report.cover.filter((r) => !r.met) : [];\n        if (unmet.length) {\n          record(name, { ...report, test: name, outcome: 'failed' });\n          throw new HarnessError(unmet.map((r) =>\n            `${law}: cover ${r.required}% \"${r.label}\" was not met (${r.observed}% of ${report.cases} generated cases)`).join('; '));\n        }\n      }\n      break;\n    } catch (error) {\n      if (error instanceof HarnessError || attempts > retries) {\n        if (!(error instanceof HarnessError)) record(name, { law, test: name, outcome: 'failed', attempts });\n        throw error;\n      }\n      flaky = true;\n    }\n  }\n  record(name, { law, test: name, outcome: flaky ? 'flaky' : 'passed', attempts, ...(report ?? {}) });\n  if (flaky) console.warn(`${law} is flaky: it failed, then passed on attempt ${attempts}`);\n}\n\nexport function skip(law, reason) {\n  record(law, { law, outcome: 'skipped', reason });\n}\n\n// A known-failing law's tests must fail. One that passes is reported: the\n// harness should no longer say it is known to fail.\nexport async function knownFailing(law, name, reason, tests) {\n  for (const test of tests) {\n    try { await test(); }\n    catch (error) {\n      record(name, { law, test: name, outcome: 'known-failing', reason });\n      console.log(`${law} is known to fail (${reason}): ${error?.message?.split('\\n')[0] ?? error}`);\n      return;\n    }\n  }\n  record(name, { law, test: name, outcome: 'known-failing-passed', reason });\n  throw new HarnessError(`${law} is marked known failing (${reason}), but it passes; remove \\`known failing\\` from its harness`);\n}\n\n// order random: the tests in an order chosen by the run's seed\n// (LAWSPEC_SEED, or one chosen here), printed so the order can be replayed.\nexport function shuffled(items, unit = 'the unit') {\n  const given = globalThis.process?.env?.LAWSPEC_SEED;\n  const seed = given === undefined ? Math.floor(Math.random() * 2 ** 31) : Number(given) | 0;\n  console.log(`order random seed ${seed} (${unit}): LAWSPEC_SEED=${seed} replays this order`);\n  let state = seed;\n  const next = () => {\n    state = (state + 0x6d2b79f5) | 0;\n    let t = Math.imul(state ^ (state >>> 15), 1 | state);\n    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n  };\n  const result = [...items];\n  for (let i = result.length - 1; i > 0; i--) {\n    const j = Math.floor(next() * (i + 1));\n    [result[i], result[j]] = [result[j], result[i]];\n  }\n  return result;\n}\n\n// parallel: how the unit's tests ran at the same time. node:test runs them\n// concurrently in one process: async laws overlap, synchronous ones take\n// turns on the event loop.\nexport function parallelism(unit) {\n  const workers = globalThis.navigator?.hardwareConcurrency ?? 1;\n  const mode = 'in-process concurrency (async laws overlap; synchronous laws take turns)';\n  record(`parallel ${unit}`, { parallel: unit, mode, workers });\n  console.log(`${unit} runs in parallel: ${mode}`);\n}\n\n// Measured, never asserted: the mean and fastest time of body.\nexport async function benchmark(name, body, budget = 200, limit = 100000) {\n  const times = [];\n  const started = performance.now();\n  while (times.length < limit && (performance.now() - started < budget || times.length < 3)) {\n    const before = performance.now();\n    await body();\n    times.push(performance.now() - before);\n  }\n  const mean = times.reduce((a, b) => a + b, 0) / times.length;\n  const fastest = Math.min(...times);\n  console.log(`benchmark ${name}: ${times.length} iteration(s), mean ${(mean * 1000).toFixed(2)} us, fastest ${(fastest * 1000).toFixed(2)} us`);\n  record(`benchmark ${name}`, { benchmark: name, iterations: times.length, mean_ns: Math.round(mean * 1e6), min_ns: Math.round(fastest * 1e6) });\n}\n"
runtimeSource "go-harness" = "// The harness plane at run time (see docs/reference/language/harness.md):\n// how a law's tests run, never what the law means. Generated tests call it\n// for strategies (frequency, one of, such that), adequacy (cover, classify,\n// label), run metadata (skip, known failing, timeout, repeat, retry flaky)\n// and benchmarks.\n//\n// A test the harness runs is a function of rapid.TB, so it can run under a\n// recorder: a failure stops it (FailNow panics) and is reported once the\n// harness has decided, for instance after a retry. Statistics go to the\n// test log, and, when LAWSPEC_STATS names a directory, to one JSON file per\n// test there, which lawspec test reads.\npackage RUNTIME_PACKAGE\n\nimport (\n\t\"encoding/json\"\n\t\"flag\"\n\t\"fmt\"\n\t\"math\"\n\t\"os\"\n\t\"path/filepath\"\n\t\"runtime\"\n\t\"sort\"\n\t\"strings\"\n\t\"sync\"\n\t\"testing\"\n\t\"time\"\n\n\t\"pgregory.net/rapid\"\n)\n\ntype lsHarnessFailure struct{ message string }\n\nfunc (f lsHarnessFailure) Error() string { return f.message }\n\nfunc lsHarnessRecord(name string, entry map[string]any) {\n\tdirectory := os.Getenv(\"LAWSPEC_STATS\")\n\tif directory == \"\" {\n\t\treturn\n\t}\n\t_ = os.MkdirAll(directory, 0o755)\n\tsafe := strings.Map(func(r rune) rune {\n\t\tif r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9' || r == '-' || r == '_' {\n\t\t\treturn r\n\t\t}\n\t\treturn '_'\n\t}, name)\n\tif bytes, err := json.Marshal(entry); err == nil {\n\t\t_ = os.WriteFile(filepath.Join(directory, safe+\".json\"), bytes, 0o644)\n\t}\n}\n\n// Strategies, drawn through rapid so failures shrink.\n\ntype lsHarnessWeighted struct {\n\tweight int\n\tdraw   func() LawSpecValue\n}\n\n// A choice among n: a wide draw, reduced, so the weights hold.\nfunc lsHarnessChoose(t *rapid.T, n int) int {\n\treturn int(rapid.Uint32().Draw(t, \"choice\") % uint32(n))\n}\n\nfunc lsHarnessFrequency(t *rapid.T, alternatives []lsHarnessWeighted) LawSpecValue {\n\ttotal := 0\n\tfor _, a := range alternatives {\n\t\ttotal += a.weight\n\t}\n\tpick := lsHarnessChoose(t, total)\n\tfor _, a := range alternatives {\n\t\tif pick < a.weight {\n\t\t\treturn a.draw()\n\t\t}\n\t\tpick -= a.weight\n\t}\n\treturn alternatives[len(alternatives)-1].draw()\n}\n\nfunc lsHarnessOneOf(t *rapid.T, values []func() LawSpecValue) LawSpecValue {\n\treturn values[lsHarnessChoose(t, len(values))]()\n}\n\nfunc lsHarnessSuchThat(draw func() LawSpecValue, predicate func(LawSpecValue) bool, limit int, strategy string) LawSpecValue {\n\tfor i := 0; i <= limit; i++ {\n\t\tif value := draw(); predicate(value) {\n\t\t\treturn value\n\t\t}\n\t}\n\tpanic(lsHarnessFailure{fmt.Sprintf(\"the strategy %s discarded more than %d values; draw closer to what `such that` keeps, or allow more discards\", strategy, limit)})\n}\n\n// A drawn value must satisfy its input's refinements: a strategy may only\n// produce values the law is about.\nfunc lsHarnessCheckDrawn(strategy, name string, holds func(LawSpecValue) bool, value LawSpecValue) LawSpecValue {\n\tif !holds(value) {\n\t\tpanic(lsHarnessFailure{fmt.Sprintf(\"the strategy %s produced %v for %s, which is outside the input's refinement; a strategy may only produce values of its type\", strategy, value.Data, name)})\n\t}\n\treturn value\n}\n\n// Adequacy: what the generated cases covered.\n\ntype lsHarnessStats struct {\n\tcases   int\n\tcover   map[string]int\n\tclasses map[string]int\n\tlabels  map[string]int\n\tbest    *float64\n}\n\nvar lsHarnessCases = struct {\n\tsync.Mutex\n\tlaws map[string]*lsHarnessStats\n}{laws: map[string]*lsHarnessStats{}}\n\ntype lsHarnessPair struct {\n\tlabel string\n\tholds bool\n}\n\ntype lsHarnessCover struct {\n\tpercent int\n\tlabel   string\n}\n\nfunc lsHarnessStatsOf(law string) *lsHarnessStats {\n\tstats, ok := lsHarnessCases.laws[law]\n\tif !ok {\n\t\tstats = &lsHarnessStats{cover: map[string]int{}, classes: map[string]int{}, labels: map[string]int{}}\n\t\tlsHarnessCases.laws[law] = stats\n\t}\n\treturn stats\n}\n\nfunc lsHarnessObserve(law string, covers, classes []lsHarnessPair, labels []LawSpecValue) {\n\tlsHarnessCases.Lock()\n\tdefer lsHarnessCases.Unlock()\n\tstats := lsHarnessStatsOf(law)\n\tstats.cases++\n\tfor _, c := range covers {\n\t\tif c.holds {\n\t\t\tstats.cover[c.label]++\n\t\t}\n\t}\n\tfor _, c := range classes {\n\t\tif c.holds {\n\t\t\tstats.classes[c.label]++\n\t\t}\n\t}\n\tfor _, l := range labels {\n\t\tstats.labels[fmt.Sprint(lsToNative(\"Text\", l, 64))]++\n\t}\n}\n\n// target maximize: rapid has no targeted search, so the best score is\n// reported with the law's statistics.\nfunc lsHarnessTarget(score LawSpecValue, law string) {\n\tvalue := lsHarnessNumber(score)\n\tlsHarnessCases.Lock()\n\tdefer lsHarnessCases.Unlock()\n\tstats := lsHarnessStatsOf(law)\n\tif stats.best == nil || value > *stats.best {\n\t\tstats.best = &value\n\t}\n}\n\nfunc lsHarnessNumber(v LawSpecValue) float64 {\n\tswitch x := v.Data.(type) {\n\tcase float64:\n\t\treturn x\n\tcase float32:\n\t\treturn float64(x)\n\tdefault:\n\t\tvar f float64\n\t\tif _, err := fmt.Sscan(fmt.Sprint(x), &f); err == nil {\n\t\t\treturn f\n\t\t}\n\t\treturn math.NaN()\n\t}\n}\n\nfunc lsHarnessAdequacy(t testing.TB, law string, covers []lsHarnessCover) map[string]any {\n\tlsHarnessCases.Lock()\n\tstats := lsHarnessStatsOf(law)\n\tdelete(lsHarnessCases.laws, law)\n\tlsHarnessCases.Unlock()\n\tresults := []map[string]any{}\n\tlines := []string{fmt.Sprintf(\"%s: %d generated case(s)\", law, stats.cases)}\n\tfor _, c := range covers {\n\t\tobserved := 0.0\n\t\tif stats.cases > 0 {\n\t\t\tobserved = math.Round(10000*float64(stats.cover[c.label])/float64(stats.cases)) / 100\n\t\t}\n\t\tmet := stats.cases > 0 && observed >= float64(c.percent)\n\t\tresults = append(results, map[string]any{\"label\": c.label, \"required\": c.percent, \"observed\": observed, \"met\": met})\n\t\tsuffix := \"\"\n\t\tif !met {\n\t\t\tsuffix = \" (not met)\"\n\t\t}\n\t\tlines = append(lines, fmt.Sprintf(\"  cover %d%% %q: %v%%%s\", c.percent, c.label, observed, suffix))\n\t}\n\tfor i, table := range []map[string]int{stats.classes, stats.labels} {\n\t\tkeys := make([]string, 0, len(table))\n\t\tfor k := range table {\n\t\t\tkeys = append(keys, k)\n\t\t}\n\t\tsort.Strings(keys)\n\t\tfor _, k := range keys {\n\t\t\tprefix := \"\"\n\t\t\tif i == 1 {\n\t\t\t\tprefix = \"label \"\n\t\t\t}\n\t\t\tlines = append(lines, fmt.Sprintf(\"  %s%s: %.1f%%\", prefix, k, 100*float64(table[k])/math.Max(1, float64(stats.cases))))\n\t\t}\n\t}\n\treport := map[string]any{\"law\": law, \"cases\": stats.cases, \"cover\": results, \"classes\": stats.classes, \"labels\": stats.labels}\n\tif stats.best != nil {\n\t\treport[\"best\"] = *stats.best\n\t\tlines = append(lines, fmt.Sprintf(\"  best target score: %v\", *stats.best))\n\t}\n\tt.Log(strings.Join(lines, \"\\n\"))\n\treturn report\n}\n\n// A recorder for one run of a test: rapid.TB, whose failures stop the run.\ntype lsHarnessT struct {\n\tname     string\n\tfailed   bool\n\tmessages []string\n}\n\ntype lsHarnessStop struct{}\n\nfunc (r *lsHarnessT) Helper()                         {}\nfunc (r *lsHarnessT) Name() string                    { return r.name }\nfunc (r *lsHarnessT) Logf(format string, args ...any) { r.messages = append(r.messages, fmt.Sprintf(format, args...)) }\nfunc (r *lsHarnessT) Log(args ...any)                 { r.messages = append(r.messages, fmt.Sprint(args...)) }\nfunc (r *lsHarnessT) Skipf(format string, args ...any) { r.Logf(format, args...); panic(lsHarnessStop{}) }\nfunc (r *lsHarnessT) Skip(args ...any)                { r.Log(args...); panic(lsHarnessStop{}) }\nfunc (r *lsHarnessT) SkipNow()                        { panic(lsHarnessStop{}) }\nfunc (r *lsHarnessT) Errorf(format string, args ...any) {\n\tr.failed = true\n\tr.Logf(format, args...)\n}\nfunc (r *lsHarnessT) Error(args ...any) { r.failed = true; r.Log(args...) }\nfunc (r *lsHarnessT) Fatalf(format string, args ...any) {\n\tr.Errorf(format, args...)\n\tpanic(lsHarnessStop{})\n}\nfunc (r *lsHarnessT) Fatal(args ...any) { r.Error(args...); panic(lsHarnessStop{}) }\nfunc (r *lsHarnessT) FailNow()          { r.failed = true; panic(lsHarnessStop{}) }\nfunc (r *lsHarnessT) Fail()             { r.failed = true }\nfunc (r *lsHarnessT) Failed() bool      { return r.failed }\n\n// One run of a test under a recorder, within a timeout (0: none). It gives\n// the failure, if any, and whether the harness itself failed.\nfunc lsHarnessOnce(name string, timeout int, test func(rapid.TB)) (string, bool) {\n\trecorder := &lsHarnessT{name: name}\n\ttype outcome struct {\n\t\tmessage string\n\t\tharness bool\n\t}\n\tdone := make(chan outcome, 1)\n\tgo func() {\n\t\tdefer func() {\n\t\t\tif err := recover(); err != nil {\n\t\t\t\tif failure, ok := err.(lsHarnessFailure); ok {\n\t\t\t\t\tdone <- outcome{failure.message, true}\n\t\t\t\t\treturn\n\t\t\t\t}\n\t\t\t\tif _, ok := err.(lsHarnessStop); !ok {\n\t\t\t\t\trecorder.failed = true\n\t\t\t\t\trecorder.messages = append(recorder.messages, fmt.Sprint(err))\n\t\t\t\t}\n\t\t\t}\n\t\t\tif recorder.failed {\n\t\t\t\tdone <- outcome{strings.Join(recorder.messages, \"\\n\"), lsHarnessHarnessMessage(recorder.messages)}\n\t\t\t} else {\n\t\t\t\tdone <- outcome{\"\", false}\n\t\t\t}\n\t\t}()\n\t\ttest(recorder)\n\t}()\n\tif timeout <= 0 {\n\t\to := <-done\n\t\treturn o.message, o.harness\n\t}\n\tselect {\n\tcase o := <-done:\n\t\treturn o.message, o.harness\n\tcase <-time.After(time.Duration(timeout) * time.Millisecond):\n\t\treturn fmt.Sprintf(\"took longer than its timeout of %d ms\", timeout), true\n\t}\n}\n\n// rapid reports a panic in a draw as text; a harness failure stays one.\nfunc lsHarnessHarnessMessage(messages []string) bool {\n\tfor _, m := range messages {\n\t\tif strings.Contains(m, \"outside the input's refinement\") || strings.Contains(m, \"discarded more than\") {\n\t\t\treturn true\n\t\t}\n\t}\n\treturn false\n}\n\n// Run one generated test of a law under its harness settings.\nfunc lsHarnessRun(t *testing.T, law, name string, timeout, repeat, retries int, covers []lsHarnessCover, observed bool, test func(rapid.TB)) {\n\tt.Helper()\n\tattempts := 0\n\tflaky := false\n\tvar report map[string]any\n\tfor {\n\t\tattempts++\n\t\tfailure, harness := \"\", false\n\t\tfor i := 0; i < repeat && failure == \"\"; i++ {\n\t\t\tlsHarnessCases.Lock()\n\t\t\tdelete(lsHarnessCases.laws, law)\n\t\t\tlsHarnessCases.Unlock()\n\t\t\tfailure, harness = lsHarnessOnce(t.Name(), timeout, test)\n\t\t\tif failure == \"\" && observed {\n\t\t\t\treport = lsHarnessAdequacy(t, law, covers)\n\t\t\t\tunmet := []string{}\n\t\t\t\tfor _, r := range report[\"cover\"].([]map[string]any) {\n\t\t\t\t\tif !r[\"met\"].(bool) {\n\t\t\t\t\t\tunmet = append(unmet, fmt.Sprintf(\"%s: cover %d%% %q was not met (%v%% of %d generated cases)\", law, r[\"required\"], r[\"label\"], r[\"observed\"], report[\"cases\"]))\n\t\t\t\t\t}\n\t\t\t\t}\n\t\t\t\tif len(unmet) > 0 {\n\t\t\t\t\tfailure, harness = strings.Join(unmet, \"; \"), true\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif failure == \"\" {\n\t\t\tbreak\n\t\t}\n\t\tif harness || attempts > retries {\n\t\t\tlsHarnessRecord(name, map[string]any{\"law\": law, \"test\": name, \"outcome\": \"failed\", \"attempts\": attempts})\n\t\t\tt.Fatalf(\"%s\", failure)\n\t\t\treturn\n\t\t}\n\t\tflaky = true\n\t}\n\tentry := map[string]any{\"law\": law, \"test\": name, \"outcome\": \"passed\", \"attempts\": attempts}\n\tif flaky {\n\t\tentry[\"outcome\"] = \"flaky\"\n\t\tt.Logf(\"%s is flaky: it failed, then passed on attempt %d\", law, attempts)\n\t}\n\tfor k, v := range report {\n\t\tentry[k] = v\n\t}\n\tlsHarnessRecord(name, entry)\n}\n\nfunc lsHarnessSkip(t *testing.T, law, reason string) {\n\tlsHarnessRecord(law, map[string]any{\"law\": law, \"outcome\": \"skipped\", \"reason\": reason})\n\tt.Skipf(\"%s: %s\", law, reason)\n}\n\n// A known-failing law's tests must fail. One that passes is reported: the\n// harness should no longer say it is known to fail.\nfunc lsHarnessKnownFailing(t *testing.T, law, name, reason string, tests []func(rapid.TB)) {\n\tfor _, test := range tests {\n\t\tif failure, _ := lsHarnessOnce(t.Name(), 0, test); failure != \"\" {\n\t\t\tlsHarnessRecord(name, map[string]any{\"law\": law, \"test\": name, \"outcome\": \"known-failing\", \"reason\": reason})\n\t\t\tt.Logf(\"%s is known to fail (%s): %s\", law, reason, strings.SplitN(failure, \"\\n\", 2)[0])\n\t\t\treturn\n\t\t}\n\t}\n\tlsHarnessRecord(name, map[string]any{\"law\": law, \"test\": name, \"outcome\": \"known-failing-passed\", \"reason\": reason})\n\tt.Fatalf(\"%s is marked known failing (%s), but it passes; remove `known failing` from its harness\", law, reason)\n}\n\n// Measured, never asserted, with Go's own benchmark harness.\nfunc lsHarnessBenchmark(t *testing.T, name string, body func()) {\n\tresult := testing.Benchmark(func(b *testing.B) {\n\t\tfor i := 0; i < b.N; i++ {\n\t\t\tbody()\n\t\t}\n\t})\n\tt.Logf(\"benchmark %s: %d iteration(s), mean %.2f us\", name, result.N, float64(result.NsPerOp())/1000)\n\tlsHarnessRecord(\"benchmark \"+name, map[string]any{\"benchmark\": name, \"iterations\": result.N, \"mean_ns\": result.NsPerOp()})\n}\n\n// lsHarnessShuffle is order random: go test runs the package's tests in an\n// order -test.shuffle chooses, here the run's seed (LAWSPEC_SEED), or the\n// clock. A -test.shuffle given on the command line wins.\nfunc lsHarnessShuffle() {\n\tif !flag.Parsed() {\n\t\tflag.Parse()\n\t}\n\tif f := flag.Lookup(\"test.shuffle\"); f != nil && f.Value.String() == \"off\" {\n\t\tseed := os.Getenv(\"LAWSPEC_SEED\")\n\t\tif seed == \"\" {\n\t\t\tseed = fmt.Sprint(time.Now().UnixNano() % 2147483647)\n\t\t}\n\t\t_ = flag.Set(\"test.shuffle\", seed)\n\t\tfmt.Printf(\"order random seed %s: LAWSPEC_SEED=%s replays this order\\n\", seed, seed)\n\t}\n}\n\n// lsHarnessParallelism records how a parallel unit's tests run: each calls\n// t.Parallel, so go test runs them on goroutines across GOMAXPROCS threads.\nfunc lsHarnessParallelism(unit string) {\n\tworkers := runtime.GOMAXPROCS(0)\n\tmode := \"goroutines (t.Parallel)\"\n\tlsHarnessRecord(\"parallel \"+unit, map[string]any{\"parallel\": unit, \"mode\": mode, \"workers\": workers})\n\tfmt.Printf(\"%s runs in parallel: %s, %d worker(s)\\n\", unit, mode, workers)\n}\n"
runtimeSource "java-harness" = "// The harness plane at run time (see docs/reference/language/harness.md):\n// how a law's tests run, never what the law means. Generated tests call it\n// for strategies (frequency, one of, such that), adequacy (cover, classify,\n// label), run metadata (known failing, timeout, repeat, retry flaky) and\n// benchmarks. Java and Kotlin tests share it.\n//\n// Statistics go to standard output, and, when LAWSPEC_STATS names a\n// directory, to one JSON file per test there, which lawspec test reads.\npackage lawspec.testing;\n\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.util.ArrayList;\nimport java.util.LinkedHashMap;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.TreeMap;\nimport java.util.concurrent.ExecutionException;\nimport java.util.concurrent.Executors;\nimport java.util.concurrent.TimeUnit;\nimport java.util.concurrent.TimeoutException;\nimport java.util.function.Predicate;\nimport java.util.function.Supplier;\nimport lawspec.runtime.LawSpecRuntime;\nimport lawspec.runtime.LawSpecRuntime.Value;\n\npublic final class LawSpecHarness {\n  private LawSpecHarness() {}\n\n  /** A harness requirement failed: a strategy or an adequacy check. */\n  public static final class HarnessError extends AssertionError {\n    public HarnessError(String message) { super(message); }\n  }\n\n  /** A generated test, run by the harness. */\n  @FunctionalInterface\n  public interface Body { void run() throws Throwable; }\n\n  public record Weighted(int weight, Supplier<Value> draw) {}\n\n  // Statistics.\n\n  private static String json(Object value) {\n    if (value == null) return \"null\";\n    if (value instanceof String s) {\n      var out = new StringBuilder(\"\\\"\");\n      for (char c : s.toCharArray()) {\n        if (c == '\"' || c == '\\\\') out.append('\\\\').append(c);\n        else if (c < 0x20) out.append(String.format(\"\\\\u%04x\", (int) c));\n        else out.append(c);\n      }\n      return out.append('\"').toString();\n    }\n    if (value instanceof Map<?, ?> m) {\n      var parts = new ArrayList<String>();\n      for (var e : m.entrySet()) parts.add(json(String.valueOf(e.getKey())) + \":\" + json(e.getValue()));\n      return \"{\" + String.join(\",\", parts) + \"}\";\n    }\n    if (value instanceof List<?> l) {\n      var parts = new ArrayList<String>();\n      for (var item : l) parts.add(json(item));\n      return \"[\" + String.join(\",\", parts) + \"]\";\n    }\n    return String.valueOf(value);\n  }\n\n  private static void record(String name, Map<String, Object> entry) {\n    var directory = System.getenv(\"LAWSPEC_STATS\");\n    if (directory == null || directory.isEmpty()) return;\n    try {\n      Files.createDirectories(Path.of(directory));\n      Files.writeString(Path.of(directory, name.replaceAll(\"[^A-Za-z0-9_-]\", \"_\") + \".json\"), json(entry), StandardCharsets.UTF_8);\n    } catch (Exception ignored) {\n      // Statistics are a convenience; a run never fails for want of them.\n    }\n  }\n\n  // Scheduling: LawSpec owns the order and parallelism of a unit's tests;\n  // JUnit and Kotest host and report them.\n\n  private static final long ORDER_SEED = chooseSeed();\n\n  private static long chooseSeed() {\n    try {\n      return Long.parseLong(System.getenv().getOrDefault(\"LAWSPEC_SEED\", \"\"));\n    } catch (NumberFormatException e) {\n      return new java.util.Random().nextInt(Integer.MAX_VALUE);\n    }\n  }\n\n  /** order random's seed: the run's (LAWSPEC_SEED), or one chosen and printed. */\n  public static long orderSeed() {\n    return ORDER_SEED;\n  }\n\n  /** order random: items in an order the seed chooses, the seed printed. */\n  public static <T> List<T> shuffled(String unit, List<T> items) {\n    var out = new ArrayList<T>(items);\n    java.util.Collections.shuffle(out, new java.util.Random(ORDER_SEED ^ unit.hashCode()));\n    System.out.println(\"order random seed \" + ORDER_SEED + \" (\" + unit + \"): LAWSPEC_SEED=\" + ORDER_SEED + \" replays this order\");\n    return out;\n  }\n\n  /** parallel: records how the unit's tests ran at the same time. */\n  public static void parallelism(String unit, String mode, int workers) {\n    var entry = new java.util.LinkedHashMap<String, Object>();\n    entry.put(\"parallel\", unit);\n    entry.put(\"mode\", mode);\n    entry.put(\"workers\", workers);\n    record(\"parallel \" + unit, entry);\n    System.out.println(unit + \" runs in parallel: \" + mode + \", \" + workers + \" worker(s)\");\n  }\n\n  // Strategies. Java draws its choices through JetCheck, so failures shrink;\n  // Kotlin through Kotest's random source. Neither library is needed here.\n\n  /** choose(n) draws a whole number below n: through JetCheck in Java, Kotest in Kotlin. */\n  public static Value frequency(java.util.function.IntUnaryOperator choose, List<Weighted> alternatives) {\n    int total = 0;\n    for (var a : alternatives) total += a.weight();\n    int pick = choose.applyAsInt(total);\n    for (var a : alternatives) {\n      if (pick < a.weight()) return a.draw().get();\n      pick -= a.weight();\n    }\n    return alternatives.get(alternatives.size() - 1).draw().get();\n  }\n\n  public static Value oneOf(java.util.function.IntUnaryOperator choose, List<Supplier<Value>> values) {\n    return values.get(choose.applyAsInt(values.size())).get();\n  }\n\n  public static Value suchThat(Supplier<Value> draw, Predicate<Value> predicate, int limit, String strategy) {\n    for (int i = 0; i <= limit; i++) {\n      var value = draw.get();\n      if (predicate.test(value)) return value;\n    }\n    throw new HarnessError(\"the strategy \" + strategy + \" discarded more than \" + limit +\n        \" values; draw closer to what `such that` keeps, or allow more discards\");\n  }\n\n  /** A drawn value must satisfy its input's refinements. */\n  public static void checkDrawn(String strategy, String name, boolean holds, Value value) {\n    if (!holds)\n      throw new HarnessError(\"the strategy \" + strategy + \" produced \" + value + \" for \" + name +\n          \", which is outside the input's refinement; a strategy may only produce values of its type\");\n  }\n\n  // Adequacy.\n\n  private static final class Stats {\n    int cases;\n    final Map<String, Integer> cover = new TreeMap<>(), classes = new TreeMap<>(), labels = new TreeMap<>();\n    Double best;\n  }\n\n  private static final Map<String, Stats> CASES = new LinkedHashMap<>();\n\n  private static synchronized Stats stats(String law) { return CASES.computeIfAbsent(law, k -> new Stats()); }\n\n  public static synchronized void observe(String law, String[] coverLabels, boolean[] covers,\n      String[] classLabels, boolean[] classes, Value[] labels) {\n    var s = stats(law);\n    s.cases++;\n    for (int i = 0; i < covers.length; i++) if (covers[i]) s.cover.merge(coverLabels[i], 1, Integer::sum);\n    for (int i = 0; i < classes.length; i++) if (classes[i]) s.classes.merge(classLabels[i], 1, Integer::sum);\n    for (var label : labels) s.labels.merge(String.valueOf(LawSpecRuntime.toNative(\"Text\", label, 64)), 1, Integer::sum);\n  }\n\n  /** target maximize: JetCheck has no targeted search; the best score is reported. */\n  public static synchronized void target(Value score, String law) {\n    var s = stats(law);\n    double value = Double.parseDouble(String.valueOf(score.data()));\n    if (s.best == null || value > s.best) s.best = value;\n  }\n\n  private static synchronized Map<String, Object> adequacy(String law, int[] percents, String[] labels) {\n    var s = CASES.remove(law);\n    if (s == null) s = new Stats();\n    var results = new ArrayList<Object>();\n    var lines = new ArrayList<String>();\n    lines.add(law + \": \" + s.cases + \" generated case(s)\");\n    for (int i = 0; i < percents.length; i++) {\n      double observed = s.cases == 0 ? 0 : Math.round(10000.0 * s.cover.getOrDefault(labels[i], 0) / s.cases) / 100.0;\n      boolean met = s.cases > 0 && observed >= percents[i];\n      var r = new LinkedHashMap<String, Object>();\n      r.put(\"label\", labels[i]); r.put(\"required\", percents[i]); r.put(\"observed\", observed); r.put(\"met\", met);\n      results.add(r);\n      lines.add(\"  cover \" + percents[i] + \"% \\\"\" + labels[i] + \"\\\": \" + observed + \"%\" + (met ? \"\" : \" (not met)\"));\n    }\n    for (var e : s.classes.entrySet()) lines.add(String.format(\"  %s: %.1f%%\", e.getKey(), 100.0 * e.getValue() / Math.max(1, s.cases)));\n    for (var e : s.labels.entrySet()) lines.add(String.format(\"  label %s: %.1f%%\", e.getKey(), 100.0 * e.getValue() / Math.max(1, s.cases)));\n    if (s.best != null) lines.add(\"  best target score: \" + s.best);\n    System.out.println(String.join(\"\\n\", lines));\n    var report = new LinkedHashMap<String, Object>();\n    report.put(\"law\", law); report.put(\"cases\", s.cases); report.put(\"cover\", results);\n    report.put(\"classes\", new LinkedHashMap<String, Object>(s.classes)); report.put(\"labels\", new LinkedHashMap<String, Object>(s.labels));\n    if (s.best != null) report.put(\"best\", s.best);\n    return report;\n  }\n\n  private static void once(Body test, long timeout, String law) throws Throwable {\n    if (timeout <= 0) { test.run(); return; }\n    var executor = Executors.newSingleThreadExecutor(r -> { var t = new Thread(r); t.setDaemon(true); return t; });\n    try {\n      var future = executor.submit(() -> { try { test.run(); } catch (Throwable t) { throw new ExecutionException(t); } return null; });\n      future.get(timeout, TimeUnit.MILLISECONDS);\n    } catch (TimeoutException e) {\n      throw new HarnessError(law + \" took longer than its timeout of \" + timeout + \" ms\");\n    } catch (ExecutionException e) {\n      var cause = e.getCause() instanceof ExecutionException inner ? inner.getCause() : e.getCause();\n      throw cause;\n    } finally {\n      executor.shutdownNow();\n    }\n  }\n\n  /** Run one generated test of a law under its harness settings. */\n  public static void run(String law, String name, long timeout, int repeat, int retries,\n      int[] percents, String[] labels, boolean observed, Body test) throws Throwable {\n    int attempts = 0;\n    boolean flaky = false;\n    Map<String, Object> report = null;\n    while (true) {\n      attempts++;\n      try {\n        for (int i = 0; i < repeat; i++) {\n          synchronized (LawSpecHarness.class) { CASES.remove(law); }\n          once(test, timeout, law);\n          report = observed ? adequacy(law, percents, labels) : null;\n          if (report != null) {\n            var unmet = new ArrayList<String>();\n            for (var r : (List<?>) report.get(\"cover\")) {\n              var m = (Map<?, ?>) r;\n              if (!(Boolean) m.get(\"met\"))\n                unmet.add(law + \": cover \" + m.get(\"required\") + \"% \\\"\" + m.get(\"label\") + \"\\\" was not met (\" +\n                    m.get(\"observed\") + \"% of \" + report.get(\"cases\") + \" generated cases)\");\n            }\n            if (!unmet.isEmpty()) throw new HarnessError(String.join(\"; \", unmet));\n          }\n        }\n        break;\n      } catch (Throwable error) {\n        if (error instanceof HarnessError || attempts > retries) {\n          var entry = new LinkedHashMap<String, Object>();\n          entry.put(\"law\", law); entry.put(\"test\", name); entry.put(\"outcome\", \"failed\"); entry.put(\"attempts\", attempts);\n          record(name, entry);\n          throw error;\n        }\n        flaky = true;\n      }\n    }\n    var entry = new LinkedHashMap<String, Object>();\n    entry.put(\"law\", law); entry.put(\"test\", name); entry.put(\"outcome\", flaky ? \"flaky\" : \"passed\"); entry.put(\"attempts\", attempts);\n    if (report != null) entry.putAll(report);\n    record(name, entry);\n    if (flaky) System.out.println(law + \" is flaky: it failed, then passed on attempt \" + attempts);\n  }\n\n  /** A known-failing law's tests must fail; one that passes is reported. */\n  public static void knownFailing(String law, String name, String reason, List<Body> tests) {\n    var entry = new LinkedHashMap<String, Object>();\n    entry.put(\"law\", law); entry.put(\"test\", name); entry.put(\"reason\", reason);\n    for (var test : tests) {\n      try {\n        test.run();\n      } catch (Throwable error) {\n        entry.put(\"outcome\", \"known-failing\");\n        record(name, entry);\n        System.out.println(law + \" is known to fail (\" + reason + \"): \" + String.valueOf(error.getMessage()).lines().findFirst().orElse(\"\"));\n        return;\n      }\n    }\n    entry.put(\"outcome\", \"known-failing-passed\");\n    record(name, entry);\n    throw new HarnessError(law + \" is marked known failing (\" + reason + \"), but it passes; remove `known failing` from its harness\");\n  }\n\n  /** Measured, never asserted: the mean and fastest time of body. */\n  public static void benchmark(String name, Body body) throws Throwable {\n    var times = new ArrayList<Long>();\n    long started = System.nanoTime();\n    while (times.size() < 100000 && (System.nanoTime() - started < 200_000_000L || times.size() < 3)) {\n      long before = System.nanoTime();\n      body.run();\n      times.add(System.nanoTime() - before);\n    }\n    long sum = 0, fastest = Long.MAX_VALUE;\n    for (long t : times) { sum += t; fastest = Math.min(fastest, t); }\n    long mean = sum / times.size();\n    System.out.printf(\"benchmark %s: %d iteration(s), mean %.2f us, fastest %.2f us%n\", name, times.size(), mean / 1000.0, fastest / 1000.0);\n    var entry = new LinkedHashMap<String, Object>();\n    entry.put(\"benchmark\", name); entry.put(\"iterations\", times.size()); entry.put(\"mean_ns\", mean); entry.put(\"min_ns\", fastest);\n    record(\"benchmark \" + name, entry);\n  }\n}\n"
runtimeSource "haskell-harness" = "-- The harness plane at run time (see docs/reference/language/harness.md):\n-- how a law's tests run, never what the law means. Generated tests call it\n-- for strategies' refinement checks, adequacy (cover, classify, label), run\n-- metadata (known failing, timeout, repeat, retry flaky) and benchmarks.\n--\n-- Statistics go to standard output, and, when LAWSPEC_STATS names a\n-- directory, to one JSON file per test there, which lawspec test reads.\nmodule LawSpecHarness\n  ( HarnessError(..), checkDrawn, observe, target, run, knownFailing, benchmark, record, shuffled, parallelism\n  ) where\n\nimport Control.Exception (Exception, SomeException, evaluate, fromException, throwIO, try)\nimport Control.Monad (forM, unless, when)\nimport Data.Char (isAlphaNum)\nimport Data.IORef (IORef, atomicModifyIORef', newIORef)\nimport Data.List (intercalate, sortOn)\nimport qualified Data.Map.Strict as M\nimport GHC.Clock (getMonotonicTimeNSec)\nimport Numeric (showFFloat)\nimport System.Environment (lookupEnv)\nimport System.IO.Unsafe (unsafePerformIO)\nimport System.Timeout (timeout)\nimport LawSpecRuntime (Scalar(..))\nimport qualified LawSpecRuntime as LS\nimport Data.Word (Word64)\nimport Test.Hspec (SpecWith, runIO)\nimport Control.Concurrent (getNumCapabilities)\n\n-- A harness requirement failed: a strategy or an adequacy check.\nnewtype HarnessError = HarnessError String\n\ninstance Show HarnessError where\n  show (HarnessError message) = message\n\ninstance Exception HarnessError\n\ndata Json = JString String | JNumber Double | JInt Integer | JBool Bool | JList [Json] | JObject [(String, Json)]\n\njson :: Json -> String\njson value = case value of\n  JString s -> show s\n  JNumber d -> show d\n  JInt n -> show n\n  JBool b -> if b then \"true\" else \"false\"\n  JList xs -> \"[\" ++ intercalate \",\" (map json xs) ++ \"]\"\n  JObject fields -> \"{\" ++ intercalate \",\" [show k ++ \":\" ++ json v | (k, v) <- fields] ++ \"}\"\n\nrecord :: String -> [(String, Json)] -> IO ()\nrecord name entry = do\n  directory <- lookupEnv \"LAWSPEC_STATS\"\n  case directory of\n    Just d | not (null d) -> do\n      let safe = map (\\c -> if isAlphaNum c || c `elem` \"-_\" then c else '_') name\n      _ <- try (writeFile (d ++ \"/\" ++ safe ++ \".json\") (json (JObject entry))) :: IO (Either SomeException ())\n      pure ()\n    _ -> pure ()\n\n-- A drawn value must satisfy its input's refinements: a strategy may only\n-- produce values the law is about.\ncheckDrawn :: String -> String -> Bool -> Scalar -> IO ()\ncheckDrawn strategy name holds value = unless holds $ throwIO (HarnessError (\"the strategy \" ++ strategy ++ \" produced \" ++\n  LS.renderValue value ++ \" for \" ++ name ++ \", which is outside the input's refinement; a strategy may only produce values of its type\"))\n\ndata Stats = Stats { cases :: Int, covered :: M.Map String Int, classes :: M.Map String Int, labels :: M.Map String Int, best :: Maybe Double }\n\nemptyStats :: Stats\nemptyStats = Stats 0 M.empty M.empty M.empty Nothing\n\nstatistics :: IORef (M.Map String Stats)\nstatistics = unsafePerformIO (newIORef M.empty)\n{-# NOINLINE statistics #-}\n\n-- What one generated case covers, classifies and labels.\nobserve :: String -> [(String, Bool)] -> [(String, Bool)] -> [Scalar] -> IO ()\nobserve law covers classified labelled = atomicModifyIORef' statistics $ \\table ->\n  let s = M.findWithDefault emptyStats law table\n      count xs m = foldr (\\(l, holds) acc -> if holds then M.insertWith (+) l 1 acc else acc) m xs\n      s' = s { cases = cases s + 1, covered = count covers (covered s), classes = count classified (classes s)\n             , labels = foldr (\\v acc -> M.insertWith (+) (text v) 1 acc) (labels s) labelled }\n  in (M.insert law s' table, ())\n  where\n    text v = case v of\n      SSequence _ units -> map toEnum units\n      other -> LS.renderValue other\n\n-- target maximize: Hedgehog has no targeted search, so the best score it\n-- draws is reported with the law's statistics, and LawSpec's own search\n-- (LS.searchClimb) climbs after the property.\ntarget :: Scalar -> String -> IO ()\ntarget score law = atomicModifyIORef' statistics $ \\table ->\n  let s = M.findWithDefault emptyStats law table\n      value = number score\n  in (M.insert law s { best = Just (maybe value (max value) (best s)) } table, ())\n  where\n    number v = case v of\n      SInteger _ n -> fromIntegral n\n      SDecimal c e -> fromIntegral c * 10 ^^ e\n      SRational n d -> fromIntegral n / fromIntegral d\n      _ -> LS.floatValue v\n\nadequacy :: String -> [(Int, String)] -> IO [(String, Json)]\nadequacy law covers = do\n  s <- atomicModifyIORef' statistics (\\table -> (M.delete law table, M.findWithDefault emptyStats law table))\n  let n = cases s\n      percent k = if n == 0 then 0 else fromIntegral (round (10000 * fromIntegral k / fromIntegral n :: Double)) / 100 :: Double\n      results = [(p, l, percent (M.findWithDefault 0 l (covered s))) | (p, l) <- covers]\n      met (p, _, observed) = n > 0 && observed >= fromIntegral p\n      shown d = showFFloat (Just 1) d \"\"\n  putStrLn (intercalate \"\\n\" (\n    [law ++ \": \" ++ show n ++ \" generated case(s)\"] ++\n    [\"  cover \" ++ show p ++ \"% \" ++ show l ++ \": \" ++ shown o ++ \"%\" ++ (if met r then \"\" else \" (not met)\") | r@(p, l, o) <- results] ++\n    [\"  \" ++ l ++ \": \" ++ shown (percent k) ++ \"%\" | (l, k) <- M.toList (classes s)] ++\n    [\"  label \" ++ l ++ \": \" ++ shown (percent k) ++ \"%\" | (l, k) <- sortOn (negate . snd) (M.toList (labels s))] ++\n    [\"  best target score: \" ++ show b | Just b <- [best s]]))\n  let unmet = [law ++ \": cover \" ++ show p ++ \"% \" ++ show l ++ \" was not met (\" ++ shown o ++ \"% of \" ++ show n ++ \" generated cases)\" | r@(p, l, o) <- results, not (met r)]\n  unless (null unmet) (throwIO (HarnessError (intercalate \"; \" unmet)))\n  pure [ (\"law\", JString law), (\"cases\", JInt (fromIntegral n))\n       , (\"cover\", JList [JObject [(\"label\", JString l), (\"required\", JInt (fromIntegral p)), (\"observed\", JNumber o), (\"met\", JBool (met r))] | r@(p, l, o) <- results])\n       , (\"classes\", JObject [(k, JInt (fromIntegral v)) | (k, v) <- M.toList (classes s)])\n       , (\"labels\", JObject [(k, JInt (fromIntegral v)) | (k, v) <- M.toList (labels s)]) ]\n\nonce :: String -> Int -> IO () -> IO ()\nonce law milliseconds test\n  | milliseconds <= 0 = test\n  | otherwise = do\n      finished <- timeout (milliseconds * 1000) test\n      case finished of\n        Just () -> pure ()\n        Nothing -> throwIO (HarnessError (law ++ \" took longer than its timeout of \" ++ show milliseconds ++ \" ms\"))\n\n-- Run one generated test of a law under its harness settings.\nrun :: String -> String -> Int -> Int -> Int -> [(Int, String)] -> Bool -> IO () -> IO ()\nrun law name milliseconds repeats retries covers observed test = go 1 False\n  where\n    attempt = fmap concat $ forM [1 .. repeats] $ \\_ -> do\n      atomicModifyIORef' statistics (\\table -> (M.delete law table, ()))\n      once law milliseconds test\n      if observed then adequacy law covers else pure []\n    go attempts flaky = do\n      outcome <- try attempt\n      case outcome of\n        Right report -> do\n          record name ([(\"law\", JString law), (\"test\", JString name), (\"attempts\", JInt attempts),\n            (\"outcome\", JString (if flaky then \"flaky\" else \"passed\"))] ++ report)\n          when flaky (putStrLn (law ++ \" is flaky: it failed, then passed on attempt \" ++ show attempts))\n        Left error'\n          | harness error' || attempts > fromIntegral retries -> do\n              record name [(\"law\", JString law), (\"test\", JString name), (\"outcome\", JString \"failed\"), (\"attempts\", JInt attempts)]\n              throwIO error'\n          | otherwise -> go (attempts + 1) True\n    harness :: SomeException -> Bool\n    harness e = case fromException e of\n      Just (HarnessError _) -> True\n      Nothing -> False\n\n-- A known-failing law's tests must fail. One that passes is reported: the\n-- harness should no longer say it is known to fail.\nknownFailing :: String -> String -> String -> [IO ()] -> IO ()\nknownFailing law name reason tests = go tests\n  where\n    go [] = do\n      record name [(\"law\", JString law), (\"test\", JString name), (\"outcome\", JString \"known-failing-passed\"), (\"reason\", JString reason)]\n      throwIO (HarnessError (law ++ \" is marked known failing (\" ++ reason ++ \"), but it passes; remove `known failing` from its harness\"))\n    go (test : rest) = do\n      outcome <- try test :: IO (Either SomeException ())\n      case outcome of\n        Left e -> do\n          record name [(\"law\", JString law), (\"test\", JString name), (\"outcome\", JString \"known-failing\"), (\"reason\", JString reason)]\n          putStrLn (law ++ \" is known to fail (\" ++ reason ++ \"): \" ++ takeWhile (/= '\\n') (show e))\n        Right () -> go rest\n\n-- Measured, never asserted: the mean and fastest time of body.\nbenchmark :: String -> IO a -> IO ()\nbenchmark name body = do\n  started <- getMonotonicTimeNSec\n  let loop times = do\n        now <- getMonotonicTimeNSec\n        if length times >= 100000 || (now - started > 200000000 && length times >= 3) then pure times else do\n          before <- getMonotonicTimeNSec\n          _ <- body >>= evaluate\n          after <- getMonotonicTimeNSec\n          loop ((after - before) : times)\n  times <- loop []\n  let mean = fromIntegral (sum times) / fromIntegral (length times) :: Double\n      fastest = fromIntegral (minimum times) :: Double\n  putStrLn (\"benchmark \" ++ name ++ \": \" ++ show (length times) ++ \" iteration(s), mean \" ++ showFFloat (Just 2) (mean / 1000) \"\" ++\n    \" us, fastest \" ++ showFFloat (Just 2) (fastest / 1000) \"\" ++ \" us\")\n  record (\"benchmark \" ++ name) [(\"benchmark\", JString name), (\"iterations\", JInt (fromIntegral (length times))),\n    (\"mean_ns\", JInt (round mean)), (\"min_ns\", JInt (round fastest))]\n\n-- order random: the unit's law tests, each law's in one block, in an order\n-- the run's seed chooses (LAWSPEC_SEED, else HSPEC_SEED, else the clock).\nshuffled :: String -> [SpecWith ()] -> SpecWith ()\nshuffled unit items = do\n  seed <- runIO $ do\n    given <- lookupEnv \"LAWSPEC_SEED\"\n    hspecSeed <- lookupEnv \"HSPEC_SEED\"\n    now <- getMonotonicTimeNSec\n    let chosen = maybe (now `mod` 2147483647) id (parse given `orElse` parse hspecSeed)\n    putStrLn (\"order random seed \" ++ show chosen ++ \" (\" ++ unit ++ \"): LAWSPEC_SEED=\" ++ show chosen ++ \" replays this order\")\n    pure chosen\n  sequence_ (permute seed items)\n  where\n    parse :: Maybe String -> Maybe Word64\n    parse text = case fmap reads text of\n      Just [(n, \"\")] -> Just n\n      _ -> Nothing\n    orElse (Just a) _ = Just a\n    orElse Nothing b = b\n    -- Fisher-Yates over SplitMix64 draws.\n    permute _ [] = []\n    permute state xs =\n      let (draw, next) = LS.splitMix64 state\n          i = fromIntegral (draw `mod` fromIntegral (length xs))\n          (before, chosen : after) = splitAt i xs\n      in chosen : permute next (before ++ after)\n\n-- | parallel: how the unit's tests run at the same time. hspec runs them on\n-- threads, which the threaded runtime (-with-rtsopts=-N) spreads over a\n-- capability per processor.\nparallelism :: String -> SpecWith ()\nparallelism unit = runIO $ do\n  workers <- getNumCapabilities\n  let mode = if workers > 1 then \"threads (hspec parallel, threaded runtime)\" else \"threads (hspec parallel; one capability, so they interleave)\"\n  record (\"parallel \" ++ unit) [(\"parallel\", JString unit), (\"mode\", JString mode), (\"workers\", JInt (fromIntegral workers))]\n  putStrLn (unit ++ \" runs in parallel: \" ++ mode ++ \", \" ++ show workers ++ \" worker(s)\")\n"
runtimeSource "rust-harness" = "//! The harness plane at run time (see docs/reference/language/harness.md):\n//! how a law's tests run, never what the law means. Generated tests call it\n//! for strategies (drawn from a seed proptest chooses), adequacy (cover,\n//! classify, label), run metadata (known failing, timeout, repeat, retry\n//! flaky) and benchmarks.\n//!\n//! Statistics go to standard output, and, when LAWSPEC_STATS names a\n//! directory, to one JSON file per test there, which lawspec test reads.\n#![allow(dead_code)]\nuse crate::lawspec_runtime::{self as ls, Value};\nuse proptest::strategy::{Strategy, ValueTree};\nuse std::collections::BTreeMap;\nuse std::sync::Mutex;\n\nfn quote(text: &str) -> String {\n    let mut out = String::from(\"\\\"\");\n    for c in text.chars() {\n        match c {\n            '\"' => out.push_str(\"\\\\\\\"\"),\n            '\\\\' => out.push_str(\"\\\\\\\\\"),\n            c if (c as u32) < 0x20 => out.push_str(&format!(\"\\\\u{:04x}\", c as u32)),\n            c => out.push(c),\n        }\n    }\n    out.push('\"');\n    out\n}\n\npub fn record(name: &str, entry: &[(&str, String)]) {\n    let Ok(directory) = std::env::var(\"LAWSPEC_STATS\") else { return };\n    if directory.is_empty() {\n        return;\n    }\n    let _ = std::fs::create_dir_all(&directory);\n    let safe: String = name.chars().map(|c| if c.is_ascii_alphanumeric() || c == '-' || c == '_' { c } else { '_' }).collect();\n    let body = entry.iter().map(|(k, v)| format!(\"{}:{}\", quote(k), v)).collect::<Vec<_>>().join(\",\");\n    let _ = std::fs::write(format!(\"{directory}/{safe}.json\"), format!(\"{{{body}}}\"));\n}\n\n/// The draws of one strategy value: choices from a seed proptest chooses\n/// (and shrinks toward zero), and default values sampled from proptest's\n/// own strategies with that seed.\npub struct Draws {\n    state: u64,\n}\n\nimpl Draws {\n    pub fn new(seed: u64) -> Draws {\n        Draws { state: seed }\n    }\n\n    fn next(&mut self) -> u64 {\n        self.state = self.state.wrapping_add(0x9E3779B97F4A7C15);\n        let mut z = self.state;\n        z = (z ^ (z >> 30)).wrapping_mul(0xBF58476D1CE4E5B9);\n        z = (z ^ (z >> 27)).wrapping_mul(0x94D049BB133111EB);\n        z ^ (z >> 31)\n    }\n\n    /// A choice among n.\n    pub fn choose(&mut self, n: u64) -> u64 {\n        self.next() % n\n    }\n\n    /// A value of the default strategy.\n    pub fn any(&mut self, strategy: &proptest::strategy::BoxedStrategy<Value>) -> Value {\n        let mut bytes = [0u8; 32];\n        for chunk in bytes.chunks_mut(8) {\n            chunk.copy_from_slice(&self.next().to_le_bytes());\n        }\n        let rng = proptest::test_runner::TestRng::from_seed(proptest::test_runner::RngAlgorithm::ChaCha, &bytes);\n        let mut runner = proptest::test_runner::TestRunner::new_with_rng(proptest::test_runner::Config::default(), rng);\n        strategy.new_tree(&mut runner).expect(\"the default strategy draws a value\").current()\n    }\n}\n\n/// A strategy's value, or a panic that names the harness's failure.\npub fn drawn(value: ls::Result<Value>) -> Value {\n    value.unwrap_or_else(|error| panic!(\"{error}\"))\n}\n\npub fn outside(strategy: &str, name: &str, value: &Value) -> String {\n    format!(\"the strategy {strategy} produced {value:?} for {name}, which is outside the input's refinement; a strategy may only produce values of its type\")\n}\n\npub fn discarded(strategy: &str, limit: usize) -> String {\n    format!(\"the strategy {strategy} discarded more than {limit} values; draw closer to what `such that` keeps, or allow more discards\")\n}\n\n#[derive(Default, Clone)]\nstruct Stats {\n    cases: usize,\n    cover: BTreeMap<String, usize>,\n    classes: BTreeMap<String, usize>,\n    labels: BTreeMap<String, usize>,\n    best: Option<f64>,\n}\n\nstatic STATISTICS: Mutex<BTreeMap<String, Stats>> = Mutex::new(BTreeMap::new());\n\nfn text(value: &Value) -> String {\n    let rendered = format!(\"{value:?}\");\n    match rendered.strip_prefix(\"Text(\\\"\").and_then(|r| r.strip_suffix(\"\\\")\")) {\n        Some(inner) => inner.to_string(),\n        None => rendered.trim_matches('\"').to_string(),\n    }\n}\n\n/// What one generated case covers, classifies and labels.\npub fn observe(law: &str, covers: &[(&str, bool)], classes: &[(&str, bool)], labels: &[Value]) {\n    let mut table = STATISTICS.lock().unwrap_or_else(|e| e.into_inner());\n    let stats = table.entry(law.to_string()).or_default();\n    stats.cases += 1;\n    for (label, holds) in covers {\n        if *holds {\n            *stats.cover.entry(label.to_string()).or_default() += 1;\n        }\n    }\n    for (label, holds) in classes {\n        if *holds {\n            *stats.classes.entry(label.to_string()).or_default() += 1;\n        }\n    }\n    for value in labels {\n        *stats.labels.entry(text(value)).or_default() += 1;\n    }\n}\n\n/// target maximize: proptest has no targeted search, so the best score is\n/// reported with the law's statistics.\npub fn target(score: &Value, law: &str) {\n    let value: f64 = format!(\"{score:?}\").trim_matches(|c: char| !(c.is_ascii_digit() || c == '-' || c == '.')).parse().unwrap_or(f64::NAN);\n    let mut table = STATISTICS.lock().unwrap_or_else(|e| e.into_inner());\n    let stats = table.entry(law.to_string()).or_default();\n    stats.best = Some(stats.best.map_or(value, |b| b.max(value)));\n}\n\nfn adequacy(law: &str, covers: &[(u32, &str)]) -> (Vec<(&'static str, String)>, Vec<String>) {\n    let stats = STATISTICS.lock().unwrap_or_else(|e| e.into_inner()).remove(law).unwrap_or_default();\n    let n = stats.cases;\n    let percent = |k: usize| if n == 0 { 0.0 } else { (10000.0 * k as f64 / n as f64).round() / 100.0 };\n    let mut lines = vec![format!(\"{law}: {n} generated case(s)\")];\n    let mut results = Vec::new();\n    let mut unmet = Vec::new();\n    for (required, label) in covers {\n        let observed = percent(*stats.cover.get(*label).unwrap_or(&0));\n        let met = n > 0 && observed >= *required as f64;\n        lines.push(format!(\"  cover {required}% {}: {observed}%{}\", quote(label), if met { \"\" } else { \" (not met)\" }));\n        results.push(format!(\"{{\\\"label\\\":{},\\\"required\\\":{required},\\\"observed\\\":{observed},\\\"met\\\":{met}}}\", quote(label)));\n        if !met {\n            unmet.push(format!(\"{law}: cover {required}% {} was not met ({observed}% of {n} generated cases)\", quote(label)));\n        }\n    }\n    for (label, count) in &stats.classes {\n        lines.push(format!(\"  {label}: {:.1}%\", percent(*count)));\n    }\n    for (label, count) in &stats.labels {\n        lines.push(format!(\"  label {label}: {:.1}%\", percent(*count)));\n    }\n    if let Some(best) = stats.best {\n        lines.push(format!(\"  best target score: {best}\"));\n    }\n    println!(\"{}\", lines.join(\"\\n\"));\n    let table = |m: &BTreeMap<String, usize>| format!(\"{{{}}}\", m.iter().map(|(k, v)| format!(\"{}:{v}\", quote(k))).collect::<Vec<_>>().join(\",\"));\n    let report = vec![\n        (\"cases\", n.to_string()),\n        (\"cover\", format!(\"[{}]\", results.join(\",\"))),\n        (\"classes\", table(&stats.classes)),\n        (\"labels\", table(&stats.labels)),\n    ];\n    (report, unmet)\n}\n\nfn once(law: &str, timeout: u64, test: fn() -> ls::Result<()>) -> Result<(), (String, bool)> {\n    let (sender, receiver) = std::sync::mpsc::channel();\n    std::thread::spawn(move || {\n        let outcome = std::panic::catch_unwind(test);\n        let _ = sender.send(outcome);\n    });\n    let outcome = if timeout == 0 {\n        receiver.recv().map_err(|e| (e.to_string(), true))?\n    } else {\n        match receiver.recv_timeout(std::time::Duration::from_millis(timeout)) {\n            Ok(outcome) => outcome,\n            Err(_) => return Err((format!(\"{law} took longer than its timeout of {timeout} ms\"), true)),\n        }\n    };\n    match outcome {\n        Ok(Ok(())) => Ok(()),\n        Ok(Err(error)) => Err((error, false)),\n        Err(panic) => {\n            let message = panic.downcast_ref::<String>().cloned()\n                .or_else(|| panic.downcast_ref::<&str>().map(|s| s.to_string()))\n                .unwrap_or_else(|| \"the test panicked\".to_string());\n            let harness = message.contains(\"outside the input's refinement\") || message.contains(\"discarded more than\");\n            Err((message, harness))\n        }\n    }\n}\n\n/// Run one law's test under its harness settings.\npub fn run(law: &str, name: &str, timeout: u64, repeat: u32, retries: u32, covers: &[(u32, &str)], observed: bool,\n    test: fn() -> ls::Result<()>) -> ls::Result<()> {\n    let mut attempts = 0;\n    let mut flaky = false;\n    let mut report = Vec::new();\n    loop {\n        attempts += 1;\n        let mut failure = None;\n        for _ in 0..repeat {\n            STATISTICS.lock().unwrap_or_else(|e| e.into_inner()).remove(law);\n            if let Err(error) = once(law, timeout, test) {\n                failure = Some(error);\n                break;\n            }\n            if observed {\n                let (r, unmet) = adequacy(law, covers);\n                report = r;\n                if !unmet.is_empty() {\n                    failure = Some((unmet.join(\"; \"), true));\n                    break;\n                }\n            }\n        }\n        match failure {\n            None => break,\n            Some((message, harness)) => {\n                let message = if message.contains(law) { message } else { format!(\"{law}: {message}\") };\n                if harness || attempts > retries {\n                    record(name, &[(\"law\", quote(law)), (\"test\", quote(name)), (\"outcome\", quote(\"failed\")), (\"attempts\", attempts.to_string())]);\n                    return Err(message);\n                }\n                flaky = true;\n            }\n        }\n    }\n    let mut entry = vec![(\"law\", quote(law)), (\"test\", quote(name)),\n        (\"outcome\", quote(if flaky { \"flaky\" } else { \"passed\" })), (\"attempts\", attempts.to_string())];\n    entry.extend(report);\n    record(name, &entry);\n    if flaky {\n        println!(\"{law} is flaky: it failed, then passed on attempt {attempts}\");\n    }\n    Ok(())\n}\n\n/// A known-failing law's test must fail. One that passes is reported: the\n/// harness should no longer say it is known to fail.\npub fn known_failing(law: &str, name: &str, reason: &str, test: fn() -> ls::Result<()>) -> ls::Result<()> {\n    match once(law, 0, test) {\n        Err((message, _)) => {\n            record(name, &[(\"law\", quote(law)), (\"test\", quote(name)), (\"outcome\", quote(\"known-failing\")), (\"reason\", quote(reason))]);\n            println!(\"{law} is known to fail ({reason}): {}\", message.lines().next().unwrap_or(\"\"));\n            Ok(())\n        }\n        Ok(()) => {\n            record(name, &[(\"law\", quote(law)), (\"test\", quote(name)), (\"outcome\", quote(\"known-failing-passed\")), (\"reason\", quote(reason))]);\n            Err(format!(\"{law} is marked known failing ({reason}), but it passes; remove `known failing` from its harness\"))\n        }\n    }\n}\n\n/// Measured, never asserted: the mean and fastest time of body.\npub fn benchmark(name: &str, mut body: impl FnMut() -> ls::Result<()>) -> ls::Result<()> {\n    let started = std::time::Instant::now();\n    let mut times = Vec::new();\n    while times.len() < 100000 && (started.elapsed().as_millis() < 200 || times.len() < 3) {\n        let before = std::time::Instant::now();\n        body()?;\n        times.push(before.elapsed().as_nanos());\n    }\n    let mean = times.iter().sum::<u128>() / times.len() as u128;\n    let fastest = *times.iter().min().unwrap_or(&0);\n    println!(\"benchmark {name}: {} iteration(s), mean {:.2} us, fastest {:.2} us\", times.len(), mean as f64 / 1000.0, fastest as f64 / 1000.0);\n    record(&format!(\"benchmark {name}\"), &[(\"benchmark\", quote(name)), (\"iterations\", times.len().to_string()),\n        (\"mean_ns\", mean.to_string()), (\"min_ns\", fastest.to_string())]);\n    Ok(())\n}\n\n/// order random: libtest runs tests in name order, several at a time, and\n/// its own shuffle is not stable. A unit with `order random` runs its law\n/// tests one at a time instead, each waiting for its turn: among the tests\n/// that have arrived and not run, the one the run's seed (LAWSPEC_SEED, or\n/// the clock) ranks first runs next, once no other has arrived for a moment.\npub struct Turn(String);\n\nstruct Turns {\n    running: bool,\n    waiting: Vec<(u64, usize)>,\n    arrived: std::time::Instant,\n}\n\nstatic TURNS: Mutex<BTreeMap<String, Turns>> = Mutex::new(BTreeMap::new());\nstatic TURN_FREE: std::sync::Condvar = std::sync::Condvar::new();\n\nfn turn_seed() -> u64 {\n    static SEED: std::sync::OnceLock<u64> = std::sync::OnceLock::new();\n    *SEED.get_or_init(|| {\n        std::env::var(\"LAWSPEC_SEED\").ok().and_then(|s| s.parse().ok()).unwrap_or_else(|| {\n            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos() as u64).unwrap_or(0)\n        })\n    })\n}\n\n/// With `parallel` too, the tests start in the seeded order and then run at\n/// the same time: a test's turn ends when it starts.\npub fn turn(unit: &str, index: usize, parallel: bool) -> Turn {\n    let rank = ls::SplitMix64::new(turn_seed() ^ (index as u64).wrapping_mul(0x9E3779B97F4A7C15)).next();\n    let mut turns = TURNS.lock().unwrap_or_else(|e| e.into_inner());\n    {\n        if !turns.contains_key(unit) {\n            let seed = turn_seed();\n            println!(\"order random seed {seed} ({unit}): LAWSPEC_SEED={seed} replays this order\");\n        }\n        let entry = turns.entry(unit.to_string()).or_insert_with(|| Turns { running: false, waiting: Vec::new(), arrived: std::time::Instant::now() });\n        entry.waiting.push((rank, index));\n        entry.arrived = std::time::Instant::now();\n    }\n    TURN_FREE.notify_all();\n    loop {\n        let entry = turns.get_mut(unit).expect(\"a unit's turns\");\n        let first = entry.waiting.iter().min().copied();\n        if !entry.running && first == Some((rank, index)) && entry.arrived.elapsed() >= std::time::Duration::from_millis(20) {\n            entry.waiting.retain(|w| *w != (rank, index));\n            entry.running = !parallel;\n            TURN_FREE.notify_all();\n            return Turn(if parallel { String::new() } else { unit.to_string() });\n        }\n        turns = TURN_FREE.wait_timeout(turns, std::time::Duration::from_millis(5)).unwrap_or_else(|e| e.into_inner()).0;\n    }\n}\n\nimpl Drop for Turn {\n    fn drop(&mut self) {\n        let mut turns = TURNS.lock().unwrap_or_else(|e| e.into_inner());\n        if let Some(entry) = turns.get_mut(&self.0) {\n            entry.running = false;\n        }\n        TURN_FREE.notify_all();\n    }\n}\n\n/// parallel: how the unit's tests run at the same time. libtest runs them on\n/// its test threads (RUST_TEST_THREADS, else one per processor).\npub fn parallelism(unit: &str) {\n    static SEEN: Mutex<Vec<String>> = Mutex::new(Vec::new());\n    let mut seen = SEEN.lock().unwrap_or_else(|e| e.into_inner());\n    if seen.iter().any(|u| u == unit) {\n        return;\n    }\n    seen.push(unit.to_string());\n    let workers = std::env::var(\"RUST_TEST_THREADS\").ok().and_then(|n| n.parse().ok())\n        .unwrap_or_else(|| std::thread::available_parallelism().map(|n| n.get()).unwrap_or(1));\n    let mode = \"threads (libtest)\";\n    record(&format!(\"parallel {unit}\"), &[(\"parallel\", quote(unit)), (\"mode\", quote(mode)), (\"workers\", workers.to_string())]);\n    println!(\"{unit} runs in parallel: {mode}, {workers} worker(s)\");\n}\n"
runtimeSource "python-network" = "\"\"\"The secure network handler of lawspec.network: node identities (ML-DSA-65,\nFIPS 204), a signed ML-KEM-768 handshake (FIPS 203), and frames sealed with\nAES-256-GCM (SP 800-38D) under a SHAKE256 (FIPS 202) key. The compiler\nwrites it beside lawspec_runtime when a program imports lawspec.network;\nimporting it registers it with the runtime, whose nodes then use it. It needs\nthe cryptography package.\"\"\"\nimport threading\n\nimport lawspec_runtime as ls\nfrom lawspec_runtime import Unreachable, WireError, _get_varint, _put_varint, _secure_random\n\n# (docs/reference/language/distribution.md,\n# \"Security\"). Every node has an ML-DSA-65 identity (FIPS 204). Before two\n# nodes exchange frames, the one that sends first runs a handshake: it sends\n# a signed hello with a fresh ML-KEM-768 encapsulation key (FIPS 203), the\n# other answers with a signed welcome carrying the ciphertext, and both derive\n# an AES-256-GCM key (SP 800-38D) with SHAKE256 (FIPS 202). Frames then cross\n# sealed. Records are bytes, so every transport carries them, and the format\n# is the same on every target.\n\n_RECORD = b'LS\\x01'\n_HELLO, _WELCOME, _DATA = 1, 2, 3\n_LABEL_HELLO = b'lawspec-handshake-v1-hello'\n_LABEL_WELCOME = b'lawspec-handshake-v1-welcome'\n_LABEL_KEY = b'lawspec-session-v1'\n_LABEL_FRAME = b'lawspec-frame-v1'\n_HANDSHAKE_RETRY = 0.1\n_HANDSHAKE_DEADLINE = 5.0\n_QUEUE_LIMIT = 4096\n\n\ndef _pq():\n    try:\n        from cryptography.hazmat.primitives.asymmetric import mldsa, mlkem\n        from cryptography.hazmat.primitives.ciphers.aead import AESGCM\n        from cryptography.exceptions import InvalidSignature, InvalidTag\n    except ImportError as error:\n        raise ImportError('a secure node needs the cryptography package: '\n                          'python -m pip install cryptography') from error\n    return mlkem, mldsa, AESGCM, InvalidSignature, InvalidTag\n\n\ndef _sha3(data):\n    import hashlib\n    return hashlib.sha3_256(data).digest()\n\n\ndef _shake(data, length):\n    import hashlib\n    return hashlib.shake_256(data).digest(length)\n\n\ndef _w(data):\n    out = bytearray()\n    _put_varint(out, len(data))\n    return bytes(out) + data\n\n\ndef _read_fields(data, pos, count):\n    fields = []\n    for _ in range(count):\n        n, pos = _get_varint(data, pos)\n        if pos + n > len(data):\n            raise WireError('a record field runs past its end')\n        fields.append(bytes(data[pos:pos + n]))\n        pos += n\n    return fields, pos\n\n\nclass NodeIdentity:\n    \"\"\"A node's long-term ML-DSA-65 identity, kept as its 32-byte seed.\"\"\"\n\n    def __init__(self, seed):\n        if len(seed) != 32:\n            raise ValueError('a node identity is a 32-byte ML-DSA-65 seed')\n        self.seed = bytes(seed)\n        key = _pq()[1].MLDSA65PrivateKey.from_seed_bytes(self.seed)\n        self._key = key\n        self.verifying_key = key.public_key().public_bytes_raw()\n\n    @staticmethod\n    def generate():\n        return NodeIdentity(_secure_random(32))\n\n    @staticmethod\n    def configured():\n        \"\"\"The identity lawspec.json binds (lawspec-network.conf, written by\n        the compiler), or a fresh one.\"\"\"\n        identity, _ = _network_config()\n        return identity if identity is not None else NodeIdentity.generate()\n\n    @property\n    def fingerprint(self):\n        \"\"\"SHA3-256 of the verifying key, in hexadecimal.\"\"\"\n        return _sha3(self.verifying_key).hex()\n\n    def sign(self, message):\n        return self._key.sign(message)\n\n\ndef _verify(verifying_key, message, signature):\n    mldsa, invalid = _pq()[1], _pq()[3]\n    try:\n        mldsa.MLDSA65PublicKey.from_public_bytes(verifying_key).verify(signature, message)\n        return True\n    except (invalid, ValueError):\n        return False\n\n\ndef _network_config():\n    \"\"\"lawspec-network.conf, which the compiler writes from lawspec.json's\n    network binding: the file LAWSPEC_NETWORK_CONF names, or the first found\n    in the working directory and the directories above it. Lines `identity\n    <file>` (a hex seed) and `trusted <file>` (hex fingerprints, one per\n    line), relative to it; `#` begins a comment.\"\"\"\n    import os\n    path = os.environ.get('LAWSPEC_NETWORK_CONF')\n    if path is None:\n        here = os.getcwd()\n        while True:\n            candidate = os.path.join(here, 'lawspec-network.conf')\n            if os.path.exists(candidate):\n                path = candidate\n                break\n            parent = os.path.dirname(here)\n            if parent == here:\n                return None, None\n            here = parent\n    if not os.path.exists(path):\n        return None, None\n    base = os.path.dirname(os.path.abspath(path))\n    identity, trusted = None, None\n    with open(path, encoding='utf-8') as conf:\n        for line in conf:\n            words = line.split(None, 1)\n            if len(words) != 2 or words[0].startswith('#'):\n                continue\n            target = os.path.join(base, words[1].strip())\n            with open(target, encoding='utf-8') as f:\n                text = f.read()\n            if words[0] == 'identity':\n                identity = NodeIdentity(bytes.fromhex(text.strip()))\n            elif words[0] == 'trusted':\n                trusted = {t.strip().lower() for t in text.split() if t.strip()}\n    return identity, trusted\n\n\ndef hello_body(session, address, verifying_key, encapsulation_key):\n    return _w(session) + _w(address.encode('utf-8')) + _w(verifying_key) + _w(encapsulation_key)\n\n\ndef welcome_body(session, address, verifying_key, ciphertext, hello):\n    return _w(session) + _w(address.encode('utf-8')) + _w(verifying_key) + _w(ciphertext) + _w(_sha3(hello))\n\n\ndef session_key(shared, hello, welcome):\n    \"\"\"The AES-256-GCM key: SHAKE256(shared || label || SHA3(hello body) ||\n    SHA3(welcome body)), 32 bytes.\"\"\"\n    return _shake(shared + _LABEL_KEY + _sha3(hello) + _sha3(welcome), 32)\n\n\ndef seal_frame(key, session, direction, frame, nonce=None):\n    nonce = _secure_random(12) if nonce is None else nonce\n    associated = _LABEL_FRAME + session + bytes([direction])\n    sealed = nonce + _pq()[2](key).encrypt(nonce, frame, associated)\n    return _RECORD + bytes([_DATA]) + _w(session) + bytes([direction]) + _w(sealed)\n\n\ndef open_frame(key, record):\n    \"\"\"The frame a data record seals, or None.\"\"\"\n    AESGCM, invalid = _pq()[2], _pq()[4]\n    try:\n        (session,), pos = _read_fields(record, 4, 1)\n        direction = record[pos]\n        (sealed,), end = _read_fields(record, pos + 1, 1)\n    except (IndexError, WireError):\n        return None\n    if end != len(record) or len(sealed) < 28:\n        return None\n    try:\n        return AESGCM(key).decrypt(sealed[:12], sealed[12:], _LABEL_FRAME + session + bytes([direction]))\n    except invalid:\n        return None\n\n\ndef handshake_vector(initiator_seed, responder_seed, kem_seed, session, initiator, responder,\n                     ciphertext, nonce, frame, hello_hash, welcome_hash, key, record):\n    \"\"\"Checks a handshake vector (hex fields): the bodies' hashes, the\n    session key and a sealed frame, as every target must compute them.\"\"\"\n    mlkem = _pq()[0]\n    x = bytes.fromhex\n    first, second = NodeIdentity(x(initiator_seed)), NodeIdentity(x(responder_seed))\n    kem = mlkem.MLKEM768PrivateKey.from_seed_bytes(x(kem_seed))\n    hello = hello_body(x(session), initiator, first.verifying_key, kem.public_key().public_bytes_raw())\n    welcome = welcome_body(x(session), responder, second.verifying_key, x(ciphertext), hello)\n    derived = session_key(kem.decapsulate(x(ciphertext)), hello, welcome)\n    sealed = seal_frame(derived, x(session), 0, x(frame), x(nonce))\n    return (_sha3(hello).hex() == hello_hash and _sha3(welcome).hex() == welcome_hash\n            and derived.hex() == key and sealed.hex() == record\n            and open_frame(derived, sealed) == x(frame))\n\n\nclass _Session:\n    def __init__(self, ident, peer, key, direction, confirmed):\n        self.id, self.peer, self.key = ident, peer, key\n        # 0: this node began the handshake; 1: the peer did.\n        self.direction = direction\n        # A session the peer began is used for sending once a frame has\n        # arrived on it, so the peer surely holds its key.\n        self.confirmed = confirmed\n\n\nclass _SecureLayer:\n    \"\"\"Handshakes, sessions and sealed frames for one node.\"\"\"\n\n    def __init__(self, node, identity, trusted):\n        self.node = node\n        self.identity = identity if identity is not None else NodeIdentity.configured()\n        if trusted is None:\n            trusted = _network_config()[1]\n        self.trusted = None if trusted is None else {t.lower() for t in trusted}\n        self.sessions = {}\n        self.outbound = {}\n        self.pending = {}\n        self.welcomes = {}\n        # The identity first seen at each address: a later, different one\n        # is refused (trust on first use, unless trusted names them).\n        self.known = {}\n        self.lock = threading.Lock()\n\n    def _accept_peer(self, address, verifying_key):\n        fingerprint = _sha3(verifying_key).hex()\n        if self.trusted is not None and fingerprint not in self.trusted:\n            return False\n        with self.lock:\n            seen = self.known.setdefault(address, fingerprint)\n        return seen == fingerprint\n\n    def send(self, peer, frame):\n        with self.lock:\n            session = self.outbound.get(peer)\n            if session is None:\n                for s in self.sessions.values():\n                    if s.peer == peer and s.confirmed:\n                        session = s\n                        break\n            if session is None:\n                pending = self.pending.get(peer)\n                start = pending is None\n                if start:\n                    pending = self.pending[peer] = self._begin(peer)\n                if len(pending['queue']) < _QUEUE_LIMIT:\n                    pending['queue'].append(frame)\n        if session is not None:\n            self.node.transport.send(peer, seal_frame(session.key, session.id, session.direction, frame))\n            return\n        if start:\n            try:\n                self.node.transport.send(peer, pending['hello'])\n            except Unreachable:\n                with self.lock:\n                    self.pending.pop(peer, None)\n                raise\n            threading.Thread(target=self._retry, args=(peer, pending), daemon=True).start()\n\n    def _begin(self, peer):\n        mlkem = _pq()[0]\n        session = _secure_random(16)\n        kem = mlkem.MLKEM768PrivateKey.from_seed_bytes(_secure_random(64))\n        body = hello_body(session, self.node.address, self.identity.verifying_key,\n                          kem.public_key().public_bytes_raw())\n        signature = self.identity.sign(_LABEL_HELLO + body)\n        return {'session': session, 'kem': kem, 'body': body, 'queue': [], 'done': threading.Event(),\n                'hello': _RECORD + bytes([_HELLO]) + body + _w(signature)}\n\n    def _retry(self, peer, pending):\n        import time\n        give_up = time.monotonic() + _HANDSHAKE_DEADLINE\n        while not pending['done'].wait(_HANDSHAKE_RETRY):\n            if self.node.closed or time.monotonic() >= give_up:\n                with self.lock:\n                    if self.pending.get(peer) is pending:\n                        del self.pending[peer]\n                return\n            try:\n                self.node.transport.send(peer, pending['hello'])\n            except Unreachable:\n                pass\n\n    def receive(self, record):\n        \"\"\"The frame a record carries, or None (a handshake record, or one\n        that fails to verify or open).\"\"\"\n        if len(record) < 4 or record[:3] != _RECORD:\n            return None\n        kind = record[3]\n        try:\n            if kind == _HELLO:\n                self._hello(record)\n            elif kind == _WELCOME:\n                self._welcome(record)\n            elif kind == _DATA:\n                return self._data(record)\n        except (WireError, IndexError, ValueError):\n            return None\n        return None\n\n    def _hello(self, record):\n        (session, address, verifying_key, encapsulation_key), pos = _read_fields(record, 4, 4)\n        (signature,), end = _read_fields(record, pos, 1)\n        if end != len(record):\n            return\n        body = record[4:pos]\n        address = address.decode('utf-8')\n        with self.lock:\n            answered = self.welcomes.get(session)\n        if answered is None:\n            if not _verify(verifying_key, _LABEL_HELLO + body, signature):\n                return\n            if not self._accept_peer(address, verifying_key):\n                return\n            mlkem = _pq()[0]\n            shared, ciphertext = mlkem.MLKEM768PublicKey.from_public_bytes(encapsulation_key).encapsulate()\n            welcome = welcome_body(session, self.node.address, self.identity.verifying_key, ciphertext, body)\n            answered = (address, _RECORD + bytes([_WELCOME]) + welcome +\n                        _w(self.identity.sign(_LABEL_WELCOME + welcome)))\n            with self.lock:\n                if session not in self.welcomes:\n                    self.welcomes[session] = answered\n                    self.sessions[session] = _Session(session, address, session_key(shared, body, welcome), 1, False)\n                answered = self.welcomes[session]\n        try:\n            self.node.transport.send(answered[0], answered[1])\n        except Unreachable:\n            pass\n\n    def _welcome(self, record):\n        (session, address, verifying_key, ciphertext, hello_hash), pos = _read_fields(record, 4, 5)\n        (signature,), end = _read_fields(record, pos, 1)\n        if end != len(record):\n            return\n        address = address.decode('utf-8')\n        with self.lock:\n            pending = self.pending.get(address)\n        if pending is None or pending['session'] != session or hello_hash != _sha3(pending['body']):\n            return\n        body = record[4:pos]\n        if not _verify(verifying_key, _LABEL_WELCOME + body, signature):\n            return\n        if not self._accept_peer(address, verifying_key):\n            return\n        key = session_key(pending['kem'].decapsulate(ciphertext), pending['body'], body)\n        established = _Session(session, address, key, 0, True)\n        with self.lock:\n            if self.pending.get(address) is not pending:\n                return\n            del self.pending[address]\n            self.sessions[session] = established\n            self.outbound[address] = established\n            queue = pending['queue']\n        pending['done'].set()\n        for frame in queue:\n            try:\n                self.node.transport.send(address, seal_frame(key, session, 0, frame))\n            except Unreachable:\n                pass\n\n    def _data(self, record):\n        (session,), _ = _read_fields(record, 4, 1)\n        with self.lock:\n            found = self.sessions.get(session)\n        if found is None:\n            return None\n        frame = open_frame(found.key, record)\n        if frame is not None and not found.confirmed:\n            found.confirmed = True\n        return frame\n\n\nclass _Provider:\n    def layer(self, node, identity, trusted):\n        return _SecureLayer(node, identity, trusted)\n\n\nls.register_secure_network(_Provider())\n"
runtimeSource "javascript-network" = "// Generated by LawSpec. Do not edit.\n// The secure network handler (docs/reference/language/distribution.md,\n// \"Security\"), written beside the runtime for programs that import\n// lawspec.network. Every node has an ML-DSA-65 identity (FIPS 204). Before\n// two nodes exchange frames, the one that sends first runs a handshake: it\n// sends a signed hello with a fresh ML-KEM-768 encapsulation key (FIPS 203),\n// the other answers with a signed welcome carrying the ciphertext, and both\n// derive an AES-256-GCM key (SP 800-38D) with SHAKE256 (FIPS 202). Frames then\n// cross sealed. Records are bytes, so every transport carries them, and the\n// format is the same on every target.\n//\n// ML-KEM and ML-DSA come from @noble/post-quantum, SHA3, SHAKE and AES-GCM\n// from node:crypto, as lawspec.crypto's default handlers have them. The\n// runtime loads this module when its first secure node is made, and uses\n// its layer (node, identity, trusted) as the node's secure layer; the module\n// imports nothing from the runtime.\nimport { createCipheriv, createDecipheriv, createHash } from 'node:crypto';\nimport { existsSync, readFileSync } from 'node:fs';\nimport { dirname, join, resolve } from 'node:path';\nimport { ml_kem768 } from '@noble/post-quantum/ml-kem.js';\nimport { ml_dsa65 } from '@noble/post-quantum/ml-dsa.js';\n\nconst UTF8 = new TextEncoder();\nconst STRICT_UTF8 = new TextDecoder('utf-8', {fatal: true});\nconst RECORD = Uint8Array.of(0x4C, 0x53, 0x01);\nconst HELLO = 1, WELCOME = 2, DATA = 3;\nconst LABEL_HELLO = UTF8.encode('lawspec-handshake-v1-hello');\nconst LABEL_WELCOME = UTF8.encode('lawspec-handshake-v1-welcome');\nconst LABEL_KEY = UTF8.encode('lawspec-session-v1');\nconst LABEL_FRAME = UTF8.encode('lawspec-frame-v1');\nconst HANDSHAKE_RETRY = 100;\nconst HANDSHAKE_DEADLINE = 5000;\nconst QUEUE_LIMIT = 4096;\nconst NO_CONTEXT = new Uint8Array(0);\n\n/** Bytes that are not a well-formed record. */\nclass RecordError extends Error {}\n\nconst asBytes = (data) => (data instanceof Uint8Array && data.constructor === Uint8Array ? data : new Uint8Array(data));\n\nfunction concatBytes(...parts) {\n  const total = parts.reduce((n, p) => n + p.length, 0);\n  const out = new Uint8Array(total);\n  let at = 0;\n  for (const p of parts) {\n    out.set(p, at);\n    at += p.length;\n  }\n  return out;\n}\n\nconst hex = (bytes) => Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');\n\nfunction fromHex(text) {\n  if (text.length % 2 !== 0 || /[^0-9a-fA-F]/.test(text)) throw new Error('not hexadecimal: ' + text);\n  const out = new Uint8Array(text.length / 2);\n  for (let i = 0; i < out.length; i++) out[i] = parseInt(text.slice(2 * i, 2 * i + 2), 16);\n  return out;\n}\n\nfunction equalBytes(a, b) {\n  if (a.length !== b.length) return false;\n  let difference = 0;\n  for (let i = 0; i < a.length; i++) difference |= a[i] ^ b[i];\n  return difference === 0;\n}\n\nfunction sha3(data) {\n  return asBytes(createHash('sha3-256').update(data).digest());\n}\n\nfunction shake(data, length) {\n  return asBytes(createHash('shake256', {outputLength: length}).update(data).digest());\n}\n\nfunction secureRandom(n) {\n  const out = new Uint8Array(n);\n  globalThis.crypto.getRandomValues(out);\n  return out;\n}\n\n/** A record field: its length (LEB128, as the wire encoding writes it), then its bytes. */\nfunction w(data) {\n  const out = [];\n  let n = data.length;\n  for (;;) {\n    const byte = n & 0x7F;\n    n = Math.floor(n / 128);\n    if (n) out.push(byte | 0x80);\n    else {\n      out.push(byte);\n      break;\n    }\n  }\n  return concatBytes(Uint8Array.from(out), data);\n}\n\nfunction readVarint(data, pos) {\n  let result = 0, scale = 1;\n  for (;;) {\n    if (pos >= data.length) throw new RecordError('the record ends in the middle of a length');\n    const byte = data[pos++];\n    result += (byte & 0x7F) * scale;\n    if (result > Number.MAX_SAFE_INTEGER) throw new RecordError('a record length is too large');\n    if (byte < 0x80) return [result, pos];\n    scale *= 128;\n  }\n}\n\nfunction readFields(data, pos, count) {\n  const fields = [];\n  for (let i = 0; i < count; i++) {\n    let n;\n    [n, pos] = readVarint(data, pos);\n    if (pos + n > data.length) throw new RecordError('a record field runs past its end');\n    fields.push(data.slice(pos, pos + n));\n    pos += n;\n  }\n  return [fields, pos];\n}\n\n/** A node's long-term ML-DSA-65 identity, kept as its 32-byte seed. */\nexport class NodeIdentity {\n  seed;\n  verifyingKey;\n  #secretKey;\n  constructor(seed) {\n    const bytes = Uint8Array.from(seed);\n    if (bytes.length !== 32) throw new Error('a node identity is a 32-byte ML-DSA-65 seed');\n    this.seed = bytes;\n    const {publicKey, secretKey} = ml_dsa65.keygen(bytes.slice());\n    this.verifyingKey = publicKey;\n    this.#secretKey = secretKey;\n  }\n  static generate() {\n    return new NodeIdentity(secureRandom(32));\n  }\n  /** The identity lawspec.json binds (lawspec-network.conf), or a fresh one. */\n  static configured() {\n    return networkConfig().identity ?? NodeIdentity.generate();\n  }\n  /** SHA3-256 of the verifying key, in hexadecimal. */\n  get fingerprint() {\n    return hex(sha3(this.verifyingKey));\n  }\n  sign(message) {\n    return ml_dsa65.sign(message, this.#secretKey.slice(), {context: NO_CONTEXT});\n  }\n}\n\nfunction verifySigned(verifyingKey, message, signature) {\n  try {\n    return ml_dsa65.verify(signature, message, verifyingKey, {context: NO_CONTEXT}) === true;\n  } catch {\n    return false;\n  }\n}\n\n/**\n * lawspec-network.conf, which the compiler writes from lawspec.json's\n * network binding: the file LAWSPEC_NETWORK_CONF names, or the first found\n * in the working directory and the directories above it. Lines `identity\n * <file>` (a hex seed) and `trusted <file>` (hex fingerprints, one per\n * line), relative to it; `#` begins a comment. Gives {identity, trusted},\n * each nul